assert_pin_unique "#192 backstop: untracked-file-never-auto-deleted safety rule" \
  'never auto-deleted; git said' "$REVIEW_SKILL"
# AC3 (#216) drift guards — coupled multi-site operative directives, pinned by occurrence
# count so dropping any one site drifts the count RED:
#  - the pathname-safe NUL read loop `IFS= read -r -d ''` at all THREE sites (BEFORE extract,
#    AFTER extract, restore loop) — a regression to a newline `read -r` at any site drops the count;
#  - no unchecked `sort -z` pipeline remains — records append directly and each write is rc-checked;
#  - the fixed repo-local fail-closed sentinel PATH at all FOUR sites (success cleanup, failure
#    producer, 3.2 short-circuit read, final cleanup). This file survives the Agent boundary;
#    a shell variable would not.
assert_eq "#216 backstop: the pathname-safe NUL read loop is present at all three sites" "yes" \
  "$([ "$(grep -cF 'IFS= read -r -d' "$REVIEW_SKILL")" -eq 3 ] && echo yes || echo no)"  # raw-guard-ok: count-based: asserts ==3 NUL read loops (BEFORE/AFTER extract + restore)
assert_eq "#484 backstop: no unchecked sort -z extraction pipeline remains" "yes" \
  "$([ "$(grep -cF 'sort -z' "$REVIEW_SKILL")" -eq 0 ] && echo yes || echo no)"  # raw-guard-ok: count-based: asserts ==0 unchecked sort -z pipelines
assert_eq "#216 backstop: the fixed fail-closed sentinel path stays coupled across its four sites" "yes" \
  "$([ "$(grep -cF '.prflow/tmp/review-dirty-tree-disabled' "$REVIEW_SKILL")" -eq 4 ] && echo yes || echo no)"  # raw-guard-ok: count-based: asserts ==4 occurrences (success cleanup + failure producer + 3.2 read + final cleanup)
# ── #216: dirty-tree backstop -z rework — git_sandbox integration proof ────────────────
# Extract and execute the real Phase 3.1 snapshot block. These checks catch three concrete
# production breaks: stale snapshot symlinks clobbering their targets, a missing `git status
# --porcelain -z` capture leaving the backstop disabled, and a race-swapped symlink being
# accepted as an authenticated baseline.
DT_SNAPSHOT="$(probe_tmp "#484 before-snapshot block extraction")"
awk '
  /Dirty-tree backstop — snapshot before dispatch/ { wanted=1; next }
  wanted && /^```bash$/ { block=1; next }
  block && /^```$/ { exit }
  block { print }
' "$REVIEW_SKILL" > "$DT_SNAPSHOT"
assert_eq "#484 before-snapshot: executable Phase 3.1 block extracted" "yes" \
  "$([ -s "$DT_SNAPSHOT" ] && echo yes || echo no)"

DT_S="$(git_sandbox "#484 before-snapshot stale-symlink repo")"
if [ -d "$DT_S" ]; then
  git -C "$DT_S" init -q
  DT_S_B="$DT_S/before"; DT_S_V="$(probe_tmp "#484 before-snapshot stale-symlink target")"
  printf 'target sentinel' > "$DT_S_V"; ln -s "$DT_S_V" "$DT_S_B"
  DT_S_OID="$(cd "$DT_S" && GIT_SNAP_BEFORE="$DT_S_B" bash "$DT_SNAPSHOT" 2>/dev/null)"
  assert_eq "#484 before-snapshot: stale symlink is removed without clobbering its target" \
    "target sentinel" "$(cat "$DT_S_V")"
  assert_eq "#216 before-snapshot: real -z capture produces an authenticated regular file" "yes" \
    "$([ -f "$DT_S_B" ] && [ ! -L "$DT_S_B" ] && [ -n "$DT_S_OID" ] && [ "$DT_S_OID" = "$(git hash-object "$DT_S_B")" ] && echo yes || echo no)"
  assert_eq "#216 before-snapshot: successful capture does not leave the disabled sentinel" "no" \
    "$([ -e "$DT_S/.prflow/tmp/review-dirty-tree-disabled" ] && echo yes || echo no)"
  rm -rf "$DT_S" "$DT_S_V"
fi

DT_SR="$(git_sandbox "#484 before-snapshot symlink-race repo")"
if [ -d "$DT_SR" ]; then
  git -C "$DT_SR" init -q
  DT_SR_B="$DT_SR/before"; DT_SR_V="$(probe_tmp "#484 before-snapshot symlink-race target")"
  DT_SR_BIN="$DT_SR/bin"; mkdir -p "$DT_SR_BIN"
  printf 'target sentinel' > "$DT_SR_V"
  DT_REAL_GIT="$(command -v git)"
  printf '%s\n' '#!/usr/bin/env bash' \
    'if [ "${1:-}" = status ]; then' \
    '  rm -f "$GIT_SNAP_BEFORE"; ln -s "$DT_RACE_TARGET" "$GIT_SNAP_BEFORE"' \
    'fi' \
    'exec "$DT_REAL_GIT" "$@"' > "$DT_SR_BIN/git"
  chmod +x "$DT_SR_BIN/git"
  ( cd "$DT_SR" && PATH="$DT_SR_BIN:$PATH" DT_REAL_GIT="$DT_REAL_GIT" \
      DT_RACE_TARGET="$DT_SR_V" GIT_SNAP_BEFORE="$DT_SR_B" bash "$DT_SNAPSHOT" ) >/dev/null 2>&1
  assert_eq "#484 before-snapshot: a race-swapped symlink disables the backstop" "yes" \
    "$([ -f "$DT_SR/.prflow/tmp/review-dirty-tree-disabled" ] && echo yes || echo no)"
  assert_eq "#484 before-snapshot: symlink-race target remains untouched" \
    "target sentinel" "$(cat "$DT_SR_V")"
  rm -rf "$DT_SR" "$DT_SR_V"
fi
rm -f "$DT_SNAPSHOT"

# AC2 (#216): a spaced-path agent mutation is correctly RESTORED (no silent no-op), a true
# rename is SURFACED-not-restored, and the spaced-path restore is COUPLED to the `-z` rework
# (RED with quoted plain-porcelain snapshots, GREEN with `-z`). The proof EXTRACTS the
# self-contained restore region from skills/review/SKILL.md and runs it against a real
# throwaway git repo (git_sandbox), so a regression of the region's NUL-handling back to the
# quoting-vulnerable shape turns this RED. The markers are referenced via vars so this source
# line never carries the contiguous marker string the extractor scans for.
DT_REGION="$(probe_tmp "#216 backstop region extraction")"
DT_BEGIN="devflow:dirty-tree-restore ""BEGIN"
DT_END="devflow:dirty-tree-restore ""END"
# Reuse the single-source-of-truth region extractor (markers excluded the same way every
# other region scanner excludes them) rather than re-rolling the region awk inline.
region_lines "$REVIEW_SKILL" "$DT_BEGIN" "$DT_END" > "$DT_REGION"
assert_eq "#216 backstop: restore region extracted from SKILL.md is non-empty" "yes" \
  "$([ -s "$DT_REGION" ] && echo yes || echo no)"
# Build a fresh sandbox repo with a committed spaced-path file + a plain file (fail-closed on
# mktemp -d failure via git_sandbox's /dev/null sentinel — a caller's `[ -d ]` guard then skips).
dt_make_repo() {  # -> prints repo dir
  local d; d="$(git_sandbox "#216 backstop fixture")" || { printf '%s\n' "$d"; return 1; }
  git -C "$d" init -q; git -C "$d" config user.email t@t; git -C "$d" config user.name t
  printf orig > "$d/my file.txt"; printf plain > "$d/plain.txt"
  git -C "$d" add -A; git -C "$d" commit -qm init
  printf '%s\n' "$d"
}
# Case A — spaced-path modify with `-z` snapshots: RESTORED (GREEN).
DT_A="$(dt_make_repo)"
if [ -d "$DT_A" ]; then
  DT_A_B="$(probe_tmp "#216 case-A before")"; DT_A_AF="$(probe_tmp "#216 case-A after")"
  git -C "$DT_A" status --porcelain -z > "$DT_A_B"
  printf changed > "$DT_A/my file.txt"
  git -C "$DT_A" status --porcelain -z > "$DT_A_AF"
  ( cd "$DT_A" && GIT_SNAP_BEFORE="$DT_A_B" GIT_SNAP_AFTER="$DT_A_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#216 backstop: a spaced-path agent modification is restored (-z snapshots)" \
    "orig" "$(cat "$DT_A/my file.txt" 2>/dev/null)"
  rm -rf "$DT_A" "$DT_A_B" "$DT_A_AF"
fi
# Case B — SAME mutation but QUOTED plain-porcelain snapshots: NOT restored. This is the
# pre-rework (RED) state — it proves the `-z` capture is load-bearing, not incidental.
DT_BR="$(dt_make_repo)"
if [ -d "$DT_BR" ]; then
  DT_BR_B="$(probe_tmp "#216 case-B before")"; DT_BR_AF="$(probe_tmp "#216 case-B after")"
  git -C "$DT_BR" status --porcelain > "$DT_BR_B"     # no -z: the spaced path is C-quoted
  printf changed > "$DT_BR/my file.txt"
  git -C "$DT_BR" status --porcelain > "$DT_BR_AF"
  ( cd "$DT_BR" && GIT_SNAP_BEFORE="$DT_BR_B" GIT_SNAP_AFTER="$DT_BR_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#216 backstop: quoted (non--z) snapshots do NOT restore the spaced path (why -z is required)" \
    "changed" "$(cat "$DT_BR/my file.txt" 2>/dev/null)"
  rm -rf "$DT_BR" "$DT_BR_B" "$DT_BR_AF"
fi
# Case C — true staged rename: SURFACED, NOT auto-restored (the file stays renamed).
DT_C="$(dt_make_repo)"
if [ -d "$DT_C" ]; then
  DT_C_B="$(probe_tmp "#216 case-C before")"; DT_C_AF="$(probe_tmp "#216 case-C after")"
  git -C "$DT_C" status --porcelain -z > "$DT_C_B"
  git -C "$DT_C" mv "plain.txt" "renamed plain.txt"
  git -C "$DT_C" status --porcelain -z > "$DT_C_AF"
  ( cd "$DT_C" && GIT_SNAP_BEFORE="$DT_C_B" GIT_SNAP_AFTER="$DT_C_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#216 backstop: a true rename is surfaced-not-restored (renamed file remains)" \
    "plain" "$(cat "$DT_C/renamed plain.txt" 2>/dev/null)"
  assert_eq "#216 backstop: a true rename leaves the original path removed (not auto-recreated)" \
    "no" "$([ -e "$DT_C/plain.txt" ] && echo yes || echo no)"
  rm -rf "$DT_C" "$DT_C_B" "$DT_C_AF"
fi
# Case D — the CENTRAL by-path safety property end-to-end: a path the orchestrator had
# ALREADY modified before dispatch is left untouched (NOT clobbered) while a DIFFERENT path an
# agent newly dirtied during the window IS restored. This exercises the absent-from-BEFORE
# membership direction against a non-empty BEFORE set — the one scenario cases A/B/C don't
# build — so a subtle regression in BEFORE-set construction or the membership direction that
# clobbers a concurrent edit fails here, not only at the literal-presence direction pin.
DT_D="$(dt_make_repo)"
if [ -d "$DT_D" ]; then
  DT_D_B="$(probe_tmp "#216 case-D before")"; DT_D_AF="$(probe_tmp "#216 case-D after")"
  printf 'concurrent edit' > "$DT_D/my file.txt"   # orchestrator's OWN edit — dirty BEFORE dispatch
  git -C "$DT_D" status --porcelain -z > "$DT_D_B"
  printf 'agent edit' > "$DT_D/plain.txt"          # a DIFFERENT path an agent dirties DURING the window
  git -C "$DT_D" status --porcelain -z > "$DT_D_AF"
  ( cd "$DT_D" && GIT_SNAP_BEFORE="$DT_D_B" GIT_SNAP_AFTER="$DT_D_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#216 backstop: an already-dirty path (clean->dirty BEFORE dispatch) is NOT clobbered by the restore" \
    "concurrent edit" "$(cat "$DT_D/my file.txt" 2>/dev/null)"
  assert_eq "#216 backstop: a newly-dirtied path (dirtied DURING the window) IS restored to HEAD" \
    "plain" "$(cat "$DT_D/plain.txt" 2>/dev/null)"
  rm -rf "$DT_D" "$DT_D_B" "$DT_D_AF"
fi
# Case D2 — checkout cannot remove an untracked file. The required post-restore
# tree-state check must surface that residual instead of trusting checkout's failure
# or falsely reporting the path restored.
DT_D2="$(dt_make_repo)"
if [ -d "$DT_D2" ]; then
  DT_D2_B="$(probe_tmp "#192 case-D2 before")"; DT_D2_AF="$(probe_tmp "#192 case-D2 after")"
  DT_D2_ERR="$(probe_tmp "#192 case-D2 stderr")"
  # No membership shim: the region's BEFORE-membership test is pure bash (issue #1470), so this
  # behavioral check reaches the restore/re-check boundary unaided on GNU and BSD/macOS alike.
  git -C "$DT_D2" status --porcelain -z > "$DT_D2_B"
  printf 'agent-created' > "$DT_D2/untracked.txt"
  git -C "$DT_D2" status --porcelain -z > "$DT_D2_AF"
  ( cd "$DT_D2" && GIT_SNAP_BEFORE="$DT_D2_B" GIT_SNAP_AFTER="$DT_D2_AF" bash "$DT_REGION" ) >/dev/null 2>"$DT_D2_ERR"
  assert_eq "#192 backstop: an untracked dispatch-window file is never auto-deleted" \
    "agent-created" "$(cat "$DT_D2/untracked.txt")"
  assert_eq "#192 backstop: failed restore is detected from live tree state and breadcrumbed" "yes" \
    "$(grep -qF "path 'untracked.txt' still dirty after restore attempt" "$DT_D2_ERR" && echo yes || echo no)"
  rm -rf "$DT_D2" "$DT_D2_B" "$DT_D2_AF" "$DT_D2_ERR"
fi
# Case E — a truncated non-NUL BEFORE record must fail closed. Without the explicit leftover-
# record check, `read -d ''` reaches EOF, the loop reports success, and the empty membership
# set misclassifies the orchestrator's already-dirty path as agent-introduced.
DT_E="$(dt_make_repo)"
if [ -d "$DT_E" ]; then
  DT_E_B="$(probe_tmp "#484 case-E before")"; DT_E_AF="$(probe_tmp "#484 case-E after")"
  printf ' M my file.txt' > "$DT_E_B"                 # deliberately missing the required NUL
  printf 'concurrent edit' > "$DT_E/my file.txt"      # must never be restored from HEAD
  printf 'agent edit' > "$DT_E/plain.txt"
  git -C "$DT_E" status --porcelain -z > "$DT_E_AF"
  ( cd "$DT_E" && GIT_SNAP_BEFORE="$DT_E_B" GIT_SNAP_AFTER="$DT_E_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#484 backstop: truncated BEFORE snapshot fails closed without clobbering an existing edit" \
    "concurrent edit" "$(cat "$DT_E/my file.txt" 2>/dev/null)"
  assert_eq "#484 backstop: truncated BEFORE snapshot skips all restoration" \
    "agent edit" "$(cat "$DT_E/plain.txt" 2>/dev/null)"
  rm -rf "$DT_E" "$DT_E_B" "$DT_E_AF"
fi
# Case D3 — the same central by-path property as case D, carried on a GLOB-metacharacter and a
# NEWLINE-containing pathname. Every case above reaches the BEFORE-membership scan only through
# the spaced path `my file.txt`, and a space is inert under glob pattern matching: a membership
# test rewritten from `[ "$bp" = "${rec:3}" ]` to `[[ $bp == ${rec:3} ]]` leaves the spaced
# fixtures GREEN while silently clobbering a concurrent orchestrator edit whose path contains
# `[`, `*` or `?` (both directions measured on bash 3.2.57).
DT_D3="$(dt_make_repo)"
if [ -d "$DT_D3" ]; then
  DT_D3_B="$(probe_tmp "#1470 case-D3 before")"; DT_D3_AF="$(probe_tmp "#1470 case-D3 after")"
  DT_D3_NL="$(printf 'new\nline.txt')"
  printf brack > "$DT_D3/g[ab].txt"; printf nl > "$DT_D3/$DT_D3_NL"; printf star > "$DT_D3/f*.txt"
  git -C "$DT_D3" add -A; git -C "$DT_D3" commit -qm special
  printf 'concurrent edit' > "$DT_D3/g[ab].txt"   # orchestrator's OWN edit — glob metacharacters
  printf 'concurrent nl' > "$DT_D3/$DT_D3_NL"     # orchestrator's OWN edit — embedded newline
  git -C "$DT_D3" status --porcelain -z > "$DT_D3_B"
  printf 'agent edit' > "$DT_D3/f*.txt"           # a DIFFERENT glob path dirtied DURING the window
  git -C "$DT_D3" status --porcelain -z > "$DT_D3_AF"
  ( cd "$DT_D3" && GIT_SNAP_BEFORE="$DT_D3_B" GIT_SNAP_AFTER="$DT_D3_AF" bash "$DT_REGION" ) >/dev/null 2>&1
  assert_eq "#1470 backstop: an already-dirty GLOB-metacharacter path is NOT clobbered by the restore" \
    "concurrent edit" "$(cat "$DT_D3/g[ab].txt" 2>/dev/null)"
  assert_eq "#1470 backstop: an already-dirty NEWLINE-containing path is NOT clobbered by the restore" \
    "concurrent nl" "$(cat "$DT_D3/$DT_D3_NL" 2>/dev/null)"
  assert_eq "#1470 backstop: a newly-dirtied glob-metacharacter path IS restored to HEAD" \
    "star" "$(cat "$DT_D3/f*.txt" 2>/dev/null)"
  rm -rf "$DT_D3" "$DT_D3_B" "$DT_D3_AF"
fi
# DEFERRAL (#1470 review, Important 2 — `set -u` guard coverage): deliberately NOT tested.
# The `${before_paths[@]+…}` guard in the extracted region is defensive only. (1) No production
# path runs that region under `set -u`: it is agent-executed prose from a Read-loaded phase
# reference (never sourced into a workflow `run:` step), and no
# `set -u` appears anywhere in the review prompt surface. (2) Bash stopped erroring on
# `"${empty[@]}"` under `set -u` in 4.4, so the guard is a no-op on every bash the suite runs
# (CI ubuntu 5.x; maintainer host PATH bash 5.3) — a committed case cannot go RED there, and a
# vacuous guard is what this suite's mutation-check discipline forbids. (3) Measured on bash
# 3.2.57, removing the guard fails CLOSED and loud: `unbound variable` on stderr and the region
# aborts before restoring anything, so no concurrent edit is clobbered.
# Revisit if the region ever gains a caller that sets `set -u`, or is relocated into a helper.
rm -f "$DT_REGION"
# #484: exercise the COMPLETE Phase 3.2 wrapper, including regular-file/OID authentication.
# The older region above intentionally starts after those guards and cannot prove their behavior.
DT_COMPARE="$(probe_tmp "#484 dirty-tree compare wrapper extraction")"
DT_COMPARE_RUN="$(probe_tmp "#484 dirty-tree compare wrapper substituted")"
DT_COMPARE_BEGIN="devflow:dirty-tree-compare ""BEGIN"
DT_COMPARE_END="devflow:dirty-tree-compare ""END"
region_lines "$REVIEW_SKILL" "$DT_COMPARE_BEGIN" "$DT_COMPARE_END" > "$DT_COMPARE"
assert_eq "#484 backstop: complete authenticated compare wrapper extracted" "yes" \
  "$([ -s "$DT_COMPARE" ] && echo yes || echo no)"

# Case F — positive control: the authentic baseline + substituted external OID proceeds into
# restore, preserving an already-dirty path while restoring the agent-introduced path.
DT_F="$(dt_make_repo)"
if [ -d "$DT_F" ]; then
  DT_F_B="$(probe_tmp "#484 case-F before")"; DT_F_AF="$(probe_tmp "#484 case-F after")"
  printf 'concurrent edit' > "$DT_F/my file.txt"
  git -C "$DT_F" status --porcelain -z > "$DT_F_B"
  DT_F_OID="$(git hash-object "$DT_F_B")"
  printf 'agent edit' > "$DT_F/plain.txt"
  sed "s/{GIT_SNAP_BEFORE_OID}/$DT_F_OID/g" "$DT_COMPARE" > "$DT_COMPARE_RUN"
  ( cd "$DT_F" && GIT_SNAP_BEFORE="$DT_F_B" GIT_SNAP_AFTER="$DT_F_AF" bash "$DT_COMPARE_RUN" ) >/dev/null 2>&1
  assert_eq "#484 backstop auth positive control: authentic OID preserves the pre-existing edit" \
    "concurrent edit" "$(cat "$DT_F/my file.txt" 2>/dev/null)"
  assert_eq "#484 backstop auth positive control: authentic OID permits snapshot-delta restore" \
    "plain" "$(cat "$DT_F/plain.txt" 2>/dev/null)"
  rm -rf "$DT_F" "$DT_F_B" "$DT_F_AF"
fi

# Case G — replace the captured baseline with a different regular file after recording its OID.
# Without the digest guard (or with a reversed comparison), the empty forged baseline authorizes
# checkout of BOTH dirty paths. Correct behavior emits the integrity breadcrumb and restores none.
DT_G="$(dt_make_repo)"
if [ -d "$DT_G" ]; then
  DT_G_B="$(probe_tmp "#484 case-G before")"; DT_G_AF="$(probe_tmp "#484 case-G after")"
  DT_G_ERR="$(probe_tmp "#484 case-G stderr")"
  printf 'concurrent edit' > "$DT_G/my file.txt"
  git -C "$DT_G" status --porcelain -z > "$DT_G_B"
  DT_G_OID="$(git hash-object "$DT_G_B")"
  printf 'agent edit' > "$DT_G/plain.txt"
  printf '' > "$DT_G_B"  # forged regular-file baseline
  sed "s/{GIT_SNAP_BEFORE_OID}/$DT_G_OID/g" "$DT_COMPARE" > "$DT_COMPARE_RUN"
  ( cd "$DT_G" && GIT_SNAP_BEFORE="$DT_G_B" GIT_SNAP_AFTER="$DT_G_AF" bash "$DT_COMPARE_RUN" ) >/dev/null 2>"$DT_G_ERR"
  assert_eq "#484 backstop auth: forged regular baseline cannot clobber the pre-existing edit" \
    "concurrent edit" "$(cat "$DT_G/my file.txt" 2>/dev/null)"
  assert_eq "#484 backstop auth: forged regular baseline skips all restoration" \
    "agent edit" "$(cat "$DT_G/plain.txt" 2>/dev/null)"
  assert_eq "#484 backstop auth: forged regular baseline emits the integrity breadcrumb" "yes" \
    "$(grep -qF 'scratch integrity failure, nothing auto-restored' "$DT_G_ERR" && echo yes || echo no)"
  rm -rf "$DT_G" "$DT_G_B" "$DT_G_AF" "$DT_G_ERR"
fi

# Case H — a symlink baseline is rejected before hashing/comparison and its target is untouched.
DT_H="$(dt_make_repo)"
if [ -d "$DT_H" ]; then
  DT_H_TARGET="$(probe_tmp "#484 case-H symlink target")"; DT_H_B="$DT_H/before-link"
  DT_H_AF="$(probe_tmp "#484 case-H after")"; DT_H_ERR="$(probe_tmp "#484 case-H stderr")"
  printf 'target sentinel' > "$DT_H_TARGET"; ln -s "$DT_H_TARGET" "$DT_H_B"
  DT_H_OID="$(git hash-object "$DT_H_TARGET")"
  printf 'agent edit' > "$DT_H/plain.txt"
  sed "s/{GIT_SNAP_BEFORE_OID}/$DT_H_OID/g" "$DT_COMPARE" > "$DT_COMPARE_RUN"
  ( cd "$DT_H" && GIT_SNAP_BEFORE="$DT_H_B" GIT_SNAP_AFTER="$DT_H_AF" bash "$DT_COMPARE_RUN" ) >/dev/null 2>"$DT_H_ERR"
  assert_eq "#484 backstop auth: symlink baseline skips restoration" \
    "agent edit" "$(cat "$DT_H/plain.txt" 2>/dev/null)"
  assert_eq "#484 backstop auth: symlink baseline target is never modified" \
    "target sentinel" "$(cat "$DT_H_TARGET" 2>/dev/null)"
  assert_eq "#484 backstop auth: symlink baseline emits the tamper breadcrumb" "yes" \
    "$(grep -qF 'possible scratch tampering, nothing auto-restored' "$DT_H_ERR" && echo yes || echo no)"
  rm -rf "$DT_H" "$DT_H_TARGET" "$DT_H_AF" "$DT_H_ERR"
fi

# Case I — an attacker-controlled stale AFTER symlink must be removed before the
# shell opens the status redirect. Otherwise `git status` truncates the symlink target.
DT_I="$(dt_make_repo)"
if [ -d "$DT_I" ]; then
  DT_I_B="$(probe_tmp "#484 case-I before")"; DT_I_AF="$DT_I/after-link"
  DT_I_TARGET="$(probe_tmp "#484 case-I stale-after target")"
  git -C "$DT_I" status --porcelain -z > "$DT_I_B"
  DT_I_OID="$(git hash-object "$DT_I_B")"
  printf 'target sentinel' > "$DT_I_TARGET"; ln -s "$DT_I_TARGET" "$DT_I_AF"
  sed "s/{GIT_SNAP_BEFORE_OID}/$DT_I_OID/g" "$DT_COMPARE" > "$DT_COMPARE_RUN"
  ( cd "$DT_I" && GIT_SNAP_BEFORE="$DT_I_B" GIT_SNAP_AFTER="$DT_I_AF" bash "$DT_COMPARE_RUN" ) >/dev/null 2>&1
  assert_eq "#484 after-snapshot: stale symlink is removed before capture, so its target is not clobbered" \
    "target sentinel" "$(cat "$DT_I_TARGET")"
  rm -rf "$DT_I" "$DT_I_B" "$DT_I_AF" "$DT_I_TARGET"
fi

# Case J — a symlink swapped into the AFTER path while `git status` is running is
# rejected as a snapshot failure. Without the post-capture symlink check, the wrapper
# compares attacker-controlled bytes and misclassifies the dispatch.
DT_J="$(dt_make_repo)"
if [ -d "$DT_J" ]; then
  DT_J_B="$(probe_tmp "#484 case-J before")"; DT_J_AF="$DT_J/after"
  DT_J_TARGET="$(probe_tmp "#484 case-J symlink-race target")"
  DT_J_ERR="$(probe_tmp "#484 case-J stderr")"; DT_J_BIN="$DT_J/bin"; mkdir -p "$DT_J_BIN"
  git -C "$DT_J" status --porcelain -z > "$DT_J_B"
  DT_J_OID="$(git hash-object "$DT_J_B")"
  printf 'agent edit' > "$DT_J/plain.txt"; printf 'target sentinel' > "$DT_J_TARGET"
  DT_REAL_GIT="$(command -v git)"
  printf '%s\n' '#!/usr/bin/env bash' \
    'if [ "${1:-}" = status ]; then' \
    '  rm -f "$GIT_SNAP_AFTER"; ln -s "$DT_RACE_TARGET" "$GIT_SNAP_AFTER"' \
    'fi' \
    'exec "$DT_REAL_GIT" "$@"' > "$DT_J_BIN/git"
  chmod +x "$DT_J_BIN/git"
  sed "s/{GIT_SNAP_BEFORE_OID}/$DT_J_OID/g" "$DT_COMPARE" > "$DT_COMPARE_RUN"
  ( cd "$DT_J" && PATH="$DT_J_BIN:$PATH" DT_REAL_GIT="$DT_REAL_GIT" \
      DT_RACE_TARGET="$DT_J_TARGET" GIT_SNAP_BEFORE="$DT_J_B" GIT_SNAP_AFTER="$DT_J_AF" \
      bash "$DT_COMPARE_RUN" ) >/dev/null 2>"$DT_J_ERR"
  assert_eq "#484 after-snapshot: race-swapped symlink skips restoration" \
    "agent edit" "$(cat "$DT_J/plain.txt")"
  assert_eq "#484 after-snapshot: race-swapped symlink emits the attributable capture-failure breadcrumb" "yes" \
    "$(grep -qF 'could not create a regular working-tree snapshot after the Phase 3.1 dispatch' "$DT_J_ERR" && echo yes || echo no)"
  assert_eq "#484 after-snapshot: symlink-race target remains untouched" \
    "target sentinel" "$(cat "$DT_J_TARGET")"
  rm -rf "$DT_J" "$DT_J_B" "$DT_J_AF" "$DT_J_TARGET" "$DT_J_ERR"
fi
rm -f "$DT_COMPARE" "$DT_COMPARE_RUN"
# Guard the SKILL-side schema statement that detect_all_audit is not persisted.
assert_pin_unique "#167 coupled-site: SKILL.md states detect_all_audit is intentionally not persisted" \
  'detect_all_audit`, is intentionally **not** persisted here' "$MAXI_SKILL"

# The Phase 2.3 sweep's executable contract lives in the implement-skill bundle:
# its sweep body plus the "Sweep selection" always-run index in
# phases/phase-2-implement.md. Those operative sites remain protected below through
# $IMPL_SKILL_BUNDLE / $P2_FILE assertions. The rationale table in
# docs/internal/implement-skill.md is a secondary prose mirror: issue #1188 retires
# its row-presence pins (see the cluster note below), while the surviving derived
# cross-site enumeration still reconciles the overall contract-sweep membership.
IMPL_SKILL="$IMPL_SKILL_BUNDLE"   # issue #218: the whole implement-skill bundle (orchestrator + 4 phase files)
IMPL_DOC="$LIB/../docs/internal/implement-skill.md"

# ── issue #218: implement skill split into orchestrator + per-phase reference files ──
# The implement skill is now a thin orchestrator (skills/implement/SKILL.md) plus four
# phases/phase-N-*.md reference files read on-demand at phase entry; IMPL_SKILL/DEF_SKILL
# above point at the CONCATENATED bundle of all five so the content pins are
# location-agnostic within the implement skill. These structural assertions guard the
# split itself, against the real orchestrator file and phases/ dir (NOT the bundle): the
# phase files exist & are non-empty; no phase file can be mistaken for an auto-discovered
# nested skill (none named SKILL.md under phases/); and the orchestrator carries an
# entry-gate read-instruction for each phase file, so a future edit cannot silently drop a
# phase's load step (which would make the engine improvise that phase from its thin stub).
IMPL_ORCH="$LIB/../skills/implement/SKILL.md"
IMPL_PHASES_DIR="$LIB/../skills/implement/phases"
# Shared phase-file path, colocated with its parent IMPL_PHASES_DIR so the #232 and #230
# pin blocks below reference one source of truth for the path (not two differently-named locals).
P4_FILE="$IMPL_PHASES_DIR/phase-4-documentation.md"
IMPL_REFS_DIR="$LIB/../skills/implement/references"
# Issue #1374 relocated §4.0.5's filing procedure out of the phase file and behind a
# predicate-gated reference, so every pin whose literal lives inside that procedure now
# names this path. The pins were re-targeted rather than deleted — with one recorded
# retirement, marked at its own site below — because a pin left on the phase file reports
# a count of zero and passes nothing.
P405_REF="$IMPL_REFS_DIR/deferred-review-findings.md"
# Directory-reconciliation: the actual phases/*.md files must equal IMPL_PHASE_STEMS — the
# single registered phase set the bundle members and the per-phase loop both derive from. A
# future phase file added to the directory (and wired into the orchestrator) WITHOUT being
# registered in IMPL_PHASE_STEMS would otherwise be silently dropped from the bundle and the
# per-phase coverage (its content pins/guards would under-cover it with zero RED); this fails
# RED instead. Reconciling against the directory, not just hand-listing, is what closes the
# coupled-site hazard of two hand-maintained mirrors. (`-maxdepth 1`: phases/ is flat; the
# misregistration guard below separately forbids a nested SKILL.md.)
_actual_phase_stems=$(find "$IMPL_PHASES_DIR" -maxdepth 1 -name '*.md' -type f -exec basename {} .md \; 2>/dev/null | sort | tr '\n' ' ' | sed 's/ *$//')
_registered_phase_stems=$(printf '%s\n' $IMPL_PHASE_STEMS | sort | tr '\n' ' ' | sed 's/ *$//')
assert_eq "implement split: phases/ dir holds exactly the registered phase set (no unregistered / missing phase file)" \
  "$_registered_phase_stems" "$_actual_phase_stems"
# #644 review finding 1: P4_FILE's "Span-suppression breadcrumb disclosure" quotes a
# breadcrumb literal that MUST match what scripts/extract-doc-needed-paths.sh actually
# emits (`suppressed a span …`). A quoted phrase the extractor never emits is a documented
# falsehood — the self-contradicting-diff carve-out. The wrong "non-path span" phrasing also
# reintroduces the dishonest characterization the script's suppress_span() comment deliberately
# removed (a suppressed multi-token span may have carried a genuine deliverable, so the phrase
# must NOT assert "a command literal" as fact). Pin both directions so the disclosure can never
# drift from the emission again.
assert_eq "#644 review: P4_FILE quotes the extractor's actual breadcrumb phrase (\`suppressed a span\`)" \
  "1" "$(grep -c 'suppressed a span' "$P4_FILE")"
assert_eq "#644 review: P4_FILE does not quote the never-emitted 'non-path span' phrasing" \
  "0" "$(grep -c 'suppressed a non-path span' "$P4_FILE")"
# The resolve-once preamble carries its own ${CLAUDE_SKILL_DIR}-empty fail-closed contract;
# the per-phase loop guards each phase's routing from the single gate statement (issue #1566),
# and the mandatory-read / halt / placeholder clauses are guarded count-free just below it.
assert_pin_unique "implement split: orchestrator preamble fails closed when \${CLAUDE_SKILL_DIR} does not resolve" \
  "did not resolve" "$IMPL_ORCH"
# One loop over the single phase-stem list checks each per-phase invariant: the phase file
# exists & is non-empty; the orchestrator ROUTES the phase from its single gate statement (a
# backticked `<stem>.md` mention, issue #1566); the phase file carries its own phase heading;
# and its boundary markers are canonical. Since #1566 the mandatory-read / fail-closed-halt /
# placeholder semantics are no longer per-phase — they are guarded count-free on the one gate
# statement just below the loop — so this loop pins routing, not those clauses. One loop
# header → one place the stem list is maintained.
for _pf in $IMPL_PHASE_STEMS; do
  _n="${_pf#phase-}"; _n="${_n%%-*}"   # phase-1-setup -> 1
  assert_eq "implement split: phases/${_pf}.md exists and is non-empty" "yes" \
    "$([ -s "$IMPL_PHASES_DIR/${_pf}.md" ] && echo yes || echo no)"
  # issue #1566: the orchestrator states the entry-gate rule ONCE, in the preamble, and
  # routes each phase from that single statement by a backticked reference-file mention
  # (the REVIEW_PHASE_STEMS routing shape). Assert that routing per stem by counting the
  # backticked `${_pf}.md` mention — a count form (not `grep -qF`) so this dynamic-literal
  # site is not a raw-presence pin the static classifier cannot inspect; deleting one
  # stem's mention drops its count to 0 and fails RED naming that stem. The single
  # statement's mandatory-read / halt / placeholder clauses are guarded count-free just
  # below the loop.
  assert_eq "implement split: orchestrator routes ${_pf}.md from the single gate statement (backticked mention)" "1" \
    "$(grep -cF '`'"${_pf}.md"'`' "$IMPL_ORCH")"
  # Phase-identity check (shadow-pass finding): the routing pin above greps $IMPL_ORCH for a
  # backticked `<stem>.md` mention, a whole-file presence, so a same-length cross-phase swap (e.g. phase-2-implement.md and
  # phase-3-review.md bodies accidentally exchanged) would leave them green — the tokens are
  # still present somewhere in the bundle. Grep the OWNING FILE directly (not the bundle) for
  # its own phase heading, the one thing that must live in THAT file and no other.
  # Anchored to the START of the line (`^`), not a bare substring match (fix-delta gate
  # finding): an unanchored match would false-PASS a swap whose real heading was lost but
  # whose phase number still happened to appear elsewhere in the body (a stray prose
  # cross-reference, a TOC entry) — the predicate must match the structural heading
  # position, not just "the digit appears somewhere in the file".
  assert_eq "implement split: phases/${_pf}.md carries its own Phase ${_n} heading (not a cross-phase swap)" "yes" \
    "$(grep -qE "^## Phase ${_n}:" "$IMPL_PHASES_DIR/${_pf}.md" && echo yes || echo no)"
  # issue #1551: match the WHOLE canonical marker line, never the path or a bare `start -->`
  # tail: a marker naming the wrong phase number is the `boundary: misrouted` shape that halts
  # every /prflow:implement run at runtime, and a path-only assertion stays green on it.
  _impl_start_marker="<!-- prflow:implement-ref phase=${_n} file=skills/implement/phases/${_pf}.md start -->"
  _impl_end_marker="<!-- prflow:implement-ref phase=${_n} file=skills/implement/phases/${_pf}.md end -->"
  assert_eq "implement boundary: phases/${_pf}.md start marker is the literal FIRST line and names its own phase and path" "yes" \
    "$(head -1 "$IMPL_PHASES_DIR/${_pf}.md" | grep -qxF -- "$_impl_start_marker" && echo yes || echo no)"
  assert_eq "implement boundary: phases/${_pf}.md end marker is the literal LAST line and names its own phase and path" "yes" \
    "$(tail -1 "$IMPL_PHASES_DIR/${_pf}.md" | grep -qxF -- "$_impl_end_marker" && echo yes || echo no)"
  assert_eq "implement boundary: phases/${_pf}.md carries exactly one start and one end marker (no duplicate)" "1|1" \
    "$(grep -cxF -- "$_impl_start_marker" "$IMPL_PHASES_DIR/${_pf}.md" | tr -d ' ')|$(grep -cxF -- "$_impl_end_marker" "$IMPL_PHASES_DIR/${_pf}.md" | tr -d ' ')"
  # The set-membership line is the SOLE operand of the orchestrator's `boundary: set-incomplete`
  # stop, so an absent, duplicated or stale one makes that stop unreachable rather than noisy.
  # `of=` is reconciled against the registered stem count for this phase, never transcribed.
  # Scoped to MULTI-file phases, matching the orchestrator's own contract: a single-file phase
  # carries no such line, and asserting one would demand bytes those files do not have under the
  # reference-size ceiling. Both directions are checked, so a stray line is caught too.
  _phase_member_count=0
  for _peer in $IMPL_PHASE_STEMS; do
    case "$_peer" in phase-"$_n"-*) _phase_member_count=$((_phase_member_count + 1)) ;; esac
  done
  _impl_set_line=$(sed -n '2p' "$IMPL_PHASES_DIR/${_pf}.md")
  if [ "$_phase_member_count" -gt 1 ]; then
    assert_eq "implement set-marker: phases/${_pf}.md line 2 names its phase and the registered member count" "yes" \
      "$(printf '%s' "$_impl_set_line" | grep -qE "^<!-- prflow:implement-set phase=${_n} part=[1-9][0-9]* of=${_phase_member_count} -->$" && echo yes || echo no)"
  else
    assert_eq "implement set-marker: single-file phases/${_pf}.md carries no set-membership line" "no" \
      "$(printf '%s' "$_impl_set_line" | grep -q 'prflow:implement-set' && echo yes || echo no)"
  fi
done
# Every phase's set-membership lines must cover 1..n exactly once: a duplicated `part=` leaves a
# member unrepresented while each file's own line still looks well-formed.
for _n in 1 2 3 4; do
  _expect=""; _got=""; _i=0
  for _pf in $IMPL_PHASE_STEMS; do
    case "$_pf" in
      phase-"$_n"-*)
        _i=$((_i + 1)); _expect="$_expect $_i"
        _got="$_got $(sed -n '2p' "$IMPL_PHASES_DIR/${_pf}.md" | sed -n 's/.* part=\([0-9][0-9]*\) .*/\1/p')"
        ;;
    esac
  done
  [ "$_i" -gt 1 ] || continue   # single-file phases carry no parts to cover
  assert_eq "implement set-marker: phase $_n parts cover 1..n exactly once" \
    "$(printf '%s' "$_expect" | tr ' ' '\n' | sort -n | tr -d '\n')" \
    "$(printf '%s' "$_got" | tr ' ' '\n' | sort -n | tr -d '\n')"
done
# issue #1566: the four per-phase entry-gate paragraphs were collapsed into ONE gate
# statement in the orchestrator preamble. These guards replace the retired per-phase
# assert_pin_unique triple: they prove the single surviving statement still carries each
# load-bearing clause (a mandatory-read imperative, the fail-closed halt, and the
# placeholder-aware halt), count-free (a `grep -cF` occurrence count asserted `-ge 1`, never
# `grep -qF`). The count form is deliberate on two axes: `-ge 1` keeps it count-free (an
# unrelated later occurrence of a clause elsewhere leaves it green — the AC7 requirement),
# and `grep -cF` (not the quiet `grep -qF`) is not a raw-presence pin, so the static pin
# classifier does not enumerate it and it needs no `# structural-pin-ok:` adjudication — the
# same reason the routing count above and the AC6 guards below use the count form. This proves
# each clause is present SOMEWHERE in the orchestrator, which equals presence in the gate
# statement only while that statement is the clause's sole home (true today: each phrase
# occurs exactly once). Deleting a clause from the statement without relocating it — the
# realistic downgrade to an inert "see also phases/…" pointer — drops its count to 0 and turns
# the matching guard RED; the routing-count and phase-identity guards cover the co-location
# whole-file presence alone does not.
assert_eq "#1566: the single entry-gate statement carries a mandatory-read imperative (not an inert see-also pointer)" "yes" \
  "$([ "$(grep -cF 'before taking any action in it' "$IMPL_ORCH")" -ge 1 ] && echo yes || echo no)"
assert_eq "#1566: the single entry-gate statement carries the fail-closed halt-with-breadcrumb clause" "yes" \
  "$([ "$(grep -cF 'halt that phase with an attributable breadcrumb' "$IMPL_ORCH")" -ge 1 ] && echo yes || echo no)"
assert_eq "#1566: the single entry-gate statement carries the placeholder-aware halt clause (count-free)" "yes" \
  "$([ "$(grep -cF 'is empty or an unsubstituted placeholder' "$IMPL_ORCH")" -ge 1 ] && echo yes || echo no)"
# AC6 — no static pin call may target the orchestrator's per-phase entry-gate text. Matching a
# pin head and its argument on ONE physical line would slip past a two-line
# `assert_pin_unique "label" \` call whose gate-text argument sits on the continuation line
# (the exact multi-line form this change retired). Instead assert each per-phase gate literal
# appears in run.sh ONLY on its own needle-definition line below: restoring any pin that
# targets that text — single- or multi-line — reintroduces the literal and pushes the count to
# 2, RED. The needles are assembled into locals so these two definition lines are the sole
# legitimate occurrence, and the assert labels below carry neither fragment, so this block
# cannot self-match.
_ppg_framing_needle="before any Phase"
_ppg_halt_needle="halt Phase "
assert_eq "#1566: the per-phase entry-gate framing literal appears in run.sh only as its own needle definition (no pin targets it)" "1" \
  "$(grep -cF -- "$_ppg_framing_needle" "$LIB/test/run.sh")"
assert_eq "#1566: the per-phase entry-gate halt literal appears in run.sh only as its own needle definition (no pin targets it)" "1" \
  "$(grep -cF -- "$_ppg_halt_needle" "$LIB/test/run.sh")"
# Misregistration guard: a present-but-empty stdout from find means NO SKILL.md under
# phases/. find over a missing dir also prints nothing (2>/dev/null), but the existence
# assertions above independently fail closed when the dir/files are absent, so this guard
# is non-vacuous once the split exists.
assert_eq "implement split: no SKILL.md under phases/ (no nested auto-discovered skill)" "" \
  "$(find "$IMPL_PHASES_DIR" -name SKILL.md 2>/dev/null)"

# ── issue #429: stale-checkout guard for adopted branches (phase-1 §1.4/§1.6, phase-2 §2.1, phase-4 §4.0) ──
# Four bounded prose rules keep an ADOPTED-branch run from adjudicating truth against a stale
# checkout (the #325 false-refutation incident). The coherence-rule and read-target-rule sites
# are COUPLED MIRRORS (phase-1-setup.md §1.6 ↔ phase-2-implement.md §2.1). Each mirror is
# checked independently so removal at either site fails.
P1_FILE="$IMPL_PHASES_DIR/phase-1-setup.md"
P2_FILE="$IMPL_PHASES_DIR/phase-2-implement.md"
# P4_FILE already defined above (phase-4-documentation.md).
# #1582 moved §1.4's resume-precheck / Signals / creation / Verdict-B procedure out of
# phase-1-setup.md into the dispatched agents/branch-setup.md (mirroring #1576's §1.6 move).
# Pins that assert the MOVED §1.4 branch-setup PROSE now target that agent file; the §1.6
# fresh-tree coupled mirrors (T4 below) and the checkpoint/§1.5 sites STAY in phase-1-setup.md.
P1582_BS="$LIB/../agents/branch-setup.md"

# T1 — freshness guard on the USE_CURRENT (adopted-branch) arm — now in branch-setup.md.
# The fetch literal carries the FORCED refspec since #779 (an unforced fetch can leave
# refs/remotes/origin/$BASE unadvanced, so the rev-list below reads a false behind-by 0); the
# forced-refspec property itself is pinned in the #779 block below.
# behind-by derivation (guard-class 2: git produces the count, bash builtins compare it).
assert_pin_unique "429/T1: branch-setup derives behind-by via git rev-list --count HEAD..origin/\$BASE" \
  'git rev-list --count "HEAD..origin/$BASE"' "$P1582_BS"
# T2 — degraded arm: a fetch failure records freshness-unverified and CONTINUES (never exit 1).
# AC2 "never hard-blocks adoption" — the fetch-failure arm must CONTINUE, not exit 1 (the
# create-arm's exit-1 contract is separately pinned and unchanged). T2 above pins the
# else-arm reflection sentence, but a regression that ADDED an `exit 1` to the adopted arm
# would keep that sentence and still pass — so pin the *continues* half directly: assert the
# USE_CURRENT freshness block carries no `exit` STATEMENT (a line-leading `exit`), while its
# comments deliberately MENTION "exit 1" in prose (those start with `#`, so the anchored
# pattern never matches them). Adding a real `exit 1` to the else arm flips this RED. The awk
# range ends at the "## Verdict B" heading that follows the Signals/freshness block in
# branch-setup.md (the create fence with its exit-1 sits AFTER Verdict B, outside the range).
assert_eq "429/T2: branch-setup adopted-branch freshness block never hard-blocks (no line-leading exit statement)" "0" \
  "$(awk '/Freshness guard \(adopted-branch arm\)/,/## Verdict B/' "$P1582_BS" | grep -cE '^[[:space:]]*exit ' || true)"

# T4 — cross-pass coherence rule, BOTH coupled mirror sites.
# MERGED + non-ancestor arm (the read-only merge-state + ancestry check), both sites.
assert_pin_unique "429/T4: §1.6 carries the MERGED+non-ancestor merge-base ancestry check" \
  'git merge-base --is-ancestor <merge_commit_sha> HEAD' "$P1_FILE"
assert_pin_unique "429/T4: §2.1 carries the MERGED+non-ancestor merge-base ancestry check (coupled mirror)" \
  'git merge-base --is-ancestor <merge_commit_sha> HEAD' "$P2_FILE"
# Indeterminate fail-closed arm (gh failure / shallow-history error → stale-suspect), both sites.
assert_pin_unique "429/T4: §1.6 indeterminate arm fails closed (a refutation requires a positively-fresh tree)" \
  'requires a positively-fresh tree' "$P1_FILE"
assert_pin_unique "429/T4: §2.1 indeterminate arm fails closed (coupled mirror)" \
  'requires a positively-fresh tree' "$P2_FILE"
# #761 — §4.2's PR-body reconciliation is a three-class claim audit (behavioral,
# verification, artifact-existence), each with its own comparand.
# T7 — no-new-grants. The new prose (Phase 1.6 fresh-tree verification + Phase 2.1 code-wins
# pass) executes during a /devflow:implement run, and `devflow-implement.yml` is the SINGLE
# workflow that runs /devflow:implement — both the automated pickup AND a manual bare
# `/devflow:implement <#>` comment fire it (devflow.yml is the LIGHT listener for
# /devflow:review, /devflow:review-and-fix, /devflow:pr-description ONLY; its trigger `if:`
# negates /devflow:implement, and its header states "the heavy /devflow:implement path lives in
# devflow-implement.yml"). So the load-bearing grant surface for the coherence rule's read-only
# `gh pr view N --json state,mergeCommit` + `git merge-base --is-ancestor` is
# devflow-implement.yml's inline --allowed-tools, and NOTHING else executes this prose. Both
# commands are already granted there, so no new grant is needed; pin exactly that surface (so a
# future removal from the file that actually gates the implement run turns RED — the #363
# silent-denial trap), plus the two implement-tier config allowed_tools arrays adding NO narrow
# merge-base/pr-view grant. Deliberately NOT pinned here, because the implement prose never runs
# under them: devflow.yml (the /devflow:review family listener) and devflow-runner.yml (the
# read-only review profile) — pinning either would give false implement-tier assurance.
_DI429="$LIB/../.github/workflows/devflow-implement.yml"   # the ONLY workflow that runs /devflow:implement (auto + manual comment)
_C429="$LIB/../.prflow/config.json"
assert_eq "429/T7: devflow-implement.yml --allowed-tools already grants git merge-base (implement tier — the only tier running the prose; no new grant)" "1" \
  "$(grep -cF 'Bash(git merge-base:*)' "$_DI429" || true)"
assert_eq "429/T7: devflow-implement.yml --allowed-tools already grants gh pr view (implement tier — the only tier running the prose; no new grant)" "1" \
  "$(grep -cF 'Bash(gh pr view:*)' "$_DI429" || true)"
assert_eq "429/T7: prflow_implement.allowed_tools adds no merge-base/pr-view grant" "0" \
  "$(jq -r '.prflow_implement.allowed_tools[]? | select(test("merge-base|pr view"))' "$_C429" 2>/dev/null | grep -c . || true)"
assert_eq "429/T7: prflow.allowed_tools adds no merge-base/pr-view grant" "0" \
  "$(jq -r '.prflow.allowed_tools[]? | select(test("merge-base|pr view"))' "$_C429" 2>/dev/null | grep -c . || true)"

# ── F1 (review): STANDING anti-vacuity proofs for the new fail-closed guards ───────────────
# The guards above are non-vacuous by construction, but the project discipline (the
# git_sandbox AC3 probes, "bake the half-revert into the suite — do not leave it a one-time
# manual act") requires that fail-closed property to be a STANDING test, not a one-time
# manual mutation. Each proof exercises the guard's real predicate/pipeline on a synthetic
# mutated input and asserts the fail-closed DIRECTION, so a future refactor that weakens a
# guard (drops the `[ -r ]`/`[ -s ]` clause, breaks the reconciliation comparison, or
# narrows the SKILL.md find) turns the suite RED here instead of silently passing.
# (a) the FACTORED bundle-member predicate (the EXACT function the bundle build calls, so no
#     replica drift) fails CLOSED on missing / empty / unreadable, and PASSES on a real file.
_f1_missing="$IMPL_PHASES_DIR/.f1-nonexistent-$$"
assert_eq "F1: bundle-member predicate fails closed on a MISSING member" "no" \
  "$(_bundle_member_usable "$_f1_missing" && echo yes || echo no)"
_f1_empty=$(probe_tmp "F1 empty-member proof"); : > "$_f1_empty"
assert_eq "F1: bundle-member predicate fails closed on an EMPTY member" "no" \
  "$(_bundle_member_usable "$_f1_empty" && echo yes || echo no)"
assert_eq "F1: bundle-member predicate PASSES on a real readable non-empty phase file (not trivially false)" "yes" \
  "$(_bundle_member_usable "$IMPL_PHASES_DIR/phase-1-setup.md" && echo yes || echo no)"
# the unreadable arm (S1's specific case) only when non-root — `[ -r ]` is always true as root.
if [ "$(id -u)" != 0 ]; then
  _f1_unreadable=$(probe_tmp "F1 unreadable-member proof"); printf 'x\n' > "$_f1_unreadable"; chmod a-r "$_f1_unreadable"
  assert_eq "F1: bundle-member predicate fails closed on an UNREADABLE member" "no" \
    "$(_bundle_member_usable "$_f1_unreadable" && echo yes || echo no)"
  chmod u+rw "$_f1_unreadable" 2>/dev/null || true
fi
# (b) the directory-reconciliation pipeline detects an unregistered stem — a synthetic dir
#     holding a rogue phase file yields an actual set != the registered set (RED). Exercises
#     the same find|sort|tr|sed pipeline shape the real reconciliation uses.
# Allocate via git_sandbox (not a bare `if mktemp -d`): a denied `mktemp -d` must FAIL the
# suite, not silently skip the proof — the exact fail-open this anti-vacuity block exists to
# prevent. git_sandbox records a suite FAIL and returns a /dev/null-rooted sentinel, so the
# `: >`/`find` below fail closed (ENOTDIR) with zero real-repo mutation.
_f1_recon=$(git_sandbox "F1 reconciliation-pipeline anti-vacuity proof")
: > "$_f1_recon/phase-1-setup.md"; : > "$_f1_recon/phase-9-rogue.md"
_f1_actual=$(find "$_f1_recon" -maxdepth 1 -name '*.md' -type f -exec basename {} .md \; 2>/dev/null | sort | tr '\n' ' ' | sed 's/ *$//')
# POSITIVE assertion (not "!= single-stem", which an empty/garbled pipeline output would
# also satisfy vacuously): the pipeline must enumerate EXACTLY the synthetic two-stem set,
# proving the enumeration works AND that the rogue stem makes the set differ from any
# 4-stem registered set — so the real reconciliation's assert_eq would go RED.
assert_eq "F1: reconciliation pipeline enumerates a synthetic dir's exact stem set (incl. the rogue, differs from registered)" \
  "phase-1-setup phase-9-rogue" "$_f1_actual"
rm -rf "$_f1_recon"
# (c) the no-SKILL.md misregistration guard detects an injected SKILL.md (find non-empty → != "").
#     Same fail-closed allocation discipline as (b).
_f1_skilldir=$(git_sandbox "F1 misregistration-guard anti-vacuity proof")
: > "$_f1_skilldir/SKILL.md"
assert_eq "F1: misregistration guard detects an injected SKILL.md (find non-empty → RED)" "no" \
  "$([ -z "$(find "$_f1_skilldir" -name SKILL.md 2>/dev/null)" ] && echo yes || echo no)"
rm -rf "$_f1_skilldir"
# ── end issue #218 structural assertions ──
# ── issue #232: the Phase 4.1 post-subagent re-anchor (phase-4-documentation.md), guarding
# against a run that stops before Phase 4 finalization (workpad frozen at an in-progress
# Status, un-described draft PR). Coupled to the skill clause: removing it turns the suite
# RED.
# (P4_FILE is the shared phase-file path hoisted next to IMPL_PHASES_DIR above.)
# Do not re-point this pin at §4.2's re-anchor or widen its literal: the literal is
# grandfathered as unique to the §4.1 note, and §4.2's counterpart is agent-executed prose
# that owes no pin (CLAUDE.md #843/#876). Provenance: docs/internal/implement-skill.md.
assert_pin_unique "#232/#362: phase-4 re-anchor scoped to **subagent** returns (AC4, reworded)" \
  'scoped to **subagent** returns' "$P4_FILE"
# review iter-2 (shadow pr-test-analyzer): pin the operative re-read instruction directly —
# the Phase 4.1 re-anchor TRIGGER is repeated in the always-loaded orchestrator so a
# subagent-return eviction cannot remove it, and dropping the pin drops that hardening.
assert_pin_unique "#232: orchestrator keeps the OPERATIVE always-loaded re-Read directive (SFH F2)" \
  'the phase file before continuing to §4.2 (resume from §4.2' "$IMPL_ORCH"
# AC4 scope constraint is mirrored in the always-loaded orchestrator too; pin that copy so the
# "not the Phase 2/3 returns" guardrail can't be dropped from the resident mirror unnoticed.
# Reworded by #362 (see the phase-4 block above) to scope the trigger to SUBAGENT returns,
# since a Skill-tool return now has its own generalized re-anchor in the same resident body.
assert_pin_unique "#232/#362: orchestrator mirror scopes the re-anchor to **subagent** returns (SFH F2 mirror)" \
  'scoped to **subagent** returns, not the Phase 2/3 subagent returns' "$IMPL_ORCH"

# ── issue #362: run-continuity guards. Three always-resident cross-phase rules in the
# orchestrator (generalized mid-phase re-anchor after ANY Skill-tool return; the
# non-interactive self-answer rule; the Agent-subagent dispatch path for interactive
# skills), plus the run-marker lifecycle (written in Phase 1.3, removed at every terminal
# Status transition) and the Phase 1.4 resume pre-check. Each pin below targets the
# OPERATIVE sentence — the minimal text whose removal alone re-introduces the #356 defect
# class (a run that dies mid-phase on a nested skill's tail call, or a resume that forks a
# second branch + PR) — never an adjacent framing clause. Independent exactly-once pins
# keep each current source boundary observable on every suite execution.
P362_P1="$IMPL_PHASES_DIR/phase-1-setup.md"

# (1) Generalized mid-phase re-anchor — fires after EVERY Skill-tool return, not just the
#     Phase 4.1 docs subagent.
assert_pin_unique "#362: orchestrator re-anchors after every Skill-tool return (trigger)" \
  'after **every** Skill-tool return mid-phase' "$IMPL_ORCH"
assert_pin_unique "#362: generalized re-anchor carries its operative resume directive" \
  'resume at the step immediately following the invocation, never re-dispatching the skill that just returned' "$IMPL_ORCH"

# (2) Non-interactive self-answer rule — the orchestrator answers a nested skill's
#     user-facing question itself on the cloud tier, and records the answer.
#     The tier gate is OPERATIVE, not framing: drop it and the rule would authorize an
#     INTERACTIVE run to answer the user's questions for them without asking. So pin the
#     `GITHUB_ACTIONS` keying itself — not just the prose lead-in, which a same-sentence
#     edit could keep while swapping the gating env var — as its own exactly-once boundary.
assert_pin_unique "#362: self-answer rule keys on the non-interactive tier by GITHUB_ACTIONS" \
  'When the run is non-interactive — `GITHUB_ACTIONS` is set (the cloud tier)' "$IMPL_ORCH"
assert_pin_unique "#362: self-answer rule carries its operative answer directive" \
  'answer that question yourself on behalf of the user, using the issue description as the primary guide' "$IMPL_ORCH"
assert_pin_unique "#362: self-answer rule requires recording each self-answered decision" \
  'record each self-answered question and the answer you chose in the workpad via `--note`' "$IMPL_ORCH"
assert_pin_unique "#362: self-answer rule is confined to a nested skill question (a Blocked pause stays a pause)" \
  'a workpad `Blocked` pause stays a pause' "$IMPL_ORCH"

# (3) Interactive skills are dispatched into an Agent-tool subagent, never Skill-invoked
#     mid-phase. Both halves are operative: the positive dispatch directive AND the
#     prohibition it replaces (dropping either re-opens the #356 tail-call death).
assert_pin_unique "#362: Skill rule routes an interactive skill into an Agent-tool subagent" \
  'dispatch that skill inside a context-isolated **Agent-tool subagent** whose prompt pre-grants the approval' "$IMPL_ORCH"
assert_pin_unique "#362: Skill rule forbids the mid-phase Skill-tool invocation it replaces" \
  'never invoke it through the Skill tool mid-phase' "$IMPL_ORCH"

# (4) Run-marker lifecycle. Written in Phase 1.3 (both the fresh and the resume arm);
#     removed by the always-resident Outcome-reaction block, which already binds every
#     terminal Status transition. Coupled to lib/implement-stop-guard.sh, which globs
#     exactly this path — change one site and this pin names the other.
# Keep this a presence check, not assert_pin_unique: the path's occurrence count is prose-driven
# and has already changed once (#1721 collapsed two marker fences into one instruction).
assert_eq "#362: Phase 1.3 writes the run marker the Stop-hook guard globs" "yes" \
  "$(grep -qF '<scratch-dir>/implement-active-$ISSUE_NUMBER' "$P362_P1" && echo yes || echo no)"  # structural-pin-ok: routing-dispatch-contract -- the run-marker path the Stop-hook guard globs, in the issue-#1633 anchored spelling (<scratch-dir> resolves to the same .prflow/tmp the guard globs); coupled to lib/implement-stop-guard.sh
assert_pin_unique "#362: the Outcome-reaction block removes the run marker at every terminal transition" \
  'remove the Phase 1.3 run-marker' "$IMPL_ORCH"
# The marker filename is a THREE-site coupled invariant: the Phase 1.3 write (pinned above),
# the guard's glob (covered functionally by every marker test), and the Outcome-reaction
# removal command. The prose pin above binds the removal *obligation*; this one binds the
# removal *path*, so a drift in the orchestrator's `rm` literal alone cannot slip through
# (it would only delay cleanup — the guard self-heals — but a silent desync is the defect).
assert_pin_unique "#362: the Outcome-reaction removal targets the exact path the guard globs" \
  '.prflow/tmp/implement-active-$ISSUE_NUMBER' "$IMPL_ORCH"

# (5) Phase 1.4 resume pre-check — runs BEFORE Signal 1, so a harness-created worktree can
#     no longer shadow an existing feature branch + open PR (the #356 resume defect).
# These are model-executed safety contracts with no executable implementation. The static
# count checks below preserve the required query shapes.
# A `gh` failure and a clean "no PRs found" both produce an empty result. Collapsing them
# makes an unresolvable query read as "nothing to resume" and forks a duplicate branch+PR.
# The assertion below checks both `gh pr list` calls retain their same-statement
# `|| PR_JSON=''` handler, which distinguishes a failed query from a clean empty one.
assert_eq "#362: both resume-pre-check gh queries mark an unresolvable result distinctly (same-statement handler)" \
  "2" "$(pin_count "|| PR_JSON=''; }" "$P1582_BS")"
# Both queries must request `closingIssuesReferences`, so this remaining count guard keeps
# the selector's required predicate input available. Issue #780 added `isCrossRepository` to
# the same two `--json` lists — §1.4.0.5's open-PR-linkage provenance source requires a
# same-repo-headed PR and fails CLOSED on an ungathered field, so a query that stops fetching
# it silently costs every landed resume its classification. Same guarantee, one more field.
assert_eq "#362/#780: both resume-pre-check queries fetch the predicate/provenance inputs they read" \
  "2" "$(pin_count ',createdAt,closingIssuesReferences,isCrossRepository)' "$P1582_BS")"

# (6) The two vendored superpowers skills stay untouched by this change (AC).
assert_eq "#362: the vendored receiving-code-review skill is still present and unvendored-from" "yes" \
  "$([ -f "$LIB/../skills/receiving-code-review/SKILL.md" ] && echo yes || echo no)"
assert_eq "#362: the vendored requesting-code-review skill is still present and unvendored-from" "yes" \
  "$([ -f "$LIB/../skills/requesting-code-review/SKILL.md" ] && echo yes || echo no)"

# ── issue #366: guard /devflow:implement against a nested-Skill tail-call early-stop.
# Three prose contracts in the always-resident orchestrator ($IMPL_ORCH) — the completion
# re-anchor, the exclusionary Skill rule, and the carve-out's SKILL.md sentence — one of
# which (the carve-out) is a coupled pair whose other half is a CLAUDE.md Conventions
# bullet pinned against the CLAUDE.md path.
# Each operative sentence is pinned with assert_pin_unique (exactly-once)
# at the owning file boundary via assert_pin_unique.
# (a) Skill-completion re-anchor trigger — completion-anchored, never re-invoke, orchestrator-resident.
assert_pin_unique "#366: SKILL re-anchor is completion-anchored, not tool-return-anchored (operative)" \
  'anchored on completion of the nested *procedure*, **not** on the' "$IMPL_ORCH"
assert_pin_unique "#366: SKILL re-anchor resumes the step and never re-invokes the nested skill (operative)" \
  'resume the interrupted step, never re-invoking the nested skill' "$IMPL_ORCH"
# (b) exclusionary Skill rule.
assert_pin_unique "#366: SKILL rule forbids the interactive skills mid-run, naming revise-claude-md/brainstorming (operative)" \
  '`claude-md-management:revise-claude-md` and the `superpowers` `brainstorming` skill are examples that must never be invoked from inside an autonomous phase' "$IMPL_ORCH"
# (c) carve-out COUPLED PAIR — SKILL.md sentence AND the CLAUDE.md Conventions bullet.
# Deleting either coupled half makes its exact-one assertion fail.
assert_pin_unique "#366: SKILL carve-out — required CLAUDE.md edit made directly by the orchestrator (operative)" \
  'is made **directly by the orchestrator**, citing the carve-out and recording it in the workpad' "$IMPL_ORCH"
assert_pin_unique "#366: CLAUDE.md carve-out bullet mirrors the SKILL rule (coupled half)" \
  'is made **directly by the orchestrator**, citing this carve-out and recording it in the workpad, **never** by invoking' "$LIB/../CLAUDE.md"
# (c') the AC4 WIDENING arm — the carve-out must cover a review finding *or the issue's own
# acceptance criteria*. A partial narrowing edit that strikes only the widening clause (reverting
# to the pre-#366 review-findings-only form) leaves the (c) substrings intact, so pin the widening
# clause on BOTH files so un-widening either side flips RED. Literal is apostrophe-free (stops before
# "issue's") per the CLAUDE.md single-quote/apostrophe gotcha.
assert_pin_unique "#366: SKILL carve-out is widened to cover the issue's own ACs (AC4 widening arm)" \
  'whether by a Phase-3 review finding **or by the issue' "$IMPL_ORCH"
assert_pin_unique "#366: CLAUDE.md carve-out bullet carries the same AC4 widening arm (coupled)" \
  'whether by a Phase-3 review finding **or by the issue' "$LIB/../CLAUDE.md"
# Do not reintroduce a wording pin over the SKILL.md terminal-status self-check: issue #1768
# retired the status-read and stall-backstop-citation pins that stood here, and a
# replacement re-freezes wording that criterion released (CLAUDE.md prose-pin policy).
# ── issue #254: Phase 4.0.5 deferrals-manifest discovery must search BOTH the pr-<N>
# slug dir and the sanitized-current-branch slug dir — a current-branch-mode
# /devflow:review-and-fix run writes its manifest under the branch slug, so a
# pr-<N>-only find silently misses those deferrals. The operative arm is the one that
# actually adds the branch-slug dir to the search set; pin it removal-proof so deleting
# the branch-slug arm goes RED. Also pin the BRANCH_SLUG derivation (its producer).
assert_pin_unique "#254: Phase 4.0.5 derives the sanitized branch slug from CUR_BRANCH" \
  'BRANCH_SLUG=$(printf '"'"'%s'"'"' "$CUR_BRANCH" | tr' "$P405_REF"  # structural-pin-ok: routing-dispatch-contract -- the slug this derives keys the second candidate search directory the discovery helper is handed; losing the derivation silently narrows the search to pr-<N>
assert_pin_unique "#254: Phase 4.0.5 adds the branch-slug dir to the manifest search set (operative)" \
  'SEARCH_DIRS="$SLUG_DIR $BRANCH_DIR"' "$P405_REF"  # structural-pin-ok: routing-dispatch-contract -- the operand handed to discover-deferral-manifests.py's argv; dropping the branch-slug arm makes a branch-mode run's manifest unreachable
# The aggregate must still be written at pr-<N>/deferrals.json (the path /pr-description reads).
assert_pin_unique "#254: Phase 4.0.5 keeps the aggregate at the pr-<N> slug path" \
  'AGG="${SLUG_DIR}/deferrals.json"' "$P405_REF"  # structural-pin-ok: cross-file-phase-contract -- the aggregate path /pr-description reads in Phase 4.2 and /prflow:review honors; a moved path leaves both consumers reading nothing
# ── issue #555: Phase 4.0.5 manifest discovery runs through the fail-closed helper, not a
# multi-root `find` whose exit status the `| sort` capture masked. Under the old shape a
# search that FAILED and a search that legitimately matched nothing both yielded an empty
# MANIFESTS, so the unconditional sentinel printed the clean `manifest=[]` and acknowledged
# deferrals were stranded with no signal (observed live on issue #533). The helper's exit
# code carries discovery status, the fence discriminates it into DISCOVERY_STATE, and the
# reader routing gains fail-closed arms. Pin the discovery statement, the sentinel field,
# the extended filing guard, and the single degraded arm.
assert_pin_unique "#555: Phase 4.0.5 discovers manifests through the fail-closed helper" \
  'if MANIFESTS=$("${CLAUDE_SKILL_DIR:-<absolute skill base directory this runner reports in context>}"/../../scripts/discover-deferral-manifests.py $SEARCH_DIRS); then' "$P405_REF"  # structural-pin-ok: helper-contract -- the discovery invocation guarded on its OWN inline exit status is a typed executable boundary between the fence and discover-deferral-manifests.py; the #1721 move off the harness-refused 2> capture changed the literal's text but not the contract it protects, exactly as the #915 move off cloud-denied /tmp did.
assert_pin_unique "#555: Phase 4.0.5 initializes DISCOVERY_STATE empty before the discovery statement (the #480 sentinel-operand rule)" \
  'DISCOVERY_STATE=""' "$P405_REF"  # structural-pin-ok: lifecycle-state-transition -- the pre-statement initialization that makes a refused discovery observable as discovery=[] rather than aborting the sentinel
assert_pin_unique "#555: Phase 4.0.5 collapses every non-zero discovery status into one after-fence-classified state" \
  'DISCOVERY_STATE=degraded' "$P405_REF"  # structural-pin-ok: lifecycle-state-transition -- the single non-zero arm's state assignment; splitting it inside the fence on stdout emptiness routes a partial run whose clean roots matched nothing to a refusal, stranding a prior run's unfiled aggregate
assert_pin_unique "#555: the sentinel carries the discovery= field, guarded with :- like filing=" \
  'discovery=[${DISCOVERY_STATE:-}]' "$P405_REF"  # structural-pin-ok: machine-sentinel-provenance -- the emitted sentinel field the reader's fail-closed routing literal-matches; without it a failed discovery is indistinguishable from a clean no-op
assert_pin_unique "#555: the filing guard requires a discovery that ran (a persisted prior aggregate must not drive filing on a refused discovery)" \
  '{ [ "$DISCOVERY_STATE" = ok ] || [ "$DISCOVERY_STATE" = degraded ]; } && [ -n "$AGG" ] && [ -s "$AGG" ]' "$P405_REF"  # structural-pin-ok: routing-dispatch-contract -- the guard that stops a persisted prior aggregate from driving filing on a refused discovery, while still admitting the degraded arm so a partial run can retry a prior run's unfiled aggregate
# (#1721) Do NOT re-pin the retired roots-echo surfacing over its replacement prose — see the
# prose-literal note beside the SP503 fence contracts.
# ── issue #555 (review finding): a bundled helper granted as a vendored-literal LEADING
# TOKEN is exec'd by path — no `python3`/`bash` wrapper is available, because an interpreter
# head is ungranted on the cloud tiers. Without the exec bit such a call dies rc 126 on every
# run, and that rc lands in the arm that looks like legitimate degradation
# (discovery=[degraded], which the filing guard admits), so the loss is silent in exactly the
# way this issue exists to stop. discover-deferral-manifests.py shipped 100644 and was caught
# in review; assert the class, not the instance — every scripts/ helper the implement profile
# grants by vendored literal must be executable in the index.
# The guard reads a human-editable JSON file, so it must not repeat the very shape it
# exists to catch: EVERY producer failure (malformed JSON, a renamed profiles/implement key,
# a scalar/empty profile, a missing python3) yields empty stdout, and an empty derived list
# would make the loop body never run and the assertion pass VACUOUSLY. So the producer's own
# exit status is checked, the derived list carries a non-empty floor, and a token that parses
# to a path not present in the index is RED (an unparseable or dangling grant), never a silent
# `continue` — the fail-open arms the blinded fix-delta gate flagged. The assertion also
# checks the shebang, because mode 100755 alone does not make a leading-token exec work.
# The guard body is a FUNCTION taking the manifest path, so the same code that runs over
# the real manifest can be driven over fixtures. Asserted-by-construction fail-closed arms
# are the class this repo keeps finding fails open (CLAUDE.md's "trace every operand back to
# its producer"): each arm below is exercised by a planted-defect fixture at the end of this
# block, so a rewrite that turns one of them into a silent `continue` goes RED at the desk.
_execbit_state() {
  _EXECBIT_MANIFEST="$1"
_EXECBIT_TOKENS="$(probe_tmp '#555 exec-bit guard token list')" || _EXECBIT_TOKENS=""
_EXECBIT_STATE=""
if [ -z "$_EXECBIT_TOKENS" ]; then
  _EXECBIT_STATE="could-not-allocate-scratch"
elif ! python3 -c "
import json, sys
# A profile entry may be an inline token OR an '@group' reference the generator
# expands against manifest['groups'] (lib/generate-capability-profiles.py's
# resolve_profile). Iterating the RAW spec would silently drop every helper that a
# later refactor moves into a shared group — the derived list would shrink, the
# non-empty floor would still pass, and the guard would go green while asserting
# nothing about the moved helpers. Expand the same way the generator does; an
# unknown group raises KeyError and rides the non-zero -> manifest-read-failed arm.
# Every failure is reported as ONE compact cause line on stderr rather than a
# traceback: the shell reads the FIRST stderr line as the breadcrumb, and a
# traceback's first line is the constant 'Traceback (most recent call last):',
# which would make every distinct producer failure carry the identical opaque
# breadcrumb the arm below promises not to emit.
try:
    m = json.load(open('$_EXECBIT_MANIFEST'))
    for entry in m['profiles']['implement']:
        tokens = m['groups'][entry[1:]] if entry.startswith('@') else [entry]
        for t in tokens:
            if '/scripts/' in t and t.startswith('Bash(.prflow/vendor/prflow/'):
                print(t)
except Exception as exc:
    sys.stderr.write('%s: %s\n' % (type(exc).__name__, exc))
    sys.exit(1)
" > "$_EXECBIT_TOKENS" 2>"$_EXECBIT_TOKENS.err"; then
  # Keep the cause: malformed JSON, a renamed profiles/implement key, an unknown
  # group ref, and an absent python3 all fail closed here, but they are different
  # repairs — an opaque breadcrumb makes the maintainer re-derive which one it was.
  # (An absent python3 emits no stderr of ours at all; the arm still fires, with an
  # empty cause, because the exit status is what selects it.)
  _EXECBIT_STATE="manifest-read-failed:$(head -n 1 "$_EXECBIT_TOKENS.err" 2>/dev/null)"
elif [ ! -s "$_EXECBIT_TOKENS" ]; then
  _EXECBIT_STATE="derived-zero-tokens"
else
  while IFS= read -r _tok; do
    [ -n "$_tok" ] || continue
    _rel="scripts/${_tok##*/scripts/}"
    _rel="${_rel%:\*)}"
    _rel="${_rel%)}"
    case "$(git -C "$LIB/.." ls-files -s -- "$_rel" | cut -c1-6)" in
      100755)
        # 100755 is necessary, not sufficient: a leading-token exec also needs a shebang.
        case "$(head -c 2 "$LIB/../$_rel" 2>/dev/null)" in
          '#!') : ;;
          *) _EXECBIT_STATE="$_EXECBIT_STATE no-shebang:$_rel" ;;
        esac ;;
      '') _EXECBIT_STATE="$_EXECBIT_STATE not-in-index:$_rel" ;;
      *)  _EXECBIT_STATE="$_EXECBIT_STATE not-executable:$_rel" ;;
    esac
  done < "$_EXECBIT_TOKENS"
fi
rm -f "$_EXECBIT_TOKENS" "$_EXECBIT_TOKENS.err" 2>/dev/null
  printf '%s' "$_EXECBIT_STATE"
}

_EXECBIT_STATE="$(_execbit_state "$LIB/capability-profiles.json")"
assert_eq "#555 every vendored-literal-granted scripts/ helper on the implement profile is executable with a shebang (a leading-token exec has no interpreter fallback), and the guard's own manifest read resolved" \
  "" "$_EXECBIT_STATE"

# Planted-defect fixtures for the guard's own fail-closed arms. Each asserts the SPECIFIC
# state string, not merely "non-empty" — a bare non-empty check cannot tell the arm under
# test from the one ten lines away, and every one of these arms produces an empty token
# list, which is exactly the vacuity that would make the live assertion above pass while
# asserting nothing. The clean-manifest positive control is the live call above: the same
# function over the real manifest returns "", so a fixture's non-empty state can only come
# from the planted defect and not from the function being broken outright.
_EXECBIT_FIX="$(probe_tmp '#555 exec-bit guard fixture manifest')" || _EXECBIT_FIX=""
if [ -n "$_EXECBIT_FIX" ]; then
  # 1. Malformed JSON — json.load raises, python3 exits non-zero.
  printf '%s' '{"profiles": {"implement": [' > "$_EXECBIT_FIX"
  case "$(_execbit_state "$_EXECBIT_FIX")" in
    manifest-read-failed:*) _EXECBIT_ARM=malformed-json-detected ;;
    *) _EXECBIT_ARM="malformed-json-MISSED:$(_execbit_state "$_EXECBIT_FIX")" ;;
  esac
  assert_eq "#555 exec-bit guard fail-closed arm: malformed manifest JSON routes to manifest-read-failed, never a vacuous pass" \
    "malformed-json-detected" "$_EXECBIT_ARM"

  # 2. Renamed profiles/implement key — a KeyError, the shape a manifest refactor produces.
  printf '%s' '{"groups": {}, "profiles": {"implement_tier": ["Bash(.prflow/vendor/prflow/scripts/x.py:*)"]}}' > "$_EXECBIT_FIX"
  case "$(_execbit_state "$_EXECBIT_FIX")" in
    manifest-read-failed:*KeyError*) _EXECBIT_ARM=renamed-key-detected ;;
    *) _EXECBIT_ARM="renamed-key-MISSED:$(_execbit_state "$_EXECBIT_FIX")" ;;
  esac
  assert_eq "#555 exec-bit guard fail-closed arm: a renamed profiles/implement key routes to manifest-read-failed carrying the KeyError cause" \
    "renamed-key-detected" "$_EXECBIT_ARM"

  # 3. An unknown '@group' reference — the arm the group expansion added; it must raise,
  #    not silently drop every helper the group holds.
  printf '%s' '{"groups": {}, "profiles": {"implement": ["@no-such-group"]}}' > "$_EXECBIT_FIX"
  case "$(_execbit_state "$_EXECBIT_FIX")" in
    manifest-read-failed:*KeyError*) _EXECBIT_ARM=unknown-group-detected ;;
    *) _EXECBIT_ARM="unknown-group-MISSED:$(_execbit_state "$_EXECBIT_FIX")" ;;
  esac
  assert_eq "#555 exec-bit guard fail-closed arm: an unknown @group reference routes to manifest-read-failed, never a silently shrunken token list" \
    "unknown-group-detected" "$_EXECBIT_ARM"

  # 4. An empty implement profile — parses fine, derives zero tokens. This is THE vacuity
  #    arm: without the non-empty floor the loop body never runs and the guard passes.
  printf '%s' '{"groups": {}, "profiles": {"implement": []}}' > "$_EXECBIT_FIX"
  assert_eq "#555 exec-bit guard fail-closed arm: an empty implement profile derives zero tokens and is RED, not a vacuous pass" \
    "derived-zero-tokens" "$(_execbit_state "$_EXECBIT_FIX")"

  # 5. A scalar profile — parses fine; iterating a string would yield characters, none of
  #    which match, so this also lands on the floor rather than a silent empty pass.
  printf '%s' '{"groups": {}, "profiles": {"implement": "Bash(.prflow/vendor/prflow/scripts/x.py:*)"}}' > "$_EXECBIT_FIX"
  assert_eq "#555 exec-bit guard fail-closed arm: a scalar implement profile derives zero tokens and is RED" \
    "derived-zero-tokens" "$(_execbit_state "$_EXECBIT_FIX")"

  # 6. A DANGLING grant — a well-formed vendored-literal token naming a helper that is not
  #    in the index. `git ls-files` prints nothing, and the guard must report it rather than
  #    `continue` past it (the fail-open arm the fix-delta gate flagged).
  printf '%s' '{"groups": {}, "profiles": {"implement": ["Bash(.prflow/vendor/prflow/scripts/no-such-helper.py:*)"]}}' > "$_EXECBIT_FIX"
  assert_eq "#555 exec-bit guard fail-closed arm: a dangling vendored-literal grant is reported as not-in-index, never skipped" \
    " not-in-index:scripts/no-such-helper.py" "$(_execbit_state "$_EXECBIT_FIX")"

  # 7. A granted helper that IS in the index but is not executable — the original defect
  #    class (discover-deferral-manifests.py shipped 100644). Any tracked non-exec scripts/
  #    file serves; assert the state names it so a reworded arm cannot mask the mode.
  printf '%s' '{"groups": {}, "profiles": {"implement": ["Bash(.prflow/vendor/prflow/scripts/devflow-cloud-writer-contract.json:*)"]}}' > "$_EXECBIT_FIX"
  assert_eq "#555 exec-bit guard fail-closed arm: a granted-but-non-executable helper is reported as not-executable" \
    " not-executable:scripts/devflow-cloud-writer-contract.json" "$(_execbit_state "$_EXECBIT_FIX")"

  rm -f "$_EXECBIT_FIX" 2>/dev/null
else
  skip "#555 exec-bit guard fail-closed arms" host-capability "could not allocate a fixture manifest under this host's scratch policy"
fi

# ── issue #555 (review finding), amended by issue #1415: the §4.0.5 routing-bullet population
# is pinned mechanically here so a later rework that adds or drops a bullet turns the suite RED
# at the desk. Issue #1415 removed the self-referential count from the shipped header itself
# (a stale self-referential count is a non-demotable REJECT, PR #553), so this guard no longer
# reads any header numeral — it counts the shipped bullets directly, keeping the population
# guard while the shipped prose carries no count. The region is the routing list between the
# exits header and the label-apply prose.
_P4_ROUTING_BULLETS="$(awk '/exits before any label is applied/,/^If the printed/' "$P405_REF" | grep -c '^- \*\*')"
assert_eq "#555 the §4.0.5 reader-routing list still carries exactly 7 routing bullets (5 exits + 2 qualifiers) — pinned mechanically, not against any shipped header numeral (#1415)" \
  "7" "$_P4_ROUTING_BULLETS"

# Issue #1188: the docs-rationale/overview MIRROR presence pins that used to sit here
# (sweep 2.3.6 / 2.3.0a / 2.3.0b keeps-the-rationale-row, and the 2.3.0b overview
# sweep-list entry) were retired prose-presence pins exempted by the frozen
# .prflow/logs retirement manifests, keyed by resolved_target. Moving the mirror docs
# from docs/ to docs/internal/ orphans that resolved_target key, and the #810 gate
# enforces frozen manifests, so the retirement can no longer be tracked. Their
# retirement is completed by removal here (#876). The docs content itself is unchanged;
# only these regression guards are dropped. See the workpad issue-accuracy note.

# Substrate-agnostic re-anchor (issue #171): the "Sweep selection (run first)" preamble
# must state that its trigger shapes apply to prose/SKILL/doc/config as much as to code,
# so an add-only prose/doc/config diff that replicates a peer rule, an enumerated-set
# member, or a mirrored contract literal across sites still trips the contract-completeness
# sweeps (2.3.0 / 2.3.0a / 2.3.0b) rather than falling through to "just the five always-on sweeps".
# The cross-site enumeration below extracts both lists and requires the SKILL and docs
# to name the same contract-sweep set without holding either sentence to exact prose.
_skill_sweeps=$(grep -oE 'still trips the contract-completeness sweeps \([^)]+\)' "$IMPL_SKILL" \
  | grep -oE '[0-9]+\.[0-9]+\.[0-9]+[a-z]*' | sort | tr '\n' ' ' | sed 's/ $//')
_docs_sweeps=$(grep -oE 'still runs the contract-completeness sweeps \([^)]+\)' "$IMPL_DOC" \
  | grep -oE '[0-9]+\.[0-9]+\.[0-9]+[a-z]*' | sort | tr '\n' ' ' | sed 's/ $//')
assert_eq "sweep selection: SKILL and docs enumerate the same contract-sweep set (cross-site)" \
  "$_skill_sweeps" "$_docs_sweeps"

# ── issue #661: exact-one/static checks preserve the relocation-discovery contracts and
# coupled docs mirror.
# AC1 — the heading names prose/heading/section/path relocation as an armed case.
# AC1 — the Sweep-selection index cue also names a relocated prose literal (the code-symbol
# under-cueing hole this change closes); presence pin (distinct wording from the heading).
assert_pin_unique "#661: Sweep-selection index cues a relocated prose literal/heading/section/path" \
  'or a relocated prose literal, heading, section, or file path' "$IMPL_PHASES_DIR/phase-2-sweeps-contract.md"  # structural-pin-ok: cross-file-phase-contract -- #661 sweep selection cues a relocated prose literal, heading, section or path
# AC2 — the enumeration mandates a whitespace-normalized search.
# AC3 — content recovery from the diff's deletion hunks and both old-location citation forms.
# AC11 — the docs/internal/implement-skill.md relocation-rationale MIRROR presence pin
# was removed here (issue #1188): a retired prose-presence pin whose frozen retirement
# key resolved_target moved with the doc; see the cluster note above.

# ── issue #474: exact-one/static checks preserve the collection-cardinality and
# derived-comparand contracts plus their coupled documentation mirrors.
# Issue #1188: the #474 docs-rationale AND overview mirror presence pins (2.3.7 rationale
# table row + sweep-index entry) were retired prose-presence pins orphaned by the
# docs/internal move; removed per the cluster note above.
# Each absence guard is paired with an INJECTION non-vacuity proof (the #465 delta form,
# 7f7161a): an absolute `== 0` alone cannot tell "phrase removed" from "grep blind", so it
# would degrade to a no-op if the phrase were reworded. Inject the phrase into a copy and
# confirm the SAME grep detects it (count rises by exactly 1) — proving the `0` is a
# reconciled body, not a blind detector. Injection (not a base-ref read) keeps the proof
# robust to merge state: origin/main carries the reconciled body once this PR merges.
for _474_ABSENT in 'numbered last only to avoid renumbering' '2.3.6 sits last'; do
  assert_eq "#474: docs no longer claim '$_474_ABSENT' (§2.3.7-falsified 'last' claim reconciled)" "0" \
    "$(grep -Fc "$_474_ABSENT" "$IMPL_DOC")"
  _474_INJ="$(probe_tmp "#474 absence-guard injection: '$_474_ABSENT'")" || continue
  { cat "$IMPL_DOC"; printf '%s (injected)\n' "$_474_ABSENT"; } > "$_474_INJ"
  assert_eq "#474: absence guard non-vacuous — injecting '$_474_ABSENT' raises the count by 1" \
    "$(( $(grep -Fc "$_474_ABSENT" "$IMPL_DOC") + 1 ))" "$(grep -Fc "$_474_ABSENT" "$_474_INJ")"
  rm -f "$_474_INJ"
done

# Drift guard: the base_branch read in the implement skill (phases/phase-1-setup.md) Phase 1.4 is
# a load-bearing inline-bash block in the skill (Phase 3.1's §3.1 re-derivation below is another) — like the max_iterations clamp above, the
# tokens it relies on can be silently broken by a SKILL edit (drop the `|| BASE=""`
# and `git fetch origin ""` runs; drop the fetch guard and a bad base fails with a
# bare git error instead of an attributable DevFlow breadcrumb). Pin the tokens so
# a refactor of the block fails here rather than shipping a silent regression.
# NOTE: the two read+guard literals below (`config-get.sh .base_branch main` and
# `[ -n "$BASE" ]`) now ALSO appear in phases/phase-3-review.md §3.1, which re-derives
# BASE before `gh pr create` (issue #224). So these two pins are scoped to the
# phase-1-setup.md file (where Phase 1.4 lives) rather than the whole bundle, keeping
# them unique-per-file; the phase-3 re-derivation has its own pins further below.
assert_pin_unique "base_branch read: branch-setup reads via config-get with the main default" 'config-get.sh .base_branch main' "$P1582_BS"
assert_pin_unique "base_branch read: branch-setup guards the empty read" '[ -n "$BASE" ]' "$P1582_BS"
# Scoped to branch-setup.md (Phase 1.4's fetches, moved there by #1582): issue #284 added a
# SECOND `git fetch origin "$BASE"` in phase-4-documentation.md's Stage-2 diff-gate retry, so a
# bundle-wide unique pin double-matches — the Phase 1.4 fetches live in branch-setup.md now.
# Issue #429 added the adopted-branch (USE_CURRENT) arm's freshness fetch, so branch-setup.md
# carries TWO `git fetch origin "$BASE"` sites (the create arm AND the adopted arm), and the
# pin asserts BOTH are present rather than a single unique one — both arms fetch the base, so
# no adopted run reads a stale fork point (the #325 guard). Issue #779 gave both sites the
# FORCED, explicitly-destinationed refspec the checkpoint helper uses, so the counted literal
# is that form — the assertion's guarantee (both arms fetch the CONFIGURED base rather than a
# hard-coded `main`) is unchanged, re-expressed against the new literal.
assert_eq "base_branch read: branch-setup fetches origin/\$BASE on both the create and adopted arms (not hard-coded main)" "2" \
  "$(grep -cF 'git fetch origin "+refs/heads/$BASE:refs/remotes/origin/$BASE"' "$P1582_BS" || true)"
assert_pin_unique "#168 create-path: branch-setup guards against an empty BRANCH name" \
  '[ -n "$BRANCH" ]' "$P1582_BS"

# ── Issue #779: the Phase 1 base-update checkpoint is ARM-INDEPENDENT ──
# The checkpoint used to be gated on `USE_CURRENT`, which the landed-resume arm never binds
# (that arm returns from the resume pre-check having skipped `#### Signals` entirely), so the
# run population most likely to be stale was the one that never reconciled with the base. The
# invocation now runs at the END of §1.4 on every arm. The static and positional checks below
# preserve arm independence and keep the out-of-scope machinery unchanged.
# Reuses the file-scope $P1_FILE / $P4_FILE (declared above with their parent $IMPL_PHASES_DIR) rather
# than introducing a third and fourth alias for the same two paths — the single-alias-per-path rule
# $P4_FILE's own declaration comment states.

# The §1.4.1 de-gating sentence is the diff's core relocation claim; pin it explicitly rather
# than relying on the positional assert below catching a re-gated fence as a side effect.

# (b) Position: the invocation is the LAST thing §1.4 does — after the branch-setup dispatch
# (which #1582 moved the create fence and the `Branch` line fill into) and before §1.5. A
# positional assert_eq (not a pin helper), so a relocation flips it without a text mutation.
# One awk pass over the file resolves all three first-hit line numbers. Each anchor records
# only its FIRST match, mirroring the `head -1` idiom.
eval "$(awk '
  d==0 && index($0, "#### Dispatch the branch-setup agent") { print "U779_DISP_LN=" NR; d=1 }
  i==0 && index($0, "/../../scripts/update-branch-checkpoint.sh") { print "U779_INV_LN=" NR; i=1 }
  p==0 && index($0, "### 1.5 Push Branch") { print "U779_15_LN=" NR; p=1 }
' "$P1_FILE")"
assert_eq "#779: the checkpoint invocation is the last §1.4 step (after the branch-setup dispatch, before §1.5)" "yes" \
  "$([ -n "$U779_DISP_LN" ] && [ -n "$U779_INV_LN" ] && [ -n "$U779_15_LN" ] \
     && [ "$U779_INV_LN" -gt "$U779_DISP_LN" ] \
     && [ "$U779_INV_LN" -lt "$U779_15_LN" ] && echo yes || echo no)"

# (c) The count above preserves the forced refspec at both Phase 1.4 fetch sites.

# The skill prose asserts its refspec is "the same forced refspec update-branch-checkpoint.sh
# uses"; without this the helper could change its refspec and the claim would silently become a
# documented falsehood while the suite stayed green (the repo's coupled-invariant class).
assert_pin_unique "#779: the checkpoint helper fetches the base with the same forced refspec the §1.4 sites use" \
  'git fetch origin "+refs/heads/$BASE:refs/remotes/origin/$BASE"' "$LIB/../scripts/update-branch-checkpoint.sh"  # structural-pin-ok: helper-contract -- the Phase 1.4 checkpoint helper must fetch the configured base through the same forced refspec as its consuming phase

# (g) #780 revisited the landed-resume routing (Verdict B classifies that arm) and decided it
# STAYS. The routing-dispatch pin that used to assert the operative routing sentence, and with it
# the landed-resume BRIDGING clause, is gone — so neither the routing decision nor the bridging
# clause carries any coverage here, and a deletion of either ships desk-green.

# (h) Checkpoint 4's CONFLICT re-invocation BOUND — without it the gate is a resolve-and-re-invoke
# loop with no exit on a persistently conflicting base.

# (i) The tool-boundary test must PRECEDE the routing list; if it moves after, every reported
# denial falls into the "empty or unrecognized field" refusal arm and Blocks. Positional, so a
# reorder flips it without needing a text mutation.
U779_TB_LN=$(grep -nF 'and be honest about which denials are observable' "$P4_FILE" | head -1 | cut -d: -f1)
U779_RT_LN=$(grep -nF 'Publish gate (checkpoint-4-specific' "$P4_FILE" | head -1 | cut -d: -f1)
assert_eq "#779: the checkpoint-4 tool-boundary test precedes the token routing list" "yes" \
  "$([ -n "$U779_TB_LN" ] && [ -n "$U779_RT_LN" ] && [ "$U779_TB_LN" -lt "$U779_RT_LN" ] && echo yes || echo no)"

# (j) The checkpoint-4 override of §1.4.1's inherited record-and-continue arm. Both halves of a
# two-sided contract: the refusal sentence is pinned above, this is the disambiguation that keeps
# §1.4.1's inherited arm from winning for a reader routing by the contract.

# (k) The helper header's caller-matching contract, which phase-4 cites as authority ("the matching
# rule scripts/update-branch-checkpoint.sh's own header states"). Delete the header block and that
# citation becomes a documented falsehood with nothing else turning RED.

# (l) The silent-cloud-matcher-denial EXCLUSION: it is indistinguishable from an unrecognized
# field, so it must take the refusal arm rather than the tier-refused publish arm. Without this
# the publish arm reads as reachable on the cloud tier, where it is not.

# (m) The bounded re-invocation is scoped to the NON-MUTATING causes only. PUSH_REJECTED and
# MERGE_IN_PROGRESS re-run fetch/merge/push and a second `git reset --hard`, so re-invoking them
# compounds a failed restore instead of clearing a transient blip.

# (e) Negative controls — machinery this issue declares OUT of scope. `#168` already pins the
# create-fence guard and the Signal-2 assignment and `#362` covers the resume pre-check.
# The former Verdict-B scope-boundary pin here was retired by issue #780, which widened
# §1.4.0.5 to the landed-resume arm — the boundary it asserted no longer exists.

# (f) Phase 4.3 publish gate. The leading-word read is the operative shape: a whole-line test
# against `UPDATED` is false for every real merge (`emit "UPDATED $BEHIND"` prints `UPDATED 3`)
# and would block publishing on exactly the runs that reconciled successfully.
# CONFLICT is exempt from the refusal: it resolves per the inherited contract and the helper is
# re-invoked, and THAT line's first field is what the gate reads.
# The success-path channel (issue #1050): a keyed `--checkpoint base-update-checkpoint-4` row
# naming the observed token on UPDATED/UP_TO_DATE/DISABLED alike, so a green run carries evidence
# of the comparison's result through a MACHINE-READABLE marker (`lib/fetch-pr-context.sh` derives
# `base_update_checkpoint4_present` from it) rather than a free-text note. §1.4.1's no-traffic rule
# for checkpoints 1-3 is unchanged, which is why this had to be a checkpoint-4-specific addition.
# The key stays OUTSIDE the `gha:` prefix so the review/review-and-fix tier discriminator (which
# reads `gha:` checkpoints as a cloud marker) is unaffected. A non-canonical body makes `--checkpoint`
# a structural no-PATCH; the prose once kept a degrade-to-`--note` fallback for it, removed outright
# by issue #1348 (the terminal Complete write is gated on the keyed row), so it now fails closed.
# The row carries no UPDATED-specific ordering condition: checkpoint 4 no longer runs a suite of
# its own, so the row records the CHECKPOINT's result on all three clean tokens alike. The
# completion-evidence flight (issue #1087) still runs after it and can route the run to Blocked
# before anything is published — the row is not a claim about the run's outcome.
# The observable discriminator for "no token reported" — "produced no output at all" is unusable
# because the helper rebinds fd 1 to stderr and a successful invocation is never silent.
# A tier that REFUSES the invocation is a distinct case from a non-clean token: it publishes,
# per §1.4.1's degraded posture. Routing it to Blocked would end every such run at its last step
# with no escape, since the off-switch yields DISABLED only when the helper actually runs.
unset U779_INV_LN U779_CO_LN U779_BR_LN U779_15_LN U779_TB_LN U779_RT_LN

# ── #1050: checkpoint-4 evidence carrier = keyed-checkpoint marker, key OUTSIDE the `gha:` prefix.
# Machine-consumed CROSS-FILE contract: phase-4 writes `--checkpoint <key>`, workpad.py validates
# the key + writes `<!-- prflow:checkpoint <key> -->`, and BOTH fetch-pr-context.sh (the
# `base_update_checkpoint4_present` field) and the review/review-and-fix tier discriminator READ
# that marker. The discriminator reads any `gha:`-prefixed checkpoint as a cloud marker and
# checkpoint 4 runs on both tiers, so a `gha:` key would silently misclassify every local run as
# cloud (issue #1050 AC: tier-discriminator invariant preserved). The key must therefore never
# carry that prefix; this is the executable guard on AC10.
CP4_KEY=$(grep -oE -- '--checkpoint base-update-checkpoint-4' "$P4_FILE" | head -1 | sed -E 's/^--checkpoint //')
assert_eq "#1050: phase-4 records checkpoint 4 through the keyed-checkpoint carrier" \
  "base-update-checkpoint-4" "$CP4_KEY"  # structural-pin-ok: cross-file-phase-contract -- the checkpoint-4 carrier key is read by fetch-pr-context.sh and the tier discriminator and validated by workpad.py; a rename must reconcile all four sites
assert_eq "#1050: the checkpoint-4 key is NOT gha:-prefixed (tier-discriminator invariant)" "yes" \
  "$(case "$CP4_KEY" in gha:*) echo no ;; *) echo yes ;; esac)"
unset CP4_KEY

# ── #1347: the tier-refused arm's carrier + the Phase 1.3 inherited strip.
# Same machine-consumed cross-file contract as #1050 above, one tier down: phase-4's
# tier-refused arm writes `--checkpoint base-update-checkpoint-4-tier-refused`, workpad.py
# declares that key in `_REQUIRED_ARTIFACT_CHECKPOINT_KEYS` (which is both what
# `--strip-inherited-checkpoints` filters on and what the strip/insert exclusion reads), and
# the same tier-discriminator invariant binds it — checkpoint 4 runs on both tiers, so a
# `gha:` prefix here would misclassify every local run as cloud. The key must ALSO be distinct
# from the clean-token key, or "reconciled" and "the tier refused" collapse into one row that
# no consumer can tell apart — which is the whole point of the swap.
CP4R_KEY=$(grep -oE -- '--checkpoint base-update-checkpoint-4-tier-refused' "$P4_FILE" | head -1 | sed -E 's/^--checkpoint //')
assert_eq "#1347: phase-4's tier-refused arm records through its own keyed carrier" \
  "base-update-checkpoint-4-tier-refused" "$CP4R_KEY"  # structural-pin-ok: cross-file-phase-contract -- the tier-refused carrier key is declared in workpad.py's _REQUIRED_ARTIFACT_CHECKPOINT_KEYS and drives the strip; a rename must reconcile both sites
assert_eq "#1347: the tier-refused key is NOT gha:-prefixed (tier-discriminator invariant)" "yes" \
  "$(case "$CP4R_KEY" in gha:*) echo no ;; *) echo yes ;; esac)"
# NO "distinct from the clean-token key" assertion here: the grep pattern above already
# spells the tier-refused key in full, so such a comparison could never be false — it would
# add a green row carrying no information. The distinctness that CAN break is between the two
# keys as workpad.py declares them, and that is asserted there, against the module's own
# constant. (That both keys are DECLARED in `_REQUIRED_ARTIFACT_CHECKPOINT_KEYS` — so the strip
# reaches both and the strip/insert exclusion covers both — is likewise asserted behaviorally in
# lib/test/test_python_scripts.py rather than by a second literal here.)
# The Phase 1.3 resume arm must carry the strip. This is a PRESENCE pin over the whole file and
# claims only that: that the strip is not ALSO described as one of the cloud-only flags the
# local arm drops is agent-executed prose no tool reads, so it carries no pin (the #843 policy)
# and the review pass is its control. The behavior that matters — that the strip lands with
# neither --checkpoint nor --expect-* in the call — is asserted in test_python_scripts.py.
assert_eq "#1347: the Phase 1.3 resume arm passes --strip-inherited-checkpoints" "yes" \
  "$(grep -q -- '--strip-inherited-checkpoints' "$IMPL_PHASES_DIR/phase-1-setup.md" && echo yes || echo no)"  # structural-pin-ok: cross-file-phase-contract -- the resume arm is the sole producer of the strip; without it the inherited row survives and base_update_checkpoint4_present describes the wrong attempt
unset CP4R_KEY

# ── Issue #755: Phase 2 §2.0 resume-idempotency gate ──
# A stalled cloud run that stall_backstop auto-resumes must NOT re-dispatch the Phase 2
# code-explorer/code-architect subagents from scratch. The gate (phase-2-implement.md §2.0)
# fires on (a) a `resume-kind: in-flight` marker + (b) a committed non-placeholder Plan, and
# then skips the two dispatches. The static pins below preserve the marker and
# Plan-seed couplings used by that gate.
# Seed-literal coupling (repo-wide): the gate's "non-placeholder Plan" discriminator (conjunct
# b) is the workpad.py new-body `## Plan` seed. If the seed literal changes in the producer but
# not the gate, the gate mis-fires on a fresh run. Bind both copies so a one-sided seed edit
# goes RED here — in addition to the existing `new-body` placeholder assertion in
# lib/test/test_python_scripts.py, which is a WEAKER sibling: it matches only the inner
# `_(planning in progress)_` substring of the generated body, not the full pinned row.
WP755_PY="$LIB/../scripts/workpad.py"
# Each of the four pins below is a half of a CROSS-FILE coupling, so its guarded regression is a
# two-file divergence that no single-file check reproduces — hence the structural declaration.
# assert_pin_unique (not a raw grep) is the repo idiom: it also
# fails a DUPLICATED literal, which a raw scan would let pass with the guarded sentence deleted
# (the PR #154 vacuous-guard hole).
assert_pin_unique "#755: workpad.py new-body Plan seed literal present (producer of the §2.0 gate discriminator)" \
  '- [ ] _(planning in progress)_' "$WP755_PY"  # structural-pin-ok: cross-file-phase-contract -- producer half of the Plan seed coupling: the literal workpad.py's new-body writes
assert_pin_unique "#755: Phase 2 §2.0 gate carries the same Plan seed literal as workpad.py new-body (coupled discriminator)" \
  '- [ ] _(planning in progress)_' "$P2_FILE"  # structural-pin-ok: cross-file-phase-contract -- consumer half: Phase 2 section 2.0 reads the same Plan seed literal as its discriminator
# resume-kind marker writer/reader coupling (conjunct a): Phase 1.3 writes it, the §2.0 gate
# reads it. Bind the pair so neither half can be dropped without the other going RED.
assert_pin_unique "#755: Phase 1.3 writes the durable resume-kind marker (writer of §2.0 conjunct a)" \
  'Emit the decided kind as a bare literal' "$P1_FILE"  # structural-pin-ok: cross-file-phase-contract -- writer half of the resume-kind cross-phase protocol
assert_pin_unique "#755: Phase 2 §2.0 gate reads the resume-kind: in-flight marker (reader of conjunct a)" \
  'resume-kind: in-flight' "$P2_FILE"  # structural-pin-ok: machine-sentinel-provenance -- reader of the resume-kind: in-flight marker the writer half emits
# The two §3.1 existing-PR pins this block used to carry are re-anchored to the extracted
# helper by the #782 block that follows — the extraction removed the inline text they
# asserted, and both guarded regressions are preserved there, one arm each.

# ── Issue #782: the §3.1 three-arm resolution is an EXTRACTED, DRIVEN helper ──
# CLAUDE.md's inline-shell-extraction convention: shell that SELECTS A BRANCH is extracted
# into a scripts/*.sh helper so the suite can drive each arm AND its arm-order, because a
# grep-pin on a message literal is not coverage of the selection that chooses it.
# scripts/describe-denial-count.sh is the reference extraction (its driver lives further
# below, at the #363 block); this block is its analogue for the §3.1 existing-PR resolver.
#
# The two #755 pins that used to assert the INLINE query form in phase-3-review.md are
# re-anchored here to helper behavior — the extraction removed the text they asserted, and a
# pin left asserting vanished text is the stale-citation defect the 2.3.0 relocation sweep
# exists to catch. Their guarded regressions are preserved verbatim, one arm each:
#   * open-scoped query    -> the `gh pr view` unscoped form silently adopts a CLOSED PR.
#   * empty-branch REFUSED -> an empty --head degrades to an UNFILTERED repo-wide query.
REP_SH="$LIB/../scripts/resolve-existing-pr.sh"
S782="$(mktemp -d)"
# gh stub. Every invocation appends its argv to $GHLOG, which is what lets the empty-branch
# row assert gh was never CALLED at all — the fail-closed property that arm exists for (a
# query reached with an empty --head is the repo-wide degradation, not a narrower query).
# REP_RC non-empty makes the stub exit with it (the `gh` non-zero row); otherwise it prints
# the JSON fixture named by REP_FIXTURE.
cat > "$S782/gh" <<'GH782'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$GHLOG"
[ -n "${REP_RC:-}" ] && exit "$REP_RC"
cat "$REP_FIXTURE"
GH782
chmod +x "$S782/gh"
printf '%s\n' '[]' > "$S782/empty.json"
printf '%s\n' '[{"number":11,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":782}]}]' > "$S782/one.json"
# Two open PRs on ONE head, deliberately listed NEWEST-FIRST so a bare `.[0]` would also
# pass: the row below asserts the newest is selected, and the reversed-order sibling row
# proves the selection is by createdAt rather than by array position.
printf '%s\n' '[{"number":22,"createdAt":"2026-02-02T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":782}]},{"number":21,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":782}]}]' > "$S782/two-newest-first.json"
printf '%s\n' '[{"number":21,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":782}]},{"number":22,"createdAt":"2026-02-02T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":782}]}]' > "$S782/two-oldest-first.json"
# An unrelated PR sharing the head branch: closes no issue AND targets another base — the
# wrong-PR adoption #782 makes visible instead of silent.
printf '%s\n' '[{"number":33,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"develop","closingIssuesReferences":[]}]' > "$S782/unrelated.json"
# Each failing check must be nameable ALONE, not only in the both-failed pair.
printf '%s\n' '[{"number":34,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"develop","closingIssuesReferences":[{"number":782}]}]' > "$S782/base-only.json"
printf '%s\n' '[{"number":35,"createdAt":"2026-01-01T00:00:00Z","baseRefName":"main","closingIssuesReferences":[{"number":999}]}]' > "$S782/closes-only.json"
# An absent baseRefName is a real gh shape (a PR whose base ref was deleted, a projection that
# omits it). It is the JSON boundary row the field-split must survive: an empty middle field
# would collapse under `read` and shift the yes/no token into PR_BASE, so the helper would name
# a check that in fact held. The `-` sentinel + fixed-vocabulary-field-first ordering fix that.
printf '%s\n' '[{"number":41,"createdAt":"2026-01-01T00:00:00Z","baseRefName":null,"closingIssuesReferences":[{"number":782}]}]' > "$S782/nullbase.json"
# Not a JSON array of PR objects — the external-format boundary row for the jq filter.
printf '%s\n' '{"number":9}' > "$S782/malformed.json"
printf '%s' '' > "$S782/empty-output.json"
# rep782 <fixture> <gh-rc-or-empty> <args…> → prints "<stdout-token>|<exit-code>".
# Both halves are asserted together on every row: the AC requires exactly one token per
# outcome WITH a matching exit code, so a token asserted without its code would leave the
# code free to drift (and vice versa).
# Each invocation is made EXACTLY ONCE and its result captured, because the arm-order rows
# below compare the same outcomes the matrix rows assert: re-invoking there would spawn a
# fresh bash+stub+jq chain per comparison for answers already in hand. The helper's stderr is likewise kept
# for the breadcrumb row, and it is read from the FILE rather than from a shell variable set
# inside rep782: every call site here is a `$(rep782 …)` command substitution, i.e. a
# SUBSHELL, so an assignment made inside the function is discarded on return — the file
# survives because the redirect writes it in the parent's filesystem, not its environment.
# (The two non-vacuity assertions below exist because the variable form silently produced two
# EMPTY strings that compared "same" — a guard that would have read as armed and could not
# fail.) $S782/err is overwritten by each call, so a row that needs it copies it immediately.
rep782() {
  local fx="$1" rc="$2"; shift 2
  local out st
  : > "$S782/ghlog"
  out="$(GHLOG="$S782/ghlog" REP_FIXTURE="$fx" REP_RC="$rc" DEVFLOW_GH="$S782/gh" \
      bash "$REP_SH" "$@" 2>"$S782/err")" && st=0 || st=$?
  printf '%s|%s\n' "$out" "$st"
}
assert_eq "#782 resolve-existing-pr.sh exists and is executable" "yes" \
  "$([ -x "$REP_SH" ] && echo yes || echo no)"
# ── The five input-matrix rows the issue enumerates, each asserting token AND exit code.
R782_REFUSED_GH="$(rep782 "$S782/empty.json" 4 --issue 782 --base main --branch feature-x)"
R782_ERR_GH="$(cat "$S782/err")"
assert_eq "#782 arm: gh exits non-zero -> REFUSED (never a create, which could duplicate)" "REFUSED|3" \
  "$R782_REFUSED_GH"
R782_CREATE="$(rep782 "$S782/empty.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 arm: an empty result array -> CREATE (a clean 'no open PR', not a failure)" "CREATE|2" \
  "$R782_CREATE"
R782_ADOPT="$(rep782 "$S782/one.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 arm: exactly one open PR -> ADOPT, validated" "ADOPT 11 OK|0" \
  "$R782_ADOPT"
# The DISCRIMINATING row: oldest-first, so a bare `.[0]` would return 21 and fail here.
assert_eq "#782 arm: two open PRs on one head -> the newest is selected by createdAt, not by array position" "ADOPT 22 OK|0" \
  "$(rep782 "$S782/two-oldest-first.json" "" --issue 782 --base main --branch feature-x)"
# Its CONTROL: newest-first, which a bare `.[0]` also passes — it proves the discriminating row
# above is not an artifact of one array ordering, and cannot itself detect the `.[0]` regression.
assert_eq "#782 arm: control — newest-first ordering still adopts the newest (passes under .[0] too)" "ADOPT 22 OK|0" \
  "$(rep782 "$S782/two-newest-first.json" "" --issue 782 --base main --branch feature-x)"
R782_REFUSED_BRANCH="$(rep782 "$S782/one.json" "" --issue 782 --base main --branch "")"
R782_ERR_BRANCH="$(cat "$S782/err")"
assert_eq "#782 arm: an empty branch name -> REFUSED" "REFUSED|3" \
  "$R782_REFUSED_BRANCH"
# The empty-branch arm's WHOLE POINT: the query is never reached. `gh pr list --head ""` is
# an UNFILTERED repo-wide open-PR query that exits 0, so a helper that merely returned an
# empty selection here would adopt an arbitrary unrelated PR on some other branch.
assert_eq "#782 empty branch: gh is never invoked (no unfiltered repo-wide query is issued)" "yes" \
  "$([ -s "$S782/ghlog" ] && echo no || echo yes)"
# ── AC1 validation: the adopt arm names EACH failed check, so a wrong-PR adoption is visible.
assert_eq "#782 validation: a PR that neither closes the issue nor targets the base names both checks" \
  "ADOPT 33 WARN:closes-issue,base-ref|0" \
  "$(rep782 "$S782/unrelated.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 validation: a base-only mismatch names base-ref alone" "ADOPT 34 WARN:base-ref|0" \
  "$(rep782 "$S782/base-only.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 validation: a closes-issue-only mismatch names closes-issue alone" "ADOPT 35 WARN:closes-issue|0" \
  "$(rep782 "$S782/closes-only.json" "" --issue 782 --base main --branch feature-x)"
# ── The remaining REFUSED causes. The helper's header argues at length that these are
# ── DIFFERENT diagnoses deserving separate breadcrumbs; an undriven arm can collapse onto a
# ── sibling's message unnoticed, which would defeat exactly that design.
#
# A value-taking flag given no value. These rows are the regression guard for a REAL defect the
# review caught: `shift 2` with one positional left FAILS and shifts nothing, so the arg loop
# re-matched the same flag forever — an unbounded hang emitting no token and no breadcrumb.
# They run under a TIMEOUT so a re-introduced hang fails THESE rows instead of wedging the whole
# suite (a timeout exit of 124 is not 3, so the assertion goes RED either way).
#
# `timeout(1)` is GNU coreutils and stock macOS/BSD ships neither it nor a `gtimeout` unless the
# user installed coreutils, so the binary is RESOLVED rather than assumed — CLAUDE.md's
# portability convention forbids depending on a tool outside the preflight-guaranteed set. With
# neither binary present the rows SELF-SKIP as `host-capability` (the #456 kind for "the host
# cannot express the condition") rather than failing with a 127 that would misattribute a
# missing binary to the argument loop. Resolution is via `command -v`, a bash builtin.
REP_TIMEOUT="$(command -v timeout || command -v gtimeout || true)"
if [ -z "$REP_TIMEOUT" ]; then
  skip "#782 arm: a value-taking flag with no value -> REFUSED, and does NOT hang" host-capability \
    "neither timeout nor gtimeout is on PATH (GNU coreutils); the hang guard needs a bounded run so a re-introduced infinite loop cannot wedge the suite"
  skip "#782 arm: a trailing --branch with no value -> REFUSED, and does NOT hang" host-capability \
    "neither timeout nor gtimeout is on PATH (GNU coreutils); the hang guard needs a bounded run so a re-introduced infinite loop cannot wedge the suite"
else
  assert_eq "#782 arm: a value-taking flag with no value -> REFUSED, and does NOT hang" "REFUSED|3" \
    "$(: > "$S782/ghlog"; _o="$(GHLOG="$S782/ghlog" REP_FIXTURE="$S782/one.json" REP_RC="" DEVFLOW_GH="$S782/gh" \
        "$REP_TIMEOUT" 10 bash "$REP_SH" --issue 2>"$S782/err")" && _s=0 || _s=$?; printf '%s|%s\n' "$_o" "$_s")"
  assert_eq "#782 arm: a trailing --branch with no value -> REFUSED, and does NOT hang" "REFUSED|3" \
    "$(: > "$S782/ghlog"; _o="$(GHLOG="$S782/ghlog" REP_FIXTURE="$S782/one.json" REP_RC="" DEVFLOW_GH="$S782/gh" \
        "$REP_TIMEOUT" 10 bash "$REP_SH" --issue 782 --branch 2>"$S782/err")" && _s=0 || _s=$?; printf '%s|%s\n' "$_o" "$_s")"
fi
assert_eq "#782 arm: an unrecognized argument -> REFUSED (never a guess)" "REFUSED|3" \
  "$(rep782 "$S782/one.json" "" --issue 782 --branch feature-x --bogus x)"
assert_eq "#782 arm: a non-numeric --issue -> REFUSED (the closes-issue check cannot be established)" "REFUSED|3" \
  "$(rep782 "$S782/one.json" "" --issue abc --base main --branch feature-x)"
assert_eq "#782 arm: gh exits 0 but prints nothing -> REFUSED (an empty listing is '[]', never empty output)" "REFUSED|3" \
  "$(rep782 "$S782/empty-output.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 arm: an unparseable listing -> REFUSED (never a clean 'none found')" "REFUSED|3" \
  "$(rep782 "$S782/malformed.json" "" --issue 782 --base main --branch feature-x)"
# ── The PRODUCTION invocation form: §3.1 passes only --issue, so the internal
# ── `git branch --show-current` read is the one path production always takes — and it was the
# ── only path with no driver. Every other row supplies --branch explicitly, which sets
# ── BRANCH_SET and skips the read entirely, so the #755 own-statement-branch-read regression
# ── would have had the mutation pin as its sole signal.
R782_GITREPO="$(mktemp -d)"
if git -C "$R782_GITREPO" init -q 2>/dev/null &&
   git -C "$R782_GITREPO" -c user.email=t@e -c user.name=t commit -q --allow-empty -m seed 2>/dev/null &&
   git -C "$R782_GITREPO" checkout -q -b feature-derived 2>/dev/null; then
  : > "$S782/ghlog"
  ( cd "$R782_GITREPO" && GHLOG="$S782/ghlog" REP_FIXTURE="$S782/one.json" REP_RC="" DEVFLOW_GH="$S782/gh" \
      bash "$REP_SH" --issue 782 --base main >/dev/null 2>"$S782/err" )
  assert_eq "#782 --branch omitted: the branch is read internally and reaches the query as --head" "yes" \
    "$(case "$(cat "$S782/ghlog")" in *"--head feature-derived"*) echo yes ;; *) echo no ;; esac)"
  # A detached HEAD is exactly what `git branch --show-current` prints EMPTY for — the shape
  # the empty-branch guard exists for, reached here through the real read rather than a
  # supplied `--branch ""`.
  if git -C "$R782_GITREPO" checkout -q --detach 2>/dev/null; then
    : > "$S782/ghlog"
    _o="$( cd "$R782_GITREPO" && GHLOG="$S782/ghlog" REP_FIXTURE="$S782/one.json" REP_RC="" DEVFLOW_GH="$S782/gh" \
        bash "$REP_SH" --issue 782 --base main 2>"$S782/err" )" && _s=0 || _s=$?
    assert_eq "#782 --branch omitted on a DETACHED HEAD: the empty read is REFUSED" "REFUSED|3" \
      "$(printf '%s|%s\n' "$_o" "$_s")"
    assert_eq "#782 --branch omitted on a DETACHED HEAD: ... and gh was never invoked" "yes" \
      "$([ -s "$S782/ghlog" ] && echo no || echo yes)"
  else
    skip "#782 --branch omitted on a DETACHED HEAD: the empty read is REFUSED" host-capability \
      "git could not detach HEAD in the scratch repository"
  fi
else
  skip "#782 --branch omitted: the branch is read internally and reaches the query as --head" host-capability \
    "git could not initialize a scratch repository for the internal branch-read rows"
fi
rm -rf "$R782_GITREPO"
# ── The partial-deployment arms: the header claims EVERY path breadcrumbs, and the four
# ── degraded resolver fallbacks are the ones the stubbed rows above never reach (they always
# ── set DEVFLOW_GH, so the `:=` short-circuits). Copy the helper WITHOUT its lib/ sibling and
# ── let it resolve `gh` off a PATH carrying only the stub, so the existence-vs-sourceability
# ── class (#247) is driven rather than asserted.
R782_PARTIAL="$(mktemp -d)"
if mkdir -p "$R782_PARTIAL/scripts" && cp "$REP_SH" "$R782_PARTIAL/scripts/" 2>/dev/null; then
  : > "$S782/ghlog"
  _o="$(GHLOG="$S782/ghlog" REP_FIXTURE="$S782/one.json" REP_RC="" PATH="$S782:/usr/bin:/bin" \
      env -u DEVFLOW_GH -u DEVFLOW_JQ bash "$R782_PARTIAL/scripts/resolve-existing-pr.sh" \
      --issue 782 --base main --branch feature-x 2>"$S782/err")" && _s=0 || _s=$?
  # REFUSED, not a guessed bare `gh`: the #245 peer-completeness pin forbids a helper
  # retaining a hardcoded `DEVFLOW_GH:=gh` default, and refusing is also the honest answer —
  # with no resolver there is no established gh, and an unestablished tool is not licence to
  # guess. The row asserts the fail-closed token AND that the process still terminates with
  # one well-formed token rather than aborting under `set -u`.
  assert_eq "#782 partial deployment (scripts/ without lib/): REFUSED with ONE well-formed token, never a set -u abort or a guessed bare gh" "REFUSED|3" \
    "$(printf '%s|%s\n' "$_o" "$_s")"
  assert_eq "#782 partial deployment: ... and breadcrumbs the real cause, naming resolve-gh.sh" "yes" \
    "$(case "$(cat "$S782/err")" in *"resolve-gh.sh"*) echo yes ;; *) echo no ;; esac)"
else
  skip "#782 partial deployment (scripts/ without lib/): REFUSED with ONE well-formed token, never a set -u abort or a guessed bare gh" host-capability \
    "could not stage a lib-less copy of the helper"
fi
rm -rf "$R782_PARTIAL"
# ── The JSON boundary row: an absent baseRefName must fail ONLY base-ref, and must not shift
# ── the field split so that closes-issue is reported failed when it in fact held.
assert_eq "#782 validation: an absent baseRefName fails base-ref ALONE (no field-shift into closes-issue)" \
  "ADOPT 41 WARN:base-ref|0" \
  "$(rep782 "$S782/nullbase.json" "" --issue 782 --base main --branch feature-x)"
assert_eq "#782 validation: ... and the breadcrumb reports the base as UNESTABLISHED, not as a mismatch named 'yes'" "yes" \
  "$(case "$(cat "$S782/err")" in *"could not be established"*) echo yes ;; *) echo no ;; esac)"
# ── The query the helper actually issues, observed from the stub's argv log rather than only
# ── pinned as source text: this survives a reformatting of the query line that a literal pin
# ── would not, and it is what proves the four --json fields AC1 requires are really requested.
assert_eq "#782 the issued query is open-scoped, branch-explicit, and requests the four AC1 fields" \
  "pr list --head feature-x --state open --json number,createdAt,baseRefName,closingIssuesReferences" \
  "$(rep782 "$S782/one.json" "" --issue 782 --base main --branch feature-x >/dev/null; cat "$S782/ghlog")"
# ── ARM ORDER, driven by PRECEDENCE — inputs on which two arms' preconditions hold at once,
# ── so the assertion records WHICH arm wins. (Pairwise distinctness of the rows above would be
# ── a tautology: each was already asserted equal to a distinct literal, so no reordering of the
# ── helper could make two of them equal while those rows still pass. Distinctness is asserted
# ── by construction; precedence is what a per-row token assertion genuinely cannot see.)
#
# (1) Argument validation precedes the branch read: a non-numeric --issue AND an empty --branch
#     both refuse, and the issue guard must be the one that fires — its breadcrumb names --issue.
R782_PREC_ISSUE="$(rep782 "$S782/one.json" "" --issue abc --branch "")"
R782_PREC_ISSUE_ERR="$(cat "$S782/err")"
assert_eq "#782 arm order: a non-numeric --issue plus an empty --branch both refuse -> REFUSED" "REFUSED|3" \
  "$R782_PREC_ISSUE"
assert_eq "#782 arm order: ... and the --issue guard is the one that fired (it precedes the branch read)" "yes" \
  "$(case "$R782_PREC_ISSUE_ERR" in *"--issue must be a number"*) echo yes ;; *) echo no ;; esac)"
# (2) The empty-branch guard precedes the query: with BOTH an empty branch and a gh that would
#     fail, the branch guard must win — and gh must never be invoked at all.
R782_PREC_BRANCH="$(rep782 "$S782/one.json" 4 --issue 782 --base main --branch "")"
R782_PREC_BRANCH_ERR="$(cat "$S782/err")"
assert_eq "#782 arm order: an empty branch plus a failing gh -> REFUSED" "REFUSED|3" \
  "$R782_PREC_BRANCH"
assert_eq "#782 arm order: ... the empty-branch guard fired, not the gh-failure arm" "yes" \
  "$(case "$R782_PREC_BRANCH_ERR" in *"the branch name is empty"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#782 arm order: ... and gh was never invoked (the guard truly precedes the query)" "yes" \
  "$([ -s "$S782/ghlog" ] && echo no || echo yes)"
# The empty-branch REFUSED and the gh-failure REFUSED are ONE outcome by design, but they
# are two different causes — the helper must still say which fired (per-branch breadcrumbs).
# Both stderr payloads were captured by the matrix rows above; no re-invocation is needed.
assert_eq "#782 the two REFUSED causes carry distinct stderr breadcrumbs" "differ" \
  "$([ "$R782_ERR_GH" != "$R782_ERR_BRANCH" ] && echo differ || echo same)"
assert_eq "#782 the gh-failure REFUSED breadcrumb is non-empty (the comparison above is not vacuous)" "yes" \
  "$([ -n "$R782_ERR_GH" ] && echo yes || echo no)"
assert_eq "#782 the empty-branch REFUSED breadcrumb is non-empty (the comparison above is not vacuous)" "yes" \
  "$([ -n "$R782_ERR_BRANCH" ] && echo yes || echo no)"
# The helper derives the base internally when --base is omitted (the §3.1 fence passes no
# $BASE across the shell boundary), via the same config-get.sh read the create arm re-derives.
assert_eq "#782 --base omitted: the base is re-derived internally (repo base_branch is main)" "ADOPT 11 OK|0" \
  "$(rep782 "$S782/one.json" "" --issue 782 --branch feature-x)"
# The §3.1 fence must invoke the extracted helper as its own leading token — the extraction is
# only real if the skill routes through it rather than keeping a second inline copy.
assert_pin_unique "#782: §3.1 invokes the extracted resolver as a leading-token vendored-literal helper" \
  'scripts/resolve-existing-pr.sh' "$IMPL_PHASES_DIR/phase-3-review.md"  # structural-pin-ok: helper-contract -- the section 3.1 fence must invoke the extracted resolver as its own leading token, which is what makes the extraction real
rm -rf "$S782"

# ── Issue #493: Phase 1.4 §1.4 PR-body run-link refresh (cloud resume) ──
# On a resumed cloud run that reaches §1.4 and finds an existing open PR, the
# draft PR body's [View run](...) line (written once at PR creation by Phase 3.1)
# is refreshed to the resumed run — mirroring the gate job's workpad Run-link
# refresh. The fence is skill prose, so its boundary is this prose-pinning
# surface; the operative single-line transform, however, is extracted to a
# deterministic helper (scripts/refresh-pr-run-link.py) and is EXECUTED here via
# fixture assertions (issue #493 review Suggestion #1 — it was previously
# asserted only as source text). The fixture tests run the helper directly for the
# Resolves-anchored rewrite, human-line preservation, idempotency, and the
# fail-closed empty-stdin / missing-arg contract.
# The single-line transform is extracted to a deterministic, fixture-tested
# helper (issue #493 review Suggestion #1: the inline python was asserted only
# as source text, never executed). The fence pipes the body through it and
# guards the output non-empty before the PATCH (issue #493 Important #1
# empty-body hardening: a direct transform|gh-api pipe without `pipefail` would
# let a crashed transform blank the body).
P493_HELPER="$LIB/../scripts/refresh-pr-run-link.py"
assert_pin_unique "#493 resume: helper rewrites only the [View run] line following Resolves # (AC2/AC3)" \
  'lines[i - 1].startswith("Resolves #")' "$P493_HELPER"
# Executable fixture coverage of the helper (Suggestion #1 — the operative
# AC1/AC2/AC3/AC8 behavior is now RUN, not merely source-pinned): only the
# Resolves-anchored line is rewritten, a human-added [View run] elsewhere is
# preserved, the transform is idempotent, and empty stdin / a missing URL arg
# fail closed (no output + non-zero exit) so the fence guard skips the PATCH.
# The human-added [View run] line is a STANDALONE `[View run](` line (line 6)
# whose predecessor (`## Reviewer Notes`) is NOT `Resolves #` — so the only thing
# protecting it is the Resolves-anchor discrimination (a `startswith("[View
# run](")`-only guard would rewrite it too). The preservation assertion therefore
# exercises the anchor directly.
P493_IN=$'## Summary\nResolves #493\n[View run](https://x/actions/runs/OLD)\n\n## Reviewer Notes\n[View run](https://x/actions/runs/HUMAN)'
assert_eq "#493 helper: rewrites the Resolves-anchored [View run] line to the new URL (AC1)" \
  '[View run](https://x/actions/runs/NEW)' \
  "$(printf '%s' "$P493_IN" | python3 "$P493_HELPER" 'https://x/actions/runs/NEW' | sed -n '3p')"
assert_eq "#493 helper: preserves a standalone human-added [View run] line not anchored to Resolves # (AC2)" \
  '[View run](https://x/actions/runs/HUMAN)' \
  "$(printf '%s' "$P493_IN" | python3 "$P493_HELPER" 'https://x/actions/runs/NEW' | sed -n '6p')"
assert_eq "#493 helper: idempotent — a second pass reproduces the same body (AC8)" \
  "$(printf '%s' "$P493_IN" | python3 "$P493_HELPER" 'https://x/actions/runs/NEW')" \
  "$(printf '%s' "$P493_IN" | python3 "$P493_HELPER" 'https://x/actions/runs/NEW' | python3 "$P493_HELPER" 'https://x/actions/runs/NEW')"
assert_eq "#493 helper: empty stdin fails closed — no output (Important #1)" \
  "" \
  "$(printf '' | python3 "$P493_HELPER" 'https://x/actions/runs/NEW')"
assert_eq "#493 helper: empty stdin fails closed — non-zero exit (Important #1)" \
  "2" \
  "$(printf '' | python3 "$P493_HELPER" 'https://x/actions/runs/NEW' >/dev/null 2>&1; echo $?)"
assert_eq "#493 helper: missing URL arg fails closed — non-zero exit (Important #1)" \
  "2" \
  "$(printf 'Resolves #1\n[View run](x)' | python3 "$P493_HELPER" >/dev/null 2>&1; echo $?)"
# #1582 moved the §1.4 resume pre-check (incl. this cloud-only run-link refresh) into
# agents/branch-setup.md, so these two prose pins target that file now.
assert_pin_unique "#493 resume: cloud-only guard skips the refresh on a local-tier resume (AC4)" \
  '[ -n "${GITHUB_RUN_ID:-}" ]; then' "$P1582_BS"
assert_pin_unique "#493 resume: best-effort warn on PR-body read failure (distinct from no-line; AC6)" \
  'could not read PR' "$P1582_BS"

# Issue #224: Phase 3.1 (phases/phase-3-review.md) opens the draft PR against the
# CONFIGURED base_branch, not the GitHub default branch. Because each phase's bash
# block is a SEPARATE shell, Phase 1.4's $BASE is out of scope at 3.1, so 3.1 must
# RE-DERIVE it through the config read and fail-closed fallback. The retained assertions
# cover that derivation boundary without pinning the detailed `gh pr create` prose.
P3_REVIEW="$IMPL_PHASES_DIR/phase-3-review.md"
assert_pin_unique "#224 Phase 3.1: re-derives BASE via config-get with the main default" 'config-get.sh .base_branch main' "$P3_REVIEW"
# Do not re-add a `[ -n "$BASE" ]` guard or a same-block ordering pin here: the fallback
# is now the `main` positional default on the pinned `config-get.sh .base_branch main`
# read above, and a guard on a variable no fence binds would assert nothing.
# Deferred (issue #224 review, Suggestion): we do NOT pin that §3.1 OMITS --head.
# Low value — `gh pr create` defaults --head to the checked-out branch, which is the
# correct feature branch at Phase 3.1; a future edit adding --head would not corrupt
# the base targeting this fix protects. Revisit only if --head is ever passed here.

# Versioning is per-repo policy, not the engine's job: implement/SKILL.md must carry NO
# version-bump step. A repo that wants version management opts in via its consumer prompt
# extension (.prflow/prompt-extensions/implement.md), which the loader appends to the skill.
# Pin (1) both removed section headings to 0, (2) no stray Phase-2.6/3.1.5 cross-refs, and
# (3) that DevFlow itself re-homes its own rule into that extension so the dogfooded behavior
# is not silently lost. ("Step 2.6" refs elsewhere belong to review-and-fix, not here.)
assert_eq "implement: no version-bump section (versioning is per-repo, not the engine)" "0" \
  "$(grep -cE '^### (2\.6 Version & changelog|3\.1\.5 Apply the version bump)' "$IMPL_SKILL")"
assert_eq "implement: no stray version-phase cross-refs (Phase 2.6 / 3.1.5)" "0" \
  "$(grep -cE '3\.1\.5|Phase 2\.6' "$IMPL_SKILL")"
assert_eq "implement: DevFlow re-homes its versioning rule to the implement prompt extension" "yes" \
  "$(EXT="$LIB/../.prflow/prompt-extensions/implement.md"; [ -s "$EXT" ] && grep -qF 'plugin.json' "$EXT" && grep -qiF 'changelog' "$EXT" && echo yes || echo no)"

# Behavioral coverage for the base_branch read+guard (token pins above catch a
# refactor that DROPS a token, but not a semantic regression in config-get's
# soft/hard contract that the guard depends on). Mirrors the max_iterations
# resolver+clamp pattern: exercise config-get's real exit behavior, then the
# branch-setup agent's inline guard logic against it. Keep byte-aligned with the
# base-derivation block in agents/branch-setup.md (the Signals source of truth).
BB_CFG="$(mktemp)"
printf '%s' '{"base_branch":"develop"}' > "$BB_CFG"
assert_eq "base_branch: configured value read back verbatim" "develop" \
  "$("$CG" .base_branch main "$BB_CFG")"
printf '%s' '{"prflow":{"effort":"high"}}' > "$BB_CFG"
assert_eq "base_branch: absent key → resolver soft-defaults to main (exit 0)" "main" \
  "$("$CG" .base_branch main "$BB_CFG")"
assert_eq "base_branch: missing config file → resolver soft-defaults to main (exit 0)" "main" \
  "$("$CG" .base_branch main /no/such/config.json)"
# Hard path: a malformed config must exit NON-ZERO with EMPTY stdout (the default is
# NOT applied) — this is the exact contract the inline guard relies on. A regression
# that made config-get emit `main` here would silently mask a malformed-config repo
# onto main; this assertion fails loudly if that contract ever drifts.
printf '%s' '{bad json' > "$BB_CFG"
BB_OUT="$("$CG" .base_branch main "$BB_CFG" 2>/dev/null)"; BB_RC=$?
assert_eq "base_branch: malformed config → resolver exits non-zero, empty stdout" "nonzero-empty" \
  "$([ "$BB_RC" -ne 0 ] && [ -z "$BB_OUT" ] && echo nonzero-empty || echo "rc=$BB_RC out='$BB_OUT'")"
rm -f "$BB_CFG"

# branch-setup.md's inline empty-read guard (Phase 1.4): an empty OR failed read → 'main'.
# Mirrors `BASE=$(config-get.sh …) || BASE=""; [ -n "$BASE" ] || BASE=main` so the
# fallback is exercised as behavior, not just asserted as text.
base_guard() {
  local v="$1" rc="${2:-0}"
  { [ "$rc" -eq 0 ] && [ -n "$v" ]; } && { printf '%s\n' "$v"; return; }
  printf 'main\n'
}
assert_eq "base_branch guard: configured value honored"            "develop" "$(base_guard develop)"
assert_eq "base_branch guard: empty read (rc 0) → main"            "main"    "$(base_guard '')"
assert_eq "base_branch guard: hard-failure read (rc≠0, empty) → main" "main" "$(base_guard '' 2)"

# Worktree-branch detection (#168): Phase 1.4 must reuse the branch a linked git
# worktree was pre-created on (whatever its name) instead of creating a SECOND
# branch. The signal is naming-independent — a linked worktree's --git-common-dir
# (the main repo's .git) differs from its --git-dir (.git/worktrees/<name>); in the
# main working tree they are equal. The behavioral matrix below covers the resulting
# reuse-versus-create decision, including base and detached-HEAD guards.
assert_eq "#168 worktree detect: branch-setup names the linked-worktree signal" "yes" \
  "$(grep -qF 'linked worktree' "$P1582_BS" && echo yes || echo no)"  # raw-guard-ok: non-unique: token appears in both prose and code in branch-setup.md (#1582)

# Behavioral coverage: mirror Phase 1.4's reuse-vs-create decision and exercise the
# whole matrix. Keep behaviorally aligned with the Signals block in agents/branch-setup.md
# (it is a restructured mirror — early-return form — not a byte-for-byte copy). Echoes "reuse"
# (skip creation, use CUR) or "create" (fall through to branch-for-issue.py). The non-empty +
# != base guards wrap BOTH signals exactly as branch-setup.md hoists them; an empty common==gitdir
# (rev-parse failed) collapses Signal 1 to "not a worktree" → create (fail-closed).
# Source of truth: agents/branch-setup.md (Signals). F-9 remains deferred: --path-format=absolute
# normalization is not exercised here because the mirror receives pre-resolved strings;
# a real-git integration test would be needed to cover the rev-parse call itself.
#   decide_branch <git-common-dir> <git-dir> <CUR> <BASE>
decide_branch() {
  local common="$1" gitdir="$2" cur="$3" base="$4"
  # Guards apply to BOTH reuse signals: never reuse a detached HEAD (empty CUR) or the
  # base branch (build on trunk), regardless of which signal would otherwise match.
  if [ -n "$cur" ] && [ "$cur" != "$base" ]; then
    # Signal 1 — linked worktree: common-dir != git-dir (both absolute, both non-empty).
    [ -n "$common" ] && [ -n "$gitdir" ] && [ "$common" != "$gitdir" ] && { echo reuse; return; }
    # Signal 2 — cloud-tier name match (GitHub Action path; not a worktree).
    case "$cur" in
      claude/issue-*|issue-*) echo reuse; return ;;
    esac
  fi
  echo create
}
# AC1+AC2: in a linked worktree, a harness branch whose name matches NEITHER pattern
# is still reused via the worktree signal — exactly the case that used to create a
# second branch.
assert_eq "#168 worktree detect: worktree + worktree-issue-165 (name matches neither) → reuse" "reuse" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/issue-165 worktree-issue-165 main)"
# Overlap: worktree AND a name-matching branch (both signals true) → reuse (locks the
# both-true path so a future refactor can't make the signals mutually exclusive).
assert_eq "#168 worktree detect: worktree + issue-9 (both signals true) → reuse" "reuse" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/x issue-9 main)"
# AC3: cloud-tier name detection still skips creation, in the main working tree (no worktree).
assert_eq "#168 worktree detect: main tree + issue-5 → reuse (name match)" "reuse" \
  "$(decide_branch /repo/.git /repo/.git issue-5 main)"
assert_eq "#168 worktree detect: main tree + claude/issue-5 → reuse (name match)" "reuse" \
  "$(decide_branch /repo/.git /repo/.git claude/issue-5 main)"
# AC4 (fail-closed): inside a worktree but ON the base branch → CREATE, never reuse —
# the change must never build directly on trunk.
assert_eq "#168 worktree detect: worktree + base branch (main) → create [fail-closed]" "create" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/x main main)"
assert_eq "#168 worktree detect: worktree + base branch (develop) → create [fail-closed]" "create" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/x develop develop)"
# AC4 (peer completeness): the base guard wraps Signal 2 too — a base branch NAMED like a
# feature branch (base_branch=issue-5) must still CREATE, not reuse via the name match,
# in the main tree AND inside a worktree.
assert_eq "#168 worktree detect: main tree + base named issue-5 (CUR==BASE) → create [fail-closed]" "create" \
  "$(decide_branch /repo/.git /repo/.git issue-5 issue-5)"
assert_eq "#168 worktree detect: worktree + base named issue-5 (CUR==BASE) → create [fail-closed]" "create" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/x issue-5 issue-5)"
# Fail-closed: detached HEAD inside a worktree (empty CUR) → CREATE, never reuse an empty branch.
assert_eq "#168 worktree detect: worktree + detached HEAD (empty CUR) → create [fail-closed]" "create" \
  "$(decide_branch /repo/.git /repo/.git/worktrees/x '' main)"
# Fail-closed: git rev-parse FAILED (empty common == empty gitdir) → Signal 1 collapses
# to "not a worktree"; a non-matching name then CREATEs (with the SKILL breadcrumb).
assert_eq "#168 worktree detect: rev-parse failure (empty dirs) + worktree-issue-165 → create [fail-closed]" "create" \
  "$(decide_branch '' '' worktree-issue-165 main)"
# Asymmetric rev-parse (one empty, one populated — injected GIT_DIR or transient failure)
# must also create, not false-positive-reuse via Signal 1 (the != inequality is vacuously
# true when one operand is empty; the non-empty guard closes this).
assert_eq "#168 worktree detect: asymmetric rev-parse (common empty, gitdir set) → create [fail-closed]" "create" \
  "$(decide_branch '' '/repo/.git/worktrees/x' worktree-issue-165 main)"
assert_eq "#168 worktree detect: asymmetric rev-parse (common set, gitdir empty) → create [fail-closed]" "create" \
  "$(decide_branch '/repo/.git' '' worktree-issue-165 main)"
# AC5: not in a worktree and not a recognized feature branch → CREATE (branch-for-issue.py path).
assert_eq "#168 worktree detect: main tree + feature-x (no worktree, no name match) → create" "create" \
  "$(decide_branch /repo/.git /repo/.git feature-x main)"
assert_eq "#168 worktree detect: main tree + base branch → create" "create" \
  "$(decide_branch /repo/.git /repo/.git main main)"

# ────────────────────────────────────────────────────────────────────────────
echo "prflow_implement.implement_pr_state (schema + resolution + Phase 4.3 gate)"
# ────────────────────────────────────────────────────────────────────────────
# implement_pr_state gates whether /devflow:implement Phase 4.3 publishes the PR
# (runs `gh pr ready`) or leaves it the draft created in Phase 3.1. The resolution
# boundary is config-get.sh (a deterministic string), so it is unit-testable here;
# the Phase 4.3 prose change (whether `gh pr ready` runs) is non-executable skill
# instructions, pinned below by token + an executable publish-decision guard that
# mirrors the SKILL's single literal-`draft` comparison. Default-to-publish is the
# safe direction: only the exact literal `draft` suppresses publishing.
IPS_SCHEMA="$LIB/../.prflow/config.schema.json"
IPS_EXAMPLE="$LIB/../.prflow/config.example.json"
IPS_PROP='.properties.prflow_implement.properties.implement_pr_state'
assert_eq "implement_pr_state: schema type is string" "string" \
  "$(jq -r "$IPS_PROP.type" "$IPS_SCHEMA")"
assert_eq "implement_pr_state: schema enum is [ready_for_review, draft]" "ready_for_review,draft" \
  "$(jq -r "$IPS_PROP.enum | join(\",\")" "$IPS_SCHEMA")"
assert_eq "implement_pr_state: schema default is ready_for_review" "ready_for_review" \
  "$(jq -r "$IPS_PROP.default" "$IPS_SCHEMA")"
assert_eq "implement_pr_state: schema has a non-empty description" "yes" \
  "$(jq -e "$IPS_PROP.description | type == \"string\" and (length > 0)" "$IPS_SCHEMA" >/dev/null && echo yes || echo no)"
assert_eq "implement_pr_state: example value matches schema default" \
  "$(jq -r "$IPS_PROP.default" "$IPS_SCHEMA")" \
  "$(jq -r '.prflow_implement.implement_pr_state' "$IPS_EXAMPLE")"

# Resolver-read behavior (the string the SKILL's Phase 4.3 reads). config-get maps an
# absent key OR an empty-string value to the supplied default (ready_for_review); any
# other value is returned verbatim and the SKILL treats non-`draft` as publish.
IPS_CFG="$(mktemp)"
printf '%s' '{"prflow_implement":{"implement_pr_state":"draft"}}' > "$IPS_CFG"
assert_eq "implement_pr_state: configured 'draft' read back verbatim" "draft" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG")"
printf '%s' '{"prflow_implement":{"implement_pr_state":"ready_for_review"}}' > "$IPS_CFG"
assert_eq "implement_pr_state: configured 'ready_for_review' read back verbatim" "ready_for_review" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG")"
printf '%s' '{"prflow_implement":{}}' > "$IPS_CFG"
assert_eq "implement_pr_state: absent key → resolver default ready_for_review" "ready_for_review" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG")"
printf '%s' '{"prflow_implement":{"implement_pr_state":""}}' > "$IPS_CFG"
assert_eq "implement_pr_state: empty-string value → resolver default ready_for_review" "ready_for_review" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG")"
printf '%s' '{"prflow_implement":{"implement_pr_state":"published"}}' > "$IPS_CFG"
assert_eq "implement_pr_state: unrecognized value read back verbatim (SKILL treats as publish)" "published" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG")"
assert_eq "implement_pr_state: missing config file → resolver default ready_for_review" "ready_for_review" \
  "$("$CG" .prflow_implement.implement_pr_state ready_for_review /no/such/config.json)"
# Hard read failure (malformed JSON): config-get exits NON-zero with EMPTY stdout — the
# exact contract the SKILL's `PR_STATE=$(…) || PR_STATE=ready_for_review` fallback leans
# on. This is the headline safety property (default-to-publish on a corrupt config); pin
# the resolver half here and the end-to-end half in the guard below.
printf '%s' '{bad json' > "$IPS_CFG"
IPS_OUT="$("$CG" .prflow_implement.implement_pr_state ready_for_review "$IPS_CFG" 2>/dev/null)"; IPS_RC=$?
assert_eq "implement_pr_state: malformed config → resolver exits non-zero, empty stdout" "nonzero-empty" \
  "$([ "$IPS_RC" -ne 0 ] && [ -z "$IPS_OUT" ] && echo nonzero-empty || echo "rc=$IPS_RC out='$IPS_OUT'")"
rm -f "$IPS_CFG"

# The retained Phase 4.3 boundaries cover the config read and clean-tree backstop;
# detailed publish-state prose is intentionally not pinned.
assert_pin_unique "implement_pr_state: SKILL reads via config-get with the ready_for_review default" 'config-get.sh .prflow_implement.implement_pr_state ready_for_review' "$IMPL_SKILL"
# Scoped to phase-4-documentation.md: the clean-tree backstop above the publish gate lives
# there. Phase 3.4's commit-before-dispatch step (issue #1575) legitimately adds a second
# `git status --porcelain` elsewhere in the bundle, so the backstop's uniqueness is asserted
# in its own phase file rather than bundle-wide.
assert_pin_unique "implement_pr_state: SKILL keeps the clean-tree backstop above the gate" 'git status --porcelain' "$IMPL_PHASES_DIR/phase-4-documentation.md"

# Executable publish-decision guard — logic-equivalent to the SKILL's single literal-`draft`
# comparison (semantically mirrors `[ "$PR_STATE" = "draft" ]`; `$1` stands in for
# `$PR_STATE`) so the dry-trace matrix {draft, ready_for_review, "", published} is
# exercised as behavior, not just asserted as prose (the absent/default row is the
# resolver matrix above feeding `ready_for_review` into this guard; the publish arm's
# success/failure split is modeled separately by `ips_outcome` below).
ips_publishes() {
  [ "$1" = "draft" ] && { printf 'draft\n'; return; }
  printf 'publish\n'
}
assert_eq "implement_pr_state gate: 'draft' → leave draft"             "draft"   "$(ips_publishes draft)"
assert_eq "implement_pr_state gate: 'ready_for_review' → publish"      "publish" "$(ips_publishes ready_for_review)"
assert_eq "implement_pr_state gate: empty string → publish"           "publish" "$(ips_publishes '')"
assert_eq "implement_pr_state gate: unrecognized 'published' → publish" "publish" "$(ips_publishes published)"

# End-to-end read+guard, mirroring the SKILL's full Phase 4.3 line
# `PR_STATE=$(config-get … ready_for_review) || PR_STATE=ready_for_review` then the
# literal-`draft` decision. This exercises the load-bearing safety property — a hard
# resolver failure (malformed config) falls back to PUBLISH — through the real resolver,
# which the `ips_publishes` matrix alone does not cover.
ips_state_decision() {
  local st
  st="$("$CG" .prflow_implement.implement_pr_state ready_for_review "$1" 2>/dev/null)" || st=ready_for_review
  ips_publishes "$st"
}
IPS_E2E="$(mktemp)"
printf '%s' '{"prflow_implement":{"implement_pr_state":"draft"}}' > "$IPS_E2E"
assert_eq "implement_pr_state e2e: configured draft → leave draft"        "draft"   "$(ips_state_decision "$IPS_E2E")"
printf '%s' '{"prflow_implement":{}}' > "$IPS_E2E"
assert_eq "implement_pr_state e2e: absent key → publish"                  "publish" "$(ips_state_decision "$IPS_E2E")"
printf '%s' '{bad json' > "$IPS_E2E"
assert_eq "implement_pr_state e2e: malformed config (resolver hard-fail) → publish" "publish" "$(ips_state_decision "$IPS_E2E")"
rm -f "$IPS_E2E"

# Outcome guard mirroring the SKILL's FOUR-arm Phase 4.3 chain:
#   1. PR_STATE=draft                          → draft (no gh pr ready)
#   2. gh pr ready succeeds                     → published
#   3. gh pr ready fails BUT PR is non-draft    → published (idempotent re-run: gh pr ready
#                                                 returns non-zero on an already-ready PR)
#   4. else (still draft, or state unknown)     → publish_failed (fail-safe direction)
# The publish_failed capture (the workpad never falsely claims a PR was published on a
# `gh pr ready` failure) and the idempotent arm (a re-run of an already-published PR is
# NOT a failure) are the headline correctness properties of this change. Modelling all
# arms here, plus the retained breadcrumbs below, catches a dropped `else` or
# idempotent arm. $1 = PR_STATE, $2 = simulated `gh pr ready` exit (0 ok / non-0), $3 = simulated
# `isDraft` re-check result ("true"/"false"/"" when the re-check itself errored).
ips_outcome() {
  [ "$1" = "draft" ] && { printf 'draft\n'; return; }
  if [ "${2:-0}" -eq 0 ]; then printf 'published\n'; return; fi
  [ "${3:-}" = "false" ] && { printf 'published\n'; return; }   # gh failed but PR already non-draft
  printf 'publish_failed\n'                                     # still draft, or state unconfirmed
}
assert_eq "implement_pr_state outcome: draft → draft (no gh pr ready)"                  "draft"          "$(ips_outcome draft 0)"
assert_eq "implement_pr_state outcome: publish + gh pr ready ok → published"            "published"      "$(ips_outcome ready_for_review 0)"
assert_eq "implement_pr_state outcome: gh fails + PR still draft → publish_failed"      "publish_failed" "$(ips_outcome ready_for_review 1 true)"
assert_eq "implement_pr_state outcome: gh fails + PR already non-draft → published (idempotent)" "published" "$(ips_outcome ready_for_review 1 false)"
assert_eq "implement_pr_state outcome: gh fails + state unconfirmed (re-check errored) → publish_failed (fail-safe)" "publish_failed" "$(ips_outcome ready_for_review 1 '')"

# Executable assertions below cover the publish-failure breadcrumbs and outcome model.
# Detailed idempotent and finalize wording is intentionally not pinned.
# Pin the outcome WORD, not a `PR_OUTCOME=` assignment: no fence binds that variable any
# more, so a pin on the assignment would pass while the failure path was swallowed.
assert_eq "implement_pr_state: SKILL captures the publish_failed outcome (gh pr ready failure not swallowed)" "yes" \
  "$(grep -qF 'publish_failed' "$IMPL_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: the publish-failed outcome word appears on multiple finalize-routing lines  # structural-pin-ok: machine-sentinel-provenance -- publish_failed is the outcome value the publish-failure path records
assert_eq "implement_pr_state: SKILL labels the idempotent re-run breadcrumb" "yes" \
  "$(grep -qF 'idempotent re-run' "$IMPL_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'idempotent re-run' appears twice in implement SKILL
# Positional check: the clean-tree backstop must run ABOVE the publish gate (the diff's
# behavioral change is that it runs unconditionally in BOTH publish and draft cases), not
# merely be present somewhere. Assert line ordering, not bare presence.
# issue #218: grep the OWNING phase file, NOT the bundle. Both literals live in Phase 4.3
# (phases/phase-4-documentation.md). A POSITIONAL guard needs a single coordinate space with
# both endpoints unique; on the multi-file bundle, `head -1` of the generic `git status
# --porcelain` idiom could grab a future earlier-phase occurrence (lower bundle line number),
# making `-lt` pass vacuously. The owning file is the only space where both endpoints stay unique.
IPS_BACKSTOP_LN=$(grep -nF 'git status --porcelain' "$IMPL_PHASES_DIR/phase-4-documentation.md" | head -1 | cut -d: -f1)
IPS_GATE_LN=$(grep -nF 'config-get.sh .prflow_implement.implement_pr_state' "$IMPL_PHASES_DIR/phase-4-documentation.md" | head -1 | cut -d: -f1)
assert_eq "implement_pr_state: clean-tree backstop precedes the publish gate (runs in both cases)" "yes" \
  "$([ -n "$IPS_BACKSTOP_LN" ] && [ -n "$IPS_GATE_LN" ] && [ "$IPS_BACKSTOP_LN" -lt "$IPS_GATE_LN" ] && echo yes || echo no)"

# Cross-file Progress-label consistency. The Phase 4.3 finalize `--tick-progress` label
# in phases/phase-4-documentation.md MUST match the `## Progress` row label that scripts/workpad.py
# OWNS (its cmd_new_body template + _PROGRESS_PHASES tuple + _STATUS_TO_PROGRESS_PHASE
# 'complete' map) — workpad.py both renders the row and ticks it by substring, so if the
# two sides drift the finalize finds no matching unticked row and the Phase 4.3 update
# ABORTS. (This guards the exact desync a mid-review rename of the row to "PR finalized"
# introduced: SKILL renamed, workpad.py not.) Both sides are pinned to the same literal,
# so renaming one without the other goes red here.
WP_PY="$LIB/../scripts/workpad.py"
# NB: `--` ends grep's option parsing — the pattern begins with `--tick-progress`, which
# grep would otherwise treat as an (invalid) long option. pin_count now carries the same `--`
# guard (#374), so the flag shape is no longer the blocker; this stays a raw presence guard
# only because the literal is NON-UNIQUE across the bundle (it recurs in phase-4-documentation.md
# alongside the SKILL.md prose site), which assert_pin_unique (== 1) would reject.
assert_eq "implement finalize: SKILL ticks the workpad.py-owned 'PR marked ready' label" "yes" \
  "$(grep -qF -- '--tick-progress "PR marked ready"' "$IMPL_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: '--tick-progress "PR marked ready"' recurs across the bundle (SKILL.md prose + phase-4)
assert_eq "implement finalize: workpad.py owns the 'PR marked ready' label (template + _PROGRESS_PHASES agree)" "yes" \
  "$(grep -qF '**PR marked ready**' "$WP_PY" && grep -qF "'PR marked ready'" "$WP_PY" && echo yes || echo no)"

# ── issue #169: workpad.py tick failure-isolation + index ticking ─────────────
# Coupled contract spanning scripts/workpad.py (the volatile-vs-structural behavior +
# the --tick-ac-n/--tick-plan-n flags) ↔ the implement-skill bundle ↔ this suite.
# Two clauses below go red on an edit to either side: workpad.py must define the index
# flags, and the SKILL.md bundle must carry the named failure-isolation contract. The
# Phase 3.4 hand-picked-substring foot-gun is guarded only by an ABSENCE pin — the
# superseded example must stay gone; the index call site itself is not positively pinned,
# so rewording it to any other form leaves this block green. The index flags themselves
# are documented by workpad.py's own --help, not by SKILL.md.
# (workpad.py's runtime behavior is pinned exhaustively in
# lib/test/test_python_scripts.py; these are the doc-mirror pins.)
assert_eq "#169: workpad.py defines the --tick-ac-n / --tick-plan-n index flags" "yes" \
  "$(grep -qF -- '--tick-ac-n' "$WP_PY" && grep -qF -- '--tick-plan-n' "$WP_PY" && echo yes || echo no)"
# The named contract heading is target-unique (a bare 'volatile' grep would stay green
# if the contract paragraph were deleted but the word survived elsewhere).
assert_pin_unique "#169: implement/SKILL.md carries the named volatile-vs-structural failure-isolation contract" \
  'Failure-isolation contract (volatile vs. structural)' "$IMPL_SKILL"  # structural-pin-ok: cross-file-phase-contract -- the implement-top failure-isolation contract governs every phase file
# ABSENCE pin (the hand-picked substring example must be GONE) — assert_pin_unique
# (count==1) cannot express absence, so it carries an explicit #157 allowlist marker.
assert_eq "#169: Phase 3.4 AC-tick uses the index form (no hand-picked '{substring of AC text}')" "yes" \
  "$(grep -qF -- '--tick-ac "{substring of AC text}"' "$IMPL_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin — the superseded substring example must be GONE
# Finding 1 (review): the gate must CONSUME the new non-zero-exit contract — the SKILL
# tells callers a tick's non-zero exit means it did not land (never advance on the
# stdout body alone). Target-unique phrase → assert_pin_unique.
assert_pin_unique "#169: implement/SKILL.md tells callers to check the tick exit code, not the stdout body alone" \
  'never advance on the stdout body alone' "$IMPL_SKILL"  # structural-pin-ok: helper-contract -- the tick helper's exit code, not its stdout body, is the caller's signal
# Finding 4 (review): ABSENCE pin — the stale '--tick-ac later' note must be gone
# (replaced by '--tick-ac-n'); allowlist marker per #157 (absence is not expressible
# via assert_pin_unique).
assert_eq "#169: implement/SKILL.md 2.2.6 note references the index gate-tick flag (no stale '--tick-ac later')" "yes" \
  "$(grep -qF 'will tick via `--tick-ac` later' "$IMPL_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin — the superseded '--tick-ac later' note must be GONE
# Shadow Finding 2 (review): the SKILL tells callers a volatile miss already PATCHed the
# status/notes, so on a non-zero exit they re-tick ONLY the row(s) and do not re-send the
# whole call (which would double-write append-only notes). Coupled with workpad.py's
# breadcrumb wording, which test_python_scripts.py shadow-F2 pins. Target-unique phrase.
assert_pin_unique "#169: implement/SKILL.md warns re-tick-only (don't re-send the whole call on a volatile miss)" \
  'do not blindly re-send the whole call' "$IMPL_SKILL"  # structural-pin-ok: helper-contract -- a volatile tick miss is re-ticked, never re-sent as the whole call
# Shadow Finding 1 (review): workpad.py reports volatile misses on the gh-PATCH-failure
# path too (not just the structural-abort and clean-PATCH paths), via the single
# _report_failed_ticks chokepoint — so a miss collected before a 5xx/auth PATCH failure
# is never silently dropped. test_python_scripts.py shadow-F1 pins the behavior.
assert_eq "#169: workpad.py routes volatile misses through _report_failed_ticks (PATCH-failure echo)" "yes" \
  "$(grep -qF 'def _report_failed_ticks' "$WP_PY" && grep -qF 'NO workpad change was persisted' "$WP_PY" && echo yes || echo no)"

# ── issue #258: terminal --status Complete self-record gate ───────────────────
# scripts/workpad.py, on a `--status Complete` write, must reconcile the workpad's
# self-record against reality: hard-fail (structural: non-zero exit, NO PATCH,
# Status not flipped) when any NON-post-merge ## Acceptance Criteria row is still
# `- [ ]`, and emit a NON-blocking stderr warning naming any unticked ## Plan row
# while still finalizing. The gate fires ONLY for --status Complete; it never
# modifies a `- [ ]` row. Exercised here as a real CLI subprocess against a gh
# stub (the five AC-7 scenarios), and pinned exhaustively at the _apply_mutations
# level in lib/test/test_python_scripts.py. Two scenarios go RED against the
# pre-gate workpad.py — (a): old code PATCHed Complete over an unticked AC; (c):
# old code emitted no Plan warning. (b)/(d)/(e) are controls that pass identically
# on old and new code — they guard against the gate OVER-firing (post-merge-only,
# all-ticked, and --status Blocked must NOT be blocked or warned).
S258="$(mktemp -d)"
cat > "$S258/gh" <<'STUB'
#!/usr/bin/env bash
# Minimal gh stub for workpad.py update: repo view, comments list (marker match),
# body fetch, and PATCH (records that a PATCH happened + echoes the patched body).
j="$*"
if [[ "$j" == *"repo view"* ]]; then echo "owner/repo"; exit 0; fi
if [[ "$j" == *"-X PATCH"* ]]; then
  echo p >> "$WP_PATCHLOG"
  for a in "$@"; do case "$a" in body=@*) cat "${a#body=@}";; esac; done
  exit 0
fi
if [[ "$j" == *"issues/comments/7"* ]]; then cat "$WP_BODY"; exit 0; fi
if [[ "$j" == *"issues/999/comments"* ]]; then echo '[{"id":7,"body":"<!-- devflow:workpad -->"}]'; exit 0; fi
echo '[]'
STUB
chmod +x "$S258/gh"

# issue #1087: the terminal gate also requires a validated completion
# verification-flight marker. Stand up a passing flight record under a temp
# repo-root and carry the marker in the fixtures' ## Progress, so the #258 AC/Plan
# self-record gate (which runs AFTER the evidence gate) is exercised on its own
# terms. run258 pins the candidate identity with --claim-identity so no git tree
# derivation is needed. A dedicated no-marker assertion below pins the evidence
# gate's own missing-evidence abort.
S258_ROOT="$(mktemp -d)"
S258_KEY="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
mkdir -p "$S258_ROOT/.prflow/tmp/verification-flights"
cat > "$S258_ROOT/.prflow/tmp/verification-flights/$S258_KEY.json" <<'VFJSON'
{"state":"passed","result":"passed","candidate_identity":"treeX","suite_summary":{"command":"lib/test/run.sh","exit_status":0,"skipped_checks":[]},"skipped_checks":[]}
VFJSON

# Fixture bodies. Base = every Plan/AC row ticked (the clean-run shape). The
# ## Progress section carries the validated completion-verification marker.
cat > "$S258/all-ticked.md" <<WPMD
<!-- devflow:workpad -->
# DevFlow Workpad — Issue #999

**Status:** 🚀 Documenting
**Last updated:** 2026-05-15T00:00:00Z

## Progress
- [x] **Setup**
  - 00:00:00 — completion verification recorded <!-- prflow:checkpoint completion-verification:$S258_KEY -->
  - 00:00:01 — checkpoint 4 clean <!-- prflow:checkpoint base-update-checkpoint-4 --> (issue #1348: the required-artifact gate needs this row before a Complete finalize)
  - 00:00:02 — review coverage recorded (issue #1453: the gate needs a complete record before a Complete finalize, and it runs BEFORE the AC hard-fail, so without this row (a)'s abort would name the coverage refusal rather than the offending AC row; the marker must be the note's LAST token — the reader accepts only a trailing marker) <!-- prflow:checkpoint review-coverage:full:attempted:complete:complete -->

## Plan
- [x] Plan step one
- [x] Plan step two

## Acceptance Criteria
- [x] AC one
- [x] AC two
WPMD
# A marker-free copy for the evidence-gate abort test (issue #1087).
grep -v 'completion-verification:' "$S258/all-ticked.md" > "$S258/no-marker.md"
# (a) a non-post-merge AC row still unticked.
sed 's/- \[x\] AC two/- [ ] AC two/' "$S258/all-ticked.md" > "$S258/ac-unticked.md"
# (b) the ONLY outstanding AC row carries the (post-merge) marker.
sed 's/- \[x\] AC two/- [ ] AC two (post-merge)/' "$S258/all-ticked.md" > "$S258/ac-postmerge.md"
# (c) a ## Plan row unticked, every AC ticked.
sed 's/- \[x\] Plan step two/- [ ] Plan step two/' "$S258/all-ticked.md" > "$S258/plan-unticked.md"

# run258 <body-file> <args...> → prints the exit code; leaves out/err/patchlog on disk.
run258() {
  local body="$1"; shift
  : > "$S258/patchlog"
  WP_BODY="$body" WP_PATCHLOG="$S258/patchlog" DEVFLOW_GH="$S258/gh" \
    python3 "$WP_PY" update 999 --print-body \
      --repo-root "$S258_ROOT" --claim-identity treeX "$@" >"$S258/out" 2>"$S258/err"
  echo $?
}

# (issue #1087) --status Complete over a workpad with NO completion marker aborts
# non-zero with NO PATCH and names missing-evidence — the "Completion requires
# marker" AC at the real CLI boundary.
_c="$(run258 "$S258/no-marker.md" --status Complete)"
assert_eq "#1087: --status Complete with no completion marker aborts non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#1087: the no-marker abort made NO PATCH" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"
assert_eq "#1087: the no-marker abort names missing-evidence" "yes" \
  "$(grep -q 'missing-evidence' "$S258/err" && echo yes || echo no)"

# (a) --status Complete aborts non-zero with NO PATCH when a non-post-merge AC is [ ].
_c="$(run258 "$S258/ac-unticked.md" --status Complete)"
assert_eq "#258(a): --status Complete aborts non-zero on an unticked non-post-merge AC" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#258(a): the abort made NO PATCH (self-record not flipped to Complete)" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"
assert_eq "#258(a): the abort names the offending AC row on stderr" "yes" \
  "$(grep -q 'AC two' "$S258/err" && echo yes || echo no)"

# (b) only outstanding AC is (post-merge) → finalizes normally (PATCH, Status flipped).
_c="$(run258 "$S258/ac-postmerge.md" --status Complete)"
assert_eq "#258(b): a post-merge-only outstanding AC finalizes (exit 0)" "0" "$_c"
assert_eq "#258(b): the post-merge-only finalize PATCHed the Status to Complete" "yes" \
  "$(grep -q '🎉 Complete' "$S258/out" && echo yes || echo no)"

# (c) a ## Plan row unticked → succeeds-with-warning (non-blocking), Status flips.
_c="$(run258 "$S258/plan-unticked.md" --status Complete)"
assert_eq "#258(c): an unticked Plan row does NOT block finalize (exit 0)" "0" "$_c"
assert_eq "#258(c): finalize emits a non-blocking Plan warning naming the unticked row" "yes" \
  "$(grep -qi 'plan' "$S258/err" && grep -q 'Plan step two' "$S258/err" && echo yes || echo no)"
assert_eq "#258(c): the Plan-warning finalize still flipped Status to Complete" "yes" \
  "$(grep -q '🎉 Complete' "$S258/out" && echo yes || echo no)"

# (d) all rows ticked → succeeds silently (no AC abort, no Plan warning).
_c="$(run258 "$S258/all-ticked.md" --status Complete)"
assert_eq "#258(d): a fully-ticked run finalizes (exit 0)" "0" "$_c"
assert_eq "#258(d): a fully-ticked finalize emits NO Plan/AC gate warning" "yes" \
  "$(grep -qiE 'unticked|refusing to finalize' "$S258/err" && echo no || echo yes)"

# (e) --status Blocked with an unticked AC is NEVER gated (behaves as today).
_c="$(run258 "$S258/ac-unticked.md" --status Blocked)"
assert_eq "#258(e): --status Blocked with an unticked AC is not gated (exit 0)" "0" "$_c"
assert_eq "#258(e): --status Blocked with an unticked AC still PATCHed (Status → Blocked)" "yes" \
  "$([ -s "$S258/patchlog" ] && grep -q '👎 Blocked' "$S258/out" && echo yes || echo no)"

# Source pin: the terminal gate + its post-merge exclusion live in workpad.py.
assert_eq "#258: workpad.py carries the terminal --status Complete self-record gate" "yes" \
  "$(grep -q '_terminal_complete_gate' "$WP_PY" && grep -q "(post-merge)" "$WP_PY" && echo yes || echo no)"

# ── issue #1348: the terminal required-artifact gate at the REAL CLI boundary ──
# Drive the actual workpad.py subprocess (run258 sets a passing completion-evidence
# flight, so a Complete write reaches the required-artifact gate) over the refusal
# path, the compliant path, both marker spellings, the tier-refused carrier, and the
# resumed-run (strip-then-Complete) case — asserting NO PATCH on every refusal. The
# in-process Python tests bypass this gate by default; this block exercises it end to
# end where the CLI actually runs it. all-ticked.md carries the clean checkpoint-4 row.
# (a) A Complete whose ## Progress carries NO checkpoint-4 row is refused with NO PATCH,
# naming the missing artifact and its producing command.
grep -v 'checkpoint base-update-checkpoint-4' "$S258/all-ticked.md" > "$S258/cp4-missing.md"
_c="$(run258 "$S258/cp4-missing.md" --status Complete)"
assert_eq "#1348 CLI: a Complete with no checkpoint-4 row is refused (exit non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#1348 CLI: the missing-artifact refusal made NO PATCH" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"
assert_eq "#1348 CLI: the refusal names the missing artifact and its producer" "yes" \
  "$(grep -q 'missing-artifact' "$S258/err" && grep -q 'update-branch-checkpoint.sh' "$S258/err" && echo yes || echo no)"
# (b) The compliant path: the clean checkpoint-4 row lets the Complete finalize.
_c="$(run258 "$S258/all-ticked.md" --status Complete)"
assert_eq "#1348 CLI: a clean checkpoint-4 row finalizes Complete (exit 0)" "0" "$_c"
assert_eq "#1348 CLI: the compliant finalize PATCHed Status → Complete" "yes" \
  "$(grep -q '🎉 Complete' "$S258/out" && echo yes || echo no)"
# (c) The superseded devflow: marker spelling also satisfies the gate.
sed 's/prflow:checkpoint base-update-checkpoint-4/devflow:checkpoint base-update-checkpoint-4/' \
  "$S258/all-ticked.md" > "$S258/cp4-devflow.md"
_c="$(run258 "$S258/cp4-devflow.md" --status Complete)"
assert_eq "#1348 CLI: the superseded devflow: checkpoint-4 spelling finalizes Complete (exit 0)" "0" "$_c"
# (d) The tier-refused carrier satisfies the required artifact.
sed 's/checkpoint base-update-checkpoint-4 -->/checkpoint base-update-checkpoint-4-tier-refused -->/' \
  "$S258/all-ticked.md" > "$S258/cp4-refused.md"
_c="$(run258 "$S258/cp4-refused.md" --status Complete)"
assert_eq "#1348 CLI: the tier-refused checkpoint-4 carrier finalizes Complete (exit 0)" "0" "$_c"
# (e) The resumed-run case: --strip-inherited-checkpoints clears the row in the same
# call, so the post-mutation Complete gate finds no row and refuses with NO PATCH
# (a resumed run cannot satisfy the gate on an inherited row).
_c="$(run258 "$S258/all-ticked.md" --strip-inherited-checkpoints --status Complete)"
assert_eq "#1348 CLI: a strip-then-Complete (resumed run) is refused (exit non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#1348 CLI: the resumed-run refusal made NO PATCH" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"

# ── issue #1611: CI-derived completion-evidence at the REAL CLI boundary ──────
# The CI family (a local/interactive run's reading of a green required check, #1607)
# validates OFFLINE against a real git repo (rev-parse HEAD + status --porcelain), so
# this block stands up a git repo as --repo-root rather than the flight-fixture dir.
# A CI body carries NO completion-verification marker; the CLI records the
# completion-ci marker and finalizes in one --record-completion-evidence-ci call.
S1611_ROOT="$(mktemp -d)"
git -C "$S1611_ROOT" init -q -b main
# A ci.yml declaring the required checks (issue #1898) — the single declared source
# _required_checks reads. Committed so the tree is clean for the validator's own check.
mkdir -p "$S1611_ROOT/.github/workflows"
printf 'jobs:\n  test:\n    # prflow:required-check\n    name: lib + python tests\n  lint:\n    # prflow:required-check\n    name: lint (shellcheck + actionlint + ruff)\n' \
  > "$S1611_ROOT/.github/workflows/ci.yml"
git -C "$S1611_ROOT" add -A
git -C "$S1611_ROOT" -c user.email=t@t -c user.name=t commit -qm init
S1611_HEAD="$(git -C "$S1611_ROOT" rev-parse HEAD)"
# The covering --completion-ci-check pairs reused across the valid-record assertions.
S1611_CHECKS=(--completion-ci-check "lib + python tests" success \
              --completion-ci-check "lint (shellcheck + actionlint + ruff)" success)
# CI body = the all-ticked shape minus the flight completion-verification marker row.
# It (and the CLI's out/err/patchlog) live OUTSIDE the repo so its own tree stays
# clean — the validator's `git status --porcelain` clean-tree check reads that repo.
grep -v 'completion-verification:' "$S258/all-ticked.md" > "$S258/ci-body.md"

run1611() {
  local body="$1"; shift
  : > "$S258/patchlog"
  WP_BODY="$body" WP_PATCHLOG="$S258/patchlog" DEVFLOW_GH="$S258/gh" \
    python3 "$WP_PY" update 999 --print-body \
      --repo-root "$S1611_ROOT" "$@" >"$S258/out" 2>"$S258/err"
  echo $?
}

# (a) A valid CI reading records the marker and finalizes Complete (exit 0, PATCH).
_c="$(run1611 "$S258/ci-body.md" \
  --record-completion-evidence-ci "$S1611_HEAD" local "https://x/runs/1" \
  "${S1611_CHECKS[@]}" \
  --status Complete)"
assert_eq "#1611 CLI: a valid CI reading finalizes Complete (exit 0)" "0" "$_c"
assert_eq "#1611 CLI: the CI finalize PATCHed Status → Complete" "yes" \
  "$(grep -q '🎉 Complete' "$S258/out" && echo yes || echo no)"
assert_eq "#1611 CLI: exactly one completion-ci marker, no flight marker" "yes" \
  "$([ "$(grep -c 'completion-ci:' "$S258/out")" = "1" ] && ! grep -q 'completion-verification:' "$S258/out" && echo yes || echo no)"

# (b) A non-success conclusion is refused with NO PATCH, naming verification-not-pass.
_c="$(run1611 "$S258/ci-body.md" \
  --record-completion-evidence-ci "$S1611_HEAD" local "https://x/runs/1" \
  --completion-ci-check "lib + python tests" failure \
  --completion-ci-check "lint (shellcheck + actionlint + ruff)" success \
  --status Complete)"
assert_eq "#1611 CLI: a failure-conclusion CI record is refused (exit non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#1611 CLI: the failure-conclusion refusal made NO PATCH" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"
assert_eq "#1611 CLI: the failure refusal names verification-not-pass" "yes" \
  "$(grep -q 'verification-not-pass' "$S258/err" && echo yes || echo no)"

# (c) A stale SHA (not the current head) is refused with NO PATCH, naming stale-candidate.
_c="$(run1611 "$S258/ci-body.md" \
  --record-completion-evidence-ci "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb" local "https://x/runs/1" \
  "${S1611_CHECKS[@]}" \
  --status Complete)"
assert_eq "#1611 CLI: a stale-SHA CI record is refused (exit non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#1611 CLI: the stale-SHA refusal made NO PATCH" "yes" \
  "$([ -s "$S258/patchlog" ] && echo no || echo yes)"
assert_eq "#1611 CLI: the stale-SHA refusal names stale-candidate" "yes" \
  "$(grep -q 'stale-candidate' "$S258/err" && echo yes || echo no)"

rm -rf "$S1611_ROOT"

rm -rf "$S258" "$S258_ROOT"

# ── issue #781: workpad-sourced acceptance criteria (acs / acs-resolve) ────────
# The review engine used to source the criteria it judges a PR against from the
# GitHub issue BODY, while /devflow:implement's authoritative criteria live in
# the workpad comment (Phase 2.2.5 narrows the set, 2.2.6 rewrites text, 3.4
# retags) — and a blind 200-line truncation could drop the section entirely.
# `workpad.py acs` reads the workpad's section back out; `acs-resolve` resolves
# BOTH surfaces, runs the PR-identity guard, selects the reviewer-facing value,
# names the source, and reports normalized divergence.
#
# Driven here as real CLI subprocesses against a gh stub over the full
# input-shape matrix the issue's testing strategy enumerates (production-realistic
# fixture, missing/duplicate/non-canonical/empty/truncated section, both
# sentinels, cross-PR workpad, unbound record, read failure, post-merge +
# Test-Plan mixture, byte-identical re-run) — asserting the SPECIFIC output for
# each shape, never merely that it exits 0.
S781="$(mktemp -d)"
cat > "$S781/gh" <<'STUB'
#!/usr/bin/env bash
# gh stub for workpad.py acs / acs-resolve. $WP781_BODY selects the workpad
# fixture, $WP781_ISSUE the issue-body fixture; the two failure knobs are each
# driven by a scenario below (no declared-but-unused knobs).
j="$*"
if [[ "$j" == *"repo view"* ]]; then echo "owner/repo"; exit 0; fi
if [[ "$j" == *"issue view"* ]]; then
  if [ "${WP781_ISSUE_FAIL:-}" = "1" ]; then echo "gh: stubbed issue-body transport failure" >&2; exit 1; fi
  cat "$WP781_ISSUE"; exit 0
fi
if [[ "$j" == *"/comments"* ]]; then
  if [ "${WP781_COMMENT_FAIL:-}" = "1" ]; then echo "gh: stubbed transport failure" >&2; exit 1; fi
  if [ "${WP781_NO_WORKPAD:-}" = "1" ]; then echo '[]'; exit 0; fi
  python3 -c 'import json,sys;print(json.dumps([{"id":7,"body":open(sys.argv[1]).read()}]))' "$WP781_BODY"
  exit 0
fi
echo '[]'
STUB
chmod +x "$S781/gh"

# The issue body every scenario compares against: three criteria, untagged (the
# issue body never carries the ` (post-merge)` tag — parse-acs.py synthesizes it
# at mirror time, which is why the divergence comparand must be UNfiltered).
cat > "$S781/issue.md" <<'ISSUEMD'
## Background
Narrative that would be truncated away on a long body.

## Acceptance Criteria

- [ ] Criterion A
- [ ] Criterion B
- [ ] Criterion C
ISSUEMD

# Production-realistic workpad: a real run's section order, a ticked criterion, a
# ` (post-merge)`-tagged one, a mirrored ## Test Plan item, and a bound
# scope-decision record. text= is base64 of "Criterion C".
cat > "$S781/wp-real.md" <<'WPMD'
<!-- devflow:workpad -->
# DevFlow Workpad — Issue #999

**Status:** 🚀 Reviewing
**Branch:** `feat`
**Last updated:** 2026-07-24 10:00 UTC

## Progress
- [x] **Setup** — branch & workpad
  - 10:00:01 — scope decision: this PR delivers A and B. <!-- devflow:scope-decision pr=143 kind=deferred text=Q3JpdGVyaW9uIEM= -->

## Plan
- [x] step one

## Acceptance Criteria
- [x] Criterion A
- [ ] Criterion B (post-merge)

- [ ] Test-plan item one

## Devflow Reflection
<details>
<summary>Devflow Reflection (click to expand)</summary>

</details>
WPMD

_wp781_variant() { python3 - "$S781/wp-real.md" "$1" "$2" "$3" <<'PY'
import sys, pathlib
src, dest, old, new = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
pathlib.Path(dest).write_text(pathlib.Path(src).read_text().replace(old, new))
PY
}
_AC781='- [x] Criterion A
- [ ] Criterion B (post-merge)

- [ ] Test-plan item one'
_wp781_variant "$S781/wp-crosspr.md"    'pr=143' 'pr=999'
_wp781_variant "$S781/wp-pending.md"    'pr=143' 'pr=pending'
_wp781_variant "$S781/wp-rewritten.md" \
  '<!-- devflow:scope-decision pr=143 kind=deferred text=Q3JpdGVyaW9uIEM= -->' \
  '<!-- devflow:scope-decision pr=143 kind=rewritten text=Q3JpdGVyaW9uIEM= newtext=Q3JpdGVyaW9uIEMy -->'
_wp781_variant "$S781/wp-unmirrored.md" "$_AC781" '_(pending — mirrored from the issue when the run begins)_'
_wp781_variant "$S781/wp-sentinel.md"   "$_AC781" '_(none provided in issue body)_'
_wp781_variant "$S781/wp-empty.md"      "$_AC781" ''
_wp781_variant "$S781/wp-noheading.md"  '## Acceptance Criteria' '## Something Else'
_wp781_variant "$S781/wp-h3.md"         '## Acceptance Criteria' '### Acceptance Criteria'
_wp781_variant "$S781/wp-colon.md"      '## Acceptance Criteria' '## Acceptance Criteria:'
_wp781_variant "$S781/wp-case.md"       '## Acceptance Criteria' '## ACCEPTANCE criteria'
_wp781_variant "$S781/wp-star.md"       '- [x] Criterion A' '* [x] Criterion A'
_wp781_variant "$S781/wp-subheading.md" '- [ ] Test-plan item one' '### Sub
- [ ] Criterion D'
_wp781_variant "$S781/wp-norecord.md" \
  '<!-- devflow:scope-decision pr=143 kind=deferred text=Q3JpdGVyaW9uIEM= -->' 'no record here'
# PARTIAL coverage: the workpad drops TWO of the issue body's criteria (B and C)
# while the single bound record covers only C. This is the one shape that
# separates the per-criterion guard from an existential one — `wp-norecord`
# carries ZERO records, so `if decisions: return True` rejects it for the right
# answer by accident, and every other fixture has full coverage. Here a mutant
# that credits the record set as a whole would ACCEPT a workpad that silently
# dropped Criterion B.
_wp781_variant "$S781/wp-partial.md" '- [ ] Criterion B (post-merge)
' ''
# SUPERSET, zero records: the workpad carries every issue-body criterion (C added)
# and one extra, with NO scope-decision record at all. It must be ACCEPTED —
# reviewing against a superset can only ADD criteria, never silently drop one, and
# dropping is the whole failure `_acs_pr_identity_ok` exists to prevent. This is the
# resume-path / widening-re-mirror shape, and no other fixture covers it: every
# other one is NARROWED and so exercises the rejection direction.
#
# What this does NOT pin, deliberately: `_acs_pr_identity_ok`'s
# `if workpad_norm >= issue_norm: return True` early return. Deleting that line was
# mutation-checked and the suite stayed GREEN — correctly, because on a superset
# `issue_norm - workpad_norm` is empty, so the per-criterion loop falls through to
# `return True` on its own. The early return is a pure short-circuit with no
# behavioral effect, so no test can pin it and none should claim to.
python3 - "$S781/wp-norecord.md" "$S781/wp-superset.md" <<'PY'
import sys, pathlib
src, dest = sys.argv[1], sys.argv[2]
pathlib.Path(dest).write_text(pathlib.Path(src).read_text().replace(
    '- [ ] Test-plan item one', '- [ ] Criterion C\n- [ ] Test-plan item one'))
PY
# Duplicate `## Acceptance Criteria` heading: the FIRST section must win, never a
# silent concatenation of both.
{ cat "$S781/wp-real.md"; printf '\n## Acceptance Criteria\n- [ ] Criterion Z\n'; } > "$S781/wp-dupe.md"
# Truncated: the body is cut mid-section, so the section is terminated by
# end-of-input rather than a sibling heading.
python3 -c 'import sys,pathlib;p=pathlib.Path(sys.argv[1]);pathlib.Path(sys.argv[2]).write_text(p.read_text().split("- [ ] Test-plan")[0].rstrip()+"\n- [ ] Criterion trunc")' \
  "$S781/wp-real.md" "$S781/wp-trunc.md"

# run781 <workpad-fixture> <args...> → prints the exit code; out/err left on disk.
run781() {
  local body="$1"; shift
  WP781_BODY="$body" WP781_ISSUE="$S781/issue.md" DEVFLOW_GH="$S781/gh" \
    python3 "$WP_PY" "$@" >"$S781/out" 2>"$S781/err"
  echo $?
}

# ---- `acs` extraction contract ------------------------------------------------
# Unfiltered by default: tick state preserved, the (post-merge) tag preserved, and
# the mirrored Test-Plan item carried through. This is the divergence comparand.
# Not a byte copy — the parsed items are re-rendered (blank lines dropped, `* [ ]`
# normalized), which is why the expectation below is the item sequence and not the
# stored section's bytes.
_c="$(run781 "$S781/wp-real.md" acs 999)"
assert_eq "#781: acs exits 0 on a resolvable workpad" "0" "$_c"
assert_eq "#781: acs prints every criterion unfiltered (tick state + (post-merge) tag + mirrored Test-Plan item)" \
  '- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Test-plan item one' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"

# The COMPOSED --emit-source-token output on a criteria-BEARING fixture: the
# other --emit-source-token assertions all use zero-criteria fixtures (sentinel,
# unmirrored, colon, noheading, empty), so only the bare token line is ever
# checked. Here the `workpad` source token must lead, followed by the rendered
# criteria — exactly the two-part shape cmd_acs's `out` list assembles and that
# Phase 0.4 parses positionally (token line first, criteria after).
run781 "$S781/wp-real.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: acs --emit-source-token composes the source token line ABOVE the rendered criteria" \
  'workpad|- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Test-plan item one' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"

# The reviewer-facing form: post-merge criteria excluded, every box neutralized.
_c="$(run781 "$S781/wp-real.md" acs 999 --exclude-post-merge --neutralize-boxes)"
assert_eq "#781: acs --exclude-post-merge --neutralize-boxes drops tagged rows and unticks the rest" \
  '- [ ] Criterion A|- [ ] Test-plan item one' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"

# Re-running against an unchanged workpad is byte-identical (a pure read: no
# PATCH, no timestamp, nothing time-varying in the output).
run781 "$S781/wp-real.md" acs 999 >/dev/null; cp "$S781/out" "$S781/rerun-a"
run781 "$S781/wp-real.md" acs 999 >/dev/null; cp "$S781/out" "$S781/rerun-b"
assert_eq "#781: acs output is byte-identical on re-run against an unchanged workpad" "yes" \
  "$(cmp -s "$S781/rerun-a" "$S781/rerun-b" && echo yes || echo no)"

# Clean absence: exit 2 with empty stdout AND empty stderr — the empty stderr is
# what lets Phase 0.4 tell it from argparse's own exit 2.
_c="$(WP781_NO_WORKPAD=1 run781 "$S781/wp-real.md" acs 999)"
assert_eq "#781: acs exits 2 when no workpad comment exists" "2" "$_c"
assert_eq "#781: the clean-absence exit 2 leaves stdout AND stderr empty" "yes" \
  "$([ -s "$S781/out" ] || [ -s "$S781/err" ] && echo no || echo yes)"
# argparse's exit 2 is the same code with NON-empty stderr — the discrimination
# Phase 0.4 applies. Without this control the empty-stderr rule is untested.
assert_eq "#781: argparse's exit 2 on a malformed invocation carries NON-empty stderr" "yes" \
  "$(python3 "$WP_PY" acs not-a-number >/dev/null 2>"$S781/argerr"; [ -s "$S781/argerr" ] && echo yes || echo no)"

# A read failure is a DIFFERENT non-zero shape, so a gh transport blip is never
# routed as "this PR has no workpad".
_c="$(WP781_COMMENT_FAIL=1 run781 "$S781/wp-real.md" acs 999)"
assert_eq "#781: acs exits 3 (not 2) on a gh read failure" "3" "$_c"

# The two sentinels both yield nothing, and both must be DISTINGUISHABLE: they
# make opposite claims about whether the issue had criteria at all.
run781 "$S781/wp-sentinel.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: the absence sentinel yields nothing and reports issue-body" "issue-body" "$(cat "$S781/out")"
run781 "$S781/wp-unmirrored.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: the un-mirrored placeholder reports a DISTINCT workpad-unmirrored token" \
  "workpad-unmirrored" "$(cat "$S781/out")"
run781 "$S781/wp-sentinel.md" acs 999 >/dev/null
assert_eq "#781: a section that yields nothing prints empty stdout at exit 0" "" "$(cat "$S781/out")"

# Non-canonical layout and section-termination edges.
for _f in h3 case star; do
  run781 "$S781/wp-$_f.md" acs 999 >/dev/null
  assert_eq "#781: non-canonical layout ($_f) still resolves the section" \
    '- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Test-plan item one' \
    "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"
done
run781 "$S781/wp-colon.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: a trailing-colon heading does NOT match (casing alone is forgiven)" "issue-body" "$(cat "$S781/out")"
run781 "$S781/wp-noheading.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: a missing section yields nothing" "issue-body" "$(cat "$S781/out")"
run781 "$S781/wp-empty.md" acs 999 --emit-source-token >/dev/null
assert_eq "#781: a present-but-empty section yields nothing" "issue-body" "$(cat "$S781/out")"
run781 "$S781/wp-dupe.md" acs 999 >/dev/null
assert_eq "#781: a duplicate heading does NOT concatenate — the first section wins" \
  '- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Test-plan item one' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"
run781 "$S781/wp-subheading.md" acs 999 >/dev/null
assert_eq "#781: a deeper ### sub-heading does NOT terminate the section" \
  '- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Criterion D' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"
run781 "$S781/wp-trunc.md" acs 999 >/dev/null
assert_eq "#781: a body truncated mid-section terminates the section at end-of-input" \
  '- [x] Criterion A|- [ ] Criterion B (post-merge)|- [ ] Criterion trunc' \
  "$(tr '\n' '|' < "$S781/out" | sed 's/|$//')"

# ---- `acs-resolve` selection, source token and divergence ---------------------
_src781() { grep '^source: ' "$S781/out" | sed 's/^source: //'; }
_div781() { sed -n '/^divergence:$/,$p' "$S781/out" | sed '1d' | tr '\n' '|' | sed 's/|$//'; }

_c="$(run781 "$S781/wp-real.md" acs-resolve 999 --pr 143)"
assert_eq "#781: acs-resolve exits 0 on a resolvable state" "0" "$_c"
assert_eq "#781: the workpad supplies the criteria when it resolves" "workpad" "$(_src781)"
assert_eq "#781: the reviewer-facing value is post-merge-filtered AND box-neutralized" \
  '- [ ] Criterion A|- [ ] Test-plan item one' \
  "$(sed -n '/^criteria:$/,/^divergence:$/p' "$S781/out" | sed '1d;$d' | tr '\n' '|' | sed 's/|$//')"
# `Criterion B (post-merge)` normalizes to `Criterion B`, so the tagged workpad
# row still MATCHES the untagged issue-body row — this is the whole reason the
# comparand is resolved unfiltered while only the reviewer-facing value is filtered.
assert_eq "#781: a covered drop is reported as an audited DEFERRED decision, not a finding" \
  'DEFERRED: Criterion C' "$(_div781)"
assert_eq "#781: the post-merge tag is stripped for comparison (a tagged row still matches its untagged twin)" \
  "no" "$(_div781 | grep -q 'Criterion B' && echo yes || echo no)"
assert_eq "#781: a workpad-side addition (the mirrored Test-Plan item) is NEVER a finding" \
  "no" "$(_div781 | grep -q 'Test-plan' && echo yes || echo no)"

run781 "$S781/wp-rewritten.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a rewritten record reports the text change with both texts" \
  'CHANGED: Criterion C -> Criterion C2' "$(_div781)"

run781 "$S781/wp-norecord.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: an UNCOVERED narrowing is reported as a DROP finding" 'DROP: Criterion C' "$(_div781)"
assert_eq "#781: a narrowed workpad carrying zero records fails CLOSED to pr-identity-mismatch" \
  "pr-identity-mismatch" "$(_src781)"

# Per-criterion coverage, not existential: ONE record covering ONE of two dropped
# criteria leaves the other unexplained, so the workpad is rejected. The divergence
# report must still show BOTH — the covered drop as an audited DEFERRED decision and
# the uncovered one as a DROP finding — so a regression cannot hide the unexplained
# criterion behind the covered one.
run781 "$S781/wp-partial.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: ONE record covering ONE of TWO dropped criteria still fails closed (per-criterion, not existential)" \
  "pr-identity-mismatch" "$(_src781)"
assert_eq "#781: the partially-covered narrowing reports the covered drop AND the uncovered one distinctly" \
  'DROP: Criterion B|DEFERRED: Criterion C' "$(_div781)"

run781 "$S781/wp-superset.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a SUPERSET workpad with ZERO records is accepted (widening is never a drop)" \
  "workpad" "$(_src781)"
assert_eq "#781: the accepted superset reports no divergence finding" "none" "$(_div781)"

run781 "$S781/wp-crosspr.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a record naming ANOTHER PR routes to the issue body under pr-identity-mismatch" \
  "pr-identity-mismatch" "$(_src781)"
run781 "$S781/wp-pending.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: an UNBOUND pr=pending record covers nothing (fails closed)" \
  "pr-identity-mismatch" "$(_src781)"
assert_eq "#781: the pr-identity-mismatch arm falls back to the issue body's criteria" \
  '- [ ] Criterion A|- [ ] Criterion B|- [ ] Criterion C' \
  "$(sed -n '/^criteria:$/,/^divergence:$/p' "$S781/out" | sed '1d;$d' | tr '\n' '|' | sed 's/|$//')"

# Current-branch mode: `--pr` is OMITTED entirely (an EMPTY value is an argparse
# type=int error, which is why Phase 0.4 has a separate arm rather than passing an
# empty flag). With no PR to bind to, NO record can be credited — including one
# bound to a real PR. Without these, the `pr=None` path is never EXECUTED and a
# regression crediting records at `pr=None` would ship green underneath the prose
# pin that guards the arm.
run781 "$S781/wp-norecord.md" acs-resolve 999 >/dev/null
assert_eq "#781: with --pr OMITTED (current-branch mode) a record-less workpad fails closed" \
  "pr-identity-mismatch" "$(_src781)"
assert_eq "#781: the --pr-omitted arm falls back to the issue body's criteria" \
  '- [ ] Criterion A|- [ ] Criterion B|- [ ] Criterion C' \
  "$(sed -n '/^criteria:$/,/^divergence:$/p' "$S781/out" | sed '1d;$d' | tr '\n' '|' | sed 's/|$//')"
run781 "$S781/wp-real.md" acs-resolve 999 >/dev/null
assert_eq "#781: a record BOUND to a real PR is NOT credited when --pr is omitted" \
  "pr-identity-mismatch" "$(_src781)"

run781 "$S781/wp-unmirrored.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: an un-mirrored workpad reports its own token, never the plain issue-body one" \
  "workpad-unmirrored" "$(_src781)"
run781 "$S781/wp-sentinel.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: the absence sentinel routes to the ordinary issue-body token" "issue-body" "$(_src781)"
WP781_NO_WORKPAD=1 run781 "$S781/wp-real.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a PR with no workpad at all routes to the ordinary issue-body token" "issue-body" "$(_src781)"
_c="$(WP781_COMMENT_FAIL=1 run781 "$S781/wp-real.md" acs-resolve 999 --pr 143)"
assert_eq "#781: a failed workpad read is ROUTED (exit 0), never a run-ending error" "0" "$_c"
assert_eq "#781: a failed workpad read reports workpad-read-failed, never a normal issue-body resolution" \
  "workpad-read-failed" "$(_src781)"

# ---- the `none` demotion is gated on CLEAN ABSENCE alone ----------------------
# `none` asserts BOTH surfaces were examined and neither carried criteria (Phase 4
# renders it as exactly that). Every routed non-workpad state falls back to the
# issue body, so when that fallback ALSO comes up empty the demotion arm fires on
# a state whose workpad was never read (`workpad-read-failed` — the repo's
# "Unknown is not zero" anti-pattern: an unestablished measurement collapsed onto
# the real value), never mirrored (`workpad-unmirrored` — the OPPOSITE claim from
# a legitimately criteria-less PR), or read but unattributable
# (`pr-identity-mismatch` — criteria DO exist, this run just cannot confirm they
# are this PR's). The compound shape is what makes it invisible: it needs a
# routed state AND a criteria-less issue body at once, so every fixture above
# (all of which use the three-criterion issue body) passes straight through it.
cat > "$S781/issue-nocriteria.md" <<'ISSUEMD'
## Background
An issue whose body carries no acceptance-criteria section at all.

## Test Plan
- [ ] something that is not the criteria section
ISSUEMD
# Same runner as run781, with the ISSUE-BODY fixture overridden.
run781_issue() {
  local issue="$1" body="$2"; shift 2
  WP781_BODY="$body" WP781_ISSUE="$issue" DEVFLOW_GH="$S781/gh" \
    python3 "$WP_PY" "$@" >"$S781/out" 2>"$S781/err"
  echo $?
}

# Positive control: `none` is still REACHABLE, and only from the clean-absence
# state. Without this the gate below could be satisfied by a mutant that never
# demotes at all.
_c="$(WP781_NO_WORKPAD=1 run781_issue "$S781/issue-nocriteria.md" "$S781/wp-real.md" acs-resolve 999 --pr 143)"
assert_eq "#781: no workpad AND a criteria-less issue body still exits 0" "0" "$_c"
assert_eq "#781: no workpad AND a criteria-less issue body is the ONE state that demotes to none" \
  "none" "$(_src781)"

_c="$(WP781_COMMENT_FAIL=1 run781_issue "$S781/issue-nocriteria.md" "$S781/wp-real.md" acs-resolve 999 --pr 143)"
assert_eq "#781: a failed workpad read over a criteria-less issue body is still ROUTED (exit 0)" "0" "$_c"
assert_eq "#781: a failed workpad read KEEPS its token when the issue-body fallback is also empty (unknown is not zero)" \
  "workpad-read-failed" "$(_src781)"

run781_issue "$S781/issue-nocriteria.md" "$S781/wp-unmirrored.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: an un-mirrored workpad KEEPS its token when the issue-body fallback is also empty" \
  "workpad-unmirrored" "$(_src781)"

# `pr-identity-mismatch` is deliberately NOT driven here: it is UNREACHABLE with a
# criteria-less issue body. `_acs_pr_identity_ok` returns True on an empty
# `issue_norm` (no criterion the workpad could have dropped), so that state and an
# empty issue-body fallback cannot co-occur — asserting it would be a vacuous test
# of a shape the code cannot take. The demotion gate still names it, because the
# gate is written as an allow-list of the ONE demoting state rather than a
# deny-list of the others, so it stays correct if that reachability ever changes.
run781_issue "$S781/issue-nocriteria.md" "$S781/wp-norecord.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a narrowed workpad over a criteria-less issue body has no dropped criterion to reject, so it RESOLVES" \
  "workpad" "$(_src781)"

# ---- a `rewritten` record with no newtext= covers nothing ---------------------
# `_parse_scope_decisions` admits a `rewritten` record whose `newtext=` field is
# ABSENT (it drops only an undecodable or empty one), so `_acs_diverge` used to
# credit it as an audited `CHANGED:` and render "(unrecorded new text)" as the
# replacement — reporting a scope narrowing as reviewed on a record that records
# nothing about what replaced the criterion. `_acs_pr_identity_ok` already fails
# closed on this exact shape (its `new_text is not None` conjunct), so the two
# read the same record set in opposite directions. The criterion must route to
# DROP, and the workpad must be rejected.
_wp781_variant "$S781/wp-rewritten-nonew.md" \
  '<!-- devflow:scope-decision pr=143 kind=deferred text=Q3JpdGVyaW9uIEM= -->' \
  '<!-- devflow:scope-decision pr=143 kind=rewritten text=Q3JpdGVyaW9uIEM= -->'
run781 "$S781/wp-rewritten-nonew.md" acs-resolve 999 --pr 143 >/dev/null
assert_eq "#781: a rewritten record with NO newtext= covers nothing and reports a DROP finding" \
  'DROP: Criterion C' "$(_div781)"
assert_eq "#781: a rewritten record with NO newtext= leaves the workpad rejected (fails closed)" \
  "pr-identity-mismatch" "$(_src781)"

# acs-resolve's exit-3 fail-closed arm, driven BEHAVIORALLY (it was asserted only by
# prose pins). Without the issue body there is no comparand and nothing to resolve, so
# this is the one failure that is NOT a routed source token: a regression routing it as
# a normal `issue-body` resolution would have the reviewer judge the PR against a
# workpad set with no comparand at all, and would have shipped green.
_c="$(WP781_ISSUE_FAIL=1 run781 "$S781/wp-real.md" acs-resolve 999 --pr 143)"
assert_eq "#781: acs-resolve exits 3 when the ISSUE BODY read fails (no comparand, nothing to resolve)" \
  "3" "$_c"
assert_eq "#781: the issue-body read failure never routes to a source token" "" \
  "$(grep '^source: ' "$S781/out" || true)"
assert_eq "#781: the issue-body read failure names itself on stderr" "yes" \
  "$([ -s "$S781/err" ] && echo yes || echo no)"

# acs-resolve is a pure read exactly as `acs` is — nothing time-varying may reach its
# output, or Phase 0.4's injected criteria block would churn between otherwise
# identical runs. `acs` had this pin; acs-resolve did not.
run781 "$S781/wp-real.md" acs-resolve 999 --pr 143 >/dev/null; cp "$S781/out" "$S781/rr-a"
run781 "$S781/wp-real.md" acs-resolve 999 --pr 143 >/dev/null; cp "$S781/out" "$S781/rr-b"
assert_eq "#781: acs-resolve output is byte-identical on re-run against unchanged surfaces" "yes" \
  "$(cmp -s "$S781/rr-a" "$S781/rr-b" && echo yes || echo no)"

# No criteria on EITHER surface → the gap is reported explicitly.
printf '## Background\nnothing here\n' > "$S781/issue-empty.md"
WP781_BODY="$S781/wp-sentinel.md" WP781_ISSUE="$S781/issue-empty.md" DEVFLOW_GH="$S781/gh" \
  python3 "$WP_PY" acs-resolve 999 --pr 143 >"$S781/out" 2>"$S781/err"
assert_eq "#781: neither surface supplying criteria reports the gap as 'none'" "none" "$(_src781)"

# The criteria value is exempt from any line cap: the issue body's section begins
# far past line 200 and must still resolve in full.
{ printf '## Background\n'; for _i in $(seq 1 400); do printf 'filler line %s\n' "$_i"; done;
  printf '\n## Acceptance Criteria\n\n- [ ] Criterion A\n- [ ] Criterion B\n- [ ] Criterion C\n'; } > "$S781/issue-long.md"
WP781_NO_WORKPAD=1 WP781_BODY="$S781/wp-real.md" WP781_ISSUE="$S781/issue-long.md" DEVFLOW_GH="$S781/gh" \
  python3 "$WP_PY" acs-resolve 999 --pr 143 >"$S781/out" 2>"$S781/err"
assert_eq "#781: a criteria section beginning past line 200 resolves in full (no line cap)" \
  '- [ ] Criterion A|- [ ] Criterion B|- [ ] Criterion C' \
  "$(sed -n '/^criteria:$/,/^divergence:$/p' "$S781/out" | sed '1d;$d' | tr '\n' '|' | sed 's/|$//')"

# ---- scope-decision record write path ----------------------------------------
# `--bind-scope-decisions` is what makes a Phase-2 record usable at review time,
# and its idempotency is what keeps a resumed run from re-binding to a new PR.
# The undecodable fixtures are deliberately CHARSET-VALID (`[A-Za-z0-9+/=]*`), so
# they match `_SCOPE_DECISION_RE` and actually REACH `_unb64` — that is the guard
# under test. A charset-INVALID payload (`text=!!!!`) is rejected by the GRAMMAR
# and never reaches `_unb64` at all, so asserting on it would prove nothing about
# the decode guard; `charset-invalid-unmatched` pins that distinction so the two
# rejection paths can never be confused again.
#   /w== → valid base64 of 0xff, which is not valid UTF-8
#   QQ=  → incorrect padding
# The `rewritten` sibling covers `new_blob is not None and new_text is None` —
# the shape that would otherwise emit a HALF-decoded record.
assert_eq "#781: scope-decision helpers round-trip, fail closed, and bind idempotently" \
  "pending-covers-nothing=0 bound=1 rebind-idempotent=143 undecodable-nonutf8=0 undecodable-padding=0 undecodable-newtext=0 empty-text=0 empty-newtext=0 charset-invalid-unmatched=yes normalized=Criterion X" \
  "$(python3 - "$WP_PY" 2>"$S781/unb64err" <<'PY'
import importlib.util, sys
spec = importlib.util.spec_from_file_location('wp', sys.argv[1])
wp = importlib.util.module_from_spec(spec); spec.loader.exec_module(wp)
rec = wp._render_scope_decision('pending', 'deferred', '  Criterion   X (post-merge) ')
bound = wp._bind_scope_decisions(rec, 143)
rebound = wp._bind_scope_decisions(bound, 999)
nonutf8 = '<!-- devflow:scope-decision pr=143 kind=deferred text=/w== -->'
padding = '<!-- devflow:scope-decision pr=143 kind=deferred text=QQ= -->'
newtext = ('<!-- devflow:scope-decision pr=143 kind=rewritten '
           'text=Q3JpdGVyaW9uIEM= newtext=/w== -->')
charset_invalid = '<!-- devflow:scope-decision pr=143 kind=deferred text=!!!! -->'
# The EMPTY-payload half of the fail-closed drop path: the regex's payload class is
# `*`-quantified, so a truncated or hand-edited `text=` (or `newtext=`) MATCHES and
# decodes cleanly to `''` — it never reaches `_unb64`'s error arm, so the undecodable
# fixtures above cannot cover it. A record naming no criterion can cover none, and
# crediting it is exactly the vacuous-coverage shape `_acs_pr_identity_ok` forbids.
empty_text = '<!-- devflow:scope-decision pr=143 kind=deferred text= -->'
empty_newtext = ('<!-- devflow:scope-decision pr=143 kind=rewritten '
                 'text=Q3JpdGVyaW9uIEM= newtext= -->')
print(
    f"pending-covers-nothing={len(wp._parse_scope_decisions(rec, 143))} "
    f"bound={len(wp._parse_scope_decisions(bound, 143))} "
    f"rebind-idempotent={143 if wp._parse_scope_decisions(rebound, 143) else 0} "
    f"undecodable-nonutf8={len(wp._parse_scope_decisions(nonutf8, 143))} "
    f"undecodable-padding={len(wp._parse_scope_decisions(padding, 143))} "
    f"undecodable-newtext={len(wp._parse_scope_decisions(newtext, 143))} "
    f"empty-text={len(wp._parse_scope_decisions(empty_text, 143))} "
    f"empty-newtext={len(wp._parse_scope_decisions(empty_newtext, 143))} "
    "charset-invalid-unmatched="
    f"{'yes' if wp._SCOPE_DECISION_RE.search(charset_invalid) is None else 'no'} "
    f"normalized={wp._parse_scope_decisions(bound, 143)[0]['text']}"
)
PY
)"
# The count alone is weak: a `_unb64` that returned the raw blob instead of None
# would still drop some of these. The BREADCRUMB is the contract — each payload
# that REACHES the decoder must read as a corrupted record (3 reaching payloads).
assert_eq "#781: each undecodable payload emits the not-decodable-UTF-8 breadcrumb (never a silent drop)" \
  "3" "$(grep -c 'not decodable UTF-8 base64' "$S781/unb64err")"
assert_eq "#781: the undecodable breadcrumb names the specific failure (non-UTF-8 byte AND bad padding)" "yes" \
  "$(grep -q '0xff' "$S781/unb64err" && grep -q 'Incorrect padding' "$S781/unb64err" && echo yes || echo no)"
assert_eq "#781: an undecodable payload states it covers no criterion" "yes" \
  "$(grep -q 'it covers no criterion' "$S781/unb64err" && echo yes || echo no)"
# The EMPTY-payload drop is a DIFFERENT breadcrumb from the undecodable one (it never
# reaches `_unb64`), and it must NAME THE FIELD — a `newtext=` truncation and a `text=`
# truncation are different corruptions, and a shared generic message would leave the
# auditor unable to tell which half of a `rewritten` record was lost.
assert_eq "#781: an empty text= payload emits its own field-naming breadcrumb" "1" \
  "$(grep -c 'whose text= payload is empty' "$S781/unb64err")"
assert_eq "#781: an empty newtext= payload emits its own field-naming breadcrumb" "1" \
  "$(grep -c 'whose newtext= payload is empty' "$S781/unb64err")"
assert_eq "#781: the empty-payload breadcrumb also states it covers no criterion" "2" \
  "$(grep -c 'payload is empty; it covers no criterion' "$S781/unb64err")"
# The cross-run adoption residual is only OBSERVABLE if the bind count is actually
# emitted; without this the KNOWN LIMITATION's sole mitigation could be dropped silently.
assert_eq "#781: binding a pending record emits the adoption count naming the target PR" "yes" \
  "$(grep -q 'bound 1 pending scope-decision record(s) to pr=143' "$S781/unb64err" && echo yes || echo no)"
assert_eq "#781: the adoption breadcrumb names the earlier-run contamination it exists to surface" "yes" \
  "$(grep -q 'records left by an earlier run on this issue were adopted' "$S781/unb64err" && echo yes || echo no)"
# A malformed PR value or an empty criterion text is STRUCTURAL — no record is
# written at all, rather than one that silently covers the wrong row (or none).
assert_eq "#781: a malformed scope-decision PR value aborts structurally" "yes" \
  "$(python3 - "$WP_PY" <<'PY'
import argparse, importlib.util, sys
spec = importlib.util.spec_from_file_location('wp', sys.argv[1])
wp = importlib.util.module_from_spec(spec); spec.loader.exec_module(wp)
ok = []
for args in (argparse.Namespace(scope_decision_deferred=[('not-a-pr', 'X')], scope_decision_rewritten=[]),
             argparse.Namespace(scope_decision_deferred=[('143', '   ')], scope_decision_rewritten=[])):
    try:
        wp._render_scope_decisions(args); ok.append(False)
    except wp._UpdateError:
        ok.append(True)
print('yes' if all(ok) else 'no')
PY
)"

# ---- scope-decision records through the REAL `update` CLI ---------------------
# The assertions above call the helpers directly against hand-written fixtures, so
# nothing exercises the path a §2.2.5/§2.2.6 call actually takes: argparse → render
# → the ## Progress note-append → PATCH. A record written to the wrong section, or
# a rendered form the parser cannot read back, would leave every direct-call test
# green while the live run silently recorded nothing the reviewer can credit. This
# drives the write end-to-end and then reads it back with `_parse_scope_decisions`,
# closing the loop on the same body the CLI PATCHed.
S781U="$(mktemp -d)"
cat > "$S781U/gh" <<'STUB'
#!/usr/bin/env bash
# gh stub for workpad.py update: repo view, comment lookup, body fetch, PATCH
# (echoes the patched body so the test can read the written record back).
j="$*"
if [[ "$j" == *"repo view"* ]]; then echo "owner/repo"; exit 0; fi
if [[ "$j" == *"-X PATCH"* ]]; then
  for a in "$@"; do case "$a" in body=@*) cat "${a#body=@}";; esac; done
  exit 0
fi
if [[ "$j" == *"issues/comments/7"* ]]; then cat "$WP_BODY"; exit 0; fi
if [[ "$j" == *"issues/999/comments"* ]]; then echo '[{"id":7,"body":"<!-- devflow:workpad -->"}]'; exit 0; fi
echo '[]'
STUB
chmod +x "$S781U/gh"
cat > "$S781U/base.md" <<'WPMD'
<!-- devflow:workpad -->
# DevFlow Workpad — Issue #999

**Status:** 🚀 Implementing
**Last updated:** 2026-05-15T00:00:00Z

## Progress
- [ ] **Implement**

## Plan
- [x] Plan step one

## Acceptance Criteria
- [ ] Criterion A
- [ ] Criterion B

## Devflow Reflection
<details>
<summary>Devflow Reflection (click to expand)</summary>

</details>
WPMD
WP_BODY="$S781U/base.md" DEVFLOW_GH="$S781U/gh" python3 "$WP_PY" update 999 \
  --print-body \
  --note 'scope decision: this PR delivers A only' \
  --scope-decision-deferred pending 'Criterion B' \
  --scope-decision-rewritten pending 'Criterion A' 'Criterion A2' \
  >"$S781U/out" 2>"$S781U/err"
_c781u=$?
assert_eq "#781: an update writing scope-decision records exits 0" "0" "$_c781u"
# Placement: the records are ## Progress bullets, and they land AFTER the free-text
# --note bullet (human narrative, then machine record) — the order workpad.py's own
# note-append comment promises. Asserting on the SECTION and the ORDER is what a
# refactor moving them into ## Plan, or ahead of the notes, has to go RED on.
assert_eq "#781: both scope-decision records land in ## Progress, never another section" "2" \
  "$(sed -n '/^## Progress$/,/^## Plan$/p' "$S781U/out" | grep -c 'prflow:scope-decision')"
# Position-independent: reduce the Progress section's appended bullets to an ORDER
# WORD per bullet, so the assertion pins the sequence itself rather than absolute
# line numbers (which shift with any unrelated skeleton edit and would make this a
# brittle pin that fails for the wrong reason).
assert_eq "#781: the records append AFTER the free-text --note bullet (narrative, then record)" \
  "note record record" \
  "$(sed -n '/^## Progress$/,/^## Plan$/p' "$S781U/out" \
     | grep 'this PR delivers A only\|prflow:scope-decision' \
     | sed -e 's/.*prflow:scope-decision.*/record/' -e 's/.*delivers A only.*/note/' \
     | tr '\n' ' ' | sed 's/ $//')"
# Round-trip: the CLI-written records must be readable by the very parser the
# reviewer runs — and they are written `pr=pending`, so they cover NOTHING until
# Phase 3.1 binds them. Both halves matter: a `pending` record credited early is the
# unbound-record fail-open, and a bound record the parser cannot read is a silent loss.
assert_eq "#781: the CLI-written records read back as pending-covers-nothing, then bind and parse" \
  "pending=0 bound=2 kinds=deferred,rewritten texts=Criterion B|Criterion A->Criterion A2" \
  "$(python3 - "$WP_PY" "$S781U/out" <<'PY'
import importlib.util, sys
spec = importlib.util.spec_from_file_location('wp', sys.argv[1])
wp = importlib.util.module_from_spec(spec); spec.loader.exec_module(wp)
body = open(sys.argv[2]).read()
bound = wp._bind_scope_decisions(body, 143)
recs = wp._parse_scope_decisions(bound, 143)
kinds = ','.join(r['kind'] for r in recs)
texts = '|'.join(r['text'] + (f"->{r['new_text']}" if r['new_text'] else '') for r in recs)
print(f"pending={len(wp._parse_scope_decisions(body, 143))} bound={len(recs)} "
      f"kinds={kinds} texts={texts}")
PY
)"

# The extractor must read the IMPLEMENT workpad marker and expose no channel
# through which /devflow:review's own `devflow:review-progress` marker could
# reach it — so neither acs subcommand accepts --marker.
assert_eq "#781: neither acs subcommand exposes a --marker override" "yes" \
  "$(python3 "$WP_PY" acs 1 --marker x >/dev/null 2>&1; _a=$?; \
     python3 "$WP_PY" acs-resolve 1 --pr 1 --marker x >/dev/null 2>&1; _b=$?; \
     [ "$_a" = 2 ] && [ "$_b" = 2 ] && echo yes || echo no)"

# The parsing rules are SINGLE-SOURCED: both helpers import them, so a rule
# change lands in one place and the mirror can never disagree with the read-back.
assert_eq "#781: parse-acs.py and workpad.py both import the shared section_parse module" "yes" \
  "$(grep -q 'from section_parse import' "$LIB/../scripts/parse-acs.py" \
     && grep -q 'from section_parse import' "$WP_PY" && echo yes || echo no)"
assert_eq "#781: parse-acs.py no longer carries its own copy of the section-extraction rule" "yes" \
  "$(grep -q 'def _extract_section' "$LIB/../scripts/parse-acs.py" && echo no || echo yes)"

# workpad.py is deployed STANDALONE in two places that copy it without its
# siblings — the Stop-hook trusted-copy closure and this suite's own guard
# sandboxes — and `status`/`id`/`update` need nothing from section_parse. A hard
# module-level import took every one of those down with a ModuleNotFoundError, so
# the import is optional and only the surfaces that need it fail, loudly.
S781X="$(mktemp -d)"; mkdir -p "$S781X/scripts"
cp "$WP_PY" "$S781X/scripts/workpad.py"
assert_eq "#781: workpad.py still loads with section_parse.py ABSENT (standalone deployment)" "yes" \
  "$(python3 "$S781X/scripts/workpad.py" --help >/dev/null 2>&1 && echo yes || echo no)"
python3 "$S781X/scripts/workpad.py" acs 1 >/dev/null 2>"$S781X/err"; _c781x=$?
assert_eq "#781: with section_parse.py absent, acs fails CLOSED (exit 3), never a silent empty read" "3" "$_c781x"
assert_eq "#781: the absent-sibling breadcrumb names section_parse.py specifically" "yes" \
  "$(grep -q 'section_parse.py' "$S781X/err" && echo yes || echo no)"
# The `acs` help text enumerates its non-zero exits, and the section_parse-absent
# arm above is a THIRD exit-3 path the module and acs-resolve docstrings document
# but the help omitted — a user-facing contract sentence that was incomplete
# against the shipped behavior the two asserts above drive. Pinned on the RENDERED
# `--help` output, never a source grep: the help string is assembled from adjacent
# wrapped literals, so it lives on no single line (the #375 wrapped-literal rule).
# Rendered from the TOP-LEVEL --help, where argparse prints a subparser's `help=`
# string (the subcommand's own --help prints its `description`, which this parser
# does not set). Whitespace is collapsed because argparse re-wraps to the terminal
# width, and that wrapping is also why the pinned phrase is kept short.
assert_eq "#781: the acs --help exit contract names the section_parse-absent exit-3 path" "yes" \
  "$(COLUMNS=400 python3 "$WP_PY" --help 2>/dev/null | tr -s '[:space:]' ' ' \
     | grep -q 'exit 3 on a gh read failure or when scripts/section_parse.py was not deployed beside workpad.py' \
     && echo yes || echo no)"
rm -rf "$S781X"
rm -rf "$S781"

# ---- class-closing absence guard over the $ARGUMENTS -> $PR_NUMBER re-anchoring
# This PR re-anchored every command and gate in the review engine off the raw
# `$ARGUMENTS` string onto the parsed `$PR_NUMBER`. Only a handful of the
# re-anchored consumers carry an individual pin, so a revert of any UNPINNED one
# (a `gh pr review $ARGUMENTS` verdict row, a `gh pr view $ARGUMENTS` gate) would
# reintroduce the exact defect this PR closes while the suite stayed green.
# One absence assertion closes the whole class instead of pinning consumers
# one at a time.
#
# Scoped to FENCED command blocks, which is where an interpolation is executed.
# The surrounding PROSE deliberately still says `$ARGUMENTS` — every occurrence is
# the rule itself ("never the raw `$ARGUMENTS` string") or the two skill roots'
# `**Input:**` parse instruction — so a whole-file grep would be RED on the very
# sentences that state the contract, and could only be made green by deleting them.
assert_eq "#781: no fenced command in the review engine interpolates the raw \$ARGUMENTS" "none" \
  "$(python3 - "$LIB/../skills/review/SKILL.md" \
       "$LIB/../skills/review-and-fix/SKILL.md" \
       "$LIB"/../skills/review/phases/*.md \
       "$LIB"/../skills/review-and-fix/references/*.md <<'PY'
import sys, pathlib
hits = []
for p in sys.argv[1:]:
    infence = False
    for n, line in enumerate(pathlib.Path(p).read_text(encoding='utf-8').splitlines(), 1):
        if line.lstrip().startswith('```'):
            infence = not infence
            continue
        if infence and '$ARGUMENTS' in line:
            hits.append(f'{pathlib.Path(p).name}:{n}')
print('|'.join(hits) or 'none')
PY
)"

# Defect restored: the issue number is derived from the PR body / branch name even
# when the caller supplied one, so a caller-supplied --issue is compared against a
# derivation instead of suppressing it — and a PR whose closes-reference was dropped
# still resolves nothing.

# Defect restored: the engine reads requirements off the issue body again, so a run
# that narrowed (2.2.5), rewrote (2.2.6) or retagged (3.4) its criteria is judged
# against the superseded set — a REJECT for descoped work.

# Defect restored: the blind 200-line cap applies to the criteria too, so on a long
# body — DevFlow's own house style puts Background and Evidence ahead of the criteria
# — the whole section is dropped and compliance runs against zero criteria.

# Defect restored: `--pr` is passed UNCONDITIONALLY, so a current-branch run (empty
# $PR_NUMBER) emits `--pr ''` — argparse rejects the empty value for a type=int flag
# and exits 2, which the fence's generic rc≠0 arm absorbs into a warning, losing the
# acceptance criteria entirely (observed live on a current-branch run).

# Defect restored: the current-branch arm passes the flag anyway, so the arm that
# exists precisely to OMIT `--pr` re-introduces the empty-value argparse exit 2.

# Defect restored: the criteria reach the merge-gating judge carrying their tick
# column — a specification pre-annotated by the party being judged, and (per the
# shadow reference) a smuggled fix decision.

# Defect restored: a gh transport blip and a legitimately criteria-less workpad
# collapse onto one report line, so a failed read presents as a normal issue-body
# resolution and a run whose mirroring silently failed reads like an ordinary
# non-implement PR.
# Defect restored: a refusal arm (non-numeric issue, absent/unreadable workpad.py,
# any rc-nonzero, a classifier denial) leaves no source token, so Phase 4 collapses the
# unestablished state onto `none` and reports that BOTH surfaces were checked and
# carried nothing - a fabricated measurement on the merge-gating report line.

# Defect restored: the headline demands a scope value unconditionally while
# not-applicable divergence supplies none, so a run that never read a workpad emits
# `scope unchanged` - an observed-fact claim beside a sentence saying nothing was read.

# Defect restored: divergence is compared over raw section text, so every implement
# PR reports divergence (the workpad carries post-merge tags and mirrored Test-Plan
# items the issue body does not) and the notice carries no signal.

# Defect restored: an audited scope decision is re-raised as a finding (or, worse,
# an unexplained drop is laundered as audited) because the check reads the
# agent-authored free-text note instead of the delimited record.

# Defect restored: a workpad-side addition is reported as divergence, so every
# implement PR raises the mirrored ## Test Plan items as findings.

# Defect restored: a run that resolved an issue but no criteria reports the
# compliance check as SKIPPED rather than as a gap, so the absence is invisible.

# Defect restored: the final-pass reviewer gets ONE Plan/Requirements slot again,
# whose winning arm at Phase 3.3 is the thin placeholder PR body — so the
# merge-gating judge reviews against a placeholder and the issue-body arm is
# unreachable.

# Defect restored: the Phase-4.4 verdict-post gate reads the RAW argument string, so
# `"123 --issue 456"` fails the is-a-PR-number test, Phase 4.4 never runs, and the
# merge-blocking `gh pr review --request-changes` post is silently skipped.
# Defect restored: the quoted extended string reaches dismiss-stale-rejections.sh as
# ONE argv element, matching no PR, so the stale-REJECT dismissal silently no-ops
# after an APPROVE and the PR stays wedged at CHANGES_REQUESTED.

# The three shadow-review reconciliations. Defect restored in each case: the shadow
# fan-out carries the criteria while a rule still bars them, so every shadow prompt
# is a non-permitted composition, records a prompt_addenda entry, and can never
# return `shadow agreed, full coverage` — the only token clearing §3.3's re-review.

# Defect restored at ONE of the two coupled implement-side invocation sites: the
# engine is invoked with no issue number, so Phase 0.4 falls back to deriving one
# and the run's own criteria are never handed over. The re-review's text says it
# uses the "same args", so a single-site edit ships an inconsistency.

# Defect restored: a Phase-2 scope-decision record is never bound to the PR, so it
# still reads pr=pending at review time, covers nothing, and every audited
# narrowing is re-raised as an unexplained DROP finding.
# Defect restored: §3.4's retroactive (post-merge) retag changes AC text with no
# record, so the criterion it rewrote reaches the engine as an unexplained text
# change — and the retag runs before the post-push standalone review.
# Defect restored: the load-bearing assumption ships without its falsifier, so a
# future writer that changes membership or text without a record silently makes the
# whole comparand untrustworthy while every check still reads green.

# Defect restored: rank 1 gains a real producer with no sub-cap, so an issue
# carrying dozens of criteria consumes the whole 100-item cap and evicts the
# absolute_claim / dependency_interaction / test_mock_alignment items §1.1.5 itself
# calls the load-bearing signal.
# Defect restored: the criteria arrive as ordinary narrative, so the generator emits
# no item tagged issue_acceptance and the rank-1 category stays empty — the exact
# defect this issue names.

# The category enum lives in the agent definition, which is in NEITHER bundle.

# ── issue #356: 💥 Failed terminal workpad status + dead-run flips ─────────────
# A cloud run that dies (job failure/cancel/exhausted auto-resume) must stop its
# Status-bearing comment lying. Two flips, one vocabulary each:
#   - implement workpad → new canonical terminal word `Failed`, glyph 💥
#   - review progress comment → the skill's existing `❌ Review failed` state
# Coupled invariant: 💥 is mirrored across workpad.py's _STATUS_GLYPHS,
# fetch-pr-context.sh's glyph strip, and the docs; the `❌ Review failed` literal
# and the run-keyed marker are a coupled contract with skills/review/SKILL.md.
S356="$(mktemp -d)"
cat > "$S356/gh" <<'STUB'
#!/usr/bin/env bash
# Minimal gh stub for workpad.py (status/update) and flip-review-progress-failed.sh
# (id/body/patch). Comments-list returns the full WP_BODY so `status` (which reads
# the body straight from the list) and `id`/`update` (which then fetch it) both work.
j="$*"
if [[ "$j" == *"repo view"* ]]; then echo "owner/repo"; exit 0; fi
if [[ "$j" == *"-X PATCH"* ]]; then
  if [ -n "${WP_PATCH_FAIL:-}" ]; then echo "patch boom" >&2; exit 1; fi
  echo p >> "$WP_PATCHLOG"
  for a in "$@"; do case "$a" in body=@*) cat "${a#body=@}" | tee "${WP_PATCHBODY:-/dev/null}";; esac; done
  exit 0
fi
if [[ "$j" == *"issue comment"* ]]; then
  # workpad.py create -> `gh issue comment <n> --body-file <path>`. WP_CREATE_FAIL
  # forces the failure arm; otherwise record the composed body and print the URL
  # cmd_create parses the new comment id out of (issue #1154's create arm).
  if [ -n "${WP_CREATE_FAIL:-}" ]; then echo "create boom" >&2; exit 1; fi
  _next=
  for a in "$@"; do
    if [ -n "$_next" ]; then [ -n "${WP_CREATEBODY:-}" ] && cp "$a" "$WP_CREATEBODY"; _next=; fi
    [ "$a" = "--body-file" ] && _next=1
  done
  echo "https://github.com/owner/repo/pull/55#issuecomment-9001"
  exit 0
fi
if [[ "$j" == *"issues/comments/7"* ]]; then
  # WP_BODY_FAIL: the single-comment read fails (403/5xx) -> workpad.py body rc 1.
  if [ -n "${WP_BODY_FAIL:-}" ]; then echo "body boom" >&2; exit 1; fi
  cat "$WP_BODY"; exit 0
fi
if [[ "$j" == *"/comments"* ]]; then
  # WP_ID_FAIL: the comment-LIST read fails (rate limit/403/5xx) -> workpad.py id
  # rc 1. Distinct from WP_ABSENT (a clean scan finding nothing -> rc 2): the flip
  # helper must diagnose these differently, never calling a failed read "absent".
  if [ -n "${WP_ID_FAIL:-}" ]; then echo "list boom" >&2; exit 1; fi
  if [ -n "${WP_ABSENT:-}" ]; then echo '[]'; exit 0; fi
  printf '[{"id":7,"body":%s}]' "$(jq -Rs . < "$WP_BODY")"; exit 0
fi
echo '[]'
STUB
chmod +x "$S356/gh"

# Fixture: an interim (🚀 Implementing) workpad with Setup ticked, Implement not,
# and an unticked non-post-merge AC (to exercise the Complete-only-gate carve-out).
cat > "$S356/interim.md" <<'WPMD'
<!-- devflow:workpad -->
# DevFlow Workpad — Issue #888

**Status:** 🚀 Implementing
**Last updated:** 2026-07-09T00:00:00Z

## Progress
- [x] **Setup** — branch & workpad
- [ ] **Implement**

## Plan
- [ ] do the thing

## Acceptance Criteria
- [ ] AC one
WPMD
# A body already carrying the terminal 💥 Failed status (for status + idempotency).
sed 's/🚀 Implementing/💥 Failed/' "$S356/interim.md" > "$S356/failed.md"

run356() {  # <body-file> <args...> → prints exit code; leaves out/err/patchlog on disk.
  local body="$1"; shift
  : > "$S356/patchlog"
  WP_BODY="$body" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
    python3 "$WP_PY" update 888 --print-body "$@" >"$S356/out" 2>"$S356/err"
  echo $?
}

# AC: `workpad.py status` prints `failed 💥 Failed` exit 0 for a 💥 Failed body
# (issue #1025 widened the class vocabulary — 💥 is now the distinct `failed`
# class rather than the collapsed `terminal`).
_so="$(WP_BODY="$S356/failed.md" DEVFLOW_GH="$S356/gh" python3 "$WP_PY" status 888 2>/dev/null)"; _src=$?
assert_eq "#356: workpad.py status prints 'failed 💥 Failed' for a 💥 Failed body" "failed 💥 Failed" "$_so"
assert_eq "#356: workpad.py status exits 0 for a 💥 Failed body" "0" "$_src"

# AC: update --status Failed writes 💥 Failed and does NOT trip the Complete-only gate.
_c="$(run356 "$S356/interim.md" --status Failed)"
assert_eq "#356: update --status Failed succeeds (exit 0) even with an unticked non-post-merge AC" "0" "$_c"
assert_eq "#356: update --status Failed writes '**Status:** 💥 Failed'" "yes" \
  "$(grep -q '^\*\*Status:\*\* 💥 Failed$' "$S356/out" && echo yes || echo no)"
assert_eq "#356: update --status Failed PATCHed (Complete-only gate not tripped)" "yes" \
  "$([ -s "$S356/patchlog" ] && echo yes || echo no)"
# The three assertions above prove Failed BYPASSES the gate — but they would all stay
# GREEN if the gate were deleted outright. Pin that the gate is Complete-ONLY by also
# asserting the CONTRAST on the identical fixture: --status Complete over the same
# unticked non-post-merge AC must abort (non-zero, no PATCH). Without this row the
# carve-out pin asserts nothing about the gate's existence.
: > "$S356/patchlog"
_c="$(run356 "$S356/interim.md" --status Complete)"
assert_eq "#356: --status Complete on the SAME unticked-AC fixture aborts (gate is Complete-only)" "yes" \
  "$([ "$_c" = "0" ] && echo no || echo yes)"
assert_eq "#356: --status Complete on an unticked AC makes NO PATCH (structural abort)" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"

# AC: re-applying --status Failed to a 💥 Failed body is idempotent (single glyph).
_c="$(run356 "$S356/failed.md" --status Failed)"
assert_eq "#356: re-applying --status Failed stays exit 0" "0" "$_c"
assert_eq "#356: re-applying --status Failed yields one 💥, not '💥 💥'" "yes" \
  "$(grep -q '^\*\*Status:\*\* 💥 Failed$' "$S356/out" && ! grep -q '💥 💥' "$S356/out" && echo yes || echo no)"

# AC: Failed is absent from _STATUS_TO_PROGRESS_PHASE, so a --note nests under the
# most-recent-ticked phase (Setup here) — the same fallback Blocked uses.
_c="$(run356 "$S356/interim.md" --status Failed --note "died here")"
assert_eq "#356: --status Failed --note nests under the most-recent-ticked phase (Setup)" "yes" \
  "$(python3 -c "
t=open('$S356/out').read().splitlines()
si=[i for i,l in enumerate(t) if 'Setup' in l and l.startswith('- [')]
ii=[i for i,l in enumerate(t) if 'Implement' in l and l.startswith('- [')]
ni=[i for i,l in enumerate(t) if 'died here' in l]
print('yes' if si and ii and ni and si[0]<ni[0]<ii[0] else 'no')
")"

# Source pins: the 💥/🛑 vocabulary lives in workpad.py (single source of truth).
# The tuple ends in 🛑 (🛑 Cancelled, issue #498); 💥 is no longer the last element.
assert_eq "#356: workpad.py _STATUS_GLYPHS includes 💥 and 🛑 (extended tuple)" "yes" \
  "$(grep -q "💥.*🛑')" "$WP_PY" && echo yes || echo no)"
assert_eq "#356: workpad.py maps 'failed' → 💥 (write path) and leaves it out of _STATUS_TO_PROGRESS_PHASE" "yes" \
  "$(grep -q "return '💥'" "$WP_PY" && ! grep -q "'failed':" "$WP_PY" && echo yes || echo no)"

# ── flip-review-progress-failed.sh unit tests ─────────────────────────────────
FLIP_SH="$LIB/../scripts/flip-review-progress-failed.sh"
RMARK="<!-- devflow:review-progress run=RUNTEST-1 -->"
# Interim review-progress comment (🚀 Reviewing) — the flip candidate.
cat > "$S356/rev-interim.md" <<RMD
$RMARK
# Devflow Review — PR #55

**Status:** 🚀 Reviewing

## Blueprint
- [ ] step one
RMD
# Terminal review-progress comment (already ❌ Review failed) — must NOT be touched.
sed 's/🚀 Reviewing/❌ Review failed/' "$S356/rev-interim.md" > "$S356/rev-terminal.md"

# (flipped) 🚀 Reviewing → ❌ Review failed, cause line appended, PATCH made, exit 0.
: > "$S356/patchlog"; : > "$S356/patchbody"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" WP_PATCHBODY="$S356/patchbody" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 on a successful flip" "0" "$_fc"
# The stub records the patched body it received to WP_PATCHBODY.
assert_eq "#356 flip: rewrote the Status line to '❌ Review failed'" "yes" \
  "$(grep -q '^\*\*Status:\*\* ❌ Review failed$' "$S356/patchbody" && echo yes || echo no)"
assert_eq "#356 flip: the interim 🚀 Reviewing status is gone after the flip" "yes" \
  "$(grep -q '🚀 Reviewing' "$S356/patchbody" && echo no || echo yes)"
assert_eq "#356 flip: a one-line cause is appended" "yes" \
  "$(grep -q 'job died' "$S356/patchbody" && echo yes || echo no)"
assert_eq "#356 flip: breadcrumb names the 'flipped' arm" "yes" \
  "$(grep -qi 'flipped' "$S356/ferr" && echo yes || echo no)"
assert_eq "#356 flip: a PATCH was actually made" "yes" \
  "$([ -s "$S356/patchlog" ] && echo yes || echo no)"

# (already-terminal) a ❌ Review failed comment is left untouched, exit 0, no PATCH.
: > "$S356/patchlog"
WP_BODY="$S356/rev-terminal.md" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 on an already-terminal comment" "0" "$_fc"
assert_eq "#356 flip: makes NO PATCH on an already-terminal comment" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: breadcrumb names the already-terminal arm" "yes" \
  "$(grep -qi 'already terminal' "$S356/ferr" && echo yes || echo no)"

# (comment absent) no matching run-keyed marker → the #1154 CREATE arm: the run
# died before the engine's Phase 0.3.5 seed, so there is nothing to flip and the
# helper authors the terminal comment instead of returning. Still exit 0, still
# no PATCH (a create is not a patch). The create arm's full contract — the body
# shape, the marker on line 1, idempotency, and the create-failure arm — is
# driven in lib/test/modules/review-trigger-helpers.sh, which can stub `create`.
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" WP_ABSENT=1 DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 when no progress comment exists" "0" "$_fc"
assert_eq "#356 flip: clean-absence arm makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#1154 flip: a confirmed clean absence CREATES the terminal comment instead of no-opping" "yes" \
  "$(grep -q 'created comment #9001' "$S356/ferr" && ! grep -qi 'no-op' "$S356/ferr" && echo yes || echo no)"

# (patch failure) the PATCH itself fails → exit 0, failure breadcrumb.
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" WP_PATCH_FAIL=1 DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 even when the PATCH fails" "0" "$_fc"
assert_eq "#356 flip: patch-failure breadcrumb names the failure arm" "yes" \
  "$(grep -qi 'patch-failure' "$S356/ferr" && echo yes || echo no)"

# (id read failure) `workpad.py id` rc 1 (a gh-api/parse failure) is a READ failure,
# NOT "comment-absent" (rc 2). Misreporting a failed lookup as an absent comment
# sends an operator hunting for a comment that in fact exists, so the two arms
# carry distinct breadcrumbs. Both are still best-effort no-ops (exit 0, no PATCH).
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" WP_ID_FAIL=1 DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 when the comment lookup itself fails" "0" "$_fc"
assert_eq "#356 flip: id-read-failure arm makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: a failed lookup is diagnosed as a read failure, not 'comment-absent'" "yes" \
  "$(grep -qi 'read-failure' "$S356/ferr" && ! grep -qi 'comment-absent' "$S356/ferr" && echo yes || echo no)"
assert_eq "#356 flip: id-read-failure breadcrumb states absence was not established" "yes" \
  "$(grep -q 'absence was NOT established' "$S356/ferr" && echo yes || echo no)"
# Assert the CAUSE CONTENT, not just the arm name: a breadcrumb that names the arm but
# carries an empty `Cause:` delivers none of the diagnostic value it exists for. (The
# stub writes `list boom` to workpad.py's stderr; a short cause must survive the clamp
# — bash's `${c: -N}` yields EMPTY when the string is shorter than N.)
assert_eq "#356 flip: id-read-failure breadcrumb carries the underlying gh cause" "yes" \
  "$(grep -qi 'list boom' "$S356/ferr" && echo yes || echo no)"

# (body read failure) the comment id resolves but the body read fails → read-failure
# no-op, exit 0, no PATCH.
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" WP_BODY_FAIL=1 DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 when the body read fails" "0" "$_fc"
assert_eq "#356 flip: body-read-failure arm makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: body-read-failure breadcrumb names the read-failure arm" "yes" \
  "$(grep -qi 'could not read body' "$S356/ferr" && echo yes || echo no)"
assert_eq "#356 flip: body-read-failure breadcrumb carries the underlying gh cause" "yes" \
  "$(grep -qi 'body boom' "$S356/ferr" && echo yes || echo no)"

# (missing args) no pr number / no marker → usage no-op, exit 0, no PATCH.
: > "$S356/patchlog"
WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" "" "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 with a missing pr number" "0" "$_fc"
assert_eq "#356 flip: missing-args arm makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
# An empty PR and an empty MARKER are DIFFERENT no-op modes and must not share one
# breadcrumb: the empty-PR path is reachable in production (finalize_check passes a
# possibly-empty pr_number output), the empty-marker path is a caller bug.
assert_eq "#356 flip: empty-pr breadcrumb names the pr number specifically" "yes" \
  "$(grep -qi 'empty pr number' "$S356/ferr" && ! grep -qi 'empty marker' "$S356/ferr" && echo yes || echo no)"
: > "$S356/patchlog"
WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 with a missing marker" "0" "$_fc"
assert_eq "#356 flip: missing-marker arm makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: empty-marker breadcrumb names the marker specifically" "yes" \
  "$(grep -qi 'empty marker' "$S356/ferr" && ! grep -qi 'empty pr number' "$S356/ferr" && echo yes || echo no)"

# (NOSTATUS) the comment exists and the marker matches, but it carries no `**Status:**`
# line -> no flip, exit 0, no PATCH. This arm is reachable if the review skill's seed
# format ever drifts, so it must fail CLOSED (never PATCH a body it cannot parse).
cat > "$S356/rev-nostatus.md" <<RMD
$RMARK
# Devflow Review — PR #55

Status is missing entirely.
RMD
: > "$S356/patchlog"
WP_BODY="$S356/rev-nostatus.md" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 on a comment with no Status line" "0" "$_fc"
assert_eq "#356 flip: no-Status arm makes NO PATCH (fails closed)" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: no-Status breadcrumb names its own arm" "yes" \
  "$(grep -qi 'has no Status line' "$S356/ferr" && echo yes || echo no)"

# Coupled contract: the helper's interim test keys on a `**Status:** 🚀 Reviewing`
# line that skills/review/SKILL.md seeds. Pin the SEED SHAPE, not just the terminal
# literal — a seed drift to e.g. `**Status**:` would silently route every flip to the
# NOSTATUS no-op arm above while every other pin stayed green.
assert_pin_unique "#356 pin: skills/review/SKILL.md seeds the '**Status:** 🚀 Reviewing' line the helper matches" \
  '**Status:** 🚀 Reviewing' "$REVIEW_BUNDLE"

# (non-numeric pr) `workpad.py id` declares its issue arg type=int, so ARGPARSE also
# exits 2 on a usage error — the same rc cmd_id uses for "scanned cleanly, no match".
# The helper must refuse a non-numeric PR before the id call, so the rc-2 arm stays
# unambiguous and a malformed invocation is never reported as "comment-absent".
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$FLIP_SH" "not-a-number" "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 on a non-numeric pr number" "0" "$_fc"
assert_eq "#356 flip: non-numeric pr makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: a non-numeric pr is NOT reported as 'comment-absent'" "yes" \
  "$(grep -qi 'not numeric' "$S356/ferr" && ! grep -qi 'comment-absent' "$S356/ferr" && echo yes || echo no)"

# (missing workpad.py sibling) `python3` ALSO exits 2 when it cannot open the script —
# `can't open file … [Errno 2]` on a partial vendor copy, `[Errno 13]` on a mode-000 file
# — the same rc `cmd_id` uses for "scanned cleanly, no match". Without a screen, that
# interpreter-level rc 2 lands in the comment-absent arm and tells an operator the comment
# does not exist when the read never happened. Copy the helper WITHOUT its workpad.py
# sibling to drive the real deployment shape, and assert it takes a read-failure arm.
mkdir -p "$S356/lonely"
cp "$FLIP_SH" "$S356/lonely/flip-review-progress-failed.sh"
: > "$S356/patchlog"
WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
  bash "$S356/lonely/flip-review-progress-failed.sh" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
assert_eq "#356 flip: exits 0 when its workpad.py sibling is missing" "0" "$_fc"
assert_eq "#356 flip: a missing workpad.py sibling makes NO PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"
assert_eq "#356 flip: a missing workpad.py sibling is NOT reported as 'comment-absent'" "yes" \
  "$(! grep -qi 'comment-absent' "$S356/ferr" && echo yes || echo no)"
assert_eq "#356 flip: a missing workpad.py sibling states absence was NOT established" "yes" \
  "$(grep -q 'absence was NOT established' "$S356/ferr" && echo yes || echo no)"
# The helper screens this class TWICE — a readable-sibling precheck and an rc-2 + non-empty
# stderr discriminator — and either alone yields a read-failure arm. So asserting only the
# OUTCOME leaves both guards individually deletable with the suite still GREEN. Pin the
# PRECHECK specifically, by the breadcrumb only it emits: the discriminator's message names
# python3's exit, never "a partial vendor copy". Deleting the precheck alone now goes RED.
# (The precheck is the robust half: the discriminator no-ops when $WP_ERR could not be
# allocated, and relies on --marker always being explicit.)
assert_eq "#356 flip: the readable-sibling PRECHECK fired (not merely the rc-2 stderr discriminator)" "yes" \
  "$(grep -q 'missing or unreadable — a partial vendor copy?' "$S356/ferr" && echo yes || echo no)"
# An unreadable (mode-000) sibling is the same class and must take the same arm, not the
# comment-absent one. Skip under a uid that ignores the mode bit (e.g. root in a container).
cp "$WP_PY" "$S356/lonely/workpad.py"
chmod 000 "$S356/lonely/workpad.py"
if [ ! -r "$S356/lonely/workpad.py" ]; then
  : > "$S356/patchlog"
  WP_BODY="$S356/rev-interim.md" WP_PATCHLOG="$S356/patchlog" DEVFLOW_GH="$S356/gh" \
    bash "$S356/lonely/flip-review-progress-failed.sh" 55 "$RMARK" "job died" >/dev/null 2>"$S356/ferr"; _fc=$?
  assert_eq "#356 flip: exits 0 when its workpad.py sibling is unreadable" "0" "$_fc"
  assert_eq "#356 flip: an unreadable workpad.py sibling is NOT reported as 'comment-absent'" "yes" \
    "$(! grep -qi 'comment-absent' "$S356/ferr" && echo yes || echo no)"
else
  # Never skip SILENTLY: under a uid that ignores the mode bit (root in a container) the
  # two assertions above cannot run, and a quietly-lower assertion count is precisely the
  # unaudited coverage loss the rest of this block exists to catch.
  echo "  SKIP  #356 flip: unreadable-sibling arm (this uid ignores the mode bit; chmod 000 stayed readable)"
fi
chmod 644 "$S356/lonely/workpad.py" 2>/dev/null || true

# Helper contract pins: SPDX header + always-exit-0 + routes via workpad.py (no bare gh).
# ── #356: the two skill-side enumerations of the status vocabulary this issue extends ──
# `Failed`/💥 is a new member of workpad.py's CLOSED status model, so every skill body that
# enumerates that model must name it. These two sites are operative (an agent reads them at
# runtime), unpinned before this change, and were left stale by the first pass — pin them so
# a future glyph addition cannot silently desync them again.
assert_pin_unique "#356: implement SKILL's Status-glyph paragraph names the full canonical glyph set (incl. 💥 and 🛑)" \
  'the helper prepends the canonical glyph (🚀/🎉/👎/💥/🛑)' "$LIB/../skills/implement/SKILL.md"
assert_pin_unique "#356: retrospective SKILL enumerates the terminal workpad_final_status values (incl. Cancelled)" \
  '`Complete` / `Blocked` / `Failed` / `Cancelled`' "$LIB/../skills/retrospective/SKILL.md"

# #626 — Stage A surface pins. The two defined-skip emitters (interim, Cancelled)
# emit the top-level "skip" key
# (distinct from a genuine failure's "error"). These are prose pins over the
# agent-run Stage A skill (its behavior cannot be driven mechanically here).
assert_pin_unique "#626: Stage A interim skip emits the \"skip\" key" \
  '{"skip": "incomplete run — workpad_final_status is <status>; skipping"}' "$LIB/../skills/retrospective/SKILL.md"
assert_pin_unique "#626: Stage A Cancelled skip emits the \"skip\" key" \
  '{"skip": "operator-cancelled run — workpad_final_status is Cancelled; a deliberate stop, not a quality signal; skipping"}' "$LIB/../skills/retrospective/SKILL.md"
assert_pin_unique "#626: Stage A recognizes a defined skip by the \"skip\" key only, not error text" \
  'by the presence of the `"skip"` key' "$LIB/../skills/retrospective/SKILL.md"

assert_eq "#356 flip: helper carries the SPDX header" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$FLIP_SH" && echo yes || echo no)"
assert_eq "#356 flip: helper routes GitHub access through workpad.py (no bare gh invocation)" "yes" \
  "$(grep -q 'workpad.py' "$FLIP_SH" && ! grep -qE '(^|[^A-Za-z_.])gh (api|issue|pr|label|repo)' "$FLIP_SH" && echo yes || echo no)"
# Coupled contract with skills/review/SKILL.md (the agent-side fatal-abort rule):
# the `❌ Review failed` literal must match. Pin the SKILL side uniquely (a rename
# there goes RED); assert the helper carries the matching literal via grep_present.
assert_pin_unique "#356 flip: skills/review/SKILL.md carries the '❌ Review failed' literal the helper mirrors" \
  '❌ Review failed' "$REVIEW_BUNDLE"
assert_eq "#356 flip: helper carries the matching '❌ Review failed' literal" "yes" \
  "$(grep -qF '❌ Review failed' "$FLIP_SH" && echo yes || echo no)"

# ── Run-keyed MARKER shape: executable producer/consumer parity ────────────────
# The helper finds the comment with `workpad.py id --marker "$FLIP_MARKER"`. If the review
# seed helper's derived marker and the workflow's FLIP_MARKER ever drift apart, `id` returns rc 2,
# the helper takes its comment-absent no-op arm, exits 0 — and BOTH dead-run flips silently
# never fire. That is a fail-open in exactly the scenario the flip exists to cover, and
# the issue-1054 block in review-trigger-helpers goes RED for it: it executes the seed
# helper and a python3-extracted, exactly-once workflow expression under one fixed env,
# then compares the two produced strings byte-for-byte. The workflow literal remains
# pinned here because it is itself the dead-run lookup producer.
#
# Declared here rather than reused from the workflow-wiring block below: that block defines
# $DEVFLOW_YML further down, and this block must not depend on statement order.
# Issue #936 retired the second consumer: devflow-review.yml (the auto PR-triggered
# review tier's caller) was removed from the tree, so the cross-FILE identity check
# between the two workflow copies has no second operand and is gone with it. The
# producer↔consumer contract this block exists to protect is now helper runtime output
# against devflow.yml's rebuilt value, covered by the executable parity row named above.
M356_DEVFLOW_YML="$LIB/../.github/workflows/devflow.yml"
assert_pin_unique "#356 marker: devflow.yml rebuilds the identical run-keyed marker" \
  'FLIP_MARKER="<!-- prflow:review-progress run=${GITHUB_RUN_ID}-${GITHUB_RUN_ATTEMPT} -->"' "$M356_DEVFLOW_YML"
# The out-of-job review_finalize backstop (issue #1174) rebuilds the SAME run-keyed
# marker under a distinct variable name (RP_RUN_MARKER) so this uniqueness pin — and
# the #1054 module's FLIP_MARKER extraction — stays anchored to the in-job flip's
# sole FLIP_MARKER literal. Both must construct the byte-identical marker string, so
# a positional pin over that shared literal keeps the finalizer's copy honest.
assert_eq "#1174 marker: review_finalize also constructs the run-keyed review-progress marker" "1" \
  "$(grep -cF 'RP_RUN_MARKER="<!-- prflow:review-progress run=${GITHUB_RUN_ID}-${GITHUB_RUN_ATTEMPT} -->"' "$M356_DEVFLOW_YML" || true)"
# The former cross-FILE identity check compared the two workflow copies of FLIP_MARKER
# against each other. Issue #936 removed the second copy with devflow-review.yml, and no
# separate prefix assertion replaces it: the module's runtime equality is stronger than
# a source-substring comparison and the remaining pin protects the workflow extraction site.

# ── fetch-pr-context.sh glyph-strip pin (unit) ────────────────────────────────
assert_eq "#356: fetch-pr-context.sh strips the full Status glyph set (incl. 💥 and 🛑)" "yes" \
  "$(grep -q '🚀|🎉|👎|💥|🛑' "$LIB/fetch-pr-context.sh" && echo yes || echo no)"

# ── Static workflow-wiring pins (the repo's #232/#258 pattern) ─────────────────
IMPL_YML="$LIB/../.github/workflows/devflow-implement.yml"
DEVFLOW_YML="$LIB/../.github/workflows/devflow.yml"

# ────────────────────────────────────────────────────────────────────────────
echo "implement-profile head guard (#484)"
# ────────────────────────────────────────────────────────────────────────────
# Phase 3 runs the review engine INLINE in the implement context. This guard audits
# every fenced head in skills/implement/**, skills/review*/**, and the dispatched
# skills/requesting-code-review/** final pass against the devflow-implement.yml baked
# --allowed-tools allowlist — NOT the review one. The scan deliberately over-approximates
# reachability: shared-source standalone-only fences (notably review Phase 4.4) remain in
# the audited set even though normal inline control flow stops after Phase 4.3. A head
# the inline flow reaches but the allowlist does not grant is silently refused (#363).
# This block fails when an audited fenced head
# is neither granted nor exactly withheld. A separate removal pin below protects
# the instruction that inline bare-workpad source shorthand expands before emission.
# The allowlist is assembled from
# the workflow's resolved `TOOLS='...'` allowlist line
# ALONE (tools-line mode; the implement region was hoisted into a `Resolve
# allowed-tools` step by issue #1170), never from .prflow/config.json — a consumer repo
# does not carry this repo's config extras, so a head reachable only via config is
# reported ungranted here (the fail-closed direction). WITHOUT --strict the extractor
# prints ungranted heads and exits 0 either way (issue #687: --strict is opt-in and NOT
# passed here), so the guard below deliberately keys on the printed output being EMPTY,
# never on the exit status. (A caller that DOES want to key on rc passes --strict, which
# makes `ungranted` exit 3 when it prints any head and 0 when it prints none.)
ECH="$LIB/test/extract-command-heads.py"
E363=
E484=
E484="$(mktemp -d)" || { echo "FAIL  #484: mktemp -d failed"; exit 1; }
_suite_tmp_dir "$E484"

# Heads deliberately left ungranted on the implement profile, each with a rationale:
#   gh pr checkout — the inline engine is already on the branch; checking out a PR
#     head would move the tree under Phase 3's fix loop and Phase 4's doc pass.
#   git rev-list — the Phase 1 behind-by capture is refused and degrades gracefully;
#     granting this head alone would not make that capture executable, and under any
#     depth-limited checkout its count can be plausible-but-wrong across the graft
#     boundary (this workflow's own checkout is full-history since #1219, but the
#     rationale is not conditioned on that — a consumer's installed copy may be older).
#   mktemp — invoked only from leading VAR=$(…) capture shapes the matcher refuses
#     regardless of a head grant; granting it would be a no-op greening the guard
#     on a still-denied path.
WITHHELD_IMPL=$'gh pr checkout\ngit rev-list\nmktemp'
# Shell builtins + extractor parse artifacts (leaked case-arm fragments) emitted
# alongside real heads. EXACT-match only (grep -xF): a head that merely begins with
# a suppressed entry (set-something.sh) is still reported ungranted.
SUPPRESS_IMPL=$'true\nset\nsetopt\nclaude/issue-*\nissue-*)\nnon-bug}'

# True iff HEAD is an EXACT member of the suppression or withheld set (grep -xF:
# fixed-string, whole-line; never a prefix match).
_impl_suppressed() {  # <head> -> 0 if suppressed/withheld, 1 otherwise
  { printf '%s\n' "$SUPPRESS_IMPL"; printf '%s\n' "$WITHHELD_IMPL"; } | grep -qxF "$1"
}

# Real ungranted heads from one skill file: extractor output minus suppressed/withheld.
_impl_ungranted() {  # <skill-file> <allowlist> <mode>
  local h output
  if ! output="$(python3 "$ECH" ungranted "$1" "$2" "$3" 2>"$E484/err")"; then
    printf '%s\n' '__extractor_error__'
    return 0
  fi
  [ -n "$output" ] || return 0
  printf '%s\n' "$output" \
    | while IFS= read -r h; do _impl_suppressed "$h" || printf '%s\n' "$h"; done
}

# Manual review-and-fix runs under devflow.yml, where gh pr checkout must be a
# real grant. Filter parser artifacts only: the implement profile's deliberately
# withheld heads are not exemptions on this separate profile.
_manual_ungranted() {  # <skill-file> <allowlist> <mode>
  local h output
  if ! output="$(python3 "$ECH" ungranted "$1" "$2" "$3" 2>"$E484/err")"; then
    printf '%s\n' '__extractor_error__'
    return 0
  fi
  [ -n "$output" ] || return 0
  printf '%s\n' "$output" \
    | while IFS= read -r h; do
        printf '%s\n' "$SUPPRESS_IMPL" | grep -qxF "$h" || printf '%s\n' "$h"
      done
}

# AC: a Bash(...) spec cited only in a YAML comment is NOT a grant — tools-line
# scopes to the resolved TOOLS='...' line, so the cited spec is unreachable. This
# is the fail-OPEN shape (a whole-file parse reading a comment as a grant) the guard
# exists to eliminate.
printf '%s\n' '```bash' 'make build' '```' > "$E484/cited.md"
{ printf '%s\n' 'steps:' '  - run: |' '      # Emits ",Bash(make:*),"' "      TOOLS='Read, Bash(echo:*)'"; } > "$E484/cited.yml"
assert_eq "#484 a Bash(...) spec cited in a YAML comment is not a grant (tools-line scopes to the TOOLS line)" \
  "make" "$(python3 "$ECH" ungranted "$E484/cited.md" "$E484/cited.yml" tools-line)"

# AC: an absent/unreadable workflow is a FAILURE, not zero findings (fail-closed —
# never the empty allowlist the default mode would silently yield).
assert_eq "#484 an absent workflow file is reported, not read as zero findings (fail-closed)" "yes" \
  "$(python3 "$ECH" ungranted "$E484/cited.md" "$E484/does-not-exist.yml" tools-line >/dev/null 2>&1 && echo no || echo yes)"

printf '%s\n' 'name: marker-free workflow' > "$E484/no-marker.yml"
assert_eq "#484 a readable workflow with no TOOLS='...' line fails closed" \
  "__extractor_error__" "$(_impl_ungranted "$E484/cited.md" "$E484/no-marker.yml" tools-line)"

# Malformed-but-present workflows must also make the contract guard visibly RED.
# A duplicate TOOLS='...' line is the fail-open vector tools-line refuses: a later
# widened copy would win at runtime while a first-match parse audited the canonical
# leading one.
{ printf '%s\n' "  TOOLS='Read'" "  TOOLS='Write'"; } > "$E484/duplicate-marker.yml"
assert_eq "#484 duplicate TOOLS='...' lines fail the implement contract guard closed" \
  "__extractor_error__" "$(_impl_ungranted "$E484/cited.md" "$E484/duplicate-marker.yml" tools-line)"
assert_eq "#484 an unknown allowlist parse mode fails closed instead of scanning the whole file" \
  "yes" "$(python3 "$ECH" ungranted "$E484/cited.md" "$E484/cited.yml" misspelled-mode >/dev/null 2>&1 && echo no || echo yes)"

# AC: a head that merely begins with a suppressed builtin survives (exact, not prefix).
printf '%s\n' '```bash' 'set-something.sh --x' '```' > "$E484/prefix.md"
assert_eq "#484 set-something.sh survives the suppression list (exact-match, not prefix)" \
  "set-something.sh" "$(python3 "$ECH" ungranted "$E484/prefix.md" "$E484/cited.yml" tools-line)"

# AC: the withheld list is exactly {gh pr checkout, git rev-list, mktemp} — it cannot
# silently grow into a suppression that hollows the guard out.
assert_eq "#484 withheld list is exactly gh pr checkout, git rev-list, mktemp" \
  "gh pr checkout git rev-list mktemp" "$(printf '%s\n' "$WITHHELD_IMPL" | sort | tr '\n' ' ' | sed 's/ *$//')"

# AC: the contract — zero ungranted real heads across the whole implement-executed
# surface (implement + the review engines Phase 3 runs inline, including the
# dispatched requesting-code-review final pass). Derive this roster
# recursively so a newly-added phase/reference cannot sit outside a frozen list
# while the guard still claims those recursive roots as coverage.
# A failed/empty find becomes a sentinel path, which `_impl_ungranted` turns into
# `__extractor_error__`; roster discovery can never masquerade as zero heads.
if ! _impl_files="$(find "$LIB/../skills/implement" "$LIB/../skills"/review* "$LIB/../skills/requesting-code-review" "$LIB/../skills/receiving-code-review" -type f -name '*.md' -print 2>"$E484/roster.err")" \
   || [ -z "$_impl_files" ]; then  # tree-walk-ok: every operand is scoped to skills/ (implement, review*, requesting-code-review, receiving-code-review), which no worktree lives under
  _impl_files="$E484/__roster_error__"
fi
assert_eq "#484 recursive roster includes nested implement phase files" "yes" \
  "$(printf '%s\n' "$_impl_files" | grep -qxF "$LIB/../skills/implement/phases/phase-4-documentation.md" && echo yes || echo no)"
assert_eq "#484 recursive roster includes the dispatched requesting-code-review skill" "yes" \
  "$(printf '%s\n' "$_impl_files" | grep -qxF "$LIB/../skills/requesting-code-review/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: roster membership assertion is scoped to the extractor input
# #539 shadow (pr-test-analyzer): pin a review-and-fix references member too — a future
# tightening of the find pattern (e.g. review* -> review) would silently drop all the
# references from the implement-profile head audit while the two pins above stay green.
assert_eq "#539 recursive roster includes the review-and-fix step references" "yes" \
  "$(printf '%s\n' "$_impl_files" | grep -qxF "$LIB/../skills/review-and-fix/references/loop-control.md" && echo yes || echo no)"  # raw-guard-ok: roster membership assertion is scoped to the extractor input
# #550: receiving-code-review now runs the completion-evidence check via the portable
# anchor, so its fenced heads must be audited on the implement profile too. Dropping
# The membership assertion below verifies that the recursive roster includes it.
assert_eq "#550 recursive roster includes the receiving-code-review skill" "yes" \
  "$(printf '%s\n' "$_impl_files" | grep -qxF "$LIB/../skills/receiving-code-review/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: roster membership assertion is scoped to the extractor input
assert_eq "#484 every implement-tier head is granted or withheld (zero ungranted real heads)" "" \
  "$(for f in $_impl_files; do _impl_ungranted "$f" "$IMPL_YML" tools-line; done | sort -u | tr '\n' ' ' | sed 's/ *$//')"

# AC (#484 + #530): the WHOLE review-and-fix bundle — thin root + every references/*.md —
# against devflow.yml's hoisted TOOLS. $MAXI_SKILL is the root+references concatenation
# (see its definition), so this is now a whole-bundle head scan on the manual tier rather
# than the pre-#530 single-SKILL.md check. gh pr checkout is granted there (the manual
# /devflow:review-and-fix path checks out the PR head at Step 0.5, in
# references/loop-control.md — part of the scanned bundle), so every head
# any bundle file emits is granted or suppressed.
assert_eq "#484/#530 every review-and-fix bundle (root+references) head is granted by devflow.yml TOOLS" "" \
  "$(_manual_ungranted "$MAXI_SKILL" "$LIB/../.github/workflows/devflow.yml" tools-line | sort -u | tr '\n' ' ' | sed 's/ *$//')"
sed -E 's/, Bash\(gh pr checkout:\*\)//' "$LIB/../.github/workflows/devflow.yml" > "$E484/manual-no-checkout.yml"
assert_eq "#484 manual gh pr checkout grant is removal-proof" "yes" \
  "$(_manual_ungranted "$MAXI_SKILL" "$E484/manual-no-checkout.yml" tools-line | grep -qxF 'gh pr checkout' && echo yes || echo no)"

# AC (#1153): git check-ignore is granted on NO profile, and a review-and-fix run
# (Actions run 29854795625) improvised one when the fence-less ignore-coverage prose asked
# it to evaluate .prflow/tmp/ coverage. That prose is removed (this issue's AC3); this guard
# is the RED-on-reintroduction backstop, proved by PLANTING the exact denied command as a
# bundle fence and asserting the whole-bundle head scan reports it ungranted against
# devflow.yml's TOOLS. It covers the "emits" (fenced command head) shape only; an
# inline-backtick/table prose `git check-ignore` is out of the head extractor's
# bash-fence-only reach — a residual stated (not silently closed) in the issue-1153 workpad.
{ cat "$MAXI_SKILL"; printf '\n```bash\ngit check-ignore -q .prflow/tmp/\n```\n'; } > "$E484/raf-plus-checkignore.md"
assert_eq "#1153 a reintroduced git check-ignore head anywhere in the review-and-fix bundle is reported ungranted" "yes" \
  "$(_manual_ungranted "$E484/raf-plus-checkignore.md" "$LIB/../.github/workflows/devflow.yml" tools-line | grep -qxF 'git check-ignore' && echo yes || echo no)"
# Positive control: the unmodified bundle emits no such head, so the planted fence is the
# sole source of the report above — the guard is not vacuously green.
# This control is not self-guarding: an extractor error emitting e.g. __extractor_error__
# would also yield "no" here. The anti-vacuity weight is carried by the PLANTED assertion
# immediately above, which runs the identical extractor and requires "yes" — so an
# extractor error fails there, loudly, rather than passing silently as a green control.
assert_eq "#1153 the unmodified review-and-fix bundle emits no git check-ignore head" "no" \
  "$(_manual_ungranted "$MAXI_SKILL" "$LIB/../.github/workflows/devflow.yml" tools-line | grep -qxF 'git check-ignore' && echo yes || echo no)"

# Skill-level recovery contracts: unit tests prove the helper behavior, while
# these removal pins prove the orchestrator still requests a failure signal and
# preserves the exact pre-workpad refusal note.
E484_IMPL_SKILL="$LIB/../skills/implement/SKILL.md"
assert_pin_unique "#484 outcome reaction requests a reportable helper failure" \
  '--reaction "$REACTION" --report-failure' "$E484_IMPL_SKILL"
assert_pin_unique "#484 prompt-extension refusal preserves the exact pending note" \
  'load-prompt-extension.sh was refused by the matcher; the consumer prompt extension could not be loaded' "$E484_IMPL_SKILL"

E484_FINAL_PASS="$LIB/../skills/requesting-code-review/code-reviewer.md"
assert_pin_unique "#484 final-pass reviewer does not emit unavailable worktree/mktemp recovery commands" \
  'Do not attempt `git worktree add`, `mktemp`, or a mutation/half-revert' "$E484_FINAL_PASS"
assert_pin_unique "#484 final-pass reviewer reports a mutation-evidence limitation instead of silently retrying" \
  'report the verification limitation to the orchestrator instead' "$E484_FINAL_PASS"
E484_PHASE4="$LIB/../skills/implement/phases/phase-4-documentation.md"
for docs_key in .docs.internal .docs.external .docs.release_notes_file .docs.changelog_file; do
  assert_pin_unique "#484 docs staging reads configured key $docs_key" \
    "config-get.sh $docs_key" "$E484_PHASE4"
done

# Disposable-mutant regression: drop the grant TOKEN (not the whole TOOLS line) from a
# scratch workflow and confirm the extractor reports the stale-prose-lint.py head
# ungranted. The token is removed in place (the region is a single TOOLS='...' line since
# issue #1170, so a line-delete would drop the entire allowlist and fail closed instead).
sed -E 's/, Bash\(\.prflow\/vendor\/prflow\/scripts\/stale-prose-lint\.py:\*\)//' "$IMPL_YML" > "$E484/impl-no-spl.yml"
assert_eq "#484 guard-behavior: with the stale-prose-lint.py grant removed the extractor reports it ungranted over review/SKILL.md" \
  "yes" "$(python3 "$ECH" ungranted "$REVIEW_BUNDLE" "$E484/impl-no-spl.yml" tools-line 2>/dev/null | grep -qF 'stale-prose-lint.py' && echo yes || echo no)"

# ── #1354 command call sites in .prflow/prompt-extensions/** ───────────────────
# extract-command-heads.py / extract-command-shapes.py are the desk gates that turn an
# ungranted head or a matcher-denied shape RED before it ever reaches a cloud run. Their
# audited population was the skills bundles only. But a live prompt extension is appended
# to the SAME agent prompt and can invoke the same helpers, so an ungranted head or a
# denied shape authored in an extension was caught by nothing at the desk — and, because
# the matcher refuses such a command silently (no output, no error, no non-zero exit), it
# was invisible in the run too. This block widens the audited population to the repo's live
# tracked prompt extensions, each paired with the allowlist(s)/profile of the tier(s) that
# load it. Only lib/test/run.sh changes: the gate is driven entirely through the existing
# extractors' `extract-command-heads.py ungranted`/`heads` and `extract-command-shapes.py
# --profile` subcommands (no new extractor). Consumer-authored extensions are out of scope — this
# repo's suite scans this repo's tree (a consumer-runnable gate is a separate deliverable).
E1354=
E1354="$(mktemp -d)" || { echo "FAIL  #1354: mktemp -d failed"; exit 1; }
_suite_tmp_dir "$E1354"
ECS1354="$LIB/test/extract-command-shapes.py"
CFG1354="$LIB/../.prflow/config.json"

# The head grant is a UNION of the tier's baked workflow allowlist (parsed via `tools-line`)
# and its .prflow/config.json `allowed_tools` array (AC2): a head is granted-by-union iff
# granted by EITHER source, so it is ungranted-by-union iff ungranted by BOTH — computed in
# _e1354_union_ungranted below as the set INTERSECTION of the two per-source `ungranted`
# reports (each tier's workflow+config row is co-located in that function's `case`). This
# union is load-bearing: the live fences invoke lib/test/regenerate-artifacts.py, whose grant
# exists ONLY in .prflow/config.json (the implement and command allowed_tools arrays), never in
# a baked workflow literal — a workflow-only check would go RED on a correctly-granted call site.
# The shape profile is just the tier name (extract-command-shapes.py --profile implement|command|review).

# The extension→tier mapping — the SINGLE enumerated table (AC4), reconciled against the
# on-disk set BOTH ways below. Every live tracked .prflow/prompt-extensions/*.md file has
# exactly one row; each row lists the tier(s) whose allowlist(s)/profile its fences are
# checked against. implement.md loads on the implement tier; review.md on the command tier
# and (auto-review) the review profile; the remaining docs / create-issue extensions on the
# command tier — the general first-party command allowlist, the conservative choice for an
# extension with no dedicated cloud dispatch, so a future fence is audited against real
# grants rather than escaping the gate. A new extension added without a row here fails the
# reconciliation, never silently shrinking the gate.
#
# review.md, review-and-fix.md and receiving-code-review.md additionally carry the IMPLEMENT
# tier because the review engine is dispatched INLINE inside the implement job: implement
# Phase 3.3 (skills/implement/phases/phase-3-review.md) runs /prflow:review-and-fix in the
# implement run's own context under devflow-implement.yml's baked --allowed-tools, and
# skills/review-and-fix/SKILL.md loads review-and-fix.md + receiving-code-review.md while
# skills/review/SKILL.md loads review.md. Checking these three against the command union
# alone left a real hole: a helper granted in .prflow.allowed_tools but dropped from
# .prflow_implement.allowed_tools stayed green here while every implement run's inline fix
# loop hit a fence the matcher refuses silently.
_E1354_MAP="implement.md:implement
review.md:command review implement
review-and-fix.md:command implement
receiving-code-review.md:command implement
create-issue.md:command
pr-description.md:command implement
docs-bootstrap-external.md:command
docs-sync-external.md:command implement
docs-sync-internal.md:command implement"

# Union-ungranted heads for one extension file under one tier, against a given config JSON
# (parameterized so the T2 fixture can drop a grant and prove the config channel is really
# consulted). Emits the intersection of the two per-source `ungranted` reports, or the
# sentinel __extractor_error__ if either extractor run fails — fail-closed, so a parse
# failure is never read as "all granted".
_e1354_union_ungranted() {  # <ext-file> <tier> <config-json>
  local ext="$1" tier="$2" cfgjson="$3" wf cfgkey a b
  local cfgspecs="$E1354/cfgspecs"
  # One `case` per tier keeps its (workflow allowlist, config key) row co-located.
  case "$tier" in
    implement) wf="$LIB/../.github/workflows/devflow-implement.yml"; cfgkey=".prflow_implement.allowed_tools" ;;
    command)   wf="$LIB/../.github/workflows/devflow.yml";           cfgkey=".prflow.allowed_tools" ;;
    review)    wf="$LIB/../.github/workflows/devflow-runner.yml";     cfgkey=".prflow_runner.allowed_tools" ;;
  esac
  # (KEY // []) so an absent/null array yields an empty allowlist, never a jq error.
  jq -r "( ${cfgkey} // [] )[]" "$cfgjson" > "$cfgspecs" 2>/dev/null || : > "$cfgspecs"
  if ! a="$(python3 "$ECH" ungranted "$ext" "$wf" tools-line 2>/dev/null)"; then
    printf '%s\n' '__extractor_error__'; return 0
  fi
  # Default mode over the isolated config array (no `tools-line`): every Bash(spec:*) rule
  # in the extracted array grants. The array holds only that tier's specs (a single jq key),
  # so the whole-file default mode reads no unrelated grant. A head is ungranted-by-union
  # iff ungranted by BOTH sources — the comm -12 intersection of the two `ungranted` reports.
  if ! b="$(python3 "$ECH" ungranted "$ext" "$cfgspecs" 2>/dev/null)"; then
    printf '%s\n' '__extractor_error__'; return 0
  fi
  local u
  u="$(comm -12 <(printf '%s\n' "$a" | sed '/^$/d' | sort -u) <(printf '%s\n' "$b" | sed '/^$/d' | sort -u))"
  [ -n "$u" ] || return 0
  # Tier-agnostic-fallback filter. An extension authored per the tier-agnostic invocation
  # procedure (issue #1256/#1350) emits the granted vendored literal
  # `.prflow/vendor/prflow/scripts/<n>` FIRST and then a bare repo-root `scripts/<n>` (or
  # `lib/<n>`) as the LOCAL-tier fallback arm — reached only on a `command not found` reading,
  # which never happens on a cloud tier where the vendored path is materialized and granted. So
  # a bare `scripts/<n>`/`lib/<n>` head is a false cloud exposure when the extension ALSO emits
  # its vendored counterpart AND the union GRANTS that counterpart (it is not itself ungranted).
  # Drop exactly those; a bare-ONLY head (no granted vendored counterpart in the head set) is
  # kept — fail-closed, so a genuinely ungranted helper still surfaces.
  # The pairing is FILE-scoped, not fence-scoped: a bare `scripts/X` anywhere in the extension
  # is suppressed when that file emits a granted `.prflow/vendor/prflow/scripts/X` anywhere
  # else in it, even from a different fence. That matches the #1256 tier-agnostic remedy (the
  # vendored literal and its bare fallback arm are one authored pair, not necessarily one
  # fence), so it is the intended scope rather than a looseness to tighten.
  local heads h vend
  heads="$(python3 "$ECH" heads "$ext" 2>/dev/null)"
  while IFS= read -r h; do
    [ -n "$h" ] || continue
    case "$h" in
      scripts/*|lib/*)
        vend=".prflow/vendor/prflow/$h"
        # vendored counterpart emitted by this extension AND not itself in the ungranted set
        # (i.e. granted) → a covered tier-agnostic fallback; suppress it.
        if printf '%s\n' "$heads" | grep -qxF "$vend" && ! printf '%s\n' "$u" | grep -qxF "$vend"; then
          continue
        fi
        ;;
    esac
    printf '%s\n' "$h"
  done <<EOF
$u
EOF
}

# On-disk population (AC6): the git INDEX via `git ls-files`, NO --others, so a sibling
# worktree under .claude/worktrees/ cannot change the result (issue #711). The `*.md`
# pathspec structurally excludes .md.example (AC7 — a path ending .example does not end .md).
_e1354_ondisk="$( cd "$LIB/.." && git ls-files '.prflow/prompt-extensions/*.md' )"

# Both-ways table↔disk reconciliation (AC4): a file with no row fails, a row with no file fails.
_e1354_table_names="$(printf '%s\n' "$_E1354_MAP" | sed 's/:.*//' | sort -u)"
_e1354_disk_names="$(printf '%s\n' "$_e1354_ondisk" | sed 's#.*/##' | sort -u)"
assert_eq "#1354 AC4: every on-disk prompt-extension has a mapping-table row" "" \
  "$(comm -23 <(printf '%s\n' "$_e1354_disk_names") <(printf '%s\n' "$_e1354_table_names") | sed '/^$/d' | tr '\n' ' ' | sed 's/ *$//')"
assert_eq "#1354 AC4: every mapping-table row names an on-disk prompt-extension" "" \
  "$(comm -13 <(printf '%s\n' "$_e1354_disk_names") <(printf '%s\n' "$_e1354_table_names") | sed '/^$/d' | tr '\n' ' ' | sed 's/ *$//')"
# T3 anti-vacuity: reconciling the REAL table against a disk set carrying a synthetic EXTRA
# file reports that file — proving the AC4 missing-row direction (comm -23) genuinely goes RED
# when an extension is added on disk without a table row, rather than being vacuously empty.
assert_eq "#1354 T3: an on-disk extension absent from the mapping table is reported RED (AC4 missing-row direction)" "unmapped-new.md" \
  "$(comm -23 <(printf '%s\n' "$_e1354_disk_names" 'unmapped-new.md' | sort -u) <(printf '%s\n' "$_e1354_table_names") | sed '/^$/d' | tr '\n' ' ' | sed 's/ *$//')"

# Head gate (AC1/AC2) + shape gate (AC3) over the live population, each extension under every
# tier its row names. T1: collect the live head set to assert it is non-empty (non-vacuous).
_e1354_head_report=""
_e1354_shape_report=""
_e1354_all_heads=""
while IFS= read -r _e1354_rel; do
  [ -n "$_e1354_rel" ] || continue
  _e1354_ext="$LIB/../$_e1354_rel"
  _e1354_bn="${_e1354_rel##*/}"
  _e1354_tiers="$(printf '%s\n' "$_E1354_MAP" | awk -F: -v b="$_e1354_bn" '$1==b{print $2}')"
  _e1354_all_heads+="$(python3 "$ECH" heads "$_e1354_ext" 2>/dev/null)"$'\n'
  for _e1354_tier in $_e1354_tiers; do
    _e1354_u="$(_e1354_union_ungranted "$_e1354_ext" "$_e1354_tier" "$CFG1354")"
    [ -n "$_e1354_u" ] && _e1354_head_report+="${_e1354_bn}[$_e1354_tier]: $(printf '%s' "$_e1354_u" | tr '\n' ',')"$'\n'
    _e1354_s="$(python3 "$ECS1354" --profile "$_e1354_tier" "$_e1354_ext" 2>&1)"
    [ -n "$_e1354_s" ] && _e1354_shape_report+="${_e1354_bn}[$_e1354_tier]: $(printf '%s' "$_e1354_s" | tr '\n' ',')"$'\n'
  done
done <<EOF
$_e1354_ondisk
EOF

assert_eq "#1354 AC1/AC2: every prompt-extension command head is granted by its tier(s)' allowlist union" "" \
  "$(printf '%s' "$_e1354_head_report" | sed '/^$/d' | tr '\n' ';' | sed 's/;*$//')"
assert_eq "#1354 AC3: every prompt-extension command shape is clean under its tier(s)' profile" "" \
  "$(printf '%s' "$_e1354_shape_report" | sed '/^$/d' | tr '\n' ';' | sed 's/;*$//')"
assert_eq "#1354 T1: the live prompt-extension head set is non-empty (the gate is not vacuously green)" "yes" \
  "$(printf '%s' "$_e1354_all_heads" | sed '/^$/d' | grep -q . && echo yes || echo no)"

# Tier-agnostic-fallback filter (positive + negative control). A helper granted ONLY as the
# vendored literal (prompt-surface-growth.py: in the workflow TOOLS, never as bare `scripts/`)
# lets us exercise the filter on the implement tier. Positive: a fixture emitting the vendored
# literal AND its bare fallback reports NOTHING (the covered fallback is suppressed — the cloud
# path uses the granted vendored form). Negative control: a fixture emitting ONLY the bare form
# still reports it (fail-closed — the filter never suppresses a bare head with no granted
# vendored counterpart).
printf '%s\n' '```bash' '.prflow/vendor/prflow/scripts/prompt-surface-growth.py --check' '```' \
  '```bash' 'scripts/prompt-surface-growth.py --check' '```' > "$E1354/fx-fallback.md"
assert_eq "#1354: a bare local-tier fallback whose granted vendored form the extension also emits is suppressed (not a false cloud finding)" "" \
  "$(_e1354_union_ungranted "$E1354/fx-fallback.md" implement "$CFG1354")"
printf '%s\n' '```bash' 'scripts/prompt-surface-growth.py --check' '```' > "$E1354/fx-bareonly.md"
assert_eq "#1354 negative control: a bare-only ungranted helper (no granted vendored counterpart) is still reported (filter fails closed)" "scripts/prompt-surface-growth.py" \
  "$(_e1354_union_ungranted "$E1354/fx-bareonly.md" implement "$CFG1354")"

# AC5 (head) anti-vacuity + negative control: an ungranted head in a fixture extension is
# reported; a fixture with only a granted head is not. Proves the head assertion path
# discriminates rather than always printing nothing.
printf '%s\n' '```bash' 'totally-not-a-granted-head --x' '```' > "$E1354/fx-ungranted.md"
assert_eq "#1354 AC5: a fixture extension's ungranted head is reported (command tier)" "totally-not-a-granted-head" \
  "$(_e1354_union_ungranted "$E1354/fx-ungranted.md" command "$CFG1354")"
printf '%s\n' '```bash' 'git status' '```' > "$E1354/fx-clean.md"
assert_eq "#1354 AC5 negative control: a fixture with only a granted head reports nothing" "" \
  "$(_e1354_union_ungranted "$E1354/fx-clean.md" command "$CFG1354")"
# The `review` tier's `case` arm (devflow-runner.yml + .prflow_runner.allowed_tools) is
# selected only for review.md, which today carries zero command heads — so drive that arm
# directly with a fixture pair so a wrong workflow/config selection in it cannot pass
# unnoticed: an ungranted head is reported, and a review-granted head (`gh pr diff`) is clean.
assert_eq "#1354 AC5: a fixture extension's ungranted head is reported (review tier)" "totally-not-a-granted-head" \
  "$(_e1354_union_ungranted "$E1354/fx-ungranted.md" review "$CFG1354")"
printf '%s\n' '```bash' 'gh pr diff 1' '```' > "$E1354/fx-review-clean.md"
assert_eq "#1354 AC5 negative control: a review-granted head reports nothing (review tier)" "" \
  "$(_e1354_union_ungranted "$E1354/fx-review-clean.md" review "$CFG1354")"

# AC5 (shape) anti-vacuity + negative control: a proven-denied shape (a leading `cd`, IR4/CR4)
# in a fixture extension is reported; a clean-shape fixture is not.
printf '%s\n' '```bash' 'cd .prflow/tmp && git status' '```' > "$E1354/fx-badshape.md"
assert_eq "#1354 AC5: a fixture extension's denied shape (leading cd) is reported (implement profile)" "yes" \
  "$(python3 "$ECS1354" --profile implement "$E1354/fx-badshape.md" 2>&1 | grep -q . && echo yes || echo no)"
assert_eq "#1354 AC5 negative control: a clean-shape fixture reports nothing (implement profile)" "" \
  "$(python3 "$ECS1354" --profile implement "$E1354/fx-clean.md" 2>&1)"
# The `review` profile uses a SEPARATE finder (find_violations / R1-R4) from the shared
# implement/command engine, and review.md IS scanned under it (its `command review` row), so
# exercise that finder's discrimination directly rather than only transitively — a leading `cd`
# is R2 under review — with the same clean control, so AC3 cannot pass vacuously for review.md.
assert_eq "#1354 AC5: a fixture extension's denied shape (leading cd) is reported (review profile)" "yes" \
  "$(python3 "$ECS1354" --profile review "$E1354/fx-badshape.md" 2>&1 | grep -q . && echo yes || echo no)"
assert_eq "#1354 AC5 negative control: a clean-shape fixture reports nothing (review profile)" "" \
  "$(python3 "$ECS1354" --profile review "$E1354/fx-clean.md" 2>&1)"

# T2/AC2: dropping the regenerate-artifacts.py grant from a fixture copy of the config turns
# implement.md's head union RED, proving the config array is really consulted (the grant
# exists in NO baked workflow literal, so the workflow-only check already reports it — the
# union clears it only because the config channel is unioned in).
jq 'del(.prflow_implement.allowed_tools[] | select(. == "Bash(lib/test/regenerate-artifacts.py:*)"))' "$CFG1354" > "$E1354/cfg-no-regen.json"
assert_eq "#1354 T2: removing the config grant reports implement.md's head ungranted (config channel is consulted)" "yes" \
  "$(_e1354_union_ungranted "$LIB/../.prflow/prompt-extensions/implement.md" implement "$E1354/cfg-no-regen.json" | grep -qF 'regenerate-artifacts.py' && echo yes || echo no)"
assert_eq "#1354 T2 positive control: with the real config, implement.md's head is granted by the union" "" \
  "$(_e1354_union_ungranted "$LIB/../.prflow/prompt-extensions/implement.md" implement "$CFG1354")"

# T4: a fence using the portable ${CLAUDE_SKILL_DIR:-…} anchor normalises to the vendored
# literal (extract-command-heads.py's shared _normalize) and is granted, proving the
# normalization transfers to this population rather than being a claim.
printf '%s\n' '```bash' '"${CLAUDE_SKILL_DIR:-/x}"/../../scripts/workpad.py id 1' '```' > "$E1354/fx-anchor.md"
# First prove the anchor fence actually PARSES to a normalised vendored-literal head, so the
# "granted" (empty-union) assertion below cannot pass merely because no head was extracted —
# closing T4's residual vacuity, mirroring T1's non-emptiness discipline.
assert_eq "#1354 T4: the anchor fence parses to a normalised vendored-literal head (non-vacuity guard)" ".prflow/vendor/prflow/scripts/workpad.py" \
  "$(python3 "$ECH" heads "$E1354/fx-anchor.md")"
assert_eq "#1354 T4: an anchor-spelled helper fence normalises to the vendored literal and is granted (implement tier)" "" \
  "$(_e1354_union_ungranted "$E1354/fx-anchor.md" implement "$CFG1354")"

# AC7: a tracked .md.example file is excluded from the *.md population — it IS in the index
# (git resolves it) yet is NOT in the scanned set. Proves the exclusion is real, not assumed.
assert_eq "#1354 AC7: a tracked .md.example is tracked yet excluded from the *.md population" "tracked-excluded" \
  "$( cd "$LIB/.." && { git ls-files --error-unmatch '.prflow/prompt-extensions/docs.md.example' >/dev/null 2>&1 \
        && ! git ls-files '.prflow/prompt-extensions/*.md' | grep -qxF '.prflow/prompt-extensions/docs.md.example'; } \
     && echo tracked-excluded || echo mismatch )"

# Implement flip: the function + each of its fail-loud call sites (at least the four
# pinned below), guarded on interim. Each pin quotes that site's unique cause string,
# so deleting the call goes RED; a fifth site added later never falsifies this prose.
assert_eq "#356 pin: devflow-implement.yml defines flip_to_failed guarded on CLASS=interim" "yes" \
  "$(grep -q 'flip_to_failed()' "$IMPL_YML" && grep -q '\[ "\${CLASS:-}" = "interim" \] || return 0' "$IMPL_YML" && echo yes || echo no)"
assert_eq "#356 pin: implement flip writes --status Failed with a dead-run note" "yes" \
  "$(grep -q -- '--status Failed' "$IMPL_YML" && grep -q 'run died:' "$IMPL_YML" && echo yes || echo no)"
assert_eq "#356 pin: implement flip called at the mktemp abort" "yes" \
  "$(grep -q 'flip_to_failed "mktemp failed' "$IMPL_YML" && echo yes || echo no)"
assert_eq "#356 pin: implement flip called at the dropped-resume-comment abort" "yes" \
  "$(grep -q 'flip_to_failed "resume re-dispatch comment did not land"' "$IMPL_YML" && echo yes || echo no)"
assert_eq "#356 pin: implement flip called at the resume-posted-but-no-App-token abort" "yes" \
  "$(grep -q 'flip_to_failed "resume comment posted but no App token' "$IMPL_YML" && echo yes || echo no)"
assert_eq "#356 pin: implement flip at the shared final exit is guarded FAIL=1 (never the green resume)" "yes" \
  "$(grep -q '\[ "\$FAIL" -eq 1 \] && flip_to_failed "\${DECISION}"' "$IMPL_YML" && echo yes || echo no)"
# Absence: the flip must NOT sit inside the resume-comment case arm (the green path) —
# writing a terminal Failed before a resume would make the resumed run's own backstop
# read `terminal -> noop` and permanently disarm it. This is THE load-bearing invariant.
#
# The range is located indentation-AGNOSTICALLY, and the arm's body is asserted
# non-empty FIRST. A range keyed on literal indentation fails OPEN on any reflow of the
# `case` block: the range never opens, awk prints nothing, and the absence check reports
# PASS while the regression sits in the arm. The positive control below turns that
# vacuous-range case RED instead — an absence pin that cannot locate its subject asserts
# nothing, so it must fail, not pass.
_resume_arm_body() {  # print the lines strictly inside the `resume)` case arm
  awk '
    /^[[:space:]]*resume\)[[:space:]]*$/ { f=1; next }
    f && /^[[:space:]]*;;[[:space:]]*$/  { f=0; next }
    f { print }
  ' "$1"
}
assert_eq "#356 pin: the resume) case arm is locatable (absence pin below is not vacuous)" "yes" \
  "$([ -n "$(_resume_arm_body "$IMPL_YML")" ] && echo yes || echo no)"
assert_eq "#356 pin: no flip_to_failed inside the resume) comment-building case arm" "yes" \
  "$(_resume_arm_body "$IMPL_YML" | grep -q 'flip_to_failed' && echo no || echo yes)"

# The flip step names the specific mode that fired, so the comment's cause line and the
# job log agree on why the run was treated as dead. Issue #1154 moved that inline
# if/else chain into scripts/describe-dead-run-cause.sh so the suite can drive every arm
# AND its order (lib/test/modules/review-trigger-helpers.sh); what stays pinned here is
# that the workflow REACHES the helper and still feeds it both observables. A cause
# literal pinned against the YAML would now assert nothing about the selection.
assert_eq "#1154 pin: devflow.yml derives the dead-run cause through describe-dead-run-cause.sh" "yes" \
  "$(grep -qF 'CAUSE="$(bash "$CAUSE_HELPER" "${CLAUDE_OUTCOME:-}" "${ENGINE_ERROR:-false}")"' "$DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#1154 pin: devflow.yml resolves the cause helper vendored-first then repo-root" "yes" \
  "$(grep -qF 'CAUSE_HELPER=.prflow/vendor/prflow/scripts/describe-dead-run-cause.sh' "$DEVFLOW_YML" \
     && grep -qF '[ -f "$CAUSE_HELPER" ] || CAUSE_HELPER=scripts/describe-dead-run-cause.sh' "$DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#1154 pin: an absent cause helper degrades with a warning instead of failing the step" "yes" \
  "$(grep -qF 'describe-dead-run-cause.sh absent at $CAUSE_HELPER' "$DEVFLOW_YML" && echo yes || echo no)"

# Review flip: devflow.yml's outcome-keyed step. Issue #936 removed
# devflow-review.yml (the auto PR-triggered tier's caller), so its finalize_check
# arms — job-failure, cancellation, and the ENGINE_ERROR-gated engine-error
# incomplete — are gone with the workflow that carried them. The manual
# /devflow:review comment path in devflow.yml is the surviving flip consumer and
# keeps its full pin set below.
assert_eq "#356 pin: devflow.yml adds the dead-run review-progress flip step" "yes" \
  "$(grep -q 'Flip review-progress comment on dead run' "$DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#356 pin: devflow.yml flip step wires the helper" "yes" \
  "$(grep -q 'flip-review-progress-failed.sh' "$DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#356 pin: devflow.yml actually INVOKES the helper (not just names it)" "yes" \
  "$(grep -qF 'bash "$FLIP_HELPER" "$TARGET_NUMBER" "$FLIP_MARKER"' "$DEVFLOW_YML" && echo yes || echo no)"
# Issue #1154 replaced the flip step's three-disjunct outcome gate with a bare
# `always()`: a run that exited CLEANLY having written no verdict matched none of the
# three disjuncts, so the backstop never fired on exactly the mode it exists to cover
# (Actions run 29854795625). The gate is now asserted by ABSENCE as well as presence —
# a reintroduced outcome disjunct on this step's own `if:` re-opens that hole while
# every other pin here stays green.
#
# The step's `if:` is located by walking forward from its `- name:` line to the first
# `if:`, so the assertion cannot be satisfied by some other step's guard, and the
# located line is asserted non-empty first (an absence pin that cannot find its subject
# asserts nothing).
DF1154_IF="$(awk '
  /^[[:space:]]*- name: Flip review-progress comment on dead run[[:space:]]*$/ { f=1; next }
  f && /^[[:space:]]*if:/ { print; exit }
' "$DEVFLOW_YML")"
assert_eq "#1154 pin: the dead-run step's own if: guard is locatable (absence pin below is not vacuous)" "yes" \
  "$([ -n "$DF1154_IF" ] && echo yes || echo no)"
assert_eq "#1154 pin: devflow.yml dead-run step's guard is always()-wrapped (runs on cancellation)" "yes" \
  "$(printf '%s' "$DF1154_IF" | grep -qF 'always()' && echo yes || echo no)"
assert_eq "#1154 pin: the dead-run step's guard carries NO steps.claude.outcome disjunct" "yes" \
  "$(printf '%s' "$DF1154_IF" | grep -qF 'steps.claude.outcome' && echo no || echo yes)"
assert_eq "#1154 pin: the dead-run step's guard carries NO steps.engine.outputs.is_error disjunct" "yes" \
  "$(printf '%s' "$DF1154_IF" | grep -qF 'steps.engine.outputs.is_error' && echo no || echo yes)"
# Both observables must still reach the step as ENV — they are inputs to the cause, and
# a guard removal that also dropped them would leave every cause undifferentiated.
assert_eq "#1154 pin: the dead-run step still receives both observables as step env" "yes" \
  "$(grep -qF 'CLAUDE_OUTCOME: ${{ steps.claude.outcome }}' "$DEVFLOW_YML" \
     && grep -qF 'ENGINE_ERROR: ${{ steps.engine.outputs.is_error }}' "$DEVFLOW_YML" && echo yes || echo no)"
# The is_error disjunct needs a producer: devflow.yml must parse the engine result
# into steps.engine, mirroring devflow-runner.yml's own parse step.
assert_eq "#356 pin: devflow.yml surfaces the engine execution result as steps.engine.is_error" "yes" \
  "$(grep -q 'id: engine' "$DEVFLOW_YML" && grep -q 'parse-engine-error.sh' "$DEVFLOW_YML" && grep -q 'is_error=\$IS_ERROR' "$DEVFLOW_YML" && echo yes || echo no)"
# ── issue #814: `update` suppresses the stdout body echo by default ──────────────
# Reuses the #356 gh stub (it is the only one of the four that tees the PATCH body
# it received to WP_PATCHBODY, which is what makes the payload-invariance pair below
# able to fail) and the #356 interim fixture. run814 deliberately does NOT pass
# --print-body, so the default arm is what these assertions observe.
run814() {  # <body-file> <args...> → prints exit code; leaves out/err/patchbody on disk.
  local body="$1"; shift
  : > "$S356/patchlog"; : > "$S356/patchbody8"
  WP_BODY="$body" WP_PATCHLOG="$S356/patchlog" WP_PATCHBODY="$S356/patchbody8" \
  DEVFLOW_GH="$S356/gh" \
    python3 "$WP_PY" update 888 "$@" >"$S356/out8" 2>"$S356/err8"
  echo $?
}

# (default) a clean PATCH writes a zero-byte stdout capture, still PATCHes, exit 0.
_c="$(run814 "$S356/interim.md" --note 'a note')"
assert_eq "#814: a clean update PATCHes and exits 0 under the default" "0" "$_c"
assert_eq "#814: a clean update writes a zero-byte stdout capture by default" "yes" \
  "$([ ! -s "$S356/out8" ] && echo yes || echo no)"
assert_eq "#814: a clean update still made a PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo yes || echo no)"
# The success breadcrumb is what keeps a successful call from being byte-identical to
# one a permission matcher silently refused (which prints nothing on either channel).
assert_eq "#814: a clean update writes exactly one success breadcrumb naming the comment id" "1" \
  "$(grep -c '^workpad.py update: PATCHed comment 7' "$S356/err8")"

# (default, --status) the breadcrumb carries the Status value read back from the PATCH
# response — the one read-back an exit code cannot discharge.
_c="$(run814 "$S356/interim.md" --status Reviewing)"
assert_eq "#814: a --status update's breadcrumb carries the read-back Status value" "yes" \
  "$(grep -q '^workpad.py update: PATCHed comment 7; Status: 🚀 Reviewing$' "$S356/err8" && echo yes || echo no)"
assert_eq "#814: a --status update still suppresses the body echo" "yes" \
  "$([ ! -s "$S356/out8" ] && echo yes || echo no)"

# (default, volatile tick miss) the stated exception: exit non-zero, the #169 report
# unchanged, NO success breadcrumb, and the body IS still written — it is the row
# inventory the mandated positional re-resolution reads before re-ticking.
_c="$(run814 "$S356/interim.md" --note 'n' --tick-ac 'NO_SUCH_AC')"
assert_eq "#814: a volatile tick miss still exits non-zero under the default" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#814: the volatile-tick-miss path still writes the patched body to stdout" "yes" \
  "$([ -s "$S356/out8" ] && grep -q '^\*\*Status:\*\*' "$S356/out8" && echo yes || echo no)"
assert_eq "#814: the volatile-tick-miss path writes NO success breadcrumb" "0" \
  "$(grep -c '^workpad.py update: PATCHed comment' "$S356/err8")"
assert_eq "#814: the #169 volatile-miss report is unchanged under the default" "yes" \
  "$(grep -q 'NO_SUCH_AC' "$S356/err8" && grep -q 'did not resolve' "$S356/err8" && echo yes || echo no)"

# (payload invariance) one fixture driven twice — default, then --print-body. The
# PATCH body the stub recorded must be byte-identical across the two RUNS (a
# comparison between a capture and that same run's stub recording would be a
# tautology), while stdout is zero bytes in the first and non-empty in the second.
# `Last updated` is minute-granular, so the two runs agree unless a minute boundary
# falls between them; normalise that one line out of both recordings so the assertion
# tests the payload rather than the clock.
run814 "$S356/interim.md" --status Reviewing >/dev/null
cp "$S356/patchbody8" "$S356/pb-default"
_defaultout_empty="$([ ! -s "$S356/out8" ] && echo yes || echo no)"
run814 "$S356/interim.md" --status Reviewing --print-body >/dev/null
cp "$S356/patchbody8" "$S356/pb-printbody"
# The normalise-and-compare runs under python3 (preflight-guaranteed) rather than
# `sed`+`cmp`: it is the value that DECIDES this assertion, and neither of those is a
# preflight-guaranteed tool, so a host missing one would silently decide the comparison
# rather than fail attributably.
assert_eq "#814: suppression changes only the echo — the PATCH payload is byte-identical across a default run and a --print-body run" "yes" \
  "$(python3 - "$S356/pb-default" "$S356/pb-printbody" <<'PY'
import re, sys
def norm(p):
    return re.sub(r'(?m)^\*\*Last updated:\*\*.*$', '**Last updated:** X', open(p, encoding='utf-8').read())
print('yes' if norm(sys.argv[1]) == norm(sys.argv[2]) else 'no')
PY
)"
assert_eq "#814: ... while the default run's stdout capture is zero bytes" "yes" "$_defaultout_empty"
assert_eq "#814: ... and the --print-body run's stdout capture is not" "yes" \
  "$([ -s "$S356/out8" ] && echo yes || echo no)"
# The echo-SOURCE question — does --print-body write the PATCH RESPONSE or the locally
# mutated body? — is deliberately NOT asked here. This stub answers a PATCH by teeing the
# body it received, so the response and the recording are the same bytes by construction
# and any comparison between them at this level passes whichever source the code reads.
# It is asked where it can actually fail: test_python_scripts.py drives cmd_update with a
# `patch_response` that differs from the stored body, so a code path echoing the mutation
# instead of the response turns that assertion RED.
# The pair only proves invariance if the recordings are real, not two empty files.
assert_eq "#814: the payload-invariance comparison ran over a non-empty recorded PATCH body" "yes" \
  "$([ -s "$S356/pb-default" ] && echo yes || echo no)"

# (workpad-absent) the id lookup finds no workpad: exit 1, nothing on stdout, and —
# load-bearing — NO success breadcrumb, so the "success line beside a failure" split
# the breadcrumb design excludes cannot reappear on the one path that never PATCHes.
: > "$S356/patchlog"
WP_BODY="$S356/interim.md" WP_PATCHLOG="$S356/patchlog" WP_ABSENT=1 DEVFLOW_GH="$S356/gh" \
  python3 "$WP_PY" update 888 --note 'n' >"$S356/out8" 2>"$S356/err8"; _c=$?
assert_eq "#814: a workpad-absent update exits non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#814: a workpad-absent update writes nothing to stdout and no success breadcrumb" "yes" \
  "$([ ! -s "$S356/out8" ] && [ "$(grep -c '^workpad.py update: PATCHed comment' "$S356/err8")" = "0" ] && echo yes || echo no)"
assert_eq "#814: ... and it made no PATCH" "yes" \
  "$([ -s "$S356/patchlog" ] && echo no || echo yes)"

# (combined --status + volatile tick miss) the shape Phase 3.4 and Phase 4.3 actually
# emit. The breadcrumb is suppressed (non-zero exit), so the landed-Status read-back
# must come from the echoed body — which this path still writes. Asserting BOTH halves
# is what keeps skills/implement/SKILL.md's absent-breadcrumb rule discharged on the
# one path where a --status write is most likely to ride along with a tick.
_c="$(run814 "$S356/interim.md" --status Reviewing --tick-ac 'NO_SUCH_AC')"
assert_eq "#814: a --status call whose tick misses exits non-zero and writes no breadcrumb" "yes" \
  "$([ "$_c" != "0" ] && [ "$(grep -c '^workpad.py update: PATCHed comment' "$S356/err8")" = "0" ] && echo yes || echo no)"
assert_eq "#814: ... and the echoed body carries the landed Status, so the read-back is still observable on that path" "yes" \
  "$(grep -q '^\*\*Status:\*\* 🚀 Reviewing$' "$S356/out8" && echo yes || echo no)"
assert_eq "#814: ... beside the unchanged volatile-miss report naming the tick" "yes" \
  "$(grep -q 'NO_SUCH_AC' "$S356/err8" && echo yes || echo no)"

# (non-writing exit paths) a structural abort and a PATCH-call failure keep their exit
# codes and write nothing to stdout under the default.
_c="$(run814 "$S356/interim.md" --replace-plan-file "$S356/no-such-plan.md")"
assert_eq "#814: a structural abort exits non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#814: a structural abort writes nothing to stdout" "yes" \
  "$([ ! -s "$S356/out8" ] && echo yes || echo no)"
# Attribute the rejection (guard-class 3): more than one structural guard could reject
# this fixture, so pin the unreadable-file guard's own signal. Without it a mutant that
# dropped that guard — leaving a sibling to reject the same input — would stay green.
assert_eq "#814: ... and the abort is attributable to the unreadable --replace-plan-file" "yes" \
  "$(grep -q 'no-such-plan.md' "$S356/err8" && echo yes || echo no)"
: > "$S356/patchlog"; : > "$S356/patchbody8"
WP_BODY="$S356/interim.md" WP_PATCHLOG="$S356/patchlog" WP_PATCH_FAIL=1 DEVFLOW_GH="$S356/gh" \
  python3 "$WP_PY" update 888 --note 'n' >"$S356/out8" 2>"$S356/err8"; _c=$?
assert_eq "#814: a PATCH-call failure exits non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#814: a PATCH-call failure writes nothing to stdout and no success breadcrumb" "yes" \
  "$([ ! -s "$S356/out8" ] && [ "$(grep -c '^workpad.py update: PATCHed comment' "$S356/err8")" = "0" ] && echo yes || echo no)"
# That failing PATCH is a real failed write, so issue #1214's replay buffer captured
# its `--note` into the CHECKOUT's own `.prflow/tmp/workpad-buffer/<comment-id>.json`
# — the buffer is anchored on the repo root, not on this block's $S356 sandbox, and
# nothing else here would reclaim it. Every later block driving `workpad.py update`
# against a stub that answers with the SAME comment id would then have that note
# replayed into its call (the stub ids are fixture constants, unique only in
# production), which is a cross-block fixture leak, not a product behavior. Drop it
# with the rest of this block's state.
rm -f "$LIB/../.prflow/tmp/workpad-buffer/7.json"

rm -rf "$S356"

# ── issue #601: self-hosted Windows runner support — path_to_claude_code_executable ──
# Each of the three shipped workflows that invoke claude-code-action must pass the
# action's `path_to_claude_code_executable` input, sourced from a new optional config
# key `setup.claude_code_executable`, defaulting to an EMPTY string (action auto-install
# path, unchanged for Linux consumers) when the key is absent. devflow.yml and
# devflow-implement.yml source it from their own `config` job; devflow-runner.yml sources
# it ONLY from the trusted base-ref config (steps.baseprovision) — never a PR-head-checked-out
# config, because that job runs under a write token and the resolved path is executed (an
# arbitrary-code-execution boundary). These are literal-presence guards over the three
# workflow surfaces; they do not claim executable mutation coverage.
I601_DEVFLOW_YML="$LIB/../.github/workflows/devflow.yml"
I601_IMPL_YML="$LIB/../.github/workflows/devflow-implement.yml"
I601_RUNNER_YML="$LIB/../.github/workflows/devflow-runner.yml"
I601_SCHEMA="$LIB/../.prflow/config.schema.json"
I601_EXAMPLE="$LIB/../.prflow/config.example.json"

# AC1 — devflow.yml: extraction (// empty default) + config-job output + with: input.
assert_eq "#601 AC1: devflow.yml extracts setup.claude_code_executable with // empty default" "yes" \
  "$(grep -qF '.setup.claude_code_executable // empty' "$I601_DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#601 AC1: devflow.yml config job exposes the claude_code_executable output" "yes" \
  "$(grep -qF 'claude_code_executable: ${{ steps.extract.outputs.claude_code_executable }}' "$I601_DEVFLOW_YML" && echo yes || echo no)"
assert_eq "#601 AC1: devflow.yml Run Claude Code passes path_to_claude_code_executable from the config job" "yes" \
  "$(grep -qF 'path_to_claude_code_executable: ${{ needs.config.outputs.claude_code_executable }}' "$I601_DEVFLOW_YML" && echo yes || echo no)"

# AC2 — devflow-implement.yml: same pattern, its own config-job resolution.
assert_eq "#601 AC2: devflow-implement.yml extracts setup.claude_code_executable with // empty default" "yes" \
  "$(grep -qF '.setup.claude_code_executable // empty' "$I601_IMPL_YML" && echo yes || echo no)"
assert_eq "#601 AC2: devflow-implement.yml config job exposes the claude_code_executable output" "yes" \
  "$(grep -qF 'claude_code_executable: ${{ steps.extract.outputs.claude_code_executable }}' "$I601_IMPL_YML" && echo yes || echo no)"
assert_eq "#601 AC2: devflow-implement.yml Run Claude Code passes path_to_claude_code_executable from the config job" "yes" \
  "$(grep -qF 'path_to_claude_code_executable: ${{ needs.config.outputs.claude_code_executable }}' "$I601_IMPL_YML" && echo yes || echo no)"

# AC3 — devflow-runner.yml: trusted base-ref source ONLY (trust boundary). The security
# property is two-sided: (a) the extraction pipes the TRUSTED $BASE_JSON (the base-ref config
# materialized by baseprovision), and (b) the with: value references steps.baseprovision —
# never a PR-head config (steps.cfg.outputs / needs.config). The positive baseprovision pin is
# the authoritative guard (it goes RED for ANY re-source); the $BASE_JSON-source pins and the
# input-line-scoped negative pin harden the two ways a re-source could slip a differently-spelled
# PR-head value past the positive pin (per the #601 pr-test-analyzer review).
assert_eq "#601 AC3: devflow-runner.yml extracts setup.claude_code_executable from the trusted base config" "yes" \
  "$(grep -qF '.setup.claude_code_executable // empty' "$I601_RUNNER_YML" && echo yes || echo no)"
# (a) The extraction line pipes $BASE_JSON specifically — pins that the value comes from the
# trusted base-ref config, not a head-checked-out config JSON. Removing $BASE_JSON from the
# extraction (e.g. switching the pipe source to a head var) goes RED.
# Anchored on `| strings` so it pins the GUARDED extraction line specifically: the raw
# probe is co-located and also pipes $BASE_JSON, so an unanchored match was satisfiable by
# the probe line alone — a re-source switching only the guarded line to a PR-head var would
# have slipped past the AC3 pins.
assert_eq "#601 AC3: runner guarded extraction pipes the trusted \$BASE_JSON (not a PR-head config)" "yes" \
  "$(grep -E 'BASE_JSON.*claude_code_executable.*\| strings' "$I601_RUNNER_YML" | grep -qF '.setup.claude_code_executable' && echo yes || echo no)"
# The raw probe must read the same trusted source (it never widens the trust boundary).
assert_eq "#601 AC3: runner raw probe also pipes the trusted \$BASE_JSON" "yes" \
  "$(grep -E 'BASE_JSON.*claude_code_executable.*\| tostring' "$I601_RUNNER_YML" | grep -qF '.setup.claude_code_executable' && echo yes || echo no)"
# (b) Scope the with:-input pins to the YAML key line itself (leading-token, colon-terminated),
# NOT `grep path_to_claude_code_executable` over the whole file — that would also match the
# comment lines above the input and make the negative pin trippable by a comment edit.
I601_RUNNER_INPUT_LINE="$(grep -E '^[[:space:]]*path_to_claude_code_executable:' "$I601_RUNNER_YML" || true)"
assert_eq "#601 AC3: runner sources path_to_claude_code_executable from trusted baseprovision" "yes" \
  "$(printf '%s' "$I601_RUNNER_INPUT_LINE" | grep -qF 'steps.baseprovision.outputs.claude_code_executable' && echo yes || echo no)"
assert_eq "#601 AC3: runner with:-input does NOT source it from a PR-head config (cfg.outputs/needs.config)" "yes" \
  "$(printf '%s' "$I601_RUNNER_INPUT_LINE" | grep -Eq 'cfg\.outputs|needs\.config' && echo no || echo yes)"

# AC4 — empty/malformed/multi-line default resolves to an EMPTY, SINGLE-LINE string
# (auto-install path, Linux unchanged). Two complementary layers, with DIFFERENT reach:
#   (1) a PRESENCE pin that BOTH the `| strings` non-string guard AND the
#       `select(test("[\n\r]") | not)` embedded-newline guard are in each workflow's extraction.
#       This is the ONLY layer that catches removal of `| strings`: with it removed, a non-string
#       leaf flows into `select(test(...))`, whose `test()` errors on a non-string and is swallowed
#       by the surrounding `try … catch` back to empty — so the sweep's array row still passes.
#       The `| strings` guard is therefore defense-in-depth (the catch already yields empty), and
#       its removal is caught by literal presence here, NOT behaviorally by the sweep below.
#   (2) an EXECUTABLE sweep of the SHIPPED filter across the config-JSON adversarial matrix,
#       driven once per workflow — the filter is extracted from EACH of the three files rather
#       than from devflow.yml alone. Driving only one file left the `try … catch` wrapper of the
#       other two behaviorally untested: dropping `try`/`catch empty` from
#       devflow-implement.yml or devflow-runner.yml could pass every presence pin, yet under
#       `set -eo pipefail` a jq evaluation error on a hand-corrupted non-object `setup` would
#       abort the assignment and fail the whole config/baseprovision job — the exact abort
#       try/catch exists to prevent. This layer DOES behaviorally catch removal of the newline
#       guard: removing `select(test("[\n\r]") | not)` makes the escaped-newline row emit a
#       multi-line value (2 lines) → that sweep row goes RED.
#   The `| strings` guard remains static-only because the surrounding catch makes its removal
#   behaviorally indistinguishable in this matrix. The newline guard is exercised by layer (2).
for _f in "$I601_DEVFLOW_YML" "$I601_IMPL_YML" "$I601_RUNNER_YML"; do
  assert_eq "#601 AC4: $(basename "$_f") extraction carries the '| strings' non-string type guard" "yes" \
    "$(grep -qF '| strings | select(test("[\n\r]") | not)' "$_f" && echo yes || echo no)"
  # The whitespace-only guard: such a value passes `| strings` and carries no newline/CR, so
  # without this select it would be forwarded verbatim as path_to_claude_code_executable.
  assert_eq "#601 AC4: $(basename "$_f") extraction carries the whitespace-only guard" "yes" \
    "$(grep -qF 'select(test("^[[:space:]]*$") | not)' "$_f" && echo yes || echo no)"
  # Rejected != unset: a non-empty raw value that resolves to empty must leave an operator
  # breadcrumb rather than silently reverting to the (Windows-fatal) auto-install path.
  assert_eq "#601 AC4: $(basename "$_f") warns when a set value is rejected (rejected != unset)" "yes" \
    "$(grep -qF '::warning::setup.claude_code_executable is set' "$_f" && echo yes || echo no)"
done
# Extract the exact jq programs shipped in EACH workflow and drive them against the matrix, so
# the sweep tests the REAL filters (not a hardcoded copy, and not one file standing in for three).
# Neither filter contains a single-quote, so `[^']*` safely spans it up to the closing
# `) catch` terminator; the per-file positive-control assertions below fail RED if a future filter
# edit breaks either extraction (e.g. introduces a quote). The guarded filter is anchored on
# `| strings` and the raw probe on `| select`/`| tostring` plus its distinct `catch "set"`
# terminator, so the two co-located programs cannot be confused for one another (a bare `[^']*`
# match would take whichever appears first in the file).
for _f in "$I601_DEVFLOW_YML" "$I601_IMPL_YML" "$I601_RUNNER_YML"; do
  _b="$(basename "$_f")"
  # Strip comment lines BEFORE extracting: `head -1` takes the first match in the file, so a
  # future edit that quoted the filter text in a `#` comment above the real one would silently
  # select the comment — every positive control would still pass while the whole sweep tested a
  # non-shipped string (a fully-green sweep testing nothing shipped, the costliest vacuity here).
  I601_SRC="$(grep -v '^[[:space:]]*#' "$_f")"
  I601_FILTER="$(printf '%s' "$I601_SRC" | grep -oE "try \(\.setup\.claude_code_executable // empty \| strings[^']*\) catch empty" | head -1)"
  I601_RAW_FILTER="$(printf '%s' "$I601_SRC" | grep -oE "try \(\.setup\.claude_code_executable \| select[^']*\| tostring[^']*\) catch \"set\"" | head -1)"
  # Pin the three files' extracted programs EQUAL to one another. The per-file sweep below
  # proves each behaves correctly, but without this a future edit to one workflow's filter
  # that still satisfies every matrix row would drift silently — and the next untested shape
  # would then behave differently per workflow (the coupled-mirror class).
  if [ "$_b" = "$(basename "$I601_DEVFLOW_YML")" ]; then
    I601_FILTER_REF="$I601_FILTER"; I601_RAW_FILTER_REF="$I601_RAW_FILTER"
  else
    assert_eq "#601 AC4: $_b guarded jq filter is byte-identical to devflow.yml's (coupled mirror)" "$I601_FILTER_REF" "$I601_FILTER"
    assert_eq "#601 AC4: $_b raw-probe jq filter is byte-identical to devflow.yml's (coupled mirror)" "$I601_RAW_FILTER_REF" "$I601_RAW_FILTER"
  fi
  assert_eq "#601 AC4: $_b guarded jq filter is extractable (positive control)" "yes" \
    "$([ -n "$I601_FILTER" ] && echo yes || echo no)"
  assert_eq "#601 AC4: $_b raw-probe jq filter is extractable (positive control)" "yes" \
    "$([ -n "$I601_RAW_FILTER" ] && echo yes || echo no)"
  if [ -n "$I601_FILTER" ]; then
    assert_eq "#601 AC4 [$_b]: absent key → empty" "" \
      "$(printf '%s' '{}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: non-object setup → empty (try/catch, no abort)" "" \
      "$(printf '%s' '{"setup":"scalar"}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: explicit empty-string value → empty" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":""}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: valid string path → passed through verbatim" "/opt/claude" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"/opt/claude"}}' | jq -r "$I601_FILTER")"
    # A Windows path (backslashes, drive letter, embedded spaces) is the REAL load-bearing
    # value for this key — it must survive verbatim, not be mangled by any guard.
    assert_eq "#601 AC4 [$_b]: Windows path with spaces → passed through verbatim" 'C:\Program Files\claude.exe' \
      "$(printf '%s' '{"setup":{"claude_code_executable":"C:\\Program Files\\claude.exe"}}' | jq -r "$I601_FILTER")"
    # Regression guard A (non-string leaf): an array must collapse to empty, NOT pretty-print
    # multi-line and corrupt the GITHUB_OUTPUT key=value line. Assert empty AND zero lines.
    assert_eq "#601 AC4 [$_b]: non-string (array) leaf → empty (no GITHUB_OUTPUT corruption)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":["a","b"]}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: non-string (array) leaf → zero output lines (single-line-safe)" "0" \
      "$(printf '%s' '{"setup":{"claude_code_executable":["a","b"]}}' | jq -r "$I601_FILTER" | grep -c .)"
    # Regression guard B (valid string with an embedded newline — the #601 iteration-2 finding):
    # a VALID JSON string carrying an ESCAPED newline (the two source chars backslash-n, exactly
    # how json.load in read-project-config round-trips one) passes `| strings` but would make jq -r
    # emit a multi-line value; the select(test("[\n\r]")|not) guard must drop it to empty. Use
    # `printf '%s'` on the single-quoted literal so the `\n` reaches jq as an ESCAPE inside VALID
    # JSON (a bare `printf '…\n…'` would expand it into a raw newline → INVALID JSON → a parse
    # error caught by try/catch, which would pass this pin VACUOUSLY even with the guard removed).
    assert_eq "#601 AC4 [$_b]: valid string with embedded newline → empty (newline guard)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"a\ntrailing"}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: valid string with embedded newline → zero output lines (single-line-safe)" "0" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"a\ntrailing"}}' | jq -r "$I601_FILTER" | grep -c .)"
    # Regression guard B' — the CR half of the `[\n\r]` alternation, previously covered only by
    # exact-literal presence. A narrowing mutation to `test("[\n]")` now goes RED behaviorally.
    assert_eq "#601 AC4 [$_b]: valid string with embedded CR → empty (CR half of the newline guard)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"a\rtrailing"}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: valid string with embedded CR → zero output lines (single-line-safe)" "0" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"a\rtrailing"}}' | jq -r "$I601_FILTER" | grep -c .)"
    # Regression guard C — whitespace-only values. These pass `| strings`, carry no newline/CR,
    # and are single-line-safe, so nothing else rejects them; the contract is "blank means unset"
    # (auto-install), NOT "forward a space as an executable path".
    assert_eq "#601 AC4 [$_b]: spaces-only value → empty (whitespace-only guard)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"   "}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: tab-only value → empty (whitespace-only guard)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":"\t"}}' | jq -r "$I601_FILTER")"
  fi
  if [ -n "$I601_RAW_FILTER" ]; then
    # The raw probe decides the ::warning:: — it must distinguish REJECTED (non-empty raw,
    # empty resolved → warn) from UNSET (empty raw → silent). The deliberate unsets are an
    # absent key, an explicit "", and JSON `null` (null ≈ absent); every OTHER shape that
    # resolves to empty is a rejection and must warn — including the valid-falsy `false`
    # leaf and a non-object `setup`, the two shapes an earlier `// empty` / `catch empty`
    # probe swallowed silently (CLAUDE.md's six-shape config matrix, valid-falsy row).
    assert_eq "#601 AC4 [$_b]: raw probe — absent key is unset, not rejected (no warning)" "" \
      "$(printf '%s' '{}' | jq -r "$I601_RAW_FILTER")"
    assert_eq "#601 AC4 [$_b]: raw probe — null leaf is a deliberate unset (no warning)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":null}}' | jq -r "$I601_RAW_FILTER")"
    # Valid-falsy row: `//` is FALSY-triggered, so a `// empty` probe swallowed `false`
    # before `tostring` — rejected to auto-install with NO breadcrumb on the one platform
    # where the key is load-bearing. Goes RED if the probe reverts to `// empty`.
    assert_eq "#601 AC4 [$_b]: raw probe — valid-falsy false leaf is rejected, not unset (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":false}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — numeric leaf is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":0}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — object leaf is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":{}}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # `setup`-level wrong-type rows: indexing a scalar/array raises a jq error that BOTH
    # filters hit, so the guarded one cannot resolve a value. `catch "set"` (not
    # `catch empty`) is what keeps that a loud rejection instead of a silent fail-open.
    assert_eq "#601 AC4 [$_b]: raw probe — non-object (scalar) setup is rejected, not unset (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":"scalar"}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — array setup is rejected, not unset (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":["a"]}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # `setup`-level valid-falsy + null rows. `{"setup":null}` is the only OTHER path to silent:
    # indexing null yields null (no jq error), so the probe's `select(. != null)` drops it. It is
    # the intended behavior (nulling the block ≈ not setting it) and nothing else pins it, so a
    # future probe edit flipping it to a spurious warning on a merely-nulled block would go RED.
    assert_eq "#601 AC4 [$_b]: raw probe — null setup is a deliberate unset (no warning)" "" \
      "$(printf '%s' '{"setup":null}' | jq -r "$I601_RAW_FILTER")"
    assert_eq "#601 AC4 [$_b]: raw probe — empty-object setup is an unset (no warning)" "" \
      "$(printf '%s' '{"setup":{}}' | jq -r "$I601_RAW_FILTER")"
    assert_eq "#601 AC4 [$_b]: raw probe — valid-falsy false setup is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":false}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — numeric setup is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":0}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # Top-level wrong-type rows: `.setup` on a non-object document raises, so BOTH filters land
    # in `catch` — guarded empty, raw "set" → a rejection verdict on a config malformed above
    # this key. The try/catch wrapper is the only reason this survives `set -eo pipefail`.
    assert_eq "#601 AC4 [$_b]: raw probe — top-level array document is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '[]' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — top-level string document is rejected (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '"str"' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # Contract pin: surrounding whitespace around real content is NOT trimmed — the value is
    # forwarded verbatim (a path may legitimately contain spaces, as the Windows row proves).
    # Pinning the direction makes trim-vs-no-trim explicit rather than incidental.
    assert_eq "#601 AC4 [$_b]: padded valid path is forwarded verbatim (NOT trimmed)" " /opt/claude " \
      "$(printf '%s' '{"setup":{"claude_code_executable":" /opt/claude "}}' | jq -r "$I601_FILTER")"
    assert_eq "#601 AC4 [$_b]: raw probe — explicit empty string is a deliberate unset (no warning)" "" \
      "$(printf '%s' '{"setup":{"claude_code_executable":""}}' | jq -r "$I601_RAW_FILTER")"
    assert_eq "#601 AC4 [$_b]: raw probe — rejected array leaf is non-empty (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":["a","b"]}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — rejected whitespace-only value is non-empty (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":"   "}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    assert_eq "#601 AC4 [$_b]: raw probe — rejected embedded-newline value is non-empty (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":"a\ntrailing"}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # A value composed ENTIRELY of newline(s) is a rejected shape too, and it is the reason
    # the probe emits a sentinel instead of the value: `$(…)` strips trailing newlines, so a
    # value-emitting probe collapsed this row to the empty string and the ::warning:: silently
    # never fired. Capture through a command substitution (as the workflow does) so the pin
    # goes RED if the sentinel is reverted to a bare `tostring`.
    assert_eq "#601 AC4 [$_b]: raw probe — pure-newline value survives \$(…) stripping (warning fires)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":"\n"}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
    # A VALID path must yield a NON-EMPTY raw probe — the other half of the warning branch.
    # Without this, a probe that always returned empty would pass every "unset" row above.
    assert_eq "#601 AC4 [$_b]: raw probe — valid path is non-empty (warning branch operand)" 'yes' \
      "$([ -n "$(printf '%s' '{"setup":{"claude_code_executable":"/opt/claude"}}' | jq -r "$I601_RAW_FILTER")" ] && echo yes || echo no)"
  fi
  if [ -n "$I601_FILTER" ] && [ -n "$I601_RAW_FILTER" ]; then
    # Drive the COMPOSED warning selection — `[ -n RAW ] && [ -z RESOLVED ]` — not just its two
    # operands separately. A reversed test, or a regression that warns on a valid path, now goes
    # RED. `_i601_warns` mirrors the workflow's shell condition exactly.
    _i601_warns() {
      local _json="$1" _raw _res
      _raw="$(printf '%s' "$_json" | jq -r "$I601_RAW_FILTER")"
      _res="$(printf '%s' "$_json" | jq -r "$I601_FILTER")"
      if [ -n "$_raw" ] && [ -z "$_res" ]; then echo warn; else echo silent; fi
    }
    assert_eq "#601 AC4 [$_b]: composed branch — valid path does NOT warn" "silent" \
      "$(_i601_warns '{"setup":{"claude_code_executable":"/opt/claude"}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — absent key does NOT warn (unset)" "silent" \
      "$(_i601_warns '{}')"
    assert_eq "#601 AC4 [$_b]: composed branch — explicit empty string does NOT warn (deliberate unset)" "silent" \
      "$(_i601_warns '{"setup":{"claude_code_executable":""}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — array leaf warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":["a","b"]}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — whitespace-only value warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":"   "}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — embedded-newline value warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":"a\ntrailing"}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — pure-newline value warns (\$(…)-stripping regression)" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":"\n"}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — null leaf does NOT warn (unset, like absent)" "silent" \
      "$(_i601_warns '{"setup":{"claude_code_executable":null}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — valid-falsy false leaf warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":false}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — numeric leaf warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":0}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — object leaf warns" "warn" \
      "$(_i601_warns '{"setup":{"claude_code_executable":{}}}')"
    assert_eq "#601 AC4 [$_b]: composed branch — non-object (scalar) setup warns" "warn" \
      "$(_i601_warns '{"setup":"scalar"}')"
    assert_eq "#601 AC4 [$_b]: composed branch — array setup warns" "warn" \
      "$(_i601_warns '{"setup":["a"]}')"
  fi
done

# AC5 — schema documents the optional string key; example carries it (empty default).
assert_eq "#601 AC5: schema setup.claude_code_executable type is string" "string" \
  "$(jq -r '.properties.setup.properties.claude_code_executable.type' "$I601_SCHEMA")"
assert_eq "#601 AC5: schema setup.claude_code_executable has a non-empty description" "yes" \
  "$(jq -e '.properties.setup.properties.claude_code_executable.description | type == "string" and (length > 0)' "$I601_SCHEMA" >/dev/null && echo yes || echo no)"
assert_eq "#601 AC5: example config carries setup.claude_code_executable (empty default)" "" \
  "$(jq -r '.setup.claude_code_executable' "$I601_EXAMPLE")"

# ── issue #645: the #602 git-env pins are ABSENT BY DEFAULT, behind two opt-in flags ──
# Supersedes the original issue-#602 both-present contract. #602/PR #643 set step-scoped
# GIT_DIR and GIT_WORK_TREE UNCONDITIONALLY on the 'Run Claude Code' step of the three
# shipped workflows, so claude-code-action's configureGitAuth would resolve the repo on a
# self-hosted Windows runner. But GIT_WORK_TREE also reaches the Claude Code CLI subprocess
# that installs plugins, where it makes `git clone` refuse an existing working tree, so every
# cloud run died at plugin install (`fatal: working tree '<path>' already exists.`) before the
# agent did any work — a checkless, verdictless run. The two variables are now decoupled into
# two independent opt-in config keys, BOTH DEFAULT FALSE, resolved by the bundled helper
# scripts/emit-git-env.sh whose stdout a step immediately before 'Run Claude Code' appends to
# $GITHUB_ENV. So the contract asserted here is the INVERSE of the old one: the action step's
# OWN env: block must carry NEITHER variable (the helper is the single producer of both).
#
# The awk extraction scopes each count to the step block (between the step `name:` and its
# `with:`). A zero-occurrence check over an EMPTY extraction passes vacuously — a renamed step
# or a reordered `with:` key would silently make this green — so the extraction is itself
# asserted non-empty first.
I602_DEVFLOW_YML="$LIB/../.github/workflows/devflow.yml"
I602_IMPL_YML="$LIB/../.github/workflows/devflow-implement.yml"
I602_RUNNER_YML="$LIB/../.github/workflows/devflow-runner.yml"
# A-1 / A-2: absent-by-default in the action step's own env:, plus the helper step present
# and positioned BEFORE it.
for _f in "$I602_DEVFLOW_YML" "$I602_IMPL_YML" "$I602_RUNNER_YML"; do
  _b="$(basename "$_f")"
  I602_STEP_BLK="$(awk '/name: Run Claude Code/{f=1} f{print} f&&/^        with:/{exit}' "$_f")"
  # Non-vacuity guard for the two zero-occurrence checks below.
  assert_eq "#645 A-1 [$_b]: the Run Claude Code step block extraction is non-empty (anti-vacuity)" \
    "yes" "$([ -n "$I602_STEP_BLK" ] && echo yes || echo no)"
  assert_eq "#645 A-1 [$_b]: Run Claude Code step's own env: carries NO GIT_DIR entry" "0" \
    "$(printf '%s\n' "$I602_STEP_BLK" | grep -c 'GIT_DIR')"
  assert_eq "#645 A-1 [$_b]: Run Claude Code step's own env: carries NO GIT_WORK_TREE entry" "0" \
    "$(printf '%s\n' "$I602_STEP_BLK" | grep -c 'GIT_WORK_TREE')"
  assert_eq "#645 A-2 [$_b]: the git-env pin helper step is present" "1" \
    "$(grep -cF 'name: Resolve git-env pins' "$_f")"
  # The invocation is `bash "$HELPER" …` (HELPER resolved by the step's own trusted-source
  # ladder on the review tier), so the operative pin is that line, not a bare path literal.
  assert_eq "#645 A-2 [$_b]: the helper step invokes the resolved helper with a workspace and a tier" "1" \
    "$(grep -cF 'bash "$HELPER" --workspace "$GITENV_WS" --config-file "$CFG" --tier' "$_f")"
  assert_eq "#645 A-2 [$_b]: the helper the step resolves is emit-git-env.sh" "yes" \
    "$(grep -q 'emit-git-env\.sh' "$_f" && echo yes || echo no)"
  # Positional: the helper step must come BEFORE the action step, so the append to
  # $GITHUB_ENV is in force when the action runs.
  assert_eq "#645 A-2 [$_b]: the helper step precedes the Run Claude Code step" "yes" \
    "$([ "$(grep -nF 'name: Resolve git-env pins' "$_f" | head -1 | cut -d: -f1)" -lt \
        "$(grep -nF 'name: Run Claude Code' "$_f" | head -1 | cut -d: -f1)" ] && echo yes || echo no)"
  # A-3 (first half): the absent-by-default assertion must catch the GUARDED REGRESSION —
  # a re-inserted GIT_WORK_TREE entry in the action step's own env: block — not merely its
  # own removal. A positive source-presence helper cannot express an INVERSE (zero-occurrence) pin, so the
  # mutation is applied here and the assertion is re-evaluated over the mutated copy: it must
  # flip from 0 to non-zero. The mutation re-creates exactly the shape that caused the outage.
  I645_MUT="$(probe_tmp "#645 A-3 [$_b] re-insertion mutation")" || I645_MUT=''
  if [ -n "$I645_MUT" ]; then
    sed -E 's|^(      - name: Run Claude Code)$|\1\n        env:\n          GIT_WORK_TREE: ${{ github.workspace }}|' "$_f" > "$I645_MUT" 2>/dev/null
    I645_MUT_BLK="$(awk '/name: Run Claude Code/{f=1} f{print} f&&/^        with:/{exit}' "$I645_MUT")"
    assert_eq "#645 A-3 [$_b]: the absent-by-default GIT_WORK_TREE assertion goes RED when the env entry is re-inserted" \
      "0->nonzero" \
      "$(printf '%s\n' "$I602_STEP_BLK" | grep -c 'GIT_WORK_TREE')->$(printf '%s\n' "$I645_MUT_BLK" | grep -q 'GIT_WORK_TREE' && echo nonzero || echo 0)"
    rm -f "$I645_MUT"
  fi
  # A-3 (second half): deleting the helper invocation step turns the A-2 pin RED.
done
# Tier wiring: each workflow passes the tier its population requires. The implement tier
# must pass --tier implement, because that is what suppresses GIT_DIR on the one tier that
# stages and pushes commits (ambient GIT_DIR makes a stage issued from a non-root working
# directory record deletions across the rest of the tree).
# Pin the tier on the INVOCATION LINE itself, not a bare `--tier X` substring: the step's
# explanatory comment also names its tier, so a bare-substring count would be 2 and would
# drift on any comment edit.
I645_INVOC='bash "$HELPER" --workspace "$GITENV_WS" --config-file "$CFG" --tier'
assert_eq "#645 A-5: devflow-implement.yml invokes the helper with --tier implement" "1" \
  "$(grep -cF "$I645_INVOC implement" "$I602_IMPL_YML")"
assert_eq "#645: devflow.yml invokes the helper with --tier command" "1" \
  "$(grep -cF "$I645_INVOC command" "$I602_DEVFLOW_YML")"
assert_eq "#645: devflow-runner.yml invokes the helper with --tier review" "1" \
  "$(grep -cF "$I645_INVOC review" "$I602_RUNNER_YML")"
# A-7: on the review tier the keys are read from the TRUSTED base-ref config baseprovision
# materializes, never the PR-head checkout — the security boundary. Negative pin: the step
# must not source its config from a workspace-relative path.
assert_eq "#645 A-7: the review tier reads the git-env keys from the trusted base-ref config" "1" \
  "$(grep -cF 'GITENV_CFGJSON: ${{ steps.baseprovision.outputs.config_json }}' "$I602_RUNNER_YML")"
assert_eq "#645 A-7: the review tier materializes the helper from a trusted source only" "1" \
  "$(grep -cF 'gitenv_helper_dir=$GITENV_HELPER_DIR' "$I602_RUNNER_YML")"
assert_eq "#645 A-7: the review tier's rank-2 fallback is gated on vendor_source == fetch" "1" \
  "$(grep -cF "GITENV_VENDORSRC\" = 'fetch' ]" "$I602_RUNNER_YML")"
# The two trigger-time tiers read the whole trusted config document forwarded by their
# `config` job, which checks out the DEFAULT BRANCH — so a key set only in a PR head is inert.
for _f in "$I602_DEVFLOW_YML" "$I602_IMPL_YML"; do
  assert_eq "#645 [$(basename "$_f")]: the git-env keys are read from the trigger-time config job" "1" \
    "$(grep -cF 'GITENV_CFGJSON: ${{ needs.config.outputs.config_json }}' "$_f")"
done
# The two keys are declared in the schema, both defaulting to false, and mirrored in the
# example config as explicit falses (the documented-off-switch class: a valid-falsy value
# must survive as false, never be coerced to a truthy default).
I645_SCHEMA="$LIB/../.prflow/config.schema.json"
I645_EXAMPLE="$LIB/../.prflow/config.example.json"
for _k in git_dir_pin git_work_tree_pin; do
  assert_eq "#645: schema declares setup.$_k as a boolean defaulting to false" "boolean:false" \
    "$(jq -r --arg k "$_k" '.properties.setup.properties[$k] | "\(.type):\(.default)"' "$I645_SCHEMA")"
  assert_eq "#645: schema description for setup.$_k names what enabling it costs" "yes" \
    "$(jq -e --arg k "$_k" '.properties.setup.properties[$k].description | test("COST")' "$I645_SCHEMA" >/dev/null && echo yes || echo no)"
  assert_eq "#645: example config carries setup.$_k as an explicit false" "false" \
    "$(jq -r --arg k "$_k" '.setup[$k]' "$I645_EXAMPLE")"
done

# ── issue #645: emit-git-env.sh behavior (A-4, A-5) ───────────────────────────
# The helper is the single producer of both variables and a shell boundary the suite drives
# directly. Every row asserts exit 0 AND the exact emitted lines, because the consuming
# workflow step appends this stdout to $GITHUB_ENV: a non-zero exit would fail the job over a
# configuration read, and a WRONG emission is what reproduces the outage. The four-row
# combination set is closed by construction (two independent booleans).
I645_HELPER="$LIB/../scripts/emit-git-env.sh"
assert_eq "#645: emit-git-env.sh exists and is executable" "yes" \
  "$([ -x "$I645_HELPER" ] && echo yes || echo no)"
I645_D="$(probe_tmp '#645 helper fixture dir')" || I645_D=''
if [ -n "$I645_D" ]; then
  rm -f "$I645_D"; mkdir -p "$I645_D"
  # Drive the helper and render its stdout as a single semicolon-joined line so an exact
  # comparison covers BOTH which lines were emitted and their order.
  _i645_run() {  # tier config-json -> "rc|joined-stdout"
    local _tier="$1" _json="$2" _out _rc _joined=''
    printf '%s' "$_json" > "$I645_D/cfg.json"
    _out="$(bash "$I645_HELPER" --workspace /ws --config-file "$I645_D/cfg.json" --tier "$_tier" 2>/dev/null)"
    _rc=$?
    while IFS= read -r _l; do
      [ -z "$_l" ] && continue
      if [ -z "$_joined" ]; then _joined="$_l"; else _joined="$_joined;$_l"; fi
    done <<EOF
$_out
EOF
    printf '%s|%s' "$_rc" "$_joined"
  }
  # A-4, the closed 4-combination set on a tier that honors both keys.
  assert_eq "#645 A-4: both keys off → emits nothing (the working default), exit 0" "0|" \
    "$(_i645_run review '{"setup":{"git_dir_pin":false,"git_work_tree_pin":false}}')"
  assert_eq "#645 A-4: git_dir_pin only → emits GIT_DIR alone" "0|GIT_DIR=/ws/.git" \
    "$(_i645_run review '{"setup":{"git_dir_pin":true}}')"
  assert_eq "#645 A-4: git_work_tree_pin only → emits GIT_WORK_TREE alone" "0|GIT_WORK_TREE=/ws" \
    "$(_i645_run review '{"setup":{"git_work_tree_pin":true}}')"
  assert_eq "#645 A-4: both keys on → emits both assignments" "0|GIT_DIR=/ws/.git;GIT_WORK_TREE=/ws" \
    "$(_i645_run review '{"setup":{"git_dir_pin":true,"git_work_tree_pin":true}}')"
  # Boundary: the JSON STRING "true" reads as enabled, matching the platform gate's
  # stringifying behavior; every other stringy value does not.
  assert_eq "#645 A-4: the JSON string \"true\" enables a key" "0|GIT_DIR=/ws/.git;GIT_WORK_TREE=/ws" \
    "$(_i645_run review '{"setup":{"git_dir_pin":"true","git_work_tree_pin":"true"}}')"
  assert_eq "#645 A-4: the JSON string \"yes\" does NOT enable a key" "0|" \
    "$(_i645_run review '{"setup":{"git_dir_pin":"yes","git_work_tree_pin":"1"}}')"
  # A-4, the six-shape adversarial config-JSON matrix (CLAUDE.md's best-effort-parser rule),
  # applied to the `setup` CONTAINER and to each key LEAF. Every shape must exit 0 and emit
  # NOTHING: a hand-corrupted config yields the working default, never a partially-set
  # environment. The valid-falsy row is load-bearing — an explicit `false` must not be
  # coerced to a truthy default (the documented-off-switch class).
  for _shape in \
    'container-object-empty:{"setup":{}}' \
    'container-array:{"setup":["git_dir_pin","git_work_tree_pin"]}' \
    'container-scalar:{"setup":"git_dir_pin"}' \
    'container-valid-falsy:{"setup":false}' \
    'container-missing:{}' \
    'container-wrong-type:{"setup":42}' \
    'leaf-object:{"setup":{"git_dir_pin":{"enabled":true},"git_work_tree_pin":{"enabled":true}}}' \
    'leaf-array:{"setup":{"git_dir_pin":[true],"git_work_tree_pin":[true]}}' \
    'leaf-scalar:{"setup":{"git_dir_pin":1,"git_work_tree_pin":1}}' \
    'leaf-valid-falsy:{"setup":{"git_dir_pin":false,"git_work_tree_pin":0}}' \
    'leaf-missing:{"setup":{"claude_code_executable":""}}' \
    'leaf-wrong-type:{"setup":{"git_dir_pin":null,"git_work_tree_pin":null}}' \
    ; do
    assert_eq "#645 A-4: config shape '${_shape%%:*}' → exit 0, emits nothing (working default)" "0|" \
      "$(_i645_run review "${_shape#*:}")"
  done
  # Error path: a config that cannot be parsed at all emits nothing and exits 0.
  printf 'this is not json {{{' > "$I645_D/cfg.json"
  assert_eq "#645 A-4: an unparseable config → exit 0, emits nothing" "0|" \
    "$(_out="$(bash "$I645_HELPER" --workspace /ws --config-file "$I645_D/cfg.json" --tier review 2>/dev/null)"; printf '%s|%s' "$?" "$_out")"
  assert_eq "#645 A-4: a nonexistent config file → exit 0, emits nothing" "0|" \
    "$(_out="$(bash "$I645_HELPER" --workspace /ws --config-file "$I645_D/absent.json" --tier review 2>/dev/null)"; printf '%s|%s' "$?" "$_out")"
  # A-5: the implement tier IGNORES git_dir_pin and says so. GIT_WORK_TREE is unaffected —
  # the two keys are independent, and only the GIT_DIR one carries the staging hazard.
  assert_eq "#645 A-5: --tier implement suppresses GIT_DIR, keeps GIT_WORK_TREE" "0|GIT_WORK_TREE=/ws" \
    "$(_i645_run implement '{"setup":{"git_dir_pin":true,"git_work_tree_pin":true}}')"
  assert_eq "#645 A-5: --tier implement with only git_dir_pin emits nothing at all" "0|" \
    "$(_i645_run implement '{"setup":{"git_dir_pin":true}}')"
  printf '%s' '{"setup":{"git_dir_pin":true}}' > "$I645_D/cfg.json"
  assert_eq "#645 A-5: --tier implement emits a breadcrumb naming that git_dir_pin was ignored" "yes" \
    "$(bash "$I645_HELPER" --workspace /ws --config-file "$I645_D/cfg.json" --tier implement 2>&1 >/dev/null \
       | grep -q 'implement tier IGNORES it' && echo yes || echo no)"
  # The GIT_DIR silent-miss warning: the one loud signal for a failure mode that is otherwise
  # undetectable (the #295 repo-root readers resolve a .prflow/ that does not exist).
  assert_eq "#645: emitting GIT_DIR always warns about the #295 repo-root silent-miss hazard" "yes" \
    "$(bash "$I645_HELPER" --workspace /ws --config-file "$I645_D/cfg.json" --tier review 2>&1 >/dev/null \
       | grep -q 'SILENT MISS' && echo yes || echo no)"
  # An empty workspace cannot produce a usable assignment: an EMPTY value is not an absent
  # one (measured — `GIT_DIR=` is fatal to git), so the helper emits a line or emits nothing.
  printf '%s' '{"setup":{"git_dir_pin":true,"git_work_tree_pin":true}}' > "$I645_D/cfg.json"
  assert_eq "#645: an enabled key with an empty --workspace emits nothing (never an empty assignment)" "0|" \
    "$(_out="$(bash "$I645_HELPER" --workspace '' --config-file "$I645_D/cfg.json" --tier review 2>/dev/null)"; printf '%s|%s' "$?" "$_out")"
  # An unrecognized tier degrades to the MOST RESTRICTIVE tier, never to a permissive one.
  assert_eq "#645: an unrecognized --tier degrades to the implement (most restrictive) tier" "0|GIT_WORK_TREE=/ws" \
    "$(_i645_run bogus-tier '{"setup":{"git_dir_pin":true,"git_work_tree_pin":true}}')"
  rm -rf "$I645_D"
fi

# ── issue #682: attribute cloud-tier writer commits to the triggering user ─────
# scripts/resolve-committer-identity.sh is the sibling of emit-git-env.sh (#645):
# a default-off config flag (prflow.attribute_commits_to_triggerer) gates whether
# the four GIT_AUTHOR_*/GIT_COMMITTER_* variables are emitted for the triggering
# human. The helper is a pure shell CLI with a deterministic stdout/exit contract,
# driven directly here with DEVFLOW_GH stubbed (the resolver's test-stub contract),
# so no network/auth. Every enabled-and-human row asserts exit 0 AND the exact
# emitted identity, because the consuming workflow step appends this stdout to
# $GITHUB_ENV: a wrong emission mis-attributes a commit and a non-zero exit would
# fail the job over an advisory attribution read.
I682_IMPL_YML="$LIB/../.github/workflows/devflow-implement.yml"
I682_DEVFLOW_YML="$LIB/../.github/workflows/devflow.yml"
I682_HELPER="$LIB/../scripts/resolve-committer-identity.sh"
I682_SCHEMA="$LIB/../.prflow/config.schema.json"
I682_EXAMPLE="$LIB/../.prflow/config.example.json"

assert_eq "#682: resolve-committer-identity.sh exists and is executable" "yes" \
  "$([ -x "$I682_HELPER" ] && echo yes || echo no)"

# Schema/example: the key is declared as boolean defaulting to false and mirrored
# in the example config as an explicit false (the documented-off-switch class — a
# valid-falsy value must survive as false, never be coerced to a truthy default).
assert_eq "#682: schema declares prflow.attribute_commits_to_triggerer as boolean:false" "boolean:false" \
  "$(jq -r '.properties.prflow.properties.attribute_commits_to_triggerer | "\(.type):\(.default)"' "$I682_SCHEMA")"
assert_eq "#682: schema description names the post-merge-only semantics" "yes" \
  "$(jq -e '.properties.prflow.properties.attribute_commits_to_triggerer.description | test("POST-MERGE-ONLY")' "$I682_SCHEMA" >/dev/null && echo yes || echo no)"
assert_eq "#682: example config carries prflow.attribute_commits_to_triggerer as an explicit false" "false" \
  "$(jq -r '.prflow.attribute_commits_to_triggerer' "$I682_EXAMPLE")"

# Workflow wiring: BOTH writer workflows carry a step that reads the flag from the
# trusted trigger-time config, wires its OWN GH_TOKEN (the git-env-pins step it
# mirrors sets none), invokes the vendored helper with the sender login, appends to
# $GITHUB_ENV, and precedes Run Claude Code. A half-done change that wires only one
# workflow, or omits the token, fails a pin.
for _f in "$I682_IMPL_YML" "$I682_DEVFLOW_YML"; do
  _b="$(basename "$_f")"
  assert_eq "#682 [$_b]: the committer-identity step is present" "1" \
    "$(grep -cF 'name: Resolve committer identity' "$_f")"
  assert_eq "#682 [$_b]: the step invokes the vendored resolve-committer-identity.sh helper" "1" \
    "$(grep -cF ".prflow/vendor/prflow/scripts/resolve-committer-identity.sh" "$_f")"
  assert_eq "#682 [$_b]: the step invokes the helper with the sender login and appends to \$GITHUB_ENV" "1" \
    "$(grep -cF 'bash "$HELPER" --login "$SENDER_LOGIN" --config-file "$CFG" >> "$GITHUB_ENV"' "$_f")"
  # Scope the token/config-source pins to the step block (from its name: down to the
  # helper invocation) so a GH_TOKEN elsewhere in the file cannot make them pass
  # vacuously. The extraction is asserted non-empty first (anti-vacuity).
  I682_STEP_BLK="$(awk '/name: Resolve committer identity/{f=1} f{print} f&&/bash "\$HELPER" --login/{exit}' "$_f")"
  assert_eq "#682 [$_b]: the committer-identity step block extraction is non-empty (anti-vacuity)" "yes" \
    "$([ -n "$I682_STEP_BLK" ] && echo yes || echo no)"
  assert_eq "#682 [$_b]: the step wires its own GH_TOKEN so the gh api call is authenticated" "yes" \
    "$(printf '%s\n' "$I682_STEP_BLK" | grep -q 'GH_TOKEN:' && echo yes || echo no)"
  assert_eq "#682 [$_b]: the step reads the flag from the trusted trigger-time config job" "yes" \
    "$(printf '%s\n' "$I682_STEP_BLK" | grep -qF 'ATTR_CFGJSON: ${{ needs.config.outputs.config_json }}' && echo yes || echo no)"
  assert_eq "#682 [$_b]: the step passes github.event.sender.login" "yes" \
    "$(printf '%s\n' "$I682_STEP_BLK" | grep -qF 'SENDER_LOGIN: ${{ github.event.sender.login }}' && echo yes || echo no)"
  assert_eq "#682 [$_b]: the committer-identity step precedes the Run Claude Code step" "yes" \
    "$([ "$(grep -nF 'name: Resolve committer identity' "$_f" | head -1 | cut -d: -f1)" -lt \
        "$(grep -nF 'name: Run Claude Code' "$_f" | head -1 | cut -d: -f1)" ] && echo yes || echo no)"
  # The source and placement checks above preserve the committer-identity step and helper invocation.
done

# Helper behavior: a fixture dir with a DEVFLOW_GH stub that returns canned user
# JSON keyed by login, plus a driver that canonicalizes the helper's heredoc-form
# stdout into a compact "KEY=VALUE;…" string (in emission order) so an exact
# comparison covers which vars were emitted, their order, AND their values.
I682_D="$(probe_tmp '#682 helper fixture dir')" || I682_D=''
if [ -n "$I682_D" ]; then
  rm -rf "$I682_D"; mkdir -p "$I682_D"
  cat > "$I682_D/gh" <<'I682STUB'
#!/usr/bin/env bash
# Canned users/<login> responses; anything else fails so a stray call is loud.
a="$*"
case "$a" in
  *"--version"*)     echo "gh version 2.50.0 (stub)"; exit 0 ;;
  *"users/alice"*)   echo '{"login":"alice","id":12345,"name":"Alice Example","type":"User"}'; exit 0 ;;
  *"users/nullname"*)echo '{"login":"nullname","id":777,"name":null,"type":"User"}'; exit 0 ;;
  *"users/orgx"*)    echo '{"login":"orgx","id":42,"name":"Org X","type":"Organization"}'; exit 0 ;;
  *"users/notype"*)  echo '{"login":"notype","id":9,"name":"No Type"}'; exit 0 ;;
  *"users/advuser"*) echo '{"login":"advuser","id":55,"name":"A; B $x `z` \"q\"","type":"User"}'; exit 0 ;;
  # A User whose .id is null (non-integer) → login-only email fallback branch.
  # A User whose .name carries a real newline/CR (JSON escapes) → the python
  # collapse-to-space path. printf '%s' keeps the \n/\r literal in the arg so the
  # JSON parser (not the shell) produces the real control chars.
  *"users/noid"*)    printf '%s\n' '{"login":"noid","id":null,"name":"No Id","type":"User"}'; exit 0 ;;
  *"users/nlname"*)  printf '%s\n' '{"login":"nlname","id":88,"name":"A\nB\rC","type":"User"}'; exit 0 ;;
  *"users/boom"*)    echo "gh: network error" >&2; exit 1 ;;
esac
echo "stub: unhandled gh call: $a" >&2; exit 1
I682STUB
  chmod +x "$I682_D/gh"

  # Canonicalize heredoc-form stdin into "KEY=VALUE;…" (single-line values, which is
  # what the helper emits — a value's newlines are collapsed by the helper).
  _i682_canon() {
    local line key val out='' state=0
    while IFS= read -r line; do
      if [ "$state" -eq 0 ]; then
        case "$line" in
          GIT_*'<<'*) key="${line%%<<*}"; state=1 ;;
        esac
      elif [ "$state" -eq 1 ]; then
        val="$line"; state=2
      else
        # closing delimiter line
        if [ -z "$out" ]; then out="$key=$val"; else out="$out;$key=$val"; fi
        state=0
      fi
    done
    printf '%s' "$out"
  }
  _i682_run() {  # cfgjson login -> "rc|canonicalized-identity"
    local _json="$1" _login="$2" _out _rc _canon
    printf '%s' "$_json" > "$I682_D/cfg.json"
    _out="$(DEVFLOW_GH="$I682_D/gh" bash "$I682_HELPER" --login "$_login" --config-file "$I682_D/cfg.json" 2>/dev/null)"
    _rc=$?
    _canon="$(printf '%s\n' "$_out" | _i682_canon)"
    printf '%s|%s' "$_rc" "$_canon"
  }

  _I682_HUMAN='GIT_AUTHOR_NAME=Alice Example;GIT_COMMITTER_NAME=Alice Example;GIT_AUTHOR_EMAIL=12345+alice@users.noreply.github.com;GIT_COMMITTER_EMAIL=12345+alice@users.noreply.github.com'
  # Enabled + confirmed human → the four vars with the canonical <id>+<login> email.
  assert_eq "#682: enabled (boolean true) + human → four GIT_* vars, canonical email" "0|$_I682_HUMAN" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' alice)"
  # The JSON string "true" also enables (lockstep with emit-git-env.sh's gate).
  assert_eq "#682: enabled (string \"true\") + human → four GIT_* vars" "0|$_I682_HUMAN" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":"true"}}' alice)"
  # A User with a null .name uses the login as the name; email stays canonical.
  assert_eq "#682: human with null .name → login as name" \
    "0|GIT_AUTHOR_NAME=nullname;GIT_COMMITTER_NAME=nullname;GIT_AUTHOR_EMAIL=777+nullname@users.noreply.github.com;GIT_COMMITTER_EMAIL=777+nullname@users.noreply.github.com" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' nullname)"
  # gh-call failure for a not-non-human login → login-only fallback (still four vars).
  assert_eq "#682: gh api failure (unclassified) → login-only fallback, four vars" \
    "0|GIT_AUTHOR_NAME=boom;GIT_COMMITTER_NAME=boom;GIT_AUTHOR_EMAIL=boom@users.noreply.github.com;GIT_COMMITTER_EMAIL=boom@users.noreply.github.com" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' boom)"
  # Non-human / non-User / bot / empty-login → emit NOTHING (fall back to current authorship).
  assert_eq "#682: non-User type (Organization) → emits nothing" "0|" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' orgx)"
  assert_eq "#682: a .type that cannot be established → emits nothing" "0|" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' notype)"
  assert_eq "#682: a [bot] login → emits nothing (no login-only fallback for a bot)" "0|" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' 'dependabot[bot]')"
  assert_eq "#682: an empty triggering login → emits nothing, exit 0" "0|" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' '')"
  # A [bot] login warns and never even calls the stub (which would fail on it).
  printf '%s' '{"prflow":{"attribute_commits_to_triggerer":true}}' > "$I682_D/cfg.json"
  assert_eq "#682: a [bot] login emits a ::warning:: naming the bot suffix" "yes" \
    "$(DEVFLOW_GH="$I682_D/gh" bash "$I682_HELPER" --login 'dependabot[bot]' --config-file "$I682_D/cfg.json" 2>&1 >/dev/null \
       | grep -q "\[bot\]' suffix" && echo yes || echo no)"

  # The six-shape adversarial config-JSON matrix (CLAUDE.md's best-effort-parser rule)
  # applied to the `devflow` CONTAINER and the flag LEAF, plus the type-boundary
  # fixtures. Every shape must exit 0 and emit NOTHING (enabled ONLY for true/"true").
  # The valid-falsy row is load-bearing (an explicit false must not coerce to enabled).
  for _shape in \
    'flag-boolean-false:{"prflow":{"attribute_commits_to_triggerer":false}}' \
    'flag-json-null:{"prflow":{"attribute_commits_to_triggerer":null}}' \
    'flag-absent:{"prflow":{}}' \
    'flag-number-1:{"prflow":{"attribute_commits_to_triggerer":1}}' \
    'flag-string-True:{"prflow":{"attribute_commits_to_triggerer":"True"}}' \
    'flag-array-true:{"prflow":{"attribute_commits_to_triggerer":[true]}}' \
    'flag-object:{"prflow":{"attribute_commits_to_triggerer":{"enabled":true}}}' \
    'container-non-object:{"prflow":42}' \
    'container-missing:{}' \
    ; do
    assert_eq "#682: config shape '${_shape%%:*}' → exit 0, emits nothing (enabled only for true/\"true\")" "0|" \
      "$(_i682_run "${_shape#*:}" alice)"
  done
  # An unparseable / nonexistent config → disabled, exit 0, emits nothing.
  printf 'not json {{{' > "$I682_D/cfg.json"
  assert_eq "#682: an unparseable config → exit 0, emits nothing" "0|" \
    "$(_out="$(DEVFLOW_GH="$I682_D/gh" bash "$I682_HELPER" --login alice --config-file "$I682_D/cfg.json" 2>/dev/null)"; printf '%s|%s' "$?" "$(printf '%s\n' "$_out" | _i682_canon)")"
  assert_eq "#682: a nonexistent config file → exit 0, emits nothing" "0|" \
    "$(_out="$(DEVFLOW_GH="$I682_D/gh" bash "$I682_HELPER" --login alice --config-file "$I682_D/absent.json" 2>/dev/null)"; printf '%s|%s' "$?" "$(printf '%s\n' "$_out" | _i682_canon)")"

  # Adversarial-input case: a login/name carrying quotes, `$`, `;`, and backticks
  # cannot split or forge a further $GITHUB_ENV line — the heredoc framing holds, so
  # the value round-trips intact as a single GIT_AUTHOR_NAME value. The emitted block
  # must parse to exactly the four vars (no injected fifth assignment).
  assert_eq "#682: an adversarial display name round-trips through the heredoc form (no line forging)" \
    "0|GIT_AUTHOR_NAME=A; B \$x \`z\` \"q\";GIT_COMMITTER_NAME=A; B \$x \`z\` \"q\";GIT_AUTHOR_EMAIL=55+advuser@users.noreply.github.com;GIT_COMMITTER_EMAIL=55+advuser@users.noreply.github.com" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' advuser)"
  # A confirmed User whose .id is not an integer (null here) → login-only email
  # fallback (name is still the display name, email degrades to <login>@… since
  # there is no numeric id for the canonical <id>+<login>@… form).
  assert_eq "#682: a User with a non-integer .id → login-only email, display name kept" \
    "0|GIT_AUTHOR_NAME=No Id;GIT_COMMITTER_NAME=No Id;GIT_AUTHOR_EMAIL=noid@users.noreply.github.com;GIT_COMMITTER_EMAIL=noid@users.noreply.github.com" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' noid)"
  # A display name carrying a real newline/CR — the actual $GITHUB_ENV line-forging
  # vector — is collapsed to spaces by the helper's python step, so the emitted
  # block still parses to exactly the four vars (the collapse code path, not just
  # shell-metacharacter safety).
  assert_eq "#682: a display name with a real newline is collapsed (heredoc block stays exactly four vars)" \
    "0|GIT_AUTHOR_NAME=A B C;GIT_COMMITTER_NAME=A B C;GIT_AUTHOR_EMAIL=88+nlname@users.noreply.github.com;GIT_COMMITTER_EMAIL=88+nlname@users.noreply.github.com" \
    "$(_i682_run '{"prflow":{"attribute_commits_to_triggerer":true}}' nlname)"

  rm -rf "$I682_D"
fi

# ── issue #338: --rewrite-ac (post-merge) retag requires a --note rationale ────
# scripts/workpad.py: an `update` call in which any --rewrite-ac pair APPENDS the
# trailing (post-merge) tag (NEW ends with it after rstrip; neither OLD nor the row
# the pair resolves to already does) and which carries no non-empty --note aborts
# STRUCTURALLY — _UpdateError, exit 1, stderr naming the offending pair, NO PATCH
# issued (all-or-nothing preserved). The same call with a non-empty --note succeeds.
# A pair targeting a row that already ends with the tag, or that removes it, needs no
# note. Exercised as a real CLI subprocess against a gh stub, mirroring the #258
# fixture pattern. T1/T4/T5 go RED against the pre-guard workpad.py (the laundered
# tag PATCHed with no rationale); T2/T3/T3c/T5b are pass controls.
S338="$(mktemp -d)"
cat > "$S338/gh" <<'STUB'
#!/usr/bin/env bash
# Minimal gh stub for workpad.py update: repo view, comments list (marker match),
# body fetch, and PATCH (records that a PATCH happened + echoes the patched body).
j="$*"
if [[ "$j" == *"repo view"* ]]; then echo "owner/repo"; exit 0; fi
if [[ "$j" == *"-X PATCH"* ]]; then
  echo p >> "$WP_PATCHLOG"
  for a in "$@"; do case "$a" in body=@*) cat "${a#body=@}";; esac; done
  exit 0
fi
if [[ "$j" == *"issues/comments/7"* ]]; then cat "$WP_BODY"; exit 0; fi
if [[ "$j" == *"issues/999/comments"* ]]; then echo '[{"id":7,"body":"<!-- devflow:workpad -->"}]'; exit 0; fi
echo '[]'
STUB
chmod +x "$S338/gh"

cat > "$S338/base.md" <<'WPMD'
<!-- devflow:workpad -->
# DevFlow Workpad — Issue #999

**Status:** 🚀 Reviewing
**Last updated:** 2026-05-15T00:00:00Z

## Progress
- [ ] **Review**

## Plan
- [x] Plan step one

## Acceptance Criteria
- [ ] AC one
- [ ] AC two
WPMD
# A fixture whose AC two already carries the (post-merge) tag (for the OLD-already-tagged case).
sed 's/- \[ \] AC two/- [ ] AC two (post-merge)/' "$S338/base.md" > "$S338/base-tagged.md"
# A fixture carrying a `## Devflow Reflection` section, so a --reflection is a VALID
# mutation on it. Without that section --reflection aborts on 'section not found', and a
# test asserting "a reflection does not satisfy the --note" would pass for that unrelated
# reason — staying green against a mutant that lets a reflection satisfy the guard (T4d).
cp "$S338/base.md" "$S338/base-refl.md"
printf '\n## Devflow Reflection\n- existing bullet\n' >> "$S338/base-refl.md"
# A fixture whose AC two is already TICKED (`- [x]`). The retag guards must treat a
# ticked row's tag exactly like an unticked one: `- [x]` rows are outside the Phase 3.4
# terminal gate's population, but a `(post-merge)` tag landing on one is still a net-added
# tagged row, and SKILL.md/DEVFLOW_SYSTEM_OVERVIEW both promise a crafted multi-pair
# sequence that net-adds such a row is caught.
sed 's/- \[ \] AC two/- [x] AC two/' "$S338/base.md" > "$S338/base-ticked.md"
# ...and one whose ticked AC two is already tagged (for the tag-preserving no-false-fire control).
sed 's/- \[ \] AC two/- [x] AC two (post-merge)/' "$S338/base.md" > "$S338/base-ticked-tagged.md"

# These cases turn on whether the call carries a non-empty --note, and issue #1214's
# replay FOLDS a buffered note into `args.note` — so a replay buffer left over for the
# comment id this block's stub answers with (7) would satisfy the very guard T1 asserts
# fires. The producing block reclaims its own buffer; clear it here too so this block's
# precondition is stated where it is relied on rather than 700 lines away.
rm -f "$LIB/../.prflow/tmp/workpad-buffer/7.json"

# run338 <body-file> <args...> → prints the exit code; leaves out/err/patchlog on disk.
run338() {
  local body="$1"; shift
  : > "$S338/patchlog"
  WP_BODY="$body" WP_PATCHLOG="$S338/patchlog" DEVFLOW_GH="$S338/gh" \
    python3 "$WP_PY" update 999 --print-body "$@" >"$S338/out" 2>"$S338/err"
  echo $?
}

# T1 (refusal — reproduces the defect): appending pair, no --note → abort, NO PATCH.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two (post-merge)")"
assert_eq "#338(T1): appending (post-merge) retag with no --note aborts non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T1): the refusal made NO PATCH (all-or-nothing)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T1): the refusal names the offending pair on stderr" "yes" \
  "$(grep -q 'AC two' "$S338/err" && grep -q 'post-merge' "$S338/err" && echo yes || echo no)"

# T2 (pass with note): identical call + non-empty --note → exit 0, row rewritten.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two (post-merge)" \
  --note "retro-tagged as post-merge (genuinely-live): live deploy target")"
assert_eq "#338(T2): the same retag WITH a non-empty --note succeeds (exit 0)" "0" "$_c"
assert_eq "#338(T2): the with-note retag PATCHed the row with the (post-merge) tag" "yes" \
  "$([ -s "$S338/patchlog" ] && grep -q '\- \[ \] AC two (post-merge)' "$S338/out" && echo yes || echo no)"

# T2b (note scope is the CALL, not the pair): the guard's documented contract is that ANY
# one non-empty --note in the same update call satisfies it, whether or not the note is
# *about* the retag — the note is appended to ## Progress, never bound to the rewritten
# row, so the guard enforces that a rationale EXISTS for the retrospective auditor to
# read, not that it is true or on-topic. This batched call carries a note describing the
# OTHER pair (the plain AC one rewrite) and never mentions the tag or the retagged row,
# and must still pass. Without this pin a refactor that bound the note to the specific
# appending pair would tighten the contract past what workpad.py's guard comment,
# SKILL.md, and docs/internal/implement-skill.md all promise, while every other S338 test — whose
# notes all happen to describe the retag itself — stayed green. Compare T5: the same
# batched shape with NO note is refused.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC one" "AC one edited" \
  --rewrite-ac "AC two" "AC two (post-merge)" \
  --note "reworded the first criterion for clarity")"
assert_eq "#338(T2b): an appending retag is satisfied by any non-empty --note in the call, even one about an unrelated pair (exit 0)" "0" "$_c"
assert_eq "#338(T2b): the call-scoped-note retag PATCHed the (post-merge) row" "yes" \
  "$([ -s "$S338/patchlog" ] && grep -q '\- \[ \] AC two (post-merge)' "$S338/out" && echo yes || echo no)"
assert_eq "#338(T2b): the unrelated pair in the same call applied too" "yes" \
  "$(grep -q '\- \[ \] AC one edited' "$S338/out" && echo yes || echo no)"

# T3 (no false fire): OLD already ends with the tag → a text tweak needs no note.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two reworded (post-merge)")"
assert_eq "#338(T3): a rewrite whose OLD already ends with (post-merge) passes with no note (exit 0)" "0" "$_c"
assert_eq "#338(T3): the tag-preserving rewrite PATCHed" "yes" \
  "$([ -s "$S338/patchlog" ] && echo yes || echo no)"

# T4 (empty note): --note "" with an appending pair is a MISSING rationale → refused.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two (post-merge)" --note "")"
assert_eq "#338(T4): an empty-string --note is treated as missing → refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T4): the empty-note refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"

# T5 (all-or-nothing): a mixed repeatable call (one appending pair among a plain
# rewrite), no note, is refused BEFORE any PATCH — no partial application.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC one" "AC one edited" \
  --rewrite-ac "AC two" "AC two (post-merge)")"
assert_eq "#338(T5): a mixed call with one appending pair, no note, aborts non-zero" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T5): the mixed-call refusal made NO PATCH (the plain rewrite did not partially apply)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"

# T5b (guard + backstop no FALSE FIRE): an ordinary batched multi-pair rewrite that never
# touches the (post-merge) tag needs no note and must apply in full. Pins the innocent
# path both guards share: a regression that miscounted a plain row as post-merge-terminal
# (or classified a plain pair as an append) would abort an honest batch, and no other
# S338 test would notice — every one of them either carries a note or expects a refusal.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC one" "AC one edited" \
  --rewrite-ac "AC two" "AC two edited")"
assert_eq "#338(T5b): an ordinary batched no-note rewrite that never touches the tag succeeds (exit 0)" "0" "$_c"
assert_eq "#338(T5b): both pairs of the innocent batch applied" "yes" \
  "$([ -s "$S338/patchlog" ] && grep -q '\- \[ \] AC one edited' "$S338/out" \
     && grep -q '\- \[ \] AC two edited' "$S338/out" && echo yes || echo no)"

# T3b (removal pair — documented no-note case, unpinned until now): NEW lacks the tag
# and OLD ends with it (de-tagging an already-post-merge row) needs no note. Pins the
# predicate's first-conjunct-False path (no current test drives it: T1/T2/T3 all have NEW
# ending in the marker), so a refactor that fired on any tag *movement* would go RED here.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two")"
assert_eq "#338(T3b): a rewrite that REMOVES the (post-merge) tag passes with no note (exit 0)" "0" "$_c"
assert_eq "#338(T3b): the tag-removing rewrite PATCHed" "yes" \
  "$([ -s "$S338/patchlog" ] && echo yes || echo no)"

# T3c (no false REFUSAL — the guard reasons over the RESOLVED ROW, not the OLD string):
# a text tweak on a row that ALREADY ends with the tag creates no new deferral, so it
# needs no note — even when the OLD substring does not itself span the tag. The
# argument-string-only predicate classified this as an append and demanded a --note,
# contradicting the exemption workpad.py's docstring, SKILL.md and docs/internal/implement-skill.md
# all publish. Fails CLOSED (an extra-note demand, never a laundered deferral), but the
# published contract must match the code. RED against the OLD-string-only predicate.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two" "AC two clarified (post-merge)")"
assert_eq "#338(T3c): a tweak on an already-(post-merge) row needs no note even when OLD omits the tag (exit 0)" "0" "$_c"
assert_eq "#338(T3c): the already-tagged-row tweak PATCHed the reworded row" "yes" \
  "$([ -s "$S338/patchlog" ] && grep -q '\- \[ \] AC two clarified (post-merge)' "$S338/out" && echo yes || echo no)"
# Control: the SAME shape onto an UNTAGGED row is still refused — the exemption is bound
# to the target row's existing tag, not to the OLD substring being a prefix.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC one" "AC one clarified (post-merge)")"
assert_eq "#338(T3c): the same shape onto an UNTAGGED row is still refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T3c): the untagged-row refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"

# T4b (trailing-whitespace anti-evasion — the reason the predicate rstrips): an appending
# pair whose NEW ends with the tag plus trailing spaces is still an append and is refused
# with no note. Pins the rstrip; a bare endswith (no rstrip) would let this evasion through
# while every other S338 test stayed green.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two (post-merge)   ")"
assert_eq "#338(T4b): an appending pair with trailing whitespace after the tag is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T4b): the trailing-whitespace-append refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"

# T4c (note-side anti-evasion — the discriminating input that actually pins `.strip()`):
# T4's `--note ""` does NOT pin it — `any([""])` is already falsy, so T4 stays GREEN
# against a mutant `has_note = any(n for n in args.note)`. A whitespace-only note is the
# input that separates them: truthy as a bare string, falsy after `.strip()`. Mutation-
# checked — dropping `.strip()` turns THIS assertion RED while T4 stays GREEN.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two (post-merge)" --note "   ")"
assert_eq "#338(T4c): a whitespace-only --note is treated as missing → refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T4c): the whitespace-note refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"

# T4d (only --note satisfies the rationale): a --reflection is a different channel
# (## Devflow Reflection) and never stands in for the retag rationale. Without this pin a
# refactor broadening has_note to accept a reflection would loosen the contract while
# every other S338 test stayed green. Runs against base-refl.md — the fixture that HAS a
# ## Devflow Reflection section — so the reflection is a valid mutation and the refusal is
# attributable to the guard; on a section-less fixture this test would pass vacuously via
# 'section not found'. The stderr assertion pins that attribution (cf. T7's 'net-adds').
_c="$(run338 "$S338/base-refl.md" --rewrite-ac "AC two" "AC two (post-merge)" \
  --reflection "retro-tagged as post-merge (genuinely-live): live deploy target")"
assert_eq "#338(T4d): a --reflection does not satisfy the --note rationale → refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T4d): the reflection-only refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T4d): the refusal is the rationale guard's, not an incidental section abort" "yes" \
  "$(grep -q 'no non-empty --note rationale' "$S338/err" && echo yes || echo no)"
# Control: the same call on the same fixture WITH a --note succeeds — proving base-refl.md
# is not itself the reason T4d is refused (the reflection applies cleanly alongside).
_c="$(run338 "$S338/base-refl.md" --rewrite-ac "AC two" "AC two (post-merge)" \
  --reflection "context bullet" --note "genuinely-live: live deploy target")"
assert_eq "#338(T4d): the same reflection call WITH a --note succeeds (exit 0)" "0" "$_c"

# T7 (state-based multi-pair backstop, issue #338 hardening): a crafted two-pair call whose
# pairs each individually dodge the per-pair guard — pair 1 places the marker non-terminally
# (NEW doesn't end in the tag), pair 2 makes it terminal (OLD ends in the tag) — net-adds a
# (post-merge) row. The per-pair guard alone would fail OPEN here; the post-loop count-of-
# post-merge-rows backstop catches it and aborts before any PATCH. RED against the pre-
# backstop code (the laundered tag PATCHes with no note).
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "(post-merge) AC two" \
  --rewrite-ac "(post-merge)" "AC two (post-merge)")"
assert_eq "#338(T7): a multi-pair call that net-adds a (post-merge) row with no note is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T7): the multi-pair backstop refusal made NO PATCH (all-or-nothing)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
# Assert the refusal came from the STATE BACKSTOP ('net-adds'), not an incidental
# _rewrite_checkbox zero/multi-match abort — so a refactor that made this call fail for
# the wrong reason (while the backstop silently rotted) is caught, not masked by T7b.
assert_eq "#338(T7): the refusal is the state backstop's 'net-adds' abort, not an incidental match failure" "yes" \
  "$(grep -q 'net-adds' "$S338/err" && echo yes || echo no)"
# T7b (backstop no false fire): the identical multi-pair call WITH a non-empty --note succeeds.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "(post-merge) AC two" \
  --rewrite-ac "(post-merge)" "AC two (post-merge)" --note "retro-tagged (genuinely-live): live endpoint")"
assert_eq "#338(T7b): the same multi-pair retag WITH a --note succeeds (exit 0)" "0" "$_c"

# T8 (single-pair append onto an already-TICKED row): the per-pair guard is tick-state
# agnostic — it reasons over the row's LABEL text, which `_CHECKBOX_ROW_RE` exposes
# independently of the `[ ]`/`[x]` state cell — so this is refused with no note. Behavior
# was already correct but unpinned; without this a refactor that skipped `[x]` rows in the
# per-pair guard (to "match" the backstop's old unticked-only population) would go
# unnoticed by every other S338 test, all of which drive `- [ ]` rows.
#
# ATTRIBUTION IS LOAD-BEARING HERE, not decoration. Since the backstop now also counts
# ticked rows, a mutant that skips `[x]` rows in the per-pair guard STILL exits non-zero
# with no PATCH — the backstop catches it one step later. rc/no-PATCH assertions alone
# therefore pass on the very mutant this test exists to kill. Pin the refusal to the
# PER-PAIR guard: its message names the offending pair, and it never says `net-adds` (the
# backstop's word). Both attribution assertions below independently kill that mutant — the
# backstop's message omits the pair AND says `net-adds` — while the rc/no-PATCH assertions
# alone stay GREEN on it. Note the backstop's message also contains the phrase
# `no non-empty --note rationale`, so that substring alone does not discriminate; the
# pair name is what does.
_c="$(run338 "$S338/base-ticked.md" --rewrite-ac "AC two" "AC two (post-merge)")"
assert_eq "#338(T8): a single-pair (post-merge) append onto a TICKED [x] row is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T8): the ticked-row single-pair refusal made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T8): the refusal is the PER-PAIR guard's (names the pair + rationale), not the backstop's" "yes" \
  "$(grep -q 'AC two' "$S338/err" && grep -q 'no non-empty --note rationale' "$S338/err" && echo yes || echo no)"
assert_eq "#338(T8): the per-pair guard — not the state backstop — refused (stderr has no 'net-adds')" "yes" \
  "$(grep -q 'net-adds' "$S338/err" && echo no || echo yes)"

# T8b (the ticked-row SHUTTLE — the fail-open this backstop population closes): the same
# crafted two-pair shuttle as T7, aimed at an already-`[x]` row. Both pairs dodge the
# per-pair guard exactly as in T7; with the backstop counting only UNTICKED rows the
# tagged row landed with NO note and exit 0, silently falsifying SKILL.md's and
# DEVFLOW_SYSTEM_OVERVIEW's promise that "a crafted multi-pair sequence that net-adds a
# (post-merge) row is caught by the same rule". Snapshotting each row's post-merge-terminal
# flag across EVERY tick state (`_post_merge_flags`) closes it. RED against the
# unticked-only population; the 'net-adds' grep pins that the STATE BACKSTOP is what
# refuses it (T8 already covers the per-pair path, so a refusal for the wrong reason would
# otherwise pass here).
_c="$(run338 "$S338/base-ticked.md" --rewrite-ac "AC two" "(post-merge) AC two" \
  --rewrite-ac "(post-merge)" "AC two (post-merge)")"
assert_eq "#338(T8b): a multi-pair shuttle that net-adds (post-merge) onto a TICKED row is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T8b): the ticked-row shuttle refusal made NO PATCH (all-or-nothing)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T8b): the ticked-row shuttle refusal is the state backstop's 'net-adds' abort" "yes" \
  "$(grep -q 'net-adds' "$S338/err" && echo yes || echo no)"
# T8c (no false fire on the widened population): a tag-PRESERVING tweak on an already-tagged
# TICKED row adds no tagged row, so the wider count must not fire — this is the assertion a
# naive "count every tagged row and abort on any tagged row present" backstop would fail.
_c="$(run338 "$S338/base-ticked-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two reworded (post-merge)")"
assert_eq "#338(T8c): a tag-preserving tweak on a TICKED tagged row still passes with no note (exit 0)" "0" "$_c"
assert_eq "#338(T8c): the ticked tag-preserving rewrite PATCHed" "yes" \
  "$([ -s "$S338/patchlog" ] && echo yes || echo no)"
# T8d (no false fire): REMOVING the tag from a ticked tagged row decreases the count → passes.
_c="$(run338 "$S338/base-ticked-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two")"
assert_eq "#338(T8d): removing the tag from a TICKED row passes with no note (exit 0)" "0" "$_c"

# T9 (net-zero tag-swap — the last laundering shape): remove the tag from one row while
# shuttling it onto ANOTHER, with no note. Every pair dodges the per-pair guard (pair 1
# removes; pair 2's NEW is non-terminal; pair 3's OLD ends with the tag), and the TOTAL
# count of tagged rows is unchanged — so an aggregate-count backstop reads "no net add"
# and PATCHes a silently-deferred criterion. Comparing each row's flag POSITIONALLY
# catches it: AC one transitions untagged -> terminally-tagged. RED against a count-based
# backstop (verified: it exits 0 and PATCHes `- [ ] AC one (post-merge)`).
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two" \
  --rewrite-ac "AC one" "(post-merge) AC one" \
  --rewrite-ac "(post-merge)" "AC one (post-merge)")"
assert_eq "#338(T9): a net-zero tag-swap onto another row is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T9): the net-zero tag-swap refusal made NO PATCH (all-or-nothing)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T9): the net-zero refusal is the state backstop's 'net-adds' abort" "yes" \
  "$(grep -q 'net-adds' "$S338/err" && echo yes || echo no)"
# T9b (no false fire): the identical net-zero swap WITH a --note succeeds.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two" \
  --rewrite-ac "AC one" "(post-merge) AC one" \
  --rewrite-ac "(post-merge)" "AC one (post-merge)" \
  --note "moved the deferral: AC one needs the live endpoint, AC two was verified")"
assert_eq "#338(T9b): the same net-zero swap WITH a --note succeeds (exit 0)" "0" "$_c"

# T10 (newline in NEW — the premise the positional comparison rests on): `_rewrite_checkbox`
# writes NEW verbatim into ONE line, so an embedded newline splits that checkbox row in two.
# That injects an unreviewed AC row AND breaks the row-index stability `_net_adds_post_merge`
# compares against. It also slips the per-pair guard, whose `NEW ends with the marker` test
# reads the whole string (`X (post-merge)\n- [ ] Y` ends with `Y`). Reject it structurally,
# note or not. RED against the pre-fix code, which exited 0 and PATCHed the injected row.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" 'AC two (post-merge)
- [ ] Injected')"
assert_eq "#338(T10): a --rewrite-ac NEW containing a line break is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T10): the line-break refusal made NO PATCH (no row injected)" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
assert_eq "#338(T10): the refusal names the line boundary, not the missing note" "yes" \
  "$(grep -q 'line boundary in NEW' "$S338/err" && echo yes || echo no)"
# T10a (the full `str.splitlines()` separator set — the superset bug): a `'\n' in s or
# '\r' in s` membership test accepts \v, \f, \x1c-\x1e, NEL, LS and PS, EVERY one of which
# `str.splitlines()` still splits on — so each injected a phantom `- [x]` row (with a
# --note, both post-merge guards are skipped, leaving the row check as the only defense).
# `_is_single_line` shares splitlines' own contract, so the rejected set matches exactly.
# Driven with a --note so a refusal cannot come from a post-merge guard. RED against the
# two-character membership test (all eight exited 0 and PATCHed an injected row).
# Interpreter note: `printf '%b'` must expand `\302\205` (NEL), `\342\200\250` (LS) and
# `\342\200\251` (PS) to their real bytes for the last three cases to drive a separator at
# all. Bash's printf does; zsh's does not — it emits the literal backslash text, which
# carries no separator, so workpad.py would accept the rewrite (exit 0) and these
# assertions would FAIL LOUDLY. They cannot degrade into a silent green. This suite's
# shebang is `#!/usr/bin/env bash`, so the expansion holds. Independently verified: under a
# membership-test mutant all eight — including these three — go RED, which they could not
# if their input carried no separator.
for _sep in '\v' '\f' '\034' '\035' '\036' '\302\205' '\342\200\250' '\342\200\251'; do
  _new="$(printf 'AC two (post-merge)%b- [x] Phantom' "$_sep")"
  _c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "$_new" --note "genuinely-live: endpoint")"
  assert_eq "#338(T10a): NEW split by separator '$_sep' is refused even with a --note" "no" \
    "$([ "$_c" = "0" ] && echo yes || echo no)"
  assert_eq "#338(T10a): separator '$_sep' injected no row (NO PATCH)" "yes" \
    "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
done
# T10b: a --note does NOT excuse it — the newline is a malformed argument, not a deferral.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" 'AC two (post-merge)
- [ ] Injected' --note "genuinely-live: live endpoint")"
assert_eq "#338(T10b): a line break in NEW is refused even WITH a --note (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
# T10c (the laundering combo the newline enabled): remove a tag from one row while
# newline-splitting another into a terminally-tagged row. Row counts differ, so an
# aggregate-count fallback reads the sum as flat and passes. Refused now — first by the
# newline check; and were that ever removed, _net_adds_post_merge's length-mismatch branch
# fails CLOSED rather than downgrading to the blind aggregate compare.
_c="$(run338 "$S338/base-tagged.md" --rewrite-ac "AC two (post-merge)" "AC two" \
  --rewrite-ac "AC one" 'AC one (post-merge)
- [ ] Injected')"
assert_eq "#338(T10c): a newline-split net-zero laundering combo is refused (non-zero)" "no" \
  "$([ "$_c" = "0" ] && echo yes || echo no)"
assert_eq "#338(T10c): the laundering combo made NO PATCH" "yes" \
  "$([ -s "$S338/patchlog" ] && echo no || echo yes)"
# T10d (no false fire): a NEW with ordinary internal whitespace (not a line break) is fine.
_c="$(run338 "$S338/base.md" --rewrite-ac "AC two" "AC two   with   spaces")"
assert_eq "#338(T10d): a NEW with internal spaces (no line break) still passes (exit 0)" "0" "$_c"

# Source pin: the length-mismatch branch fails CLOSED (returns True), never degrading to an
# aggregate `sum(post) > sum(pre)` compare that is blind to a remove-one/add-one swap.
assert_eq "#338: _net_adds_post_merge fails closed on a row-count mismatch (no aggregate fallback)" "yes" \
  "$(grep -q 'sum(post) > sum(pre)' "$WP_PY" && echo no || echo yes)"
# Source pin: the newline rejection guards the row-index-stability premise. Pin the SYMBOL,
# not the stderr wording — the message literal is an f-string wrapped across two source
# lines ("...has a line " / "boundary in NEW; ..."), so no single line contains the phrase
# whole and a source grep for it always fails. (That is the same wrapped-literal blind spot
# that let the argparse help text drift; the rendered-surface pins are the ones that catch
# wording, and T10 already asserts this message on real stderr.)
assert_eq "#338: --rewrite-ac structurally rejects a line break in NEW" "yes" \
  "$(grep -q 'offending_nl' "$WP_PY" && echo yes || echo no)"

# Source pin: the backstop's population spans every tick state AND compares positionally.
# A revert to `_unticked_rows(content)[1]` re-opens the T8b ticked-row fail-open; a revert
# to an aggregate count re-opens the T9 net-zero fail-open.
assert_eq "#338: the retag backstop snapshots per-row post-merge flags (not an aggregate count)" "yes" \
  "$(grep -q 'pre_pm = _post_merge_flags(content)' "$WP_PY" && echo yes || echo no)"
assert_eq "#338: the retag backstop compares those flags positionally via _net_adds_post_merge" "yes" \
  "$(grep -q '_net_adds_post_merge(pre_pm, _post_merge_flags(content))' "$WP_PY" && echo yes || echo no)"

# Source pin: the rationale-required guard + its predicate live in workpad.py.
assert_eq "#338: workpad.py carries the (post-merge)-retag rationale guard" "yes" \
  "$(grep -q '_pair_appends_post_merge' "$WP_PY" && echo yes || echo no)"
# Source pin: the guard SHARES the rewriter's row resolution (parse, don't validate)
# rather than re-deriving the target row from the OLD argument string. A revert to the
# two-argument, string-only predicate re-introduces the T3c false refusal.
assert_eq "#338: the retag guard resolves the target row via _find_checkbox_row" "yes" \
  "$(grep -q '_find_checkbox_row' "$WP_PY" && echo yes || echo no)"
# Coupled-invariant pin: SKILL.md publishes the row-scoped --rewrite-ac exemption
# (not the stale OLD-only form). Edited in lockstep with the predicate above.
assert_eq "#338: SKILL.md publishes the row-scoped (post-merge) exemption" "yes" \
  "$(grep -q 'neither OLD nor the row it targets already does' \
       "$LIB/../skills/implement/SKILL.md" && echo yes || echo no)"
# ...and the NEGATIVE half. `grep -q` reports presence, not exhaustiveness, so the positive
# assertion above can stay GREEN across a partial reversion to the stale OLD-only form.
# The positive half also reads only skills/implement/SKILL.md, so a reversion confined to the
# docs mirror is invisible to it. Asserting the stale form is ABSENT catches a reversion in
# either file the loop below covers — and does so without a brittle occurrence-count pin that
# a further legitimate mention would break.
for _f338 in "$LIB/../skills/implement/SKILL.md" "$LIB/../docs/internal/implement-skill.md"; do
  assert_eq "#338: $(basename "$_f338") carries no stale OLD-only (post-merge) contract sentence" "yes" \
    "$(grep -q 'NEW ends with it, OLD does not' "$_f338" && echo no || echo yes)"
done
# Coupled-invariant pin on the RENDERED CLI surface. workpad.py's --rewrite-ac argparse
# help is a third mirror of the guard contract, and it is the one a plain source grep for
# the contract sentence MISSES: argparse help is assembled from adjacent string literals,
# so the phrase wraps across lines ('... OLD does ' 'not)') and no line contains it whole.
# Pin what the user actually reads — `update --help` — so a stale OLD-only help text turns
# the suite RED. Asserts the row-scoped phrasing is present AND the stale form is gone.
_h338="$(python3 "$WP_PY" update --help 2>&1)"
assert_eq "#338: workpad.py --rewrite-ac help publishes the row-scoped exemption" "yes" \
  "$(printf '%s' "$_h338" | tr -s '[:space:]' ' ' \
     | grep -q 'neither OLD nor the row it targets already does' && echo yes || echo no)"
assert_eq "#338: workpad.py --rewrite-ac help no longer carries the stale OLD-only form" "yes" \
  "$(printf '%s' "$_h338" | tr -s '[:space:]' ' ' \
     | grep -q 'NEW ends with it, OLD does not' && echo no || echo yes)"
assert_eq "#338: workpad.py --rewrite-ac help states a --reflection does not satisfy the note" "yes" \
  "$(printf '%s' "$_h338" | tr -s '[:space:]' ' ' \
     | grep -q 'Only --note satisfies the rationale; a --reflection does not' && echo yes || echo no)"
assert_eq "#338: workpad.py --rewrite-ac help states NEW must be a single line" "yes" \
  "$(printf '%s' "$_h338" | tr -s '[:space:]' ' ' \
     | grep -q 'NEW must be a single line' && echo yes || echo no)"

# T6: exact-one check for the operative third forbidden case in phase-3-review.md §3.4;
# deletion or duplication fails.
P3REVIEW="$LIB/../skills/implement/phases/phase-3-ac-gate.md"
assert_pin_unique "#338(T6): §3.4 pins the operative sentence of the self-reconfiguration forbidden case" \
  'is runnable on this host and is never `(post-merge)`' "$P3REVIEW"  # structural-pin-ok: lifecycle-state-transition -- the self-reconfiguration forbidden case bounds the (post-merge) deferral
rm -rf "$S338"

# ── Issue #345: pre-merge probe contract before any (post-merge) AC deferral ──
# Coupled-invariant pins: the probe contract is stated once in phase-3-review.md
# (Phase 3.4, alongside the genuinely-live test + retro-tag path) and referenced
# from phase-1-setup.md (Phase 1.2 partial-live rule). Both mirror sites and these
# pins land in one commit. Each exact-one check preserves its obligation independently.
P345_P3="$IMPL_PHASES_DIR/phase-3-ac-gate.md"
P345_P1="$IMPL_PHASES_DIR/phase-1-setup.md"
# AC1: the contract exists in phase-3-review.md and the retro-tag path runs it,
# recording each probe command + observed result (or the empty-set finding).
assert_pin_unique "#345 AC1: phase-3-review.md states the Pre-merge probe contract before any (post-merge) tag/retag" \
  'Pre-merge probe contract (mandatory before any' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- the pre-merge probe gate precedes any (post-merge) tag
# AC1 operative step 1 (decompose) — checked independently of the section header.
assert_pin_unique "#345 AC1: the contract's step 1 decomposes into pre-merge-observable preconditions" \
  '**Decompose** the criterion into **(a) pre-merge-observable preconditions**' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- the deferral protocol's precondition-decomposition step
# AC1 operative step 3 (non-empty record obligation) — the auditable-record requirement
# that IS the point of the AC; pinning only its empty-set branch left this desync-open.
assert_pin_unique "#345 AC1: the contract records each probed precondition + command + observed result in the deferral note" \
  'Record each probed precondition, the probe command, and its observed result in the deferral' "$P345_P3"  # structural-pin-ok: schema-config-vocabulary -- the deferral note's probe-evidence record shape
assert_pin_unique "#345 AC1: the retro-tag path runs the probe contract before the retag lands" \
  'Before the retag lands, run the Pre-merge probe contract above' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- the retag path runs the probe contract before the retag lands
assert_pin_unique "#345 AC1: the empty observable-precondition set is a legal, explicitly recordable finding" \
  'when the observable set is genuinely empty, the explicit finding' "$P345_P3"  # structural-pin-ok: schema-config-vocabulary -- an empty observable set is an explicitly recordable finding
# AC2: an observed-cannot-succeed probe routes to a pre-merge fix or the Blocked
# path (never a deferral), and the red-flags STOP list forbids the launder.
assert_pin_unique "#345 AC2: an observed-cannot-succeed probe routes to a pre-merge fix or the Blocked path, never a deferral" \
  'cannot succeed as shipped routes to a pre-merge fix or the Blocked path (step 4 below) — never a deferral' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- a cannot-succeed criterion routes to a pre-merge fix or Blocked, never a deferral
assert_pin_unique "#345 AC2: the red-flags STOP list forbids a deferral over a failed probe" \
  'observed-cannot-succeed probe: **never** a deferral' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- a failed probe is never a deferral
# AC1/AC2 operative step 2 (probe read-only) — checked independently of decompose+record.
assert_pin_unique "#345 AC1: the contract's step 2 mandates probing every precondition read-only" \
  '**Probe every (a) precondition read-only**' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- every (a) precondition is probed read-only
# AC2 reverse-launder guard (step 5): a denial must be an inability to observe the
# state, NOT a non-zero gh-api exit carrying an observed-false answer (404/empty). This
# is the dual of the observed-cannot-succeed routing; unpinned it fails OPEN silently.
assert_pin_unique "#345 AC2: step 5 keys denial on whether the probe obtained a definitive answer, not raw exit status (no reverse launder)" \
  'Tell the two apart by whether the probe obtained a definitive answer about the precondition' "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- denial keys on a definitive probe answer, not on raw exit status
# AC3: the probe obligation includes issue-named failure modes for the mechanism.
assert_pin_unique "#345 AC3: the probe set must include any issue-named failure mode for the criterion's mechanism" \
  "any failure mode the linked issue's Potential Gotchas or Implementation Notes names for that criterion's mechanism" "$P345_P3"  # structural-pin-ok: lifecycle-state-transition -- the probe set includes each issue-named failure mode for that mechanism
# AC4: phase-1-setup.md states a passed probe never ticks the AC box.
assert_pin_unique "#345 AC4: phase-1-setup.md states a passed probe never ticks the AC box" \
  'A passed probe never ticks the AC box' "$P345_P1"
# AC4 coupled-invariant: the passed-probe-never-ticks clause also lives in phase-3's
# contract (step 6); pin the phase-3 side too so removing it there turns the suite RED
# (the two files are a stated single-source-of-truth pair).
assert_pin_unique "#345 AC4: phase-3-review.md's contract step 6 also states a passed probe never ticks the AC box" \
  'A passed probe never ticks the AC box' "$P345_P3"  # structural-pin-ok: routing-dispatch-contract -- #345 AC4 a passed probe never ticks the AC box

# ── Issue #184: Phase 1.6 Issue-Claim Audit ──────────────────────────────
# The audit heading retains its removal guard; the ordinary prose-only existence
# assertions in this group were retired.
# ── issue #547 RED: early declared-dependency preflight helper ──────────────
# The gate must distinguish explicit dependency declarations from ordinary
# provenance references before Phase 1 touches a branch.  Keep this executable
# contract beside the legacy #254 pins while the procedure moves to §1.3.5.
P547D="$(mktemp -d)"
mkdir -p "$P547D/bin"
cat > "$P547D/bin/gh" <<'EOF'
#!/usr/bin/env bash
case "${3:-}" in
  10) printf '%s\n' OPEN ;;
  11) printf '%s\n' CLOSED ;;
  12) printf '%s\n' MERGED ;;
  13) exit 1 ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$P547D/bin/gh"
printf '%s\n' 'Blocked by #10 — prerequisite' > "$P547D/open.md"
printf '%s\n' 'Depends on #11 and #12' > "$P547D/landed.md"
printf '%s\n' 'Related work: #10 is provenance only' > "$P547D/provenance.md"
printf '%s\n' '## Dependencies' '- #13 — unresolved' > "$P547D/unresolved.md"
P547_HELPER="$LIB/../scripts/preflight.py"
P547_OPEN="$(PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies --body-file "$P547D/open.md" 2>/dev/null)"; P547_OPEN_RC=$?
P547_LANDED="$(PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies --body-file "$P547D/landed.md" 2>/dev/null)"; P547_LANDED_RC=$?
P547_PROVENANCE="$(PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies --body-file "$P547D/provenance.md" 2>/dev/null)"; P547_PROVENANCE_RC=$?
P547_UNRESOLVED="$(PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies --body-file "$P547D/unresolved.md" 2>/dev/null)"; P547_UNRESOLVED_RC=$?
assert_eq "#547 RED: OPEN dependency blocks before branch setup" "BLOCKED 10" "$P547_OPEN"
assert_eq "#547 RED: OPEN dependency returns the blocked exit class" "2" "$P547_OPEN_RC"
assert_eq "#547 RED: closed and merged dependencies proceed" "PROCEED 11,12" "$P547_LANDED"
assert_eq "#547 RED: landed dependencies return success" "0" "$P547_LANDED_RC"
assert_eq "#547 RED: provenance references are not dependencies" "PROCEED" "$P547_PROVENANCE"
assert_eq "#547 RED: provenance references return success" "0" "$P547_PROVENANCE_RC"
assert_eq "#547 RED: unresolvable dependency is unavailable" "UNAVAILABLE 13" "$P547_UNRESOLVED"
assert_eq "#547 RED: unresolvable dependency returns unavailable exit class" "3" "$P547_UNRESOLVED_RC"
# An unreadable --body-file is the read-failure UNAVAILABLE arm (distinct from the
# state-resolution UNAVAILABLE above): the helper must fail closed to the same
# terminal-Blocked class, never read as a clean dependency set.
P547_BADFILE="$(PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies --body-file "$P547D/does-not-exist.md" 2>/dev/null)"; P547_BADFILE_RC=$?
assert_eq "#547 RED: unreadable --body-file is unavailable (read-failure arm)" "UNAVAILABLE body" "$P547_BADFILE"
assert_eq "#547 RED: unreadable --body-file returns the unavailable exit class" "3" "$P547_BADFILE_RC"
# A malformed invocation (missing input flag) must NOT exit with argparse's default
# code 2 — that is the BLOCKED contract code the §1.3.5 gate maps to "open
# dependencies", which would misdiagnose a bad argument as a real blocker. The
# _Parser override routes usage errors to the UNAVAILABLE class (exit 3) instead.
PATH="$P547D/bin:$PATH" python3 "$P547_HELPER" dependencies >/dev/null 2>&1; P547_USAGE_RC=$?
assert_eq "#547: a usage error exits UNAVAILABLE(3), not the BLOCKED code (2)" "3" "$P547_USAGE_RC"
rm -rf "$P547D"

# ── issue #547 review fixes: recognizer fail-direction + untested-path gaps ────
# PR #572 review (REJECT) findings on scripts/preflight.py::dependency_numbers:
#   Critical  — single-capture declaration forms drop all but the first number
#               (`blocked by #10 and #11` → only #10; the open #11 fails OPEN).
#   Important — a per-line `break` drops a second same-line declaration;
#               bare `after #N` over-matches narrative provenance prose;
#               the production `--issue` path (happy + body-fetch-fail) and the
#               `--issue notanint` subparser type-coercion exit-3 arm are untested.
# Stub gh keyed on both the queried field ($5: body|state) and the number ($3):
#   issue 100 body → a multi-number free-prose declaration; 200 body → fetch fail;
#   dependency numbers resolve their state (10 OPEN, 11/12 landed, 13 unresolvable).
P547R="$(mktemp -d)"
mkdir -p "$P547R/bin"
cat > "$P547R/bin/gh" <<'EOF'
#!/usr/bin/env bash
# argv: issue view <number> --json <field> -q .<field>
num="${3:-}"; field="${5:-}"
if [ "$field" = body ]; then
  case "$num" in
    # #100 orders the OPEN number (#10) SECOND behind the CLOSED #11 so a
    # single-capture regression (dropping all but the first number) yields
    # PROCEED 11, not BLOCKED 10 — the assertion is discriminating, not vacuous.
    100) printf '%s\n' 'blocked by #11 and #10' ;;
    101) printf '%s\n' 'depends on #11, blocked by #10' ;;
    102) printf '%s\n' 'cleanup after #10 was merged' ;;
    103) printf '%s\n' 'After #10 lands, ship this' ;;
    104) printf '%s\n' 'requires #11 first' ;;
    105) printf '%s\n' 'no dependencies here' ;;
    # Non-canonical number-run separators (Oxford comma, semicolon, ampersand):
    # each orders the OPEN #10 second so a dropped separator yields PROCEED 11.
    106) printf '%s\n' 'blocked by #11, and #10' ;;
    107) printf '%s\n' 'blocked by #11; #10' ;;
    108) printf '%s\n' 'blocked by #11 & #10' ;;
    # A recognized declaration and a soft keyword on the SAME line: the declaration
    # blocks on the OPEN #10, and the soft-keyword breadcrumb must NOT fire.
    109) printf '%s\n' 'blocked by #10 requires #11' ;;
    # Section-exit: the in-section #11 (CLOSED) is captured; the plain cross-reference
    # `see #10` (not a declaration, not a line-opening `after`) sits under a LATER
    # heading, so once the section exits it is NOT captured — a broken section-exit
    # (staying in-section, where every #N is captured) would grab the OPEN #10.
    110) printf '%s\n' '## Dependencies' '- blocked by #11' '## Notes' 'see #10 for background context' ;;
    # #111 body carries invalid UTF-8 bytes (0xFF 0xFE) around a real OPEN
    # declaration (#10). This is the gh-subprocess decode path (issue_body →
    # _gh_issue_view) — the real GitHub-data path, distinct from the --body-file
    # Path.read_text path covered below. printf's octal escapes emit the raw
    # invalid bytes into stdout that Python captures via subprocess.run.
    111) printf 'blocked by #10 \377\376 trailing invalid bytes\n' ;;
    # #112/#113: the two DECLARATIONS keywords with no prior coverage — `must merge
    # after` and `follow-up to` — each on the OPEN #10, so a keyword dropped from the
    # DECLARATIONS tuple would stop recognizing it and flip BLOCKED 10 → PROCEED.
    112) printf '%s\n' 'must merge after #10' ;;
    113) printf '%s\n' 'follow-up to #10' ;;
    # #114: _NUMBER_RUN non-joiner over-match negative. `superseded by` is NOT a run
    # joiner, so only the CLOSED #11 is captured and the trailing OPEN #10 is left
    # out → PROCEED 11. A regression widening _NUMBER_RUN to sweep any trailing #N
    # would grab the OPEN #10 and flip this to BLOCKED 10.
    114) printf '%s\n' 'depends on #11 superseded by #10' ;;
    # #115: drives issue_state's value-filter `else None` arm — the declared #13
    # resolves via a SUCCESSFUL (exit 0) state fetch that returns a word outside
    # {OPEN,CLOSED,MERGED}, distinct from the CalledProcessError arm (unknown number
    # → exit 1) already exercised. A non-set state must map to None → UNAVAILABLE.
    115) printf '%s\n' 'blocked by #13' ;;
    200) exit 1 ;;
    *) exit 1 ;;
  esac
  exit 0
fi
# field = state
case "$num" in
  10) printf '%s\n' OPEN ;;
  11) printf '%s\n' CLOSED ;;
  12) printf '%s\n' MERGED ;;
  # #115: a SUCCESSFUL fetch returning an unrecognized state word — exercises
  # issue_state's `state in {...} else None` filter, not the exception arm.
  13) printf '%s\n' DRAFT ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$P547R/bin/gh"
P547R_HELPER="$LIB/../scripts/preflight.py"
_p547r() { PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies "$@" 2>/dev/null; }
# Critical: a multi-number free-prose declaration must surface BOTH numbers. The
# OPEN #10 is ordered SECOND (behind the CLOSED #11), so a single-capture regression
# drops #10 and yields PROCEED 11 — this assertion catches the exact bug, not vacuously.
P547R_CRIT="$(_p547r --issue 100)"; P547R_CRIT_RC=$?
assert_eq "#547/#572 Critical: multi-number free-prose declaration keeps every number (OPEN #10 blocks)" "BLOCKED 10" "$P547R_CRIT"
assert_eq "#547/#572 Critical: the multi-number block returns the BLOCKED exit class" "2" "$P547R_CRIT_RC"
# Non-canonical number-run separators (Oxford comma, semicolon, ampersand): each
# must keep the OPEN #10 that trails the joiner, so a dropped separator alternative
# (the same fail-open class as the base multi-number bug) blocks-to-proceeds and is
# caught. Each body orders #10 second so the drop changes the verdict.
assert_eq "#547/#572 Important: an Oxford-comma number run keeps the trailing OPEN #10" "BLOCKED 10" "$(_p547r --issue 106)"
assert_eq "#547/#572 Important: a semicolon number run keeps the trailing OPEN #10" "BLOCKED 10" "$(_p547r --issue 107)"
assert_eq "#547/#572 Important: an ampersand number run keeps the trailing OPEN #10" "BLOCKED 10" "$(_p547r --issue 108)"
# Important #2: two declarations on one line — no early `break` — record both, so the
# OPEN #10 in the SECOND declaration still blocks (a bare `break` would drop it).
P547R_BREAK="$(_p547r --issue 101)"; P547R_BREAK_RC=$?
assert_eq "#547/#572 Important: a second same-line declaration is not dropped (OPEN #10 blocks)" "BLOCKED 10" "$P547R_BREAK"
assert_eq "#547/#572 Important: the second-declaration block returns the BLOCKED exit class" "2" "$P547R_BREAK_RC"
# Important #3: bare `after #N` mid-sentence is narrative provenance, not a dependency —
# it must NOT block; but a line-opening `After #N` is a genuine declaration and DOES.
P547R_AFTERNARR="$(_p547r --issue 102)"; P547R_AFTERNARR_RC=$?
assert_eq "#547/#572 Important: mid-sentence 'after #N' provenance does not block" "PROCEED" "$P547R_AFTERNARR"
assert_eq "#547/#572 Important: the narrative-'after' line proceeds (exit 0)" "0" "$P547R_AFTERNARR_RC"
P547R_AFTERDECL="$(_p547r --issue 103)"
assert_eq "#547/#572 Important: a line-opening 'After #N' stays a recognized declaration (OPEN #10 blocks)" "BLOCKED 10" "$P547R_AFTERDECL"
# Important #4: the production --issue path — a happy body reaching PROCEED via the
# real `--issue` → issue_body() → _gh_issue_view fetch (not --body-file), and a
# body-fetch failure reaching the third UNAVAILABLE arm (`UNAVAILABLE issue`/exit 3).
P547R_ISSUE_OK="$(_p547r --issue 105)"; P547R_ISSUE_OK_RC=$?
assert_eq "#547/#572 Important: a --issue-fetched body with no declared dependencies proceeds" "PROCEED" "$P547R_ISSUE_OK"
assert_eq "#547/#572 Important: the clean --issue-fetched body proceeds (exit 0)" "0" "$P547R_ISSUE_OK_RC"
P547R_ISSUE_FAIL="$(_p547r --issue 200)"; P547R_ISSUE_FAIL_RC=$?
assert_eq "#547/#572 Important: a --issue body-fetch failure is the UNAVAILABLE-issue arm" "UNAVAILABLE issue" "$P547R_ISSUE_FAIL"
assert_eq "#547/#572 Important: the --issue body-fetch failure returns the unavailable exit class" "3" "$P547R_ISSUE_FAIL_RC"
# Important #5: the subparser now carries parser_class=_Parser explicitly, so a
# `--issue notanint` type-coercion error routes to UNAVAILABLE(3), never argparse's
# default 2 (which the §1.3.5 gate would misread as a real BLOCKED verdict).
PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --issue notanint >/dev/null 2>&1; P547R_COERCE_RC=$?
assert_eq "#547/#572 Important: '--issue notanint' exits UNAVAILABLE(3), not the BLOCKED code (2)" "3" "$P547R_COERCE_RC"
# Important #6: a dependency-flavoured phrasing outside the recognized vocabulary
# proceeds (exit 0, observability not a new block) BUT emits a stderr breadcrumb so a
# missed declaration is observable — the breadcrumb must name the referenced number.
P547R_SOFT_ERR="$(PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --issue 104 2>&1 >/dev/null)"
P547R_SOFT_OUT="$(_p547r --issue 104)"; P547R_SOFT_RC=$?
assert_eq "#547/#572 Important: an unrecognized dependency-flavoured phrasing still proceeds" "PROCEED" "$P547R_SOFT_OUT"
assert_eq "#547/#572 Important: the unrecognized-phrasing proceed returns exit 0" "0" "$P547R_SOFT_RC"
assert_eq "#547/#572 Important: an unrecognized '#N' near a dependency keyword emits a stderr breadcrumb" "yes" \
  "$(printf '%s' "$P547R_SOFT_ERR" | grep -qF 'unrecognized dependency-flavoured reference to #11' && echo yes || echo no)"
# Soft-keyword SUPPRESSION: when a recognized declaration IS present on the same
# line as a soft keyword, the breadcrumb must NOT fire (the `not spans` guard) and
# the declaration still blocks on its OPEN #10 — removing the guard would spam
# breadcrumbs on legitimate declaration lines.
P547R_SUP_ERR="$(PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --issue 109 2>&1 >/dev/null)"
assert_eq "#547/#572 Important: a same-line declaration blocks and suppresses the soft breadcrumb (verdict)" "BLOCKED 10" "$(_p547r --issue 109)"
assert_eq "#547/#572 Important: a same-line declaration emits NO soft-keyword breadcrumb" "yes" \
  "$(printf '%s' "$P547R_SUP_ERR" | grep -qF 'unrecognized dependency-flavoured' && echo no || echo yes)"
# `## Dependencies` section-exit: the in-section CLOSED #11 is captured, and the
# narrative `after #10` under a LATER heading is NOT (section already exited), so a
# broken section-exit would capture the OPEN #10 and flip this to BLOCKED 10.
assert_eq "#547/#572 Important: the section scan exits at the next heading (out-of-section narrative not captured)" "PROCEED 11" "$(_p547r --issue 110)"
# UTF-8 hardening: a --body-file carrying invalid UTF-8 bytes must decode (errors=
# replace) and still scan for #N, yielding the TRUE BLOCKED 10 verdict. Without
# errors=replace the UnicodeDecodeError would propagate to main()'s catch-all and be
# converted to a spurious UNAVAILABLE/exit 3 — a contained wrong verdict REPLACING the
# real one — so pinning rc 2 discriminates the true verdict from that wrong exit-3.
printf 'blocked by #10 \377\376 trailing invalid bytes' > "$P547R/badutf8.md"
P547R_UTF8="$(PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --body-file "$P547R/badutf8.md" 2>/dev/null)"; P547R_UTF8_RC=$?
assert_eq "#547/#572 Important: an invalid-UTF-8 body decodes and still blocks on the OPEN #10" "BLOCKED 10" "$P547R_UTF8"
assert_eq "#547/#572 Important: an invalid-UTF-8 body stays in the {0,2,3} exit contract (not exit 1)" "2" "$P547R_UTF8_RC"
# UTF-8 hardening on the --issue/gh-subprocess decode path (issue_body →
# _gh_issue_view), NOT just the --body-file Path.read_text path above — the real
# GitHub-data path most likely to see invalid bytes. Issue #111's gh-stub body
# emits raw 0xFF 0xFE around an OPEN #10. Without errors="replace" on the gh
# subprocess.run decode, that raises UnicodeDecodeError (a ValueError the
# issue_body except (OSError, CalledProcessError) does NOT catch), which main()'s
# catch-all would then convert to a spurious UNAVAILABLE/exit 3 REPLACING the true
# verdict — so BLOCKED 10 + exit 2 is a discriminating pin (true verdict, not that
# wrong exit-3) on the gh-decode errors="replace" (PR #572 review).
P547R_ISSUE_UTF8="$(_p547r --issue 111)"; P547R_ISSUE_UTF8_RC=$?
assert_eq "#547/#572 Important: an invalid-UTF-8 --issue/gh body decodes and still blocks on the OPEN #10" "BLOCKED 10" "$P547R_ISSUE_UTF8"
assert_eq "#547/#572 Important: the invalid-UTF-8 gh-decoded body stays in the {0,2,3} exit contract (not exit 1)" "2" "$P547R_ISSUE_UTF8_RC"
# Source pin (Important #5): the subparser inherits the exit-3 contract explicitly,
# not via add_subparsers()'s implicit parser_class default.
assert_pin_unique "#547/#572: the dependencies subparser sets parser_class=_Parser explicitly" \
  'add_subparsers(dest="command", required=True, parser_class=_Parser)' "$P547R_HELPER"
# ── PR #572 review (Approve-with-notes) minor test gaps ───────────────────────
# OSError arms of issue_body/issue_state, exercised INDEPENDENTLY of the
# CalledProcessError (exit-1 stub) arms already covered above. Point DEVFLOW_GH at
# a non-existent binary so subprocess.run raises FileNotFoundError (an OSError
# subclass, NOT CalledProcessError): issue_body's OSError arm → RuntimeError →
# `UNAVAILABLE issue`/exit 3; issue_state's OSError arm → None → `UNAVAILABLE <n>`/
# exit 3. --body-file isolates issue_state (issue_body is never called on that path).
P547R_NOGH="$P547R/bin/nonexistent-gh"
P547R_OSE_BODY="$(DEVFLOW_GH="$P547R_NOGH" python3 "$P547R_HELPER" dependencies --issue 1 2>/dev/null)"; P547R_OSE_BODY_RC=$?
assert_eq "#547/#572 test-gap: issue_body OSError arm (missing gh) is UNAVAILABLE issue, distinct from CalledProcessError" "UNAVAILABLE issue" "$P547R_OSE_BODY"
assert_eq "#547/#572 test-gap: the issue_body OSError arm returns the unavailable exit class" "3" "$P547R_OSE_BODY_RC"
printf '%s\n' 'blocked by #10' > "$P547R/state-ose.md"
P547R_OSE_STATE="$(DEVFLOW_GH="$P547R_NOGH" python3 "$P547R_HELPER" dependencies --body-file "$P547R/state-ose.md" 2>/dev/null)"; P547R_OSE_STATE_RC=$?
assert_eq "#547/#572 test-gap: issue_state OSError arm (missing gh) is UNAVAILABLE <n>, distinct from CalledProcessError" "UNAVAILABLE 10" "$P547R_OSE_STATE"
assert_eq "#547/#572 test-gap: the issue_state OSError arm returns the unavailable exit class" "3" "$P547R_OSE_STATE_RC"
# Cross-line dedup: the SAME #N declared on two SEPARATE lines is recorded once
# (the add() `if number not in found` guard), so the verdict is `BLOCKED 10`, never
# `BLOCKED 10,10`. #10 is OPEN in the P547R stub, so both lines resolve to a block.
printf '%s\n' 'blocked by #10' 'depends on #10' > "$P547R/dedup.md"
P547R_DEDUP="$(PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --body-file "$P547R/dedup.md" 2>/dev/null)"
assert_eq "#547/#572 test-gap: the same #N on two separate lines is deduped (BLOCKED 10, not 10,10)" "BLOCKED 10" "$P547R_DEDUP"
# ── PR #572 review (run -3) Suggestion 5: untested DECLARATIONS keywords ───────
# `must merge after` and `follow-up to` had no coverage; each names the OPEN #10, so
# a keyword dropped from the DECLARATIONS tuple would stop recognizing it and flip
# BLOCKED 10 → PROCEED (discriminating, not vacuous).
assert_eq "#547/#572 Suggestion 5: the 'must merge after' keyword is recognized (OPEN #10 blocks)" "BLOCKED 10" "$(_p547r --issue 112)"
assert_eq "#547/#572 Suggestion 5: the 'follow-up to' keyword is recognized (OPEN #10 blocks)" "BLOCKED 10" "$(_p547r --issue 113)"
# Suggestion 5: _NUMBER_RUN non-joiner over-match NEGATIVE. `superseded by` is not a
# run joiner, so only the CLOSED #11 is captured; the trailing OPEN #10 stays out →
# PROCEED 11. A regression widening _NUMBER_RUN to sweep any trailing #N would grab
# the OPEN #10 and flip this to BLOCKED 10.
assert_eq "#547/#572 Suggestion 5: a non-joiner word does not sweep the trailing OPEN #10 (PROCEED 11)" "PROCEED 11" "$(_p547r --issue 114)"
# Suggestion 5: issue_state value-filter `else None` arm — a SUCCESSFUL (exit 0)
# state fetch returning a word outside {OPEN,CLOSED,MERGED} maps to None →
# `UNAVAILABLE <n>`/exit 3, distinct from the CalledProcessError (exit-1 stub) arm.
# #13's stub returns DRAFT; a regression accepting any non-empty state as OPEN would
# flip this to BLOCKED 13.
P547R_STATEFILTER="$(_p547r --issue 115)"; P547R_STATEFILTER_RC=$?
assert_eq "#547/#572 Suggestion 5: a successful non-set state word maps to None → UNAVAILABLE" "UNAVAILABLE 13" "$P547R_STATEFILTER"
assert_eq "#547/#572 Suggestion 5: the non-set state UNAVAILABLE stays in the {0,2,3} exit contract" "3" "$P547R_STATEFILTER_RC"
# ── PR #572 review (run -3) Suggestion 2: empty `--body-file ""` (falsy) ───────
# An explicit empty --body-file must read the (empty) file path and fail closed on
# THAT path's read error → `UNAVAILABLE body`/exit 3, not fall through to the issue
# branch and call issue_body(None) (`gh issue view None`, misreporting the surface).
# The `is not None` guard is what routes it here; reverting to `if args.body_file:`
# flips the output to `UNAVAILABLE issue`, so this pins the diagnostic surface.
P547R_EMPTYBF="$(PATH="$P547R/bin:$PATH" python3 "$P547R_HELPER" dependencies --body-file "" 2>/dev/null)"; P547R_EMPTYBF_RC=$?
assert_eq "#547/#572 Suggestion 2: empty '--body-file \"\"' fails closed on the body path (UNAVAILABLE body)" "UNAVAILABLE body" "$P547R_EMPTYBF"
assert_eq "#547/#572 Suggestion 2: the empty-body-file failure returns the unavailable exit class" "3" "$P547R_EMPTYBF_RC"
rm -rf "$P547R"

# ── issue #1197: direction is governed inside `## Dependencies`, at the LINE level ──
# The defect: the in-section limb captured every `#N` with NO keyword test, so an
# OUTBOUND declaration (`Blocks #N` — meaning THIS issue is the prerequisite) was read
# as its exact inverse and BLOCKED the run on a dependency that does not exist, while
# the out-of-section limb parsed direction correctly all along.
#
# The ruling this matrix encodes (issue #1197 AC4): direction governs the WHOLE LINE.
# A section line carrying an outbound direction word contributes NO numbers — not
# merely the number run adjacent to that word. Per-number governance cannot satisfy
# AC2 (issue #1190's real body repeats `#1188` later on the same outbound line,
# outside any number run) and would let a mixed line partially contribute.
#
# Every row is DISCRIMINATING by construction: the OPEN number is #10, so "captured"
# renders `BLOCKED 10` and "not captured" renders `PROCEED`. The stub resolves state
# only — bodies come from --body-file fixtures — and #1188 is OPEN so the real-body
# fixture below reads `BLOCKED 1188` on the pre-fix scanner (the RED it was written
# against) rather than degrading to UNAVAILABLE.
P1197="$(mktemp -d)"
mkdir -p "$P1197/bin"
cat > "$P1197/bin/gh" <<'EOF'
#!/usr/bin/env bash
# argv: issue view <number> --json state -q .state
case "${3:-}" in
  10|1188) printf '%s\n' OPEN ;;
  11) printf '%s\n' CLOSED ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$P1197/bin/gh"
P1197_HELPER="$LIB/../scripts/preflight.py"
# Each fixture is one `## Dependencies` section holding exactly the shape under test,
# followed by a `## Notes` heading so the section exit is exercised too.
_p1197_body() {  # <name> <section-line…>
  local _name="$1"; shift
  { printf '%s\n' '## Dependencies'
    printf '%s\n' "$@"
    printf '%s\n' '## Notes' 'nothing further'
  } > "$P1197/$_name.md"
}
_p1197() { PATH="$P1197/bin:$PATH" python3 "$P1197_HELPER" dependencies --body-file "$P1197/$1.md" 2>/dev/null; }
# stderr only: the `{ …; } 2>&1` grouping is the unambiguous spelling of "drop stdout,
# keep stderr" (a bare `2>&1 >/dev/null` is SC2069).
_p1197_err() { { PATH="$P1197/bin:$PATH" python3 "$P1197_HELPER" dependencies --body-file "$P1197/$1.md" >/dev/null; } 2>&1; }

# ── AC1: outbound declarations under the heading contribute nothing ──
_p1197_body outbound '- Blocks #10'
_p1197_body outbound_bold '- **Blocks #10** — the reason it must land first'
_p1197_body outbound_run '- Blocks #10 and #11'
_p1197_body outbound_upper '- BLOCKS #10'
P1197_OUT="$(_p1197 outbound)"; P1197_OUT_RC=$?
assert_eq "#1197 AC1: an outbound 'Blocks #N' under the heading is not a blocker" "PROCEED" "$P1197_OUT"
assert_eq "#1197 AC1: the outbound line proceeds (exit 0), not the BLOCKED class" "0" "$P1197_OUT_RC"
assert_eq "#1197 AC1: the bold/em-dash authoring variant is outbound too" "PROCEED" "$(_p1197 outbound_bold)"
assert_eq "#1197 AC1: an outbound multi-number run drops the whole run, both numbers" "PROCEED" "$(_p1197 outbound_run)"
assert_eq "#1197 AC1: outbound matching is case-insensitive" "PROCEED" "$(_p1197 outbound_upper)"

# ── AC3: every inbound declaration under the heading is unchanged ──
_p1197_body in_blockedby '- Blocked by #10 — still a real prerequisite'
_p1197_body in_dependson '- Depends on #10'
_p1197_body in_mustmerge '- Must merge after #10'
_p1197_body in_followup '- Follow-up to #10'
_p1197_body in_after '- After #10 lands, ship this'
assert_eq "#1197 AC3: in-section 'Blocked by #N' still blocks" "BLOCKED 10" "$(_p1197 in_blockedby)"
assert_eq "#1197 AC3: in-section 'Depends on #N' still blocks" "BLOCKED 10" "$(_p1197 in_dependson)"
assert_eq "#1197 AC3: in-section 'Must merge after #N' still blocks" "BLOCKED 10" "$(_p1197 in_mustmerge)"
assert_eq "#1197 AC3: in-section 'Follow-up to #N' still blocks" "BLOCKED 10" "$(_p1197 in_followup)"
assert_eq "#1197 AC3: in-section line-anchored 'After #N' still blocks" "BLOCKED 10" "$(_p1197 in_after)"

# ── AC4: the decided dispositions for the direction-word-free and mixed shapes ──
# bare `- #N` and `Part of #N` carry no direction word, so the section heading's own
# inbound implication stands and today's behaviour is KEPT — a stated decision, not an
# inherited one. `Related to #N` is the AC7 class (a direction-flavoured phrase the fix
# recognises as neither inbound nor outbound): also a blocker, deliberately, never
# silently inverted.
_p1197_body bare '- #10'
_p1197_body partof '- Part of #10'
_p1197_body unknown_direction '- Related to #10 in some unspecified way'
assert_eq "#1197 AC4: a bare '- #N' bullet keeps today's behaviour (still a blocker)" "BLOCKED 10" "$(_p1197 bare)"
assert_eq "#1197 AC4: 'Part of #N' keeps today's behaviour (still a blocker)" "BLOCKED 10" "$(_p1197 partof)"
assert_eq "#1197 AC7: a direction word in neither vocabulary stays a blocker (documented choice, never inverted)" "BLOCKED 10" \
  "$(_p1197 unknown_direction)"
# The mixed line — the row that DISCRIMINATES line-level governance from per-number
# governance. Under per-number governance the trailing `blocked by #10` would still
# block; under the ruling the line's outbound word governs the whole line, so nothing
# is contributed. The OPEN number is the INBOUND one, so this cannot pass vacuously.
_p1197_body mixed '- Blocks #11 but blocked by #10'
assert_eq "#1197 AC4: a mixed-direction line contributes NO numbers (line-level, not per-run)" "PROCEED" "$(_p1197 mixed)"
# issue #1267: the bounded-window narrowing closes this residual FOR THIS SPECIFIC
# FIXTURE, not in general. The code-span `Blocks` no longer governs the line because no
# number run follows it within the window, so the genuine inbound `blocked by #10` at
# the end of the line now contributes its number. The scanner is STILL NOT
# markdown-aware — a code-span outbound word written ADJACENT to a number would still
# govern its line; only this fixture's far-separated shape flips. Same disclosed family
# as the fenced-code-block gap (a `## Dependencies` heading inside a fence still opens a
# section), which remains open.
_p1197_body codespan '- The word `Blocks` is the outbound spelling — blocked by #10'
assert_eq "#1267 residual (flipped): the bounded-window narrowing closes the code-span residual for this fixture — the far-separated outbound word no longer governs, so inbound #10 contributes (scanner still not markdown-aware)" \
  "BLOCKED 10" "$(_p1197 codespan)"

# ── The out-of-section limb is UNTOUCHED (it parsed direction correctly all along) ──
# Written without the heading, so the same three shapes route through DECLARATIONS.
printf '%s\n' 'Blocks #10' > "$P1197/oos_outbound.md"
printf '%s\n' 'blocked by #10' > "$P1197/oos_inbound.md"
printf '%s\n' 'Blocks #11 but blocked by #10' > "$P1197/oos_mixed.md"
assert_eq "#1197: an out-of-section 'Blocks #N' was already ignored and still is" "PROCEED" "$(_p1197 oos_outbound)"
assert_eq "#1197: an out-of-section 'blocked by #N' still blocks" "BLOCKED 10" "$(_p1197 oos_inbound)"
assert_eq "#1197: the line-level rule is IN-SECTION only — an out-of-section mixed line still blocks on its inbound half" \
  "BLOCKED 10" "$(_p1197 oos_mixed)"

# ── AC2: issue #1190's real body, captured verbatim as a fixture ──
# FROZEN record: the fixture is a byte-for-byte capture of the live issue body and
# is never path-swept or respelled to track tree relocations — rewriting it
# falsifies the record (same class as _WSR_SWEPT_RELPATHS' revision-side rule).
# The live case. `BLOCKED 1188` / exit 2 before the fix (the stub resolves #1188 OPEN),
# `PROCEED` / exit 0 after — an issue that declares itself the PREREQUISITE of #1188 and
# states it has no blocker is no longer reported as blocked by the issue it unblocks.
P1197_REAL="$(PATH="$P1197/bin:$PATH" python3 "$P1197_HELPER" dependencies --body-file "$LIB/test/fixtures/issue-1190-body.md" 2>/dev/null)"; P1197_REAL_RC=$?
assert_eq "#1197 AC2: the live case's captured real body proceeds (it declares itself the prerequisite, not the dependent)" "PROCEED" "$P1197_REAL"
assert_eq "#1197 AC2: the real-body fixture returns the proceed exit class" "0" "$P1197_REAL_RC"

# ── AC7: the outbound skip is OBSERVABLE on the stderr-carrying entry point ──
# The dropped-number direction is fail-open (a mixed line's inbound half goes with it),
# so the skip must not be silent. The breadcrumb names the skipped number and rides the
# existing `preflight.py:` prefix, alongside the SOFT_KEYWORDS observability arm.
assert_eq "#1197 AC7: an outbound skip emits a preflight.py breadcrumb naming the skipped number" "yes" \
  "$(_p1197_err outbound | grep -q '^preflight.py: .*#10' && echo yes || echo no)"
assert_eq "#1197 AC7: the breadcrumb names the outbound direction as the reason" "yes" \
  "$(_p1197_err outbound | grep -qi 'outbound' && echo yes || echo no)"
# Negative control: an INBOUND section line emits no outbound breadcrumb, so the
# assertion above is attributable to the outbound predicate rather than to any
# unconditional emit.
assert_eq "#1197 AC7 control: an inbound section line emits no outbound breadcrumb" "" \
  "$(_p1197_err in_blockedby)"

# ── issue #1267: the outbound word governs its line only when a number run FOLLOWS it ──
# The shipped bare-keyword rule matched an outbound word ANYWHERE on the line, so a
# template-shaped `Blocked by #N — <reason it must land first>` line whose reason prose
# carried an outbound keyword ("must merge before", "blocks", …) dropped its number
# (fail-open). The narrowing requires a following number run within a bounded window.
# Every row below is DISCRIMINATING: #10 is OPEN in the stub, so a returned number
# renders `BLOCKED 10` and a dropped one renders `PROCEED`.
#
# ── #1267 positive control: a template `Blocked by #N — <reason>` line RETURNS #N even
# when the reason prose contains an outbound keyword. The seven reason wordings are the
# exact ones the issue measured as dropped, so the reported regression is pinned
# verbatim rather than paraphrased. This matrix is un-dischargeable by an implementation
# that returns an empty list / hardcodes empty / drops everything: each asserts BLOCKED
# 10, i.e. the specific number, not merely "non-empty".
_p1197_body pc_mustmerge  'Blocked by #10 — it must merge before this refactor can start'
_p1197_body pc_blocks     'Blocked by #10 — it blocks the schema change this depends on'
_p1197_body pc_requiredby 'Blocked by #10 — the parser work is required by this one'
_p1197_body pc_unblocks   'Blocked by #10 — unblocks the whole series'
_p1197_body pc_blocking   'Blocked by #10 — this is blocking the release'
_p1197_body pc_prereq     'Blocked by #10 — prerequisite for the cutover'
_p1197_body pc_unblocking 'Blocked by #10 — it is unblocking the downstream cutover'
assert_eq "#1267 positive control: reason prose 'must merge before' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_mustmerge)"
assert_eq "#1267 positive control: reason prose 'blocks' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_blocks)"
assert_eq "#1267 positive control: reason prose 'required by' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_requiredby)"
assert_eq "#1267 positive control: reason prose 'unblocks' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_unblocks)"
assert_eq "#1267 positive control: reason prose 'blocking' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_blocking)"
assert_eq "#1267 positive control: reason prose 'prerequisite for' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_prereq)"
assert_eq "#1267 positive control: reason prose 'unblocking' no longer drops the number" "BLOCKED 10" "$(_p1197 pc_unblocking)"

# ── #1267 separator matrix: an outbound keyword ADJACENT to a number (across many
# separators) still governs — returns NO number. Each shape returns no number correctly
# on the shipped recognizer too. A rule that required whitespace between keyword and
# number would start returning the number on these separator shapes (a false BLOCKED); a
# rule that allowed only punctuation there would still miss `Blocks issue #N` /
# `Blocks PR #N`, where the separator is a word. The bounded window handles them.
_p1197_body sep_colon     '- Blocks: #10'
_p1197_body sep_paren     '- Blocks (#10)'
_p1197_body sep_emdash    '- Blocks — #10'
_p1197_body sep_boldkw    '- **Blocks**: #10'
_p1197_body sep_boldcolon '- **Blocks:** #10'
_p1197_body sep_comma     '- Blocks, #10'
_p1197_body sep_table     '| Blocks | #10 |'
_p1197_body sep_issue     '- Blocks issue #10'
_p1197_body sep_pr        '- Blocks PR #10'
assert_eq "#1267 separator: 'Blocks: #N' still governs (no number)" "PROCEED" "$(_p1197 sep_colon)"
assert_eq "#1267 separator: 'Blocks (#N)' still governs (no number)" "PROCEED" "$(_p1197 sep_paren)"
assert_eq "#1267 separator: 'Blocks — #N' still governs (no number)" "PROCEED" "$(_p1197 sep_emdash)"
assert_eq "#1267 separator: '**Blocks**: #N' still governs (no number)" "PROCEED" "$(_p1197 sep_boldkw)"
assert_eq "#1267 separator: '**Blocks:** #N' still governs (no number)" "PROCEED" "$(_p1197 sep_boldcolon)"
assert_eq "#1267 separator: 'Blocks, #N' still governs (no number)" "PROCEED" "$(_p1197 sep_comma)"
assert_eq "#1267 separator: '| Blocks | #N |' (table cell) still governs (no number)" "PROCEED" "$(_p1197 sep_table)"
assert_eq "#1267 separator: 'Blocks issue #N' still governs (no number)" "PROCEED" "$(_p1197 sep_issue)"
assert_eq "#1267 separator: 'Blocks PR #N' still governs (no number)" "PROCEED" "$(_p1197 sep_pr)"

# ── #1267 positive-polarity keyword coverage: each of the SEVEN outbound keywords,
# written adjacent to a number, returns NO number. Six of the seven had no such
# coverage anywhere before, so this is what stops an implementation that narrows the
# VOCABULARY (rather than the match) from passing everything that already exists.
_p1197_body pol_blocks     '- Blocks #10'
_p1197_body pol_blocking   '- Blocking #10'
_p1197_body pol_unblocks   '- Unblocks #10'
_p1197_body pol_unblocking '- Unblocking #10'
_p1197_body pol_prereq     '- prerequisite for #10'
_p1197_body pol_requiredby '- required by #10'
_p1197_body pol_mustmerge  '- must merge before #10'
assert_eq "#1267 keyword: 'blocks' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_blocks)"
assert_eq "#1267 keyword: 'blocking' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_blocking)"
assert_eq "#1267 keyword: 'unblocks' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_unblocks)"
assert_eq "#1267 keyword: 'unblocking' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_unblocking)"
assert_eq "#1267 keyword: 'prerequisite for' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_prereq)"
assert_eq "#1267 keyword: 'required by' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_requiredby)"
assert_eq "#1267 keyword: 'must merge before' adjacent to #N governs (no number)" "PROCEED" "$(_p1197 pol_mustmerge)"

# ── #1267 line-level governance retained: a governing outbound match drops EVERY number
# on the line, including one appearing later outside any number run. #11 is CLOSED and
# #10 OPEN; per-number governance would return the trailing #10 (→ BLOCKED 10), so this
# row cannot pass vacuously — line-level governance renders PROCEED.
_p1197_body line_level '- Blocks #11 — see also #10 for the follow-up'
assert_eq "#1267 line-level: a governing outbound match drops a number later on the line too" "PROCEED" "$(_p1197 line_level)"

# ── #1267 end-to-end through the subcommand (stdout + exit code, what §1.3.5 reads): a
# template-shaped outbound-reason line naming an OPEN issue → BLOCKED/exit 2; naming a
# CLOSED issue → a proceed result/exit 0.
_p1197_body e2e_open   'Blocked by #10 — it must merge before this refactor can start'
_p1197_body e2e_closed 'Blocked by #11 — it must merge before this refactor can start'
P1267_E2E_OPEN="$(_p1197 e2e_open)"; P1267_E2E_OPEN_RC=$?
assert_eq "#1267 e2e: an open-issue template-reason line prints BLOCKED <n>" "BLOCKED 10" "$P1267_E2E_OPEN"
assert_eq "#1267 e2e: …and exits 2 (the BLOCKED class §1.3.5 routes on)" "2" "$P1267_E2E_OPEN_RC"
P1267_E2E_CLOSED="$(_p1197 e2e_closed)"; P1267_E2E_CLOSED_RC=$?
assert_eq "#1267 e2e: the same body naming a CLOSED issue prints a proceed result" "PROCEED 11" "$P1267_E2E_CLOSED"
assert_eq "#1267 e2e: …and exits 0 (the proceed class)" "0" "$P1267_E2E_CLOSED_RC"

# ── #1267 DISCLOSED RESIDUAL of the bounded window (asserted, not left to be found).
# A genuinely-OUTBOUND free-prose line whose own number sits BEYOND the window is no
# longer recognised as outbound, so its number is RETURNED — a spurious blocker the
# shipped bare-keyword rule dropped. This is the unavoidable cost of ANY finite
# character window (the mechanism issue #1267 selected) and is the same family as the
# codespan residual above: the scanner is NOT markdown/semantic-aware. It is pinned here
# so a later change that closes it (or a widened `_OUTBOUND_WINDOW`) flips a test rather
# than silently changing behavior. #10 is OPEN, so the returned number renders
# `BLOCKED 10`; the canonical `- Blocks #10` adjacent form (pinned above) is unaffected.
# This row ALSO pins the window's UPPER bound: widening `_OUTBOUND_WINDOW` far enough to
# span this gap would flip it back to PROCEED and turn this assertion RED.
_p1197_body far_outbound '- Blocks the whole downstream release train, everyone waits on #10'
assert_eq "#1267 residual: a far-separated outbound free-prose number is no longer governed (bounded-window cost; scanner not semantic-aware) — pinned, not overlooked" \
  "BLOCKED 10" "$(_p1197 far_outbound)"

# ── #1267 template mixed-number edge: a `Blocked by #N` line whose reason writes an
# outbound ordering word ADJACENT to a *second* number is governed (line-level), so BOTH
# numbers drop. #10 (the intended inbound) is OPEN and #11 (the outbound object) CLOSED,
# so a per-number reading would return #10 → BLOCKED 10; line-level governance renders
# PROCEED. This is the shape the issue-template clarification is careful to condition
# ("a reason whose ordering words introduce no #N of their own"), pinned here.
_p1197_body tmpl_mixed 'Blocked by #10 — must merge before #11 ships'
assert_eq "#1267 template mixed-number: an ordering word adjacent to a second number governs the whole line (both numbers drop)" \
  "PROCEED" "$(_p1197 tmpl_mixed)"

rm -rf "$P1197"

# ── PR #572 review (Approve-with-notes): main() top-level fail-closed catch-all ─
# main() wraps args.func(args) in `except Exception → UNAVAILABLE/exit 3`, so an
# UNANTICIPATED exception (one no inner handler catches) stays inside the {0,2,3}
# contract the §1.3.5 gate reads instead of exiting 1 — a fourth code the gate has
# no arm for. Behavioral injection: monkeypatch issue_body to raise a KeyError (NOT
# the RuntimeError `dependencies` catches), so it propagates out of dependencies()
# to main()'s catch. The harness mirrors `raise SystemExit(main())`: a contained
# error prints the exit code; an ESCAPED (uncaught) error aborts with empty stdout.
P547C_HELPER="$LIB/../scripts/preflight.py"
_p547c_run() {  # <helper-path> → stdout is main()'s exit code, or empty if the injected error escaped
  python3 - "$1" <<'PY' 2>/dev/null
import contextlib, importlib.util, os, sys
spec = importlib.util.spec_from_file_location("pf_catchall_probe", sys.argv[1])
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
def boom(_issue):
    raise KeyError("injected unanticipated failure")
mod.issue_body = boom  # not a RuntimeError → uncaught by dependencies()
sys.argv = ["preflight.py", "dependencies", "--issue", "1"]
# Redirect the module's own stdout token (`UNAVAILABLE`) to devnull so only the
# exit code below reaches real stdout. On the mutated copy main() re-raises the
# injected KeyError HERE (uncaught), aborting the process before the print — so
# escaped runs emit empty stdout, contained runs emit the returned exit code.
with open(os.devnull, "w") as _dn, contextlib.redirect_stdout(_dn):
    code = mod.main()
print(code)
PY
}
P547C_OUT="$(_p547c_run "$P547C_HELPER")"
assert_eq "#547/#572 catch-all: an unanticipated exception fails closed to UNAVAILABLE exit 3 (not 1)" "3" "$P547C_OUT"
# Mutation discipline (behavioral, not a grep pin): on a /tmp copy with the catch-all
# stripped to a bare `return args.func(args)`, the SAME injected KeyError is no longer
# contained — it escapes uncaught (empty stdout). Proves the exit-3 above is the
# catch-all's doing, not vacuous. The working tree is never touched (copy only).
P547C_MUT="$(mktemp -d)"
# Apply the strip as a CHECKED step: the writer aborts (assert n==1) if the anchor regex
# ever stops matching after a reformat of the catch-all block. Capture its exit status.
if python3 - "$P547C_HELPER" "$P547C_MUT/preflight.py" <<'PY' 2>/dev/null
import re, sys
src = open(sys.argv[1]).read()
pat = re.compile(r"    try:\n        return args\.func\(args\)\n    except Exception.*?return UNAVAILABLE_EXIT\n", re.S)
new, n = pat.subn("    return args.func(args)\n", src)
assert n == 1, f"expected exactly one main() catch-all block, replaced {n}"
open(sys.argv[2], "w").write(new)
PY
then P547C_MUT_APPLIED=yes; else P547C_MUT_APPLIED=no; fi
# Guard the escape check against a false-green: an empty mutated-run stdout reads as
# "escaped", but an UNWRITTEN mutated file (writer aborted → _p547c_run loads a missing
# path → empty stdout) produces the identical empty. So first prove the strip was really
# applied — writer succeeded AND the copy exists AND its sole `except Exception` (the
# catch-all) is gone — so the escape assertion below cannot pass on a mutation that never
# ran (PR #572 review: mutation-vacuity hole).
P547C_MUT_STRIPPED="$([ "$P547C_MUT_APPLIED" = yes ] && [ -f "$P547C_MUT/preflight.py" ] && ! grep -q 'except Exception' "$P547C_MUT/preflight.py" && echo yes || echo no)"
assert_eq "#547/#572 catch-all mutation: the strip was actually applied (not an absent-file/no-op vacuity)" "yes" "$P547C_MUT_STRIPPED"
P547C_MUT_OUT="$(_p547c_run "$P547C_MUT/preflight.py")"
assert_eq "#547/#572 catch-all mutation: removing the catch-all lets the injected exception escape (contained→escaped)" "3->escaped" \
  "$P547C_OUT->$([ -z "$P547C_MUT_OUT" ] && echo escaped || echo "$P547C_MUT_OUT")"
rm -rf "$P547C_MUT"

# ── issue #576: branch-state (Verdict B) ahead-of-base classification ─────────
# The §1.4 freshness guard derives only the BEHIND-by count, so a branch carrying
# unrelated AHEAD-only history reads "up to date" while §1.5 publishes foreign
# commits (the PR #524 incident). branch-state derives the ahead-of-base count and
# emits a one-token verdict + matching exit code, mirroring update-branch-checkpoint.sh:
#   FRESH / VALIDATED_RESUME     exit 0  proceed
#   AMBIGUOUS / DECISION_BLOCKED exit 2  stop before push/checkpoint (no history mutation)
#   UNAVAILABLE <reason>         exit 3  unestablished measurement
# The driver below builds throwaway git repos (bare origin + work tree) and exercises
# every arm AC4 enumerates, writing `<arm> <verdict-word> <rc>` lines to a file.
BS576_HELPER="$LIB/../scripts/preflight.py"
BS576_OUT="$(mktemp)"
python3 - "$BS576_HELPER" "$BS576_OUT" >/dev/null 2>&1 <<'PY'
import json, os, subprocess, sys, tempfile
HELPER, OUT = sys.argv[1], sys.argv[2]
ROOT = tempfile.mkdtemp()
lines = []
def git(args, cwd):
    return subprocess.run(["git", *args], cwd=cwd, capture_output=True, text=True)
def commit(work, name, content="x"):
    open(os.path.join(work, name), "w").write(content + "\n")
    git(["add", "-A"], work); git(["commit", "-qm", name], work)
def new_repo(tag):
    d = os.path.join(ROOT, tag); bare = os.path.join(d, "origin.git"); work = os.path.join(d, "work")
    os.makedirs(d)
    subprocess.run(["git", "init", "-q", "--bare", bare], check=True)
    subprocess.run(["git", "init", "-q", work], check=True)
    git(["config", "user.email", "a@b.c"], work); git(["config", "user.name", "t"], work)
    git(["remote", "add", "origin", bare], work)
    return bare, work
def base_repo(tag):
    bare, work = new_repo(tag)
    commit(work, "base0"); git(["branch", "-M", "main"], work)
    git(["push", "-q", "-u", "origin", "main"], work)
    return bare, work
def run(work, state, cwd=None):
    sf = os.path.join(ROOT, "state.json"); open(sf, "w").write(json.dumps(state))
    r = subprocess.run(["python3", HELPER, "branch-state", "--state-file", sf],
                       cwd=cwd or work, capture_output=True, text=True)
    return (r.stdout.split() or [""])[0], r.returncode, r.stdout.strip()
def reason_of(word, out):
    # UNAVAILABLE prints `UNAVAILABLE <reason>` on stdout; the two stop verdicts
    # print `<verdict> <payload-path>` and carry the reason slug inside the payload.
    parts = out.split()
    if word == "UNAVAILABLE":
        return parts[1] if len(parts) > 1 else "-"
    if word in ("AMBIGUOUS", "DECISION_BLOCKED") and len(parts) > 1:
        try:
            return json.load(open(parts[-1])).get("reason") or "-"
        except Exception:
            return "-"
    return "-"
def emit(arm, work, state, cwd=None):
    word, rc, out = run(work, state, cwd)
    lines.append(f"{arm} {word} {rc}")
    lines.append(f"reason_{arm} {reason_of(word, out)}")
# FRESH (ahead 0) + warm-start (ahead 0 with a workpad present)
_, work = base_repo("fresh"); git(["checkout", "-qb", "feat", "main"], work)
emit("ahead0", work, {"base": "main", "current_branch": "feat"})
emit("warmstart", work, {"base": "main", "current_branch": "feat", "provenance_established": True,
     "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
# ahead>0 on an unpushed feat (tip NOT reachable)
_, work = base_repo("ahead1"); git(["checkout", "-qb", "feat", "main"], work); commit(work, "a1")
S = {"base": "main", "current_branch": "feat"}
emit("ahead1_noprov", work, {**S, "provenance_established": False})
emit("wp_forged", work, {**S, "provenance_established": False, "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
emit("wp_matching_noverdict", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": False})
emit("wp_matching_verdict_notip", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
emit("wp_absent", work, {**S, "provenance_established": True, "workpad_body": "no branch line here", "has_proceed_verdict": False})
emit("wp_placeholder", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** _(creating…)_", "has_proceed_verdict": True})
emit("wp_duplicate", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `feat`\n**Branch:** `other`"})
emit("wp_truncated", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `feat", "has_proceed_verdict": False})
emit("wp_probe_fail", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `bad ref name`", "has_proceed_verdict": False})
emit("wp_divergent_nonexistent", work, {**S, "provenance_established": True, "workpad_body": "**Branch:** `ghost`", "has_proceed_verdict": False})
# no-history-mutation: HEAD sha + ref snapshot unchanged across a stop verdict
hb = git(["rev-parse", "HEAD"], work).stdout.strip(); rb = git(["show-ref"], work).stdout
run(work, {**S, "provenance_established": False})
ha = git(["rev-parse", "HEAD"], work).stdout.strip(); ra = git(["show-ref"], work).stdout
lines.append(f"nomut {'yes' if hb == ha and rb == ra else 'no'}")
# divergent-existing (a real 'other' branch off base)
_, work = base_repo("divergent")
git(["checkout", "-qb", "other", "main"], work); commit(work, "o1"); git(["push", "-q", "-u", "origin", "other"], work)
git(["checkout", "-qb", "feat", "main"], work); commit(work, "a1")
D = {"base": "main", "current_branch": "feat", "provenance_established": True, "workpad_body": "**Branch:** `other`"}
emit("wp_divergent_exist_verdict", work, {**D, "has_proceed_verdict": True})
emit("wp_divergent_noverdict", work, {**D, "has_proceed_verdict": False})
# VALIDATED_RESUME: ahead>0, pushed (tip reachable), matching + verdict; and absent+verdict+tip
_, work = base_repo("resume"); git(["checkout", "-qb", "feat", "main"], work); commit(work, "a1")
git(["push", "-q", "-u", "origin", "feat"], work)
emit("wp_matching_verdict", work, {"base": "main", "current_branch": "feat", "provenance_established": True, "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
emit("wp_absent_verdict_tip", work, {"base": "main", "current_branch": "feat", "provenance_established": True, "workpad_body": "no branch line", "has_proceed_verdict": True})
# Published tip EXISTS but no longer reaches HEAD (pushed, then committed locally).
# The sibling wp_matching_verdict_notip arm reaches the same slug through the
# ref-ABSENT early return, leaving `merge-base --is-ancestor` — the actual
# divergence check — unexercised: a regression returning True once the ref merely
# resolves would still pass that arm, and hand a diverged branch a VALIDATED_RESUME
# (exit 0, proceed to push). This arm is what fails on that regression.
commit(work, "local-only")
emit("wp_matching_verdict_tipdiverged", work, {"base": "main", "current_branch": "feat", "provenance_established": True,
     "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
# ── issue #780: open-PR-linkage provenance (the landed-resume arm) ────────────
# A landed resume has ahead history by definition, and its workpad provenance is
# unestablished across two large populations (a cloud run whose HANDOFF record is
# `unknown`; a local resumed run that did not create its own workpad) — so the
# workpad-only gate returned DECISION_BLOCKED for them, which is why Verdict B
# could not be widened to that arm. The PR-linkage source admits them. Its own
# fixture repo (pushed feat, ahead>0, tip reachable) so the arms are independent
# of the `resume` repo's trailing local-only commit above.
_, pwork = base_repo("prprov"); git(["checkout", "-qb", "feat", "main"], pwork); commit(pwork, "a1")
git(["push", "-q", "-u", "origin", "feat"], pwork)
_PRV = {"open_pr_branch": "feat", "open_pr_closes_issue": True, "open_pr_cross_repository": False,
        "open_pr_selected_by": "body"}
_PS = {"base": "main", "current_branch": "feat", "provenance_established": False}
# The two populations #780 must NOT re-block. They are byte-equivalent through the
# classifier — the PR-vouched path never reads has_proceed_verdict — so this pair is
# NOT distinguishing coverage; both arms exist because the issue names both
# populations by name and each is asserted individually against the new gate.
emit("pr_cloud_handoff_unknown", pwork, {**_PS, **_PRV})
emit("pr_local_no_workpad", pwork, {**_PS, **_PRV, "has_proceed_verdict": False})
# The issue-linkage DISJUNCTION: a head-branch-query-selected PR vouches without a
# closing linkage, mirroring the §1.4 pre-check's "resume target by construction"
# rule. Without this, a landed resume whose PR body reads "Part of #N" is handed a
# terminal stop by the very change that exists to remove one.
emit("pr_head_query_no_closes", pwork, {**_PS, **_PRV, "open_pr_closes_issue": False,
     "open_pr_selected_by": "head"})
# The untrusted workpad is NEUTRALIZED on the PR-vouched path, not consulted: both
# bodies below would steer the classification if they were read (a divergent
# nonexistent name → DECISION_BLOCKED, a duplicate Branch line → AMBIGUOUS).
emit("pr_forged_wp_divergent", pwork, {**_PS, **_PRV, "workpad_body": "**Branch:** `ghost`", "has_proceed_verdict": False})
emit("pr_forged_wp_duplicate", pwork, {**_PS, **_PRV, "workpad_body": "**Branch:** `a`\n**Branch:** `b`"})
# Negative direction — every conjunct of the source is required and fails CLOSED.
emit("pr_no_source", pwork, _PS)
emit("pr_branch_mismatch", pwork, {**_PS, **_PRV, "open_pr_branch": "other"})
emit("pr_not_closing", pwork, {**_PS, **_PRV, "open_pr_closes_issue": False})
emit("pr_cross_repo", pwork, {**_PS, **_PRV, "open_pr_cross_repository": True})
# PARTIAL GATHER — each of the four operands omitted in turn. What these assert is the
# REFUSAL itself: without it an ungathered field would silently vouch, which is the PR
# #524 shape on the arm #780 just widened. Refusal (not a DECISION_BLOCKED) is the point
# — a stop that names the omission, rather than one that reads as a real refutation of
# the PR the run never evaluated. They do NOT kill the `is True`/`is False` identity
# mutants: the refusal returns before `_classify_branch_state` runs, so an omitted
# operand never reaches the identity expression at all. Those mutants are equivalent
# under the two upstream guards — the boolean type-guard (any PRESENT non-bool is
# refused) and the `isinstance(pr_branch, str)` conjunct — which between them leave
# `None` as the only distinguishing value, and `None` arises only on the omission the
# gather guard already refuses. The mutation-sensitive operand here is the string
# comparison `open_pr_selected_by == "head"`, covered by its own arms.
_PG = {**_PS, **_PRV}
for _k in ("open_pr_branch", "open_pr_closes_issue", "open_pr_cross_repository", "open_pr_selected_by"):
    emit("pr_partial_" + _k, pwork, {k: v for k, v in _PG.items() if k != _k})
# GUARD-BEFORE-PRECEDENCE: a partial PR gather while the WORKPAD independently vouches.
# The gather refusal is unconditional, so this run stops UNAVAILABLE rather than falling
# back to the trusted workpad — an ordering the prose leaves implicit. Pinned so a later
# "the workpad vouched anyway, just proceed" relaxation is a visible test change rather
# than a silent widening of what a partial gather may be read as.
emit("pr_partial_wp_vouches", pwork, {"base": "main", "current_branch": "feat", "provenance_established": True,
     "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True,
     **{k: v for k, v in _PRV.items() if k != "open_pr_selected_by"}})
# Established workpad provenance is unchanged by the new source (control).
emit("pr_wp_prov_control", pwork, {"base": "main", "current_branch": "feat", "provenance_established": True,
     "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": True})
# PRECEDENCE, both sources vouching. The two are NOT interchangeable, so the shipped
# prose states the workpad wins; this arm is what makes that statement checkable
# rather than a documented claim nothing exercises. The workpad names a divergent
# nonexistent branch with no verdict, so a PR-precedence implementation would return
# VALIDATED_RESUME here instead of the workpad's finer divergent-nonexistent stop.
emit("both_wp_precedence", pwork, {"base": "main", "current_branch": "feat", "provenance_established": True,
     "workpad_body": "**Branch:** `ghost`", "has_proceed_verdict": False, **_PRV})
# The two derived payload keys are a stated contract ("a human reading a stop payload
# is never shown a PR-derived provenance the classification did not in fact use"), so
# read them out of the payload rather than leaving the claim unexercised. Emitted as
# `prov_<arm> <provenance_source> <pr_linkage_vouches>` lines.
def emit_prov(arm, work, state):
    word, rc, out = run(work, state)
    parts = out.split()
    src = vouch = "-"
    if word in ("AMBIGUOUS", "DECISION_BLOCKED") and len(parts) > 1:
        try:
            d = json.load(open(parts[-1])).get("derived", {})
            src = str(d.get("provenance_source")); vouch = str(d.get("pr_linkage_vouches"))
        except Exception:
            pass
    lines.append(f"prov_{arm} {src} {vouch}")
# Both vouch → the payload must say the WORKPAD supplied the operands, while still
# recording that the PR linkage COULD have. One key alone cannot express that.
emit_prov("both_wp_precedence", pwork, {"base": "main", "current_branch": "feat", "provenance_established": True,
          "workpad_body": "**Branch:** `ghost`", "has_proceed_verdict": False, **_PRV})
# Workpad vouches while the PR operands are present but do NOT → the source key must
# still read `workpad` while the linkage key reads False. An implementation hard-coding
# `pr_linkage_vouches` True on the workpad-precedence path passes every other payload
# arm and only this one.
emit_prov("wp_only_pr_refutes", pwork, {"base": "main", "current_branch": "feat", "provenance_established": True,
          "workpad_body": "**Branch:** `ghost`", "has_proceed_verdict": False,
          **{**_PRV, "open_pr_cross_repository": True}})
# Neither vouches → no source, and the linkage is recorded as not vouching.
emit_prov("pr_no_source", pwork, _PS)
# PR-vouched but the published tip no longer reaches HEAD: the run reaches the
# recorded-branch + proceed-verdict arms rather than short-circuiting to proceed,
# so a diverged branch still stops.
commit(pwork, "local-only")
emit("pr_tip_diverged", pwork, {**_PS, **_PRV})
emit_prov("pr_tip_diverged", pwork, {**_PS, **_PRV})
# aheadN + mixed ahead/behind
_, work = base_repo("mixed"); git(["checkout", "-qb", "feat", "main"], work)
for i in range(3): commit(work, f"a{i}")
emit("aheadN_noprov", work, {"base": "main", "current_branch": "feat", "provenance_established": False})
git(["checkout", "-q", "main"], work); commit(work, "m2"); git(["push", "-q", "origin", "main"], work)
git(["fetch", "-q", "origin"], work); git(["checkout", "-q", "feat"], work)
emit("mixed", work, {"base": "main", "current_branch": "feat", "provenance_established": False})
# base-fetch failure
_, work = base_repo("basefail"); git(["checkout", "-qb", "feat", "main"], work); commit(work, "a1")
emit("basefail", work, {"base": "nope", "current_branch": "feat"})
# underivable count: origin/main resolvable but HEAD unborn
bare, work2 = new_repo("count"); _, seed = base_repo("count_seed")
git(["push", "-q", os.path.join(ROOT, "count", "origin.git"), "main"], seed)
git(["fetch", "-q", "origin", "+refs/heads/main:refs/remotes/origin/main"], work2)
emit("count", work2, {"base": "main", "current_branch": "feat"})
# shallow wrong-digit vs post-unshallow: full clone of feat + shallow main fetch
bare_s, deep = new_repo("shallow_src")
commit(deep, "b0"); git(["branch", "-M", "main"], deep)
git(["checkout", "-qb", "feat", "main"], deep); commit(deep, "f1")
git(["checkout", "-q", "main"], deep)
for i in range(4): commit(deep, f"b{i+1}")
git(["push", "-q", "-u", "origin", "main"], deep); git(["push", "-q", "-u", "origin", "feat"], deep)
shal = os.path.join(ROOT, "shallow_clone")
subprocess.run(["git", "clone", "-q", "--branch", "feat", "file://" + bare_s, shal], check=True)
git(["config", "user.email", "a@b.c"], shal); git(["config", "user.name", "t"], shal)
git(["fetch", "-q", "--depth=1", "origin", "+refs/heads/main:refs/remotes/origin/main"], shal)
naive = git(["rev-list", "--count", "refs/remotes/origin/main..HEAD"], shal).stdout.strip()
lines.append(f"shallow_naive {naive or 'ERR'}")
# Tip-invariance across the ONE path that issues a network git command
# (fetch --unshallow). The published contract is narrow and this snapshot matches
# it exactly: no LOCAL branch tip moves and the working tree is unchanged. The
# remote-tracking ref origin/main is deliberately EXCLUDED — the deepen's refspec
# force-updates it by design, so snapshotting `show-ref` wholesale here would pin
# a claim the code does not make (and the non-shallow `nomut` arm above, which
# runs no fetch, already covers the all-refs case).
# `--untracked-files=no` (TRACKED files only) is the operand the published claim
# names: "no local branch and no tracked file is touched". A raw `--porcelain`
# here would compare UNTRACKED state too and so trip on the helper's OWN documented
# stop-verdict payload, which `_payload_dir()` writes into `<repo>/.prflow/tmp/`
# on exactly this DECISION_BLOCKED arm — grading a legitimate artifact as a tree
# mutation. Tracked-only still fails on any real working-tree modification, which
# is what the guarantee is about.
shb = git(["show-ref", "--heads"], shal).stdout
stb = git(["status", "--porcelain", "--untracked-files=no"], shal).stdout
word, rc, out = run(shal, {"base": "main", "current_branch": "feat", "provenance_established": False}, cwd=shal)
sha_ = git(["show-ref", "--heads"], shal).stdout
sta_ = git(["status", "--porcelain", "--untracked-files=no"], shal).stdout
lines.append(f"shallow_nomut {'yes' if shb == sha_ and stb == sta_ else 'no'}")
lines.append(f"shallow_deepened {git(['rev-parse', '--is-shallow-repository'], shal).stdout.strip()}")
lines.append(f"shallow {word} {rc}")
payload = out.split()[-1] if word in ("AMBIGUOUS", "DECISION_BLOCKED") else ""
derived = str(json.load(open(payload)).get("derived", {}).get("ahead")) if payload and os.path.exists(payload) else ""
lines.append(f"shallow_derived {derived}")
# shallow-undeepened: a fresh shallow clone whose origin is then broken, so the
# unshallow fetch fails and the repo stays shallow — the count is unreliable and
# must fail closed to UNAVAILABLE rather than trust a possibly-spurious value.
shal2 = os.path.join(ROOT, "shallow_undeepenable")
subprocess.run(["git", "clone", "-q", "--branch", "feat", "file://" + bare_s, shal2], check=True)
git(["config", "user.email", "a@b.c"], shal2); git(["config", "user.name", "t"], shal2)
git(["fetch", "-q", "--depth=1", "origin", "+refs/heads/main:refs/remotes/origin/main"], shal2)
git(["remote", "set-url", "origin", os.path.join(ROOT, "does-not-exist.git")], shal2)
emit("shallow_undeepened", shal2, {"base": "main", "current_branch": "feat", "provenance_established": False}, cwd=shal2)
# ── branch-state input-validation matrix (best-effort parser over agent-written
# JSON). Every arm asserts BOTH the fail-closed contract (`UNAVAILABLE state`,
# exit 3) AND a SPECIFIC stderr cause — a bare exit-code assertion could not tell
# these guards apart, since they all reject to the same token. `bad()` takes
# argv directly so the absent/empty --state-file arms are reachable at all (they
# cannot be expressed through run(), which always writes a well-formed file).
# Positive control: the same fixture repo yields FRESH on a well-formed file, so a
# rejection here cannot be an unrelated precondition (e.g. a broken sandbox).
_, vwork = base_repo("inputval"); git(["checkout", "-qb", "feat", "main"], vwork)
def bad(arm, argv, cwd):
    r = subprocess.run(["python3", HELPER, "branch-state"] + argv, cwd=cwd,
                       capture_output=True, text=True)
    lines.append(f"{arm} {(r.stdout.split() or ['-'])[0]}_{(r.stdout.split() + ['-'])[1]} {r.returncode}")
    # One whitespace-collapsed stderr line, so the cause can be substring-matched.
    lines.append(f"err_{arm} {' '.join(r.stderr.split()) or '-'}")
def bad_file(arm, content, cwd):
    p = os.path.join(ROOT, f"iv_{arm}.json"); open(p, "w").write(content)
    bad(arm, ["--state-file", p], cwd)
emit("iv_control", vwork, {"base": "main", "current_branch": "feat"})
bad("iv_noflag", [], vwork)
bad("iv_emptypath", ["--state-file", ""], vwork)
bad("iv_missing", ["--state-file", os.path.join(ROOT, "iv_absent.json")], vwork)
_ivdir = os.path.join(ROOT, "iv_dir"); os.makedirs(_ivdir)
bad("iv_unreadable", ["--state-file", _ivdir], vwork)
bad_file("iv_notjson", "{not json", vwork)
bad_file("iv_notdict", '["a"]', vwork)
bad_file("iv_nobase", json.dumps({"current_branch": "feat"}), vwork)
bad_file("iv_emptybase", json.dumps({"base": "", "current_branch": "feat"}), vwork)
bad_file("iv_nocur", json.dumps({"base": "main"}), vwork)
bad_file("iv_emptycur", json.dumps({"base": "main", "current_branch": ""}), vwork)
bad_file("iv_wrongtype", json.dumps({"base": 7, "current_branch": "feat"}), vwork)
# The two gate flags, exercised on an ahead>0 repo — the state where a truthy-string
# coercion would actually fail OPEN. A quoted "false" is truthy in Python, so before
# the type check these sailed past `unverified-provenance` (letting a forged workpad
# vouch for foreign ahead history) or manufactured a proceed verdict. Each arm pins
# the SPECIFIC flag name in the cause, so one flag's guard cannot pass for the other's;
# the bool_ok control proves real booleans still classify (the guard is not blanket).
_, bwork = base_repo("boolflags"); git(["checkout", "-qb", "feat", "main"], bwork); commit(bwork, "a1")
_B = {"base": "main", "current_branch": "feat"}
bad_file("iv_provstr", json.dumps({**_B, "provenance_established": "false"}), bwork)
bad_file("iv_verdictstr", json.dumps({**_B, "provenance_established": True,
         "workpad_body": "**Branch:** `feat`", "has_proceed_verdict": "false"}), bwork)
bad_file("iv_provnum", json.dumps({**_B, "provenance_established": 1}), bwork)
# issue #780's two boolean operands are read through IDENTITY (`is True`/`is False`),
# so a quoted "false" already fails closed on its own — unlike the two originals,
# which use truthiness and genuinely fail OPEN. They are refused anyway so the stop
# NAMES the encoding error instead of emitting `unverified-provenance`, which would
# read as a real refutation of a PR the run never actually evaluated.
_PRB = {"open_pr_branch": "feat", "open_pr_closes_issue": True,
        "open_pr_cross_repository": False, "open_pr_selected_by": "body"}
bad_file("iv_prclosesstr", json.dumps({**_B, **_PRB, "open_pr_closes_issue": "false"}), bwork)
bad_file("iv_prcrossstr", json.dumps({**_B, **_PRB, "open_pr_cross_repository": "false"}), bwork)
# JSON null takes a DIFFERENT path from an omitted key (refused as a non-bool, vs the
# partial-gather refusal), and `gh pr list --json` can serialize a null field — so the
# two are distinguished rather than assumed equivalent.
bad_file("iv_prcrossnull", json.dumps({**_B, **_PRB, "open_pr_cross_repository": None}), bwork)
# The one string operand with no boolean guard: without its own refusal a malformed
# value is the sole gate operand whose failure is silent.
bad_file("iv_prbranchnum", json.dumps({**_B, **_PRB, "open_pr_branch": 123}), bwork)
bad_file("iv_prselectedbad", json.dumps({**_B, **_PRB, "open_pr_selected_by": "search"}), bwork)
# JSON null is the shape `gh pr list --json` can actually serialize for this operand,
# and it is a NON-STRING rather than an out-of-enum string — a guard keyed on the enum
# alone (rather than on the type first) would let it through to the `== "head"` read.
bad_file("iv_prselectednull", json.dumps({**_B, **_PRB, "open_pr_selected_by": None}), bwork)
emit("iv_bool_ok", bwork, {**_B, "provenance_established": False})
# Positive control for the NEW operands specifically: real booleans + a valid
# selected-by survive every refusal above and reach the classifier, so those arms are
# the guards firing rather than a blanket rejection of any state carrying open_pr_*.
emit("iv_prbool_ok", bwork, {**_B, "provenance_established": False, **_PRB})
open(OUT, "w").write("\n".join(lines) + "\n")
import shutil; shutil.rmtree(ROOT)
PY
_bs576() { awk -v k="$1" '$1==k{print $2, $3; f=1} END{if(!f)print "MISSING"}' "$BS576_OUT"; }
_bs576v() { awk -v k="$1" '$1==k{print $2; f=1} END{if(!f)print "MISSING"}' "$BS576_OUT"; }
# Whole-line-tail accessor for the stderr causes the input-validation matrix records.
_bs576e() { awk -v k="$1" '$1==k{$1=""; sub(/^ /,""); print; f=1} END{if(!f)print "MISSING"}' "$BS576_OUT"; }
# Substring match of a recorded stderr cause → yes/no (attributes WHICH guard rejected).
_bs576err() { case "$(_bs576e "err_$1")" in *"$2"*) echo yes;; *) echo no;; esac; }
assert_eq "#576: fresh branch (ahead 0) → FRESH/proceed" "FRESH 0" "$(_bs576 ahead0)"
assert_eq "#576: warm-start (ahead 0, workpad present) → FRESH/proceed" "FRESH 0" "$(_bs576 warmstart)"
assert_eq "#576: ahead>0 under unverified provenance → DECISION_BLOCKED/stop" "DECISION_BLOCKED 2" "$(_bs576 ahead1_noprov)"
assert_eq "#576: aheadN under unverified provenance → DECISION_BLOCKED/stop" "DECISION_BLOCKED 2" "$(_bs576 aheadN_noprov)"
assert_eq "#576: mixed ahead+behind still classifies on ahead → DECISION_BLOCKED/stop" "DECISION_BLOCKED 2" "$(_bs576 mixed)"
assert_eq "#576: marker-forged hostile workpad (ahead>0, provenance false) → DECISION_BLOCKED" "DECISION_BLOCKED 2" "$(_bs576 wp_forged)"
assert_eq "#576: recorded branch matches, no verdict → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_matching_noverdict)"
assert_eq "#576: recorded matches + verdict but tip unreachable → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_matching_verdict_notip)"
assert_eq "#576: recorded matches + verdict + tip reachable → VALIDATED_RESUME/proceed" "VALIDATED_RESUME 0" "$(_bs576 wp_matching_verdict)"
assert_eq "#576: no recorded branch, no verdict → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_absent)"
assert_eq "#576: no recorded branch + verdict + tip reachable → VALIDATED_RESUME/proceed" "VALIDATED_RESUME 0" "$(_bs576 wp_absent_verdict_tip)"
assert_eq "#576: placeholder Branch line resolves to absent → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_placeholder)"
assert_eq "#576: duplicate Branch line (ambiguous workpad) → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_duplicate)"
assert_eq "#576: truncated Branch line (no closing backtick) → absent → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_truncated)"
assert_eq "#576: divergent recorded branch that EXISTS + verdict → AMBIGUOUS/stop" "AMBIGUOUS 2" "$(_bs576 wp_divergent_exist_verdict)"
assert_eq "#576: divergent recorded branch that EXISTS, no verdict → DECISION_BLOCKED/stop" "DECISION_BLOCKED 2" "$(_bs576 wp_divergent_noverdict)"
assert_eq "#576: divergent recorded branch that does NOT exist (clean-empty) → DECISION_BLOCKED/stop" "DECISION_BLOCKED 2" "$(_bs576 wp_divergent_nonexistent)"
assert_eq "#576: malformed recorded branch name (existence-probe failure) → UNAVAILABLE/3" "UNAVAILABLE 3" "$(_bs576 wp_probe_fail)"
assert_eq "#576: base ref unresolvable (base-fetch failure) → UNAVAILABLE/3" "UNAVAILABLE 3" "$(_bs576 basefail)"
assert_eq "#576: underivable ahead count (unborn HEAD) → UNAVAILABLE/3" "UNAVAILABLE 3" "$(_bs576 count)"
# no-history-mutation (behavioral): a DECISION_BLOCKED stop leaves HEAD + every ref untouched.
assert_eq "#576 no-history-mutation: a stop verdict leaves HEAD and all refs unchanged" "yes" "$(_bs576v nomut)"
# shallow wrong-digit vs post-unshallow: the naive shallow count is inflated; the helper
# unshallows once and re-derives the correct ahead count (1) recorded in the payload.
BS576_NAIVE="$(_bs576v shallow_naive)"; BS576_DERIVED="$(_bs576v shallow_derived)"
assert_eq "#576 shallow: the naive shallow ahead count differs from the post-unshallow count" "differ" \
  "$([ "$BS576_NAIVE" != "$BS576_DERIVED" ] && echo differ || echo same)"
assert_eq "#576 shallow: the helper re-derives the correct post-unshallow ahead count" "1" "$BS576_DERIVED"
assert_eq "#576 shallow: a shallow repo still yields a well-formed stop verdict" "DECISION_BLOCKED 2" "$(_bs576 shallow)"
# Tip-invariance on the ONE network-git path (fetch --unshallow). Scoped to the
# published claim: no LOCAL branch tip moves, working tree unchanged. origin/main
# is excluded because the deepen's refspec force-updates it by design.
assert_eq "#576 shallow: the deepen moves no local branch tip and leaves the tree unchanged" "yes" \
  "$(_bs576v shallow_nomut)"
# Positive control: the fetch really did run, so the invariance above is not vacuous.
assert_eq "#576 shallow: the fixture was genuinely deepened (tip-invariance is not vacuous)" "false" \
  "$(_bs576v shallow_deepened)"
# A shallow repo that CANNOT be deepened (broken origin) fails closed to UNAVAILABLE
# rather than trusting the unreliable shallow count. Direction note (the helper's
# docstring is authoritative): `origin/<base>..HEAD` excludes base-reachable
# commits, so a truncated base excludes FEWER and the shallow count can only
# OVERcount — it cannot undercount to a spurious FRESH. The count is simply
# fabricated, which is why it is refused rather than adopted in either direction.
assert_eq "#576 shallow-undeepened: an un-deepenable shallow repo fails closed to UNAVAILABLE/3" "UNAVAILABLE 3" "$(_bs576 shallow_undeepened)"
assert_eq "#576 shallow-undeepened: carries the 'shallow-undeepened' reason slug" "shallow-undeepened" "$(_bs576v reason_shallow_undeepened)"
# Reason slugs (the operator-facing remedy routing) are distinct even where the
# verdict word + rc collapse: the three UNAVAILABLE causes and the three
# DECISION_BLOCKED causes each assert their own slug, so a mis-routed reason is caught.
assert_eq "#576 reason: base-fetch failure carries the 'base' slug" "base" "$(_bs576v reason_basefail)"
assert_eq "#576 reason: underivable count carries the 'count' slug" "count" "$(_bs576v reason_count)"
assert_eq "#576 reason: malformed recorded name carries the 'existence-probe' slug" "existence-probe" "$(_bs576v reason_wp_probe_fail)"
assert_eq "#576 reason: ahead>0 under unverified provenance carries the 'unverified-provenance' slug" "unverified-provenance" "$(_bs576v reason_ahead1_noprov)"
assert_eq "#576 reason: a forged workpad still routes to 'unverified-provenance'" "unverified-provenance" "$(_bs576v reason_wp_forged)"
assert_eq "#576 reason: matching branch without a verdict carries 'matching-without-verdict'" "matching-without-verdict" "$(_bs576v reason_wp_matching_noverdict)"
assert_eq "#576 reason: a duplicate Branch line carries 'duplicate-branch-line'" "duplicate-branch-line" "$(_bs576v reason_wp_duplicate)"
assert_eq "#576 reason: divergent existing branch without a verdict carries 'divergent-without-verdict'" "divergent-without-verdict" "$(_bs576v reason_wp_divergent_noverdict)"
assert_eq "#576 reason: divergent nonexistent branch carries 'divergent-nonexistent'" "divergent-nonexistent" "$(_bs576v reason_wp_divergent_nonexistent)"
# The remaining three AMBIGUOUS arms collapse onto the same `AMBIGUOUS 2` verdict as
# the two above, so verdict-only assertions cannot tell them apart — pin their slugs too.
assert_eq "#576 reason: absent Branch line without a verdict carries 'no-recorded-branch'" "no-recorded-branch" "$(_bs576v reason_wp_absent)"
assert_eq "#576 reason: matching branch + verdict but unreachable tip carries 'matching-verdict-tip-unreachable'" \
