# ────────────────────────────────────────────────────────────────────────────
echo "scaffold-config.sh"
# ────────────────────────────────────────────────────────────────────────────
# Single shared scaffolder used by BOTH install.sh and the /devflow:init skill.
# Templates resolve relative to the script (../.prflow), so we point it at a
# throwaway TARGET root and assert against the repo's real template files.
SC="$LIB/../scripts/scaffold-config.sh"
TPL_DIR="$LIB/../.prflow"

# 1. Fresh target → scaffolds config.json (from the example) + schema.
SC_FRESH="$(mktemp -d)"
bash "$SC" "$SC_FRESH" >/dev/null 2>&1
assert_eq "scaffold: fresh exit 0" "0" "$?"
assert_eq "scaffold: config.json created" "yes" \
  "$([ -f "$SC_FRESH/.prflow/config.json" ] && echo yes || echo no)"
assert_eq "scaffold: config.json == example template" \
  "$(cat "$TPL_DIR/config.example.json")" "$(cat "$SC_FRESH/.prflow/config.json")"
assert_eq "scaffold: schema created" "yes" \
  "$([ -f "$SC_FRESH/.prflow/config.schema.json" ] && echo yes || echo no)"
# Scoped scratch ignore: created, ignores ONLY tmp/ (so config.json + learnings
# stay committable — never the .prflow/ root).
assert_eq "scaffold: .prflow/.gitignore created" "yes" \
  "$([ -f "$SC_FRESH/.prflow/.gitignore" ] && echo yes || echo no)"
assert_eq "scaffold: .gitignore ignores tmp/" "yes" \
  "$(grep -qxF '/tmp/' "$SC_FRESH/.prflow/.gitignore" && echo yes || echo no)"
assert_eq "scaffold: .gitignore does NOT ignore the .prflow root" "no" \
  "$(grep -qE '^/?\*?$|^\.$' "$SC_FRESH/.prflow/.gitignore" && echo yes || echo no)"

# 2. Existing config.json + .gitignore → the user's value is NEVER clobbered
#    (missing keys are backfilled — see block 5); schema still refreshed.
SC_KEEP="$(mktemp -d)"
mkdir -p "$SC_KEEP/.prflow"
printf '{"sentinel":true}' > "$SC_KEEP/.prflow/config.json"
printf 'STALE' > "$SC_KEEP/.prflow/config.schema.json"
printf 'CUSTOM-IGNORE\n' > "$SC_KEEP/.prflow/.gitignore"
bash "$SC" "$SC_KEEP" >/dev/null 2>&1
assert_eq "scaffold: existing custom value preserved through backfill" \
  "true" "$(jq -r '.sentinel' "$SC_KEEP/.prflow/config.json")"
assert_eq "scaffold: schema refreshed over stale" \
  "$(cat "$TPL_DIR/config.schema.json")" "$(cat "$SC_KEEP/.prflow/config.schema.json")"
assert_eq "scaffold: existing .gitignore preserved" \
  'CUSTOM-IGNORE' "$(cat "$SC_KEEP/.prflow/.gitignore")"

# 3. Idempotent: a second run leaves the scaffolded config.json AND the
#    scaffolder's OWN .gitignore byte-identical (guards the `if [ ! -f ]` create
#    guard against a regression that re-writes/appends on every run).
SC_B1="$(cat "$SC_FRESH/.prflow/config.json")"
SC_GI1="$(cat "$SC_FRESH/.prflow/.gitignore")"
bash "$SC" "$SC_FRESH" >/dev/null 2>&1
assert_eq "scaffold: idempotent re-run keeps config" \
  "$SC_B1" "$(cat "$SC_FRESH/.prflow/config.json")"
assert_eq "scaffold: idempotent re-run keeps .gitignore" \
  "$SC_GI1" "$(cat "$SC_FRESH/.prflow/.gitignore")"

# 4. Templates missing next to the script → fail loudly (exit 2), no guessing.
SC_NOTPL="$(mktemp -d)"; mkdir -p "$SC_NOTPL/scripts"
cp "$SC" "$SC_NOTPL/scripts/scaffold-config.sh"
SC_NOTPL_TGT="$(mktemp -d)"
bash "$SC_NOTPL/scripts/scaffold-config.sh" "$SC_NOTPL_TGT" >/dev/null 2>&1
assert_eq "scaffold: missing templates → exit 2" "2" "$?"

# 5. Config-key backfill on an existing config: a recursive deep-merge adds keys
#    newly introduced in the example (at any depth) while preserving the user's
#    values and arrays. No language markers in these throwaway dirs, so the
#    detect step is a no-op and only the backfill is under test.
SC_BF="$(mktemp -d)"; mkdir -p "$SC_BF/.prflow"
# An old config predating prflow_runner.provision_env: a custom top-level value,
# a custom nested value, and a user-tuned array we must not touch.
printf '%s' '{"base_branch":"release","prflow_runner":{"effort":"high"},"prflow":{"allowed_tools":["Bash(make:*)","Bash(npm:*)"]}}' \
  > "$SC_BF/.prflow/config.json"
# Capture stdout so we can also assert the backfill log line the /devflow:init
# skill (skills/init/SKILL.md) keys its "After running" guidance off of.
SC_BF_OUT="$(bash "$SC" "$SC_BF" 2>&1)"
assert_eq "scaffold-backfill: nested missing key added (prflow_runner.provision_env)" \
  "false" "$(jq -r '.prflow_runner.provision_env' "$SC_BF/.prflow/config.json")"
assert_eq "scaffold-backfill: top-level missing key added (claude_model)" \
  "claude-opus-5" "$(jq -r '.claude_model' "$SC_BF/.prflow/config.json")"
assert_eq "scaffold-backfill: existing top-level value preserved (base_branch)" \
  "release" "$(jq -r '.base_branch' "$SC_BF/.prflow/config.json")"
assert_eq "scaffold-backfill: existing nested value preserved (prflow_runner.effort)" \
  "high" "$(jq -r '.prflow_runner.effort' "$SC_BF/.prflow/config.json")"
# jq `*` replaces arrays with the right operand (the user's), never merging or
# deduping — so the user's array survives with its exact elements and order
# (read back via `jq -c`, which normalizes whitespace but not contents).
assert_eq "scaffold-backfill: existing array left unchanged (allowed_tools)" \
  '["Bash(make:*)","Bash(npm:*)"]' \
  "$(jq -c '.prflow.allowed_tools' "$SC_BF/.prflow/config.json")"
# The documented log line fires when a backfill actually happens.
assert_eq "scaffold-backfill: backfill emits the documented log line" "yes" \
  "$(printf '%s' "$SC_BF_OUT" | grep -q 'backfilled newly-added keys' && echo yes || echo no)"

# 5a-#1331. The new create_issue family grafts into a consumer config that lacks it,
# and a create_issue.investigation_record_enabled ALREADY set to false is left
# unchanged on a re-run — the existing absent-keys-only deep-merge behavior,
# asserted here so the family's addition cannot regress it.
# (i) Absent family → grafted with the example default (true).
SC_CI1="$(mktemp -d)"; mkdir -p "$SC_CI1/.prflow"
printf '%s' '{"base_branch":"main"}' > "$SC_CI1/.prflow/config.json"
bash "$SC" "$SC_CI1" >/dev/null 2>&1
assert_eq "scaffold-backfill(#1331): absent create_issue family grafted with default true" \
  "true" "$(jq -r '.create_issue.investigation_record_enabled' "$SC_CI1/.prflow/config.json")"
# (ii) Family holding a deliberate false → left unchanged (never re-grafted to true),
#      and an unrecognized sibling key inside the family is preserved.
SC_CI2="$(mktemp -d)"; mkdir -p "$SC_CI2/.prflow"
printf '%s' '{"create_issue":{"investigation_record_enabled":false,"custom_sibling":"keep"}}' \
  > "$SC_CI2/.prflow/config.json"
bash "$SC" "$SC_CI2" >/dev/null 2>&1
assert_eq "scaffold-backfill(#1331): deliberate false left unchanged on re-run" \
  "false" "$(jq -r '.create_issue.investigation_record_enabled' "$SC_CI2/.prflow/config.json")"
assert_eq "scaffold-backfill(#1331): unrecognized sibling key inside the family preserved" \
  "keep" "$(jq -r '.create_issue.custom_sibling' "$SC_CI2/.prflow/config.json")"

# 5b. A config already holding every example key is a no-op: byte-for-byte
#     identical afterwards (the merge changed nothing, so the file isn't rewritten)
#     and the backfill log line is NOT emitted.
SC_NOOP="$(mktemp -d)"; mkdir -p "$SC_NOOP/.prflow"
cp "$TPL_DIR/config.example.json" "$SC_NOOP/.prflow/config.json"
SC_NOOP_BEFORE="$(cat "$SC_NOOP/.prflow/config.json")"
SC_NOOP_OUT="$(bash "$SC" "$SC_NOOP" 2>&1)"
assert_eq "scaffold-backfill: complete config is a byte-identical no-op" \
  "$SC_NOOP_BEFORE" "$(cat "$SC_NOOP/.prflow/config.json")"
assert_eq "scaffold-backfill: no-op does NOT emit the backfill log line" "no" \
  "$(printf '%s' "$SC_NOOP_OUT" | grep -q 'backfilled newly-added keys' && echo yes || echo no)"
# The shipped example pins Sonnet 5 (no Haiku override), so a fresh scaffold of
# it must never emit the Haiku effort-cleanup log line — locks the clean path so
# a regression that re-pins Haiku-with-effort in the example is caught.
assert_eq "scaffold-migration: clean shipped example emits no Haiku cleanup log line" "no" \
  "$(printf '%s' "$SC_NOOP_OUT" | grep -q "removed unsupported 'effort' from Haiku-pinned" && echo yes || echo no)"

# 5c. jq unavailable → backfill skipped, scaffold still succeeds and leaves the
#     config untouched. Run under a PATH that resolves the coreutils the scaffold
#     needs but NOT jq, so `command -v jq` fails exactly as on a host without jq.
#     The symlink set below must track every external command scaffold-config.sh
#     (and its detect-project-tools.sh callee) reaches on the jq-absent path; git
#     is intentionally absent because TARGET_ROOT is passed explicitly ($1), and
#     mv/find/grep are not reached once `command -v jq` short-circuits.
SC_NOJQ="$(mktemp -d)"; mkdir -p "$SC_NOJQ/.prflow"
printf '%s' '{"sentinel":true}' > "$SC_NOJQ/.prflow/config.json"
NOJQ_BIN="$(mktemp -d)"
for b in bash dirname mkdir cp rm cat printf find grep diff mktemp; do
  src="$(command -v "$b")" && ln -s "$src" "$NOJQ_BIN/$b"
done
BASH_BIN="$(command -v bash)"
PATH="$NOJQ_BIN" "$BASH_BIN" "$SC" "$SC_NOJQ" >/dev/null 2>&1
assert_eq "scaffold-backfill: jq unavailable → scaffold exits 0 (best-effort)" \
  "0" "$?"
assert_eq "scaffold-backfill: jq unavailable → config left as-is (no backfill)" \
  '{"sentinel":true}' "$(cat "$SC_NOJQ/.prflow/config.json")"

# 5d. Malformed (invalid-JSON) existing config → backfill skipped, scaffold still
#     succeeds, the malformed bytes are left untouched (no clobber/truncation),
#     and the schema is still refreshed (proving the scaffold proceeded past the
#     skip). Guards the `jq -e .` validity branch.
SC_BAD="$(mktemp -d)"; mkdir -p "$SC_BAD/.prflow"
printf '%s' '{ not valid json' > "$SC_BAD/.prflow/config.json"
bash "$SC" "$SC_BAD" >/dev/null 2>&1
assert_eq "scaffold-backfill: malformed config → scaffold exits 0 (best-effort)" \
  "0" "$?"
assert_eq "scaffold-backfill: malformed config left untouched (no clobber)" \
  '{ not valid json' "$(cat "$SC_BAD/.prflow/config.json")"
assert_eq "scaffold-backfill: malformed config → schema still refreshed" \
  "$(cat "$TPL_DIR/config.schema.json")" "$(cat "$SC_BAD/.prflow/config.schema.json")"

rm -rf "$SC_FRESH" "$SC_KEEP" "$SC_NOTPL" "$SC_NOTPL_TGT" "$SC_BF" "$SC_NOOP" "$SC_NOJQ" "$NOJQ_BIN" "$SC_BAD"

# 6. Haiku effort-cleanup migration on an EXISTING config: scaffold-config.sh
#    strips `effort` from any agent_overrides entry whose model is a Haiku id.
#    An earlier release removed that effort key from the example, but the add-only
#    backfill can never propagate a removal to a pre-existing config, so the
#    dedicated cleanup is what repairs an adopter's stale HTTP-400 combo. Mirrors
#    the SC_BF inline-mktemp pattern; no language markers, so detect is a no-op.
SC_MIG="$(mktemp -d)"; mkdir -p "$SC_MIG/.prflow"
# A legacy config: Haiku deduper carrying the HTTP-400 effort key, a SECOND
# Haiku-pinned entry on a different agent (proving the cleanup generalizes to
# any Haiku override, not just the deduper — a regression that hard-coded the
# deduper key would otherwise pass green), plus a non-Haiku override whose
# effort must be left untouched.
# The override keys carry the CURRENT `prflow:` spelling on purpose (issue #1028):
# the scaffolder now renames a `devflow:`-spelled key, so a superseded-spelling
# fixture here would silently make these Haiku assertions read an absent key and
# probe nothing. The rename itself is covered by the tier1-rename-migration module;
# these blocks stay about the Haiku cleanup, the graft guard and their robustness.
printf '%s' '{"prflow_review":{"agent_overrides":{"default":{"effort":"medium"},"prflow:checklist-deduper":{"model":"claude-haiku-4-5-20251001","effort":"low"},"prflow:checklist-generator":{"model":"claude-haiku-4-5-20251001","effort":"high"},"prflow:code-reviewer":{"model":"claude-opus-4-8","effort":"high"}}}}' \
  > "$SC_MIG/.prflow/config.json"
SC_MIG_OUT="$(bash "$SC" "$SC_MIG" 2>&1)"
assert_eq "scaffold-migration: Haiku deduper effort stripped" \
  "false" "$(jq '.prflow_review.agent_overrides["prflow:checklist-deduper"] | has("effort")' "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: Haiku deduper model rewritten to the haiku alias (issue #1646)" \
  "haiku" "$(jq -r '.prflow_review.agent_overrides["prflow:checklist-deduper"].model' "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: Opus code-reviewer model rewritten to the opus alias (issue #1646)" \
  "opus" "$(jq -r '.prflow_review.agent_overrides["prflow:code-reviewer"].model' "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: second Haiku-pinned entry (non-deduper) also stripped" \
  "false" "$(jq '.prflow_review.agent_overrides["prflow:checklist-generator"] | has("effort")' "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: non-Haiku override effort left untouched" \
  "high" "$(jq -r '.prflow_review.agent_overrides["prflow:code-reviewer"].effort' "$SC_MIG/.prflow/config.json")"
# The model-less `default` entry must survive: `(.value.model // "")` yields ""
# which fails the Haiku predicate, so its effort is kept. Asserted on the FIRST
# run directly (not just via the idempotent no-op below, which would pass even
# if both runs stripped it identically), so a regression dropping the model
# guard is caught loudly.
assert_eq "scaffold-migration: model-less default override effort left untouched" \
  "medium" "$(jq -r '.prflow_review.agent_overrides.default.effort' "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: cleanup emits the documented log line" "yes" \
  "$(printf '%s' "$SC_MIG_OUT" | grep -q "removed unsupported 'effort' from Haiku-pinned" && echo yes || echo no)"
# Second run is a no-churn no-op: config already clean → byte-identical and the
# cleanup log line is NOT re-emitted.
SC_MIG_BEFORE="$(cat "$SC_MIG/.prflow/config.json")"
SC_MIG_OUT2="$(bash "$SC" "$SC_MIG" 2>&1)"
assert_eq "scaffold-migration: second run is a byte-identical no-op" \
  "$SC_MIG_BEFORE" "$(cat "$SC_MIG/.prflow/config.json")"
assert_eq "scaffold-migration: clean config does NOT re-emit the cleanup log line" "no" \
  "$(printf '%s' "$SC_MIG_OUT2" | grep -q "removed unsupported 'effort' from Haiku-pinned" && echo yes || echo no)"
rm -rf "$SC_MIG"

# 6h. issue #1646 model-alias rewrite: an existing config whose agent_overrides
#     `model` values are full Anthropic family identifiers is rewritten to the
#     accepted aliases (sonnet/opus/haiku/fable) so the operator keeps the reviewer
#     tier they chose after the resolver started dropping full identifiers. An
#     UNRECOGNIZED value and the top-level `claude_model` are left untouched, and a
#     second pass is a byte-identical no-op. Keys carry the current prflow: spelling.
SC_ALIAS="$(mktemp -d)"; mkdir -p "$SC_ALIAS/.prflow"
printf '%s' '{"claude_model":"claude-opus-4-8","prflow_review":{"agent_overrides":{"prflow:checklist-deduper":{"model":"claude-sonnet-5"},"prflow:code-reviewer":{"model":"claude-opus-5","effort":"high"},"prflow:comment-analyzer":{"model":"claude-fable-5"},"prflow:pr-test-analyzer":{"model":"z-ai/glm-5.2"}}}}' \
  > "$SC_ALIAS/.prflow/config.json"
SC_ALIAS_OUT="$(bash "$SC" "$SC_ALIAS" 2>&1)"
assert_eq "scaffold-alias(#1646): claude-sonnet-* rewritten to the sonnet alias" \
  "sonnet" "$(jq -r '.prflow_review.agent_overrides["prflow:checklist-deduper"].model' "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): claude-opus-* rewritten to the opus alias" \
  "opus" "$(jq -r '.prflow_review.agent_overrides["prflow:code-reviewer"].model' "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): claude-fable-* rewritten to the fable alias" \
  "fable" "$(jq -r '.prflow_review.agent_overrides["prflow:comment-analyzer"].model' "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): an unrecognized model value is left untouched" \
  "z-ai/glm-5.2" "$(jq -r '.prflow_review.agent_overrides["prflow:pr-test-analyzer"].model' "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): the top-level claude_model is left untouched" \
  "claude-opus-4-8" "$(jq -r '.claude_model' "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): the rewrite emits the documented log line" "yes" \
  "$(printf '%s' "$SC_ALIAS_OUT" | grep -q "rewrote agent_overrides model values to their accepted aliases" && echo yes || echo no)"
SC_ALIAS_BEFORE="$(cat "$SC_ALIAS/.prflow/config.json")"
SC_ALIAS_OUT2="$(bash "$SC" "$SC_ALIAS" 2>&1)"
assert_eq "scaffold-alias(#1646): a second pass over the rewritten config is byte-identical" \
  "$SC_ALIAS_BEFORE" "$(cat "$SC_ALIAS/.prflow/config.json")"
assert_eq "scaffold-alias(#1646): the clean second pass does NOT re-emit the rewrite log line" "no" \
  "$(printf '%s' "$SC_ALIAS_OUT2" | grep -q "rewrote agent_overrides model values to their accepted aliases" && echo yes || echo no)"
rm -rf "$SC_ALIAS"

# 6b. jq unavailable during the Haiku effort-cleanup: a config that DOES carry a
#     stale Haiku+effort combo must be LEFT UNTOUCHED (cleanup skipped, not
#     silently "nothing to do"), and the skip breadcrumb must fire. The SC_NOJQ
#     case above uses a non-Haiku config, so it cannot tell "correctly skipped"
#     from "no work"; this fixture closes that gap. Same PATH-without-jq trick.
SC_MIG_NOJQ="$(mktemp -d)"; mkdir -p "$SC_MIG_NOJQ/.prflow"
printf '%s' '{"prflow_review":{"agent_overrides":{"devflow:checklist-deduper":{"model":"claude-haiku-4-5-20251001","effort":"low"}}}}' \
  > "$SC_MIG_NOJQ/.prflow/config.json"
MIG_NOJQ_BIN="$(mktemp -d)"
for b in bash dirname mkdir cp rm cat printf find grep diff mktemp; do
  src="$(command -v "$b")" && ln -s "$src" "$MIG_NOJQ_BIN/$b"
done
MIG_BASH_BIN="$(command -v bash)"
SC_MIG_NOJQ_OUT="$(PATH="$MIG_NOJQ_BIN" "$MIG_BASH_BIN" "$SC" "$SC_MIG_NOJQ" 2>&1)"
# Read back with the test's normal (jq-present) PATH; only the scaffold RAN jq-less.
assert_eq "scaffold-migration: jq unavailable → Haiku+effort combo left untouched (skipped, not a no-op)" \
  "low" "$(jq -r '.prflow_review.agent_overrides["devflow:checklist-deduper"].effort' "$SC_MIG_NOJQ/.prflow/config.json")"
assert_eq "scaffold-migration: jq unavailable → emits the cleanup-skipped breadcrumb" "yes" \
  "$(printf '%s' "$SC_MIG_NOJQ_OUT" | grep -q 'skipping Haiku effort-cleanup' && echo yes || echo no)"
rm -rf "$SC_MIG_NOJQ" "$MIG_NOJQ_BIN"

# 6c. agent_overrides hand-corrupted to a non-object (array): the cleanup filter
#     no-ops via its `else .` arm, but the anti-silent-failure breadcrumb must
#     fire so the silence is not an ambiguous "nothing to do". The backfill leaves
#     the array in place (jq `*` lets the right operand win on a type mismatch).
SC_AO_BAD="$(mktemp -d)"; mkdir -p "$SC_AO_BAD/.prflow"
printf '%s' '{"prflow_review":{"agent_overrides":["oops"]}}' > "$SC_AO_BAD/.prflow/config.json"
SC_AO_BAD_OUT="$(bash "$SC" "$SC_AO_BAD" 2>&1)"
assert_eq "scaffold-migration: non-object agent_overrides emits the skip breadcrumb" "yes" \
  "$(printf '%s' "$SC_AO_BAD_OUT" | grep -q 'agent_overrides is present but not an object' && echo yes || echo no)"
rm -rf "$SC_AO_BAD"

# 6c-bis. prflow_review ITSELF is a non-object (a string). It is valid JSON (so it
#     passes the jq -e . gate), but `.prflow_review.agent_overrides` then ERRORS
#     rather than yielding null. The breadcrumb probe must surface that as its own
#     specific "could not inspect ... (jq error ...)" line — not fold the error into
#     "null" and stay silent (the silent-failure-hunter gap). The scaffold still
#     exits 0 (best-effort) and leaves the malformed value untouched.
SC_DR_BAD="$(mktemp -d)"; mkdir -p "$SC_DR_BAD/.prflow"
printf '%s' '{"prflow_review":"oops"}' > "$SC_DR_BAD/.prflow/config.json"
SC_DR_BAD_OUT="$(bash "$SC" "$SC_DR_BAD" 2>&1)"; SC_DR_BAD_RC=$?
assert_eq "scaffold-migration: non-object prflow_review → scaffold still exits 0 (best-effort)" \
  "0" "$SC_DR_BAD_RC"
assert_eq "scaffold-migration: non-object prflow_review emits the probe-error breadcrumb (not swallowed to 'null')" "yes" \
  "$(printf '%s' "$SC_DR_BAD_OUT" | grep -q 'could not inspect .prflow_review.agent_overrides' && echo yes || echo no)"
# A scalar prflow_review must not DETONATE the backfill or cleanup jq into a
# misdirected generic failure. The backfill still merges the other top-level keys
# (a non-object prflow_review short-circuits the graft-guard's `if` to `else .`),
# and the cleanup no-ops cleanly — so neither the "merge failed" nor the "cleanup
# failed" generic breadcrumb fires; only the accurate probe breadcrumb above does.
assert_eq "scaffold-migration: non-object prflow_review does NOT emit the misdirected backfill 'merge failed'" "no" \
  "$(printf '%s' "$SC_DR_BAD_OUT" | grep -q 'config-key backfill merge failed' && echo yes || echo no)"
assert_eq "scaffold-migration: non-object prflow_review does NOT emit the misdirected 'cleanup failed'" "no" \
  "$(printf '%s' "$SC_DR_BAD_OUT" | grep -q 'Haiku effort-cleanup failed' && echo yes || echo no)"
rm -rf "$SC_DR_BAD"

# 6d. Graft guard: a config that re-pins the deduper to a Haiku id WITHOUT effort
#     must NOT gain an effort key from the example's Sonnet-4.6+effort deduper
#     default via the backfill deep-merge (Haiku rejects effort with HTTP 400; an
#     ungated graft would re-fire on every re-scaffold and churn against the
#     cleanup). Start from a COMPLETE example-derived config so the ONLY thing the
#     backfill could change is the grafted effort — making this a precise probe.
SC_GRAFT="$(mktemp -d)"; mkdir -p "$SC_GRAFT/.prflow"
jq '.prflow_review.agent_overrides["prflow:checklist-deduper"] = {"model":"haiku"}' \
  "$TPL_DIR/config.example.json" > "$SC_GRAFT/.prflow/config.json"
SC_GRAFT_BEFORE="$(cat "$SC_GRAFT/.prflow/config.json")"
SC_GRAFT_OUT="$(bash "$SC" "$SC_GRAFT" 2>&1)"
assert_eq "scaffold-graft-guard: backfill does NOT graft effort onto a Haiku deduper" \
  "false" "$(jq '.prflow_review.agent_overrides["prflow:checklist-deduper"] | has("effort")' "$SC_GRAFT/.prflow/config.json")"
assert_eq "scaffold-graft-guard: Haiku deduper model preserved (haiku alias, issue #1646)" \
  "haiku" "$(jq -r '.prflow_review.agent_overrides["prflow:checklist-deduper"].model' "$SC_GRAFT/.prflow/config.json")"
assert_eq "scaffold-graft-guard: re-scaffold is a byte-identical quiet no-op" \
  "$SC_GRAFT_BEFORE" "$(cat "$SC_GRAFT/.prflow/config.json")"
assert_eq "scaffold-graft-guard: quiet no-op emits neither backfill nor cleanup log" "yes" \
  "$(printf '%s' "$SC_GRAFT_OUT" | grep -qE "backfilled newly-added keys|removed unsupported 'effort'" && echo no || echo yes)"
rm -rf "$SC_GRAFT"

# 6e. Graft-guard PRESERVE branch: a user who pins the deduper to a Haiku id WITH
#     their OWN effort must have that effort PRESERVED by the backfill (the
#     graft-guard strips only a *grafted* effort, never the user's) and removed by
#     the dedicated CLEANUP instead. SC_MIG only asserts the end state (effort
#     gone), which cannot tell "graft-guard preserved + cleanup stripped" from a
#     regression where "graft-guard wrongly stripped + cleanup no-op" — both leave
#     effort absent. Discriminate via the CLEANUP log: it fires only if the effort
#     SURVIVED the backfill into the cleanup. Start from a COMPLETE example-derived
#     config so the backfill is otherwise a byte-identical no-op.
SC_PRESERVE="$(mktemp -d)"; mkdir -p "$SC_PRESERVE/.prflow"
jq '.prflow_review.agent_overrides["prflow:checklist-deduper"] = {"model":"haiku","effort":"low"}' \
  "$TPL_DIR/config.example.json" > "$SC_PRESERVE/.prflow/config.json"
SC_PRESERVE_OUT="$(bash "$SC" "$SC_PRESERVE" 2>&1)"
# The discriminator: the cleanup log fires ⇒ the user's effort survived the backfill
# (graft-guard left it alone) and the dedicated cleanup is what stripped it. A
# regression that strips a user's own effort in the backfill would make the backfill
# log fire and the cleanup a silent no-op — failing this assertion.
assert_eq "scaffold-graft-guard: user's OWN Haiku effort survives backfill and is stripped by the cleanup" \
  "yes" "$(printf '%s' "$SC_PRESERVE_OUT" | grep -q "removed unsupported 'effort' from Haiku-pinned" && echo yes || echo no)"
assert_eq "scaffold-graft-guard: preserve-branch sees no backfill rewrite (graft-guard touched nothing)" \
  "no" "$(printf '%s' "$SC_PRESERVE_OUT" | grep -q 'backfilled newly-added keys' && echo yes || echo no)"
assert_eq "scaffold-graft-guard: preserve-branch effort ultimately removed" \
  "false" "$(jq '.prflow_review.agent_overrides["prflow:checklist-deduper"] | has("effort")' "$SC_PRESERVE/.prflow/config.json")"
assert_eq "scaffold-graft-guard: preserve-branch Haiku model kept through both passes (haiku alias, issue #1646)" \
  "haiku" "$(jq -r '.prflow_review.agent_overrides["prflow:checklist-deduper"].model' "$SC_PRESERVE/.prflow/config.json")"
rm -rf "$SC_PRESERVE"

# 6f. Robustness: a non-string `model` on ONE agent_overrides entry must not
#     detonate the whole backfill/cleanup jq and leave sibling Haiku entries
#     un-repaired. Without the `(.value.model | strings)` guard, `startswith` on a
#     non-string model errors (rc=5), aborting the filter for ALL entries — so a
#     valid Haiku+effort sibling keeps its HTTP-400 combo and the only breadcrumb
#     is a misdirected generic "jq error". The guard makes a non-string model fall
#     through `else .` (unmatched) so siblings are still repaired. Fixture: a
#     complete example-derived config with a valid Haiku+effort entry AND a
#     non-string-model entry.
SC_BADMODEL="$(mktemp -d)"; mkdir -p "$SC_BADMODEL/.prflow"
jq '.prflow_review.agent_overrides["prflow:checklist-generator"] = {"model":"haiku","effort":"high"}
    | .prflow_review.agent_overrides["prflow:checklist-verifier"] = {"model":{"oops":true},"effort":"low"}' \
  "$TPL_DIR/config.example.json" > "$SC_BADMODEL/.prflow/config.json"
bash "$SC" "$SC_BADMODEL" >/dev/null 2>&1; SC_BADMODEL_RC=$?
assert_eq "scaffold-robustness: non-string model entry does not abort the scaffold (exit 0)" \
  "0" "$SC_BADMODEL_RC"
assert_eq "scaffold-robustness: valid Haiku sibling still has its effort stripped despite a non-string-model entry" \
  "false" "$(jq '.prflow_review.agent_overrides["prflow:checklist-generator"] | has("effort")' "$SC_BADMODEL/.prflow/config.json")"
assert_eq "scaffold-robustness: the non-string-model entry is left untouched (unmatched, did not detonate the filter)" \
  "low" "$(jq -r '.prflow_review.agent_overrides["prflow:checklist-verifier"].effort' "$SC_BADMODEL/.prflow/config.json")"
rm -rf "$SC_BADMODEL"

# 6g. Unit-test the rewrite_config_if_changed helper in ISOLATION, sourced via the
#     library-only hook (DEVFLOW_SCAFFOLD_LIB_ONLY) so the helpers load without the
#     scaffold body running. This locks the two robustness arms the main flow's
#     validity gate keeps unreachable once it has passed: a normalization (jq)
#     failure must NOT phantom-rewrite, and a write (mv) failure must
#     log-and-continue. Run in a subshell so the helper's `set -euo pipefail` and
#     its log()/die() definitions never leak into the rest of the suite.
( export DEVFLOW_SCAFFOLD_LIB_ONLY=1
  # shellcheck disable=SC1090
  . "$SC"
  set +e +o pipefail
  # (a) cmpfail arm — the bug the helper exists to prevent: a left-hand (cfg)
  #     normalization failure must log the comparison-untrusted message and leave
  #     cfg untouched, NOT mv the candidate over it (the process-substitution
  #     phantom-rewrite trap).
  HU="$(mktemp -d)"
  printf '%s' 'not json' > "$HU/cfg.json"      # cfg fails jq --sort-keys
  printf '%s' '{"a":2}'  > "$HU/cand.json"      # cand is valid and differs
  HU_BEFORE="$(cat "$HU/cfg.json")"
  HU_OUT="$(rewrite_config_if_changed "$HU/cfg.json" "$HU/cand.json" "HELPERTEST-CHANGED" "HELPERTEST-CMPFAIL" 2>&1)"
  HU_RC=$?
  assert_eq "rewrite-helper: cmpfail arm returns 0 (does not abort the scaffold)" "0" "$HU_RC"
  assert_eq "rewrite-helper: cmpfail arm emits the comparison-untrusted message" "yes" \
    "$(printf '%s' "$HU_OUT" | grep -q 'HELPERTEST-CMPFAIL' && echo yes || echo no)"
  assert_eq "rewrite-helper: cmpfail arm does NOT phantom-rewrite (cfg bytes survive)" \
    "$HU_BEFORE" "$(cat "$HU/cfg.json")"
  assert_eq "rewrite-helper: cmpfail arm does NOT emit the changed message" "no" \
    "$(printf '%s' "$HU_OUT" | grep -q 'HELPERTEST-CHANGED' && echo yes || echo no)"
  rm -rf "$HU"

  # (b) happy path: two differing valid configs ARE rewritten, changed message fires.
  HU_OK="$(mktemp -d)"
  printf '%s' '{"a":1}' > "$HU_OK/cfg.json"
  printf '%s' '{"a":2}' > "$HU_OK/cand.json"
  HU_OK_OUT="$(rewrite_config_if_changed "$HU_OK/cfg.json" "$HU_OK/cand.json" "HELPERTEST-CHANGED" "HELPERTEST-CMPFAIL" 2>&1)"
  assert_eq "rewrite-helper: happy path rewrites the config (cand wins)" "2" \
    "$(jq -r '.a' "$HU_OK/cfg.json")"
  assert_eq "rewrite-helper: happy path emits the changed message" "yes" \
    "$(printf '%s' "$HU_OK_OUT" | grep -q 'HELPERTEST-CHANGED' && echo yes || echo no)"
  rm -rf "$HU_OK"

  # (c) mv-failure arm: a write failure must log-and-continue (return 0), leaving
  #     the original bytes — not abort under set -euo pipefail. Provoked by making
  #     cfg's directory unwritable, which only bites a non-root user; root bypasses
  #     permission bits, so skip there (CI runs non-root and exercises this).
  if [ "$(id -u)" -ne 0 ]; then
    HU_RO="$(mktemp -d)"
    printf '%s' '{"a":1}' > "$HU_RO/cfg.json"
    HU_CAND="$(mktemp)"
    printf '%s' '{"a":2}' > "$HU_CAND"
    HU_RO_BEFORE="$(cat "$HU_RO/cfg.json")"
    chmod a-w "$HU_RO"
    HU_RO_OUT="$(rewrite_config_if_changed "$HU_RO/cfg.json" "$HU_CAND" "HELPERTEST-CHANGED" "HELPERTEST-CMPFAIL" 2>&1)"
    HU_RO_RC=$?
    chmod u+w "$HU_RO"
    assert_eq "rewrite-helper: mv-failure arm returns 0 (logs-and-continues)" "0" "$HU_RO_RC"
    assert_eq "rewrite-helper: mv-failure arm emits the could-not-write message" "yes" \
      "$(printf '%s' "$HU_RO_OUT" | grep -q 'could not write' && echo yes || echo no)"
    assert_eq "rewrite-helper: mv-failure arm leaves the original bytes intact" \
      "$HU_RO_BEFORE" "$(cat "$HU_RO/cfg.json")"
    rm -rf "$HU_RO" "$HU_CAND"
  fi
)

# 6h. Positive jq-EXECUTION-failure path for the backfill arm: a CORRUPT
#     config.example.json next to a COPY of the scaffolder makes the backfill's
#     `jq -n --slurpfile ex ...` fail to PARSE the template (not merely be absent),
#     so the "merge failed (jq error)" arm fires for real — it previously had only
#     negative assertions. The existing valid config.json is left untouched and the
#     scaffold still exits 0 (best-effort). Mirrors the SC_NOTPL copy-the-script
#     layout so the template resolves next to the copy.
SC_JQERR="$(mktemp -d)"; mkdir -p "$SC_JQERR/scripts" "$SC_JQERR/.prflow"
cp "$SC" "$SC_JQERR/scripts/scaffold-config.sh"
printf '%s' '{ corrupt example'   > "$SC_JQERR/.prflow/config.example.json"
cp "$TPL_DIR/config.schema.json"    "$SC_JQERR/.prflow/config.schema.json"
SC_JQERR_TGT="$(mktemp -d)"; mkdir -p "$SC_JQERR_TGT/.prflow"
printf '%s' '{"sentinel":true}'    > "$SC_JQERR_TGT/.prflow/config.json"
SC_JQERR_OUT="$(bash "$SC_JQERR/scripts/scaffold-config.sh" "$SC_JQERR_TGT" 2>&1)"; SC_JQERR_RC=$?
assert_eq "scaffold-jqerr: corrupt example template → scaffold still exits 0 (best-effort)" \
  "0" "$SC_JQERR_RC"
assert_eq "scaffold-jqerr: corrupt example template → the backfill 'merge failed (jq error)' arm fires" "yes" \
  "$(printf '%s' "$SC_JQERR_OUT" | grep -q 'config-key backfill merge failed (jq error)' && echo yes || echo no)"
assert_eq "scaffold-jqerr: corrupt example template → existing config left untouched (no clobber)" \
  '{"sentinel":true}' "$(cat "$SC_JQERR_TGT/.prflow/config.json")"
rm -rf "$SC_JQERR" "$SC_JQERR_TGT"

# ────────────────────────────────────────────────────────────────────────────
echo "scaffold-config.sh: scaffolds an inert prompt-extension example for EVERY skill"
# ────────────────────────────────────────────────────────────────────────────
# Scaffolding must create .prflow/prompt-extensions/<skill>.md.example for every
# skill under skills/ (issue #95), not just create-issue. Each example is INERT:
# the `.example` suffix keeps it from matching the live `<skill>.md` that
# load-prompt-extension.sh treats as an extension, and its whole body is an HTML
# comment so even a misrename that drops `.example` injects no actionable text. The
# expected skill set is DERIVED from skills/*/ (the same source of truth the
# SKILL.md coverage guard uses), so this doubles as a drift guard: a new skill the
# scaffolder's authored list forgets fails the per-skill assertions below.
SC="$LIB/../scripts/scaffold-config.sh"
LPE="$LIB/../scripts/load-prompt-extension.sh"
SC_PE="$(mktemp -d)"
SC_PE_OUT="$(bash "$SC" "$SC_PE" 2>&1)"
SC_PE_DIR="$SC_PE/.prflow/prompt-extensions"

assert_eq "scaffold-pe: .prflow/prompt-extensions/ created" "yes" \
  "$([ -d "$SC_PE_DIR" ] && echo yes || echo no)"

SC_PE_MISSING=""; SC_PE_NOTCOMMENT=""; SC_PE_NOHINT=""; SC_PE_EMPTYHINT=""; SC_PE_LIVE=""; SC_PE_NOTINERT=""
for SKILL_DIR in "$LIB"/../skills/*/; do
  skill="$(basename "$SKILL_DIR")"
  f="$SC_PE_DIR/$skill.md.example"
  if [ -f "$f" ]; then
    # AC 3: body is a SINGLE comment block — first non-blank line opens `<!--`,
    # last non-blank line closes `-->`. Read the file once, then slice.
    nonblank="$(grep -v '^[[:space:]]*$' "$f")"
    first="$(printf '%s\n' "$nonblank" | head -n1)"
    last="$(printf '%s\n' "$nonblank" | tail -n1)"
    case "$first" in '<!--'*) : ;; *) SC_PE_NOTCOMMENT="$SC_PE_NOTCOMMENT $skill" ;; esac
    case "$last"  in *'-->')  : ;; *) SC_PE_NOTCOMMENT="$SC_PE_NOTCOMMENT $skill" ;; esac
    # AC 4: a per-skill hint line naming the skill, distinct from the boilerplate.
    grep -qF "Useful extension for $skill:" "$f" || SC_PE_NOHINT="$SC_PE_NOHINT $skill"
    # AC 4 (strengthened): the hint must be NON-EMPTY — `Useful extension for <skill>: `
    # with nothing after the colon-space would pass the bare presence check above but
    # ship a hint-less example. Require at least one char after the literal prefix.
    grep -qE "Useful extension for $skill: .+" "$f" || SC_PE_EMPTYHINT="$SC_PE_EMPTYHINT $skill"
  else
    SC_PE_MISSING="$SC_PE_MISSING $skill"   # AC 1
  fi
  # AC 2: the .example suffix means no live `<skill>.md` is ever scaffolded.
  [ -e "$SC_PE_DIR/$skill.md" ] && SC_PE_LIVE="$SC_PE_LIVE $skill"
  # AC 5: the REAL reader treats the scaffolded example as an inert no-op
  # (empty stdout + exit 0) — exercised, not mocked.
  RDR_OUT="$(cd "$SC_PE" && bash "$LPE" "$skill" 2>/dev/null)"; RDR_RC=$?
  { [ -z "$RDR_OUT" ] && [ "$RDR_RC" -eq 0 ]; } || SC_PE_NOTINERT="$SC_PE_NOTINERT $skill"
done
assert_eq "scaffold-pe: an example exists for every skill (AC 1)" "" "$SC_PE_MISSING"
assert_eq "scaffold-pe: every example body is a single HTML comment block (AC 3)" "" "$SC_PE_NOTCOMMENT"
assert_eq "scaffold-pe: every example carries a per-skill hint line (AC 4)" "" "$SC_PE_NOHINT"
assert_eq "scaffold-pe: every per-skill hint is non-empty (AC 4)" "" "$SC_PE_EMPTYHINT"
assert_eq "scaffold-pe: no live <skill>.md scaffolded — only .example (AC 2)" "" "$SC_PE_LIVE"
assert_eq "scaffold-pe: real load-prompt-extension reader is inert no-op for every skill (AC 5)" "" "$SC_PE_NOTINERT"
# Drift guard (bidirectional): the set of scaffolded `<skill>.md.example` basenames must
# EQUAL the set of skills under skills/*/ — catching BOTH a forgotten skill (forward
# drift: a skills/ dir with no example) AND a stale heredoc row (reverse drift: an
# orphan example for a renamed/removed skill that the per-skill loop above never visits).
SC_PE_EXPECTED="$(for d in "$LIB"/../skills/*/; do basename "$d"; done | sort | tr '\n' ' ')"
SC_PE_GOT="$(for ex in "$SC_PE_DIR"/*.md.example; do b="$(basename "$ex")"; printf '%s\n' "${b%.md.example}"; done | sort | tr '\n' ' ')"
assert_eq "scaffold-pe: scaffolded example set EQUALS skills/*/ (no missing, no orphan)" \
  "$SC_PE_EXPECTED" "$SC_PE_GOT"
# Atomic-write contract: the scaffolder writes each example to `<skill>.md.example.tmp`
# and `mv`s it into place, so a successful scaffold leaves NO `.tmp` behind (the mv
# consumed it). Pin it — every other glob here filters to `*.md.example`, so a
# regression (e.g. cp instead of mv, or a dropped rm -f) that stranded a temp would
# otherwise be invisible. Glob + [ -e ] (nullglob-off leaves the literal pattern, which
# [ -e ] rejects) rather than spawning ls.
assert_eq "scaffold-pe: no .tmp temp survives a successful scaffold (atomic mv consumed it)" "no" \
  "$(set -- "$SC_PE_DIR"/*.md.example.tmp; [ -e "$1" ] && echo yes || echo no)"
# AC 9 (created half): a creation log line is emitted on a fresh scaffold. Match the
# literal "prompt-extension example" — NOT just the dir path "prompt-extensions/",
# which any mention would satisfy — so the assertion pins the new reporting line.
assert_eq "scaffold-pe: emits a creation log line on a fresh scaffold (AC 9)" "yes" \
  "$(printf '%s\n' "$SC_PE_OUT" | grep -qF 'prompt-extension example' && echo yes || echo no)"
# Coupled-mirror guard (#443): the create-issue example the scaffolder EMITS must be byte-identical
# to this repo's COMMITTED .prflow/prompt-extensions/create-issue.md.example, so the inert
# `## Audit dimensions` sample cannot drift between the generator and the committed copy readers see.
assert_eq "scaffold-pe: emitted create-issue example matches the committed copy (#443 coupled mirror)" \
  "$(cat "$LIB/../.prflow/prompt-extensions/create-issue.md.example")" \
  "$(cat "$SC_PE_DIR/create-issue.md.example")"
# #548: the generated create-issue example carries the inert `## Evidence axes` sample (the
# Step 2 evidence-bundle forwarding hook), mirroring the `## Audit dimensions` sample. Assert
# the emitted example (driven by the generator, not just the committed copy) contains it.
assert_eq "scaffold-pe: emitted create-issue example carries the inert ## Evidence axes sample (#548)" "yes" \
  "$(grep -qF '## Evidence axes' "$SC_PE_DIR/create-issue.md.example" && echo yes || echo no)"

# AC 7 + AC 9 (no-op half): a second run rewrites nothing (every example
# byte-identical) and emits NO creation log line.
SC_PE_SUM1="$(find "$SC_PE_DIR" -type f -name '*.example' | sort | xargs cksum)"
SC_PE_OUT2="$(bash "$SC" "$SC_PE" 2>&1)"
SC_PE_SUM2="$(find "$SC_PE_DIR" -type f -name '*.example' | sort | xargs cksum)"
assert_eq "scaffold-pe: idempotent re-run keeps every example byte-identical (AC 7)" \
  "$SC_PE_SUM1" "$SC_PE_SUM2"
assert_eq "scaffold-pe: no creation log line on an all-present no-op re-run (AC 9)" "no" \
  "$(printf '%s\n' "$SC_PE_OUT2" | grep -qF 'prompt-extension example' && echo yes || echo no)"
rm -rf "$SC_PE"

# AC 6 (partial backfill): a dir that already holds ONLY create-issue.md.example
# (an adopter who ran /devflow:init before issue #95) gets the other skills backfilled,
# and the pre-existing create-issue.md.example is left byte-identical (never clobbered).
# (AC 8 — adopter live-file safety — is asserted in the separate block further below.)
SC_PE_BF="$(mktemp -d)"
mkdir -p "$SC_PE_BF/.prflow/prompt-extensions"
printf 'SENTINEL-PREEXISTING-EXAMPLE\n' > "$SC_PE_BF/.prflow/prompt-extensions/create-issue.md.example"
SC_PE_BF_SENT="$(cat "$SC_PE_BF/.prflow/prompt-extensions/create-issue.md.example")"
bash "$SC" "$SC_PE_BF" >/dev/null 2>&1
SC_PE_BF_MISSING=""
for SKILL_DIR in "$LIB"/../skills/*/; do
  skill="$(basename "$SKILL_DIR")"
  [ "$skill" = "create-issue" ] && continue
  [ -f "$SC_PE_BF/.prflow/prompt-extensions/$skill.md.example" ] || SC_PE_BF_MISSING="$SC_PE_BF_MISSING $skill"
done
assert_eq "scaffold-pe: partial backfill creates the other examples (AC 6)" "" "$SC_PE_BF_MISSING"
assert_eq "scaffold-pe: partial backfill leaves the pre-existing example byte-identical (AC 6)" \
  "$SC_PE_BF_SENT" "$(cat "$SC_PE_BF/.prflow/prompt-extensions/create-issue.md.example")"
rm -rf "$SC_PE_BF"

# AC 8 (adopter live-file safety): a real review.md the adopter authored (no .example
# suffix → a LIVE extension) is never overwritten/deleted, and — because a live
# extension already exists for that skill — the scaffolder does NOT drop a redundant
# review.md.example beside it (issue #118). The guard is per-skill, so the OTHER skills
# still get their .example backfilled.
SC_PE_LV="$(mktemp -d)"
mkdir -p "$SC_PE_LV/.prflow/prompt-extensions"
printf 'ADOPTER LIVE REVIEW RULES\n' > "$SC_PE_LV/.prflow/prompt-extensions/review.md"
SC_PE_LV_SENT="$(cat "$SC_PE_LV/.prflow/prompt-extensions/review.md")"
bash "$SC" "$SC_PE_LV" >/dev/null 2>&1
assert_eq "scaffold-pe: adopter's live review.md is untouched (AC 8)" \
  "$SC_PE_LV_SENT" "$(cat "$SC_PE_LV/.prflow/prompt-extensions/review.md")"
assert_eq "scaffold-pe: NO review.md.example created when a live review.md exists (AC 8)" "no" \
  "$([ -e "$SC_PE_LV/.prflow/prompt-extensions/review.md.example" ] && echo yes || echo no)"
# The live-extension guard is scoped to that one skill — other skills still get examples.
assert_eq "scaffold-pe: other skills still get .example beside a live review.md (AC 8)" "yes" \
  "$([ -f "$SC_PE_LV/.prflow/prompt-extensions/docs.md.example" ] && echo yes || echo no)"
rm -rf "$SC_PE_LV"

# AC 8 (compose): both a live review.md AND a pre-existing review.md.example present →
# neither is modified or deleted. The live-.md guard and the pre-existing-.example guard
# compose; the scaffolder stays non-destructive on both.
SC_PE_BOTH="$(mktemp -d)"
mkdir -p "$SC_PE_BOTH/.prflow/prompt-extensions"
printf 'ADOPTER LIVE REVIEW RULES\n' > "$SC_PE_BOTH/.prflow/prompt-extensions/review.md"
printf 'SENTINEL-PREEXISTING-REVIEW-EXAMPLE\n' > "$SC_PE_BOTH/.prflow/prompt-extensions/review.md.example"
SC_PE_BOTH_MD="$(cat "$SC_PE_BOTH/.prflow/prompt-extensions/review.md")"
SC_PE_BOTH_EX="$(cat "$SC_PE_BOTH/.prflow/prompt-extensions/review.md.example")"
bash "$SC" "$SC_PE_BOTH" >/dev/null 2>&1
assert_eq "scaffold-pe: live review.md untouched when its .example also exists (AC 8 compose)" \
  "$SC_PE_BOTH_MD" "$(cat "$SC_PE_BOTH/.prflow/prompt-extensions/review.md")"
assert_eq "scaffold-pe: pre-existing review.md.example untouched beside a live review.md (AC 8 compose)" \
  "$SC_PE_BOTH_EX" "$(cat "$SC_PE_BOTH/.prflow/prompt-extensions/review.md.example")"
rm -rf "$SC_PE_BOTH"

# Write-failure path (best-effort / silent-failure contract): a per-file write that
# fails must NOT abort the scaffold — it logs a breadcrumb naming the file and
# continues (matching rewrite_config_if_changed and the jq blocks). Make the
# prompt-extensions dir read-only so every write fails; assert the scaffolder still
# exits 0, emits a "could not write" breadcrumb, and leaves no .example at the guarded
# path. The scaffolder writes to a temp and mv's it into place atomically, so a failed
# write can NEVER leave a partial/zero-byte <skill>.md.example that the [ -e ] guard
# would then treat as present and never retry — the no-leftover assertion below holds by
# construction (atomicity), not by hoping a failed redirect wrote nothing. Root bypasses
# the perm bits, so skip under root (as the lpe unreadable test does).
SC_PE_WF="$(mktemp -d)"
mkdir -p "$SC_PE_WF/.prflow/prompt-extensions"
chmod 555 "$SC_PE_WF/.prflow/prompt-extensions"
if [ "$(id -u)" -ne 0 ] && [ ! -w "$SC_PE_WF/.prflow/prompt-extensions" ]; then
  SC_PE_WF_OUT="$(bash "$SC" "$SC_PE_WF" 2>&1)"; SC_PE_WF_RC=$?
  assert_eq "scaffold-pe: a write failure does not abort the scaffold (exit 0)" "0" "$SC_PE_WF_RC"
  assert_eq "scaffold-pe: a write failure emits a 'could not write' breadcrumb" "yes" \
    "$(printf '%s\n' "$SC_PE_WF_OUT" | grep -qF 'could not write' && echo yes || echo no)"
  assert_eq "scaffold-pe: a write failure leaves no zero-byte .example leftover" "no" \
    "$(set -- "$SC_PE_WF/.prflow/prompt-extensions/"*.md.example; [ -e "$1" ] && echo yes || echo no)"
  assert_eq "scaffold-pe: a write failure leaves no .tmp temp behind" "no" \
    "$(set -- "$SC_PE_WF/.prflow/prompt-extensions/"*.md.example.tmp; [ -e "$1" ] && echo yes || echo no)"
fi
chmod 755 "$SC_PE_WF/.prflow/prompt-extensions"
rm -rf "$SC_PE_WF"

# ────────────────────────────────────────────────────────────────────────────
echo "load-prompt-extension.sh (consumer prompt-extension reader)"
# ────────────────────────────────────────────────────────────────────────────
# Extracted to lib/test/modules/prompt-extension-reader.sh (issue #746). The
# module owns the whole former in-file section; see its .inventory.md for the
# coverage map back to this location.
if ! devflow_run_full_suite_module "$LIB/test/modules/prompt-extension-reader.sh" \
  "prompt-extension-reader" 177; then
  printf 'ERROR: prompt-extension-reader boundary could not record its result\n'
  exit 1
fi

# ────────────────────────────────────────────────────────────────────────────
echo "#295: repo-root anchoring — config/extension readers resolve from a subdir"
# ────────────────────────────────────────────────────────────────────────────
# Issue #295: the five .prflow/ readers (config-get.sh, load-prompt-extension.sh,
# workpad.py, match-deferrals.py, match-lint-adjudications.py) anchor the DEFAULT
# config/extension path to the git
# repo root (git rev-parse --show-toplevel, cwd fallback) so a skill invoked from a
# subdirectory loads the consumer's ROOT config/extension instead of silently missing
# it. Build a real temp git repo with .prflow/ at the root, cd into a nested subdir,
# and assert each reader resolves the root file. These assertions fail on the pre-#295
# (cwd-relative) code for the right reason (default/empty/wrong path) — proven live via
# a git-show-HEAD comparison during implementation.
R295="$(git_sandbox "#295 root-anchor sandbox")"
git -C "$R295" init -q
git -C "$R295" config user.email t@example.com; git -C "$R295" config user.name t
mkdir -p "$R295/.prflow/prompt-extensions" "$R295/a/b/c"
printf '{"docs":{"internal":"CUSTOM/DOCS"},"prflow":{"workpad_marker":"<!-- m295 -->","allowed_bots":"botX,botY"}}' > "$R295/.prflow/config.json"
printf 'EXT-295\n' > "$R295/.prflow/prompt-extensions/implement.md"
# Derive the expected root from git itself so the path compare is symlink-robust
# (macOS /tmp → /private/tmp): both the test and the reader use --show-toplevel.
R295_TOP="$(git -C "$R295" rev-parse --show-toplevel)"
MD295="$LIB/../scripts/match-deferrals.py"

# AC1: loader from a subdir prints the ROOT extension bytes verbatim.
assert_eq "#295 AC1: loader from subdir → root extension bytes" "EXT-295" \
  "$(cd "$R295/a/b/c" && bash "$LPE" implement 2>/dev/null)"
# AC2: config-get (no explicit config arg) from a subdir → configured value, not default.
assert_eq "#295 AC2: config-get from subdir → configured value not default" "CUSTOM/DOCS" \
  "$(cd "$R295/a/b/c" && bash "$CG" .docs.internal FALLBACK)"
# AC3: workpad.py marker from a subdir → ROOT marker (direct in-process resolution).
assert_eq "#295 AC3: workpad marker from subdir → root marker" "<!-- m295 -->" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('w','$WP_PY');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._workpad_marker())")"
# AC4: match-deferrals default config path from a subdir → ROOT config (its explicit-arg
# passing no longer defeats root anchoring).
assert_eq "#295 AC4: match-deferrals default config from subdir → root config" "$R295_TOP/.prflow/config.json" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('md','$MD295');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._default_config_path())")"
# Lockstep: config-get.sh resolves the SAME root config from the subdir (a value only the
# root config carries proves it read that file, not a cwd-relative miss).
assert_eq "#295 lockstep: all readers resolve the identical root config from subdir" "botX,botY" \
  "$(cd "$R295/a/b/c" && bash "$CG" .prflow.allowed_bots MISS)"
# AC4 (end-to-end): match-deferrals' _config_get(config_path=None) actually INVOKES
# _default_config_path() and reads the ROOT config VALUE from a subdir — proving the
# config_path=None wiring, not just _default_config_path() in isolation (a revert of the
# None default to a cwd-relative constant would leave the AC4 path-equality green but this
# value read RED).
assert_eq "#295 AC4: match-deferrals _config_get(None) reads ROOT allowed_bots from subdir" "botX,botY" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('md','$MD295');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._config_get('.prflow.allowed_bots','MISS'))")"

# AC6 (#466): match-lint-adjudications.py is the FIFTH reader in this family — it carries its
# own _repo_root()/_default_config_path()/_config_get() copy, so it gets the same pair of
# assertions as match-deferrals (path equality AND the config_path=None value read, since
# pinning the path in isolation misses the None wiring).
MLA295="$LIB/../scripts/match-lint-adjudications.py"
assert_eq "#295 AC6: match-lint-adjudications default config from subdir → root config" "$R295_TOP/.prflow/config.json" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('mla','$MLA295');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._default_config_path())")"
assert_eq "#295 AC6: match-lint-adjudications _config_get(None) reads ROOT allowed_bots from subdir" "botX,botY" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('mla','$MLA295');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._config_get('.prflow.allowed_bots','MISS'))")"

# AC5: cwd == root → byte-identical to the subdir result (no regression on common path).
assert_eq "#295 AC5: config-get at root byte-identical" "CUSTOM/DOCS" \
  "$(cd "$R295" && bash "$CG" .docs.internal FALLBACK)"
assert_eq "#295 AC5: loader at root byte-identical" "EXT-295" \
  "$(cd "$R295" && bash "$LPE" implement 2>/dev/null)"

# AC8: explicit CONFIG_FILE (3rd arg) honored verbatim from a subdir (root anchoring
# applies only to the default).
printf '{"docs":{"internal":"EXPLICIT"}}' > "$R295/explicit.json"
assert_eq "#295 AC8: explicit CONFIG_FILE 3rd arg honored from subdir" "EXPLICIT" \
  "$(cd "$R295/a/b/c" && bash "$CG" .docs.internal FALLBACK "$R295/explicit.json")"
# AC8b: match-deferrals' explicit config_path is honored verbatim over the root default
# from a subdir — pins the `if config_path is None` guard's NON-None arm. A regression
# dropping that guard (always calling _default_config_path()) would return the ROOT
# CUSTOM/DOCS value instead of EXPLICIT and turn this RED while AC4 stayed green.
assert_eq "#295 AC8b: match-deferrals explicit config_path honored over root default" "EXPLICIT" \
  "$(cd "$R295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('md','$MD295');m=u.module_from_spec(s);s.loader.exec_module(m);print(m._config_get('.docs.internal','FALLBACK','$R295/explicit.json'))")"
# AC8c: an explicit EMPTY 3rd arg still selects the root-anchored default — pins the
# `[ -n "${3:-}" ]` gate (NOT `$# -ge 3`/`${3:-…}`). A revert of that gate would set
# config_file="" (an unopenable empty path) and silently drop to FALLBACK; this stays
# RED on that revert while AC8 (non-empty explicit) stays green.
assert_eq "#295 AC8c: explicit EMPTY CONFIG_FILE 3rd arg selects root default" "CUSTOM/DOCS" \
  "$(cd "$R295/a/b/c" && bash "$CG" .docs.internal FALLBACK "")"

# AC6: non-git tree with a .prflow/ at cwd → falls back to pwd and still resolves.
NG295="$(git_sandbox "#295 non-git .prflow sandbox")"
mkdir -p "$NG295/.prflow"
printf '{"docs":{"internal":"NONGIT"}}' > "$NG295/.prflow/config.json"
assert_eq "#295 AC6: non-git tree, .prflow at cwd → resolves via pwd fallback" "NONGIT" \
  "$(cd "$NG295" && bash "$CG" .docs.internal FALLBACK)"

# AC7: neither git root nor .prflow/ → a single non-empty stderr breadcrumb, defaults used.
BARE295="$(git_sandbox "#295 bare tree sandbox")"
BARE295_ERR="$(cd "$BARE295" && bash "$CG" .docs.internal FALLBACK 2>&1 >/dev/null)"
assert_eq "#295 AC7: bare tree (no git root, no .prflow) → non-empty stderr breadcrumb" "yes" \
  "$([ -n "$BARE295_ERR" ] && echo yes || echo no)"
assert_eq "#295 AC7: bare tree still returns the default value" "FALLBACK" \
  "$(cd "$BARE295" && bash "$CG" .docs.internal FALLBACK 2>/dev/null)"
# The loader emits its OWN distinct breadcrumb on the same bare-tree path.
BARE295_LPE_ERR="$(cd "$BARE295" && bash "$LPE" implement 2>&1 >/dev/null)"
assert_eq "#295 AC7: loader bare tree → non-empty stderr breadcrumb" "yes" \
  "$([ -n "$BARE295_LPE_ERR" ] && echo yes || echo no)"
# AC7 completeness: the two PYTHON readers must ALSO emit a bare-tree breadcrumb (AC7
# says *each* reader). Pop DEVFLOW_WORKPAD_MARKER so the marker read reaches the config
# path rather than short-circuiting on an ambient env override.
BARE295_WP_ERR="$(cd "$BARE295" && python3 -c "import os;os.environ.pop('DEVFLOW_WORKPAD_MARKER',None);import importlib.util as u;s=u.spec_from_file_location('w','$WP_PY');m=u.module_from_spec(s);s.loader.exec_module(m);m._workpad_marker(None)" 2>&1 >/dev/null)"
assert_eq "#295 AC7: workpad marker bare tree → non-empty stderr breadcrumb" "yes" \
  "$([ -n "$BARE295_WP_ERR" ] && echo yes || echo no)"
BARE295_MD_ERR="$(cd "$BARE295" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('md','$MD295');m=u.module_from_spec(s);s.loader.exec_module(m);m._default_config_path()" 2>&1 >/dev/null)"
assert_eq "#295 AC7: match-deferrals bare tree → non-empty stderr breadcrumb" "yes" \
  "$([ -n "$BARE295_MD_ERR" ] && echo yes || echo no)"

# AC10: git-root-with-NO-.prflow/ (the normal unconfigured in-git case) → each reader
# stays SILENT and returns the default. This is the exact NEGATIVE of the AC7 bare-tree
# breadcrumb: every reader emits its breadcrumb ONLY when NEITHER a git root NOR a
# .prflow/ is found, so a regression moving the .prflow-existence check OUTSIDE the
# `if [ -z "$_devflow_root" ]` guard would spam stderr on every normal unconfigured
# in-git run (the overwhelmingly common case) with no other assertion going RED.
SIL295="$(git_sandbox "#295 git-root no-.prflow silence sandbox")"
git -C "$SIL295" init -q
git -C "$SIL295" config user.email t@example.com; git -C "$SIL295" config user.name t
mkdir -p "$SIL295/a/b/c"   # a real git root, deliberately NO .prflow/ anywhere
# config-get: default value returned AND empty stderr (git root found → .prflow check
# is skipped → no breadcrumb).
assert_eq "#295 AC10: config-get git-root-no-.prflow returns the default" "FALLBACK" \
  "$(cd "$SIL295/a/b/c" && bash "$CG" .docs.internal FALLBACK 2>/dev/null)"
assert_eq "#295 AC10: config-get git-root-no-.prflow stays SILENT (empty stderr)" "" \
  "$(cd "$SIL295/a/b/c" && bash "$CG" .docs.internal FALLBACK 2>&1 >/dev/null)"
# loader: no-op with empty STDOUT. Since issue #1299 the whole-file no-op arm emits a
# `PROMPT-EXTENSION-STATUS: present-empty` stderr line, so this AC10 guard checks the ABSENCE
# of the #295 could-not-resolve breadcrumb (the regression it protects) rather than empty stderr.
assert_eq "#295 AC10: loader git-root-no-.prflow emits no could-not-resolve breadcrumb" "yes" \
  "$(cd "$SIL295/a/b/c" && bash "$LPE" implement 2>&1 >/dev/null | grep -qF 'could not resolve' && echo no || echo yes)"
# workpad marker: default marker AND empty stderr (pop the env override so the read
# reaches the config path).
assert_eq "#295 AC10: workpad marker git-root-no-.prflow stays SILENT (empty stderr)" "" \
  "$(cd "$SIL295/a/b/c" && python3 -c "import os;os.environ.pop('DEVFLOW_WORKPAD_MARKER',None);import importlib.util as u;s=u.spec_from_file_location('w','$WP_PY');m=u.module_from_spec(s);s.loader.exec_module(m);m._workpad_marker(None)" 2>&1 >/dev/null)"
# match-deferrals default path: resolves the git-root .prflow/config.json AND empty stderr.
assert_eq "#295 AC10: match-deferrals git-root-no-.prflow stays SILENT (empty stderr)" "" \
  "$(cd "$SIL295/a/b/c" && python3 -c "import importlib.util as u;s=u.spec_from_file_location('md','$MD295');m=u.module_from_spec(s);s.loader.exec_module(m);m._default_config_path()" 2>&1 >/dev/null)"

rm -rf "$R295" "$NG295" "$BARE295" "$SIL295"

# ────────────────────────────────────────────────────────────────────────────
echo "load-prompt-extension.sh: every skills/*/SKILL.md carries the standardized step"
# ────────────────────────────────────────────────────────────────────────────
# Coverage / drift guard (issue #84, AC 6 + AC 7). The standardized step spans
# every skill's SKILL.md; this enumeration is the enforcement that keeps them in
# sync (a cross-file drift hazard). Pin BOTH the
# canonical helper path-suffix AND the skill's own directory name so a copy-paste
# of the wrong skill name, a half-applied removal, or a path drift all fail here
# rather than shipping silently. Fails when a future skill omits the step.
LPE_SKILL_COUNT=0
# The skills whose extension is handed to them BY PATH rather than loaded by the
# helper — dispatched subagent briefs that resolve no anchor (Stage A `retrospective`,
# issue #1333; Stage B `retrospective-audit`, issue #1338). Named once here as a
# space-delimited set rather than inlined in the loop so the by-value population stays a
# single declared value, like PA_NO_CALLSITE / PORTABLE_ANCHOR_LITERAL.
LPE_BYVALUE_SKILLS='retrospective retrospective-audit'
for SKILL_DIR in "$LIB"/../skills/*/; do
  SKILL_NAME="$(basename "$SKILL_DIR")"
  SKILL_FILE="$SKILL_DIR/SKILL.md"
  LPE_SKILL_COUNT=$((LPE_SKILL_COUNT + 1))
  # Match the FULL canonical invocation as a whole line (grep -Fx), per AC 6's
  # `${CLAUDE_SKILL_DIR}/../../scripts/load-prompt-extension.sh <skill-name>` form.
  # Whole-line fixed-string matching (a) pins each skill's OWN name so a short name
  # that is a prefix of a sibling (docs vs docs-verify, review vs review-and-fix)
  # cannot vacuously match, and (b) rejects a prose mention or a commented-out /
  # HTML-comment-wrapped reference — only a live, exact invocation line passes, so
  # a future edit that comments out the step (leaving a stale reference) fails here.
  # Issue #275: EVERY skill resolves the anchor inline in the invocation statement
  # itself (the single-statement portable form — no bare ${CLAUDE_SKILL_DIR} expansion,
  # and no cross-statement $SKILL_DIR assignment, which Copilot CLI's inline-bash
  # marshaling defeats). One canonical line, pinned whole-line (grep -Fx), so a
  # name/path drift still fails here.
  LPE_EXPECT_LINE='"${CLAUDE_SKILL_DIR:-<absolute skill base directory this runner reports in context>}"/../../scripts/load-prompt-extension.sh '"$SKILL_NAME"
  # #1333: the enumeration presupposes the skill can RUN the loader. That is false for
  # a dispatched subagent brief, which resolves no anchor (measured on Claude Code
  # 2.1.222: `printenv CLAUDE_SKILL_DIR` exits 1 with no output inside a Task subagent,
  # and no `Base directory for this skill:` line reaches it). Its extension arrives BY
  # PATH from the orchestrator and is read with the file-read tool, so both the
  # invocation line and the helper-exit-code prose are gone by design. Assert the
  # COMPLEMENT instead, so the exemption cannot hide a reintroduced invocation.
  case " $LPE_BYVALUE_SKILLS " in *" $SKILL_NAME "*) LPE_BYVALUE_HIT=1 ;; *) LPE_BYVALUE_HIT=0 ;; esac
  if [ "$LPE_BYVALUE_HIT" = 1 ]; then
    assert_eq "lpe-coverage(#1333/#1338): $SKILL_NAME/SKILL.md carries NO loader invocation (extension handed by path)" "yes" \
      "$([ -f "$SKILL_FILE" ] && ! grep -Fxq "$LPE_EXPECT_LINE" "$SKILL_FILE" && echo yes || echo no)"  # raw-guard-ok: loop body: absence pin whose target is the $SKILL_FILE loop variable
    continue
  fi
  assert_eq "lpe-coverage: $SKILL_NAME/SKILL.md invokes the helper for its own name" "yes" \
    "$([ -f "$SKILL_FILE" ] && grep -Fxq "$LPE_EXPECT_LINE" "$SKILL_FILE" && echo yes || echo no)"  # raw-guard-ok: loop body: SKILL target is the $SKILL_FILE loop variable, not a static pin
  # The invocation line alone is half the contract — the step must also tell the
  # model to HONOR the helper's exit code (surface a non-zero exit, don't silently
  # proceed). Pin a BLOCK-UNIQUE fragment of that prose, NOT a generic one: the
  # phrase "exits non-zero" recurs elsewhere in review/SKILL.md and the
  # review-and-fix references (their dismiss-stale / config-get prose), so a generic
  # grep would false-pass for those two skills even if the prompt-extension block's
  # own exit-code prose were deleted. This fragment appears ONLY in the block, so
  # the guard goes red iff the block's exit-code handling is actually removed.
  assert_eq "lpe-coverage: $SKILL_NAME/SKILL.md honors the helper exit code (prose)" "yes" \
    "$([ -f "$SKILL_FILE" ] && grep -qF 'a consumer extension exists but could not be loaded' "$SKILL_FILE" && echo yes || echo no)"  # raw-guard-ok: loop body — $SKILL_FILE is the per-skill loop target, not a static target-unique pin
done
# The two strict-JSON-stdout subagents carry an EXTRA caveat (absent from the other
# 14) that a consumer extension must not break their one-JSON-object contract. Pin
# it so a copy-paste of the generic block over them can't silently erase it.
for SUB in retrospective retrospective-audit; do
  assert_eq "lpe-coverage: $SUB keeps the strict-JSON-contract caveat" "yes" \
    "$(grep -qF 'must not break that contract' "$LIB/../skills/$SUB/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: loop body: SKILL target is the $SUB loop variable, not a static pin
done
# Guard against the loop becoming a vacuous no-op: if the skills/*/ glob ever
# matched nothing (a path typo, a restructure, a wrong CWD), the loop above would
# run zero assertions and the drift guard would silently pass. The guard's entire
# value is catching a future skill that ships without the step, so assert it
# actually enumerated the skills (>0; floor matches the current 16, kept as ≥1 so
# adding a skill never trips it).
assert_eq "lpe-coverage: enumeration is non-vacuous (skills/*/ glob matched)" "yes" \
  "$([ "$LPE_SKILL_COUNT" -ge 1 ] && echo yes || echo no)"

# ────────────────────────────────────────────────────────────────────────────
echo "init project-memory nudge: skills/init/SKILL.md carries the advisory CLAUDE.md step"
# ────────────────────────────────────────────────────────────────────────────
# Content / drift guard (issue #90). The deliverable is LLM-directing prose in a
# SKILL.md — there is no runtime code path to exercise — so the repo's established
# stand-in (mirroring the lpe-coverage and exit-code-contract grep guards above) is
# a content guard pinning the load-bearing instruction tokens. It goes red if the
# advisory step is dropped, reworded away, or loses one of its detected filenames /
# the @-import guidance / the never-write-never-block discipline. Each fragment
# below is BLOCK-UNIQUE to the new step (verified absent from the rest of the SKILL),
# so a match means the step itself is present, not some unrelated prose.
INIT_SKILL="$LIB/../skills/init/SKILL.md"
assert_eq "init-memory-nudge: advisory step heading present" "yes" \
  "$(grep -qF 'advisory project-memory check' "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'advisory project-memory check' appears twice in init SKILL
# Every detected agent-instruction filename (AC3) plus the CLAUDE.md target itself
# must be named, or the four-case behavior matrix can't be followed.
for FN in 'CLAUDE.md' '.github/copilot-instructions.md' 'AGENTS.md' 'GEMINI.md' '.cursorrules'; do
  assert_eq "init-memory-nudge: names detected file token ($FN)" "yes" \
    "$(grep -qF "$FN" "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: loop body: literal is the $FN loop variable, not a static pin
done
# AGENTS.md is matched across common spellings — case-insensitive (agents.md) plus
# the singular form (agent.md) — AC3. Pin BOTH the prose claim AND a behavioral token
# (the lowercase `agents.md` variant the step actually probes): the word alone could
# survive a regression that trims the variant list down to just `AGENTS.md`, so the
# lowercase form is what proves the spelling/case handling is really there.
assert_eq "init-memory-nudge: AGENTS.md detection is case-insensitive (prose)" "yes" \
  "$(grep -qiF 'case-insensitive' "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: case-insensitive (grep -qi); pin_count is case-sensitive -F
assert_eq "init-memory-nudge: case-insensitive AGENTS variant probed (agents.md)" "yes" \
  "$(grep -qF 'agents.md' "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'agents.md' appears 3x in init SKILL
# Retain the concrete @AGENTS.md import example.
assert_eq "init-memory-nudge: @-import example for AGENTS.md present" "yes" \
  "$(grep -qF '@AGENTS.md' "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: '@AGENTS.md' appears 3x in init SKILL
# AC2: the absent-everything case nudges toward the BUILT-IN /init.
assert_eq "init-memory-nudge: recommends the built-in /init" "yes" \
  "$(grep -qF 'built-in `/init`' "$INIT_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'built-in /init' appears 3x in init SKILL
# ────────────────────────────────────────────────────────────────────────────
echo "shipped agent_overrides: deduper pins Sonnet 5 w/ effort; no Haiku override carries effort"
# ────────────────────────────────────────────────────────────────────────────
# The shipped checklist-deduper override pins Claude Sonnet 5 (which DOES
# support `effort`) with effort "low" — a cost-saving step down from the API
# default of "high"; set it explicitly to avoid unexpected latency. A
# positive sentinel, not a bare has("effort"): a refactor that drops/renames the
# entry, swaps the model, or strips the effort each FAIL loudly rather than
# sailing through green. The entry must positively EXIST, be object-typed, pin
# claude-sonnet-5, AND carry an `effort` key — so a dropped/renamed entry
# ("missing-entry"), a model no longer Sonnet 5 ("not-sonnet"), or a removed
# effort ("no-effort") each FAIL loudly.
assert_eq "agent_overrides: shipped deduper override exists, pins Sonnet 5, and carries an effort key" \
  "ok" \
  "$(jq -r '
      (.prflow_review.agent_overrides["prflow:checklist-deduper"]) as $d
      | if ($d | type) != "object" then "missing-entry"
        elif (($d.model // "") != "sonnet") then "not-sonnet"
        elif ($d | has("effort") | not) then "no-effort"
        else "ok" end' "$TPL_DIR/config.example.json")"
# Claude Haiku rejects `effort` with HTTP 400 (supported only on Opus 4.5–4.8,
# Opus 5, Sonnet 4.6, and Sonnet 5). The shipped example no longer pins Haiku
# anywhere, but this guard
# keeps the invariant the scaffold-config.sh cleanup protects: should any shipped
# override ever pin a Haiku model, it must NOT also carry an `effort` key.
assert_eq "agent_overrides: no shipped Haiku-pinned override carries an effort key" \
  "ok" \
  "$(jq -r '
      [ (.prflow_review.agent_overrides // {}) | to_entries[]
        | select((.value | type) == "object")
        | select(((.value.model // "") | (. == "haiku" or startswith("claude-haiku-"))) and (.value | has("effort"))) ]
      | if length == 0 then "ok" else "haiku-with-effort" end' "$TPL_DIR/config.example.json")"

# ────────────────────────────────────────────────────────────────────────────
echo "config.example.json ⊇ config.schema.json (superset invariant)"
# ────────────────────────────────────────────────────────────────────────────
# config.example.json drives the scaffold/backfill (scaffold-config.sh copies it
# verbatim to a fresh config.json); config.schema.json drives editor validation.
# They are hand-maintained independently, so a key in one but not the other
# silently either won't backfill (a schema default with no example entry never
# reaches a scaffolded config) or is an undocumented/typo'd key the schema does
# not describe. These two assertions pin the relation in both directions:
#   1. every object key in the example is a property the schema defines (catches
#      typo'd / undocumented keys — the schema is additionalProperties:true, so
#      such a key would still *validate*, it would just go unnoticed).
#   2. every schema property carrying a `default` is present in the example (so a
#      backfilled config.json actually carries every defaulted key).
# Scope of the comparison (what is and isn't checked):
#   - Only OBJECT-key paths are compared. Keys nested inside example array
#     ELEMENTS are out of scope — the example has no array-of-object entries
#     (setup.install is a scalar array), and such keys would validate under
#     additionalProperties anyway; kpaths drops array-index paths accordingly.
#   - Optional schema properties with NO default (php_*, services,
#     watched_authors, node_working_directory, …) are intentionally omitted from
#     the example and so are NOT required by check 2.
#   - Defaults are collected from object properties only — dpaths does not
#     descend into array `items`: a default on an array element cannot be
#     satisfied by the (element-less) example, so check 2 would otherwise be
#     permanently unsatisfiable. spaths DOES descend into items so check 1's
#     allowed-key set stays complete (e.g. setup.services.[].image).
# A non-empty list on either side is the drift.
CFG_EXAMPLE="$TPL_DIR/config.example.json"
CFG_SCHEMA="$TPL_DIR/config.schema.json"
CFG_DRIFT="$(jq -n '
  # Property-name paths the schema DEFINES (descends into .properties + .items).
  def spaths:
    def recur($p):
      ( (.properties // {}) | to_entries[] | ($p+[.key]) as $q
        | ($q|join(".")), (.value|recur($q)) ),
      ( (.items // empty) | recur($p+["[]"]) );
    [ recur([]) ];
  # Schema OBJECT-property paths that declare a `default` (the backfillable
  # keys). Deliberately does NOT descend into array `items` — see the scope
  # note above for why an array-element default would make check 2 unsatisfiable.
  def dpaths:
    def recur($p):
      (.properties // {}) | to_entries[] | ($p+[.key]) as $q
      | (if (.value | (type=="object" and has("default"))) then ($q|join(".")) else empty end),
        (.value|recur($q));
    [ recur([]) ];
  # Object-key paths present in the example (array indices excluded).
  def kpaths:
    [ paths | select(all(.[]; type=="string")) | join(".") ];
  input as $ex | input as $sch
  | { example_not_in_schema:        (($ex|kpaths) - ($sch|spaths) | sort),
      schema_default_not_in_example: (($sch|dpaths) - ($ex|kpaths) | sort) }
' "$CFG_EXAMPLE" "$CFG_SCHEMA")"
assert_eq "config: every example key is defined in the schema" "[]" \
  "$(echo "$CFG_DRIFT" | jq -c '.example_not_in_schema')"
assert_eq "config: every schema default appears in the example" "[]" \
  "$(echo "$CFG_DRIFT" | jq -c '.schema_default_not_in_example')"

# ────────────────────────────────────────────────────────────────────────────
echo "detect-project-tools.sh"
# ────────────────────────────────────────────────────────────────────────────
# Language auto-detection: scans a throwaway repo for marker files and merges
# the matching presets (from the repo's real .prflow/tool-presets.json) into a
# .prflow/config.json. Run by scaffold-config.sh, so a regression here silently
# wires the wrong tools into the cloud reviewer.
DPT="$LIB/../scripts/detect-project-tools.sh"

# Helper: does an allowlist contain a tool pattern?
dpt_has() { jq -e --arg t "$2" "$1 | index(\$t) != null" "$3" >/dev/null 2>&1 && echo yes || echo no; }

# 1. Node + npm lockfile → tools land in ALL THREE paths; node_version filled;
#    `npm ci` chosen from package-lock.json; an existing custom entry is kept
#    at the front (ordered union, not alphabetical); install order preserved.
DT1="$(mktemp -d)"; mkdir -p "$DT1/.prflow"
printf '{"name":"x"}' > "$DT1/package.json"
printf '{}' > "$DT1/package-lock.json"
printf '{"prflow":{"allowed_tools":["Bash(make:*)"]},"setup":{"node_version":"","install":["python -m pip install pyyaml"]}}' > "$DT1/.prflow/config.json"
bash "$DPT" "$DT1" >/dev/null 2>&1
assert_eq "detect: npm tool in devflow path"   "yes" "$(dpt_has .prflow.allowed_tools           'Bash(npm:*)' "$DT1/.prflow/config.json")"
assert_eq "detect: npm tool in implement path" "yes" "$(dpt_has .prflow_implement.allowed_tools 'Bash(npm:*)' "$DT1/.prflow/config.json")"
assert_eq "detect: npm tool in runner path"    "yes" "$(dpt_has .prflow_runner.allowed_tools    'Bash(npm:*)' "$DT1/.prflow/config.json")"
assert_eq "detect: node_version filled from empty" "20" \
  "$(jq -r '.setup.node_version' "$DT1/.prflow/config.json")"
assert_eq "detect: npm ci chosen from package-lock.json" "yes" \
  "$(jq -e '.setup.install | index("npm ci") != null' "$DT1/.prflow/config.json" >/dev/null && echo yes || echo no)"
assert_eq "detect: existing custom tool preserved at front (ordered union)" "Bash(make:*)" \
  "$(jq -r '.prflow.allowed_tools[0]' "$DT1/.prflow/config.json")"
assert_eq "detect: pyyaml install line kept first (order preserved)" "python -m pip install pyyaml" \
  "$(jq -r '.setup.install[0]' "$DT1/.prflow/config.json")"
# Negative assertion: the rename must not leave a phantom `claude` object behind
# (a stale `.claude = (.claude // {})` jq initializer would silently inject one).
assert_eq "detect: no stray legacy 'claude' key written" "true" \
  "$(jq -e '.claude == null' "$DT1/.prflow/config.json" >/dev/null && echo true || echo false)"

# 2. Idempotent: a second run changes nothing.
DT1_HASH="$(jq -S . "$DT1/.prflow/config.json" | sha256sum)"
bash "$DPT" "$DT1" >/dev/null 2>&1
assert_eq "detect: idempotent re-run is a no-op" \
  "$DT1_HASH" "$(jq -S . "$DT1/.prflow/config.json" | sha256sum)"

# 3. A pinned node_version is NEVER overridden; no lockfile → `npm install`.
DT2="$(mktemp -d)"; mkdir -p "$DT2/.prflow"
printf '{"name":"y"}' > "$DT2/package.json"
printf '{"setup":{"node_version":"18","install":[]}}' > "$DT2/.prflow/config.json"
bash "$DPT" "$DT2" >/dev/null 2>&1
assert_eq "detect: pinned node_version not overridden" "18" \
  "$(jq -r '.setup.node_version' "$DT2/.prflow/config.json")"
assert_eq "detect: no lockfile → npm install" "yes" \
  "$(jq -e '.setup.install | index("npm install") != null' "$DT2/.prflow/config.json" >/dev/null && echo yes || echo no)"

# 4. False-positive guard: a marker ONLY inside node_modules must NOT match —
#    config stays exactly the empty object it started as.
DT3="$(mktemp -d)"; mkdir -p "$DT3/.prflow" "$DT3/node_modules/foo"
printf '{"x":1}' > "$DT3/node_modules/foo/package.json"
printf '{}' > "$DT3/.prflow/config.json"
bash "$DPT" "$DT3" >/dev/null 2>&1
assert_eq "detect: vendored node_modules marker does not trigger" "{}" \
  "$(jq -c . "$DT3/.prflow/config.json")"

# 5. Glob marker (*.csproj) matches dotnet.
DT4="$(mktemp -d)"; mkdir -p "$DT4/.prflow"
printf '<Project/>' > "$DT4/App.csproj"
printf '{}' > "$DT4/.prflow/config.json"
bash "$DPT" "$DT4" >/dev/null 2>&1
assert_eq "detect: *.csproj glob matches dotnet" "yes" \
  "$(dpt_has .prflow_runner.allowed_tools 'Bash(dotnet:*)' "$DT4/.prflow/config.json")"

# 6. PHP (composer.json) → php tools in all paths AND a composer install line.
DT5="$(mktemp -d)"; mkdir -p "$DT5/.prflow"
printf '{"require":{"php":">=8.2"}}' > "$DT5/composer.json"
printf '{}' > "$DT5/.prflow/config.json"
bash "$DPT" "$DT5" >/dev/null 2>&1
assert_eq "detect: composer tool in runner path" "yes" \
  "$(dpt_has .prflow_runner.allowed_tools 'Bash(composer:*)' "$DT5/.prflow/config.json")"
assert_eq "detect: composer install line added" "yes" \
  "$(jq -e '.setup.install | index("composer install --no-interaction --prefer-dist --no-progress") != null' "$DT5/.prflow/config.json" >/dev/null && echo yes || echo no)"

# 7. Subdirectory Node build (package.json + lockfile under jsx/) → detection
#    sets node_working_directory to the subdir AND scopes the install line into
#    it with a subshell `cd` (not a root-level npm ci that would no-op).
DT6="$(mktemp -d)"; mkdir -p "$DT6/.prflow" "$DT6/jsx"
printf '{"name":"bundle"}' > "$DT6/jsx/package.json"
printf '{}' > "$DT6/jsx/package-lock.json"
printf '{"setup":{"node_version":"","install":[]}}' > "$DT6/.prflow/config.json"
bash "$DPT" "$DT6" >/dev/null 2>&1
assert_eq "detect: subdir build sets node_working_directory" "jsx" \
  "$(jq -r '.setup.node_working_directory' "$DT6/.prflow/config.json")"
assert_eq "detect: subdir install line is subshell-scoped into the dir (quoted)" "yes" \
  "$(jq -e '.setup.install | index("(cd '\''jsx'\'' && npm ci)") != null' "$DT6/.prflow/config.json" >/dev/null && echo yes || echo no)"

# 8. Root Node build → node_working_directory is NEVER written (byte-identical
#    to the pre-feature behavior) and the install line stays a bare npm ci.
DT7="$(mktemp -d)"; mkdir -p "$DT7/.prflow"
printf '{"name":"rootapp"}' > "$DT7/package.json"
printf '{}' > "$DT7/package-lock.json"
printf '{"setup":{"node_version":"","install":[]}}' > "$DT7/.prflow/config.json"
bash "$DPT" "$DT7" >/dev/null 2>&1
assert_eq "detect: root build writes no node_working_directory key" "true" \
  "$(jq -e '.setup | has("node_working_directory") | not' "$DT7/.prflow/config.json" >/dev/null && echo true || echo false)"
assert_eq "detect: root build install line is bare npm ci (no cd)" "yes" \
  "$(jq -e '.setup.install | index("npm ci") != null' "$DT7/.prflow/config.json" >/dev/null && echo yes || echo no)"

# 9. Subdirectory npm-shrinkwrap.json (the 4th lockfile) → detected just like
#    package-lock.json, mapping to `npm ci`, so detection stays consistent with
#    resolve-node-cache.sh / action.yml (which both honor shrinkwrap).
DT8="$(mktemp -d)"; mkdir -p "$DT8/.prflow" "$DT8/jsx"
printf '{"name":"bundle"}' > "$DT8/jsx/package.json"
printf '{}' > "$DT8/jsx/npm-shrinkwrap.json"
printf '{"setup":{"node_version":"","install":[]}}' > "$DT8/.prflow/config.json"
bash "$DPT" "$DT8" >/dev/null 2>&1
assert_eq "detect: subdir npm-shrinkwrap.json sets node_working_directory" "jsx" \
  "$(jq -r '.setup.node_working_directory' "$DT8/.prflow/config.json")"
assert_eq "detect: subdir shrinkwrap install line is (cd 'jsx' && npm ci)" "yes" \
  "$(jq -e '.setup.install | index("(cd '\''jsx'\'' && npm ci)") != null' "$DT8/.prflow/config.json" >/dev/null && echo yes || echo no)"

# 10. A subdirectory name containing a space is single-quoted in the generated
#     install line, so it survives the `bash -c` exec in the action verbatim.
DT9="$(mktemp -d)"; mkdir -p "$DT9/.prflow" "$DT9/my app"
printf '{"name":"bundle"}' > "$DT9/my app/package.json"
printf '{}' > "$DT9/my app/package-lock.json"
printf '{"setup":{"node_version":"","install":[]}}' > "$DT9/.prflow/config.json"
bash "$DPT" "$DT9" >/dev/null 2>&1
assert_eq "detect: spaced subdir name is quoted in install line" "yes" \
  "$(jq -e '.setup.install | index("(cd '\''my app'\'' && npm ci)") != null' "$DT9/.prflow/config.json" >/dev/null && echo yes || echo no)"
assert_eq "detect: spaced subdir name written verbatim to node_working_directory" "my app" \
  "$(jq -r '.setup.node_working_directory' "$DT9/.prflow/config.json")"

# 11. Best-effort shape guard: a malformed pre-existing config (numeric
#     node_version, which the schema types as a string) is carried through the
#     merge into valid-but-wrong-shaped JSON. The guard must REFUSE to write it —
#     the user's config is left byte-identical — and the script must still exit 0
#     (best-effort, never blocks the surrounding scaffold).
DT10="$(mktemp -d)"; mkdir -p "$DT10/.prflow"
printf '{"name":"z"}' > "$DT10/package.json"
printf '{}' > "$DT10/package-lock.json"
printf '{"setup":{"node_version":20,"install":[]}}' > "$DT10/.prflow/config.json"
DT10_BEFORE="$(cat "$DT10/.prflow/config.json")"
bash "$DPT" "$DT10" >/dev/null 2>&1
assert_eq "detect: shape-drifted merge still exits 0 (best-effort)" "0" "$?"
assert_eq "detect: shape-drifted merge leaves config untouched" \
  "$DT10_BEFORE" "$(cat "$DT10/.prflow/config.json")"

# 12. The shape guard does NOT block a well-formed merge: a valid empty config
#     with a node marker is merged and written (npm tools land), confirming the
#     guard is a safety net, not a gate on the happy path.
DT11="$(mktemp -d)"; mkdir -p "$DT11/.prflow"
printf '{"name":"ok"}' > "$DT11/package.json"
printf '{}' > "$DT11/package-lock.json"
printf '{}' > "$DT11/.prflow/config.json"
bash "$DPT" "$DT11" >/dev/null 2>&1
assert_eq "detect: well-formed merge passes the guard and is written" "yes" \
  "$(dpt_has .prflow.allowed_tools 'Bash(npm:*)' "$DT11/.prflow/config.json")"

# 13. Windows regression: the native Windows jq build (winget jqlang.jq, run
#     under Git Bash) terminates every stdout line with CRLF. The marker/preset
#     read loops must strip the trailing CR — otherwise `read` captures keys like
#     $'node\r', the `.presets[$k]` lookup asks for a key that doesn't exist, and
#     a repo with valid markers is reported as "no known language markers". We
#     can't install a Windows jq in CI, so we shadow jq on PATH with a wrapper
#     that appends a CR to every output line (a faithful stand-in) and confirm a
#     plain Node repo is still detected end-to-end.
DT12="$(mktemp -d)"; mkdir -p "$DT12/.prflow" "$DT12/bin"
printf '{"name":"win"}' > "$DT12/package.json"
printf '{}' > "$DT12/package-lock.json"
printf '{}' > "$DT12/.prflow/config.json"
DT12_REAL_JQ="$(command -v jq)"
cat > "$DT12/bin/jq" <<EOF
#!/usr/bin/env bash
# Stand-in for the native Windows jq: delegate to real jq, then CRLF every line.
"$DT12_REAL_JQ" "\$@" | awk '{ printf "%s\r\n", \$0 }'
EOF
chmod +x "$DT12/bin/jq"
# Sanity guard: confirm the shim actually injects CRLF. Without this, a future
# break in the wrapper would turn the regression test below into a passing
# no-op (it would assert "yes" even with the fix removed). If this fails, the
# CRLF path is no longer being exercised — fix the shim, not the assertion.
assert_eq "detect(DT12 control): jq shim emits CRLF" "yes" \
  "$(PATH="$DT12/bin:$PATH" jq -n '1' | grep -q $'\r' && echo yes || echo no)"
PATH="$DT12/bin:$PATH" bash "$DPT" "$DT12" >/dev/null 2>&1
assert_eq "detect: CRLF jq stdout (Windows) exits 0" "0" "$?"
assert_eq "detect: CRLF jq stdout (Windows) still detects node markers" "yes" \
  "$(dpt_has .prflow.allowed_tools 'Bash(npm:*)' "$DT12/.prflow/config.json")"

rm -rf "$DT1" "$DT2" "$DT3" "$DT4" "$DT5" "$DT6" "$DT7" "$DT8" "$DT9" "$DT10" "$DT11" "$DT12"

# ────────────────────────────────────────────────────────────────────────────
echo "resolve-node-cache.sh (setup-project-env helper)"
# ────────────────────────────────────────────────────────────────────────────
# Resolves setup-node's `cache` / `cache-dependency-path` for a Node project
# that may live in a subdirectory. The script probes lockfiles relative to cwd,
# so each case runs it from a throwaway repo root. A regression here silently
# disables caching for subdir builds or — worse — regresses root-based ones.
RNC="$LIB/../.github/actions/setup-project-env/resolve-node-cache.sh"
rnc() { ( cd "$1" && bash "$RNC" "$2" "${3:-}" ); }

# Subdirectory lockfile + node_working_directory set → caching enabled, path
# qualified by the directory.
RNC_SUB="$(mktemp -d)"; mkdir -p "$RNC_SUB/jsx"; : > "$RNC_SUB/jsx/package-lock.json"
RNC_OUT="$(rnc "$RNC_SUB" 20 jsx)"
assert_eq "rnc: subdir lockfile → npm cache"        "node_cache=npm" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache=')"
assert_eq "rnc: subdir lockfile → qualified path"   "node_cache_path=jsx/package-lock.json" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache_path=')"
# Trailing slash on the directory is normalized (no doubled slash in the path).
RNC_OUT_TS="$(rnc "$RNC_SUB" 20 jsx/)"
assert_eq "rnc: trailing slash normalized"          "node_cache_path=jsx/package-lock.json" \
  "$(printf '%s\n' "$RNC_OUT_TS" | grep '^node_cache_path=')"

# Root lockfile, empty working directory → identical to the historical
# root-based outputs (no regression).
RNC_ROOT="$(mktemp -d)"; : > "$RNC_ROOT/yarn.lock"
RNC_OUT="$(rnc "$RNC_ROOT" 20 "")"
assert_eq "rnc: root yarn.lock → yarn cache"        "node_cache=yarn" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache=')"
assert_eq "rnc: root yarn.lock → bare path"         "node_cache_path=yarn.lock" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache_path=')"

# pnpm wins over a co-present npm lockfile (precedence preserved).
RNC_PREC="$(mktemp -d)"; : > "$RNC_PREC/pnpm-lock.yaml"; : > "$RNC_PREC/package-lock.json"
assert_eq "rnc: pnpm precedence over npm"           "node_cache=pnpm" \
  "$(rnc "$RNC_PREC" 20 "" | grep '^node_cache=')"

# npm-shrinkwrap.json (the 4th lockfile) → npm cache, qualified path.
RNC_SHR="$(mktemp -d)"; mkdir -p "$RNC_SHR/jsx"; : > "$RNC_SHR/jsx/npm-shrinkwrap.json"
RNC_OUT="$(rnc "$RNC_SHR" 20 jsx)"
assert_eq "rnc: subdir shrinkwrap → npm cache"      "node_cache=npm" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache=')"
assert_eq "rnc: subdir shrinkwrap → qualified path" "node_cache_path=jsx/npm-shrinkwrap.json" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache_path=')"

# Working directory set but no lockfile in it (config drift: dir named but
# lockfile not committed there) → caching off, so setup-node never errors.
RNC_WDNF="$(mktemp -d)"; mkdir -p "$RNC_WDNF/jsx"
assert_eq "rnc: working dir set but no lockfile → empty cache" "node_cache=" \
  "$(rnc "$RNC_WDNF" 20 jsx | grep '^node_cache=')"

# No lockfile → caching disabled (empty), so setup-node never errors.
RNC_NONE="$(mktemp -d)"
RNC_OUT="$(rnc "$RNC_NONE" 20 "")"
assert_eq "rnc: no lockfile → empty cache"          "node_cache=" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache=')"
assert_eq "rnc: no lockfile → empty path"           "node_cache_path=" \
  "$(printf '%s\n' "$RNC_OUT" | grep '^node_cache_path=')"

# Empty node_version → caching off even when a lockfile is present (the "Node
# not provisioned" case — setup-node won't run, so a cache key is meaningless).
assert_eq "rnc: empty node_version → no cache"      "node_cache=" \
  "$(rnc "$RNC_ROOT" "" "" | grep '^node_cache=')"

rm -rf "$RNC_SUB" "$RNC_ROOT" "$RNC_PREC" "$RNC_SHR" "$RNC_WDNF" "$RNC_NONE"

# ────────────────────────────────────────────────────────────────────────────
echo "config-source.sh"
# ────────────────────────────────────────────────────────────────────────────
( export DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json"
  . "$LIB/config-source.sh"
  assert_eq "watched authors from config" "claude,example-bot" "$(devflow_watched_authors)"
  assert_eq "min_occurrences from config" "2" "$(devflow_conf '.prflow_retrospective.min_occurrences' 99)"
  assert_eq "missing key → default" "fallback" "$(devflow_conf '.prflow_retrospective.nonexistent_key_xyz' fallback)"
)
# Resilience: config-source.sh runs under `set -e`; a missing or malformed config must
# return the default without aborting the sourcing chain.
( export DEVFLOW_CONFIG_FILE="/no/such/devflow/config.json"
  . "$LIB/config-source.sh"
  assert_eq "conf: missing file → default (no abort)" "dflt" "$(devflow_conf '.anything' dflt)"
)
( wp="$(mktemp)"; printf '{ not valid json' > "$wp"
  export DEVFLOW_CONFIG_FILE="$wp"
  . "$LIB/config-source.sh"
  assert_eq "conf: malformed JSON → default (warns, no abort)" "dflt" "$(devflow_conf '.anything' dflt 2>/dev/null)"
  rm -f "$wp"
)
# watched_authors falls back to prflow.allowed_bots when the override array is absent.
( wp="$(mktemp)"; printf '{"prflow":{"allowed_bots":"claude,fallback-bot"}}' > "$wp"
  export DEVFLOW_CONFIG_FILE="$wp"
  . "$LIB/config-source.sh"
  assert_eq "conf: watched_authors → allowed_bots fallback" "claude,fallback-bot" "$(devflow_watched_authors)"
  rm -f "$wp"
)

# ────────────────────────────────────────────────────────────────────────────
echo "scan.sh"
# ────────────────────────────────────────────────────────────────────────────
SCAN_TMP="$(mktemp -d)"
cat > "$SCAN_TMP/gh" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr list"*"author:claude"*)
    echo '[{"number":1,"headRefName":"claude/issue-1-a","author":{"login":"claude"},"mergedAt":"2026-05-01T00:00:00Z"},
           {"number":3,"headRefName":"claude/issue-3-c","author":{"login":"claude"},"mergedAt":"2026-05-03T00:00:00Z"},
           {"number":9,"headRefName":"devflow/learnings-2026-W18","author":{"login":"example-bot"},"mergedAt":"2026-05-02T00:00:00Z"}]' ;;
  *"pr list"*) echo '[]' ;;
  *"api"*"retrospectives.jsonl?ref=main"*)
    BODY="$(printf '{"pr":1}\n{"pr":2}\n' | base64 | tr -d "\n")"
    printf 'HTTP/2.0 200 OK\r\n\r\n{"content":"%s"}\n' "$BODY" ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh"
SCAN_OUT="$(DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh" bash "$LIB/scan.sh" 2>/dev/null)"
assert_eq "scan includes unprocessed PR 3"        "true"  "$(echo "$SCAN_OUT" | jq 'any(.[]; .number==3)')"
assert_eq "scan excludes already-recorded PR 1"   "false" "$(echo "$SCAN_OUT" | jq 'any(.[]; .number==1)')"
assert_eq "scan excludes devflow/learnings branch" "false" "$(echo "$SCAN_OUT" | jq 'any(.[]; .number==9)')"

# #7a: --prs ad-hoc mode — explicit numbers, no search, no processed-filter;
# still drops non-merged / non-retrospected branches.
cat > "$SCAN_TMP/gh2" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr view 1 --repo"*) echo '{"number":1,"headRefName":"claude/issue-1-a","mergedAt":"2026-05-01T00:00:00Z","state":"MERGED"}' ;;
  *"pr view 2 --repo"*) echo '{"number":2,"headRefName":"feature/hand-written","mergedAt":"2026-05-02T00:00:00Z","state":"MERGED"}' ;;
  *"pr view 3 --repo"*) echo '{"number":3,"headRefName":"claude/issue-3-c","mergedAt":"2026-05-03T00:00:00Z","state":"OPEN"}' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh2"
PRS_OUT="$(DEVFLOW_GH="$SCAN_TMP/gh2" bash "$LIB/scan.sh" --prs "1,2,3" 2>/dev/null)"
assert_eq "--prs includes explicit merged retrospected PR 1" "true"  "$(echo "$PRS_OUT" | jq 'any(.[]; .number==1)')"
assert_eq "--prs drops non-retrospected branch PR 2"        "false" "$(echo "$PRS_OUT" | jq 'any(.[]; .number==2)')"
assert_eq "--prs drops non-merged PR 3"                     "false" "$(echo "$PRS_OUT" | jq 'any(.[]; .number==3)')"
assert_eq "--prs ignores already-processed retrospectives.jsonl (PR 1 from gh stub matches an EXISTING pr in weekly mode but here is kept)" "1" "$(echo "$PRS_OUT" | jq 'length')"

# #103 I-2: in --prs mode, a jq PREDICATE EVALUATION failure must emit a distinct
# "predicate evaluation failed" breadcrumb, not be misreported as a clean "matches
# no retrospection path" exclusion (which asserts the PR was evaluated-and-excluded
# when the predicate may never have run). Force the jq error with a non-array
# `labels` shape: the predicate's `(.labels // [])` guard defaults only null/false,
# so `map(...)` over a string aborts the filter (exit non-zero).
cat > "$SCAN_TMP/gh3" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr view 5 --repo"*) echo '{"number":5,"headRefName":"claude/issue-5","mergedAt":"2026-05-01T00:00:00Z","state":"MERGED","labels":"not-an-array","closingIssuesReferences":[],"author":{"login":"x"}}' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh3"
PRS_ERR_OUT="$(DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh3" bash "$LIB/scan.sh" --prs "5" 2>&1 >/dev/null)"
assert_eq "#103 I-2: --prs jq predicate error emits 'predicate evaluation failed' breadcrumb" "true" \
  "$(echo "$PRS_ERR_OUT" | grep -q 'predicate evaluation failed' && echo true || echo false)"
assert_eq "#103 I-2: --prs jq predicate error is NOT misreported as 'matches no retrospection path'" "false" \
  "$(echo "$PRS_ERR_OUT" | grep -q 'matches no retrospection path' && echo true || echo false)"
# F1 (review): the breadcrumb names the actual jq cause (exit code + diagnostic),
# not just "failed" — `jq exit <n>:` is the format that carries the captured stderr.
assert_eq "#103 F1: --prs predicate-error breadcrumb names the jq exit code + diagnostic" "true" \
  "$(echo "$PRS_ERR_OUT" | grep -Eq 'jq exit [0-9]+:' && echo true || echo false)"

# #103 I-2 (negative): a genuine non-match still emits the "matches no retrospection
# path" breadcrumb (and NOT the predicate-failure one) — the split must not collapse
# the two cases in the other direction.
cat > "$SCAN_TMP/gh3b" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr view 6 --repo"*) echo '{"number":6,"headRefName":"feature/plain","mergedAt":"2026-05-01T00:00:00Z","state":"MERGED","labels":[],"closingIssuesReferences":[],"author":{"login":"x"}}' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh3b"
PRS_NM="$(DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh3b" bash "$LIB/scan.sh" --prs "6" 2>&1 >/dev/null)"
assert_eq "#103 I-2: genuine non-match still says 'matches no retrospection path'" "true" \
  "$(echo "$PRS_NM" | grep -q 'matches no retrospection path' && echo true || echo false)"
assert_eq "#103 I-2: genuine non-match does NOT say 'predicate evaluation failed'" "false" \
  "$(echo "$PRS_NM" | grep -q 'predicate evaluation failed' && echo true || echo false)"

# #103 I-3: in weekly mode, a candidate-source fetch hard-failure (here the
# DevFlow-label `gh pr list`) must force a NON-ZERO exit, so a partial GitHub
# outage cannot masquerade as "0 new PRs" and let a cron see success.
cat > "$SCAN_TMP/gh4" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr list"*"label:PRFlow,DevFlow"*) echo "boom: gh outage" >&2; exit 1 ;;
  *"pr list"*) echo '[]' ;;
  *"api"*"retrospectives.jsonl?ref=main"*) printf 'HTTP/2.0 404 Not Found\r\n\r\n' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh4"
SCAN_DEG="$(DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh4" bash "$LIB/scan.sh" 2>&1 >/dev/null)"; SCAN_DEG_RC=$?
assert_eq "#103 I-3: weekly label-fetch hard failure exits non-zero (no silent under-count)" "1" "$SCAN_DEG_RC"
assert_eq "#103 I-3: weekly degraded run emits an ::error:: breadcrumb" "true" \
  "$(echo "$SCAN_DEG" | grep -q '::error::scan:' && echo true || echo false)"
# F2 (review): the per-source ::warning:: names the actual gh cause, not just "failed".
assert_eq "#103 F2: weekly degraded breadcrumb names the underlying gh cause" "true" \
  "$(echo "$SCAN_DEG" | grep -q 'boom: gh outage' && echo true || echo false)"

# #103 I-3 / T1 (review): the watched-author path also degrades. Only the
# label-fetch path was exercised above; here a watched-author `pr list` returns a
# non-array, so the author-side jq RESHAPE aborts (`.labels` on a string), which
# must set DEGRADED and exit non-zero exactly like the label path.
cat > "$SCAN_TMP/gh6" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr list"*"label:PRFlow,DevFlow"*) echo '[]' ;;
  *"pr list"*"author:"*) echo '{"not":"an-array"}' ;;
  *"pr list"*) echo '[]' ;;
  *"api"*"retrospectives.jsonl?ref=main"*) printf 'HTTP/2.0 404 Not Found\r\n\r\n' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh6"
DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh6" bash "$LIB/scan.sh" >/dev/null 2>&1; SCAN_AUTHOR_DEG_RC=$?
assert_eq "#103 I-3/T1: weekly watched-author reshape failure exits non-zero too" "1" "$SCAN_AUTHOR_DEG_RC"

# #103 I-3/T1 (shadow): complete the 2x2 degraded matrix (label|author x fetch|reshape).
# gh4=label-fetch, gh6=author-reshape above; here gh7=label-RESHAPE (a non-array label
# batch aborts the reshape jq) and gh8=author-FETCH (author `pr list` exits non-zero).
cat > "$SCAN_TMP/gh7" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr list"*"label:PRFlow,DevFlow"*) echo '{"not":"an-array"}' ;;
  *"pr list"*) echo '[]' ;;
  *"api"*"retrospectives.jsonl?ref=main"*) printf 'HTTP/2.0 404 Not Found\r\n\r\n' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh7"
DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh7" bash "$LIB/scan.sh" >/dev/null 2>&1; SCAN_LBL_RESHAPE_RC=$?
assert_eq "#103 I-3/T1: weekly label-reshape failure exits non-zero" "1" "$SCAN_LBL_RESHAPE_RC"
cat > "$SCAN_TMP/gh8" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr list"*"label:PRFlow,DevFlow"*) echo '[]' ;;
  *"pr list"*"author:"*) echo "author fetch outage" >&2; exit 1 ;;
  *"pr list"*) echo '[]' ;;
  *"api"*"retrospectives.jsonl?ref=main"*) printf 'HTTP/2.0 404 Not Found\r\n\r\n' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh8"
DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh8" bash "$LIB/scan.sh" >/dev/null 2>&1; SCAN_AUTHOR_FETCH_RC=$?
assert_eq "#103 I-3/T1: weekly watched-author fetch failure exits non-zero" "1" "$SCAN_AUTHOR_FETCH_RC"

# #103 I-3 (regression): a fully-healthy weekly run still exits 0.
DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" DEVFLOW_GH="$SCAN_TMP/gh" bash "$LIB/scan.sh" >/dev/null 2>&1; SCAN_OK_RC=$?
assert_eq "#103 I-3: healthy weekly run still exits 0" "0" "$SCAN_OK_RC"

# #100: retrospectives.jsonl HTTP-200 decode is loud on a decode/parse MISS, not
# silently collapsed to [] (which would re-queue the whole backlog and create
# duplicate retrospectives). Adversarial input-shape matrix over the 200 branch:
#   content {valid-jsonl-no-pr, base64-of-non-json, invalid-base64, ""+download_url, ""+none}.
# One stub serves all shapes; the per-shape response is injected via $SCAN_RESP
# (read at runtime, so embedded quotes never traverse the stub's bash quoting).
cat > "$SCAN_TMP/gh-100" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"api"*"retrospectives.jsonl?ref=main"*) printf '%b' "$SCAN_RESP" ;;
  *"api"*"raw/retro.jsonl"*) printf '{"pr":1}\n{"pr":2}\n' ;;   # download_url: real records
  *"api"*"raw/nopr.jsonl"*) printf '{"notpr":1}\n' ;;           # download_url: parseable, zero pr records
  *"api"*"raw/fail.jsonl"*) exit 1 ;;                           # download_url: fetch failure
  *"pr list"*) echo '[]' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$SCAN_TMP/gh-100"

# Driver (house style: cf. rnc/ex/di): run scan.sh against the gh-100 stub with
# the given 200-response injected as $SCAN_RESP. Captures scan's stderr into the
# global $SCAN_ERR (stdout discarded); the call's own $? carries scan's exit, so
# a caller does `scan100 '...'; RC=$?` then asserts on $RC and $SCAN_ERR.
scan100() {  # $1 = $SCAN_RESP value (printf %b-interpreted by the stub)
  SCAN_ERR="$(SCAN_RESP="$1" DEVFLOW_CONFIG_FILE="$LIB/test/fixtures/config.json" \
    DEVFLOW_GH="$SCAN_TMP/gh-100" bash "$LIB/scan.sh" 2>&1 >/dev/null)"
}
# Substring membership → "yes"/"no" (assert_eq is the only assertion helper), so
# each loud-failure case can assert the SPECIFIC breadcrumb, not just exit 1 —
# CLAUDE.md: a generic/misdirected breadcrumb is itself the bug for this code.
have() {  # $1 = needle, $2 = haystack
  case "$2" in *"$1"*) echo yes ;; *) echo no ;; esac
}

# Build the base64 payloads with the local base64 so the test is host-portable.
B64_NOPR="$(printf '{"notpr":1}\n{"other":2}\n' | base64 | tr -d '\n')"
B64_NONJSON="$(printf 'this is not json\nat all\n' | base64 | tr -d '\n')"
B64_PR="$(printf '{"pr":1}\n{"pr":2}\n' | base64 | tr -d '\n')"

scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"'"$B64_NOPR"'"}\n'; RC=$?
assert_eq "scan #100: inline content with zero pr records exits loud" "1" "$RC"
assert_eq "scan #100: zero-record breadcrumb names the collapse" "yes" "$(have 'zero pr records' "$SCAN_ERR")"
assert_eq "scan #100: zero-record breadcrumb names the inline source" "yes" "$(have '(inline content)' "$SCAN_ERR")"

scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"'"$B64_NONJSON"'"}\n'; RC=$?
assert_eq "scan #100: base64-of-non-json content (jq parse miss) exits loud" "1" "$RC"
assert_eq "scan #100: parse-miss breadcrumb names parsing failure" "yes" "$(have 'parsing retrospectives.jsonl (inline content) failed' "$SCAN_ERR")"

scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"@@not-valid-base64@@"}\n'; RC=$?
assert_eq "scan #100: invalid base64 content (decode miss) exits loud" "1" "$RC"
assert_eq "scan #100: decode-miss breadcrumb names base64" "yes" "$(have 'base64 decode' "$SCAN_ERR")"

scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"","foo":1}\n'; RC=$?
assert_eq "scan #100: HTTP 200 with neither content nor download_url exits loud" "1" "$RC"
assert_eq "scan #100: no-fallback breadcrumb names the missing surfaces" "yes" "$(have 'neither inline content nor a download_url' "$SCAN_ERR")"

# An unparseable 200 envelope (non-JSON body) fails with its OWN accurate
# breadcrumb, not the misleading "neither content nor download_url" one.
scan100 'HTTP/2.0 200 OK\r\n\r\nthis is not a json envelope\n'; RC=$?
assert_eq "scan #100: unparseable HTTP-200 envelope exits loud" "1" "$RC"
assert_eq "scan #100: unparseable-envelope breadcrumb is specific" "yes" "$(have 'envelope was not parseable JSON' "$SCAN_ERR")"

# download_url (>1 MB) branch now shares the zero-record collapse guard: a
# parseable body carrying zero pr records must fail loud, not silently re-queue.
scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"","download_url":"https://example.test/raw/nopr.jsonl"}\n'; RC=$?
assert_eq "scan #100: download_url body with zero pr records exits loud" "1" "$RC"
assert_eq "scan #100: download_url zero-record breadcrumb names the source" "yes" "$(have '(download_url)' "$SCAN_ERR")"

# download_url branch: a failed fetch of the large file exits loud with a specific cause.
scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"","download_url":"https://example.test/raw/fail.jsonl"}\n'; RC=$?
assert_eq "scan #100: download_url fetch failure exits loud" "1" "$RC"
assert_eq "scan #100: download_url fetch-failure breadcrumb is specific" "yes" "$(have 'via download_url failed' "$SCAN_ERR")"

# Non-200/404 HTTP status is fatal — never proceed on an empty processed-set.
scan100 'HTTP/2.0 500 Internal Server Error\r\n\r\n{}\n'; RC=$?
assert_eq "scan #100: HTTP 500 exits loud" "1" "$RC"
assert_eq "scan #100: HTTP-500 breadcrumb names the status" "yes" "$(have 'HTTP 500' "$SCAN_ERR")"

# Regression: the >1 MB download_url fallback path still parses cleanly (exit 0)
# when the fetched body carries real pr records.
scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"","download_url":"https://example.test/raw/retro.jsonl"}\n'; RC=$?
assert_eq "scan #100: download_url fallback with real records succeeds (exit 0)" "0" "$RC"

# Regression: the original happy path (valid jsonl with pr records) still exits 0.
scan100 'HTTP/2.0 200 OK\r\n\r\n{"content":"'"$B64_PR"'"}\n'; RC=$?
assert_eq "scan #100: valid jsonl with pr records still succeeds (exit 0)" "0" "$RC"

rm -rf "$SCAN_TMP"

# ────────────────────────────────────────────────────────────────────────────
echo "fetch-pr-context.sh"
# ────────────────────────────────────────────────────────────────────────────
GH_STUB="$LIB/test/fixtures/gh-stub.sh"
OUT="$(DEVFLOW_GH="$GH_STUB" DEVFLOW_FIXTURE_PR=793 bash "$LIB/fetch-pr-context.sh" 793)"
CTX="$(cat "$OUT")"
assert_eq "kind=implementation"            "implementation" "$(jq -r .kind            <<<"$CTX")"
assert_eq "issue_number parsed"            "790"            "$(jq -r '.issue_number'   <<<"$CTX")"
assert_eq "review_comments_count=0"        "0"              "$(jq -r '.signals.review_comments_count' <<<"$CTX")"
assert_eq "post_bot_commits=4"             "4"              "$(jq -r '.signals.post_bot_commits'      <<<"$CTX")"
assert_eq "ci_failures=1"                  "1"              "$(jq -r '.signals.ci_failures_during_pr' <<<"$CTX")"
assert_eq "workpad_final_status=Complete"  "Complete"       "$(jq -r '.signals.workpad_final_status'  <<<"$CTX")"
# #1050: the checkpoint-4 evidence record is a machine-consumed downstream field, not prose.
# The 793 fixture workpad carries the hidden `<!-- prflow:checkpoint base-update-checkpoint-4 -->`
# marker, so the derived field is true; the CLEAN fixture (no workpad marker) is false.
assert_eq "#1050: base_update_checkpoint4_present=true when the marker is in the workpad" "true" \
  "$(jq -r '.base_update_checkpoint4_present' <<<"$CTX")"
assert_eq "review_reject_outstanding=true" "true"           "$(jq -r '.signals.review_reject_outstanding' <<<"$CTX")"
OUTC="$(DEVFLOW_GH="$GH_STUB" DEVFLOW_FIXTURE_PR=CLEAN bash "$LIB/fetch-pr-context.sh" 4242)"
CTXC="$(cat "$OUTC")"
assert_eq "clean: reject_outstanding=false" "false" "$(jq -r '.signals.review_reject_outstanding' <<<"$CTXC")"
assert_eq "clean: post_bot_commits=0"       "0"     "$(jq -r '.signals.post_bot_commits'      <<<"$CTXC")"
assert_eq "clean: ci_failures=0"            "0"     "$(jq -r '.signals.ci_failures_during_pr' <<<"$CTXC")"
assert_eq "#1050: base_update_checkpoint4_present=false when the workpad carries no marker" "false" \
  "$(jq -r '.base_update_checkpoint4_present' <<<"$CTXC")"
# ── #1347: the NEAR-MISS the two fixture cases above cannot reach. The tier-refused key
# `base-update-checkpoint-4-tier-refused` is a PREFIX EXTENSION of the clean-token key, so the
# only thing keeping "the tier refused the check" from reading downstream as "the base was
# reconciled" is the closing ` -->` in the shipped globs. That is precisely the conflation the
# two keys exist to prevent, and a later glob relaxed to `*base-update-checkpoint-4*` would
# collapse them with a green suite. Drive the SHIPPED case program itself (extracted from
# lib/fetch-pr-context.sh, never a transcribed copy — a transcribed glob would keep passing
# after the shipped one drifted) over the three bodies that discriminate it.
CP4_CASE_LINE=$(grep -n "BASE_UPDATE_CHECKPOINT4_PRESENT=false" "$LIB/fetch-pr-context.sh" | head -1 | cut -d: -f1)
CP4_CASE_PROG=$(sed -n "${CP4_CASE_LINE},$((CP4_CASE_LINE + 4))p" "$LIB/fetch-pr-context.sh")
# Name a failed extraction directly. Every drift shape already fails the rows below RED (two of
# them expect `true`, which an empty or truncated program cannot produce), so this adds no
# coverage — it turns five confusing "expected true, got ''" mismatches into one diagnostic
# naming the cause, for the day the shipped block grows past the five-line window.
assert_eq "#1347: the shipped checkpoint-4 case program extracted cleanly (whole case…esac)" "yes" \
  "$(case "$CP4_CASE_PROG" in *esac*) echo yes ;; *) echo no ;; esac)"
for _row in \
  "clean-prflow|<!-- prflow:checkpoint base-update-checkpoint-4 -->|true" \
  "clean-devflow|<!-- devflow:checkpoint base-update-checkpoint-4 -->|true" \
  "tier-refused-only|<!-- prflow:checkpoint base-update-checkpoint-4-tier-refused -->|false" \
  "tier-refused-devflow-only|<!-- devflow:checkpoint base-update-checkpoint-4-tier-refused -->|false" \
  "gha-only|<!-- prflow:checkpoint gha:1:1:phase1-entered -->|false"
do
  _name=${_row%%|*}; _rest=${_row#*|}; _body=${_rest%|*}; _want=${_rest##*|}
  assert_eq "#1347: the shipped checkpoint-4 case reads a '$_name' workpad as $_want" \
    "$_want" \
    "$(WORKPAD_BODY="- a row $_body" bash -c "$CP4_CASE_PROG"'; printf %s "$BASE_UPDATE_CHECKPOINT4_PRESENT"')"
done
unset CP4_CASE_LINE CP4_CASE_PROG _row _name _rest _body _want
assert_eq "ci_status_unknown=false (793 fixture)"   "false" "$(jq -r '.signals.ci_status_unknown' <<<"$CTX")"
assert_eq "ci_status_unknown=false (CLEAN fixture)"  "false" "$(jq -r '.signals.ci_status_unknown' <<<"$CTXC")"
# Fix 2: diff field must be a non-null string when the fixture has content
assert_eq "diff is a non-empty string" "string" "$(jq -r '.diff | type' <<<"$CTX")"
assert_eq "diff not null"              "false"  "$(jq -r '.diff == null' <<<"$CTX")"

# ────────────────────────────────────────────────────────────────────────────
echo "fetch-pr-context.sh: ci_failures_during_pr semantics (issue #1441)"
# ────────────────────────────────────────────────────────────────────────────
# Never transcribe the shipped jq filter here: a copy keeps passing after the
# shipped one drifts. Never re-route through gh-stub.sh either — its $SET
# prefixes every endpoint, so each payload shape costs a whole fixture set.
F1441="$(mktemp -d)"
cat > "$F1441/prview.json" <<'PV1441'
{"number":1441,"headRefName":"claude/issue-1441-x","baseRefName":"main","headRefOid":"sha1441beef","mergeCommit":{"oid":"merge1441"},"mergedAt":"2026-05-08T16:31:00Z","createdAt":"2026-05-08T07:00:00Z","author":{"login":"example-bot"},"title":"t","body":"Closes #1441","additions":1,"deletions":0,"files":[{"path":"x.txt"}],"labels":[]}
PV1441
cat > "$F1441/gh" <<'STUB1441'
#!/usr/bin/env bash
FX="${DEVFLOW_FX}"
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr view"*) cat "$FX/prview.json" ;;
  *"pr diff"*) echo 'diff --git a/x.txt b/x.txt' ;;
  *"pulls/"*"/comments"*) echo '[]' ;;
  *"pulls/"*"/reviews"*) echo '[]' ;;
  *"pulls/"*"/commits"*) echo '[]' ;;
  *"check-runs"*)
    printf '%s\n' "$*" >> "$FX/argv.log"
    # Emitted before the case, not as a `;;&` fallthrough arm: `;;&` is bash 4+
    # and this repo must parse under the bash 3.2 macOS ships.
    [ "${DEVFLOW_CR_MODE:-payload}" = notice ] && echo "gh: rate limit remaining 12" >&2
    [ "${DEVFLOW_CR_MODE:-payload}" = notice-multiline ] && printf 'gh: notice one\ngh: notice two\n' >&2
    case "${DEVFLOW_CR_MODE:-payload}" in
      exit-nonzero) echo "gh: HTTP 503 Service Unavailable" >&2; exit 1 ;;
      *)
        # Serve page 1 alone unless the caller really paginated, so deleting
        # --paginate from the shipped command turns the AC5 row RED instead of
        # leaving it green on a stub that ignores flags.
        case "$*" in
          *--paginate*) cat "$FX/checkruns.json" ;;
          *)            head -1 "$FX/checkruns.json" ;;
        esac
        ;;
    esac
    ;;
  *"issues/"*"/comments"*) echo '[]' ;;
  *"issues/"*) echo '{"number":1441,"title":"i","body":"b","labels":[],"comments":[]}' ;;
  *"commits/"*) echo '{"files":[]}' ;;
  *) echo '[]' ;;
esac
STUB1441
chmod +x "$F1441/gh"

# $1 label, $2 expected ci_failures_during_pr, $3 expected ci_status_unknown,
# $4 optional DEVFLOW_CR_MODE. The payload is whatever the caller last wrote to
# $F1441/checkruns.json.
cr1441() {
  local _out _ctx
  _out="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" DEVFLOW_CR_MODE="${4:-payload}" \
          bash "$LIB/fetch-pr-context.sh" 1441 2>/dev/null)"
  _ctx="$(cat "$_out" 2>/dev/null)"
  assert_eq "#1441: $1 → ci_failures_during_pr=$2" "$2" \
    "$(jq -r '.signals.ci_failures_during_pr' <<<"$_ctx")"
  assert_eq "#1441: $1 → ci_status_unknown=$3" "$3" \
    "$(jq -r '.signals.ci_status_unknown' <<<"$_ctx")"
}

# AC1 — superseded conclusions never count.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":"cancelled"},{"conclusion":"stale"},{"conclusion":"success"},{"conclusion":"neutral"},{"conclusion":"skipped"}]}
CR
cr1441 "cancelled+stale beside success/neutral/skipped" "0" "false"

# AC2 — the three real red signals each increment, asserted one conclusion at a
# time so a filter that recognises only `failure` cannot pass on a mixed payload.
for _concl in failure timed_out action_required; do
  printf '{"check_runs":[{"conclusion":"%s"}]}\n' "$_concl" > "$F1441/checkruns.json"
  cr1441 "a lone $_concl run" "1" "false"
done
unset _concl

# AC3 — never flip the filter to a failure allowlist: an unknown future
# conclusion would then read as success and the signal would fail OPEN.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":"conclusion_github_has_not_invented_yet"}]}
CR
cr1441 "an unrecognised conclusion (denylist fails closed)" "1" "false"

# Never let a superseded conclusion suppress a real red sharing its page: a
# filter that rejected the whole payload on seeing `cancelled` would leave AC1
# and AC2 both green, since neither mixes the two on one page.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":"failure"},{"conclusion":"cancelled"}]}
CR
cr1441 "a real red beside a superseded conclusion on one page" "1" "false"

# AC4 — a still-running check has conclusion null and is not a failure.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":null},{"conclusion":null}]}
CR
cr1441 "every run still in flight (conclusion null)" "0" "false"

# AC5 — a multi-page head. Keep both qualifying runs on page 2 and none on page
# 1, or the row stops discriminating a merged count from a page-1-only one.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":"success"},{"conclusion":"cancelled"}]}
{"check_runs":[{"conclusion":"failure"},{"conclusion":"timed_out"}]}
CR
cr1441 "two concatenated pages, both qualifying runs on page 2" "2" "false"
# Keep these argv pins beside the behavioral row: they name the cause when it
# fails, which a count mismatch alone does not.
assert_eq "#1441: the shipped call passes --paginate" "yes" \
  "$(grep -q -- '--paginate' "$F1441/argv.log" && echo yes || echo no)"
assert_eq "#1441: the shipped call requests the larger page size" "yes" \
  "$(grep -q 'per_page=100' "$F1441/argv.log" && echo yes || echo no)"
# Pin the commit selector too: the stub ignores the path, so swapping HEAD_SHA
# for a merge or base SHA would describe another commit's CI and stay green.
assert_eq "#1441: the shipped call addresses the PR head SHA" "yes" \
  "$(grep -q 'commits/sha1441beef/check-runs' "$F1441/argv.log" && echo yes || echo no)"

# AC6 fail-safe arm 1, both ORed conditions. A PR whose CI could not be read
# must never read as clean, so each sets unknown=true AND failures=1.
cat > "$F1441/checkruns.json" <<'CR'
{"check_runs":[{"conclusion":"success"}]}
CR
cr1441 "gh exits non-zero" "1" "true" exit-nonzero
: > "$F1441/checkruns.json"
cr1441 "gh returns an empty body" "1" "true"

# Never re-add `2>&1` to the shipped capture: a non-fatal gh notice on a
# SUCCESSFUL request would then contaminate the body and report a healthy head
# as unreadable — the exact false signal this change exists to remove.

# Two failures, not one: the fail-safe arm also yields 1, so a single-failure
# payload leaves the count row green when that regression lands.
printf '{"check_runs":[{"conclusion":"failure"},{"conclusion":"timed_out"}]}\n' > "$F1441/checkruns.json"
cr1441 "a non-fatal gh notice on stderr, request otherwise clean" "2" "false" notice

# Never delete a fail-safe breadcrumb: cr1441 discards stderr, so without the
# rows below the suite stays green while the arms become indistinguishable.
printf '{"check_runs":[{"conclusion":"success"}]}\n' > "$F1441/checkruns.json"
_CR_ERR1="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" DEVFLOW_CR_MODE=exit-nonzero bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
# Pin the exit-status VALUE, not just the label: matching `rc=` alone stays green
# when the argument is dropped, which is the regression this row names.
assert_eq "#1441: the read-failure arm reports the failing exit status" "yes" \
  "$(case "$_CR_ERR1" in *"check-runs read failed (rc=1)"*) echo yes ;; *) echo no ;; esac)"
printf 'this is not json at all\n' > "$F1441/checkruns.json"
_CR_ERR2="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
# Pin the QUOTED BODY, not the arm's label: the label predates the body clause,
# so matching it stays green when the clause this row names is deleted.
assert_eq "#1441: the unusable-body arm quotes the body it could not parse" "yes" \
  "$(case "$_CR_ERR2" in *"body began: this is not json at all"*) echo yes ;; *) echo no ;; esac)"
# Check both directions below: a one-sided check stays green once the fail-safe
# arms drift onto shared wording, which is what makes them indistinguishable.
assert_eq "#1441: the read-failure arm carries no unusable-body wording" "no" \
  "$(case "$_CR_ERR1" in *"yielded no usable count"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1441: the unusable-body arm carries no read-failure wording" "no" \
  "$(case "$_CR_ERR2" in *"check-runs read failed"*) echo yes ;; *) echo no ;; esac)"
# A breadcrumb must stay one line: a caller splits our stderr into records.
printf 'not json line one\nnot json line two\n' > "$F1441/checkruns.json"
_CR_ERR3="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
# Assert the JOINED tail, not the marker's occurrence count: the marker appears
# once whether or not the newline strip this row names is present.
assert_eq "#1441: the quoted body is newline-stripped onto one line" "yes" \
  "$(case "$_CR_ERR3" in *"body began: not json line one not json line two"*) echo yes ;; *) echo no ;; esac)"
# Pin an arm-specific jq diagnostic, or the whole re-run is freely deletable.
printf '{"check_runs":{"a":{"conclusion":"success"}}}\n' > "$F1441/checkruns.json"
_CR_ERR4="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: the breadcrumb carries jq's own wrong-type diagnostic" "yes" \
  "$(case "$_CR_ERR4" in *"jq: "*"check_runs not an array"*) echo yes ;; *) echo no ;; esac)"
printf '   \n  \n' > "$F1441/checkruns.json"
_CR_ERR5="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: the breadcrumb carries jq's own zero-page diagnostic" "yes" \
  "$(case "$_CR_ERR5" in *"jq: "*"no check-run pages"*) echo yes ;; *) echo no ;; esac)"
# This error arm needs its own pin: the behavioral rows expect 1/true, which its
# sibling arms also produce, so it would otherwise be deletable while green.
printf '{"check_runs":[7]}\n' > "$F1441/checkruns.json"
_CR_ERR6="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: the breadcrumb carries jq's own non-object diagnostic" "yes" \
  "$(case "$_CR_ERR6" in *"non-object check-run"*) echo yes ;; *) echo no ;; esac)"
# Never drop the counting run's 2>/dev/null: raw jq output would then land as its
# own line and fragment the caller's one-record-per-line contract. Match at line
# start — the breadcrumb carries jq's message mid-line, so only raw output counts.
assert_eq "#1441: no raw jq output escapes alongside the breadcrumb" "0" \
  "$(printf '%s\n' "$_CR_ERR6" | grep -c '^jq:')"
# An rc-0 empty body is not a failed call; it must say so in its own words.
: > "$F1441/checkruns.json"
_CR_ERR7="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: an rc-0 empty body is not reported as a failed read" "yes" \
  "$(case "$_CR_ERR7" in *"returned an empty body (rc=0)"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1441: the empty-body arm carries no read-failure wording" "no" \
  "$(case "$_CR_ERR7" in *"check-runs read failed"*) echo yes ;; *) echo no ;; esac)"

# gh's OWN stderr is re-emitted collapsed, not passed through raw: the caller
# folds our whole stderr into one record and then splits it on newlines, so an
# unstripped multi-line gh notice fragments into phantom rows.
printf '{"check_runs":[{"conclusion":"success"}]}\n' > "$F1441/checkruns.json"
_CR_ERR8="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" DEVFLOW_CR_MODE=notice-multiline \
            bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: gh's multi-line stderr is re-emitted joined onto one line" "yes" \
  "$(case "$_CR_ERR8" in *"gh: notice one gh: notice two"*) echo yes ;; *) echo no ;; esac)"
# Positive control on the same fixture: the request itself succeeded, so this
# row cannot be green because some earlier arm rejected the payload.
cr1441 "a multi-line gh notice, request otherwise clean" "0" "false" notice-multiline

# The jq-error operand of the breadcrumb's collapse needs its own driver: real
# jq emits single-line diagnostics, so only a stub jq exercises that strip.
cat > "$F1441/jq" <<'JQSTUB1441'
#!/usr/bin/env bash
case "$*" in
  *"no check-run pages"*)
    printf 'jq: stub error line one\njq: stub error line two\n' >&2
    exit 5 ;;
esac
exec "${DEVFLOW_REAL_JQ}" "$@"
JQSTUB1441
chmod +x "$F1441/jq"
printf '{"check_runs":[{"conclusion":"success"}]}\n' > "$F1441/checkruns.json"
_CR_ERR9="$(DEVFLOW_FX="$F1441" DEVFLOW_GH="$F1441/gh" \
            DEVFLOW_REAL_JQ="$(command -v jq)" DEVFLOW_JQ="$F1441/jq" \
            bash "$LIB/fetch-pr-context.sh" 1441 2>&1 >/dev/null || true)"
assert_eq "#1441: the jq-error operand is collapsed onto one line" "yes" \
  "$(case "$_CR_ERR9" in *"jq: stub error line one jq: stub error line two"*) echo yes ;; *) echo no ;; esac)"
# Attribute the rejection: without this the row stays green if the stub tripped
# some other arm rather than the unusable-count arm whose strip it names.
assert_eq "#1441: the jq-error row lands on the unusable-count arm" "yes" \
  "$(case "$_CR_ERR9" in *"yielded no usable count"*) echo yes ;; *) echo no ;; esac)"

unset _CR_ERR1 _CR_ERR2 _CR_ERR3 _CR_ERR4 _CR_ERR5 _CR_ERR6 _CR_ERR7 _CR_ERR8 _CR_ERR9

# Adversarial input shapes: never give `.check_runs` a `// []` default — these
# must error into the fail-safe guard, not be laundered into a clean 0.
while IFS='|' read -r _label _payload; do
  [ -n "$_label" ] || continue
  printf '%s\n' "$_payload" > "$F1441/checkruns.json"
  cr1441 "$_label" "1" "true"
done <<'CR'
a body that is not JSON|this is not json at all
valid JSON with no check_runs key|{"total_count":0}
check_runs is a scalar, not an array|{"check_runs":7}
a check_runs element that is not an object|{"check_runs":[7]}
a check_runs element that is null|{"check_runs":[null]}
check_runs is an object, not an array|{"check_runs":{"a":{"conclusion":"success"}}}
CR
unset _label _payload

# Never drop the zero-page error arm: `inputs` yields nothing for a body that
# parses to zero JSON documents, so the filter would return a clean 0 that
# passes the numeric guard and reports the head as having no CI failures.
printf '   \n  \n' > "$F1441/checkruns.json"
cr1441 "a whitespace-only body (zero JSON documents)" "1" "true"

# AC6 fail-safe arm 2. Never transcribe the guard and never extract it with a
# fixed line window: a copy drifts, and a fixed offset silently truncates the
# moment the block grows, dropping its else-arm.
CI_GUARD_PROG=$(awk 'f{print; if ($0 ~ /^[[:space:]]*fi[[:space:]]*$/) exit; next} /if \[ -z "\$_CI_COUNT" \]/{print; f=1}' "$LIB/fetch-pr-context.sh")
# Never weaken this to a substring test: if the closing `fi` drifts off its own
# line the awk over-runs to the next bare `fi`, and a presence test reports a
# clean extraction over a different, unbalanced program.
assert_eq "#1441: the extracted guard parses as balanced shell" "0" \
  "$(printf '%s\n' "$CI_GUARD_PROG" | bash -n /dev/stdin 2>/dev/null; echo $?)"
assert_eq "#1441: the extracted guard carries its else-arm" "1" \
  "$(printf '%s\n' "$CI_GUARD_PROG" | grep -c 'CI_FAILURES="\$_CI_COUNT"')"
# DEVFLOW_JQ=true keeps the guard's diagnostic re-run silent here: the extracted
# block calls jq, and an unset binary would spray command-not-found across the rows.
ci_guard1441() {  # $1 label, $2 _CI_COUNT value, $3 expected unknown, $4 expected failures
  assert_eq "#1441: the shipped guard reads a $1 _CI_COUNT as unknown=$3" "$3" \
    "$(_CI_COUNT="$2" CI_STATUS_UNKNOWN=false CI_FAILURES=x DEVFLOW_JQ=true bash -c "$CI_GUARD_PROG"'; printf %s "$CI_STATUS_UNKNOWN"' 2>/dev/null)"
  assert_eq "#1441: the shipped guard reads a $1 _CI_COUNT as failures=$4" "$4" \
    "$(_CI_COUNT="$2" CI_STATUS_UNKNOWN=false CI_FAILURES=x DEVFLOW_JQ=true bash -c "$CI_GUARD_PROG"'; printf %s "$CI_FAILURES"' 2>/dev/null)"
}
ci_guard1441 "multi-line"  "$(printf '0\n1')" true  1
ci_guard1441 "alphabetic"  "not-a-number"     true  1
ci_guard1441 "empty"       ""                 true  1
ci_guard1441 "numeric"     "3"                false 3
unset -f ci_guard1441
unset CI_GUARD_PROG
unset -f cr1441
rm -rf "$F1441"

# #356: a workpad whose Status is `💥 Failed` yields the bare word `Failed`
# (fetch-pr-context strips 💥 like the other glyphs), and cheap-gate gates it
# non-clean with reason "workpad status not Complete".
OUTF="$(DEVFLOW_GH="$GH_STUB" DEVFLOW_FIXTURE_PR=FAILED bash "$LIB/fetch-pr-context.sh" 4343)"
CTXF="$(cat "$OUTF")"
assert_eq "#356: workpad_final_status=Failed (💥 stripped)" "Failed" "$(jq -r '.signals.workpad_final_status' <<<"$CTXF")"
# Feed cheap-gate.jq the WHOLE bundle, exactly as the real consumer does
# (`run-jq.sh -f cheap-gate.jq < "$CTX"`, see skills/retrospective-weekly/SKILL.md).
# Re-wrapping as `{signals: .signals}` would drop the bundle's TOP-LEVEL `reflections`
# field — a sibling of `.signals`, not a member of it — leaving cheap-gate's reflection
# check inert against a shape the producer never emits.
assert_eq "#356: a 💥 Failed workpad gates non-clean via cheap-gate" "false" \
  "$(jq -c -f "$LIB/cheap-gate.jq" <<<"$CTXF" | jq -r .clean)"
# Assert the REASON, not just clean=false. This fixture's workpad also carries a
# `## Devflow Reflection` bullet, which is independently a non-clean signal — so
# `clean=false` alone stays GREEN even if the workpad-status check were deleted or
# reordered below the reflections check, and this block would pass for the wrong reason.
# Pinning the reason is what proves the 💥 Failed status is what gated the run.
assert_eq "#356: a 💥 Failed workpad gates non-clean for the workpad-status reason" "workpad status not Complete" \
  "$(jq -c -f "$LIB/cheap-gate.jq" <<<"$CTXF" | jq -r .reason)"

# #1: post_bot_commits / human_postbot SHA list count only *substantive* (non-merge)
# commits after the bot's last commit. A `git merge main` by a human (parents>1)
# is branch hygiene, not a fixup, and must not be counted.
_postbot_count() {  # stdin: COMMITS-shaped array; arg1: PR-author login
  jq --arg author "$1" '
    to_entries
    | [.[] | select(
        (.value.author_login | endswith("[bot]"))
        or (.value.committer_login | endswith("[bot]"))
        or (.value.author_login == $author)
        or (.value.committer_login == $author)
      ) | .key
    ] as $bot
    | if ($bot | length) == 0 then 0
      else ([.[($bot | last) + 1:][] | select((.value.parents_count // 1) <= 1)] | length)
      end'
}
assert_eq "post_bot: merge commit excluded, real fixup counted" "1" \
  "$(echo '[{"author_login":"claude[bot]","committer_login":"web-flow","parents_count":1},{"author_login":"alice","committer_login":"alice","parents_count":2},{"author_login":"alice","committer_login":"alice","parents_count":1}]' | _postbot_count someoneelse)"
assert_eq "post_bot: only a human merge after the bot → 0" "0" \
  "$(echo '[{"author_login":"claude[bot]","committer_login":"web-flow","parents_count":1},{"author_login":"alice","committer_login":"alice","parents_count":2}]' | _postbot_count someoneelse)"
assert_eq "post_bot: missing parents_count treated as non-merge (counted)" "1" \
  "$(echo '[{"author_login":"claude[bot]","committer_login":"web-flow"},{"author_login":"alice","committer_login":"alice"}]' | _postbot_count someoneelse)"

# #4 / issue #895: the /review verdict parser is now exercised by EXECUTING the
# producer (lib/fetch-pr-context.sh) through a gh stub — never by re-declaring its
# jq filter inline — so a change to the producer's filter turns these RED. See the
# "fetch-pr-context.sh: review_verdicts union" block below, which drives the
# CI-wrapper form, the standalone form, the APPROVE-WITH-CAVEAT collapse, and the
# prose-mention-ignored case through the real producer.

# #5: fetch-pr-context elides generated/vendored file bodies from the embedded
# diff but keeps every path in changed_files.
_DIFF_SAMPLE='diff --git a/src/Foo.php b/src/Foo.php
@@ -1 +1 @@
-x
+y
diff --git a/package-lock.json b/package-lock.json
@@ -1,9 +1,9 @@
- noise
+ noise
diff --git a/jsx/dist/app.min.js b/jsx/dist/app.min.js
@@ -1 +1 @@
-a
+b'
_DIFF_TRIMMED="$(printf '%s' "$_DIFF_SAMPLE" | python3 -c '
import sys, re
diff = sys.stdin.read()
noise = re.compile(r"(^|/)(package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml|composer\.lock|Gemfile\.lock|poetry\.lock|Cargo\.lock|go\.sum)$|\.min\.(js|css|mjs)$|\.map$|(^|/)(node_modules|vendor|dist|build)/")
out, elide = [], False
for line in diff.split("\n"):
    if line.startswith("diff --git "):
        parts = line.split(" ", 3)
        path = parts[2][2:] if len(parts) > 2 and parts[2].startswith("a/") else ""
        elide = bool(path and noise.search(path))
        if elide:
            out.append(line); out.append("[elided: %s]" % path); continue
    if not elide: out.append(line)
sys.stdout.write("\n".join(out))
')"
assert_eq "diff trim: real source kept"       "true"  "$(printf '%s' "$_DIFF_TRIMMED" | grep -qx -- '+y' && echo true || echo false)"
assert_eq "diff trim: lockfile body elided"   "true"  "$(printf '%s' "$_DIFF_TRIMMED" | grep -q '\[elided: package-lock.json\]' && echo true || echo false)"
assert_eq "diff trim: lockfile noise removed"  "false" "$(printf '%s' "$_DIFF_TRIMMED" | grep -q -- '- noise' && echo true || echo false)"
assert_eq "diff trim: minified bundle elided"  "true"  "$(printf '%s' "$_DIFF_TRIMMED" | grep -q '\[elided: jsx/dist/app.min.js\]' && echo true || echo false)"

# ────────────────────────────────────────────────────────────────────────────
echo "fetch-pr-context.sh: review_verdicts union (issue #895)"
# ────────────────────────────────────────────────────────────────────────────
# The verdict signal is now the UNION of the PR conversation comments and the
# durable bot PR reviews. Every assertion below EXECUTES the real producer through
# a gh stub (AC21) — the filter is never re-declared inline — so a change to the
# producer's union filter turns these RED.

# The static UNION fixture set (lib/test/fixtures/UNION-*) is the mixed-leg content
# assertion (AC22): a comment-derived APPROVE, a review-derived APPROVE, a review-
# derived DISMISSED REJECT (CI-wrapper heading form), plus a PENDING review and a
# no-heading CHANGES_REQUESTED review that both contribute nothing.
UOUT="$(DEVFLOW_GH="$GH_STUB" DEVFLOW_FIXTURE_PR=UNION bash "$LIB/fetch-pr-context.sh" 895)"
UCTX="$(cat "$UOUT")"
# Fails first against today's comment-only code, which reads only the APPROVE
# comment and reports review_reject_outstanding=false.
assert_eq "union: review-derived REJECT sets review_reject_outstanding=true" "true" \
  "$(jq -r '.signals.review_reject_outstanding' <<<"$UCTX")"
assert_eq "union: review_verdicts length = 3 (PENDING + no-heading excluded)" "3" \
  "$(jq -r '.review_verdicts | length' <<<"$UCTX")"
assert_eq "union: review_verdicts verdict sequence" "APPROVE APPROVE REJECT" \
  "$(jq -r '[.review_verdicts[].verdict] | join(" ")' <<<"$UCTX")"
assert_eq "union: review_verdicts source sequence" "pr_review pr_comment pr_review" \
  "$(jq -r '[.review_verdicts[].source] | join(" ")' <<<"$UCTX")"
assert_eq "union: review_verdicts createdAt sequence" "2026-05-08T09:00:00Z 2026-05-08T10:00:00Z 2026-05-08T11:00:00Z" \
  "$(jq -r '[.review_verdicts[].createdAt] | join(" ")' <<<"$UCTX")"
assert_eq "union: each entry carries EXACTLY verdict/createdAt/source (no index leak)" "true" \
  "$(jq -r 'all(.review_verdicts[]; (keys | sort) == ["createdAt","source","verdict"])' <<<"$UCTX")"
# End-to-end: the review-derived REJECT gates the bundle non-clean with the
# existing reason literal.
assert_eq "union: cheap-gate reason on a review-only REJECT" "outstanding /review REJECT" \
  "$(jq -c -f "$LIB/cheap-gate.jq" <<<"$UCTX" | jq -r .reason)"

# Parametric scenarios via an inline gh stub that serves swappable comments/reviews
# (the F97 pattern). Branch claude/issue-895-uv → issue 895; PR & issue thread are
# both issues/895/comments (the gh-stub.sh limitation), which is immaterial here —
# these assertions read .review_verdicts and .signals.review_reject_outstanding only.
F895="$(mktemp -d)"
cat > "$F895/prview.json" <<'PV'
{"number":895,"headRefName":"claude/issue-895-uv","baseRefName":"main","headRefOid":"sha895","mergeCommit":{"oid":"m895"},"mergedAt":"2026-05-08T16:31:00Z","createdAt":"2026-05-08T07:00:00Z","author":{"login":"example-bot"},"title":"t","body":"Closes #895","additions":1,"deletions":0,"files":[{"path":"x.txt"}],"labels":[]}
PV
cat > "$F895/gh" <<'STUB'
#!/usr/bin/env bash
FX="${DEVFLOW_FX}"
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"pr view"*) cat "$FX/prview.json" ;;
  *"pr diff"*) echo 'diff --git a/x.txt b/x.txt' ;;
  *"pulls/"*"/comments"*) echo '[]' ;;
  *"pulls/"*"/reviews"*) cat "$FX/reviews.json" ;;
  *"pulls/"*"/commits"*) echo '[]' ;;
  *"check-runs"*) echo '{"check_runs":[]}' ;;
  *"issues/895/comments"*) cat "$FX/comments.json" ;;
  *"issues/"*"/comments"*) echo '[]' ;;
  *"issues/895"*) echo '{"number":895,"title":"t","body":"b","labels":[],"comments":[]}' ;;
  *"commits/"*) echo '{"files":[]}' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$F895/gh"
# $1 = comments JSON, $2 = reviews JSON → prints the emitted bundle to stdout.
_uv() {
  printf '%s' "$1" > "$F895/comments.json"
  printf '%s' "$2" > "$F895/reviews.json"
  local _o; _o="$(DEVFLOW_FX="$F895" DEVFLOW_GH="$F895/gh" bash "$LIB/fetch-pr-context.sh" 895 2>/dev/null)"
  cat "$_o"
}
_uv_verds() { jq -r '[.review_verdicts[].verdict] | join(" ")'; }
_uv_srcs()  { jq -r '[.review_verdicts[].source]  | join(" ")'; }
_uv_rro()   { jq -r '.signals.review_reject_outstanding'; }

# Verdict-parser format coverage, now producer-driven (replaces the old inline
# _vparse): CI-wrapper form, standalone form, APPROVE-WITH-CAVEAT collapse (AC11),
# and prose-mention-ignored — exercised through BOTH legs (AC7 grammar parity).
assert_eq "union parser: CI-wrapper form in a REVIEW body → REJECT" "REJECT" \
  "$(_uv '[]' '[{"state":"COMMENTED","body":"**bot** ——\n\n---\n### /review — Verdict: **REJECT**\n\nblah","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_verds)"
assert_eq "union parser: standalone form in a COMMENT → APPROVE" "APPROVE" \
  "$(_uv '[{"body":"# Review Report\n\n## Verdict: APPROVE (looks good)\n","created_at":"2026-01-02T00:00:00Z"}]' '[]' | _uv_verds)"
assert_eq "union parser: APPROVE WITH CAVEAT collapses to APPROVE" "APPROVE" \
  "$(_uv '[{"body":"## Verdict: APPROVE WITH CAVEAT — checklist not generated\n","created_at":"2026-01-03T00:00:00Z"}]' '[]' | _uv_verds)"
assert_eq "union parser: prose mention of 'verdict: REJECT' ignored" "" \
  "$(_uv '[{"body":"I think the verdict: REJECT was harsh.","created_at":"2026-01-04T00:00:00Z"}]' '[]' | _uv_verds)"

# AC5: a review body with NO verdict heading contributes nothing whatever its state.
assert_eq "union: CHANGES_REQUESTED review with no heading → rro stays false" "false" \
  "$(_uv '[]' '[{"state":"CHANGES_REQUESTED","body":"please fix the tests","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_rro)"
# AC10: a PENDING review with a verdict heading contributes nothing.
assert_eq "union: PENDING review with a REJECT heading → rro false" "false" \
  "$(_uv '[]' '[{"state":"PENDING","body":"## Verdict: REJECT","submitted_at":null}]' | _uv_rro)"
# AC10: an absent/null/non-string state does NOT exclude the review.
assert_eq "union: absent state + heading → contributes (rro true)" "true" \
  "$(_uv '[]' '[{"body":"## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_rro)"
# AC6: a DISMISSED REJECT with no later APPROVE stays outstanding.
assert_eq "union: DISMISSED REJECT, no later APPROVE → rro true" "true" \
  "$(_uv '[]' '[{"state":"DISMISSED","body":"## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_rro)"
# AC6: cleared by a later APPROVE ordering after it.
assert_eq "union: DISMISSED REJECT cleared by later APPROVE → rro false" "false" \
  "$(_uv '[]' '[{"state":"DISMISSED","body":"## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"},{"state":"COMMENTED","body":"## Verdict: APPROVE","submitted_at":"2026-01-02T00:00:00Z"}]' | _uv_rro)"
# AC8/AC9: a non-string body skips that entry without aborting; other entries survive.
assert_eq "union: non-string body skipped, sibling survives (no abort)" "REJECT" \
  "$(_uv '[]' '[{"state":"COMMENTED","body":5,"submitted_at":"2026-01-01T00:00:00Z"},{"state":"COMMENTED","body":"## Verdict: REJECT","submitted_at":"2026-01-02T00:00:00Z"}]' | _uv_verds)"
# AC16: a timestamp-less REJECT forces rro true regardless of timestamped entries.
assert_eq "union: timestamp-less REJECT forces rro true" "true" \
  "$(_uv '[]' '[{"state":"COMMENTED","body":"## Verdict: APPROVE","submitted_at":"2026-01-01T00:00:00Z"},{"state":"COMMENTED","body":"## Verdict: REJECT","submitted_at":null}]' | _uv_rro)"
# AC17: a timestamp-less APPROVE never clears a timestamped REJECT.
assert_eq "union: timestamp-less APPROVE never clears a timestamped REJECT" "true" \
  "$(_uv '[]' '[{"state":"COMMENTED","body":"## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"},{"state":"COMMENTED","body":"## Verdict: APPROVE","submitted_at":""}]' | _uv_rro)"
# AC13: identical timestamps order the review last (comment then review).
assert_eq "union: identical timestamp → review orders last" "pr_comment pr_review" \
  "$(_uv '[{"body":"## Verdict: APPROVE","created_at":"2026-01-01T00:00:00Z"}]' '[{"state":"COMMENTED","body":"## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_srcs)"
# AC13 consequence on review_reject_outstanding: because the review orders LAST on an
# identical timestamp, a same-timestamp APPROVE *review* clears a REJECT *comment* — the
# decided tie-break direction (a same-second cross-source tie is inherently ambiguous at
# GitHub's 1s granularity; the issue's Potential Gotchas accept this ordering skew rather
# than correcting it). Pin the signal consequence, not just the sequence.
assert_eq "union: identical timestamp, APPROVE review after REJECT comment → rro false (AC13 tie-break)" "false" \
  "$(_uv '[{"body":"## Verdict: REJECT","created_at":"2026-01-01T00:00:00Z"}]' '[{"state":"COMMENTED","body":"## Verdict: APPROVE","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_rro)"
# AC4: multiple verdict headings in one body → one entry per heading.
assert_eq "union: two headings in one review body → 2 entries" "APPROVE REJECT" \
  "$(_uv '[]' '[{"state":"COMMENTED","body":"## Verdict: APPROVE\nmid\n## Verdict: REJECT","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_verds)"
# AC14: a round producing a stub review AND its progress comment → two entries, no dedup.
assert_eq "union: stub review + progress comment (same verdict) → 2 entries" "2" \
  "$(_uv '[{"body":"## Verdict: APPROVE — full report","created_at":"2026-01-01T00:00:05Z"}]' '[{"state":"COMMENTED","body":"## Verdict: APPROVE — full report in PR comment","submitted_at":"2026-01-01T00:00:00Z"}]' | jq -r '.review_verdicts | length')"
# Regression: empty comments + empty reviews → [] and false.
assert_eq "union: empty comments + empty reviews → [] and rro false" "0 false" \
  "$(_uv '[]' '[]' | jq -r '"\(.review_verdicts | length) \(.signals.review_reject_outstanding)"')"

# ── #1030: the producer marker, over the REAL census bodies ───────────────────
# The measured defect this closes: six of the nine bot CHANGES_REQUESTED bodies in
# lib/test/fixtures/review-verdict-census.json match NO heading shape, so the
# "merged over an un-cleared REJECT" detector was blind to every one of them. Each
# assertion below feeds a body built from a recorded census first line through the
# REAL producer; the unmarked control beside it is what proves the marker moved it.
UVM_HEAD="4444444444444444444444444444444444444444"
UVM_REJECT="<!-- prflow:review-verdict head=$UVM_HEAD verdict=REJECT -->"
UVM_APPROVE="<!-- prflow:review-verdict head=$UVM_HEAD verdict=APPROVE -->"
# Every non-conforming census REJECT body, marker-stamped, is recognised — and the
# same bodies unmarked are recognised by NOTHING, which is the pre-#1030 blindness.
UVM_MARKED_HITS=0
UVM_UNMARKED_HITS=0
while IFS= read -r UVM_LINE; do
  UVM_MARKED="$(_uv '[]' "$(jq -nc --arg b "$UVM_REJECT"$'\n'"$UVM_LINE" '[{state:"CHANGES_REQUESTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_verds)"
  [ "$UVM_MARKED" = "REJECT" ] && UVM_MARKED_HITS=$((UVM_MARKED_HITS + 1))
  UVM_PLAIN="$(_uv '[]' "$(jq -nc --arg b "$UVM_LINE" '[{state:"CHANGES_REQUESTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_verds)"
  [ -z "$UVM_PLAIN" ] && UVM_UNMARKED_HITS=$((UVM_UNMARKED_HITS + 1))
done < <(jq -r '.rejects[] | select(.dismisser_prose_match | not) | .first_line' "$LIB/test/fixtures/review-verdict-census.json")
assert_eq "#1030 union: every marker-stamped non-conforming census REJECT is recognised" \
  "6-6" "$UVM_MARKED_HITS-$UVM_UNMARKED_HITS"
# The consequence the retrospective loop reads: a pull request merged over a
# marker-carrying un-cleared REJECT whose body matches no heading shape.
assert_eq "#1030 union: a marker-carrying REJECT matching no heading shape sets rro true" "true" \
  "$(_uv '[]' "$(jq -nc --arg b "$UVM_REJECT"$'\n''## 🔴 Devflow Review — REJECT' '[{state:"CHANGES_REQUESTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_rro)"
# ...and a later marker-carrying APPROVE ordering after it clears the signal.
assert_eq "#1030 union: a later marker-carrying APPROVE clears the marker REJECT" "false" \
  "$(_uv '[]' "$(jq -nc --arg r "$UVM_REJECT"$'\n''## 🔴 REJECT' --arg a "$UVM_APPROVE"$'\n''## ✅ APPROVE' '[{state:"CHANGES_REQUESTED",body:$r,submitted_at:"2026-01-01T00:00:00Z"},{state:"COMMENTED",body:$a,submitted_at:"2026-01-02T00:00:00Z"}]')" | _uv_rro)"
# The marker is recognised on the COMMENT leg too, on the line after the run key.
assert_eq "#1030 union: a marker on line 2 of a progress comment is recognised" "REJECT" \
  "$(_uv "$(jq -nc --arg b '<!-- prflow:review-progress run=7-1 -->'$'\n'"$UVM_REJECT"$'\n''## 🔴 Devflow Review — REJECT' '[{body:$b,created_at:"2026-01-01T00:00:00Z"}]')" '[]' | _uv_verds)"
# ONE entry per marker-carrying artifact: a body carrying BOTH the marker and a
# heading contributes the marker's verdict once, not two entries.
assert_eq "#1030 union: a marked body contributes exactly one entry, not one per heading" "1-APPROVE" \
  "$(_uv '[]' "$(jq -nc --arg b "$UVM_APPROVE"$'\n''## Verdict: APPROVE'$'\n''## Verdict: REJECT' '[{state:"COMMENTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | jq -r '"\(.review_verdicts | length)-\(.review_verdicts[0].verdict)"')"
# A marker QUOTED below the scanned window is prose: the heading grammar decides.
assert_eq "#1030 union: a marker quoted below line 2 is not read; the heading decides" "APPROVE" \
  "$(_uv '[]' "$(jq -nc --arg b '## Verdict: APPROVE'$'\n''a finding quotes:'$'\n'"$UVM_REJECT" '[{state:"COMMENTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_verds)"
# Only the prflow: spelling is a marker — the devflow: spelling falls through.
assert_eq "#1030 union: a devflow:review-verdict spelling is not a marker" "" \
  "$(_uv '[]' "$(jq -nc --arg b "<!-- devflow:review-verdict head=$UVM_HEAD verdict=REJECT -->" '[{state:"COMMENTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_verds)"
# A non-string body still skips the entry rather than aborting the marker filter.
assert_eq "#1030 union: a non-string body skips without aborting the marker scan" "REJECT" \
  "$(_uv '[]' "$(jq -nc --arg b "$UVM_REJECT" '[{state:"COMMENTED",body:5,submitted_at:"2026-01-01T00:00:00Z"},{state:"COMMENTED",body:$b,submitted_at:"2026-01-02T00:00:00Z"}]')" | _uv_verds)"
# ── #1443: the bot-only third rung + the unparsed-artifact count ─────────────
# Four verdict shapes measured in this repository's own merged pull requests that
# rungs 1 and 2 both miss, plus the count that names what still gets missed. Every
# assertion runs the REAL producer through the stub.
_uv_unparsed() { jq -r '.review_verdict_unparsed_count'; }
_uv_shape()    { jq -r '"\(.review_verdicts | length) \(.review_verdict_unparsed_count)"'; }
# $1 = body → a one-artifact comments / reviews payload authored by a [bot] login.
_uv_botc() { jq -nc --arg b "$1" '[{user:{login:"github-actions[bot]"},body:$b,created_at:"2026-01-01T00:00:00Z"}]'; }
_uv_botr() { jq -nc --arg b "$1" '[{user:{login:"github-actions[bot]"},state:"COMMENTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]'; }
UV3_S1='## ✅ Devflow Review — APPROVE'
UV3_S2='**Devflow Review: APPROVE** ✅'
UV3_S3='## Verdict'$'\n\n''**APPROVE** ✅'
UV3_S4='**Verdict: ✅ REJECT**'
# The closed four-shape set, through the comment leg and the review leg alike.
assert_eq "#1443 rung3: heading with no Verdict: literal (comment leg)" "APPROVE" \
  "$(_uv "$(_uv_botc "$UV3_S1")" '[]' | _uv_verds)"
assert_eq "#1443 rung3: heading with no Verdict: literal (review leg)" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "$UV3_S1")" | _uv_verds)"
assert_eq "#1443 rung3: bold non-heading verdict line (comment leg)" "APPROVE" \
  "$(_uv "$(_uv_botc "$UV3_S2")" '[]' | _uv_verds)"
assert_eq "#1443 rung3: bold non-heading verdict line (review leg)" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "$UV3_S2")" | _uv_verds)"
assert_eq "#1443 rung3: Verdict heading, token on a later line (comment leg)" "APPROVE" \
  "$(_uv "$(_uv_botc "$UV3_S3")" '[]' | _uv_verds)"
assert_eq "#1443 rung3: Verdict heading, token on a later line (review leg)" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "$UV3_S3")" | _uv_verds)"
assert_eq "#1443 rung3: emoji between Verdict: and the token (comment leg)" "REJECT" \
  "$(_uv "$(_uv_botc "$UV3_S4")" '[]' | _uv_verds)"
assert_eq "#1443 rung3: emoji between Verdict: and the token (review leg)" "REJECT" \
  "$(_uv '[]' "$(_uv_botr "$UV3_S4")" | _uv_verds)"
# The login gate: a non-[bot] author never reaches the new rung, whatever the shape.
assert_eq "#1443 rung3: a non-bot login contributes nothing through the new rung" "0 1" \
  "$(_uv "$(jq -nc --arg b "$UV3_S1" '[{user:{login:"octocat"},body:$b,created_at:"2026-01-01T00:00:00Z"}]')" '[]' | _uv_shape)"
# Rung 1 wins outright: a marked body carrying an opposite-verdict shape below it
# contributes the MARKER's verdict once, and the new rung is not consulted.
assert_eq "#1443 rung3: a valid marker pre-empts the new rung (opposite shape below)" "1-APPROVE" \
  "$(_uv '[]' "$(_uv_botr "$UVM_APPROVE"$'\n'"$UV3_S4")" | jq -r '"\(.review_verdicts | length)-\(.review_verdicts[0].verdict)"')"
# The count: 0 with nothing to scan, 0 when everything parsed, 1 for one miss.
assert_eq "#1443 count: no comments and no reviews → 0" "0" \
  "$(_uv '[]' '[]' | _uv_unparsed)"
assert_eq "#1443 count: every verdict-bearing artifact parsed → 0" "0" \
  "$(_uv "$(_uv_botc "$UV3_S1")" '[]' | _uv_unparsed)"
assert_eq "#1443 count: exactly one unparsed verdict-bearing artifact → 1" "0 1" \
  "$(_uv "$(_uv_botc "APPROVE"$'\n'"REJECT"$'\n'"third")" '[]' | _uv_shape)"
# The tally aggregates across both legs, so a single-artifact case cannot exercise it.
assert_eq "#1443 count: two unparsed artifacts, one per leg → 2" "0 2" \
  "$(_uv "$(_uv_botc "APPROVE"$'\n'"REJECT"$'\n'"third")" "$(_uv_botr "APPROVE"$'\n'"REJECT"$'\n'"third")" | _uv_shape)"
# The closed malformed-payload set: the filter keeps running and the bundle is emitted.
assert_eq "#1443 malformed: comments payload is a JSON object" "0 0" \
  "$(_uv '{"a":1}' '[]' | _uv_shape)"
assert_eq "#1443 malformed: comments payload is a JSON string" "0 0" \
  "$(_uv '"hello"' '[]' | _uv_shape)"
assert_eq "#1443 malformed: body is null" "0 0" \
  "$(_uv '[{"user":{"login":"x[bot]"},"body":null,"created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: body is a number" "0 0" \
  "$(_uv '[{"user":{"login":"x[bot]"},"body":5,"created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: no body key" "0 0" \
  "$(_uv '[{"user":{"login":"x[bot]"},"created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: no user key" "0 0" \
  "$(_uv '[{"body":"nothing to read here","created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: user is null" "0 0" \
  "$(_uv '[{"user":null,"body":"nothing to read here","created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: user.login is an empty string" "0 0" \
  "$(_uv '[{"user":{"login":""},"body":"nothing to read here","created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
# A non-object `user` is the shape that indexes as a string: every reader of .user.login
# must survive it, or one malformed artifact aborts the whole bundle under set -e.
assert_eq "#1443 malformed: user is a string (comment leg)" "0 0" \
  "$(_uv '[{"user":"octocat","body":"nothing to read here","created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: user is a string (review leg)" "0 0" \
  "$(_uv '[]' '[{"user":"octocat","state":"COMMENTED","body":"nothing to read here","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_shape)"
# `// ""` replaces null and false but not a number, so a non-string login survives into
# `author` as a non-string. Coverage for the AC7 shape family, not a regression pin: no
# consumer of a comment or review `author` applies a string operation to it.
assert_eq "#1443 malformed: user.login is a number (comment leg)" "0 0" \
  "$(_uv '[{"user":{"login":123},"body":"nothing to read here","created_at":"2026-01-01T00:00:00Z"}]' '[]' | _uv_shape)"
assert_eq "#1443 malformed: user.login is an object (review leg)" "0 0" \
  "$(_uv '[]' '[{"user":{"login":{}},"state":"COMMENTED","body":"nothing to read here","submitted_at":"2026-01-01T00:00:00Z"}]' | _uv_shape)"
# The pages normalizer drops non-object ELEMENTS as well as coercing a non-array page;
# without that half a mixed-element page aborts every later .[] read.
assert_eq "#1443 malformed: a page carrying non-object elements still yields the surviving verdict" "REJECT" \
  "$(_uv '[]' "$(jq -nc --arg b "**Verdict: ✅ REJECT**" '[null,"x",{user:{login:"b[bot]"},state:"COMMENTED",body:$b,submitted_at:"2026-01-01T00:00:00Z"}]')" | _uv_verds)"
# The entry key set is unchanged, and the count feeds nothing: a rung-3 REJECT still
# drives review_reject_outstanding through review_verdicts alone.
assert_eq "#1443 entries still carry EXACTLY verdict/createdAt/source" "true" \
  "$(_uv "$(_uv_botc "$UV3_S4")" '[]' | jq -r 'all(.review_verdicts[]; (keys | sort) == ["createdAt","source","verdict"])')"
assert_eq "#1443 a rung-3 REJECT sets review_reject_outstanding=true" "true" \
  "$(_uv "$(_uv_botc "$UV3_S4")" '[]' | _uv_rro)"
assert_eq "#1443 an unparsed artifact alone never sets review_reject_outstanding" "false" \
  "$(_uv "$(_uv_botc "APPROVE"$'\n'"REJECT"$'\n'"third")" '[]' | _uv_rro)"
# The superseded devflow: spelling is accepted nowhere — not by rung 1, and not by
# the new rung reading the token out of the marker comment line.
assert_eq "#1443 a devflow:review-verdict line is not a verdict, even for a bot" "0 1" \
  "$(_uv '[]' "$(_uv_botr "<!-- devflow:review-verdict head=$UVM_HEAD verdict=REJECT -->")" | _uv_shape)"
# Adversarial: the new grammar quoted inside a finding, below the scanned window.
assert_eq "#1443 rung3: the grammar quoted below line 30 contributes nothing" "0 0" \
  "$(_uv '[]' "$(_uv_botr "$(jq -nr '[range(30)|"filler"] + ["```","## Verdict","APPROVE","```","> **Verdict: REJECT**"] | join("\n")')")" | _uv_shape)"
# Boundary: the scan window is the first 30 lines, inclusive. The probe line carries
# no `Verdict:` literal, so rung 2 — which scans every line — cannot answer for it, and
# the padding is blank so the line stays inside sub-rung 2's first-three-non-blank set.
assert_eq "#1443 rung3: a token on line 30 is read" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "$(jq -nr '[range(29)|""] + ["## ✅ Devflow Review — APPROVE"] | join("\n")')")" | _uv_verds)"
assert_eq "#1443 rung3: the same token on line 31 is neither read nor counted" "0 0" \
  "$(_uv '[]' "$(_uv_botr "$(jq -nr '[range(30)|""] + ["## ✅ Devflow Review — APPROVE"] | join("\n")')")" | _uv_shape)"
# Boundary: the heading lookahead skips blank lines but stops at another heading.
assert_eq "#1443 rung3: Verdict heading resolves across blank lines" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "one"$'\n'"two"$'\n'"three"$'\n\n'"## Verdict"$'\n\n\n\n'"**APPROVE** ✅")" | _uv_verds)"
assert_eq "#1443 rung3: Verdict heading followed by another heading does not resolve" "0 1" \
  "$(_uv '[]' "$(_uv_botr "one"$'\n'"two"$'\n'"three"$'\n\n'"## Verdict"$'\n\n'"## Findings"$'\n'"APPROVE")" | _uv_shape)"
# Multiplicity and ordering: two artifacts matching different sub-rungs, timestamp
# order preserved, and an untimestamped entry appended after the partition.
assert_eq "#1443 rung3: two artifacts, different sub-rungs → timestamp order" "APPROVE REJECT" \
  "$(_uv '[]' "$(jq -nc --arg a "$UV3_S1" --arg r "$UV3_S4" '[{user:{login:"b[bot]"},state:"COMMENTED",body:$a,submitted_at:"2026-01-01T00:00:00Z"},{user:{login:"b[bot]"},state:"COMMENTED",body:$r,submitted_at:"2026-01-02T00:00:00Z"}]')" | _uv_verds)"
assert_eq "#1443 rung3: an untimestamped entry lands after the timestamped partition" "REJECT APPROVE" \
  "$(_uv '[]' "$(jq -nc --arg a "$UV3_S1" --arg r "$UV3_S4" '[{user:{login:"b[bot]"},state:"COMMENTED",body:$a,submitted_at:null},{user:{login:"b[bot]"},state:"COMMENTED",body:$r,submitted_at:"2026-01-02T00:00:00Z"}]')" | _uv_verds)"
# Absence: an empty body and a blank-only body each contribute nothing and count nothing.
assert_eq "#1443 rung3: an empty body contributes nothing and raises no count" "0 0" \
  "$(_uv '[]' "$(_uv_botr "")" | _uv_shape)"
assert_eq "#1443 rung3: a blank-only body contributes nothing and raises no count" "0 0" \
  "$(_uv '[]' "$(_uv_botr $'\n\n\n')" | _uv_shape)"
# Negative controls INSIDE the scan window: rung 3 must not mint a verdict from
# ordinary bot prose, a substring, a quoted line, or commented-out text.
assert_eq "#1443 rung3: incidental token in bot prose is not a verdict" "0 1" \
  "$(_uv "$(_uv_botc "Claude finished addressing the REJECT findings."$'\n\n'"All fixed.")" '[]' | _uv_shape)"
assert_eq "#1443 rung3: a token in prose BELOW an anchored headline is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "### /prflow:review-and-fix"$'\n\n'"Addressed every REJECT finding from the last review.")" | _uv_shape)"
# The same-line case: the anchor and the token share one line, so no other rung-3
# constraint applies — only sub-rung 2's own whole-line shape rejects it.
assert_eq "#1443 rung3: a token in prose ON an anchored headline is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## Review: addressed the REJECT findings"$'\n\n'"Done.")" | _uv_shape)"
# The escalation guard needs a body sub-rung 2 WOULD otherwise answer, or it stays green
# with the guard deleted.
assert_eq "#1443 rung3: a non-resolving Verdict: line does not escalate to a looser sub-rung" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Verdict: pending"$'\n\n'"Devflow Review: APPROVE")" | _uv_shape)"
assert_eq "#1443 rung3: a mid-sentence Verdict: mention is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "See the prior Verdict: REJECT here."$'\n\n'"Nothing new.")" | _uv_shape)"
assert_eq "#1443 rung3: a sentence whose words collapse to a headline is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Do not review. REJECT."$'\n\n'"Explained above.")" | _uv_shape)"
assert_eq "#1443 rung3: a tilde-fenced rung-3 shape is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Quoting the contract:"$'\n\n'"~~~"$'\n'"## ✅ Devflow Review — APPROVE"$'\n'"~~~")" | _uv_shape)"
# A structural prefix is not decoration: a list marker, an ordinal, a table pipe, a
# strikethrough run and a code indent each mark the line as something other than a
# verdict headline — most often a recap QUOTING a superseded verdict.
assert_eq "#1443 rung3: a list-item Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## /prflow:review-and-fix"$'\n\n'"- [ ] Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: an ordinal-listed Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Starting from:"$'\n\n'"1. Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a table-cell Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"| Verdict: REJECT |")" | _uv_shape)"
assert_eq "#1443 rung3: a struck-through Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "~~Verdict: REJECT~~"$'\n\n'"Superseded.")" | _uv_shape)"
assert_eq "#1443 rung3: an indented-code Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Example:"$'\n\n'"    Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a table-row Review headline is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"| Review | REJECT |")" | _uv_shape)"
assert_eq "#1443 rung3: a bulleted option under a Verdict heading is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## Verdict"$'\n\n'"- APPROVE")" | _uv_shape)"
# Sub-rung 1 matches its token case-sensitively, as sub-rung 2 does.
assert_eq "#1443 rung3: a lowercase verdict token is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "verdict: reject"$'\n\n'"Explained above.")" | _uv_shape)"
# The three anchors the previous pass shipped uncovered.
assert_eq "#1443 rung3: trailing prose after the token is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Verdict: REJECT was superseded by a later APPROVE."$'\n\n'"Done.")" | _uv_shape)"
assert_eq "#1443 rung3: trailing prose after a Verdict heading token is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## Verdict"$'\n\n'"APPROVE after the fixes landed.")" | _uv_shape)"
assert_eq "#1443 count: a lowercase token still raises the residual count" "0 1" \
  "$(_uv '[]' "$(_uv_botr "the reviewer said approve"$'\n\n'"Nothing else.")" | _uv_shape)"
# A star bullet is a list marker as much as a dash is, and a typographic quote marks a
# recap of someone else's verdict — neither is emphasis.
assert_eq "#1443 rung3: a star-bulleted Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"* Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a curly-quoted Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "The earlier review said:"$'\n\n''“Verdict: REJECT”')" | _uv_shape)"
assert_eq "#1443 rung3: a bullet-glyph Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"• Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: an em-dash-prefixed Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"— Verdict: REJECT")" | _uv_shape)"
# Trailing prose is prose in every script, not only in Latin letters.
assert_eq "#1443 rung3: non-Latin trailing prose after the token is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Verdict: REJECT — 已被后续的批准取代"$'\n\n'"Done.")" | _uv_shape)"
# The leading word is script-agnostic: one word plus the anchor plus the token is the same
# headline whatever script the word is in, so this resolves exactly as an English one does.
assert_eq "#1443 rung3: a non-Latin leading word makes the same headline" "REJECT" \
  "$(_uv '[]' "$(_uv_botr "结论 Verdict: REJECT"$'\n\n'"Done.")" | _uv_verds)"
# Stripping a line must not pull a later line into sub-rung 2's three-line window.
assert_eq "#1443 rung3: stripping an indented block does not widen the three-line window" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Example:"$'\n\n'"    quoted line one"$'\n'"    quoted line two"$'\n\n'"Devflow Review: REJECT")" | _uv_shape)"
# A fence closes only on its own marker, so a tilde line inside a backtick block is content.
# No preamble: the shape must sit inside sub-rung 2's window, or the fence rule is never
# the deciding factor and the assertion cannot fail under its own named regression.
assert_eq "#1443 rung3: a tilde line does not close a backtick fence" "0 1" \
  "$(_uv '[]' "$(_uv_botr "\`\`\`"$'\n'"~~~"$'\n'"## ✅ Devflow Review — APPROVE"$'\n'"\`\`\`")" | _uv_shape)"
# Stripping a line must not close the gap between a Verdict heading and a later token:
# the line ADJACENT to the heading is a list item, so the heading resolves to nothing.
assert_eq "#1443 rung3: a stripped block does not make a later token adjacent to a heading" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## Verdict"$'\n\n'"- an item"$'\n'"- another"$'\n\n'"**REJECT**")" | _uv_shape)"
# A stripped line stays stripped even when an identical string survives elsewhere.
assert_eq "#1443 rung3: a fenced line is not re-admitted by an identical later line" "0 1" \
  "$(_uv '[]' "$(_uv_botr "\`\`\`"$'\n'"Devflow Review: REJECT"$'\n'"\`\`\`"$'\n'"padding one"$'\n'"padding two"$'\n'"Devflow Review: REJECT")" | _uv_shape)"
# Dingbat bullets and heavy quotation marks are not emoji decoration.
assert_eq "#1443 rung3: a dingbat-bulleted Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Earlier:"$'\n\n'"➤ Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a ballot-box Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Earlier:"$'\n\n'"☑ Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a heavy-quoted Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Earlier:"$'\n\n'"❝ Verdict: REJECT ❞")" | _uv_shape)"
# The emoji planes hold speech-bubble and pointer glyphs too, so the allow-list has to
# reach them as well as the dingbats — this case is separable from the dingbat siblings.
assert_eq "#1443 rung3: a speech-bubble Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Earlier:"$'\n\n'"🗨 Verdict: REJECT")" | _uv_shape)"
assert_eq "#1443 rung3: a pointer-glyph Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Earlier:"$'\n\n'"👉 Verdict: REJECT")" | _uv_shape)"
# The verdict glyphs the corpus actually uses stay legal prefixes.
assert_eq "#1443 rung3: a red-circle verdict headline still resolves" "REJECT" \
  "$(_uv '[]' "$(_uv_botr "🔴 Devflow Review — REJECT"$'\n\n'"Done.")" | _uv_verds)"
# A table row is a table row whether or not it opens with a pipe.
assert_eq "#1443 rung3: a pipe-bearing Verdict: line is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Summary:"$'\n\n'"what | Verdict: REJECT |")" | _uv_shape)"
# The comment-region strip needs a body whose commented-out line a rung WOULD read.
assert_eq "#1443 rung3: a rung-3 shape inside a multi-line HTML comment is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "<!--"$'\n'"## Devflow Review — APPROVE"$'\n'"-->"$'\n'"Some review text.")" | _uv_shape)"
# APPROVED yields no verdict, but still RAISES the residual count: the counter's operand
# stays wider than the verdict tokenizer, or an unread artifact vanishes from both.
assert_eq "#1443 rung3: APPROVED is not the APPROVE token but still counts as unread" "0 1" \
  "$(_uv '[]' "$(_uv_botr "This PR was APPROVED by the maintainer."$'\n\n'"Nothing else to say.")" | _uv_shape)"
assert_eq "#1443 count: a rung-3 shape carrying a past-tense token still counts as unread" "0 1" \
  "$(_uv '[]' "$(_uv_botr "## Devflow Review — APPROVED"$'\n\n'"Done.")" | _uv_shape)"
assert_eq "#1443 rung3: a blockquoted verdict inside the window is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Addressing the review:"$'\n\n'"> **Verdict: REJECT**"$'\n\n'"Fixed now.")" | _uv_shape)"
# The fenced shape must carry no rung-2 `Verdict:` heading: rung 2 scans every line with
# no window, so such a heading is read by rung 2 and never reaches rung 3.
assert_eq "#1443 rung3: a fenced rung-3 shape inside the window is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "Quoting the contract:"$'\n\n'"\`\`\`"$'\n'"## ✅ Devflow Review — APPROVE"$'\n'"\`\`\`")" | _uv_shape)"
assert_eq "#1443 rung3: a MULTI-LINE HTML comment carrying a marker is not a verdict" "0 1" \
  "$(_uv '[]' "$(_uv_botr "<!--"$'\n'"devflow:review-verdict head=$UVM_HEAD verdict=REJECT"$'\n'"-->"$'\n'"Some review text.")" | _uv_shape)"
# The at-most-one contract, asserted rather than only stated.
assert_eq "#1443 rung3: two rung-3 verdict lines contribute exactly one entry" "1-APPROVE" \
  "$(_uv '[]' "$(_uv_botr "**Verdict: APPROVE**"$'\n\n'"later"$'\n\n'"**Verdict: ❌ REJECT**")" | jq -r '"\(.review_verdicts | length)-\(.review_verdicts[0].verdict)"')"
# Rung 2 still pre-empts rung 3, as rung 1 does. The two rungs must disagree and the
# rung-3 shape must come FIRST, or the assertion stays green with rung 2 disabled.
assert_eq "#1443 rung3: the rung-2 heading grammar pre-empts the new rung" "APPROVE" \
  "$(_uv '[]' "$(_uv_botr "**Devflow Review: REJECT** ✅"$'\n\n'"## Verdict: APPROVE (looks good)")" | _uv_verds)"
# Idempotency: two runs over identical payloads emit byte-identical results.
UV3_RUN1="$(_uv "$(_uv_botc "$UV3_S3")" "$(_uv_botr "$UV3_S4")" | jq -c '{review_verdicts, review_verdict_unparsed_count}')"
UV3_RUN2="$(_uv "$(_uv_botc "$UV3_S3")" "$(_uv_botr "$UV3_S4")" | jq -c '{review_verdicts, review_verdict_unparsed_count}')"
assert_eq "#1443 rung3: the extraction is idempotent over identical payloads" "$UV3_RUN1" "$UV3_RUN2"
rm -rf "$F895"

# ────────────────────────────────────────────────────────────────────────────
echo "cheap-gate.jq"
# ────────────────────────────────────────────────────────────────────────────
gate() { jq -c -f "$LIB/cheap-gate.jq"; }
BASE='{"signals":{"review_comments_count":0,"post_bot_commits":0,"ci_failures_during_pr":0,"ci_status_unknown":false,"workpad_final_status":"Complete","review_reject_outstanding":false}}'
assert_eq "all clean → clean=true"            "true"  "$(echo "$BASE" | gate | jq -r .clean)"
assert_eq "reject outstanding → clean=false"  "false" "$(echo "$BASE" | jq '.signals.review_reject_outstanding=true' | gate | jq -r .clean)"
assert_eq "ci failure → clean=false"          "false" "$(echo "$BASE" | jq '.signals.ci_failures_during_pr=1' | gate | jq -r .clean)"
assert_eq "ci_status_unknown=true → clean=false" "false" "$(echo "$BASE" | jq '.signals.ci_status_unknown=true' | gate | jq -r .clean)"
assert_eq "ci_status_unknown=true reason"     "CI status could not be read" "$(echo "$BASE" | jq '.signals.ci_status_unknown=true' | gate | jq -r .reason)"
assert_eq "human commit → clean=false"        "false" "$(echo "$BASE" | jq '.signals.post_bot_commits=2' | gate | jq -r .clean)"
assert_eq "review comment → clean=false"      "false" "$(echo "$BASE" | jq '.signals.review_comments_count=1' | gate | jq -r .clean)"
assert_eq "workpad Blocked → clean=false"     "false" "$(echo "$BASE" | jq '.signals.workpad_final_status="Blocked"' | gate | jq -r .clean)"
assert_eq "#356: workpad Failed → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status="Failed"' | gate | jq -r .clean)"
assert_eq "#356: workpad Failed → reason 'workpad status not Complete'" "workpad status not Complete" "$(echo "$BASE" | jq '.signals.workpad_final_status="Failed"' | gate | jq -r .reason)"
# #626: an ABSENT workpad ("" / null / an absent key) fails CLOSED, symmetric with
# the corrupt Unparsed case — these two assertions previously pinned the fail-OPEN
# laundering this issue removes (they asserted clean=true) and are flipped here.
assert_eq "#626: workpad empty string → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status=""' | gate | jq -r .clean)"
assert_eq "#626: workpad empty string → reason 'workpad absent or status unknown'" "workpad absent or status unknown" "$(echo "$BASE" | jq '.signals.workpad_final_status=""' | gate | jq -r .reason)"
assert_eq "#626: workpad null → clean=false"         "false" "$(echo "$BASE" | jq '.signals.workpad_final_status=null' | gate | jq -r .clean)"
assert_eq "#626: workpad null → reason 'workpad absent or status unknown'" "workpad absent or status unknown" "$(echo "$BASE" | jq '.signals.workpad_final_status=null' | gate | jq -r .reason)"
assert_eq "#626: workpad absent key → clean=false" "false" "$(echo "$BASE" | jq 'del(.signals.workpad_final_status)' | gate | jq -r .clean)"
assert_eq "#626: workpad absent key → reason 'workpad absent or status unknown'" "workpad absent or status unknown" "$(echo "$BASE" | jq 'del(.signals.workpad_final_status)' | gate | jq -r .reason)"
# #626: the existing status vocabulary is unchanged — Complete stays clean; the four
# non-empty non-Complete words keep the byte-identical "workpad status not Complete".
assert_eq "#626: workpad Complete → clean=true" "true" "$(echo "$BASE" | gate | jq -r .clean)"
assert_eq "#626: workpad Unparsed → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status="Unparsed"' | gate | jq -r .clean)"
assert_eq "#626: workpad Unparsed → reason 'workpad status not Complete'" "workpad status not Complete" "$(echo "$BASE" | jq '.signals.workpad_final_status="Unparsed"' | gate | jq -r .reason)"
assert_eq "#626: workpad Absent sentinel → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status="Absent"' | gate | jq -r .clean)"
assert_eq "#626: workpad Absent sentinel → reason 'workpad status not Complete'" "workpad status not Complete" "$(echo "$BASE" | jq '.signals.workpad_final_status="Absent"' | gate | jq -r .reason)"
assert_eq "#626: workpad NoIssue sentinel → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status="NoIssue"' | gate | jq -r .clean)"
# #626: a wrong-type status (JSON boolean true) gates non-clean via the fallthrough.
assert_eq "#626: workpad wrong-type (true) → clean=false" "false" "$(echo "$BASE" | jq '.signals.workpad_final_status=true' | gate | jq -r .clean)"

# #895: fail closed when review_reject_outstanding is not readable as a boolean.
# The new arm is evaluated BEFORE every existing arm, with a reason distinct from
# both workpad reason literals (AC19/AC20). The closed set of unreadable shapes:
UGATE_REASON="review-verdict signal unreadable"
# — .signals is not a JSON object —
assert_eq "#895 gate: signals null → fail-closed reason (was 'workpad absent')" "$UGATE_REASON" \
  "$(echo '{"signals":null}' | gate | jq -r .reason)"
assert_eq "#895 gate: signals null → clean=false, no abort" "false" \
  "$(echo '{"signals":null}' | gate | jq -r .clean)"
assert_eq "#895 gate: signals absent key → fail-closed reason" "$UGATE_REASON" \
  "$(echo '{}' | gate | jq -r .reason)"
assert_eq "#895 gate: signals as a JSON string → fail-closed (no index abort)" "$UGATE_REASON" \
  "$(echo '{"signals":"nope"}' | gate | jq -r .reason)"
assert_eq "#895 gate: signals as a JSON array → fail-closed (no index abort)" "$UGATE_REASON" \
  "$(echo '{"signals":[1,2]}' | gate | jq -r .reason)"
assert_eq "#895 gate: signals as a JSON number → fail-closed" "$UGATE_REASON" \
  "$(echo '{"signals":7}' | gate | jq -r .reason)"
# — .signals is an object but the field is absent/null/non-boolean —
assert_eq "#895 gate: review_reject_outstanding absent → fail-closed" "$UGATE_REASON" \
  "$(echo "$BASE" | jq 'del(.signals.review_reject_outstanding)' | gate | jq -r .reason)"
assert_eq "#895 gate: review_reject_outstanding null → fail-closed" "$UGATE_REASON" \
  "$(echo "$BASE" | jq '.signals.review_reject_outstanding=null' | gate | jq -r .reason)"
# The two type-boundary cases: a JSON string is truthy in jq, so "false" must NOT
# read as an outstanding REJECT, and "true" must NOT pass as a real boolean.
assert_eq "#895 gate: review_reject_outstanding string \"false\" → fail-closed" "$UGATE_REASON" \
  "$(echo "$BASE" | jq '.signals.review_reject_outstanding="false"' | gate | jq -r .reason)"
assert_eq "#895 gate: review_reject_outstanding string \"true\" → fail-closed" "$UGATE_REASON" \
  "$(echo "$BASE" | jq '.signals.review_reject_outstanding="true"' | gate | jq -r .reason)"
# The new reason is neither workpad reason literal (AC20).
assert_eq "#895 gate: fail-closed reason ≠ 'workpad absent or status unknown'" "false" \
  "$([ "$UGATE_REASON" = "workpad absent or status unknown" ] && echo true || echo false)"
assert_eq "#895 gate: fail-closed reason ≠ 'workpad status not Complete'" "false" \
  "$([ "$UGATE_REASON" = "workpad status not Complete" ] && echo true || echo false)"
# Regression: a real boolean keeps today's behavior on both values.
assert_eq "#895 gate: real boolean false → clean stays true" "true" \
  "$(echo "$BASE" | gate | jq -r .clean)"
assert_eq "#895 gate: real boolean true → outstanding REJECT reason" "outstanding /review REJECT" \
  "$(echo "$BASE" | jq '.signals.review_reject_outstanding=true' | gate | jq -r .reason)"

# ────────────────────────────────────────────────────────────────────────────
echo "issue #626: dispatch-disposition.jq — mechanical skip-or-dispatch classifier"
# ────────────────────────────────────────────────────────────────────────────
# Runs only on a non-clean bundle. Returns "skip" EXACTLY when all three hold:
# gate reason is a workpad reason literal, status is a sentinel (Absent/NoIssue),
# provenance is false. Otherwise "dispatch". The producer emits sentinel "Absent"/
# "NoIssue" (non-empty, non-Complete), so the gate reason on those is the existing
# 'workpad status not Complete' arm — which the disposition accepts as a workpad
# reason alongside 'workpad absent or status unknown'.
disp() {
  local _bundle="$1" _g
  _g="$(printf '%s' "$_bundle" | jq -c -f "$LIB/cheap-gate.jq")"
  printf '%s' "$_bundle" | jq -c --argjson gate "$_g" -f "$LIB/dispatch-disposition.jq"
}
DBASE='{"signals":{"review_comments_count":0,"post_bot_commits":0,"ci_failures_during_pr":0,"ci_status_unknown":false,"review_reject_outstanding":false,"workpad_final_status":"Absent"},"pr_devflow_provenance":false}'
assert_eq "#626 disp: Absent + no provenance → skip" "skip" "$(disp "$DBASE" | jq -r .disposition)"
assert_eq "#626 disp: skip reason names the sentinel" "no DevFlow provenance and no workpad audit trail — workpad_final_status is Absent; skipping without analysis" "$(disp "$DBASE" | jq -r .reason)"
assert_eq "#626 disp: NoIssue + no provenance → skip" "skip" "$(disp "$(echo "$DBASE" | jq -c '.signals.workpad_final_status="NoIssue"')" | jq -r .disposition)"
assert_eq "#626 disp: Absent + provenance true → dispatch" "dispatch" "$(disp "$(echo "$DBASE" | jq -c '.pr_devflow_provenance=true')" | jq -r .disposition)"
assert_eq "#626 disp: NoIssue + CI failure → dispatch (non-workpad gate reason wins)" "dispatch" "$(disp "$(echo "$DBASE" | jq -c '.signals.workpad_final_status="NoIssue" | .signals.ci_failures_during_pr=1')" | jq -r .disposition)"
assert_eq "#626 disp: Absent + outstanding REJECT → dispatch" "dispatch" "$(disp "$(echo "$DBASE" | jq -c '.signals.review_reject_outstanding=true')" | jq -r .disposition)"
assert_eq "#626 disp: non-sentinel status (Blocked) → dispatch" "dispatch" "$(disp "$(echo "$DBASE" | jq -c '.signals.workpad_final_status="Blocked"')" | jq -r .disposition)"
assert_eq "#626 disp: wrong-type provenance → treated false → skip" "skip" "$(disp "$(echo "$DBASE" | jq -c '.pr_devflow_provenance="yes"')" | jq -r .disposition)"
assert_eq "#626 disp: absent provenance key → treated false → skip" "skip" "$(disp "$(echo "$DBASE" | jq -c 'del(.pr_devflow_provenance)')" | jq -r .disposition)"

# #895 disp: a non-object .signals must route to dispatch, not abort on the index
# (AC28). Drives the whole bundle through REAL cheap-gate → dispatch-disposition.
assert_eq "#895 disp: signals as a JSON string → dispatch (no abort)" "dispatch" \
  "$(disp '{"signals":"nope","pr_devflow_provenance":false}' | jq -r .disposition)"
assert_eq "#895 disp: signals as a JSON array → dispatch (no abort)" "dispatch" \
  "$(disp '{"signals":[1,2],"pr_devflow_provenance":false}' | jq -r .disposition)"
assert_eq "#895 disp: signals null → dispatch (no abort)" "dispatch" \
  "$(disp '{"signals":null,"pr_devflow_provenance":false}' | jq -r .disposition)"
# The fail-closed review-signal reason is not a workpad reason, so it dispatches
# even alongside a sentinel status and no provenance (AC21).
assert_eq "#895 disp: fail-closed review-signal reason → dispatch" "dispatch" \
  "$(disp "$(echo "$DBASE" | jq -c 'del(.signals.review_reject_outstanding)')" | jq -r .disposition)"

# ── #626 marker-entry consumer handling ──────────────────────────────────────
# A skip marker entry {kind:"skip", pr, reason} is processed-PR bookkeeping, not a
# retrospective analysis. Every reader of retrospectives.jsonl handles it deliberately.
MRK='{"kind":"skip","pr":77,"reason":"no DevFlow provenance and no workpad audit trail — workpad_final_status is Absent; skipping without analysis"}'
IMPL_ENTRY='{"schema_version":2,"kind":"implementation","pr":77,"merged_at":"2026-06-01T00:00:00Z","verdict":"imperfect","categories":["convention-violation"],"descriptors":["x"],"suggested_interventions":[{"summary":"fix it","candidate_targets":["skills/a/SKILL.md"]}]}'
# recurring-targets.jq: a skip marker contributes no target (explicit kind filter #626).
assert_eq "#626 consumer: recurring-targets excludes skip markers" "0" \
  "$(printf '%s\n' "$MRK" | jq -s -f "$LIB/recurring-targets.jq" | jq 'length')"
# A skip marker sharing a PR with a real impl entry does not perturb that target's count.
assert_eq "#626 consumer: recurring-targets counts the impl entry, skip marker ignored" "skills/a/SKILL.md" \
  "$(printf '%s\n%s\n%s\n' "$IMPL_ENTRY" "$MRK" "$(echo "$IMPL_ENTRY" | jq -c '.pr=78')" | jq -s -f "$LIB/recurring-targets.jq" | jq -r '.[0].target // "none"')"
# compute-patterns.jq: a skip marker forms no pattern (selects implementation/audit only).
assert_eq "#626 consumer: compute-patterns excludes skip markers (empty object)" "0" \
  "$(printf '%s\n' "$MRK" | jq -s -L "$LIB" -f "$LIB/compute-patterns.jq" --slurpfile overrides <(echo '{}') | jq 'keys | length')"
# open-state-pr.sh N counts entries excluding skip markers.
OSP_TMP="$(mktemp -d)"
printf '%s\n%s\n' "$IMPL_ENTRY" "$MRK" > "$OSP_TMP/retrospectives.jsonl"
assert_eq "#626 consumer: open-state-pr N excludes skip markers (1 real of 2 lines)" "1" \
  "$(cd "$OSP_TMP" && mkdir -p .prflow/learnings && cp retrospectives.jsonl .prflow/learnings/ && DEVFLOW_GH=/bin/true bash "$LIB/open-state-pr.sh" --dry-run 2>/dev/null | grep -oE '\([0-9]+ entries\)' | grep -oE '[0-9]+' | head -1)"
rm -rf "$OSP_TMP"
# materialize-retrospectives.sh: a skip marker merges by pr+kind and does NOT clobber
# the implementation entry for the same PR (different kind).
MAT_TMP="$(mktemp -d)"
printf '%s\n' "$IMPL_ENTRY" > "$MAT_TMP/store.jsonl"
printf '%s\n' "$MRK" > "$MAT_TMP/new.jsonl"
bash "$LIB/materialize-retrospectives.sh" "$MAT_TMP/new.jsonl" "$MAT_TMP/store.jsonl" >/dev/null 2>&1 || true
assert_eq "#626 consumer: materialize keeps the impl entry for PR 77 (skip marker is a distinct kind)" "1" \
  "$(jq -s '[.[] | select(.pr==77 and .kind=="implementation")] | length' "$MAT_TMP/store.jsonl")"
assert_eq "#626 consumer: materialize appends the skip marker for PR 77" "1" \
  "$(jq -s '[.[] | select(.pr==77 and .kind=="skip")] | length' "$MAT_TMP/store.jsonl")"
rm -rf "$MAT_TMP"
# build-experiment-records.py: a skip marker is excluded from experiment-record
# CANDIDACY. Observable behavior, not a grep-pin: a retro store holding ONLY a skip
# marker yields no candidates at all (the assembler breadcrumbs "no candidate PRs"
# and writes an empty store), whereas the same store holding a real entry for that
# same PR DOES select it. Deleting the `kind == "skip"` guard flips the first arm,
# because the marker carries a numeric `.pr` that `_pr_of` reads happily.
BXR626="$LIB/../scripts/build-experiment-records.py"
BXR626_TMP="$(mktemp -d)"
printf '%s\n' "$MRK" > "$BXR626_TMP/retro.jsonl"
BXR626_SKIPONLY="$(DEVFLOW_GH=/bin/false python3 "$BXR626" --repo-root "$BXR626_TMP" \
  --retrospectives "$BXR626_TMP/retro.jsonl" --store "$BXR626_TMP/store.jsonl" --dry-run 2>&1 >/dev/null || true)"
assert_eq "#626 consumer: build-experiment-records treats a skip-only store as no candidates" "true" \
  "$(printf '%s' "$BXR626_SKIPONLY" | grep -qF 'no candidate PRs to process' && echo true || echo false)"
BXR626_OUT="$(DEVFLOW_GH=/bin/false python3 "$BXR626" --repo-root "$BXR626_TMP" \
  --retrospectives "$BXR626_TMP/retro.jsonl" --store "$BXR626_TMP/store.jsonl" --dry-run 2>/dev/null || true)"
assert_eq "#626 consumer: skip marker produces no experiment record" "0" \
  "$(printf '%s' "$BXR626_OUT" | grep -c . || true)"
# Control: the SAME PR with a real retrospective entry IS a candidate — proving the
# exclusion above is the kind guard, not an unrelated empty-window artifact.
printf '%s\n' "$IMPL_ENTRY" > "$BXR626_TMP/retro.jsonl"
BXR626_REAL="$(DEVFLOW_GH=/bin/false python3 "$BXR626" --repo-root "$BXR626_TMP" \
  --retrospectives "$BXR626_TMP/retro.jsonl" --store "$BXR626_TMP/store.jsonl" --dry-run 2>&1 >/dev/null || true)"
assert_eq "#626 consumer: a real entry for the same PR IS a candidate (control)" "false" \
  "$(printf '%s' "$BXR626_REAL" | grep -qF 'no candidate PRs to process' && echo true || echo false)"
rm -rf "$BXR626_TMP"

# ── #626 render-report.sh: the `skipped:` summary line and the branch-selecting
# `### Skipped PRs` section. Both arms of the branch are driven (present when
# non-zero, omitted when empty), plus the numeric guard's degrade-to-omitted path
# — the repo convention that a message-and-branch-selecting shape is suite-driven
# rather than grep-pinned (cf. scripts/describe-denial-count.sh).
( . "$LIB/render-report.sh"
  RR626_SUM='{"prs_scanned":3,"clean_count":1,"analyzed_count":1,"skipped_count":1,"skips":["PR #77 skipped (mechanical, no DevFlow provenance): no workpad audit trail"],"intervention_issues":[],"blockers":[]}'
  RR626_REPORT="$(devflow_render_report "$RR626_SUM")"
  assert_eq "#626 render-report: summary carries the skipped: count" "true" \
    "$(printf '%s' "$RR626_REPORT" | grep -qF 'skipped: 1' && echo true || echo false)"
  assert_eq "#626 render-report: Skipped PRs section present when skips non-empty" "true" \
    "$(printf '%s' "$RR626_REPORT" | grep -qF '### Skipped PRs' && echo true || echo false)"
  assert_eq "#626 render-report: the skip record renders as a bullet" "true" \
    "$(printf '%s' "$RR626_REPORT" | grep -qF -- '- PR #77 skipped (mechanical, no DevFlow provenance)' && echo true || echo false)"
  # Empty arm: skips absent entirely → section omitted, and the summary still
  # reports skipped: 0 (the count line is unconditional, unlike the section).
  RR626_EMPTY='{"prs_scanned":1,"clean_count":1,"analyzed_count":0,"intervention_issues":[],"blockers":[]}'
  RR626_R2="$(devflow_render_report "$RR626_EMPTY")"
  assert_eq "#626 render-report: Skipped PRs section omitted when no skips" "false" \
    "$(printf '%s' "$RR626_R2" | grep -qF '### Skipped PRs' && echo true || echo false)"
  assert_eq "#626 render-report: skipped: 0 still shown with no skips" "true" \
    "$(printf '%s' "$RR626_R2" | grep -qF 'skipped: 0' && echo true || echo false)"
  # Numeric guard: a boolean `.skips` (a hand-corrupted summary) makes `length` abort
  # jq. Without the `|| true` + numeric guard, the failing substitution kills the whole
  # report under set -e; with it, the section is merely omitted and every other section
  # still renders. Assert the report survives AND stays complete, not just non-empty.
  RR626_BAD='{"prs_scanned":1,"clean_count":0,"analyzed_count":1,"skips":true,"intervention_issues":[],"blockers":[]}'
  RR626_R3="$(devflow_render_report "$RR626_BAD" 2>/dev/null || echo RENDER_ABORTED)"
  assert_eq "#626 render-report: wrong-type skips does not abort the report" "false" \
    "$(printf '%s' "$RR626_R3" | grep -qF 'RENDER_ABORTED' && echo true || echo false)"
  assert_eq "#626 render-report: wrong-type skips still renders later sections" "true" \
    "$(printf '%s' "$RR626_R3" | grep -qF '## Issues filed' && echo true || echo false)"
  assert_eq "#626 render-report: wrong-type skips omits the Skipped PRs section" "false" \
    "$(printf '%s' "$RR626_R3" | grep -qF '### Skipped PRs' && echo true || echo false)"
)

# ── #626 orchestrator surface pins (skills/retrospective-weekly/SKILL.md) ─────
RW_SKILL="$LIB/../skills/retrospective-weekly/SKILL.md"
assert_pin_unique "#626: orchestrator carries the pre-dispatch disposition call" \
  '-f $LIB/dispatch-disposition.jq' "$RW_SKILL"
assert_pin_unique "#626: orchestrator recognizes a Stage A skip by the skip key only, not error text" \
  'never by matching substrings of any error text' "$RW_SKILL"
assert_pin_unique "#626: orchestrator marker split keys the marker on the mechanical status" \
  'Whether it leaves a marker depends' "$RW_SKILL"

# ────────────────────────────────────────────────────────────────────────────
echo "issue #97: reserved DevFlow label + issue-workpad reflection ingestion"
# ────────────────────────────────────────────────────────────────────────────

# ── ensure-label.sh: REST create, idempotent, always exit 0 (best-effort) ────
# The helper now creates via `gh api --method POST repos/{owner}/{repo}/labels`
# (repo-scope only) rather than `gh label create` (org-scoped GraphQL). The stub
# matches the REST POST: first call succeeds (created); a marker makes the second
# report HTTP 422 / already_exists (the REST already-exists shape); a separate
# stub forces a hard failure. Each run still exits 0 with its own breadcrumb.
EL_TMP="$(mktemp -d)"
cat > "$EL_TMP/gh" <<'STUB'
#!/usr/bin/env bash
# Record argv so the test can assert the REST endpoint + fields are targeted.
printf '%s' "$*" > "$(dirname "$0")/create-args"
MARK="$(dirname "$0")/.created"
case "$*" in
  *"--method POST"*"/labels"*)
    if [ -f "$MARK" ]; then echo '{"message":"Validation Failed","errors":[{"resource":"Label","code":"already_exists","field":"name"}],"status":"422"}' >&2; echo "gh: Validation Failed (HTTP 422)" >&2; exit 1; fi
    touch "$MARK"; echo '{}'; exit 0 ;;
  *) exit 0 ;;
esac
STUB
chmod +x "$EL_TMP/gh"
EL_E1="$(DEVFLOW_GH="$EL_TMP/gh" bash "$LIB/../scripts/ensure-label.sh" DevFlow 2>&1 >/dev/null)"; EL_R1=$?
EL_E2="$(DEVFLOW_GH="$EL_TMP/gh" bash "$LIB/../scripts/ensure-label.sh" DevFlow 2>&1 >/dev/null)"; EL_R2=$?
assert_eq "ensure-label: first run exits 0 (created)"            "0" "$EL_R1"
assert_eq "ensure-label: second run exits 0 (already exists)"    "0" "$EL_R2"
assert_eq "ensure-label: targets REST POST repos/{owner}/{repo}/labels (not gh label create)" "yes" \
  "$(grep -qF -- 'api --method POST repos/{owner}/{repo}/labels' "$EL_TMP/create-args" && echo yes || echo no)"
assert_eq "ensure-label: passes the label name as a -f field" "yes" \
  "$(grep -qF -- 'name=DevFlow' "$EL_TMP/create-args" && echo yes || echo no)"
assert_eq "ensure-label: passes the description as a -f field" "yes" \
  "$(grep -qF -- 'description=Created by PRFlow automation' "$EL_TMP/create-args" && echo yes || echo no)"
assert_eq "ensure-label: first run breadcrumb says created" "yes" \
  "$(printf '%s' "$EL_E1" | grep -qiF 'created label' && echo yes || echo no)"
assert_eq "ensure-label: second run breadcrumb says already exists (HTTP 422)" "yes" \
  "$(printf '%s' "$EL_E2" | grep -qiF 'already exists' && echo yes || echo no)"
cat > "$EL_TMP/ghfail" <<'STUB'
#!/usr/bin/env bash
echo "HTTP 500: server error" >&2; exit 1
STUB
chmod +x "$EL_TMP/ghfail"
EL_E3="$(DEVFLOW_GH="$EL_TMP/ghfail" bash "$LIB/../scripts/ensure-label.sh" DevFlow 2>&1 >/dev/null)"; EL_R3=$?
assert_eq "ensure-label: hard gh failure still exits 0 (best-effort)" "0" "$EL_R3"
assert_eq "ensure-label: hard-failure breadcrumb names the failure" "yes" \
  "$(printf '%s' "$EL_E3" | grep -qiF 'could not ensure label' && echo yes || echo no)"
# A 422 for a DIFFERENT validation reason (no `already_exists` code) must NOT be
# swallowed as "already exists" — it routes to the failure breadcrumb. Guards the
# /simplify narrowing that dropped the over-broad bare `HTTP 422` match.
cat > "$EL_TMP/gh422" <<'STUB'
#!/usr/bin/env bash
echo '{"message":"Validation Failed","errors":[{"resource":"Label","code":"invalid","field":"name"}],"status":"422"}' >&2
echo "gh: Validation Failed (HTTP 422)" >&2; exit 1
STUB
chmod +x "$EL_TMP/gh422"
EL_E4="$(DEVFLOW_GH="$EL_TMP/gh422" bash "$LIB/../scripts/ensure-label.sh" DevFlow 2>&1 >/dev/null)"; EL_R4=$?
assert_eq "ensure-label: non-already_exists 422 still exits 0 (best-effort)" "0" "$EL_R4"
assert_eq "ensure-label: non-already_exists 422 is NOT swallowed as already-exists" "yes" \
  "$(printf '%s' "$EL_E4" | grep -qiF 'could not ensure label' && ! printf '%s' "$EL_E4" | grep -qiF 'already exists' && echo yes || echo no)"
# #480: empty/missing <name> arg-slip guard. A set-but-EMPTY argument (the shape a
# label call site emits when a configured list normalizes to blank) must warn to
# stderr and still exit 0 — NOT abort with a raw bash usage line + rc 1 (the retired
# `${1:?}` behavior). ensure-label.sh ALWAYS exits 0, so the rc==0 assertions pin only
# the best-effort contract — on their own they are vacuous against a guard-DELETION
# mutation (drop `if [ -z "$NAME" ]`, keep `${1:-}`, and control falls through to gh yet
# still exits 0). The load-bearing attribution is the `NOT a harness denial` breadcrumb,
# emitted ONLY by this guard (and apply-labels.sh's): the `gh_never` stub aborts non-zero
# if reached, so a mutant that dropped the guard falls through to gh and breadcrumbs
# `could not ensure label ''` INSTEAD — which lacks the phrase, flipping the breadcrumb
# assertions RED. So BOTH the empty-name and the zero-args capture assert the breadcrumb,
# not just the exit code — the exit-3 stub is not what proves the guard fired; the
# breadcrumb is (mirrors apply-labels.sh's marker-probe lesson, run.sh #480 block).
cat > "$EL_TMP/gh_never" <<'STUB'
#!/usr/bin/env bash
echo "ensure-label: gh must not be reached on an empty name" >&2; exit 3
STUB
chmod +x "$EL_TMP/gh_never"
EL_E5="$(DEVFLOW_GH="$EL_TMP/gh_never" bash "$LIB/../scripts/ensure-label.sh" "" 2>&1 >/dev/null)"; EL_R5=$?
assert_eq "ensure-label: empty-name arg-slip still exits 0 (best-effort, no abort)" "0" "$EL_R5"
assert_eq "ensure-label: empty-name breadcrumb names the arg-slip (NOT a harness denial)" "yes" \
  "$(printf '%s' "$EL_E5" | grep -qF 'NOT a harness denial' && echo yes || echo no)"
EL_E6="$(DEVFLOW_GH="$EL_TMP/gh_never" bash "$LIB/../scripts/ensure-label.sh" 2>&1 >/dev/null)"; EL_R6=$?
assert_eq "ensure-label: zero-args arg-slip still exits 0 (best-effort, no abort)" "0" "$EL_R6"
assert_eq "ensure-label: zero-args breadcrumb names the arg-slip (NOT a harness denial)" "yes" \
  "$(printf '%s' "$EL_E6" | grep -qF 'NOT a harness denial' && echo yes || echo no)"
rm -rf "$EL_TMP"

# ── apply-labels.sh: REST label-apply helper (best-effort, always exit 0) ─────
# Applies via POST repos/{owner}/{repo}/issues/{n}/labels (repo-scope only). The
# stub records argv so we can assert the endpoint + labels[] fields; a failing
# stub proves the best-effort exit-0 + breadcrumb contract; an empty label set
# proves no POST is made.
AL_TMP="$(mktemp -d)"
cat > "$AL_TMP/gh" <<'STUB'
#!/usr/bin/env bash
printf '%s' "$*" >> "$(dirname "$0")/apply-args"
echo '[]'; exit 0
STUB
chmod +x "$AL_TMP/gh"
: > "$AL_TMP/apply-args"
DEVFLOW_GH="$AL_TMP/gh" bash "$LIB/../scripts/apply-labels.sh" 42 DevFlow >/dev/null 2>&1; AL_R1=$?
assert_eq "apply-labels: exits 0 on success" "0" "$AL_R1"
assert_eq "apply-labels: targets REST POST issues/{n}/labels (not gh issue/pr edit)" "yes" \
  "$(grep -qF -- 'api --method POST repos/{owner}/{repo}/issues/42/labels' "$AL_TMP/apply-args" && echo yes || echo no)"
assert_eq "apply-labels: single label rides as a labels[] field" "yes" \
  "$(grep -qF -- 'labels[]=DevFlow' "$AL_TMP/apply-args" && echo yes || echo no)"
assert_eq "apply-labels: never falls back to gh issue/pr edit porcelain" "yes" \
  "$(grep -qF -- 'issue edit' "$AL_TMP/apply-args" || grep -qF -- 'pr edit' "$AL_TMP/apply-args" ; [ $? -ne 0 ] && echo yes || echo no)"
# Multi-label (separate args) and comma-separated single arg both expand every label.
: > "$AL_TMP/apply-args"
DEVFLOW_GH="$AL_TMP/gh" bash "$LIB/../scripts/apply-labels.sh" 42 DevFlow Retrospective >/dev/null 2>&1
assert_eq "apply-labels: multi-arg applies every label (DevFlow)" "yes" \
  "$(grep -qF -- 'labels[]=DevFlow' "$AL_TMP/apply-args" && echo yes || echo no)"
assert_eq "apply-labels: multi-arg applies every label (Retrospective)" "yes" \
  "$(grep -qF -- 'labels[]=Retrospective' "$AL_TMP/apply-args" && echo yes || echo no)"
: > "$AL_TMP/apply-args"
DEVFLOW_GH="$AL_TMP/gh" bash "$LIB/../scripts/apply-labels.sh" 42 "DevFlow,Deferred" >/dev/null 2>&1
assert_eq "apply-labels: comma-separated arg splits into every label (DevFlow)" "yes" \
  "$(grep -qF -- 'labels[]=DevFlow' "$AL_TMP/apply-args" && echo yes || echo no)"
assert_eq "apply-labels: comma-separated arg splits into every label (Deferred)" "yes" \
  "$(grep -qF -- 'labels[]=Deferred' "$AL_TMP/apply-args" && echo yes || echo no)"
# Empty / whitespace-only label set → no POST at all.
: > "$AL_TMP/apply-args"
DEVFLOW_GH="$AL_TMP/gh" bash "$LIB/../scripts/apply-labels.sh" 42 "   " >/dev/null 2>&1; AL_RE=$?
assert_eq "apply-labels: whitespace-only label set exits 0" "0" "$AL_RE"
assert_eq "apply-labels: whitespace-only label set makes no POST" "yes" \
  "$([ ! -s "$AL_TMP/apply-args" ] && echo yes || echo no)"
# Label value with a space/metachar rides as ONE literal labels[] field (no word-split,
# no shell expansion) — proves the "passed literally" contract the helper comment promises.
: > "$AL_TMP/apply-args"
DEVFLOW_GH="$AL_TMP/gh" bash "$LIB/../scripts/apply-labels.sh" 42 "needs review" >/dev/null 2>&1
assert_eq "apply-labels: a space-containing label is one literal labels[] field (no word-split)" "yes" \
  "$(grep -qF -- 'labels[]=needs review' "$AL_TMP/apply-args" && echo yes || echo no)"
# Best-effort: a failing gh still exits 0 and leaves a specific breadcrumb. The failure
# stub RECORDS its argv so "no porcelain fallback" is proven on the FAILURE path too — a
# future `|| gh issue edit …` retry on the RC≠0 branch would land here and trip the pin.
cat > "$AL_TMP/ghfail" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$(dirname "$0")/fail-args"
echo "HTTP 500: server error" >&2; exit 1
STUB
chmod +x "$AL_TMP/ghfail"
: > "$AL_TMP/fail-args"
AL_EF="$(DEVFLOW_GH="$AL_TMP/ghfail" bash "$LIB/../scripts/apply-labels.sh" 42 DevFlow 2>&1 >/dev/null)"; AL_RF=$?
assert_eq "apply-labels: hard gh failure still exits 0 (best-effort)" "0" "$AL_RF"
assert_eq "apply-labels: failure breadcrumb names the target and label(s)" "yes" \
  "$(printf '%s' "$AL_EF" | grep -qF '#42' && printf '%s' "$AL_EF" | grep -qF 'DevFlow' && echo yes || echo no)"
assert_eq "apply-labels: no porcelain fallback on the FAILURE path (no gh issue/pr edit retry)" "yes" \
  "$(! grep -qE 'issue edit|pr edit' "$AL_TMP/fail-args" && echo yes || echo no)"
rm -rf "$AL_TMP"

# ── apply-pr-triggerer.sh: best-effort PR assignment to the triggerer (#1165) ──
# Closed outcome contract: prints exactly ONE `assignment: applied <login>` /
# `assignment: skipped <reason>` token to STDOUT, ALWAYS exits 0, breadcrumbs to
# STDERR. Cloud tier (GITHUB_RUN_ID set) reads DEVFLOW_TRIGGERING_USER fail-closed;
# local tier resolves `gh api user --jq .login`. Confirms the login is present in
# the add-assignee response before reporting `applied`. The gh boundary is stubbed;
# the helper under test is never mocked. The `apply_pr_triggerer_matrix` below is
# closed by construction over the documented + adversarial response shapes.
# The scratch root is deliberately named with the `TMP_` prefix: the greps below read the
# argv this run's stubbed `gh` captured, not repository source, so they are executable
# assertions rather than source-presence pins — and the `TMP_`/`TEMP_` name is the
# declaration the issue-810 mutation-routing classifier reads to tell the two apart.
# Renaming it to anything else re-classifies every grep over it as a repository pin.
TMP_APT_SCRATCH="$(mktemp -d)"
# One stub, branched by GH_MODE. Records argv to $TMP_APT_SCRATCH/args so "no GitHub call on
# invalid input" is provable. `api user` returns a bare login (real gh applies --jq);
# the POST returns a raw JSON body (the helper pipes it to real jq for confirmation).
cat > "$TMP_APT_SCRATCH/gh" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$(dirname "$0")/args"
case "$*" in
  *"api user"*)
    case "${GH_MODE:-}" in
      idfail)  echo "gh: authentication failed" >&2; exit 1 ;;
      idempty) printf '' ;;
      *)       printf '%s' "${WANT:-localdev}" ;;
    esac ;;
  *"issues/"*"/assignees"*)
    case "${GH_MODE:-}" in
      apifail)     echo "HTTP 500: server error" >&2; exit 1 ;;
      omit)        echo '{"number":42,"assignees":[{"login":"someoneelse"}]}' ;;
      noassignees) echo '{"number":42}' ;;
      wrongtype)   echo '{"number":42,"assignees":"nope"}' ;;
      arrayroot)   echo '[1,2,3]' ;;
      scalarroot)  echo '"a string"' ;;
      falsyroot)   echo 'false' ;;
      already)     echo '{"number":42,"assignees":[{"login":"otheruser"},{"login":"'"${WANT:-localdev}"'"}]}' ;;
      *)           echo '{"number":42,"assignees":[{"login":"'"${WANT:-localdev}"'"}]}' ;;
    esac ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$TMP_APT_SCRATCH/gh"
APT="$LIB/../scripts/apply-pr-triggerer.sh"
# Helper: run the script capturing stdout token + exit code into APT_OUT / APT_RC.
apt_run() { APT_OUT="$(env DEVFLOW_GH="$TMP_APT_SCRATCH/gh" "$@" bash "$APT" "${APT_PR:-42}" 2>/dev/null)"; APT_RC=$?; }

# 1) local lookup success → applied <login>, exit 0
: > "$TMP_APT_SCRATCH/args"; APT_PR=42 apt_run GITHUB_RUN_ID= WANT=localdev
assert_eq "apply-pr-triggerer: local lookup success → applied" "assignment: applied localdev" "$APT_OUT"
assert_eq "apply-pr-triggerer: local success exits 0" "0" "$APT_RC"
assert_eq "apply-pr-triggerer: local success POSTs to REST issues/{n}/assignees" "yes" \
  "$(grep -qF -- 'api --method POST repos/{owner}/{repo}/issues/42/assignees' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"
assert_eq "apply-pr-triggerer: login rides as an assignees[] field" "yes" \
  "$(grep -qF -- 'assignees[]=localdev' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"
assert_eq "apply-pr-triggerer: never uses gh pr edit --add-assignee porcelain" "yes" \
  "$(! grep -qE 'pr edit|add-assignee' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"

# 2) cloud sender success → applied (reads DEVFLOW_TRIGGERING_USER, no `api user`)
: > "$TMP_APT_SCRATCH/args"; APT_PR=42 apt_run GITHUB_RUN_ID=99 DEVFLOW_TRIGGERING_USER=cloudy WANT=cloudy
assert_eq "apply-pr-triggerer: cloud sender success → applied" "assignment: applied cloudy" "$APT_OUT"
assert_eq "apply-pr-triggerer: cloud tier does NOT call 'gh api user'" "yes" \
  "$(! grep -qF -- 'api user' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"
# The cloud path is the security-sensitive one: assert the propagated DEVFLOW_TRIGGERING_USER
# actually reaches the POST as assignees[]=<login>, so a propagation→POST wiring regression
# is caught (the stub echoes WANT regardless of argv, so the applied token alone cannot).
assert_eq "apply-pr-triggerer: cloud POST carries the propagated login as assignees[]" "yes" \
  "$(grep -qF -- 'assignees[]=cloudy' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"

# 3) missing cloud sender → skipped no-triggering-user; no other account substituted
: > "$TMP_APT_SCRATCH/args"; APT_PR=42 apt_run GITHUB_RUN_ID=99 DEVFLOW_TRIGGERING_USER= GITHUB_ACTOR=tokenowner
assert_eq "apply-pr-triggerer: missing cloud sender → skipped no-triggering-user" "assignment: skipped no-triggering-user" "$APT_OUT"
assert_eq "apply-pr-triggerer: cloud skew makes NO assignment POST (no account substituted)" "yes" \
  "$(! grep -qF -- 'assignees' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"
assert_eq "apply-pr-triggerer: cloud skew never substitutes GITHUB_ACTOR" "yes" \
  "$(! grep -qF -- 'tokenowner' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"

# 3b) cloud sender entirely unset (older workflow) → same skew-safe skip.
# DEVFLOW_TRIGGERING_USER is cleared explicitly (like case 3 above) rather than
# left to ambient env: a live cloud run exports it (the triggering user), so an
# inherited value would leak in and make the helper APPLY instead of skip — a
# test-isolation leak, not a helper regression.
APT_PR=42 apt_run GITHUB_RUN_ID=99 DEVFLOW_TRIGGERING_USER=
assert_eq "apply-pr-triggerer: unset cloud sender (old workflow) → skipped no-triggering-user" "assignment: skipped no-triggering-user" "$APT_OUT"

# 4) local lookup failure → skipped identity-lookup-failed
APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE=idfail
assert_eq "apply-pr-triggerer: local lookup failure → skipped identity-lookup-failed" "assignment: skipped identity-lookup-failed" "$APT_OUT"

# 5) empty local lookup → skipped empty-identity
APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE=idempty
assert_eq "apply-pr-triggerer: empty local identity → skipped empty-identity" "assignment: skipped empty-identity" "$APT_OUT"

# 6) invalid PR number (non-numeric AND missing) → skipped invalid-input, NO GitHub call
: > "$TMP_APT_SCRATCH/args"; APT_PR=abc apt_run GITHUB_RUN_ID=
assert_eq "apply-pr-triggerer: non-numeric PR number → skipped invalid-input" "assignment: skipped invalid-input" "$APT_OUT"
assert_eq "apply-pr-triggerer: invalid input makes NO GitHub call at all" "yes" \
  "$([ ! -s "$TMP_APT_SCRATCH/args" ] && echo yes || echo no)"
APT_MISS="$(env DEVFLOW_GH="$TMP_APT_SCRATCH/gh" GITHUB_RUN_ID= bash "$APT" 2>/dev/null)"
assert_eq "apply-pr-triggerer: missing PR number → skipped invalid-input" "assignment: skipped invalid-input" "$APT_MISS"
APT_EMPTY="$(env DEVFLOW_GH="$TMP_APT_SCRATCH/gh" GITHUB_RUN_ID= bash "$APT" '' 2>/dev/null)"
assert_eq "apply-pr-triggerer: empty PR number → skipped invalid-input" "assignment: skipped invalid-input" "$APT_EMPTY"

# 7) API failure → skipped api-failure (PR preserved)
APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE=apifail
assert_eq "apply-pr-triggerer: add-assignee API failure → skipped api-failure" "assignment: skipped api-failure" "$APT_OUT"
assert_eq "apply-pr-triggerer: API failure still exits 0 (best-effort)" "0" "$APT_RC"

# 8) documented response object containing the requested login → applied
APT_PR=42 apt_run GITHUB_RUN_ID= WANT=localdev
assert_eq "apply-pr-triggerer: response object with the login → applied" "assignment: applied localdev" "$APT_OUT"

# 9) documented response object omitting the requested login → skipped unconfirmed
APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE=omit
assert_eq "apply-pr-triggerer: response omits the login → skipped unconfirmed" "assignment: skipped unconfirmed" "$APT_OUT"

# 10–14) adversarial response shapes all route to unconfirmed, never a false applied
for _m in noassignees wrongtype arrayroot scalarroot falsyroot; do
  APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE="$_m"
  assert_eq "apply-pr-triggerer: response shape '$_m' → skipped unconfirmed (never a false applied)" "assignment: skipped unconfirmed" "$APT_OUT"
  assert_eq "apply-pr-triggerer: response shape '$_m' exits 0" "0" "$APT_RC"
done

# 15) idempotency: already-assigned response containing the login → applied (does not remove others)
: > "$TMP_APT_SCRATCH/args"; APT_PR=42 apt_run GITHUB_RUN_ID= GH_MODE=already WANT=localdev
assert_eq "apply-pr-triggerer: already-assigned response with the login → applied (idempotent)" "assignment: applied localdev" "$APT_OUT"
assert_eq "apply-pr-triggerer: idempotent add uses POST add-assignees (never DELETE/PUT that would remove others)" "yes" \
  "$(grep -qF -- '--method POST' "$TMP_APT_SCRATCH/args" && ! grep -qE -- '--method (DELETE|PUT)' "$TMP_APT_SCRATCH/args" && echo yes || echo no)"

# 16) silent refusal is the ONLY empty-stdout outcome — every handled path prints a token
assert_eq "apply-pr-triggerer: every handled path prints a non-empty outcome token (silent = refusal only)" "yes" \
  "$([ -n "$APT_OUT" ] && echo yes || echo no)"
rm -rf "$TMP_APT_SCRATCH"

# ── Phase 3.1.1 integration: the emitted helper invocation ──────────────────────
# ONE pin here, and it is the emitted command fence — the shape the agent harness
# actually executes as a leading token. The two companion pins that used to sit
# below it (over the "CREATE arm ONLY" heading and the "reflection-kind
# dropped-failed" routing sentence) were retired: both literals resolve into
# agent-executed prompt PROSE that no tool reads, which is the class issues
# #375/#666/#810 prohibit and the #843/#876 recorded decision leaves uncovered by
# design. Their compensating control is the review pass that reads the prose, not a
# wording pin — do not re-add them. The behaviour they gestured at is covered where
# a program can see it: the helper's own closed outcome-token matrix above, and
# workpad.py's `--reflection-kind dropped-failed` rendering in
# lib/test/test_python_scripts.py.
P3_ASSIGN="$LIB/../skills/implement/phases/phase-3-review.md"
assert_eq "phase-3 #1165: CREATE arm invokes apply-pr-triggerer.sh as a leading-token helper" "yes" \
  "$(grep -qF 'scripts/apply-pr-triggerer.sh <draft-pr-number>' "$P3_ASSIGN" && echo yes || echo no)"  # structural-pin-ok: routing-dispatch-contract -- the leading-token helper invocation is a dispatch instruction the agent harness executes

# ── #1165 grants: propagation env + all three leading-token grant forms ──────────
IMPL_WF="$LIB/../.github/workflows/devflow-implement.yml"
PROBE_WF="$LIB/../.github/workflows/matcher-probe.yml"
PROFILES="$LIB/../lib/capability-profiles.json"
assert_eq "#1165: devflow-implement.yml propagates DEVFLOW_TRIGGERING_USER from github.event.sender.login" "yes" \
  "$(grep -qF 'DEVFLOW_TRIGGERING_USER: ${{ github.event.sender.login }}' "$IMPL_WF" && echo yes || echo no)"  # structural-pin-ok: security-credential-boundary -- the propagated triggering-user identity is the trust boundary the helper reads fail-closed
assert_eq "#1165: implement profile grants the vendored apply-pr-triggerer.sh leading token" "yes" \
  "$(grep -qF 'Bash(.prflow/vendor/prflow/scripts/apply-pr-triggerer.sh:*)' "$PROFILES" && echo yes || echo no)"  # structural-pin-ok: security-credential-boundary -- the capability manifest grant is an executable allowlist trust boundary
assert_eq "#1165: baked implement allowlist grants the vendored apply-pr-triggerer.sh leading token" "yes" \
  "$(grep -qF 'Bash(.prflow/vendor/prflow/scripts/apply-pr-triggerer.sh:*)' "$IMPL_WF" && echo yes || echo no)"  # structural-pin-ok: security-credential-boundary -- the baked workflow allowlist is the executable cloud grant trust boundary
assert_eq "#1165: matcher-probe grants the repo-root self-repo apply-pr-triggerer.sh form" "yes" \
  "$(grep -qF 'Bash(scripts/apply-pr-triggerer.sh:*)' "$PROBE_WF" && echo yes || echo no)"  # structural-pin-ok: security-credential-boundary -- the probe/self-repo allowlist is an executable grant trust boundary
assert_eq "#1165: matcher-probe grants the absolute self-repo apply-pr-triggerer.sh form" "yes" \
  "$(grep -qF 'Bash(${{ github.workspace }}/scripts/apply-pr-triggerer.sh:*)' "$PROBE_WF" && echo yes || echo no)"  # structural-pin-ok: security-credential-boundary -- the workspace-absolute grant is the trust boundary for GitHub-hosted self-repo runs

