assert_pin_unique "#275 pin (P3-live): the gated §4.0.5 reference carries a live file-deferrals.py invocation via the portable anchor" \
  "$PORTABLE_ANCHOR_LITERAL"'scripts/file-deferrals.py' "$LIB/../skills/implement/references/deferred-review-findings.md"  # structural-pin-ok: helper-contract -- the filing helper's invocation must resolve through the portable anchor; a bare or absolute spelling is refused on every runner this anchor exists for
# RETIRED by #1759: #275 pin (P4-ci) "create-issue preamble carries the never-capture operative sentence". Disposition: docs/internal/pin-corpus-issue-1759-sweep.md
# ────────────────────────────────────────────────────────────────────────────
echo "#332: resolve-main-root.sh (main-worktree root) + create-issue draft-path"
# ────────────────────────────────────────────────────────────────────────────
# The resolver prints the MAIN working-tree root so create-issue's draft path is
# correct inside a linked (Claude) worktree. Best-effort: always exit 0, pwd
# fallback + stderr breadcrumb when git can't answer. Tests use REAL throwaway
# git repos + real `git worktree add` (the boundary being proven is git's own
# worktree topology — not mocked). RED before the resolver existed (no file to run).
RMR="$LIB/../scripts/resolve-main-root.sh"
# Build a real main tree + a linked worktree under one sandbox parent.
RMR_PARENT="$(git_sandbox "#332 resolver sandbox")"
RMR_MAIN="$RMR_PARENT/main"; RMR_WT="$RMR_PARENT/wt"
mkdir -p "$RMR_MAIN"
git -C "$RMR_MAIN" init -q
git -C "$RMR_MAIN" config user.email t@example.com; git -C "$RMR_MAIN" config user.name t
printf 'x\n' > "$RMR_MAIN/f"
git -C "$RMR_MAIN" add -A; git -C "$RMR_MAIN" -c user.email=t@t -c user.name=t commit -qm init
git -C "$RMR_MAIN" worktree add -q -b rmr-feat "$RMR_WT" >/dev/null 2>&1
# Guard: the worktree must exist, else the from-worktree run would fall back to cwd
# and the AC2 assertions would be meaningless (a false GREEN).
assert_eq "#332 setup: linked worktree was created" "yes" \
  "$([ -d "$RMR_WT" ] && echo yes || echo no)"
RMR_FROM_MAIN="$(cd "$RMR_MAIN" && bash "$RMR" 2>/dev/null)"
RMR_FROM_WT="$(cd "$RMR_WT" && bash "$RMR" 2>/dev/null)"
# AC2: from inside the worktree the resolver prints the MAIN root (== the main-tree
# result), NOT the worktree path. Comparing the two runs sidesteps macOS /tmp
# symlink canonicalization (both runs canonicalize identically).
assert_eq "#332 AC2: resolver from a linked worktree prints the MAIN root (== main-tree result)" \
  "$RMR_FROM_MAIN" "$RMR_FROM_WT"
assert_eq "#332 AC2: resolver from a worktree does NOT print the worktree path" "yes" \
  "$([ -n "$RMR_FROM_WT" ] && [ "$RMR_FROM_WT" != "$RMR_WT" ] && echo yes || echo no)"
# AC3: from the main tree the resolver prints a non-empty existing dir (no regression).
assert_eq "#332 AC3: resolver from the main tree prints a non-empty existing dir" "yes" \
  "$([ -n "$RMR_FROM_MAIN" ] && [ -d "$RMR_FROM_MAIN" ] && echo yes || echo no)"
# AC3 (discriminating): run from a SUBDIRECTORY of the main tree — the resolver must return
# the enclosing main root, NOT the cwd. `git worktree list --porcelain` reports an absolute
# root independent of cwd, so this is the case that proves the resolver isn't just printing
# `pwd` on the normal-checkout path (an always-pwd regression passes the AC3 above — where
# pwd==root — but fails here where the subdir≠root). Compare against RMR_FROM_MAIN (same
# canonicalization) rather than a hardcoded path, matching the AC2 rationale.
mkdir -p "$RMR_MAIN/sub/dir"
RMR_FROM_SUBDIR="$(cd "$RMR_MAIN/sub/dir" && bash "$RMR" 2>/dev/null)"
assert_eq "#332 AC3: resolver from a main-tree subdirectory prints the main root (== main-tree result), not the cwd" \
  "$RMR_FROM_MAIN" "$RMR_FROM_SUBDIR"
assert_eq "#332 AC3: resolver from a subdirectory does NOT print the subdirectory (cwd) path" "yes" \
  "$([ -n "$RMR_FROM_SUBDIR" ] && [ "$RMR_FROM_SUBDIR" != "$RMR_MAIN/sub/dir" ] && echo yes || echo no)"

# issue #795 — the resolver's porcelain parse under a PATH holding ONLY git and bash.
#
# WHY A NEW FIXTURE, and why it could not be an assertion added to
# `cli_roundtrip_restricted_path`: that fixture `cd`s into the sandbox it then `git init`s,
# so its cwd IS the main root and a resolver that had silently regressed to its `pwd`
# fallback would print the identical answer. The assertion would pass vacuously. This
# fixture reuses the LINKED WORKTREE built above, where the two answers differ by
# construction — `pwd` is the worktree, the correct answer is the main root — so the
# restricted-PATH run is only green if the parse actually ran.
#
# `bash` is in the restricted bin because the run below invokes the helper through an
# explicit `bash` head, which PATH must still resolve. The pre-change
# `head`/`sed`/`grep` pipeline emitted `command not found` here and fell through to `pwd`;
# a value that decides the bound draft root must not be derived through a tool
# `lib/preflight.sh` does not guarantee.
RMR_RB="$RMR_MAIN/restricted-bin"
mkdir -p "$RMR_RB"
ln -sf "$(command -v git)" "$RMR_RB/git"
ln -sf "$(command -v bash)" "$RMR_RB/bash"
# Guard: both symlinks must resolve, else a PATH that resolves NOTHING would make the run
# below fail for the wrong reason and the assertions would grade a broken fixture.
assert_eq "#795 setup: the git+bash-only bin holds both runnable symlinks" "yes" \
  "$([ -x "$RMR_RB/git" ] && [ -x "$RMR_RB/bash" ] && echo yes || echo no)"
RMR_WT_RESTRICTED="$(cd "$RMR_WT" && PATH="$RMR_RB" bash "$RMR" 2>/dev/null)"
assert_eq "#795 AC: under a git+bash-only PATH the resolver still prints the MAIN root from a linked worktree" \
  "$RMR_FROM_MAIN" "$RMR_WT_RESTRICTED"
# The discriminating half: the pre-change pipeline printed the WORKTREE path here.
assert_eq "#795 AC: ... and it is not the worktree path the pwd fallback would have printed" "yes" \
  "$([ -n "$RMR_WT_RESTRICTED" ] && [ "$RMR_WT_RESTRICTED" != "$RMR_WT" ] && echo yes || echo no)"
# Behaviour-preservation under the SAME restricted PATH, over the fallback arms exercised
# below: the breadcrumb is byte-identical and the exit stays 0, so the hardening changed the
# derivation and nothing else.
RMR_NG_R="$(git_sandbox "#795 resolver non-git sandbox, restricted PATH")"
RMR_NG_R_ERR="$(cd "$RMR_NG_R" && PATH="$RMR_RB" bash "$RMR" 2>&1 >/dev/null)"
assert_eq "#795 AC: the non-git fallback breadcrumb is unchanged under a git+bash-only PATH" "1" \
  "$(printf '%s' "$RMR_NG_R_ERR" | grep -cF 'devflow: resolve-main-root: could not determine the main working-tree root')"
RMR_WT_RC=0
( cd "$RMR_WT" && PATH="$RMR_RB" bash "$RMR" >/dev/null 2>&1 ) || RMR_WT_RC=$?
assert_eq "#795 AC: the resolver still exits 0 under a git+bash-only PATH" "0" "$RMR_WT_RC"

# issue #795 — the two lifecycle-contract reconciliations and the derived measurement
# figure. NEITHER is a grep for a sentence: the helper compares the docstring's read-back
# enumeration against the set the module's emission machinery actually dispatches on (whose
# membership it checks against the parser's registered choices), and compares the ordered
# call sequence against the invocations the helper accepts. Both refuse — RED with a named
# breadcrumb — on no candidate section, more than one candidate, or zero invocations
# extracted, so a rewrap or a duplicated heading can never make them pass vacuously and
# freeze the figure below.
ALC_795="$(python3 "$LIB/test/check-audit-lifecycle-contracts.py" 2>&1)"
ALC_795_RC=$?
assert_eq "#795: the audit-lifecycle contract reconciliations hold" "0" "$ALC_795_RC"
if [ "$ALC_795_RC" -ne 0 ]; then
  printf '  %s\n' "$ALC_795"
fi
# The measurement figure is DERIVED from the shipped prose by the helper above, never
# hand-transcribed here, and BOTH counts are printed on the SUCCESS path so a passing run
# carries the evidence rather than only a failure message. The assertion is that the figure
# was established at all — a later addition of an unconditional call MOVES it, which is
# visible in this printed line rather than silently drifting from a frozen literal.
ALC_795_CALLS="$(printf '%s\n' "$ALC_795" | sed -n 's/^unconditional_call_count=//p')"
ALC_795_SUBS="$(printf '%s\n' "$ALC_795" | sed -n 's/^registered_subcommand_count=//p')"
assert_eq "#795: the per-round unconditional state-owner call count was established" "1" \
  "$(printf '%s' "$ALC_795_CALLS" | grep -c '^[0-9][0-9]*$')"
assert_eq "#795: the registered subcommand count was established" "1" \
  "$(printf '%s' "$ALC_795_SUBS" | grep -c '^[0-9][0-9]*$')"
# PIN the derived figure, do not merely print it. The AC requires that an addition raising
# the count "turns the suite RED"; a shape-only check (is it a number?) plus a MEASURE line
# is not that — the count could drift with the suite green, and the round-trip metric this
# change exists to reduce would regress unnoticed. This is CLAUDE.md's "enforcement constant"
# exception to prefer-generated-evidence: the literal IS the gate, so it is pinned rather than
# rendered. Moving the sequence legitimately? Update this ONE number in the same commit — that
# is the review prompt this pin exists to force. The assertion label reads the same variable,
# so the printed name can never report a figure the assertion is not enforcing.
# Issue #1466 raised it from 18 as a CORRECTION rather than a regression; the rationale is in
# docs/internal/cutovers/issue-795-audit-state-round-trips.md's Measurement section.
# Issue #1751 lowered it to 13: every fresh-context audit round is now user-elected, so the
# normal clean run elects nothing and the whole round-conducting set moved to _CONDITIONAL,
# while record-override (a declined run always records the user-decline) moved into the
# unconditional sequence.
# Issue #1803 lowered it to 12: every mutation/query now prints a summary-block line carrying
# the compact query-summary subset, so the clean-path standalone query-summary read at Step 4
# sub-step 3 is dropped (its answer is read from the preceding call's block).
ALC_795_EXPECT=12
assert_eq "#795: the per-round unconditional state-owner call count is $ALC_795_EXPECT" \
  "$ALC_795_EXPECT" "$ALC_795_CALLS"
printf '  MEASURE  #795 create-issue Step 3.6: unconditional_call_count=%s registered_subcommand_count=%s\n' \
  "$ALC_795_CALLS" "$ALC_795_SUBS"

# issue #795 — the dispatch-pointer fold, asserted at the generator's executable boundary.
# This is the behavioral re-anchor for the two retired #768 prose pins: they asserted that
# the pointer was extracted with python3 and returned byte-identically to the line inside
# the written file, over a read-back fence this change removed. The property they stood for
# is now the generator's own contract, and it is exercised here rather than described.
RAP_SB="$(git_sandbox '#795 dispatch-pointer stderr fold')"
if [ -d "$RAP_SB" ]; then
  printf '# Draft title\n\nBody.\n' > "$RAP_SB/d.md"
  python3 "$LIB/../scripts/render-audit-prompt.py" dispatch-instructions --slug fold \
    --draft-path "$RAP_SB/d.md" --instructions-path "$RAP_SB/i.md" \
    > "$RAP_SB/out.txt" 2> "$RAP_SB/err.txt"
  RAP_RC=$?
  assert_eq "#795: dispatch-instructions still exits 0 with the pointer fold in place" "0" "$RAP_RC"
  # The pointer is selected by PREFIX, never positionally: the renderer resolves the
  # consumer-extension path unconditionally and can emit its own breadcrumb first.
  RAP_ERR_PTR="$(grep -m1 'dispatch-pointer:' "$RAP_SB/err.txt" 2>/dev/null)"
  RAP_OUT_PTR="$(grep -m1 'dispatch-pointer: Audit' "$RAP_SB/out.txt" 2>/dev/null)"
  # (Non-emptiness of the stderr pointer is not asserted separately here: the
  # exactly-one-line assertion below is strictly stronger and subsumes it.)
  assert_eq "#795: the stderr pointer is byte-identical to the line inside the stdout it wrote" \
    "$RAP_OUT_PTR" "$RAP_ERR_PTR"
  # Positive control: an empty extraction on BOTH sides would pass the compare vacuously.
  assert_eq "#795: ... and that pointer line is non-empty" "1" \
    "$(printf '%s' "$RAP_OUT_PTR" | grep -c .)"
  # Purity: exactly one pointer line on stderr, and the mode still reads no consumer
  # extension — its stdout carries the dispatch-instructions marker pair, not render-status:.
  assert_eq "#795: exactly one dispatch-pointer line reaches stderr" "1" \
    "$(grep -c 'dispatch-pointer:' "$RAP_SB/err.txt" 2>/dev/null)"
  assert_eq "#795: dispatch-instructions stdout keeps its own marker pair (no consumer-extension read)" "1" \
    "$(sed -n 1p "$RAP_SB/out.txt" 2>/dev/null | grep -c '^dispatch-instructions:')"
  rm -rf "$RAP_SB"
fi

# AC (always exit 0 / pwd fallback / breadcrumb): a non-git directory.
RMR_NG="$(git_sandbox "#332 resolver non-git sandbox")"
RMR_NG_OUT="$(cd "$RMR_NG" && bash "$RMR" 2>/dev/null)"
RMR_NG_ERR="$(cd "$RMR_NG" && bash "$RMR" 2>&1 >/dev/null)"
RMR_NG_RC=0; (cd "$RMR_NG" && bash "$RMR" >/dev/null 2>&1) || RMR_NG_RC=$?
assert_eq "#332 fallback: non-git dir → prints pwd" "$(cd "$RMR_NG" && pwd)" "$RMR_NG_OUT"
assert_eq "#332 fallback: non-git dir → exits 0" "0" "$RMR_NG_RC"
assert_eq "#332 fallback: non-git dir → specific (not generic) stderr breadcrumb" "yes" \
  "$(printf '%s' "$RMR_NG_ERR" | grep -q 'resolve-main-root' && echo yes || echo no)"  # raw-guard-ok: breadcrumb specificity probe on captured stderr, not a content pin

# AC (git unavailable): shadow `git` with a failing stub on PATH; even inside a real
# repo the resolver must fall back to pwd + breadcrumb, exit 0.
RMR_SHADOW="$(git_sandbox "#332 resolver git-shadow bin")"
printf '#!/bin/sh\nexit 127\n' > "$RMR_SHADOW/git"; chmod +x "$RMR_SHADOW/git"
RMR_GU_OUT="$(cd "$RMR_MAIN" && PATH="$RMR_SHADOW:$PATH" bash "$RMR" 2>/dev/null)"
RMR_GU_ERR="$(cd "$RMR_MAIN" && PATH="$RMR_SHADOW:$PATH" bash "$RMR" 2>&1 >/dev/null)"
RMR_GU_RC=0; (cd "$RMR_MAIN" && PATH="$RMR_SHADOW:$PATH" bash "$RMR" >/dev/null 2>&1) || RMR_GU_RC=$?
assert_eq "#332 fallback: git unavailable → prints pwd" "$(cd "$RMR_MAIN" && pwd)" "$RMR_GU_OUT"
assert_eq "#332 fallback: git unavailable → exits 0" "0" "$RMR_GU_RC"
assert_eq "#332 fallback: git unavailable → specific (not generic) stderr breadcrumb" "yes" \
  "$(printf '%s' "$RMR_GU_ERR" | grep -q 'resolve-main-root' && echo yes || echo no)"  # raw-guard-ok: breadcrumb specificity probe on captured stderr (uniform with the non-git case — a misdirected/generic breadcrumb on the git-unavailable path is the one most easily confused with an unrelated error)

# AC (bare main repo): git worktree list reports it `bare`; the resolver falls back to pwd.
RMR_BARE="$(git_sandbox "#332 resolver bare sandbox")"
git -C "$RMR_BARE" init --bare -q
RMR_BARE_OUT="$(cd "$RMR_BARE" && bash "$RMR" 2>/dev/null)"
RMR_BARE_ERR="$(cd "$RMR_BARE" && bash "$RMR" 2>&1 >/dev/null)"
RMR_BARE_RC=0; (cd "$RMR_BARE" && bash "$RMR" >/dev/null 2>&1) || RMR_BARE_RC=$?
assert_eq "#332 fallback: bare main repo → prints pwd (not the bare git dir as a worktree)" \
  "$(cd "$RMR_BARE" && pwd)" "$RMR_BARE_OUT"
assert_eq "#332 fallback: bare main repo → exits 0" "0" "$RMR_BARE_RC"
# The bare case is the one fallback where git SUCCEEDS (returns a `bare` record the resolver
# deliberately rejects) — so it is the path most at risk of falling back without a breadcrumb
# if the `bare` detection and the breadcrumb emission ever drift apart. Assert the specific
# breadcrumb fired, mirroring the git-failure fallbacks.
assert_eq "#332 fallback: bare main repo → specific (not generic) stderr breadcrumb" "yes" \
  "$(printf '%s' "$RMR_BARE_ERR" | grep -q 'resolve-main-root' && echo yes || echo no)"  # raw-guard-ok: breadcrumb specificity probe on captured stderr

# AC (resolved root no longer exists on disk): git SUCCEEDS and reports a worktree path in
# `--porcelain`, but that path is gone from disk (e.g. inside a linked worktree whose main
# tree was removed). The `[ -d "$main_root" ]` arm must reject the stale path and fall back
# to pwd + breadcrumb — otherwise the resolver prints a nonexistent path the user cannot
# open, the exact failure this helper exists to prevent. A git stub emitting a bogus
# porcelain record exercises this branch precisely; without it every fallback test drives
# `main_root` EMPTY (gated by `[ -n ]` alone), so deleting `&& [ -d "$main_root" ]` would
# leave the suite GREEN.
RMR_STALE="$(git_sandbox "#332 resolver stale-root bin")"
printf '#!/bin/sh\nprintf "worktree /nonexistent/devflow-main-gone\\n"\n' > "$RMR_STALE/git"; chmod +x "$RMR_STALE/git"
RMR_STALE_OUT="$(cd "$RMR_MAIN" && PATH="$RMR_STALE:$PATH" bash "$RMR" 2>/dev/null)"
RMR_STALE_ERR="$(cd "$RMR_MAIN" && PATH="$RMR_STALE:$PATH" bash "$RMR" 2>&1 >/dev/null)"
RMR_STALE_RC=0; (cd "$RMR_MAIN" && PATH="$RMR_STALE:$PATH" bash "$RMR" >/dev/null 2>&1) || RMR_STALE_RC=$?
assert_eq "#332 fallback: resolved root gone from disk → prints pwd (not the stale porcelain path)" \
  "$(cd "$RMR_MAIN" && pwd)" "$RMR_STALE_OUT"
assert_eq "#332 fallback: resolved root gone from disk → does NOT print the stale nonexistent path" "yes" \
  "$([ "$RMR_STALE_OUT" != "/nonexistent/devflow-main-gone" ] && echo yes || echo no)"
assert_eq "#332 fallback: resolved root gone from disk → exits 0" "0" "$RMR_STALE_RC"
assert_eq "#332 fallback: resolved root gone from disk → specific (not generic) stderr breadcrumb" "yes" \
  "$(printf '%s' "$RMR_STALE_ERR" | grep -q 'resolve-main-root' && echo yes || echo no)"  # raw-guard-ok: breadcrumb specificity probe on captured stderr

# create-issue SKILL.md contract pins (coupled with the SKILL.md edit — reconciled in the
# same change per the AC). The draft is written at the resolved main root and displayed at
# the BOUND-root absolute path (issue #569: the display reads the root back from
# query-draft-binding's `bound=` field); no bare-relative displayed draft-save note remains.
CI_SKILL_332="$CREATE_ISSUE_BUNDLE"   # #614: content-survival target — the split bundle, not the root alone
assert_pin_unique "#332 AC4: create-issue resolves the main root via resolve-main-root.sh (portable anchor)" \
  'MAIN_ROOT="$('"$PORTABLE_ANCHOR_LITERAL"'scripts/resolve-main-root.sh)"' "$CI_SKILL_332"
# #569: the record-draft-binding statement is a SEPARATE bash fence, so it cannot read the
# fence-local $MAIN_ROOT — it re-resolves the deterministic root inline (anchor expanded inline,
# never captured). That is why the binding site has its own resolve-main-root.sh invocation,
# pinned here distinctly from the write site's MAIN_ROOT= form above. (Count-free by design: a
# comment asserting how many call sites exist rots on the next SKILL.md edit — PR #553.)
assert_pin_unique "#332/#569 AC4: the record-draft-binding --path re-resolves the root inline (self-contained fence)" \
  '--path "$('"$PORTABLE_ANCHOR_LITERAL"'scripts/resolve-main-root.sh)" --tier main-root' "$CI_SKILL_332"
assert_pin_unique "#332/#569 AC4: create-issue displays the draft at the bound-root ABSOLUTE path" \
  'Draft also saved to `<bound-root>/.prflow/tmp/issue-draft-<slug>.md` for review.' "$CI_SKILL_332"
assert_eq "#332 AC4: create-issue no longer shows a bare-relative draft-save note" "no" \
  "$(grep -qF 'Draft also saved to `.prflow/tmp/issue-draft-<slug>.md` for review.' "$CI_SKILL_332" && echo yes || echo no)"  # raw-guard-ok: absence pin (expects no) — the old cwd-relative displayed draft note must be gone
# The Step 2 derivation gate artifact deliberately STAYS cwd-anchored (internal, not shown
# to the user) — assert it was not accidentally moved to the main root.
assert_eq "#332 gotcha: Step 2 derivation artifact stays cwd-relative (not main-root)" "no" \
  "$(grep -qF '<main-root>/.prflow/tmp/issue-derivation' "$CI_SKILL_332" && echo yes || echo no)"  # raw-guard-ok: absence pin (expects no) — the internal derivation artifact must not move to the main root
# Behavioral proof — the static pins above are all greps; nothing executed the canonical
# literal itself. Run the EXACT PORTABLE_ANCHOR_LITERAL (with CLAUDE_SKILL_DIR set to a
# real skill dir, as on Claude Code) as a command head and assert the resolved helper is
# actually reached — catching a quoting/expansion defect in the literal (a moved quote, a
# glob-active placeholder char) that would break all 22 files in lockstep while every
# static pin stayed GREEN. The repo tracks only docs.md.example (no live docs.md), so the
# helper takes its whole-file no-op arm; since issue #1299 that arm emits a
# `PROMPT-EXTENSION-STATUS: present-empty` line, which is the positive reached-the-helper observable.
PA_BEHAV_CMD="$PORTABLE_ANCHOR_LITERAL"'scripts/load-prompt-extension.sh docs'
PA_BEHAV_OUT="$(cd "$LIB/.." && CLAUDE_SKILL_DIR="$PWD/skills/docs" bash -c "$PA_BEHAV_CMD" 2>&1)"; PA_BEHAV_RC=$?
assert_eq "#275 behavioral: the no-extension helper run reaches the helper (present-empty token, clean no-op)" "yes" \
  "$(case "$PA_BEHAV_OUT" in *'PROMPT-EXTENSION-STATUS: present-empty'*) echo yes ;; *) echo no ;; esac)"
assert_eq "#275 behavioral: the canonical anchor literal executes and reaches the helper (CLAUDE_SKILL_DIR set)" "0" "$PA_BEHAV_RC"
# And with the var EMPTY the same literal must fail (the placeholder is not a real path) —
# proving the fallback text is inert as a path, not accidentally resolvable.
PA_BEHAV_EMPTY_RC=0
(cd "$LIB/.." && CLAUDE_SKILL_DIR='' bash -c "$PA_BEHAV_CMD" >/dev/null 2>&1) || PA_BEHAV_EMPTY_RC=$?
assert_eq "#275 behavioral: the unsubstituted placeholder does NOT resolve (empty var -> non-zero)" "yes" \
  "$([ "$PA_BEHAV_EMPTY_RC" -ne 0 ] && echo yes || echo no)"  # raw-guard-ok: behavioral rc check, not a content pin
# Doc presence pins (#275 AC: the four Windows/Copilot-CLI operator gotchas are documented).
# DEVFLOW_GH's shim remedy predates #275 and its pin lives with the #245 block; what remains
# pinned here is the install.md side of the gotchas #275 added.
assert_eq "#275 docs: install.md documents the PowerShell UTF-16LE write pitfall + no-BOM remedy" "yes" \
  "$(grep -q 'UTF-16LE' "$LIB/../docs/internal/install.md" && grep -q 'utf8NoBOM' "$LIB/../docs/internal/install.md" && echo yes || echo no)"  # raw-guard-ok: compound doc presence pin (two coupled fragments of one gotcha)
assert_pin_unique "#275 docs: install.md documents the inline-bash variable-stripping constraint" \
  "reads **empty** in a later statement of the same command" "$LIB/../docs/internal/install.md"  # structural-pin-ok: cross-file-phase-contract -- boundary-adjudicated (literal:1316523, runner_scope_contract): install.md forbids the assign-then-use command shape that erases helper-path variables on the supported runner; the docs/internal move (issue #1188) re-scoped this site into the #810 diff, so the recorded boundary now needs the co-located site tag
assert_eq "#97 pin: implement applies DevFlow label at PR create via REST helper" "yes" \
  "$(grep -q 'ensure-label.sh PRFlow' "$IMPL_SKILL_BUNDLE" && grep -qF 'apply-labels.sh <draft-pr-number> PRFlow' "$IMPL_SKILL_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: compound: two greps && on one line (provenance: ensure-label + REST apply-labels); issue #218: bundle (label idiom in phases/phase-3-review.md). #480: the PR number is a substituted LITERAL, not "$PR_NUM" — that variable is set in a previous fence and does not survive into this separate command on the cloud runner, so the old form passed an empty number and the helper refused at its arg-slip guard (the label never landed on the PR).
assert_eq "#152 pin: meta-issue.sh ensures+applies DevFlow and Retrospective labels via REST helper" "yes" \
  "$(grep -q 'ensure-label.sh' "$LIB/meta-issue.sh" && grep -qF 'apply-labels.sh' "$LIB/meta-issue.sh" && grep -qF 'PRFlow Retrospective' "$LIB/meta-issue.sh" && echo yes || echo no)"
assert_eq "#97 pin: init creates the reserved DevFlow provenance label" "yes" \
  "$(grep -q 'ensure-label.sh PRFlow' "$LIB/../skills/init/SKILL.md" && grep -qi 'provenance' "$LIB/../skills/init/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: compound: two greps && on one line (provenance: ensure-label + provenance)
# ── #228: REST migration — no org-scoped GraphQL porcelain on any migrated path ──
# The removed invocation LITERALS (command + their args) must be gone. These exact
# forms never appear in the now-present contrastive prose (which references the bare
