assert_eq "#228: meta-issue.sh no longer invokes 'gh issue edit' for labels" "yes" \
  "$(! grep -qF '"$DEVFLOW_GH" issue edit' "$LIB/meta-issue.sh" && echo yes || echo no)"
assert_eq "#228: create-issue removed the gh issue edit --add-label command" "yes" \
  "$(! grep -qF 'gh issue edit <issue_number> --add-label DevFlow' "$CREATE_ISSUE_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: absence pin — asserts the removed porcelain command literal is GONE (negated grep, not a presence pin)
assert_eq "#228: phase-3 removed the gh pr edit --add-label command" "yes" \
  "$(! grep -qF 'gh pr edit "$PR_NUM" --add-label DevFlow' "$IMPL_SKILL_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: absence pin — asserts the removed porcelain command literal is GONE (negated grep, not a presence pin)
assert_eq "#228: phase-4 removed the gh issue edit --add-label deferred command" "yes" \
  "$(! grep -qF 'gh issue edit "$n" --add-label "$CLEAN_DEFERRED_LABELS"' "$IMPL_SKILL_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: absence pin — asserts the removed porcelain command literal is GONE (negated grep, not a presence pin)
assert_eq "#228: phase-4 removed the gh pr edit --add-label docs-label command" "yes" \
  "$(! grep -qF 'gh pr edit --add-label "$CLEAN_LABELS"' "$IMPL_SKILL_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: absence pin — asserts the removed porcelain command literal is GONE (negated grep, not a presence pin)
assert_eq "#228: phase-4 docs-label routes through apply-labels.sh (symmetric presence pin)" "yes" \
  "$(grep -qF 'apply-labels.sh <docs-pr-number> "<docs-labels>"' "$IMPL_SKILL_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: presence pin pairs with the docs-label absence pin above so a typo'd new invocation can't pass all phase-4 pins. #480: the PR number and label list are substituted LITERALS, not "$DOCS_PR_NUM"/"$CLEAN_LABELS" — the reworked 4.1 emits a single leading-token call (the old form nested it inside two `if` compounds, a shape no probe row measured).
assert_eq "#228: pr-description edits the body via REST gh api PATCH, not gh pr edit --body" "yes" \
  "$(grep -qF 'api --method PATCH' "$LIB/../skills/pr-description/SKILL.md" && ! grep -qF 'gh pr edit $PR_NUMBER --body' "$LIB/../skills/pr-description/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: compound presence+absence pin (REST PATCH present AND old porcelain gone), not a single target-unique pin
# Positively pin the migrated body-write SHAPE: `-F body=@-` reads the field literally
# from stdin (the heredoc), the form that replaced `--body-file`'s no-expansion guarantee.
# Distinguishable from the contrastive prose (which says bare `gh pr edit --body`), so this
# is the real tripwire a porcelain reintroduction would have to defeat.
assert_eq "#228: pr-description body PATCH uses the literal -F body=@- stdin form" "yes" \
  "$(grep -qF -- '-F body=@-' "$LIB/../skills/pr-description/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: presence pin on the migrated literal-read body-write form
assert_eq "#97 pin: retrospective Stage A consumes reflections" "yes" \
  "$(grep -qi 'reflection' "$LIB/../skills/retrospective/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: case-insensitive (grep -qi); pin_count is case-sensitive -F
assert_eq "#97 pin: cheap-gate carries the reflection reason string" "yes" \
  "$(grep -q 'friction reflections present' "$LIB/cheap-gate.jq" && echo yes || echo no)"
assert_eq "#97 pin: config.example.json docs.labels reverted to Documented" "Documented" \
  "$(jq -r '.docs.labels' "$LIB/../.prflow/config.example.json")"

# ── #152: propose-not-dispose contract pins (grep) ───────────────────────────
# Stage B (retrospective-audit) is a pure spec generator (zero worktrees, zero edits,
# no two-form excluded/targets contract) that since issue #893 returns a ranked
# `findings` array of one-to-three sub-patterns rather than a single {title, body}.
RA_SKILL="$LIB/../skills/retrospective-audit/SKILL.md"
assert_eq "#893: Stage B emits the findings-array contract (subslug per finding)" "yes" \
  "$(grep -qF 'subslug' "$RA_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'subslug' appears several times in retrospective-audit SKILL  # structural-pin-ok: cross-file-phase-contract -- `subslug` is the machine-consumed field name of Stage B's returned findings[] objects that lib/select-findings.sh parses; the two sides must name it identically
assert_eq "#152: Stage B runs no git worktree" "yes" \
  "$(grep -q 'git worktree' "$RA_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts Stage B runs no git worktree (expected absent)
assert_eq "#152: Stage B drops the targets[] return field" "yes" \
  "$(grep -qF '"targets"' "$RA_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts Stage B drops the targets[] field (expected absent)
assert_eq "#152: Stage B drops the excluded return field" "yes" \
  "$(grep -qF '"excluded"' "$RA_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts Stage B drops the excluded field (expected absent)
# Orchestrator (retrospective-weekly) Step 8 files issues, opens zero PRs, runs no
# worktrees, and never auto-posts /devflow:implement.
RW_SKILL="$LIB/../skills/retrospective-weekly/SKILL.md"
assert_eq "#152: orchestrator invokes meta-issue.sh" "yes" \
  "$(grep -q 'meta-issue.sh' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'meta-issue.sh' appears many times in retrospective-weekly SKILL
assert_eq "#152: orchestrator accumulates intervention_issues" "yes" \
  "$(grep -q 'intervention_issues' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'intervention_issues' appears many times in retrospective-weekly SKILL
assert_eq "#152: orchestrator opens no PR (no gh pr create)" "yes" \
  "$(grep -q 'gh pr create' "$RW_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts the orchestrator opens no PR (expected absent)
assert_eq "#152: orchestrator runs no git worktree" "yes" \
  "$(grep -q 'git worktree' "$RW_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts the orchestrator runs no git worktree (expected absent)
# AC6: the loop never auto-triggers implementation. The orchestrator posts NO
# comment to a filed issue (it may reference the pipeline by name in prose, which
# is fine) — the structural guard is the absence of any gh issue/pr comment that
# would carry an auto-trigger.
assert_eq "#152: orchestrator posts no gh issue/pr comment (no auto-trigger)" "yes" \
  "$(grep -qE 'gh (issue|pr) comment' "$RW_SKILL" && echo no || echo yes)"  # raw-guard-ok: absence pin: asserts no auto-trigger gh issue/pr comment (expected absent)
assert_eq "#152: orchestrator states filed issues await human triage" "yes" \
  "$(grep -qi 'await human triage' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: case-insensitive (grep -qi); pin_count is case-sensitive -F
# #152: the load-bearing "never report a pattern as filed when it was not"
# invariant — a malformed Stage B result OR a meta-issue.sh non-zero exit must
# record a blocker and file NOTHING. Pin BOTH failure branches' concrete blocker
# appends so a refactor cannot silently drop the file-nothing path (the orchestrator
# glue the standalone review flagged as untested). The malformed branch keys on the
# "malformed JSON" blocker; the exit-non-zero branch keys on "failed to file".
assert_eq "#152: orchestrator records a blocker on a malformed Stage B result" "yes" \
  "$(grep -q 'blockers+=.*malformed JSON' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: regex grep (no -F): asserts a regex match (blockers+=.*), not a fixed literal
assert_eq "#152: orchestrator records a blocker (files nothing) on meta-issue.sh failure" "yes" \
  "$(grep -q 'blockers+=.*failed to file the issue' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: regex grep (no -F): asserts a regex match (blockers+=.*), not a fixed literal
assert_eq "#152: orchestrator pins the never-report-unfiled-as-filed invariant" "yes" \
  "$(grep -qi 'Never report a pattern as filed when it was not' "$RW_SKILL" && echo yes || echo no)"  # raw-guard-ok: case-insensitive (grep -qi); pin_count is case-sensitive -F
# Prune: no operative engine surface references the removed audit-intervention
# kind or the devflow/audit-* branch convention (CHANGELOG history + this test
# suite's own classify-input strings are intentionally excluded — note git
# pathspec `*` crosses `/`, so lib/test/ is excluded explicitly).
PRUNE_SCAN=$( cd "$LIB/.." && git grep -lFe 'audit-intervention' -e 'devflow/audit' -- \
    'lib/*.sh' 'lib/*.jq' 'skills/*/SKILL.md' 'docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md' \
    'CLAUDE.md' '.prflow/config.schema.json' 'lib/intervention-surfaces.md' \
    ':(exclude)lib/test/' 2>/dev/null || true )
assert_eq "#152: no operative file references audit-intervention / devflow-audit" "" "$PRUNE_SCAN"
# Coupled site: the de-dup title meta-issue.sh writes is re-parsed by
# actionable-patterns.sh's cooldown map. Pin the round-trip so a format drift on
# either side goes red here, before cooldown silently stops matching.
RT_SLUG="incomplete-edit"
RT_TITLE="[devflow-retrospective] meta: ${RT_SLUG} — strengthen the gate"
RT_PARSED="$(jq -rn --arg t "$RT_TITLE" '$t | capture("\\[devflow-retrospective\\] meta: (?<slug>[A-Za-z0-9_-]+)") | .slug')"
assert_eq "#152: meta-issue title round-trips through the cooldown slug regex" "$RT_SLUG" "$RT_PARSED"
assert_eq "#152: actionable-patterns carries the meta-title slug regex" "yes" \
  "$(grep -qF 'meta: (?<slug>' "$LIB/actionable-patterns.sh" && echo yes || echo no)"

# ────────────────────────────────────────────────────────────────────────────
echo "recurring-targets.sh / recurring-targets.jq (#520)"
# ────────────────────────────────────────────────────────────────────────────
# Report-only "Recurring intervention targets" view: groups every accumulated
# entry's suggested_interventions[].candidate_targets[] by exact target path and
# emits the targets named in >= 2 DISTINCT PRs. Helper takes only the jsonl path
# (no overrides arg), so dismissal state cannot affect it by construction.
RT_TMP="$(mktemp -d)"
rt_run() {  # <jsonl-content-on-stdin> → helper stdout
  cat > "$RT_TMP/r.jsonl"
  bash "$LIB/recurring-targets.sh" "$RT_TMP/r.jsonl"
}

# AC: a target in >= 2 PRs surfaces; a target in exactly 1 PR does not.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"fix A","candidate_targets":["lib/x.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"fix B","candidate_targets":["lib/x.sh","lib/solo.sh"]}]}
JSONL
)"
assert_eq "#520: target in 2 PRs surfaces"          "true"  "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/x.sh")')"
assert_eq "#520: target's pr_count is 2"            "2"     "$(echo "$RT_OUT" | jq -r '.[] | select(.target=="lib/x.sh") | .pr_count')"
assert_eq "#520: target's prs list ascending"      "1,2"   "$(echo "$RT_OUT" | jq -r '.[] | select(.target=="lib/x.sh") | .prs | join(",")')"
assert_eq "#520: single-PR target absent (1<2)"     "false" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/solo.sh")')"
assert_eq "#520: representative_summary = earliest PR" "fix A" "$(echo "$RT_OUT" | jq -r '.[] | select(.target=="lib/x.sh") | .representative_summary')"

# AC: representative_summary tiebreak within the EARLIEST PR is document-order-first
# — when the earliest PR names the target through TWO interventions, the first
# intervention's summary wins (sort_by(.pr) is stable, so $g[0] is the earliest-PR,
# earliest-intervention record). Guards the "then intervention document order" clause.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"first-iv","candidate_targets":["lib/z.sh"]},{"summary":"second-iv","candidate_targets":["lib/z.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"later-pr-iv","candidate_targets":["lib/z.sh"]}]}
JSONL
)"
assert_eq "#520: representative_summary tiebreak = earliest-PR, earliest-intervention" "first-iv" "$(echo "$RT_OUT" | jq -r '.[] | select(.target=="lib/z.sh") | .representative_summary')"

# AC: pr_count counts DISTINCT PRs — a target named twice within one PR (across
# two interventions) contributes 1, so a same-PR-twice target does NOT surface.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":7,"verdict":"imperfect","suggested_interventions":[{"summary":"one","candidate_targets":["lib/dup.sh"]},{"summary":"two","candidate_targets":["lib/dup.sh"]}]}
JSONL
)"
assert_eq "#520: same target twice in one PR counts as 1 PR (absent)" "false" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/dup.sh")')"

# AC: // []-guards — an entry missing suggested_interventions, one carrying [],
# and an intervention missing candidate_targets each contribute nothing and never
# throw; a genuine 2-PR target alongside them still surfaces.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect"}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"clean","suggested_interventions":[]}
{"schema_version":2,"kind":"implementation","pr":3,"verdict":"imperfect","suggested_interventions":[{"summary":"no targets here"}]}
{"schema_version":2,"kind":"implementation","pr":4,"verdict":"imperfect","suggested_interventions":[{"summary":"g","candidate_targets":["lib/g.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":5,"verdict":"imperfect","suggested_interventions":[{"summary":"g2","candidate_targets":["lib/g.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: missing-field entries skipped without throwing (rc 0)" "0" "$RT_RC"
assert_eq "#520: surviving 2-PR target still surfaces"                  "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/g.sh")')"
assert_eq "#520: only the genuine recurring target is present"          "1"    "$(echo "$RT_OUT" | jq 'length')"

# Guard-class 2: a non-string candidate_targets element (agent-written store) is
# dropped by the `strings` filter, never emitted as a target and never able to
# perturb the sort's type ordering — while a genuine 2-PR string target surfaces.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"n","candidate_targets":[42,"lib/s.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"n2","candidate_targets":[null,"lib/s.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: non-string candidate_target dropped (rc 0)"  "0"    "$RT_RC"
assert_eq "#520: string target still surfaces"                "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/s.sh")')"
assert_eq "#520: no non-string target emitted"                "0"    "$(echo "$RT_OUT" | jq '[.[] | select((.target|type) != "string")] | length')"

# AC: an empty-string candidate_target (a real string that passes `strings`) is
# dropped by the SEPARATE `select(. != "")` guard — never emitted as a blank-target
# bullet — while a genuine 2-PR string target still surfaces. Distinct from the
# non-string case above: "" is a string, so `strings` alone would keep it.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"e","candidate_targets":["","lib/real.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"e2","candidate_targets":["","lib/real.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: empty-string candidate_target dropped (rc 0)" "0"    "$RT_RC"
assert_eq "#520: string target still surfaces past empty filter" "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/real.sh")')"
assert_eq "#520: no empty-string target emitted"              "0"    "$(echo "$RT_OUT" | jq '[.[] | select(.target=="")] | length')"

# Guard-class 2 (container type): retrospectives.jsonl is agent-written, so an entry
# or either container field can arrive WRONG-TYPED (not just missing). `// []` only
# fires on null — a present string/number/object would detonate the `[]` iterator
# (jq "Cannot iterate over …", rc 5), which under the SKILL's `set -euo pipefail`
# wiring empties RECURRING_TARGETS_JSON and breaks the whole `--argjson` report build.
# `objects`/`arrays` container guards must make each wrong-typed shape contribute
# nothing at rc 0. Each row: a malformed entry + a genuine 2-PR target that survives.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"n","candidate_targets":"lib/bare-string.sh"}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":"oops-not-an-array"}
{"schema_version":2,"kind":"implementation","pr":3,"verdict":"imperfect","suggested_interventions":["not-an-object"]}
{"schema_version":2,"kind":"implementation","pr":4,"verdict":"imperfect","suggested_interventions":[{"summary":"n","candidate_targets":5}]}
{"schema_version":2,"kind":"implementation","pr":5,"verdict":"imperfect","suggested_interventions":[{"summary":"g","candidate_targets":["lib/good.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":6,"verdict":"imperfect","suggested_interventions":[{"summary":"g2","candidate_targets":["lib/good.sh"]}]}
5
JSONL
)"; RT_RC=$?
assert_eq "#520: wrong-typed containers fail closed (rc 0)"   "0"    "$RT_RC"
assert_eq "#520: wrong-typed rows contribute no target"       "0"    "$(echo "$RT_OUT" | jq '[.[] | select(.target|IN("lib/bare-string.sh"))] | length')"
assert_eq "#520: genuine target survives wrong-typed siblings" "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/good.sh")')"
assert_eq "#520: only the genuine target present amid malformed rows" "1" "$(echo "$RT_OUT" | jq 'length')"

# Guard-class 2 (field type): `.summary` is agent-written, so it can arrive
# WRONG-TYPED (number/object/array), not just missing. `(.summary // "")` alone
# only substitutes for null/false — a non-string summary would flow through as
# `representative_summary` and detonate render-report.sh's `gsub("\n";" ")` (jq
# rc 5 on a non-string) under its `set -euo pipefail`, aborting the whole render.
# `((.summary | strings) // "")` must coerce every non-string summary to "" so the
# emitted `representative_summary` is ALWAYS a string. (issue #520)
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":42,"candidate_targets":["lib/nst.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":{"o":"bj"},"candidate_targets":["lib/nst.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: non-string summary does not throw (rc 0)"    "0"    "$RT_RC"
assert_eq "#520: non-string summary target still surfaces"    "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/nst.sh")')"
assert_eq "#520: non-string summary coerced to string representative_summary" "true" "$(echo "$RT_OUT" | jq '[.[] | select((.representative_summary|type) != "string")] | length == 0')"

# AC: `select(.pr | numbers)` — only a NUMBER-typed `.pr` contributes. A pr-less
# entry (defensive: the store otherwise guarantees `pr`, so this is a malformed /
# hand-corrupted line) naming a target that ONE real PR also names must NOT inflate
# that target to pr_count 2.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","verdict":"imperfect","suggested_interventions":[{"summary":"noid","candidate_targets":["lib/onlyone.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":7,"verdict":"imperfect","suggested_interventions":[{"summary":"real","candidate_targets":["lib/onlyone.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: pr-less entry skipped (rc 0)"                "0"    "$RT_RC"
assert_eq "#520: pr-less entry does not inflate to a distinct PR" "false" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/onlyone.sh")')"

# AC: a WRONG-TYPED `pr` (agent-written string "7" instead of int 7) is dropped, not
# counted as a PR distinct from the numeric 7 — otherwise a single real PR whose
# target a string-pr sibling also names would falsely surface as pr_count 2.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":"7","verdict":"imperfect","suggested_interventions":[{"summary":"strpr","candidate_targets":["lib/onlyone.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":7,"verdict":"imperfect","suggested_interventions":[{"summary":"real","candidate_targets":["lib/onlyone.sh"]}]}
JSONL
)"; RT_RC=$?
assert_eq "#520: string pr dropped (rc 0)"                    "0"    "$RT_RC"
assert_eq "#520: string pr does not inflate a numeric PR's count" "false" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/onlyone.sh")')"

# AC: primary sort key is DESCENDING pr_count — a more-recurring target ranks first.
# Target A recurs in 3 distinct PRs, target B in 2; A must precede B. The determinism
# fixture below only has equal-count targets, so it exercises the .target secondary
# tiebreak only — this fixture is the one that would catch a `-.pr_count` sign flip.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"a","candidate_targets":["lib/aaa.sh","lib/bbb.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"a","candidate_targets":["lib/aaa.sh","lib/bbb.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":3,"verdict":"imperfect","suggested_interventions":[{"summary":"a","candidate_targets":["lib/aaa.sh"]}]}
JSONL
)"
assert_eq "#520: A(3 PRs) pr_count is 3"                       "3"    "$(echo "$RT_OUT" | jq -r '.[] | select(.target=="lib/aaa.sh") | .pr_count')"
assert_eq "#520: primary sort desc pr_count (A before B)"     "lib/aaa.sh,lib/bbb.sh" "$(echo "$RT_OUT" | jq -r '[.[].target] | join(",")')"

# AC: determinism — same input twice → byte-identical output.
RT_DET_IN='{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","suggested_interventions":[{"summary":"a","candidate_targets":["lib/a.sh","lib/b.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","suggested_interventions":[{"summary":"b","candidate_targets":["lib/a.sh","lib/b.sh"]}]}'
printf '%s\n' "$RT_DET_IN" > "$RT_TMP/det.jsonl"
RT_D1="$(bash "$LIB/recurring-targets.sh" "$RT_TMP/det.jsonl")"
RT_D2="$(bash "$LIB/recurring-targets.sh" "$RT_TMP/det.jsonl")"
assert_eq "#520: deterministic (byte-identical on repeat)" "yes" "$([ "$RT_D1" = "$RT_D2" ] && echo yes || echo no)"
assert_eq "#520: sort is pr_count desc then target asc"    "lib/a.sh,lib/b.sh" "$(echo "$RT_D1" | jq -r '[.[].target] | join(",")')"

# AC: surfaces regardless of overrides.json dismissal — the entries carry a
# `categories` slug that this repo dismisses; the helper ignores categories
# entirely (no overrides arg), so the target still surfaces.
RT_OUT="$(rt_run <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":1,"verdict":"imperfect","categories":["dismissed-cat"],"suggested_interventions":[{"summary":"d","candidate_targets":["lib/dismissed.sh"]}]}
{"schema_version":2,"kind":"implementation","pr":2,"verdict":"imperfect","categories":["dismissed-cat"],"suggested_interventions":[{"summary":"d2","candidate_targets":["lib/dismissed.sh"]}]}
JSONL
)"
assert_eq "#520: dismissed-category target still surfaces (report-only)" "true" "$(echo "$RT_OUT" | jq 'any(.[]; .target=="lib/dismissed.sh")')"

# AC: empty / absent retrospectives.jsonl → [] with no error (fresh / consumer repo).
RT_EMPTY="$(bash "$LIB/recurring-targets.sh" "$RT_TMP/does-not-exist-$$.jsonl")"; RT_EMPTY_RC=$?
assert_eq "#520: absent store → [] (rc 0)"  "0"  "$RT_EMPTY_RC"
assert_eq "#520: absent store → empty array" "0" "$(echo "$RT_EMPTY" | jq 'length')"
: > "$RT_TMP/empty.jsonl"
assert_eq "#520: empty store → empty array" "0" "$(bash "$LIB/recurring-targets.sh" "$RT_TMP/empty.jsonl" | jq 'length')"

# AC: real-retrospectives.jsonl-SHAPED fixture (full entry shape, real multi-PR
# candidate_targets — NOT hand-authored identical stubs) asserts the report
# section renders NON-EMPTY — the anti-"green-suite/empty-production" guard.
cat > "$RT_TMP/real.jsonl" <<'JSONL'
{"schema_version":2,"kind":"implementation","pr":62,"issue":61,"merged_at":"2026-05-27T13:35:11Z","branch":"issue-61-x","head_sha":"85a6394","merge_commit_sha":"0469798","verdict":"imperfect","categories":["incomplete-edit","lenient-verdict"],"descriptors":["holes the standalone cloud review flagged Critical"],"signals":{"review_comments_count":0,"post_bot_commits":12,"workpad_final_status":"Complete"},"summary":"PR #62 hardened the shadow pass.","suggested_interventions":[{"summary":"Strengthen the review-and-fix loop-exit contract so a run that exits at the iteration cap with unresolved shadow findings does not present as clean.","candidate_targets":["skills/review-and-fix/SKILL.md","docs/internal/shadow-review.md"],"change_type":"skill-update","confidence":"medium"}]}
{"schema_version":2,"kind":"implementation","pr":91,"issue":90,"merged_at":"2026-06-02T09:10:00Z","branch":"issue-90-y","head_sha":"aa11bb2","merge_commit_sha":"cc33dd4","verdict":"imperfect","categories":["convention-violation"],"descriptors":["skill edit shipped without the writing-skills gate"],"signals":{"review_comments_count":2,"post_bot_commits":4,"workpad_final_status":"Complete"},"summary":"PR #91 tightened the fix loop.","suggested_interventions":[{"summary":"Add a tripwire so the fix loop cannot approve while shadow findings remain unresolved.","candidate_targets":["skills/review-and-fix/SKILL.md"],"change_type":"skill-update","confidence":"high"}]}
JSONL
( . "$LIB/render-report.sh"
  RT_REAL="$(bash "$LIB/recurring-targets.sh" "$RT_TMP/real.jsonl")"
  RT_SUM="$(jq -nc --argjson rt "$RT_REAL" '{prs_scanned:2,clean_count:0,analyzed_count:2,recurring_targets:$rt,intervention_issues:[]}')"
  RT_REPORT="$(devflow_render_report "$RT_SUM")"
  assert_eq "#520: real-shaped fixture renders the section"        "true" "$(echo "$RT_REPORT" | grep -q '## Recurring intervention targets' && echo true || echo false)"
  assert_eq "#520: real-shaped fixture surfaces the recurring target" "true" "$(echo "$RT_REPORT" | grep -qF 'skills/review-and-fix/SKILL.md' && echo true || echo false)"  # raw-guard-ok: greps the rendered report output for a recurring target path that happens to contain 'SKILL.md'; not a SKILL-file guard
  # omit-when-empty: no recurring target → no section header.
  RT_SUM_EMPTY='{"prs_scanned":1,"clean_count":1,"analyzed_count":0,"recurring_targets":[],"intervention_issues":[]}'
  assert_eq "#520: section omitted when no recurring target" "false" "$(devflow_render_report "$RT_SUM_EMPTY" | grep -q '## Recurring intervention targets' && echo true || echo false)"

  # render-report line-format coverage — the recurring-target bullet exercises
  # three render branches none of the fixtures above reach:
  #   (a) the exact `N PRs (#a, #b)` prs-list bullet text,
  #   (b) gsub("\n";" ") newline-flatten of an embedded newline, and
  #   (c) the length>220 ellipsis truncation.
  # Build one target carrying all three (prs 62,91; a summary with a newline that
  # is also >220 chars so truncation applies to the flattened form).
  # Build the summary inside jq so the "\n" is a REAL embedded newline (a shell
  # $(printf '\n') would be stripped by command substitution) and the x-run is >220.
  RT_RT_FMT="$(jq -nc '[{target:"lib/fmt.sh",pr_count:2,prs:[62,91],representative_summary:("line one\nand " + ("x"*300) + " tail")}]')"
  RT_SUM_FMT="$(jq -nc --argjson rt "$RT_RT_FMT" '{prs_scanned:2,clean_count:0,analyzed_count:0,recurring_targets:$rt,intervention_issues:[]}')"
  RT_FMT_LINE="$(devflow_render_report "$RT_SUM_FMT" | grep -F '`lib/fmt.sh`')"
  # (a) exact prs-list bullet text.
  assert_eq "#520: prs-list bullet renders '2 PRs (#62, #91)'" "true" "$(echo "$RT_FMT_LINE" | grep -qF '2 PRs (#62, #91)' && echo true || echo false)"
  # (b) the embedded newline is flattened — the text before and after the newline
  # ("line one" / "and xxx…") land on the SAME bullet line as "line one and ".
  # If gsub did not flatten, "and …" would be on a separate line and this fails.
  assert_eq "#520: embedded newline flattened onto the bullet line" "true" "$(echo "$RT_FMT_LINE" | grep -qF 'line one and ' && echo true || echo false)"
  # (c) >220-char summary is ellipsis-truncated (the "…" appears; the full 300-x
  # run cannot survive, so the bullet is shorter than the raw summary).
  assert_eq "#520: >220-char representative_summary is ellipsis-truncated" "true" "$(echo "$RT_FMT_LINE" | grep -qF '…' && echo true || echo false)"
  assert_eq "#520: truncated bullet drops the un-truncatable full x-run" "false" "$(echo "$RT_FMT_LINE" | grep -qF 'tail' && echo true || echo false)"

  # render-report re-sorts recurring_targets itself (its comment: "never depends on
  # the caller pre-sorting"). Feed a DELIBERATELY reverse-ordered 2-target array
  # (the 2-PR target listed before the 3-PR target) and assert the rendered bullet
  # order is pr_count-descending — the render-side analogue of the helper's A-before-B
  # test, so a sign flip in render-report's own sort_by is caught, not just the jq's.
  RT_RT_SORT="$(jq -nc '[{target:"lib/low.sh",pr_count:2,prs:[1,2],representative_summary:"low"},{target:"lib/high.sh",pr_count:3,prs:[1,2,3],representative_summary:"high"}]')"
  RT_SUM_SORT="$(jq -nc --argjson rt "$RT_RT_SORT" '{prs_scanned:3,clean_count:0,analyzed_count:0,recurring_targets:$rt,intervention_issues:[]}')"
  RT_SORT_ORDER="$(devflow_render_report "$RT_SUM_SORT" | grep -oE 'lib/(high|low)\.sh' | paste -sd, -)"
  assert_eq "#520: render-report re-sorts to pr_count desc (high before low)" "lib/high.sh,lib/low.sh" "$RT_SORT_ORDER"
)
rm -rf "$RT_TMP"

# ────────────────────────────────────────────────────────────────────────────
echo "clean-entry.jq / actionable-patterns.sh"
# ────────────────────────────────────────────────────────────────────────────
CTX_CLEAN='{"pr":42,"kind":"implementation","issue_number":40,"merged_at":"2026-05-01T00:00:00Z","branch":"claude/issue-40-x","head_sha":"abc","merge_commit_sha":"def","signals":{"review_comments_count":0,"post_bot_commits":0,"ci_failures_during_pr":0,"workpad_final_status":"Complete","review_reject_outstanding":false}}'
E="$(echo "$CTX_CLEAN" | jq -c -f "$LIB/clean-entry.jq")"
assert_eq "clean-entry verdict=clean"       "clean" "$(echo "$E" | jq -r .verdict)"
assert_eq "clean-entry pr=42"               "42"    "$(echo "$E" | jq -r .pr)"
assert_eq "clean-entry schema_version=2"    "2"     "$(echo "$E" | jq -r .schema_version)"
assert_eq "clean-entry categories=[]"       "0"     "$(echo "$E" | jq '.categories|length')"
assert_eq "clean-entry descriptors=[]"      "0"     "$(echo "$E" | jq '.descriptors|length')"
assert_eq "clean-entry no theme_tags field" "true"  "$(echo "$E" | jq 'has("theme_tags") | not')"
assert_eq "clean-entry signals carried"     "0"     "$(echo "$E" | jq -r .signals.post_bot_commits)"
# #152: audit-entry.jq is pruned along with the audit-intervention path.
assert_eq "#152: audit-entry.jq is removed" "true" \
  "$([ ! -f "$LIB/audit-entry.jq" ] && echo true || echo false)"
# actionable-patterns: incomplete-edit 2x imperfect, doc-accuracy 1x
AP_TMP="$(mktemp -d)"
printf '%s\n' \
  '{"schema_version":2,"kind":"implementation","pr":1,"merged_at":"2026-04-01T00:00:00Z","verdict":"imperfect","categories":["incomplete-edit"],"descriptors":["orphaned fetch left after deletion"]}' \
  '{"schema_version":2,"kind":"implementation","pr":2,"merged_at":"2026-04-10T00:00:00Z","verdict":"imperfect","categories":["incomplete-edit"],"descriptors":["stale count not propagated"]}' \
  '{"schema_version":2,"kind":"implementation","pr":3,"merged_at":"2026-04-11T00:00:00Z","verdict":"imperfect","categories":["doc-accuracy"]}' \
  > "$AP_TMP/r.jsonl"
echo '{"schema_version":2,"patterns":{},"dismissed":{}}' > "$AP_TMP/o.json"
cat > "$AP_TMP/gh" <<'STUB'
#!/usr/bin/env bash
case "$*" in *"pr list"*) echo '[]' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh"
AP="$(DEVFLOW_GH="$AP_TMP/gh" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json")"
assert_eq "actionable includes incomplete-edit"        "true"  "$(echo "$AP" | jq 'any(.[]; .tag=="incomplete-edit")')"
assert_eq "actionable excludes doc-accuracy (1<2)"     "false" "$(echo "$AP" | jq 'any(.[]; .tag=="doc-accuracy")')"
assert_eq "incomplete-edit occurrence_count=2"         "2"     "$(echo "$AP" | jq '.[] | select(.tag=="incomplete-edit") | .occurrence_count')"
assert_eq "incomplete-edit descriptors passed through" "orphaned fetch left after deletion|stale count not propagated" \
  "$(echo "$AP" | jq -r '.[] | select(.tag=="incomplete-edit") | .descriptors | sort | join("|")')"
assert_eq "incomplete-edit cooldown_active=false"      "false" "$(echo "$AP" | jq '.[] | select(.tag=="incomplete-edit") | .cooldown_active')"
# #152: cooldown is now driven by an open FILED retrospective issue (not an audit
# PR). An open "[devflow-retrospective] meta: incomplete-edit — …" issue created
# today → cooldown_active true.
cat > "$AP_TMP/gh" <<STUB
#!/usr/bin/env bash
case "\$*" in *"issue list"*) echo '[{"number":500,"title":"[devflow-retrospective] meta: incomplete-edit — strengthen the gate","createdAt":"'"$(date -u +%FT%TZ)"'"}]' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh"
AP2="$(DEVFLOW_GH="$AP_TMP/gh" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json")"
assert_eq "incomplete-edit cooldown_active=true after recent filed issue" "true" "$(echo "$AP2" | jq '.[] | select(.tag=="incomplete-edit") | .cooldown_active')"
# #152: cooldown EXPIRY boundary — an open filed issue OLDER than cooldown_days
# (default 3) → cooldown_active=false, so the pattern is re-filed. Guards the
# createdAt>=cooldown_epoch comparison (a flipped operator / epoch-sign bug would
# pin the pattern in permanent cooldown or never honor it, and the today/never
# fixtures above cannot catch it). Use 30 days ago — safely past any default.
_AP_OLD="$(python3 -c "import datetime as d; print((d.datetime.now(d.timezone.utc)-d.timedelta(days=30)).strftime('%Y-%m-%dT%H:%M:%SZ'))")"
cat > "$AP_TMP/gh" <<STUB
#!/usr/bin/env bash
case "\$*" in *"issue list"*) echo '[{"number":501,"title":"[devflow-retrospective] meta: incomplete-edit — strengthen the gate","createdAt":"${_AP_OLD}"}]' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh"
AP3="$(DEVFLOW_GH="$AP_TMP/gh" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json")"
assert_eq "incomplete-edit cooldown_active=false when filed issue is older than cooldown_days" "false" "$(echo "$AP3" | jq '.[] | select(.tag=="incomplete-edit") | .cooldown_active')"
# #152: a gh contract drift emitting an open issue with a null / malformed
# `createdAt` must be DROPPED at the cooldown-map producer (so it never reaches
# strptime and aborts the final jq), not crash the run. The producer parses with
# strptime itself, so the drop is total against strptime's real contract — the
# adversarial matrix here spans null, empty, fractional-seconds, non-Z offset,
# AND in-shape-but-out-of-range (month 13 / hour 99), which a mere shape regex
# would admit. Every drifted row is dropped → no open issue → cooldown_active=false.
cat > "$AP_TMP/gh" <<STUB
#!/usr/bin/env bash
case "\$*" in *"issue list"*) echo '[{"number":502,"title":"[devflow-retrospective] meta: incomplete-edit — x","createdAt":null},{"number":503,"title":"[devflow-retrospective] meta: incomplete-edit — x","createdAt":"2026-06-28T12:00:00.5Z"},{"number":504,"title":"[devflow-retrospective] meta: incomplete-edit — x","createdAt":""},{"number":505,"title":"[devflow-retrospective] meta: incomplete-edit — x","createdAt":"2026-06-28T12:00:00+00:00"},{"number":506,"title":"[devflow-retrospective] meta: incomplete-edit — x","createdAt":"2026-13-99T99:99:99Z"}]' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh"
AP4="$(DEVFLOW_GH="$AP_TMP/gh" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json")"; AP4_RC=$?
assert_eq "actionable: malformed createdAt rows are dropped, not crashed-on (exit 0)" "true" \
  "$([ "$AP4_RC" -eq 0 ] && echo true || echo false)"
assert_eq "actionable: malformed-createdAt open issue does not set cooldown_active" "false" \
  "$(echo "$AP4" | jq '.[] | select(.tag=="incomplete-edit") | .cooldown_active')"
# Missing overrides.json → should still emit the actionable array, not error
AP_NOOV="$(DEVFLOW_GH="$AP_TMP/gh" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "/tmp/devflow-nonexistent-overrides-$$-$RANDOM.json")" \
  && assert_eq "actionable: missing overrides → incomplete-edit still present" "true" "$(echo "$AP_NOOV" | jq 'any(.[]; .tag=="incomplete-edit")')" \
  || { echo FAIL >> "$RESULTS_FILE"; record_fail "actionable: missing overrides → script errored"; printf '  FAIL  actionable: missing overrides → script errored\n'; }
# #152: the open-issue cooldown lookup must FAIL CLOSED, not fail open. A `gh issue
# list` error (auth/rate-limit/network) that silently yielded an empty cooldown map
# would re-file a duplicate for every pattern — the fail-open-where-it-claims-closed
# class CLAUDE.md flags (#62/#98). The lookup-failure and non-JSON-body guards must
# each exit non-zero with a SPECIFIC breadcrumb naming the cooldown step.
cat > "$AP_TMP/gh-listfail" <<'STUB'
#!/usr/bin/env bash
case "$*" in *"issue list"*) exit 1 ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh-listfail"
DEVFLOW_GH="$AP_TMP/gh-listfail" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json" >/dev/null 2>"$AP_TMP/listfail.err"; AP_LF_RC=$?
assert_eq "actionable: gh issue-list failure fails closed (non-zero exit)" "true" \
  "$([ "$AP_LF_RC" -ne 0 ] && echo true || echo false)"
assert_eq "actionable: gh issue-list failure leaves a cooldown-lookup breadcrumb" "true" \
  "$(grep -q 'cooldown lookup failed' "$AP_TMP/listfail.err" && echo true || echo false)"
cat > "$AP_TMP/gh-nonjson" <<'STUB'
#!/usr/bin/env bash
case "$*" in *"issue list"*) echo 'gh: not authenticated' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh-nonjson"
DEVFLOW_GH="$AP_TMP/gh-nonjson" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json" >/dev/null 2>"$AP_TMP/nonjson.err"; AP_NJ_RC=$?
assert_eq "actionable: non-JSON open-issue body fails closed (non-zero exit)" "true" \
  "$([ "$AP_NJ_RC" -ne 0 ] && echo true || echo false)"
assert_eq "actionable: non-JSON open-issue body leaves a parse breadcrumb" "true" \
  "$(grep -q 'could not parse the open-issue list as JSON' "$AP_TMP/nonjson.err" && echo true || echo false)"
# #152: a drifted-slug title (carries the de-dup prefix but the slug token does not
# match the capture grammar) must be COUNTED and surfaced via ::warning::, not
# silently dropped from the cooldown map — a silent drop would re-file duplicates.
cat > "$AP_TMP/gh-drift" <<'STUB'
#!/usr/bin/env bash
case "$*" in *"issue list"*) echo '[{"number":7,"title":"[devflow-retrospective] meta: !!bad — x","createdAt":"2026-04-01T00:00:00Z"}]' ;; *) echo '[]' ;; esac
STUB
chmod +x "$AP_TMP/gh-drift"
DEVFLOW_GH="$AP_TMP/gh-drift" bash "$LIB/actionable-patterns.sh" "$AP_TMP/r.jsonl" "$AP_TMP/o.json" >/dev/null 2>"$AP_TMP/drift.err"
assert_eq "actionable: unparseable-slug open issue surfaces a drift ::warning::" "true" \
  "$(grep -q 'unparseable slug' "$AP_TMP/drift.err" && echo true || echo false)"
rm -rf "$AP_TMP"

# ────────────────────────────────────────────────────────────────────────────
echo "materialize-retrospectives.sh"
# ────────────────────────────────────────────────────────────────────────────
M_TMP="$(mktemp -d)"
printf '%s\n' \
  '{"pr":1,"kind":"implementation","verdict":"clean","note":"old"}' \
  '{"pr":2,"kind":"implementation","verdict":"imperfect"}' \
  > "$M_TMP/r.jsonl"
printf '%s\n' \
  '{"pr":1,"kind":"implementation","verdict":"imperfect","note":"new"}' \
  '{"pr":5,"kind":"implementation","verdict":"clean"}' \
  '{"pr":2,"kind":"audit","fixes_patterns":["t-z"]}' \
  > "$M_TMP/new.jsonl"
SUMMARY="$(bash "$LIB/materialize-retrospectives.sh" "$M_TMP/new.jsonl" "$M_TMP/r.jsonl")"
assert_eq "materialize: 4 lines after merge"      "4" "$(wc -l < "$M_TMP/r.jsonl" | tr -d ' ')"
assert_eq "materialize: pr1 replaced (note=new)"  "new" "$(grep '"pr":1' "$M_TMP/r.jsonl" | jq -r 'select(.pr==1 and .kind=="implementation") | .note')"
assert_eq "materialize: pr5 appended"             "true" "$([ -n "$(jq -c 'select(.pr==5)' "$M_TMP/r.jsonl")" ] && echo true || echo false)"
assert_eq "materialize: pr2 audit appended (impl kept)" "2" "$(jq -s '[.[]|select(.pr==2)]|length' "$M_TMP/r.jsonl")"
assert_eq "materialize: valid jsonl" "0" "$(jq -c . "$M_TMP/r.jsonl" >/dev/null 2>&1; echo $?)"
assert_eq "materialize: summary mentions replaced 1" "1" "$(echo "$SUMMARY" | grep -oE 'replaced [0-9]+' | grep -oE '[0-9]+')"
# Fix 5: missing new-entries file → should print "materialized: appended 0, replaced 0" and exit 0
M_NOFILE_TMP="$(mktemp -d)"
printf '%s\n' '{"pr":10,"kind":"implementation","verdict":"clean"}' > "$M_NOFILE_TMP/existing.jsonl"
M_NOFILE_OUT="$(bash "$LIB/materialize-retrospectives.sh" "/tmp/devflow-nonexistent-new-entries-$$-$RANDOM.jsonl" "$M_NOFILE_TMP/existing.jsonl")"
assert_eq "materialize: missing new-entries → appended 0, replaced 0" "materialized: appended 0, replaced 0" "$M_NOFILE_OUT"
assert_eq "materialize: missing new-entries → target untouched" "1" "$(wc -l < "$M_NOFILE_TMP/existing.jsonl" | tr -d ' ')"
rm -rf "$M_NOFILE_TMP"
rm -rf "$M_TMP"

# issue #672: operator home-directory paths are redacted on the merge write path.
# Positive controls assert the REDACTED output (not merely exit 0); negative
# controls assert repo-relative / non-home / CI-runner / non-string values survive
# unchanged — the pairing that distinguishes a working redactor from one that
# rewrites everything, rewrites nothing, or aborts on a numeric field.
MR_TMP="$(mktemp -d)"
: > "$MR_TMP/store.jsonl"
printf '%s\n' \
  '{"pr":101,"kind":"retro","summary":"at /Users/alice/.claude/jobs/x/w0.md"}' \
  '{"pr":102,"kind":"retro","summary":"at /home/alice/.claude/w0.md"}' \
  '{"pr":103,"kind":"retro","summary":"at C:\\Users\\bob\\tmp\\w0.md"}' \
  '{"pr":104,"kind":"retro","summary":"a /Users/bob/x and /Users/bob/y"}' \
  '{"pr":105,"kind":"retro","summary":"at /home/runner/work/x/scripts/workpad.py"}' \
  '{"pr":106,"kind":"retro","summary":"lib/scan.sh and /tmp/x","n":3,"nul":null,"ok":true}' \
  > "$MR_TMP/new.jsonl"
bash "$LIB/materialize-retrospectives.sh" "$MR_TMP/new.jsonl" "$MR_TMP/store.jsonl" >/dev/null 2>&1 || true
assert_eq "materialize #672: /Users/ prefix redacted to ~ (positive control)" \
  "at ~/.claude/jobs/x/w0.md" "$(jq -r 'select(.pr==101)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: /home/ prefix redacted to ~ (positive control)" \
  "at ~/.claude/w0.md" "$(jq -r 'select(.pr==102)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: Windows prefix redacted with single separator" \
  'at ~\tmp\w0.md' "$(jq -r 'select(.pr==103)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: both operator paths in one string redacted" \
  "a ~/x and ~/y" "$(jq -r 'select(.pr==104)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: /home/runner/ carve-out preserved unchanged" \
  "at /home/runner/work/x/scripts/workpad.py" "$(jq -r 'select(.pr==105)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: repo-relative + non-home path unchanged" \
  "lib/scan.sh and /tmp/x" "$(jq -r 'select(.pr==106)|.summary' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: numeric field survives redaction (no rc5 abort)" \
  "3" "$(jq -r 'select(.pr==106)|.n' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: .pr/.kind preserved through redaction" \
  "retro" "$(jq -r 'select(.pr==101)|.kind' "$MR_TMP/store.jsonl")"
assert_eq "materialize #672: redacted output still valid JSONL" \
  "0" "$(jq -c . "$MR_TMP/store.jsonl" >/dev/null 2>&1; echo $?)"
# runneradmin carve-out (the (admin)? alternation) — a second CI-runner account.
: > "$MR_TMP/store2.jsonl"
printf '%s\n' '{"pr":107,"kind":"retro","summary":"at /home/runneradmin/work/x.md and /Users/runner/y.md"}' > "$MR_TMP/new2.jsonl"
bash "$LIB/materialize-retrospectives.sh" "$MR_TMP/new2.jsonl" "$MR_TMP/store2.jsonl" >/dev/null 2>&1 || true
assert_eq "materialize #672: /home/runneradmin/ and /Users/runner/ carve-outs preserved" \
  "at /home/runneradmin/work/x.md and /Users/runner/y.md" "$(jq -r 'select(.pr==107)|.summary' "$MR_TMP/store2.jsonl")"
# Fail-CLOSED fallback: a MALFORMED new-entries file must NOT overwrite the store
# with unredacted content — the redaction skip routes to the post-merge JSONL
# validation, which rejects it (non-zero exit) and leaves the store untouched.
printf '%s\n' '{"pr":200,"kind":"retro","verdict":"clean"}' > "$MR_TMP/store3.jsonl"
printf '%s\n' 'this is not json {' > "$MR_TMP/bad.jsonl"
MR_BAD_RC=0
bash "$LIB/materialize-retrospectives.sh" "$MR_TMP/bad.jsonl" "$MR_TMP/store3.jsonl" >/dev/null 2>&1 || MR_BAD_RC=$?
assert_eq "materialize #672: malformed new-entries fails closed (non-zero exit)" \
  "true" "$([ "$MR_BAD_RC" -ne 0 ] && echo true || echo false)"
assert_eq "materialize #672: malformed new-entries leaves the store untouched" \
  '{"pr":200,"kind":"retro","verdict":"clean"}' "$(cat "$MR_TMP/store3.jsonl")"
rm -rf "$MR_TMP"

# ────────────────────────────────────────────────────────────────────────────
echo "render-report.sh / open-state-pr.sh / post-status.sh"
# ────────────────────────────────────────────────────────────────────────────
( . "$LIB/render-report.sh"
  # #152: the loop files issues, not PRs — a single intervention_issues[] list
  # ({tag, url}) replaces the old intervention_prs[] + meta_issues[] split.
  SUM='{"prs_scanned":8,"clean_count":3,"analyzed_count":5,"intervention_issues":[{"tag":"implement-review-miss","url":"https://x/issues/901"},{"tag":"review-reject-bypassed","url":"https://x/issues/9"}],"cooldown_skipped":["doc-inventory-inaccuracy"],"blockers":[],"state_pr":900}'
  REPORT="$(devflow_render_report "$SUM")"
  assert_eq "report has marker"        "true" "$(echo "$REPORT" | head -1 | grep -qF '<!-- prflow:audit-report -->' && echo true || echo false)"
  assert_eq "report shows prs_scanned"  "true" "$(echo "$REPORT" | grep -q '8' && echo true || echo false)"
  assert_eq "report has Issues filed section" "true" "$(echo "$REPORT" | grep -q '## Issues filed' && echo true || echo false)"
  assert_eq "report lists filed issue tag" "true" "$(echo "$REPORT" | grep -q 'implement-review-miss' && echo true || echo false)"
  assert_eq "report lists second filed tag" "true" "$(echo "$REPORT" | grep -q 'review-reject-bypassed' && echo true || echo false)"
  assert_eq "report lists cooldown tag" "true" "$(echo "$REPORT" | grep -q 'doc-inventory-inaccuracy' && echo true || echo false)"
  # #152: the pruned audit path leaves no "Intervention PRs" / "Meta-issues" headers
  assert_eq "no Intervention PRs section" "false" "$(echo "$REPORT" | grep -q '## Intervention PRs' && echo true || echo false)"
  assert_eq "no Meta-issues section"      "false" "$(echo "$REPORT" | grep -q '## Meta-issues filed' && echo true || echo false)"
  # empty filed list → explicit "_None filed._"
  SUM_NONE='{"prs_scanned":1,"clean_count":1,"analyzed_count":0,"intervention_issues":[],"cooldown_skipped":[],"blockers":[],"state_pr":1}'
  assert_eq "empty Issues filed shows None" "true" "$(devflow_render_report "$SUM_NONE" | grep -qF '_None filed._' && echo true || echo false)"
  # #7c: omit the new sections when the keys aren't supplied
  assert_eq "no Analyzed section without data" "false" "$(echo "$REPORT" | grep -q '### Analyzed PRs' && echo true || echo false)"
  assert_eq "no Patterns section without data" "false" "$(echo "$REPORT" | grep -q '## Patterns this run' && echo true || echo false)"
  # #7c: render them when supplied
  SUM2='{"prs_scanned":2,"clean_count":0,"analyzed_count":2,"analyzed":[{"pr":771,"verdict":"imperfect","summary":"merged over an outstanding /review REJECT"},{"pr":789,"verdict":"imperfect","summary":"internal doc listed files that no longer match"}],"patterns":[{"tag":"merged-over-review-reject","slug":"merged-over-review-reject","occurrence_count":2,"status":"open","cooldown_active":false},{"tag":"old-pattern","slug":"old-pattern","occurrence_count":3,"status":"open","cooldown_active":true}],"intervention_issues":[],"cooldown_skipped":["old-pattern"],"blockers":[],"state_pr":810}'
  REPORT2="$(devflow_render_report "$SUM2")"
  assert_eq "Analyzed section present"        "true" "$(echo "$REPORT2" | grep -q '### Analyzed PRs' && echo true || echo false)"
  assert_eq "Analyzed line for PR 771"        "true" "$(echo "$REPORT2" | grep -q '#771 — imperfect: merged over an outstanding' && echo true || echo false)"
  assert_eq "Patterns section present"        "true" "$(echo "$REPORT2" | grep -q '## Patterns this run' && echo true || echo false)"
  assert_eq "Patterns sorted by count desc"   "true" "$(echo "$REPORT2" | grep -A2 '## Patterns this run' | grep -q 'old-pattern.*3×' && echo true || echo false)"
  assert_eq "cooldown pattern annotated"      "true" "$(echo "$REPORT2" | grep -q 'old-pattern.*cooldown, skipped this run' && echo true || echo false)"

  # ── #894 old-summary rendering: section presence + the one stated exception ──
  # An old-shaped summary (NONE of the new #894 keys) is rendered and its SECTION
  # PRESENCE is asserted heading by heading. These are presence assertions, not a
  # byte comparison: they establish that the pre-existing headings still render and
  # that the two new gated sections stay omitted, and they deliberately do NOT
  # establish section ordering, blank-line structure, or any pre-existing section's
  # body bytes. They assert the SEMANTIC contract for an old-shaped summary — which
  # pre-existing headings render and which new gated sections stay omitted — and
  # that contract is the standing guarantee. (A one-shot pre-merge byte-identity
  # comparison against the merge-base renderer used to sit below these probes; it
  # was retired in issue #924 once #894 merged, because comparing the current
  # renderer against a merge-base that already carries the #894 sections is a
  # tautology, and the presence probes here already hold the standing contract.)
  #
  # The fixture is deliberately given a `status: regressed` pattern, so the one
  # stated exception — a regressed entry in an old summary now also surfacing the
  # Regressed-patterns section — is EXERCISED rather than dodged. The pre-existing
  # fixtures use `status: open` throughout, which would make this exception pass
  # vacuously. Because the summary carries neither `filing_queue_open`/
  # `filing_queue_max` nor `truncations`, the Filing-queue line and the truncation
  # section must both be OMITTED (the old-orchestrator shape).
  # (Assertion names intentionally carry no `#894` token: label 894 is owned wholly
  # by the retrospective-lifecycle module's coverage, and coverage_map_guard.py
  # attributes a label by where its assertions live.)
  SUM894='{"prs_scanned":2,"clean_count":0,"analyzed_count":1,"patterns":[{"tag":"reg-old","slug":"reg-old","occurrence_count":4,"status":"regressed","cooldown_active":false},{"tag":"open-old","slug":"open-old","occurrence_count":2,"status":"open","cooldown_active":false}],"intervention_issues":[],"blockers":[],"state_pr":810}'
  REPORT894="$(devflow_render_report "$SUM894")"
  assert_eq "audit-cap old summary: still renders the Patterns this run heading" "true" \
    "$(echo "$REPORT894" | grep -q '## Patterns this run' && echo true || echo false)"
  assert_eq "audit-cap old summary: a regressed entry surfaces Regressed patterns (the one stated exception)" "true" \
    "$(echo "$REPORT894" | grep -q '## Regressed patterns' && echo true || echo false)"
  assert_eq "audit-cap old summary: no new operand key → the Filing queue line is omitted" "false" \
    "$(echo "$REPORT894" | grep -q '## Filing queue' && echo true || echo false)"
  assert_eq "audit-cap old summary: no truncations key → the truncation section is omitted" "false" \
    "$(echo "$REPORT894" | grep -q 'Stage B evidence truncated' && echo true || echo false)"

)
OSPR="$(bash "$LIB/open-state-pr.sh" --branch devflow/learnings-test --dry-run 2>/dev/null)"
assert_eq "open-state-pr dry-run echoes DRYRUN" "true" "$(echo "$OSPR" | grep -q 'DRYRUN' && echo true || echo false)"
assert_eq "open-state-pr dry-run mentions git push" "true" "$(echo "$OSPR" | grep -qi 'git push' && echo true || echo false)"

# ── #519: open-state-pr.sh stdout is ONLY the PR number on every real path ────
# Reproduce-first: today (pre-fix) `git checkout -B` (via _run), `git commit`, and
# the reuse-path `gh pr edit` leak porcelain to stdout, so a `STATE_PR=$(...)`
# capture is a multiline blob that breaks the downstream `jq --argjson state_pr`.
# Both paths must yield a single bare token: create (no existing PR) and reuse
# (an existing PR for the branch, exercising `gh pr edit`).
OSPR_SB="$(git_sandbox '#519 open-state-pr bare stdout')"
( cd "$OSPR_SB" || exit 0
  git init -q -b main >/dev/null 2>&1; git config user.email t@t; git config user.name t
  git commit -q --allow-empty -m base
  # A bare repo as `origin` so open-state-pr.sh's push step succeeds (it is not
  # the subject under test; without it push fails and stdout is empty, not the PR#).
  git init -q --bare "$OSPR_SB/origin.git" >/dev/null 2>&1
  git remote add origin "$OSPR_SB/origin.git"
  mkdir -p .prflow/learnings; echo '{"pr":1}' > .prflow/learnings/retrospectives.jsonl
  # A modified tracked file so `git checkout -B` prints carried-over `M<TAB>file` lines.
  echo x > tracked.txt; git add tracked.txt; git commit -q -m t; echo modified > tracked.txt
  # gh stub whose "existing PR" answer is toggled by the OSPR_EXISTING env var.
  cat > gh <<'STUB'
#!/usr/bin/env bash
j="$*"
if [[ "$j" == *"pr list"* ]]; then printf '%s' "${OSPR_EXISTING:-}"; exit 0; fi
if [[ "$j" == *"pr create"* ]]; then echo "https://github.com/x/y/pull/77"; exit 0; fi
if [[ "$j" == *"pr edit"* ]]; then echo "https://github.com/x/y/pull/77"; exit 0; fi
printf ''; exit 0
STUB
  chmod +x gh
  # Create path: pr list returns empty first (no existing PR), then re-list returns 77.
  cat > gh-create <<'STUB'
#!/usr/bin/env bash
j="$*"; MARK="$(dirname "$0")/.listed"
if [[ "$j" == *"pr list"* ]]; then
  if [ -f "$MARK" ]; then echo "77"; else touch "$MARK"; printf ''; fi; exit 0
fi
if [[ "$j" == *"pr create"* ]]; then echo "https://github.com/x/y/pull/77"; exit 0; fi
printf ''; exit 0
STUB
  chmod +x gh-create
  CREATE_OUT="$(DEVFLOW_GH="$OSPR_SB/gh-create" bash "$LIB/open-state-pr.sh" --branch devflow/learnings-test --base main 2>/dev/null)"
  assert_eq "#519 open-state-pr create path: stdout is exactly the bare PR number" "77" "$CREATE_OUT"
  # Reuse path: pr list reports an existing PR 77 (exercises gh pr edit).
  git checkout -q main; echo modified2 > tracked.txt
  REUSE_OUT="$(OSPR_EXISTING="77" DEVFLOW_GH="$OSPR_SB/gh" bash "$LIB/open-state-pr.sh" --branch devflow/learnings-test --base main 2>/dev/null)"
  assert_eq "#519 open-state-pr reuse path: stdout is exactly the bare PR number" "77" "$REUSE_OUT"
)

# ── #519: retrospective-weekly Step-1 stale-scratch cleanup literal (coupled) ──
assert_eq "#519 pin: retrospective-weekly Step 1 removes prior-run per-PR scratch" "yes" \
  "$(grep -qF -- "find .prflow/tmp -maxdepth 1 -type f \\( -name 'result-*.json' -o -name 'pr-*.context.json' -o -name 'overrides-prefiling.json' -o -name 'patterns.json' -o -name 'patterns-full.json' -o -name 'patterns.stderr' \\) -delete 2>/dev/null" "$LIB/../skills/retrospective-weekly/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: presence pin on the byte-exact Step-1 cleanup literal (single coupled site)  # structural-pin-ok: cross-file-phase-contract -- the pinned literal is an EXECUTABLE fence the retrospective orchestrator runs, not prose: it names exactly which per-run scratch files Step 0 deletes, and lib/filing-decisions.sh's devflow_declined_refiled guards its input by readability alone, so a name dropped from this set leaves a READABLE stale snapshot that the guard accepts and the report renders from the previous run's state
PSR="$(echo '<!-- prflow:audit-report -->' > /tmp/devflow-test-report.md; bash "$LIB/post-status.sh" --pr 900 --report-file /tmp/devflow-test-report.md --dry-run 2>/dev/null; rm -f /tmp/devflow-test-report.md)"
assert_eq "post-status dry-run echoes DRYRUN" "true" "$(echo "$PSR" | grep -q 'DRYRUN' && echo true || echo false)"

# ────────────────────────────────────────────────────────────────────────────
echo "dismiss-stale-rejections.sh"
# ────────────────────────────────────────────────────────────────────────────
DSR="$LIB/../scripts/dismiss-stale-rejections.sh"

( bash "$DSR" >/dev/null 2>&1 ); DSR_RC=$?
assert_eq "no args → exit 2" "2" "$DSR_RC"

# Everything below drives the REAL script under a FAITHFUL `gh` fake: the stub
# applies the caller's own `--jq` program to a JSON fixture, so the predicate
# under test is the shipped filter itself. (The former selection check ran a
# hand-copied jq filter inside this file, which could only ever assert that the
# copy was right — it would stay green while the shipped filter regressed.)
# Every call is appended to $DSR_LOG, so "issued no dismissals request" is an
# observation rather than an inference from the exit status.
DSR_SB="$(mktemp -d)"
cat > "$DSR_SB/gh" <<'EOS'
#!/usr/bin/env bash
# Arm order is load-bearing: a dismissals URL also contains "/reviews", and a
# reviews URL also contains "/pulls/". Exit statuses are deterministic, and the
# three knobs DSR_LIST_RC / DSR_HEAD_RC / DSR_PUT_RC inject the three request
# failures the caller branches on.
filter=""; want=0
for a in "$@"; do
  if [ "$want" = 1 ]; then filter="$a"; want=0; continue; fi
  [ "$a" = "--jq" ] && want=1
done
case "$*" in
  *"dismissals"*)
    echo "dismiss $*" >> "$DSR_LOG"
    [ "${DSR_PUT_RC:-0}" = 0 ] || { echo "HTTP 422 Unprocessable Entity" >&2; exit 1; }
    exit 0 ;;
  *"repo view"*) echo "o/r"; exit 0 ;;
  *"/reviews"*)
    echo "list-reviews" >> "$DSR_LOG"
    [ "${DSR_LIST_RC:-0}" = 0 ] || { echo "HTTP 502 Bad Gateway" >&2; exit 1; }
    jq -r "$filter" "$DSR_REVIEWS"; exit 0 ;;
  *"/pulls/"*)
    echo "read-head" >> "$DSR_LOG"
    [ "${DSR_HEAD_RC:-0}" = 0 ] || { echo "HTTP 404 Not Found" >&2; exit 1; }
    # DSR_HEAD_TEXT (when SET, empty or not) replaces the fixture read, so the
    # empty-output and not-a-SHA boundary rows are expressible.
    if [ -n "${DSR_HEAD_TEXT+set}" ]; then printf '%s' "$DSR_HEAD_TEXT"; exit 0; fi
    jq -r "$filter" "$DSR_PULL"; exit 0 ;;
esac
exit 0
EOS
chmod +x "$DSR_SB/gh"

DSR_HEAD_SHA="1111111111111111111111111111111111111111"
DSR_OLD_SHA="0000000000000000000000000000000000000000"
DSR_OLD2_SHA="2222222222222222222222222222222222222222"
printf '{"head":{"sha":"%s"}}\n' "$DSR_HEAD_SHA" > "$DSR_SB/pull-head.json"
printf '{"head":{"sha":null}}\n' > "$DSR_SB/pull-nullsha.json"
printf '[]\n' > "$DSR_SB/rev-none.json"
# One review recorded against a superseded commit — the case the script exists
# for, which must keep working (the guard must not become a permanent no-op).
cat > "$DSR_SB/rev-stale.json" <<EOS
[{"id":11,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"## Verdict: REJECT (stub, superseded commit)"}]
EOS
# One review recorded against the PR's CURRENT head — the live hazard.
cat > "$DSR_SB/rev-current.json" <<EOS
[{"id":12,"state":"CHANGES_REQUESTED","commit_id":"$DSR_HEAD_SHA","body":"## Verdict: REJECT (stub, current head)"}]
EOS
# The full selection matrix on one page: body shape x state x commit_id.
cat > "$DSR_SB/rev-mixed.json" <<EOS
[
 {"id":11,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"## Verdict: REJECT (stub, superseded commit)"},
 {"id":12,"state":"CHANGES_REQUESTED","commit_id":"$DSR_HEAD_SHA","body":"## Verdict: REJECT (stub, current head)"},
 {"id":13,"state":"CHANGES_REQUESTED","commit_id":null,"body":"# Review Report (legacy, no commit_id)"},
 {"id":14,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"please fix the typo"},
 {"id":15,"state":"DISMISSED","commit_id":"$DSR_OLD_SHA","body":"## Verdict: REJECT (already dismissed)"},
 {"id":16,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":null},
 {"id":17,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD2_SHA","body":"# Review Report (legacy, superseded commit)"}
]
EOS

# $1 reviews fixture, $2 pull fixture, rest: stub knobs as VAR=VALUE. Per-case
# values go through `env` because words from "$@" expansion are NOT honored as
# assignment prefixes (POSIX recognizes only literal tokens).
dsr_run() {
  local rev="$1" pull="$2"; shift 2
  : > "$DSR_SB/log"
  DSR_ERR="$(DEVFLOW_GH="$DSR_SB/gh" DSR_LOG="$DSR_SB/log" \
             DSR_REVIEWS="$DSR_SB/$rev" DSR_PULL="$DSR_SB/$pull" \
             env "$@" bash "$DSR" 123 o/r 2>&1 >/dev/null)"
  DSR_RC=$?
}
dsr_calls() { grep -c "$1" "$DSR_SB/log"; }

dsr_run rev-none.json pull-head.json
assert_eq "empty selection → exit 0 no-op" "0" "$DSR_RC"
assert_eq "#1029 dismisser: with no candidate the head is never read (no added API call)" \
  "0" "$(dsr_calls 'read-head')"

dsr_run rev-stale.json pull-head.json
assert_eq "successful dismissal → exit 0" "0" "$DSR_RC"
assert_eq "#1029 dismisser: a review recorded against a superseded commit is still dismissed" \
  "1" "$(dsr_calls 'reviews/11/dismissals')"

dsr_run rev-stale.json pull-head.json DSR_PUT_RC=1
assert_eq "dismissal failure → exit 1" "1" "$DSR_RC"

# The hazard this guard closes: a concurrent pass's REJECT on the very commit
# the caller just approved is NOT superseded, so it is refused — loudly, and
# with an exit status distinct from a clean no-op.
dsr_run rev-current.json pull-head.json
assert_eq "#1029 dismisser: a REJECT on the PR's current head is refused, not dismissed" \
  "3" "$DSR_RC"
assert_eq "#1029 dismisser: the refused current-head review gets no dismissals request" \
  "0" "$(dsr_calls 'dismissals')"
assert_eq "#1029 dismisser: the current-head refusal names the head on stderr" \
  "1" "$(printf '%s\n' "$DSR_ERR" | grep -c "current head (reviews-API commit_id=$DSR_HEAD_SHA)")"

# One page carrying every shape at once. The exact dismissed set is the whole
# claim: the two superseded Devflow reports go, and nothing else does.
dsr_run rev-mixed.json pull-head.json
assert_eq "#1029 dismisser: mixed page — superseded stub REJECT is dismissed" \
  "1" "$(dsr_calls 'reviews/11/dismissals')"
assert_eq "#1029 dismisser: mixed page — current-head REJECT is not dismissed" \
  "0" "$(dsr_calls 'reviews/12/dismissals')"
assert_eq "#1029 dismisser: mixed page — a report with no commit_id is not dismissed" \
  "0" "$(dsr_calls 'reviews/13/dismissals')"
assert_eq "#1029 dismisser: mixed page — a human --request-changes is never selected" \
  "0" "$(dsr_calls 'reviews/14/dismissals')"
assert_eq "#1029 dismisser: mixed page — an already-DISMISSED review is never selected" \
  "0" "$(dsr_calls 'reviews/15/dismissals')"
assert_eq "#1029 dismisser: mixed page — a null-body row is never selected" \
  "0" "$(dsr_calls 'reviews/16/dismissals')"
assert_eq "#1029 dismisser: mixed page — superseded LEGACY report is dismissed" \
  "1" "$(dsr_calls 'reviews/17/dismissals')"
assert_eq "#1029 dismisser: mixed page issues exactly two dismissals requests" \
  "2" "$(dsr_calls 'dismissals')"
assert_eq "#1029 dismisser: mixed page exits 3 — something refused, nothing failed" \
  "3" "$DSR_RC"
assert_eq "#1029 dismisser: an absent commit_id fails closed with an attributable warning" \
  "1" "$(printf '%s\n' "$DSR_ERR" | grep -c 'review 13 on PR .* records neither a verdict-marker head nor a commit_id')"

dsr_run rev-mixed.json pull-head.json DSR_PUT_RC=1
assert_eq "#1029 dismisser: a real dismissal failure outranks a refusal in the exit status" \
  "1" "$DSR_RC"

# Head-read boundary rows. The head decides the selection, so an unestablished
# one must dismiss NOTHING — never fall through to a value that compares
# unequal to every commit_id and waves the whole page past the guard.
dsr_run rev-mixed.json pull-head.json DSR_HEAD_RC=1
assert_eq "#1029 dismisser: a failed head read dismisses nothing and exits 1" \
  "1-0" "$DSR_RC-$(dsr_calls 'dismissals')"
dsr_run rev-mixed.json pull-nullsha.json
assert_eq "#1029 dismisser: a null head sha dismisses nothing and exits 1" \
  "1-0" "$DSR_RC-$(dsr_calls 'dismissals')"
dsr_run rev-mixed.json pull-head.json DSR_HEAD_TEXT=
assert_eq "#1029 dismisser: an empty head read dismisses nothing and exits 1" \
  "1-0" "$DSR_RC-$(dsr_calls 'dismissals')"
dsr_run rev-mixed.json pull-head.json DSR_HEAD_TEXT=not-a-sha
assert_eq "#1029 dismisser: a non-SHA head value dismisses nothing and exits 1" \
  "1-0" "$DSR_RC-$(dsr_calls 'dismissals')"

# A failed review list is the pre-existing exit-1 path; it must now also stop
# BEFORE the head read, so a list outage costs one call, not two.
dsr_run rev-mixed.json pull-head.json DSR_LIST_RC=1
assert_eq "#1029 dismisser: a failed review list reads no head, dismisses nothing, exits 1" \
  "1-0-0" "$DSR_RC-$(dsr_calls 'read-head')-$(dsr_calls 'dismissals')"

# ── #1030: the producer marker, driven over the REAL census corpus ────────────
# lib/test/fixtures/review-verdict-census.json holds the nine bot CHANGES_REQUESTED
# bodies issue #1030 measured across PRs #942-#1024 (six of which matched NEITHER
# transitional prose shape) plus the four APPROVE-form bodies from the same census.
# Every assertion below runs the SHIPPED filter over bodies built from those recorded
# first lines — none greps a source file for wording.
DSR_CENSUS="$LIB/test/fixtures/review-verdict-census.json"
# Build three review pages from the corpus: marker-stamped, unmarked, and a
# marker-carrying APPROVE. `commit_id` is the superseded commit on every row, so the
# #1029 staleness arms wave them through and SELECTION is the only variable.
python3 - "$DSR_CENSUS" "$DSR_SB" "$DSR_OLD_SHA" <<'PYEOF'
import json, sys
census, sb, old = json.load(open(sys.argv[1])), sys.argv[2], sys.argv[3]
marker = "<!-- prflow:review-verdict head=%s verdict=%%s -->" % old
def body(row, verdict=None):
    text = row["first_line"] + "\n\nfindings follow in the progress comment.\n"
    return (marker % verdict) + "\n" + text if verdict else text
def page(rows, verdict=None):
    return [{"id": int(r["review_id"]), "state": "CHANGES_REQUESTED",
             "commit_id": old, "body": body(r, verdict)} for r in rows]
rej = census["rejects"]
json.dump(page(rej, "REJECT"), open(sb + "/rev-census-marked.json", "w"))
json.dump(page(rej), open(sb + "/rev-census-unmarked.json", "w"))
# A marker whose verdict is APPROVE is NOT a dismissal candidate even on a body whose
# prose would otherwise say nothing: the marker's verdict field is what decides.
json.dump(page([r for r in rej if not r["dismisser_prose_match"]][:1], "APPROVE"),
          open(sb + "/rev-marker-approve.json", "w"))
# A human block whose body QUOTES the marker deeper in its prose (routine on a pull
# request that touches the review engine itself) must not be selected: only line 1
# is the producer's own stamp.
quoted = ("Please fix this.\n\nThe contract line is:\n\n```\n"
          + (marker % "REJECT") + "\n```\n")
json.dump([{"id": 900, "state": "CHANGES_REQUESTED", "commit_id": old, "body": quoted}],
          open(sb + "/rev-marker-quoted.json", "w"))
# Counts this block asserts against, derived from the corpus rather than transcribed.
open(sb + "/census-counts", "w").write("%d %d %d\n" % (
    len(rej), sum(1 for r in rej if r["dismisser_prose_match"]),
    sum(1 for r in rej if not r["dismisser_prose_match"])))
PYEOF
read -r DSR_CENSUS_ALL DSR_CENSUS_CONFORMING DSR_CENSUS_NONCONFORMING < "$DSR_SB/census-counts"

# Every census REJECT, marker-stamped, is selected and dismissed — including the six
# that matched no prose shape and were therefore invisible before #1030.
dsr_run rev-census-marked.json pull-head.json
assert_eq "#1030 dismisser: every marker-stamped census REJECT is dismissed" \
  "$DSR_CENSUS_ALL" "$(dsr_calls 'dismissals')"
assert_eq "#1030 dismisser: the marker-stamped census page is a clean pass (exit 0)" \
  "0" "$DSR_RC"
assert_eq "#1030 dismisser: no marker-stamped census row is reported unselected" \
  "0" "$(printf '%s\n' "$DSR_ERR" | grep -c 'did not select')"

# Negative control — the SAME nine bodies unmarked select exactly the historically
# conforming subset, proving the transitional prose arms are unchanged rather than
# widened, and that the marker arm is what moved the other six.
dsr_run rev-census-unmarked.json pull-head.json
assert_eq "#1030 dismisser: unmarked census page selects only the historically conforming bodies" \
  "$DSR_CENSUS_CONFORMING" "$(dsr_calls 'dismissals')"
# ...and the six it cannot own are COUNTED on stderr, so the run is distinguishable
# from a clean no-op (the silent misclassification #1030 exists to end).
assert_eq "#1030 dismisser: the unowned census REJECTs are reported, not silently dropped" \
  "1" "$(printf '%s\n' "$DSR_ERR" | grep -c "carries $DSR_CENSUS_NONCONFORMING outstanding CHANGES_REQUESTED review(s) this script did not select")"

# A marker carrying verdict=APPROVE is never a dismissal candidate.
dsr_run rev-marker-approve.json pull-head.json
assert_eq "#1030 dismisser: a marker whose verdict is APPROVE is not selected" \
  "0-0" "$(dsr_calls 'dismissals')-$DSR_RC"
# A marker quoted inside a human's prose is not the producer's stamp.
dsr_run rev-marker-quoted.json pull-head.json
assert_eq "#1030 dismisser: a marker quoted in prose below line 1 is not selected" \
  "0-0" "$(dsr_calls 'dismissals')-$DSR_RC"
# The pre-existing no-candidate path still costs exactly one API call: an unowned
# review must not make the head read eager.
assert_eq "#1030 dismisser: an unowned-only page still reads no head" \
  "0" "$(dsr_calls 'read-head')"

# ── #1247: the marker `head=` is the reviewed-tree comparand; commit_id is fallback ──
# GitHub can advance a review's reviews-API commit_id after submission to a commit that
# did not exist at review time (observed on PR #1234). So the staleness comparand is the
# verdict marker's head= when the review carries one, and commit_id only for a markerless
# review. Each fixture below distinguishes the new marker-first logic from the old
# commit_id-only logic, and the first three FAIL against pre-#1247 code by exhibiting the
# wedge (or its inverse). DSR_HEAD_SHA is the current head; DSR_OLD_SHA a superseded tree.
DSR_MARK_REJECT="<!-- prflow:review-verdict head=$DSR_OLD_SHA verdict=REJECT -->"
DSR_MARK_REJECT_HEAD="<!-- prflow:review-verdict head=$DSR_HEAD_SHA verdict=REJECT -->"
# (30) PR #1234 shape: marker head is the SUPERSEDED tree, commit_id was advanced to the
# current head. Pre-#1247 compares commit_id, finds equality, and REFUSES with the
# "current head" warning; #1247 compares the marker head (superseded) and DISMISSES.
cat > "$DSR_SB/rev-marker-mutated.json" <<EOS
[{"id":30,"state":"CHANGES_REQUESTED","commit_id":"$DSR_HEAD_SHA","body":"$DSR_MARK_REJECT\n## Verdict: REJECT (marker head superseded, commit_id mutated to head)"}]
EOS
dsr_run rev-marker-mutated.json pull-head.json
assert_eq "#1247 dismisser: marker head superseded + commit_id==head → DISMISSED (PR #1234 shape)" \
  "1-0" "$(dsr_calls 'reviews/30/dismissals')-$DSR_RC"
# The dismissal's -f message= is recorded in the stub log, so the message naming the
# key the decision used is an observation. A marker-driven dismissal names the marker head.
assert_eq "#1247 dismisser: the marker-driven dismissal message names the verdict-marker head key" \
  "1" "$(grep -c 'verdict-marker head=' "$DSR_SB/log")"
# (31) inverse: marker head IS the current head, commit_id names a superseded tree.
# Pre-#1247 compares commit_id, finds inequality, and DISMISSES a review about the tree
# being merged; #1247 compares the marker head (== head) and REFUSES.
cat > "$DSR_SB/rev-marker-athead.json" <<EOS
[{"id":31,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"$DSR_MARK_REJECT_HEAD\n## Verdict: REJECT (marker head == current head)"}]
EOS
dsr_run rev-marker-athead.json pull-head.json
assert_eq "#1247 dismisser: marker head==head + commit_id superseded → REFUSED (exit 3, no dismissal)" \
  "0-3" "$(dsr_calls 'reviews/31/dismissals')-$DSR_RC"
assert_eq "#1247 dismisser: the marker-head refusal names the marker-head key on stderr" \
  "1" "$(printf '%s\n' "$DSR_ERR" | grep -c "current head (verdict-marker head=$DSR_HEAD_SHA)")"
# (32) marker head present + commit_id NULL: decided on the marker, dismissed, and NO
# "records no commit_id" warning. Pre-#1247 refuses with that warning.
cat > "$DSR_SB/rev-marker-nullcommit.json" <<EOS
[{"id":32,"state":"CHANGES_REQUESTED","commit_id":null,"body":"$DSR_MARK_REJECT\n## Verdict: REJECT (marker head superseded, no commit_id)"}]
EOS
dsr_run rev-marker-nullcommit.json pull-head.json
assert_eq "#1247 dismisser: marker head + null commit_id → dismissed on the marker (exit 0)" \
  "1-0" "$(dsr_calls 'reviews/32/dismissals')-$DSR_RC"
assert_eq "#1247 dismisser: the marker-decided null-commit_id row emits no 'records no commit_id' warning" \
  "0" "$(printf '%s\n' "$DSR_ERR" | grep -c 'records no commit_id\|records neither')"
# (33) adversarial: an OWNED transitional-prose REJECT (line 1 == '## Verdict: REJECT')
# that QUOTES a marker naming the CURRENT head below line 1. The quoted marker must NOT be
# read as the head — line 1 is not a marker, so the row falls back to commit_id (superseded)
# and is DISMISSED. Were the quoted head read, commit_id==head would refuse instead.
cat > "$DSR_SB/rev-marker-quoted-head.json" <<EOS
[{"id":33,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"## Verdict: REJECT\n\nThe contract line is:\n\n$DSR_MARK_REJECT_HEAD"}]
EOS
dsr_run rev-marker-quoted-head.json pull-head.json
assert_eq "#1247 dismisser: a marker quoted below line 1 is not read as the head (falls back to commit_id, dismissed)" \
  "1-0" "$(dsr_calls 'reviews/33/dismissals')-$DSR_RC"

# (commit_id-driven dismissal): a markerless superseded REJECT is dismissed and its
# dismissal message names the commit_id key it decided on (the fallback SRC label), so a
# regression that swapped the two SRC labels in the *dismissal* message is caught, not only
# in the refusal message. rev-stale.json is markerless (## Verdict: REJECT) + superseded.
dsr_run rev-stale.json pull-head.json
assert_eq "#1247 dismisser: a markerless (commit_id-driven) dismissal message names the reviews-API commit_id key" \
  "1" "$(grep -c 'reviews-API commit_id=' "$DSR_SB/log")"

# (case-normalization, #1247): the marker head is ascii_downcase'd before comparison, so a
# hand-authored UPPERCASE marker head naming the current head is refused (normalized ==
# head), not dismissed. Needs a head carrying hex letters — the all-digit DSR_*_SHA cannot
# exhibit case. Without the ascii_downcase this fixture DISMISSES (uppercase != lowercase
# head → treated superseded), the fail-open the silent-failure review flagged.
DSR_HEX_HEAD="abc0000000000000000000000000000000000def"
printf '{"head":{"sha":"%s"}}\n' "$DSR_HEX_HEAD" > "$DSR_SB/pull-hexhead.json"
cat > "$DSR_SB/rev-marker-uphead.json" <<EOS
[{"id":34,"state":"CHANGES_REQUESTED","commit_id":"$DSR_OLD_SHA","body":"<!-- prflow:review-verdict head=ABC0000000000000000000000000000000000DEF verdict=REJECT -->\n## Verdict: REJECT (uppercase marker head == current head)"}]
EOS
dsr_run rev-marker-uphead.json pull-hexhead.json
assert_eq "#1247 dismisser: an UPPERCASE marker head equal to the current head is refused (ascii_downcase normalization, not a case-mismatch fail-open)" \
  "0-3" "$(dsr_calls 'reviews/34/dismissals')-$DSR_RC"

rm -rf "$DSR_SB"

# ────────────────────────────────────────────────────────────────────────────
echo "post-review-verdict.sh"
# ────────────────────────────────────────────────────────────────────────────
# Issues #1059 + #1030: the formal-review verdict post is a bundled helper with a
# CLOSED outcome vocabulary that names the durable channel, and it — not the agent —
# composes the machine-readable verdict marker. Everything below drives the REAL
# script under a FAITHFUL `gh` fake: the stub records each call and its stdin (the
# JSON request body the helper composed with jq --rawfile), so "the marker is line 1
# of the posted body", "the body-file bytes reached the API" and "exactly one request
# was issued" are OBSERVATIONS from the call log rather than inferences from the exit
# status. jq is real (the helper's DEVFLOW_JQ). PRV_REVIEW_RC / PRV_COMMENT_RC inject
# the two channel refusals, PRV_ERR the (possibly multi-line) stderr.
PRV="$LIB/../scripts/post-review-verdict.sh"
PRV_SB="$(mktemp -d)"
PRV_HEAD="3333333333333333333333333333333333333333"
cat > "$PRV_SB/gh" <<'EOS'
#!/usr/bin/env bash
# Faithful-enough gh. Four endpoints matter and the arm order is load-bearing (a
# comments-list URL also contains "issues/"): the reviews POST, the issue-comments
# POST (the helper's own fallback channel), the paginated comments LIST the progress
# stamp reads, and the comment PATCH it writes. Each records its arg string to the
# call log ($PRV_LOG) and its JSON request body to a per-endpoint file the assertions
# read via jq. The literal {owner}/{repo} path passes through verbatim — the helper
# never interpolates $GITHUB_REPOSITORY (asserted separately by lint-gh-api-repo-path.py).
if [ "$1" = "api" ]; then
  case "$*" in
    *"comments?per_page"*)
      printf 'LIST %s\n' "$*" >> "$PRV_LOG"
      [ "${PRV_LIST_RC:-0}" = 0 ] || { printf 'HTTP 403 list refused' >&2; exit 1; }
      cat "${PRV_COMMENTS:-/dev/null}"; exit 0 ;;
    *"issues/comments/"*)
      BODY="$(cat)"; printf 'PATCH %s\n' "$*" >> "$PRV_LOG"; printf '%s' "$BODY" > "$PRV_SB_PATCH"
      [ "${PRV_PATCH_RC:-0}" = 0 ] || { printf 'HTTP 422 patch refused' >&2; exit 1; }
      exit 0 ;;
    *"/reviews"*)
      BODY="$(cat)"; printf 'POST %s\n' "$*" >> "$PRV_LOG"; printf '%s' "$BODY" > "$PRV_SB_BODY"
      [ "${PRV_REVIEW_RC:-0}" = 0 ] || { printf '%s' "${PRV_ERR-HTTP 422 Unprocessable Entity}" >&2; exit 1; }
      exit 0 ;;
    *"/comments"*)
      BODY="$(cat)"; printf 'COMMENT %s\n' "$*" >> "$PRV_LOG"; printf '%s' "$BODY" > "$PRV_SB_CBODY"
      [ "${PRV_COMMENT_RC:-0}" = 0 ] || { printf '%s' "${PRV_CERR-HTTP 500 comment refused}" >&2; exit 1; }
      exit 0 ;;
  esac
fi
exit 0
EOS
chmod +x "$PRV_SB/gh"

# $1 verdict token, $2 body-file path, $3 head, $4 progress marker, rest: stub knobs
# as VAR=VALUE. PRV_OUT holds every stdout line; PRV_OUT1 only the OUTCOME line, which
# is what the caller routes on.
prv_run() {
  local vd="$1" bf="$2" hd="$3" pm="$4"; shift 4
  : > "$PRV_SB/log"
  PRV_OUT="$(DEVFLOW_GH="$PRV_SB/gh" DEVFLOW_JQ=jq PRV_LOG="$PRV_SB/log" \
             PRV_SB_BODY="$PRV_SB/body" PRV_SB_CBODY="$PRV_SB/cbody" PRV_SB_PATCH="$PRV_SB/patch" \
             env "$@" bash "$PRV" 123 "$vd" "$bf" "$hd" "$pm" 2>/dev/null)"
  PRV_RC_OBS=$?
  PRV_OUT1="${PRV_OUT%%$'\n'*}"
  prv_record
}
# Append every stdout line this run observed to the covered-token log the grounded-coverage
# meta-assertion below reads. Called from prv_run and from each direct invocation, so a case
# that bypasses prv_run to control argv still contributes.
prv_record() { [ -z "$PRV_OUT" ] || printf '%s\n' "$PRV_OUT" >> "$PRV_SB/covered"; }
prv_posts() { grep -c '^POST ' "$PRV_SB/log"; }
prv_calls() { grep -c "^$1 " "$PRV_SB/log"; }
# BYTE-EXACT comparison of the posted body's TAIL (everything after the marker line)
# against the source file. jq -j (raw, NO trailing newline) writes the sent body
# verbatim, then cmp against the source — so the trailing-newline dimension (empty vs
# a lone newline) is genuinely distinguished, unlike a $()-captured compare, which
# strips ALL trailing newlines from both sides and cannot tell them apart.
prv_tail_matches() {
  jq -j '.body | sub("^[^\n]*\n"; "")' "${2:-$PRV_SB/body}" > "$PRV_SB/got"
  cmp -s "$PRV_SB/got" "$1" && echo yes || echo no
}
prv_line1() { jq -r '.body | split("\n")[0]' "${1:-$PRV_SB/body}"; }

printf 'plain body line\nsecond line\n' > "$PRV_SB/body-plain.md"
printf '' > "$PRV_SB/body-empty.md"
printf '\n' > "$PRV_SB/body-nl.md"
# Adversarial body bytes: backticks, a command substitution, a literal double
# quote — all must reach the API unmangled (the jq --rawfile guarantee).
printf '## Verdict: APPROVE\ntricky: `bt` $(cmd) "q" end\n' > "$PRV_SB/body-tricky.md"
# A body whose first bytes LOOK like a gh error blob: posted verbatim, not interpreted.
printf 'HTTP 422 Unprocessable Entity\nnot really an error\n' > "$PRV_SB/body-errshape.md"
# A body already carrying the marker on line 1 (a re-post) and one merely QUOTING the
# marker deeper in its prose (a finding citing this contract).
printf '<!-- prflow:review-verdict head=%s verdict=APPROVE -->\nreal report line\n' "$PRV_HEAD" > "$PRV_SB/body-premarked.md"
printf 'report line\n\n```\n<!-- prflow:review-verdict head=%s verdict=APPROVE -->\n```\n' "$PRV_HEAD" > "$PRV_SB/body-quoting.md"

# ── Verdict token → channel + marker verdict. The five Phase 4.2 verdict tokens, ──
# ── then the three REST-event spellings #1059 shipped (still accepted).          ──
# Each row: "<token>|<expected event>|<expected marker verdict>".
for ROW in \
  'REJECT|REQUEST_CHANGES|REJECT' \
  'REJECT (self-contradicting diff)|REQUEST_CHANGES|REJECT' \
  'APPROVE|APPROVE|APPROVE' \
  'APPROVE with notes|COMMENT|APPROVE' \
  'APPROVE WITH CAVEAT|COMMENT|APPROVE' \
  'APPROVE WITH ADVISORY NOTES|COMMENT|APPROVE' \
  'REQUEST_CHANGES|REQUEST_CHANGES|REJECT' \
  'COMMENT|COMMENT|APPROVE' ; do
  PRV_TOK="${ROW%%|*}"; PRV_REST="${ROW#*|}"
  PRV_WANT_EV="${PRV_REST%%|*}"; PRV_WANT_VD="${PRV_REST#*|}"
  prv_run "$PRV_TOK" "$PRV_SB/body-plain.md" "$PRV_HEAD" ""
  assert_eq "#1030 post-verdict: '$PRV_TOK' → POSTED review $PRV_WANT_EV, exit 0" \
    "POSTED review $PRV_WANT_EV-0" "$PRV_OUT1-$PRV_RC_OBS"
  assert_eq "#1030 post-verdict: '$PRV_TOK' issues exactly one review POST at the reviews endpoint" \
    "1-1" "$(prv_posts)-$(grep -c 'pulls/123/reviews' "$PRV_SB/log")"
  assert_eq "#1030 post-verdict: '$PRV_TOK' sends the mapped event in the JSON" \
    "$PRV_WANT_EV" "$(jq -r '.event' "$PRV_SB/body")"
  # The marker is composed by the HELPER and is byte-exactly line 1 of the posted body.
  assert_eq "#1030 post-verdict: '$PRV_TOK' stamps the normalized marker as body line 1" \
    "<!-- prflow:review-verdict head=$PRV_HEAD verdict=$PRV_WANT_VD -->" "$(prv_line1)"
  # ...and everything after it is the body file, byte for byte.
  assert_eq "#1030 post-verdict: '$PRV_TOK' sends the body-file bytes verbatim below the marker" \
    "yes" "$(prv_tail_matches "$PRV_SB/body-plain.md")"
done

# ── Boundary bodies: empty, single-newline, tricky, error-shaped — all verbatim ──
for BF in body-empty.md body-nl.md body-tricky.md body-errshape.md; do
  prv_run APPROVE "$PRV_SB/$BF" "$PRV_HEAD" ""
  assert_eq "#1059 post-verdict: body $BF → POSTED review, exit 0" \
    "POSTED review APPROVE-0" "$PRV_OUT1-$PRV_RC_OBS"
  assert_eq "#1030 post-verdict: body $BF reaches the API byte-exactly below the marker" \
    "yes" "$(prv_tail_matches "$PRV_SB/$BF")"
done

# ── Idempotency of the stamp: a body already marked on line 1 is not double-stamped, ──
# ── while a marker QUOTED in prose is preserved and the producer's own stays line 1. ──
prv_run REJECT "$PRV_SB/body-premarked.md" "$PRV_HEAD" ""
assert_eq "#1030 post-verdict: a pre-marked line 1 is replaced, never double-stamped" \
  "<!-- prflow:review-verdict head=$PRV_HEAD verdict=REJECT -->-1" \
  "$(prv_line1)-$(jq -r '.body' "$PRV_SB/body" | grep -c 'prflow:review-verdict')"
prv_run REJECT "$PRV_SB/body-quoting.md" "$PRV_HEAD" ""
assert_eq "#1030 post-verdict: a marker quoted in prose is preserved and the producer's own is line 1" \
  "<!-- prflow:review-verdict head=$PRV_HEAD verdict=REJECT -->-2" \
  "$(prv_line1)-$(jq -r '.body' "$PRV_SB/body" | grep -c 'prflow:review-verdict')"
assert_eq "#1030 post-verdict: a quoting body still reaches the API byte-exactly below the marker" \
  "yes" "$(prv_tail_matches "$PRV_SB/body-quoting.md")"

# ── Adversarial / malformed input: every SKIP issues NO request ──
# Non-numeric and empty PR numbers (drive the helper directly to control argv[1]).
for PRNUM in abc ""; do
  : > "$PRV_SB/log"
  PRV_OUT="$(DEVFLOW_GH="$PRV_SB/gh" DEVFLOW_JQ=jq PRV_LOG="$PRV_SB/log" PRV_SB_BODY="$PRV_SB/body" \
    bash "$PRV" "$PRNUM" APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" 2>/dev/null)"; PRV_RC_OBS=$?
  prv_record
  assert_eq "#1059 post-verdict: PR number '$PRNUM' → SKIP not-numeric, exit 3, no request" \
    "SKIP not-numeric-3-0" "$PRV_OUT-$PRV_RC_OBS-$(prv_posts)"
done
# A verdict token outside the enum, and the empty string, both refuse (no PENDING
# draft can be created). `APPROVED` is the near-miss the REST-state vocabulary invites.
for TOK in FOO APPROVED REJECTED "" " "; do
  prv_run "$TOK" "$PRV_SB/body-plain.md" "$PRV_HEAD" ""
  assert_eq "#1030 post-verdict: verdict token '$TOK' → SKIP unknown-event, exit 3, no request" \
    "SKIP unknown-event-3-0" "$PRV_OUT-$PRV_RC_OBS-$(prv_posts)"
done
# A head that is not exactly 40 hex characters refuses rather than stamping a marker
# whose head= field could never compare equal to a real commit_id.
for HD in "" abc 333333333333333333333333333333333333333 33333333333333333333333333333333333333333 "3333333333333333333333333333333333333zzz"; do
  prv_run APPROVE "$PRV_SB/body-plain.md" "$HD" ""
  assert_eq "#1030 post-verdict: head '$HD' → SKIP head-not-sha, exit 3, no request" \
    "SKIP head-not-sha-3-0" "$PRV_OUT-$PRV_RC_OBS-$(prv_posts)"
done
# Upper-case hex is a valid object name and must NOT be refused.
prv_run APPROVE "$PRV_SB/body-plain.md" "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" ""
assert_eq "#1030 post-verdict: an upper-case 40-hex head is accepted" \
  "POSTED review APPROVE-0" "$PRV_OUT1-$PRV_RC_OBS"
# Absent and unreadable body files both refuse.
prv_run APPROVE "$PRV_SB/does-not-exist.md" "$PRV_HEAD" ""
assert_eq "#1059 post-verdict: absent body file → SKIP body-file-unreadable, exit 3, no request" \
  "SKIP body-file-unreadable-3-0" "$PRV_OUT-$PRV_RC_OBS-$(prv_posts)"
touch "$PRV_SB/body-noperm.md"; chmod 000 "$PRV_SB/body-noperm.md"
prv_run APPROVE "$PRV_SB/body-noperm.md" "$PRV_HEAD" ""
assert_eq "#1059 post-verdict: unreadable body file → SKIP body-file-unreadable, exit 3, no request" \
  "SKIP body-file-unreadable-3-0" "$PRV_OUT-$PRV_RC_OBS-$(prv_posts)"
chmod 644 "$PRV_SB/body-noperm.md"

# ── Channel failure: the review POST is refused, the comment channel carries it ──
prv_run REJECT "$PRV_SB/body-plain.md" "$PRV_HEAD" "" PRV_REVIEW_RC=1 PRV_ERR="HTTP 422 Unprocessable Entity"
assert_eq "#1030 post-verdict: a refused review POST falls back to the comment channel, exit 0" \
  "POSTED comment REQUEST_CHANGES-0" "$PRV_OUT1-$PRV_RC_OBS"
assert_eq "#1030 post-verdict: the fallback issues exactly one review POST and one comment POST" \
  "1-1" "$(prv_posts)-$(prv_calls COMMENT)"
assert_eq "#1030 post-verdict: the fallback comment carries the SAME producer marker as line 1" \
  "<!-- prflow:review-verdict head=$PRV_HEAD verdict=REJECT -->" "$(prv_line1 "$PRV_SB/cbody")"
assert_eq "#1030 post-verdict: the fallback comment carries the body-file bytes verbatim" \
  "yes" "$(prv_tail_matches "$PRV_SB/body-plain.md" "$PRV_SB/cbody")"
# Both channels refused → the distinct no-durable-channel token and a non-zero exit.
prv_run REJECT "$PRV_SB/body-plain.md" "$PRV_HEAD" "" PRV_REVIEW_RC=1 PRV_COMMENT_RC=1 \
  PRV_ERR="HTTP 422 Unprocessable Entity" PRV_CERR="HTTP 500 comment refused"
assert_eq "#1030 post-verdict: both channels refused → FAILED no-durable-channel, exit 1" \
  "yes-1" "$(case "$PRV_OUT1" in "FAILED no-durable-channel "*) echo yes;; *) echo no;; esac)-$PRV_RC_OBS"
assert_eq "#1030 post-verdict: the no-durable-channel line names BOTH captured causes" \
  "1-1" "$(printf '%s\n' "$PRV_OUT1" | grep -c 'review: HTTP 422')-$(printf '%s\n' "$PRV_OUT1" | grep -c 'comment: HTTP 500')"
# A multi-line stderr collapses onto exactly ONE outcome line.
prv_run REJECT "$PRV_SB/body-plain.md" "$PRV_HEAD" "" PRV_REVIEW_RC=1 PRV_COMMENT_RC=1 \
  PRV_ERR=$'line one\nline two\nline three' PRV_CERR=$'c one\nc two'
assert_eq "#1059 post-verdict: a multi-line API error collapses onto one outcome line" \
  "1" "$(printf '%s\n' "$PRV_OUT1" | grep -c .)"
assert_eq "#1059 post-verdict: the collapsed line carries every captured stderr line" \
  "1" "$(printf '%s\n' "$PRV_OUT1" | grep -c 'review: line one line two line three | comment: c one c two')"
# EMPTY stderr from both channels still yields the FAILED line (never a bare exit).
prv_run REJECT "$PRV_SB/body-plain.md" "$PRV_HEAD" "" PRV_REVIEW_RC=1 PRV_COMMENT_RC=1 PRV_ERR="" PRV_CERR=""
assert_eq "#1059 post-verdict: empty API errors still print a FAILED line, exit 1" \
  "1-1" "$(printf '%s\n' "$PRV_OUT1" | grep -c 'no error output')-$PRV_RC_OBS"

# ── The run-keyed progress comment carries the SAME marker on the line AFTER its ──
# ── run key, so seed-review-progress.sh's reported literal stays byte-unchanged.  ──
PRV_PM='<!-- prflow:review-progress run=99-1 -->'
export PRV_COMMENTS="$PRV_SB/comments.json"
jq -n --arg m "$PRV_PM" \
  '[{id:11,body:"an unrelated conversation comment"},
    {id:22,body:($m+"\n## Verdict: REJECT\nReviewed HEAD: deadbeef\n")}]' > "$PRV_SB/comments.json"
prv_run REJECT "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json"
assert_eq "#1030 post-verdict: a supplied run key stamps the progress comment and reports it" \
  "POSTED review REQUEST_CHANGES/PROGRESS stamped 22" "$(printf '%s' "$PRV_OUT" | tr '\n' '/')"
assert_eq "#1030 post-verdict: the progress rewrite keeps the run key on line 1" \
  "$PRV_PM" "$(jq -r '.body | split("\n")[0]' "$PRV_SB/patch")"
assert_eq "#1030 post-verdict: the progress rewrite puts the marker on line 2" \
  "<!-- prflow:review-verdict head=$PRV_HEAD verdict=REJECT -->" "$(jq -r '.body | split("\n")[1]' "$PRV_SB/patch")"
assert_eq "#1030 post-verdict: the progress rewrite preserves every other line verbatim" \
  "## Verdict: REJECT/Reviewed HEAD: deadbeef/" "$(jq -r '.body | split("\n")[2:] | join("/")' "$PRV_SB/patch")"
# A second post for the same run replaces the marker rather than accumulating one.
jq -r '.body' "$PRV_SB/patch" > "$PRV_SB/stamped-body.txt"
jq -n --rawfile b "$PRV_SB/stamped-body.txt" '[{id:22,body:$b}]' > "$PRV_SB/comments.json"
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json"
assert_eq "#1030 post-verdict: re-stamping the progress comment leaves exactly one marker" \
  "1-<!-- prflow:review-verdict head=$PRV_HEAD verdict=APPROVE -->" \
  "$(jq -r '.body' "$PRV_SB/patch" | grep -c 'prflow:review-verdict')-$(jq -r '.body | split("\n")[1]' "$PRV_SB/patch")"
# Absent run key, no matching comment, a failed list and a failed patch each get their
# own PROGRESS token — and NONE of them moves the outcome line or the exit code.
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" ""
assert_eq "#1030 post-verdict: no run key → PROGRESS not-requested, outcome and exit unchanged" \
  "POSTED review APPROVE/PROGRESS not-requested/-0" "$(printf '%s\n' "$PRV_OUT" | tr '\n' '/')-$PRV_RC_OBS"
jq -n '[{id:11,body:"an unrelated conversation comment"}]' > "$PRV_SB/comments.json"
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json"
assert_eq "#1030 post-verdict: no comment carries the run key → PROGRESS not-found, exit 0" \
  "PROGRESS not-found-0" "$(printf '%s\n' "$PRV_OUT" | tail -1)-$PRV_RC_OBS"
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json" PRV_LIST_RC=1
assert_eq "#1030 post-verdict: a failed comments list → PROGRESS failed, exit 0" \
  "PROGRESS failed HTTP 403 list refused-0" "$(printf '%s\n' "$PRV_OUT" | tail -1)-$PRV_RC_OBS"
jq -n --arg m "$PRV_PM" '[{id:22,body:($m+"\nx\n")}]' > "$PRV_SB/comments.json"
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json" PRV_PATCH_RC=1
assert_eq "#1030 post-verdict: a failed progress patch → PROGRESS failed, outcome and exit unchanged" \
  "POSTED review APPROVE-PROGRESS failed HTTP 422 patch refused-0" \
  "$PRV_OUT1-$(printf '%s\n' "$PRV_OUT" | tail -1)-$PRV_RC_OBS"
# A non-string body in the comments page must not abort the lookup filter.
jq -n --arg m "$PRV_PM" '[{id:9,body:123},{id:22,body:($m+"\nx\n")}]' > "$PRV_SB/comments.json"
prv_run APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" "$PRV_PM" PRV_COMMENTS="$PRV_SB/comments.json"
assert_eq "#1030 post-verdict: a non-string comment body is skipped, not fatal" \
  "PROGRESS stamped 22" "$(printf '%s\n' "$PRV_OUT" | tail -1)"
unset PRV_COMMENTS

# ── Guarantee-class control (the "no outcome path is silent" coverage claim). ──
# Remove the POSTED emission from a COPY of the helper and confirm the happy-path
# assertion loses its subject — proving the assertion has teeth, not that the
# suite merely stayed green. Restore is implicit (the copy is discarded).
sed '/^[[:space:]]*_prv_say "POSTED review \$EVENT"$/d' "$PRV" > "$PRV_SB/mutant.sh"
PRV_OUT="$(DEVFLOW_GH="$PRV_SB/gh" DEVFLOW_JQ=jq PRV_LOG="$PRV_SB/log" PRV_SB_BODY="$PRV_SB/body" \
  bash "$PRV_SB/mutant.sh" 123 APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" 2>/dev/null)"
assert_eq "#1059 post-verdict: guarantee-class control — removing the POSTED emit silences the outcome (control ran)" \
  "no" "$(case "$PRV_OUT" in POSTED*) echo yes;; *) echo no;; esac)"
# Second control: remove the marker prepend and confirm the line-1 assertion loses its
# subject, so "the helper stamps the marker" is a measured claim, not a green suite.
sed 's|^MARKER="<!-- prflow:review-verdict head=\$HEAD_SHA verdict=\$MARKER_VERDICT -->"$|MARKER=""|' "$PRV" > "$PRV_SB/mutant2.sh"
: > "$PRV_SB/log"
DEVFLOW_GH="$PRV_SB/gh" DEVFLOW_JQ=jq PRV_LOG="$PRV_SB/log" PRV_SB_BODY="$PRV_SB/body" \
  bash "$PRV_SB/mutant2.sh" 123 APPROVE "$PRV_SB/body-plain.md" "$PRV_HEAD" >/dev/null 2>&1
assert_eq "#1030 post-verdict: guarantee-class control — removing the marker composition empties body line 1 (control ran)" \
  "" "$(prv_line1)"

# ── GROUNDED COVERAGE for the closed stdout vocabulary (issue #1030). ─────────────
# The rows above are only as complete as the helper's arms, so derive the emitted token set
# from the helper's OWN source and assert it equals the set those rows actually observed. A
# hand-written "these are all the arms" claim decays silently, and the caller routes on the
# token PREFIX, so a new arm keeps routing correctly while carrying neither a distinguishing
# token nor a test — exactly the decay a prefix-routed vocabulary invites. Both sides are
# computed with python3 (preflight-guaranteed) so neither can be emptied by a missing PATH
# tool while the comparison still passes.
cat > "$PRV_SB/token-sets.py" <<'PY1030'
import re, sys
# argv[1] = "emitted" | "covered"; argv[2] = the source or the observed-output log.
text = open(sys.argv[2], encoding='utf-8').read()
if sys.argv[1] == 'emitted':
    # re.M is load-bearing: without it the anchors bind to the whole string and findall
    # returns nothing, emptying this side and making the comparison vacuous. The floor row
    # below catches that too.
    # `_prv_say` is the emit head since issue #1156 (stdout line first, then the run-scoped
    # receipt); `echo` stays in the alternation so a reverted or newly authored bare-echo
    # arm is still counted here rather than dropping silently out of the emitted set.
    pat = re.compile(r'^\s*(?:echo|_prv_say) "([A-Z]+ [a-z][a-z0-9-]*)', re.M)
else:
    pat = re.compile(r'^([A-Z]+ [a-z][a-z0-9-]*)', re.M)
print(' '.join(sorted(set(pat.findall(text)))))
PY1030
PRV_EMITTED="$(python3 "$PRV_SB/token-sets.py" emitted "$PRV")"
PRV_COVERED="$(python3 "$PRV_SB/token-sets.py" covered "$PRV_SB/covered")"
# Anti-vacuity floor: a regex or fence bug that emptied EITHER side would otherwise make the
# equality row below compare two empty sets and pass over nothing.
assert_eq "#1030 post-verdict: the source emits at least the seven documented outcome tokens (anti-vacuity)" \
  "yes" "$(python3 -c 'import sys; print("yes" if len(sys.argv[1].split()) >= 7 else "no")' "$PRV_EMITTED")"
assert_eq "#1030 post-verdict: every token the source emits is driven by a test, and no test drives a token the source cannot emit" \
  "$PRV_EMITTED" "$PRV_COVERED"

rm -rf "$PRV_SB"

# ────────────────────────────────────────────────────────────────────────────
echo "review/implement trigger helpers (derive-review-verdict.sh … resolve-command-trigger.sh)"
# ────────────────────────────────────────────────────────────────────────────
# Extracted to lib/test/modules/review-trigger-helpers.sh (issue #746): the 11 consecutive
# former sections from "derive-review-verdict.sh" through "resolve-command-trigger.sh".
# ALL 11 SECTIONS ARE STILL LIVE. Issue #936 withheld the auto PR-triggered review tier and
# deleted its workflow, but every helper that tier called — including derive-review-verdict.sh
# and derive-review-preconditions.sh, whose sections lead this tranche — is RETAINED and still
# shipped, because an already-installed consumer copy still resolves them after an upgrade.
# Only two assertions left the module: the #353 pair whose subject was the deleted WORKFLOW
# file (an existence backstop and the absence pin it protected), which was the whole of the
# then-current floor drop to 399. Do not read that drop as dead code — deleting these helpers
# would break every consumer that upgrades. It stops there deliberately — the tranche was
# scoped in advance to a measured set of low-risk sections, and what follows was not in it.
# The floor has RISEN since: the plugin rename added dual-namespace acceptance
# coverage to both trigger helpers (canonical-input arms plus wildcard negative controls),
# since every pre-existing fixture fed only the transitional alias form; the
# duplicate-notice self-trigger guard was widened from the single hardcoded `/devflow:`
# to every declared command namespace, with a planted-defect control per namespace; and
# issue #989 added the dedupe-review-command.sh (Candidate C) unit suite — the named
# assertions, the malformed-response matrix, and the workflow-wiring pins.
# The floor literal on the call below is equality-checked against this module's
# `minimum_assertions` in scripts/workflow-flight-recorder-registry.json — change both
# together, or test_module_runner.py's tranche test goes RED.
# See the module's .inventory.md for the coverage map back to these locations.
if ! devflow_run_full_suite_module "$LIB/test/modules/review-trigger-helpers.sh" \
  "review-trigger-helpers" 844; then
  printf 'ERROR: review-trigger-helpers boundary could not record its result\n'
  exit 1
fi
# ────────────────────────────────────────────────────────────────────────────
echo "react-to-trigger.sh"
# ────────────────────────────────────────────────────────────────────────────
# Early-ack reaction. Picks the reactions endpoint by event type, defaults the
# content to `rocket`, and skips events with no reactions API (reviews). A `gh`
# stub records the `api` call args to $REACT_REC so we can assert the endpoint.
RT="$LIB/../scripts/react-to-trigger.sh"
RT_STUB="$(mktemp -d)"
cat > "$RT_STUB/gh" <<'STUB'
#!/usr/bin/env bash
echo "$*" >> "$REACT_REC"
STUB
chmod +x "$RT_STUB/gh"

# Per-case vars go through `env` because words from "$@" expansion are NOT
# honored as assignment prefixes (POSIX recognizes only literal tokens).
react() { REACT_REC="$(mktemp)"; PATH="$RT_STUB:$PATH" REACT_REC="$REACT_REC" GH_TOKEN=x env "$@" bash "$RT" >/dev/null 2>&1; }

# 1. issue_comment → react on the issue comment, default content rocket.
react EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=555
assert_eq "react: issue_comment → issues/comments endpoint w/ rocket" \
  "1" "$(grep -c 'repos/o/r/issues/comments/555/reactions.*content=rocket' "$REACT_REC")"
rm -f "$REACT_REC"

# 2. pull_request_review_comment → react on the PR review comment.
react EVENT_NAME=pull_request_review_comment REPO=o/r COMMENT_ID=777
assert_eq "react: review comment → pulls/comments endpoint" \
  "1" "$(grep -c 'repos/o/r/pulls/comments/777/reactions' "$REACT_REC")"
rm -f "$REACT_REC"

# 3. issues (opened) → react on the issue itself.
react EVENT_NAME=issues REPO=o/r ISSUE_NUMBER=42
assert_eq "react: issues event → issues/<n> endpoint" \
  "1" "$(grep -c 'repos/o/r/issues/42/reactions' "$REACT_REC")"
rm -f "$REACT_REC"

# 4. pull_request_review has no reactions API → no call at all.
react EVENT_NAME=pull_request_review REPO=o/r COMMENT_ID=1
assert_eq "react: review event makes no api call" \
  "0" "$(grep -c 'reactions' "$REACT_REC")"
rm -f "$REACT_REC"

# 5. REACTION env overrides the default content.
react EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=9 REACTION=eyes
assert_eq "react: REACTION env overrides default content" \
  "1" "$(grep -c 'content=eyes' "$REACT_REC")"
rm -f "$REACT_REC"

# 5b. The implement skill cannot use an env-assignment prefix, so its emitted
# leading-token call supplies every selector through CLI options. Conflicting
# environment values prove the CLI path is operative and has precedence.
REACT_REC="$(mktemp)"
DEVFLOW_GH="$RT_STUB/gh" PATH="$RT_STUB:$PATH" REACT_REC="$REACT_REC" GH_TOKEN=x \
  EVENT_NAME=pull_request_review REPO=wrong/repo COMMENT_ID=1 REACTION=confused \
  bash "$RT" --repo o/r --event issue_comment --comment 17 --reaction eyes >/dev/null 2>&1
assert_eq "react: CLI selectors override conflicting environment values" \
  "1" "$(grep -c 'repos/o/r/issues/comments/17/reactions.*content=eyes' "$REACT_REC")"
assert_eq "react: CLI selector path makes exactly one api call" \
  "1" "$(wc -l < "$REACT_REC" | tr -d ' ')"
rm -f "$REACT_REC"

# 6. gh failure (e.g. HTTP 403 from a missing write scope) must NOT fail the
# step — best-effort: the script swallows it, exits 0, and warns to stderr with
# the gh error one-lined. This is the load-bearing error branch the success
# stub above can't reach (it always exits 0). A separate stub that prints a
# multi-line error to stderr and exits 1 exercises both the exit-0 guarantee
# and the `${err//$'\n'/ }` collapse.
FAIL_STUB="$(mktemp -d)"
cat > "$FAIL_STUB/gh" <<'STUB'
#!/usr/bin/env bash
printf 'HTTP 403: Resource not accessible by integration\n(check issues/pull-requests write)\n' >&2
exit 1
STUB
chmod +x "$FAIL_STUB/gh"
# DEVFLOW_GH points at the stub EXPLICITLY: the stub fails `--version` (it exits 1
# for every arg), so with DEVFLOW_GH unset the resolver would reject it and — on a
# WSL host with Windows gh.exe interop — fall through to the REAL gh.exe, making a
# live network call and failing this test. The override path exists precisely to
# keep test stubs untouched; any PATH-only gh stub that does not answer
# `--version` with rc 0 must set DEVFLOW_GH the same way.
react_err="$(DEVFLOW_GH="$FAIL_STUB/gh" PATH="$FAIL_STUB:$PATH" GH_TOKEN=x EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=1 bash "$RT" 2>&1 >/dev/null)"
assert_eq "react: gh failure still exits 0 (best-effort, never blocks the run)" "0" "$?"
assert_eq "react: gh failure warns to stderr" \
  "1" "$(printf '%s\n' "$react_err" | grep -c '::warning::react: could not add')"
assert_eq "react: multi-line gh error is collapsed to one log line" \
  "1" "$(printf '%s\n' "$react_err" | grep -c 'integration (check issues')"

# The skill's outcome-reaction fence opts into a non-zero signal so its `||
# workpad.py update` arm can durably record the failure. The workflow path omits
# this flag and retains the universal best-effort exit-zero behavior above.
report_rc=0
report_err="$(DEVFLOW_GH="$FAIL_STUB/gh" PATH="$FAIL_STUB:$PATH" GH_TOKEN=x \
  EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=1 bash "$RT" --report-failure 2>&1 >/dev/null)" || report_rc=$?
assert_eq "react: --report-failure returns non-zero after a failed api call" "1" "$report_rc"
assert_eq "react: --report-failure preserves the attributable warning" \
  "1" "$(printf '%s\n' "$report_err" | grep -c '::warning::react: could not add')"
rm -rf "$FAIL_STUB"

# 7. Malformed CLI input stays best-effort and fails closed. A recognized flag
# without a value used to reach `shift 2` under `set -e` and violate the script's
# universal exit-zero contract. An unknown flag must likewise stop before stale
# environment values can select a real reaction endpoint.
REACT_REC="$(mktemp)"
missing_value_err="$(DEVFLOW_GH="$RT_STUB/gh" PATH="$RT_STUB:$PATH" REACT_REC="$REACT_REC" \
  GH_TOKEN=x EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=9 bash "$RT" --reaction 2>&1 >/dev/null)"
assert_eq "react: missing CLI value still exits 0 (best-effort)" "0" "$?"
assert_eq "react: missing CLI value warns and makes no api call" \
  "1-0" "$(printf '%s\n' "$missing_value_err" | grep -c 'missing value')-$(grep -c 'reactions' "$REACT_REC")"
rm -f "$REACT_REC"

REACT_REC="$(mktemp)"
unknown_arg_err="$(DEVFLOW_GH="$RT_STUB/gh" PATH="$RT_STUB:$PATH" REACT_REC="$REACT_REC" \
  GH_TOKEN=x EVENT_NAME=issue_comment REPO=o/r COMMENT_ID=9 bash "$RT" --typo value 2>&1 >/dev/null)"
assert_eq "react: unknown CLI flag still exits 0 (best-effort)" "0" "$?"
assert_eq "react: unknown CLI flag warns and makes no api call" \
  "1-0" "$(printf '%s\n' "$unknown_arg_err" | grep -c 'unknown argument')-$(grep -c 'reactions' "$REACT_REC")"
rm -f "$REACT_REC"

rm -rf "$RT_STUB"

# ────────────────────────────────────────────────────────────────────────────
echo "denial forensics: build-denial-record.sh / scrub-credentials.sh / surface D1 (#1064)"
# ────────────────────────────────────────────────────────────────────────────
# BLOCK-PRIVATE jq handle. Deliberately NOT an assignment to DEVFLOW_JQ: that name is the
# resolve-bin.sh override, honored VERBATIM and never probed (the test-stub contract), and
# run.sh sets it only as a per-command prefix. A persistent assignment here leaks into every
# later subshell — the scv(jq.exe) fixture sources install.sh inside `( PATH=...; . install.sh )`
# with a deliberately unrunnable `jq` and python3 omitted, so an inherited DEVFLOW_JQ=jq made
# install.sh honor the broken stub and the jq.exe arm could not be reached.
DEN_JQ="${DEVFLOW_JQ:-jq}"
BDR="$LIB/../scripts/build-denial-record.sh"
SCR="$LIB/../scripts/scrub-credentials.sh"
SED1064="$LIB/../scripts/surface-execution-diagnostics.sh"
DEN_TMP="$(mktemp -d)"
# A denial fixture: one long Bash command whose ungranted head (`paste`) sits in the
# TAIL — past 200 chars of the stringified tool_input envelope — and which carries a
# GitHub token that must be scrubbed. permission_denials_count:1, tool_name Bash.
_LONGCMD='NUM=x && curl -H "Authorization: Bearer ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ012345" https://example.com/very/long/path/that/keeps/going/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa | paste -sd, -'
"$DEN_JQ" -n --arg c "$_LONGCMD" \
  '{type:"result",permission_denials:[{tool_name:"Bash",tool_input:{command:$c}}],permission_denials_count:1,is_error:false}' \
  > "$DEN_TMP/exec.json"

# ── AC1: surface renders the denied COMMAND at the wider bound; the ungranted head
# (`paste`) — past char 200 of the stringified envelope — is present in the output.
SURF_OUT="$(bash "$SED1064" "$DEN_TMP/exec.json" 2>/dev/null)"
assert_eq "surface D1: ungranted head 'paste' present in denial line (>200-char cmd)" \
  "yes" "$(printf '%s' "$SURF_OUT" | grep -qF 'paste -sd, -' && echo yes || echo no)"

# ── AC2/AC7: build-denial-record, key ENABLED → present, count 1, tool_names [Bash],
# command scrubbed (token gone, ungranted head kept). commands_field_enabled true.
REC_ON="$(bash "$BDR" "$DEN_TMP/exec.json" true)"
assert_eq "denial record (enabled): count=1 state=present tools=Bash enabled=true" \
  "1|present|Bash|true" \
  "$(printf '%s' "$REC_ON" | "$DEN_JQ" -r '"\(.count)|\(.commands_state)|\(.tool_names|join(","))|\(.commands_field_enabled)"')"
assert_eq "denial record (enabled): token scrubbed, ungranted head retained" \
  "yes-scrubbed" \
  "$(printf '%s' "$REC_ON" | "$DEN_JQ" -r '.commands|join(" ")' | { IFS= read -r L; case "$L" in *ghp_ABCDEF*) echo leaked ;; *paste*REDACTED*|*REDACTED*paste*) echo yes-scrubbed ;; *) echo other ;; esac; })"
assert_eq "denial record (enabled): scrub.applied true, blocklist_incomplete true" \
  "true|true" \
  "$(printf '%s' "$REC_ON" | "$DEN_JQ" -r '"\(.scrub.applied)|\(.scrub.blocklist_incomplete)"')"

# ── AC7: key DISABLED → count + tool_name STILL persisted; commands_state 'disabled'
# (distinguishable from 'unavailable' and 'zero'); commands null; enabled false.
REC_OFF="$(bash "$BDR" "$DEN_TMP/exec.json" false)"
assert_eq "denial record (disabled): count kept, state=disabled, commands null, enabled=false" \
  "1|disabled|null|false" \
  "$(printf '%s' "$REC_OFF" | "$DEN_JQ" -r '"\(.count)|\(.commands_state)|\(.commands)|\(.commands_field_enabled)"')"
assert_eq "denial record (disabled): tool_names still carried" \
  "Bash" "$(printf '%s' "$REC_OFF" | "$DEN_JQ" -r '.tool_names|join(",")')"

# ── AC2: genuine ZERO-denial run is distinguishable from unavailable.
"$DEN_JQ" -n '{type:"result",permission_denials:[],permission_denials_count:0,is_error:false}' > "$DEN_TMP/zero.json"
REC_ZERO="$(bash "$BDR" "$DEN_TMP/zero.json" true)"
assert_eq "denial record: genuine zero → count 0, commands_state zero (not unavailable)" \
  "0|zero" \
  "$(printf '%s' "$REC_ZERO" | "$DEN_JQ" -r '"\(.count)|\(.commands_state)"')"

# ── #1064 review: a digit-STRING permission_denials_count carrier (a documented shape)
# normalizes to a number, not downgraded to 'unavailable'.
"$DEN_JQ" -n '{type:"result",permission_denials_count:"3",is_error:false}' > "$DEN_TMP/strcount.json"
assert_eq "denial record: digit-string count carrier normalized to number (not unavailable)" \
  "3" "$(bash "$BDR" "$DEN_TMP/strcount.json" true | "$DEN_JQ" -r '.count')"

# ── #1064 B2: the NO-RESULT-EVENT shape. Every fixture above is a {type:"result"} event,
# which is exactly why this gap shipped green. extract-execution-shape.sh gates every
# field on a result event being present (a deliberate contract, pinned by #438 and NOT
# widened), while this record's count comes from a recursive descent that needs no result
# event — so the two halves disagreed: a positive count beside commands_state
# "unavailable" while the command text sat right there in the file. That is the shape a
# stall/timeout/crash produces, i.e. exactly what the persist step's always() is for.
# The POSITIVE CONTROL is the whole block above (result event present), so these can fail.
"$DEN_JQ" -n --arg c "$_LONGCMD" \
  '{permission_denials:[{tool_name:"Bash",tool_input:{command:$c}}]}' > "$DEN_TMP/noresult.json"
REC_NR="$(bash "$BDR" "$DEN_TMP/noresult.json" true 2>/dev/null)"
assert_eq "denial record (no result event): commands recovered, not left 'unavailable'" \
  "present" "$(printf '%s' "$REC_NR" | "$DEN_JQ" -r '.commands_state')"
assert_eq "denial record (no result event): the ungranted head survives the recovery" \
  "yes" "$(printf '%s' "$REC_NR" | "$DEN_JQ" -r '.commands|join(" ")' | grep -qF 'paste -sd, -' && echo yes || echo no)"
# The recovery path must reach the SAME scrub — a second route to persistence that
# bypassed the blocklist would be a worse defect than the bug it fixes (AC4).
assert_eq "denial record (no result event): recovered text is SCRUBBED by the shared blocklist" \
  "yes-scrubbed" \
  "$(printf '%s' "$REC_NR" | "$DEN_JQ" -r '.commands|join(" ")' | { IFS= read -r L; case "$L" in *ghp_ABCDEF*) echo leaked ;; *REDACTED*) echo yes-scrubbed ;; *) echo other ;; esac; })"
assert_eq "denial record (no result event): scrub.applied records that the scrub ran" \
  "true" "$(printf '%s' "$REC_NR" | "$DEN_JQ" -r '.scrub.applied')"
# Three-state preserved in the other direction: denial objects that carry NO extractable
# command are still an UNESTABLISHED extraction — never an empty list, never a zero.
"$DEN_JQ" -n '{permission_denials:[{tool_name:"Write",tool_input:{file_path:"a",content:"b"}}]}' \
  > "$DEN_TMP/noresult-nocmd.json"
assert_eq "denial record (no result event): no extractable command → still 'unavailable'" \
  "unavailable" "$(bash "$BDR" "$DEN_TMP/noresult-nocmd.json" true 2>/dev/null | "$DEN_JQ" -r '.commands_state')"
assert_eq "denial record (no result event): no extractable command → commands stays null (not [])" \
  "null" "$(bash "$BDR" "$DEN_TMP/noresult-nocmd.json" true 2>/dev/null | "$DEN_JQ" -c '.commands')"
# The recovery honors the SAME bounds as extract-execution-shape.sh: a 40-entry list cap
# with an honest `truncated`, and `total` counting what was extracted (not the capped list).
"$DEN_JQ" -n '{permission_denials:[range(45) | {tool_name:"Bash",tool_input:{command:("echo c\(.)")}}]}' \
  > "$DEN_TMP/noresult-many.json"
assert_eq "denial record (no result event): 45 denials → list capped at 40, total 45, truncated true" \
  "40|45|true" \
  "$(bash "$BDR" "$DEN_TMP/noresult-many.json" true 2>/dev/null | "$DEN_JQ" -r '"\(.commands|length)|\(.total)|\(.truncated)"')"
# ...and the 500-char per-command cap with the extractor's exact suffix. Needs its OWN
# fixture: $_LONGCMD is deliberately under 500 (it exists to prove the ungranted head in
# its TAIL survives), so reusing it here would assert the cap against an uncapped string.
"$DEN_JQ" -n '{permission_denials:[{tool_name:"Bash",tool_input:{command:(("A"*600) + " | paste -sd, -")}}]}' \
  > "$DEN_TMP/noresult-long.json"
# Measure with jq's `length` (codepoints), never bash ${#var}: the suffix carries a
# multi-byte U+2026, so ${#var} would count 527 bytes in a C locale and 525 chars in a
# UTF-8 one — green at one desk, red on another runner.
assert_eq "denial record (no result event): per-command 500-char cap + the extractor's suffix" \
  "525|yes" \
  "$(bash "$BDR" "$DEN_TMP/noresult-long.json" true 2>/dev/null | "$DEN_JQ" -r '.commands[0] | "\(length)|\(if endswith(" …[per-command-truncated]") then "yes" else "no" end)"')"
# The key still gates the recovered text: disabled → count + tool_name kept, text absent.
assert_eq "denial record (no result event): key disabled still suppresses the recovered text" \
  "disabled|null" \
  "$(bash "$BDR" "$DEN_TMP/noresult.json" false 2>/dev/null | "$DEN_JQ" -r '"\(.commands_state)|\(.commands)"')"

# ── AC2: unparseable file → count 'unavailable' (never 0), never a fabricated record.
printf 'not json at all {[' > "$DEN_TMP/garbage.json"
REC_BAD="$(bash "$BDR" "$DEN_TMP/garbage.json" true)"
assert_eq "denial record: unparseable file → count 'unavailable' (unknown-is-not-zero)" \
  "unavailable" "$(printf '%s' "$REC_BAD" | "$DEN_JQ" -r '.count')"

# ── AC2: absent file → NO record emitted at all (no run observed).
REC_ABSENT="$(bash "$BDR" "$DEN_TMP/does-not-exist.json" true)"
assert_eq "denial record: absent execution file → empty output, exit 0" \
  "empty-0" "$([ -z "$REC_ABSENT" ] && echo "empty-$?" || echo "nonempty")"

# ── AC4: scrub fails closed when sed cannot run — build emits NOTHING for a run that
# WOULD persist command text. Shadow `sed` with a failing stub (keep the real PATH so
# jq/bash still resolve, isolating the sed-unavailable arm specifically).
mkdir -p "$DEN_TMP/sedbin"
printf '#!/usr/bin/env bash\nexit 1\n' > "$DEN_TMP/sedbin/sed"
chmod +x "$DEN_TMP/sedbin/sed"
REC_NOSED="$(PATH="$DEN_TMP/sedbin:$PATH" bash "$BDR" "$DEN_TMP/exec.json" true 2>/dev/null)"
assert_eq "denial record: scrub-unavailable (sed fails) → fail-closed, no record" \
  "empty" "$([ -z "$REC_NOSED" ] && echo empty || echo nonempty)"
# scrub-credentials.sh itself: redacts a token, and --shapes prints the caveat.
assert_eq "scrub-credentials: redacts a gh token" \
  "yes" "$(printf 'x ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ012345 y' | bash "$SCR" | grep -qF 'REDACTED-GH-TOKEN' && echo yes || echo no)"
assert_eq "scrub-credentials: --shapes names four shapes" \
  "yes" "$(bash "$SCR" --shapes | grep -qF 'GitHub tokens/PATs' && echo yes || echo no)"

# ── #1915 round trip: keep all four shapes in one document and keep the trailing-slash
# case — narrowing either fixture lets the Authorization bracket expressions regress to
# corrupting the bytes around a token while this block still reports green.
_SCRUB_RAW='tok ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ012345 pat github_pat_ABCDEFGHIJKLMNOPQRSTUV ant sk-ant-ABCDEFGHIJKLMNOPQRSTUV hdr "AUTHORIZATION: basic T0xENEM=" and "Authorization: Bearer abc.def-ghi~jkl+mno/pqr=" end'
_SCRUB_WANT='tok [REDACTED-GH-TOKEN] pat [REDACTED-GH-PAT] ant [REDACTED-ANTHROPIC-KEY] hdr "AUTHORIZATION: basic [REDACTED]" and "Authorization: Bearer [REDACTED]" end'
_SCRUB_IN="$("$DEN_JQ" -n -c --arg v "$_SCRUB_RAW" '{note:$v}')"
_SCRUB_EXPECT="$("$DEN_JQ" -n -c --arg v "$_SCRUB_WANT" '{note:$v}')"
_SCRUB_OUT="$(printf '%s\n' "$_SCRUB_IN" | bash "$SCR")"
assert_eq "scrub-credentials (#1915): scrubbed JSON carrying all four shapes still parses" \
  "yes" "$(printf '%s\n' "$_SCRUB_OUT" | "$DEN_JQ" -e . >/dev/null 2>&1 && echo yes || echo no)"
assert_eq "scrub-credentials (#1915): only the credential tokens changed, every other byte identical" \
  "$_SCRUB_EXPECT" "$_SCRUB_OUT"
assert_eq "scrub-credentials (#1915): a recorded sed command keeps its trailing slashes" \
  "run: sed 's/AUTHORIZATION: basic //' file" \
  "$(printf '%s\n' "run: sed 's/AUTHORIZATION: basic //' file" | bash "$SCR")"
# An escape unit belongs to the token in the Bearer rule and in the basic rule alike: narrowing
# either group to plain class members would truncate the match at the escape and emit the rest of
# a live credential. Each fixture leads with enough class members to yield that truncation.
assert_eq "scrub-credentials (#1915): Bearer token with an escaped slash is fully redacted" \
  'Authorization: Bearer [REDACTED]' \
  "$(printf '%s\n' 'Authorization: Bearer AAAABBBB\/SECRETTAIL9999' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): basic token with an escaped slash is fully redacted" \
  'AUTHORIZATION: basic [REDACTED]' \
  "$(printf '%s\n' 'AUTHORIZATION: basic AAAABBBB\/SECRETTAIL9999' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): Bearer token with an escaped backslash is fully redacted" \
  'Authorization: Bearer [REDACTED]' \
  "$(printf '%s\n' 'Authorization: Bearer AAAABBBB\\SECRETTAIL9999' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): basic token with an escaped backslash is fully redacted" \
  'AUTHORIZATION: basic [REDACTED]' \
  "$(printf '%s\n' 'AUTHORIZATION: basic AAAABBBB\\SECRETTAIL9999' | bash "$SCR")"
# The four-unit floor is the redaction boundary in the Bearer rule and in the basic rule alike:
# relaxing either back to `+` resumes eating the bare `//` of a recorded command, and raising
# either starts leaking short credentials.
assert_eq "scrub-credentials (#1915): a three-unit basic run is below the floor and left alone" \
  'AUTHORIZATION: basic ab=' \
  "$(printf '%s\n' 'AUTHORIZATION: basic ab=' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): a four-unit basic token is at the floor and redacted" \
  'AUTHORIZATION: basic [REDACTED]' \
  "$(printf '%s\n' 'AUTHORIZATION: basic abc=' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): a two-unit Bearer run is below the floor and left alone" \
  "run: sed 's/Authorization: Bearer //' file" \
  "$(printf '%s\n' "run: sed 's/Authorization: Bearer //' file" | bash "$SCR")"
assert_eq "scrub-credentials (#1915): a four-unit Bearer token is at the floor and redacted" \
  'Authorization: Bearer [REDACTED]' \
  "$(printf '%s\n' 'Authorization: Bearer abc=' | bash "$SCR")"
# Match the scheme keyword per letter, as the header name already is: narrowing it back to a
# case-sensitive tail lets a third-party emitter's uppercase scheme carry a whole credential
# through into a published transcript.
assert_eq "scrub-credentials (#1915): an uppercase BASIC scheme keyword is redacted" \
  'AUTHORIZATION: basic [REDACTED]' \
  "$(printf '%s\n' 'AUTHORIZATION: BASIC dXNlcjpwYXNz' | bash "$SCR")"
assert_eq "scrub-credentials (#1915): an uppercase BEARER scheme keyword is redacted" \
  'AUTHORIZATION: Bearer [REDACTED]' \
  "$(printf '%s\n' 'AUTHORIZATION: BEARER abcdefghijklmnop' | bash "$SCR")"

# ── AC6: the default-on key's off-switch decision (the workflow's builtin `case`). The
# decision is `false → off; everything else → on`. Drive config-get.sh over each shape
# and apply the SAME case, asserting exit 0 + the enabled/disabled result. `0`/`""` are
# documented safe-direction residuals (they read ENABLED); a real `false` DISABLES.
DEN_CFG="$(mktemp -d)"; mkdir -p "$DEN_CFG/.prflow"
CG1064="$LIB/../scripts/config-get.sh"
_key_decision() {  # $1 = the JSON value literal for the key
  printf '{"prflow":{"execution_denial_commands_enabled":%s}}' "$1" > "$DEN_CFG/.prflow/config.json"
  local raw dec
  raw="$(bash "$CG1064" .prflow.execution_denial_commands_enabled true "$DEN_CFG/.prflow/config.json" || true)"
  case "$raw" in false) dec=off ;; *) dec=on ;; esac
  printf '%s\n' "$dec"
}
assert_eq "denial key: explicit false → off (off switch works)" "off" "$(_key_decision false)"
assert_eq "denial key: true → on"                               "on"  "$(_key_decision true)"
assert_eq "denial key: 0 → on (documented safe-direction residual)"  "on" "$(_key_decision 0)"
assert_eq "denial key: \"\" → on (documented safe-direction residual)" "on" "$(_key_decision '""')"

# ── D2: build-experiment-records._denials_from_eff restores the count producer #936
# removed — reading the telemetry record's permission_denials.count (verbatim, three-way).
DEN_PY="$(python3 - "$LIB/../scripts/build-experiment-records.py" <<'PY'
import importlib.util, sys
spec = importlib.util.spec_from_file_location("ber", sys.argv[1])
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
f = m._denials_from_eff
out = []
out.append(str(f([{"permission_denials": {"count": 5}}]) == (5, "efficiency-record")))
out.append(str(f([{"permission_denials": {"count": "unavailable"}}]) == ("unavailable", "efficiency-record")))
out.append(str(f([{"permission_denials": {"count": 0}}]) == (0, "efficiency-record")))
out.append(str(f([{"harness_cost": {}}]) == (None, None)))       # no denial object → fall back
out.append(str(f([]) == (None, None)))
# a real number beats an unavailable in an earlier run
out.append(str(f([{"permission_denials": {"count": "unavailable"}}, {"permission_denials": {"count": 2}}]) == (2, "efficiency-record")))
print("|".join(out))
PY
)"
assert_eq "build-experiment-records._denials_from_eff: verbatim 3-way count restore (#1064 D2)" \
  "True|True|True|True|True|True" "$DEN_PY"

# ── D4/AC8: scrub-transcript.sh arms — the transcript channel's scrub/gate/caveat/
# fail-closed SELECTION lives in the helper, not inline. Drive each arm.
STX="$LIB/../scripts/scrub-transcript.sh"
printf '%s\n' 'line with ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ012345 token' > "$DEN_TMP/tr-in.json"
STX_OK="$(bash "$STX" "$DEN_TMP/tr-in.json" "$DEN_TMP/tr-out.json" 2>/dev/null)"
assert_eq "scrub-transcript: present+scrubbable → advertises path= on stdout" \
  "yes" "$(printf '%s' "$STX_OK" | grep -q "^path=$DEN_TMP/tr-out.json\$" && echo yes || echo no)"
assert_eq "scrub-transcript: output scrubbed (token gone) + caveat header prepended" \
  "yes" "$([ -s "$DEN_TMP/tr-out.json" ] && ! grep -qF 'ghp_ABCDEF' "$DEN_TMP/tr-out.json" && head -1 "$DEN_TMP/tr-out.json" | grep -qF 'DEVFLOW SCRUB CAVEAT' && echo yes || echo no)"
# absent file → no path advertised, exit 0.
STX_ABS="$(bash "$STX" "$DEN_TMP/nope.json" "$DEN_TMP/tr-abs.json" 2>/dev/null)"
assert_eq "scrub-transcript: absent execution file → no path advertised (fail-closed)" \
  "empty" "$([ -z "$STX_ABS" ] && echo empty || echo nonempty)"
# empty file → no path advertised (nothing worth uploading).
: > "$DEN_TMP/tr-empty.json"
STX_EMPTY="$(bash "$STX" "$DEN_TMP/tr-empty.json" "$DEN_TMP/tr-eout.json" 2>/dev/null)"
assert_eq "scrub-transcript: empty execution file → no path advertised" \
  "empty" "$([ -z "$STX_EMPTY" ] && echo empty || echo nonempty)"
# scrub fails (sed stub non-zero) → no path advertised, no unscrubbed upload.
STX_NOSED="$(PATH="$DEN_TMP/sedbin:$PATH" bash "$STX" "$DEN_TMP/tr-in.json" "$DEN_TMP/tr-fc.json" 2>/dev/null)"
assert_eq "scrub-transcript: scrub-unavailable (sed fails) → no path advertised (fail-closed)" \
  "empty" "$([ -z "$STX_NOSED" ] && echo empty || echo nonempty)"

rm -rf "$DEN_TMP" "$DEN_CFG"

# ────────────────────────────────────────────────────────────────────────────
echo "install.sh: prune_stale_devflow_workflows"
# ────────────────────────────────────────────────────────────────────────────
# On upgrade, install.sh must remove DevFlow's OWN superseded claude*.yml but
# NEVER an Anthropic-owned claude.yml. Source the installer with
# DEVFLOW_SELFTEST=1 (defines the functions, skips the installer body) and run
# the prune function against throwaway repos.
INSTALL="$LIB/../install.sh"

# Case A: DevFlow-signed claude.yml + stale runner/implement → all removed.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.github/workflows"
printf '%s\n' "name: Claude Code" "  review_dedupe:" > "$WORK/.github/workflows/claude.yml"
echo "name: Claude Runner (reusable)" > "$WORK/.github/workflows/claude-runner.yml"
echo "name: Claude Code (implement)" > "$WORK/.github/workflows/claude-implement.yml"
# shellcheck disable=SC1090  # sources install.sh at runtime under DEVFLOW_SELFTEST
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_devflow_workflows ) >/dev/null 2>&1
assert_eq "install: devflow-signed claude.yml removed" \
  "absent" "$([ -f "$WORK/.github/workflows/claude.yml" ] && echo present || echo absent)"
assert_eq "install: stale claude-runner.yml removed" \
  "absent" "$([ -f "$WORK/.github/workflows/claude-runner.yml" ] && echo present || echo absent)"
assert_eq "install: stale claude-implement.yml removed" \
  "absent" "$([ -f "$WORK/.github/workflows/claude-implement.yml" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case B: Anthropic's own claude.yml (no DevFlow signature) → preserved.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.github/workflows"
printf '%s\n' "name: Claude Code" "  claude:" "    uses: anthropics/claude-code-action@v1" \
  > "$WORK/.github/workflows/claude.yml"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_devflow_workflows ) >/dev/null 2>&1
assert_eq "install: Anthropic claude.yml preserved" \
  "present" "$([ -f "$WORK/.github/workflows/claude.yml" ] && echo present || echo absent)"
rm -rf "$WORK"

# ────────────────────────────────────────────────────────────────────────────
echo "install.sh: prune_stale_vendored_plugin"
# ────────────────────────────────────────────────────────────────────────────
# On upgrade, install.sh must remove a stale committed plugin at the OLD
# .claude/plugins/devflow location (relocated to .prflow/vendor/prflow), but
# ONLY when it is actually DevFlow's plugin, and must never remove a non-empty
# user .claude/ directory.

# Case A: a DevFlow-signed tree at the old path → removed, empty parents pruned.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.claude/plugins/devflow/.claude-plugin"
printf '{"name":"devflow"}' > "$WORK/.claude/plugins/devflow/.claude-plugin/plugin.json"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_vendored_plugin ) >/dev/null 2>&1
assert_eq "install: stale committed .claude/plugins/devflow removed" \
  "absent" "$([ -d "$WORK/.claude/plugins/devflow" ] && echo present || echo absent)"
assert_eq "install: emptied .claude/ pruned" \
  "absent" "$([ -d "$WORK/.claude" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case B: a non-DevFlow plugin.json at that path → preserved (signature guard).
WORK="$(mktemp -d)"; mkdir -p "$WORK/.claude/plugins/devflow/.claude-plugin"
printf '{"name":"not-devflow"}' > "$WORK/.claude/plugins/devflow/.claude-plugin/plugin.json"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_vendored_plugin ) >/dev/null 2>&1
assert_eq "install: non-devflow .claude/plugins/devflow preserved" \
  "present" "$([ -d "$WORK/.claude/plugins/devflow" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case C: DevFlow tree removed but a non-empty .claude/ (other content) is kept.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.claude/plugins/devflow/.claude-plugin" "$WORK/.claude/skills"
printf '{"name":"devflow"}' > "$WORK/.claude/plugins/devflow/.claude-plugin/plugin.json"
printf 'x' > "$WORK/.claude/skills/keep.md"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_vendored_plugin ) >/dev/null 2>&1
assert_eq "install: devflow tree removed under non-empty .claude" \
  "absent" "$([ -d "$WORK/.claude/plugins/devflow" ] && echo present || echo absent)"
assert_eq "install: emptied .claude/plugins parent pruned, non-empty .claude kept" \
  "absent-present" "$([ -d "$WORK/.claude/plugins" ] && echo present || echo absent)-$([ -d "$WORK/.claude" ] && echo present || echo absent)"
assert_eq "install: non-empty user .claude/ preserved" \
  "present" "$([ -f "$WORK/.claude/skills/keep.md" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case D: no old tree at all (the common thin-install path) → clean no-op, exit 0,
# and an unrelated .claude/ is untouched.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.claude/skills"; printf 'x' > "$WORK/.claude/skills/keep.md"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_vendored_plugin ) >/dev/null 2>&1
assert_eq "install: prune is a clean no-op when no old tree exists" "0" "$?"
assert_eq "install: prune leaves unrelated .claude/ untouched when no old tree" \
  "present" "$([ -f "$WORK/.claude/skills/keep.md" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case E: old dir exists but carries no devflow plugin.json (partial/interrupted
# install) → left in place (not blindly removed), exit 0.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.claude/plugins/devflow/scripts"
printf 'x' > "$WORK/.claude/plugins/devflow/scripts/stray.sh"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && prune_stale_vendored_plugin ) >/dev/null 2>&1
assert_eq "install: unsigned old tree is a clean exit" "0" "$?"
assert_eq "install: unsigned old tree is left untouched" \
  "present" "$([ -d "$WORK/.claude/plugins/devflow" ] && echo present || echo absent)"
rm -rf "$WORK"

# ────────────────────────────────────────────────────────────────────────────
echo "install.sh: manage_vendor_gitignore"
# ────────────────────────────────────────────────────────────────────────────
# Thin installs must ignore the runtime-vendored .prflow/vendor/ tree so a
# cloud run's `git add -A` never commits it; DEVFLOW_VENDOR=1 commits it on
# purpose, so the ignore line must be absent there. Patterns are relative to
# .prflow/, matching the scaffolded `/tmp/` entry.

# Case A: thin install (DEVFLOW_VENDOR unset) → /vendor/ appended, /tmp/ kept.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.prflow"; printf '/tmp/\n' > "$WORK/.prflow/.gitignore"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: thin install ignores /vendor/" \
  "yes" "$(grep -qxF '/vendor/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
assert_eq "install: thin install keeps /tmp/" \
  "yes" "$(grep -qxF '/tmp/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
# Idempotent: a second run does not duplicate the line.
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: thin /vendor/ ignore is idempotent" \
  "1" "$(grep -cxF '/vendor/' "$WORK/.prflow/.gitignore")"
rm -rf "$WORK"

# Case B: DEVFLOW_VENDOR=1 → a previously-added /vendor/ line is removed, /tmp/ kept.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.prflow"; printf '/tmp/\n/vendor/\n' > "$WORK/.prflow/.gitignore"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && DEVFLOW_VENDOR=1 manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: DEVFLOW_VENDOR=1 un-ignores /vendor/" \
  "no" "$(grep -qxF '/vendor/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
assert_eq "install: DEVFLOW_VENDOR=1 keeps /tmp/" \
  "yes" "$(grep -qxF '/tmp/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
rm -rf "$WORK"

# Case C: no scaffolded .gitignore → no-op, no crash (exit 0).
WORK="$(mktemp -d)"; mkdir -p "$WORK/.prflow"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: missing .gitignore is a clean no-op" \
  "0" "$?"
assert_eq "install: no .gitignore created when absent" \
  "absent" "$([ -f "$WORK/.prflow/.gitignore" ] && echo present || echo absent)"
rm -rf "$WORK"

# Case D: DEVFLOW_VENDOR=1 when /vendor/ is already absent → steady-state no-op,
# /tmp/ kept (symmetric to the thin-side idempotency check above).
WORK="$(mktemp -d)"; mkdir -p "$WORK/.prflow"; printf '/tmp/\n' > "$WORK/.prflow/.gitignore"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && DEVFLOW_VENDOR=1 manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: DEVFLOW_VENDOR=1 with /vendor/ already absent keeps it absent" \
  "no" "$(grep -qxF '/vendor/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
assert_eq "install: DEVFLOW_VENDOR=1 steady-state keeps /tmp/" \
  "yes" "$(grep -qxF '/tmp/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
rm -rf "$WORK"

# Case E: DEVFLOW_VENDOR=1 when /vendor/ is the ONLY line (the empty-filter edge
# the grep-exit-1 handling exists for) → removed cleanly, file left empty, exit 0.
WORK="$(mktemp -d)"; mkdir -p "$WORK/.prflow"; printf '/vendor/\n' > "$WORK/.prflow/.gitignore"
# shellcheck disable=SC1090
( cd "$WORK" && DEVFLOW_SELFTEST=1 . "$INSTALL" && DEVFLOW_VENDOR=1 manage_vendor_gitignore ) >/dev/null 2>&1
assert_eq "install: DEVFLOW_VENDOR=1 removes /vendor/ when it is the only line" "0" "$?"
assert_eq "install: only-line /vendor/ removal leaves no /vendor/" \
  "no" "$(grep -qxF '/vendor/' "$WORK/.prflow/.gitignore" && echo yes || echo no)"
rm -rf "$WORK"

# ────────────────────────────────────────────────────────────────────────────
echo "no stale .claude/plugins/devflow reference in shipped cloud-tier files"
# ────────────────────────────────────────────────────────────────────────────
# Locks the invariant this relocation establishes: the runtime-vendored plugin
# lives at .prflow/vendor/prflow, so no workflow, composite action, or config
# schema may reference the old .claude/plugins/devflow path (a stale reference
# fails closed at runtime — "resolver not found" / wiped plugin). install.sh and
# the test file are not in the scan scope (it covers only `.github` +
# config.schema.json) — they legitimately name the old path (the prune migration
# that removes it, and these tests), and there is no exclusion filter to maintain.
# NB: no `xargs -r` — that flag is GNU-only (BSD/macOS xargs rejects it), and
# CONTRIBUTING bans GNU-only flags. The `git ls-files` input is always non-empty
# (.prflow/config.schema.json + the .github workflows are tracked), so the
# no-run-if-empty behavior `-r` provides is never needed here.
STALE=$(cd "$LIB/.." && git ls-files .github .prflow/config.schema.json \
  | xargs grep -lF '.claude/plugins/devflow' 2>/dev/null || true)
assert_eq "install: no shipped cloud-tier file references the old vendored path" \
  "" "$STALE"

# The generated marketplace.json `source` is the one path-bearing installer
# output with no other coverage; a heredoc typo reverting it would ship to fresh
# consumers uncaught. Assert it matches the relocated vendor destination.
assert_eq "install: marketplace.json source matches the vendored path" \
  "1" "$(grep -cF '"source": "./.prflow/vendor/prflow"' "$LIB/../install.sh")"

# The generated marketplace.json must mirror the repo-root manifest's #142
# zero-companion-dependency shape: the allowlist key is retained but empty.
# A future edit reintroducing "claude-plugins-official" (or any non-empty
# allowlist) drops this literal's count to 0 and turns the pin RED, so the
# stale cross-marketplace dependency can never ship to a fresh consumer again.
assert_eq "install: marketplace.json allowCrossMarketplaceDependenciesOn is empty (#142/#385)" \
  "1" "$(grep -cF '"allowCrossMarketplaceDependenciesOn": []' "$LIB/../install.sh")"

# ────────────────────────────────────────────────────────────────────────────
echo "workflow partition invariant"
# ────────────────────────────────────────────────────────────────────────────
# Every gate `if:` line that matches a /devflow: command trigger must ALSO
# negate @claude on that same line, so no comment can fire both a DevFlow
# workflow and Anthropic's claude.yml. Covers devflow.yml (review/pr-description)
# and devflow-implement.yml (/devflow:implement).
WF="$LIB/../.github/workflows"
# The scanned namespace set is DERIVED from the declared plugin identity, never
# hardcoded: a guard spelling one namespace gives zero assurance for the other, and
# goes fully vacuous the moment the transitional namespace is retired. Built with
# bash builtins (no `tr`/`cut`) because it SELECTS what gets scanned — a missing
# non-preflight PATH tool would silently empty it and pass by inspecting nothing.
SUITE_CMD_NS=""
while IFS= read -r _cmd_ns; do
  case "$_cmd_ns" in
    "" ) : ;;
    *) SUITE_CMD_NS="$SUITE_CMD_NS $_cmd_ns" ;;
  esac
done <<EOF
$(python3 "$LIB/plugin_identity.py" --plugin-names 2>/dev/null || true)
EOF
case "$SUITE_CMD_NS" in
  *[!\ ]*) : ;;
  *) echo "run.sh: could not derive the accepted command namespaces from lib/plugin_identity.py; refusing to run rather than assert the partition invariant against an empty namespace set" >&2; exit 1 ;;
esac
for f in devflow devflow-implement; do
  for ns in $SUITE_CMD_NS; do
    # NON-VACUITY FIRST: the scan must actually match trigger lines for THIS
    # namespace. Without this, dropping the namespace from the workflow turns the
    # @claude assertion below into a check over an empty set — it would pass by
    # inspecting nothing, which is the exact failure class this guard exists to catch.
    hits="$(grep -cE "contains\((github\.event[^)]*),[[:space:]]*'/$ns:(review|pr-description|implement)'\)" "$WF/$f.yml" || true)"
    assert_eq "partition: $f.yml carries at least one /$ns: command trigger (guard is non-vacuous)" \
      "yes" "$([ "${hits:-0}" -gt 0 ] && echo yes || echo no)"
    bad="$(grep -nE "contains\((github\.event[^)]*),[[:space:]]*'/$ns:(review|pr-description|implement)'\)" "$WF/$f.yml" \
          | grep -v "@claude" || true)"
    assert_eq "partition: $f.yml /$ns triggers all negate @claude" "" "$bad"
  done
done

# ── devflow.yml TRIGGER-GATE coverage (#965 review, Important 1) ─────────────
# The gate `if:` is upstream of every resolver the dsc:/rct: suites cover — those
# exercise detect-standalone-command.sh / resolve-command-trigger.sh, which only
# ever run AFTER this gate has already decided to start the workflow. So both
# halves of the namespace widening were previously untested, and both fail SILENTLY:
#   * drop /prflow:review from the positive set -> canonical review comments never
#     trigger the workflow at all (no run, no error, nothing to notice);
#   * drop the /prflow:implement negation -> a /prflow:implement comment fires BOTH
#     devflow.yml and devflow-implement.yml, breaking the partition invariant.
# Asserted per-clause over the gate's event arm(s). Issue #1163 removed the two
# pull_request_review* subscriptions, so the gate now carries a SINGLE event clause
# (issue_comment); the per-clause form is retained (rather than collapsed) so a
# future re-subscription that re-adds an event arm is still audited arm-by-arm.
GATE_YML="$WF/devflow.yml"
# Echoes the gate clause lines that do NOT match $2 — empty means every clause carries it.
gate_clauses_missing() {  # $1=file $2=ERE every gate clause must match
  grep -nE "github\.event_name == '" "$1" | grep -vE "$2" || true
}
GATE_CLAUSE_COUNT="$(grep -cE "github\.event_name == '" "$GATE_YML" || true)"
assert_eq "trigger-gate: devflow.yml gate carries the sole issue_comment event clause" "1" "$GATE_CLAUSE_COUNT"
# Half 1 — the POSITIVE set accepts the canonical namespace on every clause.
assert_eq "trigger-gate: every devflow.yml clause accepts /prflow:review" \
  "" "$(gate_clauses_missing "$GATE_YML" "contains\([^)]*'/prflow:review'\)")"
assert_eq "trigger-gate: every devflow.yml clause accepts /prflow:pr-description" \
  "" "$(gate_clauses_missing "$GATE_YML" "contains\([^)]*'/prflow:pr-description'\)")"
# Half 2 — the EXCLUSION set negates the canonical heavy path on every clause.
assert_eq "trigger-gate: every devflow.yml clause EXCLUDES /prflow:implement" \
  "" "$(gate_clauses_missing "$GATE_YML" "!contains\([^)]*'/prflow:implement'\)")"
# The transitional namespace stays covered on both halves for the alias window.
assert_eq "trigger-gate: every devflow.yml clause accepts /devflow:review" \
  "" "$(gate_clauses_missing "$GATE_YML" "contains\([^)]*'/devflow:review'\)")"
assert_eq "trigger-gate: every devflow.yml clause EXCLUDES /devflow:implement" \
  "" "$(gate_clauses_missing "$GATE_YML" "!contains\([^)]*'/devflow:implement'\)")"
# PLANTED-DEFECT CONTROLS: each assertion above must actually RED on the defect it
# claims to catch. A green row over an expression that can no longer match proves
# nothing, so each control first asserts the mutation really changed the file.
TG_TMP="$(mktemp -d)"
# Control A — the positive half: break the /prflow:review disjunct.
sed "s|contains(github.event.comment.body, '/prflow:review')|contains(github.event.comment.body, '/planted:review')|g" \
  "$GATE_YML" > "$TG_TMP/no-positive.yml"
assert_eq "trigger-gate CONTROL A: the positive-half mutation really changed the gate" \
  "no" "$(cmp -s "$GATE_YML" "$TG_TMP/no-positive.yml" && echo yes || echo no)"
assert_eq "trigger-gate CONTROL A: dropping /prflow:review from a clause turns the positive check RED" \
  "yes" "$([ -n "$(gate_clauses_missing "$TG_TMP/no-positive.yml" "contains\([^)]*'/prflow:review'\)")" ] && echo yes || echo no)"
# Control B — the exclusion half: remove the /prflow:implement negation (the double-fire).
sed "s| && !contains(github.event.comment.body, '/prflow:implement')||g" \
  "$GATE_YML" > "$TG_TMP/no-negation.yml"
assert_eq "trigger-gate CONTROL B: the exclusion-half mutation really changed the gate" \
  "no" "$(cmp -s "$GATE_YML" "$TG_TMP/no-negation.yml" && echo yes || echo no)"
assert_eq "trigger-gate CONTROL B: dropping the /prflow:implement negation turns the exclusion check RED" \
  "yes" "$([ -n "$(gate_clauses_missing "$TG_TMP/no-negation.yml" "!contains\([^)]*'/prflow:implement'\)")" ] && echo yes || echo no)"
# Control C — the extractor itself is not matching everything: a token absent from
# every clause must be reported missing on every clause, so an always-empty result
# (which would make every row above vacuously green) is ruled out. With the sole
# issue_comment clause the expected count is 1 (it was 3 before issue #1163 removed
# the two review-event clauses).
assert_eq "trigger-gate CONTROL C: a token no clause carries is reported missing on the sole clause" \
  "1" "$(gate_clauses_missing "$GATE_YML" "contains\([^)]*'/nosuchns:review'\)" | grep -c . || true)"
rm -rf "$TG_TMP"

# The label trigger is gone: neither workflow may listen on `labeled`.
for f in devflow devflow-implement; do
  bad="$(grep -nE "^[[:space:]]*types:.*labeled" "$WF/$f.yml" || true)"
  assert_eq "partition: $f.yml has no labeled trigger" "" "$bad"
done

# Comment-only triggers: a /devflow:* phrase in an issue/PR DESCRIPTION must
# never start a run. Neither workflow may (a) listen on the `issues` event, nor
# (b) match the trigger phrase against an issue body/title in its gate `if:`.
# Only real comment bodies are valid trigger sources (issue #1163 dropped the
# light path's two review-triggered subscriptions, so no gate reads
# `github.event.review.body` any more).
for f in devflow devflow-implement; do
  bad="$(grep -nE "^[[:space:]]*issues:[[:space:]]*$" "$WF/$f.yml" || true)"
  assert_eq "partition: $f.yml does not listen on the issues event" "" "$bad"
  # No gate matching against issue.body / issue.title (those are descriptions).
  bad="$(grep -nE "contains\(github\.event\.issue\.(body|title)" "$WF/$f.yml" || true)"
  assert_eq "partition: $f.yml gate never matches an issue body/title" "" "$bad"
  # TRIGGER_TEXT must be sourced only from comment bodies.
  bad="$(grep -nE "TRIGGER_TEXT:.*github\.event\.issue\.(body|title)" "$WF/$f.yml" || true)"
  assert_eq "partition: $f.yml TRIGGER_TEXT excludes issue body/title" "" "$bad"
done

# Issues-only scoping of the HEAVY path (issue #124). The primary defense lives
# in the workflow, not just the resolver unit tests above — so pin it here, or a
# future workflow edit could silently reopen #124 (a PR comment is also an
# issue_comment, so the audit-report comment self-triggers on the state PR) while
# the resolver-only tests stay green.
IMPL="$WF/devflow-implement.yml"
# (a) The heavy path must NOT subscribe to the PR-only review events at all.
assert_eq "partition: devflow-implement.yml is issues-only (no PR-review subscriptions)" \
  "0" "$(grep -cE 'pull_request_review(_comment)?:' "$IMPL")"
# (a+) Positive complement to (a): the heavy path MUST still subscribe to
#      issue_comment — its SOLE event entry point now. (a) is a negative check, so
#      without this a future edit that DELETES or renames the issue_comment
#      subscription would make the whole heavy path silently inert
#      (/devflow:implement never fires on any thread) while (a) still reads 0 and
#      every other test stays green — the over-narrowing twin of the bug (a) guards.
assert_eq "partition: devflow-implement.yml subscribes to issue_comment (sole event entry point)" \
  "1" "$(grep -cE '^[[:space:]]*issue_comment:[[:space:]]*$' "$IMPL")"
# (b) The gate if: must carry the PR-context filter (comment is on an issue, not
#     a PR). Match the gate-conjunct form (trailing ` &&`) so the prose mention of
#     the same expression in the header comment isn't counted.
assert_eq "partition: devflow-implement.yml gate if: filters PR comments (issue.pull_request == null)" \
  "1" "$(grep -cF 'github.event.issue.pull_request == null &&' "$IMPL")"
# (c) The resolver backstop is only wired if the workflow passes IS_PULL_REQUEST
#     from the canonical discriminator; a wrong expression (e.g. == null) would
#     invert the guard and decline issues instead of PRs.
assert_eq "partition: devflow-implement.yml wires IS_PULL_REQUEST from issue.pull_request != null" \
  "1" "$(grep -cF 'IS_PULL_REQUEST: ${{ github.event.issue.pull_request != null }}' "$IMPL")"
# (d) Issue #1163 SUPERSEDES the earlier "stays PR-aware" decision. That decision
#     kept devflow.yml subscribed to pull_request_review[submitted] and
#     pull_request_review_comment[created] so /prflow:review and /prflow:pr-description
#     could be requested from the review-submission box and inline diff comments. But
#     on those two events GITHUB_REF resolves to refs/pull/N/merge, so every job
#     checked out PR-author content — including the config job's authorization inputs
#     and the agent's tool grants. The light path is now issue_comment-only (a review
#     requested by commenting on the PR conversation is an issue_comment and still
#     works); the review-submission-box and inline-diff-comment paths are dropped.
#     So devflow.yml must carry NO pull_request_review* subscription, mirroring the
#     heavy path's (a) above.
assert_eq "partition: devflow.yml has no PR-review subscriptions (issue #1163 superseded the earlier stays-PR-aware decision)" \
  "0" "$(grep -cE 'pull_request_review(_comment)?:' "$WF/devflow.yml")"
# (d+) Positive complement to (d): devflow.yml MUST still subscribe to issue_comment —
#      its SOLE event entry point now. Without this a future edit deleting the
#      issue_comment subscription would make the whole light path silently inert while
#      (d) still reads 0 and every other test stays green (the over-narrowing twin of
#      the bug (d) guards — same shape as the heavy path's (a+) above).
assert_eq "partition: devflow.yml subscribes to issue_comment (sole event entry point)" \
  "1" "$(grep -cE '^[[:space:]]*issue_comment:[[:space:]]*$' "$WF/devflow.yml")"
# (e) Issue #1163's OTHER half: every actions/checkout step in devflow.yml pins
#     `ref:` to the default branch. Dropping the subscriptions (d) makes the
#     trigger resolve GITHUB_REF to the default branch, but the pin is what states
#     that property in the file, so a future re-subscription cannot silently
#     reinstate a PR-head checkout of the authorization inputs and tool grants.
#     Asserted STRUCTURALLY — per checkout step, not as a whole-file count — so
#     all three regressions are caught: a dropped pin, an added unpinned fifth
#     checkout, and a pin rewritten with a `||` fallback (an empty `ref` makes
#     actions/checkout fall back to GITHUB_REF) or a literal branch name (a
#     consumer's default branch may not be `main`). Emits one `<line> <ref>` row
#     per checkout step; a step with no `ref:` in its `with:` block emits NONE.
#     Comment lines are skipped so the header prose quoting the expression is not
#     mistaken for wiring, and the row is flushed at the next step boundary so the
#     sibling `- uses: ./.github/actions/vendor-plugin` step's own
#     `ref: ${{ needs.config.outputs.prflow_version }}` is never attributed to a
#     checkout. The `uses:` match accepts an optionally quoted value; the step
#     boundary is keyed on this file's uniform 6-space step indentation, which is
#     a deliberate limit rather than an omission — a differently indented step
#     would go unrecognised, and the `count == 4` row above is what fails safe on
#     it (it is an equality, not a floor), which CONTROL D below exercises.
devflow_checkout_ref_rows() {
  awk '
    function flush(   v) {
      if (isck) { v = (refv == "" ? "NONE" : refv); printf "%d %s\n", ln, v }
      isck = 0; refv = ""
    }
    /^[[:space:]]*#/ { next }
    /^      - / { flush(); ln = NR }
    /uses:[[:space:]]*["'"'"']?actions\/checkout@/ { isck = 1 }
    /^[[:space:]]*ref:[[:space:]]*/ {
      if (isck && refv == "") { sub(/^[[:space:]]*ref:[[:space:]]*/, ""); sub(/[[:space:]]+$/, ""); refv = $0 }
    }
    END { flush() }
  ' "$1"
}
devflow_checkout_rows="$(devflow_checkout_ref_rows "$WF/devflow.yml")"
# 5 checkout steps: config, review_dedupe, gate, command, review_finalize (issue #1174).
assert_eq "partition: devflow.yml has exactly 5 actions/checkout steps (issue #1163)" \
  "5" "$(printf '%s\n' "$devflow_checkout_rows" | grep -c . || true)"
# Every one of them pins the default branch verbatim — no fallback, no literal.
devflow_unpinned_checkouts="$(
  printf '%s\n' "$devflow_checkout_rows" \
    | grep -v ' \${{ github\.event\.repository\.default_branch }}$' || true
)"
assert_eq "partition: devflow.yml pins every checkout ref: to the default branch (issue #1163)" \
  "" "$devflow_unpinned_checkouts"
# PLANTED-DEFECT CONTROLS for the auditor above, mirroring the trigger-gate
# CONTROL A/B/C pattern three blocks up. The `count == 4` row backstops only the
# "emits too few rows" mode; without these controls an over-accepting extractor
# (an `isck` that never resets, a reordered `flush()`, a `ref:` capture that
# misses) would leave `devflow_unpinned_checkouts` silently empty while a real
# dropped pin sat in the file. Each control first asserts the mutation really
# changed the file, then asserts the auditor reports the mutated step.
CK_TMP="$(mktemp -d)"
devflow_unpinned_in() {  # $1=file -> the rows the auditor does NOT accept as pinned
  devflow_checkout_ref_rows "$1" \
    | grep -v ' \${{ github\.event\.repository\.default_branch }}$' || true
}
# Control A — a dropped pin. The step must report NONE, and must NOT silently
# inherit the `ref:` of the sibling vendor-plugin step that follows it (the
# isck-never-resets mode).
# NOTE: the first-occurrence-only mutations below use awk, not `sed '0,/re/'` —
# the `0,` address form is a GNU extension that BSD sed (macOS) rejects.
devflow_mutate_first_pin() {  # $1=replacement text, or the empty string to delete the line
  awk -v repl="$1" '
    !done && $0 == "          ref: ${{ github.event.repository.default_branch }}" {
      done = 1
      if (repl != "") print repl
      next
    }
    { print }
  ' "$WF/devflow.yml"
}
devflow_mutate_first_pin "" > "$CK_TMP/dropped-pin.yml"
assert_eq "checkout-pin CONTROL A: the dropped-pin mutation really changed devflow.yml" \
  "no" "$(cmp -s "$WF/devflow.yml" "$CK_TMP/dropped-pin.yml" && echo yes || echo no)"
assert_eq "checkout-pin CONTROL A: a checkout with no ref: is reported unpinned as NONE" \
  "1" "$(devflow_unpinned_in "$CK_TMP/dropped-pin.yml" | grep -c ' NONE$' || true)"
assert_eq "checkout-pin CONTROL A: the dropped-pin file still emits 5 checkout rows" \
  "5" "$(devflow_checkout_ref_rows "$CK_TMP/dropped-pin.yml" | grep -c . || true)"
# Control B — a `||` fallback pin. An empty `ref` makes actions/checkout fall back
# to GITHUB_REF with no error, so the fallback form must be rejected, not accepted.
devflow_mutate_first_pin "          ref: \${{ github.event.repository.default_branch || 'main' }}" \
  > "$CK_TMP/fallback-pin.yml"
assert_eq "checkout-pin CONTROL B: the fallback-pin mutation really changed devflow.yml" \
  "no" "$(cmp -s "$WF/devflow.yml" "$CK_TMP/fallback-pin.yml" && echo yes || echo no)"
assert_eq "checkout-pin CONTROL B: a \`||\` fallback ref: is reported unpinned" \
  "1" "$(devflow_unpinned_in "$CK_TMP/fallback-pin.yml" | grep -c . || true)"
# Control C — a literal branch name, which is wrong for a consumer whose default
# branch is not `main`.
devflow_mutate_first_pin "          ref: main" > "$CK_TMP/literal-pin.yml"
assert_eq "checkout-pin CONTROL C: the literal-branch mutation really changed devflow.yml" \
  "no" "$(cmp -s "$WF/devflow.yml" "$CK_TMP/literal-pin.yml" && echo yes || echo no)"
assert_eq "checkout-pin CONTROL C: a literal branch-name ref: is reported unpinned" \
  "1" "$(devflow_unpinned_in "$CK_TMP/literal-pin.yml" | grep -c ' main$' || true)"
# Control D — an added extra, unpinned checkout must be caught by BOTH rows: the
# count row (which is not merely `>= 5`) and the pin row.
awk 'NR==1{print "      - uses: actions/checkout@v6"} {print}' \
  "$WF/devflow.yml" > "$CK_TMP/fifth-checkout.yml"
assert_eq "checkout-pin CONTROL D: an added extra checkout is counted" \
  "6" "$(devflow_checkout_ref_rows "$CK_TMP/fifth-checkout.yml" | grep -c . || true)"
assert_eq "checkout-pin CONTROL D: an added extra unpinned checkout is reported unpinned" \
  "1" "$(devflow_unpinned_in "$CK_TMP/fifth-checkout.yml" | grep -c ' NONE$' || true)"
rm -rf "$CK_TMP"

# ── review_finalize must MATERIALIZE the plugin (issue #1174). Every helper-consuming
# job runs the vendor-plugin action after its checkout; without it a thin-install
# consumer's bare checkout has no .prflow/vendor/prflow/scripts/ tree AND no repo-root
# scripts/, so the finalizer's helpers all hit their absent-arm no-op and the dead-run
# backstop silently produces nothing — the exact failure #1174 fixes, invisible in this
# self-repo where the repo-root scripts/ fallback masks it. Assert the vendor-plugin
# step count includes the finalizer's (config + gate + command + review_finalize = 4),
# and that a vendor-plugin step appears within the review_finalize job body.
assert_eq "#1174: devflow.yml has 4 vendor-plugin steps (config + gate + command + review_finalize)" "4" \
  "$(grep -c 'uses: \./\.github/actions/vendor-plugin' "$WF/devflow.yml" || true)"
assert_eq "#1174: the review_finalize job materializes the plugin (a vendor-plugin step in its body)" "yes" \
  "$(awk '/^  review_finalize:/{f=1} f && /uses: \.\/\.github\/actions\/vendor-plugin/{print "yes"; exit}' "$WF/devflow.yml")"

# ── The review_finalize job GATE (issue #1174). Actions evaluates this `if:` BEFORE
# the step runs, so it is unreachable from the extracted step body the #1174 wiring
# block in lib/test/modules/review-trigger-helpers.sh drives — nothing but a pin can
# see it, and a dropped conjunct ships green. Each term prevents a distinct
# spurious-banner class:
#   always()                     — the only reason this job runs at all on a dead
#                                  command-job path (the whole point of the backstop).
#   needs.<upstream>.result      — a FAILED config/gate/review_dedupe leaves `command`
#     == 'success' (x3)            skipped for an UPSTREAM reason, which the arm helper
#                                  maps to did-not-report; requiring the chain succeeded
#                                  confines that arm to a genuine command-level death.
#   enabled / should_run /       — the command job's own screen; a dedupe-SUPPRESSED run
#     suppress                     is benign, not a dead run, so it must draw no banner.
#   the two review spellings     — AC7's transitional /devflow:review alias beside the
#                                  canonical /prflow:review; losing one silently drops
#                                  the backstop for that spelling.
RF_IF="$(awk '/^  review_finalize:/{f=1} f && /^    if: /{print; exit}' "$WF/devflow.yml")"
_rf_if_has() { case "$RF_IF" in *"$1"*) echo yes ;; *) echo no ;; esac; }
assert_eq "#1174 gate: the review_finalize if: runs on every command-job exit path (always())" \
  "yes" "$(_rf_if_has 'always()')"
assert_eq "#1174 gate: the review_finalize if: requires config to have SUCCEEDED" \
  "yes" "$(_rf_if_has "needs.config.result == 'success'")"
assert_eq "#1174 gate: the review_finalize if: requires gate to have SUCCEEDED" \
  "yes" "$(_rf_if_has "needs.gate.result == 'success'")"
assert_eq "#1174 gate: the review_finalize if: requires review_dedupe to have SUCCEEDED" \
  "yes" "$(_rf_if_has "needs.review_dedupe.result == 'success'")"
assert_eq "#1174 gate: the review_finalize if: honours the workflow enable switch" \
  "yes" "$(_rf_if_has "needs.config.outputs.enabled == 'true'")"
assert_eq "#1174 gate: the review_finalize if: honours the gate's should_run screen" \
  "yes" "$(_rf_if_has "needs.gate.outputs.should_run == 'true'")"
assert_eq "#1174 gate: the review_finalize if: draws no banner on a dedupe-suppressed run" \
  "yes" "$(_rf_if_has "needs.review_dedupe.outputs.suppress != 'true'")"
assert_eq "#1174 gate: the review_finalize if: screens the canonical /prflow:review spelling" \
  "yes" "$(_rf_if_has "startsWith(needs.gate.outputs.command, '/prflow:review')")"
assert_eq "#1174 gate: the review_finalize if: screens the transitional /devflow:review spelling" \
  "yes" "$(_rf_if_has "startsWith(needs.gate.outputs.command, '/devflow:review')")"
# Negative control: the matcher really can report a missing conjunct, so the nine
# assertions above are not nine vacuous passes on an unmatched-anything comparison.
assert_eq "#1174 gate: the conjunct matcher reports a term the if: does NOT carry" \
  "no" "$(_rf_if_has "needs.command.result == 'success'")"
# AC8: the finalizer mint is opt-in on DEVFLOW_APP_ID, and its GH_TOKEN falls back to
# the built-in github.token when that variable is unset — the behaviour a consumer who
# has not configured the App relies on. Pin both halves so a future edit cannot drop the
# fallback (which would make the finalizer's writes fail for every non-App consumer).
assert_eq "#1174 AC8: the finalizer token mint is gated on vars.DEVFLOW_APP_ID" "yes" \
  "$(awk '/id: finalize-token/{f=1} f && /if: \$\{\{ vars.DEVFLOW_APP_ID != .. \}\}/{print "yes"; exit}' "$WF/devflow.yml")"
assert_eq "#1174 AC8: the finalizer GH_TOKEN falls back to github.token when the App token is empty" "1" \
  "$(grep -cF 'GH_TOKEN: ${{ steps.finalize-token.outputs.token || github.token }}' "$WF/devflow.yml" || true)"

# Early-ack reaction must stay correctly wired in BOTH gate jobs. These guard
# the load-bearing properties that the react-to-trigger.sh unit tests above
# CANNOT see (they exercise the script in isolation): it must run only after
# authorization, the gate must hold the write scopes the POST needs, and it must
# be `bash`-invoked so it doesn't depend on the vendored copy's exec bit. Slice
# out just the gate job — `issues:/pull-requests: write` also appear on the
# heavy command/claude jobs, so a whole-file grep would not prove gate scoping.
gate_block() {
  awk '
    /^  [A-Za-z0-9_-]+:[[:space:]]*$/ { inblock = ($0 ~ /^  gate:/) }
    inblock { print }
  ' "$1"
}
for f in devflow devflow-implement; do
  blk="$(gate_block "$WF/$f.yml")"
  # 1. Ack step is gated on resolver authorization — never reacts before should_run.
  guard="$(printf '%s\n' "$blk" | awk '/name: Acknowledge trigger/{f=1} f && /should_run ==/ {print "ok"; exit}')"
  assert_eq "react: $f.yml ack step gated on should_run" "ok" "$guard"
  # 2. Gate grants exactly the scopes the reactions POST needs.
  assert_eq "react: $f.yml gate grants issues:write" "1" \
    "$(printf '%s\n' "$blk" | grep -cE '^[[:space:]]+issues:[[:space:]]*write')"
  assert_eq "react: $f.yml gate grants pull-requests:write" "1" \
    "$(printf '%s\n' "$blk" | grep -cE '^[[:space:]]+pull-requests:[[:space:]]*write')"
  # 3. Invoked via `bash` (no exec-bit dependency on the vendored copy).
  bad="$(printf '%s\n' "$blk" | grep -nE 'run:.*react-to-trigger\.sh' | grep -v 'bash ' || true)"
  assert_eq "react: $f.yml invokes react-to-trigger.sh via bash" "" "$bad"
done

# ────────────────────────────────────────────────────────────────────────────
echo "#936 — surviving references to the withheld devflow-review.yml"
# ────────────────────────────────────────────────────────────────────────────
# Issue #936 withheld the automatic pull-request-triggered review tier and removed
# .github/workflows/devflow-review.yml from the tree. Every remaining mention of that
# filename must be a deliberate, reviewed one — a historical record, a withheld-tier
# statement, or a still-correct query against a consumer that retains the file. This
# assertion is the machine-consumed inventory of that set: a newly-added reference from
# any other path turns the suite RED and forces the author to state which it is.
#
# Excluded, and why: .prflow/logs/ and .prflow/learnings/ are append-only historical
# records whose whole purpose is to describe what the repo used to do; CHANGELOG.md is the
# change record that announces this very removal; .changeset/ is excluded because
# version-consolidate CONSUMES and DELETES its files on merge, so an allowlist entry naming
# one would rot RED on main the moment it landed.
#
# Disclosed residual on one allowlisted path. scripts/describe-denial-count.sh's header comment
# still names devflow-review.yml in the present tense, and issue #936 deliberately did NOT
# rewrite it: the #908 AC6 pin below asserts that file is byte-unmodified relative to the
# merge-base with origin/main, so any edit — including a tense correction — turns that pin RED.
# Re-scoping someone else's guard was out of scope here, so the stale tense is recorded as a
# known exception rather than silently fixed or silently ignored.
#
# Stated reference, lib/test/pin-corpus-lint.py: the filename appears there as a FROZEN LITERAL
# of the rename map, never as a workflow this repo runs. lib/rename-map.json lists it under
# frozen.workflow_filenames, and the rename-substitution builder's ordering comment names it as
# the concrete case its longest-first-with-frozen-winning-ties rule has to get right: the frozen
# `devflow-review.yml` must out-compete the shorter `devflow-review` config-key rule issue #1041
# added when it unfroze the two `workflows.*` sub-keys, or a pin literal naming the withheld
# workflow would be respelled and silently exempted from the #810 gate as a sanctioned rename.
# Two sibling paths already carry the same literal for the same reason and are already listed:
# lib/rename-map.json, which holds the frozen entry, and lib/test/test_pin_corpus_lint.py, which
# asserts the substitution leaves it unchanged.
#
# Stated reference, lib/test/modules/installer-wiring.sh: a fixture consumer repository that
# RETAINS the withheld tier. Those arms exist precisely because a consumer that installed the
# tier before it was withheld keeps it, and the installer must report it, leave it alone by
# default, and remove it only on the explicit opt-in — so the filename has to appear there.
#
# Stated reference, docs/internal/cloud-allowlist.md (issue #1051): a withheld-tier statement. That page's
# PreToolUse section has to name the deleted workflow to say WHY the #908 guard is inert — the
# guard's registration rides on devflow-runner.yml, which is `workflow_call`-only and lost its
# sole caller when #936 deleted devflow-review.yml. The filename is the caller that no longer
# exists, so naming it is the point of the sentence; describing it obliquely would leave a reader
# unable to check the claim against the tree.
#
# Accepted residual, stated rather than discovered later: this pins the FILENAME form only.
# The bare `devflow-review` is a config KEY, not a filename, and legitimately survives in
# .prflow/config.example.json, .prflow/config.json and .prflow/config.schema.json (each
# covered by its own criterion) — so a future reference written in the bare form is not
# caught here.
_936_EXPECTED="$(cat <<'EOF'
.github/workflows/ci.yml
.github/workflows/devflow-implement.yml
.github/workflows/devflow-runner.yml
.github/workflows/devflow.yml
.github/workflows/matcher-probe.yml
.github/workflows/telemetry-push.yml
.prflow/config.schema.json
CLAUDE.md
README.md
docs/external/docs/runs/cloud/installation.md
docs/external/release-notes.md
docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md
docs/internal/cloud-allowlist.md
docs/internal/cloud-setup.md
docs/internal/execution-file-shape.md
docs/internal/implement-skill.md
docs/internal/install.md
docs/internal/workflow-triggers.md
install.sh
lib/rename-map.json
lib/test/fixtures/issue-304-body.md
lib/test/modules/capability-profiles.sh
lib/test/modules/installer-wiring.sh
lib/test/modules/review-stall-backstop.inventory.md
lib/test/modules/review-stall-backstop.sh
lib/test/modules/review-trigger-helpers.sh
lib/test/mutation-pin-corpus-adjudications.tsv
lib/test/pin-corpus-lint.py
lib/test/run.sh
lib/test/test_pin_corpus_lint.py
lib/test/test_verification_baseline.py
scripts/build-experiment-records.py
scripts/derive-review-preconditions.sh
scripts/derive-review-verdict.sh
scripts/describe-denial-count.sh
scripts/describe-skip-title.sh
scripts/post-review-backstop-comment.sh
scripts/render-guard-visibility.sh
scripts/scaffold-config.sh
scripts/workflow-flight-recorder-registry.json
EOF
)"
# `git grep -l` reads the INDEX-plus-worktree tracked set, so it never descends into the
# sibling checkouts under .claude/worktrees/ the way a repo-root-anchored recursive walk
# would (issue #711).
# LC_ALL=C pins the collation: the checked-in list is in C order (uppercase before lowercase),
# while a UTF-8 locale's sort ignores case and punctuation and interleaves README.md and the
# docs/ paths differently. Unpinned, this assertion passes or fails on the runner's locale
# rather than on the tree's path set.
_936_ACTUAL="$(cd "$LIB/.." && git grep -lF -- 'devflow-review.yml' \
  | grep -vE '^(\.prflow/logs/|\.prflow/learnings/|\.changeset/|CHANGELOG\.md$)' | LC_ALL=C sort)"
assert_eq "#936 surviving devflow-review.yml references match the checked-in allowlist exactly" \
  "$_936_EXPECTED" "$_936_ACTUAL"  # structural-pin-ok: generated-artifact-identity -- the allowlist IS the machine-consumed inventory of surviving references to a deleted workflow; its subject is the tree's path set, not prose wording
# Positive control: the comparison must be able to say "differs" for the RIGHT reason.
# An earlier form scanned a one-file mktemp sandbox and compared that to the 32-path
# allowlist — those can never be equal, so it reported "differs" even if grep found nothing
# or were not installed. It proved only that two unequal strings are unequal. Instead, feed
# the real allowlist plus one extra path through the same equality the assertion above uses:
# a newly-referencing file must make the comparison differ, and the unmodified list must not.
assert_eq "#936 allowlist comparison detects a reference from an unlisted path (positive control)" "differs" \
  "$([ "$_936_EXPECTED"$'\n'"docs/newly-referencing-file.md" != "$_936_EXPECTED" ] && echo differs || echo same)"
assert_eq "#936 allowlist comparison reports 'same' for the unmodified list (negative control — the control above can report both)" \
  "same" "$([ "$_936_EXPECTED" != "$_936_EXPECTED" ] && echo differs || echo same)"

# ────────────────────────────────────────────────────────────────────────────
echo "#582 — configurable cloud-tier runner via DEVFLOW_RUNNER"
# ────────────────────────────────────────────────────────────────────────────
# `.github/workflows/*.yml` partitions THREE ways, and issue #936 is what made the
# third group necessary: the auto PR-triggered review tier is withheld from this
# release, so `devflow-runner.yml` and `telemetry-push.yml` are no longer shipped by
# `install.sh` — but they still EXECUTE in every consumer that installed them before
# the withholding, so they keep the parameterized DEVFLOW_RUNNER contract. The three
# groups are:
#
#   1. shipped by the installer            → _582_SHIPPED    (parameterized runs-on)
#   2. retained consumer runtime, unshipped → _582_RETAINED   (parameterized runs-on)
#   3. plugin-internal                      → _582_INTERNAL   (hardcoded ubuntu-latest)
#
# Groups 1 and 2 carry identical assertions (both run in consumer repos, on consumer
# infrastructure); they are kept as distinct lists because the *reason* differs and a
# file moving between them is a shipping decision a reader must see. Group 3 runs on
# this repo's own GitHub-hosted infra and must NOT be parameterized.
#
# The partition itself is asserted below: every `.github/workflows/*.yml` file lands in
# exactly one group — none in zero (a new workflow that nobody classified), none in two
# (a file that would be asserted both parameterized and hardcoded). Without that check
# the groups are three arbitrary lists, and a workflow added to none of them is silently
# uncovered, which is exactly how `agents-seam-probe.yml` sat outside both pre-#936 loops.
# The shipped group is DERIVED from install.sh's copy loop, never transcribed: that loop is
# the source of truth for which workflows reach a consumer repo, and issue #936 is precisely
# a change to it. A hand-copied list here could drift from the installer in either direction
# with nothing going RED — including the one regression this issue most needs caught, a
# `devflow-review` put back into the loop. Derived with builtins (a non-preflight PATH tool
# must not decide a comparison value, CLAUDE.md guard-class 2); an unparseable loop leaves
# the list empty, which the non-vacuity assertion below turns RED rather than passing.
_582_SHIPPED=""
while IFS= read -r _582_l; do
  # The loop now lives inside install.sh's apply function and is therefore indented;
  # strip the leading whitespace with builtins (never `sed`/`tr` — this value decides
  # the assertion) so the derivation follows the loop wherever it sits in the file.
  _582_l="${_582_l#"${_582_l%%[! ]*}"}"
  case "$_582_l" in
    "for w in "*"; do")
      _582_l="${_582_l#for w in }"
      _582_SHIPPED="${_582_l%; do}"
      break
      ;;
  esac
done < "$LIB/../install.sh"
assert_eq "#936/#582: install.sh's workflow copy loop ships exactly devflow + devflow-implement" \
  "devflow devflow-implement" "$_582_SHIPPED"
assert_eq "#936/#582: the withheld auto-review tier is absent from install.sh's copy loop" \
  "absent" "$(case " $_582_SHIPPED " in *" devflow-review "*|*" devflow-runner "*|*" telemetry-push "*) echo present ;; *) echo absent ;; esac)"
_582_RETAINED="devflow-runner telemetry-push"
_582_INTERNAL="ci matcher-probe version-consolidate agents-seam-probe stall-observer"
# Exhaustive-and-disjoint: compare the on-disk basename set against the three lists
# concatenated. A duplicate across lists makes the concatenated count exceed the
# deduplicated count; a missing file makes the sorted sets differ. Both are asserted.
_582_ALL_DECLARED="$(printf '%s %s %s' "$_582_SHIPPED" "$_582_RETAINED" "$_582_INTERNAL" | tr ' ' '\n' | grep -v '^$' | sort)"
_582_ON_DISK="$(ls "$WF"/*.yml | sed -e 's|.*/||' -e 's|\.yml$||' | sort)"
assert_eq "#582: the three-way workflow partition covers every .github/workflows/*.yml (none unclassified)" \
  "$_582_ON_DISK" "$(printf '%s\n' "$_582_ALL_DECLARED" | sort -u)"
assert_eq "#582: the three-way workflow partition is disjoint (no file in two groups)" \
  "$(printf '%s\n' "$_582_ALL_DECLARED" | wc -l | tr -d ' ')" \
  "$(printf '%s\n' "$_582_ALL_DECLARED" | sort -u | wc -l | tr -d ' ')"
# The canonical parameterized runs-on expression. Every consumer runs-on line
# must be BYTE-IDENTICAL to this: a mere count/mention check would pass a
# divergent-but-still-parameterized copy (a typo that keeps `vars.DEVFLOW_RUNNER`
# but garbles the rest, silently reverting that job to a different runner), so
# pin (b) below asserts fixed-string identity, not just that the variable is named.
_582_CANON="runs-on: \${{ vars.DEVFLOW_RUNNER && (startsWith(vars.DEVFLOW_RUNNER, '[') && fromJSON(vars.DEVFLOW_RUNNER) || vars.DEVFLOW_RUNNER) || 'ubuntu-latest' }}"
for f in $_582_SHIPPED $_582_RETAINED; do
  WFF="$WF/$f.yml"
  # (a) No bare `runs-on: ubuntu-latest` line survives. The parameterized form
  #     carries 'ubuntu-latest' only as a quoted fallback inside ${{ … }}, so
  #     the fixed-string `runs-on: ubuntu-latest` (unquoted) no longer appears.
  assert_eq "#582: $f.yml has no bare 'runs-on: ubuntu-latest'" "no" \
    "$(grep -qF 'runs-on: ubuntu-latest' "$WFF" && echo yes || echo no)"  # raw-guard-ok: absence pin
  # (b) Every runs-on line is byte-identical to the canonical DEVFLOW_RUNNER
  #     expression: the count of lines carrying the exact canonical fixed string
  #     equals the count of runs-on lines, so no parameterized runs-on diverges.
  assert_eq "#582: $f.yml every runs-on is the canonical DEVFLOW_RUNNER expression" \
    "$(grep -cE '^[[:space:]]*runs-on:' "$WFF")" \
    "$(grep -cF "$_582_CANON" "$WFF")"
  # (c) Top-level `defaults: run: shell: bash`. The `defaults:` key is column-0
  #     (top level); the shell key nests at 4 spaces — distinct from the 8-space
  #     step-level `shell: bash` some of them already carry. Assert the exact
  #     CONTIGUOUS `defaults:` → `  run:` → `    shell: bash` nesting (not two
  #     independent line-counts, which would both pass on a malformed interleaving
  #     — a column-0 `defaults:` and an unrelated 4-space `shell: bash` elsewhere).
  assert_eq "#582: $f.yml declares exactly one top-level 'defaults:' block" "1" \
    "$(grep -c '^defaults:$' "$WFF")"
  assert_eq "#582: $f.yml top-level defaults is the contiguous 'run: shell: bash' block" "1" \
    "$(awk 'p2=="defaults:"&&p1=="  run:"&&$0=="    shell: bash"{c++}{p2=p1;p1=$0}END{print c+0}' "$WFF")"
done
# Out-of-scope guard: the plugin-internal workflows keep the hardcoded literal
# and must NOT be parameterized (they run on this repo's GitHub-hosted infra).
for f in $_582_INTERNAL; do
  assert_eq "#582: $f.yml (plugin-internal) still uses hardcoded ubuntu-latest" "yes" \
    "$(grep -qF 'runs-on: ubuntu-latest' "$WF/$f.yml" && echo yes || echo no)"  # raw-guard-ok: presence pin
  assert_eq "#582: $f.yml (plugin-internal) is NOT parameterized on DEVFLOW_RUNNER" "no" \
    "$(grep -qF 'vars.DEVFLOW_RUNNER' "$WF/$f.yml" && echo yes || echo no)"  # raw-guard-ok: absence pin
done

# ────────────────────────────────────────────────────────────────────────────
echo "opt-in GitHub App tokens — writers full-scope + per-site downscoped (issues #201 + #269)"
# ────────────────────────────────────────────────────────────────────────────
# The opt-in PRIMARY GitHub App (vars.DEVFLOW_APP_ID + secrets.DEVFLOW_APP_PRIVATE_KEY)
# serves two contracts, pinned together here because they share one mint pattern:
#   #201 — the two CLOUD WRITERS (devflow-implement.yml, devflow.yml `command`)
#   mint a FULL-installation-scope token (Contents: write + Workflows: write)
#   so the agent's git push can edit .github/workflows/ files.
#   #269 — the other primary-App user-visible cloud posts (the trigger reactions
#   + notice comments in the devflow.yml gate/review_dedupe and
#   devflow-implement.yml gate jobs — the marker-detected workpad comment's
#   gate-job creation stays on GITHUB_TOKEN) mint a per-site token DOWNSCOPED via
#   permission-* inputs to exactly what that site does. The permission-* inputs
#   are the SOLE least-privilege enforcement (an App installation token ignores
#   the job `permissions:` block), so the exact per-site permission sets — and
#   the ABSENCE of any write-widening input — are the security boundary these
#   pins protect.
# Every primary-App mint is gated on `vars.DEVFLOW_APP_ID != ''` (inert unless an
# operator opts in), consumed with a `|| GITHUB_TOKEN` / `|| github.token`
# fallback (unset → byte-for-byte pre-App behavior), and fail-loud (no
# continue-on-error): a configured-but-broken App fails the job rather than
# silently degrading to GITHUB_TOKEN.
#   #300 — the REVIEW identity is a SEPARATE dedicated app, DevFlow-Reviewer
#   (vars.DEVFLOW_REVIEWER_APP_ID + secrets.DEVFLOW_REVIEWER_PRIVATE_KEY), so the
#   review path (devflow-runner.yml's review agent, and devflow.yml's
#   `/devflow:review` command branch) NEVER shares the PR-authoring primary-app
#   identity — Phase 4.4's `gh pr review --request-changes`/`--approve` is then
#   not a forbidden self-review. Those two review mints are pinned by the
#   REVIEWER_SITES loop below (same downscoped review perm set, but keyed on the
#   reviewer var/secret and id `reviewer-token`); the review-identity invariant
#   (review github_token resolves to the reviewer token or GITHUB_TOKEN, NEVER
#   DEVFLOW_APP_ID / the primary app token) is pinned after the consumer block.

# Site table: file | mint step name | step id | expected permission-* set
# (comma-separated; FULL = full installation scope, i.e. NO permission-* input).
APP_SITES=(
  'devflow-implement|Mint workflow-capable token (optional)|app-token|FULL'
  'devflow-implement|Mint stall-backstop token (optional)|backstop-token|FULL'
  'devflow|Mint workflow-capable token (optional)|app-token|FULL'
  'devflow|Mint downscoped reaction token (optional)|gate_app_token|permission-issues: write,permission-pull-requests: write'
  'devflow|Mint downscoped notice token (optional)|dedupe_app_token|permission-pull-requests: write'
  'devflow-implement|Mint downscoped reaction token (optional)|gate_app_token|permission-issues: write,permission-pull-requests: write'
)
for site in "${APP_SITES[@]}"; do
  IFS='|' read -r f name id scopes <<<"$site"
  WFF="$WF/$f.yml"
  blk="$(mint_blk "$name" "$WFF")"
  assert_eq "app-token: $f.yml has mint step '$name'" "yes" \
    "$([ -n "$blk" ] && echo yes || echo no)"
  assert_eq "app-token: $f.yml '$name' uses actions/create-github-app-token" "1" \
    "$(printf '%s\n' "$blk" | grep -cE 'uses:[[:space:]]*actions/create-github-app-token@')"
  # Substring match: the downscoped mints add a consumer condition to the gate
  # (`&& should_run == 'true'` on the two gate-job mints, `&& suppress ==
  # 'true'` on the review_dedupe mint — mint only when a consumer will run), so
  # the opt-in literal is asserted as a required part of the if:, not the whole
  # expression.
  assert_eq "app-token: $f.yml '$name' is gated on vars.DEVFLOW_APP_ID != ''" "1" \
    "$(printf '%s\n' "$blk" | grep -cF "vars.DEVFLOW_APP_ID != ''" || true)"
  assert_eq "app-token: $f.yml '$name' reads client-id from vars.DEVFLOW_APP_ID" "1" \
    "$(printf '%s\n' "$blk" | grep -cF 'client-id: ${{ vars.DEVFLOW_APP_ID }}')"
  assert_eq "app-token: $f.yml '$name' reads private-key from secrets.DEVFLOW_APP_PRIVATE_KEY" "1" \
    "$(printf '%s\n' "$blk" | grep -cF 'private-key: ${{ secrets.DEVFLOW_APP_PRIVATE_KEY }}')"
  # Fail-loud: no continue-on-error KEY anywhere in the mint step (the block
  # extract runs to the next `- name:`, so it can trail comment prose of the
  # following step that mentions continue-on-error — match the `key:` form).
  assert_eq "app-token: $f.yml '$name' is fail-loud (no continue-on-error)" "" \
    "$(printf '%s\n' "$blk" | grep -E '^[[:space:]]*continue-on-error:' || true)"
  # Step-id ↔ output-reference coupling: the consumer expression reads
  # steps.<id>.outputs.token; renaming the id (leaving the consumer untouched)
  # would resolve to empty on every run and silently fall the opt-in back to
  # GITHUB_TOKEN — the exact silent degradation the fail-loud contract exists
  # to prevent, reached via a wiring typo.
  assert_eq "app-token: $f.yml '$name' carries id: $id (couples to steps.$id.outputs.token)" "1" \
    "$(printf '%s\n' "$blk" | grep -cE "^[[:space:]]*id:[[:space:]]*${id}[[:space:]]*\$")"
  if [ "$scopes" = "FULL" ]; then
    # Writers stay full-installation-scope: NO permission-* downscope input
    # (adding one would silently narrow the writers' Workflows: write push).
    assert_eq "app-token: $f.yml '$name' carries no permission-* input (full scope)" "0" \
      "$(printf '%s\n' "$blk" | grep -cE '^[[:space:]]*permission-[a-z-]+:' || true)"
  else
    # "Declares exactly" = each expected permission present once AND the total
    # permission-* line count equals the expected set size, so an added
    # write-widening input (permission-contents: write, permission-workflows)
    # goes RED without needing one absence pin per conceivable permission.
    IFS=',' read -ra perms <<<"$scopes"
    for p in "${perms[@]}"; do
      assert_eq "app-token: $f.yml '$name' declares $p" "1" \
        "$(printf '%s\n' "$blk" | grep -cF "$p" || true)"
    done
    assert_eq "app-token: $f.yml '$name' declares exactly ${#perms[@]} permission-* inputs" "${#perms[@]}" \
      "$(printf '%s\n' "$blk" | grep -cE '^[[:space:]]*permission-[a-z-]+:' || true)"
  fi
done
# DevFlow-Reviewer mints (issue #300): the two REVIEW-identity mints key on the
# SEPARATE reviewer var/secret (vars.DEVFLOW_REVIEWER_APP_ID +
# secrets.DEVFLOW_REVIEWER_PRIVATE_KEY) and carry id `reviewer-token`, with the
# same downscoped review perm set as the old runner mint. devflow.yml's reviewer
# mint additionally gates on the command being `/devflow:review` (substring
# assertion tolerates the extra `&& startsWith(...)` clause, same as the
# should_run gate note above). This loop is the reviewer-app analogue of the
# APP_SITES loop, kept separate so the primary-app pins never assert the reviewer
# var/secret (and vice versa).
REVIEWER_SITES=(
  'devflow-runner|Mint downscoped DevFlow-Reviewer token (optional)|reviewer-token'
  'devflow|Mint downscoped DevFlow-Reviewer token (optional)|reviewer-token'
)
for site in "${REVIEWER_SITES[@]}"; do
  IFS='|' read -r f name id <<<"$site"
  WFF="$WF/$f.yml"
  blk="$(mint_blk "$name" "$WFF")"
  assert_eq "reviewer-token: $f.yml has mint step '$name'" "yes" \
    "$([ -n "$blk" ] && echo yes || echo no)"
  assert_eq "reviewer-token: $f.yml '$name' uses actions/create-github-app-token" "1" \
    "$(printf '%s\n' "$blk" | grep -cE 'uses:[[:space:]]*actions/create-github-app-token@')"
  # Gated on the SEPARATE reviewer variable, never the primary DEVFLOW_APP_ID.
  assert_eq "reviewer-token: $f.yml '$name' is gated on vars.DEVFLOW_REVIEWER_APP_ID != ''" "1" \
    "$(printf '%s\n' "$blk" | grep -cF "vars.DEVFLOW_REVIEWER_APP_ID != ''" || true)"
  assert_eq "reviewer-token: $f.yml '$name' reads client-id from vars.DEVFLOW_REVIEWER_APP_ID" "1" \
    "$(printf '%s\n' "$blk" | grep -cF 'client-id: ${{ vars.DEVFLOW_REVIEWER_APP_ID }}')"
  assert_eq "reviewer-token: $f.yml '$name' reads private-key from secrets.DEVFLOW_REVIEWER_PRIVATE_KEY" "1" \
    "$(printf '%s\n' "$blk" | grep -cF 'private-key: ${{ secrets.DEVFLOW_REVIEWER_PRIVATE_KEY }}')"
  # NOTE: a "reviewer block never mentions DEVFLOW_APP_ID" per-block pin is
  # deliberately NOT asserted here — mint_blk extends to the next `- name:`, so a
  # reviewer block bleeds the FOLLOWING step's leading comment, which is free to
  # name DEVFLOW_APP_ID (it did exactly that while the primary app-token step
  # still followed the reviewer mint, before #357 hoisted that step above the
  # checkout). The review-identity invariant is pinned precisely, and
  # extraction-safely, by the whole-file / review-branch-conditional pins after
  # the consumer block below.
  assert_eq "reviewer-token: $f.yml '$name' is fail-loud (no continue-on-error)" "" \
    "$(printf '%s\n' "$blk" | grep -E '^[[:space:]]*continue-on-error:' || true)"
  assert_eq "reviewer-token: $f.yml '$name' carries id: $id (couples to steps.$id.outputs.token)" "1" \
    "$(printf '%s\n' "$blk" | grep -cE "^[[:space:]]*id:[[:space:]]*${id}[[:space:]]*\$")"
  # Downscoped review perm set: exactly the 4 read/write inputs, no write-widener.
  for p in 'permission-contents: read' 'permission-issues: read' 'permission-pull-requests: write' 'permission-actions: read'; do
    assert_eq "reviewer-token: $f.yml '$name' declares $p" "1" \
      "$(printf '%s\n' "$blk" | grep -cF "$p" || true)"
  done
  # "declares exactly 4 permission-* inputs" + the four named-perm pins above
  # already make permission-contents: write and permission-workflows provably
  # absent (flipping contents:read→write fails the named pin; adding workflows
  # makes the count 5) — so no separate negative pin is needed, matching the
  # APP_SITES loop's count-based house style for downscoped sites.
  assert_eq "reviewer-token: $f.yml '$name' declares exactly 4 permission-* inputs" "4" \
    "$(printf '%s\n' "$blk" | grep -cE '^[[:space:]]*permission-[a-z-]+:' || true)"
done

# ── The push credential is the CHECKOUT token, not github_token (issue #357) ──
# actions/checkout@v6 no longer writes its auth header into .git/config: it
# writes `http.<server>/.extraheader` into an external config file and wires it
# in via `includeIf.gitdir:` (covering .git/worktrees/* too). claude-code-action's
# `git config --unset-all http.<server>/.extraheader` searches only .git/config,
# so it clears nothing ("No existing authentication headers to remove"), and the
# surviving preemptive `Authorization:` header outranks the token that action
# embeds in origin's URL. Net effect of an unseeded checkout: EVERY push in the
# job authenticates as github-actions[bot] — a GitHub App with no `workflows`
# permission — so pushes touching .github/workflows/ fail ("refusing to allow a
# GitHub App to create or update workflow … without workflows permission") while
# all other pushes succeed, which is why this hid for so long. Both halves are
# pinned per pushing job: (a) the writer mint PRECEDES the checkout, and (b) the
# checkout consumes it with the unchanged GITHUB_TOKEN fallback. Removing either
# half — or "tidying" the mint back down next to Run Claude Code — goes RED.
# The two non-pushing mint sites (gate, review_dedupe) hand their token straight
# to `gh` and are deliberately NOT covered here.
for f in devflow-implement devflow; do
  WFF="$WF/$f.yml"
  # Anchors must be unambiguous for the ordering comparison below: exactly one
  # named checkout (the pushing job's) and exactly one writer-mint id per file.
  assert_eq "checkout-token: $f.yml has exactly one named 'Checkout repository' step" "1" \
    "$(grep -c '^      - name: Checkout repository$' "$WFF" || true)"
  assert_eq "checkout-token: $f.yml has exactly one 'id: app-token' writer mint" "1" \
    "$(grep -c '^        id: app-token$' "$WFF" || true)"

  # (a) Ordering: the mint must appear ABOVE the checkout it feeds. A step can
  # only read `steps.<id>.outputs.*` of an EARLIER step; minted after, the
  # expression resolves to empty and silently degrades to GITHUB_TOKEN.
  _mint_ln="$(grep -n '^        id: app-token$' "$WFF" | head -1 | cut -d: -f1)"
  _co_ln="$(grep -n '^      - name: Checkout repository$' "$WFF" | head -1 | cut -d: -f1)"
  assert_eq "checkout-token: $f.yml writer mint precedes the checkout it feeds" "yes" \
    "$([ -n "$_mint_ln" ] && [ -n "$_co_ln" ] && [ "$_mint_ln" -lt "$_co_ln" ] && echo yes || echo no)"

  # (b) Consumption: the exact opt-in literal, INSIDE the checkout step block.
  _co_blk="$(mint_blk 'Checkout repository' "$WFF")"
  assert_eq "checkout-token: $f.yml checkout consumes steps.app-token with GITHUB_TOKEN fallback" "1" \
    "$(printf '%s\n' "$_co_blk" | grep -cF 'token: ${{ steps.app-token.outputs.token || secrets.GITHUB_TOKEN }}' || true)"

  # The read-only review identity must never become the checkout/push credential
  # (issue #300): DevFlow-Reviewer holds contents:read and must not be able to
  # seed a push. On a /devflow:review command the writer mint is skipped by
  # design and the checkout falls back to GITHUB_TOKEN.
  assert_eq "checkout-token: $f.yml checkout never consumes the reviewer token" "0" \
    "$(printf '%s\n' "$_co_blk" | grep -cF 'reviewer-token' || true)"
done

# ── actionlint's create-github-app-token carve-out stays NARROW (issue #357) ──
# actionlint checks `with:` inputs against a BUNDLED snapshot of popular actions,
# whose create-github-app-token entry predates v3's `client-id` (it still demands
# the deprecated `app-id`). `.github/actionlint.yaml` ignores exactly those two
# messages, each pinned to that one action by name. Pin the SHAPE of the carve-out
# so it is never widened into a blanket "ignore unknown inputs" that would let a
# genuine typo'd input reach a cloud run — the lint is the only gate that catches
# those before deploy.
_AL="$WF/../actionlint.yaml"
assert_eq "actionlint-config: .github/actionlint.yaml exists" "yes" \
  "$([ -f "$_AL" ] && echo yes || echo no)"
assert_eq "actionlint-config: exactly 2 ignore entries" "2" \
  "$(grep -cE "^      - '" "$_AL" || true)"
assert_eq "actionlint-config: every ignore entry names actions/create-github-app-token" "2" \
  "$(grep -E "^      - '" "$_AL" | grep -cF 'actions/create-github-app-token' || true)"

# Explicit write-widening absence pins (belt to the exact-count braces above —
# these name the two inputs that would let a downscoped site push or edit
# workflows, per the issue's negative/security dimension).
for pair in 'devflow|Mint downscoped reaction token (optional)' 'devflow|Mint downscoped notice token (optional)' 'devflow-implement|Mint downscoped reaction token (optional)'; do
  IFS='|' read -r f name <<<"$pair"
  blk="$(mint_blk "$name" "$WF/$f.yml")"
  assert_eq "app-token: $f.yml '$name' has no permission-contents" "0" \
    "$(printf '%s\n' "$blk" | grep -cF 'permission-contents' || true)"
  assert_eq "app-token: $f.yml '$name' has no permission-workflows" "0" \
    "$(printf '%s\n' "$blk" | grep -cF 'permission-workflows' || true)"
done
# Per-file mint totals — the removal-proof complement of the per-block pins
# above (a deleted mint step would otherwise only fail its own block extract).
assert_eq "app-token: devflow-implement.yml has exactly 3 mint steps (writer + gate + stall-backstop)" "3" \
  "$(grep -cE 'uses:[[:space:]]*actions/create-github-app-token@' "$WF/devflow-implement.yml")"
assert_eq "app-token: devflow.yml has exactly 6 mint steps (command primary + command reviewer + gate + review_dedupe + review-backstop + review_finalize)" "6" \
  "$(grep -cE 'uses:[[:space:]]*actions/create-github-app-token@' "$WF/devflow.yml")"
assert_eq "app-token: devflow-runner.yml has exactly 1 mint step (DevFlow-Reviewer review)" "1" \
  "$(grep -cE 'uses:[[:space:]]*actions/create-github-app-token@' "$WF/devflow-runner.yml")"
# Consumers: each token is consumed with the fallback that IS the unset-opt-in
# path keeping behavior identical for non-adopters.
assert_eq "app-token: devflow-implement.yml consumes github_token: steps.app-token || secrets.GITHUB_TOKEN" "1" \
  "$(grep -cF 'github_token: ${{ steps.app-token.outputs.token || secrets.GITHUB_TOKEN }}' "$WF/devflow-implement.yml")"
assert_eq "app-token: devflow-runner.yml keeps no bare github_token: secrets.GITHUB_TOKEN consumer" "0" \
  "$(grep -cF 'github_token: ${{ secrets.GITHUB_TOKEN }}' "$WF/devflow-runner.yml")"

# ── Review-identity invariant (issue #300) ──────────────────────────────────
# The review path's github_token resolves to the DevFlow-Reviewer token or
# GITHUB_TOKEN, and NEVER to DEVFLOW_APP_ID / the primary app token; the
# primary-app path remains for /devflow:pr-description (+ /devflow:review-and-fix).
# devflow-runner.yml (review-only runner): consumes the reviewer token; carries
# NO trace of the primary app token/var at all.
assert_eq "review-identity: devflow-runner.yml consumes github_token: steps.reviewer-token || secrets.GITHUB_TOKEN" "1" \
  "$(grep -cF 'github_token: ${{ steps.reviewer-token.outputs.token || secrets.GITHUB_TOKEN }}' "$WF/devflow-runner.yml")"
assert_eq "review-identity: devflow-runner.yml never references DEVFLOW_APP_ID (primary app var removed)" "0" \
  "$(grep -cF 'DEVFLOW_APP_ID' "$WF/devflow-runner.yml")"
assert_eq "review-identity: devflow-runner.yml never references DEVFLOW_APP_PRIVATE_KEY (primary app secret removed)" "0" \
  "$(grep -cF 'DEVFLOW_APP_PRIVATE_KEY' "$WF/devflow-runner.yml")"
assert_eq "review-identity: devflow-runner.yml has no steps.app-token consumer (renamed to reviewer-token)" "0" \
  "$(grep -cF 'steps.app-token' "$WF/devflow-runner.yml")"
# devflow.yml command job: the github_token is command-conditional. The
# `/devflow:review` branch resolves to the reviewer token or GITHUB_TOKEN; the
# else branch keeps the primary app token for /devflow:pr-description (+
# review-and-fix). Pin the whole conditional literal so a revert to a plain
# `steps.app-token || GITHUB_TOKEN` consumer (which would put the review command
# back on the primary app identity) goes RED.
assert_eq "review-identity: devflow.yml command github_token is the review-conditional expression" "1" \
  "$(grep -cF "github_token: \${{ startsWith(needs.gate.outputs.command, '/prflow:review ') && (steps.reviewer-token.outputs.token || secrets.GITHUB_TOKEN) || (steps.app-token.outputs.token || secrets.GITHUB_TOKEN) }}" "$WF/devflow.yml")"
# The review branch (startsWith .../devflow:review) selects the reviewer token,
# NEVER the primary app token — assert the ordering: reviewer-token appears
# inside the startsWith-guarded first operand, app-token only in the else.
assert_eq "review-identity: devflow.yml review branch selects reviewer-token, primary app token only in the else" "1" \
  "$(grep -cF "startsWith(needs.gate.outputs.command, '/prflow:review ') && (steps.reviewer-token.outputs.token" "$WF/devflow.yml")"
# The primary-app mint in devflow.yml is now SKIPPED on the review command, so it
# can never author the review — pin the negated startsWith on its if:. Scoped to the
# mint step's block (mint_blk): since issue #487 the same gate also guards the
# refresher/wrapper-install steps, so a whole-file count is no longer 1.
assert_eq "review-identity: devflow.yml primary app-token mint is skipped on /devflow:review" "1" \
  "$(printf '%s\n' "$(mint_blk 'Mint workflow-capable token (optional)' "$WF/devflow.yml")" | grep -cF "vars.DEVFLOW_APP_ID != '' && !startsWith(needs.gate.outputs.command, '/prflow:review ')")"
# Conversely, devflow.yml's reviewer mint fires ONLY on the review command — pin the
# positive startsWith conjunct on its if: so dropping it (which would mint the reviewer
# token on /devflow:pr-description too) goes RED, keeping the mint scoped to /devflow:review.
assert_eq "review-identity: devflow.yml reviewer-token mint fires only on /devflow:review" "1" \
  "$(grep -cF "vars.DEVFLOW_REVIEWER_APP_ID != '' && startsWith(needs.gate.outputs.command, '/prflow:review ')" "$WF/devflow.yml")"
assert_eq "app-token: devflow.yml react step consumes gate_app_token || github.token" "1" \
  "$(grep -cF 'GH_TOKEN: ${{ steps.gate_app_token.outputs.token || github.token }}' "$WF/devflow.yml")"
assert_eq "app-token: devflow.yml notice step consumes dedupe_app_token || github.token" "1" \
  "$(grep -cF 'GH_TOKEN: ${{ steps.dedupe_app_token.outputs.token || github.token }}' "$WF/devflow.yml")"
assert_eq "app-token: devflow-implement.yml react + duplicate-notice both consume gate_app_token || github.token" "2" \
  "$(grep -cF 'GH_TOKEN: ${{ steps.gate_app_token.outputs.token || github.token }}' "$WF/devflow-implement.yml")"
# The two notice posts must stay on REST `gh api` — never `gh issue comment` /
# `gh pr comment` porcelain, whose GraphQL repo resolution fails SILENTLY under
# the repo-scoped App installation token these steps now run with (the #228
# gotcha; the failure mode is invisible exactly on App-configured repos). A
# porcelain revert would otherwise ship green.
for pair in 'devflow|Notice — manual review suppressed' 'devflow-implement|Notice — duplicate ignored'; do
  IFS='|' read -r f name <<<"$pair"
  blk="$(mint_blk "$name" "$WF/$f.yml")"
  # -F (fixed-string): the literal carries a mid-pattern `$` that a
  # non-GNU/POSIX grep (e.g. ugrep) would read as an anchor and count 0,
  # failing a correct suite on such a host.
  assert_eq "app-token: $f.yml '$name' posts via REST gh api (issues comments endpoint)" "1" \
    "$(printf '%s\n' "$blk" | grep -cF 'gh api --method POST "repos/$REPO/issues/' || true)"
  assert_eq "app-token: $f.yml '$name' uses no gh issue/pr comment porcelain" "0" \
    "$(printf '%s\n' "$blk" | grep -cE 'gh (issue|pr) comment ' || true)"
done
# guard→notice `head` coupling: the guard step emits head= into GITHUB_OUTPUT
# solely for the split-out notice step's HEAD env; a drift on either half
# yields a notice with an empty commit SHA while everything stays green.
assert_eq "app-token: devflow.yml guard emits head= into GITHUB_OUTPUT" "1" \
  "$(grep -cF 'echo "head=$HEAD" >> "$GITHUB_OUTPUT"' "$WF/devflow.yml")"
assert_eq "app-token: devflow.yml notice consumes steps.guard.outputs.head" "1" \
  "$(grep -cF 'HEAD: ${{ steps.guard.outputs.head }}' "$WF/devflow.yml")"
# guard id ↔ suppress-output coupling: the dedupe mint and the notice step both
# key on steps.guard.outputs.suppress; renaming `id: guard` (or the suppress
# output key) silently disables both while the suite stays green.
assert_eq "app-token: devflow.yml review_dedupe guard step carries id: guard" "1" \
  "$(grep -cE '^      - id: guard$' "$WF/devflow.yml")"
assert_eq "app-token: devflow.yml mint + notice both gate on steps.guard.outputs.suppress == 'true'" "2" \
  "$(grep -cF "steps.guard.outputs.suppress == 'true'" "$WF/devflow.yml")"
# Producer side of the suppress coupling: emit() is the only writer of the
# suppress= output (and the job-level output maps it); renaming either half
# leaves both consumers reading empty and the downstream dedupe gate fails
# OPEN (double review) while the suite stays green.
assert_eq "app-token: devflow.yml guard emit() writes suppress= into GITHUB_OUTPUT" "1" \
  "$(grep -cF 'emit() { echo "suppress=$1" >> "$GITHUB_OUTPUT"; }' "$WF/devflow.yml")"
assert_eq "app-token: devflow.yml review_dedupe job output maps steps.guard.outputs.suppress" "1" \
  "$(grep -cF 'suppress: ${{ steps.guard.outputs.suppress }}' "$WF/devflow.yml")"
# The suppression NOTICE must carry no DevFlow trigger phrase: under the App
# token this comment fires a REAL issue_comment event (GITHUB_TOKEN comments
# are suppressed by GitHub), so a trigger substring would re-enter the gate
# and loop.
#
# Issue #989 moved the notice TEXT out of an inline workflow `NOTE=` assignment
# into the bundled helper (MODE=notice), so the trigger-token guarantee is now
# asserted against the helper's PRODUCED message for EVERY cause — a rewording
# that kept an inline literal while changing the produced text could no longer
# pass a grep over the literal. Anti-vacuity: each cause's notice is captured and
# an expected substring is asserted present, so an empty/absent notice fails.
RS_HELPER="$LIB/../scripts/dedupe-review-command.sh"
assert_eq "app-token: helper notice(legacy) carries the legacy 'already running' text (no vacuous pass)" "1" \
  "$(MODE=notice CAUSE=legacy-check-run HEAD=deadbeef1234 bash "$RS_HELPER" | grep -c 'already running for this commit')"
assert_eq "app-token: helper notice(inflight-review) carries the in-progress text (no vacuous pass)" "1" \
  "$(MODE=notice CAUSE=inflight-review HEAD=deadbeef1234 bash "$RS_HELPER" | grep -c 'already in progress')"
# Capture ALL three cause notices once, then scan the produced text over EVERY
# declared command namespace: no notice arm may carry a command token in any
# namespace (it would self-trigger under the App token). The set is DERIVED
# ($SUITE_CMD_NS, built above from the declared plugin identity), so it follows a
# namespace addition automatically and does not go vacuous when the transitional
# namespace is eventually retired.
RS_NOTICE_ALL="$(for _rs_c in legacy-check-run legacy-workflow-run inflight-review; do MODE=notice CAUSE="$_rs_c" HEAD=deadbeef1234 bash "$RS_HELPER"; done)"
# NON-VACUITY, asserted LOCALLY rather than borrowed (see the DI_CMD_NS mirror):
# $SUITE_CMD_NS is built far upstream, so assert emptiness here, at the point of use.
assert_eq "app-token: the scanned command-namespace set is non-empty (guard is not vacuous)" \
  "yes" "$(case "$SUITE_CMD_NS" in *[!\ ]*) echo yes ;; *) echo no ;; esac)"
# Anti-vacuity for the capture itself: RS_NOTICE_ALL must be non-empty (a broken
# helper invocation must not pass the absence loops below by inspecting nothing).
assert_eq "app-token: the helper notice capture is non-empty (absence loops are not vacuous)" \
  "yes" "$(case "$RS_NOTICE_ALL" in *[!\ ]*) echo yes ;; *) echo no ;; esac)"
for _rs_ns in $SUITE_CMD_NS; do
  assert_eq "app-token: helper notices contain no /$_rs_ns: command phrase" "0" \
    "$(grep -c "/$_rs_ns:" <<< "$RS_NOTICE_ALL" || true)"
done
# PLANTED-DEFECT CONTROL: each namespace's check must actually RED on the leak it
# claims to catch. Inject a namespace phrase into a copy of the produced notices
# and confirm the grep catches it.
for _rs_ns in $SUITE_CMD_NS; do
  _RS_PLANTED="$RS_NOTICE_ALL"$'\n'"see /$_rs_ns:review"
  assert_eq "app-token: CONTROL — the planted /$_rs_ns: mutation really changed the notice body" \
    "no" "$([ "$_RS_PLANTED" = "$RS_NOTICE_ALL" ] && echo yes || echo no)"
  assert_eq "app-token: CONTROL — a planted /$_rs_ns: phrase turns the helper-notice check RED" \
    "yes" "$([ "$(grep -c "/$_rs_ns:" <<< "$_RS_PLANTED" || true)" -gt 0 ] && echo yes || echo no)"
done
assert_eq "app-token: helper notices contain no @claude token" "0" \
  "$(grep -c '@claude' <<< "$RS_NOTICE_ALL" || true)"
# The notice step deliberately has no continue-on-error; its best-effort
# contract rests entirely on the `if ! err=` guard around the single gh call
# plus the specific breadcrumb. Dropping the guard would turn a transient
# comment-post failure into a red review_dedupe job (operator noise — the
# manual command was already suppressed in every run where the notice fires).
assert_eq "app-token: suppression notice guards its gh call (if ! err=)" "1" \
  "$(grep -cF 'if ! err="$(gh api --method POST "repos/$REPO/issues/$PR/comments"' "$WF/devflow.yml")"
assert_eq "app-token: suppression notice emits its specific failure breadcrumb" "1" \
  "$(grep -cF '::warning::could not post review-suppressed notice' "$WF/devflow.yml")"
# File-wide porcelain ceiling: the shipped workflows carry ZERO
# invocation-position `gh issue|pr comment` calls (both notices are REST). A
# rebase/revert restoring the old inline guard-step porcelain post would
# produce a double notice whose porcelain half fails silently under a
# repo-scoped token — and every block-scoped pin above would stay green.
for f in devflow devflow-implement; do
  assert_eq "app-token: $f.yml has no invocation-position gh issue/pr comment porcelain" "0" \
    "$(grep -cE '^[^#]*gh (issue|pr) comment ' "$WF/$f.yml" || true)"
done
# Issue #282: review_dedupe guard's HEAD/BRANCH resolution must surface `gh`
# failure the same way Signals 1/2 do (a ::warning:: carrying gh's stderr),
# never the old blind `2>/dev/null || echo ""` swallow that collapses a `gh`
# failure and a genuinely-empty result into the same generic notice.
assert_eq "app-token: devflow.yml HEAD/BRANCH resolution carries no 2>/dev/null || echo swallow" "0" \
  "$(grep -cF '2>/dev/null || echo ""' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml HEAD resolution warns with gh's captured stderr on failure" "1" \
  "$(grep -cF 'Could not resolve PR #$PR HEAD (gh pr view failed:' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml BRANCH resolution warns with gh's captured stderr on failure" "1" \
  "$(grep -cF 'Could not resolve PR #$PR BRANCH (gh pr view failed:' "$WF/devflow.yml" || true)"
# The success-but-empty/null ::notice:: fail-open path must be retained
# unchanged (distinguishable in the log from the new gh-failure ::warning::).
assert_eq "app-token: devflow.yml retains the success-but-empty HEAD ::notice:: fail-open path" "1" \
  "$(grep -cF '::notice::Could not resolve PR #$PR HEAD; fail-open (manual review proceeds).' "$WF/devflow.yml" || true)"
# The two pins above only assert the warning-text prefixes exist — they'd stay
# GREEN even if a regression re-swallowed stderr back to `2>/dev/null` while
# leaving the strings intact. Pin the actual capture mechanism: stderr
# redirected to a dedicated file (never merged into the resolved value), the
# newline-collapsed embed of that captured file, and the mktemp fail-open
# guard — so a partial regression to the old swallow trips these, not just
# the ones above.
assert_eq "app-token: devflow.yml HEAD gh pr view captures stderr to a dedicated file (not /dev/null)" "1" \
  "$(grep -cF '2>"$HEAD_ERR"' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml BRANCH gh pr view captures stderr to a dedicated file (not /dev/null)" "1" \
  "$(grep -cF '2>"$BRANCH_ERR"' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml HEAD warning embeds the newline-collapsed captured stderr" "1" \
  "$(grep -cF '$(tr '\''\n'\'' '\'' '\'' < "$HEAD_ERR")' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml BRANCH warning embeds the newline-collapsed captured stderr" "1" \
  "$(grep -cF '$(tr '\''\n'\'' '\'' '\'' < "$BRANCH_ERR")' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml HEAD_ERR temp-file allocation is mktemp-fail-open-guarded" "1" \
  "$(grep -cF 'HEAD_ERR="$(mktemp 2>/dev/null || echo /dev/null)"' "$WF/devflow.yml" || true)"
assert_eq "app-token: devflow.yml BRANCH_ERR temp-file allocation is mktemp-fail-open-guarded" "1" \
  "$(grep -cF 'BRANCH_ERR="$(mktemp 2>/dev/null || echo /dev/null)"' "$WF/devflow.yml" || true)"
# Doc↔workflow scope coupling: the cloud-setup DevFlow-Reviewer section (issue
# #300) hardcodes the review token's permission set; pin it so a future scope
# change that reconciles the REVIEWER_SITES loop but not the doc goes RED.
assert_eq "app-token: cloud-setup.md DevFlow-Reviewer section carries the review token's exact permission set" "1" \
  "$(grep -cF '**`Contents: read`**, **`Issues: read`**, **`Pull requests: write`**, and **`Actions: read`**' "$LIB/../docs/internal/cloud-setup.md" || true)"
# Consumer-condition conjuncts on the three downscoped gate/dedupe mints: the
# second half of each mint's if: keeps the common rejection path mint-free AND
# bounds fail-loud to runs where a consumer actually posts. Dropping it would
# make a configured-but-broken App fail every rejected/non-command event.
for pair in "devflow|Mint downscoped reaction token (optional)|&& steps.resolve.outputs.should_run == 'true' }}" \
            "devflow-implement|Mint downscoped reaction token (optional)|&& steps.resolve.outputs.should_run == 'true' }}" \
            "devflow|Mint downscoped notice token (optional)|&& steps.guard.outputs.suppress == 'true' }}"; do
  IFS='|' read -r f name cond <<<"$pair"
  blk="$(mint_blk "$name" "$WF/$f.yml")"
  assert_eq "app-token: $f.yml '$name' if: carries its consumer condition" "1" \
    "$(printf '%s\n' "$blk" | grep -cF "$cond" || true)"
done
# Docs carry the opt-in contract: the var, the secret, ALL five required App
# permissions, and the per-site downscope story (no more "reviewer untouched").
CS="$LIB/../docs/internal/cloud-setup.md"
# Issue #1188: unrolled from a `for tok in …` loop so the pinned literals are static
# (the $CS path move brought this site into the #810 diff scope, where a loop-variable
# literal is <unresolved-literal> and fails closed). Both tokens are machine-consumed in
# .github/workflows/, so the classifier's Step-1 consumer check clears them.
assert_eq "app-token: cloud-setup.md documents DEVFLOW_APP_ID" "yes" \
  "$(grep -qF 'DEVFLOW_APP_ID' "$CS" && echo yes || echo no)"
assert_eq "app-token: cloud-setup.md documents DEVFLOW_APP_PRIVATE_KEY" "yes" \
  "$(grep -qF 'DEVFLOW_APP_PRIVATE_KEY' "$CS" && echo yes || echo no)"
for perm in 'Contents:[[:space:]]*write' 'Workflows:[[:space:]]*write' 'Pull requests:[[:space:]]*write' 'Issues:[[:space:]]*write' 'Actions:[[:space:]]*read'; do
  assert_eq "app-token: cloud-setup.md documents App permission ${perm//\[\[:space:\]\]\*/ }" "yes" \
    "$(grep -qiE "$perm" "$CS" && echo yes || echo no)"
done
assert_eq "app-token: cloud-setup.md no longer claims the reviewer is untouched" "0" \
  "$(grep -cF 'is untouched' "$CS")"
# Issue #1188: prose-presence app-token doc mirror pin removed (retired, orphaned by the docs/internal move).
# §15 of the overview: still no bare "No GitHub App." claim, still names the
# opt-in variable, names the primary App's reactions + notices surfaces, and —
# post-#300 — routes the review agent's posts to the separate DevFlow-Reviewer
# App rather than listing them under the primary App.
OV="$LIB/../docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md"
assert_eq "app-token: overview §15 no longer asserts a bare 'No GitHub App.'" "0" \
  "$(grep -cF 'No GitHub App.' "$OV")"
assert_eq "app-token: overview §15 positively documents the optional App (DEVFLOW_APP_ID)" "yes" \
  "$(grep -qF 'DEVFLOW_APP_ID' "$OV" && echo yes || echo no)"
# Issue #1188: prose-presence overview §15 doc mirror pin removed (retired, orphaned by the docs/internal move).
# #300: §15 must route the review agent's posts to the DevFlow-Reviewer App, not
# list them under the primary App — pin the reviewer-app name so a revert that
# re-attributes review posts to the primary App goes RED.
# Issue #1188: prose-presence overview §15 DevFlow-Reviewer routing doc mirror pin removed (retired, orphaned by the docs/internal move).

# efficiency-trace + telemetry-persistence coverage (extracted from this file into
# a focused module): the efficiency-trace.jq/.sh derivation surface, --persist and
# --self-check (#80), the harness cost floor (#475), the synthesis floor (#381),
# base-ref freshness (#532), telemetry-branch persistence (#441), the push-operand
# contract (#469), the cross-workflow telemetry relay (#489), and the #499
# unavailable-telemetry normalization block that shares its `_et_show` fixture reader.
# The registry and this full-suite call share the same lower-bound contract;
# test_module_runner.py parses this operand and rejects any coupling drift.
if ! devflow_run_full_suite_module "$LIB/test/modules/efficiency-trace-telemetry.sh" \
  "efficiency-trace-telemetry" 951; then
  printf 'ERROR: efficiency-trace-telemetry boundary could not record its result\n'
  exit 1
fi

# ── Retained here, deliberately not moved with the region above ───────────────
# Four docs/internal/efficiency-trace.md presence assertions from the extracted #532 section
# stay in this file. They are not left behind for convenience: three of their four
# pinned literals resolve into ORDINARY PROSE in that document, and the issue-#948
# routing ladder in lib/test/pin-corpus-lint.py admits such a site only when the
# delta-gated adjudication ledger already records the literal as a boundary AND the
# site carries a `# structural-pin-ok:` declaration naming one of the eight closed
# categories. No category honestly describes a documentation-presence pin, and
# authorizing a new boundary adjudication needs an evidence argument this
# extraction has none of — so moving them would have meant either a false category
# or a maintainer authorization smuggled into a pure code move. Unchanged lines in
# this file are outside the classifier's merge-base diff, so leaving them here
# preserves them exactly as they are and defers the real question (whether
# documentation-presence pins should exist at all — see CLAUDE.md's #375/#666/#810
# bullet) to the pass that is draining that population. The fourth assertion moves
# with nothing to gain by separation and is kept beside its two siblings.
# Issue #1188: the prose-presence efficiency-trace doc mirror pins (transient-failure
# residual window; --persist refreshes-the-base-ref; PR-number cutoff clause) were
# retired prose-presence pins orphaned by the docs/internal move; removed per the
# cluster note earlier. The machine-shaped `refs/remotes/origin/<base>` token pin stays
# (distinctive token, machine-consumed, not retirement-exempt).
assert_eq "docs-fetch-scope(R9): docs state the fetch scope (refs/remotes/origin/<base> cache only)" "yes" \
  "$(grep -qF 'refs/remotes/origin/<base>' "$LIB/../docs/internal/efficiency-trace.md" && echo yes || echo no)"

# ── Also retained here: the #442 Critical-1 behavioral arm ────────────────────
# The static half of that guard (telemetry-branch.sh carries no bare "${arr[@]}"
# expansion) moved with the region; this BEHAVIORAL half — which reproduces the
# bash-3.2 `set -u` empty-array abort under a real bash 3.x, so it runs on the macOS
# dev tier and not on Linux CI — cannot live in a module. A module's emitted assertion
# tally is compared for EQUALITY against the floor carried in the registry and in the
# call-site operand above, so a host-conditional arm makes that triple host-dependent:
# the module would emit 882 on macOS and 879 on Linux and one of the two would always
# read as a regression. The harness's module_host_capability_skip exists for exactly
# this shape and would credit the difference — but at the cost of a permanent nonempty
# skip tally on every CI run, and a nonempty skip tally is never a clean pass (#456).
# Keeping the arm in the monolith, whose tally has no floor, keeps both the module
# triple and the CI skip tally clean. The `_et_on_branch` reader it used is not copied
# here: the one-line `git cat-file -e` it wraps is inlined instead, so no helper has two
# definitions.
# A conditional arm is correct on its own terms too: the bug is interpreter-specific, so
# probing it under the wrong interpreter would report a false clean (the #340 R7 rule).
if [ -x /bin/bash ] && case "$(/bin/bash -c 'echo "${BASH_VERSINFO[0]}"' 2>/dev/null)" in 3) true ;; *) false ;; esac; then
  TB32_REPO="$(git_sandbox "tb bash32 orphan-create repo")"
  git -C "$TB32_REPO" init -q
  git -C "$TB32_REPO" config user.email t@e.com; git -C "$TB32_REPO" config user.name t
  mkdir -p "$TB32_REPO/.prflow"; printf 'tmp/\n' > "$TB32_REPO/.prflow/.gitignore"
  git -C "$TB32_REPO" add -A; git -C "$TB32_REPO" commit -qm seed
  mkdir -p "$TB32_REPO/.prflow/tmp/review/pr-32/run-1"
  printf '%s' '{"iter":1,"phase3_dispatched":["a"],"phase3_findings":[],"convergence_inputs":{"fixes_applied":0},"telemetry":null}' \
    > "$TB32_REPO/.prflow/tmp/review/pr-32/run-1/iter-1.json"
  TB32_ERR="$( ( cd "$TB32_REPO" && /bin/bash "$LIB/efficiency-trace.sh" --persist ) 2>&1 1>/dev/null )"; TB32_RC=$?
  assert_eq "tb(#442 Critical-1): --persist under stock bash 3.2 exits 0" "0" "$TB32_RC"
  assert_eq "tb(#442 Critical-1): ...and CREATES the orphan telemetry branch (the empty parent_arg path)" "yes" \
    "$(git -C "$TB32_REPO" cat-file -e "refs/heads/prflow-telemetry:.prflow/logs/efficiency/pr-32-run-1.json" >/dev/null 2>&1 && echo yes || echo no)"
  assert_eq "tb(#442 Critical-1): ...with no 'unbound variable' abort" "no" \
    "$(printf '%s' "$TB32_ERR" | grep -qF 'unbound variable' && echo yes || echo no)"
  rm -rf "$TB32_REPO"
fi

# ────────────────────────────────────────────────────────────────────────────
echo "devflow-runner.yml: opt-in environment provisioning (issues #18, #21)"
# ────────────────────────────────────────────────────────────────────────────
# The automated reviewer gains a build environment + build-tool allowlist ONLY
# when the TRUSTED base config sets prflow_runner.provision_env: true. These
# assertions pin the load-bearing invariants: (1) provisioning is gated on the
# base-ref flag, (2) the build allowlist is appended ONLY under that guard so
# the default profile stays byte-for-byte read-only, (3) both the flag and the
# setup block are sourced from the base ref (never the PR head) so a PR cannot
# enable provisioning or inject install commands into the write-token job.
RUNNER="$LIB/../.github/workflows/devflow-runner.yml"

# The read-only base profile line must NOT contain ANY of the 8 build tools —
# this is the "byte-for-byte read-only when disabled" guarantee. Check all eight
# (not just npm): a regression that moved a less-npm-shaped token like
# Bash(make:*) or Bash(php:*) onto the base line would slip a single-tool grep
# while breaking the security invariant. (The build tokens live only on the
# separate, PROVISION_ENV-guarded append line below.)
assert_eq "provision: read-only base profile has no build tools (all 8)" "0" \
  "$(grep "TOOLS='Read,Glob,Grep" "$RUNNER" \
     | grep -cE 'Bash\((npm|npx|node|yarn|pnpm|composer|php|make):\*\)' || true)"

# Issue #401 — probe-gated review-profile grants. matcher-probe.yml run 29111394360
# empirically measured which shapes the deployed claude-code-action matcher permits:
#   - row 9: Write(.prflow/tmp/**) PERMITTED (side-effect file created) → LANDED;
#     the reviewer authors workpad/scratch into the gitignored .prflow/tmp via the
#     Write tool (never a shell `>` redirect, which the probe recorded DENIED).
#   - row 8: Write(/tmp/**) DENIED (out-of-workspace) → DROPPED.
#   - row 3: Bash(cd:*) DENIED, but confounded by an independently-denied `>` redirect
#     in the same command → UNPROVEN, DROPPED (a redirect-free re-probe must settle it).
# Pin the landed grant present and the two dropped candidates absent, so a one-sided
# removal of the scoped Write goes RED and neither dropped candidate is silently
# re-added without a fresh probe. All three read the review profile TOOLS line only.
REVIEW_TOOLS_LINE="$(grep "TOOLS='Read,Glob,Grep" "$RUNNER")"
assert_eq "#401 review profile grants Write(.prflow/tmp/**) (probe row 9 PERMITTED — scoped scratch write)" "1" \
  "$(printf '%s\n' "$REVIEW_TOOLS_LINE" | grep -cF 'Write(.prflow/tmp/**)' || true)"
assert_eq "#401 review profile does NOT grant Write(/tmp/**) (probe row 8 DENIED — out-of-workspace)" "0" \
  "$(printf '%s\n' "$REVIEW_TOOLS_LINE" | grep -cF 'Write(/tmp/**)' || true)"
assert_eq "#401 review profile does NOT grant Bash(cd:*) (probe row 3 DENIED, confounded by redirect — unproven)" "0" \
  "$(printf '%s\n' "$REVIEW_TOOLS_LINE" | grep -cF 'Bash(cd:*)' || true)"

# Issue #21: the build append is now the FREEFORM prflow_runner.allowed_tools
# list (read from the trusted base ref), not the old hard-coded npm…make set.
# (1) The fixed 8-tool append line must be GONE — listing build tools is now the
# adopter's config job, language-agnostic.
# Fixed-string match (-F): the literal contains `$TOOLS` and `(`/`)`/`*`; under a
# strict-POSIX/ugrep `grep` a mid-pattern `$` would anchor and the line would
# silently not match. -F keeps it portable.
assert_eq "provision: hard-coded npm…make build append removed" "0" \
  "$(grep -cF 'TOOLS="$TOOLS,Bash(npm:*),Bash(npx:*),Bash(node:*),Bash(yarn:*),Bash(pnpm:*),Bash(composer:*),Bash(php:*),Bash(make:*)"' "$RUNNER" || true)"

# (2) baseprovision emits runner_tools from the TRUSTED base ref ($BASE_JSON),
# joined to a comma string — the same trust channel as provision_env.
assert_eq "provision: runner_tools read from base config (BASE_JSON)" "1" \
  "$(grep -cF '.prflow_runner.allowed_tools // [] | map(strings) | join(",")' "$RUNNER" || true)"
assert_eq "provision: runner_tools written to GITHUB_OUTPUT (heredoc)" "1" \
  "$(grep -cF "printf 'runner_tools<<%s" "$RUNNER" || true)"
# The runner_tools value goes through a heredoc (not a single-line key=value
# echo), so a newline in a hand-edited base allowed_tools entry can't truncate
# the value or inject further step outputs.
assert_eq "provision: runner_tools value forwarded verbatim via heredoc" "1" \
  "$(grep -cF "printf '%s\\n' \"\$RUNNER_TOOLS\"" "$RUNNER" || true)"
# The Resolve-profile step's RUNNER_TOOLS env is wired to that base-ref output —
# never a PR-head source.
assert_eq "provision: RUNNER_TOOLS env wired to baseprovision output" "1" \
  "$(grep -cF 'RUNNER_TOOLS: ${{ steps.baseprovision.outputs.runner_tools }}' "$RUNNER" || true)"

# (3) The freeform list is appended (the filtered remainder) and that append is
# guarded by `if [ "$PROVISION_ENV" = "true" ]`, so the default profile stays
# byte-for-byte read-only. Locate the append line and confirm the guard precedes
# the deny-list filter block it lives in.
assert_eq "provision: freeform allowed_tools appended to profile" "1" \
  "$(grep -cF 'TOOLS="$TOOLS,$FILTERED"' "$RUNNER" || true)"
assert_eq "provision: freeform append guarded by PROVISION_ENV == true" "1" \
  "$(grep -c 'if \[ "\$PROVISION_ENV" = "true" \]' "$RUNNER" || true)"
# Structural: the append must sit AFTER the PROVISION_ENV guard, not merely
# coexist in the file — else a future dedent could append build tools to the
# default read-only profile while both greps above still pass. Pin line order.
APPEND_LN=$(grep -nF 'TOOLS="$TOOLS,$FILTERED"' "$RUNNER" | head -1 | cut -d: -f1)
GUARD_LN=$(grep -n 'if \[ "\$PROVISION_ENV" = "true" \]' "$RUNNER" | head -1 | cut -d: -f1)
assert_eq "provision: freeform append is inside the PROVISION_ENV guard (guard precedes append)" "yes" \
  "$([ -n "$APPEND_LN" ] && [ -n "$GUARD_LN" ] && [ "$GUARD_LN" -lt "$APPEND_LN" ] && echo yes || echo no)"

# (4) Deny-list floor: the catastrophic tier is stripped before appending. The
# filter logic lives in scripts/filter-runner-tools.sh (issue #402 — extracted so
# this suite can drive its full adversarial matrix directly, below); the workflow
# resolves + calls the helper and fails closed. Pin the deny-list names/commands
# in the HELPER (their new home), and pin the workflow's helper call + fail-closed
# arm + empty-after-strip warning.
FRT="$LIB/../scripts/filter-runner-tools.sh"
assert_eq "provision: helper strips file-tool names (Edit/Write/MultiEdit/NotebookEdit case)" "1" \
  "$(grep -cF 'Edit|Write|MultiEdit|NotebookEdit) denied=true' "$FRT" || true)"
assert_eq "provision: helper deny-list shells/eval/privilege present" "1" \
  "$(grep -c "DENY_CMDS='bash sh zsh" "$FRT" || true)"
assert_eq "provision: helper emits a per-entry strip warning" "1" \
  "$(grep -c 'never permitted on the reviewer' "$FRT" || true)"
assert_eq "provision: workflow calls the filter-runner-tools.sh helper" "1" \
  "$(grep -c 'bash "\$FILTER_HELPER"' "$RUNNER" || true)"
assert_eq "provision: workflow fails closed when helper absent (names it)" "1" \
  "$(grep -c 'deny-list floor helper (filter-runner-tools.sh) not found' "$RUNNER" || true)"
# PR-#404 REJECT fix: the floor helper is resolved ONLY from trusted sources —
# the base-ref copy baseprovision materialized (FLOOR_HELPER) or the vendored
# copy gated on vendor_source=fetch. The old checked-out-tree resolution loop
# (vendored-then-in-repo relative paths) is the vulnerability and must stay gone:
# a PR-head-editable filter is no filter.
assert_eq "#404 trust: old PR-head resolution loop is gone" "0" \
  "$(grep -cF '.prflow/vendor/prflow/scripts/filter-runner-tools.sh scripts/filter-runner-tools.sh' "$RUNNER" || true)"
assert_eq "#404 trust: FLOOR_HELPER wired to baseprovision floor_helper output" "1" \
  "$(grep -cF 'FLOOR_HELPER: ${{ steps.baseprovision.outputs.floor_helper }}' "$RUNNER" || true)"
# VENDOR_SOURCE is wired to the same fresh-fetch gate at six sites: the tools
# step's deny-floor (#404), the #458 harden-stop-hooks step, the #505 compose step
# (same trusted-source rank — the compose helper's rank-2 vendored fallback), the
# #874 baseprovision step, whose prompt-extension materialization ladder carries the
# identical fetch-gated rank so a THIN install resolves a trusted helper at all, the
# #908 harden_guard step, which keys the SAME trust signal to decide whether the
# vendored copy of the PreToolUse guard closure also needs hardening (a `fetch`
# vendor tree is official-repo content this run; any other value is PR-head content),
# and the #1064 scrub_transcript step, whose credential scrub takes the same rank-2
# fetch gate so a PR-head copy can never supply the redaction rules.
assert_eq "#404 trust: VENDOR_SOURCE wired to vendor step output (tools + #458 harden + #505 compose + #874 baseprovision + #908 harden_guard + #1064 scrub)" "6" \
  "$(grep -cF 'VENDOR_SOURCE: ${{ steps.vendor.outputs.vendor_source }}' "$RUNNER" || true)"
assert_eq "#404 trust: baseprovision materializes the floor from FETCH_HEAD" "1" \
  "$(grep -cF 'FETCH_HEAD:.prflow/vendor/prflow/scripts/filter-runner-tools.sh' "$RUNNER" || true)"
# The vendored fallback is accepted ONLY on a fresh fetch. The source check preserves
# that trusted-source gate; the ordinary attack-path fixture below exercises its behavior.
# ── #409 item 8: the deny-floor helper resolution anchors to the git repo ROOT ──
# (#295 convention: `git rev-parse --show-toplevel`, falling back to `pwd`), so a
# bare relative `.prflow/vendor/…` candidate can't be silently missed under a
# future `working-directory:` and flip every review to helper-absent fail-closed.
# Three sites anchor this way: the deny-floor (#409), the #505 compose step's
# rank-2 vendored-helper candidate, and the #1064 scrub_transcript step's rank-2
# vendored scrub candidate (all the same repo-root convention).
assert_eq "#409 item8: deny-floor helper resolution is repo-root-anchored (#295)" "3" \
  "$(grep -cF '_REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"' "$RUNNER" || true)"
assert_eq "provision: empty-after-strip warns build-aware review has no tools" "1" \
  "$(grep -c 'build-aware review is enabled with NO build tools' "$RUNNER" || true)"

# ── #927 / name-agnostic identity: the accepted plugin-identifier set is ──────
# DERIVED from one source, and nothing re-spells it as a literal.
#
# History: the trust/routing discriminators (vendor-slice.sh's `self` branch,
# devflow-runner.yml's five FETCH_HEAD-gated trusted-source arms, install.sh's
# legacy prune) each carried the plugin name as an inline ERE literal with no
# cross-assertion against the real manifest, so the suite would have stayed green
# if the manifest and the discriminators ever diverged — silently flipping the
# vendor trust ladder self->fetch. #927 added the cross-assertion. The set is now
# derived instead: `lib/plugin_identity.py` resolves
# `.claude-plugin/plugin.json` + `lib/plugin-identity.json` into the accepted
# names, the runtime consumers read it live, and the surfaces that structurally
# cannot (they inspect the very tree under examination, run curl-piped with no
# repo, or are materialized as a lone file with no sibling `lib/`) carry a
# GENERATED region compiled by `lib/generate-plugin-identity.py`.
#
# What this block guards, in order:
#   G1  the reader agrees with the real manifests (both of them);
#   G2  the generator's `--check` passes — every baked region matches the source;
#   G3  NON-VACUITY, the defect this rewrite could have introduced: `--check`
#       trivially passes over an empty region table, so assert the table resolves
#       a real, on-disk, banner-carrying region for every expected discriminator
#       file, and that each baked payload actually names every accepted name;
#   G4  no hand-written discriminator literal survives anywhere in tracked source;
#   G5  negative controls, both directions — manifest-side drift and
#       discriminator-side drift each turn `--check` RED;
#   G6  a declared alias actually reaches every baked region (the whole
#       point of the mechanism), and the resulting ERE accepts it.
P927_ROOT="$LIB/.."
P927_GEN="$P927_ROOT/lib/generate-plugin-identity.py"
P927_READER="$P927_ROOT/lib/plugin_identity.py"

# G1 — the reader's canonicals equal the REAL manifests, parsed independently
# with python3 (never a grep of the manifest: the whole point is to compare a
# real parsed value against what the discriminators will accept).
P927_MAN_NAME="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["name"])' \
  "$P927_ROOT/.claude-plugin/plugin.json" 2>/dev/null || true)"
P927_MKT_NAME="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["name"])' \
  "$P927_ROOT/.claude-plugin/marketplace.json" 2>/dev/null || true)"
assert_eq "#927 G1: the real .claude-plugin/plugin.json carries a non-empty name" "yes" \
  "$([ -n "$P927_MAN_NAME" ] && echo yes || echo no)"
assert_eq "#927 G1: the real .claude-plugin/marketplace.json carries a non-empty name" "yes" \
  "$([ -n "$P927_MKT_NAME" ] && echo yes || echo no)"
assert_eq "#927 G1: the identity reader's canonical plugin name is the manifest's" "$P927_MAN_NAME" \
  "$(python3 -c '
import json, subprocess, sys
out = subprocess.run([sys.executable, sys.argv[1], "--json"], capture_output=True, text=True)
print(json.loads(out.stdout)["plugin_canonical"] if out.returncode == 0 else "<error>")
' "$P927_READER" 2>/dev/null || echo '<error>')"
# marketplace_canonical lives in lib/plugin-identity.json because
# devflow_copy_slice removes marketplace.json from the vendored slice, so a
# consumer-tree run could never read it. That makes it a COUPLED copy — gate it.
assert_eq "#927 G1: lib/plugin-identity.json marketplace_canonical == the real marketplace.json name" "$P927_MKT_NAME" \
  "$(python3 -c '
import json, subprocess, sys
out = subprocess.run([sys.executable, sys.argv[1], "--json"], capture_output=True, text=True)
print(json.loads(out.stdout)["marketplace_canonical"] if out.returncode == 0 else "<error>")
' "$P927_READER" 2>/dev/null || echo '<error>')"

# G2 — the baked regions match the source. This is the gate a rename relies on.
P927_CHECK_RC=0
python3 "$P927_GEN" --check >/dev/null 2>&1 || P927_CHECK_RC=$?
assert_eq "#927 G2: generate-plugin-identity.py --check passes (no baked-region drift)" "0" "$P927_CHECK_RC"

# G3 — NON-VACUITY. `--check` over an empty region table passes while covering
# nothing, so prove the table resolves real files that really carry a banner.
# Derived from the generator's own REGIONS table (never a hand-transcribed list:
# a new region joins automatically), then verified against the tracked tree with
# an index-reading `git ls-files` (issue #711 — no repository-root walk).
P927_REGION_FILES="$(python3 -c '
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(sys.argv[1]).resolve().parent))
import importlib.util
spec = importlib.util.spec_from_file_location("gpi", sys.argv[1])
mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
for r in mod.REGIONS:
    print(r["file"])
' "$P927_GEN" 2>/dev/null || true)"
P927_REGION_COUNT="$(printf '%s\n' "$P927_REGION_FILES" | grep -c . || true)"
# Non-vacuity floor, expressed WITHOUT a transcribed count (a literal here rots
# the moment a region is added or removed): the table must resolve at least one
# region.
assert_eq "#927 G3: the generator's region table is non-empty" "yes" \
  "$([ "$P927_REGION_COUNT" -gt 0 ] && echo yes || echo no)"
# …and it must be COMPLETE, established from a signal independent of the table
# itself: every tracked file that actually carries a begin banner is in the
# table, and every table entry carries one. A banner-carrying file missing from
# REGIONS is the silent case --check can never see (it only walks the table), so
# its region would drift un-noticed on the next rename. `lib/test/` is excluded:
# it carries this rule's own statement text and the temp-root fixtures below.
P927_BANNER_FILES="$(git -C "$P927_ROOT" grep -lE '^[[:space:]]*# devflow-plugin-identity:begin ' \
  -- ':(exclude)lib/test/' 2>/dev/null | LC_ALL=C sort || true)"
assert_eq "#927 G3: the generator's region table equals the set of banner-carrying tracked files" \
  "$P927_BANNER_FILES" "$(printf '%s\n' "$P927_REGION_FILES" | grep . | LC_ALL=C sort || true)"
P927_BAD_REGION=0
while IFS= read -r _f; do
  [ -n "$_f" ] || continue
  # tracked, on disk, and carrying exactly one begin banner + one end marker.
  if [ -z "$(git -C "$P927_ROOT" ls-files -- "$_f")" ]; then P927_BAD_REGION=$((P927_BAD_REGION+1)); continue; fi
  if [ "$(grep -c '^[[:space:]]*# devflow-plugin-identity:begin ' "$P927_ROOT/$_f" || true)" != "1" ]; then
    P927_BAD_REGION=$((P927_BAD_REGION+1)); continue
  fi
  if [ "$(grep -c '^[[:space:]]*# devflow-plugin-identity:end$' "$P927_ROOT/$_f" || true)" != "1" ]; then
    P927_BAD_REGION=$((P927_BAD_REGION+1)); continue
  fi
  P927_BODY="$(awk '/# devflow-plugin-identity:begin /{f=1;next} /# devflow-plugin-identity:end$/{f=0} f' "$P927_ROOT/$_f")"
  if [ -z "$P927_BODY" ]; then P927_BAD_REGION=$((P927_BAD_REGION+1)); continue; fi
  # …and its payload — the lines BETWEEN the markers, not the file at large —
  # must actually name EVERY accepted plugin name. A region that resolved to a
  # file but baked an empty or partial identifier set would satisfy every
  # structural check above while accepting nothing.
  while IFS= read -r _n; do
    [ -n "$_n" ] || continue
    printf '%s' "$P927_BODY" | grep -qF "$_n" || P927_BAD_REGION=$((P927_BAD_REGION+1))
  done <<< "$(python3 "$P927_READER" --plugin-names 2>/dev/null || true)"
done <<< "$P927_REGION_FILES"
assert_eq "#927 G3: every generator region is a tracked file carrying one banner pair and every accepted name" "0" \
  "$P927_BAD_REGION"

# G4 — no hand-written discriminator literal survives. The pre-rewrite shape was
# `"name"[[:space:]]*:[[:space:]]*"<bare-name>"` with no alternation group; that
# exact shape must now appear nowhere in tracked source outside lib/test/ (which
# carries this rule's own statement text and the fixtures below).
P927_STRAY="$(git -C "$P927_ROOT" grep -cE '"name"\[\[:space:\]\]\*:\[\[:space:\]\]\*"[A-Za-z0-9_-]+"' \
  -- ':(exclude)lib/test/' 2>/dev/null | grep -c . || true)"
assert_eq "#927 G4: no hand-written (non-derived) plugin-name discriminator literal remains in tracked source" "0" \
  "$P927_STRAY"

# G4b — the workflow/probe PLUGIN-SPEC literals. Unlike a discriminator, a
# `plugins:` install spec names exactly one published id, so dual-accept is
# meaningless there and generation would buy nothing; what those literals owe is
# equality with the manifests. Enumerate every DevFlow-owned `<plugin>@<market>`
# spec across tracked workflows and require each to be the canonical spec.
# (`scripts/resolve-extra-plugins.sh`'s baked-baseline skip sets are covered
# behaviorally by the #513 I2 coupled-site block, which drives each baked YAML
# entry through the real helper.)
P927_CANON_SPEC="$(python3 "$P927_READER" --canonical-plugin-spec 2>/dev/null || true)"
P927_MKT_ALT="$(python3 "$P927_READER" --marketplace-names 2>/dev/null | tr '\n' '|' || true)"
P927_MKT_ALT="${P927_MKT_ALT%|}"
P927_SPEC_BAD="$(git -C "$P927_ROOT" grep -hoE "[A-Za-z0-9_-]+@(${P927_MKT_ALT})" \
  -- '.github/workflows/*.yml' 2>/dev/null | grep -vxF "$P927_CANON_SPEC" | grep -c . || true)"
P927_SPEC_OK="$(git -C "$P927_ROOT" grep -hoE "[A-Za-z0-9_-]+@(${P927_MKT_ALT})" \
  -- '.github/workflows/*.yml' 2>/dev/null | grep -cxF "$P927_CANON_SPEC" || true)"
assert_eq "#927 G4b non-vacuity: the workflow plugin-spec derivation resolves real canonical-spec literals" "yes" \
  "$([ "$P927_SPEC_OK" -ge 1 ] && echo yes || echo no)"
assert_eq "#927 G4b: every DevFlow plugin-spec literal in a tracked workflow equals the canonical <plugin>@<marketplace>" "0" \
  "$P927_SPEC_BAD"

# ── G5/G6 — drift and alias propagation, driven over a real temp plugin root ──
# A throwaway copy of the identity-bearing files, so every mutation below is
# exercised end-to-end through the generator rather than simulated in a string.
p927_root() {
  local d; d="$(mktemp -d)"
  mkdir -p "$d/lib" "$d/.claude-plugin" "$d/.github/actions/vendor-plugin" "$d/.github/workflows"
  cp "$P927_ROOT/lib/plugin_identity.py" "$P927_ROOT/lib/generate-plugin-identity.py" \
     "$P927_ROOT/lib/plugin-identity.json" "$P927_ROOT/lib/resolve-jq.sh" \
     "$P927_ROOT/lib/resolve-bin.sh" "$d/lib/"
  cp "$P927_ROOT/.claude-plugin/plugin.json" "$d/.claude-plugin/"
  cp "$P927_ROOT/install.sh" "$d/"
  cp -R "$P927_ROOT/scripts" "$d/scripts"
  cp "$P927_ROOT/.github/actions/vendor-plugin/vendor-slice.sh" "$d/.github/actions/vendor-plugin/"
  cp "$P927_ROOT/.github/workflows/devflow-runner.yml" "$d/.github/workflows/"
  printf '%s' "$d"
}
p927_check() { local rc=0; python3 "$1/lib/generate-plugin-identity.py" --check >/dev/null 2>&1 || rc=$?; echo "$rc"; }

# G5(a) — manifest-side drift: rename the manifest's `name` and the baked
# regions no longer describe it. (Left unguarded this is the silent trust-ladder
# flip: the rank-1 self/base-ref gate stops matching the repo it protects.)
P927_D1="$(p927_root)"
assert_eq "#927 G5a: a pristine temp plugin root passes --check" "0" "$(p927_check "$P927_D1")"
python3 -c '
import json, sys
p = sys.argv[1] + "/.claude-plugin/plugin.json"
d = json.load(open(p)); d["name"] = d["name"] + "-drifted"
json.dump(d, open(p, "w"))
' "$P927_D1"
assert_eq "#927 G5a negative control: a renamed manifest name turns --check RED" "1" "$(p927_check "$P927_D1")"

# G5(b) — discriminator-side drift: hand-edit ONE baked region (the
# vendor-slice `self`-branch hazard) and the check must flag it.
P927_D2="$(p927_root)"
python3 -c '
import re, sys
p = sys.argv[1] + "/.github/actions/vendor-plugin/vendor-slice.sh"
t = open(p).read()
t = re.sub(r"DEVFLOW_PLUGIN_NAME_ERE=.*", "DEVFLOW_PLUGIN_NAME_ERE=\x27\"name\"[[:space:]]*:[[:space:]]*\"(impostor)\"\x27", t, count=1)
open(p, "w").write(t)
' "$P927_D2"
assert_eq "#927 G5b negative control: one hand-edited baked discriminator turns --check RED" "1" "$(p927_check "$P927_D2")"

# G5(c) — a dropped alias key is unestablished, not "no aliases": the reader
# fails closed rather than silently narrowing the accepted set.
P927_D3="$(p927_root)"
python3 -c '
import json, sys
p = sys.argv[1] + "/lib/plugin-identity.json"
d = json.load(open(p)); d.pop("plugin_aliases")
json.dump(d, open(p, "w"))
' "$P927_D3"
# rc 2 (not 1) is the correct code: this is a SOURCE defect, not baked-region
# drift — the check distinguishes the two so a remedy is not misdirected.
assert_eq "#927 G5c: a missing plugin_aliases key fails closed (reader errors, --check RED)" "2" "$(p927_check "$P927_D3")"

# G6 — alias propagation: declaring one alias must reach EVERY baked region and
# produce an ERE that accepts both the canonical name and the alias while still
# rejecting an unrelated one. This is the property the whole mechanism exists
# for, and it is asserted behaviorally (the ERE is run against real manifests),
# not by reading the generator's intent back out of itself.
P927_D4="$(p927_root)"
python3 -c '
import json, sys
p = sys.argv[1] + "/lib/plugin-identity.json"
d = json.load(open(p)); d["plugin_aliases"] = ["p927alias"]
json.dump(d, open(p, "w"))
' "$P927_D4"
assert_eq "#927 G6: an added alias makes the baked regions stale until regenerated" "1" "$(p927_check "$P927_D4")"
python3 "$P927_D4/lib/generate-plugin-identity.py" >/dev/null 2>&1 || true
assert_eq "#927 G6: regenerating after the alias restores --check" "0" "$(p927_check "$P927_D4")"
P927_ALIAS_MISSES=0
while IFS= read -r _f; do
  [ -n "$_f" ] || continue
  grep -q 'p927alias' "$P927_D4/$_f" || P927_ALIAS_MISSES=$((P927_ALIAS_MISSES+1))
done <<< "$P927_REGION_FILES"
assert_eq "#927 G6: the declared alias reached EVERY generated region (none missed)" "0" "$P927_ALIAS_MISSES"
# Behavioral: run the generated ERE against real manifest bytes.
P927_ERE="$(python3 "$P927_D4/lib/plugin_identity.py" --plugin-name-ere 2>/dev/null || true)"
P927_FIX="$(mktemp -d)"
printf '{"name": "%s"}\n' "$P927_MAN_NAME"  > "$P927_FIX/canonical.json"
printf '{"name":"p927alias"}\n'             > "$P927_FIX/alias.json"
printf '{"name":"p927alias-suffixed"}\n'    > "$P927_FIX/near-miss.json"
printf '{"name":"unrelated-plugin"}\n'      > "$P927_FIX/foreign.json"
p927_match() { grep -Eq "$P927_ERE" "$P927_FIX/$1" && echo yes || echo no; }
assert_eq "#927 G6 behavior: the derived ERE accepts the canonical manifest name" "yes" "$(p927_match canonical.json)"
assert_eq "#927 G6 behavior: the derived ERE accepts the declared alias" "yes" "$(p927_match alias.json)"
assert_eq "#927 G6 behavior: the derived ERE rejects a name the alias is only a prefix of" "no" "$(p927_match near-miss.json)"
assert_eq "#927 G6 behavior: the derived ERE rejects an unrelated plugin name" "no" "$(p927_match foreign.json)"
# …and an ERE metacharacter in a declared name is refused outright rather than
# baked into an alternation where it would silently widen the discriminator.
P927_D5="$(p927_root)"
python3 -c '
import json, sys
p = sys.argv[1] + "/lib/plugin-identity.json"
d = json.load(open(p)); d["plugin_aliases"] = [".*"]
json.dump(d, open(p, "w"))
' "$P927_D5"
assert_eq "#927 G6: an ERE-metacharacter alias is refused (never widens the discriminator)" "2" "$(p927_check "$P927_D5")"

# G6b — EVERY discriminator call site carries a non-empty precondition. The
# vendor-slice self branch's fail-closed behavior is locked behaviorally in the
# vendor-slice block below; this is the class guard for the sites that have no
# drivable unit (the five FETCH_HEAD-gated workflow arms and install.sh's
# destructive prune). `grep -Eq ""` matches ANY input, so an unguarded call site
# fails OPEN on a trust boundary — a new one must not be able to slip in green.
# structural-pin-ok: security-credential-boundary -- the guard IS the trust
# discriminator's precondition; a call site without one silently match-alls.
P927_ERE_CALLS=0
P927_ERE_GUARDS=0
for _f in .github/workflows/devflow-runner.yml install.sh \
          .github/actions/vendor-plugin/vendor-slice.sh; do
  P927_ERE_CALLS=$((P927_ERE_CALLS + $(grep -cF 'grep -Eq "$DEVFLOW_PLUGIN_NAME_ERE"' "$P927_ROOT/$_f" || true)))
  P927_ERE_GUARDS=$((P927_ERE_GUARDS + $(grep -cE '\[ -n "\$\{?DEVFLOW_PLUGIN_NAME_ERE(:-\})?" \]' "$P927_ROOT/$_f" || true)))
done
assert_eq "#927 G6b non-vacuity: the discriminator has call sites to guard" "yes" \
  "$([ "$P927_ERE_CALLS" -gt 0 ] && echo yes || echo no)"
assert_eq "#927 G6b: every discriminator call site carries a non-empty precondition (never a match-all fail-open)" \
  "$P927_ERE_CALLS" "$P927_ERE_GUARDS"

# G7 — the reader's MALFORMED-SHAPE matrix, driven directly against
# `plugin_identity.load()`. The module's contract is "every accessor raises
# IdentityError rather than substituting a default", and the two manifests are
# hand-editable JSON, so this is the repo's adversarial-input-matrix discipline
# applied to that reader: each row mutates ONE field of an otherwise-valid pair
# and asserts a fail-CLOSED raise. Row `00-baseline-valid` is the positive
# control — without it a row that raised for some unrelated reason (a fixture
# the harness never made valid in the first place) would read as a pass.
P927_SHAPES="$(python3 - "$P927_ROOT" <<'P927SHAPES' 2>&1 || true
import json, pathlib, sys, importlib.util, tempfile

root = pathlib.Path(sys.argv[1])
spec = importlib.util.spec_from_file_location("pid", root / "lib" / "plugin_identity.py")
pid = importlib.util.module_from_spec(spec)
spec.loader.exec_module(pid)

BASE_MANIFEST = {"name": "devflow"}
BASE_IDENTITY = {
    "identity_version": 1,
    "plugin_aliases": [],
    "marketplace_canonical": "devflow-marketplace",
    "marketplace_aliases": [],
}

# (row id, manifest override or None, identity override or None, raw identity text or None)
ROWS = [
    ("00-baseline-valid", None, None, None),
    ("manifest-not-object", [], None, None),
    ("manifest-name-missing", {}, None, None),
    ("manifest-name-empty", {"name": ""}, None, None),
    ("manifest-name-wrong-type", {"name": 7}, None, None),
    ("identity-not-object", None, None, "[]"),
    ("identity-not-json", None, None, "{oops"),
    ("identity-empty-file", None, None, ""),
    ("version-missing", None, {"identity_version": None}, None),
    ("version-wrong-type", None, {"identity_version": "1"}, None),
    ("version-zero", None, {"identity_version": 0}, None),
    ("version-bool", None, {"identity_version": True}, None),
    ("plugin-aliases-missing", None, {"plugin_aliases": None}, None),
    ("plugin-aliases-scalar", None, {"plugin_aliases": "devflow2"}, None),
    ("plugin-aliases-object", None, {"plugin_aliases": {}}, None),
    ("plugin-aliases-empty-entry", None, {"plugin_aliases": [""]}, None),
    ("plugin-aliases-nonstring-entry", None, {"plugin_aliases": [3]}, None),
    ("plugin-aliases-repeats-canonical", None, {"plugin_aliases": ["devflow"]}, None),
    ("plugin-alias-ere-metachar", None, {"plugin_aliases": [".*"]}, None),
    ("plugin-alias-space", None, {"plugin_aliases": ["a b"]}, None),
    ("market-canonical-missing", None, {"marketplace_canonical": None}, None),
    ("market-canonical-empty", None, {"marketplace_canonical": ""}, None),
    ("market-canonical-wrong-type", None, {"marketplace_canonical": []}, None),
    ("market-canonical-space", None, {"marketplace_canonical": "a b"}, None),
    ("market-aliases-missing", None, {"marketplace_aliases": None}, None),
    ("market-aliases-scalar", None, {"marketplace_aliases": 0}, None),
    ("market-aliases-repeats-canonical", None, {"marketplace_aliases": ["devflow-marketplace"]}, None),
    ("market-alias-metachar", None, {"marketplace_aliases": ["a|b"]}, None),
]

with tempfile.TemporaryDirectory() as td:
    base = pathlib.Path(td)
    (base / "lib").mkdir()
    (base / ".claude-plugin").mkdir()
    for row, man, iden, raw in ROWS:
        manifest = BASE_MANIFEST if man is None else man
        (base / ".claude-plugin" / "plugin.json").write_text(json.dumps(manifest))
        if raw is not None:
            (base / "lib" / "plugin-identity.json").write_text(raw)
        else:
            merged = dict(BASE_IDENTITY)
            for k, v in (iden or {}).items():
                if v is None:
                    merged.pop(k, None)
                else:
                    merged[k] = v
            (base / "lib" / "plugin-identity.json").write_text(json.dumps(merged))
        try:
            pid.load(base)
            print(f"{row}=ok")
        except pid.IdentityError:
            print(f"{row}=IdentityError")
        except Exception as exc:            # any OTHER exception is a fail-OPEN escape
            print(f"{row}=UNCAUGHT:{type(exc).__name__}")
P927SHAPES
)"
P927_SHAPES_WANT='00-baseline-valid=ok'
while IFS= read -r _row; do
  case "$_row" in 00-baseline-valid*|'') continue ;; esac
  P927_SHAPES_WANT="$P927_SHAPES_WANT
${_row%%=*}=IdentityError"
done <<< "$P927_SHAPES"
assert_eq "#927 G7: every malformed identity/manifest shape fails closed with IdentityError" \
  "$P927_SHAPES_WANT" "$P927_SHAPES"
# Non-vacuity, count-free (a transcribed row total would rot on the next row
# added): the expectation above is derived from the observed row NAMES only —
# each is forced to `=IdentityError`, so an `ok`, an `UNCAUGHT:` escape, or a
# python3 traceback all diverge from it. What is left to prove is that the
# matrix drove MORE than its positive control.
assert_eq "#927 G7 non-vacuity: the shape matrix drove malformed rows, not just the control" "yes" \
  "$([ "$(printf '%s\n' "$P927_SHAPES" | grep -c '=IdentityError$' || true)" -gt 0 ] && echo yes || echo no)"

unset P927_GEN P927_MAN_NAME P927_MKT_NAME P927_CHECK_RC P927_SHAPES P927_SHAPES_WANT
unset P927_REGION_FILES P927_REGION_COUNT P927_BANNER_FILES P927_BAD_REGION P927_BODY P927_STRAY
unset P927_D1 P927_D2 P927_D3 P927_D4 P927_D5 P927_ALIAS_MISSES P927_ERE P927_FIX
unset P927_CANON_SPEC P927_MKT_ALT P927_SPEC_BAD P927_SPEC_OK
unset -f p927_check p927_match

# ── identity: the runtime-derived consumers ──────────────────────────────────
# A declared alias widens every downstream consumer's accepted set without any of
# them being re-edited — the runtime readers (resolve-review-overrides.py,
# provision-local-settings.sh) because they resolve it live, and the baked helper
# (resolve-extra-plugins.sh) because the region is regenerated below.
# Driven over a temp plugin root exactly like the block above.
PIDR="$(p927_root)"
python3 -c '
import json, sys
p = sys.argv[1] + "/lib/plugin-identity.json"
d = json.load(open(p))
d["plugin_aliases"] = ["pidalias"]
d["marketplace_aliases"] = ["pidalias-marketplace"]
json.dump(d, open(p, "w"))
' "$PIDR"
# Regenerate so the BAKED regions in the copied surfaces carry the alias too — the
# whole point is that a declared alias reaches every consumer without a hand edit.
python3 "$PIDR/lib/generate-plugin-identity.py" >/dev/null 2>&1 || true

# resolve-review-overrides.py — the closed agent_overrides allowlist accepts the
# alias namespace and still rejects an unrelated one (it is a CLOSED list: the
# widening must be exactly the declared alias, not "anything").
pid_unknown() {
  python3 "$PIDR/scripts/resolve-review-overrides.py" --config-get /usr/bin/false "$1" 2>&1 \
    | grep -c "is not a known" || true
}
# The fixture REPLACED plugin_aliases with `pidalias`, so the accepted set here is
# {canonical, pidalias} and the real tree's alias is deliberately not in it. Read the
# canonical namespace from the fixture's own identity source rather than spelling it:
# a literal here would silently become "an alias that happens to be declared today"
# after a plugin rename, which is the opposite of what this assertion means to prove.
PID_CANON="$(python3 "$PIDR/lib/plugin_identity.py" --agent-namespaces 2>/dev/null | head -n1)"
assert_eq "identity: the fixture's canonical namespace resolved" "yes" \
  "$(case "$PID_CANON" in *:) echo yes ;; *) echo no ;; esac)"
assert_eq "identity: agent_overrides accepts the canonical namespace" "0" "$(pid_unknown "${PID_CANON}code-reviewer")"
assert_eq "identity: agent_overrides accepts a declared alias namespace" "0" "$(pid_unknown "pidalias:code-reviewer")"
assert_eq "identity: agent_overrides still rejects an undeclared namespace" "1" "$(pid_unknown "impostor:code-reviewer")"
assert_eq "identity: agent_overrides still rejects an unknown leaf under an accepted namespace" "1" \
  "$(pid_unknown "pidalias:not-a-real-agent")"

# …and its DEGRADED arm, the one the closed allowlist depends on behaving well:
# with the identity source unreadable the accepted namespace set is UNESTABLISHED,
# not empty. The run must say so once, emit NO per-agent drift warning (calling
# every dispatched id unknown would be a fabricated diagnosis — unknown is not
# zero), still exit 0, and still resolve overrides.
PIDU="$(mktemp -d)"
mkdir -p "$PIDU/lib" "$PIDU/.claude-plugin"
cp -R "$PIDR/scripts" "$PIDU/scripts"
cp "$PIDR/lib/plugin_identity.py" "$PIDU/lib/"
cp "$PIDR/.claude-plugin/plugin.json" "$PIDU/.claude-plugin/"   # deliberately no lib/plugin-identity.json
PIDU_RC=0
PIDU_OUT="$(python3 "$PIDU/scripts/resolve-review-overrides.py" --config-get /usr/bin/false \
  devflow:code-reviewer impostor:code-reviewer 2>"$PIDU/err")" || PIDU_RC=$?
assert_eq "identity degraded: an unreadable identity source still exits 0" "0" "$PIDU_RC"
assert_eq "identity degraded: the unestablished namespace set is reported once" "1" \
  "$(grep -c 'the accepted plugin-namespace set could not be established' "$PIDU/err" || true)"
assert_eq "identity degraded: no per-agent drift warning is fabricated" "0" \
  "$(grep -c 'is not a known' "$PIDU/err" || true)"
assert_eq "identity degraded: overrides still resolve (a JSON object on stdout)" "yes" \
  "$(printf '%s' "$PIDU_OUT" \
     | python3 -c 'import json,sys; print("yes" if isinstance(json.load(sys.stdin), dict) else "no")' \
     2>/dev/null || echo no)"
# POSITIVE CONTROL on the same fixture — restore ONLY the identity file: the
# degraded arm falls silent and the genuine drift warning appears. Without this,
# a rejection from some unrelated precondition would read as a passing test of
# the identity arm.
cp "$PIDR/lib/plugin-identity.json" "$PIDU/lib/"
# The restored file is the FIXTURE's identity (plugin_aliases replaced with pidalias),
# so the known id must be the fixture's CANONICAL namespace, not the real tree's alias.
python3 "$PIDU/scripts/resolve-review-overrides.py" --config-get /usr/bin/false \
  "${PID_CANON}code-reviewer" impostor:code-reviewer >/dev/null 2>"$PIDU/err2" || true
assert_eq "identity degraded positive control: with the identity file present the arm is silent" "0" \
  "$(grep -c 'the accepted plugin-namespace set could not be established' "$PIDU/err2" || true)"
assert_eq "identity degraded positive control: the genuine drift warning does fire" "1" \
  "$(grep -c 'is not a known' "$PIDU/err2" || true)"

# resolve-extra-plugins.sh — a consumer settings file naming the ALIAS spec must
# be treated as DevFlow's own (silently skipped, already installed by the baked
# baseline) instead of emitted as a third-party plugin to compose.
PIDS="$(mktemp -d)"
cat > "$PIDS/settings.json" <<'PIDJSON'
{
  "extraKnownMarketplaces": {
    "pidalias-marketplace": { "source": { "source": "github", "repo": "x/y" } },
    "other-market": { "source": { "source": "github", "repo": "a/b" } }
  },
  "enabledPlugins": {
    "pidalias@pidalias-marketplace": true,
    "third-party@other-market": true
  }
}
PIDJSON
assert_eq "identity: resolve-extra-plugins skips the alias plugin spec as DevFlow's own" "" \
  "$(bash "$PIDR/scripts/resolve-extra-plugins.sh" plugins "$PIDS/settings.json" 2>/dev/null | grep 'pidalias' || true)"
assert_eq "identity: resolve-extra-plugins still emits a genuine third-party plugin" "third-party@other-market" \
  "$(bash "$PIDR/scripts/resolve-extra-plugins.sh" plugins "$PIDS/settings.json" 2>/dev/null)"
assert_eq "identity: resolve-extra-plugins skips the alias marketplace, keeps the foreign one" "https://github.com/a/b.git" \
  "$(bash "$PIDR/scripts/resolve-extra-plugins.sh" marketplaces "$PIDS/settings.json" 2>/dev/null)"
# PLANTED DEFECT for its empty-baked-set fail-closed arm: empty the generated
# identity region (the shape a missing or un-regenerated region produces). An
# empty set is UNESTABLISHED, not "DevFlow owns nothing" — treating it as the
# latter would emit DevFlow's own entries back to the compose step as
# third-party plugins. The three assertions above are this row's positive
# control: the same fixture, the unmutated helper, real output.
PIDE="$(mktemp -d)"
python3 -c '
import sys
src, dst = sys.argv[1], sys.argv[2]
s = open(src).read()
for k in ("DEVFLOW_PLUGIN_NAMES", "DEVFLOW_MARKETPLACE_NAMES"):
    before = s
    s = s.replace("\n" + k + "=\x27", "\n" + k + "=\x27\x27  #", 1)
    assert s != before, k
open(dst, "w").write(s)
' "$PIDR/scripts/resolve-extra-plugins.sh" "$PIDE/resolve-extra-plugins.sh"
PIDE_RC=0
PIDE_OUT="$(bash "$PIDE/resolve-extra-plugins.sh" plugins "$PIDS/settings.json" 2>"$PIDE/err")" || PIDE_RC=$?
assert_eq "identity planted defect: an emptied baked identity region still exits 0" "0" "$PIDE_RC"
assert_eq "identity planted defect: an emptied baked identity region emits nothing" "" "$PIDE_OUT"
assert_eq "identity planted defect: it names the unestablished identifier set (not a generic breadcrumb)" "1" \
  "$(grep -c 'the accepted DevFlow plugin/marketplace identifier set is empty or unset' "$PIDE/err" || true)"

# provision-local-settings.sh — provisioning MIGRATES: it writes the canonical
# registration and removes the superseded (alias) one, so a repo provisioned
# under a previously-declared id is never left with two live registrations.
PIDP="$(mktemp -d)"
mkdir -p "$PIDP/.claude"
cp "$PIDS/settings.json" "$PIDP/.claude/settings.json"
bash "$PIDR/scripts/provision-local-settings.sh" "$PIDP" >/dev/null 2>&1 || true
pid_have() { python3 -c '
import json, sys
d = json.load(open(sys.argv[1]))
print("yes" if sys.argv[3] in (d.get(sys.argv[2]) or {}) else "no")
' "$PIDP/.claude/settings.json" "$1" "$2"; }
assert_eq "identity: provisioning removes the superseded marketplace registration" "no" \
  "$(pid_have extraKnownMarketplaces pidalias-marketplace)"
assert_eq "identity: provisioning removes the superseded enabledPlugins spec" "no" \
  "$(pid_have enabledPlugins "pidalias@pidalias-marketplace")"
assert_eq "identity: provisioning writes the canonical marketplace registration" "yes" \
  "$(pid_have extraKnownMarketplaces "$(python3 "$PIDR/lib/plugin_identity.py" --json | python3 -c 'import json,sys; print(json.load(sys.stdin)["marketplace_canonical"])')")"
assert_eq "identity: provisioning writes the canonical enabledPlugins spec" "yes" \
  "$(pid_have enabledPlugins "$(python3 "$PIDR/lib/plugin_identity.py" --canonical-plugin-spec)")"
assert_eq "identity: provisioning leaves an unrelated marketplace untouched" "yes" \
  "$(pid_have extraKnownMarketplaces other-market)"
assert_eq "identity: provisioning leaves an unrelated plugin untouched" "yes" \
  "$(pid_have enabledPlugins "third-party@other-market")"
# …and it FAILS CLOSED (exit 2, file byte-for-byte unchanged) when the identity
# source cannot be established — never guessing a key name.
PIDF="$(mktemp -d)"
mkdir -p "$PIDF/.claude"
printf '{"a":1}\n' > "$PIDF/.claude/settings.json"
PIDBROKEN="$(mktemp -d)"
mkdir -p "$PIDBROKEN/lib" "$PIDBROKEN/.claude-plugin"
cp -R "$PIDR/scripts" "$PIDBROKEN/scripts"
cp "$PIDR/lib/plugin_identity.py" "$PIDR/lib/resolve-jq.sh" "$PIDR/lib/resolve-bin.sh" "$PIDBROKEN/lib/"
cp "$PIDR/.claude-plugin/plugin.json" "$PIDBROKEN/.claude-plugin/"   # no lib/plugin-identity.json
PIDF_RC=0
bash "$PIDBROKEN/scripts/provision-local-settings.sh" "$PIDF" >/dev/null 2>&1 || PIDF_RC=$?
assert_eq "identity: provisioning fails closed (exit 2) when the identity source is unreadable" "2" "$PIDF_RC"
assert_eq "identity: the fail-closed provisioning run left the settings file byte-for-byte unchanged" '{"a":1}' \
  "$(cat "$PIDF/.claude/settings.json")"

unset PIDR PIDS PIDP PIDF PIDBROKEN PIDF_RC PIDU PIDU_RC PIDU_OUT PIDE PIDE_RC PIDE_OUT
unset P927_ROOT P927_READER
unset -f p927_root
unset -f pid_unknown pid_have

# ── #402: deny-floor helper — direct adversarial-matrix drive ────────────────
# filter-runner-tools.sh is the AUTHORITATIVE deny-list floor. Drive it directly
# over the full input matrix, asserting BOTH channels per row: the kept list on
# stdout AND the per-entry strip warnings on stderr. This is the unit surface the
# extraction exists to expose (inline YAML could not be tested); the workflow's
# call of it stays covered end-to-end by the emit_tools behavioral block below.
frt_out()  { RUNNER_TOOLS="$1" bash "$FRT" 2>/dev/null; }               # kept list (stdout)
frt_strip(){ RUNNER_TOOLS="$1" bash "$FRT" 2>&1 1>/dev/null \
              | grep -c "^prflow_runner.allowed_tools: stripped " || true; }  # # of strip lines
# --- kept list (stdout), the #402 file-tool tightening: bare AND parameterized ---
assert_eq "#402 helper: Write(**) stripped (parameterized file-tool)" "" "$(frt_out 'Write(**)')"
assert_eq "#402 helper: Edit(src/**) stripped (parameterized file-tool)" "" "$(frt_out 'Edit(src/**)')"
assert_eq "#402 helper: notebookedit(x) stripped (case-insensitive parameterized)" "" "$(frt_out 'notebookedit(x)')"
assert_eq "#402 helper: bare Write still stripped" "" "$(frt_out 'Write')"
assert_eq "#402 helper: bare Edit still stripped" "" "$(frt_out 'Edit')"
assert_eq "#402 helper: bare MultiEdit still stripped" "" "$(frt_out 'MultiEdit')"
assert_eq "#402 helper: bare NotebookEdit still stripped" "" "$(frt_out 'NotebookEdit')"
# Individual DENY_CMDS words beyond the head of the list (exec/source/dash ride the
# same `for c in $DENY_CMDS` loop) — pin a few so an accidental deletion of a word
# from DENY_CMDS in the helper is caught, not only the grep prefix-pin of the head.
assert_eq "#402 helper: Bash(exec sh:*) stripped (exec in DENY_CMDS)" "" "$(frt_out 'Bash(exec sh:*)')"
assert_eq "#402 helper: Bash(source x:*) stripped (source in DENY_CMDS)" "" "$(frt_out 'Bash(source x:*)')"
