# ────────────────────────────────────────────────────────────────────────────
echo "subagent tool-boundary allowlists (agents/*.md)"
# ────────────────────────────────────────────────────────────────────────────
# Every DevFlow-authored subagent declares an explicit `tools:` allowlist, so the read-only
# advisory policy each one states in its own body is enforced by the harness rather than only
# requested in prose. Two measured facts drive the shape of these rows:
#   - An empty `tools:` value (bare key, `[]`, or `""`) parses IDENTICALLY to omitting the key
#     — the agent inherits EVERY tool (measured on Claude Code 2.1.220 by probing all four
#     forms against a control). So an emptied value is a silent fail-OPEN of this boundary,
#     never a tightening: each row proves the value is non-empty BEFORE testing what it omits,
#     exactly the "guard whose comparand can be absent fails open" class in CLAUDE.md.
#   - Agent frontmatter has no deny/disallow key, so the allowlist is the only lever.
# Write is granted to exactly ONE agent — checklist-verifier — because its Phase 2.1b dispatch
# prompt (skills/review/phases/phase-2-verification.md) instructs it to Write its verdict JSON
# to {VERDICT_FILE}. Granting Write to any other agent here contradicts that agent's own
# stated working-tree policy, which is why the expectation is per-agent, not global.
# NOTE: this boundary is name-level, not a claim of read-only-ness — the six agents that hold
# Bash can still reach the tree through it (`sed -i`, `git checkout --`). It closes the
# tool-shaped path; the Phase-3 dirty-tree snapshot guard remains the behavioral backstop.
AGENT_TOOL_ROSTER="checklist-deduper checklist-generator checklist-verifier code-reviewer"
AGENT_TOOL_ROSTER="$AGENT_TOOL_ROSTER comment-analyzer pr-test-analyzer silent-failure-hunter"
AGENT_TOOL_ROSTER="$AGENT_TOOL_ROSTER type-design-analyzer"
for a in $AGENT_TOOL_ROSTER; do
  # structural-pin-ok: security-credential-boundary -- the `tools:` line IS the runtime tool
  # boundary the harness parses for a dispatched subagent; no other surface constrains what a
  # dispatched review agent may do to the working tree.
  atools="$(grep -E '^tools:[[:space:]]' "$FDROOT/agents/$a.md" | head -1)"
  atools_value="${atools#tools:}"
  case "$atools_value" in
    *[![:space:]]*) atools_nonempty=yes ;;
    *) atools_nonempty=no ;;
  esac
  # Fail CLOSED on an absent/emptied/reformatted value: an empty capture would make every
  # omission row below pass VACUOUSLY (printf '' | grep -qw -> "no") while the agent had in
  # fact reverted to inheriting all tools — the precise fail-open this block exists to catch.
  assert_eq "#agent-tools agents/$a.md declares a NON-EMPTY tools: value (empty == inherits all tools)" \
    "yes" "$atools_nonempty"
  for denied in Edit MultiEdit NotebookEdit Task; do
    assert_eq "#agent-tools agents/$a.md tools: omits $denied" \
      "no" "$(printf '%s' "$atools_value" | grep -qw "$denied" && echo yes || echo no)"  # raw-guard-ok: loop body: the pattern is the $denied loop variable, not a static pin
  done
  # Write: expected on checklist-verifier (its dispatch prompt mandates the verdict-file
  # write), asserted ABSENT on every other agent — asserted both ways so neither a dropped
  # grant that would break Phase 2 nor a spread grant that would breach the policy is silent.
  case "$a" in
    checklist-verifier) atools_write_expected=yes ;;
    *) atools_write_expected=no ;;
  esac
  assert_eq "#agent-tools agents/$a.md tools: Write grant matches its dispatch contract" \
    "$atools_write_expected" "$(printf '%s' "$atools_value" | grep -qw 'Write' && echo yes || echo no)"
done

# --- #1575: Phase-3.4 AC verifier tool boundaries (issue #1575). ---
# The two dispatched Phase-3.4 verifiers must not write, edit, or dispatch a further
# subagent (AC7), and the claim verifier must EXECUTE NOTHING — so it holds no Bash while
# the evidence verifier (the only one that runs a verification command) does. Assert each
# boundary the same way the review-agent roster above does: prove the tools: value is
# non-empty (empty == inherits every tool) before testing what it omits.
for acv in ac-evidence-verifier ac-claim-verifier; do
  # structural-pin-ok: security-credential-boundary -- the `tools:` line IS the runtime tool
  # boundary the harness parses for a dispatched subagent; no other surface constrains what
  # a dispatched Phase-3.4 verifier may do to the working tree.
  acv_tools="$(grep -E '^tools:[[:space:]]' "$FDROOT/agents/$acv.md" | head -1)"
  acv_value="${acv_tools#tools:}"
  case "$acv_value" in
    *[![:space:]]*) acv_nonempty=yes ;;
    *) acv_nonempty=no ;;
  esac
  assert_eq "#1575 agents/$acv.md declares a NON-EMPTY tools: value (empty == inherits all tools)" \
    "yes" "$acv_nonempty"
  for denied in Write Edit MultiEdit NotebookEdit Task Agent; do
    assert_eq "#1575 agents/$acv.md tools: omits $denied" \
      "no" "$(printf '%s' "$acv_value" | grep -qw "$denied" && echo yes || echo no)"  # raw-guard-ok: loop body: the pattern is the $denied loop variable, not a static pin
  done
  # Bash: expected on the evidence verifier (it runs the in-env verification command),
  # asserted ABSENT on the claim verifier (which executes nothing) — both directions, so
  # neither a dropped grant that would break command verification nor a spread grant that
  # would let the claim verifier execute is silent.
  case "$acv" in
    ac-evidence-verifier) acv_bash_expected=yes ;;
    *) acv_bash_expected=no ;;
  esac
  assert_eq "#1575 agents/$acv.md tools: Bash grant matches its dispatch contract" \
    "$acv_bash_expected" "$(printf '%s' "$acv_value" | grep -qw 'Bash' && echo yes || echo no)"
done

# --- #191: retain the review agents' complete-location-set deliverable boundary. ---
assert_pin_unique "#191 code-reviewer includes the complete location set in the finding body before submitting" \
  'include the complete location set in the finding body before submitting' "$FDROOT/agents/code-reviewer.md"
assert_pin_unique "#191 comment-analyzer includes the complete location set in the finding body before submitting" \
  'include the complete location set in the finding body before submitting' "$FDROOT/agents/comment-analyzer.md"

# (5) Workflow contract: no cloud workflow installs the pr-review-toolkit companion anymore
# (the engine dispatches the first-party devflow: review agents). Pattern split-literal to
# avoid self-match; shares the tracked_scan seam as (1).
WF_PRT="pr-review-""toolkit@claude-plugins-official"
assert_eq "#141 no cloud workflow installs the pr-review-toolkit companion plugin" \
  "" "$(tracked_scan "$FDROOT" "$WF_PRT" '.github/workflows')"

# (6) Positive roster-doc rewire (AC8 names three docs that must describe the internalized
# roster). The absence scan (1) catches a leftover OLD id but not a doc that DROPPED the
# roster mention entirely, so pin each AC8 doc positively. review-agent-overrides.md needs
# this most — it is EXCLUDED from (1) (it carries the old-id migration table), so its
# operative override example would otherwise be unguarded; the other two are inside (1)'s
# scan but a dropped-mention regression is still invisible to a negative scan.
assert_eq "#141 docs/internal/review-agent-overrides.md operative example uses the internalized devflow: key" \
  "yes" "$(grep -qF '"devflow:code-reviewer": { "model"' "$FDROOT/docs/internal/review-agent-overrides.md" && echo yes || echo no)"
for d in DEVFLOW_SYSTEM_OVERVIEW.md shadow-review.md; do
  assert_eq "#141 docs/$d describes the internalized first-party review roster (devflow:code-reviewer present)" \
    "yes" "$(grep -qF 'devflow:code-reviewer' "$FDROOT/docs/internal/$d" && echo yes || echo no)"
done

# ────────────────────────────────────────────────────────────────────────────
echo "superpowers internalization (#142)"
# ────────────────────────────────────────────────────────────────────────────
# Seam 3 (final) of #139: vendors the TWO runtime-dispatched superpowers SKILLS —
# requesting-code-review (the review engine's general-purpose final-pass reviewer) and
# receiving-code-review (the fix-loop principles) — as first-party DevFlow skills under
# skills/, rewires their call-sites + the final-pass override key to the devflow: namespace,
# retires the optional using-git-worktrees reference, and removes the LAST companion
# dependency so DevFlow ships ZERO companion-plugin install dependencies. writing-skills is
# DELIBERATELY NOT vendored: it is a development-time SKILL.md-authoring discipline DevFlow's
# own contributors invoke, never something the engine dispatches at runtime, so it stays the
# EXTERNAL superpowers:writing-skills skill (referenced only in CLAUDE.md's conventions) — the
# (1c) un-fork assertions below pin that. Unlike #139/#141 (which vendored AGENTS under
# agents/), this seam vendors SKILLS under skills/, and the upstream is MIT-licensed (Jesse
# Vincent), NOT Apache-2.0/Anthropic. These assertions are the mechanical proof the
# internalization is COMPLETE; they reuse the same fail-closed tracked_scan seam (the #129
# rgb_classify rc-handling backs them).
SP_SKILLS="requesting-code-review receiving-code-review"

# (1) Reference contract (AC4): NO operative surface may reference the old namespaced
# identifier for the two internalized skills (the plugin-name + colon form). Excepted:
# .prflow/logs (append-only audit scratch), CHANGELOG.md (historical entries + the #142
# breaking-rename entry, which necessarily names the old override key), and (for the final-
# pass key only) docs/internal/review-agent-overrides.md (carries the old->new migration table) —
# mirrors the #141 migration-doc exception. Patterns are split-literal so this run.sh never
# self-matches its own grep, and the descriptions avoid the contiguous colon form for the
# same reason (a description literal would itself be a tracked hit). writing-skills is NOT
# here: it stays external, so superpowers:writing-skills is EXPECTED on CLAUDE.md (pinned
# positively in (1c)), not forbidden.
SP_PAT_REQ="superpowers:""requesting-code-review"
SP_PAT_REC="superpowers:""receiving-code-review"
assert_eq "#142 no operative surface references the old namespaced requesting-code-review id (logs/CHANGELOG/migration-doc excepted)" \
  "" "$(tracked_scan "$FDROOT" "$SP_PAT_REQ" ':!.prflow/logs' ':!CHANGELOG.md' ':!docs/internal/review-agent-overrides.md')"
assert_eq "#142 no operative surface references the old namespaced receiving-code-review id (logs/CHANGELOG excepted)" \
  "" "$(tracked_scan "$FDROOT" "$SP_PAT_REC" ':!.prflow/logs' ':!CHANGELOG.md')"

# (1c) writing-skills un-fork contract: writing-skills is a development-time discipline, NOT a
# DevFlow runtime skill, so it must NOT be vendored first-party — the skills/writing-skills/
# tree is absent — and CLAUDE.md's "invoke writing-skills before editing a SKILL.md" convention
# must reference the EXTERNAL superpowers:writing-skills id (a dev-time tool, not a consumer/
# runtime plugin dependency, so the zero-companion-dependency claim is unaffected). Pin both
# directions so a future re-fork — re-adding skills/writing-skills/ or flipping the CLAUDE.md
# reference back to devflow:writing-skills — fails loud here. Split-literal so this run.sh
# never self-matches its own grep.
SP_PAT_WRI_DEV="superpowers:""writing-skills"
assert_eq "#142 writing-skills is NOT vendored first-party (skills/writing-skills/ absent — dev-time tool, not a runtime skill)" \
  "no" "$([ -d "$FDROOT/skills/writing-skills" ] && echo yes || echo no)"
assert_eq "#142 CLAUDE.md references the EXTERNAL superpowers:writing-skills authoring convention (not a vendored devflow: id)" \
  "yes" "$(grep -qF "$SP_PAT_WRI_DEV" "$FDROOT/CLAUDE.md" && echo yes || echo no)"
assert_eq "#142 CLAUDE.md does NOT claim a vendored first-party devflow:writing-skills skill" \
  "no" "$(grep -qF 'devflow:writing-skills' "$FDROOT/CLAUDE.md" && echo yes || echo no)"

# (1d) Broadened residual contract: beyond the two internalized ids, NO operative surface
# may carry ANY bare `superpowers:` namespaced identifier. (1)'s two split-literal scans
# only catch the internalized ids; this fails closed on a stray reference to a *non*-
# internalized superpowers skill too. CLAUDE.md is excepted because it intentionally carries
# the one legitimate external reference — superpowers:writing-skills, the dev-time authoring
# discipline pinned in (1c); the internalized requesting/receiving ids are still covered on
# CLAUDE.md by (1)'s repo-wide scans, and using-git-worktrees by (6), so excepting CLAUDE.md
# here only narrows this net to "no OTHER stray superpowers: ref outside CLAUDE.md." Same
# history/migration exceptions as (1), PLUS .prflow/learnings — append-only retrospective
# audit data (same category as .prflow/logs and CHANGELOG history): an entry legitimately
# quotes a past run's "superpowers:writing-skills was unavailable" reflection, so the
# historical record naturally names the id it reports on. PLUS lib/test — this suite's own scaffolding
# necessarily names the forbidden pattern to assert its absence, and a guard cannot scan
# itself. Excepting all of lib/test leaves a narrow blind spot: a stray *non-internalized*
# superpowers: id introduced into a non-scaffolding test helper would slip THIS broad scan.
# That residual is mitigated because (1)'s targeted requesting/receiving scans are NOT path-
# scoped (they would still catch the two internalized ids anywhere in lib/test); only a brand-
# new reference to some OTHER superpowers skill, placed in lib/test, would evade detection.
# Pattern split-literal so this run.sh never self-matches outside lib/test.
SP_PAT_NS="superpowers"":"
# docs/superpowers/specs/ is excepted for the same reason CLAUDE.md is: a design
# spec authored under the superpowers brainstorming/writing-plans discipline
# legitimately NAMES the external dev-time `superpowers:writing-skills` authoring
# discipline in its prose (the skill files it directs the implementer to edit are
# edited under that discipline). Like CLAUDE.md's carried reference, this is a
# documentation surface, not a runtime dependency, so the zero-companion-dependency
# claim is unaffected. The narrow scope (only docs/superpowers/specs) keeps the net
# closed on any OTHER stray superpowers: id in an operative surface.
# .prflow/prompt-extensions is excepted for the SAME reason as CLAUDE.md and
# docs/superpowers/specs (#506): this repo's own prompt extensions (implement.md's
# prompt-surface edit routing rule, review-and-fix.md/review.md's evidence-gate criterion)
# legitimately NAME the external dev-time `superpowers:writing-skills` authoring discipline
# they route edits through. These are repo-internal policy surfaces (the live `.md`
# extensions are NOT shipped to consumers — install.sh's scaffolder (scripts/scaffold-config.sh)
# ships the `.example` templates), so
# like CLAUDE.md's carried reference the zero-companion-dependency claim is unaffected. The
# residual (a stray NON-writing-skills superpowers: id could slip in an extension) matches the
# CLAUDE.md/docs-specs exception's residual and is mitigated by the same maintainer review.
# .changeset is excepted symmetrically with CHANGELOG.md (#506): a changeset's prose is
# changelog content that consolidate-changesets.py prepends verbatim into the already-excepted
# CHANGELOG.md on merge, so a changeset that legitimately names `superpowers:writing-skills`
# (this issue's own does) is exactly as sanctioned as the CHANGELOG entry it becomes.
assert_eq "#142 no operative surface outside CLAUDE.md carries any bare superpowers: namespaced id (non-internalized refs incl.; CLAUDE.md/test scaffolding/history/migration/learnings/design-specs/prompt-extensions/changeset excepted)" \
  "" "$(tracked_scan "$FDROOT" "$SP_PAT_NS" ':!.prflow/logs' ':!.prflow/learnings' ':!.prflow/prompt-extensions' ':!.changeset' ':!CHANGELOG.md' ':!docs/internal/review-agent-overrides.md' ':!docs/superpowers/specs' ':!lib/test' ':!CLAUDE.md')"

# (2/2b/2c) Per-skill vendoring + structural validity. For each of the two skills the file
# exists first-party under skills/<name>/SKILL.md; its frontmatter declares name: <name> (so
# it resolves as devflow:<name>); and the frontmatter is well-formed (open + close ---, name:,
# bounded to the head window so a body --- horizontal rule cannot inflate the closing-fence
# count and mask a dropped closer). These are SKILLS, so no model:/tools: key is required.
for sk in $SP_SKILLS; do
  assert_eq "#142 skills/$sk/SKILL.md exists (vendored first-party)" \
    "yes" "$([ -f "$FDROOT/skills/$sk/SKILL.md" ] && echo yes || echo no)"
  assert_eq "#142 skills/$sk/SKILL.md frontmatter declares name: $sk (resolves as devflow:$sk)" \
    "yes" "$(grep -qE "^name: $sk\$" "$FDROOT/skills/$sk/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: loop body: SKILL target/literal interpolate the $sk loop variable, not a static pin
  assert_eq "#142 skills/$sk/SKILL.md has well-formed frontmatter (open+close ---, name:)" \
    "yes" "$(head -1 "$FDROOT/skills/$sk/SKILL.md" | grep -qx -- '---' \
            && [ "$(head -30 "$FDROOT/skills/$sk/SKILL.md" | grep -c '^---$')" -ge 2 ] \
            && grep -qE '^name:[[:space:]]' "$FDROOT/skills/$sk/SKILL.md" && echo yes || echo no)"  # raw-guard-ok: loop body: SKILL target interpolates the $sk loop variable, not a static pin
  # (3) Attribution contract (mirrors AC2): the vendored skills' upstream superpowers
  # attribution lives in LICENSES/superpowers-LICENSE (MIT (c) Jesse Vincent — NOT Anthropic/
  # Apache-2.0 like #139/#141), asserted once below — the per-file `Vendored from` marker was
  # removed in e398332. The no-first-party-SPDX half is proved by the (3b) property loop.
  # (2e) scaffold-config.sh registers a prompt-extension example row for this internalized
  # skill, and that row names a skill that actually exists (the skills/$sk/SKILL.md asserted
  # above) — pins the PE row to a real skill dir so a typo'd/renamed scaffold row fails loud
  # instead of scaffolding a <skill>.md.example that resolves to nothing.
  assert_eq "#142 scaffold-config.sh has a PE_SKILLS row for the internalized $sk skill" \
    "yes" "$(grep -qE "^$sk\|" "$FDROOT/scripts/scaffold-config.sh" && echo yes || echo no)"
done

# (2d) Dispatch-resolves call-sites (the load-bearing invariant the absence-grep only proxies
# for): each internalized skill's devflow: identifier must appear at its actual call-site, and
# the resolving skill file (asserted above) exists. Pinned positively so a DROPPED devflow: id
# — invisible to (1)'s negative scan — turns these rows red (the #62/#98 unverified-assumption
# trap). requesting-code-review: the engine invokes it + resolver/schema allowlist its override
# key; receiving-code-review: the fix-loop applies its principles. (writing-skills has no call-
# site here — it is external; its CLAUDE.md reference is pinned in (1c).)
# Derived (not pinned) for the reasons stated at `dispatched_roster_missing`: the haystack is
# the runtime review-engine concatenation, so a fixed-literal pin over it names a target no
# static reader can resolve. The extraction is scoped to the `/prflow:<id>` slash-invocation
# form, which is the actual call-site shape.
assert_eq "#142 review engine dispatches /prflow:requesting-code-review (derived final-pass call-site; names it when missing)" \
  "" "$(dispatched_roster_missing "$REVIEW_BUNDLE" '/prflow:[a-z0-9-]+' '/prflow:' '' requesting-code-review)"
assert_eq "#142 resolver allowlists devflow:requesting-code-review (override key resolves)" \
  "yes" "$(rro_allowlisted "devflow:requesting-code-review")"
# Negative control: the allowlist is still CLOSED - an id it never declared is refused,
# so the rows above are attributable to the roster, not to a check that accepts anything.
assert_eq "#142 resolver's allowlist stays closed (an undeclared id is refused)" \
  "no" "$(rro_allowlisted "devflow:not-a-real-agent")"
assert_eq "#142 config schema declares the devflow:requesting-code-review override key" \
  "yes" "$(grep -qF '"devflow:requesting-code-review"' "$FDROOT/.prflow/config.schema.json" && echo yes || echo no)"
assert_eq "#142 fix-loop skill applies the canonical receiving-code-review principles (call-site rewired)" \
  "yes" "$(grep -qF "prflow:receiving-code-review" "$MAXI_BUNDLE" && echo yes || echo no)"  # raw-guard-ok: non-unique: 'prflow:receiving-code-review' appears more than once in the root+references bundle (#539 review Suggestion: bundle, not thin root)

# ── #506 prompt-surface edit routing evidence gate ───────────────────────────
# Repo policy (extension-not-engine): editing a prompt-surface file (SKILL.md, an implement
# phase file, or a prompt extension) must go through the superpowers:writing-skills RED/GREEN
# discipline, routed via an Agent-subagent at edit time (implement.md) and backstopped by a
# review-gate criterion (review-and-fix.md + review.md, byte-identical). These are
# surface-presence contract pins — removing the pinned text does NOT re-introduce a NAMED prior
# regression — so assert_pin_unique applies and no executable behavioral obligation
# attaches (per issue #506 AC). The trigger-glob list and the
# `Writing-skills evidence:` marker are coupled sites, pinned in lockstep across the extensions.
WSR_IMPL="$FDROOT/.prflow/prompt-extensions/implement.md"
WSR_RAF="$FDROOT/.prflow/prompt-extensions/review-and-fix.md"
WSR_REV="$FDROOT/.prflow/prompt-extensions/review.md"
WSR_CLAUDE="$FDROOT/CLAUDE.md"
# The canonical trigger-glob list literal — must be byte-identical across all three extensions.
WSR_TGL='`skills/*/SKILL.md`, `skills/implement/phases/*.md`, `skills/implement/references/*.md`, `skills/review/phases/*.md`, `skills/review-and-fix/references/*.md`, `.prflow/prompt-extensions/*.md`'
# The evidence marker literal the routing evidence-contract writes and the gate criterion matches.
WSR_MARK='Writing-skills evidence:'

# #563 focused-module guidance is repo-local prompt behavior: a covering module is the
# iteration default (issue #707 inverted it), but it must never replace the complete
# verification gate at the end.
# #707 re-anchored the two completion-gate pins: the retired sentences they guarded
# ('A focused result is never a completion gate.' / '… never discharges a review/fix
# gate.') stated the retired rule that a focused result discharges NOTHING, and #707
# replaced it with the narrower guarantee that a focused result discharges intermediate
# iteration but never the FINAL gate. The guarded regression is unchanged in kind — a
# focused pass promoted into the final gate — so each pin moves to the new operative
# sentence.
# The two final-gate pins ABOVE stay unlooped deliberately: their operative sentences
# differ per file ('final completion gate' vs 'final review/fix gate'), so no single
# literal covers both. #707's policy pins whose sentence IS shared across the pair are not
# written as a second loop over the same two files — they join the existing #563 loop
# below, which already iterates exactly this pair. (Deliberately count-free — an ordinal
# here would rot on the next pin added to that loop.)
# #707 the reflection obligation is implement-only: it is the audit trail that makes a
# mid-iteration full-suite run a recorded decision rather than a silent reversion to the
# retired default.
# #789 RE-SPANNED: #707's literal ('record a `## Devflow Reflection` bullet stating why the
# full run was necessary') belonged to the sentence #789 replaced with the closed-set
# fallback rule. The obligation survives and is STRONGER — the bullet must now name WHICH
# closed-set case applied, not merely that a full run happened — so the pin follows the
# obligation to its new sentence rather than being deleted with the old one.
# #707 the reception/shepherd tier carries the same policy in its own adapted voice, so
# it needs its own pins — it shares no sentence with the two files above.
# #789: this file ADAPTS rather than mirrors the source section, so the #789 loop above —
# which iterates only implement.md and review-and-fix.md — does not reach it and its own
# escape-hatch sentence needs a dedicated pin. The guarded regression is the pre-#789
# behavior the sentence replaced: a covered Python unit sent to the full suite, and an
# uncovered surface paying a full run on every cycle instead of extracting on the second.
# #707 absence guard: the retired convention text must survive on NO surface — every
# extension and coupled mirror in the file list below (deliberately count-free: an
# enumeration here rots the next time a surface joins the loop). A reintroduction anywhere
# is the named regression this issue removed, so the count is pinned at 0 across the whole
# set rather than per file.
_WSR_RETIRED_HITS=0
_WSR_RETIRED_UNREADABLE=0
_WSR_RETIRED_CONTROL=0
# The literal set is written ONCE and read by BOTH the sweep and its positive control
# below. A hand-duplicated second copy is the coupled-mirror defect this repo calls its
# dominant pattern: the natural maintenance action on two identical lists is to edit both,
# which disarms a sweep arm while its control stays green — the control certifying the
# sweep against its own blind spot. One array, two readers, no drift possible.
# The set carries the retired rule's OBLIGATION sentences, not only its framing clauses.
# Framing-only literals are the repo's documented pin hole (#171/#232): the obligation
# ('Before a commit, phase completion, push, or completion claim, run ...') can be re-added
# ALONGSIDE the new focused-default prose, leaving both rules stated at once — every
# positive checks still green, because the new sentences are intact, and the sweep still 0,
# because it only looked for the framing. Each entry is a DISTINGUISHING span, never a
# generic English phrase that a future unrelated sentence would trip.
_WSR_RETIRED_LITS=(
  'A focused result discharges no gate'
  'before every commit, push, and completion claim'
  'A focused result is never a completion gate.'
  'A focused result never discharges a review/fix gate.'
  'A focused pass only accelerates RED/GREEN iteration'
  'they do not replace the complete pre-commit or CI run'
  'Before a commit, phase completion, push, or'
  'run the complete suite and every required lint gate'
  'Branch, make focused changes, run'
)
# #719 the 'Before a commit, phase completion, push, or' arm is RE-SPANNED (named, not
# indexed — an ordinal here would rot on any insertion of an earlier arm). Its retired
# obligation sentence
# ('Before a commit, phase completion, push, or completion claim, run ...') was
# LINE-WRAPPED at the pre-#707 baseline, wrapping after '…push, or', and pin_count
# is line-based (grep -oF) — so the full-sentence span matched NOTHING on any swept
# surface at 607ec800 and the arm was unmatchable by construction (the repo's own
# #375 wrapped-literal class, reintroduced inside the guard written to prevent it).
# The on-line span 'Before a commit, phase completion, push, or' is what actually
# exists on a single baseline line (in implement.md), so the baseline-corpus control
# below can validate it. It is still a DISTINGUISHING span of the retired obligation,
# not a generic phrase.
# #719 per-member baseline ref (parallel to _WSR_RETIRED_LITS by index — bash 3.2 has
# no associative arrays). Each member is validated by the baseline-corpus control below
# against the blob at the ref where its retired text EXISTED. Every member shares the pre-#707
# baseline 607ec800 today; a literal retired by a LATER change carries its own later ref,
# so the control never demands a postdated literal match a ref that predates it. A member
# with NO parallel ref (a shorter refs array) turns the control RED naming that member, so
# the literal array cannot grow past the control by omission. 607ec800 is a past-time
# snapshot (issue #656 prefer-generated-evidence EXCEPTION — a fixed historical ref, not a
# live-rendered figure), registered with that rationale rather than rendered.
_WSR_RETIRED_REFS=(
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
  '607ec800'
)
# CONTRIBUTING.md carries this policy too (issue #707 rewrote its Submitting-changes step
# and added its focused-default block), so it is swept like every other mirror. Its own
# retired form was a different sentence from the extensions' — 'Branch, make focused
# changes, run `bash lib/test/run.sh`' — so that spelling is in the literal set above;
# without it this arm would be installed and inert, sweeping a file for text it never
# carried. The sweep only proves the old rule is gone, so the new rule gets its own
# positive pin below.
for _WSR_RETIRED_FILE in "$WSR_IMPL" "$WSR_RAF" "$FDROOT/.prflow/prompt-extensions/receiving-code-review.md" \
  "$WSR_CLAUDE" "$FDROOT/docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md" "$FDROOT/CONTRIBUTING.md"; do
  # An absence guard cannot tell "the text is gone" from "the file was never read":
  # pin_count prints 0 for a missing/unreadable path, so a renamed or mistyped member of
  # this list would contribute a silent zero and the guard would pass BECAUSE it could not
  # look. Readability is therefore an asserted operand, not an assumption.
  [ -r "$_WSR_RETIRED_FILE" ] || _WSR_RETIRED_UNREADABLE=$((_WSR_RETIRED_UNREADABLE + 1))
  # Each literal is a DISTINGUISHING span of the retired rule, never a generic English
  # phrase: a bare 'before every commit' would turn the suite RED on an unrelated future
  # sentence in either large mirror document and misattribute it to this regression.
  for _WSR_RETIRED_LIT in "${_WSR_RETIRED_LITS[@]}"; do
    _WSR_RETIRED_HITS=$((_WSR_RETIRED_HITS + $(pin_count "$_WSR_RETIRED_LIT" "$_WSR_RETIRED_FILE")))
  done
done
assert_eq "#707 every surface the retired-convention sweep reads is readable" "0" "$_WSR_RETIRED_UNREADABLE"
assert_eq "#707 the retired full-suite-before-every-commit convention survives on no surface" "0" "$_WSR_RETIRED_HITS"
# ── #719 baseline-corpus control (REPLACES the self-referential planting control) ──
# The retired control planted the sweep's OWN literal array into a scratch file and counted it
# there, so — because the planting loop and the counting loop read the SAME array — it was blind
# BY CONSTRUCTION to a member that is unmatchable against the REAL retired text. That is exactly
# the #719 defect: the re-spanned arm's full-sentence span wrapped a line break at the baseline, so
# grep -oF (line-based) could never match it on any swept surface, yet the self-referential
# control still tallied because it planted and then found the same unmatchable string. The old
# control's own comment conceded it could not detect a MISTYPED literal; it did not anticipate an
# UNMATCHABLE one, the same blind spot by a different route.
# This control replaces that with an INDEPENDENTLY-AUTHORED corpus the repo does not re-author —
# the pre-#707 baseline blobs read through `git show <ref>:<file>` — so a literal that cannot
# match its real baseline text turns the suite RED at the desk. It extends the #528 derived-LIST
# discipline to a derived CORPUS.
# Fail-closed contract, exactly five arms (complete by construction) — four degraded corpus-build
# inputs plus the authoring arm below them:
#   unresolvable ref (shallow clone)  -> skip blocking-gate (a real gate that should have run here)
#   swept file with no blob at ref    -> RED naming the input (never pass by counting zero)
#   empty `git show` output           -> RED naming the input (never pass by counting zero)
#   failed scratch allocation         -> skip host-capability
#   member with no parallel ref       -> RED naming the member (an authoring defect in the parallel
#                                        arrays, not a corpus input; exercised by control 2)
# The unresolvable-ref and allocation arms are HOST-capability limits, not tree defects, so a
# shallow local clone routes to `skip` (recorded skipped — not a clean pass, not a hard failure)
# while CI's full-history checkout (fetch-depth: 0, #456) runs the gate for real. The retired
# control's `if probe_tmp; then … fi` shape (no else, no skip) is deliberately NOT copied.
# HISTORICAL PATHS — these are the swept files' relpaths AT THE BASELINE REF, not in
# the current tree. They are arguments to `git show <ref>:<path>` over a frozen
# past-time snapshot where the state directory was still named `.devflow/`. Issue
# #1002's `.devflow/` -> `.prflow/` rename is a FORWARD rename of the working tree and
# must NOT be applied here: rewriting a historical path makes every blob unresolvable,
# the builder returns NOBLOB on the first file, and the whole control collapses into one
# fail-closed RED before it validates a single literal. A tree-wide rename sweep must
# skip this array.
_WSR_SWEPT_RELPATHS=(
  '.devflow/prompt-extensions/implement.md'
  '.devflow/prompt-extensions/review-and-fix.md'
  '.devflow/prompt-extensions/receiving-code-review.md'
  'CLAUDE.md'
  'docs/DEVFLOW_SYSTEM_OVERVIEW.md'
  'CONTRIBUTING.md'
)
# Build the baseline corpus for (repo, ref) over FILES into OUT (truncated first, so a re-run
# cannot ACCUMULATE planted content). Prints exactly one status token; the ref/blob/empty
# distinctions are what let the control fail closed per the contract above, never collapse an
# unestablished `git show` onto a zero count (the repo's unknown-is-not-zero rule).
#   OK            corpus built, every blob resolved and non-empty
#   BADREF        ref does not resolve as a commit in repo (shallow clone)
#   NOBLOB:<file> ref resolves but a swept file has no blob at that ref (added after it)
#   EMPTY:<file>  git show resolved but produced empty output
_wsr_build_baseline_corpus() {  # repo ref out file...
  local repo="$1" ref="$2" out="$3"; shift 3
  if ! git -C "$repo" rev-parse --verify --quiet "${ref}^{commit}" >/dev/null 2>&1; then
    printf 'BADREF\n'; return 1
  fi
  : > "$out"
  local f blob
  for f in "$@"; do
    # One `git show` distinguishes all three states after the ref already resolved above: a
    # missing blob makes it exit nonzero (NOBLOB); an existing-but-empty blob exits 0 with empty
    # stdout (EMPTY); a normal blob exits 0 with content. The separate `cat-file -e` probe the
    # first draft used was a redundant second git fork per file.
    if ! blob="$(git -C "$repo" show "${ref}:${f}" 2>/dev/null)"; then
      printf 'NOBLOB:%s\n' "$f"; return 1
    fi
    if [ -z "$blob" ]; then
      printf 'EMPTY:%s\n' "$f"; return 1
    fi
    printf '%s\n' "$blob" >> "$out"
  done
  printf 'OK\n'; return 0
}
# Run the control over the caller-set input arrays (_WSR_BCC_LITS / _WSR_BCC_REFS parallel by
# index — bash 3.2 has no associative arrays; _WSR_BCC_FILES swept relpaths; _WSR_BCC_REPO the
# git dir). Emits real assert_eq/skip so the REAL invocation records real results; the positive
# controls below call it with RESULTS_FILE/SKIPS_FILE redirected to isolated files and inspect
# those, so their intentional RED/skip never enters the suite tally.
#   $1 name   $2 ref-override (empty = per-member ref)   $3 alloc-mode (ok|fail)
_WSR_BCC_LAST_CORPUS=""
_wsr_run_baseline_corpus_control() {
  local name="$1" ref_override="$2" alloc_mode="$3"
  local corpus cur_ref="" i lit ref n tok unmatched="" noref=""
  # Scratch allocation — the allocation degraded arm. A forced 'fail' mode or a real mktemp
  # failure routes to skip host-capability (NOT probe_tmp, which would record a FAIL): a host
  # that cannot allocate scratch is a host-capability limit, not a tree defect.
  if [ "$alloc_mode" = fail ]; then
    skip "$name — scratch corpus allocation" host-capability "mktemp unavailable (forced); baseline-corpus control could not build its scratch corpus"
    return 0
  fi
  corpus="$(mktemp 2>/dev/null)" || {
    skip "$name — scratch corpus allocation" host-capability "mktemp failed; baseline-corpus control could not build its scratch corpus"
    return 0
  }
  _WSR_BCC_LAST_CORPUS="$corpus"
  for (( i=0; i<${#_WSR_BCC_LITS[@]}; i++ )); do
    lit="${_WSR_BCC_LITS[$i]}"
    if [ -n "$ref_override" ]; then
      ref="$ref_override"
    elif [ "$i" -lt "${#_WSR_BCC_REFS[@]}" ] && [ -n "${_WSR_BCC_REFS[$i]}" ]; then
      ref="${_WSR_BCC_REFS[$i]}"
    else
      # A member with NO parallel ref (a shorter refs array, or an empty entry) is RED naming it:
      # the literal array cannot grow past the control by omission.
      noref="${noref}
  - ${lit}"
      continue
    fi
    # Build (or reuse) the corpus for this ref. One-entry cache: consecutive same-ref members
    # reuse the built corpus, so the ref-uniform real set builds it exactly once.
    if [ "$ref" != "$cur_ref" ]; then
      tok="$(_wsr_build_baseline_corpus "$_WSR_BCC_REPO" "$ref" "$corpus" "${_WSR_BCC_FILES[@]}")"
      case "$tok" in
        OK) cur_ref="$ref" ;;
        BADREF)
          skip "$name — baseline ref '$ref'" blocking-gate "ref does not resolve (shallow clone?); baseline-corpus gate could not run here — CI's full-history checkout is authoritative. To run it here, check out with fetch-depth: 0 or run 'git fetch --unshallow' first (issue #1219)"
          rm -f "$corpus"; return 0 ;;
        NOBLOB:*|EMPTY:*)
          # RED naming the unresolved input — never allowed to pass by counting zero literals.
          assert_eq "$name — every swept file resolves to a non-empty baseline blob at '$ref'" "OK" "$tok"
          rm -f "$corpus"; return 0 ;;
        *)
          # Unreachable by construction today — but an unforeseen producer token must never fall
          # through to counting against a possibly-stale corpus. RED naming the token instead.
          assert_eq "$name — the corpus builder emitted a known status token at '$ref'" "OK" "$tok"
          rm -f "$corpus"; return 0 ;;
      esac
    fi
    n="$(pin_count "$lit" "$corpus")"
    [ "$n" -ge 1 ] || unmatched="${unmatched}
  - ${lit}"
  done
  rm -f "$corpus"
  # RED (naming the offenders) when any member has no parallel ref, or matches no baseline
  # surface; a clean run records two PASSes.
  assert_eq "$name — every retired literal carries a parallel baseline ref" "" "$noref"
  assert_eq "$name — every retired literal matches its independently-authored baseline corpus" "" "$unmatched"
}
# The REAL invocation — validates the live _WSR_RETIRED_LITS against the pre-#707 baseline.
_WSR_BCC_REPO="$FDROOT"
_WSR_BCC_FILES=("${_WSR_SWEPT_RELPATHS[@]}")
_WSR_BCC_LITS=("${_WSR_RETIRED_LITS[@]}")
_WSR_BCC_REFS=("${_WSR_RETIRED_REFS[@]}")
_wsr_run_baseline_corpus_control "#719 retired-convention baseline-corpus control" "" ok
# ── Positive controls: prove the control detects each defect it exists for, in ISOLATION so
# the intentional RED / skip never counts against the suite tally. ────────────────────────────
# Controls 1-4 share ONE isolated results/skips pair, allocated once and truncated between runs.
# The allocation is guarded: an unguarded `$(mktemp)` here would fail loud but with a MISDIRECTED
# diagnosis (an empty RESULTS_FILE path reads as the control finding nothing), so a host that
# cannot allocate scratch routes to skip host-capability exactly like the control's own arm.
if _WSR_BCC_PR="$(mktemp 2>/dev/null)" && _WSR_BCC_PS="$(mktemp 2>/dev/null)"; then
# Controls 1-2 drive the control over the REAL baseline refs, so they need those refs to resolve.
# On a shallow clone they would otherwise route to `skip` inside the control and their
# `grep -q '^FAIL'` meta-assertions would flip to a spurious hard suite FAIL — contradicting this
# block's own documented shallow-clone tolerance (controls 5/6/7 avoid it via `git_sandbox`).
_WSR_BCC_REFS_OK=yes
for _WSR_BCC_R in "${_WSR_RETIRED_REFS[@]}"; do
  git -C "$FDROOT" rev-parse --verify --quiet "${_WSR_BCC_R}^{commit}" >/dev/null 2>&1 || _WSR_BCC_REFS_OK=no
done
if [ "$_WSR_BCC_REFS_OK" = yes ]; then
# (1) Planted-defect control: append one deliberately-unmatchable member — the ORIGINAL
# full-sentence span that WRAPS a line break at the baseline (the exact #719 defect) — and
# observe the control go RED naming it.
: > "$_WSR_BCC_PR"; : > "$_WSR_BCC_PS"
_WSR_BCC_REPO="$FDROOT"
_WSR_BCC_FILES=("${_WSR_SWEPT_RELPATHS[@]}")
_WSR_BCC_LITS=("${_WSR_RETIRED_LITS[@]}" 'Before a commit, phase completion, push, or completion claim, run')
_WSR_BCC_REFS=("${_WSR_RETIRED_REFS[@]}" "${_WSR_RETIRED_REFS[0]}")
_WSR_BCC_PLANTED_OUT="$( RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 planted-defect control' '' ok 2>&1 )"
assert_eq "#719 baseline-corpus control: a planted line-wrapping member is caught RED" \
  "yes" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
assert_eq "#719 baseline-corpus control: the planted member is NAMED in the RED output" \
  "yes" "$(printf '%s' "$_WSR_BCC_PLANTED_OUT" | grep -qF 'completion claim, run' && echo yes || echo no)"
# (2) Missing-ref control: a member with no parallel ref (refs array one short) goes RED naming
# the member — the array cannot grow past the control by omission.
: > "$_WSR_BCC_PR"; : > "$_WSR_BCC_PS"
_WSR_BCC_LITS=("${_WSR_RETIRED_LITS[@]}" 'a later retirement literal with no ref')
_WSR_BCC_REFS=("${_WSR_RETIRED_REFS[@]}")
_WSR_BCC_NOREF_OUT="$( RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 missing-ref control' '' ok 2>&1 )"
assert_eq "#719 baseline-corpus control: a member with no parallel baseline ref is caught RED" \
  "yes" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
assert_eq "#719 baseline-corpus control: the ref-less member is NAMED in the RED output" \
  "yes" "$(printf '%s' "$_WSR_BCC_NOREF_OUT" | grep -qF 'no ref' && echo yes || echo no)"
else
  skip "#719 baseline-corpus control: planted-defect and missing-ref controls" blocking-gate \
    "a baseline ref in _WSR_RETIRED_REFS does not resolve (shallow clone?); these two controls drive the REAL refs — CI's full-history checkout is authoritative"
fi
# (3) Unresolvable-ref control: a bogus baseline ref routes to skip blocking-gate (NOT a FAIL,
# NOT a pass) — the shallow-clone host-limit arm. Ref-resolution-independent by construction.
: > "$_WSR_BCC_PR"; : > "$_WSR_BCC_PS"
_WSR_BCC_LITS=("${_WSR_RETIRED_LITS[@]}")
_WSR_BCC_REFS=("${_WSR_RETIRED_REFS[@]}")
RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 bad-ref control' 'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef' ok >/dev/null 2>&1
assert_eq "#719 baseline-corpus control: an unresolvable baseline ref routes to skip blocking-gate" \
  "yes" "$(grep -q '^blocking-gate	' "$_WSR_BCC_PS" && echo yes || echo no)"
assert_eq "#719 baseline-corpus control: an unresolvable baseline ref records NO suite FAIL" \
  "no" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
# (4) Failed-scratch-allocation control: routes to skip host-capability (NOT a FAIL).
: > "$_WSR_BCC_PR"; : > "$_WSR_BCC_PS"
RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 alloc-fail control' '' fail >/dev/null 2>&1
assert_eq "#719 baseline-corpus control: a failed scratch allocation routes to skip host-capability" \
  "yes" "$(grep -q '^host-capability	' "$_WSR_BCC_PS" && echo yes || echo no)"
assert_eq "#719 baseline-corpus control: a failed scratch allocation records NO suite FAIL" \
  "no" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
rm -f "$_WSR_BCC_PR" "$_WSR_BCC_PR.names" "$_WSR_BCC_PS"
else
  skip "#719 baseline-corpus control: isolated positive controls 1-4" host-capability \
    "mktemp failed; the isolated results/skips pair the controls inspect could not be allocated"
fi
# (5) Missing-blob and (6) empty-output controls: build a throwaway git repo with controlled
# blobs (a file carrying every literal, an empty file, and a referenced-but-absent path) and
# drive the control against it — each degraded git input goes RED naming the input, proving the
# real git mechanism (not a mock) fails closed.
if _WSR_BCC_SBX="$(git_sandbox '#719 baseline-corpus degraded-input sandbox')"; then
  git -C "$_WSR_BCC_SBX" init -q
  {
    for _WSR_BCC_L in "${_WSR_RETIRED_LITS[@]}"; do printf '%s\n' "$_WSR_BCC_L"; done
  } > "$_WSR_BCC_SBX/real.md"
  : > "$_WSR_BCC_SBX/empty.md"
  git -C "$_WSR_BCC_SBX" add real.md empty.md
  git -C "$_WSR_BCC_SBX" -c user.email=t@t -c user.name=t commit -qm baseline >/dev/null 2>&1
  _WSR_BCC_SBX_REF="$(git -C "$_WSR_BCC_SBX" rev-parse HEAD)"
  _WSR_BCC_REPO="$_WSR_BCC_SBX"
  _WSR_BCC_LITS=("${_WSR_RETIRED_LITS[@]}")
  _WSR_BCC_REFS=()   # use the ref-override so every member shares $_WSR_BCC_SBX_REF
  # (5) missing blob: a referenced path that does not exist at the ref. The scratch pair is
  # allocated once for controls 5-7 and guarded for the same misdirected-diagnosis reason as the
  # pair above; a failed allocation skips host-capability rather than reading as a silent control.
  if _WSR_BCC_PR="$(mktemp 2>/dev/null)" && _WSR_BCC_PS="$(mktemp 2>/dev/null)"; then
  _WSR_BCC_FILES=('ghost.md' 'real.md')
  _WSR_BCC_NOBLOB_OUT="$( RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 missing-blob control' "$_WSR_BCC_SBX_REF" ok 2>&1 )"
  assert_eq "#719 baseline-corpus control: a swept file with no blob at the ref is caught RED" \
    "yes" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
  assert_eq "#719 baseline-corpus control: the missing blob is NAMED in the RED output" \
    "yes" "$(printf '%s' "$_WSR_BCC_NOBLOB_OUT" | grep -qF 'ghost.md' && echo yes || echo no)"
  # (6) empty output: a swept file whose git show is empty
  : > "$_WSR_BCC_PR"; : > "$_WSR_BCC_PS"
  _WSR_BCC_FILES=('empty.md' 'real.md')
  _WSR_BCC_EMPTY_OUT="$( RESULTS_FILE="$_WSR_BCC_PR" SKIPS_FILE="$_WSR_BCC_PS" _wsr_run_baseline_corpus_control '#719 empty-output control' "$_WSR_BCC_SBX_REF" ok 2>&1 )"
  assert_eq "#719 baseline-corpus control: an empty git-show blob is caught RED" \
    "yes" "$(grep -q '^FAIL' "$_WSR_BCC_PR" && echo yes || echo no)"
  assert_eq "#719 baseline-corpus control: the empty blob is NAMED in the RED output" \
    "yes" "$(printf '%s' "$_WSR_BCC_EMPTY_OUT" | grep -qF 'empty.md' && echo yes || echo no)"
  # (7) idempotency: run the control twice over the same clean sandbox input and require
  # byte-identical result tallies, and require the scratch corpus removed after the run.
  _WSR_BCC_FILES=('real.md')
  if _WSR_BCC_R1="$(mktemp 2>/dev/null)" && _WSR_BCC_R2="$(mktemp 2>/dev/null)" && _WSR_BCC_S0="$(mktemp 2>/dev/null)"; then
  RESULTS_FILE="$_WSR_BCC_R1" SKIPS_FILE="$_WSR_BCC_S0" _wsr_run_baseline_corpus_control '#719 idempotency probe' "$_WSR_BCC_SBX_REF" ok >/dev/null 2>&1
  assert_eq "#719 baseline-corpus control: the scratch corpus is removed after the run" \
    "gone" "$([ -e "$_WSR_BCC_LAST_CORPUS" ] && echo present || echo gone)"
  RESULTS_FILE="$_WSR_BCC_R2" SKIPS_FILE="$_WSR_BCC_S0" _wsr_run_baseline_corpus_control '#719 idempotency probe' "$_WSR_BCC_SBX_REF" ok >/dev/null 2>&1
  assert_eq "#719 baseline-corpus control: re-running over the same input yields an identical tally" \
    "yes" "$(cmp -s "$_WSR_BCC_R1" "$_WSR_BCC_R2" && echo yes || echo no)"
  rm -f "$_WSR_BCC_R1" "$_WSR_BCC_R1.names" "$_WSR_BCC_R2" "$_WSR_BCC_R2.names" "$_WSR_BCC_S0"
  else
    skip "#719 baseline-corpus control: idempotency probe" host-capability \
      "mktemp failed; the isolated result files the probe compares could not be allocated"
  fi
  rm -f "$_WSR_BCC_PR" "$_WSR_BCC_PR.names" "$_WSR_BCC_PS"
  else
    skip "#719 baseline-corpus control: degraded-git-input controls 5-7" host-capability \
      "mktemp failed; the isolated results/skips pair the controls inspect could not be allocated"
  fi
  rm -rf "$_WSR_BCC_SBX"
fi
