assert_eq "#671 marketplace multi-version: diagnostic names the marketplace + the count" "yes" \
  "$(grep -qF 'marketplace.json' "$CSD/out" && grep -qF 'found 2' "$CSD/out" && echo yes || echo no)"
assert_eq "#671 marketplace multi-version: manifest version unchanged (no partial write)" "2.8.64" "$(cs_ver "$CSD")"
rm -rf "$CSD"
# #671: the same guard's total==0 arm — a marketplace carrying NO "version" key is equally
# unsafe for the surgical rewrite (nothing to bump), so it must fail loud, not no-op silently
# past a listing that then advertises no version at all.
CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#671)\n' > "$CSD/.changeset/a.md"
printf '{\n  "plugins": [\n    { "name": "devflow" }\n  ]\n}\n' > "$CSD/.claude-plugin/marketplace.json"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-21 >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#671 marketplace zero-version: exit 2 (fail-closed, not a silent no-op)" "2" "$CS_RC"
assert_eq "#671 marketplace zero-version: diagnostic names the marketplace + the count" "yes" \
  "$(grep -qF 'marketplace.json' "$CSD/out" && grep -qF 'found 0' "$CSD/out" && echo yes || echo no)"
assert_eq "#671 marketplace zero-version: manifest version unchanged (no partial write)" "2.8.64" "$(cs_ver "$CSD")"
rm -rf "$CSD"

# #671: CITATION.cff's version must equal the manifest version at HEAD — the consolidator keeps
# them in lockstep on merge, so a drift here means the repo shipped out of sync. Both values are
# read LIVE (no checked-in literal), since version-consolidate bumps the manifest on merge to main.
CIT_CFF="$FDROOT/CITATION.cff"
CIT_PJ="$FDROOT/.claude-plugin/plugin.json"
assert_eq "#671 CITATION.cff exists" "yes" "$([ -f "$CIT_CFF" ] && echo yes || echo no)"
CIT_PJ_VER="$(python3 -c "import json; print(json.load(open('$CIT_PJ'))['version'])")"
CIT_CFF_VER="$(python3 -c "import re; t=open('$CIT_CFF').read(); m=re.search(r'(?m)^version:[ \t]*(\S+)', t); print(m.group(1) if m else '')")"
assert_eq "#671 CITATION.cff version tracks plugin.json version" "$CIT_PJ_VER" "$CIT_CFF_VER"
# #671: the marketplace plugin entry's version must likewise equal the manifest version at HEAD
# (the consolidator now bumps it in lockstep), read LIVE — a drift means the listing shipped
# behind the plugin.
CIT_MKT_VER="$(python3 -c "import json; print(json.load(open('$FDROOT/.claude-plugin/marketplace.json'))['plugins'][0]['version'])")"
assert_eq "#671 marketplace plugins[0].version tracks plugin.json version" "$CIT_PJ_VER" "$CIT_MKT_VER"

# ── #298 hardening: fail-closed OS wrapping, atomic outputs, single-source bump domain ──────
# AC: _BUMP_RANK is DERIVED from VALID_BUMPS (single source) — the two sets stay consistent,
# so a new bump value cannot desync them into a KeyError at the max(...) lookup.
assert_eq "#298 single-source: VALID_BUMPS and _BUMP_RANK keys match exactly" "ok" \
  "$(python3 -c "import importlib.util as u; s=u.spec_from_file_location('c','$CS_SCRIPT'); m=u.module_from_spec(s); s.loader.exec_module(m); print('ok' if set(m.VALID_BUMPS)==set(m._BUMP_RANK) and len(m._BUMP_RANK)==len(m.VALID_BUMPS) else 'drift')")"
# AC: the two parse helpers return NamedTuples whose fields are addressable by name.
assert_eq "#298 NamedTuple: parse helpers expose bump/section/prose + frontmatter/body fields" "ok" \
  "$(python3 -c "import importlib.util as u; s=u.spec_from_file_location('c','$CS_SCRIPT'); m=u.module_from_spec(s); s.loader.exec_module(m); print('ok' if m.Changeset._fields==('bump','section','prose') and m.Frontmatter._fields==('frontmatter','body') else 'bad')")"

# AC: the five previously-untested defensive branches each gain a named assertion.
# (1) _render_changelog no-prior-`## [`-heading append branch: entry is appended after preamble.
CSD="$(cs_repo)"; printf '# Changelog\n\nNo versioned entries yet.\n' > "$CSD/CHANGELOG.md"
printf -- '---\nbump: patch\n---\n\n- first entry (#298)\n' > "$CSD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >/dev/null 2>&1; CS_RC=$?
assert_eq "#298 no-prior-heading: exit 0" "0" "$CS_RC"
assert_eq "#298 no-prior-heading: entry appended below the preamble" "yes" \
  "$(grep -qF '## [2.8.65] — 2026-07-04' "$CSD/CHANGELOG.md" && grep -qF 'No versioned entries yet.' "$CSD/CHANGELOG.md" && echo yes || echo no)"
rm -rf "$CSD"
# (2) _read_manifest_version no-`version`-key guard: a manifest without a version key fails loud.
CSD="$(cs_repo)"; printf '{\n  "name": "devflow"\n}\n' > "$CSD/.claude-plugin/plugin.json"
printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#298 no-version-key: exit 2" "2" "$CS_RC"
assert_eq "#298 no-version-key: diagnostic names the manifest" "yes" \
  "$(grep -qF 'plugin.json' "$CSD/out" && grep -qiF 'version' "$CSD/out" && echo yes || echo no)"
rm -rf "$CSD"
# (3) _bump_version non-N.N.N guard: a malformed version string fails loud.
CSD="$(cs_repo)"; printf '{\n  "version": "1.2"\n}\n' > "$CSD/.claude-plugin/plugin.json"
printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#298 non-N.N.N version: exit 2" "2" "$CS_RC"
assert_eq "#298 non-N.N.N version: diagnostic names the offending version" "yes" \
  "$(grep -qF '1.2' "$CSD/out" && echo yes || echo no)"
rm -rf "$CSD"
# (4) --date format validation: a non-YYYY-MM-DD date fails loud before any work.
CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$CSD" --date "07/04/2026" >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#298 bad --date: exit 2" "2" "$CS_RC"
assert_eq "#298 bad --date: version unchanged" "2.8.64" "$(cs_ver "$CSD")"; rm -rf "$CSD"
# (5) frontmatter-not-a-mapping and invalid-YAML branches both fail loud naming the file.
CSD="$(cs_repo)"; printf -- '---\n- just a list item\n---\n\n- x (#298)\n' > "$CSD/.changeset/notmap.md"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#298 frontmatter-not-a-mapping: exit 2" "2" "$CS_RC"
assert_eq "#298 frontmatter-not-a-mapping: diagnostic names the file" "yes" \
  "$(grep -qF 'notmap.md' "$CSD/out" && echo yes || echo no)"
rm -rf "$CSD"
CSD="$(cs_repo)"; printf -- '---\nbump: [unclosed\n---\n\n- x (#298)\n' > "$CSD/.changeset/badyaml.md"
python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
assert_eq "#298 invalid-YAML frontmatter: exit 2" "2" "$CS_RC"
assert_eq "#298 invalid-YAML frontmatter: diagnostic names the file" "yes" \
  "$(grep -qF 'badyaml.md' "$CSD/out" && echo yes || echo no)"
rm -rf "$CSD"

# AC: read-before-write atomicity — an output-side read fault (unreadable CHANGELOG) aborts
# with exit 2 BEFORE any write, leaving both plugin.json and CHANGELOG.md byte-for-byte
# unchanged and the changeset unconsumed. chmod-based; root bypasses mode bits, so guard it.
CSD="$(cs_repo)"; printf -- '---\nbump: minor\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
CS_MANI0="$(cat "$CSD/.claude-plugin/plugin.json")"; CS_CL0="$(cat "$CSD/CHANGELOG.md")"
chmod 000 "$CSD/CHANGELOG.md"
if [ "$(id -u)" -ne 0 ] && [ ! -r "$CSD/CHANGELOG.md" ]; then
  python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
  chmod 644 "$CSD/CHANGELOG.md"
  assert_eq "#298 atomic read-before-write: exit 2 on unreadable CHANGELOG" "2" "$CS_RC"
  assert_eq "#298 atomic read-before-write: diagnostic names CHANGELOG.md" "yes" \
    "$(grep -qF 'CHANGELOG.md' "$CSD/out" && echo yes || echo no)"
  assert_eq "#298 atomic read-before-write: plugin.json byte-for-byte unchanged" "$CS_MANI0" "$(cat "$CSD/.claude-plugin/plugin.json")"
  assert_eq "#298 atomic read-before-write: CHANGELOG.md byte-for-byte unchanged" "$CS_CL0" "$(cat "$CSD/CHANGELOG.md")"
  assert_eq "#298 atomic read-before-write: changeset NOT consumed" "yes" \
    "$([ -f "$CSD/.changeset/a.md" ] && echo yes || echo no)"
else
  chmod 644 "$CSD/CHANGELOG.md" 2>/dev/null || true
fi
rm -rf "$CSD"

# AC: every OS-level fault at a wrapped site raises ChangesetError → exit 2 naming the path
# (not exit 1 with a bare OSError traceback). One representative fault per wrapped read/write/
# delete site; all chmod-based, so guard against root (which ignores mode bits).
if [ "$(id -u)" -ne 0 ]; then
  # _split_frontmatter read: an unreadable changeset file.
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 000 "$CSD/.changeset/a.md"
  if [ ! -r "$CSD/.changeset/a.md" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (changeset read): exit 2" "2" "$CS_RC"
    # Pin the PER-SITE wrap (AC1), not the removal-proof backstop (AC2): assert the clean
    # `…/a.md: cannot read changeset` diagnostic AND absence of the backstop's `unhandled OS
    # error` message (whose {exc} embeds the path too, so a bare filename match is vacuous).
    assert_eq "#298 OS-fault (changeset read): per-site diagnostic names a.md (not backstop)" "yes" \
      "$(grep -qF 'a.md: cannot read' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 644 "$CSD/.changeset/a.md" 2>/dev/null || true; rm -rf "$CSD"
  # os.listdir glob: an unlistable .changeset directory.
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 000 "$CSD/.changeset"
  if [ ! -r "$CSD/.changeset" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (listdir): exit 2" "2" "$CS_RC"
    # Per-site wrap (AC1), not the backstop (AC2): assert the `…/.changeset: cannot list
    # changesets` diagnostic AND absence of the backstop's `unhandled OS error` message.
    assert_eq "#298 OS-fault (listdir): per-site diagnostic names the .changeset dir (not backstop)" "yes" \
      "$(grep -qF '.changeset: cannot list changesets' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 755 "$CSD/.changeset" 2>/dev/null || true; rm -rf "$CSD"
  # _write_text manifest write: a read-only plugin.json (readable so render succeeds, write fails).
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 444 "$CSD/.claude-plugin/plugin.json"
  if [ ! -w "$CSD/.claude-plugin/plugin.json" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (manifest write): exit 2" "2" "$CS_RC"
    # Per-site wrap (AC1), not the backstop (AC2): assert the `…/plugin.json: cannot write`
    # diagnostic AND absence of the backstop's `unhandled OS error` message.
    assert_eq "#298 OS-fault (manifest write): per-site diagnostic names plugin.json (not backstop)" "yes" \
      "$(grep -qF 'plugin.json: cannot write' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 644 "$CSD/.claude-plugin/plugin.json" 2>/dev/null || true; rm -rf "$CSD"
  # os.remove delete loop: a non-writable .changeset dir (listdir/read OK, remove fails).
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 555 "$CSD/.changeset"
  if [ ! -w "$CSD/.changeset" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (changeset delete): exit 2" "2" "$CS_RC"
    # Per-site wrap (AC1), not the backstop (AC2): assert the `…/a.md: cannot delete consumed
    # changeset` diagnostic AND absence of the backstop's `unhandled OS error` message.
    assert_eq "#298 OS-fault (changeset delete): per-site diagnostic names a.md (not backstop)" "yes" \
      "$(grep -qF 'a.md: cannot delete consumed changeset' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 755 "$CSD/.changeset" 2>/dev/null || true; rm -rf "$CSD"
  # _read_text manifest read: an unreadable plugin.json (read fails before any render/write).
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 000 "$CSD/.claude-plugin/plugin.json"
  if [ ! -r "$CSD/.claude-plugin/plugin.json" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (manifest read): exit 2" "2" "$CS_RC"
    # Pin the PER-SITE wrap (AC1), not the removal-proof backstop (AC2): assert the clean
    # `plugin.json: cannot read …` diagnostic AND that it did NOT fall through to the
    # backstop's `unhandled OS error` message (whose {exc} would embed the path too — so a
    # bare filename match alone is vacuous w.r.t. the per-site wrap).
    assert_eq "#298 OS-fault (manifest read): per-site diagnostic names plugin.json (not backstop)" "yes" \
      "$(grep -qF 'plugin.json: cannot read' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 644 "$CSD/.claude-plugin/plugin.json" 2>/dev/null || true; rm -rf "$CSD"
  # _write_text changelog write: a read-only CHANGELOG.md (read/render succeeds, write fails —
  # manifest write lands first, so this exercises the changelog write open specifically).
  CSD="$(cs_repo)"; printf -- '---\nbump: patch\n---\n\n- x (#298)\n' > "$CSD/.changeset/a.md"
  chmod 444 "$CSD/CHANGELOG.md"
  if [ ! -w "$CSD/CHANGELOG.md" ]; then
    python3 "$CS_SCRIPT" --root "$CSD" --date 2026-07-04 >"$CSD/out" 2>&1; CS_RC=$?
    assert_eq "#298 OS-fault (changelog write): exit 2" "2" "$CS_RC"
    # Per-site wrap (AC1), not the backstop (AC2): assert the clean `CHANGELOG.md: cannot
    # write …` diagnostic AND absence of the `unhandled OS error` backstop message.
    assert_eq "#298 OS-fault (changelog write): per-site diagnostic names CHANGELOG.md (not backstop)" "yes" \
      "$(grep -qF 'CHANGELOG.md: cannot write' "$CSD/out" && ! grep -qF 'unhandled OS error' "$CSD/out" && echo yes || echo no)"
  fi
  chmod 644 "$CSD/CHANGELOG.md" 2>/dev/null || true; rm -rf "$CSD"
fi

# AC: top-level `except OSError` backstop — an OS fault at a site that is NOT individually
# wrapped (here os.path.isdir, monkeypatched) still exits 2 with a diagnostic, never a bare
# OSError traceback. Drives the backstop specifically, not a per-site wrap.
CSD="$(cs_repo)"
CS_BACKSTOP_RC="$(python3 -c "
import importlib.util as u, sys
s=u.spec_from_file_location('c','$CS_SCRIPT'); m=u.module_from_spec(s); s.loader.exec_module(m)
def boom(p): raise OSError('injected fault at an unwrapped site')
m.os.path.isdir = boom
sys.exit(m.main(['--root','$CSD','--date','2026-07-04']))
" 2>"$CSD/out"; echo $?)"
assert_eq "#298 OSError backstop: unwrapped-site fault exits 2" "2" "$CS_BACKSTOP_RC"
assert_eq "#298 OSError backstop: emits a diagnostic (no bare traceback)" "yes" \
  "$(grep -qF 'consolidate-changesets.py:' "$CSD/out" && ! grep -qF 'Traceback' "$CSD/out" && echo yes || echo no)"
rm -rf "$CSD"

# Coupled invariant: the merge-time workflow wires the consolidator and pushes on main. The
# YAML lives at .github/workflows/version-consolidate.yml; it is content-pinned here regardless
# of its path.
CS_WF="$FDROOT/.github/workflows/version-consolidate.yml"
assert_eq "#290 version-consolidate workflow exists (.github/workflows/)" "yes" "$([ -f "$CS_WF" ] && echo yes || echo no)"
assert_pin_unique "#290 workflow triggers on push to main" \
  'branches: [main]' "$CS_WF"
assert_pin_unique "#290 workflow runs the consolidator by path" \
  'python3 scripts/consolidate-changesets.py' "$CS_WF"
# #298: the consolidate step hardens its shell (explicit set -euo pipefail, not just the
# implicit Actions default) and checks the consolidator's exit status explicitly so a
# malformed changeset makes the step go red (distinguishable from the No-pending no-op).
assert_pin_unique "#298 workflow consolidate step sets an explicit set -euo pipefail" \
  'set -euo pipefail' "$CS_WF"
assert_pin_unique "#298 workflow consolidate step checks the consolidator exit status explicitly" \
  '::error::consolidator failed' "$CS_WF"
# Anchor on the 2-space-indented workflow-permissions line so this stays unique after the
# app-token step added `permission-contents: write` (which also contains `contents: write`).
assert_pin_unique "#290 workflow grants contents: write for the bump push" \
  '  contents: write' "$CS_WF"
# Self-trigger loop guard: the job skips its own `chore: bump version` head commit.
assert_pin_unique "#290 workflow guards against its own bump commit re-triggering (no loop)" \
  "startsWith(github.event.head_commit.message, 'chore: bump version')" "$CS_WF"

# The implement extension retains the engine-surface changeset gate independently of
# the Phase 3 procedure's exact wording.
assert_pin_unique "#290 implement prompt-extension gate: engine-surface change with no changeset FAILs" \
  'FAILs on an engine-surface change that carries **no** changeset file' "$FDROOT/.prflow/prompt-extensions/implement.md"
# The .changeset/ contributor doc must exist and document the required bump frontmatter.
assert_eq "#290 .changeset/README.md exists" "yes" \
  "$([ -f "$FDROOT/.changeset/README.md" ] && echo yes || echo no)"
assert_eq "#290 .changeset/README documents the bump frontmatter key" "yes" \
  "$(grep -qiF 'bump' "$FDROOT/.changeset/README.md" && echo yes || echo no)"

# ────────────────────────────────────────────────────────────────────────────
echo "#1373 repo's own pending changesets validate against the consolidator's parser"
# ────────────────────────────────────────────────────────────────────────────
# A .changeset/*.md using the npm form (`"prflow": patch`) instead of the required
# `bump: patch` parses to a human eye and passes every PR-side check, then aborts
# version-consolidate at merge time on main. lib/test/check_pending_changesets.py parses
# every tracked .changeset/*.md with the SAME _parse_changeset the consolidator uses
# (imported, never the consolidator itself — that mutates the tree), enumerating the
# population from the git index rather than a repo-root walk. Each AC of #1373 maps to at
# least one behavioral assertion below.
CS_CHECK="$FDROOT/lib/test/check_pending_changesets.py"
assert_eq "#1373 check_pending_changesets.py exists" "yes" "$([ -f "$CS_CHECK" ] && echo yes || echo no)"

# The repo's own pending changesets (enumerated from the git index) all parse — the live
# guard: a bad changeset committed to this branch turns the suite RED at the desk and in CI.
python3 "$CS_CHECK" --root "$FDROOT" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 repo's own tracked .changeset/*.md all parse cleanly" "0" "$CS_RC"

# AC: the npm `"pkg": patch` form turns the check RED, naming the offending file AND the
# parser's own error text (proving the failure is diagnosable, not a bare non-zero exit).
TMP_CSFX="$(mktemp -d)"
printf -- '---\n"prflow": patch\n---\n\n- npm form (#1373)\n' > "$TMP_CSFX/npm.md"
python3 "$CS_CHECK" "$TMP_CSFX/npm.md" >"$TMP_CSFX/out" 2>&1; CS_RC=$?
assert_eq "#1373 npm form: check exits non-zero (RED)" "yes" "$([ "$CS_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#1373 npm form: message names the offending file" "yes" \
  "$(grep -qF 'npm.md' "$TMP_CSFX/out" && echo yes || echo no)"
assert_eq "#1373 npm form: message carries the parser's own error text" "yes" \
  "$(grep -qF "missing required 'bump:' key" "$TMP_CSFX/out" && echo yes || echo no)"

# AC: the correct `bump:` form is green.
printf -- '---\nbump: patch\ntype: Fixed\n---\n\n- correct form (#1373)\n' > "$TMP_CSFX/good.md"
python3 "$CS_CHECK" "$TMP_CSFX/good.md" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 correct bump: form parses cleanly (green)" "0" "$CS_RC"

# AC: parse-only — the check never runs the consolidator (which deletes consumed changesets
# and rewrites tracked files). Run it on a VALID fixture changeset in a directory of its own
# and assert the helper ran clean, the changeset survived (the consolidator would have deleted
# it), and no consolidator output (plugin.json / CHANGELOG.md) was materialized.
CSPO="$(mktemp -d)"
printf -- '---\nbump: patch\n---\n\n- keep (#1373)\n' > "$CSPO/keep.md"
python3 "$CS_CHECK" "$CSPO/keep.md" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 parse-only: helper ran to a clean verdict on the valid fixture" "0" "$CS_RC"
assert_eq "#1373 parse-only: valid changeset NOT deleted (consolidator would delete it)" "yes" \
  "$([ -f "$CSPO/keep.md" ] && echo yes || echo no)"
assert_eq "#1373 parse-only: no consolidator output written (tree byte-identical)" "yes" \
  "$([ ! -f "$CSPO/CHANGELOG.md" ] && [ ! -e "$CSPO/.claude-plugin" ] && echo yes || echo no)"
rm -rf "$CSPO" "$TMP_CSFX"

# AC: enumeration reads the git INDEX, not a filesystem walk. A tracked-good + untracked-bad
# .changeset pair must pass — git ls-files sees only the tracked good file, while a recursive
# repo-root walk would find the untracked malformed file and (wrongly) go RED. This is also
# what makes the result worktree-immune (issue #711).
CSIDX="$(mktemp -d)"
git -C "$CSIDX" init -q >/dev/null 2>&1
mkdir -p "$CSIDX/.changeset"
printf -- '---\nbump: patch\n---\n\n- tracked good (#1373)\n' > "$CSIDX/.changeset/good.md"
git -C "$CSIDX" add .changeset/good.md >/dev/null 2>&1
printf -- '---\n"prflow": patch\n---\n\n- untracked bad (#1373)\n' > "$CSIDX/.changeset/bad.md"
python3 "$CS_CHECK" --root "$CSIDX" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 index enumeration: an UNTRACKED malformed changeset is not audited (index, not walk)" "0" "$CS_RC"
# And a TRACKED malformed changeset in the same fixture does go RED — the enumeration is live.
git -C "$CSIDX" add .changeset/bad.md >/dev/null 2>&1
python3 "$CS_CHECK" --root "$CSIDX" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 index enumeration: a TRACKED malformed changeset turns the check RED" "yes" \
  "$([ "$CS_RC" -ne 0 ] && echo yes || echo no)"
rm -rf "$CSIDX"

# AC: README.md is exempt (the consolidator's own _is_consumable predicate), so a tracked
# README.md that is not a changeset does not turn the check RED.
CSRD="$(mktemp -d)"
git -C "$CSRD" init -q >/dev/null 2>&1
mkdir -p "$CSRD/.changeset"
printf '# Changesets\nprose, not a changeset\n' > "$CSRD/.changeset/README.md"
printf -- '---\nbump: patch\n---\n\n- good (#1373)\n' > "$CSRD/.changeset/good.md"
git -C "$CSRD" add .changeset/README.md .changeset/good.md >/dev/null 2>&1
python3 "$CS_CHECK" --root "$CSRD" >/dev/null 2>&1; CS_RC=$?
assert_eq "#1373 README.md is exempt from the changeset audit" "0" "$CS_RC"
rm -rf "$CSRD"

# ────────────────────────────────────────────────────────────────────────────
echo "#953 pinned release-tag sites: derivation, drift guard, bump rewrite, tag/release"
# ────────────────────────────────────────────────────────────────────────────
# The install docs pin a release tag in two machine-recognizable forms (the installer
# download URL and DEVFLOW_REF=). Nothing coupled them to plugin.json, so a merge-time bump
# left them a release behind. scripts/version_pins.py DERIVES that site set (never a
# hardcoded file list, so a documentation page added later cannot escape), the consolidator
# rewrites it in the same commit as the bump, and scripts/publish-release.sh tags the result.
#
# Everything below is an executable test over the real interfaces, with a negative control
# for each guard — no wording pins. The tag-EXISTENCE half needs the network and therefore
# lives in the workflow, not here: this suite is network-free by contract.
VP="$FDROOT/scripts/version_pins.py"
assert_eq "#953 version_pins.py exists" "yes" "$([ -f "$VP" ] && echo yes || echo no)"
assert_eq "#953 version_pins.py is executable" "yes" "$([ -x "$VP" ] && echo yes || echo no)"

# ── The live invariant: this repository's own pins agree with its own manifest. ──────
python3 "$VP" --root "$FDROOT" --check >/dev/null 2>&1; VP_RC=$?
assert_eq "#953 live repo: every derived pin site agrees with plugin.json" "0" "$VP_RC"
# Non-vacuity: a pattern that silently stopped matching would make --check pass over an
# EMPTY site set. Require the live derivation to find sites, and both forms among them.
VP_LIVE="$(python3 "$VP" --root "$FDROOT" --list 2>/dev/null)"
assert_eq "#953 live repo: the derivation is non-empty (a pattern that matches nothing cannot pass vacuously)" "yes" \
  "$([ -n "$VP_LIVE" ] && echo yes || echo no)"
for vp_form in raw-url devflow-ref; do
  assert_eq "#953 live repo: the derivation covers the $vp_form pin form" "yes" \
    "$(printf '%s\n' "$VP_LIVE" | grep -qF "	$vp_form	" && echo yes || echo no)"
done
# --print-version is what the workflow derives the tag name from; it must equal the manifest.
assert_eq "#953 --print-version equals plugin.json's version" \
  "$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["version"])' "$FDROOT/.claude-plugin/plugin.json")" \
  "$(python3 "$VP" --root "$FDROOT" --print-version)"

# ── Fixture tree: derivation scope, the drift guard, and its negative control. ───────
# The CLI's population is index-derived (issue #711), so a fixture must be a real git repo
# with its files in the index. `git add` alone is enough — `git ls-files --cached` reads the
# index, never a commit — which also keeps the fixture cheap (no identity config needed).
vp_index() { git -C "$1" add -A >/dev/null 2>&1; }

vp_repo() {  # -> prints an isolated fake repo root carrying both pin forms
  local d; d="$(mktemp -d)"
  mkdir -p "$d/.claude-plugin" "$d/docs/internal" "$d/lib/test" "$d/.changeset" "$d/.prflow/logs" \
           "$d/.prflow/vendor/prflow/docs/internal" "$d/.prflow/learnings" "$d/.claude/worktrees/wt/docs/internal"
  printf '{\n  "name": "devflow",\n  "version": "3.1.4"\n}\n' > "$d/.claude-plugin/plugin.json"
  printf 'curl -fsSL https://raw.githubusercontent.com/o/r/v3.1.4/install.sh -o i.sh\nDEVFLOW_REF=v3.1.4 bash i.sh\n' \
    > "$d/docs/internal/install.md"
  # Version-shaped tokens that are NOT release pins: a spec URL, a vendored tool version,
  # an upstream runner version, a historical migration note. None may be rewritten.
  printf 'semver.org/spec/v2.0.0.html SHELLCHECK v0.11.0 Copilot CLI v1.0.67 migration v2.8.12\n' \
    > "$d/docs/history.md"
  # A non-UTF-8 (binary) file carrying pin-shaped BYTES. Not decodable text, therefore not a
  # pin site: it must be skipped, never fail the scan and never be rewritten.
  printf 'DEVFLOW_REF=v0.0.9 \377\376\000\001 binary asset\n' > "$d/docs/logo.bin"
  # Excluded populations, each carrying a deliberately stale pin.
  printf 'DEVFLOW_REF=v0.0.1 quoted release history\n' > "$d/CHANGELOG.md"
  printf 'DEVFLOW_REF=v0.0.2 suite fixture (the negative control for this very guard)\n' > "$d/lib/test/fx.md"
  # README.md, not a synthetic changeset: `.changeset/*.md` is a consumable population, so
  # an unparseable file there would (correctly) fail the consolidator before this fixture
  # could test anything. README.md is the one exempt name.
  printf 'DEVFLOW_REF=v0.0.3 contributor doc in the changeset dir\n' > "$d/.changeset/README.md"
  printf 'DEVFLOW_REF=v0.0.4 machine-appended corpus\n' > "$d/.prflow/logs/x.md"
  # A materialized copy of some OTHER release of the plugin — the most realistic carrier of
  # a stale pin, and the one whose accidental inclusion would make every scan drift-red.
  printf 'DEVFLOW_REF=v0.0.5 vendored copy of another release\n' > "$d/.prflow/vendor/prflow/docs/internal/install.md"
  printf 'DEVFLOW_REF=v0.0.6 machine-appended learnings corpus\n' > "$d/.prflow/learnings/p.md"
  # The issue-#711 sibling-worktree guard: another branch's checkout under .claude/worktrees/.
  printf 'DEVFLOW_REF=v0.0.7 another branch checkout\n' > "$d/.claude/worktrees/wt/docs/internal/install.md"
  git -C "$d" init -q >/dev/null 2>&1
  vp_index "$d"
  printf '%s\n' "$d"
}

VPD="$(vp_repo)"
python3 "$VP" --root "$VPD" --check >/dev/null 2>&1
assert_eq "#953 fixture: a self-consistent tree passes --check" "0" "$?"
VPL="$(python3 "$VP" --root "$VPD" --list)"
assert_eq "#953 fixture: derives exactly the two real pin sites" "2" \
  "$(printf '%s\n' "$VPL" | grep -c 'docs/internal/install.md')"
for vp_excluded in CHANGELOG.md lib/test .changeset .prflow/logs .prflow/vendor .prflow/learnings .claude/worktrees; do
  assert_eq "#953 fixture: the excluded population $vp_excluded contributes no pin site" "0" \
    "$(printf '%s\n' "$VPL" | grep -cF "$vp_excluded")"
done
assert_eq "#953 fixture: a version-shaped token that is not a release pin is not a site" "0" \
  "$(printf '%s\n' "$VPL" | grep -cF 'history.md')"
# A non-UTF-8 file is skipped as non-text: not a site, and not a scan failure either.
assert_eq "#953 fixture: a non-UTF-8 file carrying pin-shaped bytes is skipped, not a site" "0" \
  "$(printf '%s\n' "$VPL" | grep -cF 'logo.bin')"
rm -rf "$VPD"

# ── Issue #711: the CLI population is the INDEX, so untracked host state cannot decide
# ── the answer. The regression this replaces: DevFlow's own review scratch under
# ── .prflow/tmp/ holds a cached diff.patch carrying BOTH pin forms at arbitrary
# ── versions, so a repo-root filesystem walk made --check RED on any developer machine
# ── mid-review while a fresh CI checkout stayed green — the exact locally-red/CI-green,
# ── run-to-run-varying divergence CLAUDE.md's #711 convention exists to prevent.
# ── This is a CLASS control, not a .prflow/tmp/ one: the file is invisible because it is
# ── untracked, so a scratch directory nobody has invented yet is covered by the same fact.
VPD="$(vp_repo)"
mkdir -p "$VPD/.prflow/tmp/review" "$VPD/some-future-scratch-dir"
printf 'raw.githubusercontent.com/o/r/v0.0.1/install.sh\nDEVFLOW_REF=v0.0.2\n' \
  > "$VPD/.prflow/tmp/review/diff.patch"
printf 'DEVFLOW_REF=v0.0.3 a scratch dir no exclusion list names\n' \
  > "$VPD/some-future-scratch-dir/notes.md"
python3 "$VP" --root "$VPD" --check >"$VPD/out" 2>&1
assert_eq "#953 #711: untracked scratch carrying drifted pins does not redden --check" "0" "$?"
VPL="$(python3 "$VP" --root "$VPD" --list)"
for vp_scratch in .prflow/tmp some-future-scratch-dir; do
  assert_eq "#953 #711: the untracked path $vp_scratch is absent from the derived population" "0" \
    "$(printf '%s\n' "$VPL" | grep -cF "$vp_scratch")"
done
# ...and the guard is NOT merely blind: staling a TRACKED site in the same tree still reddens,
# so the control above is exclusion-by-tracking, not a disabled check.
printf 'curl -fsSL https://raw.githubusercontent.com/o/r/v3.1.3/install.sh -o i.sh\nDEVFLOW_REF=v3.1.4 bash i.sh\n' \
  > "$VPD/docs/internal/install.md"
python3 "$VP" --root "$VPD" --check >/dev/null 2>&1
assert_eq "#953 #711: a TRACKED drifted pin in that same tree still fails --check" "1" "$?"
rm -rf "$VPD"

# The index population fails CLOSED. A root that is not a git work tree cannot be enumerated
# from the index, and the CLI must say so (exit 2) rather than silently degrading to the walk
# — a silent fallback would restore the untracked-host-state dependence just removed.
VPD="$(mktemp -d)"; mkdir -p "$VPD/.claude-plugin" "$VPD/docs"
printf '{ "version": "3.1.4" }\n' > "$VPD/.claude-plugin/plugin.json"
printf 'DEVFLOW_REF=v3.1.4\n' > "$VPD/docs/internal/install.md"
python3 "$VP" --root "$VPD" --check >"$VPD/out" 2>&1
assert_eq "#953 #711: a non-git root exits 2 (fails closed, never degrades to a walk)" "2" "$?"
assert_eq "#953 #711: that fault names the index-derived population contract" "1" \
  "$(grep -c 'index-derived' "$VPD/out")"
# --print-version reads only the manifest, so it stays usable where no index exists: the
# workflow derives the tag name from it, and coupling that to an enumeration would be gratuitous.
assert_eq "#953 #711: --print-version needs no index (the workflow's tag derivation)" "3.1.4" \
  "$(python3 "$VP" --root "$VPD" --print-version)"
rm -rf "$VPD"

# ── FAIL-CLOSED FLOOR: an EMPTY site set is a fault, not a clean pass. `drifted` is empty
# ── both when every pin agrees and when the derivation matched nothing at all, so a pattern
# ── regression would silence this guard AND the merge-time render_rewrites at the same
# ── moment — the guard passing loudest exactly where it has stopped working.
VPD="$(mktemp -d)"; mkdir -p "$VPD/.claude-plugin" "$VPD/docs/internal"
printf '{ "version": "3.1.4" }\n' > "$VPD/.claude-plugin/plugin.json"
printf 'A documentation page with no release pin in either machine-recognizable form.\n' \
  > "$VPD/docs/internal/install.md"
git -C "$VPD" init -q >/dev/null 2>&1; vp_index "$VPD"
python3 "$VP" --root "$VPD" --check >"$VPD/out" 2>&1
assert_eq "#953 vacuity floor: a derivation that matches NOTHING exits 2, never a clean 0" "2" "$?"
assert_eq "#953 vacuity floor: the diagnostic says an empty site set is a fault" "1" \
  "$(grep -c 'empty site set is a fault' "$VPD/out")"
# Positive control: the SAME tree with one real pin added passes, so the floor is a floor and
# not a check that now rejects everything.
printf 'DEVFLOW_REF=v3.1.4 payload ref\n' >> "$VPD/docs/internal/install.md"; vp_index "$VPD"
python3 "$VP" --root "$VPD" --check >/dev/null 2>&1
assert_eq "#953 vacuity floor: one real pin site is enough to pass (the floor is not a wall)" "0" "$?"
rm -rf "$VPD"

# ── The --rewrite CLI mode: the only disk-writing entry point, and its OSError fault arm. ──
VPD="$(vp_repo)"
VP_OUT="$(python3 "$VP" --root "$VPD" --rewrite 3.2.0)"
assert_eq "#953 --rewrite: both pin forms in the tracked doc move to the new version" "yes" \
  "$([ "$(grep -cF 'githubusercontent.com/o/r/v3.2.0/' "$VPD/docs/internal/install.md")" = "1" ] &&
    [ "$(grep -cF 'DEVFLOW_REF=v3.2.0' "$VPD/docs/internal/install.md")" = "1" ] && echo yes || echo no)"
assert_eq "#953 --rewrite: prints exactly the files it changed" "docs/internal/install.md" "$VP_OUT"
assert_eq "#953 --rewrite: a file with no pin is never listed and never touched" "0" \
  "$(printf '%s\n' "$VP_OUT" | grep -cF 'history.md')"
# An excluded/untracked population is not rewritten either — --rewrite shares --check's
# population, so the two can never disagree about what the pin set is.
assert_eq "#953 --rewrite: the vendored copy of another release is left alone" "1" \
  "$(grep -cF 'DEVFLOW_REF=v0.0.5' "$VPD/.prflow/vendor/prflow/docs/internal/install.md")"
# Idempotent: a second --rewrite to the same version writes nothing (files already at it are
# omitted from the write set — the documented no-op-bump claim).
assert_eq "#953 --rewrite: re-running at the same version is a no-op (empty write set)" "" \
  "$(python3 "$VP" --root "$VPD" --rewrite 3.2.0)"
assert_eq "#953 --rewrite: rejects a malformed version before any write (exit 2)" "2" \
  "$(python3 "$VP" --root "$VPD" --rewrite 'not-a-version' >/dev/null 2>&1; echo $?)"
# The write fault arm: _write_rewrites maps an OSError to VersionPinError -> exit 2 with a
# named path, never a bare traceback. Injected deterministically (a chmod cannot express the
# fault as root or on a permissive filesystem).
VP_RC="$(python3 -c "
import importlib.util as u, sys
s=u.spec_from_file_location('vp','$VP'); m=u.module_from_spec(s); s.loader.exec_module(m)
_real=open
def boom(path, *a, **k):
    if str(path).endswith('docs/internal/install.md') and 'w' in (a[0] if a else k.get('mode','r')):
        raise OSError('injected write fault')
    return _real(path, *a, **k)
m.open = boom
sys.exit(m.main(['--root','$VPD','--rewrite','3.3.0']))
" 2>"$VPD/werr"; echo $?)"
assert_eq "#953 --rewrite: a write OSError exits 2" "2" "$VP_RC"
assert_eq "#953 --rewrite: that fault names the unwritable path" "1" \
  "$(grep -cF 'docs/internal/install.md: cannot write: injected write fault' "$VPD/werr")"
assert_eq "#953 --rewrite: no bare traceback on a write fault" "0" "$(grep -cF 'Traceback' "$VPD/werr")"
rm -rf "$VPD"

# NEGATIVE CONTROL for the offline drift guard: stale ONE site of the two and the guard must
# go RED, naming that site. This is the exact regression the guard exists for.
VPD="$(vp_repo)"
printf 'curl -fsSL https://raw.githubusercontent.com/o/r/v3.1.3/install.sh -o i.sh\nDEVFLOW_REF=v3.1.4 bash i.sh\n' \
  > "$VPD/docs/internal/install.md"
python3 "$VP" --root "$VPD" --check >"$VPD/out" 2>&1; VP_RC=$?
assert_eq "#953 drift negative control: one stale pin site fails --check (exit 1)" "1" "$VP_RC"
assert_eq "#953 drift negative control: the diagnostic names the drifted file, line and pattern" "1" \
  "$(grep -cF 'docs/internal/install.md:1: raw-url pins v3.1.3, expected v3.1.4' "$VPD/out")"
assert_eq "#953 drift negative control: the still-correct sibling site is NOT reported" "0" \
  "$(grep -c 'devflow-ref' "$VPD/out")"
rm -rf "$VPD"

# A structurally broken manifest is a fault (exit 2), never a silent clean pass.
VPD="$(vp_repo)"; printf '{ "name": "devflow" }\n' > "$VPD/.claude-plugin/plugin.json"
python3 "$VP" --root "$VPD" --check >/dev/null 2>&1
assert_eq "#953 fixture: a manifest with no version key exits 2 (fault, not clean)" "2" "$?"
rm -rf "$VPD"
VPD="$(vp_repo)"; printf '{ "version": "not-a-version" }\n' > "$VPD/.claude-plugin/plugin.json"
python3 "$VP" --root "$VPD" --check >/dev/null 2>&1
assert_eq "#953 fixture: a non-N.N.N manifest version exits 2" "2" "$?"
rm -rf "$VPD"

# ── The bump rewrites every derived pin site, in the consolidator's own run. ─────────
VPD="$(vp_repo)"
printf 'curl -fsSL https://raw.githubusercontent.com/o/r/v3.1.4/install.sh -o i.sh\nDEVFLOW_REF=v3.1.4 bash i.sh\n' \
  > "$VPD/docs/internal/install.md"
# A SECOND documentation page, added after the fact — the derived-set property under test.
printf 'Also pinned: DEVFLOW_REF=v3.1.4 for the payload.\n' > "$VPD/docs/late-arrival.md"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n\n### Fixed\n- old (#1)\n' > "$VPD/CHANGELOG.md"
printf -- '---\nbump: patch\ntype: Fixed\n---\n\n- Bumped. (#953)\n' > "$VPD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$VPD" --date 2026-07-30 \
  --emit-entry-to "$VPD/notes.out" --emit-write-set-to "$VPD/ws.out" \
  --emit-bump-to "$VPD/bump.out" >/dev/null 2>&1
assert_eq "#953 bump: the manifest moved to 3.1.5" "3.1.5" "$(cs_ver "$VPD")"
assert_eq "#953 bump: the URL pin moved in the same run" "1" \
  "$(grep -cF 'githubusercontent.com/o/r/v3.1.5/' "$VPD/docs/internal/install.md")"
assert_eq "#953 bump: the DEVFLOW_REF pin moved in the same run" "1" \
  "$(grep -cF 'DEVFLOW_REF=v3.1.5' "$VPD/docs/internal/install.md")"
assert_eq "#953 bump: a doc added later is covered because the site set is DERIVED, not listed" "1" \
  "$(grep -cF 'DEVFLOW_REF=v3.1.5' "$VPD/docs/late-arrival.md")"
# Index the later-added page before re-checking: the CLI's population is the index (#711),
# so leaving it untracked would make this assertion pass by not looking at it.
vp_index "$VPD"
assert_eq "#953 bump: the tree is self-consistent afterwards (the tagged tree's docs say vN)" "0" \
  "$(python3 "$VP" --root "$VPD" --check >/dev/null 2>&1; echo $?)"
# The write set is what the workflow stages; an omitted pin file is silently discarded by
# the next `git reset --hard`, so every rewritten file must appear in it.
for vp_w in .claude-plugin/plugin.json CHANGELOG.md docs/internal/install.md docs/late-arrival.md; do
  assert_eq "#953 bump: --emit-write-set-to names the rewritten file $vp_w" "1" \
    "$(grep -cxF "$vp_w" "$VPD/ws.out")"
done
assert_eq "#953 bump: --emit-write-set-to does NOT name a file the run never wrote" "0" \
  "$(grep -cF 'docs/history.md' "$VPD/ws.out")"
assert_eq "#953 bump: --emit-entry-to writes the assembled entry heading (the Release notes body)" "1" \
  "$(grep -cF '## [3.1.5]' "$VPD/notes.out")"
assert_eq "#953 bump: --emit-entry-to carries the changeset prose into that body" "1" \
  "$(grep -cF 'Bumped.' "$VPD/notes.out")"
# #970: the release decision reads the bump kind from HERE — the value this run already
# computed as the single highest pending bump — never re-inferred downstream from a version
# diff. This set is patch-only, so the side channel must say `patch`.
assert_eq "#970 bump: --emit-bump-to reports the computed highest bump (patch-only set)" "patch" \
  "$(cat "$VPD/bump.out")"
# Side channels are opt-in: without the flags nothing extra is written (the unit tests above
# call the consolidator without them, and the repo must never gain stray output files).
rm -rf "$VPD"
VPD="$(vp_repo)"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n' > "$VPD/CHANGELOG.md"
printf -- '---\nbump: patch\n---\n\n- Bumped. (#953)\n' > "$VPD/.changeset/a.md"
python3 "$CS_SCRIPT" --root "$VPD" --date 2026-07-30 >/dev/null 2>&1
assert_eq "#953 bump: the side channels are opt-in (no stray files without the flags)" "yes" \
  "$([ ! -e "$VPD/notes.out" ] && [ ! -e "$VPD/ws.out" ] && [ ! -e "$VPD/bump.out" ] &&
     echo yes || echo no)"
rm -rf "$VPD"

# #970: --emit-bump-to reports the HIGHEST of a mixed pending set, matching the version the
# same run computes. Without this the patch-only case above would pass for a helper that
# simply echoed a constant, and the announcement decision would silently drop a feature
# release whenever a patch changeset merged alongside it.
VPD="$(vp_repo)"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n' > "$VPD/CHANGELOG.md"
printf -- '---\nbump: patch\n---\n\n- A fix. (#970)\n' > "$VPD/.changeset/a.md"
printf -- '---\nbump: minor\n---\n\n- A feature. (#970)\n' > "$VPD/.changeset/b.md"
python3 "$CS_SCRIPT" --root "$VPD" --date 2026-07-30 --emit-bump-to "$VPD/bump.out" >/dev/null 2>&1
assert_eq "#970 bump: a patch alongside a minor reports minor, not patch" "minor" "$(cat "$VPD/bump.out")"
assert_eq "#970 bump: and the reported kind is the one the version actually moved by" "3.2.0" "$(cs_ver "$VPD")"
rm -rf "$VPD"
# ...and a major dominates a minor, so the ranking is exercised at both steps.
VPD="$(vp_repo)"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n' > "$VPD/CHANGELOG.md"
printf -- '---\nbump: minor\n---\n\n- A feature. (#970)\n' > "$VPD/.changeset/a.md"
printf -- '---\nbump: major\n---\n\n- A break. (#970)\n' > "$VPD/.changeset/b.md"
python3 "$CS_SCRIPT" --root "$VPD" --date 2026-07-30 --emit-bump-to "$VPD/bump.out" >/dev/null 2>&1
assert_eq "#970 bump: a minor alongside a major reports major" "major" "$(cat "$VPD/bump.out")"
rm -rf "$VPD"
# A run with NOTHING pending writes no bump kind at all: "no bump happened" must stay
# distinguishable from "a patch bump happened", or the workflow could relay a stale answer.
VPD="$(vp_repo)"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n' > "$VPD/CHANGELOG.md"
python3 "$CS_SCRIPT" --root "$VPD" --date 2026-07-30 --emit-bump-to "$VPD/bump.out" >/dev/null 2>&1
assert_eq "#970 bump: a no-op run leaves the bump-kind channel ABSENT, never defaulted" "yes" \
  "$([ ! -e "$VPD/bump.out" ] && echo yes || echo no)"
rm -rf "$VPD"

# A pin-rewrite fault must abort BEFORE any write, preserving the consolidator's
# read-before-write atomicity: the pin render is the LAST assembly step, so a fault there is
# the one most likely to be mis-ordered after the first write. Injected deterministically
# (the same monkeypatch technique the #298 OSError-backstop test uses) rather than through a
# chmod, which cannot express the fault as root or on a permissive filesystem.
VPD="$(vp_repo)"
printf '# Changelog\n\nPreamble.\n\n## [3.1.4] - 2026-07-03\n' > "$VPD/CHANGELOG.md"
printf -- '---\nbump: patch\n---\n\n- Bumped. (#953)\n' > "$VPD/.changeset/a.md"
VP_RC="$(python3 -c "
import importlib.util as u, sys
s=u.spec_from_file_location('c','$CS_SCRIPT'); m=u.module_from_spec(s); s.loader.exec_module(m)
def boom(root, version): raise m.version_pins.VersionPinError('docs/internal/install.md: injected read fault')
m.version_pins.render_rewrites = boom
sys.exit(m.main(['--root','$VPD','--date','2026-07-30']))
" 2>"$VPD/out"; echo $?)"
assert_eq "#953 pin-rewrite fault: exits 2" "2" "$VP_RC"
assert_eq "#953 pin-rewrite fault: the diagnostic names the file" "1" \
  "$(grep -cF 'docs/internal/install.md: injected read fault' "$VPD/out")"
assert_eq "#953 pin-rewrite fault: no bare traceback" "0" "$(grep -cF 'Traceback' "$VPD/out")"
assert_eq "#953 pin-rewrite fault: the manifest is left unbumped (aborts before any write)" "3.1.4" \
  "$(cs_ver "$VPD")"
assert_eq "#953 pin-rewrite fault: the changeset is NOT consumed" "yes" \
  "$([ -f "$VPD/.changeset/a.md" ] && echo yes || echo no)"
rm -rf "$VPD"

# ── scripts/publish-release.sh: every branch of the tag + Release selection. ─────────
# Extracted from the workflow precisely so each arm is drivable here. `git` is stubbed on
# PATH and `gh` through DEVFLOW_GH, so nothing touches the network.
PR953="$FDROOT/scripts/publish-release.sh"
assert_eq "#953 publish-release.sh exists and is executable" "yes" \
  "$([ -x "$PR953" ] && echo yes || echo no)"

pr953_env() {  # -> prints a scratch dir holding the git/gh stubs and their call logs
  local d; d="$(mktemp -d)"; mkdir -p "$d/bin"
  # `git push` records the landed ref in a STATE FILE rather than an env var, so the
  # parent-visible effect of a push is real: the post-push `ls-remote` verification then
  # observes what the push actually did, which is the whole point of that probe.
  cat > "$d/bin/git" <<'PR953GIT'
#!/usr/bin/env bash
printf '%s\n' "git $*" >> "$PR953_LOG"
case "$1 $2" in
  # `git ls-remote --exit-code` has THREE answers: 0 resolves, 2 queried-and-absent, and
  # anything else is the query itself failing (128 for an unreachable remote). The helper
  # must not fold the third into "absent", so the stub can produce it on demand.
  "ls-remote --exit-code")
    [ "${PR953_LSREMOTE_ERRORS:-0}" = "1" ] && exit 128
    [ -f "$PR953_STATE" ] && exit 0; exit 2 ;;
esac
case "$1" in
  tag)  exit 0 ;;
  push)
    [ "${PR953_PUSH_FAILS:-0}" = "1" ] && exit 1
    # A push that reports success without the ref landing — the exact silent failure the
    # verification probe exists to catch.
    [ "${PR953_PUSH_DOES_NOT_LAND:-0}" = "1" ] && exit 0
    : > "$PR953_STATE"; exit 0 ;;
esac
exit 0
PR953GIT
  cat > "$d/bin/gh" <<'PR953GH'
#!/usr/bin/env bash
printf '%s\n' "gh $*" >> "$PR953_LOG"
case "$*" in
  *"releases/tags/"*) [ "${PR953_RELEASE_EXISTS:-0}" = "1" ] && exit 0; exit 1 ;;
esac
[ "${PR953_RELEASE_POST_FAILS:-0}" = "1" ] && exit 1
exit 0
PR953GH
  chmod +x "$d/bin/git" "$d/bin/gh"
  printf '%s\n' "$d"
}

PRD="$(pr953_env)"

# Arm 1 (the happy path): no tag on the remote → create it, push it, verify it, publish.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: fresh tag — exit 0 (tag created, verified, Release published)" "0" "$VP_RC"
assert_eq "#953 publish-release: fresh tag — an ANNOTATED tag is created (never lightweight)" "1" \
  "$(grep -cF 'git tag -a v9.9.9' "$PRD/log")"
assert_eq "#953 publish-release: fresh tag — the tag ref is pushed" "1" \
  "$(grep -cF 'git push origin refs/tags/v9.9.9' "$PRD/log")"

# Arm 1b (NEGATIVE CONTROL for the network half of the drift guard): the push reports
# success but the ref never lands → the run must go RED, and no Release may be published
# against a tag the install docs pin but that does not exist.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_PUSH_DOES_NOT_LAND=1 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: a push that does not land fails closed (exit 1)" "1" "$VP_RC"
assert_eq "#953 publish-release: the unverified-tag error names the pin consequence" "1" \
  "$(grep -cF 'does not resolve on origin' "$PRD/out")"
assert_eq "#953 publish-release: an unverified tag publishes NO Release" "0" \
  "$(grep -c 'api --method POST' "$PRD/log")"

# Arm 2: the tag already resolves on the remote → leave it alone, still publish the Release.
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_RELEASE_EXISTS=0 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: existing tag — exit 0 (idempotent, a re-run never fails on done work)" "0" "$VP_RC"
assert_eq "#953 publish-release: existing tag — no second tag object is created" "0" \
  "$(grep -c 'git tag' "$PRD/log")"
assert_eq "#953 publish-release: existing tag — the Release is still published as latest" "1" \
  "$(grep -cF 'make_latest=true' "$PRD/log")"
assert_eq "#953 publish-release: the Release is created through REST gh api" "1" \
  "$(grep -cF 'api --method POST repos/o/r/releases' "$PRD/log")"
assert_eq "#953 publish-release: never through gh release porcelain (org-scoped GraphQL fails silently under a repo-scoped token)" "0" \
  "$(grep -c 'gh release create' "$PRD/log")"

# Arm 3: a Release for the tag already exists → leave it alone (no duplicate POST).
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_RELEASE_EXISTS=1 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: existing Release — exit 0 and no duplicate POST" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -c 'api --method POST' "$PRD/log")" -eq 0 ] && echo yes || echo no)"

# Arm 4: --release never → the tag is created and verified, but no Release is published.
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --release never >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: --release never — exit 0 with no gh call at all" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -c '^gh ' "$PRD/log")" -eq 0 ] && echo yes || echo no)"

# Arm 5: the tag push itself fails → loud, and the Release is never attempted.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_PUSH_FAILS=1 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: tag push failure — exit 1, no Release attempted" "yes" \
  "$([ "$VP_RC" -eq 1 ] && [ "$(grep -c '^gh ' "$PRD/log")" -eq 0 ] && echo yes || echo no)"

# Arm 6: the Release POST fails → loud, naming the docs-page consequence.
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_RELEASE_POST_FAILS=1 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: Release POST failure — exit 1" "1" "$VP_RC"
assert_eq "#953 publish-release: Release POST failure — the diagnostic names the missing-release consequence" "1" \
  "$(grep -cF 'Releases page the install docs cite is now missing this release' "$PRD/out")"

# Arm 7: input validation — a malformed version never reaches git.
for vp_bad in "" "2.26" "2.26.3.1" "v2.26.3" "2..3" "abc"; do
  : > "$PRD/log"; : > "$PRD/state"
  PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
    PATH="$PRD/bin:$PATH" "$PR953" --version "$vp_bad" --repo o/r >/dev/null 2>&1; VP_RC=$?
  assert_eq "#953 publish-release: rejects the malformed version '$vp_bad' (exit 2, no git call)" "yes" \
    "$([ "$VP_RC" -eq 2 ] && [ ! -s "$PRD/log" ] && echo yes || echo no)"
done
# ...and a well-formed one is accepted, so the validator is not vacuously rejecting.
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 10.0.11 --repo o/r --release never >/dev/null 2>&1
assert_eq "#953 publish-release: accepts a well-formed version (the validator is not vacuous)" "0" "$?"
assert_eq "#953 publish-release: --release rejects an unknown mode" "2" \
  "$(PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" PATH="$PRD/bin:$PATH" \
     "$PR953" --version 1.2.3 --repo o/r --release sometimes >/dev/null 2>&1; echo $?)"

# Arm 8: the remote-tag PROBE itself fails (unreachable remote / auth), which is NOT evidence
# the tag is absent. Folding that into "absent" would route a connectivity blip into the
# create-and-POST path and blame the mutation for a probe-time problem.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" PR953_LSREMOTE_ERRORS=1 DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: an ERRORED tag probe is not read as absent (exit 1)" "1" "$VP_RC"
assert_eq "#953 publish-release: the errored probe refuses to guess rather than creating a tag" "yes" \
  "$([ "$(grep -c 'git tag' "$PRD/log")" -eq 0 ] && [ "$(grep -c '^gh ' "$PRD/log")" -eq 0 ] && echo yes || echo no)"
assert_eq "#953 publish-release: the errored-probe diagnostic reports the probe's own status" "1" \
  "$(grep -cF 'git ls-remote exited 128' "$PRD/out")"

# Arm 9: the real production Release body — a --notes-file that EXISTS and is non-empty is
# uploaded as the body, not smoothed into the pointer fallback. Every other arm here takes the
# fallback, so without this one the actual shipped path is never exercised.
: > "$PRD/log"; : > "$PRD/state"
printf '## [9.9.9] - 2026-07-30\n\n### Fixed\n- A real assembled entry.\n' > "$PRD/notes.md"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --notes-file "$PRD/notes.md" \
  >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#953 publish-release: a non-empty notes file is uploaded as the Release body" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -cF "body=@$PRD/notes.md" "$PRD/log")" -eq 1 ] && echo yes || echo no)"
assert_eq "#953 publish-release: a real notes body never takes the CHANGELOG-pointer fallback" "0" \
  "$(grep -cF 'See CHANGELOG.md' "$PRD/log")"

# Arm 10: the two fallback CAUSES are distinct events and must not read as one. "No
# --notes-file was passed" is a caller choice; "--notes-file was named but is absent/empty"
# means the consolidator's --emit-entry-to side channel produced nothing — an upstream
# anomaly that must not hide behind a routine-looking warning.
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r >"$PRD/out" 2>&1
assert_eq "#953 publish-release: no --notes-file is a notice, not a warning (a caller choice)" "yes" \
  "$([ "$(grep -c '::notice::No --notes-file' "$PRD/out")" -eq 1 ] &&
    [ "$(grep -c '::warning::' "$PRD/out")" -eq 0 ] && echo yes || echo no)"
: > "$PRD/log"; : > "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --notes-file "$PRD/absent.md" \
  >"$PRD/out" 2>&1
assert_eq "#953 publish-release: a REQUESTED but empty/absent notes file warns as an upstream anomaly" "yes" \
  "$([ "$(grep -c '::warning::' "$PRD/out")" -eq 1 ] &&
    [ "$(grep -cF -- '--emit-entry-to' "$PRD/out")" -eq 1 ] && echo yes || echo no)"
assert_eq "#953 publish-release: both fallback causes still publish (notes never fail the job)" "1" \
  "$(grep -cF 'See CHANGELOG.md' "$PRD/log")"

# Arm 11: publishing needs a repository. Absent both --repo and GITHUB_REPOSITORY the helper
# dies (exit 2) rather than composing `repos//releases`.
: > "$PRD/log"; : > "$PRD/state"
assert_eq "#953 publish-release: no --repo and no GITHUB_REPOSITORY exits 2 before any gh call" "yes" \
  "$(PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" GITHUB_REPOSITORY='' DEVFLOW_GH="$PRD/bin/gh" \
     PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 >/dev/null 2>&1
     [ "$?" -eq 2 ] && [ "$(grep -c '^gh ' "$PRD/log")" -eq 0 ] && echo yes || echo no)"

# ── Arm 12: `--release minor-major`, the CONDITIONAL selection (issue #970). ─────────
# Publishing a Release emails every watcher subscribed to Releases, and a bump lands on
# every changeset-carrying merge, so only a minor/major bump is announced. The tag is
# unconditional in EVERY arm below — that is what keeps the pinned install URLs resolving
# and reproducibility unchanged; only the announcement is conditional.
#
# Driven as a MATRIX over one fixed command shape, so a condition that always took the same
# branch would fail here rather than pass vacuously: the arms must differ from each other.
for vp_bk in patch minor major; do
  : > "$PRD/log"; rm -f "$PRD/state"
  PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
    PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r \
    --release minor-major --bump "$vp_bk" >"$PRD/out" 2>&1; VP_RC=$?
  # Whatever the bump, the annotated tag is created and pushed — never conditional.
  assert_eq "#970 publish-release: a $vp_bk bump is still tagged and pushed (pins keep resolving)" "yes" \
    "$([ "$VP_RC" -eq 0 ] &&
       [ "$(grep -cF 'git tag -a v9.9.9' "$PRD/log")" -eq 1 ] &&
       [ "$(grep -cF 'git push origin refs/tags/v9.9.9' "$PRD/log")" -eq 1 ] && echo yes || echo no)"
  case "$vp_bk" in
    patch)
      assert_eq "#970 publish-release: a patch bump publishes NO Release (no gh call at all)" "0" \
        "$(grep -c '^gh ' "$PRD/log")"
      assert_eq "#970 publish-release: the patch arm says why it is quiet" "1" \
        "$(grep -c '::notice::patch bump' "$PRD/out")" ;;
    *)
      assert_eq "#970 publish-release: a $vp_bk bump DOES publish its Release" "1" \
        "$(grep -cF 'api --method POST repos/o/r/releases' "$PRD/log")"
      assert_eq "#970 publish-release: the $vp_bk arm names the bump kind it acted on" "1" \
        "$(grep -c "::notice::$vp_bk bump" "$PRD/out")" ;;
  esac
done

# Arm 12b: NEGATIVE CONTROL for the mode itself — the same `--bump patch` under the default
# `--release always` still publishes. Without this, a helper that had simply stopped
# publishing altogether would satisfy the patch arm above.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --bump patch >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#970 publish-release: --bump patch under the default mode still publishes (the mode is what decides)" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -cF 'api --method POST repos/o/r/releases' "$PRD/log")" -eq 1 ] &&
     echo yes || echo no)"

# Arm 13: UNKNOWN IS NOT PATCH. Under `minor-major` an unestablished bump kind (the
# consolidator's side channel produced nothing) must not be collapsed onto the quiet arm —
# that would silently suppress an announcement nobody chose to suppress. The tag is already
# pushed, so the helper fails loud and leaves a re-run able to publish idempotently.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --release minor-major >"$PRD/out" 2>&1; VP_RC=$?
assert_eq "#970 publish-release: an unestablished bump kind fails closed (exit 1), never silently as patch" "1" "$VP_RC"
assert_eq "#970 publish-release: it still tagged first, and published nothing" "yes" \
  "$([ "$(grep -cF 'git tag -a v9.9.9' "$PRD/log")" -eq 1 ] &&
     [ "$(grep -c '^gh ' "$PRD/log")" -eq 0 ] && echo yes || echo no)"
assert_eq "#970 publish-release: the diagnostic names the side channel to check" "1" \
  "$(grep -cF -- '--emit-bump-to' "$PRD/out")"
# An empty --bump under a mode that does not consult it is NOT a fault.
: > "$PRD/log"; rm -f "$PRD/state"
PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
  PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --release never >/dev/null 2>&1
assert_eq "#970 publish-release: an absent --bump is only a fault where the mode reads it" "0" "$?"

# Arm 14: input validation for the new operand — a MALFORMED --bump is a caller bug, so it is
# rejected before anything happens (distinct from the absent case above, which is an
# unestablished measurement handled after the tag exists).
for vp_bad in "PATCH" "patch " "1" "minor,major" "release"; do
  : > "$PRD/log"; : > "$PRD/state"
  PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" \
    PATH="$PRD/bin:$PATH" "$PR953" --version 9.9.9 --repo o/r --release minor-major \
    --bump "$vp_bad" >/dev/null 2>&1; VP_RC=$?
  assert_eq "#970 publish-release: rejects the malformed bump '$vp_bad' (exit 2, no git call)" "yes" \
    "$([ "$VP_RC" -eq 2 ] && [ ! -s "$PRD/log" ] && echo yes || echo no)"
done
assert_eq "#970 publish-release: --release still rejects an unknown mode now that a third exists" "2" \
  "$(PR953_LOG="$PRD/log" PR953_STATE="$PRD/state" DEVFLOW_GH="$PRD/bin/gh" PATH="$PRD/bin:$PATH" \
     "$PR953" --version 1.2.3 --repo o/r --release minor >/dev/null 2>&1; echo $?)"
rm -rf "$PRD"

# ── Workflow wiring: the coupled sites this suite cannot reach by execution. ─────────
# Read the workflow into a variable and assert against THAT (the same idiom the #671
# staging-list block uses), so each assertion is about the extracted content rather than a
# source-presence grep over a shipped file.
VP_WF="$(cat "$CS_WF")"
# Without this call the helper's every arm is tested above and none of them ever runs: the
# workflow is its sole caller.
assert_eq "#953 workflow invokes the extracted tag/Release helper" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'scripts/publish-release.sh')"
# The pin-rewrite set is derived, so it cannot be enumerated in the staging list; it can only
# be staged from the consolidator's own write-set file. Without it the docs repin is discarded
# by the next `git reset --hard` and the tagged tree ships stale install commands.
assert_eq "#953 workflow asks the consolidator for its write set" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF -- '--emit-write-set-to')"
assert_eq "#953 workflow stages every path in that write set" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'git add -- "$staged_path"')"
# The fail-closed backstop over any consolidator write neither staging list reached.
assert_eq "#953 workflow fails closed on a consolidator write that was not staged" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'the consolidator wrote files that were not staged')"
# The tag/Release step must be gated on the push having happened, or a no-pending-changesets
# run would tag whatever main already points at.
assert_eq "#953 workflow gates the tag step on the bump having been pushed" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF "steps.consolidate.outputs.pushed == 'true'")"
# #970: the conditional-Release wiring. Three coupled halves, none of which the arms above
# can reach by execution — the helper's `minor-major` selection is inert unless the workflow
# actually selects that mode AND actually feeds it the consolidator's own bump kind. Asking
# the consolidator is what makes this the COMPUTED highest pending bump rather than something
# re-inferred downstream from a version diff.
assert_eq "#970 workflow asks the consolidator for the highest pending bump kind" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF -- '--emit-bump-to "$BUMP_KIND_FILE"')"
assert_eq "#970 workflow selects the conditional-Release mode and feeds it that bump kind" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF -- '--release minor-major --bump "$BUMP_KIND"')"
assert_eq "#970 workflow relays the bump kind to the tag step through a step output" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'BUMP_KIND: ${{ steps.consolidate.outputs.bump }}')"
# The relay's producer half: an output the consolidate step never writes reads as empty, and
# the helper then fails closed. Read with the `read` BUILTIN — a value that decides an emitted
# result must not be derived through a non-preflight PATH tool (never `cat`/`head`).
assert_eq "#970 workflow reads that side channel with a bash builtin, never a PATH tool" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'read -r bump_kind < "$BUMP_KIND_FILE"')"
assert_eq "#970 workflow publishes the bump kind as a step output" "1" \
  "$(printf '%s\n' "$VP_WF" | grep -cF 'echo "bump=$bump_kind"')"

# ── The consolidate step's own shell, EXTRACTED from the YAML and DRIVEN. ────────────
# The tag version must be derived on its own assignment statement, BEFORE the push. Inside
# a `{ echo "version=$(…)"; } >> "$GITHUB_OUTPUT"` group a command substitution's failure is
# invisible to `set -e` — the `echo` succeeds — so a broken --print-version emitted
# `pushed=true` with an EMPTY version, the gated tag step then ran with an empty
# BUMP_VERSION, publish-release.sh died, and the run ended with the bump pushed to main and
# NO tag: the "docs pin a tag that does not exist" drift this whole workflow exists to
# prevent, reached through a swallowed error. A grep for the shape cannot catch a
# reintroduction; running the step can.
VP_WFD="$(mktemp -d)"; mkdir -p "$VP_WFD/bin" "$VP_WFD/tmp"
python3 -c "
import sys, yaml
wf = yaml.safe_load(open(sys.argv[1]))
run = next(s['run'] for s in wf['jobs']['consolidate']['steps'] if s.get('id') == 'consolidate')
open(sys.argv[2], 'w').write(run)
" "$CS_WF" "$VP_WFD/consolidate.sh"
assert_eq "#953 workflow drive: the consolidate step's shell is extractable" "yes" \
  "$([ -s "$VP_WFD/consolidate.sh" ] && echo yes || echo no)"
cat > "$VP_WFD/bin/git" <<'VPWFGIT'
#!/usr/bin/env bash
printf '%s\n' "git $*" >> "$VPWF_LOG"
case "$1 $2" in
  "status --porcelain") printf ' M CHANGELOG.md\n'; exit 0 ;;  # always dirty: a bump happened
  "diff --name-only")   exit 0 ;;                              # nothing unstaged: backstop clean
esac
exit 0
VPWFGIT
cat > "$VP_WFD/bin/python3" <<'VPWFPY'
#!/usr/bin/env bash
printf '%s\n' "python3 $*" >> "$VPWF_LOG"
case "$*" in
  *consolidate-changesets.py*)
    prev=""
    for a in "$@"; do
      case "$prev" in
        --emit-entry-to)     printf 'notes body\n' > "$a" ;;
        --emit-write-set-to) printf 'CHANGELOG.md\n' > "$a" ;;
        # The #970 bump-kind side channel. VPWF_NO_BUMP=1 makes the stub write
        # NOTHING here, reproducing the real consolidator's own no-op-ish shapes
        # (an older consolidator that does not know the flag, or a write that
        # failed) — the case the workflow must relay as an EMPTY bump, never a
        # defaulted one.
        --emit-bump-to)      [ "${VPWF_NO_BUMP:-0}" = "1" ] || printf '%s\n' "${VPWF_BUMP-minor}" > "$a" ;;
      esac
      prev="$a"
    done
    exit 0 ;;
  *version_pins.py*--print-version*)
    [ "${VPWF_PV_FAILS:-0}" = "1" ] && exit 3
    printf '%s\n' "${VPWF_PV_OUT-7.7.7}"
    exit 0 ;;
esac
exit 0
VPWFPY
chmod +x "$VP_WFD/bin/git" "$VP_WFD/bin/python3"

# Arm A (happy path): the bump is pushed and BOTH outputs are populated.
: > "$VP_WFD/log"; : > "$VP_WFD/out"
VPWF_LOG="$VP_WFD/log" RUNNER_TEMP="$VP_WFD/tmp" GITHUB_OUTPUT="$VP_WFD/out" \
  PATH="$VP_WFD/bin:$PATH" bash "$VP_WFD/consolidate.sh" >/dev/null 2>&1; VP_RC=$?
assert_eq "#953 workflow drive: the happy path exits 0 and reports pushed=true" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -cx 'pushed=true' "$VP_WFD/out")" -eq 1 ] && echo yes || echo no)"
assert_eq "#953 workflow drive: the happy path publishes the derived version, not an empty one" "1" \
  "$(grep -cx 'version=7.7.7' "$VP_WFD/out")"
# #970 PRODUCER HALF, driven rather than grep-pinned. The consumer half (the helper's
# minor-major arm) is exercised above; this is the relay that feeds it. Until this arm
# existed the `read -r bump_kind < "$BUMP_KIND_FILE"` branch ran ZERO times in the suite
# and nothing checked the emitted `bump=` line, so a regression that dropped the
# --emit-bump-to flag, read the wrong file, stopped writing the `bump=` output, or
# defaulted the value would pass every grep pin it did not touch.
# TWO DECLARED RESIDUALS these arms do NOT cover, stated rather than implied:
#   * dropping the `-s` guard is behaviour-inert — the `|| true` already absorbs the
#     failed redirect and leaves bump_kind empty, so `bump=` is empty either way;
#   * switching the builtin to `cat` is indistinguishable while `cat` is on PATH. That
#     half stays the source-shape pin above ("reads that side channel with a bash
#     builtin"); the execution arms only diverge on a host where `cat` is missing.
assert_eq "#970 workflow drive: the happy path relays the consolidator's own bump kind" "1" \
  "$(grep -cx 'bump=minor' "$VP_WFD/out")"
# The ordering that makes the fault survivable: derive BEFORE the irreversible push.
assert_eq "#953 workflow drive: --print-version is called before the push, not after it" "yes" \
  "$([ "$(grep -n -- '--print-version' "$VP_WFD/log" | head -1 | cut -d: -f1)" \
      -lt "$(grep -n 'git push origin HEAD:main' "$VP_WFD/log" | head -1 | cut -d: -f1)" ] &&
    echo yes || echo no)"

# Arm B (the regression): --print-version FAILS. The step must go red with nothing pushed —
# never `pushed=true` with an empty version.
: > "$VP_WFD/log"; : > "$VP_WFD/out"
VPWF_LOG="$VP_WFD/log" VPWF_PV_FAILS=1 RUNNER_TEMP="$VP_WFD/tmp" GITHUB_OUTPUT="$VP_WFD/out" \
  PATH="$VP_WFD/bin:$PATH" bash "$VP_WFD/consolidate.sh" >/dev/null 2>&1; VP_RC=$?
assert_eq "#953 workflow drive: a failing --print-version fails the step (never swallowed)" "yes" \
  "$([ "$VP_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#953 workflow drive: a failing --print-version pushes NOTHING (no untagged bump)" "0" \
  "$(grep -c 'git push origin HEAD:main' "$VP_WFD/log")"
assert_eq "#953 workflow drive: a failing --print-version emits no pushed=true output" "0" \
  "$(grep -cx 'pushed=true' "$VP_WFD/out")"

# Arm C: an exit-0-but-empty --print-version is the same hazard by another route, and the
# explicit non-empty guard catches it.
: > "$VP_WFD/log"; : > "$VP_WFD/out"
VPWF_LOG="$VP_WFD/log" VPWF_PV_OUT="" RUNNER_TEMP="$VP_WFD/tmp" GITHUB_OUTPUT="$VP_WFD/out" \
  PATH="$VP_WFD/bin:$PATH" bash "$VP_WFD/consolidate.sh" >"$VP_WFD/stepout" 2>&1; VP_RC=$?
assert_eq "#953 workflow drive: an EMPTY derived version fails the step and pushes nothing" "yes" \
  "$([ "$VP_RC" -ne 0 ] && [ "$(grep -c 'git push origin HEAD:main' "$VP_WFD/log")" -eq 0 ] &&
    [ "$(grep -cx 'pushed=true' "$VP_WFD/out")" -eq 0 ] && echo yes || echo no)"
assert_eq "#953 workflow drive: the empty-version error names the untaggable bump it refused" "1" \
  "$(grep -c 'refusing to push an untaggable bump' "$VP_WFD/stepout")"

# Arm D (#970): the bump side channel is ABSENT — the consolidator wrote no bump file at
# all. The step must still push (an absent side channel is not a reason to withhold the
# version bump) and must emit `bump=` EMPTY, so publish-release.sh fails loud on an
# undecidable release rather than silently suppressing — or silently publishing — an
# announcement. A default here would be the worst outcome: `patch` would suppress a real
# minor Release, `minor` would email every watcher on every patch merge.
: > "$VP_WFD/log"; : > "$VP_WFD/out"
VPWF_LOG="$VP_WFD/log" VPWF_NO_BUMP=1 RUNNER_TEMP="$VP_WFD/tmp" GITHUB_OUTPUT="$VP_WFD/out" \
  PATH="$VP_WFD/bin:$PATH" bash "$VP_WFD/consolidate.sh" >/dev/null 2>&1; VP_RC=$?
# NON-VACUITY FIRST: without this the two assertions below would both hold on a step that
# aborted before ever reaching the output block — passing by inspecting nothing.
assert_eq "#970 workflow drive: an absent bump side channel still pushes the bump (arm reached the output block)" "yes" \
  "$([ "$VP_RC" -eq 0 ] && [ "$(grep -cx 'pushed=true' "$VP_WFD/out")" -eq 1 ] && echo yes || echo no)"
assert_eq "#970 workflow drive: an absent bump side channel emits bump= EMPTY, never a default" "1" \
  "$(grep -cx 'bump=' "$VP_WFD/out")"
assert_eq "#970 workflow drive: an absent bump side channel emits no non-empty bump= line" "0" \
  "$(grep -cE '^bump=.+$' "$VP_WFD/out")"
rm -rf "$VP_WFD"

# ────────────────────────────────────────────────────────────────────────────
echo "#181 review-engine Phase 0.2 .prflow/logs/** diff-hunk filter"
# ────────────────────────────────────────────────────────────────────────────
# Phase 0.2 of skills/review/SKILL.md strips .prflow/logs/** hunks from the
# cached diff.patch (intentional DevFlow telemetry commits, not code-review
# subjects) BEFORE any Phase 1/2/3 agent sees the diff. The filter is an inline
# awk stage in the existing `… | tee diff.patch` pipeline (it rides the
# allowlisted `gh pr diff`/`git diff` leading token, so the read-only `review`
# profile permits it without a workflow allowlist change — no standalone `mv`).
#
# These assertions EXTRACT the actual awk program from the SKILL and run it
# against synthetic-diff fixtures, so they go RED if the SKILL's filter is
# missing or wrong (not a vacuous re-implementation). The contract pin below
# couples the SKILL text to that behavior.
F181_AWK="$(grep -oE "awk '[^']+'" "$REVIEW_SKILL" 2>/dev/null | grep -F 'in_logs' | head -1 | sed "s/^awk '//; s/'$//")"
# Precondition (RED until the filter is added): the awk program must be
# extractable from the SKILL. Guards every behavioral assertion below against an
# empty-program (`awk ''`) vacuous pass.
assert_eq "#181 filter: awk log-hunk filter program is present/extractable in review/SKILL.md Phase 0.2" \
  "yes" "$([ -n "$F181_AWK" ] && echo yes || echo no)"

# Fixture: a real code hunk, a telemetry-log hunk, then another code hunk.
F181_MIXED="$(printf '%s\n' \
  'diff --git a/src/a.py b/src/a.py' \
  'index 1111111..2222222 100644' \
  '--- a/src/a.py' \
  '+++ b/src/a.py' \
  '@@ -1 +1 @@' \
  '-old a' \
  '+new a' \
  'diff --git a/.prflow/logs/efficiency/pr-1.json b/.prflow/logs/efficiency/pr-1.json' \
  'index 3333333..4444444 100644' \
  '--- a/.prflow/logs/efficiency/pr-1.json' \
  '+++ b/.prflow/logs/efficiency/pr-1.json' \
  '@@ -1 +1 @@' \
  '-{"old":1}' \
  '+{"new":1}' \
  'diff --git a/src/b.py b/src/b.py' \
  'index 5555555..6666666 100644' \
  '--- a/src/b.py' \
  '+++ b/src/b.py' \
  '@@ -1 +1 @@' \
  '-old b' \
  '+new b')"
F181_MIXED_OUT="$(printf '%s\n' "$F181_MIXED" | awk "${F181_AWK:-NONEXTRACTED}" 2>/dev/null)"
# AC-2: the telemetry hunk is gone…
assert_eq "#181 filter: mixed diff drops the .prflow/logs/ hunk" \
  "absent" "$(case "$F181_MIXED_OUT" in *'.prflow/logs/'*) echo present;; *) echo absent;; esac)"
# …and BOTH real code hunks survive, in their original order (a before b).
assert_eq "#181 filter: mixed diff retains both real code hunks in original order" \
  "diff --git a/src/a.py b/src/a.py|diff --git a/src/b.py b/src/b.py" \
  "$(printf '%s\n' "$F181_MIXED_OUT" | grep '^diff --git' | paste -sd'|' -)"

# Fixture: a single logs file carrying TWO @@ hunks (the realistic accreting-telemetry shape),
# followed by a real code hunk (#209 review hardening). The filter's stickiness rides the
# `diff --git` header, NOT the @@ line, so EVERY hunk of a logs file is suppressed. A regression
# that reset in_logs per @@ (instead of per diff --git header) would leak the SECOND hunk's
# content while still passing every single-hunk fixture above — this fixture is the regression catch.
F181_MULTIHUNK="$(printf '%s\n' \
  'diff --git a/.prflow/logs/review/pr-1/run-1/iter-1.json b/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  'index 1111111..2222222 100644' \
  '--- a/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  '+++ b/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  '@@ -1,1 +1,1 @@' \
  '-{"LOGHUNKONE_old":1}' \
  '+{"LOGHUNKONE_new":1}' \
  '@@ -10,1 +10,1 @@' \
  '-{"LOGHUNKTWO_old":2}' \
  '+{"LOGHUNKTWO_new":2}' \
  'diff --git a/src/c.py b/src/c.py' \
  'index 5555555..6666666 100644' \
  '--- a/src/c.py' \
  '+++ b/src/c.py' \
  '@@ -1 +1 @@' \
  '-old c' \
  '+new c')"
F181_MULTIHUNK_OUT="$(printf '%s\n' "$F181_MULTIHUNK" | awk "${F181_AWK:-NONEXTRACTED}" 2>/dev/null)"
# The discriminating assertion: the SECOND logs hunk is dropped too (in_logs sticks across @@).
assert_eq "#181 filter: a logs file's SECOND @@ hunk is also dropped (in_logs sticks across hunks)" \
  "absent" "$(case "$F181_MULTIHUNK_OUT" in *LOGHUNKTWO*) echo present;; *) echo absent;; esac)"
# …and the trailing real code hunk after the multi-hunk logs file still survives intact.
assert_eq "#181 filter: real code hunk after a multi-hunk logs file survives" \
  "diff --git a/src/c.py b/src/c.py" \
  "$(printf '%s\n' "$F181_MULTIHUNK_OUT" | grep '^diff --git' | paste -sd'|' -)"

# Fixture: ONLY a telemetry-log hunk.
F181_LOGS_ONLY="$(printf '%s\n' \
  'diff --git a/.prflow/logs/review/pr-1/run-1/iter-1.json b/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  'index 7777777..8888888 100644' \
  '--- a/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  '+++ b/.prflow/logs/review/pr-1/run-1/iter-1.json' \
  '@@ -1 +1 @@' \
  '-{"a":1}' \
  '+{"a":2}')"
F181_LOGS_OUT="$(printf '%s\n' "$F181_LOGS_ONLY" | awk "${F181_AWK:-NONEXTRACTED}" 2>/dev/null)"
# AC-3: a logs-only diff filters to no `diff --git` headers (empty effective diff).
# Non-vacuous as a pair with the mixed test above (which proves the filter passes
# code hunks through rather than deleting everything).
assert_eq "#181 filter: logs-only diff yields no diff --git headers (empty effective diff)" \
  "0" "$(printf '%s\n' "$F181_LOGS_OUT" | grep -c '^diff --git')"

# Fixture: the FIRST hunk is a logs hunk (flag-initialization edge), and the
# surviving code hunk's body embeds the literal '.prflow/logs/' on a content
# line (the false-positive-immunity edge — the filter keys ONLY on `^diff --git`
# headers, so a source line mentioning the path must NOT be eaten). This pins the
# exact regression a careless future edit would introduce (dropping the
# `/^diff --git/` guard so `in_logs` recomputes per line).
F181_EDGE="$(printf '%s\n' \
  'diff --git a/.prflow/logs/efficiency/pr-2.json b/.prflow/logs/efficiency/pr-2.json' \
  'index aaaaaaa..bbbbbbb 100644' \
  '--- a/.prflow/logs/efficiency/pr-2.json' \
  '+++ b/.prflow/logs/efficiency/pr-2.json' \
  '@@ -1 +1 @@' \
  '-{"x":1}' \
  '+{"x":2}' \
  'diff --git a/src/c.py b/src/c.py' \
  'index ccccccc..ddddddd 100644' \
  '--- a/src/c.py' \
  '+++ b/src/c.py' \
  '@@ -1 +1,2 @@' \
  ' LOG_DIR = ".prflow/logs/efficiency"' \
  '+print(".prflow/logs/ mentioned in source")')"
F181_EDGE_OUT="$(printf '%s\n' "$F181_EDGE" | awk "${F181_AWK:-NONEXTRACTED}" 2>/dev/null)"
# Gap A: a leading logs hunk is dropped; only the code header survives.
assert_eq "#181 filter: leading logs hunk dropped, trailing code hunk survives" \
  "diff --git a/src/c.py b/src/c.py" \
  "$(printf '%s\n' "$F181_EDGE_OUT" | grep '^diff --git' | paste -sd'|' -)"
# Gap B (false-positive immunity): a source CONTENT line embedding '.prflow/logs/'
# is NOT filtered — the filter toggles only on `^diff --git` headers.
assert_eq "#181 filter: a code line embedding '.prflow/logs/' is retained, not eaten" \
  "yes" "$(case "$F181_EDGE_OUT" in *'print(".prflow/logs/ mentioned in source")'*) echo yes;; *) echo no;; esac)"

# AC-1 anchoring: the regex is anchored to the a//b/ diff-prefix boundary, so it
# strips only paths that START WITH .prflow/logs/ (AC #1's exact wording), never a
# non-root path that merely contains that substring (a test fixture or a dir named
# *.prflow/logs/). Both header paths below must SURVIVE — a regression to an
# unanchored /\.prflow\/logs\// would drop them and hide real code from review.
F181_NESTED="$(printf '%s\n' \
  'diff --git a/tests/fixtures/.prflow/logs/sample.json b/tests/fixtures/.prflow/logs/sample.json' \
  '@@ -1 +1 @@' \
  '+{"fixture":1}' \
  'diff --git a/src/foo.prflow/logs/bar.py b/src/foo.prflow/logs/bar.py' \
  '@@ -1 +1 @@' \
  '+code')"
F181_NESTED_OUT="$(printf '%s\n' "$F181_NESTED" | awk "${F181_AWK:-NONEXTRACTED}" 2>/dev/null)"
assert_eq "#181 filter: non-root paths containing '.prflow/logs/' are NOT stripped (anchored to 'starts with')" \
  "diff --git a/tests/fixtures/.prflow/logs/sample.json b/tests/fixtures/.prflow/logs/sample.json|diff --git a/src/foo.prflow/logs/bar.py b/src/foo.prflow/logs/bar.py" \
  "$(printf '%s\n' "$F181_NESTED_OUT" | grep '^diff --git' | paste -sd'|' -)"

# AC-1 / peer-completeness (2.3.0a): the awk filter is present in EVERY diff-source
# variant of the Phase 0.2 tee pipeline (PR mode, current-branch mode, and the
# head_override=local fix-loop variant) — three occurrences, one per variant.
assert_eq "#181 filter: awk log-hunk filter present in all three Phase 0.2 diff-source variants" \
  "3" "$(pin_count '{in_logs=/ [ab]\/\.prflow\/logs\//} !in_logs' "$REVIEW_SKILL")"

# ────────────────────────────────────────────────────────────────────────────
echo "issue #222: .gitattributes eol=lf + UTF-8 stream self-defense"
# ────────────────────────────────────────────────────────────────────────────
# The helper toolchain must self-defend on Windows / non-UTF-8 hosts: LF line
# endings forced by .gitattributes (so a shebang never becomes `bash\r`) and
# scripts/*.py forcing their own streams + gh I/O to UTF-8 (so emoji/em-dashes
# never trip cp1252). These assert the .gitattributes contract, the no-CR-in-.sh
# index invariant, and the cp1252 RED->GREEN behavior by SUBPROCESS (the harness
# imports the modules in-process, so the entry-path reconfigure is only
# observable when the script is RUN as a CLI — test_python_scripts.py proves the
# complementary import-no-side-effect half).
U8_ROOT="$LIB/.."
U8_SCRIPTS="$U8_ROOT/scripts"

# AC1: .gitattributes exists and `git check-attr eol` resolves to `lf` for a
# sample *.sh, *.py, and *.jq file.
assert_eq "#222: .gitattributes exists at repo root" "yes" \
  "$( [ -f "$U8_ROOT/.gitattributes" ] && echo yes || echo no )"
for _u8f in scripts/config-get.sh scripts/workpad.py lib/classify-pr-kind.jq; do
  assert_eq "#222: git check-attr eol=lf for $_u8f" "lf" \
    "$(git -C "$U8_ROOT" check-attr eol -- "$_u8f" | sed -E 's/.*: eol: //')"
done

# AC2: no tracked *.sh file carries a CR byte in the index (i/lf for every entry).
# `git ls-files --eol` prints `i/<index-eol> w/<worktree-eol> attr/<attr> <path>`;
# a crlf/mixed in the i/ column is a defect. grep -c prints 0 + exits 1 on no
# match, so `|| true` keeps the clean `0`.
assert_eq "#222: no tracked *.sh has crlf/mixed line endings in the index" "0" \
  "$(git -C "$U8_ROOT" ls-files --eol -- '*.sh' | grep -cE 'i/(crlf|mixed)' || true)"

# AC3/AC5: workpad.py new-body is a pure offline formatter whose default --branch
# carries an ellipsis and whose Status carries the rocket glyph, so non-ASCII
# fires with no flags. Under PYTHONIOENCODING=cp1252 today's UNHARDENED code
# raises UnicodeEncodeError (the reported defect); the hardened code exits 0 with
# valid UTF-8 and NO BOM (closing the UTF-16LE-corruption root).
U8_NB="$(mktemp)"
PYTHONIOENCODING=cp1252 python3 "$U8_SCRIPTS/workpad.py" new-body 1 > "$U8_NB" 2>/dev/null
U8_NB_RC=$?
assert_eq "#222 RED->GREEN: workpad.py new-body exits 0 under cp1252" "0" "$U8_NB_RC"
assert_eq "#222: new-body output contains the UTF-8 rocket glyph (did not crash)" "yes" \
  "$(grep -qF '🚀' "$U8_NB" && echo yes || echo no)"
assert_eq "#222: new-body output carries no BOM (UTF-8-no-BOM, not UTF-16LE)" "yes" \
  "$(head -c3 "$U8_NB" | od -An -tx1 | tr -d ' \n' | grep -qE '^(efbbbf|fffe|feff)' && echo no || echo yes)"
rm -f "$U8_NB"

# parse-acs.py emits non-ASCII only as the em-dash in its near-miss breadcrumb
# (a trailing-colon heading triggers it). NOTE: em-dash (U+2014) and ellipsis
# (U+2026) ARE encodable in cp1252 (0x97 / 0x85), so a cp1252 test of em-dash
# content is VACUOUS — it passes even against the unhardened code. The strictly-
# non-UTF-8 codec under which this content genuinely raises without the fix (a
# real RED->GREEN) is `ascii` (em-dash is outside both ascii and latin-1). The
# reconfigure overrides PYTHONIOENCODING, so the hardened script exits 0.
U8_PAB="$(mktemp)"; printf '## Acceptance Criteria:\n- [ ] x\n' > "$U8_PAB"
U8_PAE="$(mktemp)"
PYTHONIOENCODING=ascii python3 "$U8_SCRIPTS/parse-acs.py" --body-file "$U8_PAB" >/dev/null 2>"$U8_PAE"
U8_PA_RC=$?
assert_eq "#222 RED->GREEN: parse-acs.py exits 0 emitting its em-dash breadcrumb under ascii" "0" "$U8_PA_RC"
assert_eq "#222: parse-acs.py emits the em-dash breadcrumb as UTF-8 (did not crash)" "yes" \
  "$(grep -qF '—' "$U8_PAE" && echo yes || echo no)"
rm -f "$U8_PAB" "$U8_PAE"

# AC7 (write-side encode): file-deferrals.py --dry-run writes the issue TITLE and
# a body preview to stderr. We inject a ROCKET (U+1F680, outside cp1252) into the
# manifest `file` so it lands in the derived title. The RED->GREEN discriminates
# on emitted CONTENT, not on a crash: stderr defaults to the backslashreplace
# error handler, so the unhardened code does NOT raise under cp1252 — it exits 0
# but renders the escaped `\U0001f680` instead of the rocket, so the rocket-present
# assertion below fails RED. The hardened stream-forcing emits the real UTF-8
# rocket (GREEN). (Do NOT "simplify" this to an exit-code/crash check — both the
# hardened and unhardened paths exit 0, so a crash check would be vacuous.) The
# em-dash case would be doubly vacuous (em-dash is cp1252-encodable AND stderr
# never raises), which is why the rocket + content-assert is used here.
U8_MAN="$(mktemp)"
cat > "$U8_MAN" <<'JSON'
{"schema_version": 1, "deferrals": [
  {"file": "src/🚀mod.py", "symbol": "fn", "kind": "perf", "summary": "loop",
   "severity": "Medium", "agent": "a", "category": "scope", "explanation": "deferred"}
]}
JSON
PYTHONIOENCODING=cp1252 python3 "$U8_SCRIPTS/file-deferrals.py" \
  --source-issue 1 --pr 2 --manifest "$U8_MAN" --dry-run >/dev/null 2>"$U8_MAN.err"
U8_FD_RC=$?
assert_eq "#222 RED->GREEN: file-deferrals.py --dry-run exits 0 under cp1252 (write-side encode)" "0" "$U8_FD_RC"
assert_eq "#222: file-deferrals.py --dry-run emits its rocket-bearing title as UTF-8" "yes" \
  "$(grep -qF '🚀' "$U8_MAN.err" && echo yes || echo no)"
rm -f "$U8_MAN" "$U8_MAN.err"

# AC6/AC7 (gh decode + temp-file/stdin encode): these are pinned STATICALLY, not
# by a runtime crash, on purpose. On Linux, CPython's UTF-8 Mode (PEP 540) coerces
# the C/POSIX locale to UTF-8, so a subprocess `text=True` DECODE never raises
# here — the UnicodeDecodeError is genuinely Windows-only (cp1252 ANSI codepage,
# no UTF-8-mode coercion). The portable, deterministic guarantee is that the code
# PINS `encoding="utf-8"` at every gh-I/O and temp-file site, so the codec is
# UTF-8 regardless of the host locale. These static checks provide the portable coverage
# that a Linux-only runtime test cannot.
assert_eq "#222 AC6: workpad.py _run gh wrapper pins encoding=utf-8 (gh decode/encode)" "yes" \
  "$(grep -qF 'stderr=subprocess.PIPE, encoding="utf-8",' "$U8_SCRIPTS/workpad.py" && echo yes || echo no)"
assert_eq "#222 AC7: workpad.py NamedTemporaryFile body write pins encoding=utf-8" "yes" \
  "$(grep -qF "'w', suffix='.md', delete=False, encoding=\"utf-8\"," "$U8_SCRIPTS/workpad.py" && echo yes || echo no)"
assert_eq "#222 AC6: file-deferrals.py _run gh wrapper pins encoding=utf-8" "yes" \
  "$(grep -qF 'stdout=subprocess.PIPE, stderr=subprocess.PIPE, encoding="utf-8",' "$U8_SCRIPTS/file-deferrals.py" && echo yes || echo no)"
assert_eq "#222 AC7: file-deferrals.py gh issue create pins input encoding=utf-8" "yes" \
  "$(grep -qF 'input=body, check=False, encoding="utf-8",' "$U8_SCRIPTS/file-deferrals.py" && echo yes || echo no)"
assert_eq "#222 AC6: parse-acs.py _fetch_body pins gh decode encoding=utf-8" "yes" \
  "$(grep -qF 'check=True, capture_output=True, encoding="utf-8",' "$U8_SCRIPTS/parse-acs.py" && echo yes || echo no)"
# match-deferrals.py's _run also reads gh PR/issue *bodies* (routinely non-ASCII),
# so its decode is pinned too — closing the same Windows decode-crash path.
assert_eq "#222 AC6: match-deferrals.py _run pins gh body-decode encoding=utf-8" "yes" \
  "$(grep -qF 'stdout=subprocess.PIPE, stderr=subprocess.PIPE, encoding="utf-8",' "$U8_SCRIPTS/match-deferrals.py" && echo yes || echo no)"

# Smoke (not RED->GREEN): a gh stub returns a comment body containing a rocket;
# workpad.py id must still decode it and print the matched id. On the Linux runner
# this passes with or without the pin (UTF-8 Mode), so it is a round-trip smoke
# test that the non-ASCII body doesn't break id resolution — NOT the AC6 proof
# (that is the static pin above).
U8_GHD="$(mktemp -d)"
cat > "$U8_GHD/gh" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *"repo view"*) echo "acme/example-repo" ;;
  *"comments"*) printf '%s\n' '[{"id":42,"body":"<!-- devflow:workpad --> 🚀 status"}]' ;;
  *) echo '[]' ;;
esac
STUB
chmod +x "$U8_GHD/gh"
U8_ID_OUT="$(PATH="$U8_GHD:$PATH" python3 "$U8_SCRIPTS/workpad.py" id 1 2>/dev/null)"
assert_eq "#222 smoke: workpad.py id resolves a comment with a non-ASCII body" "42" "$U8_ID_OUT"
rm -rf "$U8_GHD"

# ────────────────────────────────────────────────────────────────────────────
echo "issue #1762: previously-unhardened commands force UTF-8 on their entry path"
# ────────────────────────────────────────────────────────────────────────────
# The stream-forcing sweep hardened every tracked scripts/*.py and lib/*.py COMMAND
# (test_python_scripts.py's derived guard proves the whole population). These three
# name the exact commands the issue calls out: each printed non-ASCII output and
# CRASHED with an unhandled UnicodeEncodeError under a non-UTF-8 codec before the
# sweep (RED), and now exits 0 with the non-ASCII content intact (GREEN). `ascii` is
# the discriminating codec — em-dash (U+2014) and section-sign (U+00A7) are
# cp1252/latin-1-encodable, so a cp1252 test of them would be vacuous.
U8W_RA="$(mktemp)"
PYTHONIOENCODING=ascii python3 "$U8_SCRIPTS/render-audit-prompt.py" checklist > "$U8W_RA" 2>/dev/null
U8W_RA_RC=$?
assert_eq "#1762 RED->GREEN: render-audit-prompt.py checklist exits 0 under ascii" "0" "$U8W_RA_RC"
assert_eq "#1762: render-audit-prompt.py checklist emits its em-dash as UTF-8 (did not crash)" "yes" \
  "$(grep -qF '—' "$U8W_RA" && echo yes || echo no)"
rm -f "$U8W_RA"

U8W_PF="$(mktemp)"
PYTHONIOENCODING=ascii python3 "$U8_SCRIPTS/preflight.py" --help > "$U8W_PF" 2>/dev/null
U8W_PF_RC=$?
assert_eq "#1762 RED->GREEN: preflight.py --help exits 0 under ascii" "0" "$U8W_PF_RC"
assert_eq "#1762: preflight.py --help emits its non-ASCII help text as UTF-8" "yes" \
  "$(grep -qF '§' "$U8W_PF" && echo yes || echo no)"
rm -f "$U8W_PF"

U8W_CE="$(mktemp)"
PYTHONIOENCODING=ascii python3 "$U8_SCRIPTS/check-completion-evidence.py" --help > "$U8W_CE" 2>/dev/null
U8W_CE_RC=$?
assert_eq "#1762 RED->GREEN: check-completion-evidence.py --help exits 0 under ascii" "0" "$U8W_CE_RC"
assert_eq "#1762: check-completion-evidence.py --help emits its em-dash as UTF-8" "yes" \
  "$(grep -qF '—' "$U8W_CE" && echo yes || echo no)"
rm -f "$U8W_CE"

# ────────────────────────────────────────────────────────────────────────────
echo "issue #1678: explicit UTF-8 decoding on local text-file readers (hostile file codec)"
# parse-acs.py --body-file, workpad.py::_read_section_file, and
# branch-for-issue.py --title-file decode local files as UTF-8 EXPLICITLY (never
# the ambient locale codec), so non-ASCII issue text survives on Windows and a
# decode failure routes through the parser, workpad, and branch-create clean
# non-zero paths (no traceback).
# AC5 (the static AST guard over ALL tracked scripts/*.py) lives in
# test_python_scripts.py; these are the hostile-codec RED->GREEN CLI and
# mutation-boundary tests — only observable when the scripts run as CLIs under a
# forced-ASCII FILE codec. PYTHONCOERCECLOCALE=0/PYTHONUTF8=0/LC_ALL=C/LANG=C
# makes locale.getpreferredencoding(False) == ASCII (the codec read_text()/open()
# use with no encoding=), reproducing the Windows/cp1252 threat model. A vacuity
# self-check (mirrors the #423 T6b guard) skips VISIBLY when a host (some
# macOS/Homebrew builds) does not reproduce the strict-ASCII file codec, so a
# trivially-green host is observable, never a silent pass.
U8D_ENC="$( env PYTHONCOERCECLOCALE=0 PYTHONUTF8=0 LC_ALL=C LANG=C python3 -c 'import locale,sys; sys.stdout.write((locale.getpreferredencoding(False) or "").lower())' 2>/dev/null )"
case "$U8D_ENC" in
  ascii|us-ascii|ansi_x3.4-1968|646)
    # AC1 — parse-acs.py --body-file preserves an em-dash+emoji AC and Test Plan
    # item (RED on baseline: the ambient-ASCII read_text() raises → empty output).
    U8D_BODY="$(mktemp)"
    printf '## Acceptance Criteria\n\n- [ ] Models/CompanySettings.cs \xe2\x80\x94 preserve \xf0\x9f\x9a\x80\n\n## Test Plan\n\n- [ ] Verify Models/CompanySettings.cs \xe2\x80\x94 preserve \xf0\x9f\x9a\x80\n' > "$U8D_BODY"
    U8D_OUT="$(mktemp)"
    env PYTHONCOERCECLOCALE=0 PYTHONUTF8=0 LC_ALL=C LANG=C python3 "$U8_SCRIPTS/parse-acs.py" --body-file "$U8D_BODY" > "$U8D_OUT" 2>/dev/null
    U8D_PA_RC=$?
    assert_eq "#1678 AC1: parse-acs.py --body-file exits 0 under ASCII file codec (codec=$U8D_ENC)" "0" "$U8D_PA_RC"
    assert_eq "#1678 AC1: the em-dash+emoji item survives in AC and Test Plan output" "2" \
      "$(grep -cF 'Models/CompanySettings.cs — preserve 🚀' "$U8D_OUT")"
    rm -f "$U8D_BODY" "$U8D_OUT"

    # AC2 — the three _read_section_file flags each preserve a UTF-8 em-dash+emoji
    # fixture through the REAL workpad mutation boundary (_read_section_file →
    # _set_section_content/_insert_section_after → _join_sections; nothing mocked).
    # RED on baseline (the ambient-ASCII read raises, so the driver prints nothing).
    U8D_DRV="$(mktemp -d)"
    cat > "$U8D_DRV/drv.py" <<'U8PY'
import sys
sys.path.insert(0, sys.argv[1])
import workpad
fix = sys.argv[2]
BODY = ("<!-- m -->\n# T\n\n**Status:** \U0001f680 Setup\n"
        "**Last updated:** x\n\n## Plan\n- [ ] a\n\n"
        "## Acceptance Criteria\n- [ ] b\n")
pre, secs = workpad._split_sections(BODY)
secs = workpad._set_section_content(secs, 'Plan', workpad._read_section_file(fix, '--replace-plan-file'))
secs = workpad._set_section_content(secs, 'Acceptance Criteria', workpad._read_section_file(fix, '--replace-acs-file'))
secs = workpad._insert_section_after(secs, 'Acceptance Criteria', '## Reproduction', workpad._read_section_file(fix, '--set-reproduction-file'))
out = workpad._join_sections(pre, secs)
n = out.count("— preserve \U0001f680")
sys.stdout.write("AC2_OK" if n == 3 else ("AC2_FAIL:%d" % n))
U8PY
    U8D_FIX="$(mktemp)"
    printf -- '- [ ] Models/CompanySettings.cs \xe2\x80\x94 preserve \xf0\x9f\x9a\x80\n' > "$U8D_FIX"
    U8D_AC2="$( env PYTHONCOERCECLOCALE=0 PYTHONUTF8=0 LC_ALL=C LANG=C python3 "$U8D_DRV/drv.py" "$U8_SCRIPTS" "$U8D_FIX" 2>/dev/null )"
    assert_eq "#1678 AC2: the 3 _read_section_file flags preserve UTF-8 through the real mutation boundary (codec=$U8D_ENC)" "AC2_OK" "$U8D_AC2"
    rm -rf "$U8D_DRV"; rm -f "$U8D_FIX"

    # AC3 — branch-for-issue.py --title-file under the hostile codec == the
    # identical positional UTF-8 title. The reference is the positional form under
    # PYTHONUTF8=1 (forces UTF-8 argv decoding regardless of host locale — argv
    # itself corrupts under the hostile codec, which is NOT the axis under test).
    # RED on baseline: the file read raises under ASCII → empty output.
    U8D_TITLE="$(mktemp)"
    printf 'Fix crash in Mod\xc3\xa8le \xf0\x9f\x9a\x80 handler' > "$U8D_TITLE"
    U8D_REF="$( env PYTHONUTF8=1 python3 "$U8_SCRIPTS/branch-for-issue.py" 1678 'Fix crash in Modèle 🚀 handler' 2>/dev/null )"
    U8D_FROMFILE="$( env PYTHONCOERCECLOCALE=0 PYTHONUTF8=0 LC_ALL=C LANG=C python3 "$U8_SCRIPTS/branch-for-issue.py" 1678 --title-file "$U8D_TITLE" 2>/dev/null )"
    assert_eq "#1678 AC3: --title-file (codec=$U8D_ENC) == positional UTF-8 title branch name" "$U8D_REF" "$U8D_FROMFILE"
    assert_eq "#1678 AC3: the reference positional branch name is non-empty (guards a vacuous ==)" "yes" \
      "$( [ -n "$U8D_REF" ] && echo yes || echo no )"
    rm -f "$U8D_TITLE"
    ;;
  *)
    skip "#1678 UTF-8 local-file decode hostile-codec self-scan (AC1/AC2/AC3)" host-capability "forced env did not downgrade the file codec to ASCII (got ${U8D_ENC:-<empty>}); the hostile-codec RED->GREEN condition is not reproducible on this host" ;;
esac

# AC4 runs UNCONDITIONALLY, OUTSIDE the hostile-codec case above: invalid UTF-8 and
# an unavailable path fail under every codec, so gating these regression legs behind
# the ASCII-codec self-skip would drop coverage of the new except-OSError/decode arms
# on a host that cannot reproduce that codec. AC1/AC2/AC3 stay gated — they need the
# hostile codec to be RED on baseline.
if true; then
    # AC4 (CLI half) — invalid UTF-8 on each affected CLI exits non-zero with a
    # flag-specific UTF-8 diagnostic, NO traceback, and NO partial stdout. (Invalid
    # UTF-8 fails under any codec, so no hostile env is needed for this leg.)
    U8D_BAD="$(mktemp)"
    printf 'bad\xff\xfe\x00utf8\xe2\x28' > "$U8D_BAD"
    U8D_PAO="$(mktemp)"; U8D_PAE="$(mktemp)"
    python3 "$U8_SCRIPTS/parse-acs.py" --body-file "$U8D_BAD" > "$U8D_PAO" 2>"$U8D_PAE"
    U8D_PA4=$?
    assert_eq "#1678 AC4: parse-acs.py --body-file invalid-UTF-8 exits non-zero" "yes" \
      "$( [ "$U8D_PA4" -ne 0 ] && echo yes || echo no )"
    assert_eq "#1678 AC4: parse-acs.py invalid-UTF-8 diagnostic is flag-specific, no traceback" "yes" \
      "$( grep -qF -- '--body-file' "$U8D_PAE" && grep -qF 'not valid UTF-8' "$U8D_PAE" \
          && ! grep -qF 'Traceback (most recent call last)' "$U8D_PAE" && echo yes || echo no )"
    assert_eq "#1678 AC4: parse-acs.py invalid-UTF-8 emits no partial stdout" "0" \
      "$(wc -c < "$U8D_PAO" | tr -d ' ')"
    U8D_BFO="$(mktemp)"; U8D_BFE="$(mktemp)"
    python3 "$U8_SCRIPTS/branch-for-issue.py" 1678 --title-file "$U8D_BAD" > "$U8D_BFO" 2>"$U8D_BFE"
    U8D_BF4=$?
    assert_eq "#1678 AC4: branch-for-issue.py --title-file invalid-UTF-8 exits non-zero" "yes" \
      "$( [ "$U8D_BF4" -ne 0 ] && echo yes || echo no )"
    assert_eq "#1678 AC4: branch-for-issue.py invalid-UTF-8 diagnostic is flag-specific, no traceback" "yes" \
      "$( grep -qF -- '--title-file' "$U8D_BFE" && grep -qF 'not valid UTF-8' "$U8D_BFE" \
          && ! grep -qF 'Traceback (most recent call last)' "$U8D_BFE" && echo yes || echo no )"
    assert_eq "#1678 AC4: branch-for-issue.py invalid-UTF-8 emits no partial stdout" "0" \
      "$(wc -c < "$U8D_BFO" | tr -d ' ')"
    # AC4 (unavailable-path half) — the issue's "unavailable path" byte-matrix row:
    # a nonexistent --body-file / --title-file exits non-zero with a flag-specific
    # "could not read" diagnostic, no traceback, and no partial stdout (the new
    # except-OSError arms this change added to the two CLIs).
    U8D_MISS="$U8D_BAD-nonexistent"   # a path guaranteed not to exist (never created)
    U8D_MPAO="$(mktemp)"; U8D_MPAE="$(mktemp)"
    python3 "$U8_SCRIPTS/parse-acs.py" --body-file "$U8D_MISS" > "$U8D_MPAO" 2>"$U8D_MPAE"
    U8D_MPA=$?
    assert_eq "#1678 AC4: parse-acs.py --body-file unavailable-path exits non-zero" "yes" \
      "$( [ "$U8D_MPA" -ne 0 ] && echo yes || echo no )"
    assert_eq "#1678 AC4: parse-acs.py unavailable-path diagnostic is flag-specific, no traceback" "yes" \
      "$( grep -qF -- '--body-file' "$U8D_MPAE" && grep -qF 'could not read' "$U8D_MPAE" \
          && ! grep -qF 'Traceback (most recent call last)' "$U8D_MPAE" && echo yes || echo no )"
    assert_eq "#1678 AC4: parse-acs.py unavailable-path emits no partial stdout" "0" \
      "$(wc -c < "$U8D_MPAO" | tr -d ' ')"
    U8D_MBFO="$(mktemp)"; U8D_MBFE="$(mktemp)"
    python3 "$U8_SCRIPTS/branch-for-issue.py" 1678 --title-file "$U8D_MISS" > "$U8D_MBFO" 2>"$U8D_MBFE"
    U8D_MBF=$?
    assert_eq "#1678 AC4: branch-for-issue.py --title-file unavailable-path exits non-zero" "yes" \
      "$( [ "$U8D_MBF" -ne 0 ] && echo yes || echo no )"
    assert_eq "#1678 AC4: branch-for-issue.py unavailable-path diagnostic is flag-specific, no traceback" "yes" \
      "$( grep -qF -- '--title-file' "$U8D_MBFE" && grep -qF 'could not read' "$U8D_MBFE" \
          && ! grep -qF 'Traceback (most recent call last)' "$U8D_MBFE" && echo yes || echo no )"
    assert_eq "#1678 AC4: branch-for-issue.py unavailable-path emits no partial stdout" "0" \
      "$(wc -c < "$U8D_MBFO" | tr -d ' ')"
    rm -f "$U8D_BAD" "$U8D_PAO" "$U8D_PAE" "$U8D_BFO" "$U8D_BFE" "$U8D_MPAO" "$U8D_MPAE" "$U8D_MBFO" "$U8D_MBFE"
fi

# ────────────────────────────────────────────────────────────────────────────
echo "python3 interpreter resolution: resolve-python.sh / provision-python3-shim.sh / preflight.sh (issue #225)"
# ────────────────────────────────────────────────────────────────────────────
# Stock Windows Python (python.org / winget) ships `python` + the `py -3` launcher and NO
# `python3` on PATH, so every literal `python3` call fails. These assertions exercise the
# shared selection contract (lib/resolve-python.sh), the consent-gated shim provisioner, the
# preflight resolution path, and install.sh delegation — using fake-interpreter PATH stubs
# (the suite is offline/gh-stubbed, so a temp-dir PATH with fake `python`/`py` fits the
# harness). The fakes pattern-match the exact `-c` probes resolve-python.sh runs and exec the
# REAL interpreter for a script argument, so the shim's arg/exit-code forwarding is exercised
# end-to-end rather than mocked.
PPS="$LIB/../scripts/provision-python3-shim.sh"
PREFLIGHT_SH="$LIB/preflight.sh"
RESOLVE_SH="$LIB/resolve-python.sh"
REAL_PY="$(command -v python3 2>/dev/null || true)"

if [ -z "$REAL_PY" ]; then
  # No real python3 to back the fakes — the whole suite already requires python3 (the python
  # section below runs under it), so this is unreachable in practice; record a FAIL rather
  # than silently skipping coverage if it ever happens.
  echo FAIL >> "$RESULTS_FILE"
  record_fail "#225 fake-interpreter stubs: no python3"
  printf '  FAIL  #225: no python3 available to back the fake-interpreter stubs (cannot run resolution tests)\n'
else
  # Populate DIR with coreutils symlinks + no-op git/gh/jq stubs, but deliberately NO python*
  # (so `command -v python3` fails inside the stub PATH); callers then drop in fake interpreters.
  build_stub_bin() {  # $1=dir
    local d="$1" t src
    for t in bash sh env dirname mktemp grep mkdir chmod mv rm ln cat sed cut tr id head wc sort cp printf; do
      src="$(command -v "$t" 2>/dev/null)" && [ -n "$src" ] && ln -s "$src" "$d/$t" 2>/dev/null
    done
    for t in git gh jq; do
      printf '#!/bin/sh\nexit 0\n' > "$d/$t" && chmod +x "$d/$t"
    done
  }
  # Write a fake Python interpreter at $1 reporting version $2 (major $3, minor $4). It honors
  # -V/--version, the `-c 'pass'` runnability probe, the resolve-python version probe, and
  # `import yaml` (present unless $5 == noyaml); any other args (a script path) exec the REAL
  # python3 so behavior is genuine. Args of the generated script are escaped (\$); $2/$3/$4/$5
  # and $REAL_PY expand now, at generation time.
  make_fake_python() {  # $1=path $2=verstring $3=maj $4=min [$5=noyaml]
    local yaml_rc=0
    [ "${5:-}" = "noyaml" ] && yaml_rc=1
    cat > "$1" <<EOF
#!/usr/bin/env bash
case "\$1" in
  -V|--version) echo "Python $2"; exit 0 ;;
esac
if [ "\$1" = "-c" ]; then
  case "\$2" in
    *"version_info >= (3, 11)"*)
      if [ "$3" -gt 3 ] || { [ "$3" -eq 3 ] && [ "$4" -ge 11 ]; }; then exit 0; else exit 1; fi ;;
    pass) exit 0 ;;
    *"import yaml"*) exit $yaml_rc ;;
    *) exit 0 ;;
  esac
fi
exec "$REAL_PY" "\$@"
EOF
    chmod +x "$1"
  }
  # Write a fake `py` launcher at $1 that supports only `-3` and delegates to the fake python at $2.
  make_fake_py() {  # $1=path $2=delegate
    cat > "$1" <<EOF
#!/usr/bin/env bash
if [ "\$1" = "-3" ]; then shift; exec "$2" "\$@"; fi
echo "py: only -3 supported in this stub" >&2; exit 1
EOF
    chmod +x "$1"
  }

  # ── AC1: provisioner exists, SPDX header, consent-gated, stable breadcrumb. ──
  assert_eq "#225 pps: provisioner file exists (AC1)" "yes" "$([ -f "$PPS" ] && echo yes || echo no)"
  assert_eq "#225 pps: SPDX header present (AC1)" "yes" "$(grep -q 'SPDX-License-Identifier: MIT' "$PPS" && echo yes || echo no)"
  assert_eq "#225 pps: consent-gated via --apply (AC1)" "yes" "$(grep -q -- '--apply' "$PPS" && echo yes || echo no)"
  assert_eq "#225 pps: stable devflow-python: breadcrumb prefix (AC1)" "yes" "$(grep -q 'devflow-python:' "$PPS" && echo yes || echo no)"
  assert_eq "#225 resolve-python.sh: SPDX header present" "yes" "$(grep -q 'SPDX-License-Identifier: MIT' "$RESOLVE_SH" && echo yes || echo no)"

  # ── AC2/AC3: alternate `python` (>=3.11), no python3 → shim installed; forwards args+exit. ──
  T1="$(mktemp -d)"; build_stub_bin "$T1"; make_fake_python "$T1/python" "3.11.5" 3 11
  T1BIN="$(mktemp -d)"
  PATH="$T1" bash "$PPS" --apply "$T1BIN" >/dev/null 2>&1; PPS_RC=$?
  assert_eq "#225 pps: alternate python, no python3 → exit 0 (AC2)" "0" "$PPS_RC"
  assert_eq "#225 pps: shim created at target dir (AC2)" "yes" "$([ -f "$T1BIN/python3" ] && echo yes || echo no)"
  assert_eq "#225 pps: shim execs the alternate, NEVER python3 (no recursion) (AC3)" "yes" \
    "$(grep -q '^exec python "\$@"' "$T1BIN/python3" && echo yes || echo no)"
  assert_eq "#225 pps: shim body does not exec python3 (AC3)" "no" \
    "$(grep -q 'exec python3 ' "$T1BIN/python3" && echo yes || echo no)"
  assert_eq "#225 pps: python3 --version via shim reports the >=3.11 interpreter (AC2)" "Python 3.11.5" \
    "$(PATH="$T1BIN:$T1" python3 --version 2>&1)"
  # The shim carries the DevFlow marker line — the clobber guard's recognition signal, so a
  # regression that wrote a working-but-unmarked shim (which would make re-apply refuse its own
  # shim) is caught directly here, not only transitively via the idempotent-rewrite test.
  assert_eq "#225 pps: written shim carries the DevFlow SHIM_MARKER line" "yes" \
    "$(grep -q 'Generated by DevFlow scripts/provision-python3-shim.sh' "$T1BIN/python3" && echo yes || echo no)"
  # Arg + exit-code forwarding through the shim → fake python → real python3.
  printf 'import sys\nprint("args:" + " ".join(sys.argv[1:]))\nsys.exit(7)\n' > "$T1BIN/check.py"
  FWD_OUT="$(PATH="$T1BIN:$T1" python3 "$T1BIN/check.py" hello 2>&1)"; FWD_RC=$?
  assert_eq "#225 pps: shim forwards exit code (AC3)" "7" "$FWD_RC"
  assert_eq "#225 pps: shim forwards args (AC3)" "args:hello" "$FWD_OUT"

  # Default (no --apply) is consent-respecting: prints the plan, writes NOTHING.
  T1D="$(mktemp -d)"
  PPS_DEF_OUT="$(PATH="$T1" bash "$PPS" "$T1D" 2>&1)"; PPS_DEF_RC=$?
  assert_eq "#225 pps: default (no --apply) → exit 0" "0" "$PPS_DEF_RC"
  assert_eq "#225 pps: default (no --apply) writes NOTHING (consent)" "no" "$([ -f "$T1D/python3" ] && echo yes || echo no)"
  assert_eq "#225 pps: default prints --apply guidance" "yes" "$(printf '%s' "$PPS_DEF_OUT" | grep -q -- '--apply' && echo yes || echo no)"

  # ── AC4: selection picks the FIRST >=3.11 (py -3 over a Python-2 `python`); Python-2 rejected. ──
  T4="$(mktemp -d)"; build_stub_bin "$T4"
  make_fake_python "$T4/python" "2.7.18" 2 7           # `python` → Python 2 (must be rejected)
  make_fake_python "$T4/_py3delegate" "3.11.0" 3 11
  make_fake_py "$T4/py" "$T4/_py3delegate"
  SEL="$(PATH="$T4" bash -c ". \"$RESOLVE_SH\"; devflow_resolve_python")"; SEL_RC=$?
  assert_eq "#225 resolve: picks 'py -3' over a Python-2 'python' (AC4)" "py -3" "$SEL"
  assert_eq "#225 resolve: rc 0 when a >=3.11 alternate exists (AC4)" "0" "$SEL_RC"

  # Python-2 only → rc 1 (a runnable interpreter exists but too old), echoes the runnable one.
  T4B="$(mktemp -d)"; build_stub_bin "$T4B"; make_fake_python "$T4B/python" "2.7.18" 2 7
  SEL2="$(PATH="$T4B" bash -c ". \"$RESOLVE_SH\"; devflow_resolve_python")"; SEL2_RC=$?
  assert_eq "#225 resolve: python2-only → echoes the first runnable invocation" "python" "$SEL2"
  assert_eq "#225 resolve: python2-only → rc 1 (too old, distinct from 'none')" "1" "$SEL2_RC"

  # ── AC2/AC3/AC4: `py -3`-resolved host writes a TWO-WORD `exec py -3 "$@"` shim and forwards
  #    end-to-end. Guards the SC2086 word-split hazard: a regression collapsing "py -3" into a
  #    single quoted token (`exec "py -3" "$@"`) would pass every `python`-form assertion above. ──
  TPY3="$(mktemp -d)"; build_stub_bin "$TPY3"
  make_fake_python "$TPY3/_py3delegate" "3.11.4" 3 11
  make_fake_py "$TPY3/py" "$TPY3/_py3delegate"
  TPY3BIN="$(mktemp -d)"
  PATH="$TPY3" bash "$PPS" --apply "$TPY3BIN" >/dev/null 2>&1; PPS_PY3_RC=$?
  assert_eq "#225 pps: py -3 host, no python3 → exit 0 (AC4)" "0" "$PPS_PY3_RC"
  assert_eq "#225 pps: py -3 host → shim written (AC2)" "yes" "$([ -f "$TPY3BIN/python3" ] && echo yes || echo no)"
  assert_eq "#225 pps: py -3 host → shim body is the two-word 'exec py -3 \"\$@\"' (AC3)" "yes" \
    "$(grep -q '^exec py -3 "\$@"' "$TPY3BIN/python3" && echo yes || echo no)"
  printf 'import sys\nprint("pyargs:" + " ".join(sys.argv[1:]))\nsys.exit(5)\n' > "$TPY3BIN/pcheck.py"
  PY3_FWD_OUT="$(PATH="$TPY3BIN:$TPY3" python3 "$TPY3BIN/pcheck.py" world 2>&1)"; PY3_FWD_RC=$?
  assert_eq "#225 pps: py -3 shim forwards exit code (AC3)" "5" "$PY3_FWD_RC"
  assert_eq "#225 pps: py -3 shim forwards args (AC3)" "pyargs:world" "$PY3_FWD_OUT"

  # ── Clobber guard (SHIM_MARKER): refuse to overwrite a foreign python3; rewrite a DevFlow shim. ──
  # Foreign (non-DevFlow) python3 already at the target → refuse with exit 2, leave it byte-for-byte.
  TCF="$(mktemp -d)"; build_stub_bin "$TCF"; make_fake_python "$TCF/python" "3.11.9" 3 11
  TCFBIN="$(mktemp -d)"; printf '#!/bin/sh\necho FOREIGN\n' > "$TCFBIN/python3"; chmod +x "$TCFBIN/python3"
  PPS_CF_OUT="$(PATH="$TCF" bash "$PPS" --apply "$TCFBIN" 2>&1)"; PPS_CF_RC=$?
  assert_eq "#225 pps: foreign python3 at target → refuse exit 2 (no clobber)" "2" "$PPS_CF_RC"
  assert_eq "#225 pps: foreign python3 → breadcrumb says 'did not create' (refuse to overwrite)" "yes" \
    "$(printf '%s' "$PPS_CF_OUT" | grep -qi 'did not create' && echo yes || echo no)"
  assert_eq "#225 pps: foreign python3 left byte-for-byte unchanged" "yes" \
    "$(grep -q 'echo FOREIGN' "$TCFBIN/python3" && echo yes || echo no)"
  # A DANGLING python3 symlink at the target: `-e` follows symlinks and reports it non-existent,
  # so the clobber guard's `-L` arm is load-bearing — without it the guard would skip and `mv`
  # would silently replace a symlink DevFlow did not create (and a broken python3 symlink is
  # exactly the corrupt-interpreter class this targets). Assert the guard still refuses (exit 2)
  # and leaves the symlink in place. (Review finding: clobber guard fail-open on dangling links.)
  TCDBIN="$(mktemp -d)"; ln -s /nonexistent-python-target "$TCDBIN/python3"
  PPS_CD_OUT="$(PATH="$TCF" bash "$PPS" --apply "$TCDBIN" 2>&1)"; PPS_CD_RC=$?
  assert_eq "#225 pps: dangling python3 symlink at target → refuse exit 2 (no clobber via -L arm)" "2" "$PPS_CD_RC"
  assert_eq "#225 pps: dangling symlink → breadcrumb says 'did not create'" "yes" \
    "$(printf '%s' "$PPS_CD_OUT" | grep -qi 'did not create' && echo yes || echo no)"
  assert_eq "#225 pps: dangling symlink left in place (still a symlink, not overwritten)" "yes" \
    "$([ -L "$TCDBIN/python3" ] && echo yes || echo no)"
  rm -rf "$TCDBIN"
  # A DevFlow shim a prior run wrote (carries the marker) → re-apply is an idempotent rewrite (exit 0).
  TCRBIN="$(mktemp -d)"
  PATH="$TCF" bash "$PPS" --apply "$TCRBIN" >/dev/null 2>&1   # first apply writes the marked shim
  PATH="$TCF" bash "$PPS" --apply "$TCRBIN" >/dev/null 2>&1; PPS_RE_RC=$?
  assert_eq "#225 pps: re-apply over DevFlow's own shim → exit 0 (idempotent rewrite, AC9)" "0" "$PPS_RE_RC"
  assert_eq "#225 pps: re-applied shim still present and still the alternate exec" "yes" \
    "$(grep -q '^exec python "\$@"' "$TCRBIN/python3" && echo yes || echo no)"

  # ── Malformed invocation: unknown option and extra positional both refuse with exit 2. ──
  PPS_OPT_RC=0; PATH="$TCF" bash "$PPS" --bogus "$(mktemp -d)" >/dev/null 2>&1 || PPS_OPT_RC=$?
  assert_eq "#225 pps: unknown option → exit 2" "2" "$PPS_OPT_RC"
  PPS_XTRA_RC=0; PATH="$TCF" bash "$PPS" "$(mktemp -d)" "$(mktemp -d)" >/dev/null 2>&1 || PPS_XTRA_RC=$?
  assert_eq "#225 pps: extra positional argument → exit 2" "2" "$PPS_XTRA_RC"

  # ── AC4/AC6: provisioner refuses (non-zero, specific version msg) on a too-old-only host. ──
  T6T="$(mktemp -d)"
  PPS_OLD_OUT="$(PATH="$T4B" bash "$PPS" --apply "$T6T" 2>&1)"; PPS_OLD_RC=$?
  assert_eq "#225 pps: too-old-only python → refuse exit 2 (AC6)" "2" "$PPS_OLD_RC"
  assert_eq "#225 pps: too-old → specific 'older than 3.11' message, not 'missing' (AC6)" "yes" \
    "$(printf '%s' "$PPS_OLD_OUT" | grep -qi 'older than 3.11' && echo yes || echo no)"
  assert_eq "#225 pps: too-old → no shim written (AC6)" "no" "$([ -f "$T6T/python3" ] && echo yes || echo no)"

  # ── AC5: preflight, no python3 but a >=3.11 alternate → provisioner pointer, NOT dead end. ──
  T5="$(mktemp -d)"; build_stub_bin "$T5"; make_fake_python "$T5/python" "3.11.7" 3 11
  PF5_OUT="$(PATH="$T5" bash "$PREFLIGHT_SH" 2>&1)"; PF5_RC=$?
  assert_eq "#225 preflight: alt python, no python3 → exit non-zero (literal python3 still missing) (AC5)" "yes" \
    "$([ "$PF5_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#225 preflight: alt python → points to provision-python3-shim.sh (AC5)" "yes" \
    "$(printf '%s' "$PF5_OUT" | grep -q 'provision-python3-shim.sh' && echo yes || echo no)"
  assert_eq "#225 preflight: alt python → NOT the bare \"missing required tool 'python3'\" dead end (AC5)" "no" \
    "$(printf '%s' "$PF5_OUT" | grep -q "missing required tool 'python3'" && echo yes || echo no)"

  # ── Broken-but-present python3 (dangling symlink / corrupt install / missing DLL — the
  #    broken-Windows-interpreter class this provisioner targets): preflight's happy path now
  #    probes runnability (`python3 -c 'pass'`), so a python3 that is on PATH but does not
  #    execute must NOT short-circuit into a misleading PyYAML/version message; it falls
  #    through to the resolver, which skips it and points at the provisioner via the >=3.11
  #    `python` alternate. (Important review finding: lib/preflight.sh happy-path runnability.)
  T5B="$(mktemp -d)"; build_stub_bin "$T5B"; make_fake_python "$T5B/python" "3.11.7" 3 11
  printf '#!/bin/sh\nexit 127\n' > "$T5B/python3"; chmod +x "$T5B/python3"  # present but never runs
  PF5B_OUT="$(PATH="$T5B" bash "$PREFLIGHT_SH" 2>&1)"; PF5B_RC=$?
  assert_eq "#225 preflight: broken python3 + alt → exit non-zero" "yes" \
    "$([ "$PF5B_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#225 preflight: broken-but-present python3 falls through to the resolver → provisioner pointer" "yes" \
    "$(printf '%s' "$PF5B_OUT" | grep -q 'provision-python3-shim.sh' && echo yes || echo no)"
  assert_eq "#225 preflight: broken python3 → NOT a misleading 'PyYAML not found' message" "no" \
    "$(printf '%s' "$PF5B_OUT" | grep -qi 'PyYAML not found' && echo yes || echo no)"

  # ── AC7: preflight runs the PyYAML check against the RESOLVED interpreter (not a hardcoded python3). ──
  T7="$(mktemp -d)"; build_stub_bin "$T7"; make_fake_python "$T7/python" "3.11.2" 3 11 noyaml
  PF7_OUT="$(PATH="$T7" bash "$PREFLIGHT_SH" 2>&1)"
  assert_eq "#225 preflight: PyYAML checked against the resolved interpreter (AC7)" "yes" \
    "$(printf '%s' "$PF7_OUT" | grep -qi 'PyYAML not found' && echo yes || echo no)"
  assert_eq "#225 preflight: PyYAML hint names the resolved interpreter, not hardcoded python3 (AC7)" "yes" \
    "$(printf '%s' "$PF7_OUT" | grep -q "'python -m pip install pyyaml'" && echo yes || echo no)"

  # ── AC6 (preflight half): too-old-only → specific <3.11 message, never 'missing'. ──
  PF6_OUT="$(PATH="$T4B" bash "$PREFLIGHT_SH" 2>&1)"; PF6_RC=$?
  assert_eq "#225 preflight: too-old python → exit non-zero (AC6)" "yes" "$([ "$PF6_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#225 preflight: too-old → specific 'Python 3.11+ required' message (AC6)" "yes" \
    "$(printf '%s' "$PF6_OUT" | grep -q 'Python 3.11+ required' && echo yes || echo no)"
  assert_eq "#225 preflight: too-old → NOT the bare \"missing required tool 'python3'\" message (AC6)" "no" \
    "$(printf '%s' "$PF6_OUT" | grep -q "missing required tool 'python3'" && echo yes || echo no)"
  # Positively pin the rc-1 ALTERNATE branch (python2-only host): its message names 'no working
  # python3 on PATH', distinguishing it from the python3-present-<3.11 version-recheck branch
  # (TOLD below). "no working python3" (not "no python3 on PATH") because python3 may be
  # present-but-broken and rejected by preflight's runnability probe, not strictly absent.
  assert_eq "#225 preflight: alternate-too-old → rc-1 branch message names 'no working python3 on PATH' (AC6)" "yes" \
    "$(printf '%s' "$PF6_OUT" | grep -q 'no working python3 on PATH' && echo yes || echo no)"

  # ── AC9: idempotent no-op when a working python3 >=3.11 already resolves. ──
  T9="$(mktemp -d)"; build_stub_bin "$T9"; make_fake_python "$T9/python3" "3.12.3" 3 12
  T9T="$(mktemp -d)"
  PPS9_OUT="$(PATH="$T9" bash "$PPS" --apply "$T9T" 2>&1)"; PPS9_RC=$?
  assert_eq "#225 pps: python3 already works → exit 0 (AC9)" "0" "$PPS9_RC"
  assert_eq "#225 pps: python3 already works → 'nothing to do' breadcrumb (AC9)" "yes" \
    "$(printf '%s' "$PPS9_OUT" | grep -qi 'nothing to do' && echo yes || echo no)"
  assert_eq "#225 pps: python3 already works → no shim written (AC9/AC10)" "no" "$([ -f "$T9T/python3" ] && echo yes || echo no)"

  # ── AC10: real python3 >=3.11 + deps present → byte-identical pass line, no provisioner pointer. ──
  T10="$(mktemp -d)"; build_stub_bin "$T10"; make_fake_python "$T10/python3" "3.12.1" 3 12
  PF10_OUT="$(PATH="$T10" bash "$PREFLIGHT_SH" 2>&1)"; PF10_RC=$?
  assert_eq "#225 preflight: python3 present + deps → exit 0 (AC10)" "0" "$PF10_RC"
  assert_eq "#225 preflight: byte-identical pass line on python3-present path (AC10)" \
    "devflow preflight: all dependencies present." "$(printf '%s\n' "$PF10_OUT" | tail -1)"
  assert_eq "#225 preflight: no provisioner pointer when python3 resolves (AC10)" "no" \
    "$(printf '%s' "$PF10_OUT" | grep -q 'provision-python3-shim.sh' && echo yes || echo no)"

  # ── #984: a working python3 >=3.11 that LACKS PyYAML → advisory demotion on the local
  #    user tier. No prior fixture covered this population — T7/TPYPRE also lack python3, so
  #    their non-zero exit came from the python3 arm, never from PyYAML. Here the ONLY gap is
  #    PyYAML, so it exits 0 with a DISTINCT advisory final line carrying the stable
  #    `PyYAML advisory` token, while the AC2 message literals ('PyYAML not found' + the
  #    resolved-interpreter pip remedy) are preserved. ──
  T984="$(mktemp -d)"; build_stub_bin "$T984"; make_fake_python "$T984/python3" "3.11.5" 3 11 noyaml
  PF984_OUT="$(PATH="$T984" bash "$PREFLIGHT_SH" 2>&1)"; PF984_RC=$?
  assert_eq "#984 preflight: PyYAML-only gap (working python3, no yaml) → exit 0 (AC1)" "0" "$PF984_RC"
  assert_eq "#984 preflight: advisory names PyYAML not found (AC1/AC2 literal preserved)" "yes" \
    "$(printf '%s' "$PF984_OUT" | grep -qF 'PyYAML not found' && echo yes || echo no)"
  assert_eq "#984 preflight: AC2 remedy literal names the resolved interpreter (python3 -m pip install pyyaml)" "yes" \
    "$(printf '%s' "$PF984_OUT" | grep -qF "'python3 -m pip install pyyaml'" && echo yes || echo no)"
  assert_eq "#984 preflight: exit-0 advisory run emits the distinct final line carrying the stable token (AC3)" "yes" \
    "$(printf '%s\n' "$PF984_OUT" | tail -1 | grep -qF 'PyYAML advisory' && echo yes || echo no)"
  assert_eq "#984 preflight: advisory final line is NOT the byte-identical all-clear (AC3)" "no" \
    "$(printf '%s\n' "$PF984_OUT" | tail -1 | grep -qxF 'devflow preflight: all dependencies present.' && echo yes || echo no)"
  # The advisory final line must land on STDOUT (where /prflow:init reads it), not stderr —
  # the captures above merge 2>&1, so a stdout-only capture is what pins the stream.
  PF984_STDOUT="$(PATH="$T984" bash "$PREFLIGHT_SH" 2>/dev/null)"
  assert_eq "#984 preflight: the advisory final line is emitted on stdout, not stderr (AC3)" \
    "devflow preflight: required dependencies present; PyYAML advisory (see above)." \
    "$(printf '%s\n' "$PF984_STDOUT" | tail -1)"
  rm -rf "$T984"

  # ── #984 AC4 negative control: each of git/gh/jq/python3, absent one at a time, still sets
  #    the aggregate flag and exits non-zero — proving the demotion is scoped to the PyYAML arm,
  #    not global. Each fixture carries a working python3+PyYAML so the removed tool is the only
  #    gap (for the python3 row, removing it leaves no py/python alternate → the missing-python3
  #    dead end). ──
  for _tool984 in git gh jq python3; do
    T984N="$(mktemp -d)"; build_stub_bin "$T984N"; make_fake_python "$T984N/python3" "3.11.5" 3 11
    rm -f "$T984N/$_tool984"
    PF984N_RC=0; PATH="$T984N" bash "$PREFLIGHT_SH" >/dev/null 2>&1 || PF984N_RC=$?
    assert_eq "#984 preflight AC4: missing '$_tool984' still exits non-zero (demotion is scoped, not global)" "yes" \
      "$([ "$PF984N_RC" -ne 0 ] && echo yes || echo no)"
    rm -rf "$T984N"
  done

  # ── #984 precedence: a run carrying BOTH a real prerequisite gap AND a missing PyYAML must
  #    take the hard stop, never the exit-0 advisory. The aggregate `missing` gate in
  #    lib/preflight.sh is deliberately ordered BEFORE the `pyyaml_advisory` arm; swapping the
  #    two exit blocks would make this fixture exit 0 and print the advisory line. Reachable
  #    combined case: a too-old python3 (sets `missing` via the version re-check) that ALSO
  #    lacks PyYAML (sets `pyyaml_advisory`). Neither the AC1 fixture (every tool present) nor
  #    the AC4 loop (PyYAML present) exercises both flags at once. ──
  T984P="$(mktemp -d)"; build_stub_bin "$T984P"; make_fake_python "$T984P/python3" "3.10.9" 3 10 noyaml
  PF984P_OUT="$(PATH="$T984P" bash "$PREFLIGHT_SH" 2>&1)"; PF984P_RC=$?
  assert_eq "#984 preflight precedence: both a real gap (python3 <3.11) and a missing PyYAML → hard stop wins (non-zero exit)" "yes" \
    "$([ "$PF984P_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#984 preflight precedence: the combined-gap run emits BOTH diagnostics (version failure + PyYAML advisory message)" "yes" \
    "$(printf '%s' "$PF984P_OUT" | grep -q 'Python 3.11+ required (found' && printf '%s' "$PF984P_OUT" | grep -qF 'PyYAML not found' && echo yes || echo no)"
  assert_eq "#984 preflight precedence: the exit-0 'PyYAML advisory' token is NEVER printed on a hard-stop run" "no" \
    "$(printf '%s' "$PF984P_OUT" | grep -qF 'PyYAML advisory' && echo yes || echo no)"
  assert_eq "#984 preflight precedence: the hard-stop run ends on the missing-dependencies line, not the advisory line" "yes" \
    "$(printf '%s\n' "$PF984P_OUT" | tail -1 | grep -qxF 'devflow preflight: one or more required dependencies are missing (see above).' && echo yes || echo no)"
  rm -rf "$T984P"

  # ── AC6 (python3-present-but-too-old): a real python3 <3.11 takes preflight's python3 branch
  #    (NOT the resolved-alternate path) and must fail with the specific version message from the
  #    version re-check — a distinct code path from the `python`(alternate)-too-old case above. ──
  TOLD="$(mktemp -d)"; build_stub_bin "$TOLD"; make_fake_python "$TOLD/python3" "3.10.9" 3 10
  PF_OLD3_OUT="$(PATH="$TOLD" bash "$PREFLIGHT_SH" 2>&1)"; PF_OLD3_RC=$?
  assert_eq "#225 preflight: python3 present but <3.11 → exit non-zero (AC6)" "yes" \
    "$([ "$PF_OLD3_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#225 preflight: python3 <3.11 → 'Python 3.11+ required (found ...)' from the version re-check (AC6)" "yes" \
    "$(printf '%s' "$PF_OLD3_OUT" | grep -q 'Python 3.11+ required (found' && echo yes || echo no)"
  assert_eq "#225 preflight: python3 <3.11 → NOT the resolved-alternate 'no working python3 on PATH' message (AC6)" "no" \
    "$(printf '%s' "$PF_OLD3_OUT" | grep -q 'no working python3 on PATH' && echo yes || echo no)"

  # ── rc-3 "no usable Python interpreter at all" (no python3, no py, no python). build_stub_bin
  #    yields a python-free PATH, so this exercises the resolver's rc-3 return end-to-end through
  #    BOTH consumers: the provisioner refuses (exit 2, "no Python interpreter found") and preflight
  #    hits its rc-3 `else` dead-end ("missing required tool 'python3'") — NOT the rc-0 provisioner
  #    pointer (there is no alternate to point at). This is the user's only guidance when they have
  #    no Python at all; without it a regression that mis-routed rc-3 to rc-0/rc-1 would ship green. ──
  TNONE="$(mktemp -d)"; build_stub_bin "$TNONE"     # git/gh/jq + coreutils only — no python/python3/py
  # Provisioner: rc-3 → exit 2 + specific breadcrumb, writes nothing.
  TNONE_T="$(mktemp -d)"
  PPS_NONE_OUT="$(PATH="$TNONE" bash "$PPS" --apply "$TNONE_T" 2>&1)"; PPS_NONE_RC=$?
  assert_eq "#225 pps: no interpreter at all → exit 2 (rc-3)" "2" "$PPS_NONE_RC"
  assert_eq "#225 pps: no interpreter at all → 'no Python interpreter found' breadcrumb (rc-3)" "yes" \
    "$(printf '%s' "$PPS_NONE_OUT" | grep -q 'no Python interpreter found' && echo yes || echo no)"
  assert_eq "#225 pps: no interpreter at all → no shim written (rc-3)" "no" "$([ -f "$TNONE_T/python3" ] && echo yes || echo no)"
  # Preflight: rc-3 → exit non-zero + the bare dead-end message, NOT the rc-0 provisioner pointer.
  PF_NONE_OUT="$(PATH="$TNONE" bash "$PREFLIGHT_SH" 2>&1)"; PF_NONE_RC=$?
  assert_eq "#225 preflight: no interpreter at all → exit non-zero (rc-3)" "yes" \
    "$([ "$PF_NONE_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#225 preflight: no interpreter at all → bare \"missing required tool 'python3'\" dead end (rc-3)" "yes" \
    "$(printf '%s' "$PF_NONE_OUT" | grep -q "missing required tool 'python3'" && echo yes || echo no)"
  assert_eq "#225 preflight: no interpreter at all → NOT the provisioner pointer (no alternate to point at) (rc-3)" "no" \
    "$(printf '%s' "$PF_NONE_OUT" | grep -q 'provision-python3-shim.sh' && echo yes || echo no)"
  rm -rf "$TNONE" "$TNONE_T"

  # ── Default target-dir selection (the PRODUCTION path — no explicit TARGET_DIR). ──
  # (a) A writable dir on PATH → the shim lands in the first writable PATH dir, no PATH note.
  TDEF="$(mktemp -d)"; build_stub_bin "$TDEF"; make_fake_python "$TDEF/python" "3.11.3" 3 11
  PPS_DEF2_OUT="$(PATH="$TDEF" bash "$PPS" --apply 2>&1)"; PPS_DEF2_RC=$?
  assert_eq "#225 pps: default target — no TARGET_DIR, writable PATH dir → exit 0" "0" "$PPS_DEF2_RC"
  assert_eq "#225 pps: default target — shim written into the first writable PATH dir" "yes" \
    "$([ -f "$TDEF/python3" ] && echo yes || echo no)"
  assert_eq "#225 pps: default target — no PATH note when the chosen dir is on PATH" "no" \
    "$(printf '%s' "$PPS_DEF2_OUT" | grep -qi 'may not be on your PATH' && echo yes || echo no)"
  # (b) No writable dir on PATH AND HOME unset → refuse with exit 2 + the HOME-unset breadcrumb.
  #     Root bypasses the -w bit (the read-only dir would read writable), so skip under root.
  if [ "$(id -u)" -ne 0 ]; then
    TRO="$(mktemp -d)"; build_stub_bin "$TRO"; make_fake_python "$TRO/python" "3.11.3" 3 11
    chmod 0555 "$TRO"
    if [ ! -w "$TRO" ]; then
      PPS_NH_OUT="$(env -u HOME PATH="$TRO" bash "$PPS" --apply 2>&1)"; PPS_NH_RC=$?
      assert_eq "#225 pps: default target — no writable PATH dir + HOME unset → exit 2" "2" "$PPS_NH_RC"
      assert_eq "#225 pps: default target — HOME-unset breadcrumb names the cause" "yes" \
        "$(printf '%s' "$PPS_NH_OUT" | grep -qi 'HOME is unset' && echo yes || echo no)"
    fi
    chmod 0755 "$TRO"   # restore so cleanup can remove it
  else
    printf '  SKIP  #225 pps: default target — HOME-unset refusal (root bypasses the -w bit; verified on non-root CI)\n'
  fi
  # (a2) POSITIVE pin of the post-write resolution check on the auto-selected-PATH-dir success
  #      path: when the chosen writable dir IS on PATH and nothing shadows the shim, python3 now
  #      resolves to it, so the breadcrumb claims 'now resolves'. (TDEF above had no other python3
  #      on PATH, so command -v python3 finds the shim.)
  assert_eq "#225 pps: default target — success breadcrumb confirms 'now resolves' (post-write check)" "yes" \
    "$(printf '%s' "$PPS_DEF2_OUT" | grep -q 'now resolves' && echo yes || echo no)"

  # (c) SHADOWED shim: the shim is written to a later writable PATH dir, but an EARLIER PATH
  #     entry holds a broken `python3` that still wins `command -v` — so the provisioner must NOT
  #     claim 'now resolves'; it warns that the shim is shadowed and exits 3 (distinct from the
  #     exit-2 "wrote nothing" refusals — the shim WAS written). This is the fail-open the
  #     unconditional success breadcrumb had. Root bypasses the -w bit (the read-only earlier dir
  #     would read writable, so auto-select would land there and clobber-refuse instead), so skip
  #     under root. (Review finding: provisioner success-overclaim vs PATH shadowing.)
  if [ "$(id -u)" -ne 0 ]; then
    TSHADOW_E="$(mktemp -d)"                                  # earlier PATH dir: a broken python3
    printf '#!/bin/sh\nexit 127\n' > "$TSHADOW_E/python3"; chmod +x "$TSHADOW_E/python3"
    chmod 0555 "$TSHADOW_E"                                   # non-writable → auto-select skips it
    TSHADOW_W="$(mktemp -d)"; build_stub_bin "$TSHADOW_W"; make_fake_python "$TSHADOW_W/python" "3.11.6" 3 11
    if [ ! -w "$TSHADOW_E" ]; then
      PPS_SH_OUT="$(PATH="$TSHADOW_E:$TSHADOW_W" bash "$PPS" --apply 2>&1)"; PPS_SH_RC=$?
      assert_eq "#225 pps: shadowed shim (earlier broken python3 wins) → exit 3 (shim written but does not win)" "3" "$PPS_SH_RC"
      assert_eq "#225 pps: shadowed shim → breadcrumb names the shadow, does NOT claim 'now resolves'" "yes" \
        "$(printf '%s' "$PPS_SH_OUT" | grep -q 'shadows the shim' && ! printf '%s' "$PPS_SH_OUT" | grep -q 'now resolves' && echo yes || echo no)"
      assert_eq "#225 pps: shadowed shim → the shim WAS written to the later writable dir" "yes" \
        "$([ -f "$TSHADOW_W/python3" ] && echo yes || echo no)"
    fi
    chmod 0755 "$TSHADOW_E"   # restore so cleanup can remove it
    rm -rf "$TSHADOW_E" "$TSHADOW_W"
  else
    printf '  SKIP  #225 pps: shadowed-shim exit-3 path (root bypasses the -w bit; verified on non-root CI)\n'
  fi

  # (d) PATH_NOTE ~/bin fallback SUCCESS path: no writable dir on PATH but HOME set → the shim is
  #     written into $HOME/bin, PATH_NOTE fires, exit 0, and the 'may not be on your PATH' note is
  #     emitted. The only prior coverage of the fallback was the HOME-unset *refusal*; this pins
  #     the success half. Skip under root (the read-only PATH dir would read writable).
  if [ "$(id -u)" -ne 0 ]; then
    TPN_RO="$(mktemp -d)"; build_stub_bin "$TPN_RO"; make_fake_python "$TPN_RO/python" "3.11.8" 3 11
    chmod 0555 "$TPN_RO"
    TPN_HOME="$(mktemp -d)"
    if [ ! -w "$TPN_RO" ]; then
      PPS_PN_OUT="$(HOME="$TPN_HOME" PATH="$TPN_RO" bash "$PPS" --apply 2>&1)"; PPS_PN_RC=$?
      assert_eq "#225 pps: ~/bin fallback success → exit 0" "0" "$PPS_PN_RC"
      assert_eq "#225 pps: ~/bin fallback success → shim written into \$HOME/bin" "yes" \
        "$([ -f "$TPN_HOME/bin/python3" ] && echo yes || echo no)"
      assert_eq "#225 pps: ~/bin fallback success → 'may not be on your PATH' note emitted" "yes" \
        "$(printf '%s' "$PPS_PN_OUT" | grep -qi 'may not be on your PATH' && echo yes || echo no)"
    fi
    chmod 0755 "$TPN_RO"
    rm -rf "$TPN_RO" "$TPN_HOME"
  else
    printf '  SKIP  #225 pps: ~/bin fallback success path (root bypasses the -w bit; verified on non-root CI)\n'
  fi

  # ── preflight resolves to a two-word `py -3` alternate: the SC2086 word-split hazard on
  #    preflight's unquoted $PYTHON must be exercised on the PREFLIGHT side too (the provisioner
  #    side has TPY3, but a regression that quoted "$PYTHON" would break `py -3` in preflight while
  #    passing the provisioner test). A py-3-only host (fake `py -3` delegate, no python3/python)
  #    with noyaml drives $PYTHON="py -3" through the PyYAML hint printf. (Review finding.) ──
  TPYPRE="$(mktemp -d)"; build_stub_bin "$TPYPRE"
  make_fake_python "$TPYPRE/_py3delegate" "3.11.1" 3 11 noyaml   # noyaml → PyYAML check fails → hint fires
  make_fake_py "$TPYPRE/py" "$TPYPRE/_py3delegate"               # `py -3` resolves; no python3, no python
  PF_PY3_OUT="$(PATH="$TPYPRE" bash "$PREFLIGHT_SH" 2>&1)"
  assert_eq "#225 preflight: py-3-only host → provisioner pointer fires (alternate resolved)" "yes" \
    "$(printf '%s' "$PF_PY3_OUT" | grep -q 'provision-python3-shim.sh' && echo yes || echo no)"
  assert_eq "#225 preflight: py-3-only host → PyYAML hint names the resolved 'py -3' (unquoted \$PYTHON word-splits)" "yes" \
    "$(printf '%s' "$PF_PY3_OUT" | grep -qF "'py -3 -m pip install pyyaml'" && echo yes || echo no)"
  rm -rf "$TPYPRE"

  # ── AC8: install.sh delegates to the provisioner on the no-python3/alternate path; not when python3 works. ──
  INSTALL_SH="$LIB/../install.sh"
  REPO_ROOT="$(cd "$LIB/.." && pwd)"
  T8="$(mktemp -d)"; build_stub_bin "$T8"; make_fake_python "$T8/python" "3.11.0" 3 11
  OFFER_OUT="$(PATH="$T8" bash -c "DEVFLOW_SELFTEST=1 . \"$INSTALL_SH\"; offer_python3_shim \"$REPO_ROOT\"" 2>&1)"
  assert_eq "#225 install.sh: no python3 → delegates to provision-python3-shim.sh (AC8)" "yes" \
    "$(printf '%s' "$OFFER_OUT" | grep -q 'devflow-python:' && echo yes || echo no)"
  T8B="$(mktemp -d)"; build_stub_bin "$T8B"; make_fake_python "$T8B/python3" "3.12.0" 3 12
  OFFER_OUT_B="$(PATH="$T8B" bash -c "DEVFLOW_SELFTEST=1 . \"$INSTALL_SH\"; offer_python3_shim \"$REPO_ROOT\"" 2>&1)"
  assert_eq "#225 install.sh: python3 present → NO delegation (AC8)" "no" \
    "$(printf '%s' "$OFFER_OUT_B" | grep -q 'devflow-python:' && echo yes || echo no)"
  # Broken-but-present python3 + a >=3.11 alternate: offer_python3_shim probes RUNNABILITY
  # (`python3 -c 'pass'`), mirroring preflight's happy-path gate, so a python3 that is on PATH
  # but does not execute must NOT short-circuit the offer — it falls through and delegates to
  # the provisioner. A bare `command -v python3` would wrongly skip the offer on exactly the
  # broken-Windows-interpreter class this change targets. (Review finding: install.sh symmetry.)
  T8C="$(mktemp -d)"; build_stub_bin "$T8C"; make_fake_python "$T8C/python" "3.11.4" 3 11
  printf '#!/bin/sh\nexit 127\n' > "$T8C/python3"; chmod +x "$T8C/python3"  # present but never runs
  OFFER_OUT_C="$(PATH="$T8C" bash -c "DEVFLOW_SELFTEST=1 . \"$INSTALL_SH\"; offer_python3_shim \"$REPO_ROOT\"" 2>&1)"
  assert_eq "#225 install.sh: broken-but-present python3 → still delegates to the provisioner" "yes" \
    "$(printf '%s' "$OFFER_OUT_C" | grep -q 'devflow-python:' && echo yes || echo no)"
  rm -rf "$T8C"
  # A provisioner REFUSAL (non-zero rc) must be surfaced with its rc and NOT abort the install —
  # the `bash "$prov" || { rc=$?; log "...rc $rc..." }` branch. Every other install test runs a
  # >=3.11 host where the plan-mode provisioner exits 0, so this branch was untested. Use a
  # too-old-only host ($T4B: python2/too-old, no python3) → offer delegates (plan-only), the
  # provisioner exits 2 (too-old refusal, before the plan/apply split), the offer surfaces the
  # rc and returns 0. (Review finding: rc-surfaced-continues contract untested.)
  OFFER_OUT_R="$(PATH="$T4B" bash -c "DEVFLOW_SELFTEST=1 . \"$INSTALL_SH\"; offer_python3_shim \"$REPO_ROOT\"; echo \"ret=\$?\"" 2>&1)"
  assert_eq "#225 install.sh: provisioner refusal (rc≠0) → surfaced with the rc, install continues" "yes" \
    "$(printf '%s' "$OFFER_OUT_R" | grep -q 'exited non-zero (rc' && echo yes || echo no)"
  assert_eq "#225 install.sh: provisioner refusal → offer_python3_shim still returns 0 (non-aborting)" "yes" \
    "$(printf '%s' "$OFFER_OUT_R" | grep -q 'ret=0' && echo yes || echo no)"

  # ── AC11 (#225) RETIRED by #271. This was a branch-wide `.github`-freeze
  #    (`git diff --name-only origin/main -- .github` must be empty), written to
  #    assert #225's own python-shim change touched no `.github/` path. As a
  #    STANDING suite assertion it is over-broad: it fires on EVERY later branch
  #    that legitimately edits `.github/` — e.g. #271 itself, which adds the
  #    `Bash(.prflow/vendor/prflow/scripts/run-jq.sh:*)` grant to
  #    devflow-implement.yml + devflow-runner.yml + devflow.yml so the
  #    cloud-governed skills can invoke the run-jq.sh wrapper. It cannot
  #    distinguish #225's diff from any
  #    other, so it can only be satisfied by never changing `.github/` again —
  #    which is not a real invariant. The load-bearing `.github/` invariants that
  #    DO warrant a standing guard (the workflow partition invariant, per-workflow
  #    allowlist correctness, the vendored-path/exec-bit contracts, the react-to-
  #    trigger wiring) are each covered by their own dedicated tests elsewhere in
  #    this suite, so retiring this catch-all loses no real coverage.

  # ── AC12: the three docs document the Windows interpreter-resolution path. ──
  for _doc in CONTRIBUTING.md docs/internal/install.md docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md; do
    assert_eq "#225 docs: $_doc documents the python3 resolution path (AC12)" "yes" \
      "$(grep -q 'provision-python3-shim.sh' "$REPO_ROOT/$_doc" && echo yes || echo no)"
  done
fi

# ────────────────────────────────────────────────────────────────────────────
echo "gh binary resolution: resolve-gh.sh / preflight.sh gh path (issue #245)"
# ────────────────────────────────────────────────────────────────────────────
# The sibling of the #225 python-resolution block, for `gh`. On Windows/WSL a
# non-executable `gh` shim (a Python-provided `gh` with a Windows shebang) can
# shadow the real GitHub CLI: `command -v gh` succeeds but `gh --version` fails
# at exec time. devflow_resolve_gh verifies EXECUTION, not presence, so it rejects
# the shim in favor of a runnable `gh.exe`. Fixtures below use bad-shebang scripts
# (exec bit set, cannot run) to reproduce the #3493 break faithfully.
RESOLVE_GH_SH="$LIB/resolve-gh.sh"
PREFLIGHT_SH="$LIB/preflight.sh"

# Static/source hygiene (mirrors the resolve-python.sh checks).
assert_eq "#245 resolve-gh.sh: file exists" "yes" "$([ -f "$RESOLVE_GH_SH" ] && echo yes || echo no)"
assert_eq "#245 resolve-gh.sh: SPDX header present" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$RESOLVE_GH_SH" && echo yes || echo no)"
assert_eq "#245 resolve-gh.sh: defines devflow_resolve_gh" "yes" \
  "$(grep -q 'devflow_resolve_gh()' "$RESOLVE_GH_SH" && echo yes || echo no)"
assert_eq "#245 resolve-gh.sh: probes with '--version' only (network/auth-free)" "yes" \
  "$(grep -q -- '--version' "$RESOLVE_GH_SH" && echo yes || echo no)"
assert_eq "#245 resolve-gh.sh: sets no 'set -e'/'set -u' (safe to source)" "no" \
  "$(grep -qE '^[[:space:]]*set -[eu]' "$RESOLVE_GH_SH" && echo yes || echo no)"
# AC3: the gh.exe fallback candidate is referenced by name only — no absolute or
# owner-specific install path is hardcoded.
assert_eq "#245 resolve-gh.sh: gh.exe candidate referenced by name only (no path separator)" "yes" \
  "$(grep -qE '(^|[^/])gh\.exe' "$RESOLVE_GH_SH" && ! grep -qE '/[^ ]*gh\.exe' "$RESOLVE_GH_SH" && echo yes || echo no)"

# ── T1 (AC1, AC2) — defect reproduction: a non-executable (bad-shebang) `gh`
#    earlier on PATH plus a runnable `gh.exe` resolves to `gh.exe`. ──
GHT1="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$GHT1/gh"; chmod +x "$GHT1/gh"
cat > "$GHT1/gh.exe" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "gh version 2.stub (stub)"; exit 0; }
exit 0
STUB
chmod +x "$GHT1/gh.exe"
T1_SEL="$(env -u DEVFLOW_GH PATH="$GHT1:$PATH" bash -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"
assert_eq "#245 T1: bad-shebang gh rejected, runnable gh.exe chosen (execution-verified)" "gh.exe" "$T1_SEL"

# ── T2 (AC4) — DEVFLOW_GH override wins and never probes `gh --version`. ──
GHT2="$(mktemp -d)"
cat > "$GHT2/gh-stub" <<'STUB'
#!/usr/bin/env bash
touch "$(dirname "$0")/.probed"
[ "$1" = "--version" ] && { echo "gh version stub"; exit 0; }
exit 0
STUB
chmod +x "$GHT2/gh-stub"
T2_SEL="$(DEVFLOW_GH="$GHT2/gh-stub" bash -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"
assert_eq "#245 T2: DEVFLOW_GH override returned verbatim (highest precedence)" "$GHT2/gh-stub" "$T2_SEL"
assert_eq "#245 T2: override path never probes gh --version (stub not invoked)" "no" \
  "$([ -f "$GHT2/.probed" ] && echo yes || echo no)"

# ── T3 (AC8) — a runnable `gh` on PATH resolves to `gh` on the first probe. ──
GHT3="$(mktemp -d)"
cat > "$GHT3/gh" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "gh version 2.stub (stub)"; exit 0; }
exit 0
STUB
chmod +x "$GHT3/gh"
T3_SEL="$(env -u DEVFLOW_GH PATH="$GHT3:$PATH" bash -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"
assert_eq "#245 T3: runnable gh on PATH resolves to 'gh' (no behavior change on Linux/macOS/cloud)" "gh" "$T3_SEL"

# ── Degenerate (AC1 tail) — no runnable candidate → bare `gh` so the caller's
#    best-effort warning path still fires (rc 0 preserved). ──
GHTD="$(mktemp -d)"; ln -s "$(command -v bash)" "$GHTD/bash"
TD_SEL="$(env -u DEVFLOW_GH PATH="$GHTD" "$GHTD/bash" -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"; TD_RC=$?
assert_eq "#245 degenerate: no runnable gh/gh.exe → falls back to bare 'gh'" "gh" "$TD_SEL"
assert_eq "#245 degenerate: fallback still exits 0 (best-effort warning path preserved)" "0" "$TD_RC"

# ── T5 (AC4 tail) — an EMPTY DEVFLOW_GH is NOT an override: it falls through to
#    probing (empty ≠ match-all, the CLAUDE.md bug class). Guards a regression of
#    the `[ -n "${DEVFLOW_GH:-}" ]` guard to a set-but-empty test, which would echo
#    the empty string and break every gh-caller while staying green. ──
T5_SEL="$(DEVFLOW_GH="" PATH="$GHT3:$PATH" bash -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"
assert_eq "#245 T5: empty DEVFLOW_GH falls through to the probe (not echoed verbatim)" "gh" "$T5_SEL"

# ── T6 (AC1 ordering) — when BOTH gh and gh.exe are runnable, gh wins (candidate
#    order gh→gh.exe). T1/T3 both pass under a reversed loop order; this pins it. ──
GHT6="$(mktemp -d)"
cat > "$GHT6/gh" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "gh version 2.stub (stub)"; exit 0; }
exit 0
STUB
cat > "$GHT6/gh.exe" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "gh version 2.stub (stub-exe)"; exit 0; }
exit 0
STUB
chmod +x "$GHT6/gh" "$GHT6/gh.exe"
T6_SEL="$(env -u DEVFLOW_GH PATH="$GHT6:$PATH" bash -c ". \"$RESOLVE_GH_SH\"; devflow_resolve_gh")"
assert_eq "#245 T6: both runnable → gh chosen over gh.exe (candidate order preserved)" "gh" "$T6_SEL"

# ── AC5 / preflight — a present-but-unrunnable `gh` is reported at preflight with
#    a remedy (execution-verified), not silently passed. Shadow BOTH candidates —
#    bad-shebang gh AND bad-shebang gh.exe — so the resolver's degenerate path is
#    forced on every host. Shadowing only `gh` is NOT hermetic: on a WSL host with
#    Windows gh.exe interop the resolver would find the real /mnt/c/.../gh.exe and
#    preflight would (correctly) pass, failing this test on the very platform the
#    resolver targets. git/jq/python3 stay real (only gh is broken). ──
GHTP="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$GHTP/gh"; chmod +x "$GHTP/gh"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$GHTP/gh.exe"; chmod +x "$GHTP/gh.exe"
PF_GH_OUT="$(PATH="$GHTP:$PATH" bash "$PREFLIGHT_SH" 2>&1)"; PF_GH_RC=$?
assert_eq "#245 preflight: unrunnable gh shim → exit non-zero (AC5)" "yes" \
  "$([ "$PF_GH_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#245 preflight: unrunnable gh shim → \"no working 'gh'\" remedy, not silent pass (AC5)" "yes" \
  "$(printf '%s' "$PF_GH_OUT" | grep -q "no working 'gh'" && echo yes || echo no)"

# ── AC5b / preflight — DEVFLOW_GH set to a BROKEN binary: the resolver echoes the
#    override with no probe (by contract), but preflight's re-probe of the chosen
#    invocation must still catch it and name the resolved string in the remedy. A
#    refactor that skips the re-probe when DEVFLOW_GH is set would fail open
#    silently — this pins the override-wins → re-probe-catches interaction. ──
PF_OVR_OUT="$(DEVFLOW_GH="$GHTP/gh" bash "$PREFLIGHT_SH" 2>&1)"; PF_OVR_RC=$?
assert_eq "#245 preflight: broken DEVFLOW_GH override → exit non-zero (re-probe catches it)" "yes" \
  "$([ "$PF_OVR_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#245 preflight: broken DEVFLOW_GH override → remedy names the resolved binary" "yes" \
  "$(printf '%s' "$PF_OVR_OUT" | grep -q "no working 'gh'.*$GHTP/gh" && echo yes || echo no)"

# ── T4 (AC6) — a Python helper run with DEVFLOW_GH pointing at a stub invokes the
#    stub, not bare `gh`. parse-acs.py shells `gh issue view … --json body`. ──
GHT4="$(mktemp -d)"
cat > "$GHT4/gh" <<'STUB'
#!/usr/bin/env bash
touch "$(dirname "$0")/.called"
# parse-acs.py calls: gh issue view N --json body -q .body
cat <<'BODY'
## Acceptance Criteria
- [ ] devflow-gh-stub-marker criterion
BODY
exit 0
STUB
chmod +x "$GHT4/gh"
PARSE_ACS="$LIB/../scripts/parse-acs.py"
T4_OUT="$(DEVFLOW_GH="$GHT4/gh" python3 "$PARSE_ACS" --issue 1 2>/dev/null)"
assert_eq "#245 T4: Python helper routes gh through DEVFLOW_GH stub (stub invoked)" "yes" \
  "$([ -f "$GHT4/.called" ] && echo yes || echo no)"
assert_eq "#245 T4: Python helper consumed the stub's output (not bare gh)" "yes" \
  "$(printf '%s' "$T4_OUT" | grep -q 'devflow-gh-stub-marker' && echo yes || echo no)"

# ── T7 (AC4 integration) — a REAL converted shell helper, run with DEVFLOW_GH
#    UNSET under a crafted PATH (bad-shebang gh + runnable gh.exe), actually
#    consults the resolver and invokes gh.exe. Guards a helper that sources the
#    resolver but still hardcodes literal `gh` at its call site — the static
#    peer-completeness grep below would stay green on that regression. ──
GHT7="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$GHT7/gh"; chmod +x "$GHT7/gh"
cat > "$GHT7/gh.exe" <<'STUB'
#!/usr/bin/env bash
case "$1" in
  --version) echo "gh version 2.stub (stub-exe)"; exit 0 ;;
esac
# ensure-label.sh calls `<gh> api --method POST .../labels` — record that gh.exe
# (not bare gh) was the binary invoked, then report the benign already-exists shape.
touch "$(dirname "$0")/.exe-called"
echo '{"errors":[{"code":"already_exists"}]}' >&2; exit 1
STUB
chmod +x "$GHT7/gh.exe"
env -u DEVFLOW_GH PATH="$GHT7:$PATH" bash "$LIB/../scripts/ensure-label.sh" DevFlow >/dev/null 2>&1; T7_RC=$?
assert_eq "#245 T7: unset-DEVFLOW_GH helper consults the resolver and invokes gh.exe (not bare gh)" "yes" \
  "$([ -f "$GHT7/.exe-called" ] && echo yes || echo no)"
assert_eq "#245 T7: helper preserves its best-effort exit 0 under the resolved gh.exe" "0" "$T7_RC"

# ── T8 (AC6 negative) — the Python empty-DEVFLOW_GH fallback: `os.environ.get(
#    "DEVFLOW_GH") or "gh"` treats an EMPTY override as fall-through-to-gh (the
#    Python analogue of T5). A regression to `os.environ.get("DEVFLOW_GH","gh")`
#    would echo "" and break every Python gh-caller while T4 stays green. ──
GHT8="$(mktemp -d)"
cat > "$GHT8/gh" <<'STUB'
#!/usr/bin/env bash
touch "$(dirname "$0")/.called"
cat <<'BODY'
## Acceptance Criteria
- [ ] devflow-gh-empty-marker criterion
BODY
exit 0
STUB
chmod +x "$GHT8/gh"
T8_OUT="$(DEVFLOW_GH="" PATH="$GHT8:$PATH" python3 "$LIB/../scripts/parse-acs.py" --issue 1 2>/dev/null)"
assert_eq "#245 T8: empty DEVFLOW_GH in a Python helper falls back to 'gh' (stub invoked)" "yes" \
  "$([ -f "$GHT8/.called" ] && echo yes || echo no)"
assert_eq "#245 T8: empty-override Python helper consumed the stub's output (not an empty argv0)" "yes" \
  "$(printf '%s' "$T8_OUT" | grep -q 'devflow-gh-empty-marker' && echo yes || echo no)"

# ── T9 (AC6 negative) — the headline #3493 fix, exercised end-to-end: pointing
#    DEVFLOW_GH at a non-executable file makes subprocess.run raise OSError
#    (ENOEXEC), which parse-acs.py's `except (subprocess.CalledProcessError,
#    OSError)` must convert into a structured stderr breadcrumb + non-zero exit —
#    never a raw Python traceback. A regression dropping OSError from that except
#    tuple (or from any of the other three Python gh-callers, per the static
#    per-script pins below) would let a raw traceback escape while every other
#    #245 test — which only ever points DEVFLOW_GH at a *runnable* stub — stays
#    green. ──
GHT9="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$GHT9/gh-broken"; chmod +x "$GHT9/gh-broken"
T9_OUT="$(DEVFLOW_GH="$GHT9/gh-broken" python3 "$LIB/../scripts/parse-acs.py" --issue 1 2>&1 >/dev/null)"; T9_RC=$?
assert_eq "#245 T9: unrunnable DEVFLOW_GH override → non-zero exit (OSError converted, not swallowed)" "yes" \
  "$([ "$T9_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#245 T9: unrunnable DEVFLOW_GH override → structured breadcrumb, not a raw Python traceback" "yes" \
  "$(printf '%s' "$T9_OUT" | grep -q 'gh issue view failed' && ! printf '%s' "$T9_OUT" | grep -q 'Traceback (most recent call last)' && echo yes || echo no)"

# ── T9b — same OSError-conversion class as T9, but for workpad.py's `_repo_full`
#    (every workpad.py subcommand's first gh call, hence the highest-traffic call
#    site of the four Python gh-callers — flagged separately because a class-level
#    fix for T9 alone would leave this specific, highest-traffic site unverified). ──
T9B_OUT="$(DEVFLOW_GH="$GHT9/gh-broken" python3 "$LIB/../scripts/workpad.py" id 1 2>&1 >/dev/null)"; T9B_RC=$?
assert_eq "#245 T9b: workpad.py _repo_full, unrunnable DEVFLOW_GH override → non-zero exit" "yes" \
  "$([ "$T9B_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#245 T9b: workpad.py _repo_full, unrunnable DEVFLOW_GH override → structured breadcrumb, not a raw Python traceback" "yes" \
  "$(printf '%s' "$T9B_OUT" | grep -q 'repo lookup' && ! printf '%s' "$T9B_OUT" | grep -q 'Traceback (most recent call last)' && echo yes || echo no)"

# ── T10 (AC5 complement) — preflight's "gh not installed" branch, distinct from
#    the AC5 shim branch above. AC5's fixture always plants a bad-shebang gh/
#    gh.exe, so `command -v gh` always succeeds and preflight's if/else always
#    takes the shim (else) branch — the "nothing named gh/gh.exe on PATH" if
#    branch is never actually exercised, even though both branches share the
#    pinned "no working 'gh'" literal and a broken if-branch message would stay
#    invisible to AC5 alone. Curate a PATH with only the other required tools
#    (no gh/gh.exe anywhere) so `command -v gh` and `command -v gh.exe` both
#    genuinely fail. ──
GHT10="$(mktemp -d)"
for _t10_bin in git jq python3 dirname cat grep sed cut tr head; do
  _t10_path="$(command -v "$_t10_bin" 2>/dev/null)"
  [ -n "$_t10_path" ] && ln -sf "$_t10_path" "$GHT10/$_t10_bin"
done
# `env PATH=<restricted> bash …` execs "bash" by searching the NEW (restricted)
# PATH, not the caller's current one — so bash itself must be resolved to its
# full path first, or the restricted PATH (which deliberately excludes real
# gh) would also make `bash` unresolvable and the test would spuriously fail
# on an `env` error rather than exercising preflight at all.
_T10_BASH_BIN="$(command -v bash)"
PF_NI_OUT="$(env -u DEVFLOW_GH PATH="$GHT10" "$_T10_BASH_BIN" "$PREFLIGHT_SH" 2>&1)"; PF_NI_RC=$?
assert_eq "#245 T10: preflight, gh genuinely absent (no gh/gh.exe on PATH) → exit non-zero" "yes" \
  "$([ "$PF_NI_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#245 T10: preflight, gh genuinely absent → \"not installed\" wording (not the shim wording)" "yes" \
  "$(printf '%s' "$PF_NI_OUT" | grep -q "no working 'gh' — the GitHub CLI is not installed" && echo yes || echo no)"
assert_eq "#245 T10: preflight, gh genuinely absent → does NOT emit the shim-specific remedy" "no" \
  "$(printf '%s' "$PF_NI_OUT" | grep -q 'does not execute' && echo yes || echo no)"

# ── Peer-completeness pin (2.3.0a): every gh-calling shell helper routes through
#    the resolver — no helper retains the bare `: "${DEVFLOW_GH:=gh}"` default, no
#    non-comment bare `gh <subcommand>` call survives outside the resolver (the
#    grep below — best-effort: diagnostic echo/printf lines are excluded, so a
#    call sharing a line with a diagnostic is not covered; T7 is the dynamic
#    backstop), and every Python gh-caller reads DEVFLOW_GH with no argv0 "gh"
#    literal left behind. ──
DGH_ROOT="$(cd "$LIB/.." && pwd)"
DGH_HARDCODE="$(grep -rlF 'DEVFLOW_GH:=gh}' "$DGH_ROOT/scripts" "$DGH_ROOT/lib" --include='*.sh' 2>/dev/null | grep -v '/test/' | grep -c . || true)"  # tree-walk-ok: scoped to $DGH_ROOT/scripts and $DGH_ROOT/lib, which no worktree lives under
assert_eq "#245 peer-completeness: no shell helper retains the bare DEVFLOW_GH:=gh default" "0" "$DGH_HARDCODE"
# Exclude the resolver itself from the sourcing count (its own header contains the
# literal 'resolve-gh.sh'); without the exclusion the count self-matches to 14 and
# one converted helper could silently drop the sourcing while >=13 stays green.
DGH_SOURCED="$(grep -rlF 'resolve-gh.sh' "$DGH_ROOT/scripts" "$DGH_ROOT/lib" --include='*.sh' 2>/dev/null | grep -v '/test/' | grep -v 'lib/resolve-gh\.sh$' | grep -c . || true)"  # tree-walk-ok: scoped to $DGH_ROOT/scripts and $DGH_ROOT/lib, which no worktree lives under
assert_eq "#245 peer-completeness: >=13 helpers source resolve-gh.sh (all gh-callers converted, resolver excluded from its own count)" "yes" \
  "$([ "$DGH_SOURCED" -ge 13 ] && echo yes || echo no)"
# The bare-call grep the block comment promises: no non-comment, non-diagnostic
# `gh <subcommand>` invocation outside the resolver. Catches a helper that sources
# the resolver but hardcodes `gh` at a call site (the pre-conversion shape of
# authorize-actor.sh / react-to-trigger.sh) — the two pins above stay green on it.
DGH_BARE="$(grep -rnE '(^|[[:space:]`;|&(])gh[[:space:]]+(api|pr|issue|label|repo|auth|search|run|workflow)([[:space:]]|$)' \
  "$DGH_ROOT/scripts" "$DGH_ROOT/lib" --include='*.sh' 2>/dev/null \
  | grep -v '/test/' | grep -v 'resolve-gh\.sh:' | grep -vE ':[[:space:]]*#' | grep -vE '(echo|printf) ' | grep -c . || true)"  # tree-walk-ok: scoped to $DGH_ROOT/scripts and $DGH_ROOT/lib, which no worktree lives under
assert_eq "#245 peer-completeness: no non-comment bare gh <subcommand> call survives outside the resolver" "0" "$DGH_BARE"
# Per-script Python routing pins: each enumerated Python gh-caller reads the
# documented DEVFLOW_GH override and keeps no bare-"gh" argv0 literal. T4/T8
# exercise parse-acs.py dynamically; these static pins keep a revert in any of
# the others (the silent-label-loss regression of #3493) from staying green.
# export-workflow-lifecycle-census.py joined the set in PR #531 (issue #527);
# build-experiment-records.py was the pre-existing member the PR #531
# early-shadow completeness critic's independent enumeration surfaced
# (grep -l DEVFLOW_GH over scripts/*.py) — the loop had under-counted it;
# preflight.py (issue #547) is the newest — the early dependency-preflight gate's
# `gh issue view` state/body reads route through the same DEVFLOW_GH pattern.
# check-completion-evidence.py (issue #550) reads gh only on its remote-trace arm
# (`gh api` for a pr-thread / follow-up-issue trace, `gh repo view` for own-repo
# scope) — the same DEVFLOW_GH-no-probe pattern.
for DGH_PY in workpad.py file-deferrals.py match-deferrals.py parse-acs.py export-workflow-lifecycle-census.py build-experiment-records.py preflight.py check-completion-evidence.py; do
  assert_eq "#245 python routing: $DGH_PY reads DEVFLOW_GH (or-\"gh\" form)" "1" \
    "$(grep -cF 'os.environ.get("DEVFLOW_GH") or "gh"' "$DGH_ROOT/scripts/$DGH_PY" || true)"
  assert_eq "#245 python routing: $DGH_PY keeps no bare-\"gh\" argv0 literal" "0" \
    "$(grep -cE '\[[[:space:]]*['"'"'\"]gh['"'"'\"][[:space:]]*,' "$DGH_ROOT/scripts/$DGH_PY" || true)"
done
rm -rf "$GHT1" "$GHT2" "$GHT3" "$GHTD" "$GHTP" "$GHT4" "$GHT6" "$GHT7" "$GHT8" "$GHT9" "$GHT10"

# ────────────────────────────────────────────────────────────────────────────
echo "shared binary resolver + path normalization: resolve-bin.sh / normalize-path.sh / jq routing (issue #247)"
# ────────────────────────────────────────────────────────────────────────────
# Generalizes the #245 gh pattern: resolve-bin.sh is the single shared
# execution-verified resolver (DEVFLOW_<TOOL> override → <tool>/<tool>.exe
# --version probe → bare fallback), resolve-gh.sh delegates to it, jq routes
# through it (DEVFLOW_JQ), and normalize-path.sh converts Windows-form paths
# to the running shell's POSIX form (wslpath → cygpath → env-detected → echo
# unchanged with a stderr breadcrumb).
RESOLVE_BIN_SH="$LIB/resolve-bin.sh"
NORMALIZE_PATH_SH="$LIB/normalize-path.sh"
RESOLVE_JQ_SH="$LIB/resolve-jq.sh"

# Restricted-PATH sandbox builder shared by the fixtures below: symlink only the
# named tools into the dir so `command -v` genuinely fails for everything else.
_mk_restricted() {  # dir tool...
  local _mr_d="$1" _mr_b _mr_p; shift
  for _mr_b in "$@"; do
    _mr_p="$(command -v "$_mr_b" 2>/dev/null)"
    [ -n "$_mr_p" ] && ln -sf "$_mr_p" "$_mr_d/$_mr_b"
  done
  return 0
}

# Static/source hygiene (mirrors the resolve-gh.sh checks).
assert_eq "#247 resolve-bin.sh: file exists" "yes" "$([ -f "$RESOLVE_BIN_SH" ] && echo yes || echo no)"
assert_eq "#247 resolve-bin.sh: SPDX header present" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$RESOLVE_BIN_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-bin.sh: defines devflow_resolve_bin" "yes" \
  "$(grep -q 'devflow_resolve_bin()' "$RESOLVE_BIN_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-bin.sh: probes with '--version' only (network/auth-free)" "yes" \
  "$(grep -q -- '--version' "$RESOLVE_BIN_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-bin.sh: sets no 'set -e'/'set -u' (safe to source)" "no" \
  "$(grep -qE '^[[:space:]]*set -[eu]' "$RESOLVE_BIN_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-bin.sh: candidates referenced by name only (no path separator before .exe)" "yes" \
  "$([ -f "$RESOLVE_BIN_SH" ] && ! grep -qE '/[^ ]*\.exe' "$RESOLVE_BIN_SH" && echo yes || echo no)"
assert_eq "#247 normalize-path.sh: file exists" "yes" "$([ -f "$NORMALIZE_PATH_SH" ] && echo yes || echo no)"
assert_eq "#247 normalize-path.sh: SPDX header present" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$NORMALIZE_PATH_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 normalize-path.sh: defines devflow_normalize_path" "yes" \
  "$(grep -q 'devflow_normalize_path()' "$NORMALIZE_PATH_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 normalize-path.sh: sets no 'set -e'/'set -u' (safe to source)" "no" \
  "$(grep -qE '^[[:space:]]*set -[eu]' "$NORMALIZE_PATH_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-jq.sh: file exists" "yes" "$([ -f "$RESOLVE_JQ_SH" ] && echo yes || echo no)"
assert_eq "#247 resolve-jq.sh: SPDX header present" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$RESOLVE_JQ_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-jq.sh: sets no 'set -e'/'set -u' (safe to source)" "no" \
  "$(grep -qE '^[[:space:]]*set -[eu]' "$RESOLVE_JQ_SH" 2>/dev/null && echo yes || echo no)"
assert_eq "#247 resolve-jq.sh: delegates via devflow_resolve_bin jq" "yes" \
  "$(grep -qE 'devflow_resolve_bin[[:space:]]+jq' "$RESOLVE_JQ_SH" 2>/dev/null && echo yes || echo no)"

# ── T0 (Linux/macOS/cloud no-change AC) — a runnable `jq` resolves to `jq` on
#    the first probe. ──
JQT0="$(mktemp -d)"
cat > "$JQT0/jq" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "jq-stub-1.7"; exit 0; }
exit 0
STUB
chmod +x "$JQT0/jq"
T0_SEL="$(env -u DEVFLOW_JQ PATH="$JQT0:$PATH" bash -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"
assert_eq "#247 T0: runnable jq on PATH resolves to 'jq' (no behavior change on Linux/macOS/cloud)" "jq" "$T0_SEL"
T0B_SEL="$(env -u DEVFLOW_JQ PATH="$JQT0:$PATH" bash -c "set -euo pipefail; . \"$RESOLVE_JQ_SH\"; printf %s \"\$DEVFLOW_JQ\"")"
assert_eq "#247 T0b: sourcing resolve-jq.sh under set -euo pipefail sets DEVFLOW_JQ" "jq" "$T0B_SEL"

# ── T1 (defect reproduction) — a non-executable (bad-shebang) `jq` earlier on
#    PATH plus a runnable `jq.exe` resolves to `jq.exe` (execution-verified). ──
JQT1="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$JQT1/jq"; chmod +x "$JQT1/jq"
cat > "$JQT1/jq.exe" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "jq-stub-1.7-exe"; exit 0; }
exit 0
STUB
chmod +x "$JQT1/jq.exe"
T1_JQ_SEL="$(env -u DEVFLOW_JQ PATH="$JQT1:$PATH" bash -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"
assert_eq "#247 T1: bad-shebang jq rejected, runnable jq.exe chosen (execution-verified)" "jq.exe" "$T1_JQ_SEL"

# ── T2 — DEVFLOW_JQ override wins verbatim and never probes `--version`. ──
JQT2="$(mktemp -d)"
cat > "$JQT2/jq-stub" <<'STUB'
#!/usr/bin/env bash
touch "$(dirname "$0")/.probed"
exit 0
STUB
chmod +x "$JQT2/jq-stub"
T2_JQ_SEL="$(DEVFLOW_JQ="$JQT2/jq-stub" bash -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"
assert_eq "#247 T2: DEVFLOW_JQ override returned verbatim (highest precedence)" "$JQT2/jq-stub" "$T2_JQ_SEL"
assert_eq "#247 T2: override path never probes --version (stub not invoked)" "no" \
  "$([ -f "$JQT2/.probed" ] && echo yes || echo no)"

# ── T2b — an EMPTY DEVFLOW_JQ is NOT an override: falls through to the probe
#    (empty ≠ match-all, the CLAUDE.md bug class; mirrors #245 T5). ──
T2B_SEL="$(DEVFLOW_JQ="" PATH="$JQT0:$PATH" bash -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"
assert_eq "#247 T2b: empty DEVFLOW_JQ falls through to the probe (not echoed verbatim)" "jq" "$T2B_SEL"

# ── T2d — the override must win WITHOUT tr on PATH (pure-bash derivation for
#    the known tools): a degenerate PATH must never silently bypass
#    DEVFLOW_<TOOL> and probe/execute the stub the contract protects. ──
JQT2D="$(mktemp -d)"
ln -s "$(command -v bash)" "$JQT2D/bash"
T2D_SEL="$(DEVFLOW_JQ=/stub/jq PATH="$JQT2D" "$JQT2D/bash" -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"
assert_eq "#247 T2d: DEVFLOW_JQ override honored with NO tr on PATH (pure-bash known-tool derivation)" "/stub/jq" "$T2D_SEL"

# ── Degenerate — no runnable candidate → bare tool echoed, rc 0 (best-effort
#    contract preserved: existing error paths downstream stay unchanged). ──
JQTD="$(mktemp -d)"; ln -s "$(command -v bash)" "$JQTD/bash"
ln -s "$(command -v tr)" "$JQTD/tr" 2>/dev/null
TD_JQ_SEL="$(env -u DEVFLOW_JQ PATH="$JQTD" "$JQTD/bash" -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin jq")"; TD_JQ_RC=$?
assert_eq "#247 degenerate: no runnable jq/jq.exe → falls back to bare 'jq'" "jq" "$TD_JQ_SEL"
assert_eq "#247 degenerate: fallback still exits 0 (best-effort contract preserved)" "0" "$TD_JQ_RC"

# ── T3 (gh refactor regression) — resolve-gh.sh now delegates to the shared
#    resolver; DEVFLOW_GH precedence and stub semantics must be unchanged. The
#    full #245 block above is the deep regression net; this pins the delegation
#    itself (resolve-gh.sh sources resolve-bin.sh and stays a thin wrapper). ──
T3_DELEG="$(DEVFLOW_GH=/fake/devflow-gh bash -c ". \"$LIB/resolve-gh.sh\"; devflow_resolve_gh")"
assert_eq "#247 T3: resolve-gh.sh delegation preserves DEVFLOW_GH override precedence" "/fake/devflow-gh" "$T3_DELEG"
assert_eq "#247 T3: resolve-gh.sh sources the shared resolver (delegation, not a second copy)" "yes" \
  "$(grep -q 'resolve-bin\.sh' "$LIB/resolve-gh.sh" && echo yes || echo no)"
assert_eq "#247 T3: resolve-gh.sh delegates via devflow_resolve_bin gh" "yes" \
  "$(grep -qE 'devflow_resolve_bin[[:space:]]+gh' "$LIB/resolve-gh.sh" && echo yes || echo no)"

# ── T4 (path normalization) — Windows-form input under a stub wslpath, a stub
#    cygpath, the env-detected fallback (uname/MSYSTEM), and POSIX passthrough.
#    uname is STUBBED in the env-detect cases so the assertions are hermetic on
#    every host (a real WSL host's `uname -r` contains "microsoft"). ──
NPT4="$(mktemp -d)"
cat > "$NPT4/wslpath" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "-u" ] && { echo "/mnt/c/from/wslpath"; exit 0; }
exit 1
STUB
chmod +x "$NPT4/wslpath"
T4A="$(PATH="$NPT4:$PATH" bash -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'")"
assert_eq "#247 T4a: wslpath preferred when present" "/mnt/c/from/wslpath" "$T4A"

NPT4B="$(mktemp -d)"
cat > "$NPT4B/cygpath" <<'STUB'
#!/usr/bin/env bash
[ "$1" = "-u" ] && { echo "/c/from/cygpath"; exit 0; }
exit 1
STUB
chmod +x "$NPT4B/cygpath"
# Restricted PATH (no wslpath anywhere) so cygpath is genuinely the first tool.
_mk_restricted "$NPT4B" bash tr grep uname dirname
_NP_BASH_BIN="$(command -v bash)"
T4B="$(PATH="$NPT4B" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'")"
assert_eq "#247 T4b: cygpath used when wslpath absent" "/c/from/cygpath" "$T4B"

# Env-detected fallback, WSL flavor: no wslpath/cygpath on PATH, stub uname
# reporting a microsoft kernel → /mnt/c translation.
NPT4C="$(mktemp -d)"
printf '#!/usr/bin/env bash\necho "5.15.0-microsoft-standard-WSL2"\n' > "$NPT4C/uname"; chmod +x "$NPT4C/uname"
_mk_restricted "$NPT4C" bash tr grep dirname
T4C="$(env -u MSYSTEM PATH="$NPT4C" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'")"
assert_eq "#247 T4c: env-detected WSL fallback (uname microsoft, no tools) → /mnt/c form" "/mnt/c/Users/x" "$T4C"

# Env-detected fallback, MSYS flavor: no tools, non-microsoft uname, MSYSTEM set.
NPT4D="$(mktemp -d)"
printf '#!/usr/bin/env bash\necho "generic-kernel"\n' > "$NPT4D/uname"; chmod +x "$NPT4D/uname"
_mk_restricted "$NPT4D" bash tr grep dirname
T4D="$(MSYSTEM=MINGW64 PATH="$NPT4D" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'")"
assert_eq "#247 T4d: env-detected MSYS fallback (MSYSTEM set, no tools) → /c form" "/c/Users/x" "$T4D"

# Last resort: no tools, no env signal → input unchanged (rc 0) + stderr breadcrumb.
NPT4E="$(mktemp -d)"
printf '#!/usr/bin/env bash\necho "generic-kernel"\n' > "$NPT4E/uname"; chmod +x "$NPT4E/uname"
_mk_restricted "$NPT4E" bash tr grep dirname
T4E_OUT="$(env -u MSYSTEM PATH="$NPT4E" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'" 2>"$NPT4E/stderr")"; T4E_RC=$?
T4E_ERR="$(cat "$NPT4E/stderr")"
assert_eq "#247 T4e: no tool + no env signal → input unchanged" 'C:\Users\x' "$T4E_OUT"
assert_eq "#247 T4e: no tool + no env signal → rc 0 (best-effort)" "0" "$T4E_RC"
assert_eq "#247 T4e: no tool + no env signal → stderr breadcrumb emitted" "yes" \
  "$(printf '%s' "$T4E_ERR" | grep -q 'could not normalize' && echo yes || echo no)"

# POSIX-form passthrough: never touched, no tools consulted, no breadcrumb.
T4F="$(bash -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path '/home/user/x'" 2>&1)"
assert_eq "#247 T4f: non-Windows-form input passes through unchanged (no breadcrumb)" "/home/user/x" "$T4F"

# ── T4k — tr absent from the restricted PATH: the env-detected arm fails
#    CLOSED (input unchanged + tr breadcrumb), never a corrupted /mnt//...
#    path; the SKILL.md block behaves identically (lockstep on this branch). ──
NPT4K="$(mktemp -d)"
printf '#!/usr/bin/env bash\necho "5.15.0-microsoft-standard-WSL2"\n' > "$NPT4K/uname"; chmod +x "$NPT4K/uname"
_mk_restricted "$NPT4K" bash grep dirname
T4K_OUT="$(env -u MSYSTEM PATH="$NPT4K" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'" 2>"$NPT4K/err")"
assert_eq "#247 T4k: tr-less env-detect arm → input unchanged (never /mnt//...)" 'C:\Users\x' "$T4K_OUT"
assert_eq "#247 T4k: tr-less arm leaves the tr breadcrumb" "yes" \
  "$(grep -q 'tr unavailable' "$NPT4K/err" && echo yes || echo no)"
# ── T4k-setE — the header's "safe to source under set -e" contract: a set -e
#    caller sourcing the helper on the same tr-less degenerate PATH must NOT
#    abort at the drive-lowercasing assignment before the empty-drive guard
#    runs. Without the `|| drive=""` fallback the tr-less pipeline's non-zero
#    status trips set -e and the guard never runs. ──
T4KSE_OUT="$(env -u MSYSTEM PATH="$NPT4K" "$_NP_BASH_BIN" -c "set -e; . \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'; printf 'SE_OK\\n'" 2>/dev/null)"; T4KSE_RC=$?
assert_eq "#247 T4k set -e: tr-less source under set -e reaches the guard, never aborts" "yes" \
  "$(printf '%s' "$T4KSE_OUT" | grep -q 'SE_OK' && echo yes || echo no)"
assert_eq "#247 T4k set -e: returns 0 to the set -e caller" "0" "$T4KSE_RC"
assert_eq "#247 T4k set -e: still yields the input unchanged (fail-closed)" 'C:\Users\x' \
  "$(printf '%s' "$T4KSE_OUT" | head -1)"
# ── Preflight jq — execution-verified via the shared resolver, mirroring the
#    #245 gh two-branch diagnosis. Shadow BOTH candidates (bad-shebang jq AND
#    jq.exe) so the degenerate path is forced on every host. ──
JQTP="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$JQTP/jq"; chmod +x "$JQTP/jq"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$JQTP/jq.exe"; chmod +x "$JQTP/jq.exe"
PF_JQ_OUT="$(env -u DEVFLOW_JQ PATH="$JQTP:$PATH" bash "$LIB/preflight.sh" 2>&1)"; PF_JQ_RC=$?
assert_eq "#247 preflight: unrunnable jq shim → exit non-zero" "yes" \
  "$([ "$PF_JQ_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#247 preflight: unrunnable jq shim → \"no working 'jq'\" remedy naming DEVFLOW_JQ, not silent pass" "yes" \
  "$(printf '%s' "$PF_JQ_OUT" | grep -q "no working 'jq'" && printf '%s' "$PF_JQ_OUT" | grep -q 'DEVFLOW_JQ' && echo yes || echo no)"

# jq genuinely absent (nothing named jq/jq.exe on PATH) → the "not installed"
# branch wording, not the shim wording (mirrors #245 T10's curated PATH).
JQT10="$(mktemp -d)"
_mk_restricted "$JQT10" git gh python3 dirname cat grep sed cut tr head
_JQ10_BASH_BIN="$(command -v bash)"
PF_JQNI_OUT="$(env -u DEVFLOW_JQ PATH="$JQT10" "$_JQ10_BASH_BIN" "$LIB/preflight.sh" 2>&1)"; PF_JQNI_RC=$?
assert_eq "#247 preflight: jq genuinely absent → exit non-zero" "yes" \
  "$([ "$PF_JQNI_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#247 preflight: jq genuinely absent → \"not installed\" wording (not the shim wording)" "yes" \
  "$(printf '%s' "$PF_JQNI_OUT" | grep -q "no working 'jq' — jq is not installed" && echo yes || echo no)"

# ── T5 (anchor recipe pin, reshaped by #275) — the create-issue anchor recipe no
#    longer carries inline SHELL normalization mirrors: Copilot CLI's inline-bash
#    marshaling drops same-command variable assignments, so the multi-statement
#    mirror blocks were removed and normalization moved to PROMPT time — the agent
#    converts a Windows-form runner-reported base directory with one standalone
#    wslpath/cygpath probe BEFORE substituting it into the single-statement
#    invocation (issue #1856 removed the tool-less drive-letter paraphrase, whose
#    T5b pin retired with it). The preamble's probe mirrors lib/normalize-path.sh's
#    tool-first tier; pin the probe fragment and that lib lockstep reference so a
#    trim of either goes RED.
CI_SKILL="$LIB/../skills/create-issue/SKILL.md"
assert_pin_unique "#247/#275 T5: create-issue preamble carries the prompt-time wslpath probe guidance" \
  "wslpath -u '<path>'" "$CI_SKILL"
assert_pin_unique "#247/#275 T5c: create-issue preamble names lib/normalize-path.sh as the rules' source (lockstep reference)" \
  'lib/normalize-path.sh' "$CI_SKILL"

# ── T6 (jq call-site integration) — a REAL converted helper, run with
#    DEVFLOW_JQ pointing at a recording stub, invokes the stub rather than bare
#    jq. Scope: the stub records ANY invocation (the first is the usability
#    gate probe), so this proves the helper consults DEVFLOW_JQ at all — the
#    static DJQ_BARE grep below is what holds every data-processing call site
#    to the converted form. ──
JQT6="$(mktemp -d)"
cat > "$JQT6/jq-rec" <<'STUB'
#!/usr/bin/env bash
touch "$(dirname "$0")/.called"
exec jq "$@"
STUB
chmod +x "$JQT6/jq-rec"
DEVFLOW_JQ="$JQT6/jq-rec" bash "$LIB/../scripts/detect-project-tools.sh" "$JQT6" >/dev/null 2>&1 || true
assert_eq "#247 T6: converted helper routes jq through DEVFLOW_JQ (stub invoked)" "yes" \
  "$([ -f "$JQT6/.called" ] && echo yes || echo no)"

# ── T4i — a wslpath that exits 0 but prints NOTHING must not yield an empty
#    path ("the caller always gets a usable string"): falls through to the
#    next tier. ──
NPT4I="$(mktemp -d)"
printf '#!/usr/bin/env bash\nexit 0\n' > "$NPT4I/wslpath"; chmod +x "$NPT4I/wslpath"
printf '#!/usr/bin/env bash\necho "5.15.0-microsoft-standard-WSL2"\n' > "$NPT4I/uname"; chmod +x "$NPT4I/uname"
_mk_restricted "$NPT4I" bash tr grep dirname
T4I="$(env -u MSYSTEM PATH="$NPT4I" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'" 2>/dev/null)"
assert_eq "#247 T4i: empty-but-successful wslpath output falls through (never an empty path)" "/mnt/c/Users/x" "$T4I"

# ── T4j — spaces and a lowercase non-C drive letter through the env-detected
#    arm (real anchors look like d:\Program Files\...). ──
T4J="$(env -u MSYSTEM PATH="$NPT4C" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'd:\\Program Files\\x'" 2>/dev/null)"
assert_eq "#247 T4j: spaces + lowercase drive letter normalize (env-detected WSL arm)" "/mnt/d/Program Files/x" "$T4J"

# ── T4g — a PRESENT-but-FAILING wslpath (prints partial output, exits 1) must
#    not contaminate the result: the chain falls through to the next tier and
#    the caller receives ONE clean line (the pre-fix form leaked the partial
#    stdout before the fallback's line). ──
NPT4G="$(mktemp -d)"
printf '#!/usr/bin/env bash\necho "/mnt/partial-garbage"; exit 1\n' > "$NPT4G/wslpath"; chmod +x "$NPT4G/wslpath"
printf '#!/usr/bin/env bash\necho "5.15.0-microsoft-standard-WSL2"\n' > "$NPT4G/uname"; chmod +x "$NPT4G/uname"
_mk_restricted "$NPT4G" bash tr grep dirname
T4G="$(env -u MSYSTEM PATH="$NPT4G" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:\\Users\\x'" 2>/dev/null)"
assert_eq "#247 T4g: failing wslpath falls through cleanly (no partial-output contamination)" "/mnt/c/Users/x" "$T4G"

# ── T4h — forward-slash Windows form (C:/...) through the env-detected arm
#    (the regex and docs both claim it; pin it so an anchor-on-backslash edit
#    goes RED). ──
T4H="$(env -u MSYSTEM PATH="$NPT4C" "$_NP_BASH_BIN" -c ". \"$NORMALIZE_PATH_SH\"; devflow_normalize_path 'C:/Users/x'")"
assert_eq "#247 T4h: forward-slash Windows form normalizes identically (env-detected WSL arm)" "/mnt/c/Users/x" "$T4H"

# ── T7 — PARTIAL-COPY deployments: resolve-jq.sh / resolve-gh.sh present
#    without their sibling resolve-bin.sh must degrade with a breadcrumb, never
#    leave DEVFLOW_JQ empty (jq) or abort set -e callers at source time (gh). ──
JQT7="$(mktemp -d)"
cp "$RESOLVE_JQ_SH" "$JQT7/resolve-jq.sh"
T7_OUT="$(env -u DEVFLOW_JQ bash -c "set -euo pipefail; . \"$JQT7/resolve-jq.sh\"; printf %s \"\$DEVFLOW_JQ\"" 2>"$JQT7/err")"
assert_eq "#247 T7: partial copy (no resolve-bin.sh) → DEVFLOW_JQ falls back to bare 'jq', not empty" "jq" "$T7_OUT"
assert_eq "#247 T7: partial copy → breadcrumb names the missing resolve-bin.sh" "yes" \
  "$(grep -q 'resolve-bin.sh not found or not sourceable beside resolve-jq.sh' "$JQT7/err" && echo yes || echo no)"
cp "$LIB/resolve-gh.sh" "$JQT7/resolve-gh.sh"
T7B_OUT="$(DEVFLOW_GH=/stub/gh bash -c "set -euo pipefail; . \"$JQT7/resolve-gh.sh\"; devflow_resolve_gh" 2>"$JQT7/err-gh")"
assert_eq "#247 T7b: partial copy (no resolve-bin.sh) → devflow_resolve_gh degrades to DEVFLOW_GH-or-bare-gh" "/stub/gh" "$T7B_OUT"
assert_eq "#247 T7b: partial copy → gh breadcrumb emitted (no raw set -e abort)" "yes" \
  "$(grep -q 'resolve-bin.sh not found or not sourceable beside resolve-gh.sh' "$JQT7/err-gh" && echo yes || echo no)"
T7C_OUT="$(env -u DEVFLOW_GH bash -c "set -euo pipefail; . \"$JQT7/resolve-gh.sh\"; devflow_resolve_gh" 2>/dev/null)"
assert_eq "#247 T7c: partial copy, no override → degraded devflow_resolve_gh defaults to bare 'gh' (set -u safe)" "gh" "$T7C_OUT"

# ── T7d — sourceability, not just existence: an UNREADABLE resolve-bin.sh
#    beside resolve-jq.sh must take the same fallback arm (bare jq +
#    breadcrumb), never leave DEVFLOW_JQ empty. ──
JQT7D="$(mktemp -d)"
cp "$RESOLVE_JQ_SH" "$JQT7D/resolve-jq.sh"
printf 'garbage' > "$JQT7D/resolve-bin.sh"; chmod 000 "$JQT7D/resolve-bin.sh"
T7D_OUT="$(env -u DEVFLOW_JQ bash -c "set -euo pipefail; . \"$JQT7D/resolve-jq.sh\"; printf %s \"\$DEVFLOW_JQ\"" 2>"$JQT7D/err")"
assert_eq "#247 T7d: unreadable resolve-bin.sh → DEVFLOW_JQ falls back to bare 'jq', not empty" "jq" "$T7D_OUT"
assert_eq "#247 T7d: unreadable resolve-bin.sh → fallback breadcrumb fires" "yes" \
  "$(grep -q 'not found or not sourceable beside resolve-jq.sh' "$JQT7D/err" && echo yes || echo no)"
chmod 600 "$JQT7D/resolve-bin.sh"
# Same sourceability class for the OTHER two guard sites: resolve-gh.sh and
# preflight.sh beside an unreadable resolve-bin.sh must take their fallback
# arms too (a regression to a bare `. file` at either site ships green
# without these).
cp "$LIB/resolve-gh.sh" "$JQT7D/resolve-gh.sh"
chmod 000 "$JQT7D/resolve-bin.sh"
T7E_OUT="$(env -u DEVFLOW_GH bash -c "set -euo pipefail; . \"$JQT7D/resolve-gh.sh\"; devflow_resolve_gh" 2>"$JQT7D/err-gh2")"
assert_eq "#247 T7e: unreadable resolve-bin.sh → devflow_resolve_gh degrades to bare 'gh'" "gh" "$T7E_OUT"
assert_eq "#247 T7e: unreadable resolve-bin.sh → gh fallback breadcrumb fires" "yes" \
  "$(grep -q 'not found or not sourceable beside resolve-gh.sh' "$JQT7D/err-gh2" && echo yes || echo no)"
cp "$LIB/preflight.sh" "$LIB/resolve-python.sh" "$JQT7D/"
T7F_ERR="$(env -u DEVFLOW_JQ -u DEVFLOW_GH bash "$JQT7D/preflight.sh" 2>&1)"; T7F_RC=$?
assert_eq "#247 T7f: preflight beside unreadable resolve-bin.sh → degraded breadcrumb, no phantom-shim wording" "yes" \
  "$(printf '%s' "$T7F_ERR" | grep -q 'missing or not sourceable beside preflight.sh' && ! printf '%s' "$T7F_ERR" | grep -q "the resolved '' does not execute" && echo yes || echo no)"
assert_eq "#247 T7f: preflight degraded mode still exits 0 on a healthy host" "0" "$T7F_RC"
chmod 600 "$JQT7D/resolve-bin.sh"

DJQ_ROOT="$(cd "$LIB/.." && pwd)"
# ── Helper-side breadcrumb literal pins — the init-relay pin above holds the
#    SKILL side; these hold the four EMITTING helpers to the same literal so a
#    reworded gate breadcrumb cannot desync the relay silently (two-sided
#    coupling). ──
for _brf in scripts/detect-project-tools.sh scripts/provision-auto-mode.sh scripts/provision-local-settings.sh scripts/scaffold-config.sh; do
  assert_eq "#247 gate breadcrumb literal present in $_brf" "yes" \
    "$(grep -q 'no usable jq (missing or not executable)' "$DJQ_ROOT/$_brf" && echo yes || echo no)"
done

# ── Shim-present negative branch (the defect #247 fixes), behavioral: a
#    bad-shebang jq with no jq.exe and no override must take the graceful
#    breadcrumb path, not detonate mid-script (a revert to `command -v jq`
#    would ship green without this). ──
JQNEG="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$JQNEG/jq"; chmod +x "$JQNEG/jq"
_mk_restricted "$JQNEG" bash tr grep dirname cat mktemp mv rm find sort head sed uniq
JQNEG_ERR="$(env -u DEVFLOW_JQ PATH="$JQNEG" "$_JQ10_BASH_BIN" "$DJQ_ROOT/scripts/detect-project-tools.sh" "$JQNEG" 2>&1)"; JQNEG_RC=$?
assert_eq "#247 shim-negative: detect-project-tools with unrunnable jq → exit 0 (best-effort preserved)" "0" "$JQNEG_RC"
assert_eq "#247 shim-negative: detect-project-tools emits the 'no usable jq' breadcrumb" "yes" \
  "$(printf '%s' "$JQNEG_ERR" | grep -q 'no usable jq (missing or not executable)' && echo yes || echo no)"

# ── Generic resolver arm (future tools): override honored via the tr path,
#    and the tr-less unknown-tool arm fails closed with the derivation
#    breadcrumb (never a mangled DEVFLOW_ lookup or the internal sentinel). ──
GEN_SEL="$(DEVFLOW_GIT=/stub/git bash -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin git")"
assert_eq "#247 generic arm: DEVFLOW_GIT override honored for an unrouted tool" "/stub/git" "$GEN_SEL"
GENTR="$(mktemp -d)"; ln -s "$(command -v bash)" "$GENTR/bash"
GEN_ERR="$(env -u DEVFLOW_GIT PATH="$GENTR" "$GENTR/bash" -c ". \"$RESOLVE_BIN_SH\"; devflow_resolve_bin git" 2>&1 >/dev/null)"
assert_eq "#247 generic arm: tr-less unknown tool → derivation breadcrumb, override not consulted" "yes" \
  "$(printf '%s' "$GEN_ERR" | grep -q 'could not derive the override variable name for \"git\"' && echo yes || echo no)"
assert_eq "#247 generic arm: degenerate breadcrumb names the user-facing override, never the sentinel" "no" \
  "$(printf '%s' "$GEN_ERR" | grep -q '__DEVFLOW_NO_OVERRIDE__' && echo yes || echo no)"

# ── T8 — a converted helper COPIED without lib/ entirely: the call-site `||`
#    fallback fires (breadcrumb + bare jq) and the helper still honors its
#    best-effort exit-0 contract. ──
DJQ_ROOT="$(cd "$LIB/.." && pwd)"
JQT8="$(mktemp -d)"
mkdir -p "$JQT8/scripts"
cp "$DJQ_ROOT/scripts/detect-project-tools.sh" "$JQT8/scripts/"
T8_ERR="$(bash "$JQT8/scripts/detect-project-tools.sh" "$JQT8" 2>&1 >/dev/null)"; T8_RC=$?
assert_eq "#247 T8: helper copied without lib/ → exit 0 (best-effort contract survives the missing resolver)" "0" "$T8_RC"
assert_eq "#247 T8: helper copied without lib/ → call-site fallback breadcrumb fires" "yes" \
  "$(printf '%s' "$T8_ERR" | grep -q 'resolve-jq.sh could not be sourced' && echo yes || echo no)"

# ── T9 — install.sh inline adaptation, defect reproduction: a bad-shebang jq
#    shim (no jq.exe, no override) with a working python3 routes
#    set_config_version to the python3 arm and still pins the version. ──
SCVJ="$(mktemp -d)"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$SCVJ/jq"; chmod +x "$SCVJ/jq"
_mk_restricted "$SCVJ" bash python3 mktemp mv cat grep tr dirname rm
printf '{\n  "docs": {}\n}\n' > "$SCVJ/config.json"
_SCV_BASH_BIN="$(command -v bash)"
env -u DEVFLOW_JQ PATH="$SCVJ" "$_SCV_BASH_BIN" -c "DEVFLOW_SELFTEST=1 . \"$DJQ_ROOT/install.sh\" && set_config_version \"$SCVJ/config.json\" abc1234" >/dev/null 2>&1
assert_eq "#247 T9: bad-shebang jq + working python3 → python3 arm pins prflow_version" "yes" \
  "$(grep -q '"prflow_version": "abc1234"' "$SCVJ/config.json" && echo yes || echo no)"

# ── T9b — install.sh, broken explicit DEVFLOW_JQ override: the warning
#    breadcrumb fires AND the python3 arm still pins the version (the one
#    deliberately-divergent contract in the family — pinned so a future
#    "unify with the shared resolver" edit goes RED). ──
SCVO="$(mktemp -d)"
_mk_restricted "$SCVO" bash python3 mktemp mv cat grep tr dirname rm
printf '{\n  "docs": {}\n}\n' > "$SCVO/config.json"
printf '#!/nonexistent/devflow-test-interpreter\necho nope\n' > "$SCVO/broken-jq"; chmod +x "$SCVO/broken-jq"
T9B_ERRLOG="$(DEVFLOW_JQ="$SCVO/broken-jq" PATH="$SCVO" "$_SCV_BASH_BIN" -c "DEVFLOW_SELFTEST=1 . \"$DJQ_ROOT/install.sh\" && set_config_version \"$SCVO/config.json\" beef1234" 2>&1)"
assert_eq "#247 T9b: broken DEVFLOW_JQ override → warning breadcrumb names the override" "yes" \
  "$(printf '%s' "$T9B_ERRLOG" | grep -q "DEVFLOW_JQ is set to .*broken-jq.* but it does not execute" && echo yes || echo no)"
assert_eq "#247 T9b: broken DEVFLOW_JQ override → python3 arm still pins prflow_version" "yes" \
  "$(grep -q '"prflow_version": "beef1234"' "$SCVO/config.json" && echo yes || echo no)"

# ── Preflight, broken DEVFLOW_JQ override: the re-probe catches it and the
#    shim-branch remedy names the resolved value (mirrors #245 AC5b). ──
PF_JQO_OUT="$(DEVFLOW_JQ="$SCVO/broken-jq" bash "$LIB/preflight.sh" 2>&1)"; PF_JQO_RC=$?
assert_eq "#247 preflight: broken DEVFLOW_JQ override → exit non-zero (re-probe catches it)" "yes" \
  "$([ "$PF_JQO_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#247 preflight: broken DEVFLOW_JQ override → remedy names the resolved binary" "yes" \
  "$(printf '%s' "$PF_JQO_OUT" | grep -q "no working 'jq'.*broken-jq" && echo yes || echo no)"

# ── Preflight partial copy (no resolve-bin.sh beside it): degrades with an
#    attributable breadcrumb and bare-name resolution — never the phantom
#    "the resolved '' does not execute" misdiagnosis. ──
PFPC="$(mktemp -d)"
cp "$LIB/preflight.sh" "$LIB/resolve-python.sh" "$LIB/resolve-gh.sh" "$LIB/resolve-jq.sh" "$PFPC/"
PF_PC_OUT="$(env -u DEVFLOW_JQ -u DEVFLOW_GH bash "$PFPC/preflight.sh" 2>&1)"; PF_PC_RC=$?
assert_eq "#247 preflight partial copy: attributable resolve-bin.sh breadcrumb emitted" "yes" \
  "$(printf '%s' "$PF_PC_OUT" | grep -q 'resolve-bin.sh missing or not sourceable beside preflight.sh' && echo yes || echo no)"
assert_eq "#247 preflight partial copy: bare-name degradation still verifies real tools (exit 0 on a healthy host)" "0" "$PF_PC_RC"
# Override-first degradation: with a WORKING override set and a broken bare jq
# unavailable-to-matter, the degraded preflight must probe the OVERRIDE (the
# value the helpers USE), not the bare name — DETECT/USE parity survives the
# partial copy. Probe with a broken override: preflight must fail and name it.
PF_PC_OVR="$(DEVFLOW_JQ="$SCVO/broken-jq" env -u DEVFLOW_GH bash "$PFPC/preflight.sh" 2>&1)"; PF_PC_OVR_RC=$?
assert_eq "#247 preflight partial copy: degraded mode still honors DEVFLOW_JQ (broken override → non-zero)" "yes" \
  "$([ "$PF_PC_OVR_RC" -ne 0 ] && echo yes || echo no)"
assert_eq "#247 preflight partial copy: degraded remedy names the override value" "yes" \
  "$(printf '%s' "$PF_PC_OVR" | grep -q "no working 'jq'.*broken-jq" && echo yes || echo no)"

# ── T5d (reshaped by #275) — the SKILL.md shell mirrors are gone (normalization is
#    prompt-time prose now), so behavioral SKILL↔lib parity is no longer executable.
#    lib/normalize-path.sh remains the canonical rules source (its own T4* behavioral
#    tests above still exercise every arm); the surviving prompt-time wslpath/cygpath
#    probe fragment and its lib lockstep reference are pinned by T5/T5c (issue #1856
#    removed T5b with the tool-less drive-letter paraphrase it guarded). Keep the
#    lib-side detection-regex pin so the helper's operative
#    detection line cannot be trimmed while its callers still rely on it. ──
assert_eq "#247 lockstep: detection regex literal present in lib/normalize-path.sh" "yes" \
  "$(grep -qF '=~ ^[A-Za-z]:[\\/] ]]' "$NORMALIZE_PATH_SH" && echo yes || echo no)"

# ── Coupled-relay pin — skills/init/SKILL.md relays the jq-gate breadcrumbs of
#    the provision/detect/scaffold helpers; the literal must track the helpers'
#    actual wording (the pre-#247 'jq not found' relay went stale silently). ──
INIT_SKILL="$LIB/../skills/init/SKILL.md"
assert_eq "#247 init relay: init SKILL.md relays the current 'no usable jq' breadcrumb at all three sites" "yes" \
  "$([ "$(grep -c 'no usable jq (missing or not executable)' "$INIT_SKILL" 2>/dev/null)" -ge 3 ] && echo yes || echo no)"  # raw-guard-ok: count-based (three relay sites)
assert_eq "#247 init relay: no stale 'jq not found' relay survives in init SKILL.md" "0" \
  "$(grep -c 'jq not found' "$INIT_SKILL" || true)"  # raw-guard-ok: count-based (absence pin)

# ── Peer-completeness pins (2.3.0a) — every in-scope jq-calling helper sources
#    the shared resolver, and no bare invocation-position `jq` survives outside
#    it. Best-effort grep, mirroring the #245 DGH_BARE discipline: comment lines
#    and diagnostic echo/printf lines are excluded; T6 is the dynamic backstop.
#    scripts/authorize-actor.sh is deliberately out of scope — its `--jq` is a
#    flag of `gh api`, not a jq-binary invocation. ──
DJQ_ROOT="$(cd "$LIB/.." && pwd)"
# 16 = 12 migrated jq-callers (7 lib + 5 scripts) + preflight.sh + resolve-gh.sh
# (both reference the shared resolver) + install.sh (inline mirror — it must run
# standalone before any checkout exists, so it carries the contract by reference
# comment rather than a source line; the DJQ_BARE grep below is what holds its
# call sites to the converted form) + scripts/run-jq.sh (issue #253 — the
# agent-tier jq wrapper skill bodies invoke by path; it sources resolve-jq.sh
# exactly as the .sh helpers do).
DJQ_SOURCED="$(grep -rlE 'resolve-(jq|bin)\.sh' "$DJQ_ROOT/scripts" "$DJQ_ROOT/lib" "$DJQ_ROOT/install.sh" --include='*.sh' 2>/dev/null | grep -v '/test/' | grep -v 'lib/resolve-bin\.sh$' | grep -v 'lib/resolve-jq\.sh$' | grep -c . || true)"  # tree-walk-ok: scoped to $DJQ_ROOT/scripts, /lib and install.sh, which no worktree lives under
assert_eq "#247 peer-completeness: >=16 helpers reference the shared resolver (all jq-callers + resolve-gh.sh + run-jq.sh converted)" "yes" \
  "$([ "$DJQ_SOURCED" -ge 16 ] && echo yes || echo no)"
# Exclusions are deliberately MINIMAL (a blanket echo/printf line-exclusion
# would mask the repo's dominant `printf ... | jq -r` idiom): full-line
# comments, the resolver's own file, and `--version` probe lines (`<cand>
# --version` IS the resolver mechanism — install.sh's inline adaptation and
# the preflight re-probe — never a data-processing call site; the exclusion
# is anchored to the probe shape `jq(.exe)? --version`, not a whole-line
# --version filter that a filter-string mention would ride). The suffix
# alternation covers flag/quoted-program/path forms AND common bareword
# filters (empty/length/keys/type/to_entries) so `jq empty <<<"$x"`-style
# reintroductions go RED too.
DJQ_BARE="$(grep -rnE '(^|[[:space:]|&;(`])jq[[:space:]]+(-|'"'"'|"|\.|empty|length|keys|type|to_entries)' \
  "$DJQ_ROOT/scripts" "$DJQ_ROOT/lib" "$DJQ_ROOT/install.sh" --include='*.sh' 2>/dev/null \
  | grep -v '/test/' | grep -v 'resolve-bin\.sh:' | grep -vE '^[^:]+:[0-9]+:[[:space:]]*#' | grep -vE 'jq(\.exe)? --version' | grep -c . || true)"  # tree-walk-ok: scoped to $DJQ_ROOT/scripts, /lib and install.sh, which no worktree lives under
assert_eq "#247 peer-completeness: no bare invocation-position jq call survives outside the resolver" "0" "$DJQ_BARE"

# ── Skills-tier jq pin (issue #253, widened by #271) — the DJQ_BARE grep above
#    is scoped to *.sh and never sees skill bodies, so agent-composed `jq` inside
#    SKILL.md fenced blocks was invisible to the #247 contract. On a shim-shadowed
#    Windows/WSL host a bare agent-typed `jq` hits the same present-but-
#    unrunnable-shim defect #247 fixed for the helpers. This pin holds every
#    executable jq in EVERY skill body to the agent-tier wrapper
#    scripts/run-jq.sh (which sources the shared resolver — DEVFLOW_JQ is not
#    exported to agent shells, so a callable-by-path wrapper is the agent-tier
#    equivalent of the .sh source-once idiom).
#    SCOPE — all skill bodies. #253 originally scoped this to the retrospective
#    family (the LOCAL weekly loop); #271 migrated the remaining cloud-governed
#    executable jq sites (skills/implement/SKILL.md, phases/phase-4-documentation.md,
#    docs-release-notes/SKILL.md) to the wrapper and added the wrapper to the cloud
#    allowlist in .github/workflows/devflow-implement.yml + devflow-runner.yml +
#    devflow.yml, so they are now IN scope: the find below no longer restricts to
#    *retrospective*.
#    (The skills/review/SKILL.md trace example is in INLINE-backtick prose (now
#    `run-jq.sh -n`), not a shell fence, so it is outside this awk-fence pin's reach —
#    #271 migrated it too; its regression guard is the dedicated review-site pin below,
#    and its cloud grant is the coupled allowlist edit, not this awk-fence pin.)
#    Fence scope: lines inside ```bash / ```sh / ```shell fences only, so
#    inline-backtick prose mentions of `jq -n` and non-shell (```json / ```dot /
#    output) fences never false-match. ──
# Positive pin: the wrapper exists and references the shared jq resolver.
assert_eq "#253 skills-jq: scripts/run-jq.sh exists and references the shared jq resolver" "yes" \
  "$([ -f "$LIB/../scripts/run-jq.sh" ] && grep -q 'resolve-jq\.sh' "$LIB/../scripts/run-jq.sh" && echo yes || echo no)"
# The wrapper's whole purpose is a cloud-tier by-path leading-token invocation
# (`.prflow/vendor/prflow/scripts/run-jq.sh …`), which requires the COMMITTED
# file to carry the executable bit — a dropped bit silently breaks the cloud
# invocation with no other failing test (the coverage above runs it via `bash
# "$RJQ_SH"`, which does not exercise the bit). Pin the git INDEX mode (what
# ships), not the working-tree `-x` (which reflects local perms), mirroring the
# comparable by-path helper lib/efficiency-trace.sh. (PR #274 review, Important.)
assert_eq "#253 skills-jq: scripts/run-jq.sh is committed executable (100755)" "100755" \
  "$(cd "$LIB/.." && git ls-files -s scripts/run-jq.sh | awk '{print $1}')"
# Absence pin: no bare invocation-position jq survives inside a shell fenced
# block of ANY skill body. The awk captures only ```bash/```sh/
# ```shell block bodies (state reset per file); the grep shape mirrors DJQ_BARE
# (flag/quoted-program/path/bareword-filter forms), excluding the resolver's own
# `--version` probe shape and the wrapper path itself.
SKILL_JQ_BARE="$(
  find "$LIB/../skills" -type f -name '*.md' 2>/dev/null | while IFS= read -r _f; do  # tree-walk-ok: scoped to skills/, which no worktree lives under
    awk '
      /^[[:space:]]*```(bash|sh|shell)[[:space:]]*$/ { inb=1; next }
      /^[[:space:]]*```[[:space:]]*$/ { inb=0; next }
      inb { print }
    ' "$_f"
  done \
  | grep -v 'run-jq\.sh' \
  | grep -E '(^|[[:space:]|&;(`])jq[[:space:]]+(-|'"'"'|"|\.|empty|length|keys|type|to_entries)' \
  | grep -vE 'jq(\.exe)? --version' | grep -c . || true)"
assert_eq "#253 skills-jq: no bare invocation-position jq survives in any skill shell fenced block" "0" "$SKILL_JQ_BARE"

# ── #271 coupled-invariant pins: the skill-body run-jq.sh migration is one half of a
#    two-sided contract — the cloud-governed skills invoke the wrapper BY PATH as the
#    command's leading token (`.prflow/vendor/prflow/scripts/run-jq.sh`), which the
#    cloud permission profile silently DENIES unless the workflow allowlist grants it
#    (the CLAUDE.md LEADING-token gotcha). Pin the grant at both cloud writer/runner
#    profiles so a dropped/reformatted allowlist entry goes RED here rather than
#    silently no-op'ing the migration in cloud (and because #271 retired the AC11
#    `.github`-freeze, this is now the only guard on this `.github` side of the couple).
IMPL_WF="$LIB/../.github/workflows/devflow-implement.yml"
RUNNER_WF="$LIB/../.github/workflows/devflow-runner.yml"
# devflow.yml is the THIRD governing workflow — the light command listener that
# runs a MANUAL bare `/devflow:review` / `/devflow:review-and-fix` comment, so it
# also executes the migrated skills/review/SKILL.md Phase 4.5 trace-authoring site
# (`run-jq.sh` by path). Its inline allowlist must grant the wrapper too or the
# by-path head is silently denied on that trigger, dropping the telemetry trace a
# bare `jq -n` previously authored (raised by PR #274 review, Important).
LIGHT_WF="$LIB/../.github/workflows/devflow.yml"
assert_eq "#271 coupled: devflow-implement.yml allowlists the run-jq.sh wrapper by vendored path" "1" \
  "$(grep -cF 'Bash(.prflow/vendor/prflow/scripts/run-jq.sh:*)' "$IMPL_WF" || true)"
assert_eq "#271 coupled: devflow-runner.yml (read-only review profile) allowlists the run-jq.sh wrapper" "1" \
  "$(grep -cF 'Bash(.prflow/vendor/prflow/scripts/run-jq.sh:*)' "$RUNNER_WF" || true)"
assert_eq "#271 coupled: devflow.yml (manual-comment review listener) allowlists the run-jq.sh wrapper" "1" \
  "$(grep -cF 'Bash(.prflow/vendor/prflow/scripts/run-jq.sh:*)' "$LIGHT_WF" || true)"
# The skills/review/SKILL.md trace-authoring example sits in INLINE-backtick prose, so the
# awk-fence absence pin above cannot reach it — pin it directly so a revert of that site to
# a bare `jq -n` goes RED (it is one of the four #271-migrated sites and would otherwise have
# no regression guard). Target-unique: `--argjson findings` follows run-jq.sh only in the
# trace example, so assert_pin_unique proves PASS-with-the-literal → FAIL-without-it.
assert_pin_unique "#271 coupled: skills/review/SKILL.md trace example invokes the run-jq.sh wrapper (not bare jq -n)" \
  'scripts/run-jq.sh -n --argjson findings' "$REVIEW_BUNDLE"
# The implement/SKILL.md reaction-comment read and the phase-4 deferrals merge are
# fenced-block sites covered by the awk absence pin above, but that pin is *negative*
# only — it goes RED on a reintroduced BARE jq, yet stays GREEN if the site is
# refactored away from jq entirely (deleting the migrated wrapper call with it),
# silently dropping the migration at that site with no failing test. Pin each
# positively so a removal/refactor of the wrapper call goes RED too (PR #274 review,
# Suggestion — parity with the review/docs-release-notes sites' positive guards).
# Target-unique substrings: `run-jq.sh -r '.comment.id` occurs only at the reaction
# read; `run-jq.sh -s '.[0] as $f` only at the phase-4 merge.
assert_pin_unique "#271 coupled: skills/implement/SKILL.md reaction-comment read invokes the run-jq.sh wrapper" \
  "scripts/run-jq.sh -r '.comment.id" "$LIB/../skills/implement/SKILL.md"
assert_pin_unique "#271 coupled: the gated §4.0.5 reference deferrals merge invokes the run-jq.sh wrapper" \
  "scripts/run-jq.sh -s '.[0] as \$f" "$LIB/../skills/implement/references/deferred-review-findings.md"

# ── #313 third-party model provider resolver ───────────────────────────────
# The provider resolver is an INLINE jq program embedded in all three cloud
# workflows (devflow.yml / devflow-implement.yml / devflow-runner.yml). It cannot
# be a scripts/*.jq file (the config-extract jobs never vendor the plugin, so no
# helper exists on disk there), so single-sourcing is enforced HERE: extract the
# program body from each workflow at test time, assert the three copies are
# byte-identical, then run ONE extracted copy live — never hand-maintain a fourth.
# IMPL_WF / RUNNER_WF / LIGHT_WF are defined in the #271 block above; reuse them.
# region_lines already prints the lines strictly between a BEGIN/END marker pair,
# substring-matched — reuse it rather than a bespoke awk extractor.
R313_IMPL="$(region_lines "$IMPL_WF" '# devflow-provider-resolver BEGIN' '# devflow-provider-resolver END')"
R313_RUNNER="$(region_lines "$RUNNER_WF" '# devflow-provider-resolver BEGIN' '# devflow-provider-resolver END')"
R313_LIGHT="$(region_lines "$LIGHT_WF" '# devflow-provider-resolver BEGIN' '# devflow-provider-resolver END')"
# --- AC2 (issue #1084): the provider resolver reads `$cfg[$section].provider`, so
# each provider step's `SECTION:` env must name the config family that workflow's
# own config reads use. devflow.yml set `SECTION: devflow` while the schema declares
# `prflow.provider` and /prflow:init scaffolds only `prflow`, so a configured
# provider was silently ignored on the entire /prflow:* command path. Assert each
# workflow's SECTION matches its family and that the superseded `devflow` spelling
# never reappears at a resolver call site.
# structural-pin-ok: routing-dispatch-contract -- the SECTION literal selects which
# config family the single-sourced resolver reads; a wrong value silently routes to
# an unread section, so this is a typed routing boundary, not documentation prose.
assert_eq "#1084 SECTION: devflow.yml provider steps name the prflow family (not the dead devflow spelling)" "2 0" \
  "$(grep -cE '^[[:space:]]*SECTION:[[:space:]]*prflow$' "$LIGHT_WF") $(grep -cE '^[[:space:]]*SECTION:[[:space:]]*devflow$' "$LIGHT_WF")"
assert_eq "#1084 SECTION: devflow-runner.yml provider steps name the prflow_runner family" "2 0" \
  "$(grep -cE '^[[:space:]]*SECTION:[[:space:]]*prflow_runner$' "$RUNNER_WF") $(grep -cE '^[[:space:]]*SECTION:[[:space:]]*devflow$' "$RUNNER_WF")"
assert_eq "#1084 SECTION: devflow-implement.yml provider steps name the prflow_implement family" "2 0" \
  "$(grep -cE '^[[:space:]]*SECTION:[[:space:]]*prflow_implement$' "$IMPL_WF") $(grep -cE '^[[:space:]]*SECTION:[[:space:]]*devflow$' "$IMPL_WF")"
# Non-empty guard: a renamed/removed sentinel would extract "" and make the
# identity asserts vacuously PASS ("" == "") — assert extraction found a program.
assert_eq "#313 resolver: program extracted from devflow-implement.yml is non-empty (sentinels intact)" "yes" \
  "$([ -n "$R313_IMPL" ] && echo yes || echo no)"
assert_eq "#313 resolver single-sourced: devflow-implement.yml vs devflow.yml byte-identical" "yes" \
  "$([ "$R313_IMPL" = "$R313_LIGHT" ] && echo yes || echo no)"
assert_eq "#313 resolver single-sourced: devflow-implement.yml vs devflow-runner.yml byte-identical" "yes" \
  "$([ "$R313_IMPL" = "$R313_RUNNER" ] && echo yes || echo no)"

# Behavioral coverage: eval the EMBEDDED copy (single-sourced — not a retyped
# program) to populate $RESOLVER, then drive it against literal config fixtures.
eval "$R313_IMPL"
r313() { jq -c --arg section "$1" "$RESOLVER"; }
# AC 1: config with no provider keys → the Anthropic-default decision.
assert_eq "#313 resolver: default (no providers, no section provider) → Anthropic-default decision" \
  '{"provider":"","base_url":"","auth":"","timeout_ms":"","effort_supported":true,"model":"claude-opus-4-8","env":{}}' \
  "$(echo '{"claude_model":"claude-opus-4-8","prflow_implement":{}}' | r313 prflow_implement)"
# ACs 3/4: implement-section decision carries openrouter fields; the runner
# section stays default in the SAME config (per-section isolation).
R313_CFG='{"claude_model":"m","providers":{"openrouter":{"base_url":"https://openrouter.ai/api","auth":"bearer","timeout_ms":3000000,"env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"z-ai/glm-4.7"}}},"prflow_implement":{"provider":"openrouter","claude_model":"z-ai/glm-5.2"}}'
assert_eq "#313 resolver: section provider selects openrouter (base_url/auth/model/env)" \
  '{"provider":"openrouter","base_url":"https://openrouter.ai/api","auth":"bearer","timeout_ms":3000000,"effort_supported":false,"model":"z-ai/glm-5.2","env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"z-ai/glm-4.7"}}' \
  "$(echo "$R313_CFG" | r313 prflow_implement)"
assert_eq "#313 resolver: unrelated section stays Anthropic-default in the same provider config (AC 4 isolation)" \
  '{"provider":"","base_url":"","auth":"","timeout_ms":"","effort_supported":true,"model":"m","env":{}}' \
  "$(echo "$R313_CFG" | r313 prflow_runner)"
# AC 3: model precedence — section claude_model beats global; global when absent.
assert_eq "#313 resolver: section claude_model beats global" "section-model" \
  "$(echo '{"claude_model":"global-model","prflow_implement":{"claude_model":"section-model"}}' | r313 prflow_implement | jq -r .model)"
assert_eq "#313 resolver: global claude_model used when section absent" "global-model" \
  "$(echo '{"claude_model":"global-model","prflow_implement":{}}' | r313 prflow_implement | jq -r .model)"
# AC 3: a section naming a provider ABSENT from an EXISTING providers map yields the
# explicit error marker. (Distinct from the matrix "providers map missing" shape below:
# here the map exists but lacks the named entry — the literal "references an undefined
# provider name" case AC 3 describes.)
assert_eq "#313 resolver: provider name absent from an existing map → explicit error marker" \
  '{"error":"undefined_provider","section":"prflow_implement","provider":"nope","detail":"provider is not defined in the providers map"}' \
  "$(echo '{"claude_model":"m","providers":{"other":{"base_url":"u","auth":"bearer"}},"prflow_implement":{"provider":"nope"}}' | r313 prflow_implement)"
# AC 7: effort_supported false/absent → false; true → true; strict (non-boolean → false).
assert_eq "#313 resolver: effort_supported false when provider omits it (drop --effort)" "false" \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"api_key"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -r .effort_supported)"
assert_eq "#313 resolver: effort_supported true when provider sets it (keep --effort)" "true" \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"api_key","effort_supported":true}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -r .effort_supported)"
# strict `== true`: a non-boolean effort_supported (string "true", number 1) resolves to
# false so --effort is dropped (fail-closed) — pins the deliberate `== true` over bare
# truthiness (a mutation to `(… // false)` would flip this GREEN→behavior on a gateway).
assert_eq "#313 resolver: effort_supported non-boolean (string) → false (strict == true)" "false" \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"api_key","effort_supported":"true"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -r .effort_supported)"
# AC 4: the provider env map (background-model/attribution/betas keys) survives intact.
# Keep every key here off the inject step's deny list (issue #1773): the resolver does no name
# filtering, so a denied key would pass here while encoding a config the inject step refuses.
assert_eq "#313 resolver: provider env map survives into the decision intact" \
  '{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"z-ai/glm-4.7","CLAUDE_CODE_ATTRIBUTION_HEADER":"0","CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS":"1"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"bearer","env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"z-ai/glm-4.7","CLAUDE_CODE_ATTRIBUTION_HEADER":"0","CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS":"1"}}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -c .env)"

# AC 1 (#1770): a bedrock_api_key entry with NO base_url resolves to an ACTIVE provider
# decision (not an incomplete_provider error) — base_url is optional on this arm, default "".
assert_eq "#313/#1770 resolver: bedrock_api_key entry without base_url → active decision (base_url empty)" \
  '{"provider":"bed","base_url":"","auth":"bedrock_api_key","timeout_ms":"","effort_supported":false,"model":"us.anthropic.claude-x","env":{"AWS_REGION":"us-east-1"}}' \
  "$(echo '{"claude_model":"m","providers":{"bed":{"auth":"bedrock_api_key","env":{"AWS_REGION":"us-east-1"}}},"prflow_implement":{"provider":"bed","claude_model":"us.anthropic.claude-x"}}' | r313 prflow_implement)"
# #1770: a bedrock_api_key entry MAY still carry a base_url — the resolver keeps it in the
# decision (the inject step ignores it and warns); the arm stays active, not an error.
assert_eq "#313/#1770 resolver: bedrock_api_key entry carrying base_url → decision retains it (inject warns)" \
  '{"provider":"bed","base_url":"https://x","auth":"bedrock_api_key","timeout_ms":"","effort_supported":false,"model":"m","env":{"AWS_REGION":"us-east-1"}}' \
  "$(echo '{"claude_model":"m","providers":{"bed":{"auth":"bedrock_api_key","base_url":"https://x","env":{"AWS_REGION":"us-east-1"}}},"prflow_implement":{"provider":"bed"}}' | r313 prflow_implement)"
# #1770 six-shape matrix (base_url on the bedrock arm): a wrong-type base_url coerces to ""
# rather than crashing or erroring — base_url is not required nor validated on this arm.
assert_eq "#313/#1770 resolver: bedrock_api_key entry with wrong-type base_url → base_url coerced to empty" "" \
  "$(echo '{"claude_model":"m","providers":{"bed":{"auth":"bedrock_api_key","base_url":{"x":1},"env":{"AWS_REGION":"us-east-1"}}},"prflow_implement":{"provider":"bed"}}' | r313 prflow_implement | jq -r .base_url)"

# AC 9: adversarial input-shape matrix — each malformed shape yields exit-0 plus its
# SPECIFIC (not generic) documented decision/error marker. The resolver type-guards every
# index, so NO shape crashes the workflow step (rc≠0) — the exit-0 sweep below proves it.
assert_eq "#313 matrix: providers map missing (+ section provider) → undefined_provider marker" \
  '{"error":"undefined_provider","section":"prflow_implement","provider":"openrouter","detail":"provider is not defined in the providers map"}' \
  "$(echo '{"claude_model":"m","prflow_implement":{"provider":"openrouter"}}' | r313 prflow_implement)"
assert_eq "#313 matrix: providers wrong-type (string) → undefined_provider marker" \
  '{"error":"undefined_provider","section":"prflow_implement","provider":"openrouter","detail":"provider is not defined in the providers map"}' \
  "$(echo '{"claude_model":"m","providers":"nope","prflow_implement":{"provider":"openrouter"}}' | r313 prflow_implement)"
# Provider PRESENT but incomplete → FAIL-LOUD error marker (not a silent default with an
# empty base_url/auth): a bearer/api_key provider-active decision must never reach the inject
# step with an empty ANTHROPIC_BASE_URL, and the resolver rejects an auth value outside
# {bearer,api_key,bedrock_api_key} before the inject step (review C1/sfh — the old fail-open).
assert_eq "#313 matrix: provider entry present (bearer) but missing base_url → incomplete_provider marker (fail-loud)" \
  '{"error":"incomplete_provider","section":"prflow_implement","provider":"p","detail":"provider entry has no base_url"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"auth":"bearer"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
# The EMPTY-STRING base_url disjunct (distinct from the missing/wrong-type one above): a
# present but empty base_url is also fail-loud. Pins the `== ""` half of the guard so a
# mutation dropping it (reintroducing the empty-ANTHROPIC_BASE_URL fail-open) goes RED.
assert_eq "#313 matrix: provider entry with EMPTY base_url → incomplete_provider marker (== \"\" disjunct)" \
  '{"error":"incomplete_provider","section":"prflow_implement","provider":"p","detail":"provider entry has no base_url"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"","auth":"bearer"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
assert_eq "#313 matrix: provider entry present but missing auth → incomplete_provider marker" \
  '{"error":"incomplete_provider","section":"prflow_implement","provider":"p","detail":"provider auth must be one of bearer, api_key, bedrock_api_key"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
assert_eq "#313 matrix: provider auth outside {bearer,api_key,bedrock_api_key} (e.g. Bearer) → incomplete_provider marker" \
  '{"error":"incomplete_provider","section":"prflow_implement","provider":"p","detail":"provider auth must be one of bearer, api_key, bedrock_api_key"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"Bearer"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
assert_eq "#313 matrix: empty-string section provider → Anthropic-default decision" \
  '{"provider":"","base_url":"","auth":"","timeout_ms":"","effort_supported":true,"model":"m","env":{}}' \
  "$(echo '{"claude_model":"m","prflow_implement":{"provider":""}}' | r313 prflow_implement)"
# Crash-class shapes (used to be jq rc=5 → set -e step abort with a raw jq error). The
# type-guards now yield a specific marker / safe default with rc=0.
assert_eq "#313 matrix: non-string section provider (number) → invalid_provider marker (no crash)" \
  '{"error":"invalid_provider","section":"prflow_implement","provider":"","detail":"section provider must be a string"}' \
  "$(echo '{"claude_model":"m","prflow_implement":{"provider":5}}' | r313 prflow_implement)"
assert_eq "#313 matrix: non-object section (scalar) → Anthropic-default decision (no crash)" \
  '{"provider":"","base_url":"","auth":"","timeout_ms":"","effort_supported":true,"model":"m","env":{}}' \
  "$(echo '{"claude_model":"m","prflow_implement":"oops"}' | r313 prflow_implement)"
assert_eq "#313 matrix: non-object top-level config → Anthropic-default decision (no crash)" \
  '{"provider":"","base_url":"","auth":"","timeout_ms":"","effort_supported":true,"model":"","env":{}}' \
  "$(echo '"not-an-object"' | r313 prflow_implement)"
assert_eq "#313 matrix: env wrong-type (string) → env:{}" "{}" \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"bearer","env":"nope"}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -c .env)"
# timeout_ms is NOT semantically type-guarded (only `// ""` for null/missing) — a wrong-type
# value flows through verbatim (the documented, accepted defense-in-depth: config is
# maintainer/base-ref-controlled and schema-typed). Completes the {field} x {wrong-type}
# matrix (review Suggestion #6) — pins the pass-through so a future type-guard is a conscious
# change, not a silent one; the inject step then writes it heredoc-safely regardless.
assert_eq "#313 matrix: timeout_ms wrong-type (object) → passes through verbatim (documented, not type-guarded)" \
  '{"x":1}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":"bearer","timeout_ms":{"x":1}}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement | jq -c .timeout_ms)"
# section claude_model is the one type-GUARDED field (`type == "string" and != ""`); a wrong-type
# section value (number/object) falls through to the global claude_model — completes the matrix's
# {type-guarded field} x {wrong-type} cell (review Suggestion #5).
assert_eq "#313 matrix: wrong-type section claude_model (number) → falls through to global claude_model" "global-m" \
  "$(echo '{"claude_model":"global-m","prflow_implement":{"claude_model":5}}' | r313 prflow_implement | jq -r .model)"
assert_eq "#313 matrix: provider entry wrong-type (string, not object) → undefined_provider marker" \
  '{"error":"undefined_provider","section":"prflow_implement","provider":"p","detail":"provider is not defined in the providers map"}' \
  "$(echo '{"claude_model":"m","providers":{"p":"x"},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
# Every malformed shape EXITS 0 — sweep the shapes that USED to crash jq (rc=5) before the
# type-guards, so a regression that drops a guard (reintroducing the set -e abort) goes RED.
for R313_BAD in \
  '{"providers":"nope","prflow_implement":{"provider":"openrouter"}}' \
  '{"prflow_implement":{"provider":5}}' \
  '{"prflow_implement":"oops"}' \
  '{"prflow_implement":["x"]}' \
  '"not-an-object"'; do
  echo "$R313_BAD" | r313 prflow_implement >/dev/null 2>&1
  assert_eq "#313 matrix: malformed shape exits 0 (no jq crash): $R313_BAD" "0" "$?"
done

# AC 1 defaults-unchanged pins — anchored to the three explicit workflow paths
# (NOT a .github/workflows glob), so the synthetic claude.yml fixture elsewhere
# in this suite can never satisfy or trip them. Each check preserves the operative
# conditional on its named workflow.
for R313_WF in "$IMPL_WF" "$RUNNER_WF" "$LIGHT_WF"; do
  R313_TAG="$(basename "$R313_WF")"
  # claude_code_oauth_token stays under the empty-decision (no-provider) condition.
  assert_pin_unique "#313 defaults: $R313_TAG passes OAuth token only on the no-provider path" \
    "steps.provider.outputs.provider == '' && secrets.CLAUDE_CODE_OAUTH_TOKEN" "$R313_WF"
  # structural-pin-ok: routing-dispatch-contract -- the use_bedrock action input is the
  # dispatch contract selecting Amazon Bedrock at the action layer (#1770 AC 2/3), an
  # expression the runner evaluates and no executed step body writes.
  assert_pin_unique "#313/#1770 AC2/3: $R313_TAG passes use_bedrock 'true' only on the bedrock_api_key arm ('' otherwise)" \
    "steps.provider.outputs.auth == 'bedrock_api_key' && 'true' || ''" "$R313_WF"
  # anthropic_api_key rides on the bearer/api_key arms: provider-active AND not the bedrock
  # arm (#1770 AC 6 narrows it so bedrock passes '' here).
  # structural-pin-ok: routing-dispatch-contract -- the anthropic_api_key action input is a
  # runner-evaluated credential-routing expression, unreachable by executing the step bodies.
  assert_pin_unique "#313 defaults: $R313_TAG passes anthropic_api_key only on the non-bedrock provider path" \
    "steps.provider.outputs.provider != '' && steps.provider.outputs.auth != 'bedrock_api_key' && secrets.DEVFLOW_PROVIDER_API_KEY" "$R313_WF"
  # AC 6 empty-secret guard: the inject step's run body is byte-identical across the three,
  # so a UNIFORM removal keeps the body-identity check GREEN — this per-file presence pin is
  # what makes dropping the fail-loud guard from all three go RED (assert_pin_unique proves
  # PASS-with → FAIL-without at each site).
  assert_pin_unique "#313 defaults: $R313_TAG inject step fails loud on an empty provider secret (AC 6)" \
    "DEVFLOW_PROVIDER_API_KEY repository secret is empty" "$R313_WF"
  # ANTHROPIC_BASE_URL is written exactly once (via genv, the newline-safe heredoc
  # writer), and only inside the provider-gated inject step — structurally proving it
  # never leaks onto the default path.
  assert_eq "#313 defaults: $R313_TAG writes ANTHROPIC_BASE_URL exactly once" "1" \
    "$(pin_count 'genv ANTHROPIC_BASE_URL' "$R313_WF")"
  # mint_blk extracts a named step's block (- name: … to the next sibling/job
  # boundary) — reuse it instead of a bespoke awk step-extractor.
  R313_INJECT="$(mint_blk 'Inject provider endpoint (provider-routed sections only)' "$R313_WF")"
  assert_eq "#313 defaults: $R313_TAG inject step is gated on provider != '' AND holds the ANTHROPIC_BASE_URL write" "yes" \
    "$(printf '%s' "$R313_INJECT" | grep -qF "steps.provider.outputs.provider != ''" \
       && printf '%s' "$R313_INJECT" | grep -qF 'genv ANTHROPIC_BASE_URL' && echo yes || echo no)"
  # The cargs COMPUTED string must actually be CONSUMED by the action step's
  # claude_args (the producer→consumer wiring pin): every cargs behavior above is
  # executed, but without this pin a merge-conflict revert of claude_args to the
  # old literal `--model …/--effort …` head would leave every #313 test green
  # while the provider path silently regained --effort (gateway 400s) and lost
  # the per-section model override.
  assert_pin_unique "#313 defaults: $R313_TAG claude_args consumes the computed cargs head" \
    '${{ steps.cargs.outputs.args }}' "$R313_WF"
done
# AC 8 default-path fail-loud OAuth guard (runner-only): the runner relaxed
# CLAUDE_CODE_OAUTH_TOKEN to an optional workflow_call secret, so it must fail loud when the
# Anthropic default path (no provider) has no OAuth token. This step is unique to the runner
# (not covered by the 3-way body-identity check), so retain its textual boundary.
assert_pin_unique "#313 defaults: devflow-runner.yml fails loud on the Anthropic default path when CLAUDE_CODE_OAUTH_TOKEN is empty (AC 8 boundary)" \
  "No model provider is configured for the prflow_runner section" "$RUNNER_WF"
# The AC-8 guard's `if:` GATE (not just its body): the body is executed below (both
# arms) and its message is retained as a textual boundary, but neither catches a deleted or
# inverted `if:` — a deleted gate makes a provider-routed, OAuth-less repo (the exact
# deployment #313 enables) fail spuriously on every review; an inverted one silently
# drops the default path's fail-loud. Same mint_blk idiom as the inject-step gate check.
R313_OAUTH_BLK="$(mint_blk 'Require OAuth token on the Anthropic default path' "$RUNNER_WF")"
assert_eq "#313 defaults: devflow-runner.yml OAuth guard step is gated on provider == '' AND reads the OAuth secret" "yes" \
  "$(printf '%s' "$R313_OAUTH_BLK" | grep -qF "steps.provider.outputs.provider == ''" \
     && printf '%s' "$R313_OAUTH_BLK" | grep -qF 'secrets.CLAUDE_CODE_OAUTH_TOKEN' && echo yes || echo no)"
# Review C1: the runner resolves its provider decision from the TRUSTED BASE ref config
# (steps.baseprovision), never PR-head steps.cfg — a PR-head-sourced base_url + secret would
# exfiltrate DEVFLOW_PROVIDER_API_KEY to an attacker gateway. Retain that trusted-source boundary.
# devflow.yml/devflow-implement.yml read the default-branch
# (base) checkout on issue_comment, so steps.cfg is already the trusted config for them.
assert_pin_unique "#313 security: devflow-runner.yml resolves the provider decision from the trusted base-ref config, not PR-head (review C1 boundary)" \
  "CONFIG_JSON: \${{ steps.baseprovision.outputs.config_json }}" "$RUNNER_WF"
# The runner's MODEL head-fallback (bootstrap case: base ref carries no committed config →
# resolver model="" → fall back to head claude_model so --model is never empty). It lives in
# the cargs step's env: block, which the run-body-identity check excludes, so pin it directly.
assert_pin_unique "#313 defaults: devflow-runner.yml MODEL falls back to head claude_model when the base-resolved model is empty (bootstrap)" \
  "steps.provider.outputs.model != '' && steps.provider.outputs.model || steps.extract.outputs.claude_model" "$RUNNER_WF"

# Single-sourcing widened past the jq body (issue #313 /simplify altitude finding):
# with the section name env-parameterized, the Resolve / Inject / Build-claude_args-head
# step `run:` BODIES are byte-identical across the three workflows too (only their `env:`
# section value + effort source legitimately differ). Pin that so a drift in the
# triplicated scaffolding — not just the jq program — goes RED. YAML-parse the step
# bodies (same python+yaml idiom as the tools-step extraction above); SKIP without PyYAML.
if command -v python3 >/dev/null 2>&1 && python3 -c 'import yaml' >/dev/null 2>&1; then
  R313_BODY_IDENT="$(python3 - "$IMPL_WF" "$RUNNER_WF" "$LIGHT_WF" <<'PY'
import sys, yaml
files = sys.argv[1:]
names = ["Resolve model provider",
         "Inject provider endpoint (provider-routed sections only)",
         "Export provider effort capability to job env",
         "Build claude_args head (model + conditional effort)"]
bodies = {n: [] for n in names}
for f in files:
    doc = yaml.safe_load(open(f))
    for job in doc["jobs"].values():
        for st in job.get("steps", []):
            if st.get("name") in bodies and "run" in st:
                bodies[st["name"]].append(st["run"])
out = []
for n in names:
    b = bodies[n]
    out.append("yes" if len(b) == 3 and b[0] == b[1] == b[2] else "no")
print(",".join(out))
PY
)"
  assert_eq "#313 single-sourced: Resolve/Inject/export-effort/cargs run: bodies byte-identical across the 3 workflows" "yes,yes,yes,yes" "$R313_BODY_IDENT"

  # #1772: the byte-identity pin above compares only each step's `run:` body, so a workflow
  # with an omitted/mistyped env block, a hardcoded value, or a late-moved export stays
  # identical and green while exporting nothing the resolver reads. Assert the wiring.
  R1772_EXPORT_ENV="$(python3 - "$IMPL_WF" "$RUNNER_WF" "$LIGHT_WF" "$REPO_ROOT/scripts/resolve-review-overrides.py" <<'PY'
import sys, re, yaml
files = sys.argv[1:4]
want = "${{ steps.provider.outputs.effort_supported }}"
# Derive the exported env-var KEY from the resolver's OWN constant so the workflow writer and
# the in-session reader stay coupled: a rename on either side that is not mirrored fails RED.
m = re.search(r'_EFFORT_SUPPORTED_ENV\s*=\s*"([^"]+)"', open(sys.argv[4]).read())
key = m.group(1) if m else None
env_ok, run_ok, pos_ok = [], [], []
for f in files:
    doc = yaml.safe_load(open(f))
    for job in doc["jobs"].values():
        steps = job.get("steps", [])
        ei = [i for i, s in enumerate(steps)
              if s.get("name") == "Export provider effort capability to job env"]
        if not ei:
            continue
        st, body = steps[ei[0]], (steps[ei[0]].get("run") or "")
        # env: the value SOURCE; run: the resolver's KEY, the env var as the written VALUE, and
        # the $GITHUB_ENV SINK. Drop any one and a green pass is compatible with dead wiring:
        # a uniform hardcode, or a write redirected to $GITHUB_OUTPUT/stdout the resolver never reads.
        env_ok.append((st.get("env") or {}).get("EFFORT_SUPPORTED") == want)
        run_ok.append(key is not None and (key + "=") in body and '"$EFFORT_SUPPORTED"' in body
                      and "$GITHUB_ENV" in body)
        # $GITHUB_ENV reaches only LATER steps: an export moved after the session step writes
        # too late, so the resolver reads an absent var and fails open to `true` — green.
        ai = [i for i, s in enumerate(steps) if "claude-code-action" in str(s.get("uses", ""))]
        pos_ok.append(bool(ai) and ei[0] < min(ai))
ok = (key is not None and len(env_ok) == 3 and all(env_ok)
      and len(run_ok) == 3 and all(run_ok)
      and len(pos_ok) == 3 and all(pos_ok))
print("yes" if ok else "no")
PY
)"
  assert_eq "#1772: effort-export step sources the provider output, writes the resolver's PRFLOW_EFFORT_SUPPORTED key from that env var into GITHUB_ENV, and precedes the session step in all 3 workflows" "yes" "$R1772_EXPORT_ENV"

  # gh_kv normalizes a $GITHUB_ENV/$GITHUB_OUTPUT file written in GitHub's newline-safe
  # multiline-heredoc form (KEY<<DELIM\nvalue\nDELIM — the form this PR now uses everywhere)
  # back into KEY=VALUE lines for whole-line assertions. All #313 emitted values are
  # single-line, which is all this needs to handle.
  gh_kv() {  # file -> KEY=VALUE lines on stdout
    awk '
      d == "" { p = index($0, "<<"); if (p > 0) { k = substr($0, 1, p-1); d = substr($0, p+2) } next }
      $0 == d { d = ""; next }
      { print k "=" $0 }
    ' "$1"
  }
  # gh_topkeys prints the top-level env/output KEY names GitHub itself would set from a
  # $GITHUB_ENV/$GITHUB_OUTPUT file, heredoc-aware: a `KEY<<DELIM` block swallows every line up
  # to DELIM as the value, so a `FORGED=evil` line INSIDE a heredoc body is NOT a top-level var.
  # This is the GitHub-faithful check behind the newline-forge-prevention tests below.
  gh_topkeys() {  # file -> top-level KEY names, one per line
    python3 -c '
import sys
d=None
for line in open(sys.argv[1]):
    line=line.rstrip("\n")
    if d is None:
        i=line.find("<<")
        if i>0:
            print(line[:i]); d=line[i+2:]
        elif "=" in line:
            print(line.split("=",1)[0])
    elif line==d:
        d=None
' "$1"
  }
  # gh_topkeys self-test (anti-vacuity): the three forge assertions below rely on its
  # plain `KEY=` arm actually REPORTING a top-level key — if that arm were broken
  # (never yielding FORGED even from a plain line), all three forge tests would pass
  # vacuously and keep passing after the guarded regression. Prove the arm live.
  R313_TKPROBE="$(probe_tmp "#313 gh_topkeys self-test")" || R313_TKPROBE=""
  if [ -n "$R313_TKPROBE" ]; then
    printf 'FORGED=evil\n' > "$R313_TKPROBE"
    assert_eq "#313 gh_topkeys self-test: a plain KEY= line IS reported as a top-level key" "FORGED" \
      "$(gh_topkeys "$R313_TKPROBE")"
    # gh_topkeys heredoc-swallow arm DIRECT self-test (shadow VC-41): the forge tests
    # that feed a KEY<<DELIM body carrying a FORGED=evil line rely on this arm treating
    # that inner line as swallowed (NOT top-level). Prove it directly rather than only
    # transitively — construct a literal heredoc block and assert the top-level keys are
    # exactly the header key, and the inner FORGED= line is NOT reported.
    printf 'REAL<<D\nFORGED=evil\nD\nAFTER=1\n' > "$R313_TKPROBE"
    assert_eq "#313 gh_topkeys self-test: a FORGED= line INSIDE a KEY<<DELIM body is NOT a top-level key (heredoc-swallow arm)" "yes" \
      "$(printf '%s\n' "$(gh_topkeys "$R313_TKPROBE")" | grep -qxF 'REAL' \
         && printf '%s\n' "$(gh_topkeys "$R313_TKPROBE")" | grep -qxF 'AFTER' \
         && ! printf '%s\n' "$(gh_topkeys "$R313_TKPROBE")" | grep -qxF 'FORGED' && echo yes || echo no)"
    rm -f "$R313_TKPROBE"
  else
    echo "  SKIP  #313 gh_topkeys self-test (no writable temp)"
  fi

  # Behavioral coverage of the Resolve + Inject + Build-claude_args-head run BODIES (issue #313
  # shadow gap 2 + review Important #2): the 3-way body-identity pin proves the copies AGREE but
  # not that they are CORRECT — a uniform logic mutation (invert the security-adjacent bearer
  # branch, drop the effort gate, drop the resolver's `exit 1` fail-loud, break the env
  # expansion) stays GREEN. EXECUTE the extracted bodies with env set and $GITHUB_ENV /
  # $GITHUB_OUTPUT pointed at temp files, then assert the emitted (heredoc) lines + exit codes.
  R313_RES_BODY="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
print(next(s["run"] for j in d["jobs"].values() for s in j.get("steps",[]) if s.get("name")=="Resolve model provider"))' "$IMPL_WF")"
  R313_INJ_BODY="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
print(next(s["run"] for j in d["jobs"].values() for s in j.get("steps",[]) if s.get("name")=="Inject provider endpoint (provider-routed sections only)"))' "$IMPL_WF")"
  R313_CARGS_BODY="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
print(next(s["run"] for j in d["jobs"].values() for s in j.get("steps",[]) if s.get("name")=="Build claude_args head (model + conditional effort)"))' "$IMPL_WF")"

  # Resolve body (review Important #2): the fail-loud undefined/incomplete-provider branch
  # (`.error != ""` → ::error:: + exit 1) had NO runtime assertion — only 3-way byte-identity —
  # so a mutation dropping the `exit 1` or inverting the `.error != ""` test kept every #313
  # assertion GREEN while the workflow proceeded past a fail-loud condition. Drive the extracted
  # body against an error-marker config (assert rc=1 + ::error::) and a default config (rc=0 +
  # the emitted heredoc scalar/decision outputs).
  R313_GOUT0="$(probe_tmp "#313 resolve GITHUB_OUTPUT")" || R313_GOUT0=""
  if [ -n "$R313_RES_BODY" ] && [ -n "$R313_GOUT0" ]; then
    # Happy path: default (no-provider) config → rc 0, scalar outputs + decision heredoc emitted.
    R313_RC=0
    ( export CONFIG_JSON='{"claude_model":"m","prflow_implement":{}}' SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313 resolve-body: default (no-provider) config resolves rc 0" "0" "$R313_RC"
    gh_kv "$R313_GOUT0" > "$R313_GOUT0.kv"
    assert_eq "#313 resolve-body: default config emits provider=(empty) + model + effort_supported + decision (heredoc-safe)" "yes" \
      "$(grep -qxF 'provider=' "$R313_GOUT0.kv" && grep -qxF 'model=m' "$R313_GOUT0.kv" && grep -qxF 'effort_supported=true' "$R313_GOUT0.kv" && grep -q '^decision={' "$R313_GOUT0.kv" && echo yes || echo no)"
    : > "$R313_GOUT0"
    # Fail-loud: a section naming an undefined provider → resolver error marker → the body's
    # `.error != ""` branch emits ::error:: and exit 1 BEFORE any action step.
    R313_RC=0
    R313_OUT="$( export CONFIG_JSON='{"claude_model":"m","prflow_implement":{"provider":"nope"}}' SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 resolve-body: undefined provider fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 resolve-body: undefined provider emits ::error:: naming the section + provider" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'prflow_implement' && printf '%s' "$R313_OUT" | grep -qF "'nope'" && echo yes || echo no)"
    : > "$R313_GOUT0"
    # #1770 AC 13: an auth value OUTSIDE the three-value set fails loud, and the refusal names
    # all three legal values while NOT instructing the reader to supply base_url (the wrapper no
    # longer carries the "base_url + auth: bearer|api_key" remediation hint).
    R313_RC=0
    R313_OUT="$( export CONFIG_JSON='{"claude_model":"m","providers":{"p":{"auth":"xyz"}},"prflow_implement":{"provider":"p"}}' SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313/#1770 resolve-body: out-of-set auth fails loud (exit 1, AC 13)" "1" "$R313_RC"
    assert_eq "#313/#1770 resolve-body: the out-of-set-auth refusal names all three legal values and does NOT instruct base_url (AC 13)" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'bearer' && printf '%s' "$R313_OUT" | grep -qF 'bedrock_api_key' && ! printf '%s' "$R313_OUT" | grep -qF 'base_url' && echo yes || echo no)"
    # Provider-active path (review Suggestion #7): the resolve body was executed only for
    # default + error configs, never a provider-active one — so a mutation in the scalar-emit
    # jq for a real provider stayed uncovered here (caught only transitively). Drive a
    # provider-active config ($R313_CFG, defined above) and assert the emitted (heredoc)
    # scalar outputs + decision.
    : > "$R313_GOUT0"
    R313_RC=0
    ( export CONFIG_JSON="$R313_CFG" SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313 resolve-body: provider-active config resolves rc 0" "0" "$R313_RC"
    gh_kv "$R313_GOUT0" > "$R313_GOUT0.kv"
    assert_eq "#313 resolve-body: provider-active config emits provider/base_url/auth/model/effort_supported + decision (heredoc-safe)" "yes" \
      "$(grep -qxF 'provider=openrouter' "$R313_GOUT0.kv" && grep -qxF 'base_url=https://openrouter.ai/api' "$R313_GOUT0.kv" && grep -qxF 'auth=bearer' "$R313_GOUT0.kv" && grep -qxF 'model=z-ai/glm-5.2' "$R313_GOUT0.kv" && grep -qxF 'effort_supported=false' "$R313_GOUT0.kv" && grep -q '^decision={' "$R313_GOUT0.kv" && echo yes || echo no)"
    : > "$R313_GOUT0"
    # Newline-forge safety of the resolve body's SCALAR emit (review Suggestion #4): base_url is
    # config-sourced, so an embedded newline in it must NOT forge a top-level step output either.
    # Feed base_url="u\nFORGED=evil" and confirm a GitHub-faithful parse yields base_url but no
    # top-level FORGED. A revert of the scalar emit to `printf '%s=%s'` goes RED.
    ( export CONFIG_JSON='{"claude_model":"m","providers":{"p":{"base_url":"u\nFORGED=evil","auth":"bearer"}},"prflow_implement":{"provider":"p"}}' SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" ) >/dev/null 2>&1
    R313_TOPKEYS="$(gh_topkeys "$R313_GOUT0")"
    assert_eq "#313 resolve-body: an embedded-newline base_url cannot forge a top-level step output" "yes" \
      "$(printf '%s\n' "$R313_TOPKEYS" | grep -qxF 'base_url' && ! printf '%s\n' "$R313_TOPKEYS" | grep -qxF 'FORGED' && echo yes || echo no)"
    : > "$R313_GOUT0"
    # EMPTY config input: jq on empty stdin emits nothing with rc 0, so without the
    # empty-DECISION tripwire the body would "succeed" with zero step outputs and the
    # run would silently take the default path (or die later on a misdirected
    # empty-model error). Assert the tripwire fails loud instead.
    R313_RC=0
    R313_OUT="$( export CONFIG_JSON="" SECTION=prflow_implement GITHUB_OUTPUT="$R313_GOUT0"; bash -c "$R313_RES_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 resolve-body: EMPTY config input fails loud (exit 1, empty-DECISION tripwire)" "1" "$R313_RC"
    assert_eq "#313 resolve-body: EMPTY config input emits ::error:: naming the no-decision cause" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'produced no decision' && echo yes || echo no)"
    rm -f "$R313_GOUT0" "$R313_GOUT0.kv"
  else
    echo "  SKIP  #313 resolve-body behavioral checks (no writable temp / body extraction failed)"
  fi

  R313_GENV="$(probe_tmp "#313 inject GITHUB_ENV")" || R313_GENV=""
  if [ -n "$R313_INJ_BODY" ] && [ -n "$R313_GENV" ]; then
    # bearer → ANTHROPIC_BASE_URL + API_TIMEOUT_MS + ANTHROPIC_AUTH_TOKEN(secret) + env map, each
    # written via the newline-safe heredoc form (normalized back to KEY=VALUE by gh_kv).
    ( export DECISION='{"env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"z-ai/glm-4.7"}}' AUTH=bearer BASE_URL=https://openrouter.ai/api TIMEOUT_MS=3000000 PROVIDER=openrouter PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    # Do not use a deny-listed key name here (issue #1773): this assertion proves the env map
    # IS written, so a denied key would exit 1 before the emit and make it vacuous.
    assert_eq "#313 inject-body: bearer exports BASE_URL + API_TIMEOUT_MS + ANTHROPIC_AUTH_TOKEN + env map" "yes" \
      "$(grep -qxF 'ANTHROPIC_BASE_URL=https://openrouter.ai/api' "$R313_GENV.kv" && grep -qxF 'API_TIMEOUT_MS=3000000' "$R313_GENV.kv" && grep -qxF 'ANTHROPIC_AUTH_TOKEN=sekret' "$R313_GENV.kv" && grep -qxF 'ANTHROPIC_DEFAULT_HAIKU_MODEL=z-ai/glm-4.7' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # api_key → base_url written, but NO ANTHROPIC_AUTH_TOKEN (key rides the action input only);
    # and with TIMEOUT_MS="" NO API_TIMEOUT_MS line either — a mutation writing it unconditionally
    # (empty value) on the provider path goes RED (review Suggestion #2).
    ( export DECISION='{"env":{}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313 inject-body: api_key writes base_url but NOT ANTHROPIC_AUTH_TOKEN or API_TIMEOUT_MS (input-only, empty timeout)" "yes" \
      "$(grep -qxF 'ANTHROPIC_BASE_URL=u' "$R313_GENV.kv" && ! grep -q 'ANTHROPIC_AUTH_TOKEN' "$R313_GENV.kv" && ! grep -q 'API_TIMEOUT_MS' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # empty provider secret → fail loud (exit 1) before writing any endpoint (AC 6).
    # Capture the output and pin the guard's OWN message too — an exit-code-only
    # assertion certifies "fails loud" even if a mutation degrades the guard to a
    # mute `exit 1` (the message is what the operator debugs from).
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{}}' AUTH=bearer BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY="" SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 inject-body: empty provider secret fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 inject-body: empty provider secret emits ::error:: naming the secret" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'DEVFLOW_PROVIDER_API_KEY repository secret is empty' && echo yes || echo no)"
    : > "$R313_GENV"
    # Newline-injection safety (review Important #1 — the property the heredoc writes EXIST for):
    # a config value carrying an embedded newline must NOT split a KEY=VALUE line into a forged
    # top-level env var. Feed an env-map value embedding `\nFORGED=evil` (jq turns the JSON \n
    # into a real newline), then parse $GITHUB_ENV the GitHub-faithful way (a KEY<<DELIM heredoc
    # swallows every line up to DELIM as the value; only OUTSIDE a heredoc is `KEY=` a top-level
    # var). Assert MKEY is a top-level key but FORGED is NOT. A mutation reverting to
    # `printf '%s=%s'` splits the line → FORGED becomes a real env var → this goes RED.
    ( export DECISION='{"env":{"MKEY":"a\nFORGED=evil"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    R313_TOPKEYS="$(gh_topkeys "$R313_GENV")"
    assert_eq "#313 inject-body: an embedded-newline env-map value cannot forge a top-level env var (heredoc newline-injection safety)" "yes" \
      "$(printf '%s\n' "$R313_TOPKEYS" | grep -qxF 'MKEY' && ! printf '%s\n' "$R313_TOPKEYS" | grep -qxF 'FORGED' && echo yes || echo no)"
    : > "$R313_GENV"
    # env-map KEY validation (shadow S3): the heredoc protects VALUES, not the KEY
    # interpolated into the `KEY<<DELIM` header — a key carrying a newline or `<<`
    # could forge a var name or break the terminator. The inject body must fail loud
    # on a key outside the env-var-name charset, BEFORE writing any $GITHUB_ENV block.
    R313_RC=0
    R313_OUT="$( export DECISION=$'{"env":{"A\\nFORGED":"x"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 inject-body: an env-map key with an embedded newline fails loud (exit 1, key-validation guard)" "1" "$R313_RC"
    assert_eq "#313 inject-body: the invalid-key guard emits ::error:: naming an invalid env-var-name key" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'not a valid environment variable name' && echo yes || echo no)"
    R313_TOPKEYS="$(gh_topkeys "$R313_GENV")"
    assert_eq "#313 inject-body: a forged env-map key writes NO top-level env var (guard fired before emit)" "yes" \
      "$([ -z "$R313_TOPKEYS" ] && echo yes || echo no)"
    : > "$R313_GENV"
    # `<<`-carrying key is also rejected (would break the heredoc terminator).
    R313_RC=0
    ( export DECISION='{"env":{"K<<X":"x"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313 inject-body: an env-map key containing '<<' fails loud (exit 1, key-validation guard)" "1" "$R313_RC"
    : > "$R313_GENV"
    # Do not re-list the denied names here: read them out of the extracted step body, so a name
    # ADDED to the guard's IN(...) is covered by this loop instead of shipping untested.
    # Anchor to the deny guard's OWN denied_env_keys= assignment (issue #1911): the warn block below
    # carries a second `ascii_upcase | IN(...)` line, and an unanchored sed would sweep the watched
    # (warn, not deny) keys into the per-key refusal loop, failing the suite on names meant to warn.
    R1773_KEYS="$(printf '%s\n' "$R313_INJ_BODY" | sed -n '/denied_env_keys=/s/.*ascii_upcase | IN(\([^)]*\)).*/\1/p' | tr ',' '\n' | tr -d '"' | tr -d ' ')"
    # Assert extracted-is-a-SUPERSET of this list, never a count: a rename or typo inside IN(...)
    # leaves the extracted count unchanged while dropping a real name, and the loop then tests the
    # misspelling. Adding a denied name keeps this green, so a new name needs no edit here.
    R1773_EXPECTED='PATH GITHUB_TOKEN GH_TOKEN GITHUB_ENV GITHUB_OUTPUT GITHUB_PATH
ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN AWS_ACCESS_KEY_ID
AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN AWS_BEARER_TOKEN_BEDROCK BASH_ENV ENV
LD_PRELOAD LD_LIBRARY_PATH DYLD_INSERT_LIBRARIES NODE_OPTIONS PYTHONPATH
CLAUDE_CODE_SUBAGENT_MODEL'
    # Do not match a key anywhere in the output: a bare substring search passes on a short name the
    # static prose happens to contain, so it would not attribute the refusal to the guard's dynamic
    # echo. Match only inside the ::error::'s "forbidden key(s): <names>" segment, word-anchored.
    r1773_names_key() {  # <output> <key> -> rc 0 iff the forbidden-key segment names <key>
      case "$1" in *'contains forbidden key(s): '*) : ;; *) return 1 ;; esac
      R1773_SEG="${1#*contains forbidden key(s): }"
      R1773_SEG="${R1773_SEG%% —*}"
      printf '%s' "$R1773_SEG" | grep -qE "(^| )$2( |$)"
    }
    R1773_MISSING=""
    for R1773_EXP_KEY in $R1773_EXPECTED; do
      printf '%s\n' "$R1773_KEYS" | grep -qxF "$R1773_EXP_KEY" || R1773_MISSING="$R1773_MISSING $R1773_EXP_KEY"
    done
    assert_eq "#1773 inject-body: the guard still denies every name this block was written against (a deletion, rename or typo goes RED)" "" "$R1773_MISSING"
    for R1773_KEY in $R1773_KEYS; do
      R313_RC=0
      R313_OUT="$( export DECISION="{\"env\":{\"$R1773_KEY\":\"x\"}}" AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
      assert_eq "#1773 inject-body: forbidden env-map key $R1773_KEY fails loud (exit 1, deny-list guard)" "1" "$R313_RC"
      # Do not name a denied key literally in the workflow's ::error:: text: this assertion
      # would then pass without the guard's dynamic key echo.
      assert_eq "#1773 inject-body: forbidden key $R1773_KEY emits ::error:: naming the key + refusing" "yes" \
        "$(r1773_names_key "$R313_OUT" "$R1773_KEY" && printf '%s' "$R313_OUT" | grep -qiF 'refusing to run' && echo yes || echo no)"
      assert_eq "#1773 inject-body: forbidden key $R1773_KEY writes NO top-level env var (guard fired before emit)" "yes" \
        "$([ ! -s "$R313_GENV" ] && echo yes || echo no)"
      : > "$R313_GENV"
    done
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"github_token":"x"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#1773 inject-body: a case-variant denied key (github_token) is also refused (exit 1)" "1" "$R313_RC"
    # Do not reduce this to an exit-code-only assertion: exit 1 alone cannot distinguish the
    # deny-list guard from the shape guard or any later failure.
    assert_eq "#1773 inject-body: the case-variant refusal is the deny-list guard (::error:: names github_token)" "yes" \
      "$(r1773_names_key "$R313_OUT" 'github_token' && printf '%s' "$R313_OUT" | grep -qiF 'refusing to run' && echo yes || echo no)"
    : > "$R313_GENV"
    # Do not delete this positive control: without it the refusal above is not attributable to
    # the denied NAME rather than to the key being lower-case.
    ( export DECISION='{"env":{"github_token_id":"z"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#1773 inject-body: a lower-case non-denied key (github_token_id) is still exported (lower case alone is not the refusal)" "yes" \
      "$(grep -qxF 'github_token_id=z' "$R313_GENV.kv" && echo yes || echo no)"
    rm -f "$R313_GENV.kv"; : > "$R313_GENV"
    # Do not reduce this to a single denied key: it is what exercises the guard's
    # [ .env|keys[]|select ]|join(" ") collection rather than a single-element match.
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"PATH":"x","ANTHROPIC_API_KEY":"y"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#1773 inject-body: two denied keys in one map fail loud (exit 1)" "1" "$R313_RC"
    assert_eq "#1773 inject-body: the ::error:: names BOTH denied keys (join collects all, not just the first)" "yes" \
      "$(r1773_names_key "$R313_OUT" 'PATH' && r1773_names_key "$R313_OUT" 'ANTHROPIC_API_KEY' && echo yes || echo no)"
    : > "$R313_GENV"
    ( export DECISION='{"env":{"GITHUB_TOKEN_ID":"z"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#1773 inject-body: a near-miss non-denied key (GITHUB_TOKEN_ID) is still exported (IN() is exact-match)" "yes" \
      "$(grep -qxF 'GITHUB_TOKEN_ID=z' "$R313_GENV.kv" && echo yes || echo no)"
    rm -f "$R313_GENV.kv"; : > "$R313_GENV"
    # Do not prefix the denied_env_keys assignment with local/export or append `|| true`: the
    # bare form takes the jq exit status, and only that makes a malformed .env abort under
    # set -e instead of yielding an empty key list the guard reads as "nothing denied".
    R313_RC=0
    ( export DECISION='{"env":"oops"}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    R313_TOPKEYS="$(gh_topkeys "$R313_GENV")"
    assert_eq "#1773 inject-body: a non-object .env fails closed (non-zero exit, no env var written)" "yes" \
      "$([ "$R313_RC" -ne 0 ] && [ -z "$R313_TOPKEYS" ] && echo yes || echo no)"
    : > "$R313_GENV"
    # A well-formed env-map key still passes (no false fire on the documented keys).
    ( export DECISION='{"env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"glm-4.7"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313 inject-body: a valid env-map key passes the key-validation guard (no false fire)" "yes" \
      "$(grep -qxF 'ANTHROPIC_DEFAULT_HAIKU_MODEL=glm-4.7' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # #1770 AC 4/5: the bedrock_api_key arm exports the secret as AWS_BEARER_TOKEN_BEDROCK and
    # writes NEITHER ANTHROPIC_BASE_URL NOR ANTHROPIC_AUTH_TOKEN; the env map (AWS_REGION) still
    # rides via the shared passthrough. A mutation exporting ANTHROPIC_BASE_URL here goes RED.
    ( export DECISION='{"env":{"AWS_REGION":"us-east-1"}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313/#1770 inject-body: bedrock arm exports AWS_BEARER_TOKEN_BEDROCK + AWS_REGION, NOT ANTHROPIC_BASE_URL/ANTHROPIC_AUTH_TOKEN (AC 4/5)" "yes" \
      "$(grep -qxF 'AWS_BEARER_TOKEN_BEDROCK=awskey' "$R313_GENV.kv" && grep -qxF 'AWS_REGION=us-east-1' "$R313_GENV.kv" && ! grep -q 'ANTHROPIC_BASE_URL' "$R313_GENV.kv" && ! grep -q 'ANTHROPIC_AUTH_TOKEN' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # #1770: API_TIMEOUT_MS is hoisted to a single post-branch write, so it applies to the bedrock
    # arm too. Pin it on the bedrock arm — a mutation moving it back inside the bearer/api_key else
    # branch would silently drop API_TIMEOUT_MS on the bedrock arm while staying GREEN elsewhere.
    ( export DECISION='{"env":{"AWS_REGION":"us-east-1"}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS=600000 PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313/#1770 inject-body: bedrock arm writes API_TIMEOUT_MS (hoisted post-branch write applies to the bedrock arm)" "yes" \
      "$(grep -qxF 'API_TIMEOUT_MS=600000' "$R313_GENV.kv" && grep -qxF 'AWS_BEARER_TOKEN_BEDROCK=awskey' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # #1770 AC 7: the bedrock arm fails loud (exit 1) when its env map sets no AWS_REGION, and the
    # error names the section and provider.
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313/#1770 inject-body: bedrock arm with no AWS_REGION fails loud (exit 1, AC 7)" "1" "$R313_RC"
    assert_eq "#313/#1770 inject-body: the missing-region error names the section + provider + AWS_REGION (AC 7)" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'prflow_implement' && printf '%s' "$R313_OUT" | grep -qF "'bed'" && printf '%s' "$R313_OUT" | grep -qF 'AWS_REGION' && echo yes || echo no)"
    : > "$R313_GENV"
    # #1770 valid-falsy row: an EMPTY-STRING AWS_REGION is treated as absent (strings|select),
    # so the region guard still fails loud rather than exporting an empty region variable.
    R313_RC=0
    ( export DECISION='{"env":{"AWS_REGION":""}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313/#1770 inject-body: bedrock arm with EMPTY-string AWS_REGION fails loud (valid-falsy → absent, exit 1)" "1" "$R313_RC"
    : > "$R313_GENV"
    # #1770 wrong-type rows (number, object): a non-string AWS_REGION is filtered out by the
    # `strings` guard and treated as absent, so the region check fails loud. Pins `strings` — a
    # mutation dropping it would let a non-string region pass, then the run authenticates and dies.
    R313_RC=0
    ( export DECISION='{"env":{"AWS_REGION":123}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313/#1770 inject-body: bedrock arm with NUMBER AWS_REGION fails loud (wrong-type → absent via strings, exit 1)" "1" "$R313_RC"
    : > "$R313_GENV"
    R313_RC=0
    ( export DECISION='{"env":{"AWS_REGION":{"x":1}}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313/#1770 inject-body: bedrock arm with OBJECT AWS_REGION fails loud (wrong-type → absent via strings, exit 1)" "1" "$R313_RC"
    : > "$R313_GENV"
    # #1770 AC 8: a bedrock entry that ALSO carries base_url CONTINUES (exit 0), warns naming the
    # section/provider/base_url, and still writes NO ANTHROPIC_BASE_URL. This fixture pins the
    # suppression by supplying the very input whose export the arm drops.
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"AWS_REGION":"us-east-1"}}' AUTH=bedrock_api_key BASE_URL="https://x" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313/#1770 inject-body: bedrock arm carrying base_url continues (exit 0, AC 8)" "0" "$R313_RC"
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313/#1770 inject-body: bedrock+base_url warns naming section/provider/base_url AND writes no ANTHROPIC_BASE_URL (AC 8)" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::warning::' && printf '%s' "$R313_OUT" | grep -qF 'prflow_implement' && printf '%s' "$R313_OUT" | grep -qF "'bed'" && printf '%s' "$R313_OUT" | grep -qF 'base_url' && ! grep -q 'ANTHROPIC_BASE_URL' "$R313_GENV.kv" && echo yes || echo no)"
    : > "$R313_GENV"
    # #1770 AC 9: a BEARER entry whose env map carries AWS_REGION runs exactly as before — base_url
    # + auth token + the AWS_REGION passthrough, no bedrock token, and NO warning (a stray AWS_REGION
    # in a gateway entry's env map must not trip the bedrock path or emit a warning).
    R313_OUT="$( export DECISION='{"env":{"AWS_REGION":"us-east-1"}}' AUTH=bearer BASE_URL=https://g TIMEOUT_MS="" PROVIDER=g PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )"
    gh_kv "$R313_GENV" > "$R313_GENV.kv"
    assert_eq "#313/#1770 inject-body: bearer arm with AWS_REGION in env map runs unchanged, no bedrock token, NO warning (AC 9)" "yes" \
      "$(grep -qxF 'ANTHROPIC_BASE_URL=https://g' "$R313_GENV.kv" && grep -qxF 'ANTHROPIC_AUTH_TOKEN=sekret' "$R313_GENV.kv" && grep -qxF 'AWS_REGION=us-east-1' "$R313_GENV.kv" && ! grep -q 'AWS_BEARER_TOKEN_BEDROCK' "$R313_GENV.kv" && ! printf '%s' "$R313_OUT" | grep -qF '::warning::' && echo yes || echo no)"
    : > "$R313_GENV"
    # --- issue #1911: warn (never deny) when the env map names a watched key ---
    # rc 0 iff the ::warning:: "env map sets key(s): <names>" segment names <key>, word-anchored —
    # a bare substring search would pass on the static prose, not the guard's dynamic key echo.
    r1911_warns_key() {  # <output> <key>
      case "$1" in *'env map sets key(s): '*) : ;; *) return 1 ;; esac
      R1911_SEG="${1#*env map sets key(s): }"
      R1911_SEG="${R1911_SEG%% —*}"
      printf '%s' "$R1911_SEG" | grep -qE "(^| )$2( |$)"
    }
    # Read the watched set out of the extracted warn block (anchored to warned_env_keys=), so a name
    # ADDED to the warn IN(...) is covered here with no hand edit — a deletion/rename/typo goes RED.
    R1911_KEYS="$(printf '%s\n' "$R313_INJ_BODY" | sed -n '/warned_env_keys=/s/.*ascii_upcase | IN(\([^)]*\)).*/\1/p' | tr ',' '\n' | tr -d '"' | tr -d ' ')"
    R1911_EXPECTED='ANTHROPIC_BASE_URL API_TIMEOUT_MS HOME RUNNER_TEMP'
    R1911_MISSING=""
    for R1911_EXP in $R1911_EXPECTED; do
      printf '%s\n' "$R1911_KEYS" | grep -qxF "$R1911_EXP" || R1911_MISSING="$R1911_MISSING $R1911_EXP"
    done
    R1911_EXTRA=""
    for R1911_GOT in $R1911_KEYS; do
      printf '%s\n' "$R1911_EXPECTED" | tr ' ' '\n' | grep -qxF "$R1911_GOT" || R1911_EXTRA="$R1911_EXTRA $R1911_GOT"
    done
    assert_eq "#1911 inject-body: the warn block watches EXACTLY the four documented keys, no more no fewer (AC 1; deletion/rename/typo/addition goes RED)" "" "$R1911_MISSING$R1911_EXTRA"
    R1911_ON_DENYLIST=""
    for R1911_W in $R1911_KEYS; do
      printf '%s\n' "$R1773_KEYS" | grep -qxF "$R1911_W" && R1911_ON_DENYLIST="$R1911_ON_DENYLIST $R1911_W"
    done
    assert_eq "#1911 inject-body: no watched key is also a denied key, so the refusal loop covers deny names only (AC 7)" "" "$R1911_ON_DENYLIST"
    # AC 1 + AC 2: each watched key warns, names itself, exits 0, and is STILL written to $GITHUB_ENV.
    for R1911_W in $R1911_KEYS; do
      R313_RC=0
      R313_OUT="$( export DECISION="{\"env\":{\"$R1911_W\":\"x\"}}" AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
      assert_eq "#1911 inject-body: watched key $R1911_W warns and exits 0 (AC 1 — report and continue)" "yes" \
        "$([ "$R313_RC" -eq 0 ] && printf '%s' "$R313_OUT" | grep -qF '::warning::' && r1911_warns_key "$R313_OUT" "$R1911_W" && echo yes || echo no)"
      gh_kv "$R313_GENV" > "$R313_GENV.kv"
      assert_eq "#1911 inject-body: watched key $R1911_W is STILL written to \$GITHUB_ENV (AC 2 — the env map still wins)" "yes" \
        "$(grep -qxF "$R1911_W=x" "$R313_GENV.kv" && echo yes || echo no)"
      rm -f "$R313_GENV.kv"; : > "$R313_GENV"
    done
    # AC 3: case-folded — a lower-case spelling warns exactly as the upper-case name does.
    R313_OUT="$( export DECISION='{"env":{"home":"x"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )"
    assert_eq "#1911 inject-body: a lower-case watched key (home) warns (AC 3 — case-folded)" "yes" \
      "$(r1911_warns_key "$R313_OUT" 'home' && echo yes || echo no)"
    : > "$R313_GENV"
    # AC 3: whole-name — a longer name CONTAINING a watched key does NOT warn.
    R313_OUT="$( export DECISION='{"env":{"HOMEDIR":"x"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )"
    assert_eq "#1911 inject-body: a longer name containing a watched key (HOMEDIR) does NOT warn (AC 3 — whole-name)" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::warning::' && echo no || echo yes)"
    : > "$R313_GENV"
    # AC 1: two watched keys emit ONE ::warning:: naming both (the join collects all, not just first).
    R313_OUT="$( export DECISION='{"env":{"HOME":"x","RUNNER_TEMP":"y"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )"
    assert_eq "#1911 inject-body: two watched keys emit ONE ::warning:: naming both (AC 1)" "yes" \
      "$([ "$(printf '%s\n' "$R313_OUT" | grep -cF '::warning::')" = "1" ] && r1911_warns_key "$R313_OUT" 'HOME' && r1911_warns_key "$R313_OUT" 'RUNNER_TEMP' && echo yes || echo no)"
    : > "$R313_GENV"
    # AC 4: an env map naming none of the four → NO warning at all.
    R313_OUT="$( export DECISION='{"env":{"ANTHROPIC_DEFAULT_HAIKU_MODEL":"glm-4.7"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )"
    assert_eq "#1911 inject-body: an env map naming none of the four produces NO warning (AC 4)" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::warning::' && echo no || echo yes)"
    : > "$R313_GENV"
    # The Bedrock arm with ANTHROPIC_BASE_URL in the map: the map-decided watched-key warning fires
    # and the step still exits 0 (the case where the step's own base_url-ignored warning disagrees).
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"AWS_REGION":"us-east-1","ANTHROPIC_BASE_URL":"http://x"}}' AUTH=bedrock_api_key BASE_URL="" TIMEOUT_MS="" PROVIDER=bed PROVIDER_API_KEY=awskey SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#1911 inject-body: bedrock arm with ANTHROPIC_BASE_URL in the map warns for it and exits 0" "yes" \
      "$([ "$R313_RC" -eq 0 ] && r1911_warns_key "$R313_OUT" 'ANTHROPIC_BASE_URL' && echo yes || echo no)"
    : > "$R313_GENV"
    # AC 8: a provider entry with NO env key at all warns nothing and exits 0 (the warn block's own
    # reading of an absent .env introduces no new failure).
    R313_RC=0
    R313_OUT="$( export DECISION='{}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#1911 inject-body: a provider entry with no env key warns nothing and exits 0 (AC 8 — absent .env)" "yes" \
      "$([ "$R313_RC" -eq 0 ] && printf '%s' "$R313_OUT" | grep -qF '::warning::' && echo no || echo yes)"
    : > "$R313_GENV"
    # AC 8: a non-object .env still fails closed exactly as today (the deny guard catches it first);
    # the warn block adds no new failure mode. Non-zero exit, no top-level env var written.
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":"oops"}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    R313_TOPKEYS="$(gh_topkeys "$R313_GENV")"
    assert_eq "#1911 inject-body: a non-object .env still fails closed as today, warn block adds no new failure (AC 8)" "yes" \
      "$([ "$R313_RC" -ne 0 ] && [ -z "$R313_TOPKEYS" ] && echo yes || echo no)"
    : > "$R313_GENV"
    # AC 5 + deny-before-warn ordering: a denied key alongside a watched key refuses first
    # (::error::, non-zero) and no ::warning:: leaks — guards a future reorder that put the warn
    # block above the deny guard, which would warn on a run that is about to refuse.
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"github_token":"x","HOME":"y"}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#1911 inject-body: a denied key beside a watched key refuses first (::error::, non-zero) with no ::warning:: leaking (AC 5 + deny-before-warn ordering)" "yes" \
      "$([ "$R313_RC" -ne 0 ] && printf '%s' "$R313_OUT" | grep -qF '::error::' && ! printf '%s' "$R313_OUT" | grep -qF '::warning::' && echo yes || echo no)"
    : > "$R313_GENV"
    # AC 1/AC 2 valid-falsy: a watched key with an empty-string value still warns and is still
    # written (jq keys[] is value-agnostic; the valid-falsy row CLAUDE.md's config matrix calls
    # load-bearing, mirroring #1770's empty-string AWS_REGION case).
    R313_RC=0
    R313_OUT="$( export DECISION='{"env":{"HOME":""}}' AUTH=api_key BASE_URL=u TIMEOUT_MS="" PROVIDER=p PROVIDER_API_KEY=sekret SECTION=prflow_implement GITHUB_ENV="$R313_GENV"; bash -c "$R313_INJ_BODY" 2>&1 )" || R313_RC=$?
    R313_TOPKEYS="$(gh_topkeys "$R313_GENV")"
    assert_eq "#1911 inject-body: a watched key with an empty-string value still warns and is still written (AC 1/AC 2 — valid-falsy)" "yes" \
      "$([ "$R313_RC" -eq 0 ] && r1911_warns_key "$R313_OUT" 'HOME' && printf '%s\n' "$R313_TOPKEYS" | grep -qxF 'HOME' && echo yes || echo no)"
    rm -f "$R313_GENV" "$R313_GENV.kv"
  else
    echo "  SKIP  #313 inject-body behavioral checks (no writable temp / body extraction failed)"
  fi
  R313_GOUT="$(probe_tmp "#313 cargs GITHUB_OUTPUT")" || R313_GOUT=""
  if [ -n "$R313_CARGS_BODY" ] && [ -n "$R313_GOUT" ]; then
    # effort_supported=true → --effort present; false → dropped (AC 7). args is written via the
    # newline-safe heredoc form (normalized back to args=… by gh_kv).
    ( export MODEL=z-ai/glm-5.2 EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1
    assert_eq "#313 cargs-body: effort_supported=true → --effort in args" "args=--model z-ai/glm-5.2 --effort high" "$(gh_kv "$R313_GOUT")"
    : > "$R313_GOUT"
    ( export MODEL=z-ai/glm-5.2 EFFORT=high EFFORT_SUPPORTED=false GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1
    assert_eq "#313 cargs-body: effort_supported=false → --effort dropped" "args=--model z-ai/glm-5.2" "$(gh_kv "$R313_GOUT")"
    : > "$R313_GOUT"
    # effort_supported=true but EFFORT empty → --effort STILL dropped (the -n co-guard). Unreachable
    # on the default path (config effort defaults to "high"), but pins the guard so a valueless
    # --effort can never reach the CLI — review Suggestion #3.
    ( export MODEL=z-ai/glm-5.2 EFFORT="" EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1
    assert_eq "#313 cargs-body: effort_supported=true but empty EFFORT → --effort dropped (no valueless flag)" "args=--model z-ai/glm-5.2" "$(gh_kv "$R313_GOUT")"
    : > "$R313_GOUT"
    # empty MODEL → fail loud (the iter-2 guard; the two command workflows had none before).
    # Capture the output and pin the guard's OWN message (exit-code-only would stay
    # green if a mutation degraded the guard to a mute exit 1).
    R313_RC=0
    R313_OUT="$( export MODEL="" EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: empty MODEL fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: empty MODEL emits ::error:: naming claude_model" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'claude_model is missing' && echo yes || echo no)"
    : > "$R313_GOUT"
    # Flag-injection guard (review iter-2 security finding): MODEL/EFFORT are spliced
    # UNQUOTED into claude_args, and the runner's MODEL bootstrap fallback can read
    # PR-head config — a value carrying whitespace would smuggle extra CLI flags
    # (e.g. `x --dangerously-skip-permissions`) into the privileged review invocation.
    # The guard must fail loud on whitespace/quotes in EITHER operand, and pass a
    # normal bracket-suffixed model id unchanged.
    R313_RC=0
    R313_OUT="$( export MODEL='x --dangerously-skip-permissions' EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: whitespace in MODEL fails loud (exit 1, flag-injection guard)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: whitespace in MODEL emits the flag-injection ::error::" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'flag-injection guard' && echo yes || echo no)"
    : > "$R313_GOUT"
    R313_RC=0
    ( export MODEL=z-ai/glm-5.2 EFFORT=$'high --evil' EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313 cargs-body: whitespace in EFFORT fails loud (exit 1, flag-injection guard)" "1" "$R313_RC"
    : > "$R313_GOUT"
    # Flag-SHAPED single tokens (the iter-1 gate's C1 bypass): rejecting whitespace/quotes
    # alone is not enough — the action tokenises claude_args shell-style, so a bare
    # `--dangerously-skip-permissions` in MODEL/EFFORT records --model/--effort as
    # valueless and passes the injected token through as its own flag. MODEL rejects a
    # leading dash; EFFORT is enum-pinned (so ANY non-enum junk also fails loud).
    # Each rejection is ATTRIBUTED to its own arm by a DISTINCT message substring
    # (shadow S4): the bare `flag-injection guard` phrase appears in all three arms,
    # so an exit-code-only assertion cannot tell a dash-arm rejection from an
    # allowlist- or enum-arm one — a reordered/merged arm would stay green. Pin the
    # arm-specific phrase so each fixture proves the arm it was written to exercise.
    R313_RC=0
    R313_OUT="$( export MODEL='--dangerously-skip-permissions' EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: flag-shaped MODEL (leading dash, no whitespace) fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: flag-shaped MODEL rejection is attributed to the leading-dash arm" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'flag-shaped (leading dash)' && echo yes || echo no)"
    : > "$R313_GOUT"
    R313_RC=0
    R313_OUT="$( export MODEL=z-ai/glm-5.2 EFFORT='--dangerously-skip-permissions' EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: flag-shaped EFFORT fails loud (exit 1, enum arm)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: flag-shaped EFFORT rejection is attributed to the effort-enum arm" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'not one of low/medium/high/xhigh/max' && echo yes || echo no)"
    : > "$R313_GOUT"
    R313_RC=0
    R313_OUT="$( export MODEL=z-ai/glm-5.2 EFFORT='garbage' EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: non-enum EFFORT fails loud (exit 1, enum arm)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: non-enum EFFORT rejection is attributed to the effort-enum arm" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'not one of low/medium/high/xhigh/max' && echo yes || echo no)"
    : > "$R313_GOUT"
    # Positive-allowlist arm (the re-gate's locale finding): a bytewise [[:space:]]
    # blacklist misses Unicode whitespace (NBSP etc.) under a non-UTF-8 locale while
    # the action's JS tokeniser still splits on it — the allowlist must reject it in
    # EVERY locale (C forced here), and a backslash (token-merge class) likewise.
    R313_RC=0
    R313_OUT="$( MODEL="$(printf 'x\302\240--dangerously-skip-permissions')"; export LC_ALL=C MODEL EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: NBSP-embedded MODEL fails loud under LC_ALL=C (allowlist, locale-proof)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: NBSP MODEL rejection is attributed to the allowlist arm" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'outside the model-id allowlist' && echo yes || echo no)"
    : > "$R313_GOUT"
    R313_RC=0
    R313_OUT="$( export MODEL='x\evil' EFFORT=high EFFORT_SUPPORTED=true GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 cargs-body: backslash in MODEL fails loud (allowlist)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: backslash MODEL rejection is attributed to the allowlist arm" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'outside the model-id allowlist' && echo yes || echo no)"
    : > "$R313_GOUT"
    # Bedrock-style colon id must pass the allowlist (no false fire on legit ids).
    ( export MODEL='us.anthropic.claude-3:0' EFFORT=high EFFORT_SUPPORTED=false GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1
    assert_eq "#313 cargs-body: colon-carrying Bedrock-style model id passes the allowlist (no false fire)" "args=--model us.anthropic.claude-3:0" "$(gh_kv "$R313_GOUT")"
    : > "$R313_GOUT"
    # Structural pin on the newline-safe args<< heredoc emit: the whitespace guard now
    # rejects an embedded-newline MODEL before any emit, so the forge test below can no
    # longer catch a revert of the emit itself to `echo "args=$ARGS"` — pin the heredoc
    # emit form directly instead (defense-in-depth for the emit idiom).
    assert_eq "#313 cargs-body: args emitted via the newline-safe heredoc form (args<< pin)" "yes" \
      "$(printf '%s' "$R313_CARGS_BODY" | grep -qF "printf 'args<<%s" && echo yes || echo no)"
    # Z.ai bracket-suffix model ids must pass the guard untouched (no false fire).
    ( export MODEL='glm-5.2[1m]' EFFORT=high EFFORT_SUPPORTED=false GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1
    assert_eq "#313 cargs-body: bracket-suffix model id passes the flag-injection guard (no false fire)" "args=--model glm-5.2[1m]" "$(gh_kv "$R313_GOUT")"
    : > "$R313_GOUT"
    # Newline-forge safety of the cargs emit: MODEL is config-sourced, so an embedded
    # newline must never forge a top-level step output. A newline is whitespace, so the
    # flag-injection guard now rejects it BEFORE any emit — assert the fail-loud exit
    # AND that the output file carries no top-level key at all (neither args nor FORGED).
    R313_RC=0
    ( export MODEL=$'x\nFORGED=evil' EFFORT=high EFFORT_SUPPORTED=false GITHUB_OUTPUT="$R313_GOUT"; bash -c "$R313_CARGS_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    R313_TOPKEYS="$(gh_topkeys "$R313_GOUT")"
    assert_eq "#313 cargs-body: an embedded-newline MODEL fails loud (whitespace guard)" "1" "$R313_RC"
    assert_eq "#313 cargs-body: an embedded-newline MODEL cannot forge a top-level step output (no keys emitted)" "yes" \
      "$([ -z "$R313_TOPKEYS" ] && echo yes || echo no)"
    rm -f "$R313_GOUT"
  else
    echo "  SKIP  #313 cargs-body behavioral checks (no writable temp / body extraction failed)"
  fi

  # Runner-only AC-8 guard (review Important #2, second gap): the "Require OAuth token on the
  # Anthropic default path" step was previously source-pinned but never EXECUTED — an
  # inverted -z/-n test would leave the ::error:: string in place and stay GREEN while silently
  # degrading the default path. Execute the extracted body: empty OAUTH → exit 1 + ::error::;
  # a present OAUTH → exit 0. (No $GITHUB_ENV/OUTPUT temp needed — the step only branches on OAUTH.)
  R313_OAUTH_BODY="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
print(next(s["run"] for j in d["jobs"].values() for s in j.get("steps",[]) if s.get("name")=="Require OAuth token on the Anthropic default path"))' "$RUNNER_WF")"
  if [ -n "$R313_OAUTH_BODY" ]; then
    R313_RC=0
    R313_OUT="$( export OAUTH=""; bash -c "$R313_OAUTH_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 oauth-guard: empty OAuth on the Anthropic default path fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 oauth-guard: empty OAuth emits ::error:: naming CLAUDE_CODE_OAUTH_TOKEN" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF '::error::' && printf '%s' "$R313_OUT" | grep -qF 'CLAUDE_CODE_OAUTH_TOKEN' && echo yes || echo no)"
    R313_RC=0
    ( export OAUTH="oauth-token"; bash -c "$R313_OAUTH_BODY" ) >/dev/null 2>&1 || R313_RC=$?
    assert_eq "#313 oauth-guard: a present OAuth token passes (exit 0)" "0" "$R313_RC"
    # Degraded-base-read branch (shadow S2): when the trusted base config was UNREADABLE
    # (config_source=degraded) the empty provider decision is NOT "no provider configured"
    # — the guard must name the real cause and NOT misdirect. Assert the degraded message,
    # and that it does NOT falsely claim no provider is configured.
    R313_RC=0
    R313_OUT="$( export OAUTH="" CONFIG_SOURCE="degraded"; bash -c "$R313_OAUTH_BODY" 2>&1 )" || R313_RC=$?
    assert_eq "#313 oauth-guard: degraded base read + empty OAuth fails loud (exit 1)" "1" "$R313_RC"
    assert_eq "#313 oauth-guard: degraded branch names the unreadable-config cause, not a false 'no provider configured'" "yes" \
      "$(printf '%s' "$R313_OUT" | grep -qF 'trusted base-ref .prflow/config.json could not be read' \
         && ! printf '%s' "$R313_OUT" | grep -qF 'No model provider is configured' && echo yes || echo no)"
  else
    echo "  SKIP  #313 oauth-guard behavioral check (body extraction failed)"
  fi

  # Step-ordering pin (shadow S1): in devflow-runner.yml the provider-endpoint inject
  # step (which writes the bearer DEVFLOW_PROVIDER_API_KEY into job-wide $GITHUB_ENV as
  # ANTHROPIC_AUTH_TOKEN) MUST run AFTER the opt-in 'Provision project environment' step
  # (which executes PR-author build code) and still BEFORE 'Run Claude Code'. A regression
  # that moves inject back before provision re-exposes the secret to PR code — pin the order.
  R313_ORDER="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
names=[s.get("name") for j in d["jobs"].values() for s in j.get("steps",[])]
def idx(n): return names.index(n) if n in names else -1
pi=idx("Provision project environment (opt-in)")
ii=idx("Inject provider endpoint (provider-routed sections only)")
ri=idx("Run Claude Code")
print("yes" if (pi>=0 and ii>=0 and ri>=0 and pi<ii<ri) else "no")' "$RUNNER_WF")"
  assert_eq "#313 security: devflow-runner.yml injects the provider endpoint AFTER provision and before Run Claude Code (shadow S1)" "yes" "$R313_ORDER"

  # config_source PRODUCER coverage (review PTA-1 + SFH-1): the shadow-S2 config_source
  # signal (ok/absent/degraded) that disambiguates the runner's OAuth-default guard remedy
  # was covered only at the CONSUMER (the OAuth-guard body above, with CONFIG_SOURCE injected
  # by hand). Its PRODUCER — the baseprovision step's three-way selection — had NO coverage,
  # so a future edit dropping a `='degraded'` assignment, or the emit itself, would silently
  # regress the misdirection fix while every #313 consumer test stayed green. Trace the operand
  # to its producer and prove it emits the right value on EVERY path (the CLAUDE.md operand-
  # producer discipline): drive the EXTRACTED baseprovision run body (not a retyped copy — the
  # same PyYAML `st["run"]` extraction the bodies above use) in a git sandbox with a local
  # origin, across every config_source outcome (ok / absent / degraded) and each read path
  # that produces it (valid, no-config, malformed, non-object, unfetchable, empty-base-ref).
  # Parse config_source DIRECTLY (it is a plain `echo
  # "config_source=…"` KEY=VALUE emit, NOT a heredoc, so gh_kv — heredoc-only — cannot read it).
  R313_BASEPROV_BODY="$(python3 -c 'import yaml,sys
d=yaml.safe_load(open(sys.argv[1]))
print(next(s["run"] for j in d["jobs"].values() for s in j.get("steps",[]) if s.get("name")=="Read trusted base-ref provisioning config"))' "$RUNNER_WF")"
  R313_CS_DIR="$(git_sandbox "#313 config_source producer sandbox")"
  if [ -n "$R313_BASEPROV_BODY" ] && [ "$R313_CS_DIR" != "/dev/null/devflow-git-sandbox-unavailable" ]; then
    # $1 = base-ref .prflow/config.json contents ('' → no config file committed);
    # $2 = BASE_REF the step reads (default 'basebr'; '' exercises the empty-base-ref path).
    # Rebuilds a fresh bare origin each call so `git fetch origin <ref>` resolves the ref we
    # control. Echoes the produced config_source.
    r313_cs() {
      rm -rf "$R313_CS_DIR/work" "$R313_CS_DIR/base.git"
      git init -q --bare "$R313_CS_DIR/base.git"
      git init -q "$R313_CS_DIR/work"
      git -C "$R313_CS_DIR/work" config user.email t@t.t
      git -C "$R313_CS_DIR/work" config user.name t
      mkdir -p "$R313_CS_DIR/work/.prflow"
      [ -n "$1" ] && printf '%s' "$1" > "$R313_CS_DIR/work/.prflow/config.json"
      git -C "$R313_CS_DIR/work" add -A >/dev/null 2>&1
      git -C "$R313_CS_DIR/work" commit -q --allow-empty -m x >/dev/null 2>&1
      git -C "$R313_CS_DIR/work" branch -M basebr >/dev/null 2>&1
      git -C "$R313_CS_DIR/work" remote add origin "$R313_CS_DIR/base.git" >/dev/null 2>&1
      git -C "$R313_CS_DIR/work" push -q origin basebr >/dev/null 2>&1
      local out; out="$(mktemp)"
      ( cd "$R313_CS_DIR/work" && export BASE_REF="${2-basebr}" RUNNER_TEMP="$R313_CS_DIR/rt" GITHUB_OUTPUT="$out"; mkdir -p "$RUNNER_TEMP"; bash -c "$R313_BASEPROV_BODY" ) >/dev/null 2>&1
      sed -n 's/^config_source=//p' "$out"
      rm -f "$out"
    }
    assert_eq "#313 config_source producer: valid base config → 'ok'" "ok" \
      "$(r313_cs '{"claude_model":"m"}')"
    assert_eq "#313 config_source producer: no committed config on the base ref → 'absent' (bootstrap case, NOT degraded)" "absent" \
      "$(r313_cs '')"
    assert_eq "#313 config_source producer: malformed base config → 'degraded' (shadow-S2 read-failed)" "degraded" \
      "$(r313_cs 'not-json{')"
    assert_eq "#313 config_source producer: non-object base config (bare scalar) → 'degraded'" "degraded" \
      "$(r313_cs '42')"
    assert_eq "#313 config_source producer: un-fetchable base ref → 'degraded'" "degraded" \
      "$(r313_cs '{"claude_model":"m"}' 'no-such-ref-xyz')"
    # SFH-1 fix: an empty BASE_REF (base ref could not be determined) must resolve to
    # 'degraded', NOT the initial 'absent' — else the OAuth-default guard would misdirect
    # ("no provider configured") when a base-configured provider was in fact silently un-read.
    # This fixture goes RED against the pre-fix code (which left it 'absent').
    assert_eq "#313 config_source producer: empty BASE_REF → 'degraded' (SFH-1: not the initial 'absent')" "degraded" \
      "$(r313_cs '{"claude_model":"m"}' '')"
    unset -f r313_cs
    rm -rf "$R313_CS_DIR" 2>/dev/null
  else
    echo "  SKIP  #313 config_source producer behavioral checks (no PyYAML body extraction / no git sandbox)"
  fi
else
  echo "  SKIP  #313 body-identity + behavioral check (PyYAML unavailable)"
fi

# Matrix completeness (review PTA-2): the {field}×{wrong-type/empty} sweep pins base_url
# both missing and empty-string, but auth only missing + wrong-value ('Bearer'); add the
# empty-string auth cell so the three-value auth disjunct is pinned
# on an EMPTY value too (a real input shape a future guard rewrite could regress).
assert_eq "#313 matrix: provider entry with EMPTY auth ('') → incomplete_provider marker (auth-disjunct completeness)" \
  '{"error":"incomplete_provider","section":"prflow_implement","provider":"p","detail":"provider auth must be one of bearer, api_key, bedrock_api_key"}' \
  "$(echo '{"claude_model":"m","providers":{"p":{"base_url":"u","auth":""}},"prflow_implement":{"provider":"p"}}' | r313 prflow_implement)"
# AC 8 (review PTA-3): the runner's dead `model` workflow_call input was removed. Pin the
# reference absence so a re-introduced `inputs.model` (a merge-revert of the threading) goes
# RED — the removal becomes a conscious future change rather than a silent regression.
assert_eq "#313 AC8: devflow-runner.yml carries no reference to the removed dead 'model' workflow_call input" "0" \
  "$(pin_count 'inputs.model' "$RUNNER_WF")"

# #1770 provider-schema vocabulary (config.schema.json): the auth enum and the base_url
# conditional are typed config-vocabulary boundaries the resolver's runtime checks mirror.
# structural-pin-ok: schema-config-vocabulary -- the provider entry auth enum + required set
# is a typed config vocabulary; AC 12 pins it to exactly three values and AC 15 pins the
# entry's closed-field guard.
R1770_SCHEMA="$LIB/../.prflow/config.schema.json"
assert_eq "#1770 AC12: providers entry auth enum accepts exactly bearer/api_key/bedrock_api_key" \
  '["bearer","api_key","bedrock_api_key"]' \
  "$(jq -c '.properties.providers.additionalProperties.properties.auth.enum' "$R1770_SCHEMA")"
assert_eq "#1770 AC15: providers entry still refuses unknown fields (additionalProperties:false)" "false" \
  "$(jq -c '.properties.providers.additionalProperties.additionalProperties' "$R1770_SCHEMA")"
assert_eq "#1770: providers entry no longer lists base_url in its top-level required set" "false" \
  "$(jq -c '(.properties.providers.additionalProperties.required // []) | any(. == "base_url")' "$R1770_SCHEMA")"
assert_eq "#1770: providers entry conditionally requires base_url for bearer/api_key (allOf if/then)" "yes" \
  "$(jq -e '.properties.providers.additionalProperties.allOf | any((.if.properties.auth.enum == ["bearer","api_key"]) and (.then.required == ["base_url"]))' "$R1770_SCHEMA" >/dev/null 2>&1 && echo yes || echo no)"

unset RESOLVER

# Mutation check: the absence pin above only proves "count is 0 today" — it does not
# prove the awk fence-parser + grep would actually *catch* a reintroduced bare jq (a
# silently-broken fence regex would also read 0 and stay GREEN). Run the identical
# pipeline against a synthetic fixture carrying one bare `jq` call inside a ```bash
# fence and assert the count flips to nonzero, proving the guard fails closed.
SKILL_JQ_BARE_FIXTURE_DIR="$(mktemp -d)"
cat > "$SKILL_JQ_BARE_FIXTURE_DIR/fixture.md" <<'EOF'
# Fixture

```bash
echo hi
jq -r '.x' <<< "$INPUT"
```
EOF
SKILL_JQ_BARE_MUTATED="$(
  find "$SKILL_JQ_BARE_FIXTURE_DIR" -type f -name '*.md' 2>/dev/null | while IFS= read -r _f; do
    awk '
      /^[[:space:]]*```(bash|sh|shell)[[:space:]]*$/ { inb=1; next }
      /^[[:space:]]*```[[:space:]]*$/ { inb=0; next }
      inb { print }
    ' "$_f"
  done \
  | grep -v 'run-jq\.sh' \
  | grep -E '(^|[[:space:]|&;(`])jq[[:space:]]+(-|'"'"'|"|\.|empty|length|keys|type|to_entries)' \
  | grep -vE 'jq(\.exe)? --version' | grep -c . || true)"
assert_eq "#253 skills-jq mutation check: awk fence-parser catches a reintroduced bare jq (guard fails closed, not vacuous)" "1" "$SKILL_JQ_BARE_MUTATED"
rm -rf "$SKILL_JQ_BARE_FIXTURE_DIR"

# ── #253 run-jq.sh behavioral coverage — the wrapper carries logic the #247
#    resolver tests don't reach (pure-bash BASH_SOURCE dir derivation, the
#    source-guard, the partial-deploy fallback, DEVFLOW_JQ honoring on that
#    fallback, and exec stdin/args/exit passthrough). Static existence-pinning
#    alone would stay GREEN if any of those regressed, so exercise them. Stub
#    jq (echoes a marker + its args, then cats stdin) proves the wrapper reached
#    it with args and stdin intact; the DEVFLOW_JQ override is honored without a
#    probe, so these stay hermetic (no real jq needed). ──
RJQ_SH="$DJQ_ROOT/scripts/run-jq.sh"
RJQ_STUB="$(mktemp -d)"
printf '#!/usr/bin/env bash\nprintf "STUBJQ:%%s\\n" "$*"\ncat\n' > "$RJQ_STUB/jq"; chmod +x "$RJQ_STUB/jq"
# (a) DEVFLOW_JQ override honored (no probe) + args + stdin pass through exec.
RJQ_OUT="$(printf 'STDIN_MARK\n' | DEVFLOW_JQ="$RJQ_STUB/jq" bash "$RJQ_SH" -r '.x')"
assert_eq "#253 run-jq.sh: DEVFLOW_JQ override honored, args + stdin pass through exec" "yes" \
  "$(printf '%s' "$RJQ_OUT" | grep -q 'STUBJQ:-r .x' && printf '%s' "$RJQ_OUT" | grep -q 'STDIN_MARK' && echo yes || echo no)"
# (b) exec propagates jq's exit code — a stub exiting 7 makes the wrapper exit 7.
printf '#!/usr/bin/env bash\nexit 7\n' > "$RJQ_STUB/jq7"; chmod +x "$RJQ_STUB/jq7"
DEVFLOW_JQ="$RJQ_STUB/jq7" bash "$RJQ_SH" '.' >/dev/null 2>&1; RJQ_RC=$?
assert_eq "#253 run-jq.sh: exec propagates jq's exit code (7), never masks it as 0" "7" "$RJQ_RC"
# (c) partial deploy — scripts/ copied WITHOUT sibling lib/: the source-guard
#     fails, a specific breadcrumb fires, DEVFLOW_JQ is still honored (never an
#     empty invocation), and the best-effort exit-0 contract survives.
RJQ_PARTIAL="$(mktemp -d)"; mkdir -p "$RJQ_PARTIAL/scripts"; cp "$RJQ_SH" "$RJQ_PARTIAL/scripts/"
RJQ_POUT="$(printf 'X\n' | DEVFLOW_JQ="$RJQ_STUB/jq" bash "$RJQ_PARTIAL/scripts/run-jq.sh" -r '.y' 2>"$RJQ_STUB/perr")"; RJQ_PRC=$?
assert_eq "#253 run-jq.sh: partial deploy (no sibling lib/) still honors DEVFLOW_JQ, no empty exec" "yes" \
  "$(printf '%s' "$RJQ_POUT" | grep -q 'STUBJQ:-r .y' && echo yes || echo no)"
assert_eq "#253 run-jq.sh: partial deploy emits the specific 'could not source lib/resolve-jq.sh' breadcrumb" "yes" \
  "$(grep -q 'could not source lib/resolve-jq.sh beside it' "$RJQ_STUB/perr" && echo yes || echo no)"
assert_eq "#253 run-jq.sh: partial deploy preserves the best-effort exit-0 contract" "0" "$RJQ_PRC"

rm -rf "$JQT0" "$JQT1" "$JQT2" "$JQT2D" "$JQTD" "$NPT4" "$NPT4B" "$NPT4C" "$NPT4D" "$NPT4E" "$NPT4G" "$NPT4I" "$JQTP" "$JQT10" "$JQT6" "$JQT7" "$JQT8" "$SCVJ" "$SCVO" "$PFPC" "$JQT7D" "$JQNEG" "$GENTR" "$RJQ_STUB" "$RJQ_PARTIAL"

