echo "helper-anchor portability + cloud-form layout fixtures (issue #702, AC6/AC7)"
# ────────────────────────────────────────────────────────────────────────────
# AC6 (local portability): a focused path-family corpus
# (lib/test/fixtures/path-portability/families.tsv) drives the REAL
# devflow_normalize_path over the four supported host-path families — Linux
# POSIX, macOS POSIX, WSL Windows-form, Git Bash/MSYS2 Windows-form — proving
# the local portable helper-anchor form resolves for each. The four families
# are complete by construction for the POSIX-shell contract; the driver asserts
# the corpus carries exactly them. Complements the #247 T4* stub tests: those
# pin individual arms of the helper, this pins the family SET as a corpus.
PP_TEST="$LIB/test/path-portability-test.sh"
# Capture the driver's per-FAIL stderr so a RED run names the failing family
# instead of only "expected ok, got FAILED"; the success path stays quiet.
_PP_ERR="$(mktemp)"
if bash "$PP_TEST" >/dev/null 2>"$_PP_ERR"; then _PP=ok; else _PP=FAILED; echo "  driver stderr (path-portability-test.sh):"; cat "$_PP_ERR"; fi
rm -f "$_PP_ERR"
assert_eq "#702 AC6: path-portability family corpus resolves for all four host-path families" "ok" "$_PP"

# AC7 (source and consumer layouts): a focused integration driver materializes
# the two committed seed layouts (lib/test/fixtures/cloud-form-layouts/
# {source-repo,consumer}) into throwaway git checkouts and executes the cloud
# helper-invocation form against each, with a space in the checkout path AND a
# shallow detached checkout represented in both. Exit 0 == every layout × state
# resolved the anchor and ran the vendored-literal helper (sentinel ANCHOR-OK).
CFL_TEST="$LIB/test/cloud-form-layout-test.sh"
# Same diagnostic capture as AC6: on failure, surface which layout x state broke.
_CFL_ERR="$(mktemp)"
if bash "$CFL_TEST" >/dev/null 2>"$_CFL_ERR"; then _CFL=ok; else _CFL=FAILED; echo "  driver stderr (cloud-form-layout-test.sh):"; cat "$_CFL_ERR"; fi
rm -f "$_CFL_ERR"
assert_eq "#702 AC7: cloud form runs against source-repo + consumer layouts (spaces + shallow detached)" "ok" "$_CFL"

# ────────────────────────────────────────────────────────────────────────────
echo "running-bash diagnostic: preflight.sh devflow-bash breadcrumb + remedy (issue #248)"
# ────────────────────────────────────────────────────────────────────────────
# preflight.sh emits a `devflow-bash:` breadcrumb naming the POSIX bash its .sh
# helpers run under (interpreter path + $BASH_VERSION) and surfaces DEVFLOW_BASH
# when it is set, so a user can confirm the intended bash took effect. When it is
# NOT running under a POSIX bash (empty $BASH_VERSION under sh/dash) it prints a
# remedy naming WSL/Git Bash/MSYS2 bash + the DEVFLOW_BASH override and exits
# non-zero BEFORE the first bash-only construct (`${BASH_SOURCE[0]}`) would abort.
# The breadcrumb goes to stderr; tests capture 2>&1. DEVFLOW_BASH is honored at
# the invocation layer (the agent/runner that shells into bash), NOT selected by
# preflight — so these tests cover the diagnostic, and V1 (the invocation-layer
# behavior) is a documented manual verification, not automatable here.
PF248="$LIB/preflight.sh"

# ── T1 (AC2/AC4): under bash, the breadcrumb names the running bash + the LIVE
#    $BASH_VERSION, the exit-0 contract and byte-identical pass line are unchanged,
#    and an unset DEVFLOW_BASH adds nothing (no-op). Stub PATH + fake python3 so
#    preflight reaches its normal exit 0. ──
T248="$(mktemp -d)"; build_stub_bin "$T248"; make_fake_python "$T248/python3" "3.12.4" 3 12
PF248_OUT="$(PATH="$T248" bash "$PF248" 2>&1)"; PF248_RC=$?
assert_eq "#248 preflight: bash run → exit 0 (AC4 unchanged)" "0" "$PF248_RC"
assert_eq "#248 preflight: emits the devflow-bash breadcrumb naming the running bash (AC2/T1)" "yes" \
  "$(printf '%s' "$PF248_OUT" | grep -q 'devflow-bash: running under bash ' && echo yes || echo no)"
assert_eq "#248 preflight: breadcrumb carries the live \$BASH_VERSION (AC2/T1)" "yes" \
  "$(printf '%s' "$PF248_OUT" | grep -qF "$BASH_VERSION" && echo yes || echo no)"
# Pin the OTHER AC2 breadcrumb component — the interpreter path (${BASH:-unknown}).
# Assert a non-empty path token sits between "running under bash " and " (": a
# regression that dropped ${BASH:-unknown} (reformatting to "running under bash
# ($BASH_VERSION)") leaves "(" immediately after the prefix and goes RED. Pins the
# FIELD's presence without hardcoding the (test-temp, per-run) path value, so it is
# robust rather than fragile. The `unknown` fallback still satisfies it (a present
# field), which is the intended AC2 semantics.
assert_eq "#248 preflight: breadcrumb carries a non-empty interpreter path (AC2/T1)" "yes" \
  "$(printf '%s' "$PF248_OUT" | grep -Eq 'devflow-bash: running under bash [^ (]' && echo yes || echo no)"
assert_eq "#248 preflight: byte-identical pass line still last with the breadcrumb added (AC4)" \
  "devflow preflight: all dependencies present." "$(printf '%s\n' "$PF248_OUT" | tail -1)"
assert_eq "#248 preflight: no DEVFLOW_BASH= in breadcrumb when unset (AC4 no-op)" "no" \
  "$(printf '%s' "$PF248_OUT" | grep -q 'DEVFLOW_BASH=' && echo yes || echo no)"

# ── T2 (AC2 override surfacing): DEVFLOW_BASH set is reflected verbatim in the
#    breadcrumb, and preflight still exits 0. ──
PF248O_OUT="$(DEVFLOW_BASH=/opt/devflow-marker/bash PATH="$T248" bash "$PF248" 2>&1)"; PF248O_RC=$?
assert_eq "#248 preflight: DEVFLOW_BASH set → still exit 0 (AC4)" "0" "$PF248O_RC"
assert_eq "#248 preflight: breadcrumb surfaces the DEVFLOW_BASH value (AC2/T2)" "yes" \
  "$(printf '%s' "$PF248O_OUT" | grep -qF 'DEVFLOW_BASH=/opt/devflow-marker/bash' && echo yes || echo no)"

# ── T2b (AC2/AC4 boundary): a set-but-EMPTY DEVFLOW_BASH is a no-op, exactly like
#    unset — the breadcrumb surfaces no `DEVFLOW_BASH=`. This pins the `[ -n … ]`
#    emptiness guard specifically: a regression swapping it for set-detection
#    (`${DEVFLOW_BASH+set}` / `-v`) would leak an empty `DEVFLOW_BASH=` into the
#    breadcrumb and otherwise ship green. ──
PF248E_OUT="$(DEVFLOW_BASH='' PATH="$T248" bash "$PF248" 2>&1)"; PF248E_RC=$?
assert_eq "#248 preflight: empty DEVFLOW_BASH → still exit 0 (AC4)" "0" "$PF248E_RC"
assert_eq "#248 preflight: empty DEVFLOW_BASH is a no-op — not surfaced (AC2/AC4 boundary)" "no" \
  "$(printf '%s' "$PF248E_OUT" | grep -q 'DEVFLOW_BASH=' && echo yes || echo no)"

# ── T3 (AC3 remedy): under a NON-bash POSIX shell (empty $BASH_VERSION) preflight
#    prints the remedy naming the supported bashes + DEVFLOW_BASH and exits non-zero,
#    BEFORE the bash-only `${BASH_SOURCE[0]}` would abort with a cryptic error.
#    Exercised with a real non-bash sh when one exists (dash/busybox, invoked by
#    absolute path); on a bash-only host the dynamic arm is skipped and recorded,
#    never replaced by a wording-only source assertion. ──
NONBASH=""
if command -v dash >/dev/null 2>&1; then NONBASH="$(command -v dash)"
elif command -v busybox >/dev/null 2>&1; then NONBASH="$(command -v busybox) sh"
fi
if [ -n "$NONBASH" ]; then
  # shellcheck disable=SC2086  # $NONBASH may be the two words "<path>/busybox sh"
  PF248R_OUT="$($NONBASH "$PF248" 2>&1)"; PF248R_RC=$?
  assert_eq "#248 preflight: non-bash shell → exit non-zero (fail closed, AC3)" "yes" \
    "$([ "$PF248R_RC" -ne 0 ] && echo yes || echo no)"
  assert_eq "#248 preflight: non-bash → 'not running under a POSIX bash' remedy (AC3)" "yes" \
    "$(printf '%s' "$PF248R_OUT" | grep -q 'devflow-bash: not running under a POSIX bash' && echo yes || echo no)"
  assert_eq "#248 preflight: remedy names WSL + Git Bash + MSYS2 (AC3)" "yes" \
    "$(printf '%s' "$PF248R_OUT" | grep -q 'WSL bash' && printf '%s' "$PF248R_OUT" | grep -q 'Git Bash' && printf '%s' "$PF248R_OUT" | grep -q 'MSYS2 bash' && echo yes || echo no)"
  assert_eq "#248 preflight: remedy names the DEVFLOW_BASH override (AC3)" "yes" \
    "$(printf '%s' "$PF248R_OUT" | grep -q 'DEVFLOW_BASH' && echo yes || echo no)"
  assert_eq "#248 preflight: remedy fires BEFORE the bash-only \${BASH_SOURCE[0]} (no array-syntax error leaks)" "no" \
    "$(printf '%s' "$PF248R_OUT" | grep -qi 'bad substitution\|BASH_SOURCE' && echo yes || echo no)"
else
  # No non-bash sh on this host: record an explicit skip so the missing dynamic
  # coverage is visible rather than substituting a wording-only fallback.
  skip "#248 preflight: non-bash remedy dynamic arm" host-capability \
    "no dash/busybox on host"
fi

rm -rf "$T248"

# ────────────────────────────────────────────────────────────────────────────
echo "#266 cloud /devflow:implement stall backstop"
# ────────────────────────────────────────────────────────────────────────────
# The decision core is extracted into scripts/stall-backstop-decide.sh precisely
# so it is drivable here with stubbed inputs (the YAML step is a thin caller).
# Every branch below is RED against the pre-change state: pre-change the helper
# does not exist, so `bash <missing>` prints nothing to stdout / exits 127 and
# each assert_eq fails. These are behavioral pins over the REAL script, so a
# broken branch in the helper goes RED — no vacuity.
DECIDE_SH266="$REPO_ROOT/scripts/stall-backstop-decide.sh"
decide266() { bash "$DECIDE_SH266" "$@" 2>/dev/null; }
assert_eq "#266 decide: disabled (enabled=false) -> skip" "skip" "$(decide266 false interim 0 2)"
assert_eq "#266 decide: terminal (legacy alias) -> noop" "noop" "$(decide266 true terminal 0 2)"
# #1025 — the widened terminal vocabulary. `workpad.py status` now names each
# terminal glyph (complete/blocked/failed/cancelled) instead of collapsing them
# to `terminal`, so a blocked run is distinguishable from a completed one. Every
# arm of the widened table is driven behaviorally here (AC5). RED pre-change: the
# helper had no complete/blocked/failed/cancelled arms, so each fell through the
# `unreadable|*` wildcard to fail-unreadable.
assert_eq "#1025 decide: complete -> noop (🎉 stays green)" "noop" "$(decide266 true complete 0 2)"
assert_eq "#1025 decide: blocked -> fail-blocked (non-success)" "fail-blocked" "$(decide266 true blocked 0 2)"
assert_eq "#1025 decide: failed -> fail-blocked (non-success)" "fail-blocked" "$(decide266 true failed 0 2)"
assert_eq "#1025 decide: cancelled (stale read, non-cancelled job) -> noop (never a failure, AC4)" "noop" "$(decide266 true cancelled 0 2)"
# #1025 AC6 — negative control: the interim arms are UNCHANGED. An interim status
# under the cap still selects resume, exactly as before the vocabulary widened.
assert_eq "#1025 decide: interim under cap -> resume (interim arm unchanged, AC6)" "resume" "$(decide266 true interim 0 2)"
# #1025 — the cap-exhausted interim arm is also unchanged (fail-exhausted != the
# new fail-blocked): a stall at the cap is still a distinct, resume-bearing class.
assert_eq "#1025 decide: interim at cap -> fail-exhausted (interim arm unchanged)" "fail-exhausted" "$(decide266 true interim 2 2)"
# #1025 — the widened terminal classes also behave under a cancelled job: every
# decided terminal end (and the legacy alias) folds to noop; only interim flips.
assert_eq "#1025 decide: complete + cancelled -> noop" "noop" "$(decide266 true complete 0 2 cancelled)"
assert_eq "#1025 decide: blocked + cancelled -> noop (a cancel is not a failure, AC4)" "noop" "$(decide266 true blocked 0 2 cancelled)"
assert_eq "#1025 decide: failed + cancelled -> noop" "noop" "$(decide266 true failed 0 2 cancelled)"
assert_eq "#1025 decide: cancelled + cancelled -> noop" "noop" "$(decide266 true cancelled 0 2 cancelled)"
assert_eq "#266 decide: interim under cap -> resume" "resume" "$(decide266 true interim 0 2)"
assert_eq "#266 decide: interim at cap -> fail-exhausted" "fail-exhausted" "$(decide266 true interim 2 2)"
assert_eq "#266 decide: interim cap=0 -> fail-exhausted (no auto-resume)" "fail-exhausted" "$(decide266 true interim 0 0)"
assert_eq "#266 decide: interim mid-cap -> resume" "resume" "$(decide266 true interim 1 2)"
assert_eq "#266 decide: unreadable -> fail-unreadable (fail closed)" "fail-unreadable" "$(decide266 true unreadable 0 2)"
assert_eq "#266 decide: unknown class -> fail-unreadable (fail closed)" "fail-unreadable" "$(decide266 true bogus 0 2)"
# #287 — a gh-api/transport/auth failure is a DISTINCT class: fail-auth, not
# fail-unreadable, so the workflow emits an auth-specific breadcrumb and never
# burns a resume attempt on a workpad it could not read. The arm must sit BEFORE
# the wildcard, so this also proves it is not swallowed into fail-unreadable.
assert_eq "#287 decide: auth-failure -> fail-auth (distinct from fail-unreadable)" "fail-auth" "$(decide266 true auth-failure 0 2)"
assert_eq "#266 decide: unrecognized enabled resolves to enabled (interim -> resume)" "resume" "$(decide266 yes interim 0 2)"
assert_eq "#266 decide: negative cap falls back to default 2 (interim,attempts=1 -> resume)" "resume" "$(decide266 true interim 1 -1)"
assert_eq "#266 decide: non-integer attempts -> 0 (interim,cap=2 -> resume)" "resume" "$(decide266 true interim notanum 2)"
# #498 — cancelled-run exclusion (issue #498). Only the exact 5th arg `cancelled`
# selects the cancel path; every other value leaves the existing table byte-
# identical (fail toward resume, so an un-upgraded caller never suppresses a
# resume). The cancelled-path rows below are complete by construction — the
# `*` arm folds the unreadable/auth-failure/unknown classes, closing the class
# space (adding a class needs no new row here; it inherits the fold). RED
# pre-change: today's helper ignores a 5th arg, so `interim + cancelled`
# printed `resume` (the defect).
assert_eq "#498 decide: ENABLED=false + cancelled -> skip (master switch wins)" "skip" "$(decide266 false interim 0 2 cancelled)"
assert_eq "#498 decide: interim + cancelled -> flip-cancelled" "flip-cancelled" "$(decide266 true interim 0 2 cancelled)"
assert_eq "#498 decide: terminal + cancelled -> noop" "noop" "$(decide266 true terminal 0 2 cancelled)"
assert_eq "#498 decide: unreadable + cancelled -> skip-cancelled" "skip-cancelled" "$(decide266 true unreadable 0 2 cancelled)"
assert_eq "#498 decide: auth-failure + cancelled -> skip-cancelled" "skip-cancelled" "$(decide266 true auth-failure 0 2 cancelled)"
assert_eq "#498 decide: unknown class + cancelled -> skip-cancelled (unreadable fold)" "skip-cancelled" "$(decide266 true bogus 0 2 cancelled)"
# #498 T2 — input shapes: every value other than the exact string `cancelled`
# falls through to the existing table byte-identical. The compare is case-
# sensitive (`Cancelled` -> resume), and an exhausted cap still flips on a
# cancel (the cancel path is taken before the attempts/max comparison, so no
# resume attempt is consumed by a cancel).
assert_eq "#498 decide: JOB_STATUS=success -> existing resume arm" "resume" "$(decide266 true interim 0 2 success)"
assert_eq "#498 decide: JOB_STATUS=failure -> existing resume arm" "resume" "$(decide266 true interim 0 2 failure)"
assert_eq "#498 decide: JOB_STATUS empty -> existing resume arm" "resume" "$(decide266 true interim 0 2 '')"
assert_eq "#498 decide: 5th arg absent (4-arg caller) -> existing resume arm" "resume" "$(decide266 true interim 0 2)"
assert_eq "#498 decide: JOB_STATUS='Cancelled' (case-sensitive) -> existing resume arm" "resume" "$(decide266 true interim 0 2 Cancelled)"
assert_eq "#498 decide: interim at cap + cancelled -> flip-cancelled (no attempt consumed)" "flip-cancelled" "$(decide266 true interim 2 2 cancelled)"
decide266 true interim 0 2 >/dev/null 2>&1
assert_eq "#266 decide: a valid decision exits 0" "0" "$?"

# post-issue-comment.sh best-effort contract (mirrors ensure-label.sh): a bad
# input never aborts — exit 0 + a breadcrumb. DEVFLOW_GH is stubbed so sourcing
# resolve-gh.sh never probes a real gh. RED pre-change (helper absent → rc 127).
POST_SH266="$REPO_ROOT/scripts/post-issue-comment.sh"
POST_RC266_NAN="$(DEVFLOW_GH=true bash "$POST_SH266" notanumber /dev/null >/dev/null 2>&1; echo $?)"
assert_eq "#266 post-issue-comment: non-numeric issue -> exit 0 (best-effort)" "0" "$POST_RC266_NAN"
POST_RC266_NF="$(DEVFLOW_GH=true bash "$POST_SH266" 5 /no/such/body/file >/dev/null 2>&1; echo $?)"
assert_eq "#266 post-issue-comment: missing body file -> exit 0 (best-effort)" "0" "$POST_RC266_NF"
POST_ERR266="$(DEVFLOW_GH=true bash "$POST_SH266" 5 /no/such/body/file 2>&1 >/dev/null)"
assert_eq "#266 post-issue-comment: missing body file leaves a specific breadcrumb" "yes" \
  "$(printf '%s' "$POST_ERR266" | grep -q 'body file not found' && echo yes || echo no)"

# Issue #1675: the always-zero contract begins when the helper starts, not after
# positional expansion. Both missing-argument arms must identify a caller slip and
# must return before the API helper is invoked.
POST_T1675="$(mktemp -d)" || { echo "FAIL  #1675: mktemp -d failed"; exit 1; }
POST_CALLS1675="$POST_T1675/calls"
POST_BODY1675="$POST_T1675/body"
printf '%s\n' 'valid body' > "$POST_BODY1675"
cat > "$POST_T1675/gh" <<'SH'
#!/usr/bin/env bash
printf 'called\n' >> "$POST_CALLS1675"
exit 0
SH
chmod +x "$POST_T1675/gh"
# Positive control: prove the recording stub sees a real helper call before the negative
# arms use that same stub to establish that caller slips make no request.
POST_RC1675_VALID="$(POST_CALLS1675="$POST_CALLS1675" DEVFLOW_GH="$POST_T1675/gh" \
  bash "$POST_SH266" 5 "$POST_BODY1675" >/dev/null 2>&1; echo $?)"
assert_eq "#1675 post-issue-comment: a valid call reaches the API stub once" \
  "0:1" "$POST_RC1675_VALID:$([ -f "$POST_CALLS1675" ] && wc -l < "$POST_CALLS1675" | tr -d ' ' || echo 0)"
: > "$POST_CALLS1675"
POST_ERR1675_NUMBER="$(POST_CALLS1675="$POST_CALLS1675" DEVFLOW_GH="$POST_T1675/gh" \
  bash "$POST_SH266" 2>&1 >/dev/null)"; POST_RC1675_NUMBER=$?
assert_eq "#1675 post-issue-comment: missing issue number exits 0 (best-effort)" \
  "0" "$POST_RC1675_NUMBER"
assert_eq "#1675 post-issue-comment: missing issue number identifies a caller argument slip" \
  "yes" "$(printf '%s' "$POST_ERR1675_NUMBER" | grep -qF 'caller argument slip' && echo yes || echo no)"
POST_ERR1675_BODY="$(POST_CALLS1675="$POST_CALLS1675" DEVFLOW_GH="$POST_T1675/gh" \
  bash "$POST_SH266" 5 2>&1 >/dev/null)"; POST_RC1675_BODY=$?
assert_eq "#1675 post-issue-comment: missing body-file argument exits 0 (best-effort)" \
  "0" "$POST_RC1675_BODY"
assert_eq "#1675 post-issue-comment: missing body-file identifies a caller argument slip" \
  "yes" "$(printf '%s' "$POST_ERR1675_BODY" | grep -qF 'caller argument slip' && echo yes || echo no)"
assert_eq "#1675 post-issue-comment: missing arguments make zero API requests" \
  "0" "$([ -f "$POST_CALLS1675" ] && wc -l < "$POST_CALLS1675" | tr -d ' ' || echo 0)"
rm -rf "$POST_T1675"

# Config keys are a coupled peer set (2.3.0a): example template ↔ schema must
# both carry stall_backstop.{enabled,max_resume_attempts}. Parse structurally so
# a key present in one but not the other goes RED.
CFG266="$(python3 - "$REPO_ROOT" <<'PY' 2>/dev/null || true
import json, sys, pathlib
root = pathlib.Path(sys.argv[1])
ex = json.loads((root / ".prflow/config.example.json").read_text())
sc = json.loads((root / ".prflow/config.schema.json").read_text())
eb = ex.get("prflow_implement", {}).get("stall_backstop", {})
sp = sc["properties"]["prflow_implement"]["properties"].get("stall_backstop", {})
props = sp.get("properties", {})
ok = (
    eb.get("enabled") is True
    and eb.get("max_resume_attempts") == 2
    and sp.get("type") == "object"
    and sp.get("additionalProperties") is False
    and props.get("enabled", {}).get("type") == "boolean"
    and props.get("enabled", {}).get("default") is True
    and props.get("max_resume_attempts", {}).get("type") == "integer"
    and props.get("max_resume_attempts", {}).get("minimum") == 0
    and props.get("max_resume_attempts", {}).get("default") == 2
)
print("yes" if ok else "no")
PY
)"
assert_eq "#266 config example+schema carry coupled stall_backstop keys (types/defaults/additionalProperties)" "yes" "$CFG266"

# ── #268 workflow wiring: the thin caller step in devflow-implement.yml that
# composes the #266 primitives (deferred from #266; needed a workflows:write
# token). Content pins over the literal YAML — RED pre-change (the step did not
# exist, so every literal below was absent). assert_pin_unique doubles as the
# removal-proof: PASS with the pinned text present exactly once, FAIL without it.
WF268="$REPO_ROOT/.github/workflows/devflow-implement.yml"
assert_pin_unique "#268 wiring: 'Stall backstop' step present in devflow-implement.yml" \
  "name: Stall backstop" "$WF268"
assert_eq "#268 wiring: stall-backstop step is gated if: always() (runs on action failure too)" "yes" \
  "$(grep -A1 'name: Stall backstop' "$WF268" | grep -q 'if: \${{ always() }}' && echo yes || echo no)"
assert_pin_unique "#268 wiring: step reads stall_backstop.enabled via vendored config-get.sh" \
  ".prflow_implement.stall_backstop.enabled" "$WF268"
assert_pin_unique "#268 wiring: step reads stall_backstop.max_resume_attempts via vendored config-get.sh" \
  ".prflow_implement.stall_backstop.max_resume_attempts" "$WF268"
assert_pin_unique "#268 wiring: step calls the vendored decision helper" \
  "stall-backstop-decide.sh" "$WF268"
assert_pin_unique "#268 wiring: step reads the workpad Status via workpad.py status" \
  'workpad.py" status' "$WF268"
assert_pin_unique "#268 wiring: step posts comments via the vendored best-effort REST helper (single funnel)" \
  "post-issue-comment.sh" "$WF268"
# Coupled literal: the resume-audit comment marker. The workflow both WRITES it
# (into each auto-resume comment) and COUNTS it (gh api --paginate + grep) to
# derive ATTEMPTS, via one shell variable — so the literal must appear exactly
# once in the YAML. Renaming it there without updating this pin goes RED.
assert_pin_unique "#268 wiring: resume-audit marker literal (written + counted via one variable)" \
  "prflow:stall-backstop-audit" "$WF268"
# The re-dispatch body is the ONLY comment carrying the trigger phrase, and it
# targets the run's own issue number.
assert_pin_unique "#268 wiring: re-dispatch body carries the canonical implement trigger phrase" \
  '/prflow:implement %s' "$WF268"
# Fail-loud exit mapping: resume keeps the job green, everything else exits
# non-zero. Drift to a bare `exit 0` (or dropping the FAIL flip) would convert
# "job goes honestly red" back into a masked stall — the marquee contract.
assert_pin_unique "#268 wiring: FAIL flips to 0 only on the resume decision" \
  '[ "$DECISION" = "resume" ] && FAIL=0' "$WF268"
assert_pin_unique "#268 wiring: step exits via the FAIL mapping" \
  'exit "$FAIL"' "$WF268"
# Coupled breadcrumb literal: the workflow's resume-arm success check greps the
# EXACT success breadcrumb post-issue-comment.sh emits. Pin BOTH sides so a
# reworded producer breadcrumb (which would turn every real resume into a
# spurious red) goes RED here instead of shipping.
assert_pin_unique "#268 wiring: resume-landed check greps the funnel success breadcrumb (consumer side)" \
  'devflow: posted comment on #' "$WF268"
assert_pin_unique "#268 wiring: post-issue-comment.sh emits that exact success breadcrumb (producer side)" \
  'devflow: posted comment on #' "$REPO_ROOT/scripts/post-issue-comment.sh"
# App-token-inert-resume fail-loud + missing-vendored-dir disambiguation wiring.
# Issue #287: the backstop now consumes a FRESHLY-minted token (steps.backstop-token),
# not the stale claude-job-scoped app-token, so both GH_TOKEN and APP_TOKEN_PRESENT
# reference the fresh step's output.
assert_pin_unique "#287 wiring: APP_TOKEN_PRESENT wired from the fresh backstop-token step output" \
  "APP_TOKEN_PRESENT: \${{ steps.backstop-token.outputs.token != '' }}" "$WF268"
assert_pin_unique "#287 wiring: stall-backstop GH_TOKEN consumes the fresh backstop-token (JIT re-mint)" \
  'GH_TOKEN: ${{ steps.backstop-token.outputs.token || secrets.GITHUB_TOKEN }}' "$WF268"
assert_pin_unique "#287 wiring: fresh backstop-token mint step present, gated on DEVFLOW_APP_ID" \
  "id: backstop-token" "$WF268"
# The backstop mint's `if:` MUST carry `always()` — that is the one clause that
# distinguishes it from the writer mint (which uses a bare `if:`), and it is
# load-bearing: without it the mint is skipped on a FAILED claude job (default
# success() gating), so APP_TOKEN_PRESENT resolves false and auto-resume fails
# loud even with the App configured — the exact regression #287 exists to fix
# and the exact edit the step's own comment warns against. The APP_SITES table
# only substring-matches `DEVFLOW_APP_ID != ''` (deliberately lenient about the
# rest of the if:), so `always()` needs its own removal-proof pin here: a
# "harmonization" that drops it ships GREEN otherwise. RED if `always()` is removed.
assert_eq "#287 wiring: backstop-token mint if: carries the always() guard (mints even after a failed claude job)" "1" \
  "$(grep -A2 'name: Mint stall-backstop token' "$WF268" | grep -cF "if: \${{ always() && vars.DEVFLOW_APP_ID != '' }}")"
assert_pin_unique "#268 wiring: CLAUDE_OUTCOME wired from the claude step outcome" \
  'CLAUDE_OUTCOME: ${{ steps.claude.outcome }}' "$WF268"
# #498 — the cancel signal's PRODUCTION delivery path: the step's `env:` must
# wire JOB_STATUS from job.status (the documented job-context string). The
# #268 behavioral harness injects JOB_STATUS directly (it extracts only the
# `run:` body, not the `env:` block), so WITHOUT this pin a future edit that
# drops the env: line leaves the suite GREEN while production $JOB_STATUS
# resolves empty — the decide helper gets an empty 5th arg, the cancel path is
# never taken, and a cancelled run auto-resumes (the exact defect #498 fixes).
assert_pin_unique "#498 wiring: JOB_STATUS wired from job.status (the cancel signal's production delivery)" \
  'JOB_STATUS: ${{ job.status }}' "$WF268"
# Actions runs run: blocks under bash -e; the step's leading `set +e` is what
# makes every fallback branch reachable. Assert it inside the step REGION (other
# steps carry their own set +e, so a whole-file pin cannot be unique) AND run
# the extracted harness under -e below, so dropping it goes RED behaviorally.
assert_eq "#268 wiring: step neutralizes Actions' errexit (set +e present in the step region)" "yes" \
  "$(awk '/name: Stall backstop/{f=1} f && /set \+e/{print "hit"; exit} f && /exit "\$FAIL"/{exit}' "$WF268" | grep -q hit && echo yes || echo no)"
# Negative producer-side pin: the funnel's FAILURE breadcrumb must never
# contain the success phrase the consumer greps (else a dropped POST could
# read as landed).
assert_eq "#268 wiring: funnel failure breadcrumb does not contain the success phrase" "0" \
  "$(grep -F 'could not post comment' "$REPO_ROOT/scripts/post-issue-comment.sh" | grep -cF 'posted comment on' || true)"
# Negative pin: the stall-backstop STEP body must never embed the workpad
# marker — the gate's self-trigger guard declines any comment containing it,
# so a workpad-marker leak into the resume body would silently kill the
# auto-resume (green job, no re-dispatch). Scope the check to the step region
# (the workpad marker legitimately appears elsewhere in the workflow).
SB268_STEP="$(awk '/name: Stall backstop/{f=1} f{print} f && /exit "\$FAIL"/{exit}' "$WF268")"
assert_eq "#268 wiring: stall-backstop step region extracted (non-empty)" "yes" \
  "$([ -n "$SB268_STEP" ] && echo yes || echo no)"
assert_eq "#268 wiring: resume body cannot trip the self-trigger guard (no workpad marker in the step)" "0" \
  "$(printf '%s' "$SB268_STEP" | grep -cF 'flow:workpad' || true)"

# Behavioral: extract the Stall backstop step's run: block (same idiom as the
# provision 'tools' step extraction above) and drive its glue logic with
# stubbed helpers — the content pins above prove presence, these prove the
# step's own wiring: the disabled early-exit really skips the status read, the
# exit code follows the decision, and a dropped resume POST fails loud.
if command -v python3 >/dev/null 2>&1 && python3 -c 'import yaml' >/dev/null 2>&1; then
  SB268_RUN=$(mktemp)
  python3 - "$WF268" >"$SB268_RUN" <<'PY'
import shlex, sys, yaml
doc = yaml.safe_load(open(sys.argv[1]))
prelude = "".join("export %s=%s\n" % (k, shlex.quote(str(v)))
                  for k, v in (doc.get("env") or {}).items())
for job in doc["jobs"].values():
    for s in job.get("steps", []):
        if s.get("name") == "Stall backstop" and "run" in s:
            sys.stdout.write("#!/usr/bin/env bash\n" + prelude + s["run"])
            raise SystemExit
raise SystemExit("Stall backstop step not found")
PY
  SB268_DIR=$(mktemp -d)
  mkdir -p "$SB268_DIR/repo/.prflow/vendor/prflow/scripts" "$SB268_DIR/bin"
  SB268_V="$SB268_DIR/repo/.prflow/vendor/prflow/scripts"
  cp "$REPO_ROOT/scripts/stall-backstop-decide.sh" "$SB268_V/"   # real decision core
  cat > "$SB268_V/config-get.sh" <<'STUB'
