FILED_STATE=""
FILED_NUMBERS=""
PR_NUMBER=99
MANIFEST_STATE=""
'"$I480_SENTINEL" 2>/dev/null | grep -qF 'phase 4.0.5 filing fence ran' && echo yes || echo no)"
