assert_eq "#1405 AC1 emits NO STALE R3 row" "no" "$(spl_has "$SPR" STALE R3)"
assert_eq "#1405 AC1 emits a non-gating UNRESOLVABLE R3 recognition row" "yes" "$(spl_has "$SPR" UNRESOLVABLE R3)"

