assert_eq "#439 § lookbehind (behavioral): a §-prefixed numeral produces no recognition row" "no" "$(spl_has "$SPR" UNRESOLVABLE R3)"

# GAP-5 (double-emission invariant): a gating line (existing _COUNT_RE surface) must NOT also
