  local r; r="$(spl_repo "$f")"
  assert_eq "#439 noun alternand [$1] fires (recognition row present)" "yes" "$(spl_has "$r" UNRESOLVABLE R3)"
}
sp439_noun "members" 'The four members below drift.'
