# ── describe-plugin-compose.sh (AC: arm classification in a suite-drivable helper) ──
assert_eq "#505: describe-plugin-compose.sh exists" "yes" "$([ -f "$DPC" ] && echo yes || echo no)"
assert_eq "#505: describe-plugin-compose.sh SPDX header" "yes" "$(grep -q 'SPDX-License-Identifier: MIT' "$DPC" && echo yes || echo no)"
assert_eq "#505: describe-plugin-compose.sh uses set -u (not set -e; always exits 0)" "yes" \
  "$(grep -qE '^set -u$' "$DPC" && ! grep -q 'set -e' "$DPC" && echo yes || echo no)"
_505_DPC_E="$(mktemp)"
_505_dpc() { printf '%s' "$2" > "$_505_DPC_E"; _OUT="$(bash "$DPC" "$1" "$_505_DPC_E" "$3" 2>/dev/null)"; _RC=$?; }
# silent-absent baseline: ok, no entries, no defect → no output
_505_dpc ok "" ""
assert_eq "#505 dpc: silent-absent arm emits nothing" "" "$_OUT"
# splice-plus-notice: ok + entries → ::notice:: listing every entry
_505_dpc ok $'a@x\nb@y' ""
assert_eq "#505 dpc: splice arm emits ::notice:: listing the entries" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::notice::' && printf '%s' "$_OUT" | grep -q 'a@x' && printf '%s' "$_OUT" | grep -q 'b@y' && echo yes || echo no)"
# degraded-shape: ok + defect → ::warning:: naming the defect
_505_dpc ok "" "enabledPlugins is not an object"
assert_eq "#505 dpc: degraded arm emits ::warning:: naming the defect" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::warning::' && printf '%s' "$_OUT" | grep -qi 'degraded' && printf '%s' "$_OUT" | grep -q 'enabledPlugins is not an object' && echo yes || echo no)"
# trusted-read-failed: failed → ::warning:: (arm order: failed outranks degraded + splice)
_505_dpc failed $'a@x' "some defect"
assert_eq "#505 dpc: trusted-read-failed arm emits ::warning:: (outranks splice)" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::warning::' && printf '%s' "$_OUT" | grep -qi 'could not read' && echo yes || echo no)"
assert_eq "#505 dpc: failed arm does NOT emit a notice" "no" "$(printf '%s' "$_OUT" | grep -q '::notice::' && echo yes || echo no)"
# mixed: ok+defect+entries → BOTH a ::warning:: (degraded entry) AND a ::notice:: (the
# valid extras were composed) — a degraded entry never suppresses the splice audit line
# (PR #513: every spliced entry logged, never silent). Regression pin for the REJECT
# driver: before #513 the degraded arm shadowed the splice notice, so a valid plugin
# spliced into the credentialed runner shipped unaudited.
_505_dpc ok $'a@x' "defect"
assert_eq "#505 dpc(#513): mixed ok+defect+entries emits the degraded ::warning::" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::warning::' && printf '%s' "$_OUT" | grep -qi 'degraded entries' && echo yes || echo no)"
assert_eq "#505 dpc(#513): mixed ok+defect+entries ALSO emits the splice ::notice:: listing the entry (never suppressed)" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::notice::' && printf '%s' "$_OUT" | grep -q 'a@x' && echo yes || echo no)"
# arm 3 (defect only, no entries) still reads "proceeding with the baked plugin baseline"
_505_dpc ok "" "defect"
assert_eq "#505 dpc(#513): defect-only (no entries) still emits the baseline-only ::warning::, no ::notice::" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::warning::' && printf '%s' "$_OUT" | grep -q 'baked plugin baseline' && ! printf '%s' "$_OUT" | grep -q '::notice::' && echo yes || echo no)"
# arm order: failed outranks degraded (failed+defect → failed warning, not degraded)
_505_dpc failed "" "defect"
assert_eq "#505 dpc: arm order — failed outranks degraded (failed+defect → 'could not read')" "yes" \
  "$(printf '%s' "$_OUT" | grep -qi 'could not read' && echo yes || echo no)"
# unknown read-outcome (the `*` case arm): a caller bug (only "failed"/"ok" are valid)
# must surface a ::warning:: naming the unknown outcome, NOT silently emit nothing — a
# silent no-op here would hide the caller bug (the helper always exits 0). This is the
# one arm the "run.sh drives every arm" convention left undriven; a sed mutation
# collapsing the `*` arm to `:` (silent) would ship green without this pin.
_505_dpc badoutcome $'a@x' "defect"
assert_eq "#505 dpc: unknown read-outcome arm emits a ::warning:: naming the unknown outcome" "yes" \
  "$(printf '%s' "$_OUT" | grep -q '::warning::' && printf '%s' "$_OUT" | grep -qi 'unknown read-outcome' && printf '%s' "$_OUT" | grep -q 'badoutcome' && echo yes || echo no)"
assert_eq "#505 dpc: unknown read-outcome arm emits NO ::notice:: (does not compose on a caller bug)" "no" \
  "$(printf '%s' "$_OUT" | grep -q '::notice::' && echo yes || echo no)"
rm -f "$_505_DPC_E"

# ── #505 workflow-wiring pins (AC4 + review-tier trusted-source ACs) ────────────
_505_BP="printf '%s\n' code-review@claude-plugins-official claude-md-management@claude-plugins-official $SUITE_PLUGIN_SPEC"
_505_BM="printf '%s\n' https://github.com/anthropics/claude-plugins-official.git ./"
# (a) baked baseline literals byte-identical across the three call sites (AC4 sync invariant)
for _f in devflow-implement devflow devflow-runner; do
  assert_eq "#505 AC4: $_f.yml carries the baked plugins baseline literal" "1" "$(grep -cF "$_505_BP" "$_505_WF/$_f.yml")"
  assert_eq "#505 AC4: $_f.yml carries the baked marketplaces baseline literal" "1" "$(grep -cF "$_505_BM" "$_505_WF/$_f.yml")"
  assert_eq "#505 AC4: $_f.yml has a Compose plugin inputs step" "1" "$(grep -c 'name: Compose plugin inputs' "$_505_WF/$_f.yml")"
  # devflow-implement.yml consumes plugin_marketplaces from the issue-#1049
  # vendor_marketplace step (which post-processes steps.plugins' composed list);
  # the other two tiers still consume steps.plugins directly. The action input must
  # name exactly the right producing step per tier.
  if [ "$_f" = devflow-implement ]; then
    _505_EXPMK='plugin_marketplaces: ${{ steps.vendor_marketplace.outputs.plugin_marketplaces }}'
  else
    _505_EXPMK='plugin_marketplaces: ${{ steps.plugins.outputs.plugin_marketplaces }}'
  fi
  assert_eq "#505 AC4: $_f.yml plugin_marketplaces action input consumes the right composed step" "1" \
    "$(grep -cF "$_505_EXPMK" "$_505_WF/$_f.yml")"
  assert_eq "#505 AC4: $_f.yml plugins consumes the step output" "1" \
    "$(grep -cF 'plugins: ${{ steps.plugins.outputs.plugins }}' "$_505_WF/$_f.yml")"
  assert_eq "#505 AC: $_f.yml routes the annotation through describe-plugin-compose.sh" "yes" \
    "$(grep -qF 'bash "$COMPOSE"' "$_505_WF/$_f.yml" && echo yes || echo no)"
done
# (a2) PR #513 I2 coupled-site cross-check: the YAML baked literals and the helper's
# Python frozensets (BAKED_PLUGINS / BASE_MARKETPLACES) must agree — the AC4 pins above
# only lock the three YAML literals to EACH OTHER (via $_505_BP/$_505_BM, themselves
# grep-pinned byte-identical to all three workflows), never to the Python constants. A
# 4th baked plugin added to the workflows but omitted from the frozenset would make the
# helper EMIT a settings-declared duplicate of that baseline entry (or breadcrumb it),
# instead of silently skipping it. So: derive the baked entries from the pinned literal
# and drive each through the REAL helper — a baked entry enabled `true` must produce
# empty stdout AND empty stderr (the frozenset silent skip), which fails RED the moment
# the YAML literal and the frozenset drift.
# Strip the `printf '%s\n' ` prefix by cutting through the last apostrophe-space
# (bash builtins; no entry may contain an apostrophe — the count control below
# fails RED if the derivation ever misparses).
_505_BP_ENTRIES="${_505_BP##*"' "}"
_505_BP_COUNT=0
for _e in $_505_BP_ENTRIES; do
  _505_BP_COUNT=$((_505_BP_COUNT + 1))
  _505_run plugins "{\"enabledPlugins\":{\"$_e\":true}}"
  assert_eq "#513 I2 coupled-site: baked plugin $_e is frozenset-covered (silent skip, no emit, no breadcrumb)" \
    "" "$_OUT$_ERR"
  # Each baked entry's @marketplace suffix must be BASE_MARKETPLACES-covered too: a
  # github-kind extraKnownMarketplaces entry REUSING that name must be silently
  # skipped by marketplaces mode (already registered by the baked baseline).
  _505_run marketplaces "{\"extraKnownMarketplaces\":{\"${_e#*@}\":{\"source\":{\"source\":\"github\",\"repo\":\"o/r\"}}}}"
  assert_eq "#513 I2 coupled-site: baked marketplace name ${_e#*@} is BASE_MARKETPLACES-covered (silent skip)" \
    "" "$_OUT$_ERR"
done
# Positive controls: the derivation actually produced the three baked entries (an
# extraction bug must not vacuously pass the loop), and a NON-baked entry of the same
# shape IS emitted / IS mapped — so the silent-skip assertions above are attributable
# to the frozensets, not to a helper that stopped emitting anything at all.
assert_eq "#513 I2 coupled-site: derived baked-entry list has the expected 3 entries (positive control)" "3" "$_505_BP_COUNT"
_505_run plugins '{"enabledPlugins":{"notbaked@claude-plugins-official":true}}'
assert_eq "#513 I2 coupled-site: non-baked entry IS emitted (positive control)" "notbaked@claude-plugins-official" "$_OUT"
_505_run marketplaces '{"extraKnownMarketplaces":{"not-a-baked-name":{"source":{"source":"github","repo":"o/r"}}}}'
assert_eq "#513 I2 coupled-site: non-baked marketplace name IS mapped (positive control)" "https://github.com/o/r.git" "$_OUT"
# (c) the inline skew arm (helper-file-absent) names prflow_version on the WRITE tiers
assert_eq "#505 AC skew: devflow-implement.yml skew arm names prflow_version" "yes" \
  "$(grep -qF 'Bump prflow_version' "$_505_WF/devflow-implement.yml" && echo yes || echo no)"
assert_eq "#505 AC skew: devflow.yml skew arm names prflow_version" "yes" \
  "$(grep -qF 'Bump prflow_version' "$_505_WF/devflow.yml" && echo yes || echo no)"
# The write-tier inline annotation fallback (HELPER present, COMPOSE absent) must
# surface a SILENT SPLICE too, not only a degraded file: valid extras were composed
# unconditionally, so a partial-vendor skew that drops describe-plugin-compose.sh must
# still emit the audit ::notice:: (docs/internal/cloud-setup.md: every spliced entry logged,
# never silent). Without this arm the extras splice into the credentialed runner with
# no audit line. Grep-pin the splice-notice fallback on both write tiers.
for _f in devflow-implement devflow; do
  assert_eq "#505 AC skew: $_f.yml inline fallback emits a splice ::notice:: for valid extras (never silent)" "yes" \
    "$(grep -qF 'Composed plugin/marketplace entries beyond the baked baseline (describe-plugin-compose.sh unavailable):' "$_505_WF/$_f.yml" && echo yes || echo no)"
  # #513: the inline fallback must emit the splice ::notice:: EVEN WHEN a degraded-entry
  # ::warning:: also fires (DEFECT and a splice coexist) — a degraded entry must not
  # suppress the audit line, mirroring describe-plugin-compose.sh's #513 fix. Pin the
  # coexist arm's both-emit ::warning:: literal so an `elif` regression (which would drop
  # the notice on the mixed case) turns RED.
  assert_eq "#513 AC skew: $_f.yml inline fallback carries the coexisting degraded+splice ::warning:: (both emitted)" "yes" \
    "$(grep -qF 'has degraded entries ($DEFECT); those are skipped, the valid extras below are composed.' "$_505_WF/$_f.yml" && echo yes || echo no)"
done
# (b) review-tier trusted-source pins
_RYML="$_505_WF/devflow-runner.yml"
assert_eq "#505 AC review: exactly one Compose plugin inputs step in devflow-runner.yml" "1" \
  "$(grep -c 'Compose plugin inputs (baseline + trusted-base-ref' "$_RYML")"
assert_eq "#505 AC review: helper invoked against the materialized path (plugins mode)" "1" \
  "$(grep -cF 'bash "$HELPER" plugins "$COMPOSE_SETTINGS"' "$_RYML")"
assert_eq "#505 AC review: helper invoked against the materialized path (marketplaces mode)" "1" \
  "$(grep -cF 'bash "$HELPER" marketplaces "$COMPOSE_SETTINGS"' "$_RYML")"
assert_eq "#505 AC review: baseprovision materializes FETCH_HEAD:.claude/settings.json" "yes" \
  "$(grep -qF 'FETCH_HEAD:.claude/settings.json' "$_RYML" && echo yes || echo no)"
# NEGATIVE: no helper invocation consumes a workspace-relative .claude/settings.json path
# (the invocations use $COMPOSE_SETTINGS, a $RUNNER_TEMP materialized path) — a retargeted
# read or a later workspace-fallback read would put a literal settings path on an
# invocation line and turn this RED.
assert_eq "#505 AC review: NO helper invocation consumes a workspace .claude/settings.json (negative)" "0" \
  "$(grep -cE 'bash "\$HELPER".*\.claude/settings\.json' "$_RYML")"
assert_eq "#505 AC review: fail-closed arm names the trusted-source rule" "yes" \
  "$(grep -qF 'trusted-source rule' "$_RYML" && echo yes || echo no)"
# The renderer-failure fallback (PR #513 "never silent"): the annotation renderer is
# invoked with its status CAPTURED (`if ! bash "$COMPOSE" …`), NOT `|| true`-swallowed, so
# a non-zero renderer (corrupt/partial COMPOSE copy) still leaves an audit ::warning:: after
# the extras were already spliced. Pin the fallback literal on all three tiers, and pin that
# the old swallow form is gone (a reintroduced `|| true` on the COMPOSE call turns this RED).
for _f in devflow-implement devflow devflow-runner; do
  assert_eq "#513 AC: $_f.yml captures the renderer status and emits a fallback ::warning:: (not '|| true')" "yes" \
    "$(grep -qF 'the audit annotation could not be rendered' "$_505_WF/$_f.yml" && echo yes || echo no)"
  assert_eq "#513 AC: $_f.yml no longer swallows the COMPOSE renderer with '|| true' (negative)" "0" \
    "$(grep -cE 'bash "\$COMPOSE".*\|\| true' "$_505_WF/$_f.yml")"
done
# Review-tier fail-closed arm for a materialized-but-vanished settings file: baseprovision
# classified the read 'ok' yet the file is absent at compose time → route to the
# trusted-read-failed arm (a ::warning::), NEVER collapse onto the silent 'absent' baseline
# ("unknown is not zero"). Pin the arm's defect literal so a regression that drops it (or
# collapses it to silence) turns RED.
assert_eq "#505 AC review: materialized-but-vanished settings file fails closed (not silent baseline)" "yes" \
  "$(grep -qF 'vanished before compose' "$_RYML" && echo yes || echo no)"

# ── PR #513 I3: EXECUTE the compose steps (write tier + review tier) ──────────────
# The wiring pins above are literal greps — necessary but not sufficient: a reordered
# arm, a dedupe() delimiter bug, or a drifted inline-fallback copy (the hand-maintained
# mirror of describe-plugin-compose.sh's arms) would ship green under greps alone.
# Mirror the emit_tools/baseprovision extracted-step harness: parse each compose step's
# run: script out of the workflow YAML (python3+yaml, keyed on the step id) and DRIVE
# it against filesystem fixtures. Coverage transfer: the two write-tier step bodies are
# pinned byte-identical below, so driving the implement copy covers devflow.yml too;
# dedupe() is pinned byte-identical across all three tiers, so its execution here
# covers the runner's copy as well.
if command -v python3 >/dev/null 2>&1 && python3 -c 'import yaml' >/dev/null 2>&1; then
  _505_extract() {  # $1=workflow file  $2=step id → extracted run: script on stdout
    python3 - "$1" "$2" <<'PY'
import shlex, sys, yaml
doc = yaml.safe_load(open(sys.argv[1]))
prelude = "".join("export %s=%s\n" % (k, shlex.quote(str(v)))
                  for k, v in (doc.get("env") or {}).items())
for job in doc["jobs"].values():
    for s in job.get("steps", []):
        if s.get("id") == sys.argv[2] and "run" in s:
            sys.stdout.write("#!/usr/bin/env bash\n" + prelude + s["run"])
            raise SystemExit
raise SystemExit("step %s not found in %s" % (sys.argv[2], sys.argv[1]))
PY
  }
  _505_WSTEP=$(mktemp); _505_extract "$_505_WF/devflow-implement.yml" plugins > "$_505_WSTEP"
  _505_WSTEP2=$(mktemp); _505_extract "$_505_WF/devflow.yml" plugins > "$_505_WSTEP2"
  _505_RSTEP=$(mktemp); _505_extract "$_505_WF/devflow-runner.yml" plugins > "$_505_RSTEP"
  assert_eq "#513 I3: write-tier compose step bodies byte-identical (driving one covers both)" "yes" \
    "$(cmp -s "$_505_WSTEP" "$_505_WSTEP2" && echo yes || echo no)"
  _505_dedupe_body() { awk '/^dedupe\(\) \{/{f=1} f{print} f&&/^\}/{exit}' "$1"; }
  assert_eq "#513 I3: dedupe() body byte-identical across the three tiers (execution below covers all)" "yes" \
    "$([ -n "$(_505_dedupe_body "$_505_WSTEP")" ] \
       && [ "$(_505_dedupe_body "$_505_WSTEP")" = "$(_505_dedupe_body "$_505_RSTEP")" ] && echo yes || echo no)"

  # Expected baked baseline (the composed output when nothing is spliced).
  _505_BASE_P="code-review@claude-plugins-official"$'\n'"claude-md-management@claude-plugins-official"$'\n'"$SUITE_PLUGIN_SPEC"
  _505_BASE_M="https://github.com/anthropics/claude-plugins-official.git"$'\n'"./"
  _505_parse_out() {  # $1=GITHUB_OUTPUT file → sets _PLG/_MKT
    _PLG="$(awk '/^plugins<</{f=1;next} f&&/^PLG_EOF_/{f=0} f' "$1")"
    _MKT="$(awk '/^plugin_marketplaces<</{f=1;next} f&&/^MKT_EOF_/{f=0} f' "$1")"
  }

  # ── write tier: drive the implement copy in a fixture cwd ──
  _505_FIXROOT=$(mktemp -d)
  _505_wstep_run() {  # run the extracted write-tier step with cwd=$_505_FIXROOT
    local out; out=$(mktemp)
    _ANN="$( cd "$_505_FIXROOT" && GITHUB_OUTPUT="$out" bash "$_505_WSTEP" 2>&1 )"; _RC=$?
    if [ "$_RC" -ne 0 ]; then _PLG="__STEP_FAILED_rc=${_RC}__"; _MKT="$_PLG"; rm -f "$out"; return; fi
    _505_parse_out "$out"; rm -f "$out"
  }
  _505_mkfix() {  # $1=vendor mode full|nohelper|nocompose|dupfake  [$2=settings json]
    rm -rf "$_505_FIXROOT"; mkdir -p "$_505_FIXROOT/.claude" "$_505_FIXROOT/.prflow/vendor/prflow/scripts"
    case "$1" in
      full)      cp "$REP" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/resolve-extra-plugins.sh"
                 cp "$DPC" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/describe-plugin-compose.sh" ;;
      nohelper)  : ;;
      nocompose) cp "$REP" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/resolve-extra-plugins.sh" ;;
      dupfake)   # a stand-in helper emitting a baseline DUPLICATE + a new entry, to
                 # drive dedupe()'s duplicate-drop (the real helper skips baked
                 # duplicates itself, so only a stand-in can feed dedupe one).
                 printf '%s\n' '#!/usr/bin/env bash' \
                   'if [ "$1" = plugins ]; then printf "%s\n" code-review@claude-plugins-official new@claude-plugins-official; fi' \
                   'exit 0' > "$_505_FIXROOT/.prflow/vendor/prflow/scripts/resolve-extra-plugins.sh"
                 cp "$DPC" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/describe-plugin-compose.sh" ;;
    esac
    if [ "${2+set}" = set ]; then printf '%s' "$2" > "$_505_FIXROOT/.claude/settings.json"; fi
  }
  # (w1) absent settings + full vendor → output IS the baked baseline, no annotation
  _505_mkfix full
  _505_wstep_run
  assert_eq "#513 I3 write: absent settings → plugins output is the baked baseline exactly" "$_505_BASE_P" "$_PLG"
  assert_eq "#513 I3 write: absent settings → marketplaces output is the baked baseline exactly" "$_505_BASE_M" "$_MKT"
  assert_eq "#513 I3 write: absent settings → NO annotation (silent baseline arm)" "no" \
    "$(printf '%s' "$_ANN" | grep -qE '::(warning|notice)::' && echo yes || echo no)"
  # (w2) settings extras → spliced AFTER the baseline, audited via the DPC ::notice::
  _505_mkfix full '{"enabledPlugins":{"extra@claude-plugins-official":true},"extraKnownMarketplaces":{"my-mk":{"source":{"source":"github","repo":"o/r"}}}}'
  _505_wstep_run
  assert_eq "#513 I3 write: extras spliced after the baked baseline (plugins)" \
    "$_505_BASE_P"$'\n'"extra@claude-plugins-official" "$_PLG"
  assert_eq "#513 I3 write: extras spliced after the baked baseline (marketplaces)" \
    "$_505_BASE_M"$'\n'"https://github.com/o/r.git" "$_MKT"
  assert_eq "#513 I3 write: splice audited via ::notice:: naming both entries (DPC-rendered)" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::notice::' && printf '%s' "$_ANN" | grep -q 'extra@claude-plugins-official' \
       && printf '%s' "$_ANN" | grep -q 'https://github.com/o/r.git' && echo yes || echo no)"
  assert_eq "#513 I3 write: clean splice emits no ::warning::" "no" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && echo yes || echo no)"
  # (w3) dedupe(): a baseline-duplicate extra is dropped, the new entry appended,
  # first-occurrence order kept (drives the |line| sentinel matching for real)
  _505_mkfix dupfake
  _505_wstep_run
  assert_eq "#513 I3 write: dedupe drops a baseline-duplicate extra, keeps the new entry" \
    "$_505_BASE_P"$'\n'"new@claude-plugins-official" "$_PLG"
  assert_eq "#513 I3 write: dedupe leaves marketplaces baseline untouched" "$_505_BASE_M" "$_MKT"
  # (w4) skew arm: helper absent → baseline + ::warning:: naming prflow_version
  _505_mkfix nohelper
  _505_wstep_run
  assert_eq "#513 I3 write: helper-absent skew → plugins output is the baseline exactly" "$_505_BASE_P" "$_PLG"
  assert_eq "#513 I3 write: helper-absent skew → ::warning:: names prflow_version as the remedy" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && printf '%s' "$_ANN" | grep -q 'Bump prflow_version' && echo yes || echo no)"
  # (w5) partial-vendor skew (HELPER present, COMPOSE absent), MIXED degraded+valid
  # settings → the inline fallback emits BOTH the ::warning:: AND the splice ::notice::
  # — executing the hand-maintained mirror of DPC's coexist arm (PR #513 never-silent)
  _505_mkfix nocompose '{"enabledPlugins":{"good@claude-plugins-official":true,"bad@claude-plugins-official":"true"}}'
  _505_wstep_run
  assert_eq "#513 I3 write: inline fallback mixed → the valid extra IS composed" \
    "$_505_BASE_P"$'\n'"good@claude-plugins-official" "$_PLG"
  assert_eq "#513 I3 write: inline fallback mixed → BOTH ::warning:: and ::notice:: (coexist, never silent)" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && printf '%s' "$_ANN" | grep -q 'degraded entries' \
       && printf '%s' "$_ANN" | grep -q '::notice::' && printf '%s' "$_ANN" | grep -q 'good@claude-plugins-official' && echo yes || echo no)"
  # (w6) COMPOSE absent, degraded-only (invalid JSON) → ::warning:: only, baseline kept
  _505_mkfix nocompose '{not json'
  _505_wstep_run
  assert_eq "#513 I3 write: inline fallback degraded-only → ::warning::, baseline, no ::notice::" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && ! printf '%s' "$_ANN" | grep -q '::notice::' \
       && [ "$_PLG" = "$_505_BASE_P" ] && echo yes || echo no)"
  # (w7) COMPOSE absent, splice-only → ::notice:: only, marked unavailable
  _505_mkfix nocompose '{"enabledPlugins":{"solo@claude-plugins-official":true}}'
  _505_wstep_run
  assert_eq "#513 I3 write: inline fallback splice-only → ::notice:: (unavailable-marked), no ::warning::" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::notice::' && printf '%s' "$_ANN" | grep -q 'describe-plugin-compose.sh unavailable' \
       && ! printf '%s' "$_ANN" | grep -q '::warning::' && echo yes || echo no)"

  # ── review tier: drive the runner copy, env-driven (rank selection + arm routing) ──
  _505_TRUST=$(mktemp -d)
  cp "$REP" "$_505_TRUST/resolve-extra-plugins.sh"; cp "$DPC" "$_505_TRUST/describe-plugin-compose.sh"
  _505_RSET="$_505_TRUST/settings.json"
  _505_rstep_run() {  # $1=COMPOSE_SETTINGS  $2=SOURCE  $3=HELPER_DIR  $4=VENDOR_SOURCE
    local out; out=$(mktemp)
    _ANN="$( cd "$_505_FIXROOT" && COMPOSE_SETTINGS="$1" COMPOSE_SETTINGS_SOURCE="$2" \
      COMPOSE_HELPER_DIR="$3" COMPOSE_HELPER_SOURCE=base-ref VENDOR_SOURCE="$4" \
      GITHUB_OUTPUT="$out" bash "$_505_RSTEP" 2>&1 )"; _RC=$?
    if [ "$_RC" -ne 0 ]; then _PLG="__STEP_FAILED_rc=${_RC}__"; _MKT="$_PLG"; rm -f "$out"; return; fi
    _505_parse_out "$out"; rm -f "$out"
  }
  # (r1) rank 1 (base-ref materialized dir) + ok settings with an extra → splice
  rm -rf "$_505_FIXROOT"; mkdir -p "$_505_FIXROOT"
  printf '%s' '{"enabledPlugins":{"extra@claude-plugins-official":true}}' > "$_505_RSET"
  _505_rstep_run "$_505_RSET" ok "$_505_TRUST" committed
  assert_eq "#513 I3 review: rank-1 trusted dir + ok settings → extra composed after baseline" \
    "$_505_BASE_P"$'\n'"extra@claude-plugins-official" "$_PLG"
  assert_eq "#513 I3 review: rank-1 announces the trusted-base-ref helper source" "yes" \
    "$(printf '%s' "$_ANN" | grep -q 'trusted base ref' && echo yes || echo no)"
  assert_eq "#513 I3 review: rank-1 splice audited via ::notice::" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::notice::' && printf '%s' "$_ANN" | grep -q 'extra@claude-plugins-official' && echo yes || echo no)"
  # (r2) rank 2: no trusted dir, vendor_source=fetch, vendored copies under the repo
  # root (cwd — not a git repo, so _REPO_ROOT falls back to pwd) → vendored copy used
  mkdir -p "$_505_FIXROOT/.prflow/vendor/prflow/scripts"
  cp "$REP" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/resolve-extra-plugins.sh"
  cp "$DPC" "$_505_FIXROOT/.prflow/vendor/prflow/scripts/describe-plugin-compose.sh"
  _505_rstep_run "$_505_RSET" ok "" fetch
  assert_eq "#513 I3 review: rank-2 (vendor_source=fetch) composes via the vendored copy" \
    "$_505_BASE_P"$'\n'"extra@claude-plugins-official" "$_PLG"
  assert_eq "#513 I3 review: rank-2 announces the runtime-fetched vendored source" "yes" \
    "$(printf '%s' "$_ANN" | grep -q 'runtime-fetched vendored copy' && echo yes || echo no)"
  # (r3) SECURITY: same vendored files present but vendor_source=committed (a PR-head
  # editable copy) → NOT consulted: fail-closed baseline + trusted-source-rule warning
  _505_rstep_run "$_505_RSET" ok "" committed
  assert_eq "#513 I3 review: vendor_source=committed → PR-editable vendored copy NOT consulted (baseline only)" \
    "$_505_BASE_P" "$_PLG"
  assert_eq "#513 I3 review: fail-closed arm names the trusted-source rule" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && printf '%s' "$_ANN" | grep -q 'trusted-source rule' && echo yes || echo no)"
  # (r4) degraded settings source (trusted read failed) → DPC failed arm ::warning::
  _505_rstep_run "" degraded "$_505_TRUST" committed
  assert_eq "#513 I3 review: degraded settings source → trusted-read-failed ::warning::, baseline" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && printf '%s' "$_ANN" | grep -qi 'could not read the trusted base-ref' \
       && [ "$_PLG" = "$_505_BASE_P" ] && echo yes || echo no)"
  # (r5) vanished: classified ok but the materialized file is GONE → fails closed to
  # the trusted-read-failed arm naming the vanish (never the silent absent baseline)
  _505_rstep_run "$_505_TRUST/definitely-gone.json" ok "$_505_TRUST" committed
  assert_eq "#513 I3 review: materialized-but-vanished settings → fail-closed ::warning:: naming the vanish" "yes" \
    "$(printf '%s' "$_ANN" | grep -q '::warning::' && printf '%s' "$_ANN" | grep -q 'vanished before compose' \
       && [ "$_PLG" = "$_505_BASE_P" ] && echo yes || echo no)"
  # (r6) absent on base ref → the silent baseline (no annotation at all)
  _505_rstep_run "" absent "$_505_TRUST" committed
  assert_eq "#513 I3 review: absent-on-base-ref → baseline exactly" "$_505_BASE_P" "$_PLG"
  assert_eq "#513 I3 review: absent-on-base-ref → NO annotation (silent)" "no" \
    "$(printf '%s' "$_ANN" | grep -qE '::(warning|notice)::' && echo yes || echo no)"
  rm -rf "$_505_FIXROOT" "$_505_TRUST"; rm -f "$_505_WSTEP" "$_505_WSTEP2" "$_505_RSTEP"
else
  skip "#513 I3 compose-step behavioral block" host-capability "python3+pyyaml unavailable; compose steps covered by static pins only this run"
fi

# ── #1049 vendored-marketplace resolution: compose-vendor-marketplace.sh + the
#    implement-tier vendor_marketplace step ──────────────────────────────────────
# This repo's cloud implement run resolved the plugin root to <workspace>/skills (the
# repo-root marketplace's ./ source) while every consumer resolves it from
# .prflow/vendor/prflow — so the shipped helper-path shape had no coverage here. The
# fix composes a job-local marketplace rooted at the vendored subtree and swaps the ./
# entry for it, implement-tier only. Constraints: the tracked marketplace.json and the
# baked baseline literal stay untouched; the composed-vs-degraded branch selection lives
# in the helper (describe-denial-count.sh extraction convention) and is driven here.
echo "compose-vendor-marketplace.sh + vendor_marketplace step (issue #1049)"
_1049_CVM="$LIB/../scripts/compose-vendor-marketplace.sh"
assert_eq "#1049 AC1: compose-vendor-marketplace.sh exists" "yes" "$([ -f "$_1049_CVM" ] && echo yes || echo no)"
assert_eq "#1049 AC1: compose-vendor-marketplace.sh SPDX header" "yes" \
  "$(grep -q 'SPDX-License-Identifier: MIT' "$_1049_CVM" && echo yes || echo no)"
# guard-class 2: the emitted marketplace-list swap is a bash read-loop, so no
# tr/sed/wc/cut/head command may derive it.
assert_eq "#1049 AC1: no tr/sed/wc/cut/head command derives the emitted list (guard-class 2)" "0" \
  "$(grep -cE '^[[:space:]]*(tr|sed|wc|cut|head)([[:space:]]|$)' "$_1049_CVM")"

# Behavioral driver: a fixture vendor tree + a marketplace-list file, run the helper,
# capture the rewritten list and the stdout annotation.
_1049_mkvendor() {  # $1=root  $2=complete|partial  → make .prflow/vendor[/prflow/.claude-plugin/plugin.json]
  mkdir -p "$1/.prflow/vendor/prflow/scripts"
  if [ "$2" = complete ]; then
    mkdir -p "$1/.prflow/vendor/prflow/.claude-plugin"
    printf '%s\n' '{"name":"prflow"}' > "$1/.prflow/vendor/prflow/.claude-plugin/plugin.json"
  fi
}
_1049_run() {  # $1=vendor-root-arg  $2=marketplaces-file-content  (cwd=$_1049_FX)
  _1049_MKF="$_1049_FX/mk.txt"; printf '%s\n' "$2" > "$_1049_MKF"
  _1049_ANN="$( cd "$_1049_FX" && bash "$_1049_CVM" "$_1049_MKF" "$1" 2>&1 )"; _1049_RC=$?
  _1049_LIST="$(cat "$_1049_MKF")"
}
# (a) composed arm: complete vendor + a list containing ./ → ./ swapped for the vendor
# root, marketplace.json written (devflow-marketplace, prflow sourced ./prflow), ::notice::
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
_1049_run .prflow/vendor "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
assert_eq "#1049 composed: helper always exits 0" "0" "$_1049_RC"
assert_eq "#1049 composed: ./ entry swapped for the vendor root" \
  "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './.prflow/vendor')" "$_1049_LIST"
# THE regression that reverted PR #1137. claude-code-action validates every
# plugin_marketplaces entry (base-action/src/install-plugins.ts): an entry is a local path
# only if it starts with ./, ../, / or a Windows drive prefix, and anything else must match
# its ^https://….git$ URL regex. The un-prefixed `.prflow/vendor` matched neither, so the
# action aborted every cloud implement run with `Invalid marketplace URL format`. That
# validator runs only inside a real cloud run — no desk lint, CI shard, or review verdict
# reaches it — so the emitted entry's prefix is asserted here, at the one point that can.
# Assert the PREDICATE the action applies, not the literal, so it still holds if the
# vendor root moves.
_1049_SWAPPED_ENTRY="${_1049_LIST##*$'\n'}"
assert_eq "#1049 composed: the emitted marketplace entry is a local path claude-code-action accepts (./, ../ or / prefix)" "yes" \
  "$(case "$_1049_SWAPPED_ENTRY" in ./*|../*|/*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1049 composed: emits a ::notice:: audit line" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::notice::' && echo yes || echo no)"
assert_eq "#1049 composed: no ::warning:: on the clean composed arm" "no" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && echo yes || echo no)"
assert_eq "#1049 composed: job-local marketplace.json is named devflow-marketplace" "yes" \
  "$(grep -q '"name": "devflow-marketplace"' "$_1049_FX/.prflow/vendor/.claude-plugin/marketplace.json" && echo yes || echo no)"
assert_eq "#1049 composed: job-local marketplace sources prflow at ./prflow" "yes" \
  "$(grep -q '"source": "./prflow"' "$_1049_FX/.prflow/vendor/.claude-plugin/marketplace.json" && echo yes || echo no)"
rm -rf "$_1049_FX"
# (b) degraded arm: partial vendor (no plugin.json) → list UNCHANGED, ::warning:: names prflow_version
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" partial
_1049_run .prflow/vendor "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
assert_eq "#1049 degraded: partial vendor → list left UNCHANGED (still ./)" \
  "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')" "$_1049_LIST"
assert_eq "#1049 degraded: ::warning:: names prflow_version as the remedy" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && printf '%s' "$_1049_ANN" | grep -q 'prflow_version' && echo yes || echo no)"
assert_eq "#1049 degraded: no marketplace.json written on the degraded arm" "no" \
  "$([ -f "$_1049_FX/.prflow/vendor/.claude-plugin/marketplace.json" ] && echo yes || echo no)"
rm -rf "$_1049_FX"
# (c) usage arm: missing args → ::warning::, exit 0, no crash
_1049_FX="$(mktemp -d)"
_1049_ANN="$( cd "$_1049_FX" && bash "$_1049_CVM" 2>&1 )"; _1049_RC=$?
assert_eq "#1049 usage: missing args exits 0" "0" "$_1049_RC"
assert_eq "#1049 usage: missing args emits a ::warning::" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && echo yes || echo no)"
rm -rf "$_1049_FX"
# (d) swap-miss arm: complete vendor but the list has NO ./ entry → marketplace.json is
# written but a ::warning:: flags that nothing consumed it (never a silent resolution).
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
_1049_run .prflow/vendor 'https://github.com/anthropics/claude-plugins-official.git'
assert_eq "#1049 swap-miss: no ./ in the list → ::warning:: (not silent)" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && echo yes || echo no)"
rm -rf "$_1049_FX"
# (e) write-failure arm: complete vendor, but the job-local marketplace.json cannot be
# written. The helper runs under `set -u` and NOT `set -e`, so the write is checked
# explicitly and the swap is GATED on it — otherwise the list would be repointed at
# $VENDOR_ROOT while the marketplace.json it depends on does not exist, i.e. a
# silently-wrong resolution wearing a green ::notice::. Without a driver for that gate a
# refactor hoisting the swap above it (or downgrading the annotation to a notice) ships
# green, so drive it here. Fixture: a regular FILE where the helper needs to mkdir
# `<vendor-root>/.claude-plugin` — portable and root-insensitive, unlike a chmod.
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
printf '%s\n' 'not a directory' > "$_1049_FX/.prflow/vendor/.claude-plugin"
_1049_run .prflow/vendor "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
assert_eq "#1049 write-failure: marketplace.json unwritable → list left UNCHANGED (no swap without a confirmed write)" \
  "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')" "$_1049_LIST"
assert_eq "#1049 write-failure: emits a ::warning:: and NO ::notice:: (never a broken resolution reported as clean)" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && ! printf '%s' "$_1049_ANN" | grep -q '::notice::' && echo yes || echo no)"
rm -rf "$_1049_FX"
# (f) rewrite-failure arm: complete vendor AND a `./` entry present, but the marketplaces
# FILE itself cannot be rewritten. Sibling of (e): (e) gates on the marketplace.json write,
# this gates on the write that actually repoints the list. Left unchecked, the run keeps
# the repo-root `./` resolution while the success ::notice:: affirms the vendored subtree —
# the same "non-clean path reported as clean" shape (e) guards one write earlier, and the
# one the whole helper exists to prevent.
#
# FIXTURE CHOICE IS LOAD-BEARING — the read must SUCCEED and only the write fail, or the
# test is vacuous. A path whose read also fails (a directory, a missing parent) leaves
# SWAPPED=0, so the swap-miss ::warning:: fires and the assertion below would pass with
# the gate REMOVED; a directory additionally aborts the helper on `set -u` (the read never
# assigns `line`) before the write is reached. Mode 0444 is the one portable mechanism
# that separates read from write, and root bypasses it — so prove the fixture is effective
# rather than trusting the mode, and take an auditable skip when it is not (#456).
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
_1049_ROF="$_1049_FX/mk.txt"
printf '%s\n%s\n' 'https://github.com/anthropics/claude-plugins-official.git' './' > "$_1049_ROF"
chmod 444 "$_1049_ROF" 2>/dev/null || true
if [ ! -w "$_1049_ROF" ]; then
  _1049_ANN="$( cd "$_1049_FX" && bash "$_1049_CVM" "$_1049_ROF" .prflow/vendor 2>&1 )"; _1049_RC=$?
  _1049_LIST="$(cat "$_1049_ROF")"
  assert_eq "#1049 rewrite-failure: unwritable marketplaces file → ::warning:: and NO ::notice:: (nothing may claim a swap that never took effect)" "yes" \
    "$(printf '%s' "$_1049_ANN" | grep -q '::warning::' && ! printf '%s' "$_1049_ANN" | grep -q '::notice::' && echo yes || echo no)"
  assert_eq "#1049 rewrite-failure: the list still carries the repo-root ./ the run actually resolves from" \
    "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')" "$_1049_LIST"
  assert_eq "#1049 rewrite-failure: helper still exits 0 (best-effort; a compose bug never breaks the credentialed run)" "0" "$_1049_RC"
else
  # Root (or a mode-ignoring filesystem) can write the 0444 fixture, so the write cannot be
  # made to fail here and the arm is unreachable. Auditable skip, never a silent absence.
  skip "#1049 rewrite-failure arm" host-capability \
    "chmod 444 did not make the marketplaces file unwritable (running as root, or a permissive filesystem)"
fi
chmod 644 "$_1049_ROF" 2>/dev/null || true
rm -rf "$_1049_FX"
# (g) baseline coupling: the helper's swap arm matches the literal `./`, but nothing
# above ties that to what the baked marketplaces baseline actually emits — every fixture
# supplies its own `./`. The #505 AC4 pins lock $_505_BM byte-identical across the three
# workflows and say nothing about whether the helper matches any line it produces, so a
# baseline respelling (`.`, a trailing slash, an absolute path) would silently take the
# swap-miss arm in production while the suite stayed green. Couple them BEHAVIORALLY
# rather than by grepping the two literals at each other: derive the baseline's emitted
# entries from the pinned literal (the same `printf '%s\n' ` prefix strip the #505 AC4
# block uses) and drive the REAL helper over them. The composed ::notice:: fires only
# when SWAPPED=1, so this goes RED if either side moves — and it survives a refactor of
# the match itself (case → if, a variable), which a literal-to-literal pin would not.
_1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
_1049_BM_ENTRIES="${_505_BM##*"' "}"
# shellcheck disable=SC2086  # deliberate word-split: reproduce the baseline printf's lines
_1049_run .prflow/vendor "$(printf '%s\n' $_1049_BM_ENTRIES)"
assert_eq "#1049 baseline coupling: the baked marketplaces baseline emits an entry the helper's swap arm matches" "yes" \
  "$(printf '%s' "$_1049_ANN" | grep -q '::notice::' && ! printf '%s' "$_1049_ANN" | grep -q '::warning::' && echo yes || echo no)"
rm -rf "$_1049_FX"

# Workflow wiring: the vendor_marketplace step is implement-tier ONLY.
_1049_IMPL="$_505_WF/devflow-implement.yml"
assert_eq "#1049 wiring: devflow-implement.yml has the vendor_marketplace step" "1" \
  "$(grep -c 'id: vendor_marketplace' "$_1049_IMPL")"
assert_eq "#1049 wiring: the step invokes compose-vendor-marketplace.sh at the vendored path" "yes" \
  "$(grep -qF 'bash "$VENDORMK" "$MKF" .prflow/vendor' "$_1049_IMPL" && echo yes || echo no)"
assert_eq "#1049 wiring: the step's vendored-helper-absent skew arm names prflow_version" "yes" \
  "$(grep -qF 'compose-vendor-marketplace.sh not found' "$_1049_IMPL" && grep -q 'Bump prflow_version' "$_1049_IMPL" && echo yes || echo no)"
# Implement-tier ONLY: the manual-command and review tiers must NOT reference either the
# step id or the helper, so their plugin root stays the repo-root ./ (out of scope here).
for _f in devflow devflow-runner; do
  assert_eq "#1049 wiring: $_f.yml does NOT reference vendor_marketplace (implement-tier only)" "0" \
    "$(grep -c 'vendor_marketplace' "$_505_WF/$_f.yml")"
  assert_eq "#1049 wiring: $_f.yml does NOT reference compose-vendor-marketplace.sh (implement-tier only)" "0" \
    "$(grep -c 'compose-vendor-marketplace.sh' "$_505_WF/$_f.yml")"
done

# Execute the extracted vendor_marketplace step against fixtures (mirrors the #513 I3
# harness): the swap must actually happen when the vendored helper is present, and the
# list must pass through unchanged (repo-root ./) when it is absent.
if command -v python3 >/dev/null 2>&1 && python3 -c 'import yaml' >/dev/null 2>&1; then
  _1049_extract() {  # $1=workflow  $2=step id → run: script on stdout
    python3 - "$1" "$2" <<'PY'
import sys, yaml
doc = yaml.safe_load(open(sys.argv[1]))
for job in doc["jobs"].values():
    for s in job.get("steps", []):
        if s.get("id") == sys.argv[2] and "run" in s:
            sys.stdout.write("#!/usr/bin/env bash\n" + s["run"]); raise SystemExit
raise SystemExit("step %s not found" % sys.argv[2])
PY
  }
  _1049_VSTEP="$(mktemp)"; _1049_extract "$_1049_IMPL" vendor_marketplace > "$_1049_VSTEP"
  # guard-class 2 on the STEP's own inline re-read loop (not just the helper): the step
  # re-derives the emitted plugin_marketplaces list via a bash while-read loop and its
  # comment claims guard-class 2, so pin that the extracted step body invokes no
  # tr/sed/wc/cut/head to derive that emitted value.
  assert_eq "#1049 step exec: the vendor_marketplace step derives no emitted value via tr/sed/wc/cut/head (guard-class 2)" "0" \
    "$(grep -cE '^[[:space:]]*(tr|sed|wc|cut|head)([[:space:]]|$)' "$_1049_VSTEP")"
  _1049_vstep_run() {  # $1=cwd  $2=COMPOSED_MK → sets _1049_OUT (plugin_marketplaces heredoc value)
    local out; out="$(mktemp)"
    ( cd "$1" && COMPOSED_MK="$2" GITHUB_OUTPUT="$out" bash "$_1049_VSTEP" >/dev/null 2>&1 )
    _1049_OUT="$(awk '/^plugin_marketplaces<</{f=1;next} f&&/^MKV_EOF_/{f=0} f' "$out")"; rm -f "$out"
  }
  # helper present + complete vendor → ./ swapped to .prflow/vendor
  _1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" complete
  cp "$_1049_CVM" "$_1049_FX/.prflow/vendor/prflow/scripts/compose-vendor-marketplace.sh"
  _1049_vstep_run "$_1049_FX" "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
  # End-to-end through the real workflow step: the value that actually reaches the action's
  # plugin_marketplaces input must carry the ./ prefix its validator requires (see the
  # composed-arm assertion above for why this is the one gate that can catch it).
  assert_eq "#1049 step exec: helper present → ./ resolved to the vendored marketplace root, ./-prefixed for the action's validator" \
    "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './.prflow/vendor')" "$_1049_OUT"
  rm -rf "$_1049_FX"
  # helper PRESENT but vendor PARTIAL (no plugin.json) → the helper exits 0 without
  # swapping (its internal degraded arm), the workflow's `|| echo warning` does NOT fire,
  # and the step's re-read loop must pass the list through unchanged (repo-root ./ kept).
  # This is a distinct end-to-end path from both cases below — the outer file-absent guard
  # is a different branch than the helper's internal manifest-absent arm.
  _1049_FX="$(mktemp -d)"; _1049_mkvendor "$_1049_FX" partial
  cp "$_1049_CVM" "$_1049_FX/.prflow/vendor/prflow/scripts/compose-vendor-marketplace.sh"
  _1049_vstep_run "$_1049_FX" "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
  assert_eq "#1049 step exec: helper present + partial vendor → list passes through unchanged (repo-root ./ kept)" \
    "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')" "$_1049_OUT"
  rm -rf "$_1049_FX"
  # helper absent (skew) → list passes through unchanged (repo-root ./ kept)
  _1049_FX="$(mktemp -d)"; mkdir -p "$_1049_FX/.prflow/vendor"
  _1049_vstep_run "$_1049_FX" "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')"
  assert_eq "#1049 step exec: helper absent → list passes through unchanged (repo-root ./ kept)" \
    "$(printf '%s\n%s' 'https://github.com/anthropics/claude-plugins-official.git' './')" "$_1049_OUT"
  rm -rf "$_1049_FX"; rm -f "$_1049_VSTEP"
else
  skip "#1049 vendor_marketplace step behavioral block" host-capability "python3+pyyaml unavailable; step covered by static pins only this run"
fi

# ── #456 skip tally, summary renderer, and the NOTE-emit meta-assertion ───────────────
# The suite reports passed/failed/skipped. A self-skipping check records a SKIP (never a
# PASS or FAIL) through the single skip() helper, and lib/test/summary.sh renders the
# terminal summary. These assertions cover: the renderer's two arms (K==0 byte-identical,
# K>0 with per-skip lines), that skip() moves SKIP and neither PASS/FAIL (with a positive
# control), the untouched exit predicate, and the comment-aware NOTE-emit meta-scan
# (mutation-checked). summary.sh is already sourced at the top of this file.
#
# Renderer arm K==0: byte-identical to the pre-#456 "N passed, M failed" format.
assert_eq "#456 summary: K==0 arm is byte-identical to the historical 'N passed, M failed' format" \
  "12 passed, 3 failed" "$(devflow_render_test_summary 12 3 0 "")"
# Renderer arm K>0: header names K, then one line per skipped check (name, kind, reason).
S456_SKIPS="$(probe_tmp '#456 renderer K>0 skips fixture')"
printf 'blocking-gate\t#434 stale-prose self-scan\torigin/main not resolvable in this checkout\n' > "$S456_SKIPS"
printf 'host-capability\t#423 T6b non-ASCII stdout self-scan\tstrict-ASCII condition not reproducible on this host\n' >> "$S456_SKIPS"
S456_K="$(grep -c . "$S456_SKIPS")"
assert_eq "#456 summary: K>0 arm header reads 'N passed, M failed, K skipped'" \
  "10 passed, 0 failed, 2 skipped" "$(devflow_render_test_summary 10 0 "$S456_K" "$S456_SKIPS" | head -1)"
assert_eq "#456 summary: K>0 arm lists the blocking-gate skip with its name, kind, and reason" "yes" \
  "$(devflow_render_test_summary 10 0 "$S456_K" "$S456_SKIPS" \
       | grep -qF 'SKIP  #434 stale-prose self-scan [blocking-gate] — origin/main not resolvable in this checkout' \
     && echo yes || echo no)"
assert_eq "#456 summary: K>0 arm lists the host-capability skip with its name, kind, and reason" "yes" \
  "$(devflow_render_test_summary 10 0 "$S456_K" "$S456_SKIPS" \
       | grep -qF 'SKIP  #423 T6b non-ASCII stdout self-scan [host-capability] — strict-ASCII condition not reproducible on this host' \
     && echo yes || echo no)"
# The renderer never sets the exit code — it returns 0 on BOTH arms (a skip never fails the
# suite; the suite's own FAIL==0 exit predicate is what decides the exit).
devflow_render_test_summary 12 3 0 "" >/dev/null; assert_eq "#456 summary: renderer returns 0 on the K==0 arm" "0" "$?"
devflow_render_test_summary 10 0 "$S456_K" "$S456_SKIPS" >/dev/null; assert_eq "#456 summary: renderer returns 0 on the K>0 arm" "0" "$?"
rm -f "$S456_SKIPS"
# Renderer honesty: an announced K>0 with an absent/unreadable skip log emits a LOUD
# breadcrumb, never a silent header-with-no-detail (the laundering #456 exists to prevent).
assert_eq "#456 summary: K>0 with an absent skip log emits a 'detail unavailable' breadcrumb, not silence" "yes" \
  "$(devflow_render_test_summary 10 0 2 "$LIB/test/.prflow-nonexistent-skip-log-zzz" | grep -qF 'SKIP  (detail unavailable' && echo yes || echo no)"
# ...and a partially-itemizable log (fewer lines than announced) surfaces the shortfall —
# WITHOUT swallowing the skips it can itemize: the breadcrumb accounts for the missing one,
# and the genuine skip is still listed, so a shortfall never costs the reader the skips the
# log does carry.
S456_SHORT="$(probe_tmp '#456 renderer shortfall fixture')"
printf 'blocking-gate\t#434 shortfall\treason\n' > "$S456_SHORT"
assert_eq "#456 summary: K announced greater than itemizable lines surfaces a shortfall breadcrumb" "yes" \
  "$(devflow_render_test_summary 10 0 2 "$S456_SHORT" | grep -qF '1 of 2 announced skip(s) could not be itemized' && echo yes || echo no)"
assert_eq "#456 summary: the shortfall arm STILL itemizes the skip the log does carry (the breadcrumb adds to the detail, never replaces it)" "1" \
  "$(devflow_render_test_summary 10 0 2 "$S456_SHORT" | grep -cxF '  SKIP  #434 shortfall [blocking-gate] — reason')"
# The OVER-count direction is reconciled too: a log carrying MORE itemizable skips than the
# announced K means the tally the reader trusts under-reports the run's real skip population —
# every skip is listed, but the header is wrong, which is the same laundering in the other
# direction. Surface it; never print a "1 skipped" header over a 2-skip log in silence.
S456_SKIPS_OVER="$(probe_tmp '#456 renderer over-count fixture')"
printf 'blocking-gate\t#434 over-count A\treason A\n' > "$S456_SKIPS_OVER"
printf 'host-capability\t#423 over-count B\treason B\n' >> "$S456_SKIPS_OVER"
assert_eq "#456 summary: K announced LESS than the itemized lines surfaces a tally/log disagreement breadcrumb" "yes" \
  "$(devflow_render_test_summary 10 0 1 "$S456_SKIPS_OVER" | grep -qF 'itemizes 1 more skip(s) than the announced tally of 1' && echo yes || echo no)"
assert_eq "#456 summary: the over-count arm still itemizes EVERY skip in the log (both, not just the announced one)" "2" \
  "$(devflow_render_test_summary 10 0 1 "$S456_SKIPS_OVER" | grep -c '^  SKIP  #4')"
# ...and an EXACT agreement emits neither reconciliation breadcrumb (the positive control that
# keeps the two arms above non-vacuous — they fire on disagreement, not on every K > 0 run).
assert_eq "#456 summary: an agreeing tally and log emit NO reconciliation breadcrumb (positive control)" "0" \
  "$(devflow_render_test_summary 10 0 2 "$S456_SKIPS_OVER" | grep -cE 'could not be itemized|tally and log disagree')"
rm -f "$S456_SHORT" "$S456_SKIPS_OVER"
# A final UNTERMINATED line (no trailing newline) is still itemized — `grep -c .` counts it,
# so a renderer that dropped it (the bare `while read` behavior) would fire a shortfall
# breadcrumb over a log whose only defect is a missing final newline.
S456_UNTERM="$(probe_tmp '#456 renderer unterminated-line fixture')"
printf 'blocking-gate\t#434 unterminated\treason' > "$S456_UNTERM"
assert_eq "#456 summary: a final unterminated log line is still itemized (the tally counts it, so the renderer must too)" "1" \
  "$(devflow_render_test_summary 10 0 1 "$S456_UNTERM" | grep -cxF '  SKIP  #434 unterminated [blocking-gate] — reason')"
assert_eq "#456 summary: the unterminated-line log reconciles with its tally (no breadcrumb)" "0" \
  "$(devflow_render_test_summary 10 0 1 "$S456_UNTERM" | grep -cE 'could not be itemized|tally and log disagree')"
rm -f "$S456_UNTERM"
# A present-but-UNREADABLE skip log takes the loud "absent or unreadable" arm — the arm whose
# wording claims it. Positive control on the SAME fixture first: while readable it itemizes
# normally, so the breadcrumb below is attributable to the unreadability and not to some
# unrelated defect in the fixture. Where the host cannot express unreadability (running as
# root, which reads a chmod-000 file anyway), this self-skips as host-capability rather than
# asserting vacuously.
S456_UNREAD="$(probe_tmp '#456 renderer unreadable-log fixture')"
printf 'blocking-gate\t#434 unreadable\treason\n' > "$S456_UNREAD"
assert_eq "#456 summary: positive control — the unreadable-log fixture itemizes normally WHILE readable" "1" \
  "$(devflow_render_test_summary 10 0 1 "$S456_UNREAD" | grep -cxF '  SKIP  #434 unreadable [blocking-gate] — reason')"
chmod 000 "$S456_UNREAD" 2>/dev/null || true
if [ -r "$S456_UNREAD" ]; then
  skip "#456 renderer present-but-unreadable skip log" host-capability \
    "this host reads a chmod-000 file anyway (running as root?) — the unreadable condition is not reproducible here"
else
  assert_eq "#456 summary: a present-but-UNREADABLE skip log takes the 'absent or unreadable' arm (not the shortfall arm, which would name the wrong cause)" "yes" \
    "$(devflow_render_test_summary 10 0 1 "$S456_UNREAD" | grep -qF 'SKIP  (detail unavailable — skip log absent or unreadable)' && echo yes || echo no)"
fi
chmod 600 "$S456_UNREAD" 2>/dev/null || true
rm -f "$S456_UNREAD"
# Renderer honesty (fail-closed on an unestablished tally): a skip argument that is not a
# plain count — empty (a caller whose grep derivation errored, rc >= 2, prints nothing) or
# non-numeric — renders a LOUD "tally unavailable" line, never a silent coercion to the
# clean 0-skips format (unknown is not zero).
assert_eq "#456 summary: an EMPTY skip tally renders the 'skip tally unavailable' breadcrumb, not a clean 0-skips line" "yes" \
  "$(devflow_render_test_summary 10 0 "" "" | grep -qF 'skip tally unavailable' && echo yes || echo no)"
assert_eq "#456 summary: a NON-NUMERIC skip tally ('abc') renders the same loud 'skip tally unavailable' line" "yes" \
  "$(devflow_render_test_summary 10 0 "abc" "" | grep -qF 'skip tally unavailable' && echo yes || echo no)"
assert_eq "#456 summary: the unestablished-tally arm keeps the pass/fail header as its first line" \
  "10 passed, 0 failed" "$(devflow_render_test_summary 10 0 "" "" | head -1)"
devflow_render_test_summary 10 0 "" "" >/dev/null; assert_eq "#456 summary: renderer returns 0 on the unestablished-tally arm" "0" "$?"
# The suite's exit predicate is unchanged (AC: exits zero when FAIL==0 regardless of K). The
# search literal is ASSEMBLED (so this assertion's own source lines never carry the contiguous
# predicate) and must appear exactly once — the real predicate line, no copy in prose.
S456_EXIT_PRED="$(printf '[ "$%s" -eq 0 ]' 'FAIL')"
assert_eq "#456 the suite exit predicate (FAIL==0) is present exactly once, unchanged by the SKIP tally" \
  "1" "$(grep -cF "$S456_EXIT_PRED" "$SELF_SRC")"
# The tail's SKIP derivation guard fails closed when the tally cannot be derived (a grep
# error prints nothing; an empty value must never be reported as 0 skipped). The literal is
# ASSEMBLED so this assertion's own source lines do not inflate the count (#370 self-match).
S456_UNDERIV="$(printf 'SKIP tally %s' 'underivable')"
assert_eq "#456 the tail SKIP derivation guard is present exactly once (an unestablished tally fails closed, never reads as 0)" \
  "1" "$(grep -cF "$S456_UNDERIV" "$SELF_SRC")"
# ...and the guard's DECISION is driven, not merely grepped. The tail's `case` glob used to be
# a second copy of the renderer's, pinned by source presence only — so a mistyped glob or a
# deleted arm could survive as long as the message literal above still matched. Both callers
# now share ONE predicate (devflow_tally_is_derivable, lib/test/summary.sh), exercised here
# over every arm it decides: a real count is derivable; an empty value (the grep-error shape
# the guard exists for), a non-numeric one, a negative/spaced one, and NO argument at all are
# not. A predicate that answered "derivable" to any of the latter is exactly the fail-OPEN the
# tail guard claims to prevent.
s456_deriv() { devflow_tally_is_derivable "$@" && echo derivable || echo underivable; }
assert_eq "#456 tally predicate: a plain count is derivable" "derivable" "$(s456_deriv 0)"
assert_eq "#456 tally predicate: a multi-digit count is derivable" "derivable" "$(s456_deriv 42)"
assert_eq "#456 tally predicate: an EMPTY value (the grep-error shape) is underivable" "underivable" "$(s456_deriv "")"
assert_eq "#456 tally predicate: a non-numeric value is underivable" "underivable" "$(s456_deriv "grep: no such file")"
assert_eq "#456 tally predicate: a negative value is underivable" "underivable" "$(s456_deriv "-1")"
assert_eq "#456 tally predicate: a digits-with-whitespace value is underivable" "underivable" "$(s456_deriv "1 2")"
assert_eq "#456 tally predicate: NO argument at all is underivable (never an unbound-variable abort)" \
  "underivable" "$(s456_deriv)"
# Wiring: the tail routes through that predicate and fails closed on false. Assemble the
# literal so this check does not carry a contiguous second copy.
S456_TAIL_CALL="$(printf 'if ! devflow_tally_is_derivable "$%s"; then' 'SKIP')"
assert_eq "#456 the tail routes its SKIP tally through the shared derivability predicate" "1" \
  "$(grep -cF "$S456_TAIL_CALL" "$SELF_SRC")"
# The tail's TERMINAL summary emit routes through the renderer — a regression reverting it to
# a bare `echo "$PASS passed, $FAIL failed"` would keep every renderer test above green while
# the real run never reports a skip again. Assemble the literal so this block carries no
# contiguous copy of the call.
S456_RENDER_CALL="$(printf 'devflow_render_test_summary "$%s" "$%s" "$%s" "$%s"' 'PASS' 'FAIL' 'SKIP' 'SKIPS_FILE')"
assert_eq "#456 the tail emits the terminal summary through devflow_render_test_summary (never a bare echo)" "1" \
  "$(grep -cF "$S456_RENDER_CALL" "$SELF_SRC")"
# PASS and FAIL route through the same guard (round 3): all three tallies share one derivation
# mechanism and one failure shape, so all three take the derivability guard — an emptied PASS
# would otherwise be laundered to a number by the python-tally arithmetic, and an emptied FAIL
# would abort as a bare test error instead of a named refusal. Use the same assembled-literal
# pattern as the SKIP guard above.
S456_PASS_GUARD="$(printf 'if ! devflow_tally_is_derivable "$%s"; then' 'PASS')"
S456_FAIL_GUARD="$(printf 'if ! devflow_tally_is_derivable "$%s"; then' 'FAIL')"
assert_eq "#456 the tail routes its PASS tally through the shared derivability predicate" "1" \
  "$(grep -cF "$S456_PASS_GUARD" "$SELF_SRC")"
assert_eq "#456 the tail routes its FAIL tally through the shared derivability predicate" "1" \
  "$(grep -cF "$S456_FAIL_GUARD" "$SELF_SRC")"
#
# skip() records a SKIP and moves NEITHER counter — with a positive control on the same
# results fixture proving a normal assertion DOES still record a PASS (so the zero below is a
# real "a skip doesn't count", not "nothing was ever counted").
S456_SK="$(probe_tmp '#456 skip() skip-log fixture')"; : > "$S456_SK"
S456_RES="$(probe_tmp '#456 skip() results fixture')"; : > "$S456_RES"
S456_NOTE_OUT="$(SKIPS_FILE="$S456_SK" RESULTS_FILE="$S456_RES" skip "#456 probe-check" host-capability "probe reason")"
assert_eq "#456 skip() appends exactly one line to the skip log (SKIP increments)" "1" "$(grep -c . "$S456_SK")"
assert_eq "#456 skip() records NO PASS/FAIL line (neither counter moves)" "0" "$(grep -c . "$S456_RES")"
# The inline NOTE emit is NAME-first (unlike the kind-first STORED line) — assert the exact
# emitted format so a transposition of the two orderings cannot ship unnoticed.
assert_eq "#456 skip() inline NOTE emit is name-first: 'NOTE  <name> skipped [<kind>] — <reason>'" \
  '  NOTE  #456 probe-check skipped [host-capability] — probe reason' "$S456_NOTE_OUT"
# End-to-end order pin: drive the log the skip() call ABOVE produced through the renderer and
# assert the name and kind land in their rendered slots. The K>0 renderer tests earlier use
# hand-written fixtures, so only THIS test couples skip()'s kind-first storage order to the
# renderer's read order — a skip() regression storing name-first would transpose every
# rendered skip's name/kind while those fixture tests stay green.
assert_eq "#456 e2e: a skip()-produced log renders with name and kind in the correct slots" "1" \
  "$(devflow_render_test_summary 1 0 1 "$S456_SK" | grep -cxF '  SKIP  #456 probe-check [host-capability] — probe reason')"
# Positive control: a normal assertion routed to the SAME isolated results file DOES record a PASS.
RESULTS_FILE="$S456_RES" assert_eq "#456 positive control (recorded to the isolated fixture)" "x" "x" >/dev/null
assert_eq "#456 positive control: a normal assertion still records a PASS to the fixture (the zero above is real)" \
  "1" "$(grep -c '^PASS$' "$S456_RES")"
rm -f "$S456_SK" "$S456_RES" "$S456_RES.names"
#
# Adversarial field shapes: skip() SANITIZES the log's own delimiters at the sole producer, so
# the renderer's per-line tab-field split cannot be defeated by a field's content.
# An embedded TAB in a name would otherwise split into an extra field and transpose every slot
# to its right (name → the tail of the name, reason → the real name's remainder); an embedded
# NEWLINE would forge a whole extra log line and inflate the tally. Both are driven end-to-end
# through skip() → renderer, since the store and the read are the pair that must survive them.
S456_ADV="$(probe_tmp '#456 skip() delimiter-sanitization skip log')"; : > "$S456_ADV"
S456_ADV_RES="$(probe_tmp '#456 skip() delimiter-sanitization results')"; : > "$S456_ADV_RES"
SKIPS_FILE="$S456_ADV" RESULTS_FILE="$S456_ADV_RES" \
  skip "$(printf 'na\tme')" host-capability "$(printf 'rea\tson')" >/dev/null
assert_eq "#456 skip(): an embedded TAB in a field is sanitized — the stored line keeps exactly 3 fields" "3" \
  "$(awk -F'\t' 'NR==1 { print NF }' "$S456_ADV")"
assert_eq "#456 skip(): a TAB-carrying name still renders in the NAME slot (no field transposition)" "1" \
  "$(devflow_render_test_summary 1 0 1 "$S456_ADV" | grep -cxF '  SKIP  na me [host-capability] — rea son')"
: > "$S456_ADV"
SKIPS_FILE="$S456_ADV" RESULTS_FILE="$S456_ADV_RES" \
  skip "#456 newline probe" host-capability "$(printf 'two\nlines')" >/dev/null
assert_eq "#456 skip(): an embedded NEWLINE in a field is sanitized — one skip appends exactly ONE log line (no forged tally)" \
  "1" "$(grep -c . "$S456_ADV")"
assert_eq "#456 skip(): the NEWLINE-carrying reason renders on the skip's single line" "1" \
  "$(devflow_render_test_summary 1 0 1 "$S456_ADV" | grep -cxF '  SKIP  #456 newline probe [host-capability] — two lines')"
# CARRIAGE RETURN joins the sanitized class (round 3): a CR is not a log delimiter, but it
# rides verbatim into the rendered summary line, where a terminal treats it as
# return-to-column-0 — a crafted field could visually overwrite the line. Same producer,
# same parameter-expansion class as TAB/NEWLINE, driven end-to-end skip() → renderer.
: > "$S456_ADV"
SKIPS_FILE="$S456_ADV" RESULTS_FILE="$S456_ADV_RES" \
  skip "$(printf 'cr\rname')" host-capability "$(printf 'rea\rson')" >/dev/null
assert_eq "#456 skip(): an embedded CARRIAGE RETURN in a field is sanitized out of the stored line" "0" \
  "$(grep -c "$(printf '\r')" "$S456_ADV")"
assert_eq "#456 skip(): the CR-carrying fields render with spaces in their slots (no control char reaches the summary)" "1" \
  "$(devflow_render_test_summary 1 0 1 "$S456_ADV" | grep -cxF '  SKIP  cr name [host-capability] — rea son')"
# An EMPTY name is normalized at the producer (fail-closed placeholder): the tally counts the
# log line either way (`grep -c .` counts any non-empty line), so an unnamed skip must still
# be itemized — the tally and the itemization use ONE definition of "a skip line", and a
# dropped detail line would trip a reconciliation breadcrumb naming the wrong cause.
: > "$S456_ADV"
SKIPS_FILE="$S456_ADV" RESULTS_FILE="$S456_ADV_RES" \
  skip "" host-capability "no name supplied" >/dev/null
assert_eq "#456 skip(): an EMPTY name is stored as the '(unnamed check)' placeholder (never an empty field)" "1" \
  "$(grep -cF "$(printf '\t(unnamed check)\t')" "$S456_ADV")"
assert_eq "#456 e2e: the skip(\"\")-produced line renders with '(unnamed check)' in the NAME slot" "1" \
  "$(devflow_render_test_summary 1 0 1 "$S456_ADV" | grep -cxF '  SKIP  (unnamed check) [host-capability] — no name supplied')"
assert_eq "#456 e2e: a skip(\"\")-produced log RECONCILES (tally == itemized lines, no breadcrumb)" "0" \
  "$(devflow_render_test_summary 1 0 "$(grep -c . "$S456_ADV")" "$S456_ADV" | grep -cE 'could not be itemized|tally and log disagree')"
# Renderer defense-in-depth for a log skip() did NOT write (hand-corrupted): a NAME-empty line
# is still itemized under the placeholder — the itemization counts exactly what the tally
# counts (non-empty lines), so the two cannot disagree over a missing field, and the
# reconciliation breadcrumbs stay reserved for a tally and a log that have really come apart.
: > "$S456_ADV"
printf 'blocking-gate\t\tname field empty by hand\n' > "$S456_ADV"
printf 'host-capability\tnamed sibling\treason\n' >> "$S456_ADV"
assert_eq "#456 summary: a hand-corrupted NAME-EMPTY log line is itemized under '(unnamed check)' (itemization matches the tally's definition)" "1" \
  "$(devflow_render_test_summary 1 0 2 "$S456_ADV" | grep -cxF '  SKIP  (unnamed check) [blocking-gate] — name field empty by hand')"
assert_eq "#456 summary: the name-empty line trips NO reconciliation breadcrumb (the tally and the itemization agree definitionally)" "0" \
  "$(devflow_render_test_summary 1 0 2 "$S456_ADV" | grep -cE 'could not be itemized|tally and log disagree')"
assert_eq "#456 summary: positive control — the named sibling in the same log still renders normally" "1" \
  "$(devflow_render_test_summary 1 0 2 "$S456_ADV" | grep -cxF '  SKIP  named sibling [host-capability] — reason')"
rm -f "$S456_ADV" "$S456_ADV_RES" "$S456_ADV_RES.names"
#
# ── issue #838: module_host_capability_skip, the sole module-reachable skip surface ──
# The wrapper (module-harness.sh) is what the chmod-000 arms in
# lib/test/modules/review-stall-backstop.sh call instead of a bare `echo`. It must emit
# through skip() — not a second NOTE producer of its own — and record the arm's declared
# assertion credit for the boundary's floor reconciliation. Driven here with the same
# env-override pattern the #456 probes above use; the boundary-side fold, credit
# validation, and floor arithmetic are driven end-to-end in lib/test/test_module_runner.py.
S838_SK="$(probe_tmp '#838 module skip fixture')"; : > "$S838_SK"
S838_RES="$(probe_tmp '#838 module skip results fixture')"; : > "$S838_RES"
S838_CR="$(probe_tmp '#838 module skip credit fixture')"; : > "$S838_CR"
S838_NOTE_OUT="$(SKIPS_FILE="$S838_SK" RESULTS_FILE="$S838_RES" MODULE_SKIP_CREDIT_FILE="$S838_CR" \
  module_host_capability_skip "#838 probe arm" "host cannot deny reads" 2)"
assert_eq "#838 module_host_capability_skip emits through skip() (the sole NOTE producer), unchanged format" \
  '  NOTE  #838 probe arm skipped [host-capability] — host cannot deny reads' "$S838_NOTE_OUT"
assert_eq "#838 module_host_capability_skip stores the skip with the host-capability kind (the only kind the boundary folds)" \
  "1" "$(grep -cxF "$(printf 'host-capability\t#838 probe arm\thost cannot deny reads')" "$S838_SK")"
assert_eq "#838 module_host_capability_skip records the declared assertion credit" "2" "$(cat "$S838_CR")"
assert_eq "#838 module_host_capability_skip records NO PASS/FAIL (a skip is neither)" "0" "$(grep -c . "$S838_RES")"
# An omitted credit is zero, never an unbound-variable abort under the modules' `set -u`.
: > "$S838_CR"
SKIPS_FILE="$S838_SK" RESULTS_FILE="$S838_RES" MODULE_SKIP_CREDIT_FILE="$S838_CR" \
  module_host_capability_skip "#838 creditless arm" "host cannot deny reads" >/dev/null
assert_eq "#838 module_host_capability_skip with no credit argument records 0, not an abort" "0" "$(cat "$S838_CR")"
# An empty MODULE_SKIP_CREDIT_FILE must still emit the skip rather than fail on the
# unbound path — the binding the full-suite boundary supplies is what the credit half
# depends on, and the emit half may not depend on it.
: > "$S838_SK"
S838_UNBOUND_OUT="$(SKIPS_FILE="$S838_SK" RESULTS_FILE="$S838_RES" MODULE_SKIP_CREDIT_FILE="" \
  module_host_capability_skip "#838 unbound-credit arm" "host cannot deny reads" 2)"
assert_eq "#838 module_host_capability_skip with no credit file bound still emits its skip" \
  '  NOTE  #838 unbound-credit arm skipped [host-capability] — host cannot deny reads' "$S838_UNBOUND_OUT"
rm -f "$S838_SK" "$S838_RES" "$S838_RES.names" "$S838_CR"
#
# NOTE-emit meta-assertion. The SOLE `printf '  NOTE ` emit lives inside skip(), delimited by
# the split-built markers below (split so these definition lines add no second occurrence).
SKIP_HELPER_BMARK="SKIP_HELPER_REGION_""BEGIN"
SKIP_HELPER_EMARK="SKIP_HELPER_REGION_""END"
# Fail-closed marker controls (a missing marker would make the scan below fail OPEN):
assert_eq "#456 meta: skip-helper region BEGIN marker present exactly once" "1" "$(pin_count "$SKIP_HELPER_BMARK" "$SELF_SRC")"
assert_eq "#456 meta: skip-helper region END marker present exactly once" "1" "$(pin_count "$SKIP_HELPER_EMARK" "$SELF_SRC")"
# Count `printf '  NOTE ` emit-shapes that are NOT inside the skip-helper region and NOT on a
# comment line. Keyed on the EMIT SHAPE (a printf line carrying the quote+two-space `  NOTE `
# format prefix), not the bare token NOTE (which occurs ~32 times in comments/assertion names),
# and comment-aware (leading `#` lines are skipped) so prose cannot inflate it. Scope is the
# CONTIGUOUS source shape — the accidental un-routed skip a maintainer would actually write;
# an emit assembled from a variable/pieces (as these very tests do to avoid self-tripping)
# bypasses it by construction, and defending against determined evasion is a non-goal.
count_note_emits_outside_skip_region() {  # file -> count of out-of-region, non-comment NOTE emits
  awk -v b="$SKIP_HELPER_BMARK" -v e="$SKIP_HELPER_EMARK" -v sq="'" '
    index($0,b){inreg=1; next}
    index($0,e){inreg=0; next}
    {
      line=$0; sub(/^[[:space:]]+/,"",line)
      if (line ~ /^#/) next            # comment-aware: a NOTE in prose cannot trip it
      if (inreg) next                  # the sole legit emit lives in the skip() region
      if (index($0,"printf")>0 && index($0, sq "  NOTE ")>0) c++
    }
    END{ print c+0 }' "$1"
}
assert_eq "#456 meta: no printf NOTE emit appears outside the skip() helper region (comment-aware)" \
  "0" "$(count_note_emits_outside_skip_region "$SELF_SRC")"
# Mutation proof (RED direction): an injected out-of-region NOTE emit trips the scan. The
# emit-shape token is built from a variable (like the AC3(b) injection proofs) so THIS test's
# own source lines never carry the literal `<quote>  NOTE ` shape — otherwise they would
# themselves trip the "expect 0" scan on run.sh above. The single-quote is assembled the same
# way so no source line here contains the contiguous emit prefix.
S456_NOTE_SHAPE="$(printf '%s  NOTE  injected out-of-region emit' "'")"
S456_META="$(probe_tmp '#456 meta injection copy')"
cp "$SELF_SRC" "$S456_META"
printf '  printf %s\\n\n' "$S456_NOTE_SHAPE" >> "$S456_META"
assert_eq "#456 meta MUTATION: an injected out-of-region NOTE emit trips the scan (1, RED)" \
  "1" "$(count_note_emits_outside_skip_region "$S456_META")"
# Control: the SAME emit shape inside a COMMENT does not trip the scan (comment-awareness).
cp "$SELF_SRC" "$S456_META"
printf '# a comment: printf %s must not count\n' "$S456_NOTE_SHAPE" >> "$S456_META"
assert_eq "#456 meta CONTROL: a NOTE emit inside a comment does not trip the scan (stays 0)" \
  "0" "$(count_note_emits_outside_skip_region "$S456_META")"
rm -f "$S456_META"
#
# The three real self-skip sites route through skip() with the correct kind. Both search
# literals are ASSEMBLED from adjacent pieces so these assertion source lines do not
# themselves carry the contiguous `skip "..." <kind>` string (else the count would inflate by
# this test's own line — the #370 self-match trap).
S456_T6B_CALL="$(printf 'skip "#423 T6b non-ASCII stdout self-scan" %s' 'host-capability')"
S456_434_CALL="$(printf 'skip "#434 stale-prose self-scan" %s' 'blocking-gate')"
assert_eq "#456 the #423 T6b site is a host-capability skip through skip()" "1" \
  "$(grep -cF "$S456_T6B_CALL" "$SELF_SRC")"
assert_eq "#456 both #434 self-scan arms are blocking-gate skips through skip()" "2" \
  "$(grep -cF "$S456_434_CALL" "$SELF_SRC")"
#
# ── ci.yml shard-job settings whose ABSENCE disarms a suite gate rather than failing it ──
# Both pins below guard that failure class, so both go through one matcher. A plain
# substring scan of the job region fails OPEN on the most common way a step is disabled:
# commenting it out leaves the matched literal intact inside the comment body, so the pin
# still prints `yes` while the step no longer runs — precisely the silent disarm these
# pins exist to catch. The matcher therefore skips comment lines, and the negative
# controls below drive that arm rather than trusting it.
# Fails CLOSED to a distinct token — never to `no`. `no` is an assertion-satisfying value
# for the negative controls below, so an empty file, an absent one, or a broken `awk`
# (not a lib/preflight.sh-guaranteed tool) would otherwise satisfy every "expect no"
# assertion while proving nothing — the guard-class-2 shape CLAUDE.md names, where a
# SELECTION is derived through a non-preflight PATH tool.
#
# Every non-`yes`/`no` outcome is mapped to a named token, including the one an
# exit-status check alone misses: an `awk` that exits 0 while printing nothing. Gating on
# rc only would return the empty string there — not `no`, so no assertion is satisfied,
# but not diagnosable either. `unexpected-output` closes that third state by construction,
# so the tokens named here are exhaustive rather than merely the two that were foreseen.
# EREs reach `awk -v` through one round of escape processing, so a backslash escape like
# `\.` is undefined there — gawk preserves it, mawk (Debian/Ubuntu's default awk, i.e.
# CI's) strips it and leaves a wildcard. Call sites therefore use bracket classes (`[.]`),
# which are escape-free and identical across every awk.
# The implementation is job-parameterized (devflow_wf_job_has, defined below and used by the
# #1219 pins); this stays as the shard-job-scoped wrapper — ci.yml by default, file
# overridable via $2, which is exactly how the #671 mutation controls drive their mutated
# copies. One parser, so a fix to the fail-closed contract or the awk escape rule cannot
# reach one copy and miss the other.
devflow_ci_shard_has() {  # $1 = ERE, matched only against UNCOMMENTED lines of the shard job
  devflow_wf_job_has shard "$1" "${2:-$LIB/../.github/workflows/ci.yml}"
}
# `no` is a CONFLATED answer — it means "the job was scanned and the pattern was absent" OR
# "the job header never matched, so nothing was scanned". A malformed ERE fails closed
# (`awk-failed`), but a valid-but-wrong one yields a permanent vacuous `no`. So every
# `no`-valued pin must be paired with a `yes`-valued pin over the SAME job and file, which
# goes RED first when the anchor stops matching; the #1219 call sites below do that, and
# additionally drive the negative pattern to `yes` against a mutated copy.
devflow_wf_job_has() {  # $1 = job name, $2 = ERE, $3 = workflow file; UNCOMMENTED lines of that job only
  local _out
  [ -s "$3" ] || { printf 'unreadable'; return; }
  _out="$(awk -v job="^  $1:[[:space:]]*$" -v pat="$2" '
    $0 ~ job {ins=1; next}
    /^  [A-Za-z_][A-Za-z0-9_-]*:/{ins=0}
    ins && /^[[:space:]]*#/{next}
    ins && $0 ~ pat {f=1}
    END{print (f?"yes":"no")}' "$3")" || { printf 'awk-failed'; return; }
  case "$_out" in
    yes|no) printf '%s' "$_out" ;;
    *)      printf 'unexpected-output' ;;
  esac
}
# ci.yml: the shard job's checkout sets fetch-depth: 0 so origin/main resolves. The
# #434 stale-prose self-scan runs in the `monolith` shard (issue #877 split the single
# test job into a concurrent shard matrix + a `lib + python tests` aggregator); the
# aggregator only recombines tallies and needs no history, so fetch-depth: 0 moved to
# the shard job that actually runs lib/test/run.sh.
assert_eq "#456 ci.yml: the shard job checkout sets fetch-depth: 0" "yes" \
  "$(devflow_ci_shard_has 'fetch-depth: 0')"
#
# ── #1219 the two agent-running cloud jobs check out FULL history ──
# Same failure class as the ci.yml pin above, in the two workflows install.sh actually
# ships. Both jobs run this suite in-env, and the #719 baseline-corpus control resolves a
# FIXED past commit through `git show <ref>:<path>`; that commit only moves further behind
# the branch tip, so any bounded depth is a number that goes stale. What makes the
# regression silent is that it presents as a *skip*, which exits 0 — nothing else turns
# red, and scripts/check-completion-evidence.py's _validate_implement_record then refuses
# the run's completion evidence for a suite pass that otherwise looks clean.
# Job-scoped rather than file-scoped: each of these workflows has several jobs with their own
# checkouts, and only the agent-running job runs the suite.
_I1219_IMPL_YML="$LIB/../.github/workflows/devflow-implement.yml"
_I1219_CMD_YML="$LIB/../.github/workflows/devflow.yml"
# Both patterns are ANCHORED on the VALUE, not merely prefix-matched, because an unanchored
# pair is defeated by a single input: `fetch-depth: 050` matches `fetch-depth: 0` as a
# PREFIX (so the positive pin answers yes) while `[[:space:]]*[1-9]` never sees a digit in
# 1-9 immediately after the space (so the negative pin answers no) — both pins green with a
# bounded depth in force. So the positive pin requires the value to BE `0` (end of line) and
# the negative pin tolerates leading zeros before the first nonzero digit. A trailing
# comment or a quoted `'0'` makes the positive pin answer no, i.e. RED — the fail-closed
# direction, and the reason the value pattern is stated once here rather than loosened.
# structural-pin-ok: cross-file-phase-contract -- the executed checkout line is what supplies the history the #719 baseline-corpus gate needs; bounding it makes that gate self-skip while the workflow stays green
assert_eq "#1219 devflow-implement.yml: the claude job checkout sets fetch-depth: 0" "yes" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_IMPL_YML")"
# A PLAIN revert to a bounded depth is already caught by the positive pin above, which goes
# RED on its own the moment `fetch-depth: 0` is gone — the negative pin's job is the narrower
# one the positive pin cannot do: forbid a SECOND, bounded fetch-depth line added BESIDE a
# retained `fetch-depth: 0`, whose effective value is parser-dependent and which a line
# matcher cannot rank. The optional quote is load-bearing there: `'50'` and `"50"` are valid
# YAML scalars actions/checkout accepts, and a bare `[1-9]` would let the added line through
# while the retained `0` kept the positive pin green.
# structural-pin-ok: cross-file-phase-contract -- a bounded depth anywhere in this job re-arms the shallow-checkout failure the positive pin above exists to prevent
assert_eq "#1219 devflow-implement.yml: the claude job checkout sets no bounded fetch-depth" "no" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_IMPL_YML")"
# structural-pin-ok: cross-file-phase-contract -- the command job hosts /prflow:review-and-fix, whose in-env verification runs the same suite under the same no-skip accounting
assert_eq "#1219 devflow.yml: the command job checkout sets fetch-depth: 0" "yes" \
  "$(devflow_wf_job_has command 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_CMD_YML")"
# structural-pin-ok: cross-file-phase-contract -- a bounded depth anywhere in this job re-arms the shallow-checkout failure the positive pin above exists to prevent
assert_eq "#1219 devflow.yml: the command job checkout sets no bounded fetch-depth" "no" \
  "$(devflow_wf_job_has command 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_CMD_YML")"
# Discriminating controls for the helper itself, so a `no`/`yes` above is evidence rather
# than an artifact of a matcher that can only answer one way: an absent job must answer
# `no` (not `yes`, and not the job-agnostic whole-file answer), and an unreadable file must
# answer `unreadable` (not `no`, which would let a mistyped path pass every pin above).
assert_eq "#1219 devflow_wf_job_has control: an absent job answers no" "no" \
  "$(devflow_wf_job_has no_such_job 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_IMPL_YML")"
assert_eq "#1219 devflow_wf_job_has control: an unreadable file answers unreadable" "unreadable" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_IMPL_YML.nope")"
# Positive control for the NEGATIVE pattern itself — the norm the #671 block states below
# ("`no` is the value the arm's assertion accepts, so [something] that silently produced an
# unusable [input] would satisfy every arm while proving nothing"), applied here. Without
# it a valid-but-wrong ERE (a typo'd bracket class, a `;` for `:`) yields a permanent
# vacuous `no` and the two negative pins above forbid nothing.
# git_sandbox, not probe_tmp: this needs a temp DIRECTORY to hold the mutated copies, and
# probe_tmp allocates a FILE — redirecting into `<file>/bare.yml` is ENOTDIR, so the copies
# would never exist and the matcher would answer `unreadable` against the expected `yes`.
# (Learned the hard way: the first authoring used probe_tmp and went RED in CI.) On failure
# git_sandbox records its own suite FAIL and returns a /dev/null-rooted sentinel, so the
# redirects below fail closed rather than writing anywhere real.
_I1219_MUT="$(git_sandbox '#1219 negative-pattern positive control')"
_suite_tmp_dir "$_I1219_MUT"
# One planted copy per spelling the two patterns CLAIM to handle — bare, single-quoted,
# double-quoted, and leading-zero. A claimed spelling with no planted copy is an unproven
# claim: the pattern could be wrong for that arm alone and every assertion would stay green,
# which is exactly how the pre-anchoring `050` hole survived its own review.
sed 's/^          fetch-depth: 0$/          fetch-depth: 50/' "$_I1219_IMPL_YML" > "$_I1219_MUT/bare.yml" 2>/dev/null
sed "s/^          fetch-depth: 0$/          fetch-depth: '50'/" "$_I1219_IMPL_YML" > "$_I1219_MUT/squoted.yml" 2>/dev/null
sed 's/^          fetch-depth: 0$/          fetch-depth: "50"/' "$_I1219_IMPL_YML" > "$_I1219_MUT/dquoted.yml" 2>/dev/null
sed 's/^          fetch-depth: 0$/          fetch-depth: 050/' "$_I1219_IMPL_YML" > "$_I1219_MUT/leadzero.yml" 2>/dev/null
assert_eq "#1219 negative-pattern control: a planted bare bounded depth answers yes" "yes" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_MUT/bare.yml")"
assert_eq "#1219 negative-pattern control: a planted SINGLE-quoted bounded depth answers yes" "yes" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_MUT/squoted.yml")"
assert_eq "#1219 negative-pattern control: a planted DOUBLE-quoted bounded depth answers yes" "yes" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_MUT/dquoted.yml")"
# The leading-zero arm is the one the unanchored pair let through: BOTH pins must react to
# it, so it is the only planted copy asserted against both patterns.
assert_eq "#1219 negative-pattern control: a planted LEADING-ZERO bounded depth answers yes" "yes" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*['"'"'"]?0*[1-9]' "$_I1219_MUT/leadzero.yml")"
assert_eq "#1219 positive-pin control: a planted LEADING-ZERO depth is NOT read as fetch-depth 0" "no" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_MUT/leadzero.yml")"
# The mutated copies must otherwise still parse as the same job, or the `yes` answers above
# could come from a `sed` that mangled the file rather than from the planted line.
assert_eq "#1219 negative-pattern control: the bare mutated copy lost its fetch-depth: 0" "no" \
  "$(devflow_wf_job_has claude 'fetch-depth:[[:space:]]*0[[:space:]]*$' "$_I1219_MUT/bare.yml")"
unset _I1219_IMPL_YML _I1219_CMD_YML _I1219_MUT
#
# ci.yml: the shard job installs the Claude Code CLI, which is what ARMS the #671
# `claude plugin validate --strict` gate earlier in this file. Same failure class as the
# fetch-depth: 0 pin above. With no CLI on PATH that gate takes its blocking-gate skip
# branch, and a skip exits 0, so dropping this step would silently retire the CLI's
# strict plugin-tree validation while CI stayed green. Scope note: the PyYAML frontmatter
# and JSON manifest gates sit OUTSIDE that `command -v claude` branch and keep running
# regardless — only the strict plugin-tree layer is disarmed.
# Two lines are pinned because they fail independently: the installer fetches the binary,
# and the GITHUB_PATH append is what actually puts it on PATH for later steps — an
# install whose PATH export was dropped leaves the gate skipping just as surely. Matching
# these rather than the step names keeps a renamed step passing.
#
# Declaration note for every `devflow_ci_shard_has` pin below. These are NOT wording-only
# pins: each literal is machine-consumed — GitHub Actions executes these lines, and their
# absence DISARMS a suite gate rather than changing prose — so they sit inside the
# `# structural-pin-ok:` regime rather than under the new-wording-pin prohibition, and
# each carries its own declaration. Worth knowing why the declarations are documentary
# here: pin-corpus-lint.py's classifier only scans call sites of the helpers it
# recognizes, and these route through this file's own bespoke matcher, so the gate never
# sees them either to demand or to validate a marker. They are written for the reader,
# and so the sites are already declared if that extractor ever learns this helper.
# structural-pin-ok: cross-file-phase-contract -- the workflow line that installs the CLI is what arms the #671 gate; its removal makes that gate self-skip while CI stays green
assert_eq "#671 ci.yml: the shard job installs the claude CLI (arms the plugin-validate gate)" "yes" \
  "$(devflow_ci_shard_has 'claude[.]ai/install[.]sh')"
# The fuller shape, not a bare `GITHUB_PATH`: that token alone would be satisfied forever
# by any future unrelated append in this job, so the pin would outlive the thing it guards.
# structural-pin-ok: cross-file-phase-contract -- the PATH export is the half that makes the installed binary visible to later steps; dropped, the gate self-skips exactly as if nothing were installed
assert_eq "#671 ci.yml: the install exports the CLI onto PATH for later steps" "yes" \
  "$(devflow_ci_shard_has '[.]local/bin.*GITHUB_PATH')"
# Negative controls — mutation-checked, not assumed. Each arm copies ci.yml, comments out
# every UNCOMMENTED occurrence of one pinned line, and asserts the matcher flips to `no`,
# so a matcher that silently reverted to a comment-blind substring scan turns this block
# RED. (Already-commented occurrences are left alone: `fetch-depth: 0` also appears in
# prose, and prefixing a second `#` would misdescribe what the arm mutates.)
#
# Each arm carries its OWN positive control over the COPY, asserted before the mutation.
# That is not ceremony: `no` is the value the arm's assertion accepts, so a `cp` that
# silently produced an unusable copy would satisfy every arm while proving nothing. That
# is precisely and only what this control covers — the neighbouring failure modes are
# already owned elsewhere, and claiming them here would misdescribe it: a failed
# `mktemp -d` is fatal a few lines above, and a truncated MUTATED write is caught by the
# separate "the mutated copy is otherwise intact" witness assertion inside the loop. The
# fail-closed `unreadable` token in the matcher is the second, independent layer.
CI671_TMP="$(mktemp -d)"
[ -n "$CI671_TMP" ] && [ -d "$CI671_TMP" ] || { printf 'FATAL: mktemp -d failed for the #671 ci.yml pin controls\n' >&2; exit 1; }
for ci671_pat in 'fetch-depth: 0' 'curl -fsSL https://claude.ai/install.sh' 'echo "$HOME/.local/bin"'; do
  case "$ci671_pat" in
    'fetch-depth: 0')  ci671_probe='fetch-depth: 0' ;;
    *install.sh)       ci671_probe='claude[.]ai/install[.]sh' ;;
    *)                 ci671_probe='[.]local/bin.*GITHUB_PATH' ;;
  esac
  cp "$LIB/../.github/workflows/ci.yml" "$CI671_TMP/ci.yml"
  assert_eq "#671 ci.yml pin control ($ci671_pat): the UNMUTATED copy still yields yes" "yes" \
    "$(devflow_ci_shard_has "$ci671_probe" "$CI671_TMP/ci.yml")"
  awk -v target="$ci671_pat" '{ if (index($0, target) && $0 !~ /^[[:space:]]*#/) print "#" $0; else print }' \
    "$LIB/../.github/workflows/ci.yml" > "$CI671_TMP/ci.yml"
  ci671_mut_rc=$?
  assert_eq "#671 ci.yml pin control ($ci671_pat): the mutating awk itself succeeded" "0" "$ci671_mut_rc"
  # Integrity of the MUTATED copy, not just of the `cp` above: a truncated-but-nonempty
  # write would yield a genuine `no` and a vacuously green arm. An unrelated pinned line
  # must still be found in the mutated file, which is only true if the whole file landed.
  case "$ci671_pat" in
    'fetch-depth: 0') ci671_witness='claude[.]ai/install[.]sh' ;;
    *)                ci671_witness='fetch-depth: 0' ;;
  esac
  assert_eq "#671 ci.yml pin control ($ci671_pat): the mutated copy is otherwise intact" "yes" \
    "$(devflow_ci_shard_has "$ci671_witness" "$CI671_TMP/ci.yml")"
  assert_eq "#671 ci.yml pin is comment-aware: commenting out '$ci671_pat' flips the matcher to no" "no" \
    "$(devflow_ci_shard_has "$ci671_probe" "$CI671_TMP/ci.yml")"
done
# The matcher's OTHER limb — job scoping — needs its own control: the arms above drive
# only comment-skipping. Move the CLI's PATH export out of `shard:` into the `test:` job
# and the pin must stop seeing it, which exercises both the matcher's end-anchored
# `^  <job>:` job anchor and its `^  <key>:` next-top-level-key reset. (The awk on the next
# line is the FIXTURE generator, not the matcher — its own `/^  shard:/` and `/^  [a-z]/`
# patterns are its business and are correct as written; do not read them as the matcher's.)
# Without this, a matcher that scanned the whole file would stay green.
awk '/^  shard:/{ins=1} /^  [a-z]/{if (!/^  shard:/) ins=0}
     ins && index($0, "echo \"$HOME/.local/bin\""){next}
     {print}
     /^  test:/{print "    steps:"; print "      - run: echo \"$HOME/.local/bin\" >> \"$GITHUB_PATH\""}' \
  "$LIB/../.github/workflows/ci.yml" > "$CI671_TMP/ci.yml"
assert_eq "#671 ci.yml pin is job-scoped: the same line under the test: job does NOT satisfy it" "no" \
  "$(devflow_ci_shard_has '[.]local/bin.*GITHUB_PATH' "$CI671_TMP/ci.yml")"
# ...and its positive control: the line must still EXIST in that fixture, just outside the
# shard job. Without this the arm above would also pass if the mutation simply deleted the
# line, which would prove nothing about job scoping. (The fixture is only ever read
# line-wise by the matcher, never parsed as YAML, so its duplicate `steps:` key is inert.)
assert_eq "#671 ci.yml job-scoping control: the moved line is still present in the fixture" "yes" \
  "$(awk '/^[[:space:]]*#/{next} /\.local\/bin.*GITHUB_PATH/{f=1} END{print (f?"yes":"no")}' "$CI671_TMP/ci.yml")"
# Fail-closed controls for the matcher itself: an empty or absent file must NOT read as
# a clean `no`, or every negative control above could pass on a copy that never landed.
: > "$CI671_TMP/empty.yml"
assert_eq "#671 ci.yml matcher fails closed on an empty file (never a bare 'no')" "unreadable" \
  "$(devflow_ci_shard_has 'GITHUB_PATH' "$CI671_TMP/empty.yml")"
assert_eq "#671 ci.yml matcher fails closed on an absent file (never a bare 'no')" "unreadable" \
  "$(devflow_ci_shard_has 'GITHUB_PATH' "$CI671_TMP/no-such-file.yml")"
# The awk-failure limb needs its own arm too — it guards the guard-class-2 shape, so
# dropping or reordering it must not stay green. A malformed ERE makes awk exit nonzero
# without touching PATH (a PATH-shadowing fixture would be the heavier, flakier way).
assert_eq "#671 ci.yml matcher fails closed when awk itself errors (malformed ERE)" "awk-failed" \
  "$(devflow_ci_shard_has '[' "$LIB/../.github/workflows/ci.yml" 2>/dev/null)"
# The THIRD token needs its own arm, or the `case`'s `*)` branch can be deleted — or
# collapsed into `no` — with this block still green, while the matcher's comment claims
# the token set is exhaustive rather than merely the two shapes that were foreseen. The
# state it names is an awk that exits 0 while printing nothing; the real program cannot
# produce it (its END block always prints), so it is driven with a PATH shim rather than
# left as an unreachable claim. The shim is confined to the one command substitution.
mkdir -p "$CI671_TMP/bin"
printf '%s\n' '#!/bin/sh' 'exit 0' > "$CI671_TMP/bin/awk"
chmod +x "$CI671_TMP/bin/awk"
assert_eq "#671 ci.yml matcher fails closed when awk exits 0 but prints nothing" "unexpected-output" \
  "$(PATH="$CI671_TMP/bin:$PATH"; devflow_ci_shard_has 'GITHUB_PATH' "$LIB/../.github/workflows/ci.yml")"
# ...and its positive control on the same fixture and pattern: with the shim off the PATH,
# the same call must yield `yes`. Without it the arm above would also pass if the file or
# the pattern were simply wrong, which would prove nothing about the token.
assert_eq "#671 ci.yml matcher unexpected-output control: the same call without the shim yields yes" "yes" \
  "$(devflow_ci_shard_has 'GITHUB_PATH' "$LIB/../.github/workflows/ci.yml")"
rm -rf "$CI671_TMP"
# The pinned CLI version. The VERIFY half fails closed on an empty pin on its own
# (scripts/assert-cli-version.sh exits 2), but the INSTALL half does not: `bash -s ""`
# silently takes whatever the installer defaults to. So a dropped or renamed env: key
# would still leave an unpinned CLI installed, and this pin is what catches its removal.
# structural-pin-ok: cross-file-phase-contract -- the env: key is the single source both the install and verify halves read; dropped or emptied, the install silently takes the installer's default version
assert_eq "#671 ci.yml: the CLI version literal is declared in the shard job" "yes" \
  "$(devflow_ci_shard_has 'CLAUDE_CLI_VERSION:[[:space:]]*[0-9]')"
# ...and ci.yml must actually CALL the extracted assertion. Pinning only the helper's
# existence would leave a workflow that stopped invoking it entirely still green.
# structural-pin-ok: cross-file-phase-contract -- pins that the workflow still invokes the extracted verifier; a helper that exists but is never called verifies nothing
assert_eq "#671 ci.yml: the verify step calls the extracted version assertion" "yes" \
  "$(devflow_ci_shard_has 'assert-cli-version[.]sh')"
# ...and the INSTALL half must actually be passed the pin. Matching only the installer
# URL leaves `bash -s "$CLAUDE_CLI_VERSION"` free to be dropped, or replaced with a
# hardcoded literal, with every assertion still green — the unguarded half of the pair.
# structural-pin-ok: cross-file-phase-contract -- pins that the pin reaches the installer; without it the version argument can be dropped or hardcoded with every other assertion green
assert_eq "#671 ci.yml: the installer is passed the pinned version" "yes" \
  "$(devflow_ci_shard_has 'bash -s "[$]CLAUDE_CLI_VERSION"')"
# The retry wrapper must stay in the invocation path; without it the loop, the backoff
# and the terminal exit are all bypassed while the install still appears to run.
# structural-pin-ok: cross-file-phase-contract -- pins that the install still routes through the extracted retry wrapper; bypassed, the retry/backoff/terminal-exit arms drive code the workflow no longer runs
assert_eq "#671 ci.yml: the install goes through the retry wrapper" "yes" \
  "$(devflow_ci_shard_has 'retry-with-backoff[.]sh')"
# ...and pipefail inside the command string, which was the one machine-consumed token of
# that statement asserted by nothing but a comment. Dropping it restores precisely the
# failure this whole gate exists to remove: a failed download feeds bash an empty script,
# the install step exits 0, and the CLI is absent while CI stays green — a silent disarm.
# Note this pin cannot be satisfied by the neighbouring comment that discusses the option,
# because the matcher skips comment lines; it matches only the live command string.
# structural-pin-ok: cross-file-phase-contract -- pipefail is what turns a failed download into a failed step; without it the install reports success and the #671 gate silently self-skips again
assert_eq "#671 ci.yml: the install command string sets pipefail" "yes" \
  "$(devflow_ci_shard_has 'set -o pipefail')"
#
# ── scripts/assert-cli-version.sh: every arm of the extracted version check ──
# The decision this helper makes used to be inline workflow shell, which no assertion
# could drive: the entire verify step could be deleted with the suite still green.
# Each arm asserts the EXIT CODE, which is the helper's contract, and the empty-pin arm
# is distinguished from the mismatch arm so a collapsed `exit 1` cannot pass as either.
ACV="$LIB/../scripts/assert-cli-version.sh"
devflow_acv_rc() { bash "$ACV" "$1" "$2" >/dev/null 2>&1; echo $?; }
assert_eq "#671 assert-cli-version: exact match on the version field exits 0" "0" \
  "$(devflow_acv_rc '2.1.212' '2.1.212 (Claude Code)')"
assert_eq "#671 assert-cli-version: a longer version sharing the prefix is REJECTED (2.1.2120 vs 2.1.212)" "1" \
  "$(devflow_acv_rc '2.1.212' '2.1.2120 (Claude Code)')"
assert_eq "#671 assert-cli-version: a different version is rejected" "1" \
  "$(devflow_acv_rc '2.1.212' '2.0.9 (Claude Code)')"
# The empty pin fails CLOSED with its own distinct code — never 0, and never silently
# folded into the mismatch arm, because an empty pin is a broken workflow config rather
# than a wrong CLI, and the two want different remedies.
assert_eq "#671 assert-cli-version: an EMPTY pin fails closed with its own exit code (2)" "2" \
  "$(devflow_acv_rc '' '2.1.999 (Claude Code)')"
assert_eq "#671 assert-cli-version: an empty pin never exits 0, whatever the version string" "2" \
  "$(devflow_acv_rc '' '')"
# Empty ACTUAL output (the CLI absent or printing nothing) must not satisfy a real pin.
assert_eq "#671 assert-cli-version: empty version output does not satisfy a real pin" "1" \
  "$(devflow_acv_rc '2.1.212' '')"
assert_eq "#671 assert-cli-version: the empty-pin arm names the unset variable" "yes" \
  "$(bash "$ACV" '' 'x' 2>&1 | grep -q 'CLAUDE_CLI_VERSION is unset or empty' && echo yes || echo no)"
assert_eq "#671 assert-cli-version: the mismatch arm names both expected and observed" "yes" \
  "$(bash "$ACV" '2.1.212' '2.0.9 (Claude Code)' 2>&1 | grep -q 'expected claude 2.1.212 on PATH, got: 2.0.9' && echo yes || echo no)"
# Both message arms above merge stderr into stdout (2>&1) to READ the text, which cannot
# distinguish a message written to stderr from one written to stdout. The helper emits both
# ::error:: lines with an explicit >&2, so assert the ROUTING too: with stderr discarded
# there must be nothing left on stdout. Without these, dropping the >&2 keeps them green.
assert_eq "#671 assert-cli-version: the mismatch ::error:: goes to STDERR, not stdout" "" \
  "$(bash "$ACV" '2.1.212' '2.0.9 (Claude Code)' 2>/dev/null)"
assert_eq "#671 assert-cli-version: the empty-pin ::error:: goes to STDERR, not stdout" "" \
  "$(bash "$ACV" '' 'x' 2>/dev/null)"
# `got="${actual%% *}"` is a parser over externally-produced output (`claude --version`),
# so it gets the boundary rows CLAUDE.md's best-effort-parser rule asks for. Both currently
# fail CLOSED; the arms exist so a future "trim harder / be lenient" edit cannot silently
# turn either into a false PASS.
assert_eq "#671 assert-cli-version: LEADING WHITESPACE does not satisfy the pin (fails closed)" "1" \
  "$(devflow_acv_rc '2.1.212' ' 2.1.212 (Claude Code)')"
assert_eq "#671 assert-cli-version: MULTI-LINE version output does not satisfy the pin (fails closed)" "1" \
  "$(devflow_acv_rc '2.1.212' 'warning: something
2.1.212 (Claude Code)')"
#
# ── scripts/retry-with-backoff.sh: every arm of the extracted install retry ──
# Extracted from ci.yml's install step, where nothing drove the retry arms, the backoff
# schedule or the terminal exit.
#
# Wall-clock discipline, since these arms sit on a REQUIRED check: every arm passes base
# delay 0, which exercises the retry path without sleeping at all. The ONE exception is
# the schedule arm below, which has to pass a nonzero base to observe growth — it uses
# the smallest base that does (1 → 1s, 3s), not a larger one. Keep new arms at 0 unless
# they genuinely assert the schedule, and if a second schedule arm is ever needed, add a
# no-sleep seam to the helper rather than paying the seconds twice.
RWB="$LIB/../scripts/retry-with-backoff.sh"
RWB_TMP="$(mktemp -d)"
[ -n "$RWB_TMP" ] && [ -d "$RWB_TMP" ] || { printf 'FATAL: mktemp -d failed for the retry-with-backoff arms\n' >&2; exit 1; }
devflow_rwb_rc() { bash "$RWB" "$@" >/dev/null 2>&1; echo $?; }
assert_eq "#671 retry: a command that succeeds first time exits 0" "0" \
  "$(devflow_rwb_rc 3 0 'true')"
assert_eq "#671 retry: a command that never succeeds exhausts and exits 1" "1" \
  "$(devflow_rwb_rc 3 0 'false')"
# The success-after-failure path: the counter file makes the attempt count observable,
# so this asserts the retry actually retried rather than merely returning 0.
printf '0' > "$RWB_TMP/n"
RWB_CMD="n=\$(cat '$RWB_TMP/n'); n=\$((n+1)); printf '%s' \"\$n\" > '$RWB_TMP/n'; [ \"\$n\" -ge 3 ]"
assert_eq "#671 retry: a command that succeeds on the third attempt exits 0" "0" \
  "$(devflow_rwb_rc 3 0 "$RWB_CMD")"
assert_eq "#671 retry: ...and it genuinely took three attempts (not an early exit)" "3" \
  "$(cat "$RWB_TMP/n")"
# Exhaustion is decided by an explicit flag, not by comparing against a hand-transcribed
# terminal literal — so WIDENING the attempt budget must still fail closed. A literal
# coupled to the loop bound would silently stop firing here and report success.
printf '0' > "$RWB_TMP/n"
assert_eq "#671 retry: a widened attempt budget still fails closed when every attempt fails" "1" \
  "$(devflow_rwb_rc 7 0 'false')"
assert_eq "#671 retry: the exhaustion message names the attempt count" "yes" \
  "$(bash "$RWB" 2 0 'false' 2>&1 | grep -q 'failed after 2 attempt' && echo yes || echo no)"
# ...and the LAST OBSERVED EXIT CODE. The helper's own exit stays a flat 1 (so it never
# collides with the 2 that means "unusable arguments"), which makes the message the only
# place a deterministic failure is distinguishable from a transient one — a mistyped
# version pinning a 404 retries three times and must not report the same text as a
# network flake. `exit 7` is chosen because it is not 1: a message that merely echoed the
# helper's own exit would still pass against 1.
assert_eq "#671 retry: the exhaustion message names the LAST observed exit code" "yes" \
  "$(bash "$RWB" 2 0 'exit 7' 2>&1 | grep -q 'last exit 7' && echo yes || echo no)"
# Backoff growth is asserted from the emitted schedule rather than by timing the run.
# Base 1 (not 2) is deliberate: it is the smallest base that still shows the x3 growth,
# and this is the one arm in the block that sleeps for real — see the note above.
RWB_SCHED="$(bash "$RWB" 3 1 'false' 2>&1 | grep -o 'retrying in [0-9]*s' | tr '\n' ' ')"
assert_eq "#671 retry: the backoff grows exponentially (1s then 3s) and emits no dead third wait" \
  "retrying in 1s retrying in 3s " "$RWB_SCHED"
# The retried command is run by `bash -c` INSIDE the helper, so a single-quoted command
# string (the shape ci.yml passes) has its variables expanded there, per attempt, from the
# caller's exported environment. ci.yml depends on exactly this: `bash -s "$CLAUDE_CLI_VERSION"`
# is single-quoted in the workflow, so nothing expands it until the helper runs it. A
# hardening edit to `env -i bash -c` or `--noprofile` would silently install the
# installer's DEFAULT version while every other arm here stayed green.
export DEVFLOW_RWB_PROBE=inherited
assert_eq "#671 retry: the retried command inherits the caller's exported environment" "0" \
  "$(devflow_rwb_rc 1 0 '[ "$DEVFLOW_RWB_PROBE" = inherited ]')"
# ...with its negative control on the same fixture, so the arm above cannot pass by the
# command succeeding for some unrelated reason: with the variable gone the SAME command
# must fail. Without this, a command string that never expanded anything would still be
# green.
unset DEVFLOW_RWB_PROBE
assert_eq "#671 retry: ...and the control — with the variable unset the same command fails" "1" \
  "$(devflow_rwb_rc 1 0 '[ "${DEVFLOW_RWB_PROBE-}" = inherited ]')"
# Unusable arguments fail closed with their own code rather than retrying nothing.
assert_eq "#671 retry: a non-numeric attempt count fails closed (exit 2)" "2" \
  "$(devflow_rwb_rc x 0 'true')"
assert_eq "#671 retry: a zero attempt count fails closed (exit 2, never a silent no-op success)" "2" \
  "$(devflow_rwb_rc 0 0 'true')"
# The BASE DELAY validation arm needs driving too — it is the one exit-2 guard whose
# deletion stayed green. Without it `retry-with-backoff.sh 3 x 'false'` reaches
# `[ "$delay" -gt 0 ]` with delay=x, which emits a bash integer-expression error per
# attempt and proceeds with broken backoff instead of failing closed.
assert_eq "#671 retry: a non-numeric BASE DELAY fails closed (exit 2)" "2" \
  "$(devflow_rwb_rc 3 x 'true')"
# ...attributed to the base-delay guard specifically. Three other guards also exit 2, so
# a bare exit-code assertion cannot tell which one rejected this fixture — and the
# fixture is otherwise valid (attempts 3, command 'true'), which the exit-0 arm at the
# top of this block already establishes.
assert_eq "#671 retry: ...and the rejection is attributed to the base-delay guard" "yes" \
  "$(bash "$RWB" 3 x 'true' 2>&1 | grep -q "base delay must be a non-negative integer, got: 'x'" && echo yes || echo no)"
assert_eq "#671 retry: an empty command fails closed (exit 2)" "2" \
  "$(devflow_rwb_rc 3 0 '')"
rm -rf "$RWB_TMP"
unset -f devflow_rwb_rc
unset -f devflow_acv_rc devflow_ci_shard_has devflow_wf_job_has
assert_eq "#456 ci.yml: shipped lib/test orchestrators are added to shellcheck scope" "yes" \
  "$(grep -qF 'lib/test/module-harness.sh lib/test/run-module.sh lib/test/summary.sh' \
       "$LIB/../.github/workflows/ci.yml" && echo yes || echo no)"
#
# ── #745 no UNESCAPED backtick may appear in an assertion label ──
# The defect this issue fixed: a markdown backtick inside a double-quoted assert label is
# command substitution, so bash EXECUTES the label's own prose (`--issue notanint` ran
# `--issue`; `must merge after` ran `must`) and the assertion's name renders with the span
# deleted. The CI lint does NOT gate this class — ShellCheck reports backticks as SC2006,
# which is `style` severity and therefore filtered out by the `--severity=warning` every
# lint step uses. Only 2 of the 8 live instances were caught at all, and only incidentally,
# as SC2215/SC1010 because their contents happened to parse as a flag or a keyword. So the
# class needs its own guard: scan every assertion label for an UNESCAPED backtick. An
# escaped \` is inert (bash does not substitute it) and stays legal, which is what the many
# existing \`…\` labels use.
assert_eq "#745 no assertion label carries an unescaped backtick (bash would execute it)" "" \
  "$(python3 - "$SELF_SRC" <<'PY745'
import re, sys
# Three scoping requirements, each a false-negative class the first draft had:
#   - the call need not START a line (`[ -d x ] && assert_eq "..."`, `);  assert_eq "..."`,
#     a `case` arm, a `VAR=v assert_eq "..."`), so match at any command-start position;
#   - the label may sit on a CONTINUATION line (an assertion head then the label),
#     so scan the whole file text with DOTALL rather than line by line;
#   - a doubled backslash before a backtick is a LITERAL backslash plus a LIVE backtick, so
#     a plain `(?<!\\)` lookbehind is unsound — walk the label consuming `\\`/`\X` pairs
#     instead, and flag the first backtick that survives.
text = open(sys.argv[1], encoding="utf-8").read()
CALL = re.compile(
    r'(?:^|[;&|(){}]|&&|\|\||\s)\s*(?:assert_\w+|devflow_module_pin\w*)'
    r'(?:\s*\\\s*\n)?\s+"((?:[^"\\]|\\.)*)"', re.M)
def live_backtick(label):
    i = 0
    while i < len(label):
        if label[i] == "\\":
            i += 2          # consume the escape pair: \\ or \` or \" ...
            continue
        if label[i] == "`":
            return True     # reached unescaped -> bash substitutes it
        i += 1
    return False
out = []
for m in CALL.finditer(text):
    if live_backtick(m.group(1)):
        out.append(str(text.count("\n", 0, m.start(1)) + 1))
print(" ".join(sorted(set(out), key=int)))
PY745
)"
# ── #745 ci.yml lints lib/test/run.sh, with the flag AND the pin that make it possible ──
# The carve-out guard below proves run.sh is NAMED to a shellcheck invocation. It cannot see
# the two properties that make that invocation actually survive on a 16 GB ubuntu-latest
# runner, so they are pinned here against their re-introduced failure:
#   - dropping --extended-analysis=false restores ShellCheck's ~15 GB dataflow pass and the
#     runner is evicted mid-analysis (6/6 runs, PR #734);
#   - dropping the >= 0.10.0 pin falls back to the image's 0.9.0, where the flag ERRORS.
CI745="$LIB/../.github/workflows/ci.yml"
# The pinned version must satisfy the >= 0.10.0 floor --extended-analysis needs; a pin at
# 0.9.x would install a binary that rejects the flag, so the version itself is the contract.
assert_eq "#745 ci.yml: every pinned SHELLCHECK_VERSION is >= 0.10.0" "yes" \
  "$(python3 - "$CI745" <<'PY745'
import re, sys
# ALL matches, and the MINIMUM must clear the floor: a first-match read let a comment
# mentioning any version shadow a genuinely downgraded `env:` key. Absent = "no" (a floor
# nothing declares is unestablished, not satisfied).
vs = [(int(a), int(b)) for a, b, _c in
      re.findall(r"SHELLCHECK_VERSION:\s*v?(\d+)\.(\d+)\.(\d+)",
                 open(sys.argv[1], encoding="utf-8").read())]
print("yes" if vs and min(vs) >= (0, 10) else "no")
PY745
)"
# The floor above governs the value; this pin governs the thing the value actually selects.
# Without it the download URL could hardcode a version (or drift to 0.9.x) while the env key
# still read v0.11.0 — every other assertion in this block would pass and CI would
# install 0.9.0.
# AC2: the job stays on a standard runner and never tolerates a failing lint step.
# Both scans are scoped to the `lint:` job, and both anchors are load-bearing:
#   - `runs-on: ubuntu-latest[[:space:]]*$` is ANCHORED. Unanchored, `ubuntu-latest-16-cores`
#     contains the literal and satisfies the very assertion whose contract is "no larger
#     runner" — the AC2 regression could not be caught by its own guard.
#   - the job-scope reset accepts ANY job-name character class, not just lowercase: `lint:`
#     is currently the last job, so a later appended `Notify:`/`test2:` would otherwise never
#     reset the scope and its content would leak into both scans.
#   - the escape-hatch scan matches the `key:` FORM (a comment line starts with `#`, so a
#     `continue-on-error` mentioned in prose can never be counted as a hatch — the #370
#     count-inflation trap; the app-token blocks above use the same guard). It deliberately
#     does NOT match on the VALUE `true`: Actions also accepts `"true"`, `True`, and a
#     `${{ … }}` expression, each of which tolerates a failing lint step, so a value match
#     would be the fail-open direction. Only an explicit `false` — which tolerates nothing —
#     is excluded.
assert_eq "#745 ci.yml: the lint job runs on standard ubuntu-latest (no larger runner)" "yes" \
  "$(awk '/^  lint:/{inlint=1; next} /^  [A-Za-z0-9_-]+:/{inlint=0} inlint && /runs-on: ubuntu-latest[[:space:]]*$/{f=1} END{print (f?"yes":"no")}' "$CI745")"
assert_eq "#745 ci.yml: the lint job carries no continue-on-error escape hatch" "0" \
  "$(awk '/^  lint:/{inlint=1; next} /^  [A-Za-z0-9_-]+:/{inlint=0} inlint && /^[[:space:]]*continue-on-error:/ && $0 !~ /:[[:space:]]*false[[:space:]]*$/{n++} END{print n+0}' "$CI745")"
#
# ── #717/#745 lib/test lint carve-out guard (lib/test/lint-carveout-guard.py) ──
# The guard reads ci.yml, derives which lib/test/**/*.sh files CI lints, and fails
# closed / names the offending path when a tracked lib/test file is neither CI-linted
# nor under the exempt prefix lib/test/fixtures/. These assertions drive it over the
# REAL ci.yml + tree AND a matrix of synthetic ci.yml fixtures (the CLAUDE.md
# best-effort-parser discipline applied to a workflow-YAML input).
LCG_PY="$LIB/test/lint-carveout-guard.py"
LCG_CI="$CI745"   # alias of $CI745 so the ci.yml path literal is written once
# _lcg CI_FILE FILES_FILE -> "<exit>|<verdict-word>" (OK / FAIL); verdict = text up to first ':'
_lcg() {
  local out ec
  out="$(python3 "$LCG_PY" --ci-file "$1" --files-file "$2" 2>/dev/null)"; ec=$?
  printf '%s|%s' "$ec" "${out%%:*}"
}
# Real-tree pass: the guard passes over the real ci.yml + real git ls-files tree.
assert_eq "#717 guard: passes over the real ci.yml + tracked tree" "0|OK" \
  "$(out="$(cd "$LIB/.." && python3 "$LCG_PY" --repo-root . 2>/dev/null)"; ec=$?; printf '%s|%s' "$ec" "${out%%:*}")"
# lib/test/run.sh itself is present in the real ci.yml's CI-linted set (AC): check the
# real ci.yml against a files list of exactly run.sh.
LCG_ONLY_RUNSH="$(probe_tmp '#717 guard: run.sh-only files list')"
printf '%s\n' 'lib/test/run.sh' > "$LCG_ONLY_RUNSH"
assert_eq "#717 guard: lib/test/run.sh is in the real ci.yml CI-linted set" "0|OK" \
  "$(_lcg "$LCG_CI" "$LCG_ONLY_RUNSH")"
rm -f "$LCG_ONLY_RUNSH"
# Synthetic well-formed ci.yml: glob (exact exclusion), explicit list, run.sh job.
LCG_FX_OK="$(probe_tmp '#717 guard: well-formed ci.yml fixture')"
cat > "$LCG_FX_OK" <<'YAML'
name: CI
jobs:
  lint:
    runs-on: ubuntu-latest
    steps:
      - run: |
          git ls-files '*.sh' | grep -v '^lib/test/' \
            | xargs -r shellcheck --severity=warning -e SC1091
          shellcheck --severity=warning -e SC1091 \
            lib/test/alpha.sh lib/test/modules/beta.sh
  runsh:
    runs-on: ubuntu-latest
    steps:
      - run: shellcheck --severity=warning -e SC1091 lib/test/run.sh
YAML
# Synthetic ci.yml whose glob exclusion is NARROWED (not the exact recognized form).
LCG_FX_GLOB="$(probe_tmp '#717 guard: narrowed-glob ci.yml fixture')"
cat > "$LCG_FX_GLOB" <<'YAML'
name: CI
jobs:
  lint:
    steps:
      - run: |
          git ls-files '*.sh' | grep -v '^lib/test/fixtures/' | xargs -r shellcheck --severity=warning -e SC1091
          shellcheck --severity=warning -e SC1091 lib/test/alpha.sh
YAML
# Synthetic ci.yml naming a lib/test path ONLY in a comment (not a shellcheck arg).
LCG_FX_CMT="$(probe_tmp '#717 guard: comment-only-path ci.yml fixture')"
cat > "$LCG_FX_CMT" <<'YAML'
name: CI
jobs:
  lint:
    steps:
      - run: |
          git ls-files '*.sh' | grep -v '^lib/test/' | xargs -r shellcheck --severity=warning -e SC1091
          # lib/test/delta.sh is linted elsewhere (a comment, never coverage)
          shellcheck --severity=warning -e SC1091 lib/test/alpha.sh
YAML
# Synthetic ci.yml with NO shellcheck invocation anywhere.
LCG_FX_NOSC="$(probe_tmp '#717 guard: no-shellcheck ci.yml fixture')"
cat > "$LCG_FX_NOSC" <<'YAML'
name: CI
jobs:
  build:
    steps:
      - run: echo "no shellcheck here"
YAML
LCG_FX_BAD="$(probe_tmp '#717 guard: non-YAML ci.yml fixture')"
printf 'a: b: c\n' > "$LCG_FX_BAD"
LCG_FX_EMPTY="$(probe_tmp '#717 guard: empty ci.yml fixture')"
: > "$LCG_FX_EMPTY"
# File lists (synthetic tracked-file populations).
LCG_L_OK="$(probe_tmp '#717 guard: covered files')"
printf '%s\n' 'lib/test/alpha.sh' 'lib/test/modules/beta.sh' 'lib/test/run.sh' 'lib/test/fixtures/malformed.sh' > "$LCG_L_OK"
LCG_L_MISS="$(probe_tmp '#717 guard: files with one uncovered')"
printf '%s\n' 'lib/test/alpha.sh' 'lib/test/modules/beta.sh' 'lib/test/run.sh' 'lib/test/gamma.sh' > "$LCG_L_MISS"
LCG_L_FX="$(probe_tmp '#717 guard: files with a new fixture')"
printf '%s\n' 'lib/test/alpha.sh' 'lib/test/modules/beta.sh' 'lib/test/run.sh' 'lib/test/fixtures/new-adversarial.sh' > "$LCG_L_FX"
LCG_L_CMT="$(probe_tmp '#717 guard: files incl. comment-only path')"
printf '%s\n' 'lib/test/alpha.sh' 'lib/test/delta.sh' > "$LCG_L_CMT"
LCG_L_ALPHA="$(probe_tmp '#717 guard: alpha-only files')"
printf '%s\n' 'lib/test/alpha.sh' > "$LCG_L_ALPHA"
# Case a — well-formed, every non-fixture file covered → PASS.
assert_eq "#717 guard: well-formed ci.yml covering every non-fixture file passes" "0|OK" \
  "$(_lcg "$LCG_FX_OK" "$LCG_L_OK")"
# Case b — one file named nowhere → FAIL (the planted-defect positive control).
assert_eq "#717 guard: a missing lib/test file fails the guard (planted-defect control)" "1|FAIL" \
  "$(_lcg "$LCG_FX_OK" "$LCG_L_MISS")"
assert_eq "#717 guard: the failure names the exact offending path" "yes" \
  "$(python3 "$LCG_PY" --ci-file "$LCG_FX_OK" --files-file "$LCG_L_MISS" 2>/dev/null | grep -qF 'lib/test/gamma.sh' && echo yes || echo no)"
# Case c — a new lib/test/fixtures/ file named nowhere → PASS (exempt prefix works).
assert_eq "#717 guard: a new lib/test/fixtures/ file is exempt and passes" "0|OK" \
  "$(_lcg "$LCG_FX_OK" "$LCG_L_FX")"
# Case d — no shellcheck invocation at all → fail closed naming ci.yml.
assert_eq "#717 guard: absent shellcheck invocations fail closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_NOSC" "$LCG_L_OK")"
assert_eq "#717 guard: the absent-invocation failure names .github/workflows/ci.yml" "yes" \
  "$(python3 "$LCG_PY" --ci-file "$LCG_FX_NOSC" --files-file "$LCG_L_OK" 2>/dev/null | grep -qF '.github/workflows/ci.yml' && echo yes || echo no)"
# Case e — empty file → fail closed.
assert_eq "#717 guard: an empty ci.yml fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_EMPTY" "$LCG_L_OK")"
# Case f — not valid YAML → fail closed naming ci.yml.
assert_eq "#717 guard: a non-YAML ci.yml fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_BAD" "$LCG_L_OK")"
# Case g — a path named ONLY in a comment is not counted as covered → FAIL.
assert_eq "#717 guard: a lib/test path named only in a comment is not covered" "1|FAIL" \
  "$(_lcg "$LCG_FX_CMT" "$LCG_L_CMT")"
# Case h — the glob's lib/test exclusion narrowed from the exact form → fail closed.
assert_eq "#717 guard: a narrowed glob exclusion fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_GLOB" "$LCG_L_ALPHA")"
# Case i — the SAME narrowed exclusion but written across POSIX trailing-pipe
# continuations (bare `|` line-ends, no backslash) instead of a backslash-joined line.
# Left unfolded this pipeline spans several physical lines and escapes the single-line
# glob search entirely (fail-OPEN); the operator-continuation fold makes it fail closed
# like Case h regardless of pipe layout (issue #717 review — corroborated fail-open gap).
LCG_FX_PIPE="$(probe_tmp '#717 guard: trailing-pipe narrowed-glob ci.yml fixture')"
cat > "$LCG_FX_PIPE" <<'YAML'
name: CI
jobs:
  lint:
    steps:
      - run: |
          git ls-files '*.sh' |
            grep -v '^lib/test/fixtures/' |
            xargs -r shellcheck --severity=warning -e SC1091
          shellcheck --severity=warning -e SC1091 lib/test/alpha.sh
YAML
assert_eq "#717 guard: a narrowed exclusion across trailing-pipe continuations fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_PIPE" "$LCG_L_ALPHA")"
# Case j — the glob's `grep -v` exclusion removed ENTIRELY (a different way to regress it
# than narrowing): the glob line reaches shellcheck with no exclusion at all, so the
# `not m` predicate in _glob_exclusion_ok fires → fail closed.
LCG_FX_NOGREP="$(probe_tmp '#717 guard: no-grep-exclusion ci.yml fixture')"
cat > "$LCG_FX_NOGREP" <<'YAML'
name: CI
jobs:
  lint:
    steps:
      - run: |
          git ls-files '*.sh' | xargs -r shellcheck --severity=warning -e SC1091
          shellcheck --severity=warning -e SC1091 lib/test/alpha.sh
YAML
assert_eq "#717 guard: a glob pipeline with no grep exclusion at all fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_NOGREP" "$LCG_L_ALPHA")"
# Case k — valid YAML mapping but NO `jobs:` key (a ci.yml restructure that moves lint
# out of jobs:) → the distinct no-jobs-mapping fail-closed arm fires.
LCG_FX_NOJOBS="$(probe_tmp '#717 guard: no-jobs-mapping ci.yml fixture')"
printf 'name: CI\n' > "$LCG_FX_NOJOBS"
assert_eq "#717 guard: a ci.yml with no jobs: mapping fails closed" "1|FAIL" \
  "$(_lcg "$LCG_FX_NOJOBS" "$LCG_L_ALPHA")"
rm -f "$LCG_FX_OK" "$LCG_FX_GLOB" "$LCG_FX_CMT" "$LCG_FX_NOSC" "$LCG_FX_BAD" "$LCG_FX_EMPTY" \
      "$LCG_FX_PIPE" "$LCG_FX_NOGREP" "$LCG_FX_NOJOBS" \
      "$LCG_L_OK" "$LCG_L_MISS" "$LCG_L_FX" "$LCG_L_CMT" "$LCG_L_ALPHA"
#
# review-and-fix: verification_evidence gains a skipped_checks list, and the not-a-clean-pass
# clause stays repo-agnostic (names no lib/test/run.sh / lib + python tests / --flag).
RAF456="$MAXI_BUNDLE"   # #530: root+references bundle
assert_eq "#456 review-and-fix: verification_evidence documents a skipped_checks list" "yes" \
  "$(grep -qF 'skipped_checks' "$RAF456" && echo yes || echo no)"
assert_eq "#456 review-and-fix: the not-a-clean-pass clause is present and repo-agnostic" "yes" \
  "$(grep -qF 'not reported by the loop as a clean pass' "$RAF456" \
       && ! grep -F 'not reported by the loop as a clean pass' "$RAF456" | grep -qE 'run\.sh|lib/test|lib \+ python' \
     && echo yes || echo no)"
# ...and the clause names a CONCRETE (but still runner-agnostic) extraction mechanism — the
# runner's own reported output — so an implementer is never left inferring skips from the
# exit code, which a skipped check deliberately does not change (round 3).
assert_eq "#456 review-and-fix: the skip-detection clause names its extraction mechanism (the runner's own reported output) and stays repo-agnostic" "yes" \
  "$(grep -qF "the runner's own reported output" "$RAF456" \
       && ! grep -F "the runner's own reported output" "$RAF456" | grep -qE 'run\.sh|lib/test|lib \+ python' \
     && echo yes || echo no)"

# ────────────────────────────────────────────────────────────────────────────
echo "#466 match-lint-adjudications.py — stale-prose FP adjudication carry-forward"
# ────────────────────────────────────────────────────────────────────────────
# Drive the real CLI (stdin JSON {rows, comments} -> demotion-map JSON) over the
# mla-* named scenarios with inline JSON fixtures. The driver builds inputs, runs
# the helper via subprocess, and emits one TAB-separated `name<TAB>expected<TAB>actual`
# line per named check; run.sh feeds each to assert_eq so every mla-* assertion lands
# in the suite tally. TSV/base64 fixtures live in the driver (python) so tab and
# base64 handling stay byte-exact.
MLA_HELPER_PATH="$LIB/../scripts/match-lint-adjudications.py"
MLA_CFG_FILE="$(mktemp)"
# allowed_bots carries a User-type login ("trusted-human") to exercise the
# additional-author-allowance arm; a Bot-type author is trusted regardless.
printf '{"prflow":{"allowed_bots":"claude,devflow-autopilot,trusted-human"}}' > "$MLA_CFG_FILE"
MLA_DRIVER="$(mktemp)"
cat > "$MLA_DRIVER" <<'PYEOF'
import base64, json, os, subprocess, sys

HELPER = os.environ["MLA_HELPER"]
CFG = os.environ["MLA_CFG"]
MARKER = "<!-- prflow:review-progress run=999-1 -->"
S = "<!-- prflow:lint-adjudications-start -->"
E = "<!-- prflow:lint-adjudications-end -->"
# The superseded spellings (issue #1003). The rename rewrites no existing progress
# comment, so both are honored -- and every sentinel count, search and offset is
# computed over their UNION, never per spelling.
MARKER_OLD = "<!-- devflow:review-progress run=999-1 -->"
S_OLD = "<!-- devflow:lint-adjudications-start -->"
E_OLD = "<!-- devflow:lint-adjudications-end -->"

def tsv(verdict, rule, path, line, detail):
    return f"{verdict}\t{rule}\t{path}\t{line}\t{detail}"

def payload(row_tsv):
    return "<!-- prflow:lint-fp-adjudicated " + base64.b64encode(row_tsv.encode()).decode() + " -->"


def payload_old(row_tsv):
    return "<!-- devflow:lint-fp-adjudicated " + base64.b64encode(row_tsv.encode()).decode() + " -->"

def adj_comment(author, atype, row_tsv, marker=MARKER, with_section=True):
    inner = payload(row_tsv)
    if with_section:
        body = f"{marker}\n# report\n{S}\n{inner}\n{E}\n"
    else:  # marker present but no sentinel section — payload sits loose in the body
        body = f"{marker}\n# report\n> evidence quote: {inner}\n"
    return {"author": author, "author_type": atype, "body": body}

def run(rows, comments):
    proc = subprocess.run(
        [sys.executable, HELPER, "--config", CFG],
        input=json.dumps({"rows": rows, "comments": comments}),
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
    )
    out = json.loads(proc.stdout) if proc.stdout.strip() else {}
    return proc.returncode, out, proc.stderr

checks = []
def chk(name, expected, actual):
    checks.append((name, str(expected), str(actual)))

ROW = tsv("STALE", "count-locked", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 42, "claims 5 skills")
CBOT = adj_comment("devflow-reviewer[bot]", "Bot", ROW)

# mla-match: exact (rule,path,detail) payload, Bot author -> demoted, run_key surfaced
rc, out, _ = run([ROW], [CBOT])
chk("mla-match rc0", "0", rc)
chk("mla-match demoted len 1", "1", len(out["demoted"]))
chk("mla-match row_index 0", "0", out["demoted"][0]["row_index"])
chk("mla-match run_key surfaced", "999-1", out["demoted"][0]["run_key"])

# mla-detail-drift: one-char detail change -> not demoted
_, out, _ = run([tsv("STALE", "count-locked", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 42, "claims 6 skills")], [CBOT])
chk("mla-detail-drift not demoted", "0", len(out["demoted"]))

# mla-key-scope: diff rule (no), diff path (no), line-only diff (yes -> line excluded from key)
rows = [
    tsv("STALE", "other-rule", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 42, "claims 5 skills"),
    tsv("STALE", "count-locked", "OTHER.md", 42, "claims 5 skills"),
    tsv("STALE", "count-locked", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 7777, "claims 5 skills"),
]
_, out, _ = run(rows, [CBOT])
chk("mla-key-scope only line-diff demoted (len 1)", "1", len(out["demoted"]))
chk("mla-key-scope line-diff row_index 2", "2", out["demoted"][0]["row_index"])

# mla-verdict-scope: a non-STALE row whose payload matches byte-for-byte is NEVER demoted.
# Each verdict is run ALONE, and stale_rows (the filter's own distinct signal) is asserted —
# both are load-bearing against a vacuous pass. Putting the two rows in ONE fixture (as this
# check first did) made them share a match key, so deleting the `if verdict != STALE: continue`
# guard merely tripped the COLLISION guard one step later: demoted stayed 0 and the check
# passed against the exact mutant it exists to kill (guard-class shape 3 — refusal from the
# wrong guard). Alone, a mutant demotes the row (len 1) and reports stale_rows 1 -> RED.
for _v in ("VERIFIED", "UNRESOLVABLE"):
    _r = tsv(_v, "count-locked", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 42, "claims 5 skills")
    _, out, _ = run([_r], [CBOT])
    chk(f"mla-verdict-scope {_v} alone: not demoted", "0", len(out["demoted"]))
    chk(f"mla-verdict-scope {_v} alone: not counted as a STALE row", "0", out["stats"]["stale_rows"])

# mla-rule-scope (#466 shadow): an R4 row is NEVER carried forward, even against a
# byte-identical payload. R4's detail is a pure function of the CLAIM line (operator token +
# excerpt) and carries nothing about the PERMITTING line, so — unlike R1/R2/R3/R3b, whose
# details embed the observed referent — an old R4 adjudication keeps matching after a later
# commit adds a GENUINE contradicting permit, which would demote exactly the self-
# contradicting-diff finding the lint exists to catch. Assert the exclusion's own counter,
# not just demoted==0 (a mutant admitting R4 demotes the row -> both assertions RED).
R4ROW = tsv("STALE", "R4", "docs/GUIDE.md", 12, "deny-absolute forbids `cd` but the same file asserts it permitted — never use `cd`")
_, out_r4, _ = run([R4ROW], [adj_comment("devflow-reviewer[bot]", "Bot", R4ROW)])
chk("mla-rule-scope R4 never demoted (detail carries no referent)", "0", len(out_r4["demoted"]))
chk("mla-rule-scope R4 exclusion counted", "1", out_r4["stats"]["rows_rule_excluded"])
# Positive control on the same shape, using a REAL eligible rule id the lint actually emits
# ("R3" — referent-bearing detail), not a synthetic token: it IS carried forward. This proves
# the exclusion is rule-scoped rather than a blanket "nothing demotes" regression, and that the
# eligible ids in CARRY_FORWARD_EXCLUDED_RULES' complement are the ones the lint really emits.
R3ROW = tsv("STALE", "R3", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 42, "claims 5 skills but adjacent block has 6")
_, out_r3, _ = run([R3ROW], [adj_comment("devflow-reviewer[bot]", "Bot", R3ROW)])
chk("mla-rule-scope real R3 row still demotes (positive control)", "1", len(out_r3["demoted"]))
chk("mla-rule-scope real R3 row not rule-excluded", "0", out_r3["stats"]["rows_rule_excluded"])

# mla-row-malformed: a column-deficient STALE row is DROPPED but COUNTED + breadcrumbed
# (the payload side already did; the row side dropped it silently, leaving rows_in-stale_rows
# unexplained). Assert the counter, not just the absence of a demotion.
_, out_rm, err_rm = run(["STALE\tcount-locked"], [CBOT])
chk("mla-row-malformed counted", "1", out_rm["stats"]["rows_malformed"])
chk("mla-row-malformed no stale row", "0", out_rm["stats"]["stale_rows"])
chk("mla-row-malformed breadcrumb", "yes", "yes" if "skipping malformed row" in err_rm else "no")

# mla-trust: User-not-in-allowed (no, counted); Bot (yes); User-in-allowed (yes)
_, out, _ = run([ROW], [adj_comment("random-user", "User", ROW)])
chk("mla-trust untrusted-user not demoted", "0", len(out["demoted"]))
chk("mla-trust untrusted-user counted", "1", out["stats"]["payloads_untrusted"])
_, out, _ = run([ROW], [CBOT])
chk("mla-trust bot-author demoted", "1", len(out["demoted"]))
_, out, _ = run([ROW], [adj_comment("trusted-human", "User", ROW)])
chk("mla-trust allowlisted-user demoted", "1", len(out["demoted"]))

# mla-malformed: non-base64 payload + 2-column payload -> skipped, breadcrumb, exit 0, no demote
bad = "<!-- prflow:lint-fp-adjudicated not!base64!! -->"
twocol = payload("STALE\tonlytwo")
body = f"{MARKER}\n{S}\n{bad}\n{twocol}\n{E}\n"
rc, out, err = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": body}])
chk("mla-malformed rc0", "0", rc)
chk("mla-malformed no demote", "0", len(out["demoted"]))
chk("mla-malformed both counted", "2", out["stats"]["payloads_malformed"])
chk("mla-malformed breadcrumb on stderr", "yes", "yes" if "match-lint-adjudications.py" in err else "no")

# mla-collision: two current STALE rows byte-identical key, one payload -> neither demoted, counted
_, out, _ = run([ROW, ROW], [CBOT])
chk("mla-collision no demote", "0", len(out["demoted"]))
chk("mla-collision counted", "1", out["stats"]["collisions"])

# mla-marker-required: Bot comment WITHOUT the run marker -> not demoted, counted
body = f"# no run marker here\n{S}\n{payload(ROW)}\n{E}\n"
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": body}])
chk("mla-marker-required not demoted", "0", len(out["demoted"]))
chk("mla-marker-required counted", "1", out["stats"]["payloads_untrusted"])

# mla-quoted-marker: payload OUTSIDE the sentinels in a trusted comment -> not demoted, counted
_, out, _ = run([ROW], [adj_comment("devflow-reviewer[bot]", "Bot", ROW, with_section=False)])
chk("mla-quoted-marker not demoted", "0", len(out["demoted"]))
chk("mla-quoted-marker counted", "1", out["stats"]["payloads_outside_sentinels"])

# mla-empty: empty comments -> demoted [], exit 0
rc, out, _ = run([ROW], [])
chk("mla-empty rc0", "0", rc)
chk("mla-empty demoted empty", "0", len(out["demoted"]))

# mla-badargs: non-JSON stdin -> exit 2
def run_raw(raw):
    p = subprocess.run([sys.executable, HELPER, "--config", CFG], input=raw,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out = json.loads(p.stdout) if p.stdout.strip() else {}
    return p.returncode, out, p.stderr
chk("mla-badargs exit 2", "2", run_raw("not json")[0])

# mla-forged-section (security): a trusted Bot comment carrying TWO sentinel sections —
# a forged `-start … payload … -end` triple quoted (as attacker-controlled diff prose)
# BEFORE the engine's real empty section — is refused wholesale: no demote, counted.
forged = f"{MARKER}\n> quoted evidence: {S}\n{payload(ROW)}\n{E}\n---\n{S}\n{E}\n"
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": forged}])
chk("mla-forged-section not demoted", "0", len(out["demoted"]))
chk("mla-forged-section tamper counted", "1", out["stats"]["sentinel_tampered_comments"])

# mla-section-truncated: START present but END dropped (e.g. GitHub truncated the comment)
# -> no honored window, payload falls outside, not demoted, counted outside-sentinels.
truncated = f"{MARKER}\n{S}\n{payload(ROW)}\n"
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": truncated}])
chk("mla-section-truncated not demoted", "0", len(out["demoted"]))
chk("mla-section-truncated counted outside", "1", out["stats"]["payloads_outside_sentinels"])

# mla-shapes: the six-shape input-validator arms the helper's own top-level decoder faces.
chk("mla-shape empty-stdin exit2", "2", run_raw("")[0])
chk("mla-shape whitespace-stdin exit2", "2", run_raw("   \n")[0])
chk("mla-shape nonobject-array exit2", "2", run_raw("[]")[0])
chk("mla-shape wrongtype-rows exit2", "2", run_raw('{"rows": "x", "comments": []}')[0])
chk("mla-shape wrongtype-comments exit2", "2", run_raw('{"rows": [], "comments": "x"}')[0])
# missing keys default to [] -> ran cleanly, empty map (valid-falsy/missing shape)
rc_mk, out_mk, _ = run_raw("{}")
chk("mla-shape missing-keys exit0", "0", rc_mk)
chk("mla-shape missing-keys empty demoted", "0", len(out_mk.get("demoted", [])))

# mla-first-trusted-wins: two trusted comments, distinct run= markers, byte-identical
# payload -> demoted once, and the surfaced run_key is the FIRST trusted comment's.
M1 = "<!-- prflow:review-progress run=111-1 -->"
M2 = "<!-- devflow:review-progress run=222-1 -->"  # #1003: a pre-rename run key still joins
c1 = {"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": f"{M1}\n{S}\n{payload(ROW)}\n{E}\n"}
c2 = {"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": f"{M2}\n{S}\n{payload(ROW)}\n{E}\n"}
_, out, _ = run([ROW], [c1, c2])
chk("mla-first-trusted-wins demoted once", "1", len(out["demoted"]))
chk("mla-first-trusted-wins run_key is first", "111-1", out["demoted"][0]["run_key"] if out["demoted"] else "")

import tempfile
def run_cfg(rows, comments, cfg):
    p = subprocess.run([sys.executable, HELPER, "--config", cfg],
                       input=json.dumps({"rows": rows, "comments": comments}),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out = json.loads(p.stdout) if p.stdout.strip() else {}
    return p.returncode, out, p.stderr
_tmp_cfgs = []  # track every temp config so the driver unlinks them (no /tmp accretion)
def write_cfg(devflow_obj):
    f = tempfile.NamedTemporaryFile("w", suffix=".json", delete=False)
    json.dump({"prflow": devflow_obj}, f); f.close()
    _tmp_cfgs.append(f.name)
    return f.name

# mla-tamper-end-only: exactly one START but TWO END sentinels -> the guard's END arm
# (short-circuited in mla-forged-section, which trips on START) trips independently.
end2 = f"{MARKER}\n{S}\n{payload(ROW)}\n{E}\n> quoted: {E}\n"
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": end2}])
chk("mla-tamper-end-only not demoted", "0", len(out["demoted"]))
chk("mla-tamper-end-only counted", "1", out["stats"]["sentinel_tampered_comments"])

# ── #1003: the sentinel guard counts the UNION of both marker spellings ──────
# THE forgery this issue names. One GENUINE new-form section plus one
# attacker-quoted OLD-form section is `1` and `1` when each spelling is counted
# independently -- no tamper flag raised, and the earlier (forged) window honored.
# Counting the union is what refuses it. Driven in both orders, because a
# first-occurrence window makes the forged-first order the exploitable one and the
# forged-second order the control that must ALSO refuse.
mixed_forged_first = (
    f"{MARKER}\n> quoted evidence: {S_OLD}\n{payload_old(ROW)}\n{E_OLD}\n"
    f"---\n{S}\n{E}\n"
)
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot",
                         "body": mixed_forged_first}])
chk("mla-1003 mixed-spelling forgery (old quoted BEFORE the real section) not demoted",
    "0", len(out["demoted"]))
chk("mla-1003 mixed-spelling forgery counted as tampering",
    "1", out["stats"]["sentinel_tampered_comments"])
mixed_forged_second = (
    f"{MARKER}\n{S}\n{E}\n---\n> quoted evidence: {S_OLD}\n{payload_old(ROW)}\n{E_OLD}\n"
)
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot",
                         "body": mixed_forged_second}])
chk("mla-1003 mixed-spelling forgery (old quoted AFTER the real section) not demoted",
    "0", len(out["demoted"]))
chk("mla-1003 mixed-spelling forgery (after) counted as tampering",
    "1", out["stats"]["sentinel_tampered_comments"])
# The mirror: a genuine OLD-form section with a quoted NEW-form triple is the same
# shape from a pre-rename comment's point of view, and is refused identically.
mixed_reverse = (
    f"{MARKER_OLD}\n> quoted evidence: {S}\n{payload(ROW)}\n{E}\n---\n{S_OLD}\n{E_OLD}\n"
)
_, out, _ = run([ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot",
                         "body": mixed_reverse}])
chk("mla-1003 reverse mixed-spelling forgery not demoted", "0", len(out["demoted"]))
chk("mla-1003 reverse mixed-spelling forgery counted", "1",
    out["stats"]["sentinel_tampered_comments"])
# POSITIVE CONTROLS, so the rows above are not vacuous refusals. A wholly
# pre-rename comment (old marker, old sentinels, old payload) is still honored --
# that is the whole point of accepting both spellings -- and so is a MIXED but
# untampered comment, whose section is opened in one spelling and closed in the
# other (the shape a pre-rename comment re-written by the current engine takes).
all_old = {"author": "devflow-reviewer[bot]", "author_type": "Bot",
           "body": f"{MARKER_OLD}\n# report\n{S_OLD}\n{payload_old(ROW)}\n{E_OLD}\n"}
_, out, _ = run([ROW], [all_old])
chk("mla-1003 a wholly pre-rename comment is still honored", "1", len(out["demoted"]))
chk("mla-1003 ...and its pre-rename run key is surfaced", "999-1",
    out["demoted"][0]["run_key"] if out["demoted"] else "")
chk("mla-1003 a wholly pre-rename comment raises no tamper flag", "0",
    out["stats"]["sentinel_tampered_comments"])
mixed_pair = {"author": "devflow-reviewer[bot]", "author_type": "Bot",
              "body": f"{MARKER}\n# report\n{S_OLD}\n{payload(ROW)}\n{E}\n"}
_, out, _ = run([ROW], [mixed_pair])
chk("mla-1003 a mixed-spelling sentinel PAIR is honored (window offsets follow the "
    "spelling actually present)", "1", len(out["demoted"]))
chk("mla-1003 a mixed-spelling pair raises no tamper flag", "0",
    out["stats"]["sentinel_tampered_comments"])
# ...and the window is still a window: a payload OUTSIDE a mixed-spelling pair is
# refused, so the offset arithmetic did not silently widen to the whole body.
mixed_outside = {"author": "devflow-reviewer[bot]", "author_type": "Bot",
                 "body": f"{MARKER}\n> quoted: {payload(ROW)}\n{S_OLD}\n{E}\n"}
_, out, _ = run([ROW], [mixed_outside])
chk("mla-1003 a payload outside a mixed-spelling pair is still refused", "0",
    len(out["demoted"]))
chk("mla-1003 ...and counted as outside-sentinels", "1",
    out["stats"]["payloads_outside_sentinels"])

# mla-zero-match: a trusted, honored payload whose (rule,path,detail) is absent from the
# current STALE rows (the common real case — the FP was fixed so the lint no longer emits
# it) -> silent no-op: not demoted, not a collision.
other_row = tsv("STALE", "count-locked", "docs/internal/DEVFLOW_SYSTEM_OVERVIEW.md", 9, "claims 99 skills")
_, out, _ = run([other_row], [CBOT])
chk("mla-zero-match not demoted", "0", len(out["demoted"]))
chk("mla-zero-match no collision", "0", out["stats"]["collisions"])

# mla-shape-allowed-bots: dogfood THIS PR's own six-shape config-derivation rule over the
# helper's own `.prflow.allowed_bots` read. Every shape must (a) not crash (exit 0) and
# (b) fail toward the SAFE arm — a Bot-type author still demotes (trust independent of
# allowed_bots), so a corrupt allowed_bots can never OPEN trust it should have closed.
SHAPES = [("object", {"k": "v"}), ("array", ["a", "b"]), ("scalar-number", 5),
          ("valid-falsy-emptystr", ""), ("wrong-type-bool", False)]
for name, val in SHAPES:
    cfg = write_cfg({"allowed_bots": val})
    _, out, _ = run_cfg([ROW], [CBOT], cfg)
    chk(f"mla-shape allowed_bots {name}: bot-author still demotes (fail-safe)", "1", len(out["demoted"]))
    # The fail-SAFE row above is allowlist-INDEPENDENT (author_ok short-circuits on the Bot
    # arm before allowed_bots is consulted), so on its own it would stay green even if the
    # derivation were deleted. Pair every shape with the fail-CLOSED direction — an
    # allowlist-only User author — which is the assertion the derivation actually decides.
    _, out_u, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], cfg)
    chk(f"mla-shape allowed_bots {name}: non-listed User NOT trusted (fail-closed)",
        "0", len(out_u["demoted"]))
# Positive control for the same derivation: a login that IS in the (well-formed) array shape
# IS trusted. Without it, every row above stays green under a mutant that empties allowed_bots
# unconditionally — "nobody is trusted" would satisfy all the fail-closed rows.
cfg_ok = write_cfg({"allowed_bots": ["trusted-human", "other"]})
_, out_ok, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], cfg_ok)
chk("mla-shape allowed_bots array: LISTED User IS trusted (positive control)", "1", len(out_ok["demoted"]))
# missing key shape (no allowed_bots at all)
cfg_missing = write_cfg({})
_, out, _ = run_cfg([ROW], [CBOT], cfg_missing)
chk("mla-shape allowed_bots missing: bot-author still demotes (fail-safe)", "1", len(out["demoted"]))
# fail-CLOSED proof: under a malformed (object) allowed_bots, an allowlist-only User author
# is NOT trusted (the corrupt shape yields no usable login) -> not demoted.
cfg_obj = write_cfg({"allowed_bots": {"k": "v"}})
_, out, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], cfg_obj)
chk("mla-shape allowed_bots object: allowlist-User NOT trusted (fail-closed)", "0", len(out["demoted"]))

# mla-degraded-config: --config points at a MALFORMED config (config-get.sh's HARD-failure
# path, rc!=0 — a nonexistent path is its SOFT path, exit 0, and would not fire the breadcrumb).
# allowed_bots empties but the helper still RUNS (exit 0): a Bot author still demotes, an
# allowlist-only User does not, and the widened rc!=0 breadcrumb names config-get.sh.
_badf = tempfile.NamedTemporaryFile("w", suffix=".json", delete=False)
_badf.write("{ this is not valid json ")
_badf.close()
NOCFG = _badf.name
rc_d, out_d, err_d = run_cfg([ROW], [CBOT], NOCFG)
chk("mla-degraded-config exit0", "0", rc_d)
chk("mla-degraded-config bot still demotes", "1", len(out_d.get("demoted", [])))
chk("mla-degraded-config breadcrumb names config-get.sh", "yes", "yes" if "config-get.sh exited" in err_d else "no")
_, out_du, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], NOCFG)
chk("mla-degraded-config allowlist-User NOT trusted (fail-closed)", "0", len(out_du["demoted"]))

# mla-multi-demote (R9 collection-cardinality): TWO distinct honored payloads matching TWO
# distinct STALE rows in one run -> demoted carries both, sorted by row_index. The comment
# lists payload(ROW) [input index 1] BEFORE payload(ROW_B) [input index 0], so the pre-sort
# append order is [1, 0]; asserting [0, 1] proves demoted.sort() actually runs (the multi-
# entry output path + sort were entirely unexercised by the len-in-{0,1} scenarios above).
ROW_B = tsv("STALE", "legend-sum", "docs/OTHER.md", 3, "Expected total = 7")
body_multi = f"{MARKER}\n{S}\n{payload(ROW)}\n{payload(ROW_B)}\n{E}\n"
_, out_m, _ = run([ROW_B, ROW], [{"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": body_multi}])
chk("mla-multi-demote both rows demoted", "2", len(out_m["demoted"]))
chk("mla-multi-demote output sorted by row_index", "[0, 1]", str([d["row_index"] for d in out_m["demoted"]]))

# mla-shape valid-falsy / missing allowed_bots — the SECURITY direction (shadow: the empty/
# missing shapes previously asserted only that a Bot still demotes, which is allowlist-
# INDEPENDENT, so the load-bearing valid-falsy row was inert). Assert an allowlist-only User
# is NOT trusted when allowed_bots is empty/absent — proving the comma-split derivation empties.
cfg_emptystr = write_cfg({"allowed_bots": ""})
_, out, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], cfg_emptystr)
chk("mla-shape allowed_bots empty-string: allowlist-User NOT trusted (fail-closed)", "0", len(out["demoted"]))
cfg_absent = write_cfg({})
_, out, _ = run_cfg([ROW], [adj_comment("trusted-human", "User", ROW)], cfg_absent)
chk("mla-shape allowed_bots missing-key: allowlist-User NOT trusted (fail-closed)", "0", len(out["demoted"]))

# mla-element-malformed — a well-typed rows/comments LIST carrying a malformed ELEMENT (a
# partial-shape leak) is skip-and-counted, never an uncaught exception; helper still exits 0
# and valid siblings still process. (shadow: a non-string body previously raised TypeError
# and aborted the whole run outside the 0/2 exit contract.)
_, out, _ = run([42, ROW], [CBOT])  # 42 = non-string row element
chk("mla-element-malformed-row still demotes valid sibling", "1", len(out["demoted"]))
chk("mla-element-malformed-row counted", "1", out["stats"]["rows_malformed"])
rc_c, out_c, _ = run_raw(json.dumps({"rows": [ROW], "comments": [["x"], CBOT]}))  # non-dict comment
chk("mla-element-malformed-comment exit0", "0", rc_c)
chk("mla-element-malformed-comment counted", "1", out_c["stats"]["comments_malformed"])
rc_b, out_b, _ = run_raw(json.dumps({"rows": [ROW], "comments": [
    {"author": "devflow-reviewer[bot]", "author_type": "Bot", "body": ["a"]}]}))  # non-string body
chk("mla-nonstring-body exit0 (skip-and-count, no abort)", "0", rc_b)
chk("mla-nonstring-body counted", "1", out_b["stats"]["comments_malformed"])

# Clean up every temp config the shape/degraded scenarios created (no /tmp accretion across runs).
for _c in _tmp_cfgs + [NOCFG]:
    try:
        os.unlink(_c)
    except OSError:
        pass

for name, expected, actual in checks:
    sys.stdout.write(f"{name}\t{expected}\t{actual}\n")
PYEOF
# Capture the driver's output to a file and gate on BOTH its exit status and the
# emitted check count BEFORE looping — otherwise a driver that crashes (a helper
# import error, a fixture bug) yields empty output, the while-loop runs zero times,
# and every mla-* assertion silently vanishes while the suite stays green (the exact
# existence-standing-in-for-outcome silent-failure class this repo guards against).
MLA_RESULTS="$(mktemp)"; MLA_DRV_ERR="$(mktemp)"
# Capture the driver's own stderr to a file (NOT /dev/null): on a driver crash the Python
# traceback names the cause, and discarding it forces a blind manual re-run to diagnose.
MLA_HELPER="$MLA_HELPER_PATH" MLA_CFG="$MLA_CFG_FILE" python3 "$MLA_DRIVER" > "$MLA_RESULTS" 2>"$MLA_DRV_ERR"
MLA_DRV_RC=$?
assert_eq "#466 mla driver ran to completion (exit 0 — a crash would silently drop every mla-* check)" "0" "$MLA_DRV_RC"
[ "$MLA_DRV_RC" -eq 0 ] || printf '    mla driver stderr:\n%s\n' "$(sed 's/^/      /' "$MLA_DRV_ERR")"
assert_eq "#466 mla driver emitted all 92 named checks (guards against a silent partial run)" "92" \
  "$(grep -c . "$MLA_RESULTS")"
while IFS="$(printf '\t')" read -r _mla_name _mla_exp _mla_act; do
  [ -n "$_mla_name" ] && assert_eq "$_mla_name" "$_mla_exp" "$_mla_act"
done < "$MLA_RESULTS"
rm -f "$MLA_DRIVER" "$MLA_CFG_FILE" "$MLA_RESULTS" "$MLA_DRV_ERR"

# #466 drift-proof: every stats key the helper actually EMITS must be documented in its
# docstring Output enumeration (the recurrence-proofing for the sentinel_tampered_comments
# omission that shipped in iter-1). NON-VACUITY (this guard derives its comparand through a
# pipeline, so it MUST assert the input arrived before comparing — else a crashed helper
# yields empty output and the check passes green while never running; the exact silent-fail
# class the driver guard above defends against): the single Python below runs the helper,
# and emits a non-empty `GUARD-BROKEN: …` sentinel (which fails the assert_eq below) if the
# helper did not exit 0, its stdout is unparseable, its stats are empty, or the docstring's
# **Output block** (bounded precisely, not substring-anywhere-in-docstring) is absent — so
# the guard can only pass when it actually ran end to end.
MLA_UNDOC="$(python3 - "$LIB/../scripts/match-lint-adjudications.py" <<'PYEOF'
import json, re, subprocess, sys
helper = sys.argv[1]
p = subprocess.run([sys.executable, helper], input='{"rows":[],"comments":[]}',
                   stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
if p.returncode != 0:
    print(f"GUARD-BROKEN: helper exit {p.returncode}: {p.stderr.strip()[:120]}"); sys.exit()
try:
    parsed = json.loads(p.stdout)
except json.JSONDecodeError as e:
    print(f"GUARD-BROKEN: helper stdout not JSON: {e}"); sys.exit()
# isinstance BEFORE .get: valid-but-non-object JSON (a list/scalar) must not raise an
# uncaught AttributeError that empties stdout and passes the guard vacuously.
stats = parsed.get("stats") if isinstance(parsed, dict) else None
if not isinstance(stats, dict) or not stats:
    print("GUARD-BROKEN: helper emitted no stats object"); sys.exit()
src = open(helper, encoding="utf-8").read()
m = re.search(r"Output \(JSON to stdout.*?Exit codes:", src, re.S)  # the Output enumeration block only
if not m:
    print("GUARD-BROKEN: docstring Output block not found"); sys.exit()
outblock = m.group(0)
# Match each key as a QUOTED token ("key"), not substring-anywhere, so a key that is a
# substring of unrelated prose can never read as "documented".
print(" ".join(sorted(k for k in stats if f'"{k}"' not in outblock)))
PYEOF
)"
assert_eq "#466 every emitted stats key is documented in the helper docstring Output block (non-vacuous)" "" "$MLA_UNDOC"

# #466 mla-neutralization (finding A root fix): the Phase 4.1.7 producer contract carries the
# sentinel-channel neutralization rule so a forged sentinel quoted from diff prose can never
# render verbatim in a post-feature comment.
assert_pin_unique "#466 mla-neutralization: review skill Phase 4.1.7 carries the producer sentinel-neutralization rule" \
  'Sentinel-channel integrity (producer neutralization' "$REVIEW_SKILL"

# #466 mla-flatten: `gh api --paginate` applies `--jq` PER PAGE, so the fetched file holds
# CONCATENATED arrays and the Phase 0.6 join MUST flatten them (`$comments | add`). Reading
# `$comments[0]` would silently pass only page 1 — and since issue comments are served
# oldest-first, that drops the most RECENT progress comments, i.e. exactly the ones carrying
# the adjudication payloads: the feature would no-op on any PR past 100 comments, exit 0, and
# fire no degradation arm. Pin the flatten (Phase 0.3.6 already mandates the same idiom), and
# pin the truncating form ABSENT so a revert to `$comments[0]` goes RED at the desk.
assert_pin_unique "#466 mla-flatten: Phase 0.6 join flattens the concatenated --paginate pages" \
  'comments: ($comments | add // [])' "$REVIEW_SKILL"
# The fetch must keep gh's OWN exit status (an in-workspace redirect), not tee's — a piped
# fetch exits 0 on a failed gh, writes an empty file, and the join then reports a clean
# `demoted: []` instead of taking the degraded arm. And it must address the repo by the
# {owner}/{repo} placeholders: $GITHUB_REPOSITORY is EMPTY outside Actions, so the local
# PR-mode tier would fetch `repos//issues/...` and the join would never run.
assert_eq "#466 mla-fetch: Phase 0.6 comment fetch does not address the repo via \$GITHUB_REPOSITORY" "0" \
  "$(grep -cF 'repos/$GITHUB_REPOSITORY/issues/' "$REVIEW_SKILL" || true)"
assert_pin_unique "#466 mla-fetch: Phase 0.6 comment fetch uses the {owner}/{repo} placeholders" \
  'gh api --paginate "repos/{owner}/{repo}/issues/$PR_NUMBER/comments?per_page=100"' "$REVIEW_SKILL"

echo "#664 gh-api REST path: \$GITHUB_REPOSITORY is not a repo address outside Actions"
# The two #466 arms above are review-bundle-scoped and stay exactly as they are: they hold DEPTH
# over that bundle (they match the literal anywhere in its bytes, including Markdown prose outside
# any fence and a literal reached through one assignment hop). The scanner below adds population
# BREADTH — it reaches every audited file in the tree, which the bundle-scoped arms never see —
# and its own reach is narrower by construction (a `gh api` argument, never prose). Neither
# subsumes the other, which is why both live here.
E664_LINT="$LIB/test/lint-gh-api-repo-path.py"
E664_FX="$LIB/test/fixtures/ghapi-repo-path"

# Real-tree run. The tally is asserted POSITIVE as well: a green run whose audited count had
# silently collapsed to zero (a broken enumeration, an over-wide exclusion) would otherwise read
# as "clean" while auditing nothing at all.
E664_OUT="$(python3 "$E664_LINT" 2>&1)"; E664_RC=$?
# The comparand is the exit code alone: the success arm prints `rc=0` and nothing else, so no
# audited-file count is encoded here — a count every added file to the repo would drift. (The
# scanner prints its tally on BOTH arms; the tally is folded in only on the failure arm, where it
# is diagnostic rather than comparand. The positive-tally assertion below reads it from an rc=0
# run, which is why that read must not go through this assertion's comparand.)
assert_eq "#664 scanner: clean on the tree as it stands" "rc=0" \
  "$([ "$E664_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$E664_RC" "$E664_OUT")"
assert_eq "#664 scanner: the real-tree run audited a positive number of files" "yes" \
  "$(printf '%s' "$E664_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"

# Fixture-driven behavior. Every case is driven through --files-from over a synthetic path list
# rooted at the fixture directory, because the audited population excludes lib/test/ — the
# fixtures are unreachable from the default enumeration by design.
e664_run() {  # <root> <path…>  -> prints "rc=<n>|<stdout+stderr>"
  local root="$1"; shift
  local list out rc
  list="$(probe_tmp '#664 fixture list')" || return 0
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$E664_LINT" --root "$root" --files-from "$list" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}

# Legitimate corpus: a --repo flag value, a run-URL composition, a workflow env: assignment, a
# Python os.environ.get, a comment naming the variable, and prose quoting the prohibition itself.
assert_eq "#664 scanner: the legitimate corpus produces no violation" \
  "rc=0|lint-gh-api-repo-path: audited 4 of 4 files" \
  "$(e664_run "$E664_FX" legit-source.sh legit-python.py legit-prose.md legit-workflow.yml)"

# Planted defects, one assertion per named form. Fields are read with `IFS=:` from a heredoc
# (not a pipeline — the loop must stay in this shell), so no manual `%%:*` unpacking and no
# hidden "the description may not contain a colon" constraint.
while IFS=: read -r _e664_file _e664_line _e664_what; do
  [ -n "$_e664_file" ] || continue
  assert_eq "#664 scanner: flags a violation $_e664_what ($_e664_file)" "yes" \
    "$(case "$(e664_run "$E664_FX" "$_e664_file")" in *"|$_e664_file:$_e664_line: gh api REST path"*) echo yes ;; *) echo no ;; esac)"
done <<'E664_VIOLATIONS'
violation-basic.sh:3:plain dollar form
violation-brace.sh:2:brace form
violation-markdown.md:4:inside a bash fence
violation-resolved-head.sh:2:resolved-binary head
adversarial-heredoc.sh:5:inside a heredoc body
adversarial-singlequote.sh:4:inside a single-quoted string
adversarial-unterminated.md:8:after an unterminated fence
adversarial-nonutf8.sh:3:in a file carrying a non-UTF-8 byte
adversarial-continuation.sh:4:on a backslash-continued statement
adversarial-mdexample-fence.md.example:4:inside a .md.example fence
violation-leading-slash.sh:4:on the documented leading-slash /repos/ spelling
violation-preflag.sh:3:when a global flag sits between the head and the api subcommand
violation-gh-exe.sh:3:on the gh.exe Windows head
violation-nested-substitution.sh:3:nested two substitutions deep
violation-suffix-gh-var.sh:5:on a $VAR head whose name merely ENDS in GH (the suffix rule)
violation-tilde-fence.md:4:inside a ~~~ fence, not only a backtick fence
E664_VIOLATIONS

# Shapes that must NOT be flagged, each for its own reason.
while IFS=: read -r _e664_file _e664_why; do
  [ -n "$_e664_file" ] || continue
  assert_eq "#664 scanner: does not flag $_e664_why ($_e664_file)" \
    "rc=0|lint-gh-api-repo-path: audited 1 of 1 files" "$(e664_run "$E664_FX" "$_e664_file")"
done <<'E664_CLEAN'
adversarial-prose-only.md:a Markdown occurrence outside any fence
adversarial-mdexample-prose.md.example:a .md.example occurrence outside any fence
adversarial-empty.sh:an empty file
adversarial-nogh.sh:a file with no gh invocation
legit-nongh-var-head.sh:a variable head whose name does not end in GH (a declared residual)
E664_CLEAN

# Two violations in one file, each on its own reported line.
assert_eq "#664 scanner: reports both violations of one file on separate lines" "3 5" \
  "$(e664_run "$E664_FX" violation-basic.sh | python3 -c 'import re,sys
body = sys.stdin.read().split("|", 1)[1]
print(" ".join(re.findall(r"^violation-basic\.sh:(\d+):", body, re.M)))')"

# A call reached through more than one nesting level is reported ONCE. The substitution
# descent visits a nested `$( … $(gh api …) … )` through both bodies, so without the
# (line, argument) dedup this reports the same call twice and a reader double-counts.
assert_eq "#664 scanner: a nested-substitution call is reported once, not once per nesting level" "1" \
  "$(e664_run "$E664_FX" violation-nested-substitution.sh | python3 -c 'import sys
print(sys.stdin.read().split("|", 1)[1].count(": gh api REST path"))')"

# A selected path that cannot be READ is never absorbed into a clean pass: it is named on
# stderr, excluded from the read tally, and — when it is the whole population — fails closed.
# The tally counts files READ against files SELECTED precisely so "audited nothing" can never
# print the same thing as "audited everything, found nothing".
assert_eq "#664 scanner: an unreadable selected path is named, not silently skipped" "yes" \
  "$(case "$(e664_run "$E664_FX" no-such-file.sh)" in *"SKIPPED no-such-file.sh"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#664 scanner: a wholly unreadable population fails closed rather than reporting clean" "rc=1|0 of 1" \
  "$(e664_run "$E664_FX" no-such-file.sh | python3 -c 'import re,sys
t = sys.stdin.read()
m = re.search(r"audited (\d+ of \d+)", t)
print("rc=" + re.match(r"rc=(\d+)", t).group(1) + "|" + (m.group(1) if m else "no-tally"))')"

# Violations spread across separate files: still one non-zero exit for the process as a whole.
assert_eq "#664 scanner: two violating files exit non-zero once, reporting both" "rc=1 2" \
  "$(e664_run "$E664_FX" violation-brace.sh violation-second-file.sh | python3 -c 'import re,sys
t = sys.stdin.read()
print("rc=" + re.match(r"rc=(\d+)", t).group(1), len(re.findall(r": gh api REST path", t)))')"

# Fixture-integrity guards. Both fixtures below carry bytes `* text=auto` would normalize away,
# and a normalized fixture makes its assertion VACUOUS rather than red — the CRLF twin would
# simply become a second copy of its LF sibling, and the undecodable byte would vanish. The
# `-text` .gitattributes entries are what preserve them; the assertions below are what notice if
# those entries are ever dropped, since no downstream assertion can tell the difference.
e664_fixture_keeps() {  # <crlf|undecodable> <path> -> yes|no
  python3 -c 'import pathlib, sys
mode, data = sys.argv[1], pathlib.Path(sys.argv[2]).read_bytes()
if mode == "crlf":
    print("yes" if b"\r\n" in data else "no")
else:
    try:
        data.decode("utf-8")
    except UnicodeDecodeError:
        print("yes")
    else:
        print("no")' "$1" "$2"
}
assert_eq "#664 fixture integrity: the CRLF twin still carries CR bytes (not normalized to LF)" "yes" \
  "$(e664_fixture_keeps crlf "$E664_FX/adversarial-crlf.txt")"
assert_eq "#664 fixture integrity: the non-UTF-8 fixture still carries an undecodable byte" "yes" \
  "$(e664_fixture_keeps undecodable "$E664_FX/adversarial-nonutf8.sh")"

# CRLF twin: identical verdict AND identical line numbers to its LF sibling.
assert_eq "#664 scanner: a CRLF file yields the same line numbers as its LF twin" "same" \
  "$(python3 -c 'import sys
lf, crlf = sys.argv[1], sys.argv[2]
print("same" if lf.split(":",1)[1] == crlf.split(":",1)[1] else "differ: %s vs %s" % (lf, crlf))' \
    "$(e664_run "$E664_FX" adversarial-lf.sh)" "$(e664_run "$E664_FX" adversarial-crlf.txt)")"

# Population selection, driven over a mini-root whose every excluded-prefix file carries a planted
# violation: only the one included file is reported, and the tally counts post-exclusion files.
assert_eq "#664 scanner: every excluded prefix keeps its planted violation out of reach" \
  "rc=1|included/planted.sh|1" \
  "$(e664_run "$E664_FX/exroot" \
      lib/test/planted.sh docs/planted.sh .github/workflows/planted.yml \
      .github/actions/act/planted.sh .prflow/logs/planted.md .prflow/learnings/planted.md \
      .changeset/planted.md CHANGELOG.md .claude/worktrees/w/planted.sh included/planted.sh \
    | python3 -c 'import re,sys
t = sys.stdin.read()
body = t.split("|", 1)[1]
print("|".join([
    "rc=" + re.match(r"rc=(\d+)", t).group(1),
    ",".join(re.findall(r"^(\S+):\d+: gh api REST path", body, re.M)),
    re.search(r"audited (\d+) of", body).group(1),
]))')"

# A post-exclusion population of zero is a LEGAL outcome (exit 0, zero tally) and must never be
# confused with the fail-closed arms below — that confusion is what would let an over-wide
# exclusion read as a clean audit.
assert_eq "#664 scanner: an all-excluded population is a zero tally at exit 0, not a failure" \
  "rc=0|lint-gh-api-repo-path: audited 0 of 0 files" \
  "$(e664_run "$E664_FX/exroot" lib/test/planted.sh docs/planted.sh)"

# issue #711: this scanner's population is a WORKING-TREE enumeration (--others), so before the
# helper carried its own .claude/worktrees/ exclusion it swept every sibling worktree and could
# report a violation living in another branch's checkout. It survived only through the untracked,
# harness-managed .git/info/exclude line — machine-local state a bare clone does not inherit —
# so this assertion drives the exclusion directly through --files-from, where that line has no
# say at all, and therefore holds on a clone that lacks it.
assert_eq "#711 the gh-api lint is worktree-immune without the local exclude" \
  "rc=0|lint-gh-api-repo-path: audited 0 of 0 files" \
  "$(e664_run "$E664_FX/exroot" .claude/worktrees/w/planted.sh)"

# Fail-closed arms, measured PRE-exclusion, each naming which of the two occurred.
assert_eq "#664 scanner: an empty pre-exclusion population fails closed with its own breadcrumb" "yes" \
  "$(case "$(e664_run "$E664_FX")" in "rc=0"*) echo "no: exited 0" ;; *"yielded zero paths before any exclusion"*) echo yes ;; *) echo no ;; esac)"
E664_MISSING="$(probe_tmp '#664 missing list')"
rm -f "$E664_MISSING"
assert_eq "#664 scanner: an unreadable --files-from list fails closed with its own breadcrumb" "yes" \
  "$(E664_OUT2="$(python3 "$E664_LINT" --root "$E664_FX" --files-from "$E664_MISSING" 2>&1)"
     case "$?:$E664_OUT2" in 0:*) echo "no: exited 0" ;; *"could not be read"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#664 scanner: a non-repository root fails closed naming git ls-files" "yes" \
  "$(E664_SB="$(probe_tmp '#664 non-repo root')"
     rm -f "$E664_SB"; mkdir -p "$E664_SB"
     E664_OUT3="$(python3 "$E664_LINT" --root "$E664_SB" 2>&1)"
     E664_RC3=$?
     rmdir "$E664_SB" 2>/dev/null || true
     case "$E664_RC3:$E664_OUT3" in 0:*) echo "no: exited 0" ;; *"git ls-files exited"*) echo yes ;; *) echo no ;; esac)"

echo "#1524 negated-compound-redirect: a !-negated compound must not carry a redirect on the compound"
# ────────────────────────────────────────────────────────────────────────────
# bash does not propagate a failed redirect on a COMPOUND command through `!`, so
# `if ! { …; } > "$f"` reads as success when the redirect cannot open and the failure arm
# never runs. This lint guards against reintroducing the idiom the four #1524 fixes removed.
NCR_LINT="$LIB/test/lint-negated-compound-redirect.py"
NCR_FX="$LIB/test/fixtures/lint-negated-compound-redirect"
# Real-tree run: clean, and auditing a positive number of files (a collapsed-to-zero audit
# would read "clean" while scanning nothing).
NCR_OUT="$(python3 "$NCR_LINT" 2>&1)"; NCR_RC=$?
assert_eq "#1524 scanner: clean on the tree as it stands" "rc=0" \
  "$([ "$NCR_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$NCR_RC" "$NCR_OUT")"
assert_eq "#1524 scanner: the real-tree run audited a positive number of files" "yes" \
  "$(printf '%s' "$NCR_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"
# Fixture-driven behavior. Each case is driven through --files-from over a path list rooted
# at the fixture directory, because the audited population excludes that directory by design.
ncr_run() {  # <path…>  -> prints "rc=<n>|<stdout+stderr>"
  local list out rc
  list="$(probe_tmp '#1524 fixture list')" || return 0
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$NCR_LINT" --root "$NCR_FX" --files-from "$list" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
# Planted defects — each named form flags on the close line.
while IFS=: read -r _ncr_file _ncr_line _ncr_what; do
  [ -n "$_ncr_file" ] || continue
  assert_eq "#1524 scanner: flags a violation $_ncr_what ($_ncr_file)" "yes" \
    "$(case "$(ncr_run "$_ncr_file")" in *"|$_ncr_file:$_ncr_line: a !-negated compound"*) echo yes ;; *) echo no ;; esac)"
done <<'NCR_VIOLATIONS'
defect-brace-oneline.sh:3:brace group, single line
defect-subshell-oneline.sh:3:subshell, single line
defect-brace-multiline.sh:5:brace group across lines, redirect on the close line
defect-input.sh:3:an input redirect (< "$f") whose first redirect is non-/dev/null
defect-append.sh:3:an append redirect (>> "$f")
defect-devnull-then-data.sh:3:a data redirect hidden behind a leading 2>/dev/null (scan every clause, not just the first)
defect-clobber.sh:3:a clobber-override redirect (>| "$f")
defect-ampredirect.sh:3:a both-streams-to-file redirect (&> "$f")
NCR_VIOLATIONS
# Shapes that must NOT be flagged, each for its own reason.
while IFS=: read -r _ncr_file _ncr_why; do
  [ -n "$_ncr_file" ] || continue
  assert_eq "#1524 scanner: does not flag $_ncr_why ($_ncr_file)" \
    "rc=0|lint-negated-compound-redirect: audited 1 of 1 files" "$(ncr_run "$_ncr_file")"
done <<'NCR_CLEAN'
safe-inside.sh:a redirect placed INSIDE the group (close followed by ;)
safe-devnull.sh:a redirect to /dev/null on the compound (cannot fail to open)
safe-not-negated.sh:the correct rc-capture idiom with no ! negation
safe-marker.sh:a suppressed finding carrying the negated-compound-redirect-ok marker (above the opener)
safe-marker-trailing.sh:a suppressed finding whose marker is a trailing comment on the opener/close line
safe-string.sh:the defect shape appearing only inside a quoted string
safe-fddup.sh:a descriptor dup (>&2) on the compound, which opens no file
safe-heredoc.sh:a heredoc (<<EOF) on the compound, whose body is in-memory
safe-herestring.sh:a here-string (<<< word) on the compound, whose body is in-memory
NCR_CLEAN
# An unreadable selected path is named and fails closed, never absorbed into a clean pass.
assert_eq "#1524 scanner: an unreadable selected path is named, not silently skipped" "yes" \
  "$(case "$(ncr_run no-such-file.sh)" in *"SKIPPED no-such-file.sh"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1524 scanner: a wholly unreadable population fails closed rather than reporting clean" "rc=1|0 of 1" \
  "$(ncr_run no-such-file.sh | python3 -c 'import re,sys
t = sys.stdin.read()
m = re.search(r"audited (\d+ of \d+)", t)
print("rc=" + re.match(r"rc=(\d+)", t).group(1) + "|" + (m.group(1) if m else "no-tally"))')"

echo "#1312 executable-helper-mode: an -x-gated bundled helper must be tracked 100755"
# Mechanical guard (issue #1312): scripts/dedupe-review-command.sh shipped 100644 while
# devflow.yml gates on `[ ! -x ... ]`, so Candidate-C dedupe never fired and no test caught
# it (both arms fail open). This lint derives the -x-gated helper set by joining VAR=<path>
# assignments to `[ -x "$VAR" ]` tests across tracked .github/workflows/*.yml, scripts/*.sh,
# lib/*.sh and asserts every resolved repo helper is tracked 100755. Driven like the sibling
# #664/#711 lints: the real tree as the live gate, plus fresh git sandboxes for the RED cases.
E1312_LINT="$LIB/test/lint-executable-helper-mode.py"

# Real-tree run: exit 0, and the audited tally is asserted POSITIVE so a collapsed enumeration
# (which would audit nothing yet exit 0) cannot read as clean.
E1312_OUT="$(python3 "$E1312_LINT" 2>&1)"; E1312_RC=$?
assert_eq "#1312 helper-mode lint: clean on the tree as it stands" "rc=0" \
  "$([ "$E1312_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$E1312_RC" "$E1312_OUT")"
assert_eq "#1312 helper-mode lint: the real-tree run audited a positive number of files" "yes" \
  "$(printf '%s' "$E1312_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"
assert_eq "#1312 helper-mode lint: the real-tree run checks at least one -x-gated repo helper" "yes" \
  "$(printf '%s' "$E1312_OUT" | python3 -c 'import re,sys
m = re.search(r"\((\d+) -x-gated repo helper", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"

# Fresh git sandbox with a workflow -x-gating two vendored helpers (`.prflow/vendor/prflow/…`,
# mapped to the repo-root path before the mode lookup), a script-dir-anchored -x test, a runtime
# -x site (a `gh` binary, classified out of scope, not asserted), a `source`d/`-f`-guarded 644
# helper (must NOT be swept — AC4), plus any extra run-block lines the caller appends. $1 is the
# mode of the variable-mode helper scripts/dedupe.sh.
e1312_make() {  # <dedupe-mode> [extra-run-lines]  -> prints repo dir
  local d; d="$(git_sandbox "#1312 fixture")" || { printf '%s\n' "$d"; return 1; }
  git -C "$d" init -q; git -C "$d" config user.email t@t; git -C "$d" config user.name t
  mkdir -p "$d/scripts" "$d/.github/workflows" "$d/lib"
  printf '#!/usr/bin/env bash\necho hi\n' > "$d/scripts/dedupe.sh"
  printf '#!/usr/bin/env bash\necho ok\n' > "$d/scripts/detector.sh"
  printf '#!/usr/bin/env bash\necho c\n' > "$d/scripts/child.sh"
  printf '%s\n' '#!/usr/bin/env bash' \
    'SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"' \
    'if [ ! -x "$SELF/child.sh" ]; then echo warn; fi' > "$d/scripts/self.sh"
  # lib/sourced.sh (644) is only `source`d / `-f`-guarded here, never `-x`-tested — AC4.
  printf '%s\n' '#!/usr/bin/env bash' 'X=/tmp' \
    'if [ -f "$X/lib/sourced.sh" ]; then source "$X/lib/sourced.sh"; fi' > "$d/lib/user.sh"
  printf '#!/usr/bin/env bash\ntrue\n' > "$d/lib/sourced.sh"
  # scripts/probe644.sh (644) is un-referenced by the base workflow; the resolution-shape
  # variants below `-x`-gate it via each supported operand form, so an appended form is the
  # SOLE source of RED and a regression in that form's parsing flips the assertion.
  printf '#!/usr/bin/env bash\ntrue\n' > "$d/scripts/probe644.sh"
  chmod 644 "$d/scripts/probe644.sh"
  { printf '%s\n' 'jobs:' '  a:' '    steps:' '      - run: |' \
      '          CC_HELPER=.prflow/vendor/prflow/scripts/dedupe.sh' \
      '          if [ ! -x "$CC_HELPER" ]; then echo w; fi' \
      '          DETECTOR=.prflow/vendor/prflow/scripts/detector.sh' \
      '          if [ ! -x "$DETECTOR" ]; then echo w; fi' \
      '          REAL="$(command -v gh 2>/dev/null || true)"' \
      '          if [ -n "$REAL" ] && [ -x "$REAL" ]; then :; fi'
    [ -n "$2" ] && printf '%s\n' "$2"
  } > "$d/.github/workflows/wf.yml"
  chmod 755 "$d/scripts/detector.sh" "$d/scripts/child.sh" "$d/scripts/self.sh" "$d/lib/user.sh"
  chmod 644 "$d/lib/sourced.sh"
  chmod "$1" "$d/scripts/dedupe.sh"
  git -C "$d" add -A
  printf '%s\n' "$d"
}
e1312_run() {  # <root>  -> prints "rc=<n>|<stdout+stderr>"
  local out rc
  out="$(python3 "$E1312_LINT" --root "$1" 2>&1)"; rc=$?
  printf 'rc=%s|%s' "$rc" "$out"
}

# GREEN: every -x-gated repo helper is 755 → exit 0; the runtime `gh` site and the 644
# `source`d/`-f`-guarded lib/sourced.sh are not flagged.
E1312_GREEN="$(e1312_make 755)"
if [ -d "$E1312_GREEN" ]; then
  E1312_G_OUT="$(e1312_run "$E1312_GREEN")"
  assert_eq "#1312 lint: fixed tree (every -x-gated helper 755) passes" "yes" \
    "$(case "$E1312_G_OUT" in "rc=0|"*) echo yes ;; *) echo "no: $E1312_G_OUT" ;; esac)"
  assert_eq "#1312 lint: AC4 a source'd/-f-guarded 644 helper is not swept" "yes" \
    "$(case "$E1312_G_OUT" in *"sourced.sh is tracked"*|*"sourced.sh resolves"*) echo no ;; *) echo yes ;; esac)"
  assert_eq "#1312 lint: the runtime gh -x site is classified, not asserted" "yes" \
    "$(case "$E1312_G_OUT" in *"RUNTIME"*"REAL"*) echo yes ;; *) echo no ;; esac)"
  rm -rf "$E1312_GREEN"
fi

# RED AC6: the -x-gated helper is 644 → RED naming the file and its mode.
E1312_RED="$(e1312_make 644)"
if [ -d "$E1312_RED" ]; then
  E1312_R_OUT="$(e1312_run "$E1312_RED")"
  assert_eq "#1312 lint: AC6 a 644 -x-gated helper fails RED naming file+mode" "yes" \
    "$(case "$E1312_R_OUT" in "rc=1|"*"scripts/dedupe.sh is tracked mode 100644"*) echo yes ;; *) echo "no: $E1312_R_OUT" ;; esac)"
  rm -rf "$E1312_RED"
fi

# RED AC5 (untracked resolution): an -x operand resolving to an in-repo path that is not a
# tracked file is named and RED — never silently skipped.
E1312_GHOST="$(e1312_make 755 '          GHOST=.prflow/vendor/prflow/scripts/ghost.sh
          if [ ! -x "$GHOST" ]; then echo w; fi')"
if [ -d "$E1312_GHOST" ]; then
  E1312_GH_OUT="$(e1312_run "$E1312_GHOST")"
  assert_eq "#1312 lint: AC5 an operand resolving to an untracked in-repo path fails RED, named" "yes" \
    "$(case "$E1312_GH_OUT" in "rc=1|"*"scripts/ghost.sh"*"not a tracked repo file"*) echo yes ;; *) echo "no: $E1312_GH_OUT" ;; esac)"
  rm -rf "$E1312_GHOST"
fi

# RED AC5 (unresolvable shape): an -x operand whose shape the resolver cannot account for is
# named and RED, never skipped.
E1312_SHAPE="$(e1312_make 755 '          if [ -x "$UNRESOLVABLE_A$UNRESOLVABLE_B" ]; then echo w; fi')"
if [ -d "$E1312_SHAPE" ]; then
  E1312_SH_OUT="$(e1312_run "$E1312_SHAPE")"
  assert_eq "#1312 lint: AC5 an unresolvable operand shape fails RED, named" "yes" \
    "$(case "$E1312_SH_OUT" in "rc=1|"*"could not be resolved"*"refusing to silently skip"*) echo yes ;; *) echo "no: $E1312_SH_OUT" ;; esac)"
  rm -rf "$E1312_SHAPE"
fi

# Resolution-shape regression fixtures. Each gates the un-referenced 644 scripts/probe644.sh
# via one supported operand form, so the appended form is the SOLE source of RED — a parsing
# regression in that form flips the assertion. These cover the forms that had no exercising
# test (test -x, [[ -x ]], var-ref transitive) and the fail-open closures (a ${VAR:-<literal>}
# default naming a real helper; a real assignment winning over a read/for name collision).
e1312_form_red() {  # <label> <extra-run-lines>
  local d out
  d="$(e1312_make 755 "$2")"; [ -d "$d" ] || return 0
  out="$(e1312_run "$d")"
  assert_eq "#1312 lint: $1 resolves to the 644 helper and fails RED" "yes" \
    "$(case "$out" in "rc=1|"*"scripts/probe644.sh is tracked mode 100644"*) echo yes ;; *) echo "no: $out" ;; esac)"
  rm -rf "$d"
}
e1312_form_red "test -x form" '          PB3=.prflow/vendor/prflow/scripts/probe644.sh
          if test ! -x "$PB3"; then echo w; fi'
e1312_form_red "[[ -x ]] form" '          PB4=scripts/probe644.sh
          if [[ ! -x "$PB4" ]]; then echo w; fi'
e1312_form_red "var-ref transitive resolution" '          PBASE=.prflow/vendor/prflow/scripts
          PB5="$PBASE/probe644.sh"
          if [ ! -x "$PB5" ]; then echo w; fi'
e1312_form_red "brace-default operand (fail-open closure)" '          if [ ! -x "${MISSING:-.prflow/vendor/prflow/scripts/probe644.sh}" ]; then echo w; fi'
e1312_form_red "brace-default assignment (fail-open closure)" '          PB6=${MISSING:-scripts/probe644.sh}
          if [ ! -x "$PB6" ]; then echo w; fi'
e1312_form_red "real assignment wins over read/for name collision (fail-open closure)" '          PB7=scripts/probe644.sh
          echo "please read PB7 before running"
          if [ ! -x "$PB7" ]; then echo w; fi'

# Fail-closed: a non-repository root names the git failure rather than reporting clean.
E1312_NONREPO="$(probe_tmp '#1312 non-repo root')"
rm -f "$E1312_NONREPO"; mkdir -p "$E1312_NONREPO"
assert_eq "#1312 lint: a non-repository root fails closed naming git" "yes" \
  "$(E1312_NR_OUT="$(python3 "$E1312_LINT" --root "$E1312_NONREPO" 2>&1)"; E1312_NR_RC=$?
     rmdir "$E1312_NONREPO" 2>/dev/null || true
     case "$E1312_NR_RC:$E1312_NR_OUT" in 0:*) echo "no: exited 0" ;; *"git ls-files"*) echo yes ;; *) echo no ;; esac)"

echo "#711 tree enumeration: a repository-root recursive walk is declared, not silent"
# The guard joins the desk-time static-lint family (extract-command-heads.py, pin-corpus-lint.py,
# lint-gh-api-repo-path.py, lint-issue-body-refetch.py, coverage_map_guard.py — deliberately no
# ordinal: it is a member of the DECLARATION-MARKER family, which is a different set, and
# a count of this one accretes) and is driven the same way: the real tree as the
# live gate, plus synthetic fixtures through --root/--files-from. Its audited population INCLUDES
# lib/test/, which is why its fixtures are written into probe_tmp scratch rather than checked in —
# a tracked fixture carrying an unmarked walk would be caught by the guard's own real-tree run.
E711_LINT="$LIB/test/lint-tree-enumeration.py"
E711_CLAUDE="$LIB/../CLAUDE.md"
E711_GROWTH="$LIB/../docs/internal/cutovers/issue-711-tree-enumeration-growth.md"

# Anchored at "$LIB/.." rather than left to resolve from the process cwd: the helper accepts
# --root, and the repo's #295 contract is to audit the tree the caller means, not whichever git
# root the cwd happens to sit in. (The --root-absent fallback keeps its own assertion below.)
E711_OUT="$(python3 "$E711_LINT" --root "$LIB/.." 2>&1)"; E711_RC=$?
# Comparand is the exit code alone: the audited count would drift with every file added to
# lib/test/, so the positive-tally check below is a SEPARATE assertion reading the same rc=0 run.
assert_eq "#711 the real tree audits clean" "rc=0" \
  "$([ "$E711_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$E711_RC" "$E711_OUT")"
assert_eq "#711 the real-tree run audited a positive number of files" "yes" \
  "$(printf '%s' "$E711_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"
# The real-tree population contains one file that is not valid UTF-8 (an adversarial fixture
# planted for the #664 lint, whose own population excludes lib/test/). A decode that raised, or
# that dropped the file, would show up here as a skip — and any skip refuses to report clean.
assert_eq "#711 the real tree decodes without raising" "yes" \
  "$(case "$E711_OUT" in *"SKIPPED"*) echo "no: $E711_OUT" ;; *) echo yes ;; esac)"

# Fixture driver. Bodies are composed from PARTS at write time so no candidate token literal
# lands in this file's own source — every fixture line would otherwise need a marker of its own.
E711_TOK_R="rglob"; E711_TOK_W="os.walk"; E711_TOK_G="glob"
e711_run() {  # <root> <path…>  -> prints "rc=<n>|<stdout+stderr>"
  local root="$1"; shift
  local list out rc
  list="$(probe_tmp '#711 fixture list')" || list=""
  # probe_tmp prints the literal /dev/null on mktemp failure. Writing the fixture list there
  # yields an EMPTY population, which the guard fails closed on with rc 1 — so every assertion
  # whose expected value is the bare string `rc=1` would PASS, having proven nothing about the
  # walk detection it names. probe_tmp has already recorded its own FAIL, so the run is red
  # either way; emit a value that can match no expectation, so the misattribution cannot happen.
  case "$list" in
    ""|/dev/null) printf 'rc=probe-unavailable|fixture list could not be allocated'; return 0 ;;
  esac
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$E711_LINT" --root "$root" --files-from "$list" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
e711_rc() {  # <root> <path…>  -> prints just "rc=<n>"; assert_eq prints the value on a miss,
             # so a bespoke per-case failure string buys nothing the helper does not already give.
  # Pure parameter expansion — no tr/sed/cut: this value DECIDES an assertion, and the repo's
  # guard-class-2 rule keeps such a value off every non-preflight PATH tool.
  local out; out="$(e711_run "$@")"
  # The guard exits 1 both when it DETECTS a walk and when it refuses to audit at all (the
  # load-failure arm: the shared extract-command-heads.py could not be resolved). Every
  # "<shape> is a candidate" assertion compares against the bare string `rc=1`, so a rename of
  # that shared helper would turn ~20 detection assertions green while nothing was scanned —
  # the same misattribution the probe_tmp sentinel above is short-circuited to prevent. Emit a
  # value no expectation can match instead. A `SKIPPED` outcome is deliberately NOT caught here:
  # it is a real per-file verdict some assertions legitimately expect through rc=1.
  case "$out" in
    *"refusing to audit"*) printf 'rc=guard-unusable'; return 0 ;;
  esac
  printf '%s' "${out%%|*}"
}
e711_run_outcome() {  # <root> <path…> -> like e711_run, minus the all-excluded NOTE line
  # The note's WORDING is not this assertion's subject — the rc and the audited tally are. Pinning
  # the prose verbatim made an ordinary rewording break two unrelated assertions, so the note gets
  # its own dedicated assertion below and these compare the outcome. Filtered with python3 (a
  # preflight-guaranteed interpreter), never sed/grep: this value decides an assertion.
  local out; out="$(e711_run "$@")"
  printf '%s' "$out" | python3 -c 'import sys
text = sys.stdin.read()
# The rc= prefix rides on the FIRST body line, so split it off before filtering — otherwise the
# note line reads as "rc=0|lint-tree-enumeration: note: …" and no prefix test matches it.
prefix, _, body = text.partition("|")
keep = [l for l in body.split("\n") if "lint-tree-enumeration: note:" not in l]
print(prefix + "|" + "\n".join(keep), end="")'
}
e711_write() {  # <root> <relpath> <line…>  -> writes a fixture file, creating parents
  local root="$1" rel="$2" dir; shift 2
  dir="${rel%/*}"; [ "$dir" = "$rel" ] || mkdir -p "$root/$dir"
  printf '%s\n' "$@" > "$root/$rel"
}

E711_FX="$(probe_tmp '#711 fixture root')"
# probe_tmp prints the literal /dev/null when mktemp fails (unlike git_sandbox, whose
# /dev/null/... sentinel fails every downstream mkdir closed by construction). An unguarded
# `rm -f` on it would, under a root container with a writable /dev, delete the device node and
# silently change the meaning of every `2>/dev/null` in the rest of the suite.
case "$E711_FX" in ""|/dev/null) : ;; *) rm -f "$E711_FX"; mkdir -p "$E711_FX" ;; esac
e711_write "$E711_FX" lib/test/clean.py "import os" "print(os.sep)"
e711_write "$E711_FX" lib/test/unmarked.py "for p in root.${E711_TOK_R}('*.json'):" "    print(p)"
e711_write "$E711_FX" lib/test/marked.py \
  "for p in root.${E711_TOK_R}('*.json'):  # tree-walk-ok: scoped to a per-test sandbox" "    print(p)"
e711_write "$E711_FX" lib/test/nearmiss.py \
  "for p in root.${E711_TOK_R}('*.json'):  # tree-walk-ok scoped to a per-test sandbox" "    print(p)"
e711_write "$E711_FX" lib/test/emptyreason.py \
  "for p in root.${E711_TOK_R}('*.json'):  # tree-walk-ok:" "    print(p)"
e711_write "$E711_FX" lib/test/commented.py "# a walk would be ${E711_TOK_W}(root) here" "print(1)"
e711_write "$E711_FX" lib/test/starglob.py "paths = ROOT.${E711_TOK_G}(\"**/x.json\")"
e711_write "$E711_FX" lib/test/broken.py "def f(:"
e711_write "$E711_FX" other/outside.py "for p in root.${E711_TOK_R}('*.json'):" "    print(p)"
# Multi-element fixtures for the cardinality-sensitive part of the report: findings are sorted by
# line and deduplicated per line, neither of which a single-violation file exercises. `dual.py`
# plants two violations OUT of line order in the file's own structure, so a broken sort key shows
# up as reordered output rather than passing silently. The DEDUPE is exercised separately by
# `dedupe.py` below: a `**`-pattern line cannot also reach the non-literal-pattern arm (arm 1
# appends and short-circuits), so no single line of `dual.py` can ever emit two findings — only a
# line reaching the LITERAL arm and an AST arm at once does, which is what `dedupe.py` plants.
e711_write "$E711_FX" lib/test/dual.py \
  "a = ROOT.${E711_TOK_G}(joined(\"**\", \"x.json\"))" \
  "b = 1" \
  "c = root.${E711_TOK_R}('*.json')"
e711_write "$E711_FX" lib/test/second.py "d = root.${E711_TOK_W}(base)"
# One line reaching the literal arm AND AST arm 1 at once — the only shape that generates a
# duplicate finding for a single line, so deleting the per-line dedupe reports this line twice.
e711_write "$E711_FX" lib/test/dedupe.py "e = root.${E711_TOK_R}(\"**/x.json\")"
# AST arm 2's positive control: a `glob(`-family call whose pattern argument is a plain NAME.
# No other fixture reaches arm 2 — without this one, deleting the arm leaves the block green.
e711_write "$E711_FX" lib/test/nonliteral.py "f = ROOT.${E711_TOK_G}(pattern)"
# Arm 2's documented complement: a call with no positional argument at all is not a candidate.
e711_write "$E711_FX" lib/test/kwonly.py "g = ROOT.${E711_TOK_G}(pattern=p)"
# Positive controls for the two LITERAL_TOKENS members no other fixture reaches. Both shapes are
# deliberately invisible to BOTH AST arms — a plain string pattern with no `**` component — so the
# literal arm is the only thing that can flag them, and deleting either tuple member turns exactly
# one of these RED instead of leaving the whole block green. Tokens are assembled from parts for
# the same reason as the rest: an intact literal here would make run.sh its own candidate.
E711_TOK_I="ig""lob"; E711_TOK_RT="recursive""=True"
e711_write "$E711_FX" lib/test/iglob.py "k = ${E711_TOK_G}.${E711_TOK_I}(\"*.txt\")"
e711_write "$E711_FX" lib/test/recursivekw.py "l = ${E711_TOK_G}.${E711_TOK_G}(\"*.txt\", ${E711_TOK_RT})"
# Minor #2's uncovered branch: a file that is BOTH unparseable and carries a literal-arm walk.
# `broken.py` carries no walk token, so the "report literal findings alongside the parse skip"
# path was unexercised — deleting that report would have left the block green.
e711_write "$E711_FX" lib/test/brokenwalk.py "m = root.${E711_TOK_R}('*.json')" "def f(:"
# The residual docstring now states positively that a keyword-LITERAL `**` pattern is still
# caught (the `**`-component arm reads every string constant in the call, whatever its argument
# position). `kwonly.py`'s pattern is a NAME, so it cannot discharge that claim — this fixture is
# the control that keeps the stated contract from becoming a documented falsehood.
e711_write "$E711_FX" lib/test/kwstar.py "n = ROOT.${E711_TOK_G}(pattern=\"**/x.json\")"

# --- Shell arm fixtures. Every fixture above is `.py`, so without these the whole shell arm
# --- (fold_continuations, statements_in, the path-operand scan, ROOT_FRAGMENTS, the substring
# --- pre-filter) has no positive control and emptying it leaves the suite green. Heads and root
# --- fragments are assembled from parts for the same reason the Python tokens are: an assembled
# --- head keeps run.sh's own source below the guard's substring pre-filter, so no fixture line
# --- here becomes a candidate in the file that writes it.
E711_TOK_F="fi""nd"; E711_TOK_GR="gr""ep"; E711_RV="RO""OT"
e711_write "$E711_FX" lib/test/sh_find.sh "${E711_TOK_F} \"\$LIB/../skills\" -name x"
e711_write "$E711_FX" lib/test/sh_capture.sh "V=\"\$(${E711_TOK_GR} -rlF x \"\$DGH_${E711_RV}/lib\")\""
e711_write "$E711_FX" lib/test/sh_repo_root.sh "${E711_TOK_GR} -r x \"\$REPO_${E711_RV}/lib\""
e711_write "$E711_FX" lib/test/sh_marked.sh \
  "${E711_TOK_F} \"\$LIB/../skills\" -name x  # tree-walk-ok: scoped to a per-test sandbox"
e711_write "$E711_FX" lib/test/sh_nonroot.sh "${E711_TOK_GR} -rn z \"\$SOMEDIR\""
e711_write "$E711_FX" lib/test/sh_nonrecursive.sh "${E711_TOK_GR} -n z \"\$${E711_RV}/x\""
e711_write "$E711_FX" lib/test/sh_continued.sh \
  "V=\"\$(${E711_TOK_GR} -rlF x \\\\" \
  "  \"\$${E711_RV}/lib\")\""
# The three fail-open shapes the inline review fixed, each retained as a live regression control.
e711_write "$E711_FX" lib/test/sh_paramexp.sh "d=\${rel#*/}; ${E711_TOK_F} \"\$${E711_RV}\" -type f"
e711_write "$E711_FX" lib/test/sh_optvalue.sh \
  "V=\"\$(${E711_TOK_GR} -r --include '*.sh' NEEDLE \"\$${E711_RV}\")\""
e711_write "$E711_FX" lib/test/strmarker.py \
  "h = [\"# tree-walk-ok: not a comment\", root.${E711_TOK_R}('*.json')]"
# Head POSITION. The head is located through extract-command-heads.py's own classification, not
# assumed to be token 0; each shape below reported `audited 1 of 1 files` at exit 0 before that.
e711_write "$E711_FX" lib/test/sh_envprefix.sh "LC_ALL=C ${E711_TOK_GR} -rn needle \"\$${E711_RV}\""
e711_write "$E711_FX" lib/test/sh_wrapper.sh "timeout 5 ${E711_TOK_F} \"\$${E711_RV}\" -type f"
e711_write "$E711_FX" lib/test/sh_redirect.sh ">out ${E711_TOK_F} \"\$${E711_RV}\" -type f"
e711_write "$E711_FX" lib/test/sh_negated.sh "! ${E711_TOK_GR} -rq needle \"\$${E711_RV}\""
e711_write "$E711_FX" lib/test/sh_ifcond.sh "if ${E711_TOK_F} \"\$${E711_RV}\" -type f; then :; fi"
e711_write "$E711_FX" lib/test/sh_procsub.sh \
  "while IFS= read -r f; do :; done < <(${E711_TOK_F} \"\$${E711_RV}\" -type f)"
e711_write "$E711_FX" lib/test/sh_subshell.sh "(${E711_TOK_F} \"\$${E711_RV}\" -name sub)"
# Span acceptance on the Python side: the marker sits on the wrapped call's CLOSING line.
e711_write "$E711_FX" lib/test/pyspan.py \
  "j = ROOT.${E711_TOK_G}(" \
  "    \"**/y.json\"" \
  ")  # tree-walk-ok: scoped to a per-test sandbox"
# The long recursive flags and the operand-less cwd default: both are live arms with no other
# fixture, so narrowing _GREP_RECURSIVE or dropping the implicit `.` was previously invisible.
e711_write "$E711_FX" lib/test/sh_longflag.sh "${E711_TOK_GR} --recursive x \"\$${E711_RV}/lib\""
e711_write "$E711_FX" lib/test/sh_cwddefault.sh "${E711_TOK_GR} -rn NEEDLE"
# The unbalanced-quote fallback in _comment_split: this line's opening quote lives on the PREVIOUS
# physical line, so a quote-aware-only split would swallow the marker and report a declared walk.
e711_write "$E711_FX" lib/test/sh_markedcont.sh \
  "V=\"\$(${E711_TOK_F} \"\$${E711_RV}/lib\" \\\\" \
  "  -name x)\"  # tree-walk-ok: scoped to a per-test sandbox"
# is_audited's separator normalization: a backslash-form path still selects into the population.
e711_write "$E711_FX" lib/test/backslash.py "i = root.${E711_TOK_R}('*.json')"

# Planted-defect positive control — the assertion that discharges the guard-coverage claim.
assert_eq "#711 guard flags an unmarked walk in the audited population" "rc=1|lib/test/unmarked.py" \
  "$(e711_run "$E711_FX" lib/test/unmarked.py | python3 -c 'import re,sys
t = sys.stdin.read()
print("rc=%s|%s" % (re.match(r"rc=(\d+)", t).group(1),
                    ",".join(re.findall(r"^(\S+):\d+: undeclared", t.split("|",1)[1], re.M))))')"
assert_eq "#711 two violations in one file are reported once each, in line order" "rc=1|1,3" \
  "$(e711_run "$E711_FX" lib/test/dual.py | python3 -c 'import re,sys
t = sys.stdin.read()
print("rc=%s|%s" % (re.match(r"rc=(\d+)", t).group(1),
                    ",".join(re.findall(r"^\S+:(\d+): undeclared", t.split("|",1)[1], re.M))))')"
assert_eq "#711 two violating files exit non-zero once, reporting both" "rc=1|lib/test/dual.py,lib/test/dual.py,lib/test/second.py|2" \
  "$(e711_run "$E711_FX" lib/test/dual.py lib/test/second.py | python3 -c 'import re,sys
t = sys.stdin.read()
body = t.split("|", 1)[1]
print("|".join([
    "rc=" + re.match(r"rc=(\d+)", t).group(1),
    ",".join(re.findall(r"^(\S+):\d+: undeclared", body, re.M)),
    re.search(r"audited (\d+) of", body).group(1),
]))')"
assert_eq "#711 guard accepts a marked walk" "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/marked.py)"
assert_eq "#711 a bare tree-walk-ok substring does not exempt" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/nearmiss.py)"
assert_eq "#711 a marker with an empty reason does not exempt" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/emptyreason.py)"
assert_eq "#711 a walk token inside a comment is not a candidate" "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/commented.py)"
assert_eq "#711 a root-anchored glob with a ** component is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/starglob.py)"
assert_eq "#711 guard reports its audited count on the clean path" "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/clean.py)"
# An unparseable audited file has NOT been audited; reporting clean over it would be the same
# fail-open the guard exists to prevent, so it is a named skip and a non-zero exit.
assert_eq "#711 a keyword-literal ** pattern is still a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/kwstar.py)"
assert_eq "#711 an unparseable audited file is a named skip, not a silent pass" "yes" \
  "$(case "$(e711_run "$E711_FX" lib/test/broken.py)" in rc=0*) echo "no: exited 0" ;; *"SKIPPED lib/test/broken.py"*) echo yes ;; *) echo no ;; esac)"
# The OTHER skip arm — an unopenable path — reaches the same fail-closed exit through different
# code (_read's OSError arm, not the parse arm), so it needs its own control.
assert_eq "#711 an unreadable selected path is a named skip, not a silent pass" "yes" \
  "$(case "$(e711_run "$E711_FX" lib/test/no-such-file.py)" in rc=0*) echo "no: exited 0" ;; *"SKIPPED lib/test/no-such-file.py"*) echo yes ;; *) echo no ;; esac)"

# AST arm 2 (a non-literal pattern argument) and the per-line dedupe. Neither is reachable from
# any fixture above, so without these two assertions deleting either leaves the whole block green.
assert_eq "#711 a glob call whose pattern is not a literal is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/nonliteral.py)"
assert_eq "#711 a glob call with no positional pattern argument is not a candidate" \
  "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/kwonly.py)"
# The literal arm's two otherwise-uncovered members. The reason string is part of the comparand:
# it names the token that fired, so a fixture accidentally flagged by an AST arm instead cannot
# masquerade as the control this assertion claims to be.
assert_eq "#711 an iglob call with a plain literal pattern is a literal-arm candidate" \
  "rc=1|1:${E711_TOK_I}(" \
  "$(e711_run "$E711_FX" lib/test/iglob.py | python3 -c 'import re,sys
t = sys.stdin.read()
b = t.split("|",1)[1]
m = re.search(r"^\S+:(\d+): undeclared recursive walk \(`([^`]+)`\)", b, re.M)
print("rc=%s|%s" % (re.match(r"rc=(\d+)", t).group(1), "%s:%s" % m.groups() if m else "none"))')"
assert_eq "#711 a recursive= keyword glob is a literal-arm candidate" \
  "rc=1|1:${E711_TOK_RT}" \
  "$(e711_run "$E711_FX" lib/test/recursivekw.py | python3 -c 'import re,sys
t = sys.stdin.read()
b = t.split("|",1)[1]
m = re.search(r"^\S+:(\d+): undeclared recursive walk \(`([^`]+)`\)", b, re.M)
print("rc=%s|%s" % (re.match(r"rc=(\d+)", t).group(1), "%s:%s" % m.groups() if m else "none"))')"
# An unparseable file that ALSO carries a literal-arm walk reports BOTH — the finding is not
# discarded by the parse skip, so the author does not pay a second red run for a known violation.
assert_eq "#711 a parse skip still reports the literal-arm findings it already collected" \
  "rc=1|finding=1|skip=1" \
  "$(e711_run "$E711_FX" lib/test/brokenwalk.py | python3 -c 'import re,sys
t = sys.stdin.read()
b = t.split("|",1)[1]
print("|".join([
    "rc=" + re.match(r"rc=(\d+)", t).group(1),
    "finding=%d" % len(re.findall(r"^lib/test/brokenwalk\.py:\d+: undeclared", b, re.M)),
    "skip=%d" % len(re.findall(r"SKIPPED lib/test/brokenwalk\.py", b)),
]))')"
assert_eq "#711 one line reaching two arms is reported once" "rc=1|1" \
  "$(e711_run "$E711_FX" lib/test/dedupe.py | python3 -c 'import re,sys
t = sys.stdin.read()
print("rc=%s|%s" % (re.match(r"rc=(\d+)", t).group(1),
                    ",".join(re.findall(r"^\S+:(\d+): undeclared", t.split("|",1)[1], re.M))))')"

# --- Shell-arm assertions. The arm fires only on a `find`/`grep -r` whose path operand resolves
# --- to the repository root, so each shape below is asserted against its own negative control:
# --- emptying ROOT_FRAGMENTS, inverting the substring pre-filter, breaking fold_continuations, or
# --- narrowing the path-operand scan each turns one of these RED.
assert_eq "#711 a shell find over a repository-root path is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_find.sh)"
assert_eq "#711 a captured recursive grep over a repository-root path is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_capture.sh)"
# Named for what it measures: a $REPO_ROOT-spelled operand is a candidate. It is NOT a control
# for the REPO_ROOT tuple member, which `ROOT` subsumes as its own source comment concedes —
# dropping that member changes no verdict, by construction.
assert_eq "#711 a REPO_ROOT-spelled operand is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_repo_root.sh)"
assert_eq "#711 a line-continued recursive grep whose root operand wraps is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_continued.sh)"
assert_eq "#711 a marked shell walk is accepted" "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/sh_marked.sh)"
# The shell arm's documented complement, asserted so an over-wide fragment set goes RED here.
assert_eq "#711 a recursive grep rooted below the repository root is not a candidate" \
  "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/sh_nonroot.sh)"
assert_eq "#711 a non-recursive grep at the repository root is not a candidate" \
  "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/sh_nonrecursive.sh)"

# Three fail-open regressions the inline review found and fixed, each kept as a live control.
# Every one of them reported `audited 1 of 1 files` at exit 0 over a real undeclared walk.
assert_eq "#711 a shell parameter expansion does not hide the rest of its line" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_paramexp.sh)"
assert_eq "#711 an option taking a separated value does not hide the root operand" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_optvalue.sh)"
assert_eq "#711 marker text inside a string literal does not exempt the line" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/strmarker.py)"

# Head POSITION — six shapes that put something before the command. Each reported clean before
# the head was located through the shared classification, and each is one character of ordinary
# idiom away from the sites this suite already writes.
assert_eq "#711 a walk behind a leading env assignment is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_envprefix.sh)"
assert_eq "#711 a walk behind a process wrapper is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_wrapper.sh)"
assert_eq "#711 a walk behind a leading redirection is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_redirect.sh)"
assert_eq "#711 a negated walk is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_negated.sh)"
assert_eq "#711 a walk in a compound-command condition is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_ifcond.sh)"
assert_eq "#711 a walk inside a process substitution is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_procsub.sh)"
assert_eq "#711 a walk inside a bare subshell is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_subshell.sh)"
# The AST arms accept a declaration anywhere in a wrapped call's span (the shell analogue is
# sh_markedcont.sh). Several markers this change plants sit on wrapped calls, so the span logic
# is load-bearing on shipped code and was otherwise exercised only incidentally by the real tree.
assert_eq "#711 a marker on the closing line of a wrapped Python call is accepted" \
  "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/pyspan.py)"
# The two shell arms with no other fixture: the long recursive flag and the cwd default.
assert_eq "#711 a long-form recursive grep flag is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_longflag.sh)"
assert_eq "#711 an operand-less recursive grep defaults to the cwd and is a candidate" "rc=1" \
  "$(e711_rc "$E711_FX" lib/test/sh_cwddefault.sh)"
# The unbalanced-quote fallback: without it the marker on this continued statement is swallowed
# and a correctly-declared walk is reported — a false positive, the fallback's whole purpose.
assert_eq "#711 a marked walk on a quote-unbalanced continuation stays declared" \
  "rc=0|lint-tree-enumeration: audited 1 of 1 files" \
  "$(e711_run "$E711_FX" lib/test/sh_markedcont.sh)"
# Population selection normalizes separators, so a backslash-form path still selects in.
assert_eq "#711 a backslash-form path is not silently dropped from the population" "rc=1" \
  "$(e711_rc "$E711_FX" 'lib\test\backslash.py')"
# The --root default: with no flag and no git toplevel the helper must breadcrumb, never silently
# resolve against a wrong root (the #295 no-silent-default contract). Nothing else exercises it.
assert_eq "#711 an absent --root outside a repository breadcrumbs rather than defaulting silently" "yes" \
  "$(E711_NR="$(probe_tmp '#711 no-root cwd')"
     case "$E711_NR" in ""|/dev/null) echo yes; exit 0 ;; esac
     rm -f "$E711_NR"; mkdir -p "$E711_NR"
     E711_NROUT="$(cd "$E711_NR" && python3 "$E711_LINT" 2>&1)"
     rm -rf "$E711_NR" 2>/dev/null || true
     case "$E711_NROUT" in *"no git toplevel"*) echo yes ;; *) echo "no: $E711_NROUT" ;; esac)"

# Population selection: a path outside lib/test/ is excluded even while carrying a planted walk,
# and an all-excluded population is a zero tally at exit 0 — never confused with the fail-closed
# arms below, which is the confusion that would let an over-wide exclusion read as a clean audit.
assert_eq "#711 a path outside the audited population is excluded at exit 0" \
  "rc=0|lint-tree-enumeration: audited 0 of 0 files" \
  "$(e711_run_outcome "$E711_FX" other/outside.py)"
# The all-excluded NOTE is asserted on its own, by its stable identifying prefix rather than its
# full prose: "audited nothing" must not look like "audited everything, found nothing", but the
# sentence explaining that is free to be reworded without breaking the outcome assertions above.
assert_eq "#711 a fully-excluded population says so on stderr" "yes" \
  "$(case "$(e711_run "$E711_FX" other/outside.py)" in
       *"lint-tree-enumeration: note: all 1 enumerated path(s) were excluded"*) echo yes ;;
       *) echo no ;;
     esac)"

# Self-exclusion: the guard's own path is dropped from the population, so a list naming only it
# audits zero files. The real-tree clean run above is the other half of the same claim.
assert_eq "#711 the guard does not flag itself" \
  "rc=0|lint-tree-enumeration: audited 0 of 0 files" \
  "$(e711_run_outcome "$E711_FX" lib/test/lint-tree-enumeration.py)"

# Fail-closed arms, measured PRE-exclusion. Both halves of the #664 precedent are imported: a
# zero pre-exclusion population fails closed with its own breadcrumb, while a fully-excluded
# non-empty one is the legal `audited 0 of 0` above. Without the first half a wrong cwd or a
# non-repository root would make the guard audit nothing and report a clean pass.
E711_EMPTY="$(probe_tmp '#711 empty list')"
: > "$E711_EMPTY"
assert_eq "#711 an empty pre-exclusion enumeration fails closed" "yes" \
  "$(E711_OUT2="$(python3 "$E711_LINT" --root "$E711_FX" --files-from "$E711_EMPTY" 2>&1)"
     case "$?:$E711_OUT2" in 0:*) echo "no: exited 0" ;; *"yielded zero paths before any exclusion"*) echo yes ;; *) echo no ;; esac)"
case "$E711_EMPTY" in ""|/dev/null) : ;; *) rm -f "$E711_EMPTY" ;; esac   # probe_tmp sentinel: never rm /dev/null
assert_eq "#711 a non-repository root fails closed naming git ls-files" "yes" \
  "$(E711_SB="$(probe_tmp '#711 non-repo root')"
     # probe_tmp's mktemp-failure sentinel. It has ALREADY recorded a suite FAIL and its own
     # breadcrumb, so the run is red either way; short-circuiting here avoids `rm -f /dev/null`
     # (which under root would delete the device node) and a second, misattributed failure.
     case "$E711_SB" in ""|/dev/null) echo yes; exit 0 ;; esac
     rm -f "$E711_SB"; mkdir -p "$E711_SB"
     E711_OUT3="$(python3 "$E711_LINT" --root "$E711_SB" 2>&1)"
     E711_RC3=$?
     rmdir "$E711_SB" 2>/dev/null || true
     case "$E711_RC3:$E711_OUT3" in 0:*) echo "no: exited 0" ;; *"git ls-files exited"*) echo yes ;; *) echo no ;; esac)"

# The guard is a pure read: running it twice over the same population yields byte-identical output.
assert_eq "#711 the guard is idempotent over one population" "same" \
  "$([ "$(e711_run "$E711_FX" lib/test/clean.py)" = "$(e711_run "$E711_FX" lib/test/clean.py)" ] && echo same || echo differ)"
case "$E711_FX" in ""|/dev/null) : ;; *) rm -rf "$E711_FX" ;; esac   # probe_tmp sentinel: never rm -rf /dev/null

# Documentation surfaces. The rule's behavioral guarantee is carried by the guard's own
# fixture-driven assertions above, not by a prose-removal check — the pin below states the
# enumeration-source convention its ledger row records, and its declaration says so.
assert_pin_unique "#711 CLAUDE.md carries the enumeration-source rule" \
  'sources its population from an index-reading `git ls-files`' "$E711_CLAUDE"  # structural-pin-ok: helper-contract -- the root convention requires index-based enumeration so a check stays invariant across repository layouts
assert_eq "#711 the growth artifact exists" "yes" \
  "$([ -f "$E711_GROWTH" ] && echo yes || echo no)"

# ────────────────────────────────────────────────────────────────────────────
# Windows-uncheckoutable tracked-path guard (lib/test/lint-windows-uncheckoutable-path.py).
# The plugin `source` is `./`, so the whole repository is cloned by every consumer; git's
# Windows reserved-name/path validation is compiled OUT on the linux/macOS platforms we test
# on, so a path that aborts every Windows clone ships green here (issue #1196). The guard is a
# member of the desk-time static-lint family (extract-command-heads.py, pin-corpus-lint.py,
# lint-gh-api-repo-path.py, lint-tree-enumeration.py, …) and is driven the same way: the real
# tree as the live gate, plus the real pre-fix tree and synthetic fixtures via --files-from.
# ────────────────────────────────────────────────────────────────────────────
echo "#1196 Windows-uncheckoutable tracked-path guard"
E1196_LINT="$LIB/test/lint-windows-uncheckoutable-path.py"

# Real tree: clean, AND a positive audited tally so a collapsed enumeration (a broken
# population, an ls-files that yielded nothing) cannot read as clean. Comparand is the exit
# code alone — the audited count drifts with every file added, so the positive-tally check is
# a SEPARATE assertion reading the same rc=0 run.
E1196_OUT="$(python3 "$E1196_LINT" --root "$LIB/.." 2>&1)"; E1196_RC=$?
assert_eq "#1196 the real tree audits clean" "rc=0" \
  "$([ "$E1196_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$E1196_RC" "$E1196_OUT")"
assert_eq "#1196 the real-tree run audited a positive number of paths" "yes" \
  "$(printf '%s' "$E1196_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) tracked", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"

# Fixture driver — feed a synthetic path list through --files-from (never plant a reserved-name
# file on disk: a tracked nul.md would re-break every Windows clone while the guard reported
# green, the exact incident this guard prevents). Prints "rc=<n>|<stdout+stderr>".
e1196_run() {  # <path…>  -> "rc=<n>|<output>"
  local list out rc
  list="$(probe_tmp '#1196 fixture list')" || list=""
  case "$list" in
    ""|/dev/null) printf 'rc=probe-unavailable|fixture list could not be allocated'; return 0 ;;
  esac
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$E1196_LINT" --root "$LIB/.." --files-from "$list" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
e1196_rc() {  # <path…> -> prints just "rc=<n>"
  # Pure parameter expansion strips everything from the FIRST `|` on (greedy `%%`), so a
  # multi-line RED report after the `rc=<n>|` prefix is dropped cleanly — never `cut`, whose
  # per-line split would leak the report lines AND which is a non-preflight PATH tool this
  # assertion-deciding value must not depend on (CLAUDE.md guard-class 2).
  local out; out="$(e1196_run "$@")"
  printf '%s' "${out%%|*}"
}

# Historical regression case (AC4): the pre-fix parent 5179c5a1 of merge 1753565e tracks
# lib/test/fixtures/shipped-pruned-path/skills/nul.md — a real positive case, not synthetic.
# Fed from that tree's own path list (git ls-tree), so no Windows host and no checkout of the
# offending path is needed. Self-skips when the commit is unreachable (a shallow local clone);
# CI checks out full history (fetch-depth: 0), so the gate runs there.
if git cat-file -e 5179c5a1 2>/dev/null; then
  E1196_HIST_LIST="$(probe_tmp '#1196 historical path list')" || E1196_HIST_LIST=""
  case "$E1196_HIST_LIST" in
    ""|/dev/null) E1196_HIST="rc=probe-unavailable|list unallocatable" ;;
    *)
      # Guard the ls-tree rc AND a non-empty result: an empty/truncated list would make the
      # guard raise EnumerationError (rc=1), and the "goes RED" assertion below matches "rc=1|"
      # — so an unchecked degraded ls-tree would pass assertion 1 for the WRONG reason
      # (enumeration-unusable, not a detected reserved name). Route that to a sentinel that
      # matches neither "rc=1|" nor the fixture-name test, so both assertions fail on the real
      # cause instead of one passing coincidentally.
      # `-c core.quotePath=false` for the same reason the guard's own live enumeration carries
      # it: under git's default a non-ASCII path is emitted C-QUOTED, and the guard would flag
      # the escape backslashes as a backslash-in-path violation. This tree's path of interest
      # is ASCII, so the flag changes nothing observable here today — it is carried so the two
      # enumerations that feed this guard cannot disagree about what a path looks like.
      if git -c core.quotePath=false ls-tree -r 5179c5a1 --name-only > "$E1196_HIST_LIST" 2>/dev/null && [ -s "$E1196_HIST_LIST" ]; then
        E1196_HIST_OUT="$(python3 "$E1196_LINT" --root "$LIB/.." --files-from "$E1196_HIST_LIST" 2>&1)"
        E1196_HIST_RC=$?
        E1196_HIST="rc=$E1196_HIST_RC|$E1196_HIST_OUT"
      else
        E1196_HIST="rc=hist-list-unavailable|git ls-tree produced no path list for 5179c5a1"
      fi
      rm -f "$E1196_HIST_LIST"
      ;;
  esac
  assert_eq "#1196 the pre-fix tree 5179c5a1 goes RED" "yes" \
    "$(case "$E1196_HIST" in "rc=1|"*) echo yes ;; *) echo "no: $E1196_HIST" ;; esac)"
  assert_eq "#1196 the pre-fix RED names the reserved-name fixture" "yes" \
    "$(case "$E1196_HIST" in *"lib/test/fixtures/shipped-pruned-path/skills/nul.md"*) echo yes ;; *) echo "no: $E1196_HIST" ;; esac)"
else
  # BOTH historical assertions self-skip together — the #456 registered-check population must
  # be stable across environments, so a shallow clone must report the same two check names a
  # full-history clone reports, one per skip line, rather than silently dropping the second.
  skip "#1196 the pre-fix tree 5179c5a1 goes RED" host-capability \
    "commit 5179c5a1 is unreachable in this checkout (shallow clone); CI runs with full history"
  skip "#1196 the pre-fix RED names the reserved-name fixture" host-capability \
    "commit 5179c5a1 is unreachable in this checkout (shallow clone); CI runs with full history"
fi

# Mutation check (AC5): every rule the guard implements, one synthetic violating path each. A
# component judged by a rule must go RED; the same set with the offending path removed is GREEN.
assert_eq "#1196 mutation: reserved stem with an extension (nul.md)" "rc=1" "$(e1196_rc skills/nul.md)"
assert_eq "#1196 mutation: bare reserved stem (nul)" "rc=1" "$(e1196_rc skills/nul)"
assert_eq "#1196 mutation: reserved stem in a NON-final component (nul/x.md)" "rc=1" "$(e1196_rc skills/nul/x.md)"
# These two cases each have a violating input that a SECOND, independent rule also catches,
# so an exit-code comparand passes them for the wrong reason (the PR #1201 review's finding
# 1): `:` is independently a member of _FORBIDDEN_CHARS, and a trailing space is independently
# caught by the trailing-space arm — so `nul:ads` and `nul ` both stay rc=1 with the
# reserved-name rule's terminator handling (its `:` terminator and its trailing-space skip)
# deleted outright. Measured before this change: with both deleted, the whole block was green.
# The discriminating comparand is the REASON the guard reports, which names the rule that
# actually fired. Under that deletion it becomes forbidden-character(':') / trailing-space
# instead of reserved-device-name(NUL), so these two go RED where the exit code could not.
# `rc=1|` is matched too, so each still subsumes the exit-code check it replaces.
E1196_TSP="$(e1196_run 'skills/nul ')"
assert_eq "#1196 mutation: reserved stem with a trailing space (nul ) fires the RESERVED-NAME rule" "yes" \
  "$(case "$E1196_TSP" in "rc=1|"*"'nul ' reserved-device-name(NUL)"*) echo yes ;; *) echo "no: $E1196_TSP" ;; esac)"
E1196_ADS="$(e1196_run skills/nul:ads)"
assert_eq "#1196 mutation: reserved name followed by : (nul:ads) fires the RESERVED-NAME rule" "yes" \
  "$(case "$E1196_ADS" in "rc=1|"*"'nul:ads' reserved-device-name(NUL)"*) echo yes ;; *) echo "no: $E1196_ADS" ;; esac)"
# A `:` in a NON-reserved component reaches the forbidden-character arm (nul:ads above is caught
# by the reserved-device branch first), so this is the case that goes RED if `:` were dropped
# from _FORBIDDEN_CHARS — and it is the DOS-drive-prefix protection the guard subsumes via `:`.
assert_eq "#1196 mutation: forbidden : in a non-reserved component (DOS-drive-prefix class)" "rc=1" "$(e1196_rc skills/a:b.md)"
assert_eq "#1196 mutation: CONIN\$ reserved name" "rc=1" "$(e1196_rc 'skills/CONIN$')"
assert_eq "#1196 mutation: component with a trailing dot (foo.)" "rc=1" "$(e1196_rc skills/foo./x.md)"
assert_eq "#1196 mutation: component with a trailing space (foo )" "rc=1" "$(e1196_rc 'skills/foo /x.md')"
assert_eq "#1196 mutation: forbidden character (<)" "rc=1" "$(e1196_rc 'skills/a<b.md')"
assert_eq "#1196 mutation: control character (0x01)" "rc=1" "$(e1196_rc "$(printf 'skills/a\001b.md')")"
assert_eq "#1196 mutation: backslash in path" "rc=1" "$(e1196_rc 'docs/a\b.md')"
# Removing the offending path leaves a clean population (RED→GREEN, the AC5 pairing).
assert_eq "#1196 mutation: the same set MINUS the violation is GREEN" "rc=0" \
  "$(e1196_rc skills/normal.md docs/readme.md)"

# Negative controls (AC6): look-alikes that must NOT be flagged.
assert_eq "#1196 negative controls are not flagged" "rc=0" \
  "$(e1196_rc skills/nulls.md skills/console.md skills/common.md skills/com0.md skills/a.b.c.md)"

# COM/LPT asymmetry (AC7), demonstrated in BOTH directions: com0 not flagged, lpt0 flagged.
assert_eq "#1196 asymmetry: com0.md is NOT flagged" "rc=0" "$(e1196_rc skills/com0.md)"
assert_eq "#1196 asymmetry: lpt0.md IS flagged" "rc=1" "$(e1196_rc skills/lpt0.md)"
# ...plus the POSITIVE half of the COM range (the PR #1201 review's finding 2). com0 being
# clean pins only where the range STARTS: a regression that emptied _RESERVED_STEMS of every
# COM member would leave BOTH assertions above passing, since neither reads a reserved COM.
# The comparand is the guard's own violation TALLY over all nine, not the exit code — rc=1
# over a nine-path list is satisfied by a single surviving member, so one hit could carry the
# whole set; `9 violation(s)` cannot be satisfied by fewer than nine.
E1196_COM="$(e1196_run skills/com1.md skills/com2.md skills/com3.md skills/com4.md skills/com5.md \
                       skills/com6.md skills/com7.md skills/com8.md skills/com9.md)"
assert_eq "#1196 asymmetry: every one of COM1-COM9 IS flagged" "yes" \
  "$(case "$E1196_COM" in *"audited 9 tracked path(s), 9 violation(s)"*) echo yes ;; *) echo "no: $E1196_COM" ;; esac)"

# ── Path-quoting regression (PR #1201 review finding 1) ──────────────────────
# `core.quotePath` defaults to TRUE, under which git emits a non-ASCII path in C-QUOTED form:
# a legal, Windows-checkout-able `café.md` comes out as the literal string `"caf\303\251.md"`
# — surrounding double quotes and backslash escapes that are not in the path. Fed to the
# guard, that string trips its absolute backslash rule, so the first legitimately-named
# non-ASCII tracked path anyone commits would take the WHOLE SUITE RED for a character the
# path does not contain, and this guard deliberately ships no declaration marker to wave
# it through.
# The guard therefore enumerates with `core.quotePath=false`.
#
# Two assertions, covering the two halves separately:
#   (a) the JUDGEMENT half — an unquoted non-ASCII path string is clean. Reached via
#       --files-from, which bypasses the enumeration entirely, so this one holds with or
#       without the flag; it pins the intended verdict the enumeration must deliver.
#   (b) the ENUMERATION half — the guard run over a real repository whose index carries such
#       a path. This is the seam --files-from cannot reach, and it is RED without the flag.
assert_eq "#1196 negative control: an unquoted non-ASCII path is not flagged" "rc=0" \
  "$(e1196_rc "$(printf 'docs/caf\303\251.md')" skills/normal.md)"

# (b) is driven through a THROWAWAY git repo (git_sandbox — never the real one) because it is
# a property of the live `git ls-files` call. The fixture name is ordinary and fully
# Windows-checkout-able, so nothing exotic is planted anywhere: the no-reserved-name-on-disk
# rule above is about the violating names this guard hunts, not about non-ASCII text.
E1196_SB="$(git_sandbox '#1196 non-ASCII enumeration sandbox')" || E1196_SB=""
case "$E1196_SB" in
  ""|/dev/null*) E1196_NA="rc=sandbox-unavailable|git_sandbox allocated no usable directory" ;;
  *)
    # Octal escapes rather than a literal é: the bytes under test are fixed here instead of
    # being inherited from whatever encoding this file is read with.
    E1196_NA_NAME="$(printf 'caf\303\251.md')"
    if git -C "$E1196_SB" init -q 2>/dev/null &&
       printf 'x\n' > "$E1196_SB/$E1196_NA_NAME" 2>/dev/null &&
       git -C "$E1196_SB" add -A -f >/dev/null 2>&1; then
      E1196_NA_OUT="$(python3 "$E1196_LINT" --root "$E1196_SB" 2>&1)"; E1196_NA_RC=$?
      E1196_NA="rc=$E1196_NA_RC|$E1196_NA_OUT"
    else
      # A setup that did not complete must not read as a pass: route it to a sentinel that
      # is not "rc=0", so the assertion goes RED naming the real cause.
      E1196_NA="rc=sandbox-setup-failed|could not stage the non-ASCII fixture in the sandbox"
    fi
    rm -rf "$E1196_SB"
    ;;
esac
assert_eq "#1196 the live enumeration does not flag a legally-named non-ASCII tracked path" \
  "rc=0" "${E1196_NA%%|*}"
# The population was really established — an EnumerationError would also have to be excluded
# before "rc=0" could be read as "the path was judged and found clean", but rc=0 is only
# reachable through a non-empty population, so assert the tally the run actually reported.
assert_eq "#1196 the non-ASCII sandbox run audited its one tracked path" "yes" \
  "$(case "$E1196_NA" in *"audited 1 tracked path(s), 0 violation(s)"*) echo yes ;; *) echo "no: $E1196_NA" ;; esac)"

# Fail-closed on an unestablished population (AC8): an empty --files-from list must be a
# non-zero "enumeration unusable", never a clean pass — "audited nothing" ≠ "found nothing".
E1196_EMPTY="$(probe_tmp '#1196 empty population')" || E1196_EMPTY=""
case "$E1196_EMPTY" in
  # probe_tmp has already recorded its own allocation FAIL, so this host is not silently
  # green — but the NAMED check below would still vanish from the registered-check
  # population here, and the #456 rule is that the population stays STABLE across
  # environments: a host that cannot allocate scratch must report the same check name a
  # host that can does. Emit it through the sole sanctioned skip emitter (the same way the
  # historical block above handles its unreachable-commit host), rather than dropping it.
  ""|/dev/null)
     skip "#1196 an empty population fails closed (not a clean pass)" host-capability \
       "probe_tmp allocated no usable scratch file for the empty --files-from list" ;;
  *) : > "$E1196_EMPTY"
     E1196_EOUT="$(python3 "$E1196_LINT" --root "$LIB/.." --files-from "$E1196_EMPTY" 2>&1)"; E1196_ERC=$?
     rm -f "$E1196_EMPTY"
     assert_eq "#1196 an empty population fails closed (not a clean pass)" "yes" \
       "$(case "$E1196_ERC:$E1196_EOUT" in 0:*) echo "no: exited 0" ;; *"enumeration unusable"*) echo yes ;; *) echo "no: $E1196_ERC|$E1196_EOUT" ;; esac)"
     ;;
esac


# ────────────────────────────────────────────────────────────────────────────
# Shared-population PATH-QUOTING regression (issue #1217).
# `core.quotePath` defaults to ON, so `git ls-files` renders a tracked non-ASCII path in
# C-quoted form: a legal `café.md` comes back as the literal string `"caf\303\251.md"`.
# That string names no real file, and the lints sharing `lib/test/lint_population.py`
# mishandled it in two distinct ways, so BOTH classes are pinned here:
#   * SILENT-DROP — a lint selecting by path PREFIX stops recognising the file (git puts
#     the opening quote at the FRONT of the whole path, so `lib/test/café.py` becomes
#     `"lib/test/caf\303\251.py"`, which no longer starts with `lib/test/`). It drops the
#     file before opening it, reports `audited 0 of 0` and exits 0 — a FALSE CLEAN. The
#     comparand here is therefore the lint's own audited TALLY, never its exit code: the
#     buggy behaviour already exits 0, so an exit-code assertion could not go RED first.
#   * HARD-FAIL — a lint selecting everything MINUS an exclusion list keeps the string,
#     fails to open it, records a skip and exits 1 — a FALSE RED for a character the path
#     does not contain, which would take the whole suite (and CI's required check) down
#     until someone renamed a perfectly legal file.
# Both are driven through a THROWAWAY git repo (git_sandbox — never the real one) because
# each is a property of the live `git ls-files` call, which `--files-from` bypasses
# entirely. The fixture name is built from `printf` octal escapes so the bytes under test
# are fixed here rather than inherited from whatever encoding this file is read with, and
# NO exotically-named file is committed to this repository (issue #1196).
echo "#1217 shared-population path-quoting"
E1217_SB="$(git_sandbox '#1217 path-quoting sandbox')" || E1217_SB=""
E1217_DROP="rc=sandbox-unavailable|git_sandbox allocated no usable directory"
E1217_HARD="$E1217_DROP"
case "$E1217_SB" in
  ""|/dev/null*) : ;;
  *)
    E1217_NAME="$(printf 'caf\303\251')"
    # `core.quotePath` defaults to true, but it is a SETTABLE option: on a host that sets it
    # false globally the pre-fix behaviour is unreproducible and every assertion below would
    # pass with the splice deleted — a RED-first claim silently degrading to a tautology.
    # Pin the defect precondition in the sandbox's own config rather than inheriting it. The
    # command-line `-c core.quotePath=false` still wins over a repo-local setting, so only the
    # negative control is affected, never the post-fix assertion.
    if git -C "$E1217_SB" init -q 2>/dev/null &&
       git -C "$E1217_SB" config core.quotePath true 2>/dev/null &&
       mkdir -p "$E1217_SB/lib/test" "$E1217_SB/scripts" 2>/dev/null &&
       printf 'x\n' > "$E1217_SB/lib/test/$E1217_NAME.py" 2>/dev/null &&
       printf 'x\n' > "$E1217_SB/scripts/$E1217_NAME.sh" 2>/dev/null &&
       git -C "$E1217_SB" add -A -f >/dev/null 2>&1; then
      E1217_DOUT="$(python3 "$LIB/test/lint-tree-enumeration.py" --root "$E1217_SB" 2>&1)"
      E1217_DROP="rc=$?|$E1217_DOUT"
      E1217_HOUT="$(python3 "$LIB/test/lint-gh-api-repo-path.py" --root "$E1217_SB" 2>&1)"
      E1217_HARD="rc=$?|$E1217_HOUT"
    else
      # A setup that did not complete must not read as a pass: route it to a sentinel that
      # is neither "rc=0" nor a matching tally, so each assertion goes RED naming the cause.
      E1217_DROP="rc=sandbox-setup-failed|could not stage the non-ASCII fixtures in the sandbox"
      E1217_HARD="$E1217_DROP"
    fi
    rm -rf "$E1217_SB"
    ;;
esac
# SILENT-DROP class. The tally is the discriminating comparand (see above): before the fix
# this reads `audited 0 of 0 files` at rc=0, which no exit-code assertion can distinguish
# from a clean run.
assert_eq "#1217 silent-drop class: the non-ASCII tracked path is actually audited" "yes" \
  "$(case "$E1217_DROP" in *"audited 1 of 1 files"*) echo yes ;; *) echo "no: $E1217_DROP" ;; esac)"
assert_eq "#1217 silent-drop class: the run still exits clean" "rc=0" "${E1217_DROP%%|*}"
# HARD-FAIL class. Here the exit code IS discriminating — rc=1 before the fix — and the
# tally is asserted too so a run that exits 0 having audited nothing cannot satisfy it.
assert_eq "#1217 hard-fail class: no false RED for a character the path does not contain" "rc=0" \
  "${E1217_HARD%%|*}"
assert_eq "#1217 hard-fail class: the path was audited rather than skipped" "yes" \
  "$(case "$E1217_HARD" in *SKIPPED*) echo "no (skipped): $E1217_HARD" ;; *"audited 1 of 1 files"*) echo yes ;; *) echo "no: $E1217_HARD" ;; esac)"
# Two more enumeration classes are exercised BEHAVIOURALLY rather than by a source-shape
# grep, because a grep over a Python literal breaks on a cosmetic reformat while passing if
# the constant later loses the flag — and because a source-presence pin is what issue #810
# prohibits. Both classes reinstate the original defect when their splice is deleted, with
# nothing else in the suite noticing:
#   * lint-subagent-dispatch-namespace.py's audited-surface argv (the second of the two
#     formerly-inline argvs a constants-only fix would have missed, issue #1217 AC3). Its
#     `is_audited` selects by the `skills/` prefix, so a C-quoted surface drops and the
#     tally falls to `audited 0 prompt surfaces` — the same silent-drop shape as above.
#   * coverage_map_guard.py's `_git_tracked` AND `_git_executable`, two of the non-reader call
#     sites that splice QUOTE_PATH_OFF by hand. Both are called directly (they are importable
#     helpers) and their RETURNED PATHS are the comparand: pre-fix each is the C-quoted
#     spelling. `_git_executable` is driven as well as `_git_tracked` because its own docstring
#     states the concrete regression — its mode row must still join against `_git_tracked`'s
#     path — and a splice deleted from only one of the two silently breaks that join, grading a
#     non-ASCII coverage-map-referenced script as non-executable rather than unestablished.
#     pin-corpus-lint.py's three splices are deliberately NOT driven here (they need a far
#     richer sandbox); lint_population.py's docstring records that they are review-gated.
E1217_SB2="$(git_sandbox '#1217 non-reader splice sandbox')" || E1217_SB2=""
E1217_NS="rc=sandbox-unavailable|git_sandbox allocated no usable directory"
E1217_CMG="sandbox-unavailable"
case "$E1217_SB2" in
  ""|/dev/null*) : ;;
  *)
    # Same host-independence pin as the sandbox above.
    if git -C "$E1217_SB2" init -q 2>/dev/null &&
       git -C "$E1217_SB2" config core.quotePath true 2>/dev/null &&
       mkdir -p "$E1217_SB2/skills" "$E1217_SB2/bin" 2>/dev/null &&
       printf 'no qualified ids here\n' > "$E1217_SB2/skills/$(printf 'caf\303\251').md" 2>/dev/null &&
       printf '#!/bin/sh\n' > "$E1217_SB2/bin/$(printf 'caf\303\251').sh" 2>/dev/null &&
       chmod +x "$E1217_SB2/bin/$(printf 'caf\303\251').sh" 2>/dev/null &&
       git -C "$E1217_SB2" add -A -f >/dev/null 2>&1; then
      E1217_NSOUT="$(python3 "$LIB/test/lint-subagent-dispatch-namespace.py" --root "$E1217_SB2" 2>&1)"
      E1217_NS="rc=$?|$E1217_NSOUT"
      # `_git_tracked` is imported and called directly; the assertion is that the returned
      # path is the RAW spelling, i.e. it does not begin with git's C-quoting double quote.
      E1217_CMG="$(E1217_SB2="$E1217_SB2" python3 -c '
import importlib.util, os, sys
from pathlib import Path
s = importlib.util.spec_from_file_location("g", sys.argv[1])
g = importlib.util.module_from_spec(s); s.loader.exec_module(g)
root = Path(os.environ["E1217_SB2"])
tracked = g._git_tracked(root)
execs = g._git_executable(root)
q = chr(34)
bad = [p for p in tracked if p.startswith(q)] + [p for p in (execs or ()) if p.startswith(q)]
if bad:
    print("quoted: %r" % (bad,))
elif execs is None:
    print("exec-unestablished")
elif not (set(execs) <= set(tracked)) or not execs:
    print("join-broken: tracked=%r execs=%r" % (tracked, sorted(execs)))
else:
    print("raw")
' "$LIB/test/coverage_map_guard.py" 2>&1)"
    else
      E1217_NS="rc=sandbox-setup-failed|could not stage the non-ASCII prompt surface"
      E1217_CMG="sandbox-setup-failed"
    fi
    rm -rf "$E1217_SB2"
    ;;
esac
assert_eq "#1217 the dispatch-namespace audited-surface argv enumerates the non-ASCII surface" "yes" \
  "$(case "$E1217_NS" in *"audited 1 prompt surface"*) echo yes ;; *) echo "no: $E1217_NS" ;; esac)"
assert_eq "#1217 coverage_map_guard returns raw paths and its mode row still joins against them" \
  "raw" "$E1217_CMG"
# The AC8 claim (the flag alters only how a path is PRINTED, so the index-reading argv
# acquired no `--others`) is pinned by the #724 preset assertion further down, which
# already reported `index-has-others=False` and gained a `quote-off=True` conjunct in the
# same change, from a module load it already performs. Asserting it a second time here
# would only pay a second `python3` start for a signal that block already carries.
# ────────────────────────────────────────────────────────────────────────────
# Subagent DISPATCH-NAMESPACE guard (lib/test/lint-subagent-dispatch-namespace.py).
# A qualified subagent id in prompt prose is a dispatch string whose namespace half is
# the plugin name, so a plugin rename that misses one ships a review engine whose
# reviewers resolve to nothing — a `coverage: "not_verified"` verdict with no
# diagnosis, not a loud failure. Unlike the agent_overrides config keys (a closed
# allowlist that accepts every declared namespace), dispatch accepts the canonical
# namespace only, and this is the sole check that reads it.
# ────────────────────────────────────────────────────────────────────────────
echo "subagent dispatch-namespace guard"
DNS_LINT="$LIB/test/lint-subagent-dispatch-namespace.py"

# Real-tree run: clean, AND a positive surface tally so a collapsed audit (a broken
# population, an is_audited that matches nothing) cannot read as clean.
DNS_OUT="$(python3 "$DNS_LINT" --root "$LIB/.." 2>&1)"; DNS_RC=$?
assert_eq "dispatch-ns: clean on the tree as it stands" "rc=0" \
  "$([ "$DNS_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$DNS_RC" "$DNS_OUT")"
assert_eq "dispatch-ns: the real-tree run audited a positive number of prompt surfaces" "yes" \
  "$(printf '%s' "$DNS_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) prompt", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"

# Positive control: a prompt surface carrying a STALE-namespace dispatch id must go
# red. Without this the clean run above is unfalsifiable — an audit that flags nothing
# ever would satisfy it. The fixture supplies only the surface; the dispatchable-leaf
# set and the canonical namespace come from the real plugin, so the fixture needs no
# agents/ tree of its own. The stale namespace is composed at runtime from the real
# alias namespace rather than hardcoded, so this control cannot rot into a tautology
# if the alias set changes.
DNS_FIXROOT="$(git_sandbox 'dispatch-ns fixture root')"
mkdir -p "$DNS_FIXROOT/skills/fixture" 2>/dev/null
# The alias namespace (the declared non-canonical one) is by definition a namespace
# that does not dispatch — exactly what the guard must reject. Both namespaces are
# read from the identity reader rather than hardcoded, so this control cannot rot
# into a tautology if the declared set changes.
DNS_ALIAS="$(python3 "$LIB/plugin_identity.py" --agent-namespaces 2>/dev/null | tail -n1)"
DNS_CANON="$(python3 "$LIB/plugin_identity.py" --agent-namespaces 2>/dev/null | head -n1)"
assert_eq "dispatch-ns: the fixture's two namespaces resolved and differ" "yes" \
  "$([ -n "$DNS_ALIAS" ] && [ -n "$DNS_CANON" ] && [ "$DNS_ALIAS" != "$DNS_CANON" ] && echo yes || echo no)"
printf '%s\n' 'skills/fixture/SKILL.md' > "$DNS_FIXROOT/list.txt" 2>/dev/null
dns_run() {  # <namespace> <leaf> -> "rc=<n>|<output>"
  local out rc
  printf 'Dispatch %s%s now.\n' "$1" "$2" > "$DNS_FIXROOT/skills/fixture/SKILL.md" 2>/dev/null
  out="$(python3 "$DNS_LINT" --root "$DNS_FIXROOT" --files-from "$DNS_FIXROOT/list.txt" 2>&1)"
  rc=$?
  printf 'rc=%s|%s' "$rc" "$out"
}
DNS_BAD="$(dns_run "$DNS_ALIAS" code-reviewer)"
assert_eq "dispatch-ns: a stale-namespace dispatch id in a prompt surface goes red" "nonzero" \
  "$(case "$DNS_BAD" in 'rc=0|'*) printf 'ZERO | %s' "$DNS_BAD" ;; *) printf 'nonzero' ;; esac)"
assert_eq "dispatch-ns: the diagnosis names the offending id and the remedy" "yes" \
  "$(printf '%s' "$DNS_BAD" | grep -qF "${DNS_ALIAS}code-reviewer" \
     && printf '%s' "$DNS_BAD" | grep -qF "${DNS_CANON}code-reviewer" \
     && echo yes || echo no)"
# Negative control on the SAME fixture: the canonical namespace is accepted, so the
# red above is the namespace VERDICT and not merely "the fixture surface was read".
assert_eq "dispatch-ns: the same surface with the canonical namespace is clean" "rc=0" \
  "$(printf '%s' "$(dns_run "$DNS_CANON" code-reviewer)" | sed -n 's/^\(rc=[0-9]*\)|.*/\1/p')"
# A leaf that is NOT dispatchable stays out of scope even under the alias namespace —
# this is what keeps plain skill/command references from being swept into the gate.
assert_eq "dispatch-ns: a non-dispatchable leaf under the alias namespace is not flagged" "rc=0" \
  "$(printf '%s' "$(dns_run "$DNS_ALIAS" some-unrelated-slug)" | sed -n 's/^\(rc=[0-9]*\)|.*/\1/p')"

# ── The PROMPT-EXTENSION half of the audited population (is_audited's _EXTENSION_RE).
# Every control above drives a skills/**/SKILL.md surface, and the real-tree tally
# asserts only `audited > 0` — which the skills population satisfies on its own. So a
# typo or path-shape regression in _EXTENSION_RE would silently stop auditing
# .prflow/prompt-extensions/*.md, which ARE dispatch-carrying surfaces, while every
# assertion here stayed green: the same silent `coverage: "not_verified"` failure this
# guard exists to prevent, occurring inside the guard itself. Driven with its own
# fixture surface so the branch has a positive control and a negative twin.
DNS_EXT_REL='.prflow/prompt-extensions/fixture-ext.md'
mkdir -p "$DNS_FIXROOT/.prflow/prompt-extensions" 2>/dev/null
printf '%s\n' "$DNS_EXT_REL" > "$DNS_FIXROOT/ext-list.txt" 2>/dev/null
dns_run_ext() {  # <namespace> <leaf> -> "rc=<n>|<output>"
  local out rc
  printf 'Dispatch %s%s now.\n' "$1" "$2" > "$DNS_FIXROOT/$DNS_EXT_REL" 2>/dev/null
  out="$(python3 "$DNS_LINT" --root "$DNS_FIXROOT" --files-from "$DNS_FIXROOT/ext-list.txt" 2>&1)"
  rc=$?
  printf 'rc=%s|%s' "$rc" "$out"
}
DNS_EXT_BAD="$(dns_run_ext "$DNS_ALIAS" code-reviewer)"
assert_eq "dispatch-ns: a stale-namespace dispatch id in a PROMPT EXTENSION goes red" "nonzero" \
  "$(case "$DNS_EXT_BAD" in 'rc=0|'*) printf 'ZERO | %s' "$DNS_EXT_BAD" ;; *) printf 'nonzero' ;; esac)"
assert_eq "dispatch-ns: the prompt-extension diagnosis names the offending id and the remedy" "yes" \
  "$(printf '%s' "$DNS_EXT_BAD" | grep -qF "${DNS_ALIAS}code-reviewer" \
     && printf '%s' "$DNS_EXT_BAD" | grep -qF "${DNS_CANON}code-reviewer" \
     && echo yes || echo no)"
DNS_EXT_OK="$(dns_run_ext "$DNS_CANON" code-reviewer)"
assert_eq "dispatch-ns: the same PROMPT EXTENSION with the canonical namespace is clean" "rc=0" \
  "$(printf '%s' "$DNS_EXT_OK" | sed -n 's/^\(rc=[0-9]*\)|.*/\1/p')"
# Non-vacuity for the clean arm: rc=0 alone cannot tell "read and accepted" from "never
# entered the population at all", which is precisely the regression being guarded.
assert_eq "dispatch-ns: the prompt-extension surface really entered the audited population" "yes" \
  "$(printf '%s' "$DNS_EXT_OK" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) prompt", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"
rm -rf "$DNS_FIXROOT"
unset DNS_LINT DNS_OUT DNS_RC DNS_FIXROOT DNS_ALIAS DNS_CANON DNS_BAD
unset DNS_EXT_REL DNS_EXT_BAD DNS_EXT_OK
unset -f dns_run dns_run_ext

# ────────────────────────────────────────────────────────────────────────────
# #834 subagent extension-handoff lint (lib/test/lint-subagent-extension-handoff.py).
# The registry (lib/subagent-dispatch-sites.json) is the authority; the lint gates
# that a subagent dispatch of a DevFlow skill is registered. Fixture trees and
# registries are built in scratch dirs (like the #711 block) and driven through
# --root/--files-from/--registry; the lint under test is never mocked.
# ────────────────────────────────────────────────────────────────────────────
echo "#834 subagent extension-handoff lint"
E834_LINT="$LIB/test/lint-subagent-extension-handoff.py"
E834_REG_REAL="$LIB/subagent-dispatch-sites.json"

# Real-tree run: clean now, plus a POSITIVE record tally so a collapsed audit can't read clean.
E834_OUT="$(python3 "$E834_LINT" --root "$LIB/.." 2>&1)"; E834_RC=$?
assert_eq "#834 lint: clean on the tree as it stands" "rc=0" \
  "$([ "$E834_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$E834_RC" "$E834_OUT")"
assert_eq "#834 lint: the real-tree run audited a positive number of records" "yes" \
  "$(printf '%s' "$E834_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print("yes" if m and int(m.group(1)) > 0 else "no")')"

# Positive control over the REAL tree (AC16): for every non-inherited registry record,
# a registry missing that record makes the lint exit non-zero — because the site's real
# dispatch wording still flags in the tree but no record accounts for it. Inherited
# records (the shadow re-dispatch) are the sole exemption. This is the assertion that
# fails if the token set / reference forms ever stop matching a registered site.
E834_POSCTL="$(python3 - "$E834_REG_REAL" "$LIB/.." "$E834_LINT" <<'PY'
import json, subprocess, sys, tempfile, os
reg_path, root, lint = sys.argv[1], sys.argv[2], sys.argv[3]
reg = json.load(open(reg_path))
results = []
for i, rec in enumerate(reg["sites"]):
    if rec.get("handoff") == "inherited":
        continue
    trimmed = {**reg, "sites": [s for j, s in enumerate(reg["sites"]) if j != i]}
    fd, tmp = tempfile.mkstemp(suffix=".json"); os.close(fd)
    json.dump(trimmed, open(tmp, "w"))
    rc = subprocess.run([sys.executable, lint, "--root", root, "--registry", tmp],
                        capture_output=True).returncode
    os.unlink(tmp)
    results.append(f"{rec['dispatcher']}::{rec['skill']}={'nonzero' if rc != 0 else 'ZERO'}")
print("all-nonzero" if all(r.endswith("nonzero") for r in results) and results else "|".join(results))
PY
)"
assert_eq "#834 lint: every non-inherited registered site is a positive control (removal → red)" \
  "all-nonzero" "$E834_POSCTL"

# --- Fixture tree. Build a synthetic skills/ tree so slugs resolve and dispatcher
# --- md files are audited. Registries are generated inline per assertion.
e834_write() {  # <root> <relpath> <line…>
  local root="$1" rel="$2" dir; shift 2
  dir="${rel%/*}"; [ "$dir" = "$rel" ] || mkdir -p "$root/$dir"
  printf '%s\n' "$@" > "$root/$rel"
}
e834_run() {  # <root> <registry> <path…> -> "rc=<n>|<stdout+stderr>"
  local root="$1" reg="$2"; shift 2
  local list out rc
  list="$(probe_tmp '#834 fixture list')" || list=""
  case "$list" in
    ""|/dev/null) printf 'rc=probe-unavailable|fixture list could not be allocated'; return 0 ;;
  esac
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$E834_LINT" --root "$root" --files-from "$list" --registry "$reg" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}

E834_FX="$(probe_tmp '#834 fixture root')"
case "$E834_FX" in ""|/dev/null) : ;; *) rm -f "$E834_FX"; mkdir -p "$E834_FX" ;; esac
# Resolvable slugs: childskill/otherskill under skills/, someagent under agents/.
e834_write "$E834_FX" skills/childskill/.keep ""
e834_write "$E834_FX" skills/otherskill/.keep ""
e834_write "$E834_FX" agents/someagent.md "an agent definition"
# Real dispatch (invoke form) and a second real dispatch (path form).
e834_write "$E834_FX" skills/d/real.md \
  "## Real dispatch" "Spawn a subagent with the Agent tool and instruct it to invoke the \`devflow:childskill\` skill."
e834_write "$E834_FX" skills/d/pathform.md \
  "## Path-form dispatch" "Use the Agent tool. Read and follow \`../childskill/SKILL.md\` exactly."
# Prose ABOUT a dispatch — same lexical shape, but not a real dispatch → needs an nd exemption.
e834_write "$E834_FX" skills/d/prose.md \
  "## Prose about dispatch" "The Agent tool path where the run would invoke the \`devflow:childskill\` skill is described here for context; nothing is dispatched."
# Complement inputs, each present so the claimed non-flagging is exercised, not assumed.
e834_write "$E834_FX" skills/d/agentref.md \
  "## Agent ref" "Use the Agent tool to invoke the \`devflow:someagent\` skill."     # resolves agents/
e834_write "$E834_FX" skills/d/superref.md \
  "## Super ref" "Use the Agent tool to invoke the \`superpowers:writing-skills\` skill."  # not devflow
e834_write "$E834_FX" skills/d/tokenonly.md "## Token only" "Use the Agent tool here."
e834_write "$E834_FX" skills/d/refonly.md "## Ref only" "Please invoke the \`devflow:childskill\` skill."
e834_write "$E834_FX" skills/d/split.md \
  "# Token section" "Use the Agent tool." "# Ref section" "invoke the \`devflow:childskill\` skill"
e834_write "$E834_FX" skills/d/fenced.md \
  "## Fenced" "Example below:" '```' "# Agent tool: invoke the \`devflow:childskill\` skill" '```' "Nothing outside the fence."
# An UNTERMINATED fence must NOT hide a real dispatch after it — the scan fails CLOSED
# (matching the sibling git-ls-files lints), so the region stays scannable.
e834_write "$E834_FX" skills/d/unterminated.md \
  "## After an unterminated fence" '```' "an example fence that is never closed" "Use the Agent tool to invoke the \`devflow:childskill\` skill."
# A file whose one section dispatches TWO children — the second-dispatch-in-a-registered-file case.
e834_write "$E834_FX" skills/d/twochild.md \
  "## Two children" "Use the Agent tool to invoke the \`devflow:childskill\` skill and also invoke the \`devflow:otherskill\` skill."
# Preamble + token/ref split across two DIFFERENT sections → NOT flagged (own-line attribution:
# the level-0 preamble owns only its pre-heading text, so it cannot re-unite them file-wide).
e834_write "$E834_FX" skills/d/preamble-split.md \
  "Some intro before any heading." "" "# Section A" "Use the Agent tool." "# Section B" "Please invoke the \`devflow:childskill\` skill."
# Nested: a PARENT section carries its own dispatch AND a deeper child qualifies. Own-line
# attribution flags BOTH — the parent's own dispatch is not masked by the nested child (fail-open fix).
e834_write "$E834_FX" skills/d/nested.md \
  "## Parent dispatch" "Use the Agent tool to invoke the \`devflow:otherskill\` skill." \
  "### Child dispatch" "Use the Agent tool to invoke the \`devflow:childskill\` skill."

# Happy path: sites cover real.md + pathform.md, nd exempts prose.md → exact agreement, exit 0.
E834_REG_OK="$(probe_tmp '#834 reg ok')"
cat > "$E834_REG_OK" <<'JSON'
{"schema_version":1,
 "sites":[{"dispatcher":"skills/d/real.md","skill":"childskill","handoff":"by-path"},
          {"dispatcher":"skills/d/pathform.md","skill":"childskill","handoff":"by-path"}],
 "declared_non_dispatch":[{"dispatcher":"skills/d/prose.md","section":"Prose about dispatch","reason":"prose describing a dispatch, not a dispatch"}]}
JSON
assert_eq "#834 lint: happy path over agreeing fixture exits 0 with a machine-rendered tally" \
  "rc=0|audited 2 of 2 records" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_OK" skills/d/real.md skills/d/pathform.md skills/d/prose.md)" in
       "rc=0|"*"audited 2 of 2 records"*) echo "rc=0|audited 2 of 2 records" ;;
       *) e834_run "$E834_FX" "$E834_REG_OK" skills/d/real.md skills/d/pathform.md skills/d/prose.md ;; esac)"

# Singular-tally path and empty-registry path.
E834_REG_ONE="$(probe_tmp '#834 reg one')"
cat > "$E834_REG_ONE" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/real.md","skill":"childskill","handoff":"by-path"}],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: one-record registry prints the singular tally" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_ONE" skills/d/real.md)" in *"audited 1 of 1 record"*) echo yes ;; *) echo no ;; esac)"
E834_REG_EMPTY="$(probe_tmp '#834 reg empty')"
cat > "$E834_REG_EMPTY" <<'JSON'
{"schema_version":1,"sites":[],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: empty registry over a non-dispatching file is audited 0 of 0, exit 0" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/tokenonly.md)" in
       "rc=0|"*"audited 0 of 0 records"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#834 lint: empty registry over a dispatching tree fails naming the unregistered site" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/real.md)" in
       "rc=0|"*) echo no ;;
       *"unregistered dispatch"*"skills/d/real.md"*"childskill"*) echo yes ;; *) echo no ;; esac)"

# Second dispatch added to a registered file is caught, naming the (dispatcher, skill) pair.
E834_REG_TWO="$(probe_tmp '#834 reg twochild')"
cat > "$E834_REG_TWO" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/twochild.md","skill":"childskill","handoff":"by-path"}],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: a second dispatch in a registered file is caught, naming the pair" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_TWO" skills/d/twochild.md)" in
       *"skills/d/twochild.md"*"otherskill"*) echo yes ;; *) echo no ;; esac)"

# Complement: agents/-resolving, non-devflow, token-only, ref-only, split, fenced → not flagged.
assert_eq "#834 lint: the complement (agents/, superpowers, token-only, ref-only, split, fenced) is not flagged" \
  "rc=0" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/agentref.md skills/d/superref.md skills/d/tokenonly.md skills/d/refonly.md skills/d/split.md skills/d/fenced.md)" in
       "rc=0|"*) echo "rc=0" ;; *) e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/agentref.md skills/d/superref.md skills/d/tokenonly.md skills/d/refonly.md skills/d/split.md skills/d/fenced.md ;; esac)"

# Section-scoped conjunction: a token and a reference in two DIFFERENT sections, even with a
# file-level preamble, produce no finding (own-line attribution — no whole-file preamble span).
assert_eq "#834 lint: token and reference in two different sections (with a preamble) is not flagged" \
  "rc=0" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/preamble-split.md)" in
       "rc=0|"*) echo "rc=0" ;; *) e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/preamble-split.md ;; esac)"

# A parent section's OWN dispatch is not masked by a qualifying nested child (fail-open fix):
# with only the child registered, the parent's own unregistered dispatch is still caught.
E834_REG_NEST="$(probe_tmp '#834 reg nested')"
cat > "$E834_REG_NEST" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/nested.md","skill":"childskill","handoff":"by-path"}],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: a parent-section dispatch is not masked by a qualifying nested child" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_NEST" skills/d/nested.md)" in
       *"skills/d/nested.md"*"otherskill"*) echo yes ;; *) echo no ;; esac)"

# Direction-2 in isolation: a registered NON-inherited site the scan does not flag (its section
# has a token but no reference) fails "does not reach"; the same record marked `inherited` is clean.
E834_REG_UNREACH="$(probe_tmp '#834 reg unreach')"
cat > "$E834_REG_UNREACH" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/tokenonly.md","skill":"childskill","handoff":"by-path"}],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: a non-inherited registered site the scan does not reach fails" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_UNREACH" skills/d/tokenonly.md)" in *"does not reach"*) echo yes ;; *) echo no ;; esac)"
E834_REG_INHER="$(probe_tmp '#834 reg inherited')"
cat > "$E834_REG_INHER" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/tokenonly.md","skill":"childskill","handoff":"inherited"}],"declared_non_dispatch":[]}
JSON
assert_eq "#834 lint: an inherited registered site is exempt from the reach check (clean)" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_INHER" skills/d/tokenonly.md)" in "rc=0|"*) echo yes ;; *) echo no ;; esac)"

# Malformed (non-JSON) and top-level-non-object registries fail with their own messages
# (CLAUDE.md config-parser boundary rows), plus the string-scalar shape the six-shape loop omits.
E834_REG_BADJSON="$(probe_tmp '#834 reg badjson')"
printf 'not json{\n' > "$E834_REG_BADJSON"
assert_eq "#834 lint: a non-JSON registry fails naming invalid JSON" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_BADJSON" skills/d/tokenonly.md)" in *"not valid JSON"*) echo yes ;; *) echo no ;; esac)"
E834_REG_TOPARR="$(probe_tmp '#834 reg toparr')"
printf '[]\n' > "$E834_REG_TOPARR"
assert_eq "#834 lint: a top-level non-object registry fails" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_TOPARR" skills/d/tokenonly.md)" in *"top-level JSON object"*) echo yes ;; *) echo no ;; esac)"

# Fail-closed: a dispatch after an UNTERMINATED fence is still flagged (not hidden).
assert_eq "#834 lint: a dispatch after an unterminated fence is not hidden (fails closed)" "yes" \
  "$(case "$(e834_run "$E834_FX" "$E834_REG_EMPTY" skills/d/unterminated.md)" in
       *"unregistered dispatch"*"skills/d/unterminated.md"*"childskill"*) echo yes ;; *) echo no ;; esac)"

# Stale declared_non_dispatch (names a section the scan no longer flags) → red.
E834_REG_STALE="$(probe_tmp '#834 reg stale')"
cat > "$E834_REG_STALE" <<'JSON'
{"schema_version":1,"sites":[{"dispatcher":"skills/d/real.md","skill":"childskill","handoff":"by-path"}],"declared_non_dispatch":[{"dispatcher":"skills/d/tokenonly.md","section":"Token only","reason":"stale"}]}
JSON
assert_eq "#834 lint: a stale declared_non_dispatch entry fails" "yes" \
