  "permissionrequest-probe=PermissionRequest:matcher-bash:nonempty:json-ok:1 pretooluse-deny-probe=PreToolUse:matcher-bash:nonempty:json-ok:1 defer-probe=PreToolUse:matcher-bash:nonempty:json-ok:1" \
  "$HAP_HOOKS"

