  assert_eq "#908 harden_guard: base-fetch success displaces the PR-head transitive-import dependency too (fix-delta gate regression lock)" "yes" \
    "$(grep -qF 'MALICIOUS_PR_HEAD_HEADS' "$HG_FIX/ws/lib/test/extract-command-heads.py" && echo no || echo yes)"
  assert_eq "#908 harden_guard: displaced content is the TRUSTED base copy, not a stub" "yes" \
    "$(diff -q "$HG_FIX/origin/scripts/pretooluse-shape-guard.py" "$HG_FIX/ws/scripts/pretooluse-shape-guard.py" >/dev/null 2>&1 && echo yes || echo no)"
  # Fail-closed arm: base ref cannot be fetched (a deleted/unreachable base) — the
  # PR-head bytes must never survive; they are stubbed inline instead.
  echo "MALICIOUS_PR_HEAD_GUARD" > "$HG_FIX/ws/scripts/pretooluse-shape-guard.py"
  echo "MALICIOUS_PR_HEAD_SHAPES" > "$HG_FIX/ws/lib/test/extract-command-shapes.py"
  echo "MALICIOUS_PR_HEAD_HEADS" > "$HG_FIX/ws/lib/test/extract-command-heads.py"
  ( cd "$HG_FIX/ws" && BASE_REF=nonexistent-branch-xyz-908 GITHUB_OUTPUT="$HG_FIX/gh_out2.txt" bash -e "$HG_SCRIPT" ) >"$HG_FIX/out2.log" 2>&1
  assert_eq "#908 harden_guard errexit: the fail-closed arm also survives bash -e {0}" "0" "$?"
  assert_eq "#908 harden_guard: an unreachable base ref stubs the PR-head guard (fail-closed), never leaves it intact" "yes" \
    "$(grep -qF 'MALICIOUS_PR_HEAD_GUARD' "$HG_FIX/ws/scripts/pretooluse-shape-guard.py" && echo no || echo yes)"
  assert_eq "#908 harden_guard: an unreachable base ref stubs the dynamic-import dependency too" "yes" \
    "$(grep -qF 'MALICIOUS_PR_HEAD_SHAPES' "$HG_FIX/ws/lib/test/extract-command-shapes.py" && echo no || echo yes)"
  assert_eq "#908 harden_guard: an unreachable base ref stubs the transitive-import dependency too (fix-delta gate regression lock)" "yes" \
    "$(grep -qF 'MALICIOUS_PR_HEAD_HEADS' "$HG_FIX/ws/lib/test/extract-command-heads.py" && echo no || echo yes)"
  assert_eq "#908 harden_guard: the fail-closed stub warns rather than silently succeeding" "1" \
    "$(grep -c 'could not materialize a trusted base copy' "$HG_FIX/out2.log" || true)"
  # Shadow-review finding (issue #908 review, early shadow trigger): the last-resort
  # stub WRITE itself must be verified — a stub write failure (wholly unwritable
  # target) must FAIL the job (exit 1), never merely warn-and-proceed, or a PR-head
  # copy could remain executable in this secrets-bearing job with no signal that the
  # fail-closed arm itself failed open.
  HG_FIX3="$(git_sandbox '#908 harden_guard write-failure fixture')"
  mkdir -p "$HG_FIX3/ws/scripts" "$HG_FIX3/ws/lib/test"
  echo "MALICIOUS_PR_HEAD_GUARD" > "$HG_FIX3/ws/scripts/pretooluse-shape-guard.py"
  echo "MALICIOUS_PR_HEAD_SHAPES" > "$HG_FIX3/ws/lib/test/extract-command-shapes.py"
  echo "MALICIOUS_PR_HEAD_HEADS" > "$HG_FIX3/ws/lib/test/extract-command-heads.py"
  git -C "$HG_FIX3/ws" init -q 2>/dev/null
  git -C "$HG_FIX3/ws" add -A 2>/dev/null
  git -C "$HG_FIX3/ws" -c user.email=t@t -c user.name=t commit -qm x 2>/dev/null
  chmod 444 "$HG_FIX3/ws/scripts/pretooluse-shape-guard.py" 2>/dev/null
  chmod 555 "$HG_FIX3/ws/scripts" 2>/dev/null
  ( cd "$HG_FIX3/ws" && BASE_REF=nonexistent-branch-xyz-908 GITHUB_OUTPUT="$HG_FIX3/gh_out3.txt" bash -e "$HG_SCRIPT" ) >"$HG_FIX3/out3.log" 2>&1
  assert_eq "#908 harden_guard: an un-stubbable target (wholly unwritable) fails the job with a fail-closed ::error:: (issue #908 review regression lock)" "1" \
    "$(grep -c 'Failing the job BEFORE Run Claude Code so no PR-controlled guard hook fires' "$HG_FIX3/out3.log" || true)"
  chmod 755 "$HG_FIX3/ws/scripts" 2>/dev/null
  chmod 644 "$HG_FIX3/ws/scripts/pretooluse-shape-guard.py" 2>/dev/null
  # ── Absent-target skip arms (issue #908 confirmatory review) ────────────────
  # The skip arms are the principal behavioral change of that iteration and had no
  # fixture: deleting either one, or dropping the working-tree half of its predicate,
  # left the suite green. Two shapes, and the SECOND is the security-critical one —
  # the working-tree half of the predicate is the only thing keeping the skip from
  # being a fail-open, so a test that exercises only the benign shape proves nothing.
  #
  # Shape A — CONSUMER repo: the targets exist on NEITHER the base ref NOR the working
  # tree. Nothing to harden: no phantom files, empty guard_paths, no ::warning::.
  HG_FIX4="$(git_sandbox '#908 harden_guard absent-target fixture')"
  mkdir -p "$HG_FIX4/origin"
  echo "unrelated consumer file" > "$HG_FIX4/origin/README.md"
  git -C "$HG_FIX4/origin" init -q 2>/dev/null
  git -C "$HG_FIX4/origin" add -A 2>/dev/null
  git -C "$HG_FIX4/origin" -c user.email=t@t -c user.name=t commit -qm base 2>/dev/null
  git -C "$HG_FIX4/origin" branch -q -M main 2>/dev/null
  git clone -q "$HG_FIX4/origin" "$HG_FIX4/ws" 2>/dev/null
  ( cd "$HG_FIX4/ws" && BASE_REF=main GITHUB_OUTPUT="$HG_FIX4/gh_out4.txt" bash -e "$HG_SCRIPT" ) >"$HG_FIX4/out4.log" 2>&1
  assert_eq "#908 harden_guard errexit: the absent-target (consumer-repo) arm survives bash -e {0}" "0" "$?"
  assert_eq "#908 harden_guard: an absent target creates NO phantom scripts/ file in a consumer checkout (issue-#502 class regression lock)" "no" \
    "$([ -e "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py" ] && echo yes || echo no)"
  assert_eq "#908 harden_guard: an absent target creates NO phantom lib/test/ files in a consumer checkout" "no" \
    "$([ -e "$HG_FIX4/ws/lib/test/extract-command-shapes.py" ] || [ -e "$HG_FIX4/ws/lib/test/extract-command-heads.py" ] && echo yes || echo no)"
  assert_eq "#908 harden_guard: the absent-target arm emits NO spurious deployment-fault ::warning:: (every consumer auto-review saw one before this fix)" "0" \
    "$(grep -c 'could not materialize a trusted base copy' "$HG_FIX4/out4.log" || true)"
  assert_eq "#908 harden_guard: the absent-target arm publishes an EMPTY guard_paths (no false displacement disclosure)" "yes" \
    "$(python3 - "$HG_FIX4/gh_out4.txt" <<'PY'
import re, sys
body = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"^guard_paths<<(\S+)\n(.*?)^\1$", body, re.S | re.M)
print("yes" if m and not m.group(2).strip() else "no")
PY
)"
  # The grep target is a TEMP_-named alias for the run's captured GITHUB_OUTPUT
  # scratch: `disposition=guard-absent` doubles as a real harden-stop-hooks.sh
  # source token, so a bare `grep -qF … "$HG_FIX4/gh_out4.txt"` reads to the
  # mutation-routing raw-presence detector as an undeclared source-presence pin.
  # The TEMP_ name IS the declaration that this is a runtime executable assertion
  # over scratch, not a source pin (see pin-corpus-lint.py's TMP_/TEMP_ carve-out).
  TEMP_HG_OUT4="$HG_FIX4/gh_out4.txt"
  assert_eq "#908 harden_guard: the absent-target arm reports disposition=guard-absent, not a false guard-displaced" "yes" \
    "$(grep -qF 'disposition=guard-absent' "$TEMP_HG_OUT4" && echo yes || echo no)"
  # Shape B (SECURITY NEGATIVE CONTROL) — the PR *adds* a guard target: absent on the
  # base ref, PRESENT in the working tree. This MUST still route to the fail-closed
  # stub arm. If it did not, the skip would be exactly the fail-open the predicate's
  # working-tree half exists to prevent.
  echo "MALICIOUS_PR_ADDED_GUARD" > "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py" 2>/dev/null || mkdir -p "$HG_FIX4/ws/scripts" && echo "MALICIOUS_PR_ADDED_GUARD" > "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py"
  ( cd "$HG_FIX4/ws" && BASE_REF=main GITHUB_OUTPUT="$HG_FIX4/gh_out5.txt" bash -e "$HG_SCRIPT" ) >"$HG_FIX4/out5.log" 2>&1
  assert_eq "#908 harden_guard: a PR-ADDED guard target (absent on base, present in tree) is still stubbed — the skip arm is not a fail-open (issue #908 confirmatory-review security regression lock)" "yes" \
    "$(grep -qF 'MALICIOUS_PR_ADDED_GUARD' "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py" && echo no || echo yes)"
  # Shape C (SECURITY NEGATIVE CONTROL) — a PR-added DANGLING symlink at a guard path.
  # `[ ! -e ]` alone follows the link and reads it as absent, so the target would be
  # neither displaced nor stubbed, and materializing its destination later in the job
  # would reopen PR-controlled execution. The paired `[ ! -L ]` is what closes this.
  rm -f "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py"
  ln -s /nonexistent/attacker-target-908 "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py"
  ( cd "$HG_FIX4/ws" && BASE_REF=main GITHUB_OUTPUT="$HG_FIX4/gh_out6.txt" bash -e "$HG_SCRIPT" ) >"$HG_FIX4/out6.log" 2>&1
  assert_eq "#908 harden_guard: a PR-added DANGLING symlink at a guard path is not skipped as absent (issue #908 confirmatory-review Critical regression lock)" "no" \
    "$([ -L "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py" ] && echo yes || echo no)"
  assert_eq "#908 harden_guard: the dangling-symlink path holds a real stub afterwards, not a link to an attacker-materializable destination" "yes" \
    "$([ -f "$HG_FIX4/ws/scripts/pretooluse-shape-guard.py" ] && echo yes || echo no)"
  # Shadow-review finding (issue #908 review, early shadow trigger, Critical): harden_guard
  # must publish its own displaced_paths output (mirroring harden_hooks' #504 AC1
  # contract) or the grounding-block renderer never learns these three files were
  # displaced/stubbed — exactly on the harden_hooks-skipped consumer-repo arm this step
  # exists to still cover. Behavioral: re-run the success-arm fixture and assert the
  # GITHUB_OUTPUT carries all three GUARD_TARGETS under displaced_paths.
  # Read each fixture's GITHUB_OUTPUT capture into a variable and test membership with
  # bash `case` (not `grep -qF`) — a dynamic mktemp'd fixture path can never be a
  # statically-inspectable structural-pin target, so this deliberately avoids the
  # raw-presence grep-for-literal shape rather than declaring an uninspectable pin.
  _908_gh1="$(cat "$HG_FIX/gh_out1.txt" 2>/dev/null)"
  _908_gh1_ok=no
  case "$_908_gh1" in
    *"scripts/pretooluse-shape-guard.py"*)
      case "$_908_gh1" in
        *"lib/test/extract-command-shapes.py"*)
          case "$_908_gh1" in
            *"lib/test/extract-command-heads.py"*) _908_gh1_ok=yes ;;
          esac
          ;;
      esac
      ;;
  esac
  assert_eq "#908 harden_guard: publishes guard_paths for the success arm (shadow-review regression lock)" "yes" "$_908_gh1_ok"
  _908_gh2="$(cat "$HG_FIX/gh_out2.txt" 2>/dev/null)"
  _908_gh2_ok=no
  case "$_908_gh2" in
    *"scripts/pretooluse-shape-guard.py"*)
      case "$_908_gh2" in
        *"lib/test/extract-command-shapes.py"*)
          case "$_908_gh2" in
            *"lib/test/extract-command-heads.py"*) _908_gh2_ok=yes ;;
          esac
          ;;
      esac
      ;;
  esac
  assert_eq "#908 harden_guard: publishes guard_paths for the stubbed arm too" "yes" "$_908_gh2_ok"
  assert_eq "#908 review: displaced_join wires harden_guard's guard_paths as a third producer" "yes" \
    "$(grep -qF 'GUARD_PATHS: ${{ steps.harden_guard.outputs.guard_paths }}' "$_908_RUNNER_YML" && grep -qF '[ -n "$GUARD_PATHS" ] && printf' "$_908_RUNNER_YML" && echo yes || echo no)"  # structural-pin-ok: cross-file-phase-contract -- pins that harden_guard's displacement reaches the joined hardened_paths output the grounding-block renderer reads, so a reviewing agent is told these three files are trusted-base/stub bytes rather than reading them as untouched PR-head content
fi
# ────────────────────────────────────────────────────────────────────────────

# ── #1084 superseded-config-key guard (lib/test/lint-superseded-config-keys.py) ──
# The consumer-facing `devflow` config family was renamed to `prflow` (#1002); #1068 and
# #1084 swept the tree of stale `devflow.<key>` leaves twice, so a one-time sweep has a known
# recurrence rate. This guard fails RED on a newly introduced superseded leaf. It sources its
# population from `git ls-files` (no recursive walk, #711) and carries a declared-exemption
# list for the do-not-sweep sites. Driven here so the whole tree is re-scanned every run.
L1084_LINT="$LIB/test/lint-superseded-config-keys.py"
assert_eq "#1084 guard: no superseded devflow.<key> config leaf in the tree" "rc=0" \
  "$(cd "$LIB/.." && python3 "$L1084_LINT" >/dev/null 2>&1 && echo rc=0 || echo "rc=$?")"
# Non-vacuous detector: assert the leaf regex fires on a superseded leaf and a jq path, and
# correctly skips the frozen forms (a bare `SECTION:` family word with no leaf, a filename
# extension, the `/`-alias colon form) — so an accidental weakening of the pattern is caught,
# not just an empty tree. Drives the module's own `_LEAF_RE` / `_EXTENSIONS` directly. The
# superseded family word is ASSEMBLED FROM PARTS so no literal superseded leaf appears in this
# file's own source — otherwise this fixture would be a candidate the guard flags in run.sh.
assert_eq "#1084 guard: leaf detector matches superseded leaves and skips frozen forms" "T T F F F" \
  "$(python3 - "$L1084_LINT" <<'PY'
import importlib.util, sys
spec = importlib.util.spec_from_file_location("g", sys.argv[1])
g = importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
F = "dev" + "flow"  # assembled so this file carries no literal superseded leaf
def hit(line):
    m = g._LEAF_RE.search(line)
    return bool(m) and m.group(1) not in g._EXTENSIONS
def t(b): return "T" if b else "F"
print(" ".join(t(hit(x)) for x in (
    F + ".allowed_bots", "read `." + F + ".workpad_marker`",
    "SECTION: " + F, F + ".yml", "/" + F + ":review")))
PY
)"
# main()-level RED-path test: drive the WHOLE guard pipeline (not just the regex) over a
# synthetic population by monkeypatching the shared population reader, so a neutered exemption
# list, a swallowed skip, or an unhandled enumeration failure is caught — the clean-tree rc=0
# assertion above is vacuous if _exempt() is broadened to match everything. Asserts, in order:
# an offender in a NON-exempt file → rc 1; an offender only in an EXEMPT file → rc 0; a
# non-exempt file that cannot be read → rc 1 (fail-closed skip, not a silent clean pass); an
# enumeration failure → rc 2. The offending leaf is assembled from parts so this file carries
# none.
assert_eq "#1084 guard: main() pipeline red-paths (offender/exact-exempt/prefix-exempt/skip/enum)" "1 0 0 1 2" \
  "$(python3 - "$L1084_LINT" <<'PY'
import importlib.util, io, sys, contextlib
spec = importlib.util.spec_from_file_location("g", sys.argv[1])
g = importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
F = "dev" + "flow"
OFFENDER = "a comment naming " + F + ".allowed_bots here"
def run_main(pop, reader):
    g._pop.enumerate_population = lambda root, ff, *, ls_files_argv: pop
    g._pop.read_source = reader
    with contextlib.redirect_stderr(io.StringIO()):
        return g.main()
off = lambda p, *, skip_nul: (OFFENDER, None)
# 1) offender in a NON-exempt file → rc 1
r_off = run_main(["some/live-file.md"], off)
# 2) offender only in an EXACT-exempt file (install.sh) → rc 0 (_EXEMPT_EXACT honored)
r_exact = run_main(["install.sh"], off)
# 3) offender only in a PREFIX-exempt file (.changeset/) → rc 0 (_EXEMPT_PREFIXES honored)
r_prefix = run_main([".changeset/x.md"], off)
# 4) a non-exempt, non-binary file that cannot be read → rc 1 (fail-closed skip)
r_skip = run_main(["some/live-file.md"], lambda p, *, skip_nul: (None, "unreadable (permission)"))
# 5) enumeration failure → rc 2
def raise_enum(root, ff, *, ls_files_argv):
    raise g._pop.EnumerationError("git ls-files failed")
g._pop.enumerate_population = raise_enum
with contextlib.redirect_stderr(io.StringIO()):
    r_enum = g.main()
print(r_off, r_exact, r_prefix, r_skip, r_enum)
PY
)"
# #1096: line-scoped `# superseded-key-ok:` marker. The live migration files (config-get.sh,
# scaffold-config.sh, migrate-consumer-tier1.sh, migrate-config-values.py) moved OFF the
# whole-file exemption, so an UNDECLARED superseded leaf inside one of them must fail RED again
# (the regression AC2 demands), while a leaf carrying the marker with a non-empty reason is
# exempt, a bare/empty-reason marker does NOT exempt (else a marker with no rationale would
# silently launder any line), whitespace-only reason does NOT exempt (the `\S` anchor), the
# marker text sitting inside a STRING LITERAL does NOT exempt a real leaf on that same code
# line (the marker is matched against the balanced-quote-aware comment tail, not the raw line —
# else the guard fails open exactly where it claims closed), and the marker is genuinely
# LINE-scoped: a marker on a different line does NOT launder an undeclared leaf (the literal
# meaning of "line-scoped", so a future regression to file-level "any marker exempts the file"
# fails RED). The spoof arms are ATTRIBUTED (issue #1107 review note): arm 5's `#` sits directly
# after the opening quote, so `_comment_split`'s WORD-BOUNDARY rule alone rejects it and the arm
# stays green even against a mutant with quote tracking fully disabled — it pins the boundary
# rule, not quote awareness. Arms 7 and 8 put a SPACE before the in-literal `#`, so only quote
# tracking can reject them; both were observed rc 0 (guard fails open) against that mutant and
# rc 1 at HEAD. Arm 8 uses a SINGLE-quoted literal carrying a backslash, the jq/regex idiom in
# scaffold-config.sh, covering `_split_at_hash`'s single-quote-specific `quote != "'"` carve-out.
# Drives the WHOLE guard pipeline over a synthetic population of a now-non-exempt migration
# path; the leaf is assembled from parts so run.sh carries no literal.
assert_eq "#1096 guard: line-scoped superseded-key-ok marker (undeclared/marked/empty/ws/spoof x3/cross-line)" "1 0 1 1 1 1 1 1" \
  "$(python3 - "$L1084_LINT" <<'PY'
import importlib.util, io, sys, contextlib
spec = importlib.util.spec_from_file_location("g", sys.argv[1])
g = importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
LEAF = "dev" + "flow" + "_implement.stall_backstop"
def run_main(line):
    g._pop.enumerate_population = lambda root, ff, *, ls_files_argv: ["scripts/config-get.sh"]
    g._pop.read_source = lambda p, *, skip_nul: (line, None)
    with contextlib.redirect_stderr(io.StringIO()):
        return g.main()
# 1) undeclared leaf in a now-non-exempt migration file → rc 1 (AC2 regression is caught)
r_undeclared = run_main("# probes ." + LEAF + " here")
# 2) same leaf declared with a non-empty reason → rc 0 (exempt)
r_marked = run_main("# probes ." + LEAF + "  # superseded-key-ok: legitimate migration probe")
# 3) same leaf with a bare/empty-reason marker → rc 1 (reason must be non-empty)
r_empty = run_main("# probes ." + LEAF + "  # superseded-key-ok:")
# 4) same leaf with a whitespace-only reason → rc 1 (the `\S` anchor rejects it)
r_ws = run_main("# probes ." + LEAF + "  # superseded-key-ok:   ")
# 5) marker text inside a STRING literal, real leaf in code on the same line → rc 1 (no spoof).
#    Rejection is attributable to the WORD-BOUNDARY rule: the `#` follows the opening quote
#    directly, so no whitespace precedes it. This arm does NOT exercise quote tracking.
r_spoof = run_main('bad = "# superseded-key-ok: spoof"; probe(' + LEAF + ')')
# 6) leaf on one line, marker on a DIFFERENT line → rc 1 (line-scoped, not file-scoped)
r_crossline = run_main("# probes ." + LEAF + "\n# superseded-key-ok: on a different line")
# 7) DOUBLE-quoted literal with a SPACE before the in-literal `#` → rc 1. The word-boundary rule
#    cannot reject this one, so only quote tracking can: this is the arm that goes rc 0 against a
#    quote-tracking mutant.
r_spoof_dq = run_main('bad = " # superseded-key-ok: spoof"; probe(' + LEAF + ')')
# 8) SINGLE-quoted literal carrying a backslash, space before the in-literal `#` → rc 1. Covers
#    `_split_at_hash`'s single-quote-specific backslash carve-out over the jq-program idiom the
#    newly line-scoped scaffold-config.sh actually contains; also rc 0 against that mutant.
r_spoof_sq = run_main("jq 'sub(\"a\\\\.\"; \"b\") # superseded-key-ok: spoof'; probe(" + LEAF + ")")
print(r_undeclared, r_marked, r_empty, r_ws, r_spoof, r_crossline, r_spoof_dq, r_spoof_sq)
PY
)"
# #1096: config-get.sh's real `# superseded-key-ok:` marker is honored on the LIVE tree — the
# guard's own clean-tree rc=0 above would still pass if config-get.sh were re-added to
# _EXEMPT_EXACT, so assert the file is NOT whole-file exempt yet the tree stays clean (i.e. the
# marker, not an exemption, is what keeps it green).
assert_eq "#1096 guard: migration files are line-scoped, not whole-file exempt" "not-exempt" \
  "$(python3 - "$L1084_LINT" <<'PY'
import importlib.util, sys
spec = importlib.util.spec_from_file_location("g", sys.argv[1])
g = importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
files = ("scripts/config-get.sh", "scripts/scaffold-config.sh",
         "scripts/migrate-consumer-tier1.sh", "lib/migrate-config-values.py")
print("not-exempt" if not any(g._exempt(f) for f in files) else "still-exempt")
PY
)"
# #1084 AC5: the sweep must not touch any FROZEN identifier. Verified against a
# lib/rename-map.json-derived assertion rather than a bare negative: derive the frozen
# workflow filenames present in the tree, the DEVFLOW_ env prefix, devflow-marketplace, the
# /devflow: alias and the DevFlow product name from the map + tree, and assert each SURVIVES.
assert_eq "#1084 AC5: frozen identifiers survive the superseded-leaf sweep" "ALL-PRESENT" \
  "$(cd "$LIB/.." && python3 - <<'PY'
import json, subprocess, sys
m = json.load(open("lib/rename-map.json"))
def present(needle):
    r = subprocess.run(["git", "grep", "-qF", needle], capture_output=True)
    return r.returncode == 0
def ftracked(path):
    r = subprocess.run(["git", "ls-files", "--error-unmatch", path], capture_output=True)
    return r.returncode == 0
missing = []
# Frozen workflow FILENAMES that ship in the tree (devflow-review.yml / telemetry-push.yml
# are withheld from this release, so only assert survival of the ones actually present).
for fn in m["frozen"]["workflow_filenames"]:
    p = ".github/workflows/" + fn
    if ftracked(p) and not present(fn):
        missing.append(fn)
# Frozen consumer-facing env identifiers keep their DEVFLOW_ spelling (no PRFLOW_ read exists).
for row in m["frozen"]["env_identifiers"]["identifiers"]:
    if not present(row["name"]):
        missing.append(row["name"])
# Frozen top-level identifiers: the marketplace slug, the /devflow: command alias, the
# devflow:<agent> override namespace, and the DevFlow product name.
for lit in ("devflow-marketplace", "/devflow:", "devflow:code-reviewer", "DevFlow"):
    if not present(lit):
        missing.append(lit)
print("ALL-PRESENT" if not missing else "MISSING: " + ", ".join(missing))
PY
)"
# ────────────────────────────────────────────────────────────────────────────

# ── #1072 shipped-pruned-path lint (lib/test/lint-shipped-pruned-path.py) ──
# The vendor slice prunes lib/test / docs/site / docs/external / docs/internal /
# .claude-plugin/marketplace.json from the
# vendored plugin, so a shipped prompt sentence naming one of them resolves against a consumer
# tree where it does not exist. This lint derives the prune set from vendor-slice.sh itself (not
# a hardcoded literal) and audits skills/** + agents/** for an unmarked reference. It joins the
# desk-time static-lint family, driven the same way: the real tree as the live gate, plus
# synthetic fixtures through --root/--files-from/--slice-source.
# Issue #1309: two prune targets (docs/external, docs/internal) are also documented docs.*
# config defaults — the consumer's OWN doc roots — so the lint derives a docs.* exemption set
# from .prflow/config.schema.json and subtracts them before scanning. The fixture harness
# supplies a schema shape independently of a slice shape through --schema-source (a schemas/
# sibling of slices/); the helpers below default to the real-shaped fixture schema so the
# pre-existing lib/test-target assertions are exemption-neutral.
SP_LINT="$LIB/test/lint-shipped-pruned-path.py"
SP_FX="$LIB/test/fixtures/shipped-pruned-path"
SP_SIMPLE="$SP_FX/slices/simple.sh"
SP_SCHEMA="$SP_FX/schemas/real-docs.json"
# Issue #1402: the never-shipped-workflow set is derived from install.sh + .github/workflows/,
# neither of which exists under a fixture root, so every --root-overriding helper below names
# the REAL pair. That is deliberate rather than incidental: the audited-scan cases assert real
# workflow names, so the derivation they run against must be the real one. The derivation
# matrix drives synthetic pairs instead.
SP_INSTALL_REAL="$LIB/../install.sh"
SP_WORKFLOWS_REAL="$LIB/../.github/workflows"
SP_INSTALL_FX="$SP_FX/installs/simple.sh"
SP_WORKFLOWS_FX="$SP_FX/workflows/real"

# Real-tree run: exits 0 AND its audited count equals an independently derived tracked
# skills/** + agents/** count. A positive-only floor would stay green if one audited prefix
# disappeared while the other still selected files.
SP_OUT="$(cd "$LIB/.." && python3 "$SP_LINT" 2>&1)"; SP_RC=$?
assert_eq "#1072 lint: clean on the tree as it stands" "rc=0" \
  "$([ "$SP_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$SP_RC" "$SP_OUT")"
SP_TRACKED_POPULATION="$(cd "$LIB/.." && git ls-files -- 'skills/**' 'agents/**' | python3 -c 'import sys; print(sum(1 for line in sys.stdin if line.strip()))')"
assert_eq "#1072 lint: the real-tree audited count matches the independently enumerated tracked population" "$SP_TRACKED_POPULATION" \
  "$(printf '%s' "$SP_OUT" | python3 -c 'import re,sys
m = re.search(r"audited (\d+) of", sys.stdin.read())
print(m.group(1) if m else "unestablished")')"

# AC11 / test_derived_set_matches_pinned_expectation: the POST-EXEMPTION derived set from the
# REAL slice and REAL schema equals the checked-in expectation. The floor the non-empty check
# alone does not provide — dropping the one live member (lib/test) still leaves a non-empty set,
# so a bare non-empty check would pass over a population it no longer covers. Reading the live
# vendor-slice.sh + .prflow/config.schema.json through --print-prune-set. Issue #1309: docs/external
# and docs/internal are exempt (documented docs.* defaults), so the pinned set below drops them; the
# expectation literal itself — not this comment — is the drift-proof record of the membership.
assert_eq "#1072 lint: derived prune set matches the checked-in expectation" \
  ".claude-plugin/marketplace.json docs/site lib/test" \
  "$(cd "$LIB/.." && python3 "$SP_LINT" --print-prune-set | python3 -c 'import sys; print(" ".join(sys.stdin.read().split()))')"

# Prune-set / exempt-set derivation over synthetic slices, driven through --slice-source
# (AC10 matrix). Both print-and-exit flags share one base so the rc-encoding and one-lining
# — which the assertions compare against — cannot drift between the two. The schema defaults
# to the real-shaped fixture so a lib/test-target slice is exemption-neutral; a caller needing
# a specific exemption shape passes $3 (sp_printset) / $2 (the flag-specific wrappers).
sp_encode() {  # <lint arg…> -> "rc=<n>|<one-line joined stdout+stderr>". The one
  # rc-encoding and one-lining every print-flag assertion compares against.
  local out rc
  out="$(python3 "$SP_LINT" "$@" 2>&1)"; rc=$?
  printf 'rc=%s|%s' "$rc" "$(printf '%s' "$out" | tr '\n' ' ')"
}
sp_printset() {  # <print-flag> <slice> [schema]
  sp_encode "$1" --slice-source "$2" --schema-source "${3:-$SP_SCHEMA}"
}
sp_pruneset() {  # <slice> [schema]
  sp_printset --print-prune-set "$@"
}
# test_nested_removal_is_a_target: a qualifying rm inside a conditional inside the body yields it.
assert_eq "#1072 lint: a nested (conditional) removal is a target" "rc=0|lib/test" \
  "$(sp_pruneset "$SP_FX/slices/nested-removal.sh")"
# test_staging_variable_renamed_refuses (derive half): renaming the staging variable still derives
# the same target, proving the name was DERIVED from the function, not transcribed.
assert_eq "#1072 lint: a renamed staging variable still derives the same target" "rc=0|lib/test" \
  "$(sp_pruneset "$SP_FX/slices/renamed.sh")"
# A target wrapped across a line continuation is folded and derived.
assert_eq "#1072 lint: a target across a line continuation is derived" "rc=0|lib/test" \
  "$(sp_pruneset "$SP_FX/slices/continuation.sh")"
# test_bare_stage_argument_rejected: the bare staging directory yields an empty set + refusal,
# never a set whose empty-suffix member would match every line of every audited file.
assert_eq "#1072 lint: a bare staging-directory argument is rejected (refusal, not empty suffix)" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/bare-stage.sh")" in "rc=1|"*"no qualifying rm target"*) echo yes ;; *) echo no ;; esac)"
# A find … -exec {} composite yields no target.
assert_eq "#1072 lint: a find -exec {} composite is not a target" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/find-exec.sh")" in "rc=1|"*"no qualifying rm target"*) echo yes ;; *) echo no ;; esac)"
# A removal keyed on the destination variable is not a target.
assert_eq "#1072 lint: a removal keyed on a non-staging variable is not a target" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/dest-var.sh")" in "rc=1|"*"no qualifying rm target"*) echo yes ;; *) echo no ;; esac)"
# An rm outside the function body is not scanned.
assert_eq "#1072 lint: an rm outside the function body is not a target" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/outside-func.sh")" in "rc=1|"*"no qualifying rm target"*) echo yes ;; *) echo no ;; esac)"
# test_staging_variable_renamed_refuses (refuse half): removing the composing assignment refuses,
# naming the inability to identify the staging variable.
assert_eq "#1072 lint: an absent composing assignment refuses (cannot identify staging variable)" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/no-assignment.sh")" in "rc=1|"*"could not identify the staging variable"*) echo yes ;; *) echo no ;; esac)"
# test_absent_prune_statement_refuses: the refusal names the slice source it read and audits nothing.
assert_eq "#1072 lint: an unparseable slice refuses non-zero naming the slice source" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/bare-stage.sh")" in *"slices/bare-stage.sh"*) echo yes ;; *) echo no ;; esac)"
# The remaining "cannot establish" arms, each ATTRIBUTED to its own guard rather than to a bare
# rc=1: bare-stage.sh above refuses via the empty-target path, so without these three the
# _function_body and _destination_param refusals are undriven and a mutant disabling one of them
# stays green. Each fixture is otherwise a well-formed slice, so the rejection cannot come from an
# unrelated precondition.
assert_eq "#1072 lint: a slice with no devflow_copy_slice() refuses, attributed to the missing function" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/no-function.sh")" in "rc=1|"*"devflow_copy_slice() not found"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1072 lint: an unclosed function body refuses, attributed to the missing closing brace" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/unclosed-brace.sh")" in "rc=1|"*"closing brace not found"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1072 lint: an unidentifiable destination parameter refuses, attributed to \$2" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/no-dest-param.sh")" in "rc=1|"*"could not identify the destination parameter"*) echo yes ;; *) echo no ;; esac)"
# An unlexable line inside the function body refuses instead of best-effort re-splitting. The
# fixture carries TWO rm targets and mangles only the second: under a `line.split()` fallback the
# survivor (docs/site) keeps the set non-empty, so the empty-set refusal never fires and the lint
# audits the shipped surface against a set silently missing lib/test. The assertion pins the
# lexer's own attribution, so that fail-open cannot pass as this refusal.
assert_eq "#1072 lint: an unlexable body line refuses, attributed to the lexer, not silently re-split" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/unlexable.sh")" in "rc=1|"*"could not lex a line of devflow_copy_slice()"*) echo yes ;; *) echo no ;; esac)"
# Positive control for the arm above: a `#` comment carrying an apostrophe is stripped BEFORE
# lexing, so prose inside the function body (as the real slice carries) still derives its set.
assert_eq "#1072 lint: an apostrophe inside a body comment does not refuse (comments stripped pre-lex)" "rc=0|lib/test" \
  "$(sp_pruneset "$SP_FX/slices/comment-apostrophe.sh")"

# ── #1309 docs.* exemption: a prune target that is also a documented docs.* default is exempt ──
# A schema-specific audit helper (sp_run defaults its schema; these need a chosen shape).
sp_run_schema() {  # <slice> <schema> <path…> -> "rc=<n>|<stdout+stderr>"
  local slice="$1" schema="$2"; shift 2
  local list out rc
  list="$(probe_tmp '#1309 fixture list')" || return 0
  printf '%s\n' "$@" > "$list"
  out="$(python3 "$SP_LINT" --root "$SP_FX" --files-from "$list" --slice-source "$slice" --schema-source "$schema" \
    --install-source "$SP_INSTALL_REAL" --workflows-source "$SP_WORKFLOWS_REAL" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
sp_exemptset() {  # <slice> [schema] — shares sp_printset's base with sp_pruneset (no drift)
  sp_printset --print-exempt-set "$@"
}
# The two print modes are alternate complete outputs, not an ordered pair. Rejecting their
# combination attributes the failure to argparse's mutual-exclusion guard; the single-flag
# success assertions below are the positive controls on the same slice/schema operands.
SP_BOTH_OUT="$(python3 "$SP_LINT" --print-prune-set --print-exempt-set --slice-source "$SP_FX/slices/ext-site-libtest.sh" --schema-source "$SP_FX/schemas/ext-only.json" 2>&1)"; SP_BOTH_RC=$?
assert_eq "#1309 lint: --print-prune-set and --print-exempt-set are mutually exclusive" "yes" \
  "$(case "rc=$SP_BOTH_RC|$SP_BOTH_OUT" in "rc=2|"*"argument --print-exempt-set: not allowed with argument --print-prune-set"*) echo yes ;; *) echo no ;; esac)"
# Assertion 1 (RED-first): a prune target that equals a docs.external default is subtracted from
# the prune set; the co-pruned non-defaults (docs/site, lib/test) survive. RED before #1309: the
# set still contained docs/external.
assert_eq "#1309 lint: a docs.* default prune target is exempt from the prune set" "rc=0|docs/site lib/test" \
  "$(sp_pruneset "$SP_FX/slices/ext-site-libtest.sh" "$SP_FX/schemas/ext-only.json")"
# Assertion 2 (RED-first): a shipped line naming only the .docs.external default audits clean —
# no finding, no marker needed. RED before #1309: it reported a pruned-path finding.
assert_eq "#1309 lint: a line naming only a docs.* default produces no finding" \
  "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: docs/site lib/test" \
  "$(sp_run_schema "$SP_FX/slices/ext-site-libtest.sh" "$SP_FX/schemas/ext-only.json" skills/docs-external-default.md)"
# Assertion 3 (control, GREEN today): the SAME file additionally naming an unmarked lib/test path
# is still reported — the exemption removes only the exempt root, not the still-forbidden target.
assert_eq "#1309 lint: a still-forbidden path on an otherwise-exempt file is reported" "yes" \
  "$(case "$(sp_run_schema "$SP_FX/slices/ext-site-libtest.sh" "$SP_FX/schemas/ext-only.json" skills/docs-external-and-libtest.md)" in "rc=1|"*"docs-external-and-libtest.md:2:"*"lib/test"*) echo yes ;; *) echo no ;; esac)"
# Assertion 4 (control): membership is EQUALITY, not prefix. A schema whose only default is
# docs/internal/ does NOT exempt a coarser `docs` prune target (a finer default emptying the guard
# via prefix would be a silent fail-open).
assert_eq "#1309 lint: exemption is equality not prefix (a finer default does not exempt a coarser target)" "rc=0|docs" \
  "$(sp_pruneset "$SP_FX/slices/prune-docs-bare.sh" "$SP_FX/schemas/internal-only.json")"
# Reverse-direction control: a coarser default must not exempt either finer prune target.
# Together the pair kills either one-way prefix implementation while preserving equality.
assert_eq "#1309 lint: exemption is equality not prefix (a coarser default does not exempt finer targets)" "rc=0|docs/external docs/internal" \
  "$(sp_pruneset "$SP_FX/slices/only-docs.sh" "$SP_FX/schemas/docs-bare-default.json")"
# Assertion 5 (control): a non-string default contributes no exemption and raises no error.
assert_eq "#1309 lint: a non-string default contributes no exemption and does not error" \
  "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run_schema "$SP_SIMPLE" "$SP_FX/schemas/boolean-default.json" skills/clean.md)"
# Assertion 5a (control): a non-path default (no '/') is never an exemption. --print-exempt-set over
# the real schema emits neither Documented nor CHANGELOG.md, and a slice pruning CHANGELOG.md against
# the real schema leaves CHANGELOG.md forbidden.
assert_eq "#1309 lint: --print-exempt-set omits non-path docs.* defaults (Documented, CHANGELOG.md)" "" \
  "$(cd "$LIB/.." && python3 "$SP_LINT" --print-exempt-set | grep -E 'Documented|CHANGELOG' || true)"
assert_eq "#1309 lint: a non-path default does not exempt a CHANGELOG.md prune target" "rc=0|CHANGELOG.md" \
  "$(sp_pruneset "$SP_FX/slices/prune-changelog.sh")"
# Assertion 6 (new-mechanism): five unestablished schema shapes each refuse non-zero naming the
# schema source and audit nothing — the config-JSON six-shape matrix applied to a schema default.
assert_eq "#1309 lint fail-closed: an absent schema refuses, naming the schema source" "yes" \
  "$(case "$(sp_pruneset "$SP_SIMPLE" "$SP_FX/schemas/does-not-exist.json")" in "rc=1|"*"could not read schema source"*"does-not-exist.json"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1309 lint fail-closed: an unreadable schema (a directory) refuses, naming the schema source" "yes" \
  "$(case "$(sp_pruneset "$SP_SIMPLE" "$SP_FX/schemas")" in "rc=1|"*"could not read schema source"*"schemas"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1309 lint fail-closed: an unparseable-JSON schema refuses, naming the schema source" "yes" \
  "$(case "$(sp_pruneset "$SP_SIMPLE" "$SP_FX/schemas/invalid-json.json")" in "rc=1|"*"invalid-json.json"*"do not parse as JSON"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1309 lint fail-closed: a schema with no properties.docs.properties key refuses" "yes" \
  "$(case "$(sp_pruneset "$SP_SIMPLE" "$SP_FX/schemas/no-docs-props.json")" in "rc=1|"*"no-docs-props.json"*"no properties.docs.properties key"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1309 lint fail-closed: a properties.docs.properties that is a JSON array refuses" "yes" \
  "$(case "$(sp_pruneset "$SP_SIMPLE" "$SP_FX/schemas/docs-props-array.json")" in "rc=1|"*"docs-props-array.json"*"not a JSON object"*) echo yes ;; *) echo no ;; esac)"
# Assertion 7 (new-mechanism): an exemption set covering EVERY prune target empties the forbidden
# set — the fail-open shape one level down from the empty-prune-set refusal — and refuses non-zero
# naming BOTH source files, before the --print-prune-set branch.
assert_eq "#1309 lint fail-closed: an exemption covering every target empties the forbidden set and refuses, naming both sources" "yes" \
  "$(case "$(sp_pruneset "$SP_FX/slices/only-docs.sh" "$SP_FX/schemas/ext-int.json")" in "rc=1|"*"only-docs.sh"*"ext-int.json"*"forbidden set empty"*) echo yes ;; "rc=1|"*"ext-int.json"*"only-docs.sh"*"forbidden set empty"*) echo yes ;; *) echo no ;; esac)"
# Assertion 8 (new-mechanism): --print-exempt-set emits the MEMBERS SUBTRACTED, not the full set of
# path-shaped docs.* defaults. Over the real slice+schema it is exactly docs/external and
# docs/internal — NOT docs/external/release-notes.md (a path-shaped default that is not a prune
# target, so it subtracts nothing). It emits nothing with exit 0 when the two sets share no member.
assert_eq "#1309 lint: --print-exempt-set emits exactly the subtracted prune targets (real tree)" \
  "docs/external docs/internal" \
  "$(cd "$LIB/.." && python3 "$SP_LINT" --print-exempt-set | python3 -c 'import sys; print(" ".join(sys.stdin.read().split()))')"
assert_eq "#1309 lint: --print-exempt-set emits nothing (exit 0) when the sets share no member" "rc=0|" \
  "$(sp_exemptset "$SP_SIMPLE" "$SP_FX/schemas/ext-int.json")"
# Assertion 9 (RED-first): over the REAL slice and schema the post-exemption prune set contains
# neither docs/external nor docs/internal. RED before #1309: both were present. (The pinned
# three-member expectation above and the real-tree clean run — which audits all skills/**+agents/**
# under both scan_text and scan_citations with the fifteen markers deleted — are the companions.)
assert_eq "#1309 lint: the real post-exemption prune set contains neither docs/external nor docs/internal" "" \
  "$(cd "$LIB/.." && python3 "$SP_LINT" --print-prune-set | grep -E '^docs/(external|internal)$' || true)"

# Marker-deletion census: a declaration on a line whose only prune-target match is an
# exempt root, and which suppresses no citation, is redundant. Re-derive that predicate from
# the live slice/schema and scan the complete tracked population so restoring any deleted
# false-positive marker makes this assertion RED.
assert_eq "#1309 lint: no redundant exempt-root-only pruned-path marker remains in the tracked population" "" \
  "$(cd "$LIB/.." && python3 - "$SP_LINT" <<'PY'
import importlib.util
import subprocess
import sys
from pathlib import Path

root = Path.cwd()
spec = importlib.util.spec_from_file_location("shipped_pruned_path", sys.argv[1])
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
all_targets = mod.parse_prune_targets(
    (root / mod.DEFAULT_SLICE_REL).read_text(encoding="utf-8", errors="replace")
)
defaults = mod.parse_docs_defaults((root / mod.DEFAULT_SCHEMA_REL).read_bytes())
exempt = [target for target in all_targets if target.rstrip("/") in defaults]
forbidden = [target for target in all_targets if target.rstrip("/") not in defaults]
paths = subprocess.run(
    ["git", "ls-files", "--", "skills/**", "agents/**"],
    cwd=root,
    check=True,
    capture_output=True,
    text=True,
).stdout.splitlines()
redundant = []
for relative in paths:
    lines = (root / relative).read_text(encoding="utf-8").split("\n")
    states = mod._fence_states(lines)
    for number, (line, fenced) in enumerate(zip(lines, states), 1):
        marker = mod._MARKER_SHELL if fenced else mod._MARKER_HTML
        if not marker.search(line):
            continue
        if not any(target in line for target in exempt):
            continue
        if any(target in line for target in forbidden) or mod._CITATION.search(line):
            continue
        redundant.append(f"{relative}:{number}")
print(" ".join(redundant))
PY
)"

# Audited-population behavior, driven over the fixture skills/ tree with a fixture slice (target
# lib/test). Every list rides through probe_tmp so the fixtures stay unreachable from the default
# index enumeration.
sp_run() {  # <slice> <path…> -> "rc=<n>|<stdout+stderr>"
  local slice="$1"; shift
  local list out rc
  list="$(probe_tmp '#1072 fixture list')" || return 0
  printf '%s\n' "$@" > "$list"
  # --schema-source is REQUIRED here: --root points at $SP_FX, which carries no
  # .prflow/config.schema.json, so the default schema path would be absent and the
  # lint would refuse. The real-shaped fixture schema keeps a lib/test-target slice
  # exemption-neutral (neither docs/external nor docs/internal is lib/test).
  out="$(python3 "$SP_LINT" --root "$SP_FX" --files-from "$list" --slice-source "$slice" --schema-source "$SP_SCHEMA" \
    --install-source "$SP_INSTALL_REAL" --workflows-source "$SP_WORKFLOWS_REAL" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
# test_unmarked_reference_is_reported / test_marked_reference_is_not — the discriminating pair.
assert_eq "#1072 lint: an unmarked reference is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/unmarked.md)" in "rc=1|"*"skills/unmarked.md:1:"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1072 lint: a marked (HTML) reference is not reported" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/marked-html.md)"
# test_marker_with_empty_reason_is_reported.
assert_eq "#1072 lint: a marker with an empty reason is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/marked-empty.md)" in "rc=1|"*"skills/marked-empty.md:1:"*) echo yes ;; *) echo no ;; esac)"
# An HTML comment that is not the marker does not suppress.
assert_eq "#1072 lint: an HTML comment that is not the marker does not suppress" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/html-nonmarker.md)" in "rc=1|"*"skills/html-nonmarker.md:1:"*) echo yes ;; *) echo no ;; esac)"
# A clean file with no reference is silent.
assert_eq "#1072 lint: a file with no reference is clean" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/clean.md)"

# ── #1241 citation check: PRFlow-internal issue/PR-number + acceptance-criterion references ──
# skills/** and agents/** ship verbatim into a consumer, so a `#441`/`issue #441`/`AC5`
# citation resolves against THIS repo's own tracker and points at nothing in a consumer.
# The citation scan rides the SAME audited population and the SAME pruned-path-ok marker
# family as the prune-path scan. Both directions are exercised (AC4): an unmarked citation
# is reported, a marked one is suppressed; the AC-reference row covers the second shape.
assert_eq "#1241 lint: an unmarked issue-number citation is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/cite-unmarked.md)" in "rc=1|"*"skills/cite-unmarked.md:1:"*"cites PRFlow-internal '#441'"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1241 lint: a marked citation is not reported" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/cite-marked.md)"
assert_eq "#1241 lint: an unmarked acceptance-criterion reference is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/cite-ac.md)" in "rc=1|"*"skills/cite-ac.md:1:"*"cites PRFlow-internal 'AC5'"*) echo yes ;; *) echo no ;; esac)"
# The `#\d+\b` word boundary exists precisely so a hex colour (`#1D76DB`, whose `#1` is
# followed by a letter) and a bare run id (no `#`) are NOT citations — guard that boundary
# so dropping the `\b` (which would flip a hex colour into a false finding) fails RED.
assert_eq "#1241 lint: a hex colour and a run id are not citations (word-boundary control)" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/cite-hex-clean.md)"
# `\bAC\d+\b`'s LEADING boundary is the counterpart control to `cite-hex-clean`'s trailing
# one: `MAC5` embeds `AC5` and `AC-5` is a non-recognized adjacent spelling, so dropping the
# leading `\b` (or broadening to the hyphenated form) turns this fixture RED.
assert_eq "#1241 lint: MAC5 and AC-5 are not citations (AC leading-boundary control)" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/cite-ac-boundary-clean.md)"
# The docstring advertises the `PR`-prefixed number shape distinctly from the bare one;
# exercise it so the advertised form is a tested claim rather than a prose assertion. The
# assertion LABEL must not itself spell a `#`-number: the issue-591 coverage-map guard reads
# `#N` out of run.sh assertion labels as a coverage label, so a fixture shape quoted into a
# label is indistinguishable there from a real issue reference and files a phantom entry.
assert_eq "#1241 lint: an unmarked PR-prefixed number citation is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/cite-pr-unmarked.md)" in "rc=1|"*"skills/cite-pr-unmarked.md:1:"*"cites PRFlow-internal '#123'"*) echo yes ;; *) echo no ;; esac)"
# `_scan` reports the FIRST match per line only. Pin it with an exact-output assertion: a
# change to per-match reporting would emit a second finding line and turn this RED.
assert_eq "#1241 lint: two citations on one line report the first only" \
  "rc=1|skills/cite-two-on-one-line.md:1: cites PRFlow-internal '#441' (issue/PR or acceptance-criterion reference) with no pruned-path-ok marker
lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/cite-two-on-one-line.md)"
# Fence branch for the CITATION scan (the prune-path scan's fence matrix below covers only
# path references). `_scan` newly decides these three for citations too, so each is driven:
# an unmarked citation inside a fence is reported; the shell-form marker suppresses inside a
# fence; the HTML-form marker does NOT (a fenced line is emitted verbatim into a shell).
assert_eq "#1241 lint fence-state: an unmarked citation inside a fence is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/cite-fence-unmarked.md)" in "rc=1|"*"skills/cite-fence-unmarked.md:3:"*"cites PRFlow-internal '#441'"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1241 lint fence-state: a # marker inside a fence suppresses a citation" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/cite-fence-shell-marked.md)"
assert_eq "#1241 lint fence-state: an HTML marker inside a fence does not suppress a citation" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/cite-fence-html-marked.md)" in "rc=1|"*"skills/cite-fence-html-marked.md:3:"*"cites PRFlow-internal '#441'"*) echo yes ;; *) echo no ;; esac)"
# test_marker_in_emitted_fence + fence-state matrix (AC14/AC15). Each row states its own reason.
while IFS='|' read -r _sp_file _sp_expect _sp_why; do
  [ -n "$_sp_file" ] || continue
  assert_eq "#1072 lint fence-state: $_sp_why ($_sp_file)" "$_sp_expect" \
    "$(case "$(sp_run "$SP_SIMPLE" "$_sp_file")" in "rc=0|"*) echo suppressed ;; *"$_sp_file:"*) echo reported ;; *) echo other ;; esac)"
done <<'SP_FENCE'
skills/fence-shell.md|suppressed|a # pruned-path-ok marker inside a backtick fence suppresses
skills/fence-html-in-fence.md|reported|an HTML marker inside a fence is not recognized
skills/fence-tilde.md|suppressed|a # marker inside a tilde fence suppresses
skills/fence-tilde-in-backtick.md|suppressed|a tilde line does not close a backtick fence
skills/fence-unclosed.md|suppressed|an unclosed fence runs to end of file
skills/fence-indented.md|reported|an indented fence is not recognized, so the shell marker does not apply
SP_FENCE
# AC18 / test_planted_reference_is_caught: the positive control — skills/planted.md is a verbatim
# copy of the head of skills/review/phases/phase-0-setup.md (real prose, a real fenced block) into
# which a prune-target reference has been planted after the fence; the lint reports it.
assert_eq "#1072 lint: a planted reference in a shipped-file copy is caught (positive control)" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/planted.md)" in "rc=1|"*"skills/planted.md:"*) echo yes ;; *) echo no ;; esac)"
# The audited SUBSET carries its own floor. enumerate_population floors on zero TOTAL index paths,
# BEFORE is_audited() narrows to skills/**+agents/**, so an enumeration that selects only
# non-audited paths reaches the read loop zero times and would print `audited 0 of 0` and return 0
# — a clean pass over an unchecked shipped surface, the lint's own fail-open class one level up.
# The pair below is discriminating: the same invocation differing only in whether ONE audited path
# is present separates the floor from any unrelated refusal.
assert_eq "#1072 lint: an enumeration selecting no skills/agents path refuses (empty-audited floor)" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" slices/simple.sh)" in "rc=1|"*"selected no file under skills/ or agents/"*) echo yes ;; *) echo no ;; esac)"
# Positive control on the same shape, doubling as is_audited's negative half: adding ONE audited
# path to that same list audits and passes, and the `1 of 1` count proves the non-audited
# slices/simple.sh was excluded rather than read. So the refusal above is attributable to the empty
# subset, not to the list mechanism.
assert_eq "#1072 lint: the same list plus one audited path audits 1 of 1 (floor control + is_audited negative)" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" slices/simple.sh skills/clean.md)"
# The agents/ prefix, which the real-tree positive-count assertion cannot isolate from skills/.
assert_eq "#1072 lint: an agents/ path is audited (second prefix, reported like skills/)" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" agents/unmarked-agent.md)" in "rc=1|"*"agents/unmarked-agent.md:1:"*) echo yes ;; *) echo no ;; esac)"
# A NUL-carrying file is a fail-closed skip, never absorbed into a clean pass.
#
# The NUL fixture is GENERATED here rather than tracked. Its former tracked path was
# lib/test/fixtures/shipped-pruned-path/skills/nul.md, and BOTH of that path's properties are
# hazards to a consumer: `nul` is a Windows reserved device-name stem, which git's own checkout
# path validation refuses there (`error: invalid path '<path>'`), and the file's bytes carry a
# NUL. This repository is published as a marketplace whose plugin `source` is `./`, so the whole
# tree is the plugin — one unwriteable path takes `claude plugin marketplace add/update` down for
# every consumer on that platform, and lib/test being pruned from the vendor slice does not help,
# because the refusal happens at clone/checkout time, before any pruning. Generating the fixture
# removes both properties from the index at once: nothing about this assertion needs the file to
# be tracked, only for a file whose bytes carry a NUL to exist when the lint reads it.
#
# The root comes from git_sandbox for its fail-closed sentinel (no git is run inside it): on an
# mktemp failure the mkdir below fails with ENOTDIR, the lint then reports an `unreadable` skip
# rather than the NUL skip, and the reason-specific assertion goes RED instead of passing on a
# fixture that never materialized.
SP_NUL_ROOT="$(git_sandbox '#1072 generated NUL fixture root')"
mkdir -p "$SP_NUL_ROOT/skills" 2>/dev/null
# Seed a vendored-provenance SKILL.md (issue #1401) so this generated root's derived
# vendored-skill scope is non-empty — otherwise the empty-derivation refusal fires
# before the NUL skip this pair asserts. The seeded dir holds no forbidden token, and
# the NUL fixtures below live directly under skills/ (not under it), so it changes no
# other behavior here.
mkdir -p "$SP_NUL_ROOT/skills/vendored" 2>/dev/null
printf 'Originates in the MIT-licensed `superpowers` plugin.\n' > "$SP_NUL_ROOT/skills/vendored/SKILL.md" 2>/dev/null
printf 'refers to lib/test/run.sh\000 with a NUL byte\n' > "$SP_NUL_ROOT/skills/nul-byte.md" 2>/dev/null
# The control writes the SAME line with the NUL byte removed, so the pair differs in exactly one
# byte. It is what attributes the skip to the NUL rather than to the generated root, the file
# name, or the --files-from plumbing: without the NUL the file is scanned to completion and its
# `lib/test` reference is REPORTED, which a skipped file's output can never look like.
printf 'refers to lib/test/run.sh with a NUL byte\n' > "$SP_NUL_ROOT/skills/no-nul.md" 2>/dev/null
sp_run_root() {  # <root> <slice> <path…> -> "rc=<n>|<stdout+stderr>"
  local root="$1" slice="$2"; shift 2
  local list out rc
  list="$(probe_tmp '#1072 generated fixture list')" || return 0
  printf '%s\n' "$@" > "$list"
  # --schema-source is REQUIRED (issue #1309): $root is a generated sandbox with no
  # .prflow/config.schema.json, so the default schema path would be absent and the lint
  # would refuse before ever reaching the NUL skip this pair asserts. The real-shaped
  # fixture schema is exemption-neutral for the lib/test-target slice used here.
  out="$(python3 "$SP_LINT" --root "$root" --files-from "$list" --slice-source "$slice" --schema-source "$SP_SCHEMA" \
    --install-source "$SP_INSTALL_REAL" --workflows-source "$SP_WORKFLOWS_REAL" 2>&1)"; rc=$?
  rm -f "$list"
  printf 'rc=%s|%s' "$rc" "$out"
}
assert_eq "#1072 lint: a NUL-carrying file is a fail-closed skip naming the NUL reason" "yes" \
  "$(case "$(sp_run_root "$SP_NUL_ROOT" "$SP_SIMPLE" skills/nul-byte.md)" in
       "rc=1|"*"SKIPPED skills/nul-byte.md: not a UTF-8-superset text file (NUL bytes"*) echo yes ;;
       *) echo no ;; esac)"
assert_eq "#1072 lint: the same line without the NUL byte is scanned and reported (NUL-skip control)" "yes" \
  "$(case "$(sp_run_root "$SP_NUL_ROOT" "$SP_SIMPLE" skills/no-nul.md)" in
       *"SKIPPED"*) echo no ;;
       "rc=1|skills/no-nul.md:1: references pruned path 'lib/test'"*) echo yes ;;
       *) echo no ;; esac)"
rm -rf "$SP_NUL_ROOT"
# test_slice_source_independent_of_root (AC12): the run reads the FIXTURE slice, not the repo's —
# proven by the reported prune set being the fixture's single member, not the repo's three.
assert_eq "#1072 lint: --slice-source is read independently of --root" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/clean.md)" in *"prune set: lib/test"*) echo yes ;; *) echo no ;; esac)"
# AC12 default: with no --slice-source, the default is <root>/.github/actions/vendor-plugin/
# vendor-slice.sh — absent under the fixture root, so the run refuses naming that path.
assert_eq "#1072 lint: the default slice source is the resolved root's vendor-slice.sh" "yes" \
  "$(SP_L="$(probe_tmp '#1072 default-slice list')" && printf '%s\n' skills/clean.md > "$SP_L"
     SP_D="$(python3 "$SP_LINT" --root "$SP_FX" --files-from "$SP_L" 2>&1)"; rm -f "$SP_L"
     case "$SP_D" in *".github/actions/vendor-plugin/vendor-slice.sh"*) echo yes ;; *) echo no ;; esac)"
# main()-level fail-closed red-paths: an enumeration failure and an unreadable audited file both
# fail closed (rc 1), never a silent clean pass. Monkeypatch the shared population reader, mirroring
# the #1084 driver, so the fail-closed arms are exercised without fixture plumbing.
assert_eq "#1072 lint: main() fail-closed red-paths (enumeration failure / unreadable file)" "1 1" \
  "$(python3 - "$SP_LINT" "$SP_SIMPLE" <<'PY'
import importlib.util, io, sys, contextlib
spec = importlib.util.spec_from_file_location("sp", sys.argv[1])
sp = importlib.util.module_from_spec(spec); spec.loader.exec_module(sp)
argv = ["--slice-source", sys.argv[2]]
def run(pop_fn, reader):
    sp._pop.enumerate_population = pop_fn
    sp._pop.read_source = reader
    with contextlib.redirect_stderr(io.StringIO()), contextlib.redirect_stdout(io.StringIO()):
        return sp.main(argv)
def raise_enum(root, ff, *, ls_files_argv):
    raise sp._pop.EnumerationError("git ls-files failed")
r_enum = run(raise_enum, lambda p, *, skip_nul: ("", None))
r_skip = run(lambda root, ff, *, ls_files_argv: ["skills/x.md"],
             lambda p, *, skip_nul: (None, "unreadable (permission)"))
print(r_enum, r_skip)
PY
)"

# ── #1401 vendored-skill CLAUDE.md-token ban (lib/test/lint-shipped-pruned-path.py) ──
# A vendored skill body (skills/receiving-code-review/, skills/requesting-code-review/)
# ships verbatim into every consumer, so a pointer to PRFlow's own CLAUDE.md resolves
# against the consumer's unrelated project-memory file. The lint bans the CLAUDE.md
# token, but ONLY inside the DERIVED vendored-skill directories — every skills/<name>/
# whose SKILL.md carries the vendored-provenance sentence — so the correct generic
# CLAUDE.md references every other shipped file carries are not reported. The fixture
# skills/receiving-code-review/ and skills/requesting-code-review/ dirs under $SP_FX each
# carry a provenance-bearing SKILL.md so the derivation is non-empty; a skills/implement/
# SKILL.md and an agents/ file (no provenance) are the scope negative controls. The cases
# below are complete by construction (issue #1401).
# Case 1 — fires on the SKILL member itself.
assert_eq "#1401 lint: a CLAUDE.md reference in a vendored SKILL.md is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/receiving-code-review/SKILL.md)" in "rc=1|"*"skills/receiving-code-review/SKILL.md:"*"references PRFlow's own 'CLAUDE.md'"*) echo yes ;; *) echo no ;; esac)"
# Case 2 — fires on a non-SKILL companion under the same derived directory (the scope is
# the directory, not a two-file list — this is skills/requesting-code-review/code-reviewer.md's real risk).
assert_eq "#1401 lint: a CLAUDE.md reference in a non-SKILL vendored file is reported (derived-directory scope)" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/requesting-code-review/code-reviewer.md)" in "rc=1|"*"skills/requesting-code-review/code-reviewer.md:"*"references PRFlow's own 'CLAUDE.md'"*) echo yes ;; *) echo no ;; esac)"
# Case 3 — the shared declaration marker discharges the reference.
assert_eq "#1401 lint: a marked CLAUDE.md reference in a vendored file is not reported" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/receiving-code-review/marked-claude.md)"
# Case 4 (both directions) — docs/CLAUDE.md contains the token as a substring and fires;
# CLAUDE.local.md does not contain it as a substring and is clean. This pair exists to stop
# an implementer widening the plain substring test into a regular expression.
assert_eq "#1401 lint: docs/CLAUDE.md contains the token as a substring and is reported" "yes" \
  "$(case "$(sp_run "$SP_SIMPLE" skills/receiving-code-review/docs-claude.md)" in "rc=1|"*"docs-claude.md:"*"references PRFlow's own 'CLAUDE.md'"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1401 lint: CLAUDE.local.md does not contain the token as a substring and is clean" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/receiving-code-review/claude-local.md)"
# Case 5 — an empty derived population fails closed. Needs a root of its own: a seeded
# $SP_FX can no longer produce an empty derivation.
SP_EMPTY_ROOT="$(git_sandbox '#1401 empty-derivation root')"
mkdir -p "$SP_EMPTY_ROOT/skills" 2>/dev/null
printf 'names CLAUDE.md but no vendored SKILL.md exists in this tree\n' > "$SP_EMPTY_ROOT/skills/x.md" 2>/dev/null
assert_eq "#1401 lint: an empty vendored-skill derivation refuses, naming the empty population" "yes" \
  "$(case "$(sp_run_root "$SP_EMPTY_ROOT" "$SP_SIMPLE" skills/x.md)" in "rc=1|"*"no skills/<name>/SKILL.md"*"empty derived population"*) echo yes ;; *) echo no ;; esac)"
rm -rf "$SP_EMPTY_ROOT"
# Case 6 — scope negative controls: the token in a non-vendored skill SKILL.md and in an
# agents/ file is correct generic usage and is NOT reported.
assert_eq "#1401 lint: CLAUDE.md in a non-vendored skill SKILL.md is not reported (scope control)" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/implement/SKILL.md)"
assert_eq "#1401 lint: CLAUDE.md in an agents/ file is not reported (scope control)" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" agents/code-reviewer.md)"
# Case 7 — the directory-prefix boundary. Membership is startswith() over a TRAILING-SLASH
# member, so a sibling whose name merely prefixes a derived directory is out of scope; drop
# the slash and every skills/receiving-code-review-*/ tree would be scanned as vendored.
assert_eq "#1401 lint: a sibling directory that merely prefixes a derived one is not reported" "rc=0|lint-shipped-pruned-path: audited 1 of 1 files; prune set: lib/test" \
  "$(sp_run "$SP_SIMPLE" skills/receiving-code-review-x/notes.md)"
# The scope key is an exact prose substring, so a reword in ONE vendored body drops that
# directory from scope while the other keeps the empty-derivation guard quiet — the reword
# that most needs the ban is the one that would silently lift it. Mirrors the #1072 derived
# prune-set floor: the expectation literal is the drift-proof record of the membership.
assert_eq "#1401 lint: the derived vendored-skill scope matches the checked-in expectation" \
  "skills/receiving-code-review/ skills/requesting-code-review/" \
  "$(cd "$LIB/.." && python3 - "$SP_LINT" <<'PY'
import importlib.util, pathlib, sys
spec = importlib.util.spec_from_file_location("sp", sys.argv[1])
sp = importlib.util.module_from_spec(spec); spec.loader.exec_module(sp)
print(" ".join(sorted(sp.derive_vendored_skill_dirs(pathlib.Path.cwd()))))
PY
)"
# An unreadable skills/*/SKILL.md refuses instead of silently narrowing the scope: without
# this arm one unreadable body leaves a non-empty derivation and its whole directory escapes.
SP_UNREADABLE_ROOT="$(git_sandbox '#1401 unreadable-SKILL root')"
# A DIRECTORY named SKILL.md is an unreadable member on every platform (IsADirectoryError /
# PermissionError, both OSError) — deterministic where a chmod is not, since CI may run as root.
mkdir -p "$SP_UNREADABLE_ROOT/skills/vendored/SKILL.md" 2>/dev/null
assert_eq "#1401 lint: an unreadable vendored SKILL.md fails the scope derivation closed" "VendoredScopeError" \
  "$(python3 - "$SP_LINT" "$SP_UNREADABLE_ROOT" <<'PY'
import importlib.util, pathlib, sys
spec = importlib.util.spec_from_file_location("sp", sys.argv[1])
sp = importlib.util.module_from_spec(spec); spec.loader.exec_module(sp)
try:
    sp.derive_vendored_skill_dirs(pathlib.Path(sys.argv[2]))
except sp.VendoredScopeError:
    print("VendoredScopeError")
else:
    print("no-raise")
PY
)"
rm -rf "$SP_UNREADABLE_ROOT"

# ── #1402 never-shipped-workflow class (lib/test/lint-shipped-pruned-path.py) ──
# Why membership rather than a path ban, and why the set is derived: see the
# lint-shipped-pruned-path.py module docstring's never-shipped section.
# --- Derivation matrix over synthetic install.sh + workflow-source pairs. ---
sp_neverset() {  # <install> <workflows> — shares sp_printset's encoder (no drift)
  sp_encode --print-never-shipped-set --install-source "$1" --workflows-source "$2"
}
# The fixture install.sh carries the withheld-tier loop (which iterates a VARIABLE) BEFORE the
# copy loop, and both loop bodies name .github/workflows/$<var>.yml. A parser keyed on the body
# reference alone selects the decoy and derives no name; only the literal-operand conjunct tells
# them apart. Dropping that conjunct turns this assertion RED.
assert_eq "#1402 lint: the derived never-shipped set is the workflow-source complement of the copy loop" \
  "rc=0|alpha beta internal-only probe" \
  "$(sp_neverset "$SP_INSTALL_FX" "$SP_WORKFLOWS_FX")"
# Membership is over PARSED WORD LISTS, never a substring search. The decoy fixture carries
# `probe` and `alpha` as substrings of unrelated lines, including prose that REMOVES the probe
# tier — under a substring test both would read as shipped and drop out of the forbidden set.
assert_eq "#1402 lint: membership is word-list, not substring (a decoy occurrence does not ship a name)" \
  "rc=0|alpha beta internal-only probe shipped-two" \
  "$(sp_neverset "$SP_FX/installs/substring-decoy.sh" "$SP_WORKFLOWS_FX")"
# One token is one loop iteration: a QUOTED operand list iterates a single joined value,
# so neither member is installed and both stay forbidden. Re-splitting the token on
# whitespace — which `_literal_words` did while DEVFLOW_WITHHELD_TIER was its producer —
# drops both from the set below, a fail-open this fixture is the control for.
assert_eq "#1402/#1423 lint: a QUOTED copy-loop operand list ships neither member" \
  "rc=0|alpha beta internal-only probe shipped-one shipped-two" \
  "$(sp_neverset "$SP_FX/installs/quoted-loop.sh" "$SP_WORKFLOWS_FX")"
# Fail-closed arms: each unestablished declaration refuses non-zero naming install.sh and its
# own cause, so an unestablished set is never silently an empty one.
assert_eq "#1402 lint fail-closed: no loop naming a workflow path refuses, naming install.sh" "yes" \
  "$(case "$(sp_neverset "$SP_FX/installs/no-copy-loop.sh" "$SP_WORKFLOWS_FX")" in "rc=1|"*"no-copy-loop.sh"*"no workflow copy loop found"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1402 lint fail-closed: a variable-only candidate loop refuses, naming install.sh" "yes" \
  "$(case "$(sp_neverset "$SP_FX/installs/variable-only-loop.sh" "$SP_WORKFLOWS_FX")" in "rc=1|"*"variable-only-loop.sh"*"declares a literal workflow name"*) echo yes ;; *) echo no ;; esac)"
# Issue #1423: the DECISION, pinned at the derivation. The withheld tier ships nothing, so
# the lint does not read DEVFLOW_WITHHELD_TIER at all and its members stay forbidden.
# Neither fixture's declaration shape — absent in `no-withheld.sh`, empty in
# `empty-withheld.sh` — can change the derived set, so each still derives the copy-loop
# complement rather than refusing. Re-reading the declaration would turn these two and the
# duplicated-declaration case further below RED.
assert_eq "#1402/#1423 lint: an absent DEVFLOW_WITHHELD_TIER does not refuse (the lint does not read it)" \
  "rc=0|alpha beta internal-only probe" \
  "$(sp_neverset "$SP_FX/installs/no-withheld.sh" "$SP_WORKFLOWS_FX")"
assert_eq "#1402/#1423 lint: an empty DEVFLOW_WITHHELD_TIER does not refuse (the lint does not read it)" \
  "rc=0|alpha beta internal-only probe" \
  "$(sp_neverset "$SP_FX/installs/empty-withheld.sh" "$SP_WORKFLOWS_FX")"
# The print flag exits before the slice and schema reads, so a query about the workflow set
# cannot be refused by — or misdiagnosed against — a source it never consults.
assert_eq "#1402 lint: --print-never-shipped-set is independent of the slice and schema sources" \
  "rc=0|agents-seam-probe ci devflow-runner matcher-probe stall-observer telemetry-push version-consolidate" \
  "$(cd "$LIB/.." && sp_encode --print-never-shipped-set --slice-source /dev/null --schema-source /dev/null)"
# Selection collects every candidate before choosing, so ambiguity refuses rather than
# resolving by position. Both conjuncts say nothing about a loop's DIRECTION — the fixture's
# removal loop over literal workflow names satisfies them and would invert the shipped set.
assert_eq "#1402 lint fail-closed: two literal workflow loops refuse, naming both lines" "yes" \
  "$(case "$(sp_neverset "$SP_FX/installs/two-literal-loops.sh" "$SP_WORKFLOWS_FX")" in "rc=1|"*"more than one loop over literal workflow names"*"lines 7, 12"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1402/#1423 lint: a duplicated DEVFLOW_WITHHELD_TIER does not refuse (the lint does not read it)" \
  "rc=0|alpha beta internal-only probe" \
  "$(sp_neverset "$SP_FX/installs/two-withheld.sh" "$SP_WORKFLOWS_FX")"
# A workflows source that is not a git repository is an unestablished listing, not an empty
# one — the arm that decides whether an unreadable population fails closed or degrades.
assert_eq "#1402 lint fail-closed: a non-repository workflows source refuses, naming git's own error" "yes" \
