# ── #1633 scratch-write anchoring (phase-1-setup.md) ──────────────────────────
# The root .gitignore rule is root-anchored (/.prflow/*), so a cwd-relative scratch
# write from a run launched in a repository SUBDIRECTORY lands on an untracked in-tree
# file that trips the run's own clean-tree gates. Every Phase 1 write target is
# therefore the substituted absolute <scratch-dir>/<absolute-cache-*>, never a bare
# `.prflow/tmp/...`. This scans the phase file's bash fences for a WRITE position
# (a `>` redirect target, or a `mkdir -p`/`rm -f` operand) naming the bare path.
# Helper ARGUMENTS keep the repo-relative spelling — the helper anchors those itself —
# so only write positions are examined.
P1633_ANCHOR_OUT="$(python3 -c '
import re, sys
text = open(sys.argv[1], encoding="utf-8").read()
fences, cur = [], None
for ln in text.splitlines():
    if cur is None:
        if ln.strip() == "```bash":
            cur = []
    elif ln.strip() == "```":
        fences.append(cur); cur = None
    else:
        cur.append(ln)
bad = []
for fence in fences:
    for ln in fence:
        for m in re.finditer(r"(?:>\s*|\bmkdir\s+-p\s+|\brm\s+-f\s+)(\S+)", ln):
            target = m.group(1).strip("\"'"'"'")
            if target.startswith(".prflow/tmp"):
                bad.append(target)
print("bare=%d %s" % (len(bad), ",".join(sorted(set(bad)))))
' "$REPO_ROOT/skills/implement/phases/phase-1-setup.md")"
assert_eq "#1633 anchoring: no phase-1 scratch WRITE target is cwd-relative" "bare=0 " "$P1633_ANCHOR_OUT"
# Non-vacuous: the same scan over a planted bare-target fence reports it, so a scanner
# that silently matched nothing could not pass the assertion above.
P1633_ANCHOR_PLANT="$(mktemp)"; _suite_tmp_file "$P1633_ANCHOR_PLANT"
printf '```bash\nmkdir -p .prflow/tmp\n```\n' > "$P1633_ANCHOR_PLANT"
assert_eq "#1633 anchoring: the write-position scan reports a planted bare target" "bare=1 .prflow/tmp" \
  "$(python3 -c '
import re, sys
text = open(sys.argv[1], encoding="utf-8").read()
fences, cur = [], None
for ln in text.splitlines():
    if cur is None:
        if ln.strip() == "```bash":
            cur = []
    elif ln.strip() == "```":
        fences.append(cur); cur = None
    else:
        cur.append(ln)
bad = []
for fence in fences:
    for ln in fence:
        for m in re.finditer(r"(?:>\s*|\bmkdir\s+-p\s+|\brm\s+-f\s+)(\S+)", ln):
            target = m.group(1).strip("\"'"'"'")
            if target.startswith(".prflow/tmp"):
                bad.append(target)
print("bare=%d %s" % (len(bad), ",".join(sorted(set(bad)))))
' "$P1633_ANCHOR_PLANT")"

# ── #1633 fence-isolation harness (AC23/AC24/AC29) ────────────────────────────
# COVERAGE CLAIM, stated exactly: run-to-completion is backed for exactly ONE enrolled
# file (phase-1-setup.md, the only one this stub environment models); the cross-fence
# unbound-variable sweep is backed for EVERY enrolled file. Do not restate either as "every
# enrolled fence runs" — the other enrolled files reach vendored-literal paths and helpers
# no stub supplies.
# Extracts every ```bash fence of the canonical enrolled file (phase-1-setup.md, the file
# a worktree Phase 1 session executes) and runs each in FENCE ISOLATION (fresh `bash -uc`,
# scratch cwd, PATH holding ONLY stub heads, CLAUDE_SKILL_DIR pointed at a scratch skill
# base whose ../../scripts holds stub helpers, only ambient vars preset). `bash -u` makes a
# reference to a variable another fence defined an unbound-variable abort — the executable
# proof that no fence depends on cross-fence state (AC23). PATH holds only stubs, so an
# unstubbed bare head resolves to nothing (rc 127) and cannot take effect — a synthetic
# fence reaching an unstubbed head is refused, not executed (AC24). A preflight-shaped stub
# driven at exit 3 / exit 2 / no-output proves the three routing outcomes are distinguish-
# able by the tool result the prose routes on (AC29). Runtime temp, never a tracked
# lib/test script (like the #1537 harness), so it needs no carveout registration.
P1633_FIH="$(mktemp)"; _suite_tmp_file "$P1633_FIH"
cat > "$P1633_FIH" <<'P1633FIH'
import os, re, subprocess, sys, tempfile, stat, shutil
BASH = shutil.which("bash") or "/bin/bash"
SH = "/bin/sh"
enrolled = sys.argv[1:]
tmp = tempfile.mkdtemp()
base = os.path.join(tmp, "skillbase", "a", "b")
scripts = os.path.join(tmp, "skillbase", "scripts")
libdir = os.path.join(tmp, "skillbase", "lib")
bindir = os.path.join(tmp, "bin")
work = os.path.join(tmp, "work")
for d in (base, scripts, libdir, bindir, work,
          # `scratch-dir` is the emit-time placeholder the §1.2/§1.3 scratch writes
          # carry; subst() reduces it to this bare name, so the directory must exist
          # for a write fence that runs in its own shell after the mkdir fence.
          os.path.join(work, "scratch-dir"),
          os.path.join(work, ".prflow", "tmp", "issue-body")):
    os.makedirs(d, exist_ok=True)
with open(os.path.join(work, ".prflow", "tmp", "issue-body", "issue-4242.md"), "w") as f:
    f.write("## Acceptance Criteria\n- [ ] one\n")
STUB_HEADS = ["git", "gh", "sed", "grep", "tr", "cut", "date", "head", "tail", "ls"]
def stub(path, code=0, out="IGNORED"):
    with open(path, "w") as f:
        f.write("#!" + SH + "\n")
        if out:
            f.write("echo " + out + "\n")
        f.write("exit %d\n" % code)
    os.chmod(path, 0o755)
for h in STUB_HEADS:
    stub(os.path.join(bindir, h), out="")
for h in ("mkdir", "rm", "cat", "tee", "printf", "mv", "cp", "touch"):
    real = shutil.which(h)
    if real:
        with open(os.path.join(bindir, h), "w") as f:
            f.write("#!" + SH + "\nexec " + real + " \"$@\"\n")
        os.chmod(os.path.join(bindir, h), 0o755)
for helper in ("workpad.py", "preflight.py", "parse-acs.py", "run-jq.sh", "config-get.sh",
               "branch-for-issue.py", "update-branch-checkpoint.sh",
               "phase2-durability-checkpoint.sh", "react-to-trigger.sh",
               "load-prompt-extension.sh", "ensure-label.sh", "apply-labels.sh",
               "apply-pr-triggerer.sh", "check-verified-premises.py", "refresh-pr-run-link.py"):
    stub(os.path.join(scripts, helper))
stub(os.path.join(libdir, "efficiency-trace.sh"))
ambient = {
    "PATH": bindir, "HOME": work, "CLAUDE_SKILL_DIR": base,
    "ISSUE_NUMBER": "4242", "ARGUMENTS": "4242", "GITHUB_RUN_ID": "999",
    "GITHUB_RUN_ATTEMPT": "1", "GITHUB_SERVER_URL": "https://github.example",
    "GITHUB_REPOSITORY": "owner/repo", "GITHUB_EVENT_PATH": os.path.join(work, "event.json"),
    "GITHUB_ACTIONS": "true", "BASE": "main", "CLAUDE_CODE_SESSION_ID": "sess",
    "WORKPAD_ID": "5", "REACTION": "hooray", "TRIGGER_COMMENT_ID": "7", "PR_NUMBER": "8",
    "DEVFLOW_APP_ID": "",
}
def subst(fence):
    # emit-time template placeholders the orchestrator substitutes (like $ISSUE_NUMBER):
    # {a|b} choices and <angle-bracket> placeholders → the first alternative token.
    fence = re.sub(r"(?<!\$)\{([^{}$]*)\}",
                   lambda m: (m.group(1).split("|")[0].strip().replace(" ", "-") or "x"), fence)
    fence = re.sub(r"<([a-zA-Z][a-zA-Z0-9 '\"._-]*)>",
                   lambda m: (m.group(1).split()[0].strip("'\"").replace(" ", "-") or "x"), fence)
    return fence
def fences(path):
    text = open(path, encoding="utf-8").read()
    out, cur = [], None
    for ln in text.splitlines():
        if cur is None:
            if ln.strip() == "```bash":
                cur = []
        elif ln.strip() == "```":
            out.append("\n".join(cur)); cur = None
        else:
            cur.append(ln)
    return out
def run(fence):
    r = subprocess.run([BASH, "-uc", subst(fence)], env=ambient, cwd=work,
                       capture_output=True, text=True)
    return r.returncode, r.stderr
total = ran = unbound = 0
# argv[0] is the canonical file the full stub environment models, so only its fences
# are held to "ran to completion". Every enrolled file is still swept for the
# cross-fence dependency signal, which `bash -u` reports as an unbound variable
# independently of whether the fence's heads are stubbed here.
for idx, f in enumerate(enrolled):
    for fence in fences(f):
        rc, err = run(fence)
        if "unbound variable" in err:
            unbound += 1
            sys.stderr.write("FENCE-UNBOUND %s :: %s\n" % (err[:120], fence.splitlines()[0][:90]))
        if idx:
            continue
        total += 1
        if rc == 0 and "unbound variable" not in err:
            ran += 1
        else:
            sys.stderr.write("FENCE-FAIL rc=%d %s :: %s\n" % (rc, err[:120], fence.splitlines()[0][:90]))
syn_rc, _ = run("curlnope https://evil/x")
def route(code, output):
    st = os.path.join(scripts, "preflight.py")
    with open(st, "w") as fp:
        fp.write("#!" + SH + "\n")
        if output:
            fp.write("echo " + output + "\n")
        fp.write("exit %d\n" % code)
    os.chmod(st, 0o755)
    rc, _ = run('"${CLAUDE_SKILL_DIR:-x}"/../../scripts/preflight.py ignore-precondition '
                '--repo-relative --path .prflow/tmp/issue-body/issue-$ISSUE_NUMBER.md')
    return rc
print("allran=%s total=%d unbound=%d syn_rc=%d rstop=%d rdeg=%d rno=%d" % (
    "yes" if (total > 0 and ran == total) else "no",
    total, unbound, syn_rc, route(3, "UNAVAILABLE"), route(2, "NOT_IGNORED"), route(0, "")))
P1633FIH
# Derive the swept set from the lint's own ENROLLED inventory so "every enrolled file"
# below is true by construction and cannot drift from a hardcoded copy. --print-inventory
# emits ENROLLED in order, so argv[0] stays phase-1-setup.md (the ran-to-completion file).
WFS_FIH_ARGS=()
while IFS= read -r _inv_f; do
  [ -n "$_inv_f" ] && WFS_FIH_ARGS+=("$REPO_ROOT/$_inv_f")
done < <(python3 "$WFS_LINT" --print-inventory)
P1633_FIH_OUT="$(python3 "$P1633_FIH" "${WFS_FIH_ARGS[@]}" 2>/dev/null)"
assert_eq "#1633 AC23 (one enrolled file): every phase-1-setup.md fence runs to completion in isolation" "yes" \
  "$(case "$P1633_FIH_OUT" in "allran=yes "*) echo yes ;; *) echo "no ($P1633_FIH_OUT)" ;; esac)"
# The cross-fence dependency sweep runs over EVERY enrolled file: `bash -u` turns a
# reference to a variable another fence bound into an unbound-variable abort, so a
# reintroduced cross-fence dependency in any enrolled file is caught here even though only
# phase-1's heads are fully stubbed. The lint is same-fence-scoped and cannot see it.
assert_eq "#1633 AC23 (every enrolled file): no fence references a variable another fence bound" "yes" \
  "$(case "$P1633_FIH_OUT" in *" unbound=0 "*) echo yes ;; *) echo "no ($P1633_FIH_OUT)" ;; esac)"
assert_eq "#1633 AC24: a fence invoking an unstubbed bare head is refused, not executed (rc 127)" "yes" \
  "$(case "$P1633_FIH_OUT" in *"syn_rc=127"*) echo yes ;; *) echo "no ($P1633_FIH_OUT)" ;; esac)"
assert_eq "#1633 AC29: the ignore-precondition outcomes are distinguishable by exit code (stop=3, degraded=2, no-output=0)" "yes" \
  "$(case "$P1633_FIH_OUT" in *"rstop=3 rdeg=2 rno=0"*) echo yes ;; *) echo "no ($P1633_FIH_OUT)" ;; esac)"

# ── #1594 reported-base-dir-first arm lint (lib/test/lint-reported-base-dir-arm.py) ──
# The resolve-once `echo "${CLAUDE_SKILL_DIR:-…}"` command is refused on runners whose
# matcher denies the ${VAR:-default} argument expansion, so the two skill bodies resolve
# <skill-dir> from the runner-reported base directory FIRST and keep the echo command only
# as the fallback (the run-id evidence is in the lint's docstring). This inventory-driven
# lint fails when an enrolled site consumes a value-consuming anchor expansion with no
# reported-base-directory-first arm (the <!-- prflow:skill-dir-reported-base-first -->
# sentinel) ahead of it. Driven like the #1124 sibling: real tree as the live gate, plus
# RED/GREEN/fail-closed fixtures so the guard is proven non-vacuous.
RBD_LINT="$LIB/test/lint-reported-base-dir-arm.py"
RBD_FX="$LIB/test/fixtures/reported-base-dir-arm"
# Real tree: both enrolled clauses carry the arm ahead of the fallback → clean.
RBD_OUT="$(python3 "$RBD_LINT" 2>&1)"; RBD_RC=$?
assert_eq "#1594 lint: clean on the tree as it stands (enrolled clauses carry the arm)" "rc=0" \
  "$([ "$RBD_RC" -eq 0 ] && printf 'rc=0' || printf 'rc=%s | %s' "$RBD_RC" "$RBD_OUT")"
# RED fixture: an arm-less value-consuming anchor at the fenced (implement) and the
# inline-code-in-bullet (review) sites → rc=1 naming the offending file. The two shapes
# are asserted separately so a matcher that recognised only the fenced one would go RED.
RBD_RED_OUT="$(python3 "$RBD_LINT" --root "$RBD_FX/red" 2>&1)"; RBD_RED_RC=$?
assert_eq "#1594 lint: an arm-less enrolled site is reported (RED, non-vacuous)" "1" "$RBD_RED_RC"
assert_eq "#1594 lint: the RED report names the fenced-shape site (implement)" "yes" \
  "$(case "$RBD_RED_OUT" in *"skills/implement/SKILL.md: a value-consuming"*) echo yes ;; *) echo no ;; esac)"
assert_eq "#1594 lint: the RED report names the inline-code-shape site (review)" "yes" \
  "$(case "$RBD_RED_OUT" in *"skills/review/SKILL.md: a value-consuming"*) echo yes ;; *) echo no ;; esac)"
# GREEN fixture: the arm precedes the fallback at the enrolled sites → rc=0.
assert_eq "#1594 lint: an arm-ahead enrolled site passes (GREEN)" "yes" \
  "$(python3 "$RBD_LINT" --root "$RBD_FX/green" >/dev/null 2>&1 && echo yes || echo no)"
# PATH-following fixture: an anchor expansion followed by a helper path is not value-
# consuming → rc=0 (a path-naming call site is not flagged).
assert_eq "#1594 lint: an anchor followed by a helper path is unflagged (path-naming)" "yes" \
  "$(python3 "$RBD_LINT" --root "$RBD_FX/path" >/dev/null 2>&1 && echo yes || echo no)"
# SENTINEL-AFTER fixture: the sentinel is present but sits BELOW the value-consuming
# expansion → rc=1. This pins the "arm AHEAD of it" ordering contract; a regression
# weakening the check to mere sentinel presence would wrongly pass this. Driven single-file
# via the inventory override so only the crafted implement site is audited.
assert_eq "#1594 lint: a sentinel placed AFTER the expansion still fails (ordering pinned)" "1" \
  "$(python3 "$RBD_LINT" --root "$RBD_FX/sentinel-after" --inventory "$RBD_FX/inventory-implement-only.txt" >/dev/null 2>&1; echo $?)"
# WRAPPED-SENTINEL fixture: the sentinel is wrapped across adjacent lines and is found only
# after whitespace normalization → rc=0. This makes the `" ".join(text.split())` line
# load-bearing: deleting it would leave the raw `.find` unable to locate the sentinel and
# flip this to a false RED.
assert_eq "#1594 lint: a line-wrapped sentinel is found after normalization (GREEN)" "0" \
  "$(python3 "$RBD_LINT" --root "$RBD_FX/wrapped-sentinel" --inventory "$RBD_FX/inventory-implement-only.txt" >/dev/null 2>&1; echo $?)"
# Fail-closed inputs — exactly three, complete by construction: empty inventory, absent
# enrolled file, unreadable enrolled file. The inventory is reachable via --inventory /
# --print-inventory so these arms need no source edit.
RBD_EMPTY_OUT="$(python3 "$RBD_LINT" --inventory "$RBD_FX/inventory-empty.txt" 2>&1)"; RBD_EMPTY_RC=$?
assert_eq "#1594 lint: an empty enrolled inventory fails closed" "1" "$RBD_EMPTY_RC"
assert_eq "#1594 lint: the empty-inventory report says so" "yes" \
  "$(case "$RBD_EMPTY_OUT" in *"inventory is empty"*) echo yes ;; *) echo no ;; esac)"
RBD_ABSENT_OUT="$(python3 "$RBD_LINT" --root "$RBD_FX/absent" 2>&1)"; RBD_ABSENT_RC=$?
assert_eq "#1594 lint: a missing enrolled file fails closed" "1" "$RBD_ABSENT_RC"
assert_eq "#1594 lint: the missing-file report says so" "yes" \
  "$(case "$RBD_ABSENT_OUT" in *"enrolled file is missing"*) echo yes ;; *) echo no ;; esac)"
RBD_UNREAD_OUT="$(python3 "$RBD_LINT" --root "$RBD_FX/unreadable" --inventory "$RBD_FX/inventory-implement-only.txt" 2>&1)"; RBD_UNREAD_RC=$?
assert_eq "#1594 lint: an unreadable enrolled file fails closed" "1" "$RBD_UNREAD_RC"
assert_eq "#1594 lint: the unreadable-file report says so" "yes" \
  "$(case "$RBD_UNREAD_OUT" in *"could not be read"*) echo yes ;; *) echo no ;; esac)"
# Inventory exposure: --print-inventory lists the enrolled sites and exits 0.
assert_eq "#1594 lint: --print-inventory exposes the enrolled inventory (exit 0)" "yes" \
  "$(python3 "$RBD_LINT" --print-inventory >/dev/null 2>&1 && echo yes || echo no)"

# ── Public documentation source contract ────────────────────────────────────
# The public site is source-only: Markdown/MDX, authored CSS and docs.json. Mintlify reads
# this subtree directly, so route membership, file membership and category
# landing pages are repository behavior rather than deployment-time convention.
PUBLIC_SITE_ROOT="$LIB/../docs/external"
PUBLIC_SITE_CONFIG="$PUBLIC_SITE_ROOT/docs.json"
PUBLIC_RUN_JQ="$LIB/../scripts/run-jq.sh"

public_nav_routes() {
  local config
  config="${1:-$PUBLIC_SITE_CONFIG}"
  [ -r "$config" ] || return 1
  "$PUBLIC_RUN_JQ" -r '
    def routes:
      .[]? |
      if type == "string" then .
      elif type == "object" then ((.pages // []) | routes)
      else empty
      end;
    (.navigation.pages // []) | routes
  ' "$config" 2>/dev/null
}

public_route_files_resolve() {
  local site_root config routes route
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  config="${2:-$site_root/docs.json}"
  routes="$(public_nav_routes "$config")" || { printf 'no\n'; return; }
  [ -n "$routes" ] || { printf 'no\n'; return; }
  while IFS= read -r route; do
    [ -n "$route" ] || continue
    if [ ! -f "$site_root/$route.md" ] && [ ! -f "$site_root/$route.mdx" ]; then
      printf 'no\n'
      return
    fi
  done <<< "$routes"
  printf 'yes\n'
}

public_docs_pages_are_navigated_once() {
  local site_root docs_root config routes file route count
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  docs_root="${2:-$site_root/docs}"
  config="${3:-$site_root/docs.json}"
  [ -d "$docs_root" ] && [ -r "$config" ] || { printf 'no\n'; return; }
  routes="$(public_nav_routes "$config")" || { printf 'no\n'; return; }
  [ -n "$routes" ] || { printf 'no\n'; return; }
  while IFS= read -r file; do
    route="${file#"$site_root/"}"
    route="${route%.md}"
    route="${route%.mdx}"
    count="$(printf '%s\n' "$routes" | awk -v wanted="$route" '$0 == wanted { n++ } END { print n + 0 }')"
    if [ "$count" != "1" ]; then
      printf 'no\n'
      return
    fi
  done < <(find "$docs_root" -type f \( -name '*.md' -o -name '*.mdx' \) -print) # tree-walk-ok: include unstaged public pages while validating the local source tree
  printf 'yes\n'
}

public_internal_links_resolve() {
  local site_root
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  [ -d "$site_root" ] || { printf 'no\n'; return; }
  python3 - "$site_root" <<'PY'
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
link_pattern = re.compile(r"(?<!!)\[[^]]+\]\((/[^)\s]+)")

for page in root.rglob("*"):  # tree-walk-ok: scoped to the selected public-site source root, including unstaged Markdown pages but never repository worktrees
    if not page.is_file() or page.suffix not in {".md", ".mdx"}:
        continue
    for href in link_pattern.findall(page.read_text(encoding="utf-8")):
        route = href.split("#", 1)[0].split("?", 1)[0].lstrip("/")
        if not route:
            continue
        candidates = (root / route, root / f"{route}.md", root / f"{route}.mdx")
        if not any(candidate.is_file() for candidate in candidates):
            print("no")
            raise SystemExit(0)

print("yes")
PY
}

public_directories_have_index() {
  local site_root docs_root directory
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  docs_root="${2:-$site_root/docs}"
  [ -d "$docs_root" ] || { printf 'no\n'; return; }
  while IFS= read -r directory; do
    [ -f "$directory/index.md" ] || { printf 'no\n'; return; }
  done < <(find "$docs_root" -type d -print) # tree-walk-ok: validate category indexes in the unstaged local public-doc tree
  printf 'yes\n'
}

public_docs_stay_shallow() {
  local site_root docs_root file relative
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  docs_root="${2:-$site_root/docs}"
  [ -d "$docs_root" ] || { printf 'no\n'; return; }
  while IFS= read -r file; do
    relative="${file#"$docs_root/"}"
    if [ "$(awk -F/ '{ print NF }' <<< "$relative")" -gt 3 ]; then
      printf 'no\n'
      return
    fi
  done < <(find "$docs_root" -type f \( -name '*.md' -o -name '*.mdx' \) -print) # tree-walk-ok: enforce depth for unstaged public pages before they enter the index
  printf 'yes\n'
}

public_docs_rely_on_renderer_h1() {
  local site_root docs_root
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  docs_root="${2:-$site_root/docs}"
  [ -d "$docs_root" ] || { printf 'no\n'; return; }
  python3 - "$docs_root" <<'PY'
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
fence = re.compile(r"^\s*(```|~~~)")
heading = re.compile(r"^#\s+")

for page in root.rglob("*.md"):  # tree-walk-ok: inspect every authored inner page, including unstaged additions
    in_fence = False
    for line in page.read_text(encoding="utf-8").splitlines():
        if fence.match(line):
            in_fence = not in_fence
            continue
        if not in_fence and heading.match(line):
            print("no")
            raise SystemExit(0)

print("yes")
PY
}

public_site_has_no_build_output() {
  # `find`'s own status is read directly rather than a tail-of-pipe `grep -q`: piping made a
  # failed walk indistinguishable from a clean one (empty stdout -> `yes`), so the guard failed
  # OPEN on exactly the traversal errors it should refuse.
  local site_root hit
  site_root="${1:-$PUBLIC_SITE_ROOT}"
  [ -d "$site_root" ] || { printf 'no\n'; return; }
  hit="$(find "$site_root" \( -type d -name node_modules -o -type f \( -name '*.html' -o -name '*.js' -o -name package.json -o -name package-lock.json -o -name pnpm-lock.yaml -o -name yarn.lock -o -name bun.lock -o -name bun.lockb \) \) -print -quit)" || { printf 'no\n'; return; } # tree-walk-ok: reject generated or dependency output even while the public site is unstaged
  if [ -n "$hit" ]; then
    printf 'no\n'
  else
    printf 'yes\n'
  fi
}

public_file_contains() {
  local file="$1" needle="$2" content
  [ -r "$file" ] || { printf 'no\n'; return; }
  content="$(cat "$file")"
  case "$content" in
    *"$needle"*) printf 'yes\n' ;;
    *) printf 'no\n' ;;
  esac
}

